CREATE OR REPLACE FUNCTION "public"."_apply_catalog_stock_lines"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_reference_type" "text", "p_reference_prefix" "text", "p_lines" "jsonb", "p_scope" "text" DEFAULT 'full'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line jsonb;
  v_product uuid;
  v_qty numeric;
  v_variant uuid;
  v_mod_ids uuid[];
  v_recipe record;
  v_tracked boolean;
  v_option_mapped uuid[];
  v_line_key text;
  v_ref_base text;
BEGIN
  IF p_scope NOT IN ('full', 'recipe_only', 'finished_goods_only') THEN
    RAISE EXCEPTION 'catalog_stock_scope_invalid';
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_product := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    v_variant := NULLIF(v_line ->> 'variant_id', '')::uuid;
    v_line_key := COALESCE(NULLIF(btrim(v_line ->> 'line_key'), ''), 'L1');

    SELECT COALESCE(array_agg(DISTINCT x.opt_id), ARRAY[]::uuid[])
      INTO v_mod_ids
    FROM (
      SELECT NULLIF(elem #>> '{}', '')::uuid AS opt_id
      FROM jsonb_array_elements(COALESCE(v_line -> 'modifier_option_ids', '[]'::jsonb)) AS elem
    ) x
    WHERE x.opt_id IS NOT NULL;

    IF v_product IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    v_ref_base := p_reference_prefix || ':' || v_line_key || ':' || v_product::text;

    IF p_scope IN ('full', 'finished_goods_only') THEN
      SELECT track_stock INTO v_tracked
      FROM public.default_prices
      WHERE id = v_product AND organization_id = p_organization_id;

      IF v_tracked IS TRUE THEN
        PERFORM public.apply_catalog_stock_movement(
          p_organization_id,
          p_outlet_id,
          'product',
          v_product,
          v_variant,
          NULL,
          'sale',
          -v_qty,
          p_reference_type,
          v_ref_base,
          'Product sale'
        );
      END IF;
    END IF;

    IF p_scope IN ('full', 'recipe_only') THEN
      FOR v_recipe IN
        SELECT l.ingredient_id, l.quantity
        FROM public.catalog_product_recipes r
        JOIN public.catalog_product_recipe_lines l ON l.recipe_id = r.id
        JOIN public.catalog_ingredients i ON i.id = l.ingredient_id
        WHERE r.product_id = v_product
          AND r.modifier_option_id IS NULL
          AND i.track_inventory = true
          AND i.is_deleted = false
      LOOP
        PERFORM public.apply_catalog_stock_movement(
          p_organization_id,
          p_outlet_id,
          'ingredient',
          NULL,
          NULL,
          v_recipe.ingredient_id,
          'recipe_consume',
          -(v_recipe.quantity * v_qty),
          p_reference_type,
          v_ref_base || ':ing:' || v_recipe.ingredient_id::text,
          'Recipe consume'
        );
      END LOOP;

      IF cardinality(v_mod_ids) > 0 THEN
        v_option_mapped := ARRAY[]::uuid[];

        FOR v_recipe IN
          SELECT moi.ingredient_id, moi.quantity, moi.option_id AS modifier_option_id
          FROM public.catalog_modifier_option_ingredients moi
          JOIN public.catalog_modifier_options o ON o.id = moi.option_id
          JOIN public.catalog_modifier_groups g ON g.id = o.group_id
          JOIN public.catalog_ingredients i ON i.id = moi.ingredient_id
          WHERE moi.option_id = ANY (v_mod_ids)
            AND g.stock_enabled IS TRUE
            AND g.organization_id = p_organization_id
            AND i.track_inventory = true
            AND i.is_deleted = false
        LOOP
          v_option_mapped := array_append(v_option_mapped, v_recipe.modifier_option_id);
          PERFORM public.apply_catalog_stock_movement(
            p_organization_id,
            p_outlet_id,
            'ingredient',
            NULL,
            NULL,
            v_recipe.ingredient_id,
            'recipe_consume',
            -(v_recipe.quantity * v_qty),
            p_reference_type,
            v_ref_base || ':mod:' || v_recipe.modifier_option_id::text || ':ing:' || v_recipe.ingredient_id::text,
            'modifier option ingredient consume'
          );
        END LOOP;

        FOR v_recipe IN
          SELECT l.ingredient_id, l.quantity, r.modifier_option_id
          FROM public.catalog_product_recipes r
          JOIN public.catalog_product_recipe_lines l ON l.recipe_id = r.id
          JOIN public.catalog_ingredients i ON i.id = l.ingredient_id
          JOIN public.catalog_modifier_options o ON o.id = r.modifier_option_id
          JOIN public.catalog_modifier_groups g ON g.id = o.group_id
          WHERE r.product_id = v_product
            AND r.modifier_option_id = ANY (v_mod_ids)
            AND g.stock_enabled IS TRUE
            AND NOT (r.modifier_option_id = ANY (v_option_mapped))
            AND i.track_inventory = true
            AND i.is_deleted = false
        LOOP
          PERFORM public.apply_catalog_stock_movement(
            p_organization_id,
            p_outlet_id,
            'ingredient',
            NULL,
            NULL,
            v_recipe.ingredient_id,
            'recipe_consume',
            -(v_recipe.quantity * v_qty),
            p_reference_type,
            v_ref_base || ':mod:' || v_recipe.modifier_option_id::text || ':ing:' || v_recipe.ingredient_id::text,
            'modifier recipe consume'
          );
        END LOOP;
      END IF;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."_apply_catalog_stock_lines"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_reference_type" "text", "p_reference_prefix" "text", "p_lines" "jsonb", "p_scope" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_apply_plan_modules"("p_subscription_plan_id" "uuid", "p_modules" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_catalog text[];
  v_key text;
  v_val boolean;
  v_after jsonb := '{}'::jsonb;
BEGIN
  v_catalog := public.sales_module_catalog_keys();

  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_modules) AS e(key, value)
    WHERE e.key = ANY (ARRAY['dashboard', 'subscription'])
       OR NOT (e.key = ANY (v_catalog))
       OR jsonb_typeof(e.value) <> 'boolean'
  ) THEN
    RAISE EXCEPTION 'invalid module keys in payload' USING ERRCODE = '22023';
  END IF;

  PERFORM public.seed_plan_module_access_defaults(p_subscription_plan_id);

  FOREACH v_key IN ARRAY v_catalog
  LOOP
    IF p_modules ? v_key THEN
      v_val := (p_modules ->> v_key)::boolean;
    ELSE
      SELECT m.is_enabled
      INTO v_val
      FROM public.subscription_plan_module_access m
      WHERE m.subscription_plan_id = p_subscription_plan_id
        AND m.module_key = v_key;
      v_val := coalesce(v_val, false);
    END IF;

    INSERT INTO public.subscription_plan_module_access (
      subscription_plan_id,
      module_key,
      is_enabled,
      updated_at
    ) VALUES (
      p_subscription_plan_id,
      v_key,
      v_val,
      now()
    )
    ON CONFLICT (subscription_plan_id, module_key)
    DO UPDATE SET
      is_enabled = EXCLUDED.is_enabled,
      updated_at = now();

    v_after := v_after || jsonb_build_object(v_key, v_val);
  END LOOP;

  RETURN v_after;
END;
$$;


ALTER FUNCTION "public"."_apply_plan_modules"("p_subscription_plan_id" "uuid", "p_modules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_billing_cycle_from_term_months"("p_months" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE WHEN public._coerce_billing_term_months(p_months) = 12 THEN 'yearly' ELSE 'monthly' END;
$$;


ALTER FUNCTION "public"."_billing_cycle_from_term_months"("p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_billing_term_discount"("p_discounts" "jsonb", "p_months" integer) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE WHEN p_discounts ? p_months::text THEN (p_discounts ->> p_months::text)::numeric ELSE NULL END;
$$;


ALTER FUNCTION "public"."_billing_term_discount"("p_discounts" "jsonb", "p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_build_plan_features_from_modules"("p_base_price_per_member" numeric, "p_modules" "jsonb", "p_max_members" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_features jsonb := '[]'::jsonb;
  v_key text;
  v_cap integer;
BEGIN
  v_cap := public._resolve_plan_max_members(p_max_members, NULL, p_base_price_per_member);

  IF v_cap IS NOT NULL THEN
    v_features := v_features || jsonb_build_array(v_cap::text || ' Member Allowed');
  END IF;

  IF p_base_price_per_member IS NOT NULL AND p_base_price_per_member >= 0 THEN
    v_features := v_features || jsonb_build_array(
      'Rp ' || trim(to_char(p_base_price_per_member, 'FM999G999G999')) || ' per member / bulan'
    );
  END IF;

  FOREACH v_key IN ARRAY public.sales_module_catalog_keys()
  LOOP
    IF v_key IN ('customerSupport', 'whatsappBusiness') THEN
      CONTINUE;
    END IF;
    IF p_modules ? v_key AND (p_modules ->> v_key)::boolean IS TRUE THEN
      v_features := v_features || jsonb_build_array('Modul ' || public._plan_module_label(v_key));
    END IF;
  END LOOP;

  v_features := v_features || jsonb_build_array('Dashboard selalu aktif');

  RETURN v_features;
END;
$$;


ALTER FUNCTION "public"."_build_plan_features_from_modules"("p_base_price_per_member" numeric, "p_modules" "jsonb", "p_max_members" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_coerce_billing_term_months"("p_months" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE WHEN p_months IN (1, 3, 6, 12) THEN p_months ELSE 1 END;
$$;


ALTER FUNCTION "public"."_coerce_billing_term_months"("p_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_collect_organization_auth_users_to_delete"("p_organization_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_users uuid[];
BEGIN
  IF to_regclass('public.user_organizations') IS NULL THEN
    RETURN '{}'::uuid[];
  END IF;

  SELECT coalesce(array_agg(uo.user_id), '{}'::uuid[])
  INTO v_users
  FROM public.user_organizations uo
  WHERE uo.organization_id = p_organization_id
    AND NOT EXISTS (
      SELECT 1
      FROM public.user_organizations uo2
      WHERE uo2.user_id = uo.user_id
        AND uo2.organization_id <> p_organization_id
    )
    AND (
      to_regclass('public.cms_admins') IS NULL
      OR NOT EXISTS (
        SELECT 1 FROM public.cms_admins ca WHERE ca.user_id = uo.user_id
      )
    );

  RETURN coalesce(v_users, '{}'::uuid[]);
END;
$$;


ALTER FUNCTION "public"."_collect_organization_auth_users_to_delete"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_computed_bank_balance"("p_bank_account_id" "uuid", "p_org_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    COALESCE((
      SELECT SUM(it.amount::NUMERIC)
      FROM public.income_transactions it
      WHERE it.bank_account_id = p_bank_account_id
        AND it.organization_id = p_org_id
        AND it.status IN ('completed', 'pending')
    ), 0)
    - COALESCE((
      SELECT SUM(e.amount::NUMERIC)
      FROM public.expenses e
      WHERE e.bank_account_id = p_bank_account_id
        AND e.organization_id = p_org_id
        AND e.status = 'active'
    ), 0)
    + COALESCE((
      SELECT SUM(btj.amount::NUMERIC)
      FROM public.bank_transfer_journals btj
      WHERE btj.to_bank_account_id = p_bank_account_id
        AND btj.organization_id = p_org_id
        AND btj.income_transaction_id IS NULL
    ), 0)
    - COALESCE((
      SELECT SUM(btj.amount::NUMERIC)
      FROM public.bank_transfer_journals btj
      WHERE btj.from_bank_account_id = p_bank_account_id
        AND btj.organization_id = p_org_id
        AND btj.income_transaction_id IS NULL
    ), 0);
$$;


ALTER FUNCTION "public"."_computed_bank_balance"("p_bank_account_id" "uuid", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_count_organization_rows"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r record;
  v_sql text;
  v_count bigint;
  v_result jsonb := '{}'::jsonb;
BEGIN
  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    INNER JOIN information_schema.tables t
      ON t.table_schema = c.table_schema
      AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = 'organization_id'
      AND t.table_type = 'BASE TABLE'
      AND c.table_name NOT IN ('organizations', 'cms_organization_deletions')
    ORDER BY c.table_name
  LOOP
    v_sql := format(
      'SELECT count(*)::bigint FROM public.%I WHERE organization_id = $1',
      r.table_name
    );
    EXECUTE v_sql INTO v_count USING p_organization_id;
    IF v_count > 0 THEN
      v_result := v_result || jsonb_build_object(r.table_name, v_count);
    END IF;
  END LOOP;

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_count_organization_rows"("p_organization_id" "uuid") OWNER TO "postgres";


