CREATE OR REPLACE FUNCTION "public"."_haversine_km"("lat1" double precision, "lon1" double precision, "lat2" double precision, "lon2" double precision) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT (
    6371.0 * acos(
      LEAST(
        1.0::double precision,
        GREATEST(
          -1.0::double precision,
          cos(radians(lat1)) * cos(radians(lat2))
          * cos(radians(lon2) - radians(lon1))
          + sin(radians(lat1)) * sin(radians(lat2))
        )
      )
    )
  )::numeric;
$$;


ALTER FUNCTION "public"."_haversine_km"("lat1" double precision, "lon1" double precision, "lat2" double precision, "lon2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_merge_assert_org_access"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required' USING ERRCODE = 'P0001';
  END IF;

  v_role := coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '');

  -- SQL Editor / migration: sesi DB owner tanpa JWT. session_user tidak berubah
  -- oleh SECURITY DEFINER (berbeda dengan current_user).
  IF v_role = '' AND session_user IN ('postgres', 'supabase_admin') THEN
    RETURN;
  END IF;

  IF v_role = 'service_role' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NOT NULL
     AND p_organization_id IN (SELECT public.user_organization_ids()) THEN
    RETURN;
  END IF;

  RAISE EXCEPTION 'not_authorized' USING ERRCODE = 'P0001';
END;
$$;


ALTER FUNCTION "public"."_lead_merge_assert_org_access"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_merge_execute_cluster"("p_organization_id" "uuid", "p_kind" "text", "p_cluster_key" "text", "p_winner" "uuid", "p_losers" "uuid"[], "p_actor" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone text;
  v_email text;
  v_client text;
BEGIN
  IF p_winner IS NULL OR p_losers IS NULL OR cardinality(p_losers) = 0 THEN
    RETURN;
  END IF;

  p_losers := array(
    SELECT l.id
    FROM public.leads l
    WHERE l.id = ANY (p_losers)
      AND l.organization_id = p_organization_id
      AND l.merged_into_lead_id IS NULL
      AND l.id IS DISTINCT FROM p_winner
  );
  IF cardinality(p_losers) = 0 THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.leads w
    WHERE w.id = p_winner
      AND w.organization_id = p_organization_id
      AND w.merged_into_lead_id IS NULL
  ) THEN
    RETURN;
  END IF;

  UPDATE public.sales_activities
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.sales_invoices
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.lead_submissions
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.lead_magnet_enrollments
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.lead_magnet_participant_profiles
  SET canonical_lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND canonical_lead_id = ANY (p_losers);

  UPDATE public.whatsapp_recipient_list_members
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.whatsapp_template_followups
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.clients
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.client_visits
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.pos_pending_checkouts
  SET lead_id = p_winner
  WHERE organization_id = p_organization_id
    AND lead_id = ANY (p_losers);

  UPDATE public.customer_visits cv
  SET lead_id = p_winner
  WHERE cv.organization_id = p_organization_id
    AND cv.lead_id = ANY (p_losers)
    AND NOT (
      lower(cv.status) = 'completed'
      AND cv.match_status = 'matched'
      AND EXISTS (
        SELECT 1
        FROM public.customer_visits w
        WHERE w.organization_id = cv.organization_id
          AND w.lead_id = p_winner
          AND w.visit_date = cv.visit_date
          AND w.match_status = 'matched'
          AND lower(w.status) = 'completed'
      )
    );

  UPDATE public.lead_follow_up_updates
  SET lead_id = p_winner
  WHERE lead_id = ANY (p_losers);

  UPDATE public.lead_status_history
  SET lead_id = p_winner
  WHERE lead_id = ANY (p_losers);

  IF NOT EXISTS (
    SELECT 1 FROM public.google_ads_conversion_uploads g WHERE g.lead_id = p_winner
  ) THEN
    UPDATE public.google_ads_conversion_uploads u
    SET lead_id = p_winner
    WHERE u.id = (
      SELECT g.id
      FROM public.google_ads_conversion_uploads g
      WHERE g.lead_id = ANY (p_losers)
      ORDER BY g.updated_at DESC NULLS LAST
      LIMIT 1
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.meta_ads_conversion_uploads m WHERE m.lead_id = p_winner
  ) THEN
    UPDATE public.meta_ads_conversion_uploads u
    SET lead_id = p_winner
    WHERE u.id = (
      SELECT g.id
      FROM public.meta_ads_conversion_uploads g
      WHERE g.lead_id = ANY (p_losers)
      ORDER BY g.updated_at DESC NULLS LAST
      LIMIT 1
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.lead_google_contact_links g
    WHERE g.organization_id = p_organization_id
      AND g.lead_id = p_winner
  ) THEN
    UPDATE public.lead_google_contact_links u
    SET lead_id = p_winner
    WHERE u.id = (
      SELECT g.id
      FROM public.lead_google_contact_links g
      WHERE g.organization_id = p_organization_id
        AND g.lead_id = ANY (p_losers)
      ORDER BY g.updated_at DESC NULLS LAST
      LIMIT 1
    );
  END IF;

  UPDATE public.google_contacts_sync_jobs j
  SET lead_id = p_winner
  WHERE j.organization_id = p_organization_id
    AND j.lead_id = ANY (p_losers);

  SELECT
    (SELECT l.phone_number FROM public.leads l
     WHERE l.id = ANY (p_losers)
       AND public.normalize_wa_phone_key(l.phone_number) IS NOT NULL
     ORDER BY l.updated_at DESC NULLS LAST LIMIT 1),
    (SELECT NULLIF(lower(btrim(l.email)), '') FROM public.leads l
     WHERE l.id = ANY (p_losers)
       AND NULLIF(btrim(l.email), '') IS NOT NULL
     ORDER BY l.updated_at DESC NULLS LAST LIMIT 1),
    (SELECT l.client FROM public.leads l
     WHERE l.id = ANY (p_losers)
       AND NOT public.is_generic_customer_name(l.client)
     ORDER BY l.updated_at DESC NULLS LAST LIMIT 1)
  INTO v_phone, v_email, v_client;

  UPDATE public.leads
  SET
    phone_number = NULL,
    email = NULL,
    merged_into_lead_id = p_winner,
    merged_at = now(),
    merged_by = p_actor,
    updated_at = now()
  WHERE id = ANY (p_losers)
    AND organization_id = p_organization_id
    AND merged_into_lead_id IS NULL;

  UPDATE public.leads
  SET
    phone_number = CASE
      WHEN public.normalize_wa_phone_key(phone_number) IS NULL AND v_phone IS NOT NULL
      THEN v_phone
      ELSE phone_number
    END,
    email = CASE
      WHEN NULLIF(btrim(COALESCE(email, '')), '') IS NULL AND v_email IS NOT NULL
      THEN v_email
      ELSE email
    END,
    client = CASE
      WHEN public.is_generic_customer_name(client)
           AND v_client IS NOT NULL
           AND NOT public.is_generic_customer_name(v_client)
      THEN v_client
      ELSE client
    END,
    updated_at = now()
  WHERE id = p_winner;

  INSERT INTO public.lead_merge_events (
    organization_id,
    cluster_kind,
    cluster_key,
    winner_lead_id,
    loser_lead_ids,
    skipped,
    skip_reason,
    created_by
  ) VALUES (
    p_organization_id,
    p_kind,
    p_cluster_key,
    p_winner,
    p_losers,
    false,
    NULL,
    p_actor
  );
END;
$$;


ALTER FUNCTION "public"."_lead_merge_execute_cluster"("p_organization_id" "uuid", "p_kind" "text", "p_cluster_key" "text", "p_winner" "uuid", "p_losers" "uuid"[], "p_actor" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_lead_merge_execute_cluster"("p_organization_id" "uuid", "p_kind" "text", "p_cluster_key" "text", "p_winner" "uuid", "p_losers" "uuid"[], "p_actor" "uuid") IS 'Soft-merge cluster: rebind FKs, archive losers (clear phone/email) first, then fill-empty contacts on winner.';



CREATE OR REPLACE FUNCTION "public"."_lead_merge_is_attributed"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_source" "text", "p_ticket_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    btrim(COALESCE(p_source, '')) = 'Lead Magnet'
    OR upper(btrim(COALESCE(p_ticket_id, ''))) LIKE 'LEAD-%'
    OR EXISTS (
      SELECT 1
      FROM public.lead_magnet_enrollments e
      WHERE e.organization_id = p_organization_id
        AND e.lead_id = p_lead_id
    );
$$;


ALTER FUNCTION "public"."_lead_merge_is_attributed"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_source" "text", "p_ticket_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_merge_is_typo_domain"("p_valid" "text", "p_invalid" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v text := lower(btrim(COALESCE(p_valid, '')));
  inv text := lower(btrim(COALESCE(p_invalid, '')));
BEGIN
  IF v = '' OR inv = '' OR v = inv THEN
    RETURN false;
  END IF;
  IF inv LIKE v || '%' AND substring(inv from length(v) + 1) ~ '^[a-z]{2,}$' THEN
    RETURN true;
  END IF;
  RETURN false;
END;
$_$;


ALTER FUNCTION "public"."_lead_merge_is_typo_domain"("p_valid" "text", "p_invalid" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_merge_is_valid_identity_email"("p_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  n text;
  domain text;
BEGIN
  n := lower(btrim(COALESCE(p_email, '')));
  IF n = '' OR position('@' IN n) = 0 THEN
    RETURN false;
  END IF;
  IF n !~ '^[^\s@]+@[^\s@]+\.[a-z]{2,24}$' THEN
    RETURN false;
  END IF;
  domain := split_part(n, '@', 2);
  IF domain ~ '(^|\.)(com|net|org|edu|gov|co|io|id|me|app|dev)[a-z]{2,}$' THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."_lead_merge_is_valid_identity_email"("p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_merge_pick_winner"("p_organization_id" "uuid", "p_lead_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_winner uuid;
BEGIN
  SELECT l.id
  INTO v_winner
  FROM public.leads l
  WHERE l.organization_id = p_organization_id
    AND l.id = ANY (p_lead_ids)
    AND l.merged_into_lead_id IS NULL
  ORDER BY
    CASE
      WHEN public._lead_merge_is_attributed(p_organization_id, l.id, l.source, l.ticket_id)
      THEN 1 ELSE 0
    END DESC,
    CASE
      WHEN public.is_generic_customer_name(l.client) THEN 0
      ELSE 1
    END DESC,
    COALESCE(l.updated_at, l.created_at) DESC NULLS LAST,
    l.created_at DESC NULLS LAST
  LIMIT 1;

  RETURN v_winner;
END;
$$;


ALTER FUNCTION "public"."_lead_merge_pick_winner"("p_organization_id" "uuid", "p_lead_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_mcp_resolve_semi_finished"("p_organization_id" "uuid", "p_search" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text := btrim(COALESCE(p_search, ''));
  v_id uuid;
  v_count integer;
  v_names text;
BEGIN
  IF v_search = '' OR length(v_search) > 120 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT count(*), min(i.id::text)::uuid
    INTO v_count, v_id
  FROM public.catalog_ingredients i
  WHERE i.organization_id = p_organization_id
    AND i.kind = 'semi_finished'
    AND NOT COALESCE(i.is_deleted, false)
    AND lower(i.name) = lower(v_search);
  IF v_count = 1 THEN
    RETURN v_id;
  END IF;

  SELECT count(*), min(i.id::text)::uuid, string_agg(i.name, ' | ' ORDER BY i.name)
    INTO v_count, v_id, v_names
  FROM public.catalog_ingredients i
  WHERE i.organization_id = p_organization_id
    AND i.kind = 'semi_finished'
    AND NOT COALESCE(i.is_deleted, false)
    AND i.name ILIKE '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  IF v_count = 1 THEN
    RETURN v_id;
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION '%', 'ambiguous: ' || v_names USING ERRCODE = '22023';
  END IF;
  RAISE EXCEPTION 'production_item_not_found' USING ERRCODE = 'P0002';
END;
$$;


ALTER FUNCTION "public"."_mcp_resolve_semi_finished"("p_organization_id" "uuid", "p_search" "text") OWNER TO "postgres";


