CREATE OR REPLACE FUNCTION "public"."_parse_member_limit_from_features"("p_features" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_feature text;
  v_match text[];
BEGIN
  IF p_features IS NULL OR jsonb_typeof(p_features) <> 'array' THEN
    RETURN NULL;
  END IF;

  FOR v_feature IN
    SELECT jsonb_array_elements_text(p_features)
  LOOP
    v_match := regexp_match(v_feature, '^(\d+)\s*Member\s*Allowed', 'i');
    IF v_match IS NOT NULL THEN
      RETURN greatest(1, (v_match[1])::integer);
    END IF;

    v_match := regexp_match(v_feature, '^Hingga\s*(\d+)', 'i');
    IF v_match IS NOT NULL THEN
      RETURN greatest(1, (v_match[1])::integer);
    END IF;

    v_match := regexp_match(
      v_feature,
      '(\d+)\s*(employee\s*limit|karyawan|orang|employees?|members?|anggota)',
      'i'
    );
    IF v_match IS NOT NULL THEN
      RETURN greatest(1, (v_match[1])::integer);
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."_parse_member_limit_from_features"("p_features" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plan_module_label"("p_module_key" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
