CREATE OR REPLACE FUNCTION "public"."_preview_organization_key_counts"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_result jsonb := '{}'::jsonb;
  v_count bigint;
  r record;
BEGIN
  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    INNER JOIN information_schema.tables t
      ON t.table_schema = c.table_schema
      AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = 'organization_id'
      AND t.table_type = 'BASE TABLE'
      AND c.table_name = ANY(ARRAY[
        'employees','user_organizations','payments','organization_subscriptions',
        'attendance_records','payroll_runs','crm_leads','projects','social_media_posts'
      ])
    ORDER BY c.table_name
  LOOP
    EXECUTE format(
      'SELECT count(*)::bigint FROM public.%I WHERE organization_id = $1',
      r.table_name
    ) INTO v_count USING p_organization_id;
    IF v_count > 0 THEN
      v_result := v_result || jsonb_build_object(r.table_name, v_count);
    END IF;
  END LOOP;
  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."_preview_organization_key_counts"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_purge_organization_rows"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r record;
  v_sql text;
  v_count bigint;
  v_deleted jsonb := '{}'::jsonb;
  v_pass int;
  v_max_passes int := 40;
  v_remaining bigint;
  v_total_remaining bigint;
  v_prev_count bigint;
BEGIN
  FOR v_pass IN 1..v_max_passes LOOP
    FOR r IN
      SELECT c.table_name
      FROM information_schema.columns c
      INNER JOIN information_schema.tables t
        ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      WHERE c.table_schema = 'public' AND c.column_name = 'organization_id'
        AND t.table_type = 'BASE TABLE'
        AND c.table_name NOT IN ('organizations', 'cms_organization_deletions')
      ORDER BY c.table_name
    LOOP
      BEGIN
        EXECUTE format('DELETE FROM public.%I WHERE organization_id = $1', r.table_name) USING p_organization_id;
        GET DIAGNOSTICS v_count = ROW_COUNT;
        IF v_count > 0 THEN
          v_prev_count := coalesce((v_deleted ->> r.table_name)::bigint, 0);
          v_deleted := v_deleted || jsonb_build_object(r.table_name, v_prev_count + v_count);
        END IF;
      EXCEPTION WHEN foreign_key_violation THEN NULL;
               WHEN undefined_column THEN NULL;
      END;
    END LOOP;
    v_total_remaining := 0;
    FOR r IN
      SELECT c.table_name FROM information_schema.columns c
      INNER JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
      WHERE c.table_schema = 'public' AND c.column_name = 'organization_id'
        AND t.table_type = 'BASE TABLE'
        AND c.table_name NOT IN ('organizations', 'cms_organization_deletions')
      ORDER BY c.table_name
    LOOP
      BEGIN
        EXECUTE format('SELECT count(*)::bigint FROM public.%I WHERE organization_id = $1', r.table_name)
          INTO v_remaining USING p_organization_id;
        v_total_remaining := v_total_remaining + coalesce(v_remaining, 0);
      EXCEPTION WHEN undefined_column THEN NULL;
      END;
    END LOOP;
    EXIT WHEN v_total_remaining = 0;
  END LOOP;
  IF v_total_remaining > 0 THEN
    RAISE EXCEPTION 'purge incomplete: % tenant rows remain after % passes', v_total_remaining, v_max_passes USING ERRCODE = '23503';
  END IF;
  DELETE FROM public.organizations WHERE id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'organization row missing after purge' USING ERRCODE = 'P0002'; END IF;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  v_deleted := v_deleted || jsonb_build_object('organizations', v_count);
  RETURN v_deleted;
END;
$_$;


ALTER FUNCTION "public"."_purge_organization_rows"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_draft_check_lines"("p_org" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out jsonb := '[]'::jsonb;
  v_elem jsonb;
  v_id uuid;
  v_qty numeric;
  v_seen uuid[] := ARRAY[]::uuid[];
  v_name text;
BEGIN
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array'
    OR jsonb_array_length(p_lines) < 1 OR jsonb_array_length(p_lines) > 50 THEN
    RAISE EXCEPTION 'recipe_draft_lines_invalid' USING ERRCODE = '22023';
  END IF;

  FOR v_elem IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    BEGIN
      v_id := (v_elem ->> 'ingredient_id')::uuid;
      v_qty := (v_elem ->> 'quantity')::numeric;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'recipe_draft_lines_invalid' USING ERRCODE = '22023';
    END;
    IF v_id IS NULL OR v_qty IS NULL THEN
      RAISE EXCEPTION 'recipe_draft_lines_invalid' USING ERRCODE = '22023';
    END IF;

    SELECT i.name INTO v_name
    FROM public.catalog_ingredients i
    WHERE i.id = v_id AND i.organization_id = p_org AND i.is_deleted = false;
    IF v_name IS NULL THEN
      RAISE EXCEPTION 'recipe_draft_ingredient_not_found' USING ERRCODE = 'P0002';
    END IF;
    IF v_id = ANY (v_seen) THEN
      RAISE EXCEPTION '%', 'recipe_draft_duplicate_ingredient: ' || v_name USING ERRCODE = '22023';
    END IF;
    v_seen := v_seen || v_id;

    v_qty := round(v_qty, 3);
    IF v_qty <= 0 THEN
      RAISE EXCEPTION '%', 'recipe_draft_quantity_too_small: ' || v_name USING ERRCODE = '22023';
    END IF;
    IF v_qty > 100000 THEN
      RAISE EXCEPTION '%', 'recipe_draft_quantity_too_large: ' || v_name USING ERRCODE = '22023';
    END IF;

    v_out := v_out || jsonb_build_object('ingredient_id', v_id, 'quantity', v_qty);
  END LOOP;

  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."_recipe_draft_check_lines"("p_org" "uuid", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_draft_insert"("p_user" "uuid", "p_org" "uuid", "p_outlet" "uuid", "p_product" "uuid", "p_lines" "jsonb", "p_note" "text", "p_source" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lines jsonb;
  v_id uuid;
  v_fp text;
  v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
BEGIN
  IF v_note IS NOT NULL AND char_length(v_note) > 1000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_lines := public._recipe_draft_check_lines(p_org, p_lines);
  v_fp := public.catalog_recipe_fingerprint(p_product);

  UPDATE public.catalog_recipe_drafts
  SET status = 'superseded', decided_at = now(), updated_at = now()
  WHERE product_id = p_product AND status = 'pending';

  INSERT INTO public.catalog_recipe_drafts (
    organization_id, outlet_id, product_id, draft_type, lines, original_lines,
    base_fingerprint, request_note, source, requested_by
  ) VALUES (
    p_org, p_outlet, p_product, CASE WHEN v_fp = '' THEN 'new' ELSE 'update' END,
    v_lines, v_lines, v_fp, v_note, p_source, p_user
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."_recipe_draft_insert"("p_user" "uuid", "p_org" "uuid", "p_outlet" "uuid", "p_product" "uuid", "p_lines" "jsonb", "p_note" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_draft_list"("p_user" "uuid", "p_org" "uuid", "p_status" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text := COALESCE(NULLIF(btrim(COALESCE(p_status, '')), ''), 'pending');
  v_out jsonb := '[]'::jsonb;
  v_row record;
  v_review jsonb;
BEGIN
  IF NOT public._recipe_is_member(p_user, p_org) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
  IF v_status NOT IN ('pending', 'published', 'rejected', 'superseded', 'expired', 'all') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    SELECT d.id
    FROM public.catalog_recipe_drafts d
    WHERE d.organization_id = p_org
      AND (
        v_status = 'all'
        OR (v_status = 'pending' AND d.status = 'pending' AND d.expires_at > now())
        OR (v_status = 'expired' AND (d.status = 'expired' OR (d.status = 'pending' AND d.expires_at <= now())))
        OR (v_status NOT IN ('pending', 'expired') AND d.status = v_status)
      )
    ORDER BY d.created_at DESC
    LIMIT 50
  LOOP
    v_review := public._recipe_draft_review(v_row.id, p_user);
    v_out := v_out || jsonb_build_object(
      'id', v_row.id,
      'product_id', v_review #>> '{draft,product_id}',
      'outlet_id', v_review #>> '{draft,outlet_id}',
      'outlet_name', v_review #>> '{draft,outlet_name}',
      'product_name', v_review #>> '{draft,product_name}',
      'draft_type', v_review #>> '{draft,draft_type}',
      'status', v_review #>> '{draft,status}',
      'requested_by_name', v_review #>> '{draft,requested_by_name}',
      'request_note', v_review #>> '{draft,request_note}',
      'created_at', v_review #> '{draft,created_at}',
      'edited', v_review #> '{draft,edited}',
      'line_count', (SELECT count(*) FROM jsonb_array_elements(v_review -> 'rows') r WHERE (r ->> 'after_qty') IS NOT NULL),
      'hpp_before', v_review #> '{totals,hpp_before}',
      'hpp_after', v_review #> '{totals,hpp_after}',
      'warning_count', jsonb_array_length(v_review -> 'warnings'),
      'blocked', jsonb_array_length(v_review -> 'blocking') > 0
    );
  END LOOP;

  RETURN jsonb_build_object('status', v_status, 'drafts', v_out);
END;
$$;


ALTER FUNCTION "public"."_recipe_draft_list"("p_user" "uuid", "p_org" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_draft_review"("p_draft_id" "uuid", "p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  d public.catalog_recipe_drafts%ROWTYPE;
  v_product text;
  v_category text;
  v_outlet text;
  v_price numeric;
  v_fg boolean;
  v_effective_status text;
  v_before jsonb;
  v_rows jsonb;
  v_hpp_before numeric;
  v_hpp_after numeric;
  v_warnings jsonb := '[]'::jsonb;
  v_blocking jsonb := '[]'::jsonb;
  v_names jsonb;
  v_has_live boolean;
BEGIN
  SELECT * INTO d FROM public.catalog_recipe_drafts WHERE id = p_draft_id;
  IF NOT FOUND OR NOT public._recipe_is_member(p_user, d.organization_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT dp.name, cat.name, COALESCE(link.unit_price, dp.unit_price), COALESCE(link.track_cogs, false)
    INTO v_product, v_category, v_price, v_fg
  FROM public.default_prices dp
  LEFT JOIN public.catalog_product_categories cat ON cat.id = dp.product_category_id
  LEFT JOIN public.catalog_product_outlets link
    ON link.product_id = dp.id AND link.outlet_id = d.outlet_id AND link.organization_id = d.organization_id
  WHERE dp.id = d.product_id;

  SELECT o.name INTO v_outlet FROM public.pos_outlets o WHERE o.id = d.outlet_id;

  v_effective_status := CASE
    WHEN d.status = 'pending' AND d.expires_at <= now() THEN 'expired'
    ELSE d.status
  END;

  IF d.status = 'published' THEN
    SELECT h.lines INTO v_before
    FROM public.catalog_product_recipe_history h
    WHERE h.draft_id = d.id
    ORDER BY h.replaced_at DESC
    LIMIT 1;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ingredient_id', l.ingredient_id, 'quantity', l.quantity)), '[]'::jsonb)
      INTO v_before
    FROM public.catalog_product_recipes r
    JOIN public.catalog_product_recipe_lines l ON l.recipe_id = r.id
    WHERE r.product_id = d.product_id AND r.modifier_option_id IS NULL;
  END IF;
  v_before := COALESCE(v_before, '[]'::jsonb);
  v_has_live := jsonb_array_length(v_before) > 0;

  WITH bef AS (
    SELECT (e ->> 'ingredient_id')::uuid AS ingredient_id, (e ->> 'quantity')::numeric AS qty
    FROM jsonb_array_elements(v_before) e
  ),
  aft AS (
    SELECT (e ->> 'ingredient_id')::uuid AS ingredient_id, (e ->> 'quantity')::numeric AS qty, ord
    FROM jsonb_array_elements(d.lines) WITH ORDINALITY AS t(e, ord)
  ),
  joined AS (
    SELECT
      COALESCE(a.ingredient_id, b.ingredient_id) AS ingredient_id,
      b.qty AS before_qty,
      a.qty AS after_qty,
      COALESCE(a.ord, 1000) AS ord
    FROM aft a
    FULL OUTER JOIN bef b ON b.ingredient_id = a.ingredient_id
  ),
  priced AS (
    SELECT
      j.*,
      i.name,
      i.unit_code,
      i.kind,
      COALESCE(i.is_deleted, true) AS deleted,
      CASE WHEN COALESCE(io.track_cogs, false) THEN COALESCE(io.avg_cost, 0) ELSE 0 END AS unit_cost,
      (COALESCE(io.track_cogs, false) AND COALESCE(io.avg_cost, 0) > 0) AS has_cost
    FROM joined j
    LEFT JOIN public.catalog_ingredients i ON i.id = j.ingredient_id
    LEFT JOIN public.catalog_ingredient_outlets io
      ON io.ingredient_id = j.ingredient_id AND io.outlet_id = d.outlet_id AND io.organization_id = d.organization_id
  ),
  shaped AS (
    SELECT
      p.*,
      COALESCE(p.before_qty, 0) * p.unit_cost AS before_cost,
      COALESCE(p.after_qty, 0) * p.unit_cost AS after_cost,
      CASE
        WHEN p.after_qty IS NULL THEN 'removed'
        WHEN p.before_qty IS NULL THEN 'new'
        WHEN p.after_qty <> p.before_qty THEN 'changed'
        ELSE 'same'
      END AS change,
      (p.after_qty IS NOT NULL AND (
        (p.unit_code IN ('kg', 'l') AND p.after_qty > 1)
        OR (p.unit_code IN ('g', 'ml') AND p.after_qty > 1000)
        OR (p.before_qty IS NOT NULL AND p.before_qty > 0 AND p.after_qty / p.before_qty >= 5)
      )) AS unusual
    FROM priced p
  )
  SELECT
    COALESCE(jsonb_agg(jsonb_build_object(
      'ingredient_id', s.ingredient_id,
      'name', COALESCE(s.name, '(bahan tidak ditemukan)'),
      'unit_code', s.unit_code,
      'kind', s.kind,
      'deleted', s.deleted,
      'unit_cost', s.unit_cost,
      'has_cost', s.has_cost,
      'before_qty', s.before_qty,
      'after_qty', s.after_qty,
      'before_cost', round(s.before_cost, 2),
      'after_cost', round(s.after_cost, 2),
      'delta_cost', round(s.after_cost - s.before_cost, 2),
      'change', s.change,
      'unusual', s.unusual
    ) ORDER BY s.ord, s.name), '[]'::jsonb),
    COALESCE(SUM(s.before_cost), 0),
    COALESCE(SUM(s.after_cost), 0)
  INTO v_rows, v_hpp_before, v_hpp_after
  FROM shaped s;

  IF v_effective_status <> 'pending' THEN
    v_blocking := v_blocking || jsonb_build_object('code', 'not_pending', 'status', v_effective_status);
  END IF;
  IF d.status = 'pending' AND d.base_fingerprint <> public.catalog_recipe_fingerprint(d.product_id) THEN
    v_blocking := v_blocking || jsonb_build_object('code', 'stale');
  END IF;
  SELECT jsonb_agg(r ->> 'name') INTO v_names
  FROM jsonb_array_elements(v_rows) r
  WHERE (r ->> 'after_qty') IS NOT NULL AND (r ->> 'deleted')::boolean;
  IF v_names IS NOT NULL THEN
    v_blocking := v_blocking || jsonb_build_object('code', 'deleted_ingredient', 'items', v_names);
  END IF;
  IF jsonb_array_length(d.lines) = 0 THEN
    v_blocking := v_blocking || jsonb_build_object('code', 'empty');
  END IF;

  SELECT jsonb_agg(r ->> 'name') INTO v_names
  FROM jsonb_array_elements(v_rows) r
  WHERE (r ->> 'after_qty') IS NOT NULL AND NOT (r ->> 'has_cost')::boolean AND NOT (r ->> 'deleted')::boolean;
  IF v_names IS NOT NULL THEN
    v_warnings := v_warnings || jsonb_build_object('code', 'missing_cost', 'items', v_names);
  END IF;
  SELECT jsonb_agg(r ->> 'name') INTO v_names
  FROM jsonb_array_elements(v_rows) r WHERE (r ->> 'unusual')::boolean;
  IF v_names IS NOT NULL THEN
    v_warnings := v_warnings || jsonb_build_object('code', 'unusual_quantity', 'items', v_names);
  END IF;
  SELECT jsonb_agg(r ->> 'name') INTO v_names
  FROM jsonb_array_elements(v_rows) r WHERE r ->> 'change' = 'removed';
  IF v_names IS NOT NULL THEN
    v_warnings := v_warnings || jsonb_build_object('code', 'removed_ingredient', 'items', v_names);
  END IF;
  IF v_hpp_before > 0 AND abs(v_hpp_after - v_hpp_before) / v_hpp_before > 0.2 THEN
    v_warnings := v_warnings || jsonb_build_object(
      'code', 'hpp_change',
      'percent', round((v_hpp_after - v_hpp_before) / v_hpp_before * 100, 1)
    );
  END IF;

  RETURN jsonb_build_object(
    'draft', jsonb_build_object(
      'id', d.id,
      'status', v_effective_status,
      'draft_type', d.draft_type,
      'source', d.source,
      'product_id', d.product_id,
      'product_name', v_product,
      'category', v_category,
      'outlet_id', d.outlet_id,
      'outlet_name', v_outlet,
      'request_note', d.request_note,
      'requested_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.user_id = d.requested_by LIMIT 1),
      'created_at', d.created_at,
      'edited', d.edited_at IS NOT NULL,
      'edited_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.user_id = d.edited_by LIMIT 1),
      'edited_at', d.edited_at,
      'expires_at', d.expires_at,
      'decided_at', d.decided_at,
      'decided_by_name', (SELECT p.full_name FROM public.profiles p WHERE p.user_id = d.decided_by LIMIT 1),
      'decision_note', d.decision_note
    ),
    'can_manage', public._recipe_is_manager(p_user, d.organization_id),
    'has_live_recipe', v_has_live,
    'selling_price', v_price,
    'finished_goods_cost', v_fg,
    'rows', v_rows,
    'original_lines', d.original_lines,
    'totals', jsonb_build_object(
      'hpp_before', CASE WHEN v_has_live THEN round(v_hpp_before, 2) END,
      'hpp_after', round(v_hpp_after, 2),
      'delta', CASE WHEN v_has_live THEN round(v_hpp_after - v_hpp_before, 2) END,
      'margin_before', CASE WHEN v_has_live THEN round(v_price - v_hpp_before, 2) END,
      'margin_after', round(v_price - v_hpp_after, 2),
      'margin_pct_before', CASE WHEN v_has_live AND v_price > 0 THEN round((v_price - v_hpp_before) / v_price * 100, 1) END,
      'margin_pct_after', CASE WHEN v_price > 0 THEN round((v_price - v_hpp_after) / v_price * 100, 1) END
    ),
    'warnings', v_warnings,
    'blocking', v_blocking,
    'requires_confirmation', jsonb_array_length(v_warnings) > 0,
    'can_publish', jsonb_array_length(v_blocking) = 0 AND public._recipe_is_manager(p_user, d.organization_id)
  );
END;
$$;


ALTER FUNCTION "public"."_recipe_draft_review"("p_draft_id" "uuid", "p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_is_manager"("p_user" "uuid", "p_org" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public._recipe_is_member(p_user, p_org) AND EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = p_user AND ur.organization_id = p_org AND ur.role IN ('owner', 'admin')
  );
$$;


ALTER FUNCTION "public"."_recipe_is_manager"("p_user" "uuid", "p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recipe_is_member"("p_user" "uuid", "p_org" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p_user IS NOT NULL AND p_org IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_user AND uo.organization_id = p_org AND COALESCE(uo.is_active, true)
  );
$$;


ALTER FUNCTION "public"."_recipe_is_member"("p_user" "uuid", "p_org" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_regenerate_plan_features_for_plan"("p_subscription_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan public.subscription_plans%ROWTYPE;
  v_modules jsonb;
  v_features jsonb;
BEGIN
  SELECT * INTO v_plan
  FROM public.subscription_plans
  WHERE id = p_subscription_plan_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan not found' USING ERRCODE = 'P0002';
  END IF;

  v_modules := public._plan_modules_json_for_plan(p_subscription_plan_id);
  v_features := public._build_plan_features_from_modules(
    v_plan.base_price_per_member,
    v_modules,
    v_plan.max_members
  );

  RETURN v_features;
END;
$$;


ALTER FUNCTION "public"."_regenerate_plan_features_for_plan"("p_subscription_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_resolve_plan_max_members"("p_max_members" integer, "p_jumlah_hari_trial" integer, "p_base_price_per_member" numeric) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_validated integer;
BEGIN
  IF p_base_price_per_member IS NOT NULL AND p_base_price_per_member > 0 THEN
    IF p_max_members IS NOT NULL THEN
      RETURN public._validate_plan_max_members(p_max_members);
    END IF;
    RETURN NULL;
  END IF;

  v_validated := public._validate_plan_max_members(p_max_members);
  IF v_validated IS NOT NULL THEN
    RETURN v_validated;
  END IF;

  IF p_jumlah_hari_trial IS NOT NULL AND p_jumlah_hari_trial > 0 THEN
    RETURN 1;
  END IF;

  RETURN 1;
END;
$$;


ALTER FUNCTION "public"."_resolve_plan_max_members"("p_max_members" integer, "p_jumlah_hari_trial" integer, "p_base_price_per_member" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_cart_subtotal"("p_cart" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(SUM(GREATEST(0, COALESCE((elem ->> 'quantity')::numeric, 0)) * GREATEST(0, COALESCE((elem ->> 'unitPrice')::numeric, 0))), 0)
  FROM jsonb_array_elements(COALESCE(p_cart, '[]'::jsonb)) AS elem;
$$;


ALTER FUNCTION "public"."_synckerja_order_cart_subtotal"("p_cart" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_checkout_totals"("p_org" "uuid", "p_subtotal" numeric, "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_sales_type_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_subtotal numeric := GREATEST(0, round(COALESCE(p_subtotal, 0)));
  v_settings public.catalog_checkout_settings%ROWTYPE;
  v_method text := 'add';
  v_tax_enabled boolean := false;
  v_grat_enabled boolean := false;
  v_sales_type_id uuid := p_sales_type_id;
  v_grat_lines jsonb := '[]'::jsonb;
  v_tax_lines jsonb := '[]'::jsonb;
  v_grat numeric := 0;
  v_tax numeric := 0;
  v_tax_base numeric := 0;
  v_grat_pct numeric := 0;
  v_tax_pct numeric := 0;
  v_pre_tax numeric := 0;
  v_grand numeric := 0;
BEGIN
  SELECT * INTO v_settings
  FROM public.catalog_checkout_settings
  WHERE organization_id = p_org;

  v_method := CASE
    WHEN COALESCE(v_settings.application_method, 'add') = 'include' THEN 'include'
    ELSE 'add'
  END;
  v_tax_enabled := COALESCE(v_settings.tax_enabled, false);
  v_grat_enabled := COALESCE(v_settings.gratuity_enabled, false);

  IF v_sales_type_id IS NULL AND p_outlet_id IS NOT NULL THEN
    SELECT st.id INTO v_sales_type_id
    FROM public.catalog_sales_types st
    JOIN public.catalog_sales_type_outlets sto
      ON sto.sales_type_id = st.id AND sto.outlet_id = p_outlet_id
    WHERE st.organization_id = p_org
      AND st.is_active
      AND lower(st.name) LIKE '%dine%'
    ORDER BY st.sort_order
    LIMIT 1;
  END IF;

  IF v_grat_enabled THEN
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', g.name,
          'amount', 0,
          'amount_percent', g.amount_percent
        )
        ORDER BY g.sort_order, g.name
      ), '[]'::jsonb),
      COALESCE(SUM(g.amount_percent), 0)
    INTO v_grat_lines, v_grat_pct
    FROM public.catalog_gratuities g
    WHERE g.organization_id = p_org
      AND g.is_active = true
      AND g.amount_percent > 0
      AND (
        p_outlet_id IS NULL
        OR EXISTS (
          SELECT 1 FROM public.catalog_gratuity_outlets go
          WHERE go.gratuity_id = g.id AND go.outlet_id = p_outlet_id
        )
      )
      AND (
        v_sales_type_id IS NULL
        OR EXISTS (
          SELECT 1 FROM public.catalog_sales_type_gratuities gst
          WHERE gst.gratuity_id = g.id AND gst.sales_type_id = v_sales_type_id
        )
      );
  END IF;

  IF v_tax_enabled THEN
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', t.name,
          'amount', 0,
          'amount_percent', t.amount_percent
        )
        ORDER BY t.sort_order, t.name
      ), '[]'::jsonb),
      COALESCE(SUM(t.amount_percent), 0)
    INTO v_tax_lines, v_tax_pct
    FROM public.catalog_taxes t
    WHERE t.organization_id = p_org
      AND t.is_active = true
      AND t.amount_percent > 0
      AND (
        p_outlet_id IS NULL
        OR EXISTS (
          SELECT 1 FROM public.catalog_tax_outlets txo
          WHERE txo.tax_id = t.id AND txo.outlet_id = p_outlet_id
        )
      );
  END IF;

  v_grat_lines := COALESCE(v_grat_lines, '[]'::jsonb);
  v_tax_lines := COALESCE(v_tax_lines, '[]'::jsonb);
  v_grat_pct := COALESCE(v_grat_pct, 0);
  v_tax_pct := COALESCE(v_tax_pct, 0);

  IF v_method = 'include' THEN
    IF (v_grat_pct + v_tax_pct) > 0 AND v_subtotal > 0 THEN
      v_pre_tax := round(v_subtotal / (1 + (v_grat_pct + v_tax_pct) / 100.0));
    ELSE
      v_pre_tax := v_subtotal;
    END IF;

    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', line ->> 'name',
          'amount', round(v_pre_tax * (line ->> 'amount_percent')::numeric / 100.0),
          'amount_percent', (line ->> 'amount_percent')::numeric
        )
      ), '[]'::jsonb),
      COALESCE(SUM(round(v_pre_tax * (line ->> 'amount_percent')::numeric / 100.0)), 0)
    INTO v_grat_lines, v_grat
    FROM jsonb_array_elements(v_grat_lines) AS line;

    v_tax_base := v_pre_tax + v_grat;

    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', line ->> 'name',
          'amount', round(v_tax_base * (line ->> 'amount_percent')::numeric / 100.0),
          'amount_percent', (line ->> 'amount_percent')::numeric
        )
      ), '[]'::jsonb),
      COALESCE(SUM(round(v_tax_base * (line ->> 'amount_percent')::numeric / 100.0)), 0)
    INTO v_tax_lines, v_tax
    FROM jsonb_array_elements(v_tax_lines) AS line;

    v_grand := v_subtotal;
  ELSE
    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', line ->> 'name',
          'amount', round(v_subtotal * (line ->> 'amount_percent')::numeric / 100.0),
          'amount_percent', (line ->> 'amount_percent')::numeric
        )
      ), '[]'::jsonb),
      COALESCE(SUM(round(v_subtotal * (line ->> 'amount_percent')::numeric / 100.0)), 0)
    INTO v_grat_lines, v_grat
    FROM jsonb_array_elements(v_grat_lines) AS line;

    v_tax_base := v_subtotal + v_grat;

    SELECT
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'name', line ->> 'name',
          'amount', round(v_tax_base * (line ->> 'amount_percent')::numeric / 100.0),
          'amount_percent', (line ->> 'amount_percent')::numeric
        )
      ), '[]'::jsonb),
      COALESCE(SUM(round(v_tax_base * (line ->> 'amount_percent')::numeric / 100.0)), 0)
    INTO v_tax_lines, v_tax
    FROM jsonb_array_elements(v_tax_lines) AS line;

    v_grand := v_subtotal + v_grat + v_tax;
  END IF;

  RETURN jsonb_build_object(
    'subtotal', v_subtotal,
    'taxBase', v_tax_base,
    'taxLines', COALESCE(v_tax_lines, '[]'::jsonb),
    'gratuityLines', COALESCE(v_grat_lines, '[]'::jsonb),
    'taxTotal', COALESCE(v_tax, 0),
    'gratuityTotal', COALESCE(v_grat, 0),
    'grandTotal', v_grand,
    'applicationMethod', v_method
  );
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_checkout_totals"("p_org" "uuid", "p_subtotal" numeric, "p_outlet_id" "uuid", "p_sales_type_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_synckerja_order_checkout_totals"("p_org" "uuid", "p_subtotal" numeric, "p_outlet_id" "uuid", "p_sales_type_id" "uuid") IS 'Guest-order totals aligned with POS computeCatalogCheckoutTotals (tax on subtotal+gratuity when application_method=add).';



CREATE OR REPLACE FUNCTION "public"."_synckerja_order_default_weekly_hours"() RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT jsonb_build_array(
    jsonb_build_object('dow', 1, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 2, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 3, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 4, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 5, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 6, 'closed', false, 'open', '11:00', 'close', '22:00'),
    jsonb_build_object('dow', 7, 'closed', false, 'open', '11:00', 'close', '22:00')
  );
$$;


ALTER FUNCTION "public"."_synckerja_order_default_weekly_hours"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_ensure_lead"("p_org" "uuid", "p_actor" "uuid", "p_status" "uuid", "p_client" "text", "p_phone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead uuid;
  v_existing_client text;
  v_phone text;
  v_email text;
  v_phone_key text;
  v_client text;
BEGIN
  v_client := COALESCE(NULLIF(btrim(p_client), ''), 'Walk-in');
  IF public.is_generic_customer_name(v_client) THEN
    v_client := 'Walk-in';
  END IF;
  v_phone := NULLIF(left(btrim(COALESCE(p_phone, '')), 32), '');
  v_email := NULLIF(left(btrim(COALESCE(p_email, '')), 120), '');
  v_phone_key := public.normalize_wa_phone_key(v_phone);

  IF v_phone_key IS NOT NULL THEN
    SELECT l.id, l.client
    INTO v_lead, v_existing_client
    FROM public.leads l
    WHERE l.organization_id = p_org
      AND l.merged_into_lead_id IS NULL
      AND l.phone_number IS NOT NULL
      AND public.normalize_wa_phone_key(l.phone_number) = v_phone_key
    ORDER BY l.updated_at DESC NULLS LAST, l.created_at DESC
    LIMIT 1;

    IF v_lead IS NOT NULL THEN
      IF public.is_generic_customer_name(v_existing_client)
         AND NOT public.is_generic_customer_name(v_client) THEN
        UPDATE public.leads SET client = v_client WHERE id = v_lead;
      END IF;
      IF v_email IS NOT NULL THEN
        UPDATE public.leads
        SET email = COALESCE(NULLIF(btrim(email), ''), v_email)
        WHERE id = v_lead;
      END IF;
      RETURN v_lead;
    END IF;
  END IF;

  BEGIN
    INSERT INTO public.leads (
      ticket_id, client, title, category, created_by, created_by_name, assignee,
      status_id, organization_id, source, followup, phone_number, email
    ) VALUES (
      'pos-walkin-' || gen_random_uuid()::text,
      v_client,
      'POS Walk-in',
      'POS',
      p_actor,
      'Synckerja Order',
      '',
      p_status,
      p_org,
      'POS',
      0,
      v_phone,
      v_email
    ) RETURNING id INTO v_lead;
  EXCEPTION
    WHEN OTHERS THEN
      IF SQLERRM LIKE '%pos_checkout_phone_exists%' AND v_phone_key IS NOT NULL THEN
        SELECT l.id INTO v_lead
        FROM public.leads l
        WHERE l.organization_id = p_org
          AND l.merged_into_lead_id IS NULL
          AND l.phone_number IS NOT NULL
          AND public.normalize_wa_phone_key(l.phone_number) = v_phone_key
        ORDER BY l.updated_at DESC NULLS LAST, l.created_at DESC
        LIMIT 1;
        IF v_lead IS NULL THEN
          RAISE;
        END IF;
      ELSE
        RAISE;
      END IF;
  END;

  RETURN v_lead;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_ensure_lead"("p_org" "uuid", "p_actor" "uuid", "p_status" "uuid", "p_client" "text", "p_phone" "text", "p_email" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_synckerja_order_ensure_lead"("p_org" "uuid", "p_actor" "uuid", "p_status" "uuid", "p_client" "text", "p_phone" "text", "p_email" "text") IS 'Find or create a POS lead for Synckerja Order checkout; reuses phone matches instead of duplicate insert.';



CREATE OR REPLACE FUNCTION "public"."_synckerja_order_fire_kitchen"("p_org" "uuid", "p_outlet" "uuid", "p_session" "uuid", "p_table_id" "uuid", "p_table_name" "text", "p_customer_name" "text", "p_cart" "jsonb", "p_event" "text", "p_sales_type_label" "text", "p_sales_type_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_policy text;
  v_should boolean := false;
  v_had boolean := false;
  v_ticket uuid;
  v_line jsonb;
  v_sort int := 0;
BEGIN
  SELECT COALESCE(kitchen_fire_by_sales_type ->> 'dine_in', 'save_bill')
  INTO v_policy
  FROM public.pos_kitchen_outlet_settings
  WHERE organization_id = p_org AND outlet_id = p_outlet
  LIMIT 1;
  v_policy := COALESCE(v_policy, 'save_bill');

  SELECT EXISTS (
    SELECT 1 FROM public.pos_kitchen_tickets t
    WHERE t.session_id = p_session AND t.status IN ('new', 'in_progress', 'ready', 'done')
  ) INTO v_had;

  IF p_event = 'save_bill' THEN
    v_should := (v_policy = 'save_bill');
  ELSIF p_event = 'on_pay' THEN
    v_should := (v_policy = 'on_pay') OR (v_policy = 'save_bill' AND NOT v_had);
  END IF;
  IF NOT v_should THEN
    RETURN;
  END IF;
  IF jsonb_array_length(COALESCE(p_cart, '[]'::jsonb)) < 1 THEN
    RETURN;
  END IF;

  INSERT INTO public.pos_kitchen_tickets (
    organization_id, outlet_id, session_id, pos_table_id, table_name,
    customer_name, sales_type_id, sales_type_label, status
  ) VALUES (
    p_org, p_outlet, p_session, p_table_id, COALESCE(NULLIF(btrim(p_table_name), ''), 'Walk-in'),
    NULLIF(btrim(COALESCE(p_customer_name, '')), ''), p_sales_type_id, p_sales_type_label, 'new'
  ) RETURNING id INTO v_ticket;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_cart)
  LOOP
    IF COALESCE(v_line ->> 'kind', 'product') <> 'product' THEN
      CONTINUE;
    END IF;
    v_sort := v_sort + 1;
    INSERT INTO public.pos_kitchen_ticket_lines (
      ticket_id, line_fingerprint, display_name, modifiers_text, quantity, sort_index
    ) VALUES (
      v_ticket,
      COALESCE(NULLIF(v_line ->> 'lineKey', ''), 'plain:' || COALESCE(v_line ->> 'catalogId', '')),
      COALESCE(NULLIF(v_line ->> 'serviceName', ''), 'Item'),
      public._synckerja_order_line_modifiers_text(v_line),
      GREATEST(1, floor(COALESCE((v_line ->> 'quantity')::numeric, 1))::int),
      v_sort
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_fire_kitchen"("p_org" "uuid", "p_outlet" "uuid", "p_session" "uuid", "p_table_id" "uuid", "p_table_name" "text", "p_customer_name" "text", "p_cart" "jsonb", "p_event" "text", "p_sales_type_label" "text", "p_sales_type_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_hhmm_minutes"("p_value" "text") RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_h int;
  v_m int;
BEGIN
  IF p_value IS NULL OR p_value !~ '^\d{1,2}:\d{2}$' THEN
    RETURN 0;
  END IF;
  v_h := GREATEST(0, LEAST(23, split_part(p_value, ':', 1)::int));
  v_m := GREATEST(0, LEAST(59, split_part(p_value, ':', 2)::int));
  RETURN v_h * 60 + v_m;
END;
$_$;


ALTER FUNCTION "public"."_synckerja_order_hhmm_minutes"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_hour_rule"("p_hours" "jsonb", "p_dow" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT COALESCE(
    (
      SELECT elem
      FROM jsonb_array_elements(COALESCE(p_hours, public._synckerja_order_default_weekly_hours())) elem
      WHERE (elem ->> 'dow')::int = p_dow
      LIMIT 1
    ),
    jsonb_build_object('dow', p_dow, 'closed', false, 'open', '11:00', 'close', '22:00')
  );
$$;


ALTER FUNCTION "public"."_synckerja_order_hour_rule"("p_hours" "jsonb", "p_dow" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_hours_state"("p_outlet" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_force boolean := false;
  v_hours jsonb := public._synckerja_order_default_weekly_hours();
  v_now timestamp;
  v_dow int;
  v_mins int;
  v_today jsonb;
  v_yest jsonb;
  v_open boolean := false;
  v_from_yest boolean := false;
  v_open_m int;
  v_close_m int;
  v_y_open_m int;
  v_y_close_m int;
  v_open_hhmm text;
  v_close_hhmm text;
  v_next_dow int;
  v_next_hhmm text;
  v_next_today boolean := false;
  v_offset int;
  v_cursor int;
  v_rule jsonb;
  v_tz text := 'Asia/Jakarta';
BEGIN
  SELECT
    COALESCE(force_closed, false),
    COALESCE(weekly_hours, public._synckerja_order_default_weekly_hours()),
    COALESCE(NULLIF(timezone, ''), 'Asia/Jakarta')
  INTO v_force, v_hours, v_tz
  FROM public.synckerja_order_outlet_settings
  WHERE outlet_id = p_outlet;

  v_now := timezone(v_tz, now());
  v_dow := EXTRACT(ISODOW FROM v_now)::int;
  v_mins := EXTRACT(HOUR FROM v_now)::int * 60 + EXTRACT(MINUTE FROM v_now)::int;
  v_today := public._synckerja_order_hour_rule(v_hours, v_dow);
  v_yest := public._synckerja_order_hour_rule(v_hours, CASE WHEN v_dow = 1 THEN 7 ELSE v_dow - 1 END);

  IF v_force THEN
    v_open := false;
  ELSE
    v_open_m := public._synckerja_order_hhmm_minutes(v_today ->> 'open');
    v_close_m := public._synckerja_order_hhmm_minutes(v_today ->> 'close');
    v_y_open_m := public._synckerja_order_hhmm_minutes(v_yest ->> 'open');
    v_y_close_m := public._synckerja_order_hhmm_minutes(v_yest ->> 'close');

    IF NOT COALESCE((v_today ->> 'closed')::boolean, false) THEN
      IF v_close_m = v_open_m THEN
        v_open := true;
      ELSIF v_close_m > v_open_m THEN
        v_open := v_mins >= v_open_m AND v_mins < v_close_m;
      ELSE
        v_open := v_mins >= v_open_m;
      END IF;
    END IF;

    IF NOT v_open
      AND NOT COALESCE((v_yest ->> 'closed')::boolean, false)
      AND v_y_close_m < v_y_open_m
      AND v_mins < v_y_close_m
    THEN
      v_open := true;
      v_from_yest := true;
    END IF;
  END IF;

  IF v_open THEN
    IF v_from_yest THEN
      v_open_hhmm := v_yest ->> 'open';
      v_close_hhmm := v_yest ->> 'close';
    ELSE
      v_open_hhmm := v_today ->> 'open';
      v_close_hhmm := v_today ->> 'close';
    END IF;
    RETURN jsonb_build_object(
      'is_open', true,
      'force_closed', v_force,
      'open_hhmm', v_open_hhmm,
      'close_hhmm', v_close_hhmm,
      'next_open_hhmm', NULL,
      'next_open_is_today', false,
      'next_open_dow', NULL,
      'next_open_at', NULL,
      'closes_at', (
        CASE
          WHEN v_from_yest THEN (date_trunc('day', v_now) + make_interval(mins => public._synckerja_order_hhmm_minutes(v_close_hhmm)))
          WHEN public._synckerja_order_hhmm_minutes(v_close_hhmm) < public._synckerja_order_hhmm_minutes(v_open_hhmm)
            THEN (date_trunc('day', v_now) + interval '1 day' + make_interval(mins => public._synckerja_order_hhmm_minutes(v_close_hhmm)))
          ELSE (date_trunc('day', v_now) + make_interval(mins => public._synckerja_order_hhmm_minutes(v_close_hhmm)))
        END
      ) AT TIME ZONE v_tz
    );
  END IF;

  IF NOT v_force AND NOT COALESCE((v_today ->> 'closed')::boolean, false)
    AND v_mins < public._synckerja_order_hhmm_minutes(v_today ->> 'open')
  THEN
    v_next_dow := v_dow;
    v_next_hhmm := v_today ->> 'open';
    v_next_today := true;
    v_offset := 0;
  ELSE
    v_next_dow := NULL;
    FOR v_offset IN 1..7 LOOP
      v_cursor := ((v_dow - 1 + v_offset) % 7) + 1;
      v_rule := public._synckerja_order_hour_rule(v_hours, v_cursor);
      IF NOT COALESCE((v_rule ->> 'closed')::boolean, false) THEN
        v_next_dow := v_cursor;
        v_next_hhmm := v_rule ->> 'open';
        EXIT;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'is_open', false,
    'force_closed', v_force,
    'open_hhmm', NULL,
    'close_hhmm', NULL,
    'next_open_hhmm', v_next_hhmm,
    'next_open_is_today', v_next_today,
    'next_open_dow', v_next_dow,
    'next_open_at', CASE
      WHEN v_next_hhmm IS NULL THEN NULL
      ELSE (
        date_trunc('day', v_now)
        + make_interval(days => COALESCE(v_offset, 0))
        + make_interval(mins => public._synckerja_order_hhmm_minutes(v_next_hhmm))
      ) AT TIME ZONE v_tz
    END,
    'closes_at', NULL
  );
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_hours_state"("p_outlet" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_line_modifiers_text"("p_line" "jsonb") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
  SELECT NULLIF(
    concat_ws(
      ' · ',
      NULLIF(
        concat_ws(
          ', ',
          NULLIF(btrim(COALESCE(p_line ->> 'variantName', '')), ''),
          (
            SELECT string_agg(txt, ', ' ORDER BY ord)
            FROM (
              SELECT
                CASE
                  WHEN nm IS NULL THEN NULL
                  WHEN GREATEST(1, floor(COALESCE((m ->> 'quantity')::numeric, 1))) > 1
                    THEN nm || ' ×' || GREATEST(1, floor(COALESCE((m ->> 'quantity')::numeric, 1)))::int::text
                  ELSE nm
                END AS txt,
                ord
              FROM jsonb_array_elements(COALESCE(p_line -> 'modifiers', '[]'::jsonb)) WITH ORDINALITY AS t(m, ord)
              CROSS JOIN LATERAL (
                SELECT NULLIF(btrim(COALESCE(m ->> 'name', m ->> 'option_name', '')), '') AS nm
              ) named
            ) labeled
            WHERE txt IS NOT NULL
          )
        ),
        ''
      ),
      CASE
        WHEN public._synckerja_order_sanitize_kitchen_note(
          COALESCE(p_line ->> 'kitchenNote', p_line ->> 'kitchen_note')
        ) IS NULL THEN NULL
        ELSE 'Catatan: ' || public._synckerja_order_sanitize_kitchen_note(
          COALESCE(p_line ->> 'kitchenNote', p_line ->> 'kitchen_note')
        )
      END
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."_synckerja_order_line_modifiers_text"("p_line" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_modifier_option_oos"("p_outlet" "uuid", "p_group_id" "uuid", "p_option_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_stock boolean;
BEGIN
  SELECT COALESCE(g.stock_enabled, false)
  INTO v_stock
  FROM public.catalog_modifier_groups g
  WHERE g.id = p_group_id;
  IF NOT COALESCE(v_stock, false) THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.catalog_modifier_option_ingredients i
    WHERE i.option_id = p_option_id
  ) THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1
    FROM public.catalog_modifier_option_ingredients i
    JOIN public.catalog_ingredients ing ON ing.id = i.ingredient_id
    LEFT JOIN public.catalog_ingredient_outlets io
      ON io.ingredient_id = i.ingredient_id
     AND io.outlet_id = p_outlet
    WHERE i.option_id = p_option_id
      AND COALESCE(ing.track_inventory, false) = true
      AND COALESCE(io.in_stock, 0) < i.quantity
  );
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_modifier_option_oos"("p_outlet" "uuid", "p_group_id" "uuid", "p_option_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_new_claim_token"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text;
  v_try integer := 0;
BEGIN
  LOOP
    v_token := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.pos_pending_checkouts p WHERE p.claim_token = v_token
    );
    v_try := v_try + 1;
    IF v_try > 12 THEN
      RAISE EXCEPTION 'claim_token_collision';
    END IF;
  END LOOP;
  RETURN v_token;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_new_claim_token"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_org_actor"("p_org" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT ur.user_id FROM public.user_roles ur
  WHERE ur.organization_id = p_org AND lower(ur.role::text) IN ('owner', 'admin')
  ORDER BY CASE WHEN lower(ur.role::text) = 'owner' THEN 0 ELSE 1 END LIMIT 1;
$$;


