CREATE OR REPLACE FUNCTION "public"."_synckerja_order_resolve_outlet"("p_code" "text") RETURNS TABLE("organization_id" "uuid", "outlet_id" "uuid", "outlet_name" "text", "public_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT o.organization_id, o.id, o.name, o.public_code
  FROM public.pos_outlets o
  JOIN public.synckerja_order_outlet_settings s ON s.outlet_id = o.id AND s.enabled = true
  JOIN public.synckerja_order_org_settings org ON org.organization_id = o.organization_id
    AND org.terms_accepted_at IS NOT NULL
  WHERE o.public_code = lower(btrim(p_code))
    AND o.is_deleted = false
    AND o.is_active = true
    AND public.synckerja_order_sales_module_enabled(o.organization_id, 'pos')
    AND public.synckerja_order_subscription_current(o.organization_id)
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_resolve_outlet"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_resolve_outlet_paid"("p_code" "text") RETURNS TABLE("organization_id" "uuid", "outlet_id" "uuid", "outlet_name" "text", "public_code" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT o.organization_id, o.id, o.name, o.public_code
  FROM public.pos_outlets o
  JOIN public.synckerja_order_outlet_settings s ON s.outlet_id = o.id AND s.enabled = true
  JOIN public.synckerja_order_org_settings org ON org.organization_id = o.organization_id
    AND org.terms_accepted_at IS NOT NULL
  WHERE o.public_code = lower(btrim(p_code))
    AND o.is_deleted = false
    AND o.is_active = true
  LIMIT 1;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_resolve_outlet_paid"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_resolve_sales_type"("p_org" "uuid", "p_fulfillment" "text") RETURNS TABLE("sales_type_id" "uuid", "sales_type_name" "text", "fulfillment" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mode text := lower(btrim(COALESCE(p_fulfillment, 'dine_in')));
  v_id uuid;
  v_name text;
BEGIN
  IF v_mode NOT IN ('dine_in', 'takeaway') THEN
    v_mode := 'dine_in';
  END IF;

  IF v_mode = 'takeaway' THEN
    SELECT st.id, st.name INTO v_id, v_name
    FROM public.catalog_sales_types st
    WHERE st.organization_id = p_org
      AND st.is_active
      AND (lower(st.name) LIKE '%take%' OR lower(st.name) LIKE '%bawa%')
    ORDER BY st.sort_order
    LIMIT 1;
    IF v_id IS NULL THEN
      v_name := 'Takeaway';
    END IF;
  ELSE
    SELECT st.id, st.name INTO v_id, v_name
    FROM public.catalog_sales_types st
    WHERE st.organization_id = p_org
      AND st.is_active
      AND lower(st.name) LIKE '%dine%'
    ORDER BY st.sort_order
    LIMIT 1;
    IF v_id IS NULL THEN
      v_name := 'Dine In';
    END IF;
  END IF;

  sales_type_id := v_id;
  sales_type_name := COALESCE(v_name, CASE WHEN v_mode = 'takeaway' THEN 'Takeaway' ELSE 'Dine In' END);
  fulfillment := v_mode;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_resolve_sales_type"("p_org" "uuid", "p_fulfillment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_sanitize_cart"("p_org" "uuid", "p_outlet" "uuid", "p_cart" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line jsonb;
  v_out jsonb := '[]'::jsonb;
  v_item public.default_prices%ROWTYPE;
  v_bundle public.catalog_bundles%ROWTYPE;
  v_qty numeric;
  v_price numeric;
  v_name text;
  v_kind text;
  v_id uuid;
  v_variant_id uuid;
  v_variant_name text;
  v_variant_count int;
  v_skip boolean;
  v_mod jsonb;
  v_opt_id uuid;
  v_mod_qty jsonb;
  v_opt_qty int;
  v_group record;
  v_count int;
  v_min int;
  v_max int;
  v_extras numeric;
  v_resolved jsonb;
  v_opt_name text;
  v_opt_extra numeric;
  v_group_name text;
  v_unknown boolean;
  v_note text;
BEGIN
  IF p_cart IS NULL OR jsonb_typeof(p_cart) <> 'array' THEN
    RETURN '[]'::jsonb;
  END IF;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_cart)
  LOOP
    v_qty := GREATEST(1, floor(COALESCE((v_line ->> 'quantity')::numeric, 1)));
    v_kind := COALESCE(NULLIF(v_line ->> 'kind', ''), 'product');
    v_note := public._synckerja_order_sanitize_kitchen_note(
      COALESCE(v_line ->> 'kitchenNote', v_line ->> 'kitchen_note')
    );
    BEGIN
      v_id := NULLIF(v_line ->> 'catalogId', '')::uuid;
    EXCEPTION WHEN others THEN
      CONTINUE;
    END;
    IF v_id IS NULL THEN
      CONTINUE;
    END IF;

    IF v_kind = 'bundle' THEN
      SELECT cb.* INTO v_bundle
      FROM public.catalog_bundles cb
      JOIN public.synckerja_order_catalog_items ci
        ON ci.bundle_id = cb.id
       AND ci.outlet_id = p_outlet
       AND ci.organization_id = p_org
      JOIN public.catalog_bundle_outlets cbo
        ON cbo.bundle_id = cb.id
       AND cbo.outlet_id = p_outlet
      WHERE cb.id = v_id
        AND cb.organization_id = p_org
        AND cb.is_active
        AND COALESCE(cb.is_deleted, false) = false
      LIMIT 1;
      IF NOT FOUND THEN
        CONTINUE;
      END IF;
      v_out := v_out || jsonb_build_array(
        jsonb_build_object(
          'lineKey', COALESCE(NULLIF(v_line ->> 'lineKey', ''), 'plain:' || v_bundle.id::text),
          'catalogId', v_bundle.id,
          'kind', 'bundle',
          'serviceId', NULL,
          'subServiceId', NULL,
          'serviceName', COALESCE(NULLIF(v_bundle.name, ''), COALESCE(v_line ->> 'serviceName', 'Bundle')),
          'subServiceName', NULL,
          'quantity', v_qty,
          'unitPrice', COALESCE(v_bundle.bundle_price, 0),
          'trackStock', false,
          'inventorySkuId', NULL,
          'availableQty', NULL,
          'productCategoryId', NULL,
          'variantId', NULL,
          'variantName', NULL,
          'modifiers', '[]'::jsonb,
          'kitchenNote', to_jsonb(v_note)
        )
      );
      CONTINUE;
    END IF;

    SELECT dp.* INTO v_item
    FROM public.default_prices dp
    JOIN public.synckerja_order_catalog_items ci
      ON ci.catalog_item_id = dp.id
     AND ci.outlet_id = p_outlet
     AND ci.organization_id = p_org
    JOIN public.catalog_product_outlets cpo
      ON cpo.product_id = dp.id
     AND cpo.outlet_id = p_outlet
     AND cpo.organization_id = p_org
    WHERE dp.id = v_id
      AND dp.organization_id = p_org
      AND COALESCE(cpo.pos_status, dp.pos_status, 'available') <> 'hidden'
    LIMIT 1;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    SELECT count(*)::int INTO v_variant_count
    FROM public.catalog_product_variants v
    WHERE v.product_id = v_item.id;

    v_variant_id := NULL;
    v_variant_name := NULL;
    v_price := COALESCE(v_item.unit_price, 0);
    BEGIN
      v_variant_id := NULLIF(v_line ->> 'variantId', '')::uuid;
    EXCEPTION WHEN others THEN
      v_variant_id := NULL;
    END;

    IF v_variant_count > 0 THEN
      IF v_variant_id IS NOT NULL THEN
        SELECT v.name, v.price INTO v_variant_name, v_price
        FROM public.catalog_product_variants v
        WHERE v.product_id = v_item.id AND v.id = v_variant_id
        LIMIT 1;
        IF NOT FOUND THEN
          CONTINUE;
        END IF;
      ELSIF v_variant_count = 1 THEN
        SELECT v.id, v.name, v.price INTO v_variant_id, v_variant_name, v_price
        FROM public.catalog_product_variants v
        WHERE v.product_id = v_item.id
        ORDER BY v.sort_order
        LIMIT 1;
      ELSE
        CONTINUE;
      END IF;
    ELSE
      v_variant_id := NULL;
      v_variant_name := NULL;
    END IF;

    v_mod_qty := '{}'::jsonb;
    v_skip := false;
    FOR v_mod IN SELECT value FROM jsonb_array_elements(COALESCE(v_line -> 'modifiers', '[]'::jsonb))
    LOOP
      BEGIN
        v_opt_id := COALESCE(NULLIF(v_mod ->> 'optionId', ''), NULLIF(v_mod ->> 'option_id', ''))::uuid;
      EXCEPTION WHEN others THEN
        v_skip := true;
        EXIT;
      END;
      IF v_opt_id IS NULL THEN
        CONTINUE;
      END IF;
      BEGIN
        v_opt_qty := GREATEST(0, floor(COALESCE((v_mod ->> 'quantity')::numeric, 1))::int);
      EXCEPTION WHEN others THEN
        v_opt_qty := 1;
      END;
      IF v_opt_qty < 1 THEN
        CONTINUE;
      END IF;
      v_mod_qty := v_mod_qty || jsonb_build_object(v_opt_id::text, v_opt_qty);
    END LOOP;
    IF v_skip THEN
      CONTINUE;
    END IF;

    SELECT EXISTS (
      SELECT 1
      FROM jsonb_object_keys(v_mod_qty) AS oid
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.catalog_product_modifiers cpm
        JOIN public.catalog_modifier_options o
          ON o.group_id = cpm.group_id
         AND o.id::text = oid
         AND o.is_active
        JOIN public.catalog_modifier_groups g ON g.id = cpm.group_id AND g.is_active
        WHERE cpm.product_id = v_item.id
          AND (
            NOT EXISTS (SELECT 1 FROM public.catalog_modifier_outlets mo WHERE mo.group_id = g.id)
            OR EXISTS (
              SELECT 1 FROM public.catalog_modifier_outlets mo
              WHERE mo.group_id = g.id AND mo.outlet_id = p_outlet
            )
          )
      )
    ) INTO v_unknown;
    IF COALESCE(v_unknown, false) THEN
      CONTINUE;
    END IF;

    v_resolved := '[]'::jsonb;
    v_extras := 0;
    v_skip := false;
    FOR v_group IN
      SELECT
        g.id,
        g.name,
        g.limit_enabled,
        g.is_required,
        g.min_selected,
        g.max_selected,
        COALESCE(g.option_qty_enabled, false) AS option_qty_enabled,
        (
          SELECT count(*)::int
          FROM public.catalog_modifier_options o
          WHERE o.group_id = g.id AND o.is_active
        ) AS option_count
      FROM public.catalog_product_modifiers cpm
      JOIN public.catalog_modifier_groups g ON g.id = cpm.group_id
      WHERE cpm.product_id = v_item.id
        AND g.is_active
        AND (
          NOT EXISTS (SELECT 1 FROM public.catalog_modifier_outlets mo WHERE mo.group_id = g.id)
          OR EXISTS (
            SELECT 1 FROM public.catalog_modifier_outlets mo
            WHERE mo.group_id = g.id AND mo.outlet_id = p_outlet
          )
        )
    LOOP
      IF v_group.limit_enabled THEN
        v_max := GREATEST(1, COALESCE(v_group.max_selected, 1));
        IF v_group.is_required THEN
          v_min := LEAST(v_max, GREATEST(1, COALESCE(v_group.min_selected, 1)));
        ELSE
          v_min := 0;
        END IF;
      ELSE
        v_min := 0;
        v_max := GREATEST(1, COALESCE(v_group.option_count, 1));
      END IF;

      IF v_group.option_qty_enabled THEN
        SELECT COALESCE(SUM(GREATEST(0, (v_mod_qty ->> o.id::text)::int)), 0)::int
        INTO v_count
        FROM public.catalog_modifier_options o
        WHERE o.group_id = v_group.id AND o.is_active;
      ELSE
        SELECT count(*)::int INTO v_count
        FROM public.catalog_modifier_options o
        WHERE o.group_id = v_group.id
          AND o.is_active
          AND v_mod_qty ? o.id::text;
      END IF;

      IF v_count < v_min OR v_count > v_max THEN
        v_skip := true;
        EXIT;
      END IF;

      FOR v_opt_id IN
        SELECT o.id
        FROM public.catalog_modifier_options o
        WHERE o.group_id = v_group.id
          AND o.is_active
          AND v_mod_qty ? o.id::text
        ORDER BY o.sort_order, o.name
      LOOP
        IF public._synckerja_order_modifier_option_oos(p_outlet, v_group.id, v_opt_id) THEN
          v_skip := true;
          EXIT;
        END IF;
        SELECT o.name, COALESCE(o.extra_price, 0)
        INTO v_opt_name, v_opt_extra
        FROM public.catalog_modifier_options o
        WHERE o.id = v_opt_id;
        IF v_group.option_qty_enabled THEN
          v_opt_qty := GREATEST(1, COALESCE((v_mod_qty ->> v_opt_id::text)::int, 1));
        ELSE
          v_opt_qty := 1;
        END IF;
        v_extras := v_extras + COALESCE(v_opt_extra, 0) * v_opt_qty;
        v_group_name := v_group.name;
        v_resolved := v_resolved || jsonb_build_array(
          jsonb_build_object(
            'optionId', v_opt_id,
            'name', v_opt_name,
            'extraPrice', v_opt_extra,
            'quantity', v_opt_qty,
            'groupName', v_group_name
          )
        );
      END LOOP;
      EXIT WHEN v_skip;
    END LOOP;
    IF v_skip THEN
      CONTINUE;
    END IF;

    v_price := GREATEST(0, COALESCE(v_price, 0) + COALESCE(v_extras, 0));
    v_name := COALESCE(NULLIF(v_item.name, ''), COALESCE(v_line ->> 'serviceName', 'Item'));
    v_out := v_out || jsonb_build_array(
      jsonb_build_object(
        'lineKey', COALESCE(NULLIF(v_line ->> 'lineKey', ''), 'plain:' || v_item.id::text),
        'catalogId', v_item.id,
        'kind', COALESCE(NULLIF(v_item.kind, ''), 'product'),
        'serviceId', v_item.service_id,
        'subServiceId', v_item.sub_service_id,
        'serviceName', v_name,
        'subServiceName', v_line -> 'subServiceName',
        'quantity', v_qty,
        'unitPrice', v_price,
        'trackStock', COALESCE(v_item.track_stock, false),
        'inventorySkuId', v_item.inventory_sku_id,
        'availableQty', NULL,
        'productCategoryId', v_item.product_category_id,
        'variantId', v_variant_id,
        'variantName', v_variant_name,
        'modifiers', v_resolved,
        'kitchenNote', to_jsonb(v_note)
      )
    );
  END LOOP;
  RETURN v_out;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_sanitize_cart"("p_org" "uuid", "p_outlet" "uuid", "p_cart" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_sanitize_kitchen_note"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT NULLIF(
    left(
      btrim(
        regexp_replace(
          regexp_replace(
            regexp_replace(COALESCE(p_raw, ''), '<[^>]*>', '', 'g'),
            '[[:cntrl:]]+',
            ' ',
            'g'
          ),
          '\s+',
          ' ',
          'g'
        )
      ),
      200
    ),
    ''
  );
$$;


ALTER FUNCTION "public"."_synckerja_order_sanitize_kitchen_note"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_session_is_guest_cashier_hold"("p_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(s.awaiting_cashier_claim, false)
    OR EXISTS (
      SELECT 1
      FROM public.pos_pending_checkouts p
      WHERE p.session_id = p_session_id
        AND p.checkout_channel = 'synckerja_cashier'
        AND p.status = 'pending'
    )
  FROM public.pos_table_sessions s
  WHERE s.id = p_session_id;
$$;


ALTER FUNCTION "public"."_synckerja_order_session_is_guest_cashier_hold"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_synckerja_order_table_state"("p_org" "uuid", "p_outlet" "uuid", "p_table_name" "text") RETURNS TABLE("table_id" "uuid", "table_name" "text", "group_id" "uuid", "table_pax" integer, "occupied_pax" integer, "remaining_pax" integer, "open_session_id" "uuid", "join_state" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_table public.pos_tables%ROWTYPE;
  v_occ int := 0;
  v_session uuid;
BEGIN
  IF p_table_name IS NULL OR btrim(p_table_name) = '' THEN
    RETURN;
  END IF;
  SELECT t.* INTO v_table
  FROM public.pos_tables t
  WHERE t.organization_id = p_org
    AND t.outlet_id = p_outlet
    AND t.is_deleted = false
    AND lower(btrim(t.name)) = lower(btrim(p_table_name))
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN;
  END IF;
  SELECT COALESCE(SUM(s.pax), 0) INTO v_occ
  FROM public.pos_table_sessions s
  WHERE s.organization_id = p_org
    AND s.outlet_id = p_outlet
    AND s.pos_table_id = v_table.id
    AND s.status = 'open'
    AND NOT COALESCE(public._synckerja_order_session_is_guest_cashier_hold(s.id), false);
  SELECT s.id INTO v_session
  FROM public.pos_table_sessions s
  WHERE s.organization_id = p_org
    AND s.outlet_id = p_outlet
    AND s.pos_table_id = v_table.id
    AND s.status = 'open'
    AND NOT COALESCE(public._synckerja_order_session_is_guest_cashier_hold(s.id), false)
    AND s.sales_activity_id IS NULL
  ORDER BY s.created_at DESC
  LIMIT 1;
  IF v_session IS NULL THEN
    SELECT s.id INTO v_session
    FROM public.pos_table_sessions s
    WHERE s.organization_id = p_org
      AND s.outlet_id = p_outlet
      AND s.pos_table_id = v_table.id
      AND s.status = 'open'
      AND NOT COALESCE(public._synckerja_order_session_is_guest_cashier_hold(s.id), false)
    ORDER BY s.created_at DESC
    LIMIT 1;
  END IF;
  table_id := v_table.id;
  table_name := v_table.name;
  group_id := v_table.group_id;
  table_pax := v_table.pax;
  occupied_pax := v_occ;
  remaining_pax := GREATEST(0, v_table.pax - v_occ);
  open_session_id := v_session;
  IF v_occ <= 0 THEN
    join_state := 'empty';
  ELSIF remaining_pax >= 1 THEN
    join_state := 'join';
  ELSE
    join_state := 'full';
  END IF;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."_synckerja_order_table_state"("p_org" "uuid", "p_outlet" "uuid", "p_table_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_task_step_history_org_id"("p_history_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT dt.organization_id
  FROM public.task_step_history h
  LEFT JOIN public.task_steps ts ON ts.id = h.task_step_id
  LEFT JOIN public.task_steps_to_steps s ON s.id = h.task_steps_to_steps_id
  LEFT JOIN public.task_steps ts2 ON ts2.id = s.parent_step_id
  LEFT JOIN public.daily_tasks dt ON dt.id = COALESCE(ts.task_id, ts2.task_id)
  WHERE h.id = p_history_id
  LIMIT 1;
$$;


ALTER FUNCTION "public"."_task_step_history_org_id"("p_history_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tg_lock_income_if_allocated"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.income_allocations ia WHERE ia.income_transaction_id = OLD.id) THEN
    IF NEW.amount IS DISTINCT FROM OLD.amount
      OR NEW.bank_account_id IS DISTINCT FROM OLD.bank_account_id
      OR NEW.transaction_date IS DISTINCT FROM OLD.transaction_date
      OR NEW.status IS DISTINCT FROM OLD.status
      OR NEW.payment_method IS DISTINCT FROM OLD.payment_method
      OR NEW.income_type_id IS DISTINCT FROM OLD.income_type_id
      OR NEW.category_id IS DISTINCT FROM OLD.category_id
      OR NEW.service_id IS DISTINCT FROM OLD.service_id
      OR NEW.sub_service_id IS DISTINCT FROM OLD.sub_service_id
      OR NEW.is_recurring IS DISTINCT FROM OLD.is_recurring
      OR NEW.recurring_frequency IS DISTINCT FROM OLD.recurring_frequency
      OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
      OR NEW.user_id IS DISTINCT FROM OLD.user_id
    THEN
      RAISE EXCEPTION 'INCOME_HAS_ALLOCATIONS';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_tg_lock_income_if_allocated"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tg_validate_income_allocation_expense_only"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_income RECORD;
  v_other_sum NUMERIC(15, 2);
  v_exp RECORD;
  v_pay RECORD;
  v_alloc_to_pay_sum NUMERIC(15, 2);
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'INCOME_ALLOCATION_IMMUTABLE';
  END IF;

  IF NOT (
    (
      NEW.expense_id IS NOT NULL
      AND NEW.debt_payment_id IS NULL
    )
    OR (
      NEW.expense_id IS NULL
      AND NEW.debt_payment_id IS NOT NULL
    )
  ) THEN
    RAISE EXCEPTION 'INCOME_ALLOCATION_TARGET_XOR';
  END IF;

  SELECT
    it.id,
    it.organization_id,
    it.amount,
    it.bank_account_id
  INTO v_income
  FROM public.income_transactions it
  WHERE
    it.id = NEW.income_transaction_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'INCOME_ALLOCATION_INVALID_INCOME';
  END IF;

  IF NEW.organization_id IS DISTINCT FROM v_income.organization_id THEN
    RAISE EXCEPTION 'INCOME_ALLOCATION_ORG_MISMATCH';
  END IF;

  SELECT
    COALESCE(SUM(ia.amount), 0) INTO v_other_sum
  FROM public.income_allocations ia
  WHERE
    ia.income_transaction_id = NEW.income_transaction_id
    AND ia.id IS DISTINCT FROM NEW.id;

  IF v_other_sum + NEW.amount > v_income.amount THEN
    RAISE EXCEPTION 'INCOME_ALLOCATION_EXCEEDS_INCOME';
  END IF;

  IF NEW.expense_id IS NOT NULL THEN
    SELECT
      e.id,
      e.organization_id,
      e.amount,
      e.bank_account_id
    INTO v_exp
    FROM public.expenses e
    WHERE
      e.id = NEW.expense_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_INVALID_EXPENSE';
    END IF;

    IF v_exp.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_ORG_MISMATCH';
    END IF;

    IF NEW.amount > v_exp.amount THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_EXCEEDS_EXPENSE';
    END IF;

    IF v_income.bank_account_id IS NOT NULL AND v_exp.bank_account_id IS NOT NULL THEN
      IF v_income.bank_account_id IS DISTINCT FROM v_exp.bank_account_id THEN
        RAISE EXCEPTION 'INCOME_ALLOCATION_BANK_MISMATCH';
      END IF;
    END IF;
  ELSE
    SELECT
      dp.id,
      dp.organization_id,
      dp.payment_amount,
      dp.payment_method
    INTO v_pay
    FROM public.debt_payments dp
    WHERE
      dp.id = NEW.debt_payment_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_INVALID_DEBT_PAYMENT';
    END IF;

    IF v_pay.organization_id IS DISTINCT FROM NEW.organization_id THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_ORG_MISMATCH';
    END IF;

    IF v_pay.payment_method IS NULL THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_DEBT_PAYMENT_NO_BANK';
    END IF;

    IF NEW.amount > v_pay.payment_amount THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_EXCEEDS_DEBT_PAYMENT';
    END IF;

    SELECT
      COALESCE(SUM(ia.amount), 0) INTO v_alloc_to_pay_sum
    FROM public.income_allocations ia
    WHERE
      ia.debt_payment_id = NEW.debt_payment_id
      AND ia.id IS DISTINCT FROM NEW.id;

    IF v_alloc_to_pay_sum + NEW.amount > v_pay.payment_amount THEN
      RAISE EXCEPTION 'INCOME_ALLOCATION_DEBT_PAYMENT_OVER_ALLOCATED';
    END IF;

    IF v_income.bank_account_id IS NOT NULL AND v_pay.payment_method IS NOT NULL THEN
      IF v_income.bank_account_id IS DISTINCT FROM v_pay.payment_method THEN
        RAISE EXCEPTION 'INCOME_ALLOCATION_BANK_MISMATCH';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."_tg_validate_income_allocation_expense_only"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_tg_validate_income_allocation_expense_only"() IS 'Validates income_allocations: either expense_id (expense path) or debt_payment_id (debt payment path).';



CREATE OR REPLACE FUNCTION "public"."_time_text_to_minutes"("p_time" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT
    split_part(COALESCE(p_time, '09:00'), ':', 1)::integer * 60
    + COALESCE(NULLIF(split_part(COALESCE(p_time, '09:00'), ':', 2), ''), '0')::integer;
$$;


ALTER FUNCTION "public"."_time_text_to_minutes"("p_time" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_billing_term_discounts"("p_discounts" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_key text; v_val numeric; v_out jsonb := public._default_billing_term_discounts();
BEGIN
  IF p_discounts IS NULL THEN RETURN v_out; END IF;
  IF jsonb_typeof(p_discounts) <> 'object' THEN RAISE EXCEPTION 'billing_term_discounts must be a json object'; END IF;
  FOREACH v_key IN ARRAY ARRAY['1','3','6','12'] LOOP
    IF p_discounts ? v_key AND p_discounts ->> v_key IS NOT NULL AND p_discounts ->> v_key <> 'null' THEN
      v_val := (p_discounts ->> v_key)::numeric;
      IF v_val < 0 OR v_val > 100 THEN RAISE EXCEPTION 'discount out of range'; END IF;
      v_out := jsonb_set(v_out, ARRAY[v_key], to_jsonb(v_val), true);
    END IF;
  END LOOP;
  RETURN v_out;
END; $$;


ALTER FUNCTION "public"."_validate_billing_term_discounts"("p_discounts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_validate_plan_max_members"("p_max_members" integer) RETURNS integer
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_max_members IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_max_members < 1 OR p_max_members > 1000 THEN
    RAISE EXCEPTION 'max_members must be between 1 and 1000' USING ERRCODE = '22023';
  END IF;

  RETURN p_max_members;
END;
$$;


ALTER FUNCTION "public"."_validate_plan_max_members"("p_max_members" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."accept_ownership_transfer"("_transfer_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  uid uuid := auth.uid();
  rec public.ownership_transfers%ROWTYPE;
  updated_rows integer;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT * INTO rec
  FROM public.ownership_transfers
  WHERE id = _transfer_id
    AND status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'transfer not found or not pending';
  END IF;

  IF rec.to_user_id <> uid THEN
    RAISE EXCEPTION 'only the invited user can accept this transfer';
  END IF;

  UPDATE public.user_roles ur
  SET role = 'admin', updated_at = now()
  WHERE ur.organization_id = rec.organization_id
    AND ur.user_id = rec.from_user_id
    AND lower(ur.role) = 'owner';

  UPDATE public.user_roles ur
  SET role = 'owner', updated_at = now()
  WHERE ur.organization_id = rec.organization_id
    AND ur.user_id = rec.to_user_id;

  GET DIAGNOSTICS updated_rows = ROW_COUNT;

  IF updated_rows = 0 THEN
    INSERT INTO public.user_roles (user_id, organization_id, role)
    VALUES (rec.to_user_id, rec.organization_id, 'owner');
  END IF;

  UPDATE public.organizations o
  SET user_id = rec.to_user_id,
      email = COALESCE(
        (
          SELECT NULLIF(btrim(p.email), '')
          FROM public.profiles p
          WHERE p.user_id = rec.to_user_id
        ),
        o.email
      ),
      updated_at = now()
  WHERE o.id = rec.organization_id;

  UPDATE public.employees e
  SET manager_id = NULL
  WHERE e.organization_id = rec.organization_id
    AND e.user_id = rec.to_user_id
    AND e.manager_id IS NOT NULL;

  UPDATE public.ownership_transfers ot
  SET status = 'completed', updated_at = now()
  WHERE ot.id = _transfer_id;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."accept_ownership_transfer"("_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_content_plan_media_version"("p_user_id" "uuid", "p_version_id" "uuid", "p_new_link" "text", "p_move_schedules" boolean) RETURNS TABLE("social_media_plan_id" "uuid", "google_drive_link" "text", "moved_schedules" integer, "cancelled_schedules" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_version public.content_plan_media_versions%ROWTYPE;
  v_plan public.social_media_plans%ROWTYPE;
  v_moved integer := 0;
  v_cancelled integer := 0;
BEGIN
  SELECT * INTO v_version FROM public.content_plan_media_versions WHERE id = p_version_id;
  IF NOT FOUND OR v_version.status <> 'ready' OR v_version.drive_file_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public.can_approve_content_production(p_user_id, v_version.organization_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_new_link IS NULL OR position(v_version.drive_file_id IN p_new_link) = 0 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_plan
  FROM public.social_media_plans
  WHERE id = v_version.social_media_plan_id
    AND organization_id = v_version.organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  UPDATE public.social_media_plans
  SET google_drive_link = p_new_link,
      updated_at = now()
  WHERE id = v_plan.id;
  IF p_move_schedules THEN
    UPDATE public.social_media_scheduled_posts sp
    SET media_url_snapshot = p_new_link,
        media_resolved_url = NULL,
        updated_at = now()
    WHERE sp.social_media_plan_id = v_plan.id
      AND sp.status = 'pending';
    GET DIAGNOSTICS v_moved = ROW_COUNT;
  ELSE
    v_cancelled := public.cancel_social_media_scheduled_posts_for_plan(v_plan.id, 'google_drive_link_changed');
  END IF;
  social_media_plan_id := v_plan.id;
  google_drive_link := p_new_link;
  moved_schedules := v_moved;
  cancelled_schedules := v_cancelled;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."activate_content_plan_media_version"("p_user_id" "uuid", "p_version_id" "uuid", "p_new_link" "text", "p_move_schedules" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."active_ms_hist_bucket_idx"("p_active_ms" bigint) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    CASE
      WHEN p_active_ms IS NULL THEN NULL
      WHEN p_active_ms <= 0 THEN 1
      ELSE
        CASE
          WHEN floor(p_active_ms / 1000.0) <= 60
            THEN floor(p_active_ms / 1000.0)::int + 1
          WHEN floor(p_active_ms / 1000.0) <= 300
            THEN 61 + ((floor(p_active_ms / 1000.0)::int - 60 + 4) / 5)
          ELSE 110
        END
    END;
$$;


ALTER FUNCTION "public"."active_ms_hist_bucket_idx"("p_active_ms" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."active_ms_percentile_from_hist"("p_hist" bigint[], "p_percentile" double precision) RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  total bigint := 0;
  target bigint := 0;
  cum bigint := 0;
  i int;
  lower_ms bigint;
  width_ms bigint;
BEGIN
  IF p_hist IS NULL OR array_length(p_hist, 1) IS NULL THEN
    RETURN 0;
  END IF;

  FOR i IN 1..array_length(p_hist, 1) LOOP
    total := total + COALESCE(p_hist[i], 0);
  END LOOP;

  IF total <= 0 THEN
    RETURN 0;
  END IF;

  IF p_percentile IS NULL THEN
    target := (total + 1) / 2;
  ELSE
    IF p_percentile < 0 THEN p_percentile := 0; END IF;
    IF p_percentile > 1 THEN p_percentile := 1; END IF;
    target := greatest(1, ceil(p_percentile * total)::bigint);
  END IF;

  FOR i IN 1..array_length(p_hist, 1) LOOP
    cum := cum + COALESCE(p_hist[i], 0);
    IF cum >= target THEN
      IF i <= 61 THEN
        lower_ms := ((i - 1)::bigint) * 1000;
        width_ms := 1000;
        RETURN lower_ms + (width_ms / 2);
      ELSIF i <= 109 THEN
        lower_ms := (60::bigint + (i - 61)::bigint * 5) * 1000;
        width_ms := 5000;
        RETURN lower_ms + (width_ms / 2);
      ELSE
        -- Open-ended bucket: return its lower bound (300s) as "300s+"
        RETURN 300000;
      END IF;
    END IF;
  END LOOP;

  RETURN 300000;
END;
$$;


ALTER FUNCTION "public"."active_ms_percentile_from_hist"("p_hist" bigint[], "p_percentile" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_operational_email_recipient"("p_organization_id" "uuid", "p_email" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_email text;
  v_count integer;
  v_token uuid;
  v_row public.operational_email_recipients;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_email := lower(btrim(p_email));

  IF v_email IS NULL OR v_email = '' THEN
    RAISE EXCEPTION 'email_required';
  END IF;

  IF v_email !~* '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'email_invalid';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.operational_email_recipients r
    WHERE r.organization_id = p_organization_id
      AND lower(btrim(r.email)) = v_email
  ) THEN
    RAISE EXCEPTION 'email_duplicate';
  END IF;

  SELECT count(*)::integer INTO v_count
  FROM public.operational_email_recipients r
  WHERE r.organization_id = p_organization_id;

  IF v_count >= 20 THEN
    RAISE EXCEPTION 'recipient_limit_reached';
  END IF;

  v_token := gen_random_uuid();

  INSERT INTO public.operational_email_recipients (
    organization_id,
    email,
    status,
    verification_token,
    verification_expires_at,
    created_by
  )
  VALUES (
    p_organization_id,
    v_email,
    'pending',
    v_token,
    now() + interval '7 days',
    auth.uid()
  )
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'email', v_row.email,
    'status', v_row.status,
    'verification_token', v_row.verification_token
  );
END;
$_$;


ALTER FUNCTION "public"."add_operational_email_recipient"("p_organization_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_analytics_summary"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_web_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
declare
  v_web_id text;
  v_daily jsonb;
  v_top_paths jsonb;
  v_top_keys jsonb;
  v_top_blog jsonb;
  v_duration jsonb;
  v_heatmap jsonb;
  v_service jsonb;
  v_acquisition_channels jsonb;
  v_acquisition_top_campaigns jsonb;
  v_acquisition_top_meta_ads jsonb;
  v_totals_part jsonb;
  v_summary jsonb;
begin
  if not exists (select 1 from public.cms_admins c where c.user_id = auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  v_web_id := public.hub_require_active_web_id(p_web_id, false);

  if p_to < p_from then
    raise exception 'invalid range' using errcode = '22023';
  end if;

  -- Keep the same "human view" heuristic already applied in 20260605171900_filter_human_visitors.sql

  select coalesce(
    jsonb_agg(to_jsonb(d) order by d.day),
    '[]'::jsonb
  )
  into v_daily
  from (
    select
      x.day,
      coalesce(i.impressions, 0)::bigint as impressions,
      coalesce(c.clicks, 0)::bigint as clicks
    from (
      select distinct date_trunc('day', started_at at time zone 'Asia/Jakarta') as day
      from public.analytics_page_views
      where web_id = v_web_id and started_at >= p_from and started_at < p_to
        and (
          coalesce(active_ms, 0) > 0
          or coalesce(scroll_max_pct, 0) >= 5
          or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
        )
      union
      select distinct date_trunc('day', created_at at time zone 'Asia/Jakarta') as day
      from public.analytics_click_events
      where web_id = v_web_id and created_at >= p_from and created_at < p_to
    ) x
    left join (
      select
        date_trunc('day', started_at at time zone 'Asia/Jakarta') as day,
        count(*)::bigint as impressions
      from public.analytics_page_views
      where web_id = v_web_id and started_at >= p_from and started_at < p_to
        and (
          coalesce(active_ms, 0) > 0
          or coalesce(scroll_max_pct, 0) >= 5
          or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
        )
      group by 1
    ) i on i.day = x.day
    left join (
      select
        date_trunc('day', created_at at time zone 'Asia/Jakarta') as day,
        count(*)::bigint as clicks
      from public.analytics_click_events
      where web_id = v_web_id and created_at >= p_from and created_at < p_to
      group by 1
    ) c on c.day = x.day
  ) d;

  select coalesce(jsonb_agg(to_jsonb(t) order by t.impressions desc), '[]'::jsonb)
  into v_top_paths
  from (
    with ranked as (
      select path, count(*)::bigint as impressions
      from public.analytics_page_views
      where web_id = v_web_id and started_at >= p_from and started_at < p_to
        and (
          coalesce(active_ms, 0) > 0
          or coalesce(scroll_max_pct, 0) >= 5
          or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
        )
      group by path
      order by count(*) desc
      limit 10
    )
    select
      r.path,
      r.impressions,
      coalesce(s.unique_sessions, 0)::bigint as unique_sessions,
      coalesce(c.path_clicks, 0)::bigint as path_clicks,
      coalesce(d.duration_n, 0)::bigint as duration_n,
      d.median_active_ms,
      d.avg_active_ms
    from ranked r
    left join (
      select path, count(distinct session_id)::bigint as unique_sessions
      from public.analytics_page_views
      where web_id = v_web_id and started_at >= p_from and started_at < p_to
        and (
          coalesce(active_ms, 0) > 0
          or coalesce(scroll_max_pct, 0) >= 5
          or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
        )
      group by path
    ) s on s.path = r.path
    left join (
      select path, count(*)::bigint as path_clicks
      from public.analytics_click_events
      where web_id = v_web_id and created_at >= p_from and created_at < p_to
      group by path
    ) c on c.path = r.path
    left join (
      select
        path,
        count(*)::bigint as duration_n,
        (percentile_disc(0.5) within group (order by active_ms))::bigint as median_active_ms,
        round(avg(active_ms))::bigint as avg_active_ms
      from public.analytics_page_views
      where web_id = v_web_id and started_at >= p_from and started_at < p_to
        and (ended_at is not null or active_ms > 0)
        and (
          coalesce(active_ms, 0) > 0
          or coalesce(scroll_max_pct, 0) >= 5
          or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
        )
      group by path
    ) d on d.path = r.path
  ) t;

  select coalesce(jsonb_agg(to_jsonb(k)), '[]'::jsonb)
  into v_top_keys
  from (
    with
      impressions_total as (
        select count(*)::bigint as n
        from public.analytics_page_views
        where web_id = v_web_id and started_at >= p_from and started_at < p_to
          and (
            coalesce(active_ms, 0) > 0
            or coalesce(scroll_max_pct, 0) >= 5
            or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
          )
      ),
      key_counts as (
        select
          track_key,
          count(*)::bigint as clicks
        from public.analytics_click_events
        where web_id = v_web_id and created_at >= p_from and created_at < p_to
          and track_key is not null
        group by track_key
        order by count(*) desc
        limit 5
      )
    select
      kc.track_key,
      kc.clicks,
      case
        when it.n > 0 then round((kc.clicks::numeric / it.n::numeric), 6)
        else 0::numeric
      end as ctr
    from key_counts kc
    cross join impressions_total it
  ) k;

  select coalesce(jsonb_agg(to_jsonb(b)), '[]'::jsonb)
  into v_top_blog
  from (
    select
      pv.path,
      coalesce(p.title, pv.path) as title,
      count(*)::bigint as impressions,
      round(avg(pv.active_ms))::bigint as avg_active_ms
    from public.analytics_page_views pv
    left join public.posts p on p.slug = substring(pv.path from '^/blog/(.+)$')
    where pv.web_id = v_web_id and pv.started_at >= p_from and pv.started_at < p_to
      and pv.path ~ '^/blog/.+'
      and pv.path <> '/blog'
      and (
        coalesce(pv.active_ms, 0) > 0
        or coalesce(pv.scroll_max_pct, 0) >= 5
        or (pv.ended_at is not null and extract(epoch from (pv.ended_at - pv.started_at)) >= 5)
      )
    group by pv.path, p.title
    order by impressions desc
    limit 5
  ) b;

  select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb)
  into v_duration
  from (
    select path, round(avg(active_ms))::bigint as avg_ms
    from public.analytics_page_views
    where web_id = v_web_id and started_at >= p_from and started_at < p_to
      and (ended_at is not null or active_ms > 0)
      and (
        coalesce(active_ms, 0) > 0
        or coalesce(scroll_max_pct, 0) >= 5
        or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
      )
    group by path
    order by avg_ms desc
    limit 30
  ) u;

  select coalesce(jsonb_agg(to_jsonb(h)), '[]'::jsonb)
  into v_heatmap
  from (
    select
      case
        when path = '/' then 'home'
        when path = '/service' then 'service'
        when path = '/blog' then 'blog_index'
        when path ~ '^/blog/.+' then 'blog_post'
        else 'other'
      end as route_bucket,
      extract(hour from (started_at at time zone 'Asia/Jakarta'))::int as hour_of_day,
      round(avg(active_ms))::bigint as avg_ms
    from public.analytics_page_views
    where web_id = v_web_id and started_at >= p_from and started_at < p_to
      and (
        coalesce(active_ms, 0) > 0
        or coalesce(scroll_max_pct, 0) >= 5
        or (ended_at is not null and extract(epoch from (ended_at - started_at)) >= 5)
      )
    group by 1, 2
    order by 1, 2
  ) h;

  select jsonb_build_object(
    'impressions',
    (select count(*)::bigint from public.analytics_page_views pv2
      where pv2.web_id = v_web_id and pv2.started_at >= p_from and pv2.started_at < p_to and pv2.path = '/service'
        and (
          coalesce(pv2.active_ms, 0) > 0
          or coalesce(pv2.scroll_max_pct, 0) >= 5
          or (pv2.ended_at is not null and extract(epoch from (pv2.ended_at - pv2.started_at)) >= 5)
        )),
    'contact_clicks_on_service',
    (select count(*)::bigint from public.analytics_click_events ce2
      where ce2.web_id = v_web_id and ce2.created_at >= p_from and ce2.created_at < p_to
        and ce2.path = '/service'
        and ce2.track_key = 'contact_cta'),
    'conversion',
    case
      when (select count(*) from public.analytics_page_views pv3
            where pv3.web_id = v_web_id and pv3.started_at >= p_from and pv3.started_at < p_to and pv3.path = '/service'
              and (
                coalesce(pv3.active_ms, 0) > 0
                or coalesce(pv3.scroll_max_pct, 0) >= 5
                or (pv3.ended_at is not null and extract(epoch from (pv3.ended_at - pv3.started_at)) >= 5)
              )) > 0
      then round(
        (select count(*)::numeric from public.analytics_click_events ce3
          where ce3.web_id = v_web_id and ce3.created_at >= p_from and ce3.created_at < p_to
            and ce3.path = '/service'
            and ce3.track_key = 'contact_cta')
        / (select count(*)::numeric from public.analytics_page_views pv4
            where pv4.web_id = v_web_id and pv4.started_at >= p_from and pv4.started_at < p_to and pv4.path = '/service'
              and (
                coalesce(pv4.active_ms, 0) > 0
                or coalesce(pv4.scroll_max_pct, 0) >= 5
                or (pv4.ended_at is not null and extract(epoch from (pv4.ended_at - pv4.started_at)) >= 5)
              )),
        6
      )
      else 0::numeric
    end
  ) into v_service;

  -- Sessions with activity in range → one channel per session (heuristic; not GA4-equivalent).
  select coalesce(jsonb_agg(to_jsonb(a) order by a.sessions desc), '[]'::jsonb)
  into v_acquisition_channels
  from (
    select channel, count(*)::bigint as sessions
    from (
      select
        sc.id,
        case
          when sc.has_gclid or sc.has_gbraid or sc.has_wbraid then 'Paid search'
          when sc.has_msclkid then 'Paid search'
          when sc.has_fbclid then 'Paid social'
          when lower(coalesce(sc.utm_medium, '')) ~ '(cpc|ppc|paidsearch|paid|cpm|cad|display|banner)'
            and lower(coalesce(sc.utm_medium, '')) !~ 'social' then 'Paid (UTM)'
          when lower(coalesce(sc.utm_medium, '')) ~ '(cpc|ppc|paidsearch|paid|cpm|cad|display|banner)'
            and lower(coalesce(sc.utm_medium, '')) ~ 'social' then 'Paid social'
          when lower(coalesce(sc.utm_medium, '')) = 'email'
            or lower(coalesce(sc.utm_source, '')) ~ '(email|newsletter|e-mail)' then 'Email'
          when nullif(btrim(sc.utm_source), '') is not null
            or nullif(btrim(sc.utm_medium), '') is not null then
            case
              when lower(coalesce(sc.utm_medium, '')) ~ 'social' then 'Social (UTM)'
              else 'Campaign (UTM)'
            end
          when lower(coalesce(sc.landing_url, '')) like '%utm_%' then 'Campaign (UTM)'
          else
            case
              when nullif(btrim(sc.referrer), '') is null then 'Direct'
              when sc.ref_host is null or sc.ref_host = '' then 'Referral'
              when sc.ref_host ~ '(^|\.)google\.' and sc.ref_host !~* 'googleusercontent' then 'Organic search'
              when sc.ref_host ~ '(^|\.)(bing\.|yahoo\.|duckduckgo\.|yandex\.|baidu\.|ecosia\.)' then 'Organic search'
              when sc.ref_host ~ '(facebook|fb\.|instagram|linkedin|twitter|t\.co|tiktok|youtube|pinterest|threads\.|snap\.)' then 'Social'
              else 'Referral'
            end
        end as channel
      from (
        select
          s.id,
          s.referrer,
          s.landing_url,
          s.utm_source,
          s.utm_medium,
          s.has_gclid,
          s.has_gbraid,
          s.has_wbraid,
          s.has_msclkid,
          s.has_fbclid,
          lower((regexp_match(nullif(trim(s.referrer), ''), '^https?://([^/[:space:]]+)', 'i'))[1]) as ref_host
        from (
          select distinct pv.session_id
          from public.analytics_page_views pv
          where pv.web_id = v_web_id and pv.started_at >= p_from and pv.started_at < p_to
            and (
              coalesce(pv.active_ms, 0) > 0
              or coalesce(pv.scroll_max_pct, 0) >= 5
              or (pv.ended_at is not null and extract(epoch from (pv.ended_at - pv.started_at)) >= 5)
            )
        ) act
        inner join public.analytics_sessions s
          on s.id = act.session_id and s.web_id = v_web_id
      ) sc
    ) ch
    group by channel
  ) a;

  -- The rest of admin_analytics_summary stays identical to the human-filtered version.
  -- Reuse campaign/meta breakdowns and totals from 20260605171900.

  select coalesce(jsonb_agg(to_jsonb(c) order by c.sessions desc), '[]'::jsonb)
  into v_acquisition_top_campaigns
  from (
    select
      coalesce(nullif(btrim(s.utm_source), ''), '') as utm_source,
      coalesce(nullif(btrim(s.utm_medium), ''), '') as utm_medium,
      coalesce(nullif(btrim(s.utm_campaign), ''), '') as utm_campaign,
      coalesce(nullif(btrim(s.utm_content), ''), '') as utm_content,
      coalesce(nullif(btrim(s.utm_term), ''), '') as utm_term,
      coalesce(max(nullif(btrim(s.meta_campaign_name), '')), '') as meta_campaign_name,
      coalesce(max(nullif(btrim(s.meta_adset_name), '')), '') as meta_adset_name,
      coalesce(max(nullif(btrim(s.meta_ad_name), '')), '') as meta_ad_name,
      count(distinct s.id)::bigint as sessions
    from (
      select distinct pv.session_id
      from public.analytics_page_views pv
      where pv.web_id = v_web_id and pv.started_at >= p_from and pv.started_at < p_to
        and (
          coalesce(pv.active_ms, 0) > 0
          or coalesce(pv.scroll_max_pct, 0) >= 5
          or (pv.ended_at is not null and extract(epoch from (pv.ended_at - pv.started_at)) >= 5)
        )
    ) act
    inner join public.analytics_sessions s on s.id = act.session_id and s.web_id = v_web_id
    where nullif(btrim(s.utm_campaign), '') is not null
    group by 1, 2, 3, 4, 5
    order by sessions desc
    limit 20
  ) c;

  select coalesce(jsonb_agg(to_jsonb(m) order by m.sessions desc), '[]'::jsonb)
  into v_acquisition_top_meta_ads
  from (
    select
      coalesce(nullif(btrim(s.meta_campaign_name), ''), '') as meta_campaign_name,
      coalesce(nullif(btrim(s.meta_adset_name), ''), '') as meta_adset_name,
      coalesce(nullif(btrim(s.meta_ad_name), ''), '') as meta_ad_name,
      count(distinct s.id)::bigint as sessions
    from (
      select distinct pv.session_id
      from public.analytics_page_views pv
      where pv.web_id = v_web_id and pv.started_at >= p_from and pv.started_at < p_to
        and (
          coalesce(pv.active_ms, 0) > 0
          or coalesce(pv.scroll_max_pct, 0) >= 5
          or (pv.ended_at is not null and extract(epoch from (pv.ended_at - pv.started_at)) >= 5)
        )
    ) act
    inner join public.analytics_sessions s on s.id = act.session_id and s.web_id = v_web_id
    where
      nullif(btrim(s.meta_campaign_name), '') is not null
      or nullif(btrim(s.meta_adset_name), '') is not null
      or nullif(btrim(s.meta_ad_name), '') is not null
    group by 1, 2, 3
    order by sessions desc
    limit 20
  ) m;

  v_totals_part := jsonb_build_object(
    'impressions',
    (select count(*)::bigint
     from public.analytics_page_views pv_tot
     where pv_tot.web_id = v_web_id and pv_tot.started_at >= p_from and pv_tot.started_at < p_to
       and (
         coalesce(pv_tot.active_ms, 0) > 0
         or coalesce(pv_tot.scroll_max_pct, 0) >= 5
         or (pv_tot.ended_at is not null and extract(epoch from (pv_tot.ended_at - pv_tot.started_at)) >= 5)
       )),
    'clicks',
    (select count(*)::bigint
     from public.analytics_click_events ce_tot
     where ce_tot.web_id = v_web_id and ce_tot.created_at >= p_from and ce_tot.created_at < p_to),
    'unique_sessions',
    (select count(distinct pv_tot2.session_id)::bigint
     from public.analytics_page_views pv_tot2
     where pv_tot2.web_id = v_web_id and pv_tot2.started_at >= p_from and pv_tot2.started_at < p_to
       and (
         coalesce(pv_tot2.active_ms, 0) > 0
         or coalesce(pv_tot2.scroll_max_pct, 0) >= 5
         or (pv_tot2.ended_at is not null and extract(epoch from (pv_tot2.ended_at - pv_tot2.started_at)) >= 5)
       ))
  );

  execute $summ$
    select jsonb_build_object(
      'totals', $1::jsonb,
      'daily', $2::jsonb,
      'top_paths', $3::jsonb,
      'top_track_keys', $4::jsonb,
      'top_blog', $5::jsonb,
      'duration_by_path', $6::jsonb,
      'heatmap', $7::jsonb,
      'service', $8::jsonb,
      'acquisition_channels', $9::jsonb,
      'acquisition_top_campaigns', $10::jsonb,
      'acquisition_top_meta_ads', $11::jsonb
    )
  $summ$
  into v_summary
  using
    v_totals_part,
    v_daily,
    v_top_paths,
    v_top_keys,
    v_top_blog,
    v_duration,
    v_heatmap,
    v_service,
    v_acquisition_channels,
    v_acquisition_top_campaigns,
    v_acquisition_top_meta_ads;

  return v_summary;
end;
$_$;


ALTER FUNCTION "public"."admin_analytics_summary"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_analytics_summary"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_web_id" "text") IS 'CMS dashboard: aggregates for one web_id. Human-filtered page views; channel classification treats landing_url containing utm_ as Campaign (UTM) to avoid mislabel as Direct when UTM parsing fails.';



CREATE OR REPLACE FUNCTION "public"."admin_apply_sales_signed_contract"("p_organization_id" "uuid", "p_contract_path" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_self_service boolean;
  v_pending public.cms_sales_contract_pending%ROWTYPE;
  v_contract_path text;
  v_meta jsonb;
  v_size bigint := 0;
  v_before_sub public.organization_subscriptions%ROWTYPE;
  v_after_sub public.organization_subscriptions%ROWTYPE;
  v_before_modules jsonb := '{}'::jsonb;
  v_after_modules jsonb := '{}'::jsonb;
  v_hr jsonb;
  v_removed jsonb := '[]'::jsonb;
  v_closed jsonb := '[]'::jsonb;
  v_effective_status text;
  v_end timestamptz;
  v_pos boolean := false;
  v_quote jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  SELECT o.subscription_self_service_enabled INTO v_self_service
  FROM public.organizations o WHERE o.id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_self_service IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'sales contract pending is only for sales tenants' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_pending FROM public.cms_sales_contract_pending p
  WHERE p.organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'no pending sales contract' USING ERRCODE = 'P0002';
  END IF;

  v_contract_path := nullif(btrim(coalesce(p_contract_path, '')), '');
  IF v_contract_path IS NULL
     OR v_contract_path !~ ('^' || p_organization_id::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$')
  THEN
    RAISE EXCEPTION 'contract pdf required' USING ERRCODE = '22023';
  END IF;

  SELECT o.metadata INTO v_meta
  FROM storage.objects o
  WHERE o.bucket_id = 'sales-subscription-contracts'
    AND o.name = v_contract_path
    AND (o.owner = auth.uid() OR o.owner_id = auth.uid()::text);
  IF NOT FOUND THEN
    RAISE EXCEPTION 'contract file not found' USING ERRCODE = 'P0002';
  END IF;
  IF coalesce(v_meta->>'mimetype', '') <> 'application/pdf' THEN
    RAISE EXCEPTION 'contract must be a pdf' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_size := COALESCE((v_meta->>'size')::bigint, (v_meta->>'contentLength')::bigint, 0);
  EXCEPTION WHEN invalid_text_representation THEN
    v_size := 0;
  END;
  IF v_size <= 0 OR v_size > 10485760 THEN
    RAISE EXCEPTION 'contract file is too large' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM public.cms_subscription_adjustments a WHERE a.contract_path = v_contract_path) THEN
    RAISE EXCEPTION 'contract file already used' USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_before_sub FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription not found for organization' USING ERRCODE = 'P0002';
  END IF;

  IF v_pending.is_trial THEN
    IF v_pending.monthly_price_idr IS NOT NULL OR v_pending.billing_mode IS NOT NULL
       OR v_pending.ppn_included IS NOT NULL OR v_pending.price_effective_on IS NOT NULL
       OR v_pending.period_value_idr IS NOT NULL OR v_pending.adjustment_idr IS NOT NULL THEN
      RAISE EXCEPTION 'trial contract has no package price' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF v_pending.monthly_price_idr IS NULL OR v_pending.billing_mode IS NULL
       OR v_pending.ppn_included IS NULL OR v_pending.price_effective_on IS NULL
       OR v_pending.period_value_idr IS NULL OR v_pending.adjustment_idr IS NULL
       OR v_pending.subscription_end_date IS NULL THEN
      RAISE EXCEPTION 'package price required' USING ERRCODE = '22023';
    END IF;
    v_quote := public.sales_contract_price_quote(
      v_before_sub.sales_monthly_price_idr, v_pending.monthly_price_idr,
      (v_before_sub.subscription_end_date AT TIME ZONE 'Asia/Jakarta')::date,
      (v_pending.subscription_end_date AT TIME ZONE 'Asia/Jakarta')::date,
      v_pending.price_effective_on, v_pending.billing_mode
    );
    IF (v_quote->>'period_value_idr')::bigint IS DISTINCT FROM v_pending.period_value_idr
       OR (v_quote->>'adjustment_idr')::bigint IS DISTINCT FROM v_pending.adjustment_idr THEN
      RAISE EXCEPTION 'contract price is stale' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT COALESCE(jsonb_object_agg(m.module_key, m.is_enabled), '{}'::jsonb) INTO v_before_modules
  FROM public.organization_sales_module_access m WHERE m.organization_id = p_organization_id;

  PERFORM set_config('synckerja.apply_sales_contract', '1', true);
  PERFORM public.admin_update_organization_subscription(
    p_organization_id, v_pending.is_trial, v_pending.trial_end_date,
    v_pending.subscription_end_date, v_pending.reason, NULL
  );
  PERFORM public.admin_update_organization_sales_modules(p_organization_id, v_pending.modules, v_pending.reason);
  v_hr := public.admin_set_organization_hr_seats(
    p_organization_id, v_pending.hr_seat_count, v_pending.reason,
    v_pending.keep_employee_ids, v_pending.omnichannel_paid_seat_count
  );
  PERFORM public.admin_set_organization_ai_employee_seats(
    p_organization_id,
    CASE WHEN coalesce((v_pending.modules->>'aiEmployee')::boolean, false)
      THEN v_pending.ai_employee_seat_count ELSE 0 END,
    v_pending.reason
  );
  v_removed := COALESCE(v_hr->'removed_roster', '[]'::jsonb);

  SELECT coalesce(m.is_enabled, false) INTO v_pos
  FROM public.organization_sales_module_access m
  WHERE m.organization_id = p_organization_id AND m.module_key = 'pos';
  v_closed := public.apply_sales_outlet_quota(
    p_organization_id, v_pos, v_pending.outlet_quota, v_pending.keep_outlet_ids
  );

  IF NOT v_pending.is_trial THEN
    UPDATE public.organization_subscriptions
    SET sales_monthly_price_idr = v_pending.monthly_price_idr,
        sales_billing_mode = v_pending.billing_mode,
        sales_ppn_included = v_pending.ppn_included,
        sales_price_effective_on = v_pending.price_effective_on
    WHERE organization_id = p_organization_id;
  END IF;

  SELECT * INTO v_after_sub FROM public.organization_subscriptions os WHERE os.organization_id = p_organization_id;
  SELECT COALESCE(jsonb_object_agg(m.module_key, m.is_enabled), '{}'::jsonb) INTO v_after_modules
  FROM public.organization_sales_module_access m WHERE m.organization_id = p_organization_id;

  IF v_after_sub.is_trial THEN v_end := v_after_sub.trial_end_date;
  ELSE v_end := v_after_sub.subscription_end_date; END IF;
  IF v_end IS NOT NULL AND v_end < now() THEN v_effective_status := 'expired';
  ELSIF v_after_sub.is_trial THEN v_effective_status := 'trial';
  ELSIF v_after_sub.status = 'active' THEN v_effective_status := 'active';
  ELSE v_effective_status := coalesce(v_after_sub.status, 'unknown'); END IF;

  INSERT INTO public.cms_subscription_adjustments (
    organization_id, adjusted_by, reason, before_state, after_state, contract_path
  ) VALUES (
    p_organization_id, auth.uid(), v_pending.reason,
    jsonb_build_object(
      'is_trial', v_before_sub.is_trial, 'status', v_before_sub.status,
      'trial_end_date', v_before_sub.trial_end_date,
      'subscription_end_date', v_before_sub.subscription_end_date,
      'member_count', v_before_sub.member_count,
      'omnichannel_paid_seat_count', v_before_sub.omnichannel_paid_seat_count,
      'ai_employee_seat_count', v_before_sub.ai_employee_seat_count,
      'sales_outlet_quota', v_before_sub.sales_outlet_quota,
      'sales_monthly_price_idr', v_before_sub.sales_monthly_price_idr,
      'sales_billing_mode', v_before_sub.sales_billing_mode,
      'sales_ppn_included', v_before_sub.sales_ppn_included,
      'sales_price_effective_on', v_before_sub.sales_price_effective_on,
      'modules', v_before_modules
    ),
    jsonb_build_object(
      'is_trial', v_after_sub.is_trial, 'status', v_after_sub.status,
      'trial_end_date', v_after_sub.trial_end_date,
      'subscription_end_date', v_after_sub.subscription_end_date,
      'auto_renew', v_after_sub.auto_renew,
      'has_active_subscription', (SELECT o.has_active_subscription FROM public.organizations o WHERE o.id = p_organization_id),
      'member_count', v_after_sub.member_count,
      'omnichannel_paid_seat_count', v_after_sub.omnichannel_paid_seat_count,
      'ai_employee_seat_count', v_after_sub.ai_employee_seat_count,
      'sales_outlet_quota', v_after_sub.sales_outlet_quota,
      'sales_monthly_price_idr', v_after_sub.sales_monthly_price_idr,
      'sales_billing_mode', v_after_sub.sales_billing_mode,
      'sales_ppn_included', v_after_sub.sales_ppn_included,
      'sales_price_effective_on', v_after_sub.sales_price_effective_on,
      'period_value_idr', v_pending.period_value_idr,
      'adjustment_idr', v_pending.adjustment_idr,
      'modules', v_after_modules,
      'removed_roster', v_removed,
      'closed_outlets', v_closed
    ),
    v_contract_path
  );

  DELETE FROM public.cms_sales_contract_pending WHERE organization_id = p_organization_id;
  RETURN jsonb_build_object('organization_id', p_organization_id, 'contract_path', v_contract_path, 'effective_status', v_effective_status);
END;
$_$;


ALTER FUNCTION "public"."admin_apply_sales_signed_contract"("p_organization_id" "uuid", "p_contract_path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_apply_sales_signed_contract"("p_organization_id" "uuid", "p_contract_path" "text") IS 'Applies the waiting Sales package after a signed PDF is stored, then deletes that package.';



CREATE OR REPLACE FUNCTION "public"."admin_blog_post_page_view_totals"("p_web_id" "text") RETURNS TABLE("path" "text", "total_views" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  w text;
begin
  w := public.hub_require_active_web_id(p_web_id, false);

  return query
  select pv.path, count(*)::bigint as total_views
  from public.analytics_page_views pv
  where pv.web_id = w
    and pv.path ~ '^/blog/[^/]+$'
  group by pv.path;
end;
$_$;


ALTER FUNCTION "public"."admin_blog_post_page_view_totals"("p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_blog_post_page_view_totals"("p_web_id" "text") IS 'Agregat count analytics_page_views per path /blog/:slug (all-time), difilter web_id + heuristic human engagement.';



CREATE OR REPLACE FUNCTION "public"."admin_create_subscription_plan"("p_name" "text", "p_base_price_per_member" numeric, "p_modules" "jsonb", "p_is_active" boolean, "p_reason" "text", "p_description" "text" DEFAULT NULL::"text", "p_billing_term_discounts" "jsonb" DEFAULT NULL::"jsonb", "p_jumlah_hari_trial" integer DEFAULT NULL::integer, "p_max_members" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_plan public.subscription_plans%ROWTYPE;
  v_modules_after jsonb;
  v_features jsonb;
  v_slug text;
  v_max_members integer;
  v_discounts jsonb;
  v_annual numeric;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF p_modules IS NULL OR jsonb_typeof(p_modules) <> 'object' THEN
    RAISE EXCEPTION 'modules must be a json object' USING ERRCODE = '22023';
  END IF;

  v_slug := lower(trim(p_name));

  IF v_slug IS NULL OR char_length(v_slug) < 2 THEN
    RAISE EXCEPTION 'plan name required (min 2 characters)' USING ERRCODE = '22023';
  END IF;

  IF v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN
    RAISE EXCEPTION 'plan name must be lowercase slug (a-z, 0-9, hyphen)' USING ERRCODE = '22023';
  END IF;

  PERFORM public.admin_validate_price_amount(p_base_price_per_member);

  IF p_jumlah_hari_trial IS NOT NULL AND p_jumlah_hari_trial < 0 THEN
    RAISE EXCEPTION 'jumlah_hari_trial must be >= 0' USING ERRCODE = '22023';
  END IF;

  v_discounts := public._validate_billing_term_discounts(coalesce(p_billing_term_discounts, public._default_billing_term_discounts()));
  v_annual := public._billing_term_discount(v_discounts, 12);

  v_max_members := public._resolve_plan_max_members(
    public._validate_plan_max_members(p_max_members),
    p_jumlah_hari_trial,
    p_base_price_per_member
  );

  v_features := public._build_plan_features_from_modules(
    p_base_price_per_member,
    p_modules,
    v_max_members
  );

  INSERT INTO public.subscription_plans (
    name,
    description,
    base_price_per_member,
    features,
    is_active,
    billing_term_discounts,
    annual_discount_percentage,
    jumlah_hari_trial,
    max_members
  )
  VALUES (
    v_slug,
    nullif(trim(p_description), ''),
    p_base_price_per_member,
    v_features,
    coalesce(p_is_active, true),
    v_discounts,
    v_annual,
    p_jumlah_hari_trial,
    v_max_members
  )
  RETURNING * INTO v_plan;

  v_modules_after := public._apply_plan_modules(v_plan.id, p_modules);

  INSERT INTO public.cms_plan_price_adjustments (
    entity_type, entity_id, plan_id, adjusted_by, reason, before_state, after_state
  ) VALUES (
    'plan',
    v_plan.id,
    v_plan.id,
    auth.uid(),
    trim(p_reason),
    jsonb_build_object('created', true),
    jsonb_build_object(
      'base_price_per_member', v_plan.base_price_per_member,
      'billing_term_discounts', v_plan.billing_term_discounts,
      'modules', v_modules_after
    )
  );

  RETURN jsonb_build_object(
    'id', v_plan.id,
    'name', v_plan.name,
    'base_price_per_member', v_plan.base_price_per_member,
    'billing_term_discounts', v_plan.billing_term_discounts,
    'annual_discount_percentage', v_plan.annual_discount_percentage,
    'jumlah_hari_trial', v_plan.jumlah_hari_trial,
    'max_members', v_plan.max_members,
    'is_active', v_plan.is_active,
    'features', v_plan.features
  );
END;
$_$;


ALTER FUNCTION "public"."admin_create_subscription_plan"("p_name" "text", "p_base_price_per_member" numeric, "p_modules" "jsonb", "p_is_active" boolean, "p_reason" "text", "p_description" "text", "p_billing_term_discounts" "jsonb", "p_jumlah_hari_trial" integer, "p_max_members" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_delete_organization"("p_organization_id" "uuid", "p_confirm_name" "text", "p_confirm_phrase" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_sub public.organization_subscriptions%ROWTYPE;
  v_auth_users uuid[];
  v_deleted jsonb;
  v_snapshot jsonb;
  v_audit_id uuid;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF public._normalize_org_confirm_name(p_confirm_phrase) <> 'hapus organisasi ini' THEN
    RAISE EXCEPTION 'invalid confirmation phrase' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_org FROM public.organizations WHERE id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF public._normalize_org_confirm_name(p_confirm_name)
    <> public._normalize_org_confirm_name(v_org.company_name) THEN
    RAISE EXCEPTION 'organization name does not match' USING ERRCODE = '22023';
  END IF;

  IF public._organization_has_cms_admin_member(p_organization_id) THEN
    RAISE EXCEPTION 'organization has cms admin members' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_sub FROM public.organization_subscriptions WHERE organization_id = p_organization_id;

  v_auth_users := public._collect_organization_auth_users_to_delete(p_organization_id);

  v_snapshot := jsonb_build_object(
    'organization', to_jsonb(v_org),
    'subscription', CASE WHEN v_sub.id IS NULL THEN NULL ELSE to_jsonb(v_sub) END
  );

  INSERT INTO public.cms_organization_deletions (
    organization_id,
    company_name,
    deleted_by,
    reason,
    confirm_name,
    snapshot,
    counts,
    auth_users_to_delete
  )
  VALUES (
    v_org.id,
    v_org.company_name,
    auth.uid(),
    trim(p_reason),
    trim(p_confirm_name),
    v_snapshot,
    '{}'::jsonb,
    v_auth_users
  )
  RETURNING id INTO v_audit_id;

  v_deleted := public._purge_organization_rows(p_organization_id);

  UPDATE public.cms_organization_deletions
  SET counts = v_deleted
  WHERE id = v_audit_id;

  RETURN jsonb_build_object(
    'audit_id', v_audit_id,
    'organization_id', p_organization_id,
    'company_name', v_org.company_name,
    'deleted_counts', v_deleted,
    'auth_users_to_delete', v_auth_users,
    'storage_prefix', p_organization_id::text
  );
END;
$$;


ALTER FUNCTION "public"."admin_delete_organization"("p_organization_id" "uuid", "p_confirm_name" "text", "p_confirm_phrase" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_delete_organization"("p_organization_id" "uuid", "p_confirm_name" "text", "p_confirm_phrase" "text", "p_reason" "text") IS 'CMS admin: hard delete one organization, purge tenant rows, audit to cms_organization_deletions.';



CREATE OR REPLACE FUNCTION "public"."admin_get_organization_sales_modules"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_is_sales boolean;
  v_modules jsonb := '{}'::jsonb;
  v_key text;
  v_enabled boolean;
  v_paid integer := 0;
  v_hr integer := 0;
  v_ai integer := 0;
  v_outlet_quota integer;
  v_monthly bigint;
  v_billing text;
  v_ppn boolean;
  v_effective date;
  v_roster jsonb := '[]'::jsonb;
  v_outlets jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  SELECT coalesce(o.subscription_self_service_enabled, true) INTO v_is_sales
  FROM public.organizations o WHERE o.id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  v_is_sales := NOT v_is_sales;
  IF NOT v_is_sales THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'is_sales_tenant', false,
      'modules', '{}'::jsonb,
      'omnichannel_paid_seat_count', 0,
      'hr_seat_count', 0,
      'ai_employee_seat_count', 0,
      'active_employee_count', 0,
      'active_ai_employee_count', 0,
      'roster_eligible_employee_count', 0,
      'omnichannel_roster', '[]'::jsonb,
      'sales_outlet_quota', NULL,
      'outlets', '[]'::jsonb,
      'sales_monthly_price_idr', NULL,
      'sales_billing_mode', NULL,
      'sales_ppn_included', NULL,
      'sales_price_effective_on', NULL
    );
  END IF;
  FOREACH v_key IN ARRAY public.sales_module_catalog_keys() LOOP
    SELECT m.is_enabled INTO v_enabled
    FROM public.organization_sales_module_access m
    WHERE m.organization_id = p_organization_id AND m.module_key = v_key;
    v_modules := v_modules || jsonb_build_object(v_key, coalesce(v_enabled, false));
  END LOOP;
  SELECT
    COALESCE(os.omnichannel_paid_seat_count, 0),
    COALESCE(os.member_count, 0),
    COALESCE(os.ai_employee_seat_count, 0),
    os.sales_outlet_quota,
    os.sales_monthly_price_idr,
    os.sales_billing_mode,
    os.sales_ppn_included,
    os.sales_price_effective_on
  INTO v_paid, v_hr, v_ai, v_outlet_quota, v_monthly, v_billing, v_ppn, v_effective
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id
  LIMIT 1;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('employee_id', s.employee_id, 'full_name', COALESCE(e.full_name, ''), 'email', e.email, 'role', s.role) ORDER BY e.full_name), '[]'::jsonb)
  INTO v_roster
  FROM public.organization_omnichannel_staff s
  JOIN public.employees e ON e.id = s.employee_id
  WHERE s.organization_id = p_organization_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name, 'is_active', o.is_active, 'is_default', o.is_default) ORDER BY o.is_default DESC, o.sort_order, o.name), '[]'::jsonb)
  INTO v_outlets
  FROM public.pos_outlets o
  WHERE o.organization_id = p_organization_id AND coalesce(o.is_deleted, false) = false;
  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'is_sales_tenant', true,
    'modules', v_modules,
    'omnichannel_paid_seat_count', COALESCE(v_paid, 0),
    'hr_seat_count', COALESCE(v_hr, 0),
    'ai_employee_seat_count', COALESCE(v_ai, 0),
    'active_employee_count', public.count_active_employees_for_org(p_organization_id),
    'active_ai_employee_count', public.count_active_ai_employees_for_org(p_organization_id),
    'roster_eligible_employee_count', public.count_roster_eligible_employees(p_organization_id),
    'omnichannel_roster', v_roster,
    'sales_outlet_quota', v_outlet_quota,
    'outlets', v_outlets,
    'sales_monthly_price_idr', v_monthly,
    'sales_billing_mode', v_billing,
    'sales_ppn_included', v_ppn,
    'sales_price_effective_on', v_effective
  );
END;
$$;


ALTER FUNCTION "public"."admin_get_organization_sales_modules"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_plan_modules"("p_subscription_plan_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_modules jsonb := '{}'::jsonb;
  v_key text;
  v_enabled boolean;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.subscription_plans WHERE id = p_subscription_plan_id
  ) THEN
    RAISE EXCEPTION 'plan not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.seed_plan_module_access_defaults(p_subscription_plan_id);

  FOREACH v_key IN ARRAY public.sales_module_catalog_keys()
  LOOP
    SELECT m.is_enabled
    INTO v_enabled
    FROM public.subscription_plan_module_access m
    WHERE m.subscription_plan_id = p_subscription_plan_id
      AND m.module_key = v_key;

    v_modules := v_modules || jsonb_build_object(v_key, coalesce(v_enabled, false));
  END LOOP;

  RETURN jsonb_build_object(
    'subscription_plan_id', p_subscription_plan_id,
    'modules', v_modules
  );
END;
$$;


