CREATE OR REPLACE FUNCTION "public"."admin_list_lead_submissions"("p_web_id" "text" DEFAULT NULL::"text", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_form_id" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "web_id" "text", "property_display_name" "text", "form_id" "text", "form_version" integer, "step" integer, "status" "text", "name" "text", "phone_number" "text", "email" "text", "package_label" "text", "lead_id" "uuid", "analytics_session_id" "uuid", "gclid" "text", "attribution_label" "text", "submitted_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "form_data" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  w text;
  lim int;
  off int;
begin
  if not exists (select 1 from public.cms_admins c where c.user_id = auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  w := public.hub_require_active_web_id(p_web_id, true);
  lim := greatest(1, least(coalesce(p_limit, 50), 200));
  off := greatest(coalesce(p_offset, 0), 0);

  return query
  select
    ls.id,
    ls.web_id,
    p.display_name as property_display_name,
    ls.form_id,
    ls.form_version,
    ls.step,
    ls.status,
    ls.name,
    ls.phone_number,
    ls.email,
    ls.package_label,
    ls.lead_id,
    ls.analytics_session_id,
    ls.gclid,
    ls.attribution_label,
    ls.submitted_at,
    ls.created_at,
    ls.updated_at,
    ls.form_data
  from public.lead_submissions ls
  inner join public.properties p on p.slug = ls.web_id
  where (w is null or ls.web_id = w)
    and (p_form_id is null or btrim(p_form_id) = '' or ls.form_id = btrim(p_form_id))
    and (p_from is null or ls.created_at >= p_from)
    and (p_to is null or ls.created_at < p_to)
  order by ls.created_at desc
  limit lim
  offset off;
end;
$$;


