CREATE OR REPLACE FUNCTION "public"."admin_list_organizations"("p_status_filter" "text" DEFAULT NULL::"text", "p_search" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS TABLE("organization_id" "uuid", "company_name" "text", "email" "text", "created_at" timestamp with time zone, "subscription_status" "text", "effective_status" "text", "is_active" boolean, "is_trial" boolean, "plan_name" "text", "subscription_end_date" timestamp with time zone, "trial_end_date" timestamp with time zone, "has_active_subscription" boolean, "member_count" integer, "subscription_self_service_enabled" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  lim int;
  off int;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  lim := greatest(1, least(coalesce(p_limit, 100), 200));
  off := greatest(coalesce(p_offset, 0), 0);

  RETURN QUERY
  WITH enriched AS (
    SELECT
      o.id AS organization_id,
      o.company_name,
      o.email,
      o.created_at,
      o.has_active_subscription,
      o.subscription_self_service_enabled,
      os.status AS subscription_status,
      coalesce(os.is_trial, false) AS is_trial,
      os.subscription_end_date,
      os.trial_end_date,
      os.member_count,
      sp.name AS plan_name,
      CASE
        WHEN coalesce(os.is_trial, false) THEN os.trial_end_date
        ELSE os.subscription_end_date
      END AS v_end,
      (os.id IS NOT NULL) AS has_sub
    FROM public.organizations o
    LEFT JOIN public.organization_subscriptions os ON os.organization_id = o.id
    LEFT JOIN public.subscription_plans sp ON sp.id = os.subscription_plan_id
  ),
  computed AS (
    SELECT
      e.*,
      (e.v_end IS NOT NULL AND e.v_end < now()) AS is_expired,
      CASE
        WHEN NOT e.has_sub THEN 'none'
        WHEN e.v_end IS NOT NULL AND e.v_end < now() THEN 'expired'
        WHEN e.is_trial THEN 'trial'
        WHEN e.subscription_status = 'active' THEN 'active'
        ELSE coalesce(e.subscription_status, 'unknown')
      END AS effective_status
    FROM enriched e
  ),
  final AS (
    SELECT
      c.organization_id,
      c.company_name,
      c.email,
      c.created_at,
      c.subscription_status,
      c.effective_status,
      (
        NOT c.is_expired AND (
          (c.is_trial AND (c.trial_end_date IS NULL OR c.trial_end_date > now()))
          OR (
            NOT c.is_trial
            AND c.subscription_status = 'active'
            AND (c.subscription_end_date IS NULL OR c.subscription_end_date > now())
          )
        )
      ) AS is_active,
      c.is_trial,
      c.plan_name,
      c.subscription_end_date,
      c.trial_end_date,
      c.has_active_subscription,
      c.member_count,
      c.subscription_self_service_enabled
    FROM computed c
    WHERE (
      p_search IS NULL OR btrim(p_search) = ''
      OR c.company_name ILIKE '%' || btrim(p_search) || '%'
    )
    AND (
      p_status_filter IS NULL OR btrim(p_status_filter) = ''
      OR (
        lower(btrim(p_status_filter)) = 'active'
        AND (
          NOT c.is_expired AND (
            (c.is_trial AND (c.trial_end_date IS NULL OR c.trial_end_date > now()))
            OR (
              NOT c.is_trial
              AND c.subscription_status = 'active'
              AND (c.subscription_end_date IS NULL OR c.subscription_end_date > now())
            )
          )
        )
      )
      OR (
        lower(btrim(p_status_filter)) = 'expired'
        AND c.effective_status = 'expired'
      )
    )
  )
  SELECT
    f.organization_id,
    f.company_name,
    f.email,
    f.created_at,
    f.subscription_status,
    f.effective_status,
    f.is_active,
    f.is_trial,
    f.plan_name,
    f.subscription_end_date,
    f.trial_end_date,
    f.has_active_subscription,
    f.member_count,
    f.subscription_self_service_enabled
  FROM final f
  ORDER BY f.created_at DESC
  LIMIT lim
  OFFSET off;
END;
$$;


ALTER FUNCTION "public"."admin_list_organizations"("p_status_filter" "text", "p_search" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_list_plan_add_on_overrides"("p_plan_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("subscription_plan_id" "uuid", "plan_name" "text", "add_on_id" "uuid", "add_on_code" "text", "add_on_name" "text", "unit_price_override_per_month" numeric, "default_unit_price_per_month" numeric, "resolved_unit_price_per_month" numeric, "display_order" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    pao.subscription_plan_id,
    sp.name AS plan_name,
    pao.add_on_id,
    ao.code AS add_on_code,
    ao.name AS add_on_name,
    pao.unit_price_override_per_month,
    ao.default_unit_price_per_month,
    coalesce(pao.unit_price_override_per_month, ao.default_unit_price_per_month) AS resolved_unit_price_per_month,
    pao.display_order
  FROM public.subscription_plan_add_ons pao
  JOIN public.subscription_plans sp ON sp.id = pao.subscription_plan_id
  JOIN public.subscription_add_ons ao ON ao.id = pao.add_on_id
  WHERE p_plan_id IS NULL OR pao.subscription_plan_id = p_plan_id
  ORDER BY sp.name, pao.display_order, ao.name;
END;
$$;


