CREATE OR REPLACE FUNCTION "public"."admin_list_subscription_plans"() RETURNS TABLE("id" "uuid", "name" "text", "description" "text", "base_price_per_member" numeric, "billing_term_discounts" "jsonb", "annual_discount_percentage" numeric, "jumlah_hari_trial" integer, "max_members" integer, "is_active" boolean, "subscriber_count" bigint, "enabled_module_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    sp.id,
    sp.name,
    sp.description,
    sp.base_price_per_member,
    sp.billing_term_discounts,
    sp.annual_discount_percentage,
    sp.jumlah_hari_trial,
    sp.max_members,
    sp.is_active,
    count(DISTINCT os.id) AS subscriber_count,
    coalesce((
      SELECT count(*)::bigint
      FROM public.subscription_plan_module_access pm
      WHERE pm.subscription_plan_id = sp.id AND pm.is_enabled = true
    ), 0) AS enabled_module_count,
    sp.created_at,
    sp.updated_at
  FROM public.subscription_plans sp
  LEFT JOIN public.organization_subscriptions os ON os.subscription_plan_id = sp.id
  GROUP BY sp.id
  ORDER BY sp.name;
END;
$$;


ALTER FUNCTION "public"."admin_list_subscription_plans"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_organizations_summary"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  WITH enriched AS (
    SELECT
      o.id AS organization_id,
      os.status AS subscription_status,
      coalesce(os.is_trial, false) AS is_trial,
      os.subscription_end_date,
      os.trial_end_date,
      CASE
        WHEN coalesce(os.is_trial, false) THEN os.trial_end_date
        ELSE os.subscription_end_date
      END AS v_end,
      (os.id IS NOT NULL) AS has_sub
    FROM public.organizations o
    LEFT JOIN public.organization_subscriptions os ON os.organization_id = o.id
  ),
  computed AS (
    SELECT
      e.organization_id,
      (e.v_end IS NOT NULL AND e.v_end < now()) AS is_expired,
      CASE
        WHEN NOT e.has_sub THEN 'none'
        WHEN e.v_end IS NOT NULL AND e.v_end < now() THEN 'expired'
        WHEN e.is_trial THEN 'trial'
        WHEN e.subscription_status = 'active' THEN 'active'
        ELSE coalesce(e.subscription_status, 'unknown')
      END AS effective_status,
      (
        NOT (e.v_end IS NOT NULL AND e.v_end < now()) AND (
          (e.is_trial AND (e.trial_end_date IS NULL OR e.trial_end_date > now()))
          OR (
            NOT e.is_trial
            AND e.subscription_status = 'active'
            AND (e.subscription_end_date IS NULL OR e.subscription_end_date > now())
          )
        )
      ) AS is_active
    FROM enriched e
  )
  SELECT jsonb_build_object(
    'total_count', count(*)::int,
    'active_count', count(*) FILTER (WHERE is_active)::int,
    'trial_count', count(*) FILTER (WHERE effective_status = 'trial')::int,
    'expired_count', count(*) FILTER (WHERE effective_status = 'expired')::int
  )
  INTO result
  FROM computed;

  RETURN coalesce(result, '{"total_count":0,"active_count":0,"trial_count":0,"expired_count":0}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."admin_organizations_summary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_preview_organization_deletion"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_sub public.organization_subscriptions%ROWTYPE;
  v_table_counts jsonb;
  v_member_count bigint := 0;
  v_user_count bigint := 0;
  v_auth_delete_count int;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_org FROM public.organizations WHERE id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_sub FROM public.organization_subscriptions WHERE organization_id = p_organization_id;

  IF to_regclass('public.user_organizations') IS NOT NULL THEN
    SELECT count(*)::bigint INTO v_user_count
    FROM public.user_organizations
    WHERE organization_id = p_organization_id;
  END IF;

  IF to_regclass('public.employees') IS NOT NULL THEN
    SELECT count(*)::bigint INTO v_member_count
    FROM public.employees
    WHERE organization_id = p_organization_id;
  END IF;

  v_table_counts := public._preview_organization_key_counts(p_organization_id);
  v_auth_delete_count := coalesce(
    cardinality(public._collect_organization_auth_users_to_delete(p_organization_id)),
    0
  );

  RETURN jsonb_build_object(
    'organization_id', v_org.id,
    'company_name', v_org.company_name,
    'email', v_org.email,
    'created_at', v_org.created_at,
    'subscription_status', v_sub.status,
    'is_trial', coalesce(v_sub.is_trial, false),
    'has_active_subscription', coalesce(v_org.has_active_subscription, false),
    'member_count', v_member_count,
    'user_count', v_user_count,
    'auth_users_to_delete', v_auth_delete_count,
    'table_counts', v_table_counts,
    'table_counts_scope', 'key_tables_only',
    'has_cms_admin_member', public._organization_has_cms_admin_member(p_organization_id),
    'confirm_phrase', 'hapus organisasi ini'
  );
END;
$$;


ALTER FUNCTION "public"."admin_preview_organization_deletion"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_preview_organization_deletion"("p_organization_id" "uuid") IS 'CMS admin: lightweight preview (key tables only) before deleting an organization.';



CREATE OR REPLACE FUNCTION "public"."admin_preview_sales_contract_price"("p_organization_id" "uuid", "p_monthly_price_idr" bigint, "p_billing_mode" "text", "p_ppn_included" boolean, "p_price_effective_on" "date", "p_subscription_end_date" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_self_service boolean;
  v_old_monthly bigint;
  v_old_end date;
  v_price jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  SELECT o.subscription_self_service_enabled
  INTO v_self_service
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF v_self_service IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'sales contract pending is only for sales tenants' USING ERRCODE = '42501';
  END IF;

  SELECT
    os.sales_monthly_price_idr,
    (os.subscription_end_date AT TIME ZONE 'Asia/Jakarta')::date
  INTO v_old_monthly, v_old_end
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription not found for organization' USING ERRCODE = 'P0002';
  END IF;

  v_price := public.sales_contract_prepare_price(
    false,
    p_monthly_price_idr,
    p_billing_mode,
    p_ppn_included,
    p_price_effective_on,
    p_subscription_end_date,
    v_old_monthly,
    v_old_end
  );

  RETURN v_price || jsonb_build_object('old_monthly_price_idr', v_old_monthly);
END;
$$;


ALTER FUNCTION "public"."admin_preview_sales_contract_price"("p_organization_id" "uuid", "p_monthly_price_idr" bigint, "p_billing_mode" "text", "p_ppn_included" boolean, "p_price_effective_on" "date", "p_subscription_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_save_sales_contract_pending"("p_organization_id" "uuid", "p_is_trial" boolean, "p_trial_end_date" timestamp with time zone, "p_subscription_end_date" timestamp with time zone, "p_modules" "jsonb", "p_hr_seat_count" integer, "p_omnichannel_paid_seat_count" integer, "p_ai_employee_seat_count" integer, "p_keep_employee_ids" "uuid"[], "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[], "p_monthly_price_idr" bigint, "p_billing_mode" "text", "p_ppn_included" boolean, "p_price_effective_on" "date", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_self_service boolean;
  v_catalog text[];
  v_key text;
  v_val boolean;
  v_modules jsonb := '{}'::jsonb;
  v_active_end timestamptz;
  v_max_future timestamptz := now() + interval '366 days';
  v_active integer;
  v_ai_active integer;
  v_ai_seats integer;
  v_eligible integer;
  v_omni_max integer;
  v_cap integer;
  v_roster_ids uuid[];
  v_roster_count integer;
  v_keep_count integer;
  v_keep uuid[] := ARRAY[]::uuid[];
  v_outlets jsonb;
  v_outlet_quota integer;
  v_keep_outlets uuid[] := ARRAY[]::uuid[];
  v_old_monthly bigint;
  v_old_end date;
  v_price jsonb;
  v_row public.cms_sales_contract_pending%ROWTYPE;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  SELECT o.subscription_self_service_enabled INTO v_self_service
  FROM public.organizations o WHERE o.id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  IF v_self_service IS DISTINCT FROM false THEN
    RAISE EXCEPTION 'sales contract pending is only for sales tenants' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.organization_subscriptions os WHERE os.organization_id = p_organization_id) THEN
    RAISE EXCEPTION 'subscription not found for organization' USING ERRCODE = 'P0002';
  END IF;

  IF coalesce(p_is_trial, false) THEN
    IF p_trial_end_date IS NULL THEN
      RAISE EXCEPTION 'trial_end_date required when in trial mode' USING ERRCODE = '22023';
    END IF;
    v_active_end := p_trial_end_date;
  ELSE
    IF p_subscription_end_date IS NULL THEN
      RAISE EXCEPTION 'subscription_end_date required when in paid mode' USING ERRCODE = '22023';
    END IF;
    v_active_end := p_subscription_end_date;
  END IF;
  IF v_active_end > now() AND v_active_end > v_max_future THEN
    RAISE EXCEPTION 'end date cannot exceed 366 days from now' USING ERRCODE = '22023';
  END IF;
  IF p_modules IS NULL OR jsonb_typeof(p_modules) <> 'object' THEN
    RAISE EXCEPTION 'modules must be a json object' USING ERRCODE = '22023';
  END IF;

  v_catalog := public.sales_module_catalog_keys();
  IF EXISTS (
    SELECT 1 FROM jsonb_each(p_modules) AS e(key, value)
    WHERE e.key = ANY (ARRAY['dashboard', 'subscription'])
       OR NOT (e.key = ANY (v_catalog))
       OR jsonb_typeof(e.value) <> 'boolean'
  ) THEN
    RAISE EXCEPTION 'invalid module keys in payload' USING ERRCODE = '22023';
  END IF;

  FOREACH v_key IN ARRAY v_catalog LOOP
    IF p_modules ? v_key THEN
      v_val := (p_modules ->> v_key)::boolean;
    ELSE
      SELECT m.is_enabled INTO v_val
      FROM public.organization_sales_module_access m
      WHERE m.organization_id = p_organization_id AND m.module_key = v_key;
      v_val := coalesce(v_val, false);
    END IF;
    v_modules := v_modules || jsonb_build_object(v_key, v_val);
  END LOOP;

  IF coalesce((v_modules->>'digitalMarketing')::boolean, false) IS NOT TRUE THEN
    v_modules := jsonb_set(v_modules, '{leadMagnet}', 'false'::jsonb, true);
  END IF;
  IF coalesce((v_modules->>'omnichannel')::boolean, false) IS NOT TRUE THEN
    v_modules := jsonb_set(v_modules, '{whatsappBusiness}', 'false'::jsonb, true);
  END IF;

  IF p_hr_seat_count IS NULL OR p_hr_seat_count < 0
     OR p_omnichannel_paid_seat_count IS NULL OR p_omnichannel_paid_seat_count < 0
     OR p_ai_employee_seat_count IS NULL OR p_ai_employee_seat_count < 0 THEN
    RAISE EXCEPTION 'seats must be >= 0' USING ERRCODE = '22023';
  END IF;

  v_active := public.count_active_employees_for_org(p_organization_id);
  IF p_hr_seat_count < v_active THEN
    RAISE EXCEPTION 'seat HR minimal %', v_active USING ERRCODE = '22023';
  END IF;

  v_ai_active := public.count_active_ai_employees_for_org(p_organization_id);
  IF coalesce((v_modules->>'aiEmployee')::boolean, false) THEN
    IF p_ai_employee_seat_count < v_ai_active THEN
      RAISE EXCEPTION 'kuota karyawan AI minimal %', v_ai_active USING ERRCODE = '22023';
    END IF;
    v_ai_seats := p_ai_employee_seat_count;
  ELSE
    IF v_ai_active > 0 THEN
      RAISE EXCEPTION 'kuota karyawan AI minimal %', v_ai_active USING ERRCODE = '22023';
    END IF;
    v_ai_seats := 0;
  END IF;

  v_eligible := public.count_roster_eligible_employees(p_organization_id);
  v_omni_max := LEAST(p_hr_seat_count, v_eligible);
  IF p_omnichannel_paid_seat_count > v_omni_max THEN
    RAISE EXCEPTION 'kuota maksimal %', v_omni_max USING ERRCODE = '22023';
  END IF;
  v_cap := LEAST(p_hr_seat_count, p_omnichannel_paid_seat_count);

  SELECT COALESCE(array_agg(s.employee_id), ARRAY[]::uuid[]) INTO v_roster_ids
  FROM public.organization_omnichannel_staff s WHERE s.organization_id = p_organization_id;
  v_roster_count := COALESCE(cardinality(v_roster_ids), 0);
  IF v_roster_count > v_cap THEN
    SELECT COUNT(DISTINCT k.employee_id) INTO v_keep_count
    FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id);
    IF v_keep_count IS DISTINCT FROM v_cap
      OR EXISTS (
        SELECT 1 FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id)
        WHERE NOT (k.employee_id = ANY(v_roster_ids))
      ) THEN
      RAISE EXCEPTION 'pilih tepat % user yang tetap aktif', v_cap USING ERRCODE = '22023';
    END IF;
    SELECT COALESCE(array_agg(DISTINCT k.employee_id), ARRAY[]::uuid[]) INTO v_keep
    FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id);
  END IF;

  v_outlets := public.resolve_sales_outlet_package(
    p_organization_id,
    coalesce((v_modules->>'pos')::boolean, false),
    p_outlet_quota,
    p_keep_outlet_ids
  );
  v_outlet_quota := (v_outlets->>'outlet_quota')::integer;
  SELECT coalesce(array_agg(value::uuid), ARRAY[]::uuid[]) INTO v_keep_outlets
  FROM jsonb_array_elements_text(v_outlets->'keep_outlet_ids') AS value;

  SELECT os.sales_monthly_price_idr, (os.subscription_end_date AT TIME ZONE 'Asia/Jakarta')::date
  INTO v_old_monthly, v_old_end
  FROM public.organization_subscriptions os WHERE os.organization_id = p_organization_id;

  v_price := public.sales_contract_prepare_price(
    coalesce(p_is_trial, false), p_monthly_price_idr, p_billing_mode, p_ppn_included,
    p_price_effective_on, p_subscription_end_date, v_old_monthly, v_old_end
  );

  INSERT INTO public.cms_sales_contract_pending (
    organization_id, saved_by, reason, is_trial, trial_end_date, subscription_end_date, modules,
    hr_seat_count, omnichannel_paid_seat_count, ai_employee_seat_count, keep_employee_ids,
    outlet_quota, keep_outlet_ids, monthly_price_idr, billing_mode, ppn_included,
    price_effective_on, period_value_idr, adjustment_idr, saved_at
  ) VALUES (
    p_organization_id, auth.uid(), trim(p_reason), coalesce(p_is_trial, false),
    p_trial_end_date, p_subscription_end_date, v_modules,
    p_hr_seat_count, p_omnichannel_paid_seat_count, v_ai_seats, COALESCE(v_keep, ARRAY[]::uuid[]),
    v_outlet_quota, COALESCE(v_keep_outlets, ARRAY[]::uuid[]),
    (v_price->>'monthly_price_idr')::bigint, v_price->>'billing_mode', (v_price->>'ppn_included')::boolean,
    (v_price->>'price_effective_on')::date, (v_price->>'period_value_idr')::bigint,
    (v_price->>'adjustment_idr')::bigint, now()
  )
  ON CONFLICT (organization_id) DO UPDATE SET
    saved_by = EXCLUDED.saved_by, reason = EXCLUDED.reason, is_trial = EXCLUDED.is_trial,
    trial_end_date = EXCLUDED.trial_end_date, subscription_end_date = EXCLUDED.subscription_end_date,
    modules = EXCLUDED.modules, hr_seat_count = EXCLUDED.hr_seat_count,
    omnichannel_paid_seat_count = EXCLUDED.omnichannel_paid_seat_count,
    ai_employee_seat_count = EXCLUDED.ai_employee_seat_count,
    keep_employee_ids = EXCLUDED.keep_employee_ids, outlet_quota = EXCLUDED.outlet_quota,
    keep_outlet_ids = EXCLUDED.keep_outlet_ids, monthly_price_idr = EXCLUDED.monthly_price_idr,
    billing_mode = EXCLUDED.billing_mode, ppn_included = EXCLUDED.ppn_included,
    price_effective_on = EXCLUDED.price_effective_on, period_value_idr = EXCLUDED.period_value_idr,
    adjustment_idr = EXCLUDED.adjustment_idr, saved_at = EXCLUDED.saved_at
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'organization_id', v_row.organization_id, 'reason', v_row.reason, 'is_trial', v_row.is_trial,
    'trial_end_date', v_row.trial_end_date, 'subscription_end_date', v_row.subscription_end_date,
    'modules', v_row.modules, 'hr_seat_count', v_row.hr_seat_count,
    'omnichannel_paid_seat_count', v_row.omnichannel_paid_seat_count,
    'ai_employee_seat_count', v_row.ai_employee_seat_count,
    'keep_employee_ids', to_jsonb(v_row.keep_employee_ids),
    'outlet_quota', v_row.outlet_quota, 'keep_outlet_ids', to_jsonb(v_row.keep_outlet_ids),
    'monthly_price_idr', v_row.monthly_price_idr, 'billing_mode', v_row.billing_mode,
    'ppn_included', v_row.ppn_included, 'price_effective_on', v_row.price_effective_on,
    'period_value_idr', v_row.period_value_idr, 'adjustment_idr', v_row.adjustment_idr,
    'saved_at', v_row.saved_at
  );
END;
$$;


ALTER FUNCTION "public"."admin_save_sales_contract_pending"("p_organization_id" "uuid", "p_is_trial" boolean, "p_trial_end_date" timestamp with time zone, "p_subscription_end_date" timestamp with time zone, "p_modules" "jsonb", "p_hr_seat_count" integer, "p_omnichannel_paid_seat_count" integer, "p_ai_employee_seat_count" integer, "p_keep_employee_ids" "uuid"[], "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[], "p_monthly_price_idr" bigint, "p_billing_mode" "text", "p_ppn_included" boolean, "p_price_effective_on" "date", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_save_sales_contract_pending"("p_organization_id" "uuid", "p_is_trial" boolean, "p_trial_end_date" timestamp with time zone, "p_subscription_end_date" timestamp with time zone, "p_modules" "jsonb", "p_hr_seat_count" integer, "p_omnichannel_paid_seat_count" integer, "p_ai_employee_seat_count" integer, "p_keep_employee_ids" "uuid"[], "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[], "p_monthly_price_idr" bigint, "p_billing_mode" "text", "p_ppn_included" boolean, "p_price_effective_on" "date", "p_reason" "text") IS 'Replaces the waiting Sales package, including the package price. Does not change the live subscription.';



CREATE OR REPLACE FUNCTION "public"."admin_set_organization_ai_employee_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_active integer;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;
  IF p_seats IS NULL OR p_seats < 0 THEN
    RAISE EXCEPTION 'seats must be >= 0' USING ERRCODE = '22023';
  END IF;
  IF NOT public.sales_contract_apply_active() THEN
    RAISE EXCEPTION 'sales changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_org FROM public.organizations WHERE id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;
  IF coalesce(v_org.subscription_self_service_enabled, true) THEN
    RAISE EXCEPTION 'organization is not a sales tenant' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization subscription not found' USING ERRCODE = 'P0002';
  END IF;

  v_active := public.count_active_ai_employees_for_org(p_organization_id);
  IF p_seats < v_active THEN
    RAISE EXCEPTION 'kuota karyawan AI minimal %', v_active USING ERRCODE = '22023';
  END IF;

  UPDATE public.organization_subscriptions
  SET ai_employee_seat_count = p_seats
  WHERE organization_id = p_organization_id;
END;
$$;


ALTER FUNCTION "public"."admin_set_organization_ai_employee_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_organization_hr_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text", "p_keep_employee_ids" "uuid"[], "p_omnichannel_seats" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_before_hr integer;
  v_before_omni integer;
  v_active integer;
  v_eligible integer;
  v_target_omni integer;
  v_omni_max integer;
  v_cap integer;
  v_roster_ids uuid[];
  v_roster_count integer;
  v_keep_count integer;
  v_remove_ids uuid[] := ARRAY[]::uuid[];
  v_removed jsonb := '[]'::jsonb;
  v_applying boolean := false;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF p_seats IS NULL OR p_seats < 0 THEN
    RAISE EXCEPTION 'seats must be >= 0' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(42, hashtext(p_organization_id::text));

  SELECT *
  INTO v_org
  FROM public.organizations
  WHERE id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF coalesce(v_org.subscription_self_service_enabled, true) THEN
    RAISE EXCEPTION 'organization is not a sales tenant' USING ERRCODE = '22023';
  END IF;

  v_applying := public.sales_contract_apply_active();

  IF NOT v_applying THEN
    RAISE EXCEPTION 'sales changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  SELECT
    COALESCE(os.member_count, 0),
    COALESCE(os.omnichannel_paid_seat_count, 0)
  INTO v_before_hr, v_before_omni
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization subscription not found' USING ERRCODE = 'P0002';
  END IF;

  v_active := public.count_active_employees_for_org(p_organization_id);
  IF p_seats < v_active THEN
    RAISE EXCEPTION 'seat HR minimal %', v_active USING ERRCODE = '22023';
  END IF;

  v_eligible := public.count_roster_eligible_employees(p_organization_id);
  v_omni_max := LEAST(p_seats, v_eligible);

  IF p_omnichannel_seats IS NULL THEN
    v_target_omni := LEAST(v_before_omni, p_seats);
  ELSE
    IF p_omnichannel_seats < 0 THEN
      RAISE EXCEPTION 'seats must be >= 0' USING ERRCODE = '22023';
    END IF;
    IF p_omnichannel_seats > v_omni_max THEN
      RAISE EXCEPTION 'kuota maksimal %', v_omni_max USING ERRCODE = '22023';
    END IF;
    v_target_omni := p_omnichannel_seats;
  END IF;

  v_cap := LEAST(p_seats, v_target_omni);

  PERFORM 1
  FROM public.organization_omnichannel_staff s
  WHERE s.organization_id = p_organization_id
  FOR UPDATE;

  SELECT COALESCE(array_agg(s.employee_id), ARRAY[]::uuid[])
  INTO v_roster_ids
  FROM public.organization_omnichannel_staff s
  WHERE s.organization_id = p_organization_id;

  v_roster_count := COALESCE(cardinality(v_roster_ids), 0);

  IF v_roster_count > v_cap THEN
    SELECT COUNT(DISTINCT k.employee_id)
    INTO v_keep_count
    FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id);

    IF v_keep_count IS DISTINCT FROM v_cap
      OR EXISTS (
        SELECT 1
        FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id)
        WHERE NOT (k.employee_id = ANY(v_roster_ids))
      ) THEN
      RAISE EXCEPTION 'pilih tepat % user yang tetap aktif', v_cap USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(array_agg(rid), ARRAY[]::uuid[])
    INTO v_remove_ids
    FROM unnest(v_roster_ids) AS rid
    WHERE NOT (rid = ANY(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])));
  END IF;

  IF COALESCE(cardinality(v_remove_ids), 0) > 0 THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'employee_id', e.id,
        'full_name', COALESCE(e.full_name, ''),
        'email', e.email
      )
      ORDER BY e.full_name
    ), '[]'::jsonb)
    INTO v_removed
    FROM public.employees e
    WHERE e.id = ANY(v_remove_ids);

    UPDATE public.whatsapp_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.instagram_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.facebook_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.threads_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.leads
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    DELETE FROM public.organization_omnichannel_staff
    WHERE organization_id = p_organization_id
      AND employee_id = ANY(v_remove_ids);
  END IF;

  UPDATE public.organization_subscriptions
  SET
    member_count = p_seats,
    omnichannel_paid_seat_count = v_target_omni
  WHERE organization_id = p_organization_id;

  IF NOT v_applying THEN
    INSERT INTO public.cms_subscription_adjustments (
      organization_id,
      adjusted_by,
      reason,
      before_state,
      after_state
    ) VALUES (
      p_organization_id,
      auth.uid(),
      trim(p_reason),
      jsonb_build_object(
        'member_count', v_before_hr,
        'omnichannel_paid_seat_count', v_before_omni
      ),
      jsonb_build_object(
        'member_count', p_seats,
        'omnichannel_paid_seat_count', v_target_omni,
        'removed_roster', v_removed
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'member_count', p_seats,
    'omnichannel_paid_seat_count', v_target_omni,
    'active_employee_count', v_active,
    'removed_roster', v_removed
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_organization_hr_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text", "p_keep_employee_ids" "uuid"[], "p_omnichannel_seats" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_organization_omnichannel_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text", "p_keep_employee_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_before integer;
  v_hr integer;
  v_eligible integer;
  v_max integer;
  v_roster_ids uuid[];
  v_roster_count integer;
  v_keep_count integer;
  v_remove_ids uuid[] := ARRAY[]::uuid[];
  v_removed jsonb := '[]'::jsonb;
  v_applying boolean := false;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF p_seats IS NULL OR p_seats < 0 THEN
    RAISE EXCEPTION 'seats must be >= 0' USING ERRCODE = '22023';
  END IF;

  PERFORM pg_advisory_xact_lock(42, hashtext(p_organization_id::text));

  SELECT *
  INTO v_org
  FROM public.organizations
  WHERE id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF coalesce(v_org.subscription_self_service_enabled, true) THEN
    RAISE EXCEPTION 'organization is not a sales tenant' USING ERRCODE = '22023';
  END IF;

  v_applying := public.sales_contract_apply_active();

  IF NOT v_applying THEN
    RAISE EXCEPTION 'sales changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  SELECT
    COALESCE(os.omnichannel_paid_seat_count, 0),
    COALESCE(os.member_count, 0)
  INTO v_before, v_hr
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization subscription not found' USING ERRCODE = 'P0002';
  END IF;

  v_eligible := public.count_roster_eligible_employees(p_organization_id);
  v_max := LEAST(v_hr, v_eligible);

  IF p_seats > v_max THEN
    RAISE EXCEPTION 'kuota maksimal %', v_max USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.organization_omnichannel_staff s
  WHERE s.organization_id = p_organization_id
  FOR UPDATE;

  SELECT COALESCE(array_agg(s.employee_id), ARRAY[]::uuid[])
  INTO v_roster_ids
  FROM public.organization_omnichannel_staff s
  WHERE s.organization_id = p_organization_id;

  v_roster_count := COALESCE(cardinality(v_roster_ids), 0);

  IF v_roster_count > p_seats THEN
    SELECT COUNT(DISTINCT k.employee_id)
    INTO v_keep_count
    FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id);

    IF v_keep_count IS DISTINCT FROM p_seats
      OR EXISTS (
        SELECT 1
        FROM unnest(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])) AS k(employee_id)
        WHERE NOT (k.employee_id = ANY(v_roster_ids))
      ) THEN
      RAISE EXCEPTION 'pilih tepat % user yang tetap aktif', p_seats USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(array_agg(rid), ARRAY[]::uuid[])
    INTO v_remove_ids
    FROM unnest(v_roster_ids) AS rid
    WHERE NOT (rid = ANY(COALESCE(p_keep_employee_ids, ARRAY[]::uuid[])));
  END IF;

  IF COALESCE(cardinality(v_remove_ids), 0) > 0 THEN
    SELECT COALESCE(jsonb_agg(
      jsonb_build_object(
        'employee_id', e.id,
        'full_name', COALESCE(e.full_name, ''),
        'email', e.email
      )
      ORDER BY e.full_name
    ), '[]'::jsonb)
    INTO v_removed
    FROM public.employees e
    WHERE e.id = ANY(v_remove_ids);

    UPDATE public.whatsapp_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.instagram_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.facebook_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.threads_conversations
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    UPDATE public.leads
    SET assignee_id = NULL
    WHERE organization_id = p_organization_id
      AND assignee_id = ANY(v_remove_ids);

    DELETE FROM public.organization_omnichannel_staff
    WHERE organization_id = p_organization_id
      AND employee_id = ANY(v_remove_ids);
  END IF;

  UPDATE public.organization_subscriptions
  SET omnichannel_paid_seat_count = p_seats
  WHERE organization_id = p_organization_id;

  IF NOT v_applying THEN
    INSERT INTO public.cms_subscription_adjustments (
      organization_id,
      adjusted_by,
      reason,
      before_state,
      after_state
    ) VALUES (
      p_organization_id,
      auth.uid(),
      trim(p_reason),
      jsonb_build_object('omnichannel_paid_seat_count', v_before),
      jsonb_build_object(
        'omnichannel_paid_seat_count', p_seats,
        'removed_roster', v_removed
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'omnichannel_paid_seat_count', p_seats,
    'hr_seat_count', v_hr,
    'roster_eligible_employee_count', v_eligible,
    'removed_roster', v_removed
  );
END;
$$;


ALTER FUNCTION "public"."admin_set_organization_omnichannel_seats"("p_organization_id" "uuid", "p_seats" integer, "p_reason" "text", "p_keep_employee_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_organization_sales_modules"("p_organization_id" "uuid", "p_modules" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb := '{}'::jsonb;
  v_key text;
  v_val boolean;
  v_catalog text[];
  v_applying boolean := false;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF p_modules IS NULL OR jsonb_typeof(p_modules) <> 'object' THEN
    RAISE EXCEPTION 'modules must be a json object' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_org
  FROM public.organizations
  WHERE id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  IF coalesce(v_org.subscription_self_service_enabled, true) THEN
    RAISE EXCEPTION 'organization is not a sales tenant' USING ERRCODE = '22023';
  END IF;

  v_applying := public.sales_contract_apply_active();

  IF NOT v_applying THEN
    RAISE EXCEPTION 'sales changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  v_catalog := public.sales_module_catalog_keys();

  IF EXISTS (
    SELECT 1
    FROM jsonb_each(p_modules) AS e(key, value)
    WHERE e.key = ANY (ARRAY['dashboard', 'subscription'])
       OR NOT (e.key = ANY (v_catalog))
       OR jsonb_typeof(e.value) <> 'boolean'
  ) THEN
    RAISE EXCEPTION 'invalid module keys in payload' USING ERRCODE = '22023';
  END IF;

  PERFORM public.seed_sales_module_access_defaults(p_organization_id);

  FOREACH v_key IN ARRAY v_catalog
  LOOP
    SELECT m.is_enabled
    INTO v_val
    FROM public.organization_sales_module_access m
    WHERE m.organization_id = p_organization_id
      AND m.module_key = v_key;

    v_before := v_before || jsonb_build_object(v_key, coalesce(v_val, false));
  END LOOP;

  FOREACH v_key IN ARRAY v_catalog
  LOOP
    IF p_modules ? v_key THEN
      v_val := (p_modules ->> v_key)::boolean;
    ELSE
      SELECT m.is_enabled
      INTO v_val
      FROM public.organization_sales_module_access m
      WHERE m.organization_id = p_organization_id
        AND m.module_key = v_key;
      v_val := coalesce(v_val, false);
    END IF;

    INSERT INTO public.organization_sales_module_access (
      organization_id,
      module_key,
      is_enabled,
      updated_at
    ) VALUES (
      p_organization_id,
      v_key,
      v_val,
      now()
    )
    ON CONFLICT (organization_id, module_key)
    DO UPDATE SET
      is_enabled = EXCLUDED.is_enabled,
      updated_at = now();

    v_after := v_after || jsonb_build_object(v_key, v_val);
  END LOOP;

  IF NOT v_applying THEN
    INSERT INTO public.cms_organization_module_adjustments (
      organization_id,
      adjusted_by,
      reason,
      before_state,
      after_state
    ) VALUES (
      p_organization_id,
      auth.uid(),
      trim(p_reason),
      jsonb_build_object('modules', v_before),
      jsonb_build_object('modules', v_after)
    );
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'modules', v_after,
    'before_state', jsonb_build_object('modules', v_before),
    'after_state', jsonb_build_object('modules', v_after)
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_organization_sales_modules"("p_organization_id" "uuid", "p_modules" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_organization_settings"("p_organization_id" "uuid", "p_subscription_self_service_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org public.organizations%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_was_sales boolean;
  v_will_be_sales boolean;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  IF p_subscription_self_service_enabled IS NULL THEN
    RAISE EXCEPTION 'subscription_self_service_enabled required' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_org
  FROM public.organizations
  WHERE id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization not found' USING ERRCODE = 'P0002';
  END IF;

  v_was_sales := NOT coalesce(v_org.subscription_self_service_enabled, true);
  v_will_be_sales := NOT p_subscription_self_service_enabled;

  v_before := jsonb_build_object(
    'subscription_self_service_enabled', v_org.subscription_self_service_enabled
  );

  v_after := jsonb_build_object(
    'subscription_self_service_enabled', p_subscription_self_service_enabled
  );

  UPDATE public.organizations
  SET subscription_self_service_enabled = p_subscription_self_service_enabled
  WHERE id = p_organization_id;

  IF v_will_be_sales AND NOT v_was_sales THEN
    PERFORM public.seed_sales_module_access_defaults(p_organization_id);
  END IF;

  INSERT INTO public.cms_subscription_adjustments (
    organization_id,
    adjusted_by,
    reason,
    before_state,
    after_state
  ) VALUES (
    p_organization_id,
    auth.uid(),
    trim(p_reason),
    v_before,
    v_after
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'subscription_self_service_enabled', p_subscription_self_service_enabled,
    'before_state', v_before,
    'after_state', v_after
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_organization_settings"("p_organization_id" "uuid", "p_subscription_self_service_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_update_organization_settings"("p_organization_id" "uuid", "p_subscription_self_service_enabled" boolean, "p_reason" "text") IS 'CMS admin: toggle organizations.subscription_self_service_enabled with audit log.';



CREATE OR REPLACE FUNCTION "public"."admin_update_organization_subscription"("p_organization_id" "uuid", "p_is_trial" boolean, "p_trial_end_date" timestamp with time zone, "p_subscription_end_date" timestamp with time zone, "p_reason" "text", "p_contract_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_sub public.organization_subscriptions%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_new_status text;
  v_new_is_trial boolean;
  v_new_trial_end timestamptz;
  v_new_sub_end timestamptz;
  v_effective_status text;
  v_end timestamptz;
  v_max_future timestamptz := now() + interval '366 days';
  v_active_end timestamptz;
  v_sales boolean := false;
  v_terms_changed boolean := false;
  v_applying boolean := false;
  v_contract_path text;
  v_meta jsonb;
  v_size bigint := 0;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(o.subscription_self_service_enabled, true) = false
  INTO v_sales
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription not found for organization' USING ERRCODE = 'P0002';
  END IF;

  v_applying := public.sales_contract_apply_active();

  IF COALESCE(v_sales, false) AND NOT v_applying THEN
    RAISE EXCEPTION 'sales changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_sub
  FROM public.organization_subscriptions
  WHERE organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subscription not found for organization' USING ERRCODE = 'P0002';
  END IF;

  v_new_is_trial := coalesce(p_is_trial, false);
  v_new_trial_end := p_trial_end_date;
  v_new_sub_end := p_subscription_end_date;
  v_contract_path := nullif(btrim(coalesce(p_contract_path, '')), '');

  v_terms_changed :=
    coalesce(p_is_trial, false) IS DISTINCT FROM coalesce(v_sub.is_trial, false)
    OR date_trunc('minute', p_trial_end_date) IS DISTINCT FROM date_trunc('minute', v_sub.trial_end_date)
    OR date_trunc('minute', p_subscription_end_date) IS DISTINCT FROM date_trunc('minute', v_sub.subscription_end_date);

  IF NOT v_applying THEN
    IF COALESCE(v_sales, false) AND v_terms_changed THEN
      IF v_contract_path IS NULL
         OR v_contract_path !~ (
           '^' || p_organization_id::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$'
         )
      THEN
        RAISE EXCEPTION 'contract pdf required' USING ERRCODE = '22023';
      END IF;

      SELECT o.metadata
      INTO v_meta
      FROM storage.objects o
      WHERE o.bucket_id = 'sales-subscription-contracts'
        AND o.name = v_contract_path
        AND (o.owner = auth.uid() OR o.owner_id = auth.uid()::text);

      IF NOT FOUND THEN
        RAISE EXCEPTION 'contract file not found' USING ERRCODE = 'P0002';
      END IF;

      IF coalesce(v_meta->>'mimetype', '') <> 'application/pdf' THEN
        RAISE EXCEPTION 'contract must be a pdf' USING ERRCODE = '22023';
      END IF;

      BEGIN
        v_size := COALESCE((v_meta->>'size')::bigint, (v_meta->>'contentLength')::bigint, 0);
      EXCEPTION
        WHEN invalid_text_representation THEN
          v_size := 0;
      END;

      IF v_size <= 0 OR v_size > 10485760 THEN
        RAISE EXCEPTION 'contract file is too large' USING ERRCODE = '22023';
      END IF;

      IF EXISTS (
        SELECT 1
        FROM public.cms_subscription_adjustments a
        WHERE a.contract_path = v_contract_path
      ) THEN
        RAISE EXCEPTION 'contract file already used' USING ERRCODE = '23505';
      END IF;
    ELSIF v_contract_path IS NOT NULL THEN
      RAISE EXCEPTION 'contract pdf is not allowed for this change' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_new_is_trial THEN
    IF v_new_trial_end IS NULL THEN
      RAISE EXCEPTION 'trial_end_date required when in trial mode' USING ERRCODE = '22023';
    END IF;
    v_active_end := v_new_trial_end;
  ELSE
    IF v_new_sub_end IS NULL THEN
      RAISE EXCEPTION 'subscription_end_date required when in paid mode' USING ERRCODE = '22023';
    END IF;
    v_active_end := v_new_sub_end;
  END IF;

  IF v_active_end > now() AND v_active_end > v_max_future THEN
    RAISE EXCEPTION 'end date cannot exceed 366 days from now' USING ERRCODE = '22023';
  END IF;

  v_before := jsonb_build_object(
    'is_trial', v_sub.is_trial,
    'status', v_sub.status,
    'trial_end_date', v_sub.trial_end_date,
    'subscription_end_date', v_sub.subscription_end_date,
    'auto_renew', v_sub.auto_renew
  );

  IF v_new_is_trial THEN
    IF v_new_trial_end > now() THEN
      v_new_status := 'trial';
    ELSE
      v_new_status := 'expired';
      v_new_is_trial := false;
    END IF;
  ELSE
    v_new_is_trial := false;
    IF v_new_sub_end > now() THEN
      v_new_status := 'active';
    ELSE
      v_new_status := 'expired';
    END IF;
  END IF;

  UPDATE public.organization_subscriptions
  SET
    is_trial = v_new_is_trial,
    status = v_new_status,
    trial_end_date = v_new_trial_end,
    subscription_end_date = v_new_sub_end,
    auto_renew = CASE
      WHEN NOT v_new_is_trial AND v_new_status = 'active' THEN true
      WHEN v_new_status = 'expired' THEN false
      ELSE auto_renew
    END,
    updated_at = now()
  WHERE organization_id = p_organization_id
  RETURNING * INTO v_sub;

  v_after := jsonb_build_object(
    'is_trial', v_sub.is_trial,
    'status', v_sub.status,
    'trial_end_date', v_sub.trial_end_date,
    'subscription_end_date', v_sub.subscription_end_date,
    'auto_renew', v_sub.auto_renew,
    'has_active_subscription', (
      SELECT o.has_active_subscription
      FROM public.organizations o
      WHERE o.id = p_organization_id
    )
  );

  IF v_sub.is_trial THEN
    v_end := v_sub.trial_end_date;
  ELSE
    v_end := v_sub.subscription_end_date;
  END IF;

  IF v_end IS NOT NULL AND v_end < now() THEN
    v_effective_status := 'expired';
  ELSIF v_sub.is_trial THEN
    v_effective_status := 'trial';
  ELSIF v_sub.status = 'active' THEN
    v_effective_status := 'active';
  ELSE
    v_effective_status := coalesce(v_sub.status, 'unknown');
  END IF;

  IF NOT v_applying THEN
    INSERT INTO public.cms_subscription_adjustments (
      organization_id,
      adjusted_by,
      reason,
      before_state,
      after_state,
      contract_path
    ) VALUES (
      p_organization_id,
      auth.uid(),
      trim(p_reason),
      v_before,
      v_after,
      v_contract_path
    );
  END IF;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'effective_status', v_effective_status,
    'is_trial', v_sub.is_trial,
    'trial_end_date', v_sub.trial_end_date,
    'subscription_end_date', v_sub.subscription_end_date,
    'has_active_subscription', v_after->'has_active_subscription',
    'after_state', v_after,
    'contract_path', CASE WHEN v_applying THEN NULL ELSE v_contract_path END
  );
END;
$_$;


ALTER FUNCTION "public"."admin_update_organization_subscription"("p_organization_id" "uuid", "p_is_trial" boolean, "p_trial_end_date" timestamp with time zone, "p_subscription_end_date" timestamp with time zone, "p_reason" "text", "p_contract_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_plan_add_on_override"("p_plan_id" "uuid", "p_add_on_id" "uuid", "p_unit_price_override_per_month" numeric, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.subscription_plan_add_ons%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_entity_id uuid;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  PERFORM public.admin_validate_price_amount(p_unit_price_override_per_month);

  SELECT * INTO v_row
  FROM public.subscription_plan_add_ons
  WHERE subscription_plan_id = p_plan_id
    AND add_on_id = p_add_on_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan add-on relation not found' USING ERRCODE = 'P0002';
  END IF;

  v_entity_id := p_plan_id;

  v_before := jsonb_build_object(
    'subscription_plan_id', v_row.subscription_plan_id,
    'add_on_id', v_row.add_on_id,
    'unit_price_override_per_month', v_row.unit_price_override_per_month
  );

  UPDATE public.subscription_plan_add_ons
  SET unit_price_override_per_month = p_unit_price_override_per_month
  WHERE subscription_plan_id = p_plan_id
    AND add_on_id = p_add_on_id
  RETURNING * INTO v_row;

  v_after := jsonb_build_object(
    'subscription_plan_id', v_row.subscription_plan_id,
    'add_on_id', v_row.add_on_id,
    'unit_price_override_per_month', v_row.unit_price_override_per_month
  );

  INSERT INTO public.cms_plan_price_adjustments (
    entity_type, entity_id, plan_id, add_on_id, adjusted_by, reason, before_state, after_state
  ) VALUES (
    'plan_add_on', v_entity_id, p_plan_id, p_add_on_id, auth.uid(), trim(p_reason), v_before, v_after
  );

  RETURN jsonb_build_object(
    'subscription_plan_id', v_row.subscription_plan_id,
    'add_on_id', v_row.add_on_id,
    'unit_price_override_per_month', v_row.unit_price_override_per_month,
    'after_state', v_after
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_plan_add_on_override"("p_plan_id" "uuid", "p_add_on_id" "uuid", "p_unit_price_override_per_month" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_plan_modules"("p_subscription_plan_id" "uuid", "p_modules" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan public.subscription_plans%ROWTYPE;
  v_before jsonb := '{}'::jsonb;
  v_after jsonb;
  v_key text;
  v_val boolean;
  v_features jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_plan
  FROM public.subscription_plans
  WHERE id = p_subscription_plan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan not found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.seed_plan_module_access_defaults(p_subscription_plan_id);

  FOREACH v_key IN ARRAY public.sales_module_catalog_keys()
  LOOP
    SELECT m.is_enabled
    INTO v_val
    FROM public.subscription_plan_module_access m
    WHERE m.subscription_plan_id = p_subscription_plan_id
      AND m.module_key = v_key;

    v_before := v_before || jsonb_build_object(v_key, coalesce(v_val, false));
  END LOOP;

  v_after := public._apply_plan_modules(p_subscription_plan_id, p_modules);

  v_features := public._build_plan_features_from_modules(
    v_plan.base_price_per_member,
    v_after,
    v_plan.max_members
  );

  UPDATE public.subscription_plans
  SET features = v_features, updated_at = now()
  WHERE id = p_subscription_plan_id;

  INSERT INTO public.cms_plan_module_adjustments (
    subscription_plan_id,
    adjusted_by,
    reason,
    before_state,
    after_state
  )
  VALUES (
    p_subscription_plan_id,
    auth.uid(),
    trim(p_reason),
    jsonb_build_object('modules', v_before),
    jsonb_build_object('modules', v_after)
  );

  RETURN jsonb_build_object(
    'subscription_plan_id', p_subscription_plan_id,
    'modules', v_after,
    'before_state', jsonb_build_object('modules', v_before),
    'after_state', jsonb_build_object('modules', v_after)
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_plan_modules"("p_subscription_plan_id" "uuid", "p_modules" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_subscription_add_on"("p_add_on_id" "uuid", "p_default_unit_price_per_month" numeric, "p_follows_plan_annual_discount" boolean, "p_is_active" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_add_on public.subscription_add_ons%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  PERFORM public.admin_validate_price_amount(p_default_unit_price_per_month);

  SELECT * INTO v_add_on
  FROM public.subscription_add_ons
  WHERE id = p_add_on_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'add-on not found' USING ERRCODE = 'P0002';
  END IF;

  v_before := jsonb_build_object(
    'default_unit_price_per_month', v_add_on.default_unit_price_per_month,
    'follows_plan_annual_discount', v_add_on.follows_plan_annual_discount,
    'is_active', v_add_on.is_active
  );

  UPDATE public.subscription_add_ons
  SET
    default_unit_price_per_month = p_default_unit_price_per_month,
    follows_plan_annual_discount = coalesce(p_follows_plan_annual_discount, v_add_on.follows_plan_annual_discount),
    is_active = coalesce(p_is_active, v_add_on.is_active),
    updated_at = now()
  WHERE id = p_add_on_id
  RETURNING * INTO v_add_on;

  v_after := jsonb_build_object(
    'default_unit_price_per_month', v_add_on.default_unit_price_per_month,
    'follows_plan_annual_discount', v_add_on.follows_plan_annual_discount,
    'is_active', v_add_on.is_active
  );

  INSERT INTO public.cms_plan_price_adjustments (
    entity_type, entity_id, add_on_id, adjusted_by, reason, before_state, after_state
  ) VALUES (
    'add_on', p_add_on_id, p_add_on_id, auth.uid(), trim(p_reason), v_before, v_after
  );

  RETURN jsonb_build_object(
    'id', v_add_on.id,
    'code', v_add_on.code,
    'name', v_add_on.name,
    'default_unit_price_per_month', v_add_on.default_unit_price_per_month,
    'follows_plan_annual_discount', v_add_on.follows_plan_annual_discount,
    'is_active', v_add_on.is_active,
    'after_state', v_after
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_subscription_add_on"("p_add_on_id" "uuid", "p_default_unit_price_per_month" numeric, "p_follows_plan_annual_discount" boolean, "p_is_active" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_update_subscription_plan"("p_plan_id" "uuid", "p_base_price_per_member" numeric, "p_billing_term_discounts" "jsonb", "p_jumlah_hari_trial" integer, "p_max_members" integer, "p_is_active" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan public.subscription_plans%ROWTYPE;
  v_before jsonb;
  v_after jsonb;
  v_features jsonb;
  v_max_members integer;
  v_discounts jsonb;
  v_annual numeric;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;

  IF p_reason IS NULL OR char_length(trim(p_reason)) < 3 THEN
    RAISE EXCEPTION 'reason required (min 3 characters)' USING ERRCODE = '22023';
  END IF;

  PERFORM public.admin_validate_price_amount(p_base_price_per_member);

  IF p_jumlah_hari_trial IS NOT NULL AND p_jumlah_hari_trial < 0 THEN
    RAISE EXCEPTION 'jumlah_hari_trial must be >= 0' USING ERRCODE = '22023';
  END IF;

  v_discounts := public._validate_billing_term_discounts(p_billing_term_discounts);
  v_annual := public._billing_term_discount(v_discounts, 12);

  SELECT * INTO v_plan
  FROM public.subscription_plans
  WHERE id = p_plan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'plan not found' USING ERRCODE = 'P0002';
  END IF;

  v_max_members := public._resolve_plan_max_members(
    public._validate_plan_max_members(p_max_members),
    coalesce(p_jumlah_hari_trial, v_plan.jumlah_hari_trial),
    p_base_price_per_member
  );

  v_before := jsonb_build_object(
    'base_price_per_member', v_plan.base_price_per_member,
    'billing_term_discounts', v_plan.billing_term_discounts,
    'annual_discount_percentage', v_plan.annual_discount_percentage,
    'jumlah_hari_trial', v_plan.jumlah_hari_trial,
    'max_members', v_plan.max_members,
    'is_active', v_plan.is_active
  );

  v_features := public._build_plan_features_from_modules(
    p_base_price_per_member,
    public._plan_modules_json_for_plan(p_plan_id),
    v_max_members
  );

  UPDATE public.subscription_plans
  SET
    base_price_per_member = p_base_price_per_member,
    billing_term_discounts = v_discounts,
    annual_discount_percentage = v_annual,
    jumlah_hari_trial = p_jumlah_hari_trial,
    max_members = v_max_members,
    features = v_features,
    is_active = coalesce(p_is_active, v_plan.is_active),
    updated_at = now()
  WHERE id = p_plan_id
  RETURNING * INTO v_plan;

  v_after := jsonb_build_object(
    'base_price_per_member', v_plan.base_price_per_member,
    'billing_term_discounts', v_plan.billing_term_discounts,
    'annual_discount_percentage', v_plan.annual_discount_percentage,
    'jumlah_hari_trial', v_plan.jumlah_hari_trial,
    'max_members', v_plan.max_members,
    'is_active', v_plan.is_active
  );

  INSERT INTO public.cms_plan_price_adjustments (
    entity_type, entity_id, plan_id, adjusted_by, reason, before_state, after_state
  ) VALUES (
    'plan', p_plan_id, p_plan_id, auth.uid(), trim(p_reason), v_before, v_after
  );

  RETURN jsonb_build_object(
    'id', v_plan.id,
    'name', v_plan.name,
    'base_price_per_member', v_plan.base_price_per_member,
    'billing_term_discounts', v_plan.billing_term_discounts,
    'annual_discount_percentage', v_plan.annual_discount_percentage,
    'jumlah_hari_trial', v_plan.jumlah_hari_trial,
    'max_members', v_plan.max_members,
    'is_active', v_plan.is_active,
    'features', v_plan.features,
    'after_state', v_after
  );
END;
$$;


ALTER FUNCTION "public"."admin_update_subscription_plan"("p_plan_id" "uuid", "p_base_price_per_member" numeric, "p_billing_term_discounts" "jsonb", "p_jumlah_hari_trial" integer, "p_max_members" integer, "p_is_active" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_validate_price_amount"("p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_amount IS NULL THEN
    RETURN;
  END IF;
  IF p_amount < 0 OR p_amount > 10000000 THEN
    RAISE EXCEPTION 'price must be between 0 and 10000000' USING ERRCODE = '22023';
  END IF;
END;
$$;


ALTER FUNCTION "public"."admin_validate_price_amount"("p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_verify_organization_deleted"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  r record;
  v_sql text;
  v_count bigint;
  v_remaining jsonb := '{}'::jsonb;
  v_org_exists boolean;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.organizations WHERE id = p_organization_id
  ) INTO v_org_exists;

  FOR r IN
    SELECT c.table_name
    FROM information_schema.columns c
    INNER JOIN information_schema.tables t
      ON t.table_schema = c.table_schema
      AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = 'organization_id'
      AND t.table_type = 'BASE TABLE'
      AND c.table_name NOT IN ('cms_organization_deletions')
    ORDER BY c.table_name
  LOOP
    v_sql := format(
      'SELECT count(*)::bigint FROM public.%I WHERE organization_id = $1',
      r.table_name
    );
    EXECUTE v_sql INTO v_count USING p_organization_id;
    IF v_count > 0 THEN
      v_remaining := v_remaining || jsonb_build_object(r.table_name, v_count);
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'organization_exists', v_org_exists,
    'is_clean', (NOT v_org_exists) AND v_remaining = '{}'::jsonb,
    'remaining_counts', v_remaining
  );
END;
$_$;


ALTER FUNCTION "public"."admin_verify_organization_deleted"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."admin_verify_organization_deleted"("p_organization_id" "uuid") IS 'CMS admin: verify no organization_id rows remain after deletion.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_accept_execution"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_idea uuid;
  v_pillar uuid;
  v_statement text;
  v_facts jsonb;
  v_checks jsonb;
  v_script jsonb;
  v_check text;
  v_pillar_name text;
  v_existing uuid;
  v_id uuid;
  v_required text[] := ARRAY[
    'hookHolds', 'soundsSpoken', 'usesSlang', 'pillarFits', 'formatHolds',
    'mechanismVisible', 'messageStays', 'causeChain', 'viewerClimb', 'emotionalTone'
  ];
BEGIN
  BEGIN
    v_idea := NULLIF(v_payload->>'idea_id', '')::uuid;
    v_pillar := NULLIF(v_payload->>'content_pillar_id', '')::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'input', 'model_call', true);
  END;
  IF p_employee_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND employee.is_ai
  ) THEN
    RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'input', 'model_call', true);
  END IF;

  v_statement := NULLIF(left(btrim(COALESCE(v_payload->>'statement', '')), 4000), '');
  v_facts := v_payload->'facts';
  v_checks := v_payload->'checks';
  v_script := v_payload->'script';

  IF v_idea IS NULL OR v_pillar IS NULL OR v_statement IS NULL
    OR jsonb_typeof(v_facts) IS DISTINCT FROM 'object'
    OR jsonb_typeof(v_checks) IS DISTINCT FROM 'array'
    OR jsonb_typeof(v_script) IS DISTINCT FROM 'object'
    OR position('portraitPath' IN v_script::text) > 0
    OR position('bodyPath' IN v_script::text) > 0
    OR position('sheetPath' IN v_script::text) > 0
    OR position('locationPath' IN v_script::text) > 0
    OR position('propertyPath' IN v_script::text) > 0
  THEN
    RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'input', 'model_call', true);
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.thinking_lab_ideas idea
    WHERE idea.id = v_idea
      AND idea.organization_id = p_organization_id
      AND idea.status = 'locked'
      AND idea.validation->>'decision' = 'LOLOS'
  ) THEN
    RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'idea', 'model_call', true);
  END IF;

  SELECT pillar.name INTO v_pillar_name
  FROM public.content_pillars pillar
  WHERE pillar.id = v_pillar
    AND pillar.is_active
    AND (pillar.organization_id = p_organization_id OR pillar.is_default);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'pillarFits', 'model_call', true);
  END IF;

  IF COALESCE(v_facts->>'resolution', '') IS DISTINCT FROM 'RESOLVED'
    OR COALESCE(v_facts->>'relationToParent', '') IS DISTINCT FROM 'VALID_EXECUTION'
    OR jsonb_typeof(v_facts->'unresolvedReasons') IS DISTINCT FROM 'array'
    OR jsonb_array_length(v_facts->'unresolvedReasons') <> 0
  THEN
    RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', 'admission', 'model_call', true);
  END IF;

  FOREACH v_check IN ARRAY v_required LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_checks) AS item
      WHERE item->>'id' = v_check
        AND item->>'state' = 'pass'
    ) THEN
      RETURN jsonb_build_object('ok', true, 'accepted', false, 'check_id', v_check, 'model_call', true);
    END IF;
  END LOOP;

  SELECT ex.id INTO v_existing
  FROM public.thinking_lab_executions ex
  WHERE ex.organization_id = p_organization_id
    AND ex.idea_id = v_idea
    AND ex.content_pillar_id = v_pillar
    AND ex.creative_idea_id IS NULL
    AND ex.author_employee_id = p_employee_id
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE public.thinking_lab_executions ex
    SET pillar = v_pillar::text,
        pillar_name = v_pillar_name,
        statement = v_statement,
        script = v_script,
        canonical_semantic = v_facts || jsonb_build_object('pillar', v_pillar_name),
        admission = 'GENERATE_VALID',
        author_employee_id = p_employee_id
    WHERE ex.id = v_existing
      AND ex.author_employee_id = p_employee_id
    RETURNING ex.id INTO v_id;
  ELSE
    INSERT INTO public.thinking_lab_executions (
      organization_id, idea_id, pillar, content_pillar_id, pillar_name,
      statement, script, canonical_semantic, admission, author_employee_id
    ) VALUES (
      p_organization_id, v_idea, v_pillar::text, v_pillar, v_pillar_name,
      v_statement, v_script, v_facts || jsonb_build_object('pillar', v_pillar_name),
      'GENERATE_VALID', p_employee_id
    )
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'accepted', true, 'execution_id', v_id, 'model_call', true);
END;
$$;


ALTER FUNCTION "public"."ai_employee_accept_execution"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_angle_options"("p_organization_id" "uuid", "p_selected" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  WITH linked AS (
    SELECT
      angle.id,
      left(COALESCE(btrim(master.statement), ''), 240) AS master,
      master.service_id,
      left(COALESCE(btrim(angle.code), ''), 16) AS code,
      left(
        COALESCE(
          NULLIF(btrim(angle.canonical_semantic->>'subject'), ''),
          NULLIF(btrim(angle.code), ''),
          'Angle'
        ),
        80
      ) AS name,
      left(COALESCE(btrim(angle.statement), ''), 500) AS statement,
      angle.admission,
      master.statement AS master_sort
    FROM public.thinking_lab_angles angle
    JOIN public.thinking_lab_territories territory
      ON territory.id = angle.territory_id
     AND territory.organization_id = angle.organization_id
    JOIN public.thinking_big_thoughts thought
      ON thought.id = territory.big_thought_id
     AND thought.organization_id = angle.organization_id
    JOIN public.thinking_master_thoughts master
      ON master.id = thought.master_thought_id
     AND master.organization_id = angle.organization_id
     AND master.workspace = 'thinking_lab'
    WHERE angle.organization_id = p_organization_id
  ),
  chosen AS (
    SELECT fresh.id
    FROM (
      SELECT linked.id
      FROM linked
      WHERE linked.admission = 'GENERATE_VALID'
      ORDER BY linked.master_sort, linked.code
      LIMIT 200
    ) fresh
    UNION
    SELECT linked.id
    FROM linked
    WHERE linked.id = ANY (COALESCE(p_selected, '{}'::uuid[]))
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', item.id,
    'label', 'Angle - ' || item.code,
    'master', item.master,
    'code', item.code,
    'name', item.name,
    'statement', item.statement,
    'service_id', item.service_id,
    'ideas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', idea.id,
        'code', left(COALESCE(btrim(idea.code), ''), 16),
        'name', left(
          COALESCE(
            NULLIF(btrim(idea.canonical_semantic->>'subject'), ''),
            NULLIF(btrim(idea.code), ''),
            'Idea'
          ),
          80
        ),
        'statement', left(COALESCE(btrim(idea.statement), ''), 400)
      ) ORDER BY idea.sort_order, idea.code)
      FROM (
        SELECT idea.id, idea.code, idea.statement, idea.canonical_semantic, idea.sort_order
        FROM public.thinking_lab_ideas idea
        WHERE idea.angle_id = item.id
          AND idea.organization_id = p_organization_id
          AND idea.status = 'locked'
          AND idea.validation->>'decision' = 'LOLOS'
        ORDER BY idea.sort_order, idea.code
        LIMIT 12
      ) idea
    ), '[]'::jsonb),
    'pillar_ids', COALESCE((
      SELECT jsonb_agg(DISTINCT pillar.id)
      FROM public.thinking_lab_ideas idea
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(idea.development_paths, '[]'::jsonb)) AS path
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(path->'reviews', '[]'::jsonb)) AS review
      JOIN public.content_pillars pillar
        ON pillar.id = CASE
          WHEN path->>'contentPillarId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN (path->>'contentPillarId')::uuid
          ELSE NULL
        END
       AND pillar.is_active
       AND (pillar.organization_id = p_organization_id OR pillar.is_default)
      WHERE idea.angle_id = item.id
        AND idea.organization_id = p_organization_id
        AND idea.status = 'locked'
        AND idea.validation->>'decision' = 'LOLOS'
        AND path->>'status' = 'RECOMMENDED'
        AND (
          path->'format' = 'null'::jsonb
          OR path->>'format' IS NULL
          OR path->>'format' = 'carousel'
        )
        AND review->>'contentPillarId' = path->>'contentPillarId'
        AND btrim(COALESCE(review->>'development', '')) <> ''
    ), '[]'::jsonb),
    'other_idea_count', (
      SELECT count(*)::int
      FROM public.thinking_lab_ideas idea
      WHERE idea.angle_id = item.id
        AND idea.organization_id = p_organization_id
        AND NOT (idea.status = 'locked' AND idea.validation->>'decision' = 'LOLOS')
    )
  ) ORDER BY item.master, item.code), '[]'::jsonb)
  FROM linked item
  WHERE item.id IN (SELECT chosen.id FROM chosen);
$_$;


ALTER FUNCTION "public"."ai_employee_angle_options"("p_organization_id" "uuid", "p_selected" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_assert_job_claim"("p_employee_id" "uuid", "p_run_id" "uuid", "p_payload" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job uuid;
  v_token uuid;
BEGIN
  SELECT run.job_id
  INTO v_job
  FROM public.ai_employee_runs run
  WHERE run.id = p_run_id
    AND run.employee_id = p_employee_id;

  IF v_job IS NULL THEN
    RETURN;
  END IF;

  BEGIN
    v_token := NULLIF(p_payload->>'claim_token', '')::uuid;
  EXCEPTION
    WHEN invalid_text_representation THEN
      v_token := NULL;
  END;

  IF v_token IS NULL THEN
    RAISE EXCEPTION 'stale_claim' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.ai_employee_jobs job
  WHERE job.id = v_job
    AND job.employee_id = p_employee_id
    AND job.run_id = p_run_id
    AND job.status = 'running'
    AND job.claim_token = v_token
  FOR UPDATE OF job;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale_claim' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_assert_job_claim"("p_employee_id" "uuid", "p_run_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_assert_task"("p_employee_id" "uuid", "p_org" "uuid", "p_task_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.daily_tasks t
    WHERE t.id = p_task_id
      AND t.organization_id = p_org
      AND (
        t.requested_ai_employee_id = p_employee_id
        OR EXISTS (
          SELECT 1
          FROM public.daily_tasks_assigned a
          WHERE a.daily_task_id = t.id
            AND a.employee_id = p_employee_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'not_assignee' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_assert_task"("p_employee_id" "uuid", "p_org" "uuid", "p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_assign_content_plan_position"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_position uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = p_employee_id AND e.organization_id = p_organization_id AND COALESCE(e.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'karyawan AI tidak ditemukan' USING ERRCODE = 'P0002';
  END IF;

  SELECT jp.id INTO v_position
  FROM public.job_positions jp
  WHERE jp.organization_id = p_organization_id
    AND jp.department_id IS NULL
    AND lower(btrim(jp.name)) = 'content plan'
  ORDER BY jp.is_active DESC, jp.created_at
  LIMIT 1;

  IF v_position IS NULL THEN
    INSERT INTO public.job_positions (organization_id, name, department_id, is_active)
    VALUES (p_organization_id, 'Content Plan', NULL, true)
    RETURNING id INTO v_position;
  ELSE
    UPDATE public.job_positions
    SET is_active = true, updated_at = now()
    WHERE id = v_position AND is_active IS NOT TRUE;
  END IF;

  UPDATE public.employees
  SET job_position_id = v_position, updated_at = now()
  WHERE id = p_employee_id AND organization_id = p_organization_id AND job_position_id IS NULL;
END;
$$;


ALTER FUNCTION "public"."ai_employee_assign_content_plan_position"("p_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_ids"("p_values" "jsonb") RETURNS "uuid"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids uuid[] := '{}';
  v_text text;
BEGIN
  IF p_values IS NULL OR jsonb_typeof(p_values) = 'null' THEN
    RETURN v_ids;
  END IF;
  IF jsonb_typeof(p_values) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  FOR v_text IN SELECT jsonb_array_elements_text(p_values)
  LOOP
    BEGIN
      v_ids := v_ids || v_text::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END;
  END LOOP;
  SELECT COALESCE(array_agg(DISTINCT id), '{}')
  INTO v_ids
  FROM unnest(v_ids) AS id;
  RETURN v_ids;
END;
$$;


ALTER FUNCTION "public"."ai_employee_brief_ids"("p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_payload"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_row public.ai_employee_briefs%ROWTYPE;
  v_org uuid;
BEGIN
  SELECT * INTO v_row FROM public.ai_employee_briefs WHERE employee_id = p_employee_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'service_ids', '[]'::jsonb,
      'services', '[]'::jsonb,
      'audience', '',
      'persona_ids', '[]'::jsonb,
      'personas', '[]'::jsonb,
      'voice', '',
      'required_notes', '',
      'forbidden_notes', '',
      'pillar_ids', '[]'::jsonb,
      'split_rule', '',
      'product_knowledge_ids', '[]'::jsonb,
      'products', '[]'::jsonb,
      'angle_ids', '[]'::jsonb,
      'angles', '[]'::jsonb,
      'repeat_voices', '[]'::jsonb,
      'use_system_hooks', true,
      'execution_check_enabled', true,
    'references', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'position', ref.position,
        'storage_path', ref.storage_path
      ) ORDER BY ref.position)
      FROM public.ai_employee_brief_references ref
      WHERE ref.employee_id = p_employee_id
    ), '[]'::jsonb),
    'brand_color_id', NULL,
    'company_logo_id', NULL,
    'brand_colors', '[]'::jsonb,
    'company_logos', '[]'::jsonb,
    'content_plan_auto_approve', false,
    'sub_service_id', NULL,
    'sub_service_ids', '[]'::jsonb,
    'sub_services', '[]'::jsonb,
    'palette', NULL
    );
  END IF;
  v_org := v_row.organization_id;
  RETURN jsonb_build_object(
    'service_ids', to_jsonb(v_row.service_ids),
    'services', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', svc.id, 'name', left(btrim(svc.name), 80)) ORDER BY svc.name)
      FROM public.services svc
      WHERE svc.organization_id = v_org
        AND svc.id = ANY (v_row.service_ids)
        AND COALESCE(svc.is_active, true)
    ), '[]'::jsonb),
    'audience', v_row.audience,
    'persona_ids', to_jsonb(v_row.persona_ids),
    'personas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', knowledge.id,
        'audience', left(btrim(COALESCE(
          CASE jsonb_typeof(knowledge.target_audience)
            WHEN 'string' THEN knowledge.target_audience #>> '{}'
            WHEN 'array' THEN knowledge.target_audience #>> '{0}'
            ELSE COALESCE(
              knowledge.target_audience->>'name',
              knowledge.target_audience->>'description',
              knowledge.target_audience->>'persona',
              ''
            )
          END, '')), 500)
      ) ORDER BY knowledge.created_at)
      FROM public.product_knowledge knowledge
      WHERE knowledge.organization_id = v_org
        AND knowledge.id = ANY (v_row.persona_ids)
    ), '[]'::jsonb),
    'voice', v_row.voice,
    'required_notes', v_row.required_notes,
    'forbidden_notes', v_row.forbidden_notes,
    'pillar_ids', to_jsonb(v_row.pillar_ids),
    'split_rule', v_row.split_rule,
    'product_knowledge_ids', to_jsonb(v_row.product_knowledge_ids),
    'products', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', knowledge.id,
        'feature_name', left(btrim(knowledge.feature_name), 80),
        'service_name', left(btrim(COALESCE(svc.name, '')), 80),
        'sub_service_name', left(btrim(COALESCE(sub.name, '')), 80),
        'audience', left(btrim(COALESCE(public.ai_employee_product_clip(knowledge.target_audience, 160), '')), 160)
      ) ORDER BY knowledge.feature_name)
      FROM public.product_knowledge knowledge
      LEFT JOIN public.services svc
        ON svc.id = knowledge.service_id
       AND svc.organization_id = knowledge.organization_id
      LEFT JOIN public.sub_services sub
        ON sub.id = knowledge.sub_service_id
       AND sub.organization_id = knowledge.organization_id
      WHERE knowledge.organization_id = v_org
        AND knowledge.id = ANY (v_row.product_knowledge_ids)
    ), '[]'::jsonb),
    'angle_ids', to_jsonb(v_row.angle_ids),
    'angles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', picked.id, 'label', picked.label) ORDER BY picked.label)
      FROM jsonb_to_recordset(public.ai_employee_angle_options(v_org, v_row.angle_ids))
        AS picked(id uuid, label text)
      WHERE picked.id = ANY (v_row.angle_ids)
    ), '[]'::jsonb),
    'repeat_voices', to_jsonb(v_row.repeat_voices),
    'use_system_hooks', COALESCE(v_row.use_system_hooks, true),
    'execution_check_enabled', COALESCE(v_row.execution_check_enabled, true),
    'references', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'position', ref.position,
        'storage_path', ref.storage_path
      ) ORDER BY ref.position)
      FROM public.ai_employee_brief_references ref
      WHERE ref.employee_id = p_employee_id
        AND ref.organization_id = v_org
    ), '[]'::jsonb),
    'brand_color_id', CASE
      WHEN cardinality(v_row.service_ids) = 1 AND EXISTS (
        SELECT 1 FROM public.digital_asset_brand_colors color
        WHERE color.id = v_row.brand_color_id
          AND color.organization_id = v_org
          AND color.service_id = v_row.service_ids[1]
      ) THEN v_row.brand_color_id
      ELSE NULL
    END,
    'company_logo_id', CASE
      WHEN cardinality(v_row.service_ids) = 1 AND EXISTS (
        SELECT 1 FROM public.digital_asset_company_logos logo
        WHERE logo.id = v_row.company_logo_id
          AND logo.organization_id = v_org
          AND logo.service_id = v_row.service_ids[1]
      ) THEN v_row.company_logo_id
      ELSE NULL
    END,
    'brand_colors', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', color.id,
        'brand_name', left(btrim(COALESCE(color.brand_name, '')), 80),
        'primary_color_hex', color.primary_color_hex,
        'secondary_color_hex', color.secondary_color_hex,
        'accent_color_hex', color.accent_color_hex
      ) ORDER BY color.updated_at DESC)
      FROM public.digital_asset_brand_colors color
      WHERE cardinality(v_row.service_ids) = 1
        AND color.organization_id = v_org
        AND color.service_id = v_row.service_ids[1]
    ), '[]'::jsonb),
    'company_logos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', logo.id,
        'brand_name', left(btrim(COALESCE(logo.brand_name, '')), 80),
        'tagline', left(btrim(COALESCE(logo.tagline, '')), 120),
        'headline_font', left(btrim(COALESCE(logo.headline_font, '')), 60),
        'body_font', left(btrim(COALESCE(logo.body_font, '')), 60),
        'website_url', left(btrim(COALESCE(logo.website_url, '')), 200),
        'default_contact', left(btrim(COALESCE(logo.default_contact, '')), 80),
        'hashtags', to_jsonb(COALESCE(logo.hashtags, '{}'::text[])),
        'logo_path', logo.logo_path
      ) ORDER BY logo.updated_at DESC)
      FROM public.digital_asset_company_logos logo
      WHERE cardinality(v_row.service_ids) = 1
        AND logo.organization_id = v_org
        AND logo.service_id = v_row.service_ids[1]
    ), '[]'::jsonb),
    'content_plan_auto_approve', COALESCE(v_row.content_plan_auto_approve, false),
    'sub_service_id', CASE
      WHEN cardinality(v_row.service_ids) = 1 AND EXISTS (
        SELECT 1 FROM public.sub_services sub
        WHERE sub.id = v_row.sub_service_id
          AND sub.organization_id = v_org
          AND sub.service_id = v_row.service_ids[1]
          AND COALESCE(sub.is_active, true)
      ) THEN v_row.sub_service_id
      ELSE NULL
    END,
    'sub_service_ids', COALESCE((
      SELECT jsonb_agg(item.id ORDER BY item.ord)
      FROM unnest(COALESCE(v_row.sub_service_ids, '{}'::uuid[])) WITH ORDINALITY AS item(id, ord)
      JOIN public.sub_services sub ON sub.id = item.id
      WHERE cardinality(v_row.service_ids) = 1
        AND sub.organization_id = v_org
        AND sub.service_id = v_row.service_ids[1]
        AND COALESCE(sub.is_active, true)
        AND lower(btrim(sub.name)) <> 'general content'
    ), '[]'::jsonb),
    'sub_services', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', sub.id,
        'name', left(btrim(sub.name), 80),
        'service_id', sub.service_id,
        'has_library_photo', EXISTS (
          SELECT 1 FROM public.sub_service_library_photos(v_org, ARRAY[sub.id])
        )
      ) ORDER BY sub.name)
      FROM public.sub_services sub
      WHERE cardinality(v_row.service_ids) = 1
        AND sub.organization_id = v_org
        AND sub.service_id = v_row.service_ids[1]
        AND COALESCE(sub.is_active, true)
    ), '[]'::jsonb),
    'palette', (
      SELECT jsonb_build_object(
        'primary', lower(color.primary_color_hex),
        'secondary', lower(color.secondary_color_hex),
        'accent', lower(color.accent_color_hex)
      )
      FROM public.digital_asset_brand_colors color
      WHERE color.id = v_row.brand_color_id
        AND cardinality(v_row.service_ids) = 1
        AND color.organization_id = v_org
        AND color.service_id = v_row.service_ids[1]
        AND color.primary_color_hex ~ '^#[0-9A-Fa-f]{6}$'
        AND color.secondary_color_hex ~ '^#[0-9A-Fa-f]{6}$'
        AND color.accent_color_hex ~ '^#[0-9A-Fa-f]{6}$'
    )
  );
END;
$_$;


ALTER FUNCTION "public"."ai_employee_brief_payload"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_read"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id);
  IF NOT EXISTS (
    SELECT 1 FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object('ok', true, 'brief', public.ai_employee_brief_payload(p_employee_id));
END;
$$;


ALTER FUNCTION "public"."ai_employee_brief_read"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_reference_clear"("p_employee_id" "uuid", "p_position" smallint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_path text;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  IF p_position IS NULL OR p_position < 1 OR p_position > 5 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT ref.storage_path
  INTO v_path
  FROM public.ai_employee_brief_references ref
  WHERE ref.employee_id = p_employee_id
    AND ref.organization_id = v_org
    AND ref.position = p_position;

  DELETE FROM public.ai_employee_brief_references ref
  WHERE ref.employee_id = p_employee_id
    AND ref.organization_id = v_org
    AND ref.position = p_position;

  IF v_path IS NOT NULL THEN
    PERFORM set_config('storage.allow_delete_query', 'true', true);
    DELETE FROM storage.objects object
    WHERE object.bucket_id = 'ai-employee-references'
      AND object.name = v_path;
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_brief_reference_clear"("p_employee_id" "uuid", "p_position" smallint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_brief_reference_clear"("p_employee_id" "uuid", "p_position" smallint) IS 'Owner mengosongkan satu slot referensi visual dan menghapus berkasnya.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_reference_set"("p_employee_id" "uuid", "p_position" smallint, "p_storage_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_old text;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  IF p_position IS NULL OR p_position < 1 OR p_position > 5 OR p_storage_path IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_storage_path !~ (
    '^' || v_org::text || '/' || p_employee_id::text || '/' || p_position::text || '\.(png|jpe?g|webp)$'
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects object
    WHERE object.bucket_id = 'ai-employee-references'
      AND object.name = p_storage_path
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT ref.storage_path
  INTO v_old
  FROM public.ai_employee_brief_references ref
  WHERE ref.employee_id = p_employee_id
    AND ref.position = p_position;

  INSERT INTO public.ai_employee_brief_references (employee_id, organization_id, position, storage_path, updated_at)
  VALUES (p_employee_id, v_org, p_position, p_storage_path, now())
  ON CONFLICT (employee_id, position) DO UPDATE
  SET organization_id = EXCLUDED.organization_id,
      storage_path = EXCLUDED.storage_path,
      updated_at = now();

  IF v_old IS NOT NULL AND v_old IS DISTINCT FROM p_storage_path THEN
    PERFORM set_config('storage.allow_delete_query', 'true', true);
    DELETE FROM storage.objects object
    WHERE object.bucket_id = 'ai-employee-references'
      AND object.name = v_old;
  END IF;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_brief_reference_set"("p_employee_id" "uuid", "p_position" smallint, "p_storage_path" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_brief_reference_set"("p_employee_id" "uuid", "p_position" smallint, "p_storage_path" "text") IS 'Owner mencatat satu slot referensi visual setelah berkas ada di bucket privat.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_voices"("p_values" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$ DECLARE v_voices text[] := '{}'; v_text text; BEGIN IF p_values IS NULL OR jsonb_typeof(p_values) = 'null' THEN RETURN v_voices; END IF; IF jsonb_typeof(p_values) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023'; END IF; FOR v_text IN SELECT btrim(item) FROM jsonb_array_elements_text(p_values) AS element(item) LOOP IF v_text = '' THEN CONTINUE; END IF; IF char_length(v_text) > 500 THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023'; END IF; IF NOT (v_text = ANY (v_voices)) THEN v_voices := v_voices || v_text; END IF; END LOOP; RETURN v_voices; END; $$;


ALTER FUNCTION "public"."ai_employee_brief_voices"("p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_brief_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_brief" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$ DECLARE v_previous jsonb; v_services uuid[]; v_personas uuid[]; v_pillars uuid[]; v_products uuid[]; v_angles uuid[]; v_voices text[]; v_has_angles boolean; v_has_voices boolean; v_audience text; v_voice text; v_required text; v_forbidden text; v_split text; v_sub uuid; v_subs uuid[]; v_auto boolean; v_hooks boolean; v_exec_check boolean; v_has_sub boolean; v_has_auto boolean; v_has_hooks boolean; v_has_exec_check boolean; BEGIN PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id); IF p_brief IS NULL OR jsonb_typeof(p_brief) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023'; END IF; IF NOT EXISTS (SELECT 1 FROM public.employees employee WHERE employee.id = p_employee_id AND employee.organization_id = p_organization_id AND COALESCE(employee.is_ai, false)) THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF; v_services := public.ai_employee_brief_ids(p_brief->'service_ids'); v_personas := public.ai_employee_brief_ids(p_brief->'persona_ids'); v_pillars := public.ai_employee_brief_ids(p_brief->'pillar_ids'); v_products := public.ai_employee_brief_ids(p_brief->'product_knowledge_ids'); v_has_angles := p_brief ? 'angle_ids'; v_has_voices := p_brief ? 'repeat_voices'; v_angles := CASE WHEN v_has_angles THEN public.ai_employee_brief_ids(p_brief->'angle_ids') ELSE '{}'::uuid[] END; v_voices := CASE WHEN v_has_voices THEN public.ai_employee_brief_voices(p_brief->'repeat_voices') ELSE '{}'::text[] END; v_audience := left(btrim(COALESCE(p_brief->>'audience', '')), 1001); v_voice := left(btrim(COALESCE(p_brief->>'voice', '')), 1001); v_required := left(btrim(COALESCE(p_brief->>'required_notes', '')), 2001); v_forbidden := left(btrim(COALESCE(p_brief->>'forbidden_notes', '')), 2001); v_split := left(btrim(COALESCE(p_brief->>'split_rule', '')), 1001); IF char_length(v_audience) > 1000 OR char_length(v_voice) > 1000 OR char_length(v_required) > 2000 OR char_length(v_forbidden) > 2000 OR char_length(v_split) > 1000 OR cardinality(v_services) > 1 OR cardinality(v_personas) > 12 OR cardinality(v_pillars) > 12 OR cardinality(v_products) > 12 OR (v_has_angles AND cardinality(v_angles) > 6) OR (v_has_voices AND cardinality(v_voices) > 3) THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023'; END IF; IF EXISTS (SELECT 1 FROM unnest(v_services) AS picked(picked_id) WHERE NOT EXISTS (SELECT 1 FROM public.services svc WHERE svc.id = picked.picked_id AND svc.organization_id = p_organization_id AND COALESCE(svc.is_active, true))) OR EXISTS (SELECT 1 FROM unnest(v_personas) AS picked(picked_id) WHERE NOT EXISTS (SELECT 1 FROM public.product_knowledge knowledge WHERE knowledge.id = picked.picked_id AND knowledge.organization_id = p_organization_id)) OR EXISTS (SELECT 1 FROM unnest(v_pillars) AS picked(picked_id) WHERE NOT EXISTS (SELECT 1 FROM public.content_pillars pillar WHERE pillar.id = picked.picked_id AND pillar.is_active AND (pillar.organization_id = p_organization_id OR pillar.is_default))) OR EXISTS (SELECT 1 FROM unnest(v_products) AS picked(picked_id) WHERE NOT EXISTS (SELECT 1 FROM public.product_knowledge knowledge LEFT JOIN public.sub_services sub ON sub.id = knowledge.sub_service_id AND sub.organization_id = knowledge.organization_id WHERE knowledge.id = picked.picked_id AND knowledge.organization_id = p_organization_id AND (knowledge.service_id = ANY (v_services) OR sub.service_id = ANY (v_services)))) OR (v_has_angles AND EXISTS (SELECT 1 FROM unnest(v_angles) AS picked(picked_id) WHERE NOT EXISTS (SELECT 1 FROM public.thinking_lab_angles angle WHERE angle.id = picked.picked_id AND angle.organization_id = p_organization_id AND angle.admission = 'GENERATE_VALID'))) THEN RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023'; END IF; v_has_sub := p_brief ? 'sub_service_ids' OR p_brief ? 'sub_service_id';
  v_has_auto := p_brief ? 'content_plan_auto_approve';
  v_subs := '{}'::uuid[];
  v_sub := NULL;
  IF p_brief ? 'sub_service_ids' THEN
    IF jsonb_typeof(p_brief->'sub_service_ids') IS DISTINCT FROM 'array'
      OR jsonb_array_length(p_brief->'sub_service_ids') > 8 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(p_brief->'sub_service_ids') AS elem(value)
      WHERE NULLIF(btrim(elem.value), '') IS NOT NULL
        AND btrim(elem.value) !~ '^[0-9a-fA-F-]{36}$'
    ) THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    SELECT COALESCE(array_agg(picked.id ORDER BY picked.ord), '{}'::uuid[])
      INTO v_subs
    FROM (
      SELECT elem.value::uuid AS id, min(elem.ord) AS ord
      FROM jsonb_array_elements_text(p_brief->'sub_service_ids') WITH ORDINALITY AS elem(value, ord)
      WHERE btrim(elem.value) ~ '^[0-9a-fA-F-]{36}$'
      GROUP BY elem.value::uuid
    ) AS picked;
  ELSIF NULLIF(btrim(COALESCE(p_brief->>'sub_service_id', '')), '') IS NOT NULL THEN
    IF (p_brief->>'sub_service_id') !~ '^[0-9a-fA-F-]{36}$' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_subs := ARRAY[(p_brief->>'sub_service_id')::uuid];
  END IF;
  v_sub := CASE WHEN cardinality(v_subs) > 0 THEN v_subs[1] ELSE NULL END;
  v_auto := CASE
    WHEN NOT v_has_auto THEN false
    WHEN jsonb_typeof(p_brief->'content_plan_auto_approve') = 'boolean' THEN (p_brief->>'content_plan_auto_approve')::boolean
    ELSE NULL
  END;
  IF v_has_auto AND v_auto IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_has_hooks := p_brief ? 'use_system_hooks';
  v_hooks := CASE
    WHEN NOT v_has_hooks THEN true
    WHEN jsonb_typeof(p_brief->'use_system_hooks') = 'boolean' THEN (p_brief->>'use_system_hooks')::boolean
    ELSE NULL
  END;
  IF v_has_hooks AND v_hooks IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_has_exec_check := p_brief ? 'execution_check_enabled';
  v_exec_check := CASE
    WHEN NOT v_has_exec_check THEN true
    WHEN jsonb_typeof(p_brief->'execution_check_enabled') = 'boolean' THEN (p_brief->>'execution_check_enabled')::boolean
    ELSE NULL
  END;
  IF v_has_exec_check AND v_exec_check IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_subs) > 0 AND (
    cardinality(v_services) <> 1
    OR EXISTS (
      SELECT 1
      FROM unnest(v_subs) AS picked(picked_id)
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.sub_services sub
        WHERE sub.id = picked.picked_id
          AND sub.organization_id = p_organization_id
          AND sub.service_id = v_services[1]
          AND COALESCE(sub.is_active, true)
          AND lower(btrim(sub.name)) <> 'general content'
      )
    )
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_previous := public.ai_employee_brief_payload(p_employee_id); INSERT INTO public.ai_employee_briefs (employee_id, organization_id, service_ids, audience, persona_ids, voice, required_notes, forbidden_notes, pillar_ids, product_knowledge_ids, angle_ids, repeat_voices, split_rule, sub_service_id, sub_service_ids, content_plan_auto_approve, use_system_hooks, execution_check_enabled, updated_at) VALUES (p_employee_id, p_organization_id, v_services, v_audience, v_personas, v_voice, v_required, v_forbidden, v_pillars, v_products, v_angles, v_voices, v_split, v_sub, v_subs, COALESCE(v_auto, false), COALESCE(v_hooks, true), COALESCE(v_exec_check, true), now()) ON CONFLICT (employee_id) DO UPDATE SET service_ids = EXCLUDED.service_ids, audience = EXCLUDED.audience, persona_ids = EXCLUDED.persona_ids, voice = EXCLUDED.voice, required_notes = EXCLUDED.required_notes, forbidden_notes = EXCLUDED.forbidden_notes, pillar_ids = EXCLUDED.pillar_ids, product_knowledge_ids = EXCLUDED.product_knowledge_ids, angle_ids = CASE WHEN v_has_angles THEN EXCLUDED.angle_ids ELSE ai_employee_briefs.angle_ids END, repeat_voices = CASE WHEN v_has_voices THEN EXCLUDED.repeat_voices ELSE ai_employee_briefs.repeat_voices END, split_rule = EXCLUDED.split_rule,
      sub_service_ids = CASE
        WHEN v_has_sub THEN EXCLUDED.sub_service_ids
        WHEN cardinality(EXCLUDED.service_ids) = 1 THEN COALESCE((
          SELECT array_agg(kept.id ORDER BY kept.ord)
          FROM (
            SELECT item.id, item.ord
            FROM unnest(ai_employee_briefs.sub_service_ids) WITH ORDINALITY AS item(id, ord)
            JOIN public.sub_services sub ON sub.id = item.id
            WHERE sub.organization_id = EXCLUDED.organization_id
              AND sub.service_id = (EXCLUDED.service_ids)[1]
              AND COALESCE(sub.is_active, true)
              AND lower(btrim(sub.name)) <> 'general content'
          ) AS kept
        ), '{}'::uuid[])
        ELSE '{}'::uuid[]
      END,
      sub_service_id = CASE
        WHEN v_has_sub THEN EXCLUDED.sub_service_id
        WHEN cardinality(EXCLUDED.service_ids) = 1 AND EXISTS (
          SELECT 1 FROM public.sub_services sub
          WHERE sub.id = ai_employee_briefs.sub_service_id
            AND sub.organization_id = EXCLUDED.organization_id
            AND sub.service_id = (EXCLUDED.service_ids)[1]
            AND COALESCE(sub.is_active, true)
        ) THEN ai_employee_briefs.sub_service_id
        ELSE NULL
      END,
      content_plan_auto_approve = CASE
        WHEN v_has_auto THEN EXCLUDED.content_plan_auto_approve
        ELSE ai_employee_briefs.content_plan_auto_approve
      END,
      use_system_hooks = CASE
        WHEN v_has_hooks THEN EXCLUDED.use_system_hooks
        ELSE ai_employee_briefs.use_system_hooks
      END,
      execution_check_enabled = CASE
        WHEN v_has_exec_check THEN EXCLUDED.execution_check_enabled
        ELSE ai_employee_briefs.execution_check_enabled
      END,
      brand_color_id = CASE
        WHEN cardinality(EXCLUDED.service_ids) = 1 AND EXISTS (
          SELECT 1 FROM public.digital_asset_brand_colors color
          WHERE color.id = ai_employee_briefs.brand_color_id
            AND color.organization_id = EXCLUDED.organization_id
            AND color.service_id = (EXCLUDED.service_ids)[1]
        ) THEN ai_employee_briefs.brand_color_id
        ELSE NULL
      END,
      company_logo_id = CASE
        WHEN cardinality(EXCLUDED.service_ids) = 1 AND EXISTS (
          SELECT 1 FROM public.digital_asset_company_logos logo
          WHERE logo.id = ai_employee_briefs.company_logo_id
            AND logo.organization_id = EXCLUDED.organization_id
            AND logo.service_id = (EXCLUDED.service_ids)[1]
        ) THEN ai_employee_briefs.company_logo_id
        ELSE NULL
      END,
      updated_at = now(); RETURN jsonb_build_object('ok', true, 'previous', v_previous, 'brief', public.ai_employee_brief_payload(p_employee_id)); END; $_$;


