CREATE OR REPLACE FUNCTION "public"."ai_employee_canva_brief"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("required_notes" "text", "forbidden_notes" "text", "company_logo_id" "uuid", "service_ids" "uuid"[], "sub_service_ids" "uuid"[], "sub_service_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT brief.required_notes,
         brief.forbidden_notes,
         brief.company_logo_id,
         brief.service_ids,
         brief.sub_service_ids,
         brief.sub_service_id
  FROM public.ai_employee_briefs brief
  JOIN public.employees employee
    ON employee.id = brief.employee_id
   AND employee.organization_id = brief.organization_id
   AND COALESCE(employee.is_ai, false)
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = p_organization_id
$$;


ALTER FUNCTION "public"."ai_employee_canva_brief"("p_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_carousel_fields"("p_organization_id" "uuid", "p_payload" "jsonb") RETURNS TABLE("brief" "text", "caption" "text", "content_type_id" "uuid", "concept" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_count integer;
  v_index integer;
  v_slide jsonb;
  v_timing text;
  v_visual text;
  v_vo text;
  v_element text;
  v_tagging text;
  v_lines text[] := ARRAY[
    '| Timing | Visual | Scene Visual | Teks | Element Lainnya | Tagging |',
    '| --- | --- | --- | --- | --- | --- |'
  ];
  v_caption text;
  v_reason text;
  v_type uuid;
  v_brief text;
  v_primary text;
  v_secondary text;
  v_accent text;
  v_color text := '';
BEGIN
  IF jsonb_typeof(p_payload->'slides') <> 'array' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_count := jsonb_array_length(p_payload->'slides');
  IF v_count < 2 OR v_count > 10 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_caption := NULLIF(btrim(COALESCE(p_payload->>'caption', '')), '');
  IF v_caption IS NULL OR char_length(v_caption) > 800 OR position('#' IN v_caption) = 0 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_reason := NULLIF(regexp_replace(btrim(COALESCE(p_payload->>'concept', '')), '\s+', ' ', 'g'), '');
  IF v_reason IS NULL OR char_length(v_reason) < 40 OR char_length(v_reason) > 800 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR v_index IN 0 .. v_count - 1 LOOP
    v_slide := p_payload->'slides'->v_index;
    v_timing := regexp_replace(btrim(COALESCE(v_slide->>'timing', '')), '\s+', ' ', 'g');
    v_visual := left(regexp_replace(replace(btrim(COALESCE(v_slide->>'visual', '')), '|', '/'), '\s+', ' ', 'g'), 500);
    v_vo := left(regexp_replace(replace(btrim(COALESCE(v_slide->>'vo', '')), '|', '/'), '\s+', ' ', 'g'), 500);
    v_element := left(regexp_replace(replace(btrim(COALESCE(v_slide->>'element', '')), '|', '/'), '\s+', ' ', 'g'), 500);
    v_tagging := left(regexp_replace(replace(btrim(COALESCE(v_slide->>'tagging', '')), '|', '/'), '\s+', ' ', 'g'), 500);
    IF v_timing IS DISTINCT FROM ('Slide ' || (v_index + 1)::text) OR v_visual = '' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_lines := v_lines || format(
      '| %s |  | %s | %s | %s | %s |',
      v_timing, v_visual, v_vo, v_element, v_tagging
    );
  END LOOP;

  v_primary := lower(btrim(COALESCE(p_payload #>> '{palette,primary}', '')));
  v_secondary := lower(btrim(COALESCE(p_payload #>> '{palette,secondary}', '')));
  v_accent := lower(btrim(COALESCE(p_payload #>> '{palette,accent}', '')));
  IF v_primary ~ '^#[0-9a-f]{6}$'
    AND v_secondary ~ '^#[0-9a-f]{6}$'
    AND v_accent ~ '^#[0-9a-f]{6}$'
  THEN
    v_color := format(
      E'\n\nWarna: primer %s, sekunder %s, aksen %s',
      v_primary, v_secondary, v_accent
    );
  END IF;

  v_brief := array_to_string(v_lines, E'\n') || v_color || E'\n\n'
    || format(
      '<!--synckerja-brief-sequences:%s-->',
      jsonb_build_array(jsonb_build_object(
        'id', gen_random_uuid(),
        'name', 'Carousel',
        'rowCount', v_count
      ))::text
    );

  SELECT ct.id
  INTO v_type
  FROM public.content_types ct
  WHERE COALESCE(ct.is_active, true)
    AND (ct.organization_id = p_organization_id OR ct.organization_id IS NULL)
    AND lower(btrim(ct.name)) = 'carousel'
  ORDER BY (ct.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ct.id
  LIMIT 1;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'carousel_type_missing' USING ERRCODE = 'P0002';
  END IF;

  brief := v_brief;
  caption := v_caption;
  content_type_id := v_type;
  concept := jsonb_build_object(
    'v', 1,
    'postAspect', '4:5',
    'reason', v_reason,
    'locations', '[]'::jsonb,
    'characters', '[]'::jsonb,
    'properties', '[]'::jsonb
  )::text;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_carousel_fields"("p_organization_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_carousel_fields"("p_organization_id" "uuid", "p_payload" "jsonb") IS 'Menyusun brief carousel tanpa kolom voice over. Bila payload punya palet katalog, satu baris Warna ditambahkan di luar tabel.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_carousel_path_allowed"("p_employee_id" "uuid", "p_idea_id" "uuid", "p_pillar_id" "uuid", "p_voice" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.ai_employee_carousel_paths(p_employee_id) path WHERE path.idea_id = p_idea_id AND path.content_pillar_id = p_pillar_id AND coalesce(path.delivery_voice, '') = coalesce(NULLIF(btrim(COALESCE(p_voice, '')), ''), '')); $$;


ALTER FUNCTION "public"."ai_employee_carousel_path_allowed"("p_employee_id" "uuid", "p_idea_id" "uuid", "p_pillar_id" "uuid", "p_voice" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_carousel_paths"("p_employee_id" "uuid") RETURNS TABLE("queue_order" integer, "idea_id" "uuid", "content_pillar_id" "uuid", "pillar_name" "text", "angle_id" "uuid", "development" "text", "prompt_voice" "text", "delivery_voice" "text", "is_repeat" boolean, "previous_title" "text", "previous_caption" "text", "idea_statement" "text", "angle_statement" "text", "master_statement" "text", "territory_statement" "text", "big_thought_statement" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$ DECLARE v_org uuid; BEGIN SELECT employee.organization_id INTO v_org FROM public.employees employee WHERE employee.id = p_employee_id AND COALESCE(employee.is_ai, false); IF v_org IS NULL THEN RETURN; END IF; RETURN QUERY WITH brief AS (SELECT employee_brief.angle_ids, employee_brief.pillar_ids, employee_brief.voice, employee_brief.repeat_voices FROM public.ai_employee_briefs employee_brief WHERE employee_brief.employee_id = p_employee_id AND employee_brief.organization_id = v_org), locked_path AS (SELECT DISTINCT ON (idea.id, pillar.id) idea.id AS idea_id, idea.sort_order, idea.created_at AS idea_created_at, idea.statement AS idea_statement, angle.id AS angle_id, angle.statement AS angle_statement, master.statement AS master_statement, territory.statement AS territory_statement, thought.statement AS big_thought_statement, pillar.id AS content_pillar_id, pillar.name AS pillar_name, left(btrim(review->>'development'), 800) AS development FROM brief JOIN public.thinking_lab_ideas idea ON idea.organization_id = v_org JOIN public.thinking_lab_angles angle ON angle.id = idea.angle_id AND angle.organization_id = idea.organization_id AND angle.id = ANY (brief.angle_ids) AND angle.admission = 'GENERATE_VALID' JOIN public.thinking_lab_territories territory ON territory.id = angle.territory_id AND territory.organization_id = angle.organization_id JOIN public.thinking_big_thoughts thought ON thought.id = territory.big_thought_id AND thought.organization_id = angle.organization_id JOIN public.thinking_master_thoughts master ON master.id = thought.master_thought_id AND master.organization_id = angle.organization_id AND master.workspace = 'thinking_lab' CROSS JOIN LATERAL jsonb_array_elements(COALESCE(idea.development_paths, '[]'::jsonb)) AS path CROSS JOIN LATERAL jsonb_array_elements(COALESCE(path->'reviews', '[]'::jsonb)) AS review JOIN public.content_pillars pillar ON pillar.id = CASE WHEN path->>'contentPillarId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (path->>'contentPillarId')::uuid ELSE NULL END AND pillar.is_active AND (pillar.organization_id = v_org OR pillar.is_default) WHERE cardinality(brief.angle_ids) > 0 AND idea.status = 'locked' AND idea.validation->>'decision' = 'LOLOS' AND path->>'status' = 'RECOMMENDED' AND (path->'format' = 'null'::jsonb OR path->>'format' IS NULL OR path->>'format' = 'carousel') AND review->>'contentPillarId' = path->>'contentPillarId' AND btrim(COALESCE(review->>'development', '')) <> '' AND (cardinality(brief.pillar_ids) = 0 OR pillar.id = ANY (brief.pillar_ids)) ORDER BY idea.id, pillar.id, COALESCE(path->>'savedAt', '') DESC, char_length(btrim(review->>'development')) DESC), usage AS (SELECT locked_path.idea_id, locked_path.content_pillar_id, count(plan.id)::integer AS plan_count, (array_agg(plan.id) FILTER (WHERE plan.delivery_voice IS NULL))[1] AS primary_id FROM locked_path LEFT JOIN public.social_media_plans plan ON plan.organization_id = v_org AND plan.thinking_idea_id = locked_path.idea_id AND plan.content_pillar_id = locked_path.content_pillar_id GROUP BY locked_path.idea_id, locked_path.content_pillar_id), cohort AS (SELECT metric.platform, metric.plan_id, metric.views, metric.likes + metric.comments + metric.shares AS engagement FROM public.content_plan_post_metrics metric JOIN public.social_media_plans plan ON plan.id = metric.plan_id AND plan.organization_id = v_org WHERE metric.organization_id = v_org AND metric.fetched_at >= now() - interval '14 days' AND EXISTS (SELECT 1 FROM public.social_media_scheduled_posts post WHERE post.social_media_plan_id = plan.id AND post.organization_id = v_org AND post.status = 'published' AND post.published_at <= now() - interval '7 days' AND lower(post.platform) = metric.platform)), stats AS (SELECT cohort.platform, count(*)::integer AS cohort_count, percentile_cont(0.5) WITHIN GROUP (ORDER BY cohort.views) AS median_views, percentile_cont(0.5) WITHIN GROUP (ORDER BY cohort.engagement) AS median_engagement FROM cohort GROUP BY cohort.platform), passed AS (SELECT cohort.plan_id FROM cohort JOIN stats ON stats.platform = cohort.platform GROUP BY cohort.plan_id HAVING count(*) >= 1 AND bool_and(stats.cohort_count >= 4 AND cohort.views > stats.median_views AND cohort.engagement > stats.median_engagement)), queued AS (SELECT locked_path.*, false AS is_repeat, NULL::uuid AS primary_id, NULLIF(btrim(COALESCE(brief.voice, '')), '') AS prompt_voice, NULL::text AS delivery_voice FROM locked_path JOIN usage ON usage.idea_id = locked_path.idea_id AND usage.content_pillar_id = locked_path.content_pillar_id CROSS JOIN brief WHERE usage.plan_count = 0 UNION ALL SELECT locked_path.*, true AS is_repeat, usage.primary_id, NULLIF(btrim(COALESCE(brief.repeat_voices[1], '')), '') AS prompt_voice, NULLIF(btrim(COALESCE(brief.repeat_voices[1], '')), '') AS delivery_voice FROM locked_path JOIN usage ON usage.idea_id = locked_path.idea_id AND usage.content_pillar_id = locked_path.content_pillar_id CROSS JOIN brief JOIN passed ON passed.plan_id = usage.primary_id WHERE usage.plan_count = 1 AND usage.primary_id IS NOT NULL AND NULLIF(btrim(COALESCE(brief.repeat_voices[1], '')), '') IS NOT NULL) SELECT row_number() OVER (ORDER BY queued.is_repeat, queued.sort_order, queued.idea_created_at, queued.pillar_name, queued.idea_id, queued.content_pillar_id)::integer AS queue_order, queued.idea_id, queued.content_pillar_id, left(btrim(queued.pillar_name), 80) AS pillar_name, queued.angle_id, queued.development, queued.prompt_voice, queued.delivery_voice, queued.is_repeat, left(btrim(COALESCE(primary_plan.title, '')), 200) AS previous_title, left(btrim(COALESCE(caption.content, '')), 400) AS previous_caption, left(btrim(queued.idea_statement), 500) AS idea_statement, left(btrim(queued.angle_statement), 240) AS angle_statement, left(btrim(queued.master_statement), 240) AS master_statement, left(btrim(COALESCE(queued.territory_statement, '')), 240) AS territory_statement, left(btrim(COALESCE(queued.big_thought_statement, '')), 240) AS big_thought_statement FROM queued LEFT JOIN public.social_media_plans primary_plan ON primary_plan.id = queued.primary_id LEFT JOIN public.brief_captions caption ON caption.social_media_plan_id = primary_plan.id ORDER BY queued.is_repeat, queued.sort_order, queued.idea_created_at, queued.pillar_name, queued.idea_id, queued.content_pillar_id; END; $_$;


ALTER FUNCTION "public"."ai_employee_carousel_paths"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_color_delete"("p_employee_id" "uuid", "p_color_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service uuid;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_saved_catalog(p_employee_id);
  IF p_color_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.digital_asset_brand_colors color
  WHERE color.id = p_color_id
    AND color.organization_id = v_org
    AND color.service_id = v_service;
END;
$$;


ALTER FUNCTION "public"."ai_employee_catalog_color_delete"("p_employee_id" "uuid", "p_color_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_color_save"("p_employee_id" "uuid", "p_color_id" "uuid", "p_brand_name" "text", "p_primary" "text", "p_secondary" "text", "p_accent" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_service uuid;
  v_id uuid;
  v_name text;
  v_primary text := lower(btrim(COALESCE(p_primary, '')));
  v_secondary text := lower(btrim(COALESCE(p_secondary, '')));
  v_accent text := lower(btrim(COALESCE(p_accent, '')));
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_saved_catalog(p_employee_id);
  IF v_primary !~ '^#[0-9a-f]{6}$'
    OR v_secondary !~ '^#[0-9a-f]{6}$'
    OR v_accent !~ '^#[0-9a-f]{6}$'
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_name := NULLIF(left(btrim(COALESCE(p_brand_name, '')), 80), '');
  IF p_color_id IS NULL THEN
    INSERT INTO public.digital_asset_brand_colors (
      organization_id, service_id, brand_name,
      primary_color_hex, secondary_color_hex, accent_color_hex, text_color_hex
    ) VALUES (
      v_org, v_service, v_name, v_primary, v_secondary, v_accent, NULL
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.digital_asset_brand_colors color
    SET brand_name = v_name,
        primary_color_hex = v_primary,
        secondary_color_hex = v_secondary,
        accent_color_hex = v_accent,
        updated_at = now()
    WHERE color.id = p_color_id
      AND color.organization_id = v_org
      AND color.service_id = v_service
    RETURNING color.id INTO v_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;
  UPDATE public.ai_employee_briefs brief
  SET brand_color_id = v_id,
      updated_at = now()
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;
  RETURN v_id;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_catalog_color_save"("p_employee_id" "uuid", "p_color_id" "uuid", "p_brand_name" "text", "p_primary" "text", "p_secondary" "text", "p_accent" "text") OWNER TO "postgres";


