CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_logo_delete"("p_employee_id" "uuid", "p_logo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service uuid;
  v_path text;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_saved_catalog(p_employee_id);
  IF p_logo_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  DELETE FROM public.digital_asset_company_logos logo
  WHERE logo.id = p_logo_id
    AND logo.organization_id = v_org
    AND logo.service_id = v_service
  RETURNING logo.logo_path INTO v_path;
  IF v_path IS NOT NULL THEN
    DELETE FROM storage.objects object
    WHERE object.bucket_id = 'digital-asset-company-logos'
      AND object.name = v_path;
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_catalog_logo_delete"("p_employee_id" "uuid", "p_logo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_logo_save"("p_employee_id" "uuid", "p_logo_id" "uuid", "p_brand_name" "text", "p_storage_path" "text", "p_tagline" "text" DEFAULT NULL::"text", "p_headline_font" "text" DEFAULT NULL::"text", "p_body_font" "text" DEFAULT NULL::"text", "p_website_url" "text" DEFAULT NULL::"text", "p_default_contact" "text" DEFAULT NULL::"text", "p_hashtags" "text"[] DEFAULT NULL::"text"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_service uuid;
  v_id uuid;
  v_name text;
  v_tagline text;
  v_headline text;
  v_body text;
  v_website text;
  v_contact text;
  v_tags text[] := '{}'::text[];
  v_path text := NULLIF(btrim(COALESCE(p_storage_path, '')), '');
  v_old text;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_saved_catalog(p_employee_id);
  v_name := NULLIF(left(btrim(COALESCE(p_brand_name, '')), 80), '');
  v_tagline := NULLIF(left(btrim(COALESCE(p_tagline, '')), 120), '');
  v_headline := NULLIF(left(btrim(COALESCE(p_headline_font, '')), 60), '');
  v_body := NULLIF(left(btrim(COALESCE(p_body_font, '')), 60), '');
  v_website := NULLIF(left(btrim(COALESCE(p_website_url, '')), 200), '');
  v_contact := NULLIF(left(btrim(COALESCE(p_default_contact, '')), 80), '');

  IF v_headline IS NOT NULL AND v_headline NOT IN (
    'Montserrat', 'Poppins', 'Open Sans', 'Lato', 'Roboto', 'Nunito', 'Raleway',
    'Oswald', 'Playfair Display', 'Source Sans 3', 'Inter', 'Merriweather', 'DM Sans', 'Bebas Neue'
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF v_body IS NOT NULL AND v_body NOT IN (
    'Montserrat', 'Poppins', 'Open Sans', 'Lato', 'Roboto', 'Nunito', 'Raleway',
    'Oswald', 'Playfair Display', 'Source Sans 3', 'Inter', 'Merriweather', 'DM Sans', 'Bebas Neue'
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_website IS NOT NULL THEN
    IF v_website ~* '[\s<>"''`]' OR v_website ~* '^(javascript|data):' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF v_website !~* '^https?://' THEN
      IF v_website !~* '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+(/.*)?$' THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
      v_website := 'https://' || v_website;
    ELSIF v_website !~* '^https?://[^\s/$.?#].[^\s]*$' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_website := left(v_website, 200);
  END IF;

  IF v_contact IS NOT NULL THEN
    IF v_contact ~* '[<>"''`]' OR v_contact ~* '^(javascript|data):' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF v_contact !~* '^https?://'
       AND v_contact !~* '^wa\.me/'
       AND v_contact !~* '^[+0-9][+0-9[:space:].()-]{6,78}$' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_hashtags IS NOT NULL THEN
    SELECT COALESCE(array_agg(picked.tag ORDER BY picked.ord), '{}'::text[])
      INTO v_tags
    FROM (
      SELECT normalized.tag, min(normalized.ord) AS ord
      FROM (
        SELECT
          left(
            CASE
              WHEN left(btrim(raw), 1) = '#' THEN btrim(raw)
              ELSE '#' || btrim(raw)
            END,
            48
          ) AS tag,
          ord
        FROM unnest(p_hashtags) WITH ORDINALITY AS item(raw, ord)
        WHERE NULLIF(btrim(raw), '') IS NOT NULL
      ) AS normalized
      WHERE normalized.tag ~ '^#[A-Za-z0-9_]+$'
      GROUP BY normalized.tag
      ORDER BY min(normalized.ord)
      LIMIT 30
    ) AS picked;

    IF cardinality(p_hashtags) > 0 AND cardinality(v_tags) = 0 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_path IS NOT NULL AND v_path !~ (
    '^' || v_org::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(png|jpe?g|webp|gif)$'
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF v_path IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM storage.objects object
    WHERE object.bucket_id = 'digital-asset-company-logos'
      AND object.name = v_path
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_logo_id IS NULL THEN
    IF v_path IS NULL THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.digital_asset_company_logos (
      organization_id, service_id, brand_name, logo_path, tagline, headline_font, body_font,
      website_url, default_contact, hashtags
    ) VALUES (
      v_org, v_service, v_name, v_path, v_tagline, v_headline, v_body,
      v_website, v_contact, v_tags
    )
    RETURNING id INTO v_id;
  ELSE
    SELECT logo.logo_path
    INTO v_old
    FROM public.digital_asset_company_logos logo
    WHERE logo.id = p_logo_id
      AND logo.organization_id = v_org
      AND logo.service_id = v_service;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    UPDATE public.digital_asset_company_logos logo
    SET brand_name = v_name,
        logo_path = COALESCE(v_path, logo.logo_path),
        tagline = v_tagline,
        headline_font = v_headline,
        body_font = v_body,
        website_url = v_website,
        default_contact = v_contact,
        hashtags = CASE WHEN p_hashtags IS NULL THEN logo.hashtags ELSE v_tags END,
        updated_at = now()
    WHERE logo.id = p_logo_id
    RETURNING logo.id INTO v_id;
    IF v_path IS NOT NULL AND v_old IS NOT NULL AND v_old IS DISTINCT FROM v_path THEN
      DELETE FROM storage.objects object
      WHERE object.bucket_id = 'digital-asset-company-logos'
        AND object.name = v_old;
    END IF;
  END IF;

  UPDATE public.ai_employee_briefs brief
  SET company_logo_id = v_id,
      updated_at = now()
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;
  RETURN v_id;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_catalog_logo_save"("p_employee_id" "uuid", "p_logo_id" "uuid", "p_brand_name" "text", "p_storage_path" "text", "p_tagline" "text", "p_headline_font" "text", "p_body_font" "text", "p_website_url" "text", "p_default_contact" "text", "p_hashtags" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_logo_select"("p_employee_id" "uuid", "p_logo_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service uuid;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_saved_catalog(p_employee_id);
  IF p_logo_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.digital_asset_company_logos logo
    WHERE logo.id = p_logo_id
      AND logo.organization_id = v_org
      AND logo.service_id = v_service
      AND NULLIF(btrim(COALESCE(logo.logo_path, '')), '') IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  UPDATE public.ai_employee_briefs brief
  SET company_logo_id = p_logo_id,
      updated_at = now()
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;
END;
$$;


ALTER FUNCTION "public"."ai_employee_catalog_logo_select"("p_employee_id" "uuid", "p_logo_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_catalog_sub_service"("p_organization_id" "uuid", "p_service_id" "uuid", "p_chosen" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_id uuid; BEGIN IF p_organization_id IS NULL OR p_service_id IS NULL THEN RETURN NULL; END IF; SELECT sub.id INTO v_id FROM public.sub_services sub WHERE sub.id = p_chosen AND sub.organization_id = p_organization_id AND sub.service_id = p_service_id AND COALESCE(sub.is_active, true); IF v_id IS NOT NULL THEN RETURN v_id; END IF; SELECT sub.id INTO v_id FROM public.sub_services sub WHERE sub.organization_id = p_organization_id AND sub.service_id = p_service_id AND COALESCE(sub.is_active, true) AND lower(btrim(sub.name)) = 'general content' ORDER BY sub.created_at LIMIT 1; IF v_id IS NOT NULL THEN RETURN v_id; END IF; INSERT INTO public.sub_services (organization_id, service_id, name, is_active) VALUES (p_organization_id, p_service_id, 'General Content', true) RETURNING id INTO v_id; RETURN v_id; END; $$;


ALTER FUNCTION "public"."ai_employee_catalog_sub_service"("p_organization_id" "uuid", "p_service_id" "uuid", "p_chosen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_claim_due_jobs"("p_at" timestamp with time zone DEFAULT "clock_timestamp"(), "p_exclude" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS TABLE("job_id" "uuid", "employee_id" "uuid", "organization_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job_id uuid;
  v_employee uuid;
  v_org uuid;
  v_count integer := 0;
BEGIN
  LOOP
    EXIT WHEN v_count >= 3;
    v_job_id := NULL;
    SELECT job.id
    INTO v_job_id
    FROM public.ai_employee_jobs AS job
    JOIN public.ai_employee_profiles AS profile
      ON profile.employee_id = job.employee_id
     AND profile.organization_id = job.organization_id
    JOIN public.employees AS employee
      ON employee.id = job.employee_id
     AND employee.organization_id = job.organization_id
    WHERE job.status IN ('queued', 'deferred')
      AND job.next_attempt_at <= p_at
      AND profile.is_active
      AND COALESCE(employee.is_ai, false)
      AND COALESCE(profile.performance_status, '') <> 'disabled'
      AND NOT (job.employee_id = ANY (COALESCE(p_exclude, '{}'::uuid[])))
      AND NOT EXISTS (
        SELECT 1
        FROM public.ai_employee_jobs busy
        WHERE busy.employee_id = job.employee_id
          AND busy.status IN ('claimed', 'running')
      )
      AND (
        job.priority = 'urgent'
        OR public.ai_employee_in_work_hours(
          COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta'),
          p_at
        )
      )
    ORDER BY CASE job.priority
        WHEN 'urgent' THEN 1
        WHEN 'high' THEN 2
        WHEN 'medium' THEN 3
        ELSE 4
      END,
      job.created_at,
      job.id
    FOR UPDATE OF job SKIP LOCKED
    LIMIT 1;

    EXIT WHEN v_job_id IS NULL;

    v_employee := NULL;
    v_org := NULL;
    UPDATE public.ai_employee_jobs AS job
    SET status = 'claimed',
        claimed_at = p_at,
        claim_token = gen_random_uuid(),
        run_id = NULL,
        updated_at = clock_timestamp()
    WHERE job.id = v_job_id
      AND job.status IN ('queued', 'deferred')
    RETURNING job.employee_id, job.organization_id
    INTO v_employee, v_org;

    EXIT WHEN v_employee IS NULL;

    job_id := v_job_id;
    employee_id := v_employee;
    organization_id := v_org;
    RETURN NEXT;
    v_count := v_count + 1;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_employee_claim_due_jobs"("p_at" timestamp with time zone, "p_exclude" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_claim_due_routines"() RETURNS TABLE("routine_id" "uuid", "employee_id" "uuid", "organization_id" "uuid", "action_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  FOR v_id IN
    SELECT routine.id
    FROM public.ai_employee_routines AS routine
    JOIN public.ai_employee_profiles AS profile
      ON profile.employee_id = routine.employee_id
     AND profile.organization_id = routine.organization_id
    JOIN public.employees AS employee
      ON employee.id = routine.employee_id
     AND employee.organization_id = routine.organization_id
    WHERE routine.is_active
      AND profile.is_active
      AND COALESCE(employee.is_ai, false)
      AND routine.action_code IN ('work_report.daily', 'work_report.weekly', 'work_report.monthly')
      AND COALESCE(profile.performance_status, '') <> 'disabled'
      AND routine.next_run_at IS NOT NULL
      AND routine.next_run_at <= clock_timestamp()
    ORDER BY routine.next_run_at, routine.id
    FOR UPDATE OF routine SKIP LOCKED
    LIMIT 5
  LOOP
    RETURN QUERY
    UPDATE public.ai_employee_routines AS routine
    SET next_run_at = public.ai_employee_next_report_at(
      routine.employee_id,
      routine.organization_id,
      routine.action_code,
      routine.cadence,
      routine.weekday,
      routine.weekdays,
      routine.time_local,
      COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta'),
      clock_timestamp()
    )
    FROM public.ai_employee_profiles AS profile
    WHERE routine.id = v_id
      AND profile.employee_id = routine.employee_id
      AND profile.organization_id = routine.organization_id
      AND routine.next_run_at <= clock_timestamp()
    RETURNING routine.id, routine.employee_id, routine.organization_id, routine.action_code;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_employee_claim_due_routines"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_claim_due_routines"() IS 'Mengunci laporan yang jatuh tempo dan memajukan next_run_at dengan prioritas saudara.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_claim_due_schedules"() RETURNS TABLE("schedule_id" "uuid", "employee_id" "uuid", "organization_id" "uuid", "sop_code" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  FOR v_id IN
    SELECT schedule.id
    FROM public.ai_employee_schedules AS schedule
    JOIN public.ai_employee_profiles AS profile
      ON profile.employee_id = schedule.employee_id
     AND profile.organization_id = schedule.organization_id
    JOIN public.employees AS employee
      ON employee.id = schedule.employee_id
     AND employee.organization_id = schedule.organization_id
    WHERE schedule.is_active
      AND schedule.cadence = 'days'
      AND profile.is_active
      AND COALESCE(employee.is_ai, false)
      AND schedule.sop_code IN ('SOP1', 'SOP4')
      AND COALESCE(profile.performance_status, '') <> 'disabled'
      AND schedule.next_run_at IS NOT NULL
      AND schedule.next_run_at <= clock_timestamp()
    ORDER BY schedule.next_run_at, schedule.id
    FOR UPDATE OF schedule SKIP LOCKED
    LIMIT 5
  LOOP
    RETURN QUERY
    UPDATE public.ai_employee_schedules AS schedule
    SET next_run_at = CASE schedule.sop_code
          WHEN 'SOP4' THEN public.ai_employee_next_story_at(
            schedule.weekdays,
            schedule.start_times,
            schedule.start_local,
            COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta'),
            clock_timestamp()
          )
          ELSE public.ai_employee_next_content_at(
            schedule.employee_id,
            schedule.organization_id,
            schedule.cadence,
            schedule.weekday,
            schedule.weekdays,
            schedule.start_local,
            COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta'),
            clock_timestamp()
          )
        END,
        last_claimed_at = clock_timestamp()
    FROM public.ai_employee_profiles AS profile
    WHERE schedule.id = v_id
      AND profile.employee_id = schedule.employee_id
      AND profile.organization_id = schedule.organization_id
      AND schedule.next_run_at <= clock_timestamp()
    RETURNING schedule.id, schedule.employee_id, schedule.organization_id, schedule.sop_code;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_employee_claim_due_schedules"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_claim_due_schedules"() IS 'Locks due SOP1 or SOP4 day schedules and advances next_run_at (content_at vs story_at).';



CREATE OR REPLACE FUNCTION "public"."ai_employee_content_schedules_retarget"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text;
  v_row record;
BEGIN
  SELECT COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta')
  INTO v_zone
  FROM public.ai_employee_profiles profile
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = p_organization_id;

  v_zone := COALESCE(v_zone, 'Asia/Jakarta');

  FOR v_row IN
    SELECT schedule.id, schedule.cadence, schedule.weekday, schedule.weekdays, schedule.start_local
    FROM public.ai_employee_schedules schedule
    WHERE schedule.employee_id = p_employee_id
      AND schedule.organization_id = p_organization_id
      AND schedule.sop_code = 'SOP1'
  LOOP
    UPDATE public.ai_employee_schedules schedule
    SET next_run_at = public.ai_employee_next_content_at(
      p_employee_id,
      p_organization_id,
      v_row.cadence,
      v_row.weekday,
      v_row.weekdays,
      v_row.start_local,
      v_zone,
      clock_timestamp()
    )
    WHERE schedule.id = v_row.id
      AND schedule.next_run_at IS DISTINCT FROM public.ai_employee_next_content_at(
        p_employee_id,
        p_organization_id,
        v_row.cadence,
        v_row.weekday,
        v_row.weekdays,
        v_row.start_local,
        v_zone,
        clock_timestamp()
      );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_employee_content_schedules_retarget"("p_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_context"("p_employee_id" "uuid", "p_run_id" "uuid", "p_scope" "text", "p_params" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_from date;
  v_to date;
  v_rows jsonb;
  v_count integer;
  v_ads jsonb := '[]'::jsonb;
BEGIN
  IF p_scope NOT IN ('plans', 'calendar', 'catalog', 'pillars', 'thinking', 'feedback', 'tasks', 'brief', 'performance', 'product', 'carousel_paths', 'story_brief') THEN
    RAISE EXCEPTION 'scope_forbidden' USING ERRCODE = '42501';
  END IF;

  v_org := public.ai_employee_require_run(p_employee_id, p_run_id);
  v_from := COALESCE((NULLIF(p_params->>'from', ''))::date, (timezone('Asia/Jakarta', now()))::date);
  v_to := COALESCE((NULLIF(p_params->>'to', ''))::date, v_from + 7);
  IF p_scope = 'performance' AND NULLIF(p_params->>'from', '') IS NULL THEN
    v_to := (timezone('Asia/Jakarta', now()))::date;
    v_from := v_to - 27;
  END IF;

  IF p_scope = 'plans' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT p.id, p.title, p.brief, p.post_date, p.production_status,
             p.content_pillar_id, p.service_id, p.approved, p.production_approved
      FROM public.social_media_plans p
      WHERE p.organization_id = v_org
        AND p.author_employee_id = p_employee_id
        AND (
          NULLIF(p_params->>'from', '') IS NULL
          OR (timezone('Asia/Jakarta', p.post_date))::date BETWEEN v_from AND v_to
        )
      ORDER BY p.post_date DESC NULLS LAST
      LIMIT 100
    ) x;
  ELSIF p_scope = 'calendar' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT p.id,
             left(btrim(COALESCE(p.title, '')), 200) AS title,
             (timezone('Asia/Jakarta', p.post_date))::date AS post_date,
             p.content_pillar_id,
             left(btrim(COALESCE(pillar.name, '')), 80) AS pillar_name,
             p.service_id,
             left(btrim(COALESCE(svc.name, '')), 80) AS service_name,
             left(btrim(COALESCE(author.full_name, '')), 80) AS author_name,
             left(btrim(COALESCE(pic.full_name, '')), 80) AS pic_name
      FROM public.social_media_plans p
      LEFT JOIN public.content_pillars pillar ON pillar.id = p.content_pillar_id
      LEFT JOIN public.services svc
        ON svc.id = p.service_id
       AND svc.organization_id = p.organization_id
      LEFT JOIN public.employees author
        ON author.id = p.author_employee_id
       AND author.organization_id = p.organization_id
      LEFT JOIN public.employees pic
        ON pic.id = p.pic_id
       AND pic.organization_id = p.organization_id
      WHERE p.organization_id = v_org
        AND (timezone('Asia/Jakarta', p.post_date))::date BETWEEN v_from AND v_to
      ORDER BY p.post_date, p.id
      LIMIT 100
    ) x;
  ELSIF p_scope = 'catalog' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT s.id, s.name
      FROM public.services s
      WHERE s.organization_id = v_org
        AND s.is_active
      ORDER BY s.name
      LIMIT 100
    ) x;
  ELSIF p_scope = 'pillars' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT c.id, c.name
      FROM public.content_pillars c
      WHERE c.is_active
        AND (c.organization_id = v_org OR c.is_default)
      ORDER BY c.name
      LIMIT 100
    ) x;
  ELSIF p_scope = 'thinking' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT idea.id AS idea_id,
             angle.id AS angle_id,
             left(btrim(idea.statement), 500) AS idea_statement,
             left(btrim(master.statement), 500) AS master_statement,
             NULLIF(left(btrim(COALESCE(master.canonical_semantic->>'subject', '')), 200), '') AS master_subject,
             left(btrim(thought.statement), 500) AS big_thought_statement,
             left(btrim(territory.statement), 500) AS territory_statement,
             left(btrim(angle.statement), 500) AS angle_statement,
             EXISTS (
               SELECT 1 FROM public.social_media_plans plan
               WHERE plan.organization_id = idea.organization_id
                 AND plan.thinking_idea_id = idea.id
             ) AS used,
             COALESCE((
               SELECT jsonb_agg(jsonb_build_object('id', pillar.id, 'name', left(btrim(pillar.name), 80)) ORDER BY pillar.name)
               FROM (
                 SELECT pillar.id, pillar.name
                 FROM public.content_pillars pillar
                 WHERE pillar.is_active
                   AND (pillar.organization_id = v_org OR pillar.is_default)
                 ORDER BY pillar.name
                 LIMIT 20
               ) pillar
             ), '[]'::jsonb) AS pillars,
             COALESCE((
               SELECT jsonb_agg(jsonb_build_object(
                 'id', ex.id,
                 'pillar_name', left(btrim(COALESCE(ex.pillar_name, '')), 80),
                 'title', left(btrim(COALESCE(ex.script->>'title', '')), 120),
                 'passed', ex.admission = 'GENERATE_VALID'
               ) ORDER BY ex.updated_at DESC)
               FROM (
                 SELECT ex_inner.*
                 FROM public.thinking_lab_executions ex_inner
                 WHERE ex_inner.organization_id = v_org
                   AND ex_inner.idea_id = idea.id
                   AND ex_inner.creative_idea_id IS NULL
                 ORDER BY ex_inner.updated_at DESC
                 LIMIT 5
               ) ex
             ), '[]'::jsonb) AS executions
      FROM public.thinking_lab_ideas idea
      JOIN public.thinking_lab_angles angle
        ON angle.id = idea.angle_id
       AND angle.organization_id = idea.organization_id
      JOIN public.thinking_lab_territories territory
        ON territory.id = angle.territory_id
       AND territory.organization_id = idea.organization_id
      JOIN public.thinking_big_thoughts thought
        ON thought.id = territory.big_thought_id
       AND thought.organization_id = idea.organization_id
      JOIN public.thinking_master_thoughts master
        ON master.id = thought.master_thought_id
       AND master.organization_id = idea.organization_id
       AND master.workspace = 'thinking_lab'
      WHERE idea.organization_id = v_org
        AND idea.status = 'locked'
        AND idea.validation->>'decision' = 'LOLOS'
      ORDER BY used ASC, idea.updated_at DESC, idea.id DESC
      LIMIT 8
    ) x;
  ELSIF p_scope = 'feedback' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT f.id, f.object_type, f.object_id, f.reason, f.expires_at
      FROM public.ai_employee_feedback f
      WHERE f.employee_id = p_employee_id
        AND f.organization_id = v_org
        AND f.dismissed_at IS NULL
        AND f.expires_at > now()
      ORDER BY f.created_at DESC
      LIMIT 10
    ) x;
  ELSIF p_scope = 'brief' THEN
    SELECT jsonb_build_array(public.ai_employee_brief_payload(p_employee_id)) INTO v_rows;
  ELSIF p_scope = 'performance' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT 'content' AS kind,
             pillar.id AS pillar_id,
             left(btrim(pillar.name), 80) AS pillar_name,
             count(*)::integer AS plan_count,
             v_from AS window_start,
             v_to AS window_end
      FROM public.social_media_plans plan
      JOIN public.content_pillars pillar ON pillar.id = plan.content_pillar_id
      WHERE plan.organization_id = v_org
        AND (timezone('Asia/Jakarta', plan.post_date))::date BETWEEN v_from AND v_to
      GROUP BY pillar.id, pillar.name
      ORDER BY count(*) DESC, pillar.name
      LIMIT 3
    ) x;
    IF to_regclass('public.organization_google_ads_accounts') IS NOT NULL THEN
      EXECUTE 'SELECT count(*)::integer FROM public.organization_google_ads_accounts WHERE organization_id = $1'
        INTO v_count USING v_org;
      v_ads := v_ads || jsonb_build_array(jsonb_build_object('kind', 'ads', 'platform', 'google', 'connected_accounts', v_count, 'spend', NULL));
    END IF;
    IF to_regclass('public.organization_meta_ads_accounts') IS NOT NULL THEN
      EXECUTE 'SELECT count(*)::integer FROM public.organization_meta_ads_accounts WHERE organization_id = $1'
        INTO v_count USING v_org;
      v_ads := v_ads || jsonb_build_array(jsonb_build_object('kind', 'ads', 'platform', 'meta', 'connected_accounts', v_count, 'spend', NULL));
    END IF;
    IF to_regclass('public.organization_tiktok_ads_accounts') IS NOT NULL THEN
      EXECUTE 'SELECT count(*)::integer FROM public.organization_tiktok_ads_accounts WHERE organization_id = $1'
        INTO v_count USING v_org;
      v_ads := v_ads || jsonb_build_array(jsonb_build_object('kind', 'ads', 'platform', 'tiktok', 'connected_accounts', v_count, 'spend', NULL));
    END IF;
    v_rows := COALESCE(v_rows, '[]'::jsonb) || v_ads;
  ELSIF p_scope = 'product' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.ai_employee_permissions perm
      WHERE perm.employee_id = p_employee_id
        AND perm.organization_id = v_org
        AND perm.action_code = 'product.knowledge.list'
    ) THEN
      RAISE EXCEPTION 'scope_forbidden' USING ERRCODE = '42501';
    END IF;
    SELECT COALESCE(jsonb_agg((to_jsonb(x) - 'sort_selected' - 'sort_unused' - 'sort_updated') ORDER BY x.sort_selected DESC, x.sort_unused DESC, x.sort_updated DESC, x.id), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT knowledge.id,
             left(btrim(COALESCE(svc.name, '')), 80) AS service_name,
             left(btrim(COALESCE(sub.name, '')), 80) AS sub_service_name,
             left(btrim(knowledge.feature_name), 120) AS feature_name,
             left(btrim(knowledge.feature_description), 400) AS feature_description,
             left(btrim(COALESCE(knowledge.solusi, '')), 400) AS solusi,
             left(btrim(COALESCE(public.ai_employee_product_clip(knowledge.competitive_advantage, 400), '')), 400) AS competitive_advantage,
             left(btrim(COALESCE(public.ai_employee_product_clip(knowledge.target_audience, 240), '')), 240) AS target_audience,
             left(array_to_string(ARRAY(
               SELECT left(btrim(item), 80)
               FROM unnest(COALESCE(knowledge.problems_solved, '{}'::text[])) AS item
               WHERE btrim(item) <> ''
               LIMIT 4
             ), '; '), 320) AS problems_solved,
             left(btrim(knowledge.impact), 240) AS impact,
             left(btrim(COALESCE(knowledge.wants, '')), 240) AS wants,
             left(btrim(COALESCE(knowledge.needs, '')), 240) AS needs,
             left(btrim(COALESCE(knowledge.hidden_needs, '')), 240) AS hidden_needs,
             left(btrim(COALESCE(knowledge.false_belief, '')), 240) AS false_belief,
             left(btrim(COALESCE(knowledge.false_belief_impact, '')), 240) AS false_belief_impact,
             left(btrim(COALESCE(knowledge.what_makes_them_stop, '')), 240) AS what_makes_them_stop,
             (knowledge.id = ANY (COALESCE(brief.product_knowledge_ids, '{}'))) AS selected,
             NOT EXISTS (
               SELECT 1 FROM public.social_media_plans plan
               WHERE plan.organization_id = knowledge.organization_id
                 AND plan.product_knowledge_id = knowledge.id
             ) AS unused,
             (knowledge.id = ANY (COALESCE(brief.product_knowledge_ids, '{}'))) AS sort_selected,
             NOT EXISTS (
               SELECT 1 FROM public.social_media_plans plan
               WHERE plan.organization_id = knowledge.organization_id
                 AND plan.product_knowledge_id = knowledge.id
             ) AS sort_unused,
             knowledge.updated_at AS sort_updated
      FROM public.product_knowledge knowledge
      LEFT JOIN public.ai_employee_briefs brief
        ON brief.employee_id = p_employee_id
       AND brief.organization_id = v_org
      LEFT JOIN public.services svc
        ON svc.id = knowledge.service_id
       AND svc.organization_id = knowledge.organization_id
      LEFT JOIN public.sub_services sub
        ON sub.id = knowledge.sub_service_id
       AND sub.organization_id = knowledge.organization_id
      WHERE knowledge.organization_id = v_org
        AND knowledge.service_id = ANY (COALESCE(brief.service_ids, '{}'))
        AND (
          COALESCE(cardinality(brief.product_knowledge_ids), 0) = 0
          OR knowledge.id = ANY (brief.product_knowledge_ids)
        )
      ORDER BY
        (knowledge.id = ANY (COALESCE(brief.product_knowledge_ids, '{}'))) DESC,
        (
          NOT EXISTS (
            SELECT 1 FROM public.social_media_plans plan
            WHERE plan.organization_id = knowledge.organization_id
              AND plan.product_knowledge_id = knowledge.id
          )
        ) DESC,
        knowledge.updated_at DESC,
        knowledge.id
      LIMIT 30
    ) x;
  ELSIF p_scope = 'carousel_paths' THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(path) ORDER BY path.queue_order), '[]'::jsonb)
    INTO v_rows
    FROM public.ai_employee_carousel_paths(p_employee_id) path;
  ELSIF p_scope = 'story_brief' THEN
    SELECT jsonb_build_array(public.ai_employee_story_brief_payload(p_employee_id)) INTO v_rows;
  ELSE
    SELECT COALESCE(jsonb_agg(to_jsonb(x)), '[]'::jsonb)
    INTO v_rows
    FROM (
      SELECT t.id, t.title, t.status, t.due_date, t.priority, t.ai_revision_count,
        COALESCE((
          SELECT jsonb_agg(
            jsonb_build_object(
              'id', s.id,
              'title', s.title,
              'order', s."order",
              'is_completed', s.is_completed
            )
            ORDER BY s."order"
          )
          FROM public.task_steps s
          WHERE s.task_id = t.id
        ), '[]'::jsonb) AS steps
      FROM public.daily_tasks t
      WHERE t.organization_id = v_org
        AND (
          t.requested_ai_employee_id = p_employee_id
          OR EXISTS (
            SELECT 1 FROM public.daily_tasks_assigned a
            WHERE a.daily_task_id = t.id
              AND a.employee_id = p_employee_id
          )
        )
      ORDER BY t.created_at DESC
      LIMIT 100
    ) x;
  END IF;

  RETURN jsonb_build_object(
    'organization_id', v_org,
    'scope', p_scope,
    'rows', COALESCE(v_rows, '[]'::jsonb)
  );
END;
$_$;


ALTER FUNCTION "public"."ai_employee_context"("p_employee_id" "uuid", "p_run_id" "uuid", "p_scope" "text", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_dispatch"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url text;
  v_secret text;
  v_row record;
  v_count integer := 0;
  v_busy uuid[] := '{}'::uuid[];
  v_mode text;
BEGIN
  PERFORM public.ai_employee_requeue_stuck_jobs();
  PERFORM public.ai_employee_notify_missed_sop1();

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    RETURN 0;
  END IF;

  BEGIN
    SELECT decrypted_secret INTO v_url
    FROM vault.decrypted_secrets
    WHERE name = 'ai_employee_project_url'
    LIMIT 1;

    SELECT decrypted_secret INTO v_secret
    FROM vault.decrypted_secrets
    WHERE name = 'ai_employee_internal_secret'
    LIMIT 1;
  EXCEPTION
    WHEN undefined_table OR invalid_schema_name THEN
      RETURN 0;
  END;

  IF v_url IS NULL OR btrim(v_url) = '' OR v_secret IS NULL OR btrim(v_secret) = '' THEN
    RAISE LOG 'ai_employee_dispatch: vault secret ai_employee_project_url or ai_employee_internal_secret is missing';
    RETURN 0;
  END IF;

  FOR v_row IN
    SELECT claimed.schedule_id, claimed.employee_id, claimed.sop_code
    FROM public.ai_employee_claim_due_schedules() AS claimed
  LOOP
    v_mode := lower(btrim(COALESCE(v_row.sop_code, 'SOP1')));
    IF v_mode NOT IN ('sop1', 'sop4') THEN
      v_mode := 'sop1';
    END IF;
    v_count := v_count + 1;
    v_busy := v_busy || v_row.employee_id;
    PERFORM net.http_post(
      url := rtrim(v_url, '/') || '/functions/v1/ai-employee-run',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-synckerja-internal-secret', v_secret
      ),
      body := jsonb_build_object(
        'employee_id', v_row.employee_id,
        'mode', v_mode,
        'schedule_id', v_row.schedule_id
      ),
      timeout_milliseconds := 120000
    );
  END LOOP;

  FOR v_row IN
    SELECT claimed.job_id, claimed.employee_id
    FROM public.ai_employee_claim_due_jobs(clock_timestamp(), v_busy) AS claimed
  LOOP
    v_count := v_count + 1;
    PERFORM net.http_post(
      url := rtrim(v_url, '/') || '/functions/v1/ai-employee-run',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-synckerja-internal-secret', v_secret
      ),
      body := jsonb_build_object(
        'employee_id', v_row.employee_id,
        'mode', 'job',
        'job_id', v_row.job_id
      ),
      timeout_milliseconds := 120000
    );
  END LOOP;

  FOR v_row IN
    SELECT claimed.routine_id, claimed.employee_id
    FROM public.ai_employee_claim_due_routines() AS claimed
  LOOP
    v_count := v_count + 1;
    PERFORM net.http_post(
      url := rtrim(v_url, '/') || '/functions/v1/ai-employee-routine',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-synckerja-internal-secret', v_secret
      ),
      body := jsonb_build_object(
        'employee_id', v_row.employee_id,
        'routine_id', v_row.routine_id
      ),
      timeout_milliseconds := 60000
    );
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."ai_employee_dispatch"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_dispatch"() IS 'Dispatches due SOP1/SOP4 schedules (mode from sop_code), jobs, and routines.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_idea_chain"("p_organization_id" "uuid", "p_idea_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'idea', jsonb_build_object(
      'id', idea.id,
      'code', left(COALESCE(btrim(idea.code), ''), 16),
      'statement', left(COALESCE(btrim(idea.statement), ''), 400)
    ),
    'angle', CASE WHEN angle.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', angle.id,
      'code', left(COALESCE(btrim(angle.code), ''), 16),
      'statement', left(COALESCE(btrim(angle.statement), ''), 400)
    ) END,
    'territory', CASE WHEN territory.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', territory.id,
      'code', left(COALESCE(btrim(territory.code), ''), 16),
      'statement', left(COALESCE(btrim(territory.statement), ''), 400)
    ) END,
    'big_thought', CASE WHEN thought.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', thought.id,
      'code', left(COALESCE(btrim(thought.code), ''), 16),
      'statement', left(COALESCE(btrim(thought.statement), ''), 400)
    ) END,
    'master', CASE WHEN master.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', master.id,
      'statement', left(COALESCE(btrim(master.statement), ''), 400)
    ) END
  )
  FROM public.thinking_lab_ideas idea
  LEFT JOIN public.thinking_lab_angles angle
    ON angle.id = idea.angle_id AND angle.organization_id = idea.organization_id
  LEFT JOIN public.thinking_lab_territories territory
    ON territory.id = angle.territory_id AND territory.organization_id = idea.organization_id
  LEFT JOIN public.thinking_big_thoughts thought
    ON thought.id = territory.big_thought_id AND thought.organization_id = idea.organization_id
  LEFT JOIN public.thinking_master_thoughts master
    ON master.id = thought.master_thought_id AND master.organization_id = idea.organization_id
  WHERE idea.id = p_idea_id
    AND idea.organization_id = p_organization_id
$$;


ALTER FUNCTION "public"."ai_employee_idea_chain"("p_organization_id" "uuid", "p_idea_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_in_work_hours"("p_time_zone" "text", "p_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
BEGIN
  IF p_at IS NULL THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;
  v_local := timezone(v_zone, p_at);
  RETURN EXTRACT(ISODOW FROM v_local) BETWEEN 1 AND 5
    AND v_local::time >= time '08:00'
    AND v_local::time < time '17:00';
END;
$$;


ALTER FUNCTION "public"."ai_employee_in_work_hours"("p_time_zone" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_install_content_plan"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sop uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = p_employee_id
      AND e.organization_id = p_organization_id
      AND COALESCE(e.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'karyawan AI tidak ditemukan' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.ai_employee_profiles (
    employee_id, organization_id, job_title, time_zone, is_active, performance_status
  ) VALUES (
    p_employee_id, p_organization_id, 'Content Planner', 'Asia/Jakarta', true, 'on_track'
  )
  ON CONFLICT (employee_id) DO NOTHING;

  INSERT INTO public.ai_employee_sops (
    employee_id, organization_id, code, version, is_current, title
  )
  SELECT p_employee_id, p_organization_id, 'SOP1', 1, true, 'Content Plan Carousel'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.ai_employee_sops s
    WHERE s.employee_id = p_employee_id AND s.code = 'SOP1' AND s.is_current
  );

  SELECT s.id INTO v_sop
  FROM public.ai_employee_sops s
  WHERE s.employee_id = p_employee_id AND s.code = 'SOP1' AND s.is_current
  LIMIT 1;

  IF v_sop IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.ai_employee_sop_steps step WHERE step.sop_id = v_sop
  ) THEN
    INSERT INTO public.ai_employee_sop_steps (sop_id, step_no, instruction, may_call_model)
    VALUES
      (v_sop, 1, 'Tanpa model, baca kalender, plan yang sudah ada, katalog aktif, content pillar organisasi, rantai Thinking Lab yang sudah dikonfirmasi manusia, dan sebaran pillar karyawan ini.', false),
      (v_sop, 2, 'Tanpa model, hitung hari yang belum punya plan dan pangsa tiap pillar. Hasil hitungan masuk log run.', false),
      (v_sop, 3, 'Bila jendela sudah penuh dan tidak ada pillar yang melewati 40%, berhenti. Log run berstatus selesai tanpa memanggil model.', false),
      (v_sop, 4, 'Bila ada celah, pilih pillar yang penambahannya tidak membuat pangsa melewati 40%. Panggil model di dalam batas harian. Konteks prompt: SOP ini, pillar yang dipilih, katalog, rantai Thinking Lab, dan catatan penolakan yang masih berlaku.', true),
      (v_sop, 5, 'Simpan draf plan. Satu plan punya judul, tanggal, brief, dan content pillar. Jumlah plan mengikuti jadwal harian.', false),
      (v_sop, 6, 'Untuk plan yang lahir dari Thinking Lab, jalankan pemeriksaan eksekusi. Yang gagal tidak diserahkan. Perbaiki sekali, lalu cek ulang.', true),
      (v_sop, 7, 'Set status produksi need review. Jangan set approved atau jadwal tayang.', false),
      (v_sop, 8, 'Tulis log run: waktu mulai, waktu selesai, jumlah plan baru, jumlah panggilan model, dan daftar id plan.', false);
  END IF;

  INSERT INTO public.ai_employee_schedules (
    employee_id, organization_id, sop_code, weekday, start_local, due_local, is_active, cadence, weekdays, plan_count, start_times
  )
  SELECT p_employee_id, p_organization_id, 'SOP1', NULL, TIME '09:00', TIME '09:00', false, 'days',
    ARRAY[1, 2, 3, 4, 5, 6, 7]::smallint[], 1, ARRAY[TIME '09:00']
  WHERE NOT EXISTS (
    SELECT 1 FROM public.ai_employee_schedules s
    WHERE s.employee_id = p_employee_id AND s.organization_id = p_organization_id
      AND s.sop_code = 'SOP1' AND s.cadence = 'days'
  );

  INSERT INTO public.ai_employee_permissions (employee_id, organization_id, action_code)
  SELECT p_employee_id, p_organization_id, allowed.action_code
  FROM (
    VALUES
      ('content.plans.list'), ('product.knowledge.list'), ('content.calendar.list'), ('content.catalog.list'),
      ('thinking.ideas.list'), ('thinking.chain.read'), ('okr.cycles.list'), ('okr.objectives.list'),
      ('okr.departments.list'), ('tasks.list'), ('tasks.steps.list'), ('content.plans.create'),
      ('content.plans.update'), ('content.briefs.create'), ('thinking.plan.save'), ('thinking.plan.direct'),
      ('thinking.execution.check'), ('tasks.update'), ('tasks.steps.create'), ('tasks.steps.update'),
      ('tasks.substeps.create'), ('tasks.completion.request')
  ) AS allowed(action_code)
  ON CONFLICT (employee_id, action_code) DO NOTHING;

  PERFORM public.ai_employee_install_design_story_shell(p_employee_id, p_organization_id);
END;
$$;


