CREATE OR REPLACE FUNCTION "public"."ai_employee_install_design_story_shell"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sop uuid;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = p_employee_id
      AND e.organization_id = p_organization_id
      AND COALESCE(e.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'karyawan AI tidak ditemukan' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.ai_employee_sops (
    employee_id, organization_id, code, version, is_current, title
  )
  SELECT p_employee_id, p_organization_id, 'SOP4', 1, true, 'Design Story'
  WHERE NOT EXISTS (
