    1,
    ARRAY[TIME '09:00']
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.ai_employee_schedules s
    WHERE s.employee_id = p_employee_id
      AND s.organization_id = p_organization_id
      AND s.sop_code = 'SOP4'
      AND s.cadence = 'days'
