CREATE OR REPLACE FUNCTION "public"."ai_employee_job_bind"("p_employee_id" "uuid", "p_job_id" "uuid", "p_run_id" "uuid", "p_claim_token" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.ai_employee_runs run
    WHERE run.id = p_run_id
      AND run.employee_id = p_employee_id
      AND run.status = 'running'
  ) THEN
    RAISE EXCEPTION 'run_not_running' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ai_employee_jobs
  SET run_id = p_run_id,
      updated_at = clock_timestamp()
  WHERE id = p_job_id
    AND employee_id = p_employee_id
    AND status = 'running'
    AND claim_token = p_claim_token;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'stale_claim' USING ERRCODE = '42501';
  END IF;

  UPDATE public.ai_employee_runs
  SET job_id = p_job_id
  WHERE id = p_run_id
    AND employee_id = p_employee_id
    AND status = 'running';
END;
$$;


ALTER FUNCTION "public"."ai_employee_job_bind"("p_employee_id" "uuid", "p_job_id" "uuid", "p_run_id" "uuid", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_job_finish"("p_employee_id" "uuid", "p_job_id" "uuid", "p_run_id" "uuid", "p_status" "text", "p_reason" "text", "p_plan_id" "uuid", "p_title" "text", "p_brief" "text", "p_claim_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.ai_employee_jobs%ROWTYPE;
  v_org uuid;
  v_zone text;
  v_step uuid;
  v_assigner uuid;
  v_done integer;
  v_rows bigint;
  v_token text;
  v_reason text := left(COALESCE(p_reason, ''), 500);
BEGIN
  IF p_status NOT IN ('done', 'failed', 'rejected', 'deferred') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_job
  FROM public.ai_employee_jobs
  WHERE id = p_job_id
    AND employee_id = p_employee_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_claim_token IS NULL OR v_job.claim_token IS DISTINCT FROM p_claim_token THEN
    RAISE EXCEPTION 'stale_claim' USING ERRCODE = '42501';
  END IF;
  IF v_job.status IN ('done', 'failed', 'rejected') THEN
    RETURN jsonb_build_object('ok', true, 'status', v_job.status);
  END IF;
  IF p_status = 'deferred' AND v_job.status = 'deferred' THEN
    RETURN jsonb_build_object('ok', true, 'status', 'deferred');
  END IF;
  IF v_job.status NOT IN ('claimed', 'running') THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  v_org := v_job.organization_id;

  IF p_status = 'deferred' THEN
    SELECT COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta')
    INTO v_zone
    FROM public.ai_employee_profiles profile
    WHERE profile.employee_id = p_employee_id
      AND profile.organization_id = v_org;
    UPDATE public.ai_employee_jobs
    SET status = 'deferred',
        run_id = COALESCE(p_run_id, run_id),
        reason = COALESCE(NULLIF(v_reason, ''), 'Kuota model habis.'),
        next_attempt_at = public.ai_employee_next_morning(COALESCE(v_zone, 'Asia/Jakarta'), clock_timestamp()),
        claimed_at = NULL,
        updated_at = clock_timestamp()
    WHERE id = v_job.id;
    PERFORM public.ai_employee_notify_reviewer(
      p_employee_id, v_org, 'Job ditunda', 'Kuota model habis. Job dilanjutkan besok pukul 08:00.',
      v_job.daily_task_id, v_job.plan_id
    );
    RETURN jsonb_build_object('ok', true, 'status', 'deferred');
  END IF;

  IF p_status = 'done' AND v_job.source = 'revision' THEN
    SELECT count(*)::integer INTO v_done
    FROM public.ai_employee_jobs job
    WHERE job.plan_id = v_job.plan_id
      AND job.source = 'revision'
      AND job.status = 'done';
    IF COALESCE(v_done, 0) >= 2 THEN
      p_status := 'rejected';
      v_reason := 'Revisi sudah 2 kali. Plan kembali ke reviewer.';
    ELSE
      v_token := gen_random_uuid()::text;
      INSERT INTO public.ai_employee_brief_tickets (plan_id, token)
      VALUES (v_job.plan_id, v_token)
      ON CONFLICT (plan_id) DO UPDATE
        SET token = EXCLUDED.token, created_at = clock_timestamp();
      PERFORM set_config('ai_employee.brief_write', v_token, true);
      UPDATE public.social_media_plans
      SET title = CASE
            WHEN NULLIF(btrim(COALESCE(p_title, '')), '') IS NULL THEN title
            ELSE left(btrim(p_title), 200)
          END,
          brief = CASE
            WHEN NULLIF(btrim(COALESCE(p_brief, '')), '') IS NULL THEN brief
            ELSE left(p_brief, 8000)
          END,
          updated_at = clock_timestamp()
      WHERE id = v_job.plan_id
        AND organization_id = v_org
        AND author_employee_id = p_employee_id
        AND status = 'Request Revision';
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows IS DISTINCT FROM 1 THEN
        PERFORM set_config('ai_employee.brief_write', '', true);
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
      DELETE FROM public.ai_employee_brief_tickets
      WHERE plan_id = v_job.plan_id
        AND token = v_token;
      PERFORM set_config('ai_employee.brief_write', '', true);
    END IF;
  END IF;

  IF p_status = 'rejected' AND v_job.source = 'task' THEN
    INSERT INTO public.task_steps (task_id, title, description, "order")
    VALUES (
      v_job.daily_task_id,
      'Di luar job desk',
      left(COALESCE(NULLIF(v_reason, ''), 'Di luar job desk.'), 2000),
      1
    );
    UPDATE public.daily_tasks
    SET has_steps = true, updated_at = clock_timestamp()
    WHERE id = v_job.daily_task_id;
  END IF;

  IF p_status = 'done' AND v_job.source = 'task' AND p_plan_id IS NOT NULL THEN
    INSERT INTO public.task_steps (task_id, title, description, "order", social_media_plan_id)
    VALUES (
      v_job.daily_task_id,
      left(COALESCE(NULLIF(btrim(p_title), ''), 'Content plan'), 200),
      left(COALESCE(p_brief, ''), 2000),
      1,
      p_plan_id
    )
    RETURNING id INTO v_step;
    UPDATE public.daily_tasks
    SET has_steps = true, updated_at = clock_timestamp()
    WHERE id = v_job.daily_task_id
      AND status IS DISTINCT FROM 'completed';

    SELECT assigned.assigned_by
    INTO v_assigner
    FROM public.daily_tasks_assigned assigned
    WHERE assigned.daily_task_id = v_job.daily_task_id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1;
    IF v_assigner IS NULL THEN
      SELECT profile.reviewer_employee_id
      INTO v_assigner
      FROM public.ai_employee_profiles profile
      WHERE profile.employee_id = p_employee_id
        AND profile.organization_id = v_org;
    END IF;
    IF v_assigner IS NOT NULL THEN
      INSERT INTO public.completion_approvals (
        organization_id, entity_type, daily_task_id, task_step_id,
        assignee_employee_id, assigner_employee_id, status
      ) VALUES (
        v_org, 'step', v_job.daily_task_id, v_step,
        p_employee_id, v_assigner, 'pending'
      );
    END IF;
  END IF;

  IF p_status = 'rejected' THEN
    PERFORM public.ai_employee_notify_reviewer(
      p_employee_id, v_org, 'Job ditolak', COALESCE(NULLIF(v_reason, ''), 'Job ditolak.'),
      v_job.daily_task_id, v_job.plan_id
    );
  ELSIF p_status = 'failed' THEN
    PERFORM public.ai_employee_notify_reviewer(
      p_employee_id, v_org, 'Job gagal', COALESCE(NULLIF(v_reason, ''), 'Job gagal.'),
      v_job.daily_task_id, v_job.plan_id
    );
  END IF;

  UPDATE public.ai_employee_jobs
  SET status = p_status,
      run_id = COALESCE(p_run_id, run_id),
      reason = COALESCE(NULLIF(v_reason, ''), reason),
      finished_at = clock_timestamp(),
      updated_at = clock_timestamp()
  WHERE id = v_job.id;

  RETURN jsonb_build_object('ok', true, 'status', p_status, 'plan_id', COALESCE(p_plan_id, v_job.plan_id));
END;
$$;


ALTER FUNCTION "public"."ai_employee_job_finish"("p_employee_id" "uuid", "p_job_id" "uuid", "p_run_id" "uuid", "p_status" "text", "p_reason" "text", "p_plan_id" "uuid", "p_title" "text", "p_brief" "text", "p_claim_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_job_put"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_source" "text", "p_task_id" "uuid", "p_plan_id" "uuid", "p_priority" "text", "p_status" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.ai_employee_jobs (
    employee_id, organization_id, source, daily_task_id, plan_id,
    priority, status, reason, finished_at
  ) VALUES (
    p_employee_id,
    p_organization_id,
    p_source,
    p_task_id,
    p_plan_id,
    p_priority,
    p_status,
    left(COALESCE(p_reason, ''), 500),
    CASE WHEN p_status IN ('rejected', 'failed', 'done') THEN clock_timestamp() ELSE NULL END
  );
EXCEPTION
  WHEN unique_violation THEN
    IF p_status = 'queued' THEN
      UPDATE public.ai_employee_jobs
      SET reason = left(COALESCE(NULLIF(p_reason, ''), reason), 500),
          updated_at = clock_timestamp()
      WHERE status = 'queued'
        AND organization_id = p_organization_id
        AND (
          (p_source = 'task' AND daily_task_id = p_task_id)
          OR (p_source = 'revision' AND plan_id = p_plan_id)
        );
    END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_job_put"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_source" "text", "p_task_id" "uuid", "p_plan_id" "uuid", "p_priority" "text", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_job_take"("p_employee_id" "uuid", "p_job_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.ai_employee_jobs%ROWTYPE;
  v_task public.daily_tasks%ROWTYPE;
  v_plan public.social_media_plans%ROWTYPE;
  v_done integer := 0;
BEGIN
  UPDATE public.ai_employee_jobs
  SET status = 'running',
      updated_at = clock_timestamp()
  WHERE id = p_job_id
    AND employee_id = p_employee_id
    AND status = 'claimed'
    AND claim_token IS NOT NULL
  RETURNING * INTO v_job;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_job.source = 'task' THEN
    SELECT * INTO v_task FROM public.daily_tasks WHERE id = v_job.daily_task_id;
  ELSE
    SELECT * INTO v_plan FROM public.social_media_plans WHERE id = v_job.plan_id;
    SELECT count(*)::integer INTO v_done
    FROM public.ai_employee_jobs job
    WHERE job.plan_id = v_job.plan_id
      AND job.source = 'revision'
      AND job.status = 'done';
  END IF;

  RETURN jsonb_build_object(
    'id', v_job.id,
    'source', v_job.source,
    'priority', v_job.priority,
    'reason', v_job.reason,
    'claim_token', v_job.claim_token,
    'task_id', v_job.daily_task_id,
    'task_title', COALESCE(v_task.title, ''),
    'task_description', COALESCE(v_task.description, ''),
    'plan_id', v_job.plan_id,
    'plan_title', COALESCE(v_plan.title, ''),
    'plan_brief', COALESCE(v_plan.brief, ''),
    'revision_count', COALESCE(v_plan.revision_count, 0),
    'done_revisions', v_done
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_job_take"("p_employee_id" "uuid", "p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_jobs_on_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_priority text;
  v_ai boolean;
  v_reason text;
BEGIN
  SELECT COALESCE(employee.is_ai, false)
  INTO v_ai
  FROM public.employees employee
  WHERE employee.id = NEW.employee_id
    AND employee.organization_id = NEW.organization_id;

  IF NOT COALESCE(v_ai, false) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ai_employee_profiles profile
    WHERE profile.employee_id = NEW.employee_id
      AND profile.organization_id = NEW.organization_id
  ) THEN
    RETURN NEW;
  END IF;

  SELECT CASE lower(btrim(COALESCE(task.priority, 'medium')))
    WHEN 'urgent' THEN 'urgent'
    WHEN 'high' THEN 'high'
    WHEN 'low' THEN 'low'
    ELSE 'medium'
  END
  INTO v_priority
  FROM public.daily_tasks task
  WHERE task.id = NEW.daily_task_id
    AND task.organization_id = NEW.organization_id;

  v_reason := public.ai_employee_queue_actor_reason(
    NEW.employee_id, NEW.organization_id, NULL, NEW.assigned_by, true
  );
  IF v_reason IS NULL THEN
    PERFORM public.ai_employee_job_put(
      NEW.employee_id, NEW.organization_id, 'task', NEW.daily_task_id, NULL,
      COALESCE(v_priority, 'medium'), 'queued', ''
    );
  ELSE
    PERFORM public.ai_employee_job_put(
      NEW.employee_id, NEW.organization_id, 'task', NEW.daily_task_id, NULL,
      COALESCE(v_priority, 'medium'), 'rejected', v_reason
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_jobs_on_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_jobs_on_plan_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ai boolean;
  v_done integer;
  v_reason text;
  v_actor text;
BEGIN
  IF NEW.status IS DISTINCT FROM 'Request Revision' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;
  IF NEW.author_employee_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(employee.is_ai, false)
  INTO v_ai
  FROM public.employees employee
  WHERE employee.id = NEW.author_employee_id
    AND employee.organization_id = NEW.organization_id;
  IF NOT COALESCE(v_ai, false) THEN
    RETURN NEW;
  END IF;

  v_actor := public.ai_employee_queue_actor_reason(
    NEW.author_employee_id, NEW.organization_id, NULL, NULL, false
  );
  IF v_actor IS NOT NULL THEN
    PERFORM public.ai_employee_job_put(
      NEW.author_employee_id, NEW.organization_id, 'revision', NULL, NEW.id,
      'high', 'rejected', v_actor
    );
    RETURN NEW;
  END IF;

  SELECT count(*)::integer
  INTO v_done
  FROM public.ai_employee_jobs job
  WHERE job.plan_id = NEW.id
    AND job.source = 'revision'
    AND job.status = 'done';

  SELECT left(btrim(feedback.reason), 500)
  INTO v_reason
  FROM public.ai_employee_feedback feedback
  WHERE feedback.object_id = NEW.id
    AND feedback.organization_id = NEW.organization_id
    AND feedback.object_type = 'plan'
    AND feedback.employee_id = NEW.author_employee_id
  ORDER BY feedback.created_at DESC
  LIMIT 1;

  IF COALESCE(v_done, 0) >= 2 OR COALESCE(NEW.revision_count, 0) > 2 THEN
    PERFORM public.ai_employee_job_put(
      NEW.author_employee_id, NEW.organization_id, 'revision', NULL, NEW.id,
      'high', 'rejected', 'Revisi sudah 2 kali. Plan kembali ke reviewer.'
    );
    PERFORM public.ai_employee_notify_reviewer(
      NEW.author_employee_id,
      NEW.organization_id,
      'Revisi plan berhenti',
      'Revisi sudah 2 kali. Plan kembali ke reviewer.',
      NULL,
      NEW.id
    );
  ELSE
    PERFORM public.ai_employee_job_put(
      NEW.author_employee_id, NEW.organization_id, 'revision', NULL, NEW.id,
      'high', 'queued', COALESCE(NULLIF(v_reason, ''), 'Plan ditolak reviewer.')
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_jobs_on_plan_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_jobs_on_task_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_priority text;
  v_ai boolean;
  v_reason text;
BEGIN
  IF NEW.requested_ai_employee_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.requested_ai_employee_id IS NOT DISTINCT FROM OLD.requested_ai_employee_id THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(employee.is_ai, false)
  INTO v_ai
  FROM public.employees employee
  WHERE employee.id = NEW.requested_ai_employee_id
    AND employee.organization_id = NEW.organization_id;
  IF NOT COALESCE(v_ai, false) THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.ai_employee_profiles profile
    WHERE profile.employee_id = NEW.requested_ai_employee_id
      AND profile.organization_id = NEW.organization_id
  ) THEN
    RETURN NEW;
  END IF;

  v_priority := CASE lower(btrim(COALESCE(NEW.priority, 'medium')))
    WHEN 'urgent' THEN 'urgent'
    WHEN 'high' THEN 'high'
    WHEN 'low' THEN 'low'
    ELSE 'medium'
  END;

  v_reason := public.ai_employee_queue_actor_reason(
    NEW.requested_ai_employee_id, NEW.organization_id, NEW.created_by, NULL, true
  );
  IF v_reason IS NULL THEN
    PERFORM public.ai_employee_job_put(
      NEW.requested_ai_employee_id, NEW.organization_id, 'task', NEW.id, NULL,
      v_priority, 'queued', ''
    );
  ELSE
    PERFORM public.ai_employee_job_put(
      NEW.requested_ai_employee_id, NEW.organization_id, 'task', NEW.id, NULL,
      v_priority, 'rejected', v_reason
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_jobs_on_task_request"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_may_assign"("p_actor_employee_id" "uuid", "p_ai_employee_id" "uuid", "p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.employees actor
    JOIN public.user_roles role
      ON role.user_id = actor.user_id
     AND role.organization_id = p_organization_id
    WHERE actor.id = p_actor_employee_id
      AND actor.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) OR EXISTS (
    SELECT 1
    FROM public.ai_employee_profiles profile
    WHERE profile.employee_id = p_ai_employee_id
      AND profile.organization_id = p_organization_id
      AND profile.reviewer_employee_id = p_actor_employee_id
  );
$$;


ALTER FUNCTION "public"."ai_employee_may_assign"("p_actor_employee_id" "uuid", "p_ai_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_next_content_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
  v_day date;
  v_candidate timestamp;
  v_dow integer;
  v_month_end boolean;
  v_offset integer;
  v_weekly smallint;
  v_weekly_active boolean := false;
  v_monthly_active boolean := false;
  v_times time[] := ARRAY[]::time[];
  v_time time;
BEGIN
  IF p_start IS NULL OR p_after IS NULL OR p_cadence NOT IN ('days', 'weekly', 'monthly') THEN
    RETURN NULL;
  END IF;
  IF p_cadence = 'days' AND COALESCE(cardinality(p_weekdays), 0) < 1 THEN
    RETURN NULL;
  END IF;
  IF p_cadence = 'weekly' AND (p_weekday IS NULL OR p_weekday < 1 OR p_weekday > 7) THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;

  SELECT schedule.weekday, schedule.is_active
  INTO v_weekly, v_weekly_active
  FROM public.ai_employee_schedules schedule
  WHERE schedule.employee_id = p_employee_id
    AND schedule.organization_id = p_organization_id
    AND schedule.sop_code = 'SOP1'
    AND schedule.cadence = 'weekly'
  LIMIT 1;

  SELECT schedule.is_active
  INTO v_monthly_active
  FROM public.ai_employee_schedules schedule
  WHERE schedule.employee_id = p_employee_id
    AND schedule.organization_id = p_organization_id
    AND schedule.sop_code = 'SOP1'
    AND schedule.cadence = 'monthly'
  LIMIT 1;

  v_weekly_active := COALESCE(v_weekly_active, false)
    AND v_weekly IS NOT NULL
    AND v_weekly BETWEEN 1 AND 7;
  v_monthly_active := COALESCE(v_monthly_active, false);

  IF p_cadence = 'days' THEN
    SELECT schedule.start_times
    INTO v_times
    FROM public.ai_employee_schedules schedule
    WHERE schedule.employee_id = p_employee_id
      AND schedule.organization_id = p_organization_id
      AND schedule.sop_code = 'SOP1'
      AND schedule.cadence = 'days'
    LIMIT 1;

    IF v_times IS NULL OR cardinality(v_times) = 0 THEN
      v_times := ARRAY[p_start];
    ELSE
      SELECT COALESCE(array_agg(slot ORDER BY slot), ARRAY[]::time[])
      INTO v_times
      FROM unnest(v_times) AS slot
      WHERE slot IS NOT NULL;
      IF v_times IS NULL OR cardinality(v_times) = 0 THEN
        v_times := ARRAY[p_start];
      END IF;
    END IF;
  END IF;

  v_local := timezone(v_zone, p_after);

  FOR v_offset IN 0..400 LOOP
    v_day := v_local::date + v_offset;
    v_dow := EXTRACT(ISODOW FROM v_day)::integer;
    v_month_end := v_day = (date_trunc('month', v_day::timestamp) + interval '1 month' - interval '1 day')::date;

    IF p_cadence = 'monthly' AND v_month_end THEN
      v_candidate := v_day + p_start;
      IF v_candidate > v_local THEN
        RETURN v_candidate AT TIME ZONE v_zone;
      END IF;
    END IF;

    IF p_cadence = 'weekly'
       AND v_dow = p_weekday
       AND NOT (v_month_end AND v_monthly_active) THEN
      v_candidate := v_day + p_start;
      IF v_candidate > v_local THEN
        RETURN v_candidate AT TIME ZONE v_zone;
      END IF;
    END IF;

    IF p_cadence = 'days'
       AND v_dow = ANY (p_weekdays)
       AND NOT (v_weekly_active AND v_dow = v_weekly)
       AND NOT (v_month_end AND v_monthly_active) THEN
      FOREACH v_time IN ARRAY v_times LOOP
        v_candidate := v_day + v_time;
        IF v_candidate > v_local THEN
          RETURN v_candidate AT TIME ZONE v_zone;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_content_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_content_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) IS 'Jam berikutnya untuk content plan. Harian memakai setiap jam di start_times dan melewati slot yang sudah lewat.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_next_morning"("p_time_zone" "text", "p_at" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;
  v_local := timezone(v_zone, COALESCE(p_at, clock_timestamp()));
  RETURN (date_trunc('day', v_local) + interval '1 day' + time '08:00') AT TIME ZONE v_zone;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_morning"("p_time_zone" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_next_report_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_weekly smallint := NULL;
  v_monthly boolean := false;
  v_slot timestamptz;
  v_local timestamp;
  v_send_local timestamp;
  v_work_local timestamp;
  v_work_dow integer;
  v_blocked boolean;
  v_guard integer := 0;
BEGIN
  IF p_cadence = 'days' AND COALESCE(cardinality(p_weekdays), 0) < 1 THEN
    RETURN NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;
  IF p_action_code IS DISTINCT FROM 'work_report.weekly' THEN
    SELECT routine.weekday INTO v_weekly
    FROM public.ai_employee_routines routine
    WHERE routine.employee_id = p_employee_id
      AND routine.organization_id = p_organization_id
      AND routine.action_code = 'work_report.weekly'
      AND routine.is_active;
  END IF;
  IF p_action_code IS DISTINCT FROM 'work_report.monthly' THEN
    SELECT true INTO v_monthly
    FROM public.ai_employee_routines routine
    WHERE routine.employee_id = p_employee_id
      AND routine.organization_id = p_organization_id
      AND routine.action_code = 'work_report.monthly'
      AND routine.is_active;
    v_monthly := COALESCE(v_monthly, false);
  END IF;
  IF p_cadence = 'days' THEN
    IF p_time IS NULL OR p_after IS NULL THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_local := timezone(v_zone, p_after);
    v_send_local := date_trunc('day', v_local) + p_time;
    IF v_send_local <= v_local THEN
      v_send_local := v_send_local + interval '1 day';
    END IF;
    LOOP
      v_work_local := v_send_local - interval '1 day';
      v_work_dow := EXTRACT(ISODOW FROM v_work_local)::integer;
      v_blocked := NOT (v_work_dow = ANY (COALESCE(p_weekdays, '{}'::smallint[])));
      IF v_weekly IS NOT NULL AND v_work_dow = v_weekly THEN
        v_blocked := true;
      END IF;
      IF v_monthly
         AND v_work_local::date = (date_trunc('month', v_work_local) + interval '1 month' - interval '1 day')::date
      THEN
        v_blocked := true;
      END IF;
      EXIT WHEN NOT v_blocked;
      v_send_local := v_send_local + interval '1 day';
      v_guard := v_guard + 1;
      IF v_guard > 370 THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    END LOOP;
    RETURN v_send_local AT TIME ZONE v_zone;
  END IF;
  v_slot := public.ai_employee_next_routine_at(p_cadence, p_weekday, p_time, v_zone, p_after, p_weekdays);
  IF p_cadence = 'monthly' OR (v_weekly IS NULL AND NOT v_monthly) THEN
    RETURN v_slot;
  END IF;
  LOOP
    v_local := timezone(v_zone, v_slot);
    v_blocked := false;
    IF v_monthly AND v_local::date = (date_trunc('month', v_local) + interval '1 month' - interval '1 day')::date THEN
      v_blocked := true;
    END IF;
    IF p_cadence = 'days' AND v_weekly IS NOT NULL AND EXTRACT(ISODOW FROM v_local)::integer = v_weekly THEN
      v_blocked := true;
    END IF;
    EXIT WHEN NOT v_blocked;
    IF p_cadence = 'weekly' THEN
      v_slot := (timezone(v_zone, v_slot) + interval '7 days') AT TIME ZONE v_zone;
    ELSE
      v_slot := public.ai_employee_next_routine_at('days', NULL, p_time, v_zone, v_slot, p_weekdays);
    END IF;
    v_guard := v_guard + 1;
    IF v_guard > 370 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END LOOP;
  RETURN v_slot;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_report_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_report_at"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" smallint, "p_weekdays" smallint[], "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) IS 'Slot berikutnya. Harian dikirim pagi setelah hari kerja yang dipilih. Bulanan aktif menahan tanggal terakhir. Mingguan aktif menahan weekday-nya pada harian.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN public.ai_employee_next_routine_at(
    p_cadence,
    p_weekday,
    p_time,
    p_time_zone,
    p_after,
    NULL::smallint[]
  );
