ALTER FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) IS 'Pembungkus lima argumen. Hari pilihan dikirim lewat fungsi enam argumen.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone, "p_weekdays" smallint[]) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
  v_dow integer;
  v_delta integer;
  v_month timestamp;
  v_candidate timestamp;
  v_guard integer := 0;
  v_days smallint[] := COALESCE(p_weekdays, '{}'::smallint[]);
BEGIN
  IF p_time IS NULL
     OR p_after IS NULL
     OR p_cadence NOT IN ('daily', 'mon_thu', 'days', 'weekly', 'monthly')
     OR (p_cadence = 'weekly' AND (p_weekday IS NULL OR p_weekday < 1 OR p_weekday > 7))
     OR (p_cadence = 'days' AND (cardinality(v_days) < 1 OR p_weekday IS NOT NULL))
     OR (p_cadence IN ('daily', 'mon_thu', 'monthly') AND p_weekday IS NOT NULL)
     OR EXISTS (SELECT 1 FROM unnest(v_days) AS day WHERE day < 1 OR day > 7)
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;

  v_local := timezone(v_zone, p_after);
  IF p_cadence = 'monthly' THEN
    v_month := date_trunc('month', v_local);
    v_candidate := date_trunc('day', v_month + interval '1 month' - interval '1 day') + p_time;
    IF v_candidate <= v_local THEN
      v_month := v_month + interval '1 month';
      v_candidate := date_trunc('day', v_month + interval '1 month' - interval '1 day') + p_time;
    END IF;
  ELSIF p_cadence = 'days' THEN
    v_candidate := date_trunc('day', v_local) + p_time;
    IF v_candidate <= v_local THEN
      v_candidate := v_candidate + interval '1 day';
    END IF;
    WHILE NOT (EXTRACT(ISODOW FROM v_candidate)::integer = ANY (v_days)) LOOP
      v_candidate := v_candidate + interval '1 day';
      v_guard := v_guard + 1;
      IF v_guard > 7 THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    END LOOP;
  ELSIF p_cadence IN ('daily', 'mon_thu') THEN
    v_candidate := date_trunc('day', v_local) + p_time;
    IF v_candidate <= v_local THEN
      v_candidate := v_candidate + interval '1 day';
    END IF;
    IF p_cadence = 'mon_thu' THEN
      WHILE EXTRACT(ISODOW FROM v_candidate)::integer NOT BETWEEN 1 AND 4 LOOP
        v_candidate := v_candidate + interval '1 day';
      END LOOP;
    END IF;
  ELSE
    v_dow := EXTRACT(ISODOW FROM v_local)::integer;
    v_delta := (p_weekday - v_dow + 7) % 7;
    v_candidate := date_trunc('day', v_local) + make_interval(days => v_delta) + p_time;
    IF v_candidate <= v_local THEN
      v_candidate := v_candidate + interval '7 days';
    END IF;
  END IF;

  RETURN v_candidate AT TIME ZONE v_zone;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone, "p_weekdays" smallint[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_routine_at"("p_cadence" "text", "p_weekday" smallint, "p_time" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone, "p_weekdays" smallint[]) IS 'Slot berikutnya. days memakai weekday yang dipilih, weekly satu hari, monthly tanggal terakhir bulan berjalan.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_next_run_at"("p_weekday" smallint, "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone DEFAULT "now"()) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
  v_dow integer;
  v_delta integer;
  v_candidate timestamp;
BEGIN
  IF p_weekday IS NULL OR p_weekday < 1 OR p_weekday > 7 OR p_start IS NULL OR p_after IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;

  v_local := timezone(v_zone, p_after);
  v_dow := EXTRACT(ISODOW FROM v_local)::integer;
  v_delta := (p_weekday - v_dow + 7) % 7;
  v_candidate := date_trunc('day', v_local) + make_interval(days => v_delta) + p_start;
  IF v_candidate <= v_local THEN
    v_candidate := v_candidate + interval '7 days';
  END IF;

  RETURN v_candidate AT TIME ZONE v_zone;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_run_at"("p_weekday" smallint, "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_run_at"("p_weekday" smallint, "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) IS 'Kejadian weekday+start berikutnya yang benar-benar setelah p_after, di zona waktu profil. Zona tidak dikenal jatuh ke Asia/Jakarta.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_next_story_at"("p_weekdays" smallint[], "p_start_times" time without time zone[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_local timestamp;
  v_day date;
  v_candidate timestamp;
  v_dow integer;
  v_offset integer;
  v_times time[] := ARRAY[]::time[];
  v_time time;
BEGIN
  IF p_after IS NULL OR COALESCE(cardinality(p_weekdays), 0) < 1 THEN
    RETURN NULL;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;

  IF p_start_times IS NOT NULL AND cardinality(p_start_times) > 0 THEN
    SELECT COALESCE(array_agg(slot ORDER BY slot), ARRAY[]::time[])
    INTO v_times
    FROM unnest(p_start_times) AS slot
    WHERE slot IS NOT NULL;
  END IF;

  IF v_times IS NULL OR cardinality(v_times) = 0 THEN
    IF p_start IS NULL THEN
      RETURN NULL;
    END IF;
    v_times := ARRAY[p_start];
  END IF;

  v_local := timezone(v_zone, p_after);

  FOR v_offset IN 0..400 LOOP
    v_day := v_local::date + v_offset;
    v_dow := EXTRACT(ISODOW FROM v_day)::integer;
    IF v_dow = ANY (p_weekdays) THEN
      FOREACH v_time IN ARRAY v_times LOOP
        v_candidate := v_day + v_time;
        IF v_candidate > v_local THEN
          RETURN v_candidate AT TIME ZONE v_zone;
        END IF;
      END LOOP;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."ai_employee_next_story_at"("p_weekdays" smallint[], "p_start_times" time without time zone[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_next_story_at"("p_weekdays" smallint[], "p_start_times" time without time zone[], "p_start" time without time zone, "p_time_zone" "text", "p_after" timestamp with time zone) IS 'Next Design Story (SOP4) run: days cadence only, weekdays + start_times, no SOP1 weekly/monthly coupling.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_notify_missed_sop1"("p_at" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_count integer := 0;
BEGIN
  FOR v_row IN
    SELECT schedule.id, schedule.employee_id, schedule.organization_id, schedule.last_claimed_at
    FROM public.ai_employee_schedules AS schedule
    WHERE schedule.sop_code = 'SOP1'
      AND schedule.last_claimed_at IS NOT NULL
      AND schedule.last_claimed_at <= p_at - interval '15 minutes'
      AND (schedule.missed_notified_at IS NULL OR schedule.missed_notified_at < schedule.last_claimed_at)
      AND NOT EXISTS (
        SELECT 1
        FROM public.ai_employee_runs run
        WHERE run.employee_id = schedule.employee_id
          AND run.organization_id = schedule.organization_id
          AND run.sop_code = 'SOP1'
          AND run.started_at >= schedule.last_claimed_at
          AND run.started_at < schedule.last_claimed_at + interval '15 minutes'
      )
    ORDER BY schedule.last_claimed_at, schedule.id
  LOOP
    PERFORM public.ai_employee_notify_reviewer(
      v_row.employee_id,
      v_row.organization_id,
      'SOP1 tidak berjalan',
      'Jadwal SOP1 sudah diklaim, tetapi tidak ada log run dalam 15 menit.',
      NULL,
      NULL
    );
    UPDATE public.ai_employee_schedules
    SET missed_notified_at = p_at
    WHERE id = v_row.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."ai_employee_notify_missed_sop1"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_notify_reviewer"("p_employee_id" "uuid", "p_event_type" "text", "p_title" "text", "p_body" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_user uuid;
BEGIN
  SELECT p.organization_id, reviewer.user_id
  INTO v_org, v_user
  FROM public.ai_employee_profiles p
  LEFT JOIN public.employees reviewer ON reviewer.id = p.reviewer_employee_id
  WHERE p.employee_id = p_employee_id;

  IF v_org IS NULL OR v_user IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.daily_task_notifications (
    user_id, organization_id, title, body, daily_task_id, created_at
  ) VALUES (
    v_user, v_org, p_title, p_body, NULL, now()
  );

  INSERT INTO public.daily_task_completion_push_queue (
    organization_id, recipient_user_id, event_type, entity_type,
    daily_task_id, title, url
  ) VALUES (
    v_org, v_user, p_event_type, 'ai_run',
    NULL, p_title, '/tools/daily-task?view=jobdesc'
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_notify_reviewer"("p_employee_id" "uuid", "p_event_type" "text", "p_title" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_notify_reviewer"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_body" "text", "p_task_id" "uuid", "p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
BEGIN
  SELECT reviewer.user_id
  INTO v_user
  FROM public.ai_employee_profiles profile
  JOIN public.employees reviewer
    ON reviewer.id = profile.reviewer_employee_id
   AND reviewer.organization_id = profile.organization_id
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = p_organization_id;

  IF v_user IS NULL THEN
    RETURN;
  END IF;

  IF p_plan_id IS NOT NULL THEN
    INSERT INTO public.plan_status_change_notifications (
      user_id, social_media_plan_id, organization_id, title, body, change_kind
    ) VALUES (
      v_user,
      p_plan_id,
      p_organization_id,
      left(COALESCE(p_title, ''), 200),
      left(COALESCE(p_body, ''), 500),
      'ai_employee'
    );
  ELSE
    INSERT INTO public.daily_task_notifications (
      user_id, organization_id, title, body, daily_task_id
    ) VALUES (
      v_user,
      p_organization_id,
      left(COALESCE(p_title, ''), 200),
      left(COALESCE(p_body, ''), 500),
      p_task_id
    );
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_notify_reviewer"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_body" "text", "p_task_id" "uuid", "p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_office_catalogs"("p_organization_id" "uuid") RETURNS TABLE("employee_id" "uuid", "catalog_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF p_organization_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_roles role
    WHERE role.user_id = auth.uid()
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT employee.id,
    (
      SELECT service.name
      FROM unnest(brief.service_ids) WITH ORDINALITY AS picked(service_id, ordinal)
      JOIN public.services service
        ON service.id = picked.service_id
       AND service.organization_id = employee.organization_id
      ORDER BY picked.ordinal
      LIMIT 1
    )
  FROM public.employees employee
  LEFT JOIN public.ai_employee_briefs brief
    ON brief.employee_id = employee.id
   AND brief.organization_id = employee.organization_id
  WHERE employee.organization_id = p_organization_id
    AND COALESCE(employee.is_ai, false);
END;
$$;


ALTER FUNCTION "public"."ai_employee_office_catalogs"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_page_brief_save"("p_employee_id" "uuid", "p_brief" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  RETURN public.ai_employee_brief_write(auth.uid(), v_org, p_employee_id, p_brief);
END;
$$;


ALTER FUNCTION "public"."ai_employee_page_brief_save"("p_employee_id" "uuid", "p_brief" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_page_brief_save"("p_employee_id" "uuid", "p_brief" "jsonb") IS 'Owner menyimpan brief lewat ai_employee_brief_write. Aturan katalog, persona, pilar, dan produk tidak disalin ulang.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_page_gate"("p_employee_id" "uuid", "p_write" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org uuid;
  v_ai boolean;
BEGIN
  IF p_employee_id IS NULL OR v_uid IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT employee.organization_id, COALESCE(employee.is_ai, false)
  INTO v_org, v_ai
  FROM public.employees employee
  WHERE employee.id = p_employee_id;

  IF NOT FOUND OR NOT COALESCE(v_ai, false) OR v_org IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations membership
    WHERE membership.user_id = v_uid
      AND membership.organization_id = v_org
      AND COALESCE(membership.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(p_write, false) THEN
    PERFORM public.ai_employee_require_owner(v_uid, v_org);
    RETURN v_org;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = v_uid
      AND role.organization_id = v_org
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  RETURN v_org;
END;
$$;


ALTER FUNCTION "public"."ai_employee_page_gate"("p_employee_id" "uuid", "p_write" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_page_gate"("p_employee_id" "uuid", "p_write" boolean) IS 'Pintu halaman AI. Pengguna dari auth.uid(), organisasi dari karyawan AI, keanggotaan aktif. Ubah: owner. Baca: owner atau admin.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_page_read"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_can_edit boolean;
  v_name text;
  v_title text;
  v_reviewer text;
  v_status text;
  v_active boolean;
  v_brief jsonb;
  v_story_brief jsonb;
  v_service_ids uuid[];
  v_persona_ids uuid[];
  v_pillar_ids uuid[];
  v_product_ids uuid[];
  v_angle_ids uuid[];
  v_key_results jsonb;
  v_runs jsonb;
  v_jobs jsonb;
  v_schedules jsonb;
  v_routines jsonb;
  v_copy_1 text;
  v_copy_2 text;
  v_sender text;
  v_services jsonb;
  v_personas jsonb;
  v_pillars jsonb;
  v_products jsonb;
  v_angles jsonb;
  v_cap integer;
  v_used integer;
  v_remaining integer;
  v_date date;
  v_org_limit integer;
  v_org_used integer;
  v_org_date date;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, false);

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = auth.uid()
      AND role.organization_id = v_org
      AND lower(btrim(role.role)) = 'owner'
  )
  INTO v_can_edit;

  SELECT employee.full_name,
         profile.job_title,
         reviewer.full_name,
         profile.performance_status,
         profile.is_active
  INTO v_name, v_title, v_reviewer, v_status, v_active
  FROM public.employees employee
  LEFT JOIN public.ai_employee_profiles profile
    ON profile.employee_id = employee.id
   AND profile.organization_id = employee.organization_id
  LEFT JOIN public.employees reviewer
    ON reviewer.id = profile.reviewer_employee_id
   AND reviewer.organization_id = employee.organization_id
  WHERE employee.id = p_employee_id
    AND employee.organization_id = v_org;

  v_brief := public.ai_employee_brief_payload(p_employee_id);
  v_story_brief := public.ai_employee_story_brief_payload(p_employee_id);
  v_service_ids := public.ai_employee_brief_ids(v_brief->'service_ids');
  v_persona_ids := public.ai_employee_brief_ids(v_brief->'persona_ids');
  v_pillar_ids := public.ai_employee_brief_ids(v_brief->'pillar_ids');
  v_product_ids := public.ai_employee_brief_ids(v_brief->'product_knowledge_ids');
  v_angle_ids := public.ai_employee_brief_ids(v_brief->'angle_ids');
  v_angles := public.ai_employee_angle_options(v_org, v_angle_ids);

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'code', kr.ai_kr_code,
    'title', kr.title,
    'current_value', kr.current_value,
    'target_value', kr.target_value,
    'unit', kr.unit,
    'progress_percentage', kr.progress_percentage
  ) ORDER BY kr.ai_kr_code, kr.title), '[]'::jsonb)
  INTO v_key_results
  FROM public.key_results kr
  JOIN public.individual_objectives objective
    ON objective.id = kr.individual_objective_id
  WHERE objective.organization_id = v_org
    AND objective.employee_id = p_employee_id
    AND kr.ai_kr_code IN ('KR1', 'KR2', 'KR3', 'KR4', 'KR5');

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', run.id,
    'started_at', run.started_at,
    'finished_at', run.finished_at,
    'sop_code', run.sop_code,
    'status', run.status,
    'plan_count', run.plan_count,
    'note', left(COALESCE(run.note, ''), 240),
    'plans', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', plan.id,
        'title', COALESCE(plan.title, '')
      ) ORDER BY plan.title)
      FROM public.social_media_plans plan
      WHERE plan.organization_id = v_org
        AND plan.id = ANY (run.object_ids)
    ), '[]'::jsonb)
  ) ORDER BY run.started_at DESC), '[]'::jsonb)
  INTO v_runs
  FROM (
    SELECT id, started_at, finished_at, sop_code, status, plan_count, note, object_ids
    FROM public.ai_employee_runs
    WHERE employee_id = p_employee_id
      AND organization_id = v_org
    ORDER BY started_at DESC, id DESC
    LIMIT 20
  ) run;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', job.id,
    'source', job.source,
    'priority', job.priority,
    'status', job.status,
    'attempts', job.attempts,
    'reason', job.reason,
    'daily_task_id', job.daily_task_id,
    'plan_id', job.plan_id,
    'run_id', job.run_id,
    'next_attempt_at', job.next_attempt_at,
    'created_at', job.created_at,
    'claimed_at', job.claimed_at,
    'finished_at', job.finished_at
  ) ORDER BY job.created_at DESC, job.id DESC), '[]'::jsonb)
  INTO v_jobs
  FROM (
    SELECT id, source, priority, status, attempts, reason, daily_task_id, plan_id,
           run_id, next_attempt_at, created_at, claimed_at, finished_at
    FROM public.ai_employee_jobs
    WHERE employee_id = p_employee_id
      AND organization_id = v_org
    ORDER BY created_at DESC, id DESC
    LIMIT 20
  ) job;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'sop_code', schedule.sop_code,
    'cadence', schedule.cadence,
    'weekday', schedule.weekday,
    'weekdays', schedule.weekdays,
    'start_local', to_char(schedule.start_local, 'HH24:MI'),
    'due_local', to_char(schedule.due_local, 'HH24:MI'),
    'start_times', COALESCE((
      SELECT jsonb_agg(to_char(slot, 'HH24:MI') ORDER BY slot)
      FROM unnest(COALESCE(schedule.start_times, ARRAY[schedule.start_local])) AS slot
    ), '[]'::jsonb),
    'plan_count', schedule.plan_count,
    'is_active', schedule.is_active,
    'next_run_at', schedule.next_run_at
  ) ORDER BY schedule.sop_code, schedule.cadence), '[]'::jsonb)
  INTO v_schedules
  FROM public.ai_employee_schedules schedule
  WHERE schedule.employee_id = p_employee_id
    AND schedule.organization_id = v_org;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'action_code', routine.action_code,
    'cadence', routine.cadence,
    'weekday', routine.weekday,
    'weekdays', routine.weekdays,
    'time_local', to_char(routine.time_local, 'HH24:MI'),
    'is_active', routine.is_active,
    'next_run_at', routine.next_run_at,
    'last_sent_at', routine.last_sent_at,
    'last_status', routine.last_status,
    'last_error', left(routine.last_error, 240),
    'reviewer_name', reviewer.full_name,
    'reviewer_email', NULLIF(btrim(reviewer.email), '')
  ) ORDER BY routine.action_code), '[]'::jsonb)
  INTO v_routines
  FROM public.ai_employee_routines routine
  JOIN public.ai_employee_profiles profile
    ON profile.employee_id = routine.employee_id
   AND profile.organization_id = routine.organization_id
  LEFT JOIN public.employees reviewer
    ON reviewer.id = profile.reviewer_employee_id
   AND reviewer.organization_id = routine.organization_id
  WHERE routine.employee_id = p_employee_id
    AND routine.organization_id = v_org;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', item.id,
    'label', item.label
  ) ORDER BY item.label), '[]'::jsonb)
  INTO v_services
  FROM (
    SELECT svc.id, left(btrim(svc.name), 80) AS label
    FROM public.services svc
    WHERE svc.organization_id = v_org
      AND (
        COALESCE(svc.is_active, true)
        OR svc.id = ANY (v_service_ids)
      )
      AND (
        svc.id = ANY (v_service_ids)
        OR svc.id IN (
          SELECT picked.id
          FROM public.services picked
          WHERE picked.organization_id = v_org
            AND COALESCE(picked.is_active, true)
          ORDER BY picked.name
          LIMIT 200
        )
      )
  ) item;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', item.id,
    'label', item.label
  ) ORDER BY item.label), '[]'::jsonb)
  INTO v_personas
  FROM (
    SELECT knowledge.id,
           left(btrim(COALESCE(NULLIF(btrim(knowledge.feature_name), ''), 'Persona')), 80) AS label
    FROM public.product_knowledge knowledge
    WHERE knowledge.organization_id = v_org
      AND (
        knowledge.id = ANY (v_persona_ids)
        OR knowledge.id IN (
          SELECT picked.id
          FROM public.product_knowledge picked
          WHERE picked.organization_id = v_org
          ORDER BY picked.feature_name
          LIMIT 200
        )
      )
  ) item;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', item.id,
    'label', item.label
  ) ORDER BY item.label), '[]'::jsonb)
  INTO v_pillars
  FROM (
    SELECT pillar.id, left(btrim(pillar.name), 80) AS label
    FROM public.content_pillars pillar
    WHERE (
        pillar.id = ANY (v_pillar_ids)
        OR (
          pillar.is_active
          AND (pillar.organization_id = v_org OR pillar.is_default)
        )
      )
      AND (
        pillar.id = ANY (v_pillar_ids)
        OR pillar.id IN (
          SELECT picked.id
          FROM public.content_pillars picked
          WHERE picked.is_active
            AND (picked.organization_id = v_org OR picked.is_default)
          ORDER BY picked.name
          LIMIT 200
        )
      )
  ) item;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', item.id,
    'label', item.label,
    'service_id', item.service_id,
    'parent_service_id', item.parent_service_id
  ) ORDER BY item.label), '[]'::jsonb)
  INTO v_products
  FROM (
    SELECT knowledge.id,
           left(btrim(COALESCE(NULLIF(btrim(knowledge.feature_name), ''), 'Produk')), 80) AS label,
           knowledge.service_id,
           sub.service_id AS parent_service_id
    FROM public.product_knowledge knowledge
    LEFT JOIN public.sub_services sub
      ON sub.id = knowledge.sub_service_id
     AND sub.organization_id = knowledge.organization_id
    WHERE knowledge.organization_id = v_org
      AND (
        knowledge.id = ANY (v_product_ids)
        OR knowledge.id IN (
          SELECT picked.id
          FROM public.product_knowledge picked
          WHERE picked.organization_id = v_org
          ORDER BY picked.feature_name
          LIMIT 200
        )
      )
  ) item;

  v_date := (timezone('Asia/Jakarta', now()))::date;
  v_org_date := (timezone('UTC', now()))::date;

  SELECT CASE WHEN profile.performance_status = 'coaching' THEN 8 ELSE 1000 END
  INTO v_cap
  FROM public.ai_employee_profiles profile
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = v_org;

  SELECT calls.call_count
  INTO v_used
  FROM public.ai_employee_model_calls calls
  WHERE calls.employee_id = p_employee_id
    AND calls.usage_date = v_date;
  v_used := COALESCE(v_used, 0);
  IF v_cap IS NULL THEN
    v_remaining := NULL;
  ELSE
    v_remaining := GREATEST(v_cap - v_used, 0);
  END IF;

  SELECT COALESCE(config.daily_limit, 50)
  INTO v_org_limit
  FROM public.organization_script_ai_config config
  WHERE config.organization_id = v_org;
  IF v_org_limit IS NULL OR v_org_limit < 1 THEN
    v_org_limit := 50;
  END IF;

  SELECT COALESCE(usage."count", 0)
  INTO v_org_used
  FROM public.script_ai_daily_usage usage
  WHERE usage.organization_id = v_org
    AND usage.usage_date = v_org_date;
  v_org_used := COALESCE(v_org_used, 0);

  SELECT profile.report_copy_email_1,
         profile.report_copy_email_2,
         COALESCE(
           NULLIF(btrim(sender.full_name), ''),
           NULLIF(btrim(v_reviewer), '')
         )
  INTO v_copy_1, v_copy_2, v_sender
  FROM public.ai_employee_profiles profile
  LEFT JOIN public.profiles sender
    ON sender.user_id = profile.report_sender_user_id
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = v_org;

  RETURN jsonb_build_object(
    'organization_id', v_org,
    'can_edit', v_can_edit,
    'summary', jsonb_build_object(
      'full_name', v_name,
      'job_title', v_title,
      'reviewer_name', v_reviewer,
      'performance_status', v_status,
      'is_active', v_active,
      'report_copy_email_1', v_copy_1,
      'report_copy_email_2', v_copy_2,
      'report_sender_name', v_sender
    ),
    'key_results', v_key_results,
    'runs', v_runs,
    'jobs', v_jobs,
    'schedules', v_schedules,
    'routines', v_routines,
    'brief', v_brief,
    'story_brief', v_story_brief,
    'options', jsonb_build_object(
      'services', v_services,
      'personas', v_personas,
      'pillars', v_pillars,
      'products', v_products,
      'angles', v_angles
    ),
    'quota', jsonb_build_object(
      'usage_date', v_date,
      'used', v_used,
      'cap', v_cap,
      'remaining', v_remaining,
      'org_usage_date', v_org_date,
      'org_used', v_org_used,
      'org_limit', v_org_limit,
      'org_remaining', GREATEST(v_org_limit - v_org_used, 0)
    )
  );
END;
$$;


