CREATE OR REPLACE FUNCTION "public"."ai_employee_perform"("p_employee_id" "uuid", "p_run_id" "uuid", "p_action" "text", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_payload_org uuid;
  v_id uuid;
  v_task uuid;
  v_parent uuid;
  v_assigner uuid;
  v_title text;
  v_brief text;
  v_pillar uuid;
  v_post timestamptz;
  v_order integer;
  v_entity text;
  v_brief_token text;
  v_service uuid;
  v_idea uuid;
  v_execution uuid;
  v_product uuid;
  v_fields text[];
  v_carousel_brief text;
  v_carousel_caption text;
  v_carousel_type uuid;
  v_carousel_concept text;
  v_delivery_voice text;
BEGIN
  v_org := public.ai_employee_require_run(p_employee_id, p_run_id);
  PERFORM public.ai_employee_assert_job_claim(p_employee_id, p_run_id, v_payload);

  IF p_action = ANY (ARRAY[
    'content.plans.schedule',
    'tasks.delete',
    'tasks.steps.delete',
    'tasks.substeps.delete',
    'session.switchOrg'
  ]) OR p_action LIKE 'finance.%'
    OR p_action LIKE 'payroll.%'
    OR p_action LIKE 'hr.%'
    OR p_action LIKE 'crm.%'
    OR p_action LIKE 'ads.%'
  THEN
    RAISE EXCEPTION 'action_forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT (p_action = ANY (ARRAY[
    'content.plans.create',
    'content.plans.update',
    'content.briefs.create',
    'thinking.plan.save',
    'thinking.plan.direct',
    'thinking.execution.check',
    'tasks.update',
    'tasks.steps.create',
    'tasks.steps.update',
    'tasks.substeps.create',
    'tasks.completion.request'
  ])) THEN
    RAISE EXCEPTION 'action_forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.ai_employee_permissions perm
    WHERE perm.employee_id = p_employee_id
      AND perm.action_code = p_action
  ) THEN
    RAISE EXCEPTION 'action_forbidden' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(v_payload->>'approved', '') IN ('true', 't', '1')
    OR COALESCE(v_payload->>'production_approved', '') IN ('true', 't', '1')
    OR lower(btrim(COALESCE(v_payload->>'production_status', ''))) = 'approved'
    OR (
      p_action = 'tasks.completion.request'
      AND lower(btrim(COALESCE(v_payload->>'status', 'pending'))) <> 'pending'
    )
    OR (
      p_action LIKE 'tasks.%'
      AND p_action <> 'tasks.completion.request'
      AND lower(btrim(COALESCE(v_payload->>'status', ''))) IN ('completed', 'cancelled', 'approved')
    )
  THEN
    RAISE EXCEPTION 'approval_forbidden' USING ERRCODE = '42501';
  END IF;

  IF jsonb_exists(v_payload, 'organization_id') THEN
    BEGIN
      v_payload_org := NULLIF(v_payload->>'organization_id', '')::uuid;
    EXCEPTION
      WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'organization_mismatch' USING ERRCODE = '42501';
    END;
    IF v_payload_org IS DISTINCT FROM v_org THEN
      RAISE EXCEPTION 'organization_mismatch' USING ERRCODE = '42501';
    END IF;
  END IF;

  IF p_action = 'thinking.execution.check' THEN
    RETURN public.ai_employee_accept_execution(v_org, p_employee_id, v_payload);
  END IF;

  IF p_action IN ('content.plans.create', 'thinking.plan.save', 'thinking.plan.direct') THEN
    v_title := NULLIF(btrim(COALESCE(v_payload->>'title', '')), '');
    v_brief := NULLIF(v_payload->>'brief', '');
    IF v_title IS NULL OR char_length(v_title) > 200 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF v_brief IS NOT NULL AND char_length(v_brief) > 200000 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF NULLIF(v_payload->>'post_date', '') IS NULL THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_post := ((v_payload->>'post_date')::date::timestamp) AT TIME ZONE 'Asia/Jakarta';

    IF NULLIF(v_payload->>'content_pillar_id', '') IS NOT NULL
      OR p_action LIKE 'thinking.%'
    THEN
      v_pillar := NULLIF(v_payload->>'content_pillar_id', '')::uuid;
      IF v_pillar IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.content_pillars c
        WHERE c.id = v_pillar
          AND c.is_active
          AND (c.organization_id = v_org OR c.is_default)
      ) THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    END IF;

    v_service := NULL;
    v_idea := NULL;
    v_execution := NULL;
    IF NULLIF(v_payload->>'service_id', '') IS NOT NULL THEN
      v_service := (v_payload->>'service_id')::uuid;
      IF NOT EXISTS (
        SELECT 1 FROM public.services svc
        WHERE svc.id = v_service
          AND svc.organization_id = v_org
          AND COALESCE(svc.is_active, true)
      ) THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    END IF;

    IF p_action = 'thinking.plan.save' THEN
      v_idea := NULLIF(v_payload->>'idea_id', '')::uuid;
      IF v_idea IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.thinking_lab_ideas idea
        WHERE idea.id = v_idea
          AND idea.organization_id = v_org
          AND idea.status = 'locked'
          AND idea.validation->>'decision' = 'LOLOS'
      ) THEN
        RAISE EXCEPTION 'idea_not_found' USING ERRCODE = 'P0002';
      END IF;
      v_delivery_voice := NULLIF(left(btrim(COALESCE(v_payload->>'delivery_voice', '')), 500), '');
      IF NULLIF(v_payload->>'path_pillar_id', '') IS NOT NULL THEN
        v_pillar := NULLIF(v_payload->>'path_pillar_id', '')::uuid;
        IF v_pillar IS NULL OR NOT public.ai_employee_carousel_path_allowed(
          p_employee_id, v_idea, v_pillar, v_delivery_voice
        ) THEN
          RAISE EXCEPTION 'path_not_allowed' USING ERRCODE = '42501';
        END IF;
      ELSIF EXISTS (
        SELECT 1 FROM public.social_media_plans existing
        WHERE existing.organization_id = v_org
          AND existing.thinking_idea_id = v_idea
          AND existing.content_pillar_id = v_pillar
      ) THEN
        RAISE EXCEPTION 'idea_used' USING ERRCODE = '23505';
      END IF;
      IF NULLIF(v_payload->>'execution_id', '') IS NOT NULL THEN
        v_execution := (v_payload->>'execution_id')::uuid;
        IF NOT EXISTS (
          SELECT 1 FROM public.thinking_lab_executions ex
          WHERE ex.id = v_execution
            AND ex.organization_id = v_org
            AND ex.idea_id = v_idea
            AND ex.admission = 'GENERATE_VALID'
            AND ex.creative_idea_id IS NULL
        ) THEN
          RAISE EXCEPTION 'execution_not_passed' USING ERRCODE = '42501';
        END IF;
      END IF;
    END IF;

    v_product := NULL;
    IF NULLIF(v_payload->>'product_knowledge_id', '') IS NOT NULL THEN
      v_product := (v_payload->>'product_knowledge_id')::uuid;
      IF NOT EXISTS (
        SELECT 1
        FROM public.product_knowledge knowledge
        LEFT JOIN public.sub_services sub
          ON sub.id = knowledge.sub_service_id
         AND sub.organization_id = knowledge.organization_id
        JOIN public.ai_employee_briefs brief
          ON brief.employee_id = p_employee_id
         AND brief.organization_id = v_org
        WHERE knowledge.id = v_product
          AND knowledge.organization_id = v_org
          AND (
            COALESCE(cardinality(brief.product_knowledge_ids), 0) = 0
            OR knowledge.id = ANY (brief.product_knowledge_ids)
          )
          AND (
            knowledge.service_id = ANY (brief.service_ids)
            OR sub.service_id = ANY (brief.service_ids)
          )
      ) THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    END IF;

    v_fields := NULL;
    IF v_product IS NOT NULL
      AND jsonb_typeof(v_payload->'product_knowledge_fields') = 'array'
    THEN
      SELECT array_agg(picked.field ORDER BY picked.field)
      INTO v_fields
      FROM (
        SELECT DISTINCT src.field
        FROM (
          SELECT left(btrim(element.item #>> '{}'), 80) AS field
          FROM jsonb_array_elements(v_payload->'product_knowledge_fields') WITH ORDINALITY AS element(item, ordinality)
          WHERE element.ordinality <= 13
            AND jsonb_typeof(element.item) = 'string'
        ) src
        JOIN public.product_knowledge knowledge
          ON knowledge.id = v_product
         AND knowledge.organization_id = v_org
        WHERE src.field IN (
          'feature_name', 'feature_description', 'problems_solved', 'impact', 'solusi',
          'competitive_advantage', 'target_audience', 'wants', 'needs', 'hidden_needs',
          'false_belief', 'false_belief_impact', 'what_makes_them_stop'
        )
          AND CASE src.field
            WHEN 'feature_name' THEN btrim(knowledge.feature_name) <> ''
            WHEN 'feature_description' THEN btrim(knowledge.feature_description) <> ''
            WHEN 'problems_solved' THEN EXISTS (
              SELECT 1 FROM unnest(COALESCE(knowledge.problems_solved, '{}'::text[])) AS piece
              WHERE btrim(piece) <> ''
            )
            WHEN 'impact' THEN btrim(knowledge.impact) <> ''
            WHEN 'solusi' THEN btrim(COALESCE(knowledge.solusi, '')) <> ''
            WHEN 'competitive_advantage' THEN btrim(COALESCE(public.ai_employee_product_clip(knowledge.competitive_advantage, 400), '')) <> ''
            WHEN 'target_audience' THEN btrim(COALESCE(public.ai_employee_product_clip(knowledge.target_audience, 240), '')) <> ''
            WHEN 'wants' THEN btrim(COALESCE(knowledge.wants, '')) <> ''
            WHEN 'needs' THEN btrim(COALESCE(knowledge.needs, '')) <> ''
            WHEN 'hidden_needs' THEN btrim(COALESCE(knowledge.hidden_needs, '')) <> ''
            WHEN 'false_belief' THEN btrim(COALESCE(knowledge.false_belief, '')) <> ''
            WHEN 'false_belief_impact' THEN btrim(COALESCE(knowledge.false_belief_impact, '')) <> ''
            WHEN 'what_makes_them_stop' THEN btrim(COALESCE(knowledge.what_makes_them_stop, '')) <> ''
            ELSE false
          END
      ) picked;
    END IF;

    IF COALESCE(v_payload->>'content_kind', '') = 'story' THEN
      IF p_action <> 'thinking.plan.save' OR v_execution IS NULL THEN
        RAISE EXCEPTION 'execution_not_passed' USING ERRCODE = '42501';
      END IF;
      SELECT packed.brief, packed.caption, packed.content_type_id, packed.concept
      INTO v_carousel_brief, v_carousel_caption, v_carousel_type, v_carousel_concept
      FROM public.ai_employee_story_fields(v_org, v_payload) AS packed;
      v_brief := v_carousel_brief;
    ELSIF jsonb_typeof(v_payload->'slides') = 'array' THEN
      IF p_action <> 'thinking.plan.save' THEN
        RAISE EXCEPTION 'execution_not_passed' USING ERRCODE = '42501';
      END IF;
      SELECT packed.brief, packed.caption, packed.content_type_id, packed.concept
      INTO v_carousel_brief, v_carousel_caption, v_carousel_type, v_carousel_concept
      FROM public.ai_employee_carousel_fields(v_org, v_payload) AS packed;
      v_brief := v_carousel_brief;
    END IF;

    INSERT INTO public.social_media_plans (
      organization_id, title, brief, post_date, content_pillar_id, service_id, sub_service_id, thinking_idea_id,
      product_knowledge_id, product_knowledge_fields, author_employee_id, content_type_id, pic_id,
      delivery_voice, pic_production_id, pic_production_source, production_status, approved, production_approved, status
    ) VALUES (
      v_org, v_title, v_brief, v_post, v_pillar, v_service,
      public.ai_employee_catalog_sub_service(
        v_org,
        v_service,
        public.ai_employee_pick_brief_sub_service(p_employee_id, v_org, v_service)
      ),
      v_idea,
      v_product, v_fields, p_employee_id, v_carousel_type,
      (SELECT ai_author.id
         FROM public.employees ai_author
        WHERE ai_author.id = p_employee_id
          AND ai_author.organization_id = v_org
          AND ai_author.is_ai IS TRUE),
      CASE WHEN NULLIF(v_payload->>'path_pillar_id', '') IS NOT NULL THEN v_delivery_voice ELSE NULL END,
      (SELECT ai_author.id
         FROM public.employees ai_author
        WHERE ai_author.id = p_employee_id
          AND ai_author.organization_id = v_org
          AND ai_author.is_ai IS TRUE),
      CASE
        WHEN EXISTS (
          SELECT 1
            FROM public.employees ai_author
           WHERE ai_author.id = p_employee_id
             AND ai_author.organization_id = v_org
             AND ai_author.is_ai IS TRUE
        ) THEN 'content_pic'
        ELSE NULL
      END,
      NULL, false, false, 'Need Review'
    )
    RETURNING id INTO v_id;

    IF v_carousel_type IS NOT NULL THEN
      INSERT INTO public.brief_captions (social_media_plan_id, content)
      VALUES (v_id, v_carousel_caption);
      INSERT INTO public.brief_target_audiences (social_media_plan_id, description)
      VALUES (v_id, v_carousel_concept);
    END IF;

    IF v_service IS NOT NULL AND (
      (
        COALESCE(v_payload->>'content_kind', '') = 'story'
        AND EXISTS (
          SELECT 1
          FROM public.ai_employee_story_briefs story_brief
          WHERE story_brief.employee_id = p_employee_id
            AND story_brief.organization_id = v_org
            AND story_brief.story_auto_approve IS TRUE
        )
      )
      OR (
        COALESCE(v_payload->>'content_kind', '') IS DISTINCT FROM 'story'
        AND EXISTS (
          SELECT 1
          FROM public.ai_employee_briefs brief
          WHERE brief.employee_id = p_employee_id
            AND brief.organization_id = v_org
            AND brief.content_plan_auto_approve IS TRUE
        )
      )
    ) THEN
      UPDATE public.social_media_plans
      SET approved = true,
          status = 'Approved',
          completion_date = now()
      WHERE id = v_id
        AND approved IS NOT TRUE;
    END IF;

    UPDATE public.ai_employee_runs
    SET object_ids = CASE WHEN v_id = ANY (object_ids) THEN object_ids ELSE object_ids || v_id END,
        plan_count = plan_count + 1
    WHERE id = p_run_id;

    RETURN jsonb_build_object('ok', true, 'id', v_id);
  END IF;

  IF p_action IN ('content.plans.update', 'content.briefs.create') THEN
    v_id := NULLIF(v_payload->>'plan_id', '')::uuid;
    IF v_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM public.social_media_plans p
      WHERE p.id = v_id
        AND p.organization_id = v_org
        AND p.author_employee_id = p_employee_id
    ) THEN
      RAISE EXCEPTION 'not_assignee' USING ERRCODE = '42501';
    END IF;

    IF p_action = 'content.briefs.create' THEN
      v_brief := NULLIF(v_payload->>'brief', '');
      IF v_brief IS NULL THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
      v_brief_token := gen_random_uuid()::text;
      INSERT INTO public.ai_employee_brief_tickets (plan_id, token)
      VALUES (v_id, v_brief_token)
      ON CONFLICT (plan_id) DO UPDATE
        SET token = EXCLUDED.token, created_at = now();
      PERFORM set_config('ai_employee.brief_write', v_brief_token, true);
      UPDATE public.social_media_plans
      SET brief = v_brief,
          approved = false,
          production_approved = false,
          updated_at = now()
      WHERE id = v_id;
      DELETE FROM public.ai_employee_brief_tickets
      WHERE plan_id = v_id AND token = v_brief_token;
      PERFORM set_config('ai_employee.brief_write', '', true);
    ELSE
      IF jsonb_exists(v_payload, 'title') THEN
        v_title := NULLIF(btrim(v_payload->>'title'), '');
        IF v_title IS NULL OR char_length(v_title) > 200 THEN
          RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
        END IF;
      END IF;
      IF NULLIF(v_payload->>'post_date', '') IS NOT NULL THEN
        v_post := ((v_payload->>'post_date')::date::timestamp) AT TIME ZONE 'Asia/Jakarta';
      END IF;
      IF NULLIF(v_payload->>'content_pillar_id', '') IS NOT NULL THEN
        v_pillar := (v_payload->>'content_pillar_id')::uuid;
        IF NOT EXISTS (
          SELECT 1 FROM public.content_pillars c
          WHERE c.id = v_pillar
            AND c.is_active
            AND (c.organization_id = v_org OR c.is_default)
        ) THEN
          RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
        END IF;
      END IF;
      v_brief_token := gen_random_uuid()::text;
      INSERT INTO public.ai_employee_brief_tickets (plan_id, token)
      VALUES (v_id, v_brief_token)
      ON CONFLICT (plan_id) DO UPDATE
        SET token = EXCLUDED.token, created_at = now();
      PERFORM set_config('ai_employee.brief_write', v_brief_token, true);
      UPDATE public.social_media_plans
      SET title = COALESCE(v_title, title),
          brief = CASE WHEN jsonb_exists(v_payload, 'brief') THEN v_payload->>'brief' ELSE brief END,
          post_date = COALESCE(v_post, post_date),
          content_pillar_id = COALESCE(v_pillar, content_pillar_id),
          author_employee_id = p_employee_id,
          approved = false,
          production_approved = false,
          updated_at = now()
      WHERE id = v_id;
      DELETE FROM public.ai_employee_brief_tickets
      WHERE plan_id = v_id AND token = v_brief_token;
      PERFORM set_config('ai_employee.brief_write', '', true);
    END IF;

    RETURN jsonb_build_object('ok', true, 'id', v_id);
  END IF;

  IF p_action = 'tasks.update' THEN
    v_task := NULLIF(v_payload->>'task_id', '')::uuid;
    PERFORM public.ai_employee_assert_task(p_employee_id, v_org, v_task);
    UPDATE public.daily_tasks
    SET title = COALESCE(NULLIF(v_payload->>'title', ''), title),
        description = CASE WHEN jsonb_exists(v_payload, 'description') THEN v_payload->>'description' ELSE description END,
        priority = COALESCE(NULLIF(v_payload->>'priority', ''), priority),
        due_date = CASE
          WHEN NULLIF(v_payload->>'due_date', '') IS NULL THEN due_date
          ELSE (v_payload->>'due_date')::timestamptz
        END,
        updated_at = now()
    WHERE id = v_task
      AND organization_id = v_org;
    RETURN jsonb_build_object('ok', true, 'id', v_task);
  END IF;

  IF p_action = 'tasks.steps.create' THEN
    v_task := NULLIF(v_payload->>'task_id', '')::uuid;
    PERFORM public.ai_employee_assert_task(p_employee_id, v_org, v_task);
    v_title := COALESCE(NULLIF(v_payload->>'title', ''), '');
    v_order := COALESCE((NULLIF(v_payload->>'order', ''))::integer, 1);
    INSERT INTO public.task_steps (task_id, title, description, "order")
    VALUES (v_task, v_title, v_payload->>'description', v_order)
    RETURNING id INTO v_id;
    UPDATE public.daily_tasks
    SET has_steps = true, updated_at = now()
    WHERE id = v_task;
    RETURN jsonb_build_object('ok', true, 'id', v_id);
  END IF;

  IF p_action = 'tasks.steps.update' THEN
    v_id := NULLIF(v_payload->>'step_id', '')::uuid;
    SELECT task_id INTO v_task FROM public.task_steps WHERE id = v_id;
    PERFORM public.ai_employee_assert_task(p_employee_id, v_org, v_task);
    UPDATE public.task_steps
    SET title = COALESCE(NULLIF(v_payload->>'title', ''), title),
        description = CASE WHEN jsonb_exists(v_payload, 'description') THEN v_payload->>'description' ELSE description END,
        "order" = COALESCE((NULLIF(v_payload->>'order', ''))::integer, "order"),
        is_completed = CASE
          WHEN jsonb_exists(v_payload, 'is_completed') THEN (v_payload->>'is_completed')::boolean
          ELSE is_completed
        END,
        updated_at = now()
    WHERE id = v_id;
    RETURN jsonb_build_object('ok', true, 'id', v_id);
  END IF;

  IF p_action = 'tasks.substeps.create' THEN
    v_parent := NULLIF(v_payload->>'parent_step_id', '')::uuid;
    SELECT s.task_id INTO v_task
    FROM public.task_steps s
    JOIN public.daily_tasks t ON t.id = s.task_id
    WHERE s.id = v_parent
      AND t.organization_id = v_org;
    PERFORM public.ai_employee_assert_task(p_employee_id, v_org, v_task);
    v_order := COALESCE((NULLIF(v_payload->>'order', ''))::integer, 1);
    INSERT INTO public.task_steps_to_steps (parent_step_id, organization_id, title, "order")
    VALUES (v_parent, v_org, COALESCE(NULLIF(v_payload->>'title', ''), ''), v_order)
    RETURNING id INTO v_id;
    UPDATE public.daily_tasks
    SET has_substeps = true, updated_at = now()
    WHERE id = v_task;
    RETURN jsonb_build_object('ok', true, 'id', v_id);
  END IF;

  v_entity := COALESCE(NULLIF(v_payload->>'entity_type', ''), 'task');
  IF v_entity NOT IN ('task', 'step', 'substep') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_task := NULLIF(v_payload->>'task_id', '')::uuid;
  IF v_entity = 'step' THEN
    SELECT task_id INTO v_task
    FROM public.task_steps
    WHERE id = NULLIF(v_payload->>'step_id', '')::uuid;
  ELSIF v_entity = 'substep' THEN
    SELECT s.task_id INTO v_task
    FROM public.task_steps_to_steps sub
    JOIN public.task_steps s ON s.id = sub.parent_step_id
    WHERE sub.id = NULLIF(v_payload->>'substep_id', '')::uuid;
  END IF;

  PERFORM public.ai_employee_assert_task(p_employee_id, v_org, v_task);

  SELECT a.assigned_by INTO v_assigner
  FROM public.daily_tasks_assigned a
  WHERE a.daily_task_id = v_task
  ORDER BY a.assigned_at DESC
  LIMIT 1;

  IF v_assigner IS NULL THEN
    RAISE EXCEPTION 'not_assignee' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.completion_approvals (
    organization_id, entity_type, daily_task_id, task_step_id, task_steps_to_steps_id,
    assignee_employee_id, assigner_employee_id, status
  ) VALUES (
    v_org,
    v_entity,
    v_task,
    NULLIF(v_payload->>'step_id', '')::uuid,
    NULLIF(v_payload->>'substep_id', '')::uuid,
    p_employee_id,
    v_assigner,
    'pending'
  )
  RETURNING id INTO v_id;

  UPDATE public.ai_employee_runs
  SET object_ids = CASE WHEN v_id = ANY (object_ids) THEN object_ids ELSE object_ids || v_id END
  WHERE id = p_run_id;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'pending');
END;
$$;


ALTER FUNCTION "public"."ai_employee_perform"("p_employee_id" "uuid", "p_run_id" "uuid", "p_action" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_pick_brief_sub_service"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_service_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids uuid[];
  v_chosen uuid;
BEGIN
  SELECT COALESCE(brief.sub_service_ids, '{}'::uuid[])
    INTO v_ids
  FROM public.ai_employee_briefs brief
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = p_organization_id;

  IF v_ids IS NULL OR cardinality(v_ids) = 0 THEN
    RETURN (
      SELECT brief.sub_service_id
      FROM public.ai_employee_briefs brief
      WHERE brief.employee_id = p_employee_id
        AND brief.organization_id = p_organization_id
    );
  END IF;

  SELECT item.id
    INTO v_chosen
  FROM unnest(v_ids) WITH ORDINALITY AS item(id, ord)
  JOIN public.sub_services sub ON sub.id = item.id
  WHERE sub.organization_id = p_organization_id
    AND sub.service_id = p_service_id
    AND COALESCE(sub.is_active, true)
    AND lower(btrim(sub.name)) <> 'general content'
  ORDER BY (
    SELECT max(plan.created_at)
    FROM public.social_media_plans plan
    WHERE plan.organization_id = p_organization_id
      AND plan.pic_id = p_employee_id
      AND plan.sub_service_id = item.id
  ) NULLS FIRST, item.ord
  LIMIT 1;

  RETURN v_chosen;
END;
$$;


ALTER FUNCTION "public"."ai_employee_pick_brief_sub_service"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_service_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_product_clip"("p_value" "jsonb", "p_max" integer) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT left(btrim(COALESCE(
    CASE
      WHEN p_value IS NULL OR jsonb_typeof(p_value) = 'null' THEN ''
      WHEN jsonb_typeof(p_value) = 'string' THEN p_value #>> '{}'
      WHEN jsonb_typeof(p_value) = 'array' THEN (
        SELECT string_agg(left(btrim(COALESCE(
          CASE jsonb_typeof(item)
            WHEN 'string' THEN item #>> '{}'
            ELSE COALESCE(item->>'name', item->>'text', item->>'description', '')
          END, '')), 120), '; ')
        FROM (
          SELECT item
          FROM jsonb_array_elements(p_value) AS item
          LIMIT 4
        ) items
      )
      WHEN jsonb_typeof(p_value) = 'object' THEN COALESCE(
        p_value->>'name',
        p_value->>'description',
        p_value->>'persona',
        p_value->>'text',
        ''
      )
      ELSE ''
    END, '')), GREATEST(COALESCE(p_max, 240), 0));
$$;


ALTER FUNCTION "public"."ai_employee_product_clip"("p_value" "jsonb", "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_profiles_retarget_schedules"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text;
BEGIN
  IF NEW.time_zone IS NOT DISTINCT FROM OLD.time_zone THEN
    RETURN NEW;
  END IF;
  v_zone := COALESCE(NULLIF(btrim(NEW.time_zone), ''), 'Asia/Jakarta');
  PERFORM public.ai_employee_content_schedules_retarget(NEW.employee_id, NEW.organization_id);
  UPDATE public.ai_employee_schedules AS schedule
  SET next_run_at = public.ai_employee_next_run_at(schedule.weekday, schedule.start_local, v_zone, clock_timestamp())
  WHERE schedule.employee_id = NEW.employee_id
    AND schedule.organization_id = NEW.organization_id
    AND schedule.is_active
    AND schedule.sop_code IS DISTINCT FROM 'SOP1'
    AND schedule.weekday BETWEEN 1 AND 7;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_profiles_retarget_schedules"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_queue_actor_reason"("p_ai_employee_id" "uuid", "p_organization_id" "uuid", "p_fallback_user_id" "uuid", "p_fallback_employee_id" "uuid", "p_allow_service" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NOT NULL THEN
    IF public.ai_employee_user_may_assign(v_uid, p_ai_employee_id, p_organization_id) THEN
      RETURN NULL;
    END IF;
    RETURN 'Bukan owner, admin, atau reviewer.';
  END IF;

  IF COALESCE(p_allow_service, false) AND public.ai_employee_caller_is_service() THEN
    IF p_fallback_user_id IS NOT NULL
      AND public.ai_employee_user_may_assign(p_fallback_user_id, p_ai_employee_id, p_organization_id) THEN
      RETURN NULL;
    END IF;
    IF p_fallback_employee_id IS NOT NULL
      AND public.ai_employee_may_assign(p_fallback_employee_id, p_ai_employee_id, p_organization_id) THEN
      RETURN NULL;
    END IF;
    IF p_fallback_user_id IS NULL AND p_fallback_employee_id IS NULL THEN
      RETURN 'Penugas tidak teridentifikasi.';
    END IF;
    RETURN 'Bukan owner, admin, atau reviewer.';
  END IF;

  RETURN 'Penugas tidak teridentifikasi.';
END;
$$;


ALTER FUNCTION "public"."ai_employee_queue_actor_reason"("p_ai_employee_id" "uuid", "p_organization_id" "uuid", "p_fallback_user_id" "uuid", "p_fallback_employee_id" "uuid", "p_allow_service" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_reference_object_allowed"("p_name" "text", "p_write" boolean) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_employee uuid;
  v_role text;
BEGIN
  IF auth.uid() IS NULL OR p_name IS NULL THEN
    RETURN false;
  END IF;
  IF p_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[1-5]\.(png|jpe?g|webp)$' THEN
    RETURN false;
  END IF;
  v_org := split_part(p_name, '/', 1)::uuid;
  v_employee := split_part(p_name, '/', 2)::uuid;
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = v_employee
      AND employee.organization_id = v_org
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RETURN false;
  END IF;
  SELECT lower(btrim(role.role))
  INTO v_role
  FROM public.user_roles role
  WHERE role.user_id = auth.uid()
    AND role.organization_id = v_org
    AND lower(btrim(role.role)) IN ('owner', 'admin')
  ORDER BY CASE lower(btrim(role.role)) WHEN 'owner' THEN 0 ELSE 1 END
  LIMIT 1;
  IF v_role IS NULL THEN
    RETURN false;
  END IF;
  IF COALESCE(p_write, false) THEN
    RETURN v_role = 'owner';
  END IF;
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_reference_object_allowed"("p_name" "text", "p_write" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_refresh_krs"("p_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_closed integer;
  v_on_time integer;
  v_kr1 numeric;
  v_plan_count integer;
  v_pillar_count integer;
  v_missing_pillar integer;
  v_max_share numeric;
  v_kr3 numeric;
  v_kr3_metric text;
  v_kr3_unit text;
  v_approved integer;
  v_scheduled integer;
  v_kr5 numeric;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.employees
  WHERE id = p_employee_id
    AND COALESCE(is_ai, false);

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'not_ai_employee' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.key_results kr
    JOIN public.individual_objectives io ON io.id = kr.individual_objective_id
    WHERE io.employee_id = p_employee_id
      AND io.organization_id = v_org
      AND kr.ai_kr_code IN ('KR1', 'KR3', 'KR5')
  ) THEN
    RETURN;
  END IF;

  -- Penyebut sementara: run SOP1 yang sudah ditutup. Penyebut yang benar adalah
  -- minggu yang dijadwalkan. Itu diperbaiki di step 5 saat instance jadwal ada.
  SELECT
    COUNT(*) FILTER (
      WHERE status IN ('succeeded', 'late', 'failed', 'deferred', 'returned')
    ),
    COUNT(*) FILTER (
      WHERE status = 'succeeded'
        AND finished_at IS NOT NULL
        AND EXTRACT(ISODOW FROM timezone('Asia/Jakarta', started_at)) = 5
        AND timezone('Asia/Jakarta', finished_at)
            <= date_trunc('day', timezone('Asia/Jakarta', started_at)) + interval '17 hours'
    )
  INTO v_closed, v_on_time
  FROM public.ai_employee_runs
  WHERE employee_id = p_employee_id
    AND organization_id = v_org
    AND sop_code = 'SOP1';

  v_kr1 := CASE
    WHEN COALESCE(v_closed, 0) = 0 THEN 0
    ELSE ROUND((100.0 * v_on_time / v_closed)::numeric, 2)
  END;

  UPDATE public.key_results kr
  SET current_value = v_on_time,
      progress_percentage = v_kr1,
      metric_type = 'percentage',
      unit = '%',
      updated_at = now()
  FROM public.individual_objectives io
  WHERE kr.individual_objective_id = io.id
    AND io.employee_id = p_employee_id
    AND io.organization_id = v_org
    AND kr.ai_kr_code = 'KR1';

  SELECT COUNT(*)
  INTO v_plan_count
  FROM public.social_media_plans p
  WHERE p.organization_id = v_org
    AND p.author_employee_id = p_employee_id
    AND p.post_date >= now() - interval '28 days';

  SELECT COUNT(*)
  INTO v_pillar_count
  FROM public.content_pillars c
  WHERE c.is_active
    AND (c.organization_id = v_org OR c.is_default);

  IF v_plan_count < 5 OR v_pillar_count < 3 THEN
    v_kr3 := 0;
    v_kr3_metric := 'unrated';
    v_kr3_unit := 'belum dinilai';
  ELSE
    SELECT COUNT(*) FILTER (WHERE content_pillar_id IS NULL)
    INTO v_missing_pillar
    FROM public.social_media_plans p
    WHERE p.organization_id = v_org
      AND p.author_employee_id = p_employee_id
      AND p.post_date >= now() - interval '28 days';

    SELECT MAX(cnt)::numeric / NULLIF(v_plan_count, 0)
    INTO v_max_share
    FROM (
      SELECT COUNT(*) AS cnt
      FROM public.social_media_plans p
      WHERE p.organization_id = v_org
        AND p.author_employee_id = p_employee_id
        AND p.post_date >= now() - interval '28 days'
      GROUP BY p.content_pillar_id
    ) shares;

    IF COALESCE(v_missing_pillar, 0) > 0 OR COALESCE(v_max_share, 0) = 0 THEN
      v_kr3 := 0;
    ELSE
      v_kr3 := LEAST(100, ROUND((100.0 * 0.40 / v_max_share)::numeric, 2));
    END IF;
    v_kr3_metric := 'percentage';
    v_kr3_unit := '%';
  END IF;

  UPDATE public.key_results kr
  SET current_value = CASE WHEN v_kr3_metric = 'unrated' THEN NULL ELSE v_kr3 END,
      progress_percentage = v_kr3,
      metric_type = v_kr3_metric,
      unit = v_kr3_unit,
      updated_at = now()
  FROM public.individual_objectives io
  WHERE kr.individual_objective_id = io.id
    AND io.employee_id = p_employee_id
    AND io.organization_id = v_org
    AND kr.ai_kr_code = 'KR3';

  SELECT COUNT(*)
  INTO v_approved
  FROM public.social_media_plans p
  WHERE p.organization_id = v_org
    AND p.author_employee_id = p_employee_id
    AND p.production_approved;

  SELECT COUNT(*)
  INTO v_scheduled
  FROM public.social_media_plans p
  WHERE p.organization_id = v_org
    AND p.author_employee_id = p_employee_id
    AND p.production_approved
    AND p.production_approved_date IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.social_media_scheduled_posts sp
      WHERE sp.social_media_plan_id = p.id
        AND sp.scheduled_at BETWEEN p.production_approved_date - interval '7 days'
                                AND p.production_approved_date + interval '7 days'
    );

  v_kr5 := CASE
    WHEN COALESCE(v_approved, 0) = 0 THEN 0
    ELSE ROUND((100.0 * v_scheduled / v_approved)::numeric, 2)
  END;

  UPDATE public.key_results kr
  SET current_value = v_scheduled,
      progress_percentage = v_kr5,
      metric_type = 'percentage',
      unit = '%',
      updated_at = now()
  FROM public.individual_objectives io
  WHERE kr.individual_objective_id = io.id
    AND io.employee_id = p_employee_id
    AND io.organization_id = v_org
    AND kr.ai_kr_code = 'KR5';

  UPDATE public.individual_objectives io
  SET progress_percentage = scored.score,
      updated_at = now()
  FROM (
    SELECT io2.id,
      COALESCE(
        ROUND(
          (
            SUM(COALESCE(kr.weight, 0) * COALESCE(kr.progress_percentage, 0))
            / NULLIF(SUM(COALESCE(kr.weight, 0)), 0)
          )::numeric,
          2
        ),
        0
      ) AS score
    FROM public.individual_objectives io2
    JOIN public.key_results kr ON kr.individual_objective_id = io2.id
    WHERE io2.employee_id = p_employee_id
      AND io2.organization_id = v_org
      AND COALESCE(kr.metric_type, '') NOT IN ('manual', 'unrated')
    GROUP BY io2.id
  ) scored
  WHERE io.id = scored.id;
END;
$$;


ALTER FUNCTION "public"."ai_employee_refresh_krs"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_repeat_voices_ok"("p_voices" "text"[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$ SELECT COALESCE(bool_and(char_length(btrim(voice)) BETWEEN 1 AND 500), true) FROM unnest(COALESCE(p_voices, '{}'::text[])) AS voice; $$;


ALTER FUNCTION "public"."ai_employee_repeat_voices_ok"("p_voices" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_report_apply_priority"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_weekday smallint;
  v_zone text;
BEGIN
  SELECT routine.weekday
  INTO v_weekday
  FROM public.ai_employee_routines routine
  WHERE routine.employee_id = p_employee_id
    AND routine.organization_id = p_organization_id
    AND routine.action_code = 'work_report.weekly'
    AND routine.is_active;

  IF v_weekday IS NOT NULL THEN
    UPDATE public.ai_employee_routines AS daily
    SET weekdays = COALESCE((
          SELECT array_agg(day::smallint ORDER BY day)
          FROM unnest(daily.weekdays) AS day
          WHERE day IS DISTINCT FROM v_weekday
        ), '{}'::smallint[]),
        is_active = CASE
          WHEN COALESCE((
            SELECT count(*)
            FROM unnest(daily.weekdays) AS day
            WHERE day IS DISTINCT FROM v_weekday
          ), 0) = 0 THEN false
          ELSE daily.is_active
        END
    WHERE daily.employee_id = p_employee_id
      AND daily.organization_id = p_organization_id
      AND daily.action_code = 'work_report.daily'
      AND v_weekday = ANY (daily.weekdays);
  END IF;

  SELECT COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta')
  INTO v_zone
  FROM public.ai_employee_profiles profile
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = p_organization_id;
  v_zone := COALESCE(v_zone, 'Asia/Jakarta');

  UPDATE public.ai_employee_routines AS routine
  SET next_run_at = public.ai_employee_next_report_at(
    routine.employee_id,
    routine.organization_id,
    routine.action_code,
    routine.cadence,
    routine.weekday,
    routine.weekdays,
    routine.time_local,
    v_zone,
    clock_timestamp()
  )
  WHERE routine.employee_id = p_employee_id
    AND routine.organization_id = p_organization_id
    AND routine.is_active
    AND routine.action_code IN ('work_report.daily', 'work_report.weekly');
END;
$$;


ALTER FUNCTION "public"."ai_employee_report_apply_priority"("p_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_report_apply_priority"("p_employee_id" "uuid", "p_organization_id" "uuid") IS 'Membuang hari mingguan dari harian, mematikan harian yang kosong, lalu menghitung ulang slot harian dan mingguan.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_report_copies_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_email_1" "text", "p_email_2" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_one text;
  v_two text;
  v_reviewer text;
BEGIN
  PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id);
  v_one := public.ai_employee_report_email(p_email_1);
  v_two := public.ai_employee_report_email(p_email_2);
  IF v_one IS NOT NULL AND v_one = v_two THEN
    RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
  END IF;

  SELECT lower(btrim(reviewer.email))
  INTO v_reviewer
  FROM public.ai_employee_profiles profile
  LEFT JOIN public.employees reviewer
    ON reviewer.id = profile.reviewer_employee_id
   AND reviewer.organization_id = profile.organization_id
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_reviewer IS NOT NULL AND v_reviewer <> '' AND (v_one = v_reviewer OR v_two = v_reviewer) THEN
    RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
  END IF;

  UPDATE public.ai_employee_profiles
  SET report_copy_email_1 = v_one,
      report_copy_email_2 = v_two,
      report_sender_user_id = p_user_id
  WHERE employee_id = p_employee_id
    AND organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'ok', true,
    'report_copy_email_1', v_one,
    'report_copy_email_2', v_two,
    'report_sender_user_id', p_user_id
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_report_copies_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_email_1" "text", "p_email_2" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_report_copies_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_email_1" "text", "p_email_2" "text") IS 'Owner menyimpan paling banyak dua email tambahan dan mengingat user yang menyimpan sebagai nama pengirim.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_report_day_counts"("p_at" timestamp with time zone, "p_time_zone" "text", "p_exclude_weekday" smallint, "p_exclude_month_end" boolean) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_local timestamp;
BEGIN
  IF p_at IS NULL THEN
    RETURN false;
  END IF;
  v_local := timezone(p_time_zone, p_at);
  IF p_exclude_weekday IS NOT NULL
     AND EXTRACT(ISODOW FROM v_local)::integer = p_exclude_weekday
  THEN
    RETURN false;
  END IF;
  IF COALESCE(p_exclude_month_end, false)
     AND v_local::date = (date_trunc('month', v_local) + interval '1 month' - interval '1 day')::date
  THEN
    RETURN false;
  END IF;
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."ai_employee_report_day_counts"("p_at" timestamp with time zone, "p_time_zone" "text", "p_exclude_weekday" smallint, "p_exclude_month_end" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_report_day_counts"("p_at" timestamp with time zone, "p_time_zone" "text", "p_exclude_weekday" smallint, "p_exclude_month_end" boolean) IS 'True bila waktu lokal itu masuk hitungan. Weekday atau tanggal terakhir yang dikecualikan tidak masuk.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_report_email"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_email text := lower(btrim(COALESCE(p_value, '')));
BEGIN
  IF v_email = '' THEN
    RETURN NULL;
  END IF;
  IF char_length(v_email) > 320
     OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  THEN
    RAISE EXCEPTION 'invalid_email' USING ERRCODE = '22023';
  END IF;
  RETURN v_email;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_report_email"("p_value" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_report_email"("p_value" "text") IS 'Menormalisasi satu alamat laporan. Kosong menjadi null. Format salah ditolak.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_requeue_stuck_jobs"("p_at" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job public.ai_employee_jobs%ROWTYPE;
  v_count integer := 0;
  v_attempts integer;
BEGIN
  FOR v_job IN
    SELECT job.*
    FROM public.ai_employee_jobs AS job
    WHERE job.status IN ('claimed', 'running')
      AND job.claimed_at IS NOT NULL
      AND job.claimed_at <= p_at - interval '15 minutes'
    ORDER BY job.claimed_at, job.id
    FOR UPDATE OF job SKIP LOCKED
  LOOP
    v_attempts := v_job.attempts + 1;
    v_count := v_count + 1;
    IF v_attempts >= 3 THEN
      UPDATE public.ai_employee_jobs
      SET status = 'failed',
          attempts = v_attempts,
          reason = 'Job macet 3 kali.',
          finished_at = p_at,
          claim_token = NULL,
          updated_at = clock_timestamp()
      WHERE id = v_job.id;
      PERFORM public.ai_employee_notify_reviewer(
        v_job.employee_id,
        v_job.organization_id,
        'Job karyawan AI gagal',
        'Job macet 3 kali.',
        v_job.daily_task_id,
        v_job.plan_id
      );
    ELSE
      UPDATE public.ai_employee_jobs
      SET status = 'queued',
          attempts = v_attempts,
          claimed_at = NULL,
          claim_token = NULL,
          run_id = NULL,
          next_attempt_at = p_at,
          updated_at = clock_timestamp()
      WHERE id = v_job.id;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."ai_employee_requeue_stuck_jobs"("p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_require_owner"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = p_user_id
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) = 'owner'
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."ai_employee_require_owner"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_require_run"("p_employee_id" "uuid", "p_run_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_owner uuid;
  v_status text;
  v_is_ai boolean;
  v_active boolean;
  v_performance text;
BEGIN
  SELECT r.organization_id, r.employee_id, r.status, e.is_ai, p.is_active, p.performance_status
  INTO v_org, v_owner, v_status, v_is_ai, v_active, v_performance
  FROM public.ai_employee_runs r
  JOIN public.employees e
    ON e.id = r.employee_id
   AND e.organization_id IS NOT DISTINCT FROM r.organization_id
  LEFT JOIN public.ai_employee_profiles p ON p.employee_id = e.id
  WHERE r.id = p_run_id
  FOR UPDATE OF r;

  IF NOT FOUND OR v_owner IS DISTINCT FROM p_employee_id OR v_status IS DISTINCT FROM 'running' THEN
    RAISE EXCEPTION 'run_not_running' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(v_is_ai, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not_ai_employee' USING ERRCODE = '42501';
  END IF;

  IF v_active IS NOT TRUE OR v_performance = 'disabled' THEN
    RAISE EXCEPTION 'profile_inactive' USING ERRCODE = '42501';
  END IF;

  RETURN v_org;
END;
$$;


ALTER FUNCTION "public"."ai_employee_require_run"("p_employee_id" "uuid", "p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_reserve_model_call"("p_employee_id" "uuid", "p_run_id" "uuid", "p_commit" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_jakarta date;
  v_utc date;
  v_cap integer;
  v_used integer;
  v_org_limit integer;
  v_org_used integer;
  v_allowed boolean;
BEGIN
  v_org := public.ai_employee_require_run(p_employee_id, p_run_id);
  v_jakarta := (timezone('Asia/Jakarta', now()))::date;
  v_utc := (timezone('UTC', now()))::date;

  SELECT CASE WHEN performance_status = 'coaching' THEN 8 ELSE 1000 END
  INTO v_cap
  FROM public.ai_employee_profiles
  WHERE employee_id = p_employee_id;

  INSERT INTO public.ai_employee_model_calls (employee_id, usage_date, call_count)
  VALUES (p_employee_id, v_jakarta, 0)
  ON CONFLICT (employee_id, usage_date) DO NOTHING;

  SELECT call_count INTO v_used
  FROM public.ai_employee_model_calls
  WHERE employee_id = p_employee_id
    AND usage_date = v_jakarta
  FOR UPDATE;

  SELECT COALESCE(daily_limit, 50)
  INTO v_org_limit
  FROM public.organization_script_ai_config
  WHERE organization_id = v_org;

  IF v_org_limit IS NULL OR v_org_limit < 1 THEN
    v_org_limit := 50;
  END IF;

  SELECT COALESCE(count, 0)
  INTO v_org_used
  FROM public.script_ai_daily_usage
  WHERE organization_id = v_org
    AND usage_date = v_utc;

  v_org_used := COALESCE(v_org_used, 0);
  v_allowed := v_used < v_cap AND v_org_used < v_org_limit;

  IF COALESCE(p_commit, false) AND NOT v_allowed THEN
    RAISE EXCEPTION 'quota_exceeded' USING ERRCODE = '42501';
  END IF;

  IF COALESCE(p_commit, false) AND v_allowed THEN
    UPDATE public.ai_employee_model_calls
    SET call_count = call_count + 1,
        updated_at = now()
    WHERE employee_id = p_employee_id
      AND usage_date = v_jakarta;
    v_used := v_used + 1;
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_allowed,
    'used', v_used,
    'cap', v_cap,
    'usage_date', v_jakarta,
    'org_used', v_org_used,
    'org_limit', v_org_limit,
    'org_usage_date', v_utc
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_reserve_model_call"("p_employee_id" "uuid", "p_run_id" "uuid", "p_commit" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_count"("p_value" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT CASE
    WHEN p_value ~ '^[0-9]+$' THEN p_value::integer
    ELSE 0
  END;
$_$;


ALTER FUNCTION "public"."ai_employee_routine_count"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_finish"("p_routine_id" "uuid", "p_status" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_recipient_email" "text", "p_summary" "jsonb", "p_error" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_routine public.ai_employee_routines;
  v_status text := NULLIF(btrim(COALESCE(p_status, '')), '');
  v_summary jsonb := CASE
    WHEN p_summary IS NULL OR jsonb_typeof(p_summary) IS DISTINCT FROM 'object' THEN '{}'::jsonb
    ELSE p_summary
  END;
  v_results jsonb := '[]'::jsonb;
BEGIN
  IF p_routine_id IS NULL
     OR v_status NOT IN ('sent', 'failed', 'skipped')
     OR p_period_start IS NULL
     OR p_period_end IS NULL
     OR p_period_end <= p_period_start
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT routine.*
  INTO v_routine
  FROM public.ai_employee_routines routine
  WHERE routine.id = p_routine_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF jsonb_typeof(v_summary->'key_results') = 'array' THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'code', item->>'code',
      'title', left(COALESCE(item->>'title', ''), 120),
      'current_value', CASE
        WHEN (item->>'current_value') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (item->>'current_value')::numeric
        ELSE NULL
      END,
      'target_value', CASE
        WHEN (item->>'target_value') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (item->>'target_value')::numeric
        ELSE NULL
      END,
      'unit', left(COALESCE(item->>'unit', ''), 40),
      'progress_percentage', CASE
        WHEN (item->>'progress_percentage') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (item->>'progress_percentage')::numeric
        ELSE NULL
      END
    ) ORDER BY item->>'code'), '[]'::jsonb)
    INTO v_results
    FROM jsonb_array_elements(v_summary->'key_results') item
    WHERE item->>'code' IN ('KR1', 'KR2', 'KR3', 'KR4', 'KR5');
  END IF;

  v_summary := jsonb_build_object(
    'runs_succeeded', public.ai_employee_routine_count(v_summary->>'runs_succeeded'),
    'runs_failed', public.ai_employee_routine_count(v_summary->>'runs_failed'),
    'runs_other', public.ai_employee_routine_count(v_summary->>'runs_other'),
    'plans_created', public.ai_employee_routine_count(v_summary->>'plans_created'),
    'jobs_done', public.ai_employee_routine_count(v_summary->>'jobs_done'),
    'jobs_rejected', public.ai_employee_routine_count(v_summary->>'jobs_rejected'),
    'jobs_failed', public.ai_employee_routine_count(v_summary->>'jobs_failed'),
    'key_results', COALESCE(v_results, '[]'::jsonb)
  );

  INSERT INTO public.ai_employee_routine_deliveries (
    routine_id,
    employee_id,
    organization_id,
    period_start,
    period_end,
    status,
    recipient_email,
    summary,
    error
  ) VALUES (
    v_routine.id,
    v_routine.employee_id,
    v_routine.organization_id,
    p_period_start,
    p_period_end,
    v_status,
    left(COALESCE(p_recipient_email, ''), 320),
    v_summary,
    left(COALESCE(p_error, ''), 500)
  );

  UPDATE public.ai_employee_routines routine
  SET last_status = v_status,
      last_error = left(COALESCE(p_error, ''), 500),
      last_sent_at = CASE WHEN v_status = 'sent' THEN clock_timestamp() ELSE routine.last_sent_at END
  WHERE routine.id = v_routine.id;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_routine_finish"("p_routine_id" "uuid", "p_status" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_recipient_email" "text", "p_summary" "jsonb", "p_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_routine_finish"("p_routine_id" "uuid", "p_status" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_recipient_email" "text", "p_summary" "jsonb", "p_error" "text") IS 'Menutup satu percobaan kirim. Hanya status sent yang mengisi last_sent_at. next_run_at tidak digeser ulang.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_prepare"("p_routine_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_routine public.ai_employee_routines;
  v_name text;
  v_reviewer_name text;
  v_email text;
  v_zone text;
  v_active boolean;
  v_performance text;
  v_sender_id uuid;
  v_sender text;
  v_copy_1 text;
  v_copy_2 text;
  v_start timestamptz;
  v_end timestamptz := clock_timestamp();
  v_exclude_weekday smallint := NULL;
  v_exclude_month_end boolean := false;
  v_work_local timestamp;
  v_daily_skip boolean := false;
BEGIN
  IF p_routine_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  SELECT routine.* INTO v_routine FROM public.ai_employee_routines routine WHERE routine.id = p_routine_id;
  IF NOT FOUND OR v_routine.action_code NOT IN ('work_report.daily', 'work_report.weekly', 'work_report.monthly') THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT employee.full_name, profile.is_active, profile.performance_status,
         COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta'),
         NULLIF(btrim(reviewer.email), ''), NULLIF(btrim(reviewer.full_name), ''),
         profile.report_copy_email_1, profile.report_copy_email_2, profile.report_sender_user_id
  INTO v_name, v_active, v_performance, v_zone, v_email, v_reviewer_name, v_copy_1, v_copy_2, v_sender_id
  FROM public.employees employee
  JOIN public.ai_employee_profiles profile ON profile.employee_id = employee.id AND profile.organization_id = employee.organization_id
  LEFT JOIN public.employees reviewer ON reviewer.id = profile.reviewer_employee_id AND reviewer.organization_id = employee.organization_id
  WHERE employee.id = v_routine.employee_id AND employee.organization_id = v_routine.organization_id AND COALESCE(employee.is_ai, false);
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;
  SELECT NULLIF(btrim(sender.full_name), '') INTO v_sender FROM public.profiles sender WHERE sender.user_id = v_sender_id;
  v_sender := COALESCE(v_sender, v_reviewer_name, NULLIF(btrim(v_name), ''));
  IF v_routine.action_code = 'work_report.daily' THEN
    v_end := date_trunc('day', timezone(v_zone, clock_timestamp())) AT TIME ZONE v_zone;
    v_start := v_end - interval '1 day';
    SELECT routine.weekday INTO v_exclude_weekday FROM public.ai_employee_routines routine
    WHERE routine.employee_id = v_routine.employee_id AND routine.organization_id = v_routine.organization_id AND routine.action_code = 'work_report.weekly' AND routine.is_active;
    SELECT true INTO v_exclude_month_end FROM public.ai_employee_routines routine
    WHERE routine.employee_id = v_routine.employee_id AND routine.organization_id = v_routine.organization_id AND routine.action_code = 'work_report.monthly' AND routine.is_active;
    v_exclude_month_end := COALESCE(v_exclude_month_end, false);
    v_work_local := timezone(v_zone, v_start);
    v_daily_skip := NOT (EXTRACT(ISODOW FROM v_work_local)::integer = ANY (COALESCE(v_routine.weekdays, '{}'::smallint[])));
    IF v_exclude_weekday IS NOT NULL AND EXTRACT(ISODOW FROM v_work_local)::integer = v_exclude_weekday THEN
      v_daily_skip := true;
    END IF;
    IF v_exclude_month_end AND v_work_local::date = (date_trunc('month', v_work_local) + interval '1 month' - interval '1 day')::date THEN
      v_daily_skip := true;
    END IF;
  ELSIF v_routine.cadence = 'weekly' THEN
    IF v_routine.last_sent_at IS NOT NULL AND v_routine.last_sent_at < v_end THEN
      v_start := v_routine.last_sent_at;
    ELSE
      v_start := v_end - interval '7 days';
    END IF;
    SELECT true INTO v_exclude_month_end FROM public.ai_employee_routines routine
    WHERE routine.employee_id = v_routine.employee_id AND routine.organization_id = v_routine.organization_id AND routine.action_code = 'work_report.monthly' AND routine.is_active;
    v_exclude_month_end := COALESCE(v_exclude_month_end, false);
  ELSIF v_routine.cadence = 'monthly' THEN
    IF v_routine.last_sent_at IS NOT NULL AND v_routine.last_sent_at < v_end THEN
      v_start := v_routine.last_sent_at;
    ELSE
      v_start := date_trunc('month', timezone(v_zone, v_end)) AT TIME ZONE v_zone;
    END IF;
  ELSE
    v_start := v_end - interval '24 hours';
  END IF;
  IF v_copy_1 IS NOT NULL AND lower(v_copy_1) = lower(COALESCE(v_email, '')) THEN v_copy_1 := NULL; END IF;
  IF v_copy_2 IS NOT NULL AND lower(v_copy_2) = lower(COALESCE(v_email, '')) THEN v_copy_2 := NULL; END IF;
  IF v_copy_1 IS NOT NULL AND v_copy_1 = v_copy_2 THEN v_copy_2 := NULL; END IF;
  RETURN jsonb_build_object(
    'routine_id', v_routine.id,
    'employee_id', v_routine.employee_id,
    'organization_id', v_routine.organization_id,
    'action_code', v_routine.action_code,
    'employee_name', COALESCE(v_name, ''),
    'sender_name', COALESCE(v_sender, ''),
    'recipient_email', v_email,
    'copy_emails', COALESCE((SELECT jsonb_agg(item.email ORDER BY item.slot) FROM (SELECT 1 AS slot, v_copy_1 AS email UNION ALL SELECT 2, v_copy_2) item WHERE item.email IS NOT NULL), '[]'::jsonb),
    'period_start', v_start,
    'period_end', v_end,
    'summary', public.ai_employee_routine_summary(v_routine.employee_id, v_routine.organization_id, v_start, v_end, v_exclude_weekday, v_exclude_month_end, v_zone),
    'skip_reason', CASE
      WHEN v_active IS NOT TRUE OR v_performance = 'disabled' THEN 'profile_inactive'
      WHEN v_email IS NULL THEN 'reviewer_email_missing'
      WHEN v_routine.action_code = 'work_report.daily' AND v_daily_skip THEN 'outside_work_day'
      ELSE NULL
    END
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_routine_prepare"("p_routine_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_routine_prepare"("p_routine_id" "uuid") IS 'Menyiapkan satu irama. Harian menghitung hari kalender yang baru selesai. Nama pengirim dari profile yang menyimpan, atau nama reviewer. Email tambahan tidak menggantikan penerima utama.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_summary"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_succeeded integer;
  v_failed integer;
  v_other integer;
  v_plans integer;
  v_done integer;
  v_rejected integer;
  v_job_failed integer;
  v_key_results jsonb;
BEGIN
  SELECT
    count(*) FILTER (WHERE run.status = 'succeeded')::integer,
    count(*) FILTER (WHERE run.status = 'failed')::integer,
    count(*) FILTER (WHERE run.status NOT IN ('succeeded', 'failed'))::integer,
    COALESCE(sum(run.plan_count), 0)::integer
  INTO v_succeeded, v_failed, v_other, v_plans
  FROM public.ai_employee_runs run
  WHERE run.employee_id = p_employee_id
    AND run.organization_id = p_organization_id
    AND run.started_at >= p_start
    AND run.started_at < p_end;

  SELECT
    count(*) FILTER (WHERE job.status = 'done')::integer,
    count(*) FILTER (WHERE job.status = 'rejected')::integer,
    count(*) FILTER (WHERE job.status = 'failed')::integer
  INTO v_done, v_rejected, v_job_failed
  FROM public.ai_employee_jobs job
  WHERE job.employee_id = p_employee_id
    AND job.organization_id = p_organization_id
    AND job.finished_at >= p_start
    AND job.finished_at < p_end;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'code', kr.ai_kr_code,
    'title', left(COALESCE(kr.title, ''), 120),
    'current_value', kr.current_value,
    'target_value', kr.target_value,
    'unit', kr.unit,
    'progress_percentage', kr.progress_percentage
  ) ORDER BY kr.ai_kr_code), '[]'::jsonb)
  INTO v_key_results
  FROM public.key_results kr
  JOIN public.individual_objectives objective
    ON objective.id = kr.individual_objective_id
  WHERE objective.organization_id = p_organization_id
    AND objective.employee_id = p_employee_id
    AND kr.ai_kr_code IN ('KR1', 'KR2', 'KR3', 'KR4', 'KR5');

  RETURN jsonb_build_object(
    'runs_succeeded', COALESCE(v_succeeded, 0),
    'runs_failed', COALESCE(v_failed, 0),
    'runs_other', COALESCE(v_other, 0),
    'plans_created', COALESCE(v_plans, 0),
    'jobs_done', COALESCE(v_done, 0),
    'jobs_rejected', COALESCE(v_rejected, 0),
    'jobs_failed', COALESCE(v_job_failed, 0),
    'key_results', COALESCE(v_key_results, '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_routine_summary"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_routine_summary"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) IS 'Angka meja kerja karyawan AI: run, plan, antrean, dan KR1–KR5. Bukan laporan HRD atau payroll.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_summary"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_exclude_weekday" smallint, "p_exclude_month_end" boolean, "p_time_zone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text := COALESCE(NULLIF(btrim(p_time_zone), ''), 'Asia/Jakarta');
  v_succeeded integer;
  v_failed integer;
  v_other integer;
  v_plans integer;
  v_done integer;
  v_rejected integer;
  v_job_failed integer;
  v_key_results jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = v_zone) THEN
    v_zone := 'Asia/Jakarta';
  END IF;

  SELECT
    count(*) FILTER (WHERE run.status = 'succeeded')::integer,
    count(*) FILTER (WHERE run.status = 'failed')::integer,
    count(*) FILTER (WHERE run.status NOT IN ('succeeded', 'failed'))::integer,
    COALESCE(sum(run.plan_count), 0)::integer
  INTO v_succeeded, v_failed, v_other, v_plans
  FROM public.ai_employee_runs run
  WHERE run.employee_id = p_employee_id
    AND run.organization_id = p_organization_id
    AND run.started_at >= p_start
    AND run.started_at < p_end
    AND public.ai_employee_report_day_counts(
      run.started_at,
      v_zone,
      p_exclude_weekday,
      p_exclude_month_end
    );

  SELECT
    count(*) FILTER (WHERE job.status = 'done')::integer,
    count(*) FILTER (WHERE job.status = 'rejected')::integer,
    count(*) FILTER (WHERE job.status = 'failed')::integer
  INTO v_done, v_rejected, v_job_failed
  FROM public.ai_employee_jobs job
  WHERE job.employee_id = p_employee_id
    AND job.organization_id = p_organization_id
    AND job.finished_at >= p_start
    AND job.finished_at < p_end
    AND public.ai_employee_report_day_counts(
      job.finished_at,
      v_zone,
      p_exclude_weekday,
      p_exclude_month_end
    );

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'code', kr.ai_kr_code,
    'title', left(COALESCE(kr.title, ''), 120),
    'current_value', kr.current_value,
    'target_value', kr.target_value,
    'unit', kr.unit,
    'progress_percentage', kr.progress_percentage
  ) ORDER BY kr.ai_kr_code), '[]'::jsonb)
  INTO v_key_results
  FROM public.key_results kr
  JOIN public.individual_objectives objective
    ON objective.id = kr.individual_objective_id
  WHERE objective.organization_id = p_organization_id
    AND objective.employee_id = p_employee_id
    AND kr.ai_kr_code IN ('KR1', 'KR2', 'KR3', 'KR4', 'KR5');

  RETURN jsonb_build_object(
    'runs_succeeded', COALESCE(v_succeeded, 0),
    'runs_failed', COALESCE(v_failed, 0),
    'runs_other', COALESCE(v_other, 0),
    'plans_created', COALESCE(v_plans, 0),
    'jobs_done', COALESCE(v_done, 0),
    'jobs_rejected', COALESCE(v_rejected, 0),
    'jobs_failed', COALESCE(v_job_failed, 0),
    'key_results', COALESCE(v_key_results, '[]'::jsonb)
  );
END;
$$;


