COMMENT ON FUNCTION "public"."ai_employee_routine_summary"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone, "p_exclude_weekday" smallint, "p_exclude_month_end" boolean, "p_time_zone" "text") IS 'Hitungan pekerjaan content planner. Weekday atau tanggal terakhir yang dikecualikan tidak masuk. KR tetap snapshot saat ini.';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."ai_employee_routines" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "action_code" "text" NOT NULL,
    "cadence" "text" NOT NULL,
    "weekday" smallint,
    "time_local" time without time zone NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "next_run_at" timestamp with time zone,
    "last_sent_at" timestamp with time zone,
    "last_status" "text",
    "last_error" "text" DEFAULT ''::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "weekdays" smallint[] DEFAULT '{}'::smallint[] NOT NULL,
    CONSTRAINT "ai_employee_routines_action_check" CHECK (("action_code" = ANY (ARRAY['work_report.daily'::"text", 'work_report.weekly'::"text", 'work_report.monthly'::"text"]))),
    CONSTRAINT "ai_employee_routines_cadence_check" CHECK (("cadence" = ANY (ARRAY['days'::"text", 'weekly'::"text", 'monthly'::"text"]))),
    CONSTRAINT "ai_employee_routines_error_length" CHECK (("char_length"("last_error") <= 500)),
    CONSTRAINT "ai_employee_routines_status_check" CHECK ((("last_status" IS NULL) OR ("last_status" = ANY (ARRAY['sent'::"text", 'failed'::"text", 'skipped'::"text"])))),
    CONSTRAINT "ai_employee_routines_weekday_check" CHECK (((("action_code" = 'work_report.daily'::"text") AND ("cadence" = 'days'::"text") AND ("weekday" IS NULL) AND ("weekdays" <@ ARRAY[(1)::smallint, (2)::smallint, (3)::smallint, (4)::smallint, (5)::smallint, (6)::smallint, (7)::smallint]) AND ((("cardinality"("weekdays") >= 1) AND ("cardinality"("weekdays") <= 7)) OR (("cardinality"("weekdays") = 0) AND ("is_active" IS NOT TRUE)))) OR (("action_code" = 'work_report.weekly'::"text") AND ("cadence" = 'weekly'::"text") AND (("weekday" >= 1) AND ("weekday" <= 7)) AND ("cardinality"("weekdays") = 0)) OR (("action_code" = 'work_report.monthly'::"text") AND ("cadence" = 'monthly'::"text") AND ("weekday" IS NULL) AND ("cardinality"("weekdays") = 0))))
);


ALTER TABLE "public"."ai_employee_routines" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_view"("p_routine" "public"."ai_employee_routines") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
