    AS $$
  SELECT jsonb_build_object(
    'action_code', p_routine.action_code,
    'cadence', p_routine.cadence,
    'weekday', p_routine.weekday,
    'weekdays', p_routine.weekdays,
    'time_local', to_char(p_routine.time_local, 'HH24:MI'),
    'is_active', p_routine.is_active,
    'next_run_at', p_routine.next_run_at,
    'last_sent_at', p_routine.last_sent_at,
    'last_status', p_routine.last_status
  );
$$;


ALTER FUNCTION "public"."ai_employee_routine_view"("p_routine" "public"."ai_employee_routines") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_routine_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" integer, "p_time_local" time without time zone, "p_is_active" boolean, "p_weekdays" integer[] DEFAULT NULL::integer[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action text := NULLIF(btrim(COALESCE(p_action_code, '')), '');
  v_cadence text := NULLIF(btrim(COALESCE(p_cadence, '')), '');
  v_weekday smallint;
  v_weekdays smallint[] := '{}'::smallint[];
  v_block smallint;
  v_active boolean := p_is_active;
  v_previous public.ai_employee_routines;
  v_next public.ai_employee_routines;
BEGIN
  PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id);
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_time_local IS NULL OR p_is_active IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_weekdays IS NOT NULL AND EXISTS (
    SELECT 1 FROM unnest(p_weekdays) AS day WHERE day IS NULL OR day < 1 OR day > 7
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT day::smallint ORDER BY day::smallint), '{}'::smallint[])
  INTO v_weekdays
  FROM unnest(COALESCE(p_weekdays, ARRAY[]::integer[])) AS day;

  IF v_action = 'work_report.daily' AND v_cadence = 'days' THEN
    v_weekday := NULL;
    SELECT routine.weekday
    INTO v_block
    FROM public.ai_employee_routines routine
    WHERE routine.employee_id = p_employee_id
      AND routine.organization_id = p_organization_id
      AND routine.action_code = 'work_report.weekly'
      AND routine.is_active;
    IF v_block IS NOT NULL THEN
      SELECT COALESCE(array_agg(day::smallint ORDER BY day), '{}'::smallint[])
      INTO v_weekdays
      FROM unnest(v_weekdays) AS day
      WHERE day IS DISTINCT FROM v_block;
    END IF;
    IF COALESCE(cardinality(v_weekdays), 0) = 0 THEN
      v_active := false;
    ELSIF cardinality(v_weekdays) > 7 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  ELSIF v_action = 'work_report.weekly' AND v_cadence = 'weekly' AND p_weekday BETWEEN 1 AND 7 THEN
    v_weekday := p_weekday::smallint;
    v_weekdays := '{}'::smallint[];
  ELSIF v_action = 'work_report.monthly' AND v_cadence = 'monthly' THEN
    v_weekday := NULL;
    v_weekdays := '{}'::smallint[];
  ELSE
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT routine.*
  INTO v_previous
  FROM public.ai_employee_routines routine
  WHERE routine.employee_id = p_employee_id
    AND routine.organization_id = p_organization_id
    AND routine.action_code = v_action
  FOR UPDATE;

  BEGIN
    INSERT INTO public.ai_employee_routines (
      employee_id,
      organization_id,
      action_code,
      cadence,
      weekday,
      weekdays,
      time_local,
      is_active
    ) VALUES (
      p_employee_id,
      p_organization_id,
      v_action,
      v_cadence,
      v_weekday,
      v_weekdays,
      p_time_local,
      v_active
    )
    ON CONFLICT (employee_id, action_code) DO UPDATE
    SET cadence = EXCLUDED.cadence,
        weekday = EXCLUDED.weekday,
        weekdays = EXCLUDED.weekdays,
        time_local = EXCLUDED.time_local,
        is_active = EXCLUDED.is_active
    RETURNING *
    INTO v_next;
  EXCEPTION
    WHEN check_violation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END;

  PERFORM public.ai_employee_report_apply_priority(p_employee_id, p_organization_id);

  SELECT routine.*
  INTO v_next
  FROM public.ai_employee_routines routine
  WHERE routine.id = v_next.id;

  RETURN jsonb_build_object(
    'ok', true,
    'previous', CASE WHEN v_previous.id IS NULL THEN NULL ELSE public.ai_employee_routine_view(v_previous) END,
    'routine', public.ai_employee_routine_view(v_next)
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_routine_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" integer, "p_time_local" time without time zone, "p_is_active" boolean, "p_weekdays" integer[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_routine_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_action_code" "text", "p_cadence" "text", "p_weekday" integer, "p_time_local" time without time zone, "p_is_active" boolean, "p_weekdays" integer[]) IS 'Owner menyimpan satu irama. Menyimpan mingguan membuang hari yang sama dari harian. Harian tanpa hari tersisa dimatikan.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_routines_set_next_run"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text;
BEGIN
  IF NEW.cadence IN ('weekly', 'monthly', 'daily', 'mon_thu') THEN
    NEW.weekdays := '{}'::smallint[];
  END IF;
  IF NEW.cadence IN ('days', 'monthly', 'daily', 'mon_thu') THEN
    NEW.weekday := NULL;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.next_run_at IS NOT NULL
     AND NEW.cadence IS NOT DISTINCT FROM OLD.cadence
     AND NEW.weekday IS NOT DISTINCT FROM OLD.weekday
     AND NEW.weekdays IS NOT DISTINCT FROM OLD.weekdays
     AND NEW.time_local IS NOT DISTINCT FROM OLD.time_local
     AND (NEW.is_active IS NOT TRUE OR OLD.is_active IS TRUE)
  THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(NULLIF(btrim(time_zone), ''), 'Asia/Jakarta')
  INTO v_zone
  FROM public.ai_employee_profiles
  WHERE employee_id = NEW.employee_id
    AND organization_id = NEW.organization_id;

  NEW.updated_at := clock_timestamp();
  NEW.next_run_at := public.ai_employee_next_report_at(
    NEW.employee_id,
    NEW.organization_id,
    NEW.action_code,
    NEW.cadence,
    NEW.weekday,
    NEW.weekdays,
    NEW.time_local,
    COALESCE(v_zone, 'Asia/Jakarta'),
    clock_timestamp()
  );
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_routines_set_next_run"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_run_finish"("p_employee_id" "uuid", "p_run_id" "uuid", "p_status" "text", "p_model_calls" integer, "p_plan_count" integer, "p_object_ids" "uuid"[], "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_event text;
  v_title text;
  v_body text;
BEGIN
  IF p_status NOT IN ('succeeded', 'deferred', 'late', 'failed', 'returned') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  v_org := public.ai_employee_require_run(p_employee_id, p_run_id);

  UPDATE public.ai_employee_runs
  SET status = p_status,
      finished_at = now(),
      model_calls = COALESCE(p_model_calls, model_calls),
      plan_count = COALESCE(p_plan_count, plan_count),
      object_ids = COALESCE(p_object_ids, object_ids),
      note = COALESCE(p_note, note)
  WHERE id = p_run_id
    AND employee_id = p_employee_id
    AND organization_id = v_org
    AND status = 'running';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'run_not_running' USING ERRCODE = '42501';
  END IF;

  IF p_status = 'succeeded' THEN
    RETURN;
  END IF;

  v_event := CASE p_status
    WHEN 'failed' THEN 'run_failed'
    WHEN 'late' THEN 'run_late'
    WHEN 'deferred' THEN 'run_deferred'
    ELSE 'revision_returned'
  END;

  v_title := CASE p_status
    WHEN 'failed' THEN 'Rencana karyawan AI gagal'
    WHEN 'late' THEN 'Rencana karyawan AI melewati batas'
    WHEN 'deferred' THEN 'Rencana karyawan AI tertunda karena kuota'
    ELSE 'Revisi dikembalikan ke reviewer'
  END;

  v_body := v_title;
  PERFORM public.ai_employee_notify_reviewer(p_employee_id, v_event, v_title, v_body);
END;
$$;


ALTER FUNCTION "public"."ai_employee_run_finish"("p_employee_id" "uuid", "p_run_id" "uuid", "p_status" "text", "p_model_calls" integer, "p_plan_count" integer, "p_object_ids" "uuid"[], "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_run_log"("p_employee_id" "uuid", "p_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_month date;
  v_from timestamptz;
  v_to timestamptz;
  v_summary jsonb;
  v_rows jsonb;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, false);
  v_month := date_trunc('month', COALESCE(p_month, timezone('Asia/Jakarta', now())::date))::date;
  v_from := v_month::timestamp AT TIME ZONE 'Asia/Jakarta';
  v_to := (v_month + interval '1 month')::timestamp AT TIME ZONE 'Asia/Jakarta';

  WITH runs AS (
    SELECT run.*
    FROM public.ai_employee_runs run
    WHERE run.employee_id = p_employee_id
      AND run.organization_id = v_org
      AND run.sop_code IN ('SOP1', 'SOP2', 'SOP3', 'SOP4')
      AND run.started_at >= v_from
      AND run.started_at < v_to
  ),
  plans AS (
    SELECT plan.id, plan.thinking_idea_id
    FROM runs
    CROSS JOIN LATERAL unnest(COALESCE(runs.object_ids, '{}'::uuid[])) AS object_id
    JOIN public.social_media_plans plan
      ON plan.id = object_id AND plan.organization_id = v_org
  )
  SELECT jsonb_build_object(
    'runs', (SELECT count(*) FROM runs),
    'succeeded', (SELECT count(*) FROM runs WHERE status = 'succeeded'),
    'failed', (SELECT count(*) FROM runs WHERE status = 'failed'),
    'deferred', (SELECT count(*) FROM runs WHERE status IN ('deferred', 'late')),
    'running', (SELECT count(*) FROM runs WHERE status = 'running'),
    'plans', (SELECT count(*) FROM plans),
    'unique_ideas', (SELECT count(DISTINCT thinking_idea_id) FROM plans)
  )
  INTO v_summary;

  SELECT COALESCE(jsonb_agg(row_data ORDER BY started_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT run.started_at, jsonb_build_object(
      'id', run.id,
      'sop_code', run.sop_code,
      'status', run.status,
      'trigger_source', run.trigger_source,
      'started_at', run.started_at,
      'finished_at', run.finished_at,
      'note', left(COALESCE(run.note, ''), 200),
      'plan_count', COALESCE(run.plan_count, 0),
      'attempt', CASE
        WHEN run.attempted_idea_id IS NULL AND run.attempted_pillar_id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'chain', CASE WHEN run.attempted_idea_id IS NULL THEN NULL
            ELSE public.ai_employee_idea_chain(v_org, run.attempted_idea_id) END,
          'pillar_id', run.attempted_pillar_id,
          'pillar_name', (
            SELECT pillar.name FROM public.content_pillars pillar
            WHERE pillar.id = run.attempted_pillar_id
              AND (pillar.organization_id = v_org OR pillar.is_default)
          )
        )
      END,
      'plans', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', plan.id,
          'title', left(COALESCE(plan.title, ''), 200),
          'post_date', plan.post_date,
          'pillar_id', plan.content_pillar_id,
          'pillar_name', pillar.name,
          'chain', CASE WHEN plan.thinking_idea_id IS NULL THEN NULL
            ELSE public.ai_employee_idea_chain(v_org, plan.thinking_idea_id) END,
          'idea_month_count', CASE WHEN plan.thinking_idea_id IS NULL THEN 0 ELSE (
            SELECT count(*)
            FROM public.social_media_plans used
            WHERE used.organization_id = v_org
              AND used.thinking_idea_id = plan.thinking_idea_id
              AND used.created_at >= v_from
              AND used.created_at < v_to
          ) END,
          'canva', (
            SELECT jsonb_build_object(
              'status', canva.status,
              'images_ready', canva.images_ready,
              'logo_placed', canva.logo_placed,
              'error', left(COALESCE(canva.error, ''), 160),
              'design_url', canva.design_url
            )
            FROM public.canva_carousel_runs canva
            WHERE canva.social_media_plan_id = plan.id
          )
        ) ORDER BY plan.created_at)
        FROM unnest(COALESCE(run.object_ids, '{}'::uuid[])) AS object_id
        JOIN public.social_media_plans plan
          ON plan.id = object_id AND plan.organization_id = v_org
        LEFT JOIN public.content_pillars pillar
          ON pillar.id = plan.content_pillar_id
      ), '[]'::jsonb)
    ) AS row_data
    FROM public.ai_employee_runs run
    WHERE run.employee_id = p_employee_id
      AND run.organization_id = v_org
      AND run.sop_code IN ('SOP1', 'SOP2', 'SOP3', 'SOP4')
      AND run.started_at >= v_from
      AND run.started_at < v_to
    ORDER BY run.started_at DESC
    LIMIT 300
  ) listed;

  RETURN jsonb_build_object(
    'month', to_char(v_month, 'YYYY-MM'),
    'summary', v_summary,
    'rows', v_rows
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_run_log"("p_employee_id" "uuid", "p_month" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_run_start"("p_employee_id" "uuid", "p_sop_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_is_ai boolean;
  v_active boolean;
  v_performance text;
  v_run uuid;
  v_sop text := NULLIF(btrim(COALESCE(p_sop_code, '')), '');
BEGIN
  SELECT e.organization_id, e.is_ai, p.is_active, p.performance_status
  INTO v_org, v_is_ai, v_active, v_performance
  FROM public.employees e
  LEFT JOIN public.ai_employee_profiles p
    ON p.employee_id = e.id
   AND p.organization_id IS NOT DISTINCT FROM e.organization_id
  WHERE e.id = p_employee_id
  FOR UPDATE OF e;

  IF NOT FOUND OR v_org IS NULL OR COALESCE(v_is_ai, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not_ai_employee' USING ERRCODE = '42501';
  END IF;

  IF v_active IS NOT TRUE OR v_performance = 'disabled' THEN
    RAISE EXCEPTION 'profile_inactive' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.ai_employee_runs (employee_id, organization_id, sop_code, status, trigger_source)
  VALUES (
    p_employee_id,
    v_org,
    v_sop,
    'running',
    CASE v_sop WHEN 'SOP1' THEN 'schedule' WHEN 'CHAT' THEN 'chat' ELSE 'job' END
  )
  RETURNING id INTO v_run;

  RETURN v_run;
END;
$$;


ALTER FUNCTION "public"."ai_employee_run_start"("p_employee_id" "uuid", "p_sop_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_saved_catalog"("p_employee_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_services uuid[];
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  SELECT brief.service_ids
  INTO v_services
  FROM public.ai_employee_briefs brief
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;
  IF v_services IS NULL OR cardinality(v_services) <> 1 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.services svc
    WHERE svc.id = v_services[1]
      AND svc.organization_id = v_org
      AND COALESCE(svc.is_active, true)
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  RETURN v_services[1];
END;
$$;


ALTER FUNCTION "public"."ai_employee_saved_catalog"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_schedule_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_sop_code" "text", "p_cadence" "text", "p_weekday" integer, "p_weekdays" smallint[], "p_start_local" time without time zone, "p_plan_count" integer, "p_start_times" time without time zone[], "p_is_active" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_code text := NULLIF(btrim(COALESCE(p_sop_code, '')), '');
  v_cadence text := NULLIF(btrim(COALESCE(p_cadence, '')), '');
  v_days smallint[];
  v_times time[];
  v_id uuid;
  v_prev jsonb;
  v_weekday smallint;
  v_start time;
  v_count smallint;
  v_active boolean;
  v_next timestamptz;
  v_saved_times time[];
BEGIN
  PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id);
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_code IS NULL
    OR v_cadence NOT IN ('days', 'weekly', 'monthly')
    OR p_start_local IS NULL
    OR p_plan_count IS NULL
    OR p_plan_count < 1
    OR p_plan_count > 7
    OR p_is_active IS NULL
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF v_code = 'SOP1' AND v_cadence <> 'days' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(DISTINCT day ORDER BY day), ARRAY[]::smallint[])
  INTO v_days
  FROM unnest(COALESCE(p_weekdays, ARRAY[]::smallint[])) AS day
  WHERE day BETWEEN 1 AND 7;

  SELECT COALESCE(array_agg(DISTINCT slot ORDER BY slot), ARRAY[]::time[])
  INTO v_times
  FROM unnest(COALESCE(NULLIF(p_start_times, ARRAY[]::time[]), ARRAY[p_start_local])) AS slot
  WHERE slot IS NOT NULL;

  IF v_code = 'SOP1' THEN
    IF NOT public.ai_employee_start_times_ok(v_times) THEN
      RAISE EXCEPTION 'times_too_close' USING ERRCODE = '22023';
    END IF;
    p_plan_count := 1;
    p_start_local := v_times[1];
  ELSE
    v_times := ARRAY[p_start_local];
  END IF;

  IF v_cadence = 'weekly' AND (p_weekday IS NULL OR p_weekday < 1 OR p_weekday > 7) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF v_cadence = 'days' AND p_is_active AND COALESCE(cardinality(v_days), 0) < 1 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT schedule.id
  INTO v_id
  FROM public.ai_employee_schedules schedule
  WHERE schedule.employee_id = p_employee_id
    AND schedule.organization_id = p_organization_id
    AND schedule.sop_code = v_code
    AND schedule.cadence = v_cadence
  FOR UPDATE;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'schedule_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT jsonb_build_object(
    'sop_code', schedule.sop_code,
    'cadence', schedule.cadence,
    'weekday', schedule.weekday,
    'weekdays', schedule.weekdays,
    'start_local', to_char(schedule.start_local, 'HH24:MI'),
    'start_times', COALESCE((
      SELECT jsonb_agg(to_char(slot, 'HH24:MI') ORDER BY slot)
      FROM unnest(schedule.start_times) AS slot
    ), '[]'::jsonb),
    'plan_count', schedule.plan_count,
    'is_active', schedule.is_active,
    'next_run_at', schedule.next_run_at
  )
  INTO v_prev
  FROM public.ai_employee_schedules schedule
  WHERE schedule.id = v_id;

  BEGIN
    UPDATE public.ai_employee_schedules schedule
    SET weekday = CASE WHEN v_cadence = 'weekly' THEN p_weekday::smallint ELSE NULL END,
        weekdays = CASE WHEN v_cadence = 'days' THEN v_days ELSE ARRAY[]::smallint[] END,
        start_local = p_start_local,
        due_local = p_start_local,
        start_times = v_times,
        plan_count = p_plan_count::smallint,
        is_active = p_is_active
    WHERE schedule.id = v_id
    RETURNING schedule.weekday, schedule.start_local, schedule.plan_count, schedule.is_active, schedule.next_run_at, schedule.start_times
    INTO v_weekday, v_start, v_count, v_active, v_next, v_saved_times;
  EXCEPTION
    WHEN check_violation OR numeric_value_out_of_range THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END;

  IF v_code = 'SOP1' THEN
    UPDATE public.ai_employee_schedules schedule
    SET is_active = false
    WHERE schedule.employee_id = p_employee_id
      AND schedule.organization_id = p_organization_id
      AND schedule.sop_code = v_code
      AND schedule.cadence IN ('weekly', 'monthly');
  ELSIF v_cadence = 'weekly' AND p_is_active THEN
    UPDATE public.ai_employee_schedules schedule
    SET weekdays = COALESCE((
          SELECT array_agg(day ORDER BY day)
          FROM unnest(schedule.weekdays) AS day
          WHERE day IS DISTINCT FROM p_weekday::smallint
        ), ARRAY[]::smallint[]),
        is_active = CASE
          WHEN cardinality(array_remove(schedule.weekdays, p_weekday::smallint)) = 0 THEN false
          ELSE schedule.is_active
        END
    WHERE schedule.employee_id = p_employee_id
      AND schedule.organization_id = p_organization_id
      AND schedule.sop_code = v_code
      AND schedule.cadence = 'days';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'previous', v_prev,
    'schedule', jsonb_build_object(
      'sop_code', v_code,
      'cadence', v_cadence,
      'weekday', v_weekday,
      'weekdays', CASE WHEN v_cadence = 'days' THEN v_days ELSE ARRAY[]::smallint[] END,
      'start_local', to_char(v_start, 'HH24:MI'),
      'start_times', COALESCE((
        SELECT jsonb_agg(to_char(slot, 'HH24:MI') ORDER BY slot)
        FROM unnest(v_saved_times) AS slot
      ), '[]'::jsonb),
      'plan_count', v_count,
      'is_active', v_active,
      'next_run_at', v_next
    )
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_schedule_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_sop_code" "text", "p_cadence" "text", "p_weekday" integer, "p_weekdays" smallint[], "p_start_local" time without time zone, "p_plan_count" integer, "p_start_times" time without time zone[], "p_is_active" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_schedule_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_sop_code" "text", "p_cadence" "text", "p_weekday" integer, "p_weekdays" smallint[], "p_start_local" time without time zone, "p_plan_count" integer, "p_start_times" time without time zone[], "p_is_active" boolean) IS 'Mengubah jadwal yang sudah ada. SOP1 hanya harian, satu plan per jam, jarak minimal satu jam.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_schedules_fill_start_times"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.start_times IS NULL OR cardinality(NEW.start_times) = 0 THEN
    NEW.start_times := ARRAY[COALESCE(NEW.start_local, TIME '09:00')];
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_schedules_fill_start_times"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_schedules_set_next_run"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.cadence IS NOT DISTINCT FROM OLD.cadence
     AND NEW.weekday IS NOT DISTINCT FROM OLD.weekday
     AND NEW.weekdays IS NOT DISTINCT FROM OLD.weekdays
     AND NEW.start_local IS NOT DISTINCT FROM OLD.start_local
     AND NEW.start_times IS NOT DISTINCT FROM OLD.start_times
     AND NEW.is_active IS NOT DISTINCT FROM OLD.is_active
     AND NEW.sop_code IS NOT DISTINCT FROM OLD.sop_code
     AND NEW.employee_id IS NOT DISTINCT FROM OLD.employee_id
     AND NEW.organization_id IS NOT DISTINCT FROM OLD.organization_id
  THEN
    RETURN NEW;
  END IF;

  IF NEW.sop_code = 'SOP1' THEN
    PERFORM public.ai_employee_content_schedules_retarget(NEW.employee_id, NEW.organization_id);
    RETURN NEW;
  END IF;

  IF NEW.sop_code = 'SOP4' THEN
    PERFORM public.ai_employee_story_schedules_retarget(NEW.employee_id, NEW.organization_id);
    RETURN NEW;
  END IF;

  SELECT COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta')
  INTO v_zone
  FROM public.ai_employee_profiles profile
  WHERE profile.employee_id = NEW.employee_id
    AND profile.organization_id = NEW.organization_id;

  UPDATE public.ai_employee_schedules schedule
  SET next_run_at = public.ai_employee_next_run_at(
    NEW.weekday,
    NEW.start_local,
    COALESCE(v_zone, 'Asia/Jakarta'),
    clock_timestamp()
  )
  WHERE schedule.id = NEW.id
    AND NEW.weekday BETWEEN 1 AND 7;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_schedules_set_next_run"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_seat_allowance"("p_org_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT CASE
      WHEN coalesce(o.subscription_self_service_enabled, true) = false THEN
        CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.organization_sales_module_access m
            WHERE m.organization_id = o.id
              AND m.module_key = 'aiEmployee'
              AND m.is_enabled IS TRUE
          ) THEN COALESCE(os.ai_employee_seat_count, 0)
          ELSE 0
        END
      ELSE COALESCE(os.ai_employee_paid_seat_count, 0)
    END
    FROM public.organizations o
    LEFT JOIN public.organization_subscriptions os ON os.organization_id = o.id
    WHERE o.id = p_org_id
  ), 0);
$$;


ALTER FUNCTION "public"."ai_employee_seat_allowance"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_set_performance_status"("p_employee_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_token text;
BEGIN
  IF p_status NOT IN ('on_track', 'attention', 'coaching', 'disabled') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  SELECT organization_id INTO v_org
  FROM public.ai_employee_profiles
  WHERE employee_id = p_employee_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT public.user_has_org_role(v_org, ARRAY['owner']) THEN
    RAISE EXCEPTION 'owner_required' USING ERRCODE = '42501';
  END IF;

  v_token := gen_random_uuid()::text;
  INSERT INTO public.ai_employee_status_tickets (employee_id, token)
  VALUES (p_employee_id, v_token)
  ON CONFLICT (employee_id) DO UPDATE SET token = EXCLUDED.token, created_at = now();

  PERFORM set_config('ai_employee.status_write', v_token, true);

  UPDATE public.ai_employee_profiles
  SET performance_status = p_status,
      updated_at = now()
  WHERE employee_id = p_employee_id;
END;
$$;


ALTER FUNCTION "public"."ai_employee_set_performance_status"("p_employee_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_sop1_manual_begin"("p_user_id" "uuid", "p_employee_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_active boolean;
  v_performance text;
  v_run uuid;
BEGIN
  SELECT employee.organization_id, profile.is_active, profile.performance_status
  INTO v_org, v_active, v_performance
  FROM public.employees employee
  LEFT JOIN public.ai_employee_profiles profile
    ON profile.employee_id = employee.id
   AND profile.organization_id = employee.organization_id
  WHERE employee.id = p_employee_id
    AND COALESCE(employee.is_ai, false)
  FOR UPDATE OF employee;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.ai_employee_require_owner(p_user_id, v_org);

  IF v_active IS NOT TRUE OR v_performance = 'disabled' THEN
    RAISE EXCEPTION 'profile_inactive' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.ai_employee_runs run
    WHERE run.employee_id = p_employee_id
      AND run.organization_id = v_org
      AND run.sop_code = 'SOP1'
      AND run.status = 'running'
  ) THEN
    RAISE EXCEPTION 'too_soon' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_employee_runs (employee_id, organization_id, sop_code, status, note, trigger_source)
  VALUES (p_employee_id, v_org, 'SOP1', 'running', 'manual', 'manual')
  RETURNING id INTO v_run;

  RETURN v_run;
END;
$$;


ALTER FUNCTION "public"."ai_employee_sop1_manual_begin"("p_user_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_sop1_manual_begin"("p_user_id" "uuid", "p_employee_id" "uuid") IS 'Owner memulai satu Content Plan sekarang. Tidak menggeser jadwal. Ditolak hanya bila run SOP1 masih berstatus berjalan.';



