CREATE OR REPLACE FUNCTION "public"."ai_employee_start_times_ok"("p_times" time without time zone[]) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(cardinality(p_times), 0) BETWEEN 1 AND 7
    AND (
      SELECT count(DISTINCT slot)
      FROM unnest(p_times) AS slot
    ) = cardinality(p_times)
    AND NOT EXISTS (
      SELECT 1
      FROM unnest(p_times) AS left_slot
      JOIN unnest(p_times) AS right_slot
        ON left_slot < right_slot
      WHERE LEAST(
        abs(extract(epoch FROM (right_slot - left_slot))),
        86400 - abs(extract(epoch FROM (right_slot - left_slot)))
      ) < 3600
    );
$$;


ALTER FUNCTION "public"."ai_employee_start_times_ok"("p_times" time without time zone[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_status_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text;
BEGIN
  IF NEW.performance_status IS NOT DISTINCT FROM OLD.performance_status THEN
    RETURN NEW;
  END IF;

  v_token := current_setting('ai_employee.status_write', true);
  IF v_token IS NULL OR v_token = '' THEN
    RAISE EXCEPTION 'performance_status_locked'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.ai_employee_status_tickets
  WHERE employee_id = NEW.employee_id
    AND token = v_token;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'performance_status_locked'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ai_employee_status_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_brief_payload"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_row public.ai_employee_story_briefs%ROWTYPE;
  v_services uuid[];
  v_angles uuid[];
  v_pillars uuid[];
  v_color uuid;
  v_headline text;
  v_body text;
  v_auto boolean;
  v_found boolean := false;
BEGIN
  SELECT employee.organization_id
  INTO v_org
  FROM public.employees employee
  WHERE employee.id = p_employee_id
    AND COALESCE(employee.is_ai, false);
  IF v_org IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT *
  INTO v_row
  FROM public.ai_employee_story_briefs brief
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;
  v_found := FOUND;

  IF v_found THEN
    v_services := COALESCE(v_row.service_ids, '{}'::uuid[]);
    v_angles := COALESCE(v_row.angle_ids, '{}'::uuid[]);
    v_pillars := COALESCE(v_row.pillar_ids, '{}'::uuid[]);
    v_color := v_row.brand_color_id;
    v_headline := COALESCE(v_row.headline_font, '');
    v_body := COALESCE(v_row.body_font, '');
    v_auto := COALESCE(v_row.story_auto_approve, true);
  ELSE
    v_services := '{}'::uuid[];
    v_angles := '{}'::uuid[];
    v_pillars := '{}'::uuid[];
    v_color := NULL;
    v_headline := '';
    v_body := '';
    v_auto := true;
  END IF;

  -- Katalog awal: mirror dari carousel jika Story belum punya katalog.
  IF cardinality(v_services) = 0 THEN
    SELECT CASE
      WHEN cardinality(COALESCE(carousel.service_ids, '{}'::uuid[])) >= 1
        THEN ARRAY[carousel.service_ids[1]]
      ELSE '{}'::uuid[]
    END
    INTO v_services
    FROM public.ai_employee_briefs carousel
    WHERE carousel.employee_id = p_employee_id
      AND carousel.organization_id = v_org;
    v_services := COALESCE(v_services, '{}'::uuid[]);
  END IF;

  RETURN jsonb_build_object(
    'service_ids', to_jsonb(v_services),
    'angle_ids', to_jsonb(v_angles),
    'pillar_ids', to_jsonb(v_pillars),
    'brand_color_id', v_color,
    'headline_font', v_headline,
    'body_font', v_body,
    'story_auto_approve', v_auto,
    'services', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', svc.id,
        'label', left(btrim(svc.name), 80)
      ) ORDER BY svc.name)
      FROM public.services svc
      WHERE svc.organization_id = v_org
        AND svc.id = ANY (v_services)
    ), '[]'::jsonb),
    'angles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', angle.id,
        'label', left(btrim(COALESCE(
          NULLIF(btrim(angle.statement), ''),
          NULLIF(btrim(angle.code), ''),
          angle.id::text
        )), 80)
      ) ORDER BY angle.code)
      FROM public.thinking_lab_angles angle
      WHERE angle.organization_id = v_org
        AND angle.id = ANY (v_angles)
    ), '[]'::jsonb),
    'pillars', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pillar.id,
        'label', left(btrim(pillar.name), 80)
      ) ORDER BY pillar.name)
      FROM public.content_pillars pillar
      WHERE pillar.id = ANY (v_pillars)
    ), '[]'::jsonb),
    'brand_colors', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', color.id,
        'brand_name', COALESCE(color.brand_name, ''),
        'primary_color_hex', color.primary_color_hex,
        'secondary_color_hex', color.secondary_color_hex,
        'accent_color_hex', color.accent_color_hex
      ) ORDER BY color.created_at NULLS LAST, color.id)
      FROM public.digital_asset_brand_colors color
      WHERE color.organization_id = v_org
        AND (
          cardinality(v_services) = 0
          OR color.service_id = ANY (v_services)
          OR color.id = v_color
        )
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_brief_payload"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_brief_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_brief" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_services uuid[];
  v_angles uuid[];
  v_pillars uuid[];
  v_color uuid;
  v_headline text;
  v_body text;
  v_auto boolean;
BEGIN
  PERFORM public.ai_employee_require_owner(p_user_id, p_organization_id);

  IF p_brief IS NULL OR jsonb_typeof(p_brief) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  v_services := public.ai_employee_brief_ids(p_brief->'service_ids');
  v_angles := public.ai_employee_brief_ids(p_brief->'angle_ids');
  v_pillars := public.ai_employee_brief_ids(p_brief->'pillar_ids');
  v_color := NULLIF(btrim(COALESCE(p_brief->>'brand_color_id', '')), '')::uuid;
  v_headline := left(btrim(COALESCE(p_brief->>'headline_font', '')), 60);
  v_body := left(btrim(COALESCE(p_brief->>'body_font', '')), 60);
  v_auto := COALESCE((p_brief->>'story_auto_approve')::boolean, true);

  IF cardinality(v_services) > 1
     OR cardinality(v_angles) > 6
     OR cardinality(v_pillars) > 12 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(v_services) AS picked(picked_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.services svc
      WHERE svc.id = picked.picked_id
        AND svc.organization_id = p_organization_id
        AND COALESCE(svc.is_active, true)
    )
  ) OR EXISTS (
    SELECT 1
    FROM unnest(v_angles) AS picked(picked_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.thinking_lab_angles angle
      WHERE angle.id = picked.picked_id
        AND angle.organization_id = p_organization_id
    )
  ) OR EXISTS (
    SELECT 1
    FROM unnest(v_pillars) AS picked(picked_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.content_pillars pillar
      WHERE pillar.id = picked.picked_id
        AND pillar.is_active
        AND (pillar.organization_id = p_organization_id OR pillar.is_default)
    )
  ) OR (
    v_color IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.digital_asset_brand_colors color
      WHERE color.id = v_color
        AND color.organization_id = p_organization_id
    )
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_employee_story_briefs (
    employee_id,
    organization_id,
    service_ids,
    angle_ids,
    pillar_ids,
    brand_color_id,
    headline_font,
    body_font,
    story_auto_approve,
    updated_at
  ) VALUES (
    p_employee_id,
    p_organization_id,
    v_services,
    v_angles,
    v_pillars,
    v_color,
    v_headline,
    v_body,
    v_auto,
    now()
  )
  ON CONFLICT (employee_id) DO UPDATE SET
    organization_id = EXCLUDED.organization_id,
    service_ids = EXCLUDED.service_ids,
    angle_ids = EXCLUDED.angle_ids,
    pillar_ids = EXCLUDED.pillar_ids,
    brand_color_id = EXCLUDED.brand_color_id,
    headline_font = EXCLUDED.headline_font,
    body_font = EXCLUDED.body_font,
    story_auto_approve = EXCLUDED.story_auto_approve,
    updated_at = now();

  RETURN public.ai_employee_story_brief_payload(p_employee_id);
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_brief_write"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_brief" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_catalog_color_delete"("p_employee_id" "uuid", "p_color_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service uuid;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_story_saved_catalog(p_employee_id);
  IF p_color_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  UPDATE public.ai_employee_story_briefs brief
  SET brand_color_id = NULL,
      updated_at = now()
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org
    AND brief.brand_color_id = p_color_id;

  DELETE FROM public.digital_asset_brand_colors color
  WHERE color.id = p_color_id
    AND color.organization_id = v_org
    AND color.service_id = v_service;
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_catalog_color_delete"("p_employee_id" "uuid", "p_color_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_catalog_color_save"("p_employee_id" "uuid", "p_color_id" "uuid", "p_brand_name" "text", "p_primary" "text", "p_secondary" "text", "p_accent" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
  v_service uuid;
  v_id uuid;
  v_name text;
  v_primary text := lower(btrim(COALESCE(p_primary, '')));
  v_secondary text := lower(btrim(COALESCE(p_secondary, '')));
  v_accent text := lower(btrim(COALESCE(p_accent, '')));
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_story_saved_catalog(p_employee_id);
  IF v_primary !~ '^#[0-9a-f]{6}$'
    OR v_secondary !~ '^#[0-9a-f]{6}$'
    OR v_accent !~ '^#[0-9a-f]{6}$'
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_name := NULLIF(left(btrim(COALESCE(p_brand_name, '')), 80), '');
  IF p_color_id IS NULL THEN
    INSERT INTO public.digital_asset_brand_colors (
      organization_id, service_id, brand_name,
      primary_color_hex, secondary_color_hex, accent_color_hex, text_color_hex
    ) VALUES (
      v_org, v_service, v_name, v_primary, v_secondary, v_accent, NULL
    )
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.digital_asset_brand_colors color
    SET brand_name = v_name,
        primary_color_hex = v_primary,
        secondary_color_hex = v_secondary,
        accent_color_hex = v_accent,
        updated_at = now()
    WHERE color.id = p_color_id
      AND color.organization_id = v_org
      AND color.service_id = v_service
    RETURNING color.id INTO v_id;
    IF v_id IS NULL THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.ai_employee_story_briefs (
    employee_id, organization_id, brand_color_id, story_auto_approve, updated_at
  ) VALUES (
    p_employee_id, v_org, v_id, true, now()
  )
  ON CONFLICT (employee_id) DO UPDATE SET
    brand_color_id = EXCLUDED.brand_color_id,
    updated_at = now();

  RETURN v_id;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_story_catalog_color_save"("p_employee_id" "uuid", "p_color_id" "uuid", "p_brand_name" "text", "p_primary" "text", "p_secondary" "text", "p_accent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_catalog_color_set"("p_employee_id" "uuid", "p_color_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_service uuid;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, true);
  v_service := public.ai_employee_story_saved_catalog(p_employee_id);
  IF p_color_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.digital_asset_brand_colors color
    WHERE color.id = p_color_id
      AND color.organization_id = v_org
      AND color.service_id = v_service
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.ai_employee_story_briefs (
    employee_id, organization_id, brand_color_id, story_auto_approve, updated_at
  ) VALUES (
    p_employee_id, v_org, p_color_id, true, now()
  )
  ON CONFLICT (employee_id) DO UPDATE SET
    brand_color_id = EXCLUDED.brand_color_id,
    updated_at = now();
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_catalog_color_set"("p_employee_id" "uuid", "p_color_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_fields"("p_organization_id" "uuid", "p_payload" "jsonb") RETURNS TABLE("brief" "text", "caption" "text", "content_type_id" "uuid", "concept" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_caption text;
  v_reason text;
  v_visual text;
  v_headline text;
  v_type uuid;
  v_brief text;
  v_primary text;
  v_secondary text;
  v_accent text;
  v_color text := '';
  v_fonts text := '';
BEGIN
  IF COALESCE(p_payload->>'content_kind', '') IS DISTINCT FROM 'story' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_caption := NULLIF(btrim(COALESCE(p_payload->>'caption', '')), '');
  IF v_caption IS NULL OR char_length(v_caption) < 20 OR char_length(v_caption) > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_reason := NULLIF(regexp_replace(btrim(COALESCE(p_payload->>'concept', '')), '\s+', ' ', 'g'), '');
  IF v_reason IS NULL OR char_length(v_reason) < 40 OR char_length(v_reason) > 800 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_visual := left(regexp_replace(replace(btrim(COALESCE(p_payload->>'visual', '')), '|', '/'), '\s+', ' ', 'g'), 800);
  IF v_visual = '' THEN
    v_visual := v_reason;
  END IF;
  v_headline := left(regexp_replace(replace(btrim(COALESCE(p_payload->>'headline', '')), '|', '/'), '\s+', ' ', 'g'), 200);

  v_primary := lower(btrim(COALESCE(p_payload #>> '{palette,primary}', '')));
  v_secondary := lower(btrim(COALESCE(p_payload #>> '{palette,secondary}', '')));
  v_accent := lower(btrim(COALESCE(p_payload #>> '{palette,accent}', '')));
  IF v_primary ~ '^#[0-9a-f]{6}$'
    AND v_secondary ~ '^#[0-9a-f]{6}$'
    AND v_accent ~ '^#[0-9a-f]{6}$'
  THEN
    v_color := format(
      E'\nWarna: primer %s, sekunder %s, aksen %s',
      v_primary, v_secondary, v_accent
    );
  END IF;

  IF NULLIF(btrim(COALESCE(p_payload->>'headline_font', '')), '') IS NOT NULL
     OR NULLIF(btrim(COALESCE(p_payload->>'body_font', '')), '') IS NOT NULL
  THEN
    v_fonts := format(
      E'\nFont: headline %s, body %s',
      COALESCE(NULLIF(btrim(p_payload->>'headline_font'), ''), 'Default'),
      COALESCE(NULLIF(btrim(p_payload->>'body_font'), ''), 'Default')
    );
  END IF;

  v_brief := format(
    E'Format: Instagram Story 9:16 (satu frame)\nHeadline: %s\nVisual: %s\nConcept: %s%s%s\n\n<!--synckerja-brief-sequences:%s-->',
    COALESCE(NULLIF(v_headline, ''), '—'),
    v_visual,
    v_reason,
    v_color,
    v_fonts,
    jsonb_build_array(jsonb_build_object(
      'id', gen_random_uuid(),
      'name', 'Story',
      'rowCount', 1
    ))::text
  );

  SELECT ct.id
  INTO v_type
  FROM public.content_types ct
  WHERE COALESCE(ct.is_active, true)
    AND (ct.organization_id = p_organization_id OR ct.organization_id IS NULL)
    AND lower(btrim(ct.name)) = 'story'
  ORDER BY (ct.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ct.id
  LIMIT 1;
  IF v_type IS NULL THEN
    RAISE EXCEPTION 'story_type_missing' USING ERRCODE = 'P0002';
  END IF;

  brief := v_brief;
  caption := v_caption;
  content_type_id := v_type;
  concept := jsonb_build_object(
    'v', 1,
    'postAspect', '9:16',
    'reason', v_reason,
    'locations', '[]'::jsonb,
    'characters', '[]'::jsonb,
    'properties', '[]'::jsonb
  )::text;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."ai_employee_story_fields"("p_organization_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_plans"("p_employee_id" "uuid", "p_month" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_month date;
  v_from timestamptz;
  v_to timestamptz;
  v_rows jsonb;
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, false);
  v_month := date_trunc('month', COALESCE(p_month, timezone('Asia/Jakarta', now())::date))::date;
  v_from := v_month::timestamp AT TIME ZONE 'Asia/Jakarta';
  v_to := (v_month + interval '1 month')::timestamp AT TIME ZONE 'Asia/Jakarta';

  SELECT COALESCE(jsonb_agg(row_data ORDER BY post_date DESC NULLS LAST, created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT
      plan.post_date,
      plan.created_at,
      jsonb_build_object(
        'id', plan.id,
        'post_date', plan.post_date,
        'pic_name', left(COALESCE(pic.full_name, ''), 120),
        'content_type_name', left(COALESCE(ctype.name, 'Story'), 40),
        'service_id', plan.service_id,
        'service_name', left(COALESCE(service.name, ''), 120),
        'pillar_name', left(COALESCE(pillar.name, ''), 120),
        'brief_preview', left(COALESCE(plan.brief, ''), 280),
        'google_drive_link', left(COALESCE(plan.google_drive_link, ''), 500),
        'production_status', left(COALESCE(plan.production_status, ''), 40),
        'production_approved', COALESCE(plan.production_approved, false),
        'canva', CASE
          WHEN canva.social_media_plan_id IS NULL THEN NULL
          ELSE jsonb_build_object(
            'status', canva.status,
            'design_url', canva.design_url,
            'error', left(COALESCE(canva.error, ''), 160),
            'images_ready', canva.images_ready,
            'refresh_requested', canva.refresh_requested,
            'export_path', canva.export_path
          )
        END
      ) AS row_data
    FROM public.social_media_plans plan
    JOIN public.content_types ctype
      ON ctype.id = plan.content_type_id
     AND lower(btrim(ctype.name)) = 'story'
    LEFT JOIN public.employees pic ON pic.id = plan.pic_id
    LEFT JOIN public.services service ON service.id = plan.service_id
    LEFT JOIN public.content_pillars pillar ON pillar.id = plan.content_pillar_id
    LEFT JOIN public.canva_story_runs canva ON canva.social_media_plan_id = plan.id
    WHERE plan.organization_id = v_org
      AND (plan.pic_id = p_employee_id OR plan.author_employee_id = p_employee_id)
      AND plan.post_date >= v_from
      AND plan.post_date < v_to
    ORDER BY plan.post_date DESC NULLS LAST, plan.created_at DESC
    LIMIT 300
  ) listed;

  RETURN jsonb_build_object(
    'month', to_char(v_month, 'YYYY-MM'),
    'rows', v_rows
  );
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_plans"("p_employee_id" "uuid", "p_month" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_story_plans"("p_employee_id" "uuid", "p_month" "date") IS 'Story plans for one AI employee month view; includes service_id for Content Scheduling account filter.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_story_saved_catalog"("p_employee_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_service uuid;
BEGIN
  SELECT brief.service_ids[1]
  INTO v_service
  FROM public.ai_employee_story_briefs brief
  WHERE brief.employee_id = p_employee_id
    AND cardinality(brief.service_ids) = 1;
  IF v_service IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  RETURN v_service;
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_saved_catalog"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_story_schedules_retarget"("p_employee_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_zone text;
  v_row record;
  v_next timestamptz;
BEGIN
  SELECT COALESCE(NULLIF(btrim(profile.time_zone), ''), 'Asia/Jakarta')
  INTO v_zone
  FROM public.ai_employee_profiles profile
  WHERE profile.employee_id = p_employee_id
    AND profile.organization_id = p_organization_id;

  v_zone := COALESCE(v_zone, 'Asia/Jakarta');

  FOR v_row IN
    SELECT
      schedule.id,
      schedule.weekdays,
      schedule.start_times,
      schedule.start_local,
      schedule.is_active
    FROM public.ai_employee_schedules schedule
    WHERE schedule.employee_id = p_employee_id
      AND schedule.organization_id = p_organization_id
      AND schedule.sop_code = 'SOP4'
      AND schedule.cadence = 'days'
  LOOP
    IF v_row.is_active IS DISTINCT FROM TRUE THEN
      UPDATE public.ai_employee_schedules schedule
      SET next_run_at = NULL
      WHERE schedule.id = v_row.id
        AND schedule.next_run_at IS NOT NULL;
      CONTINUE;
    END IF;

    v_next := public.ai_employee_next_story_at(
      v_row.weekdays,
      v_row.start_times,
      v_row.start_local,
      v_zone,
      clock_timestamp()
    );

    UPDATE public.ai_employee_schedules schedule
    SET next_run_at = v_next
    WHERE schedule.id = v_row.id
      AND schedule.next_run_at IS DISTINCT FROM v_next;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_employee_story_schedules_retarget"("p_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ai_employee_story_schedules_retarget"("p_employee_id" "uuid", "p_organization_id" "uuid") IS 'Recalculate next_run_at for Design Story SOP4 day schedules.';



CREATE OR REPLACE FUNCTION "public"."ai_employee_sync_reviewer_from_manager"("p_employee_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_manager uuid;
  v_is_ai boolean;
  v_reviewer uuid;
BEGIN
  SELECT e.organization_id, e.manager_id, COALESCE(e.is_ai, false)
  INTO v_org, v_manager, v_is_ai
  FROM public.employees e
  WHERE e.id = p_employee_id;
  IF v_org IS NULL OR v_is_ai IS NOT TRUE THEN
    RETURN;
  END IF;
  v_reviewer := NULL;
  IF v_manager IS NOT NULL THEN
    SELECT m.id INTO v_reviewer
    FROM public.employees m
    WHERE m.id = v_manager
      AND m.organization_id = v_org
      AND COALESCE(m.is_ai, false) IS NOT TRUE
      AND m.user_id IS NOT NULL;
  END IF;
  UPDATE public.ai_employee_profiles
  SET reviewer_employee_id = v_reviewer, updated_at = now()
  WHERE employee_id = p_employee_id
    AND organization_id = v_org
    AND reviewer_employee_id IS DISTINCT FROM v_reviewer;
END;
$$;


ALTER FUNCTION "public"."ai_employee_sync_reviewer_from_manager"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_thinking_tree"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_focus uuid[];
  v_pillars uuid[];
BEGIN
  v_org := public.ai_employee_page_gate(p_employee_id, false);

  SELECT COALESCE(brief.angle_ids, '{}'::uuid[]), COALESCE(brief.pillar_ids, '{}'::uuid[])
  INTO v_focus, v_pillars
  FROM public.ai_employee_briefs brief
  WHERE brief.employee_id = p_employee_id
    AND brief.organization_id = v_org;

  RETURN COALESCE((
    SELECT jsonb_agg(node ORDER BY depth, sort_key, created_at)
    FROM (
      SELECT 0 AS depth, master.created_at, 0 AS sort_key, jsonb_build_object(
        'level', 'master', 'id', master.id, 'parent_id', NULL, 'code', '',
        'label', left(COALESCE(btrim(master.statement), ''), 200),
        'ready', master.status = 'locked', 'in_focus', false
      ) AS node
      FROM public.thinking_master_thoughts master
      WHERE master.organization_id = v_org AND master.workspace = 'thinking_lab'

      UNION ALL
      SELECT 1, thought.created_at, COALESCE(thought.sort_order, 0), jsonb_build_object(
        'level', 'bigThought', 'id', thought.id, 'parent_id', thought.master_thought_id,
        'code', left(COALESCE(btrim(thought.code), ''), 16),
        'label', left(COALESCE(NULLIF(btrim(thought.title), ''), btrim(thought.statement), ''), 200),
        'ready', thought.status = 'locked', 'in_focus', false
      )
      FROM public.thinking_big_thoughts thought
      JOIN public.thinking_master_thoughts master
        ON master.id = thought.master_thought_id AND master.organization_id = v_org AND master.workspace = 'thinking_lab'
      WHERE thought.organization_id = v_org

      UNION ALL
      SELECT 2, territory.created_at, COALESCE(territory.sort_order, 0), jsonb_build_object(
        'level', 'territory', 'id', territory.id, 'parent_id', territory.big_thought_id,
        'code', left(COALESCE(btrim(territory.code), ''), 16),
        'label', left(COALESCE(btrim(territory.statement), ''), 200),
        'ready', territory.status = 'locked', 'in_focus', false
      )
      FROM public.thinking_lab_territories territory
      WHERE territory.organization_id = v_org

      UNION ALL
      SELECT 3, angle.created_at, COALESCE(angle.sort_order, 0), jsonb_build_object(
        'level', 'angle', 'id', angle.id, 'parent_id', angle.territory_id,
        'code', left(COALESCE(btrim(angle.code), ''), 16),
        'label', left(COALESCE(btrim(angle.statement), ''), 200),
        'ready', angle.status = 'locked' AND angle.admission = 'GENERATE_VALID',
        'in_focus', angle.id = ANY (COALESCE(v_focus, '{}'::uuid[]))
      )
      FROM public.thinking_lab_angles angle
      WHERE angle.organization_id = v_org

      UNION ALL
      SELECT 4, idea.created_at, COALESCE(idea.sort_order, 0), jsonb_build_object(
        'level', 'idea', 'id', idea.id, 'parent_id', idea.angle_id,
        'code', left(COALESCE(btrim(idea.code), ''), 16),
        'label', left(COALESCE(btrim(idea.statement), ''), 200),
        'ready', idea.status = 'locked' AND COALESCE(idea.validation ->> 'decision', '') = 'LOLOS',
        'in_focus', false
      )
      FROM public.thinking_lab_ideas idea
      WHERE idea.organization_id = v_org

      UNION ALL
      SELECT 5, pillar.created_at, 0, jsonb_build_object(
        'level', 'pillar', 'id', pillar.id, 'parent_id', NULL, 'code', '',
        'label', left(COALESCE(btrim(pillar.name), ''), 120),
        'ready', true, 'in_focus', pillar.id = ANY (COALESCE(v_pillars, '{}'::uuid[]))
      )
      FROM public.content_pillars pillar
      WHERE COALESCE(pillar.is_active, true)
        AND (pillar.organization_id = v_org OR pillar.is_default)
        AND (COALESCE(cardinality(v_pillars), 0) = 0 OR pillar.id = ANY (v_pillars))
    ) nodes
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."ai_employee_thinking_tree"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_employee_user_may_assign"("p_user_id" "uuid", "p_ai_employee_id" "uuid", "p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = p_user_id
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) OR EXISTS (
    SELECT 1
    FROM public.employees actor
    JOIN public.ai_employee_profiles profile
      ON profile.reviewer_employee_id = actor.id
     AND profile.organization_id = p_organization_id
     AND profile.employee_id = p_ai_employee_id
    WHERE actor.user_id = p_user_id
      AND actor.organization_id = p_organization_id
  );
$$;


ALTER FUNCTION "public"."ai_employee_user_may_assign"("p_user_id" "uuid", "p_ai_employee_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."analytics_session_touch"("p_session" "uuid", "p_web_id" "text", "p_referrer" "text", "p_ua_hash" "text", "p_auth" "uuid" DEFAULT NULL::"uuid", "p_landing_url" "text" DEFAULT NULL::"text", "p_utm_source" "text" DEFAULT NULL::"text", "p_utm_medium" "text" DEFAULT NULL::"text", "p_utm_campaign" "text" DEFAULT NULL::"text", "p_utm_content" "text" DEFAULT NULL::"text", "p_utm_term" "text" DEFAULT NULL::"text", "p_meta_campaign_name" "text" DEFAULT NULL::"text", "p_meta_adset_name" "text" DEFAULT NULL::"text", "p_meta_ad_name" "text" DEFAULT NULL::"text", "p_has_gclid" boolean DEFAULT false, "p_has_fbclid" boolean DEFAULT false, "p_has_msclkid" boolean DEFAULT false, "p_has_gbraid" boolean DEFAULT false, "p_has_wbraid" boolean DEFAULT false, "p_visitor_id" "text" DEFAULT NULL::"text", "p_gclid" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_visitor text;
  v_web text;
  v_gclid text;
begin
  v_web := public.hub_require_active_web_id(p_web_id, false);
  v_visitor := left(coalesce(nullif(trim(p_visitor_id), ''), p_session::text), 64);
  v_gclid := left(nullif(btrim(p_gclid), ''), 500);

  insert into public.analytics_sessions (
    id, web_id, visitor_id, referrer, ua_hash, auth_user_id,
    landing_url, utm_source, utm_medium, utm_campaign, utm_content, utm_term,
    meta_campaign_name, meta_adset_name, meta_ad_name,
    has_gclid, has_fbclid, has_msclkid, has_gbraid, has_wbraid,
    gclid,

    first_landing_url, first_referrer,
    first_utm_source, first_utm_medium, first_utm_campaign, first_utm_content, first_utm_term,
    first_meta_campaign_name, first_meta_adset_name, first_meta_ad_name,
    first_has_gclid, first_has_fbclid, first_has_msclkid, first_has_gbraid, first_has_wbraid,

    last_landing_url, last_referrer,
    last_utm_source, last_utm_medium, last_utm_campaign, last_utm_content, last_utm_term,
    last_meta_campaign_name, last_meta_adset_name, last_meta_ad_name,
    last_has_gclid, last_has_fbclid, last_has_msclkid, last_has_gbraid, last_has_wbraid
  )
  values (
    p_session,
    v_web,
    v_visitor,
    left(nullif(trim(p_referrer), ''), 500),
    left(nullif(trim(p_ua_hash), ''), 64),
    p_auth,
    left(nullif(trim(p_landing_url), ''), 1000),
    left(nullif(trim(p_utm_source), ''), 200),
    left(nullif(trim(p_utm_medium), ''), 200),
    left(nullif(trim(p_utm_campaign), ''), 200),
    left(nullif(trim(p_utm_content), ''), 200),
    left(nullif(trim(p_utm_term), ''), 200),
    left(nullif(trim(p_meta_campaign_name), ''), 200),
    left(nullif(trim(p_meta_adset_name), ''), 200),
    left(nullif(trim(p_meta_ad_name), ''), 200),
    coalesce(p_has_gclid, false),
    coalesce(p_has_fbclid, false),
    coalesce(p_has_msclkid, false),
    coalesce(p_has_gbraid, false),
    coalesce(p_has_wbraid, false),
    v_gclid,

    left(nullif(trim(p_landing_url), ''), 1000),
    left(nullif(trim(p_referrer), ''), 500),
    left(nullif(trim(p_utm_source), ''), 200),
    left(nullif(trim(p_utm_medium), ''), 200),
    left(nullif(trim(p_utm_campaign), ''), 200),
    left(nullif(trim(p_utm_content), ''), 200),
    left(nullif(trim(p_utm_term), ''), 200),
    left(nullif(trim(p_meta_campaign_name), ''), 200),
    left(nullif(trim(p_meta_adset_name), ''), 200),
    left(nullif(trim(p_meta_ad_name), ''), 200),
    coalesce(p_has_gclid, false),
    coalesce(p_has_fbclid, false),
    coalesce(p_has_msclkid, false),
    coalesce(p_has_gbraid, false),
    coalesce(p_has_wbraid, false),

    left(nullif(trim(p_landing_url), ''), 1000),
    left(nullif(trim(p_referrer), ''), 500),
    left(nullif(trim(p_utm_source), ''), 200),
    left(nullif(trim(p_utm_medium), ''), 200),
    left(nullif(trim(p_utm_campaign), ''), 200),
    left(nullif(trim(p_utm_content), ''), 200),
    left(nullif(trim(p_utm_term), ''), 200),
    left(nullif(trim(p_meta_campaign_name), ''), 200),
    left(nullif(trim(p_meta_adset_name), ''), 200),
    left(nullif(trim(p_meta_ad_name), ''), 200),
    coalesce(p_has_gclid, false),
    coalesce(p_has_fbclid, false),
    coalesce(p_has_msclkid, false),
    coalesce(p_has_gbraid, false),
    coalesce(p_has_wbraid, false)
  )
  on conflict (id) do update set
    last_seen_at = now(),
    web_id = excluded.web_id,
    visitor_id = excluded.visitor_id,
    referrer = coalesce(excluded.referrer, public.analytics_sessions.referrer),
    ua_hash = coalesce(excluded.ua_hash, public.analytics_sessions.ua_hash),
    auth_user_id = coalesce(excluded.auth_user_id, public.analytics_sessions.auth_user_id),

    landing_url = coalesce(
      nullif(btrim(public.analytics_sessions.landing_url), ''),
      nullif(btrim(excluded.landing_url), '')
    ),
    utm_source = coalesce(
      nullif(btrim(public.analytics_sessions.utm_source), ''),
      nullif(btrim(excluded.utm_source), '')
    ),
    utm_medium = coalesce(
      nullif(btrim(public.analytics_sessions.utm_medium), ''),
      nullif(btrim(excluded.utm_medium), '')
    ),
    utm_campaign = coalesce(
      nullif(btrim(public.analytics_sessions.utm_campaign), ''),
      nullif(btrim(excluded.utm_campaign), '')
    ),
    utm_content = coalesce(
      nullif(btrim(public.analytics_sessions.utm_content), ''),
      nullif(btrim(excluded.utm_content), '')
    ),
    utm_term = coalesce(
      nullif(btrim(public.analytics_sessions.utm_term), ''),
      nullif(btrim(excluded.utm_term), '')
    ),
    meta_campaign_name = coalesce(
      nullif(btrim(public.analytics_sessions.meta_campaign_name), ''),
      nullif(btrim(excluded.meta_campaign_name), '')
    ),
    meta_adset_name = coalesce(
      nullif(btrim(public.analytics_sessions.meta_adset_name), ''),
      nullif(btrim(excluded.meta_adset_name), '')
    ),
    meta_ad_name = coalesce(
      nullif(btrim(public.analytics_sessions.meta_ad_name), ''),
      nullif(btrim(excluded.meta_ad_name), '')
    ),
    has_gclid = public.analytics_sessions.has_gclid or excluded.has_gclid,
    has_fbclid = public.analytics_sessions.has_fbclid or excluded.has_fbclid,
    has_msclkid = public.analytics_sessions.has_msclkid or excluded.has_msclkid,
    has_gbraid = public.analytics_sessions.has_gbraid or excluded.has_gbraid,
    has_wbraid = public.analytics_sessions.has_wbraid or excluded.has_wbraid,

    gclid = coalesce(
      nullif(btrim(public.analytics_sessions.gclid), ''),
      nullif(btrim(excluded.gclid), '')
    ),

    first_landing_url = coalesce(
      nullif(btrim(public.analytics_sessions.first_landing_url), ''),
      nullif(btrim(excluded.first_landing_url), '')
    ),
    first_referrer = coalesce(
      nullif(btrim(public.analytics_sessions.first_referrer), ''),
      nullif(btrim(excluded.first_referrer), '')
    ),
    first_utm_source = coalesce(
      nullif(btrim(public.analytics_sessions.first_utm_source), ''),
      nullif(btrim(excluded.first_utm_source), '')
    ),
    first_utm_medium = coalesce(
      nullif(btrim(public.analytics_sessions.first_utm_medium), ''),
      nullif(btrim(excluded.first_utm_medium), '')
    ),
    first_utm_campaign = coalesce(
      nullif(btrim(public.analytics_sessions.first_utm_campaign), ''),
      nullif(btrim(excluded.first_utm_campaign), '')
    ),
    first_utm_content = coalesce(
      nullif(btrim(public.analytics_sessions.first_utm_content), ''),
      nullif(btrim(excluded.first_utm_content), '')
    ),
    first_utm_term = coalesce(
      nullif(btrim(public.analytics_sessions.first_utm_term), ''),
      nullif(btrim(excluded.first_utm_term), '')
    ),
    first_meta_campaign_name = coalesce(
      nullif(btrim(public.analytics_sessions.first_meta_campaign_name), ''),
      nullif(btrim(excluded.first_meta_campaign_name), '')
    ),
    first_meta_adset_name = coalesce(
      nullif(btrim(public.analytics_sessions.first_meta_adset_name), ''),
      nullif(btrim(excluded.first_meta_adset_name), '')
    ),
    first_meta_ad_name = coalesce(
      nullif(btrim(public.analytics_sessions.first_meta_ad_name), ''),
      nullif(btrim(excluded.first_meta_ad_name), '')
    ),
    first_has_gclid = public.analytics_sessions.first_has_gclid or excluded.first_has_gclid,
    first_has_fbclid = public.analytics_sessions.first_has_fbclid or excluded.first_has_fbclid,
    first_has_msclkid = public.analytics_sessions.first_has_msclkid or excluded.first_has_msclkid,
    first_has_gbraid = public.analytics_sessions.first_has_gbraid or excluded.first_has_gbraid,
    first_has_wbraid = public.analytics_sessions.first_has_wbraid or excluded.first_has_wbraid,

    last_landing_url = coalesce(nullif(btrim(excluded.last_landing_url), ''), public.analytics_sessions.last_landing_url),
    last_referrer = coalesce(nullif(btrim(excluded.last_referrer), ''), public.analytics_sessions.last_referrer),
    last_utm_source = coalesce(nullif(btrim(excluded.last_utm_source), ''), public.analytics_sessions.last_utm_source),
    last_utm_medium = coalesce(nullif(btrim(excluded.last_utm_medium), ''), public.analytics_sessions.last_utm_medium),
    last_utm_campaign = coalesce(nullif(btrim(excluded.last_utm_campaign), ''), public.analytics_sessions.last_utm_campaign),
    last_utm_content = coalesce(nullif(btrim(excluded.last_utm_content), ''), public.analytics_sessions.last_utm_content),
    last_utm_term = coalesce(nullif(btrim(excluded.last_utm_term), ''), public.analytics_sessions.last_utm_term),
    last_meta_campaign_name = coalesce(nullif(btrim(excluded.last_meta_campaign_name), ''), public.analytics_sessions.last_meta_campaign_name),
    last_meta_adset_name = coalesce(nullif(btrim(excluded.last_meta_adset_name), ''), public.analytics_sessions.last_meta_adset_name),
    last_meta_ad_name = coalesce(nullif(btrim(excluded.last_meta_ad_name), ''), public.analytics_sessions.last_meta_ad_name),
    last_has_gclid = public.analytics_sessions.last_has_gclid or excluded.last_has_gclid,
    last_has_fbclid = public.analytics_sessions.last_has_fbclid or excluded.last_has_fbclid,
    last_has_msclkid = public.analytics_sessions.last_has_msclkid or excluded.last_has_msclkid,
    last_has_gbraid = public.analytics_sessions.last_has_gbraid or excluded.last_has_gbraid,
    last_has_wbraid = public.analytics_sessions.last_has_wbraid or excluded.last_has_wbraid;
end;
$$;


