COMMENT ON FUNCTION "public"."api_current_user_is_active_org_owner"() IS 'True if auth user owns the organization in profiles.active_organization_id.';



CREATE OR REPLACE FUNCTION "public"."app_apply_catalog_stock_movement"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_movement_type" "text", "p_qty_delta" numeric, "p_reference_type" "text", "p_reference_id" "text", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_movement_type NOT IN ('opening', 'adjustment') THEN
    RAISE EXCEPTION 'catalog_stock_movement_type_invalid' USING ERRCODE = '22023';
  END IF;

  -- Adjustment: hanya Owner/Admin, dan wajib alasan.
  IF p_movement_type = 'adjustment' THEN
    IF NOT public.catalog_can_adjust_stock(auth.uid(), p_organization_id) THEN
      RAISE EXCEPTION 'catalog_adjustment_forbidden' USING ERRCODE = '42501';
    END IF;
    IF NULLIF(btrim(COALESCE(p_note, '')), '') IS NULL THEN
      RAISE EXCEPTION 'catalog_adjustment_reason_required' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_qty_delta IS NULL OR abs(p_qty_delta) > 1000000000 THEN
    RAISE EXCEPTION 'catalog_stock_qty_invalid' USING ERRCODE = '22023';
  END IF;

  IF length(COALESCE(p_note, '')) > 1000 OR length(COALESCE(p_reference_type, '')) > 64
     OR length(COALESCE(p_reference_id, '')) > 64 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.pos_outlets o
    WHERE o.id = p_outlet_id AND o.organization_id = p_organization_id AND NOT COALESCE(o.is_deleted, false)
  ) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_item_kind = 'ingredient' THEN
    IF p_product_id IS NOT NULL OR p_variant_id IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM public.catalog_ingredients i
      WHERE i.id = p_ingredient_id AND i.organization_id = p_organization_id AND NOT COALESCE(i.is_deleted, false)
    ) THEN
      RAISE EXCEPTION 'catalog_stock_forbidden' USING ERRCODE = '42501';
    END IF;
  ELSIF p_item_kind = 'product' THEN
    IF p_ingredient_id IS NOT NULL OR NOT EXISTS (
      SELECT 1 FROM public.default_prices dp
      WHERE dp.id = p_product_id AND dp.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'catalog_stock_forbidden' USING ERRCODE = '42501';
    END IF;
    IF p_variant_id IS NOT NULL AND NOT EXISTS (
      SELECT 1 FROM public.catalog_product_variants v
      WHERE v.id = p_variant_id AND v.product_id = p_product_id
    ) THEN
      RAISE EXCEPTION 'catalog_stock_forbidden' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'catalog_stock_kind_invalid' USING ERRCODE = '22023';
  END IF;

  RETURN public.apply_catalog_stock_movement(
    p_organization_id, p_outlet_id, p_item_kind, p_product_id, p_variant_id, p_ingredient_id,
    p_movement_type, p_qty_delta, p_reference_type, p_reference_id, p_note
  );
END;
$$;


ALTER FUNCTION "public"."app_apply_catalog_stock_movement"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_movement_type" "text", "p_qty_delta" numeric, "p_reference_type" "text", "p_reference_id" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_ai_employee_paid_seats_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_details jsonb;
  v_raw text;
  v_bundled integer;
  v_renewal boolean;
  v_current integer;
  v_active integer;
  v_target integer;
BEGIN
  IF NEW.status IS DISTINCT FROM 'success' OR OLD.status IS NOT DISTINCT FROM 'success' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.ai_employee_seats_applied, false) THEN
    RETURN NEW;
  END IF;

  v_details := COALESCE(NEW.prorate_details, '{}'::jsonb);
  IF NOT (v_details ? 'bundled_ai_employee_units') THEN
    RETURN NEW;
  END IF;

  v_raw := v_details->>'bundled_ai_employee_units';
  v_bundled := CASE WHEN v_raw ~ '^[0-9]+$' THEN v_raw::integer ELSE 0 END;
  v_bundled := LEAST(50, GREATEST(0, v_bundled));
  v_renewal := COALESCE(v_details->>'renewal_full_period', '') IN ('true', '1');

  SELECT COALESCE(os.ai_employee_paid_seat_count, 0)
  INTO v_current
  FROM public.organization_subscriptions os
  WHERE os.organization_id = NEW.organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  v_active := public.count_active_ai_employees_for_org(NEW.organization_id);
  IF v_renewal THEN
    v_target := GREATEST(v_bundled, v_active);
  ELSE
    v_target := GREATEST(v_current, v_bundled, v_active);
  END IF;

  UPDATE public.organization_subscriptions
  SET ai_employee_paid_seat_count = v_target,
      last_payment_id = NEW.id,
      updated_at = now()
  WHERE organization_id = NEW.organization_id;

  NEW.ai_employee_seats_applied := true;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."apply_ai_employee_paid_seats_on_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_attendance_auto_checkout"("p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rules record;
  v_org record;
  v_tz text;
  v_today date;
  v_now_local time;
  v_updated integer := 0;
  v_ar record;
BEGIN
  FOR v_org IN
    SELECT ars.organization_id, ars.auto_checkout_time
    FROM public.attendance_rules_settings ars
    WHERE COALESCE(ars.auto_checkout_enabled, false)
      AND (p_organization_id IS NULL OR ars.organization_id = p_organization_id)
  LOOP
    SELECT COALESCE(wss.timezone, 'Asia/Jakarta')
    INTO v_tz
    FROM public.work_schedule_settings wss
    WHERE wss.organization_id = v_org.organization_id
      AND COALESCE(wss.is_active, true)
    ORDER BY wss.is_default DESC NULLS LAST, wss.created_at ASC
    LIMIT 1;

    v_tz := COALESCE(v_tz, 'Asia/Jakarta');
    v_today := (timezone(v_tz, now()))::date;
    v_now_local := (timezone(v_tz, now()))::time;

    IF v_now_local < v_org.auto_checkout_time THEN
      CONTINUE;
    END IF;

    FOR v_ar IN
      SELECT ar.id, ar.employee_id, ar.attendance_date, ar.check_in_at, ar.check_in_time
      FROM public.attendance_records ar
      WHERE ar.organization_id = v_org.organization_id
        AND ar.attendance_date = v_today
        AND (ar.check_in_time IS NOT NULL OR ar.check_in_at IS NOT NULL)
        AND ar.check_out_time IS NULL
        AND ar.check_out_at IS NULL
    LOOP
      UPDATE public.attendance_records ar
      SET
        check_out_time = v_org.auto_checkout_time,
        check_out_at = (v_ar.attendance_date + v_org.auto_checkout_time) AT TIME ZONE v_tz,
        status = COALESCE(ar.status, 'present'),
        notes = CASE
          WHEN ar.notes IS NULL OR btrim(ar.notes) = '' THEN '[auto_checkout]'
          WHEN ar.notes NOT LIKE '%[auto_checkout]%' THEN ar.notes || ' [auto_checkout]'
          ELSE ar.notes
        END,
        updated_at = now()
      WHERE ar.id = v_ar.id
        AND ar.check_out_time IS NULL
        AND ar.check_out_at IS NULL;

      IF FOUND THEN
        v_updated := v_updated + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('updated', v_updated);
END;
$$;


ALTER FUNCTION "public"."apply_attendance_auto_checkout"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_attendance_auto_checkout"("p_organization_id" "uuid") IS 'Auto check-out open attendance rows when org auto_checkout_enabled and local time >= auto_checkout_time. Scheduled via pg_cron job attendance-auto-checkout every 15 min; optional edge function attendance-auto-checkout for manual/external trigger.';



CREATE OR REPLACE FUNCTION "public"."apply_brick_va_settlement"("p_brick_payment_request_id" "uuid", "p_brick_payment_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_req public.brick_payment_requests%ROWTYPE;
  v_sap public.sales_activity_payments%ROWTYPE;
  v_sa public.sales_activities%ROWTYPE;
  v_bank_id uuid;
  v_income_id uuid;
  v_income public.income_transactions%ROWTYPE;
  v_amount numeric;
  v_new_status text;
  v_auto_confirm boolean := true;
BEGIN
  SELECT * INTO v_req FROM public.brick_payment_requests WHERE id = p_brick_payment_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'brick_payment_request_not_found';
  END IF;
  IF v_req.status = 'completed' THEN
    RETURN jsonb_build_object('ok', true, 'already_completed', true);
  END IF;

  SELECT COALESCE(obs.auto_confirm_on_completed, true) INTO v_auto_confirm
  FROM public.organization_brick_settings obs
  WHERE obs.organization_id = v_req.organization_id;
  IF NOT FOUND THEN
    v_auto_confirm := true;
  END IF;

  SELECT * INTO v_sap FROM public.sales_activity_payments WHERE id = v_req.sales_activity_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sales_activity_payment_not_found';
  END IF;

  SELECT * INTO v_sa FROM public.sales_activities WHERE id = v_sap.sales_activity_id;

  v_bank_id := public.resolve_brick_va_bank_account_id(v_req.organization_id, v_req.bank_short_code);
  v_amount := v_sap.payment_amount;

  UPDATE public.brick_payment_requests
  SET
    status = 'completed',
    brick_payment_id = COALESCE(p_brick_payment_id, brick_payment_id),
    paid_at = COALESCE(paid_at, now()),
    completed_at = now(),
    updated_at = now()
  WHERE id = v_req.id;

  IF v_auto_confirm THEN
    UPDATE public.sales_activity_payments
    SET
      transfer_verification_status = 'approved',
      transfer_verified_at = now(),
      payment_method = 'bank_transfer',
      notes = COALESCE(notes, '') || CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE ' | ' END || 'Paid via Brick VA'
    WHERE id = v_sap.id;

    SELECT id INTO v_income_id
    FROM public.income_transactions
    WHERE organization_id = v_req.organization_id
      AND sales_activity_payment_id = v_sap.id
    LIMIT 1;

    IF v_income_id IS NULL THEN
      INSERT INTO public.income_transactions (
        organization_id, user_id, transaction_date, amount, customer_name, payment_method,
        description, bank_account_id, sales_activity_payment_id, status, created_by
      )
      VALUES (
        v_req.organization_id,
        v_sap.created_by,
        CURRENT_DATE,
        v_amount,
        COALESCE(v_sa.client_name, 'Customer'),
        'bank_transfer',
        'Brick VA - Piutang payment',
        v_bank_id,
        v_sap.id,
        'pending',
        v_sap.created_by
      )
      RETURNING id INTO v_income_id;
    ELSE
      UPDATE public.income_transactions
      SET
        bank_account_id = COALESCE(bank_account_id, v_bank_id),
        payment_method = 'bank_transfer'
      WHERE id = v_income_id;
    END IF;

    SELECT * INTO v_income FROM public.income_transactions WHERE id = v_income_id FOR UPDATE;

    IF v_income.deposit_confirmed_at IS NULL THEN
      v_new_status := public.income_status_after_deposit(
        v_income.income_type_id,
        v_income.category_id,
        COALESCE(v_income.bank_account_id, v_bank_id)
      );

      UPDATE public.income_transactions
      SET
        deposit_confirmed_at = now(),
        deposit_confirmed_by = v_sap.created_by,
        deposit_source = 'brick_va',
        status = v_new_status,
        bank_account_id = COALESCE(bank_account_id, v_bank_id),
        updated_at = now()
      WHERE id = v_income_id;

      PERFORM public.credit_income_bank_deposit(
        v_income_id,
        COALESCE(v_income.bank_account_id, v_bank_id),
        v_req.organization_id,
        v_amount,
        v_sap.created_by,
        'Brick VA settlement'
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'income_id', v_income_id,
    'bank_account_id', v_bank_id,
    'auto_confirmed', v_auto_confirm
  );
END;
$$;


ALTER FUNCTION "public"."apply_brick_va_settlement"("p_brick_payment_request_id" "uuid", "p_brick_payment_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_catalog_checkout_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_activity_id" "text", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_line jsonb;
  v_line_idx integer := 0;
  v_line_key text;
  v_scope text;
  v_applied integer := 0;
  v_skipped integer := 0;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_activity_id IS NULL OR btrim(p_activity_id) = '' THEN
    RAISE EXCEPTION 'catalog_stock_activity_required';
  END IF;

  v_outlet := p_outlet_id;
  IF v_outlet IS NULL THEN
    SELECT id INTO v_outlet
    FROM public.pos_outlets
    WHERE organization_id = p_organization_id
    ORDER BY is_default DESC, sort_order, created_at
    LIMIT 1;
  END IF;
  IF v_outlet IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_outlet_required';
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_line_idx := v_line_idx + 1;
    v_line_key := COALESCE(NULLIF(btrim(v_line ->> 'line_key'), ''), 'L' || v_line_idx::text);
    v_scope := COALESCE(NULLIF(btrim(v_line ->> 'stock_scope'), ''), 'full');
    IF v_scope NOT IN ('full', 'recipe_only', 'finished_goods_only') THEN
      v_scope := 'full';
    END IF;

    -- Idempotent per activity + line_key (allows mixed scopes in one checkout).
    IF EXISTS (
      SELECT 1
      FROM public.catalog_stock_movements
      WHERE organization_id = p_organization_id
        AND reference_type = 'store_checkout'
        AND reference_id LIKE p_activity_id || ':' || v_line_key || ':%'
    ) THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    PERFORM public._apply_catalog_stock_lines(
      p_organization_id,
      v_outlet,
      'store_checkout',
      p_activity_id,
      jsonb_build_array(v_line || jsonb_build_object('line_key', v_line_key)),
      v_scope
    );
    v_applied := v_applied + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'outlet_id', v_outlet,
    'applied', v_applied,
    'skipped', v_skipped
  );
END;
$$;


ALTER FUNCTION "public"."apply_catalog_checkout_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_activity_id" "text", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_catalog_checkout_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_activity_id" "text", "p_lines" "jsonb") IS 'Checkout stock deduct. Optional per-line stock_scope (full|recipe_only|finished_goods_only). Idempotent per activity_id+line_key.';



CREATE OR REPLACE FUNCTION "public"."apply_catalog_fulfillment_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_fulfillment_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_batch text;
  v_ref_prefix text;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;

  v_outlet := p_outlet_id;
  IF v_outlet IS NULL AND p_session_id IS NOT NULL THEN
    SELECT outlet_id INTO v_outlet
    FROM public.pos_table_sessions
    WHERE id = p_session_id AND organization_id = p_organization_id;
  END IF;
  IF v_outlet IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_outlet_required';
  END IF;

  v_batch := COALESCE(NULLIF(btrim(p_fulfillment_id), ''), gen_random_uuid()::text);
  v_ref_prefix := COALESCE(p_session_id::text, v_batch) || ':fulfill:' || v_batch;

  PERFORM public._apply_catalog_stock_lines(
    p_organization_id,
    v_outlet,
    'pos_fulfillment',
    v_ref_prefix,
    p_lines,
    'finished_goods_only'
  );

  RETURN jsonb_build_object('ok', true, 'outlet_id', v_outlet, 'fulfillment_id', v_batch);
END;
$$;


ALTER FUNCTION "public"."apply_catalog_fulfillment_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_fulfillment_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_catalog_ingredient_produce"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_output_ingredient_id" "uuid", "p_produce_qty" numeric, "p_activity_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_recipe_id uuid;
  v_yield numeric;
  v_scale numeric;
  v_line record;
  v_stock numeric;
  v_batch_cost numeric := 0;
  v_unit_cost numeric := 0;
  v_cost_qty numeric := 0;
  v_line_cost numeric;
  v_avg numeric;
  v_track_cogs boolean;
  v_output_track boolean;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_outlet_required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.pos_outlets o
    WHERE o.id = p_outlet_id
      AND o.organization_id = p_organization_id
      AND NOT COALESCE(o.is_deleted, false)
  ) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_output_ingredient_id IS NULL THEN
    RAISE EXCEPTION 'catalog_produce_output_required';
  END IF;
  IF p_produce_qty IS NULL OR p_produce_qty <= 0 THEN
    RAISE EXCEPTION 'catalog_produce_qty_required';
  END IF;
  IF p_activity_id IS NULL OR btrim(p_activity_id) = '' THEN
    RAISE EXCEPTION 'catalog_produce_activity_required';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_stock_movements
    WHERE organization_id = p_organization_id
      AND reference_type = 'ingredient_produce'
      AND reference_id LIKE p_activity_id || ':%'
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'duplicate');
  END IF;

  SELECT track_inventory INTO v_output_track
  FROM public.catalog_ingredients
  WHERE id = p_output_ingredient_id
    AND organization_id = p_organization_id
    AND is_deleted = false
    AND kind = 'semi_finished';
  IF v_output_track IS NOT TRUE THEN
    RAISE EXCEPTION 'catalog_produce_output_invalid';
  END IF;

  SELECT r.id, r.yield_qty
    INTO v_recipe_id, v_yield
  FROM public.catalog_ingredient_recipes r
  WHERE r.output_ingredient_id = p_output_ingredient_id
    AND r.organization_id = p_organization_id;
  IF v_recipe_id IS NULL OR v_yield IS NULL OR v_yield <= 0 THEN
    RAISE EXCEPTION 'catalog_produce_recipe_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.catalog_ingredient_recipe_lines l
    WHERE l.recipe_id = v_recipe_id AND l.quantity > 0
  ) THEN
    RAISE EXCEPTION 'catalog_produce_recipe_required';
  END IF;

  v_scale := p_produce_qty / v_yield;

  -- Pre-check raw stock (tracked ingredients only)
  FOR v_line IN
    SELECT l.ingredient_id, l.quantity
    FROM public.catalog_ingredient_recipe_lines l
    JOIN public.catalog_ingredients i ON i.id = l.ingredient_id
    WHERE l.recipe_id = v_recipe_id
      AND l.quantity > 0
      AND i.track_inventory = true
      AND i.is_deleted = false
  LOOP
    SELECT io.in_stock INTO v_stock
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = v_line.ingredient_id
      AND io.outlet_id = p_outlet_id;
    v_stock := COALESCE(v_stock, 0);
    IF v_stock < (v_line.quantity * v_scale) THEN
      RAISE EXCEPTION 'catalog_stock_insufficient';
    END IF;
  END LOOP;

  -- Consume raw ingredients + accumulate batch cost for COGS
  FOR v_line IN
    SELECT l.ingredient_id, l.quantity
    FROM public.catalog_ingredient_recipe_lines l
    JOIN public.catalog_ingredients i ON i.id = l.ingredient_id
    WHERE l.recipe_id = v_recipe_id
      AND l.quantity > 0
      AND i.track_inventory = true
      AND i.is_deleted = false
  LOOP
    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      p_outlet_id,
      'ingredient',
      NULL,
      NULL,
      v_line.ingredient_id,
      'recipe_consume',
      -(v_line.quantity * v_scale),
      'ingredient_produce',
      p_activity_id || ':raw:' || v_line.ingredient_id::text,
      'Produce recipe consume'
    );

    SELECT io.avg_cost, io.track_cogs
      INTO v_avg, v_track_cogs
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = v_line.ingredient_id
      AND io.outlet_id = p_outlet_id;
    IF v_track_cogs IS TRUE THEN
      v_line_cost := COALESCE(v_avg, 0) * (v_line.quantity * v_scale);
      v_batch_cost := v_batch_cost + v_line_cost;
      v_cost_qty := v_cost_qty + (v_line.quantity * v_scale);
    END IF;
  END LOOP;

  IF p_produce_qty > 0 AND v_batch_cost > 0 THEN
    v_unit_cost := v_batch_cost / p_produce_qty;
  ELSE
    v_unit_cost := 0;
  END IF;

  -- Weighted avg on output before inbound (same order as PO)
  PERFORM public.catalog_po_update_avg_cost(
    p_organization_id,
    p_outlet_id,
    'ingredient',
    NULL,
    NULL,
    p_output_ingredient_id,
    p_produce_qty,
    v_unit_cost
  );

  PERFORM public.apply_catalog_stock_movement(
    p_organization_id,
    p_outlet_id,
    'ingredient',
    NULL,
    NULL,
    p_output_ingredient_id,
    'production',
    p_produce_qty,
    'ingredient_produce',
    p_activity_id || ':out:' || p_output_ingredient_id::text,
    'Produce semi-finished'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'outlet_id', p_outlet_id,
    'scale', v_scale,
    'unit_cost', v_unit_cost,
    'batch_cost', v_batch_cost
  );
END;
$$;


ALTER FUNCTION "public"."apply_catalog_ingredient_produce"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_output_ingredient_id" "uuid", "p_produce_qty" numeric, "p_activity_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_catalog_ingredient_produce"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_output_ingredient_id" "uuid", "p_produce_qty" numeric, "p_activity_id" "text") IS 'Produce semi-finished stock: consume raw recipe lines, update weighted avg cost, add production inbound.';



CREATE OR REPLACE FUNCTION "public"."apply_catalog_kitchen_commit_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_commit_batch_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_line jsonb;
  v_batch text;
  v_line_fingerprint text;
  v_line_index integer;
  v_qty numeric;
  v_ref_prefix text;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_session_required';
  END IF;

  v_outlet := p_outlet_id;
  IF v_outlet IS NULL THEN
    SELECT outlet_id INTO v_outlet
    FROM public.pos_table_sessions
    WHERE id = p_session_id AND organization_id = p_organization_id;
  END IF;
  IF v_outlet IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_outlet_required';
  END IF;

  v_batch := COALESCE(NULLIF(btrim(p_commit_batch_id), ''), gen_random_uuid()::text);
  v_ref_prefix := p_session_id::text || ':' || v_batch;

  PERFORM public._apply_catalog_stock_lines(
    p_organization_id,
    v_outlet,
    'pos_kitchen_commit',
    v_ref_prefix,
    p_lines,
    'recipe_only'
  );

  FOR v_line IN SELECT value FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_line_fingerprint := NULLIF(btrim(v_line ->> 'line_fingerprint'), '');
    v_line_index := GREATEST(1, COALESCE((v_line ->> 'line_index')::integer, 1));
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    IF v_line_fingerprint IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.pos_session_stock_commits (
      organization_id,
      outlet_id,
      session_id,
      line_fingerprint,
      line_index,
      committed_qty,
      last_reference_id
    ) VALUES (
      p_organization_id,
      v_outlet,
      p_session_id,
      v_line_fingerprint,
      v_line_index,
      v_qty,
      v_ref_prefix
    )
    ON CONFLICT (session_id, line_fingerprint) DO UPDATE SET
      committed_qty = public.pos_session_stock_commits.committed_qty + EXCLUDED.committed_qty,
      line_index = EXCLUDED.line_index,
      last_reference_id = EXCLUDED.last_reference_id,
      last_committed_at = now(),
      updated_at = now();
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'outlet_id', v_outlet, 'batch_id', v_batch);
END;
$$;


ALTER FUNCTION "public"."apply_catalog_kitchen_commit_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_commit_batch_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_catalog_kitchen_commit_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_commit_batch_id" "text") IS 'Kitchen print: deduct recipe ingredients (delta). Updates pos_session_stock_commits.';



CREATE OR REPLACE FUNCTION "public"."apply_catalog_stock_movement"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_movement_type" "text", "p_qty_delta" numeric, "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_current numeric(14, 3);
  v_next numeric(14, 3);
  v_variant uuid;
  v_row public.catalog_stock_movements%ROWTYPE;
  v_is_service boolean := (auth.role() = 'service_role');
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;

  IF v_is_service THEN
    IF NOT EXISTS (SELECT 1 FROM public.organizations o WHERE o.id = p_organization_id) THEN
      RAISE EXCEPTION 'catalog_stock_forbidden';
    END IF;
  ELSIF p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;

  IF p_qty_delta IS NULL OR p_qty_delta = 0 THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'zero_delta');
  END IF;

  v_variant := p_variant_id;

  IF p_item_kind = 'product' THEN
    IF v_variant IS NULL THEN
      SELECT v.id
        INTO v_variant
      FROM public.catalog_product_variants v
      WHERE v.product_id = p_product_id
      ORDER BY v.sort_order, v.created_at
      LIMIT 1;
    END IF;

    IF v_variant IS NOT NULL THEN
      SELECT vo.in_stock INTO v_current
      FROM public.catalog_product_variant_outlets vo
      WHERE vo.variant_id = v_variant AND vo.outlet_id = p_outlet_id
      FOR UPDATE;
      IF v_current IS NULL THEN
        INSERT INTO public.catalog_product_variant_outlets (
          variant_id, outlet_id, organization_id, in_stock
        ) VALUES (v_variant, p_outlet_id, p_organization_id, 0)
        ON CONFLICT (variant_id, outlet_id) DO NOTHING;
        SELECT vo.in_stock INTO v_current
        FROM public.catalog_product_variant_outlets vo
        WHERE vo.variant_id = v_variant AND vo.outlet_id = p_outlet_id
        FOR UPDATE;
      END IF;
    ELSE
      SELECT po.in_stock INTO v_current
      FROM public.catalog_product_outlets po
      WHERE po.product_id = p_product_id AND po.outlet_id = p_outlet_id
      FOR UPDATE;
      IF v_current IS NULL THEN
        INSERT INTO public.catalog_product_outlets (
          product_id, outlet_id, organization_id, in_stock
        ) VALUES (p_product_id, p_outlet_id, p_organization_id, 0)
        ON CONFLICT (product_id, outlet_id) DO NOTHING;
        SELECT po.in_stock INTO v_current
        FROM public.catalog_product_outlets po
        WHERE po.product_id = p_product_id AND po.outlet_id = p_outlet_id
        FOR UPDATE;
      END IF;
    END IF;
  ELSIF p_item_kind = 'ingredient' THEN
    SELECT io.in_stock INTO v_current
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id
    FOR UPDATE;
    IF v_current IS NULL THEN
      INSERT INTO public.catalog_ingredient_outlets (
        ingredient_id, outlet_id, organization_id, in_stock
      ) VALUES (p_ingredient_id, p_outlet_id, p_organization_id, 0)
      ON CONFLICT (ingredient_id, outlet_id) DO NOTHING;
      SELECT io.in_stock INTO v_current
      FROM public.catalog_ingredient_outlets io
      WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id
      FOR UPDATE;
    END IF;
  ELSE
    RAISE EXCEPTION 'catalog_stock_kind_invalid';
  END IF;

  v_current := COALESCE(v_current, 0);
  v_next := v_current + p_qty_delta;
  IF v_next < 0 AND p_movement_type <> 'adjustment' THEN
    RAISE EXCEPTION 'catalog_stock_insufficient';
  END IF;
  IF v_next < 0 THEN
    v_next := 0;
  END IF;

  IF p_item_kind = 'product' AND v_variant IS NOT NULL THEN
    UPDATE public.catalog_product_variant_outlets
    SET in_stock = v_next
    WHERE variant_id = v_variant AND outlet_id = p_outlet_id;
  ELSIF p_item_kind = 'product' THEN
    UPDATE public.catalog_product_outlets
    SET in_stock = v_next
    WHERE product_id = p_product_id AND outlet_id = p_outlet_id;
  ELSE
    UPDATE public.catalog_ingredient_outlets
    SET in_stock = v_next
    WHERE ingredient_id = p_ingredient_id AND outlet_id = p_outlet_id;
  END IF;

  INSERT INTO public.catalog_stock_movements (
    organization_id,
    outlet_id,
    item_kind,
    product_id,
    variant_id,
    ingredient_id,
    movement_type,
    qty_delta,
    qty_after,
    reference_type,
    reference_id,
    note,
    created_by
  )
  VALUES (
    p_organization_id,
    p_outlet_id,
    p_item_kind,
    CASE WHEN p_item_kind = 'product' THEN p_product_id ELSE NULL END,
    CASE WHEN p_item_kind = 'product' THEN v_variant ELSE NULL END,
    CASE WHEN p_item_kind = 'ingredient' THEN p_ingredient_id ELSE NULL END,
    p_movement_type,
    p_qty_delta,
    v_next,
    p_reference_type,
    p_reference_id,
    p_note,
    auth.uid()
  )
  RETURNING * INTO v_row;

  RETURN to_jsonb(v_row);
END;
$$;


ALTER FUNCTION "public"."apply_catalog_stock_movement"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_movement_type" "text", "p_qty_delta" numeric, "p_reference_type" "text", "p_reference_id" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_reserve_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line jsonb;
  v_product uuid;
  v_variant uuid;
  v_variant_key uuid;
  v_target_qty numeric;
  v_current_qty numeric;
  v_delta numeric;
  v_reserve text;
  v_ref text;
  v_outlet uuid;
  v_null_variant constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_outlet_required';
  END IF;
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'catalog_stock_session_required';
  END IF;

  v_outlet := p_outlet_id;
  v_reserve := COALESCE(NULLIF(btrim(p_reserve_id), ''), gen_random_uuid()::text);
  v_ref := p_session_id::text || ':reserve:' || v_reserve;

  FOR v_line IN SELECT value FROM jsonb_array_elements(COALESCE(p_lines, '[]'::jsonb))
  LOOP
    v_product := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_variant := NULLIF(v_line ->> 'variant_id', '')::uuid;
    v_variant_key := COALESCE(v_variant, v_null_variant);
    v_target_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    IF v_product IS NULL OR v_target_qty < 0 THEN
      CONTINUE;
    END IF;

    SELECT reserved_qty INTO v_current_qty
    FROM public.pos_session_stock_reserves
    WHERE session_id = p_session_id
      AND product_id = v_product
      AND variant_id = v_variant_key
    FOR UPDATE;

    v_current_qty := COALESCE(v_current_qty, 0);
    v_delta := v_target_qty - v_current_qty;

    IF v_delta = 0 THEN
      CONTINUE;
    END IF;

    IF v_delta > 0 THEN
      IF v_variant IS NOT NULL THEN
        UPDATE public.catalog_product_variant_outlets
        SET reserved_qty = reserved_qty + v_delta
        WHERE variant_id = v_variant AND outlet_id = v_outlet;
      ELSE
        UPDATE public.catalog_product_outlets
        SET reserved_qty = reserved_qty + v_delta
        WHERE product_id = v_product AND outlet_id = v_outlet;
      END IF;

      PERFORM public.apply_catalog_stock_movement(
        p_organization_id,
        v_outlet,
        'product',
        v_product,
        v_variant,
        NULL,
        'reserve',
        0,
        'pos_stock_reserve',
        v_ref || ':' || v_product::text || ':+' || v_delta::text,
        'Stock reserve delta'
      );
    ELSE
      IF v_variant IS NOT NULL THEN
        UPDATE public.catalog_product_variant_outlets
        SET reserved_qty = GREATEST(0, reserved_qty + v_delta)
        WHERE variant_id = v_variant AND outlet_id = v_outlet;
      ELSE
        UPDATE public.catalog_product_outlets
        SET reserved_qty = GREATEST(0, reserved_qty + v_delta)
        WHERE product_id = v_product AND outlet_id = v_outlet;
      END IF;

      PERFORM public.apply_catalog_stock_movement(
        p_organization_id,
        v_outlet,
        'product',
        v_product,
        v_variant,
        NULL,
        'release',
        0,
        'pos_stock_reserve',
        v_ref || ':' || v_product::text || ':-' || ABS(v_delta)::text,
        'Stock reserve release delta'
      );
    END IF;

    INSERT INTO public.pos_session_stock_reserves (
      organization_id,
      outlet_id,
      session_id,
      product_id,
      variant_id,
      reserved_qty,
      last_reference_id
    )
    VALUES (
      p_organization_id,
      v_outlet,
      p_session_id,
      v_product,
      v_variant_key,
      v_target_qty,
      v_ref
    )
    ON CONFLICT ON CONSTRAINT pos_session_stock_reserves_session_product_uniq DO UPDATE SET
      reserved_qty = EXCLUDED.reserved_qty,
      last_reference_id = EXCLUDED.last_reference_id,
      last_reserved_at = now(),
      updated_at = now();
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'reserve_id', v_reserve);
END;
$$;


ALTER FUNCTION "public"."apply_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_reserve_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_reserve_id" "text") IS 'Delta reserve: p_lines qty is target cart qty; only reserve/release the difference vs ledger.';



CREATE OR REPLACE FUNCTION "public"."apply_due_subscription_change_requests"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.subscription_change_requests%ROWTYPE;
  v_applied integer := 0;
  v_employees integer;
  v_roster integer;
  v_omni_target integer;
  v_lm_target boolean;
  v_pos_target integer;
  v_pos_addon_target boolean;
  v_outlet_count integer;
  v_omni_json jsonb;
  v_lm_json jsonb;
  v_pos_json jsonb;
  v_ai_json jsonb;
  v_ai_target integer;
  v_ai_active integer;
BEGIN
  IF current_user IN ('anon', 'authenticated') AND auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  FOR v_row IN
    SELECT *
    FROM public.subscription_change_requests
    WHERE status = 'pending'
      AND scheduled_date <= now()
      AND (
        current_user NOT IN ('anon', 'authenticated')
        OR public.user_can_manage_subscription(organization_id)
      )
    ORDER BY scheduled_date ASC
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_employees := public.count_active_employees_for_org(v_row.organization_id);
      IF v_employees > v_row.target_member_count THEN
        RAISE EXCEPTION 'active employees (%) exceed target member count (%)', v_employees, v_row.target_member_count;
      END IF;

      v_omni_json := v_row.target_addon_selections -> 'omnichannel_roster';
      IF v_omni_json IS NOT NULL AND jsonb_typeof(v_omni_json) = 'object' THEN
        IF COALESCE((v_omni_json ->> 'included')::boolean, false) THEN
          v_omni_target := GREATEST(0, COALESCE((v_omni_json ->> 'quantity')::integer, 0));
        ELSE
          v_omni_target := 0;
        END IF;
      ELSE
        SELECT COALESCE(os.omnichannel_paid_seat_count, 0)
        INTO v_omni_target
        FROM public.organization_subscriptions os
        WHERE os.organization_id = v_row.organization_id;
      END IF;

      SELECT COUNT(*)::integer INTO v_roster
      FROM public.organization_omnichannel_staff oos
      WHERE oos.organization_id = v_row.organization_id;

      IF v_roster > v_omni_target THEN
        RAISE EXCEPTION 'omnichannel roster (%) exceeds target paid seats (%)', v_roster, v_omni_target;
      END IF;

      v_lm_json := v_row.target_addon_selections -> 'lead_magnet';
      IF v_lm_json IS NOT NULL AND jsonb_typeof(v_lm_json) = 'object' THEN
        v_lm_target := COALESCE((v_lm_json ->> 'included')::boolean, false);
      ELSE
        SELECT COALESCE(os.lead_magnet_active, false)
        INTO v_lm_target
        FROM public.organization_subscriptions os
        WHERE os.organization_id = v_row.organization_id;
      END IF;

      v_pos_json := v_row.target_addon_selections -> 'pos_outlets';
      IF v_pos_json IS NOT NULL AND jsonb_typeof(v_pos_json) = 'object' THEN
        v_pos_addon_target := COALESCE((v_pos_json ->> 'included')::boolean, false);
        IF v_pos_addon_target THEN
          v_pos_target := GREATEST(0, LEAST(20, COALESCE((v_pos_json ->> 'quantity')::integer, 0)));
        ELSE
          v_pos_target := 0;
        END IF;
      ELSE
        SELECT COALESCE(os.pos_paid_outlet_count, 0), COALESCE(os.pos_addon_active, false)
        INTO v_pos_target, v_pos_addon_target
        FROM public.organization_subscriptions os
        WHERE os.organization_id = v_row.organization_id;
      END IF;

      SELECT COUNT(*)::integer INTO v_outlet_count
      FROM public.pos_outlets po
      WHERE po.organization_id = v_row.organization_id
        AND COALESCE(po.is_deleted, false) = false;

      IF v_outlet_count > (1 + v_pos_target) THEN
        RAISE EXCEPTION 'active outlets (%) exceed POS quota (%)', v_outlet_count, (1 + v_pos_target);
      END IF;

      v_ai_json := v_row.target_addon_selections -> 'ai_employee';
      IF v_ai_json IS NOT NULL AND jsonb_typeof(v_ai_json) = 'object' THEN
        IF COALESCE((v_ai_json ->> 'included')::boolean, false) THEN
          v_ai_target := GREATEST(0, LEAST(50, COALESCE((v_ai_json ->> 'quantity')::integer, 0)));
        ELSE
          v_ai_target := 0;
        END IF;
      ELSE
        SELECT COALESCE(os.ai_employee_paid_seat_count, 0)
        INTO v_ai_target
        FROM public.organization_subscriptions os
        WHERE os.organization_id = v_row.organization_id;
      END IF;

      v_ai_active := public.count_active_ai_employees_for_org(v_row.organization_id);
      IF v_ai_active > v_ai_target THEN
        RAISE EXCEPTION 'active AI employees (%) exceed target seats (%)', v_ai_active, v_ai_target;
      END IF;

      UPDATE public.organization_subscriptions os
      SET
        subscription_plan_id = COALESCE(v_row.target_plan_id, os.subscription_plan_id),
        member_count = v_row.target_member_count,
        billing_cycle = COALESCE(v_row.target_billing_cycle, os.billing_cycle),
        omnichannel_paid_seat_count = v_omni_target,
        lead_magnet_active = v_lm_target,
        pos_paid_outlet_count = v_pos_target,
        pos_addon_active = v_pos_addon_target,
        ai_employee_paid_seat_count = v_ai_target,
        updated_at = now()
      WHERE os.organization_id = v_row.organization_id;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'organization subscription not found';
      END IF;

      UPDATE public.subscription_change_requests
      SET status = 'applied', applied_at = now(), apply_error = NULL
      WHERE id = v_row.id;

      v_applied := v_applied + 1;
    EXCEPTION
      WHEN OTHERS THEN
        UPDATE public.subscription_change_requests
        SET status = 'failed', apply_error = SQLERRM, applied_at = now()
        WHERE id = v_row.id;
    END;
  END LOOP;

  RETURN v_applied;
END;
$$;


ALTER FUNCTION "public"."apply_due_subscription_change_requests"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_due_subscription_change_requests"() IS 'Applies pending subscription_change_requests whose scheduled_date <= now(). Returns count applied.';



CREATE OR REPLACE FUNCTION "public"."apply_late_arrival_penalties"("p_attendance_record_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ar public.attendance_records%ROWTYPE;
  v_emp public.employees%ROWTYPE;
  v_settings public.penalty_settings%ROWTYPE;
  v_sched record;
  v_penalizable integer;
  v_rule record;
  v_amount numeric;
  v_hourly numeric;
  v_basic numeric;
  v_daily_sum numeric := 0;
  v_monthly_sum numeric := 0;
  v_applied integer := 0;
  v_month_start date;
  v_month_end date;
  v_row_count integer;
  v_tolerance integer;
BEGIN
  SELECT *
  INTO v_ar
  FROM public.attendance_records ar
  WHERE ar.id = p_attendance_record_id;

  IF v_ar.id IS NULL THEN
    RETURN jsonb_build_object('applied', 0, 'reason', 'attendance_not_found');
  END IF;

  IF COALESCE(v_ar.is_late, false) IS NOT TRUE OR COALESCE(v_ar.late_minutes, 0) <= 0 THEN
    RETURN jsonb_build_object('applied', 0, 'reason', 'not_late');
  END IF;

  IF public.has_penalty_exemption(v_ar.employee_id, v_ar.organization_id, v_ar.attendance_date, NULL) THEN
    RETURN jsonb_build_object('applied', 0, 'reason', 'exempt_all_rules');
  END IF;

  SELECT *
  INTO v_emp
  FROM public.employees e
  WHERE e.id = v_ar.employee_id;

  SELECT *
  INTO v_settings
  FROM public.penalty_settings ps
  WHERE ps.organization_id = v_ar.organization_id;

  IF v_settings.id IS NULL OR COALESCE(v_settings.enable_automatic_penalties, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('applied', 0, 'reason', 'automatic_penalties_disabled');
  END IF;

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(
    v_ar.employee_id,
    v_ar.organization_id,
    v_ar.attendance_date
  ) r
  LIMIT 1;

  v_tolerance := COALESCE(v_sched.late_tolerance_minutes, 0);
  v_penalizable := GREATEST(0, COALESCE(v_ar.late_minutes, 0) - v_tolerance);

  IF v_penalizable <= 0 THEN
    RETURN jsonb_build_object(
      'applied', 0,
      'reason', 'within_tolerance',
      'penalizable_minutes', 0,
      'late_tolerance_minutes', v_tolerance
    );
  END IF;

  SELECT COALESCE(epi.basic_salary, 0)
  INTO v_basic
  FROM public.employee_payroll_info epi
  WHERE epi.employee_id = v_ar.employee_id
  ORDER BY epi.updated_at DESC NULLS LAST
  LIMIT 1;

  v_month_start := date_trunc('month', v_ar.attendance_date)::date;
  v_month_end := (date_trunc('month', v_ar.attendance_date) + interval '1 month - 1 day')::date;

  SELECT COALESCE(SUM(ap.penalty_amount), 0)
  INTO v_daily_sum
  FROM public.attendance_penalties ap
  WHERE ap.employee_id = v_ar.employee_id
    AND ap.organization_id = v_ar.organization_id
    AND ap.applied_date = v_ar.attendance_date
    AND ap.status = 'active';

  SELECT COALESCE(SUM(ap.penalty_amount), 0)
  INTO v_monthly_sum
  FROM public.attendance_penalties ap
  WHERE ap.employee_id = v_ar.employee_id
    AND ap.organization_id = v_ar.organization_id
    AND ap.applied_date BETWEEN v_month_start AND v_month_end
    AND ap.status = 'active';

  FOR v_rule IN
    SELECT pr.*
    FROM public.penalty_rules pr
    WHERE pr.organization_id = v_ar.organization_id
      AND pr.rule_type = 'late_arrival'
      AND COALESCE(pr.is_active, true)
      AND v_penalizable >= COALESCE(pr.threshold_minutes, 0)
      AND (
        COALESCE(pr.applies_to_all, true)
        OR (
          v_emp.department_id IS NOT NULL
          AND v_emp.department_id = ANY (COALESCE(pr.specific_departments, ARRAY[]::uuid[]))
        )
      )
    ORDER BY pr.threshold_minutes DESC
  LOOP
    IF public.has_penalty_exemption(v_ar.employee_id, v_ar.organization_id, v_ar.attendance_date, v_rule.id) THEN
      CONTINUE;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.attendance_penalties ap
      WHERE ap.attendance_record_id = v_ar.id
        AND ap.penalty_rule_id = v_rule.id
        AND ap.applied_date = v_ar.attendance_date
    ) THEN
      CONTINUE;
    END IF;

    v_amount := 0;

    IF v_rule.calculation_type = 'hourly' THEN
      v_hourly := COALESCE(v_rule.hourly_rate, v_settings.default_hourly_rate, 0);
      v_amount := round((v_penalizable / 60.0) * v_hourly, 2);
    ELSIF v_rule.calculation_type = 'salary_percentage' THEN
      v_amount := round(
        COALESCE(v_basic, 0) * COALESCE(v_rule.salary_percentage, v_settings.default_salary_percentage, 0) / 100.0,
        2
      );
    ELSE
      v_amount := round(COALESCE(v_rule.penalty_amount, 0), 2);
    END IF;

    IF COALESCE(v_settings.minimum_penalty_amount, 0) > 0 AND v_amount > 0 THEN
      v_amount := GREATEST(v_amount, v_settings.minimum_penalty_amount);
    END IF;

    IF COALESCE(v_settings.maximum_daily_penalty, 0) > 0 THEN
      v_amount := LEAST(v_amount, GREATEST(0, v_settings.maximum_daily_penalty - v_daily_sum));
    END IF;

    IF COALESCE(v_settings.maximum_monthly_penalty, 0) > 0 THEN
      v_amount := LEAST(v_amount, GREATEST(0, v_settings.maximum_monthly_penalty - v_monthly_sum));
    END IF;

    IF COALESCE(v_rule.max_penalty_per_month, 0) > 0 THEN
      v_amount := LEAST(v_amount, v_rule.max_penalty_per_month);
    END IF;

    IF v_amount <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.attendance_penalties (
      attendance_record_id,
      employee_id,
      organization_id,
      penalty_rule_id,
      penalty_amount,
      penalty_reason,
      applied_date,
      status,
      auto_generated,
      violation_details
    )
    VALUES (
      v_ar.id,
      v_ar.employee_id,
      v_ar.organization_id,
      v_rule.id,
      v_amount,
      COALESCE(v_rule.name, 'Late arrival'),
      v_ar.attendance_date,
      'active',
      true,
      jsonb_build_object(
        'shift_id', v_sched.shift_id,
        'employee_shift_id', v_sched.employee_shift_id,
        'schedule_source', v_sched.source,
        'start_time', v_sched.start_time,
        'late_minutes', v_ar.late_minutes,
        'late_tolerance_minutes', v_tolerance,
        'penalizable_minutes', v_penalizable,
        'calculation_type', v_rule.calculation_type,
        'visit_day_mode', v_ar.visit_day_mode,
        'check_in_source', v_ar.check_in_source,
        'client_visit_id', v_ar.client_visit_id
      )
    )
    ON CONFLICT (attendance_record_id, penalty_rule_id, applied_date) DO NOTHING;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    IF v_row_count > 0 THEN
      v_applied := v_applied + 1;
      SELECT COALESCE(SUM(ap.penalty_amount), 0)
      INTO v_daily_sum
      FROM public.attendance_penalties ap
      WHERE ap.employee_id = v_ar.employee_id
        AND ap.organization_id = v_ar.organization_id
        AND ap.applied_date = v_ar.attendance_date
        AND ap.status = 'active';

      SELECT COALESCE(SUM(ap.penalty_amount), 0)
      INTO v_monthly_sum
      FROM public.attendance_penalties ap
      WHERE ap.employee_id = v_ar.employee_id
        AND ap.organization_id = v_ar.organization_id
        AND ap.applied_date BETWEEN v_month_start AND v_month_end
        AND ap.status = 'active';
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'applied', v_applied,
    'penalizable_minutes', v_penalizable,
    'late_tolerance_minutes', v_tolerance
  );
END;
$$;


ALTER FUNCTION "public"."apply_late_arrival_penalties"("p_attendance_record_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_meta_session_expired_conversations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  n INT := 0;
  r RECORD;
  v_expired_id UUID;
  v_old_name TEXT;
BEGIN
  FOR r IN
    SELECT w.id, w.organization_id, w.lead_status_id, ls.name AS status_name
    FROM public.whatsapp_conversations w
    LEFT JOIN public.lead_statuses ls ON ls.id = w.lead_status_id
    WHERE w.meta_session_expires_at IS NOT NULL
      AND w.meta_session_expires_at < NOW()
  LOOP
    IF lower(btrim(COALESCE(r.status_name, ''))) IN ('closed', 'lost', 'converted', 'expired') THEN
      CONTINUE;
    END IF;

    SELECT ls2.id
    INTO v_expired_id
    FROM public.lead_statuses ls2
    WHERE lower(btrim(ls2.name)) = 'expired'
      AND (ls2.organization_id = r.organization_id OR ls2.organization_id IS NULL)
    ORDER BY CASE WHEN ls2.organization_id IS NOT DISTINCT FROM r.organization_id THEN 0 ELSE 1 END
    LIMIT 1;

    IF v_expired_id IS NULL THEN
      CONTINUE;
    END IF;

    v_old_name := r.status_name;

    UPDATE public.whatsapp_conversations
    SET lead_status_id = v_expired_id, updated_at = NOW()
    WHERE id = r.id;

    INSERT INTO public.whatsapp_conversation_status_history (
      conversation_id, old_status, new_status, changed_at, changed_by, changed_by_name, organization_id
    ) VALUES (
      r.id, v_old_name, 'Expired', NOW(), NULL, 'Meta', r.organization_id
    );

    n := n + 1;
  END LOOP;

  -- Instagram native conversations (same Meta-driven rule; no WA-style history table).
  FOR r IN
    SELECT i.id, i.organization_id, i.lead_status_id, ls.name AS status_name
    FROM public.instagram_conversations i
    LEFT JOIN public.lead_statuses ls ON ls.id = i.lead_status_id
    WHERE i.meta_session_expires_at IS NOT NULL
      AND i.meta_session_expires_at < NOW()
  LOOP
    IF lower(btrim(COALESCE(r.status_name, ''))) IN ('closed', 'lost', 'converted', 'expired') THEN
      CONTINUE;
    END IF;

    SELECT ls2.id
    INTO v_expired_id
    FROM public.lead_statuses ls2
    WHERE lower(btrim(ls2.name)) = 'expired'
      AND (ls2.organization_id = r.organization_id OR ls2.organization_id IS NULL)
    ORDER BY CASE WHEN ls2.organization_id IS NOT DISTINCT FROM r.organization_id THEN 0 ELSE 1 END
    LIMIT 1;

    IF v_expired_id IS NULL THEN
      CONTINUE;
    END IF;

    UPDATE public.instagram_conversations
    SET lead_status_id = v_expired_id, updated_at = NOW()
    WHERE id = r.id;

    n := n + 1;
  END LOOP;

  RETURN n;
END;
$$;


ALTER FUNCTION "public"."apply_meta_session_expired_conversations"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_meta_session_expired_conversations"() IS 'Sets lead_status_id to Expired when meta_session_expires_at < now() from Meta; skips Closed/Lost/Converted/Expired. Inserts WA conversation status history. Schedule via pg_cron.';



CREATE OR REPLACE FUNCTION "public"."apply_performance_bonus"("p_payment_terms_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pt public.kol_payment_terms%ROWTYPE;
  v_bonus numeric(15, 2);
  v_total_pct numeric;
BEGIN
  SELECT * INTO v_pt FROM public.kol_payment_terms WHERE id = p_payment_terms_id;
  IF NOT FOUND OR v_pt.type <> 'agreement' THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(SUM(LEAST(t.bonus_percentage, 100)), 0),
    COALESCE(SUM(COALESCE(v_pt.base_amount, 0) * LEAST(t.bonus_percentage, 100) / 100), 0)
  INTO v_total_pct, v_bonus
  FROM public.kol_performance_thresholds t
  WHERE t.payment_terms_id = p_payment_terms_id
    AND t.is_achieved = true
    AND t.is_active IS NOT FALSE;

  v_total_pct := LEAST(v_total_pct, 100);
  v_bonus := LEAST(v_bonus, COALESCE(v_pt.base_amount, 0));

  UPDATE public.kol_payment_terms
  SET bonus_amount = v_bonus, updated_at = timezone('utc'::text, now())
  WHERE id = p_payment_terms_id
    AND bonus_amount IS DISTINCT FROM v_bonus;

  IF v_pt.campaign_id IS NOT NULL AND v_pt.kol_profile_id IS NOT NULL THEN
    PERFORM public.refresh_budget_allocation_payout(v_pt.campaign_id, v_pt.kol_profile_id);
  END IF;
END;
$$;


ALTER FUNCTION "public"."apply_performance_bonus"("p_payment_terms_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_sales_outlet_quota"("p_organization_id" "uuid", "p_pos_enabled" boolean, "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_resolved jsonb;
  v_quota integer;
  v_keep uuid[] := ARRAY[]::uuid[];
  v_id uuid;
  v_default uuid;
  v_closed jsonb := '[]'::jsonb;
BEGIN
  IF NOT public.sales_contract_apply_active() THEN
    RAISE EXCEPTION 'outlet changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_cms_admin() THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;

  v_resolved := public.resolve_sales_outlet_package(
    p_organization_id,
    p_pos_enabled,
    p_outlet_quota,
    p_keep_outlet_ids
  );
  v_quota := (v_resolved->>'outlet_quota')::integer;

  SELECT coalesce(array_agg(value::uuid), ARRAY[]::uuid[])
  INTO v_keep
  FROM jsonb_array_elements_text(v_resolved->'keep_outlet_ids') AS value;

  UPDATE public.organization_subscriptions os
  SET
    sales_outlet_quota = v_quota,
    pos_addon_active = coalesce(p_pos_enabled, false)
  WHERE os.organization_id = p_organization_id;

  IF NOT coalesce(p_pos_enabled, false) OR v_quota = 0 OR coalesce(cardinality(v_keep), 0) > 0 THEN
    UPDATE public.pos_outlets o
    SET
      is_active = false,
      is_default = false
    WHERE o.organization_id = p_organization_id
      AND coalesce(o.is_deleted, false) = false
      AND (
        NOT coalesce(p_pos_enabled, false)
        OR v_quota = 0
        OR NOT (o.id = ANY (v_keep))
      )
      AND (o.is_active OR o.is_default);
  END IF;

  IF coalesce(p_pos_enabled, false) AND v_quota > 0 AND coalesce(cardinality(v_keep), 0) = 0 THEN
    FOR v_id IN
      SELECT o.id
      FROM public.pos_outlets o
      WHERE o.organization_id = p_organization_id
        AND coalesce(o.is_deleted, false) = false
        AND NOT o.is_active
      ORDER BY o.sort_order, o.name
    LOOP
      UPDATE public.pos_outlets o
      SET is_active = true
      WHERE o.id = v_id
        AND NOT o.is_active;
    END LOOP;
  ELSIF coalesce(cardinality(v_keep), 0) > 0 THEN
    FOREACH v_id IN ARRAY v_keep
    LOOP
      UPDATE public.pos_outlets o
      SET is_active = true
      WHERE o.id = v_id
        AND o.organization_id = p_organization_id
        AND NOT o.is_active;
    END LOOP;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pos_outlets o
    WHERE o.organization_id = p_organization_id
      AND coalesce(o.is_deleted, false) = false
      AND o.is_active
      AND o.is_default
  ) THEN
    SELECT o.id
    INTO v_default
    FROM public.pos_outlets o
    WHERE o.organization_id = p_organization_id
      AND coalesce(o.is_deleted, false) = false
      AND o.is_active
    ORDER BY o.sort_order, o.name
    LIMIT 1;

    IF v_default IS NOT NULL THEN
      UPDATE public.pos_outlets o
      SET is_default = false
      WHERE o.organization_id = p_organization_id
        AND o.is_default
        AND o.id IS DISTINCT FROM v_default;

      UPDATE public.pos_outlets o
      SET is_default = true
      WHERE o.id = v_default;
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(
    jsonb_build_object('id', o.id, 'name', o.name)
    ORDER BY o.name
  ), '[]'::jsonb)
  INTO v_closed
  FROM public.pos_outlets o
  WHERE o.organization_id = p_organization_id
    AND coalesce(o.is_deleted, false) = false
    AND NOT o.is_active;

  RETURN v_closed;
END;
$$;


ALTER FUNCTION "public"."apply_sales_outlet_quota"("p_organization_id" "uuid", "p_pos_enabled" boolean, "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_store_checkout_income"("p_activity_id" "uuid", "p_payment_method" "text", "p_actor" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_activity public.sales_activities%ROWTYPE;
  v_payment_id uuid;
  v_income_id uuid;
  v_income_amount numeric;
  v_income_bank uuid;
  v_income_deposit_at timestamptz;
  v_income_status text;
  v_method text;
  v_needs_bank boolean;
  v_amount numeric;
  v_bank_id uuid;
  v_actor uuid;
  v_client_name text;
  v_tx_date date;
  v_description text;
  v_payment_notes text;
  v_ref text;
  v_credited boolean := false;
BEGIN
  IF p_activity_id IS NULL THEN
    RAISE EXCEPTION 'store_checkout_not_found';
  END IF;

  SELECT * INTO v_activity
  FROM public.sales_activities
  WHERE id = p_activity_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'store_checkout_not_found';
  END IF;

  IF v_activity.activity_type IS DISTINCT FROM 'Store Checkout' THEN
    RAISE EXCEPTION 'store_checkout_wrong_type';
  END IF;

  v_amount := COALESCE(v_activity.total_amount, 0);
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'store_checkout_invalid_amount';
  END IF;

  v_method := lower(btrim(COALESCE(NULLIF(p_payment_method, ''), v_activity.payment_method, 'cash')));
  IF v_method = 'transfer' THEN
    v_method := 'bank_transfer';
  END IF;
  IF v_method NOT IN ('cash', 'bank_transfer', 'e_wallet', 'qris') THEN
    RAISE EXCEPTION 'store_checkout_invalid_payment_method';
  END IF;

  v_needs_bank := v_method IN ('bank_transfer', 'e_wallet', 'qris');

  v_actor := COALESCE(p_actor, v_activity.created_by);
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'store_checkout_actor_required';
  END IF;

  IF v_needs_bank THEN
    IF v_method = 'qris' THEN
      SELECT ba.id INTO v_bank_id
      FROM public.bank_accounts ba
      WHERE ba.organization_id = v_activity.organization_id
        AND ba.use_for_xendit_income = true
        AND ba.is_active = true
      ORDER BY ba.created_at ASC
      LIMIT 1;

      IF v_bank_id IS NULL THEN
        SELECT ba.id INTO v_bank_id
        FROM public.bank_accounts ba
        WHERE ba.organization_id = v_activity.organization_id
          AND ba.is_active = true
        ORDER BY ba.created_at ASC
        LIMIT 1;
      END IF;
    ELSE
      SELECT ba.id INTO v_bank_id
      FROM public.bank_accounts ba
      WHERE ba.organization_id = v_activity.organization_id
        AND ba.use_for_omnichannel_income = true
        AND ba.is_active = true
      ORDER BY ba.created_at ASC
      LIMIT 1;

      IF v_bank_id IS NULL THEN
        RAISE EXCEPTION 'store_checkout_omnichannel_bank_missing';
      END IF;
    END IF;
  END IF;

  v_ref := NULLIF(btrim(COALESCE(v_activity.payment_reference, '')), '');
  v_payment_notes := 'Store checkout';
  IF v_ref IS NOT NULL THEN
    v_payment_notes := v_payment_notes || ' · ' || v_ref;
  END IF;

  SELECT id INTO v_payment_id
  FROM public.sales_activity_payments
  WHERE sales_activity_id = v_activity.id
  ORDER BY created_at ASC, payment_sequence ASC
  LIMIT 1
  FOR UPDATE;

  IF v_payment_id IS NULL THEN
    INSERT INTO public.sales_activity_payments (
      sales_activity_id,
      organization_id,
      payment_amount,
      payment_date,
      payment_method,
      payment_type,
      payment_sequence,
      notes,
      receipt_url,
      created_by,
      transfer_verification_status,
      transfer_verified_at,
      transfer_verified_by
    )
    VALUES (
      v_activity.id,
      v_activity.organization_id,
      v_amount,
      COALESCE(v_activity.date, CURRENT_DATE),
      v_method,
      'final_payment',
      1,
      v_payment_notes,
      NULL,
      v_actor,
      'approved',
      now(),
      v_actor
    )
    RETURNING id INTO v_payment_id;
  END IF;

  -- QRIS income amount/net is recorded by apply_xendit_qris_settlement
  IF v_method = 'qris' THEN
    UPDATE public.sales_activities
    SET
      payment_method = v_method,
      total_paid_amount = v_amount,
      remaining_amount = 0,
      updated_at = now()
    WHERE id = v_activity.id;

    RETURN jsonb_build_object(
      'ok', true,
      'already_recorded', false,
      'payment_id', v_payment_id,
      'income_deferred', true,
      'status', 'completed'
    );
  END IF;

  SELECT
    it.id,
    it.amount,
    it.bank_account_id,
    it.deposit_confirmed_at,
    it.status
  INTO
    v_income_id,
    v_income_amount,
    v_income_bank,
    v_income_deposit_at,
    v_income_status
  FROM public.income_transactions it
  WHERE it.organization_id = v_activity.organization_id
    AND it.sales_activity_payment_id = v_payment_id
  LIMIT 1
  FOR UPDATE;

  IF v_income_id IS NOT NULL AND (
    NOT v_needs_bank
    OR v_income_deposit_at IS NOT NULL
  ) THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_recorded', true,
      'income_id', v_income_id,
      'payment_id', v_payment_id,
      'status', v_income_status
    );
  END IF;

  v_client_name := COALESCE(NULLIF(btrim(v_activity.client_name), ''), 'Walk-in');
  v_tx_date := COALESCE(v_activity.date, CURRENT_DATE);
  v_description := 'Store checkout - ' || v_client_name;
  IF v_ref IS NOT NULL THEN
    v_description := v_description || ' · ' || v_ref;
  END IF;

  IF v_income_id IS NULL THEN
    INSERT INTO public.income_transactions (
      organization_id,
      user_id,
      transaction_date,
      amount,
      customer_name,
      payment_method,
      description,
      bank_account_id,
      income_type_id,
      category_id,
      service_id,
      sub_service_id,
      sales_activity_payment_id,
      status,
      created_by
    )
    VALUES (
      v_activity.organization_id,
      v_actor,
      v_tx_date,
      v_amount,
      v_client_name,
      v_method,
      v_description,
      CASE WHEN v_needs_bank THEN v_bank_id ELSE NULL END,
      NULL,
      NULL,
      v_activity.service_id,
      v_activity.sub_service_id,
      v_payment_id,
      CASE WHEN v_needs_bank THEN 'pending' ELSE 'completed' END,
      v_actor
    )
    RETURNING id, amount, bank_account_id INTO v_income_id, v_income_amount, v_income_bank;
  END IF;

  IF v_needs_bank AND v_income_deposit_at IS NULL THEN
    UPDATE public.income_transactions
    SET
      bank_account_id = COALESCE(bank_account_id, v_bank_id),
      deposit_confirmed_at = now(),
      deposit_confirmed_by = v_actor,
      deposit_source = 'store_checkout',
      status = 'completed',
      updated_at = now()
    WHERE id = v_income_id;

    PERFORM public.credit_income_bank_deposit(
      v_income_id,
      COALESCE(v_income_bank, v_bank_id),
      v_activity.organization_id,
      COALESCE(v_income_amount, v_amount),
      v_actor,
      'Store checkout deposit'
    );
    v_credited := true;
  END IF;

  UPDATE public.sales_activities
  SET
    payment_method = v_method,
    total_paid_amount = v_amount,
    remaining_amount = 0,
    updated_at = now()
  WHERE id = v_activity.id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_recorded', false,
    'income_id', v_income_id,
    'payment_id', v_payment_id,
    'status', 'completed',
    'credited', v_credited
  );
END;
$$;


ALTER FUNCTION "public"."apply_store_checkout_income"("p_activity_id" "uuid", "p_payment_method" "text", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_template_followup_customer_reply"("p_lead_id" "uuid", "p_conv_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ticket_id text;
  v_now timestamptz := NOW();
BEGIN
  IF p_conv_id IS NULL AND p_lead_id IS NULL THEN
    RETURN;
  END IF;

  IF p_conv_id IS NOT NULL THEN
    SELECT ticket_id INTO v_ticket_id FROM public.whatsapp_conversations WHERE id = p_conv_id;

    UPDATE public.whatsapp_conversations
    SET
      template_followup_awaiting_reply = false,
      follow_up_cycle_reset_at = v_now,
      followup = 0,
      fu_priority = 'Set Status',
      updated_at = v_now
    WHERE id = p_conv_id
      AND template_followup_awaiting_reply = true;

    IF v_ticket_id IS NOT NULL AND trim(v_ticket_id) <> '' THEN
      UPDATE public.leads
      SET
        template_followup_awaiting_reply = false,
        follow_up_cycle_reset_at = v_now,
        followup = 0,
        fu_priority = 'Set Status',
        updated_at = v_now
      WHERE ticket_id = trim(v_ticket_id)
        AND template_followup_awaiting_reply = true;
    END IF;
  END IF;

  IF p_lead_id IS NOT NULL THEN
    UPDATE public.leads
    SET
      template_followup_awaiting_reply = false,
      follow_up_cycle_reset_at = v_now,
      followup = 0,
      fu_priority = 'Set Status',
      updated_at = v_now
    WHERE id = p_lead_id
      AND template_followup_awaiting_reply = true;
  END IF;
END;
$$;


ALTER FUNCTION "public"."apply_template_followup_customer_reply"("p_lead_id" "uuid", "p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_template_followup_sent"("p_lead_id" "uuid", "p_conv_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_reset_at timestamptz;
  v_template_cnt integer;
  v_ticket_id text;
BEGIN
  IF p_conv_id IS NULL AND p_lead_id IS NULL THEN
    RETURN;
  END IF;

  IF p_conv_id IS NOT NULL THEN
    SELECT follow_up_cycle_reset_at, ticket_id
    INTO v_reset_at, v_ticket_id
    FROM public.whatsapp_conversations
    WHERE id = p_conv_id;

    v_template_cnt := public.count_template_followups_since_reset(p_conv_id, p_lead_id, v_reset_at);

    UPDATE public.whatsapp_conversations
    SET
      template_followup_awaiting_reply = true,
      followup = v_template_cnt,
      updated_at = NOW()
    WHERE id = p_conv_id;

    IF v_ticket_id IS NOT NULL AND trim(v_ticket_id) <> '' THEN
      UPDATE public.leads l
      SET
        template_followup_awaiting_reply = true,
        followup = v_template_cnt,
        updated_at = NOW()
      WHERE l.ticket_id = trim(v_ticket_id);
    ELSIF p_lead_id IS NOT NULL THEN
      SELECT follow_up_cycle_reset_at INTO v_reset_at FROM public.leads WHERE id = p_lead_id;
      v_template_cnt := public.count_template_followups_since_reset(p_conv_id, p_lead_id, v_reset_at);
      UPDATE public.leads
      SET template_followup_awaiting_reply = true, followup = v_template_cnt, updated_at = NOW()
      WHERE id = p_lead_id;
    END IF;
  ELSIF p_lead_id IS NOT NULL THEN
    SELECT follow_up_cycle_reset_at INTO v_reset_at FROM public.leads WHERE id = p_lead_id;
    v_template_cnt := public.count_template_followups_since_reset(NULL, p_lead_id, v_reset_at);
    UPDATE public.leads
    SET template_followup_awaiting_reply = true, followup = v_template_cnt, updated_at = NOW()
    WHERE id = p_lead_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."apply_template_followup_sent"("p_lead_id" "uuid", "p_conv_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_xendit_gateway_withdrawal_settlement"("p_disbursement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_disb public.xendit_disbursements%ROWTYPE;
  v_withdrawal public.xendit_gateway_withdrawals%ROWTYPE;
  v_balance_before numeric;
  v_balance_after numeric;
  v_credit numeric;
  v_statement_line_id uuid;
  v_already_settled boolean := false;
BEGIN
  SELECT * INTO v_disb
  FROM public.xendit_disbursements
  WHERE id = p_disbursement_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'xendit_disbursement_not_found';
  END IF;

  IF v_disb.source_type <> 'gateway_withdrawal' THEN
    RAISE EXCEPTION 'not_gateway_withdrawal_disbursement';
  END IF;

  IF v_disb.status <> 'completed' THEN
    RAISE EXCEPTION 'disbursement_not_completed';
  END IF;

  SELECT * INTO v_withdrawal
  FROM public.xendit_gateway_withdrawals
  WHERE id = v_disb.source_id::uuid
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'xendit_gateway_withdrawal_not_found';
  END IF;

  v_credit := COALESCE(v_withdrawal.net_amount, v_withdrawal.amount);

  v_already_settled := (
    v_withdrawal.status = 'completed' AND v_withdrawal.settled_at IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.bank_account_balance_history h
    WHERE h.transaction_type = 'gateway_withdrawal'
      AND h.transaction_id = v_withdrawal.id
  );

  IF v_already_settled THEN
    UPDATE public.xendit_gateway_withdrawals
    SET
      status = 'completed',
      xendit_disbursement_id = COALESCE(xendit_disbursement_id, v_disb.id),
      settled_at = COALESCE(settled_at, now()),
      updated_at = now()
    WHERE id = v_withdrawal.id
      AND (status <> 'completed' OR settled_at IS NULL OR xendit_disbursement_id IS DISTINCT FROM v_disb.id);

    v_statement_line_id := public.upsert_bank_statement_from_gateway_withdrawal(v_withdrawal.id);
    RETURN jsonb_build_object(
      'ok', true,
      'already_settled', true,
      'withdrawal_id', v_withdrawal.id,
      'bank_account_id', v_withdrawal.bank_account_id,
      'amount', v_credit,
      'gross_amount', v_withdrawal.amount,
      'platform_fee_amount', v_withdrawal.platform_fee_amount,
      'bank_statement_line_id', v_statement_line_id
    );
  END IF;

  INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
  VALUES (v_withdrawal.bank_account_id, v_withdrawal.organization_id, 0)
  ON CONFLICT (bank_account_id) DO NOTHING;

  SELECT balance INTO v_balance_before
  FROM public.bank_account_balances
  WHERE bank_account_id = v_withdrawal.bank_account_id
  FOR UPDATE;

  v_balance_after := COALESCE(v_balance_before, 0) + v_credit;

  UPDATE public.bank_account_balances
  SET balance = v_balance_after, updated_at = now()
  WHERE bank_account_id = v_withdrawal.bank_account_id;

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    v_withdrawal.bank_account_id,
    v_withdrawal.organization_id,
    'gateway_withdrawal',
    v_withdrawal.id,
    v_credit,
    COALESCE(v_balance_before, 0),
    v_balance_after,
    'Xendit gateway withdrawal to payout bank',
    v_withdrawal.initiated_by
  );

  UPDATE public.xendit_gateway_withdrawals
  SET
    status = 'completed',
    xendit_disbursement_id = v_disb.id,
    settled_at = now(),
    updated_at = now()
  WHERE id = v_withdrawal.id;

  v_statement_line_id := public.upsert_bank_statement_from_gateway_withdrawal(v_withdrawal.id);

  RETURN jsonb_build_object(
    'ok', true,
    'withdrawal_id', v_withdrawal.id,
    'bank_account_id', v_withdrawal.bank_account_id,
    'amount', v_credit,
    'gross_amount', v_withdrawal.amount,
    'platform_fee_amount', v_withdrawal.platform_fee_amount,
    'balance_after', v_balance_after,
    'bank_statement_line_id', v_statement_line_id
  );
END;
$$;


ALTER FUNCTION "public"."apply_xendit_gateway_withdrawal_settlement"("p_disbursement_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_xendit_gateway_withdrawal_settlement"("p_disbursement_id" "uuid") IS 'Credits payout bank once per gateway withdrawal; idempotent via history row + settled_at.';



CREATE OR REPLACE FUNCTION "public"."apply_xendit_qris_settlement"("p_payment_request_id" "uuid", "p_xendit_payment_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_req public.xendit_payment_requests%ROWTYPE;
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_sap public.sales_activity_payments%ROWTYPE;
  v_sa public.sales_activities%ROWTYPE;
  v_bank_id uuid;
  v_income_id uuid;
  v_income public.income_transactions%ROWTYPE;
  v_finalize jsonb;
  v_gross numeric;
  v_platform_fee integer;
  v_net numeric;
  v_new_status text;
  v_fee_note text;
  v_payment_id uuid;
  v_activity_id uuid;
BEGIN
  SELECT * INTO v_req
  FROM public.xendit_payment_requests
  WHERE id = p_payment_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'xendit_payment_request_not_found';
  END IF;

  IF v_req.payment_type IS DISTINCT FROM 'qris' THEN
    RAISE EXCEPTION 'xendit_payment_request_not_qris';
  END IF;

  IF v_req.status = 'paid' AND v_req.sales_activity_id IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'already_paid', true, 'sales_activity_id', v_req.sales_activity_id);
  END IF;

  IF v_req.pos_pending_checkout_id IS NULL THEN
    RAISE EXCEPTION 'pos_pending_checkout_missing';
  END IF;

  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = v_req.pos_pending_checkout_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pos_pending_checkout_not_found';
  END IF;

  v_finalize := public.pos_finalize_qris_checkout(v_req.pos_pending_checkout_id, v_pending.created_by);
  v_activity_id := (v_finalize ->> 'sales_activity_id')::uuid;
  v_payment_id := (v_finalize ->> 'payment_id')::uuid;

  SELECT * INTO v_sap FROM public.sales_activity_payments WHERE id = v_payment_id FOR UPDATE;
  SELECT * INTO v_sa FROM public.sales_activities WHERE id = v_activity_id;

  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = v_req.organization_id
    AND ba.use_for_xendit_income = true
    AND ba.is_active = true
  ORDER BY ba.created_at ASC
  LIMIT 1;

  IF v_bank_id IS NULL THEN
    SELECT ba.id INTO v_bank_id
    FROM public.bank_accounts ba
    WHERE ba.organization_id = v_req.organization_id
      AND ba.is_active = true
    ORDER BY ba.created_at ASC
    LIMIT 1;
  END IF;

  v_gross := COALESCE(v_req.expected_amount, v_sa.total_amount, 0);
  v_platform_fee := GREATEST(COALESCE(v_req.platform_fee_amount, 0), 0);
  v_net := GREATEST(v_gross - v_platform_fee, 0);
  v_fee_note := CASE
    WHEN v_platform_fee > 0 THEN ' | Platform fee Rp ' || v_platform_fee::text
    ELSE ''
  END;

  UPDATE public.xendit_payment_requests
  SET
    status = 'paid',
    paid_at = now(),
    xendit_payment_id = COALESCE(p_xendit_payment_id, xendit_payment_id),
    sales_activity_id = v_activity_id,
    updated_at = now()
  WHERE id = v_req.id;

  UPDATE public.sales_activity_payments
  SET
    transfer_verification_status = 'approved',
    transfer_verified_at = now(),
    payment_method = 'qris',
    notes = COALESCE(notes, '') || CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE ' | ' END
      || 'Paid via QRIS' || v_fee_note
  WHERE id = v_payment_id;

  SELECT id INTO v_income_id
  FROM public.income_transactions
  WHERE organization_id = v_req.organization_id
    AND sales_activity_payment_id = v_payment_id
  LIMIT 1;

  IF v_income_id IS NULL THEN
    INSERT INTO public.income_transactions (
      organization_id, user_id, transaction_date, amount, customer_name, payment_method,
      description, bank_account_id, sales_activity_payment_id, status, created_by
    )
    VALUES (
      v_req.organization_id,
      v_sap.created_by,
      CURRENT_DATE,
      v_net,
      COALESCE(v_sa.client_name, 'Customer'),
      'qris',
      'POS QRIS payment' || v_fee_note,
      v_bank_id,
      v_payment_id,
      'pending',
      v_sap.created_by
    )
    RETURNING id INTO v_income_id;
  ELSE
    UPDATE public.income_transactions
    SET
      amount = v_net,
      bank_account_id = COALESCE(bank_account_id, v_bank_id),
      payment_method = 'qris',
      description = COALESCE(description, 'POS QRIS payment') || v_fee_note
    WHERE id = v_income_id;
  END IF;

  SELECT * INTO v_income FROM public.income_transactions WHERE id = v_income_id FOR UPDATE;

  IF v_income.deposit_confirmed_at IS NULL THEN
    v_new_status := public.income_status_after_deposit(
      v_income.income_type_id,
      v_income.category_id,
      COALESCE(v_income.bank_account_id, v_bank_id)
    );

    UPDATE public.income_transactions
    SET
      deposit_confirmed_at = now(),
      deposit_confirmed_by = v_sap.created_by,
      deposit_source = 'xendit_qris',
      status = v_new_status,
      bank_account_id = COALESCE(bank_account_id, v_bank_id),
      updated_at = now()
    WHERE id = v_income_id;

    PERFORM public.credit_income_bank_deposit(
      v_income_id,
      COALESCE(v_income.bank_account_id, v_bank_id),
      v_req.organization_id,
      v_net,
      v_sap.created_by,
      'POS QRIS settlement' || v_fee_note
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'sales_activity_id', v_activity_id,
    'payment_id', v_payment_id,
    'income_id', v_income_id,
    'gross_amount', v_gross,
    'platform_fee_amount', v_platform_fee,
    'net_amount', v_net
  );
END;
$$;


ALTER FUNCTION "public"."apply_xendit_qris_settlement"("p_payment_request_id" "uuid", "p_xendit_payment_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_xendit_va_settlement"("p_payment_request_id" "uuid", "p_xendit_payment_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_req public.xendit_payment_requests%ROWTYPE;
  v_sap public.sales_activity_payments%ROWTYPE;
  v_sa public.sales_activities%ROWTYPE;
  v_bank_id uuid;
  v_income_id uuid;
  v_income public.income_transactions%ROWTYPE;
  v_gross numeric;
  v_platform_fee integer;
  v_net numeric;
  v_new_status text;
  v_fee_note text;
BEGIN
  SELECT * INTO v_req FROM public.xendit_payment_requests WHERE id = p_payment_request_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'xendit_payment_request_not_found';
  END IF;
  IF v_req.status = 'paid' THEN
    RETURN jsonb_build_object('ok', true, 'already_paid', true);
  END IF;

  SELECT * INTO v_sap FROM public.sales_activity_payments WHERE id = v_req.sales_activity_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'sales_activity_payment_not_found';
  END IF;

  SELECT * INTO v_sa FROM public.sales_activities WHERE id = v_sap.sales_activity_id;

  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = v_req.organization_id
    AND ba.use_for_xendit_income = true
    AND ba.is_active = true
  ORDER BY ba.created_at ASC
  LIMIT 1;

  IF v_bank_id IS NULL THEN
    SELECT ba.id INTO v_bank_id
    FROM public.bank_accounts ba
    WHERE ba.organization_id = v_req.organization_id
      AND ba.is_active = true
    ORDER BY ba.created_at ASC
    LIMIT 1;
  END IF;

  v_gross := v_sap.payment_amount;
  v_platform_fee := GREATEST(COALESCE(v_req.platform_fee_amount, 0), 0);
  v_net := GREATEST(v_gross - v_platform_fee, 0);
  v_fee_note := CASE
    WHEN v_platform_fee > 0 THEN ' | Platform fee Rp ' || v_platform_fee::text
    ELSE ''
  END;

  UPDATE public.xendit_payment_requests
  SET
    status = 'paid',
    paid_at = now(),
    xendit_payment_id = COALESCE(p_xendit_payment_id, xendit_payment_id),
    updated_at = now()
  WHERE id = v_req.id;

  UPDATE public.sales_activity_payments
  SET
    transfer_verification_status = 'approved',
    transfer_verified_at = now(),
    payment_method = 'xendit_va',
    notes = COALESCE(notes, '') || CASE WHEN notes IS NULL OR notes = '' THEN '' ELSE ' | ' END
      || 'Paid via Xendit VA' || v_fee_note
  WHERE id = v_sap.id;

  SELECT id INTO v_income_id
  FROM public.income_transactions
  WHERE organization_id = v_req.organization_id
    AND sales_activity_payment_id = v_sap.id
  LIMIT 1;

  IF v_income_id IS NULL THEN
    INSERT INTO public.income_transactions (
      organization_id, user_id, transaction_date, amount, customer_name, payment_method,
      description, bank_account_id, sales_activity_payment_id, status, created_by
    )
    VALUES (
      v_req.organization_id,
      v_sap.created_by,
      CURRENT_DATE,
      v_net,
      COALESCE(v_sa.client_name, 'Customer'),
      'xendit_va',
      'Xendit VA - Piutang payment' || v_fee_note,
      v_bank_id,
      v_sap.id,
      'pending',
      v_sap.created_by
    )
    RETURNING id INTO v_income_id;
  ELSE
    UPDATE public.income_transactions
    SET
      amount = v_net,
      bank_account_id = COALESCE(bank_account_id, v_bank_id),
      payment_method = 'xendit_va',
      description = COALESCE(description, 'Xendit VA - Piutang payment') || v_fee_note
    WHERE id = v_income_id;
  END IF;

  SELECT * INTO v_income FROM public.income_transactions WHERE id = v_income_id FOR UPDATE;

  IF v_income.deposit_confirmed_at IS NULL THEN
    v_new_status := public.income_status_after_deposit(
      v_income.income_type_id,
      v_income.category_id,
      COALESCE(v_income.bank_account_id, v_bank_id)
    );

    UPDATE public.income_transactions
    SET
      deposit_confirmed_at = now(),
      deposit_confirmed_by = v_sap.created_by,
      deposit_source = 'xendit_va',
      status = v_new_status,
      bank_account_id = COALESCE(bank_account_id, v_bank_id),
      updated_at = now()
    WHERE id = v_income_id;

    PERFORM public.credit_income_bank_deposit(
      v_income_id,
      COALESCE(v_income.bank_account_id, v_bank_id),
      v_req.organization_id,
      v_net,
      v_sap.created_by,
      'Xendit VA settlement' || v_fee_note
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'income_id', v_income_id,
    'bank_account_id', v_bank_id,
    'gross_amount', v_gross,
    'platform_fee_amount', v_platform_fee,
    'net_amount', v_net
  );
END;
$$;


ALTER FUNCTION "public"."apply_xendit_va_settlement"("p_payment_request_id" "uuid", "p_xendit_payment_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.catalog_stock_transfers%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_transfer_forbidden';
  END IF;
  IF NOT public.user_has_inventory_feature_access(p_organization_id, 'transfer_approval') THEN
    RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
  END IF;

  SELECT * INTO v_transfer
  FROM public.catalog_stock_transfers
  WHERE id = p_transfer_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_transfer_not_found';
  END IF;
  IF v_transfer.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'catalog_transfer_invalid_status';
  END IF;

  UPDATE public.catalog_stock_transfers
  SET
    status = 'approved',
    approved_at = now(),
    approved_by = auth.uid(),
    updated_at = now()
  WHERE id = v_transfer.id;

  PERFORM public.catalog_transfer_insert_event(v_transfer.id, p_organization_id, 'approved', p_comment);

  RETURN to_jsonb((SELECT t FROM public.catalog_stock_transfers t WHERE t.id = v_transfer.id));
END;
$$;


ALTER FUNCTION "public"."approve_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_wa_resolve_submission_email"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead_id uuid;
  v_ticket text;
BEGIN
  IF TG_TABLE_NAME = 'leads' THEN
    IF NEW.status_id IS NOT DISTINCT FROM OLD.status_id THEN
      RETURN NEW;
    END IF;
    IF NOT public.is_resolved_lead_status_id(NEW.status_id) THEN
      RETURN NEW;
    END IF;
    v_ticket := COALESCE(NEW.ticket_id, '');
    IF upper(btrim(v_ticket)) NOT LIKE 'WA-%' THEN
      RETURN NEW;
    END IF;
    v_lead_id := NEW.id;
  ELSIF TG_TABLE_NAME = 'whatsapp_conversations' THEN
    IF NEW.lead_status_id IS NOT DISTINCT FROM OLD.lead_status_id THEN
      RETURN NEW;
    END IF;
    IF NOT public.is_resolved_lead_status_id(NEW.lead_status_id) THEN
      RETURN NEW;
    END IF;
    v_ticket := COALESCE(NEW.ticket_id, '');
    IF upper(btrim(v_ticket)) NOT LIKE 'WA-%' THEN
      RETURN NEW;
    END IF;
    SELECT l.id
    INTO v_lead_id
    FROM public.leads l
    WHERE l.organization_id = NEW.organization_id
      AND l.ticket_id ILIKE v_ticket
    ORDER BY l.updated_at DESC NULLS LAST
    LIMIT 1;
    IF v_lead_id IS NULL THEN
      RAISE EXCEPTION 'resolve_email_required' USING ERRCODE = 'P0001';
    END IF;
  ELSE
    RETURN NEW;
  END IF;

  IF NOT public.lead_submission_email_ok(v_lead_id) THEN
    RAISE EXCEPTION 'resolve_email_required' USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."assert_wa_resolve_submission_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_brief_voice_clip_shot_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.kind = 'vo' AND NEW.shot_id IS NULL THEN
    SELECT shot.id
      INTO NEW.shot_id
    FROM public.brief_storyboard_shots AS shot
    WHERE shot.social_media_plan_id = NEW.social_media_plan_id
      AND shot.row_index = NEW.row_index;
  END IF;
  RETURN NEW;
END;
$$;


