CREATE OR REPLACE FUNCTION "public"."audit_duplicate_payment_milestones"() RETURNS TABLE("payment_terms_id" "uuid", "milestone_order" integer, "duplicate_count" bigint, "organization_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pm.payment_terms_id,
    pm.milestone_order,
    COUNT(*) AS duplicate_count,
    kpt.organization_id
  FROM public.payment_milestones pm
  JOIN public.kol_payment_terms kpt ON kpt.id = pm.payment_terms_id
  GROUP BY pm.payment_terms_id, pm.milestone_order, kpt.organization_id
  HAVING COUNT(*) > 1
  ORDER BY duplicate_count DESC;
$$;


