CREATE OR REPLACE FUNCTION "public"."auto_create_budget_allocation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_base_amount numeric(15, 2) := 0;
  v_payment_model text := 'fixed';
  v_payment_terms_id uuid;
BEGIN
  IF NEW.campaign_id IS NULL OR NEW.kol_profile_id IS NULL OR NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT kpt.id, COALESCE(kpt.base_amount, 0), COALESCE(kpt.payment_model, 'fixed')
  INTO v_payment_terms_id, v_base_amount, v_payment_model
  FROM public.kol_payment_terms kpt
  WHERE kpt.kol_content_post_id = NEW.id
  LIMIT 1;

  IF v_base_amount <= 0 AND NEW.campaign_deliverable_id IS NOT NULL THEN
    SELECT COALESCE(kcd.total_price, kcd.price_per_deliverable, 0)
    INTO v_base_amount
    FROM public.kol_campaign_deliverables kcd
    WHERE kcd.id = NEW.campaign_deliverable_id;
  END IF;

  PERFORM public.upsert_kol_budget_allocation(
    NEW.campaign_id,
    NEW.kol_profile_id,
    NEW.organization_id,
    COALESCE(v_base_amount, 0),
    v_payment_model,
    v_payment_terms_id
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_create_budget_allocation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_resolve_conversations_after_24h"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  updated_email INTEGER := 0;
BEGIN
  WITH target AS (
    SELECT e.id, e.organization_id
    FROM public.email_conversations e
    LEFT JOIN public.lead_statuses ls ON ls.id = e.lead_status_id AND ls.organization_id = e.organization_id
    WHERE (COALESCE(e.last_inbound_at, e.created_at)) < (NOW() - INTERVAL '24 hours')
      AND (
        ls.name IN ('In Progress', 'Converted', 'Qualified')
        OR e.lead_status_id IS NULL
        OR ls.id IS NULL
      )
  ),
  closed AS (
    SELECT t.id, ls_closed.id AS closed_id
    FROM target t
    JOIN public.lead_statuses ls_closed ON ls_closed.organization_id = t.organization_id AND ls_closed.name = 'Closed'
  ),
  updated AS (
    UPDATE public.email_conversations e
    SET lead_status_id = c.closed_id, updated_at = NOW()
    FROM closed c
    WHERE e.id = c.id
    RETURNING e.id
  )
  SELECT COUNT(*)::INTEGER INTO updated_email FROM updated;

  RETURN updated_email;
END;
$$;


ALTER FUNCTION "public"."auto_resolve_conversations_after_24h"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_resolve_conversations_after_24h"() IS 'Email only: sets email_conversations to Closed after 24h inactivity. WA/IG use Meta meta_session_expires_at + apply_meta_session_expired_conversations() instead.';



CREATE OR REPLACE FUNCTION "public"."auto_resolve_email_conversations_after_24h"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  in_progress_id UUID;
  closed_id UUID;
  updated_count INTEGER := 0;
BEGIN
  SELECT id INTO in_progress_id FROM lead_statuses WHERE name = 'In Progress' LIMIT 1;
  SELECT id INTO closed_id FROM lead_statuses WHERE name = 'Closed' LIMIT 1;

  IF in_progress_id IS NULL OR closed_id IS NULL THEN
    RETURN 0;
  END IF;

  WITH updated AS (
    UPDATE email_conversations
    SET lead_status_id = closed_id, updated_at = NOW()
    WHERE lead_status_id = in_progress_id
      AND last_message_at IS NOT NULL
      AND last_message_at < (NOW() - INTERVAL '24 hours')
    RETURNING id
  )
  SELECT COUNT(*)::INTEGER INTO updated_count FROM updated;

  RETURN updated_count;
END;
$$;


ALTER FUNCTION "public"."auto_resolve_email_conversations_after_24h"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."auto_resolve_email_conversations_after_24h"() IS 'Sets email_conversations to Closed (Resolved) when status is In Progress and last_message_at is older than 24 hours. Schedule with pg_cron or call from a scheduled job.';



CREATE OR REPLACE FUNCTION "public"."build_daily_task_deeplink"("p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    CASE
      WHEN p_entity_type = 'task' THEN '/tools/daily-task?task_id=' || p_daily_task_id::text
      WHEN p_entity_type = 'step' THEN '/tools/daily-task?task_step_id=' || p_task_step_id::text
      ELSE '/tools/daily-task?task_steps_to_steps_id=' || p_task_steps_to_steps_id::text
    END
$$;


