CREATE OR REPLACE FUNCTION "public"."bump_whatsapp_campaign_read_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.wa_delivery_status IS NOT NULL
       AND lower(trim(NEW.wa_delivery_status)) = 'read'
       AND (
         OLD.wa_delivery_status IS NULL
         OR lower(trim(OLD.wa_delivery_status)) IS DISTINCT FROM 'read'
       )
    THEN
      UPDATE public.whatsapp_campaigns
      SET read_count = read_count + 1,
          updated_at = now()
      WHERE id = NEW.campaign_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."bump_whatsapp_campaign_read_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_employee_leave_balance"("employee_id_param" "uuid", "as_of_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_allocated numeric;
  v_used numeric;
  v_effective_date date;
BEGIN
  v_effective_date := COALESCE(as_of_date, (timezone('utc', now()))::date);

  SELECT e.organization_id, COALESCE(e.leave_balance::numeric, 12)
  INTO v_org, v_allocated
  FROM public.employees e
  WHERE e.id = employee_id_param;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Employee not found'
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT (v_org IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(COALESCE(lr.total_days, 0)), 0)
  INTO v_used
  FROM public.leave_requests lr
  WHERE lr.employee_id = employee_id_param
    AND lr.organization_id = v_org
    AND lr.status = 'approved'
    AND lr.start_date IS NOT NULL
    AND EXTRACT(YEAR FROM lr.start_date) = EXTRACT(YEAR FROM v_effective_date);

  SELECT COALESCE(e.leave_balance::numeric, 12)
  INTO v_allocated
  FROM public.employees e
  WHERE e.id = employee_id_param;

  RETURN jsonb_build_object(
    'total_allocated', v_allocated,
    'total_used', v_used,
    'remaining_balance', GREATEST(0, v_allocated - v_used),
    'expired_days', 0,
    'calculation_date', to_char(v_effective_date, 'YYYY-MM-DD')
  );
END;
$$;


ALTER FUNCTION "public"."calculate_employee_leave_balance"("employee_id_param" "uuid", "as_of_date" "date") OWNER TO "postgres";


