CREATE OR REPLACE FUNCTION "public"."calculate_payroll_run_totals"("p_run_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org FROM public.payroll_runs WHERE id = p_run_id;
  IF v_org IS NULL THEN
    RAISE EXCEPTION 'Payroll run not found' USING ERRCODE = 'P0001';
  END IF;

  IF NOT (v_org IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  UPDATE public.payroll_runs pr
  SET
    total_employees = sub.cnt,
    total_gross_pay = sub.gross,
    total_net_pay = sub.net,
    total_deductions = sub.deductions,
    total_penalties = sub.penalties,
    total_taxes = sub.taxes,
    updated_at = now()
  FROM (
    SELECT
      COUNT(*)::integer AS cnt,
      COALESCE(SUM(gross_pay), 0) AS gross,
      COALESCE(SUM(take_home_pay), 0) AS net,
      COALESCE(SUM(total_deductions), 0) AS deductions,
      COALESCE(SUM(total_penalties), 0) AS penalties,
      COALESCE(SUM(total_tax_deductions), 0) AS taxes
    FROM public.employee_payroll_calculations
    WHERE payroll_run_id = p_run_id
  ) sub
  WHERE pr.id = p_run_id;
END;
$$;


ALTER FUNCTION "public"."calculate_payroll_run_totals"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_prorate_upgrade"("org_id" "uuid", "new_member_count" integer, "target_plan_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_sub           record;
  v_payment       record;
  v_current_plan  jsonb;
  v_target_plan   jsonb;
  v_end_ts        timestamptz;
  v_start_ts      timestamptz;
  v_now           timestamptz := now();
  v_total_days    integer;
  v_remaining_days integer;
  v_prorate_pct   numeric;
  v_member_diff   integer;
  v_is_plan_change boolean;
  v_is_upgrade    boolean;
  v_plan_change_charge numeric := 0;
  v_member_change_charge numeric := 0;
  v_prorate_amount numeric := 0;
  v_charge_now    boolean;
  v_change_type   text;
  v_scheduled_date timestamptz;
  v_current_daily_rate numeric;
  v_target_daily_rate numeric;
  v_result        jsonb;
  v_os_end        timestamptz;
  v_payment_period_end timestamptz;
  v_last_paid_amount numeric;
  v_last_paid_member_count integer;
  v_skip_prorate_startup_to_scale boolean := false;
  v_curr_nm       text;
  v_tgt_nm        text;
  v_tgt_list_price numeric;
  v_tgt_annual    numeric;
BEGIN
  SELECT os.id, os.subscription_plan_id, os.member_count, os.billing_cycle,
         os.subscription_start_date, os.subscription_end_date, os.trial_end_date, os.created_at,
         sp.id AS plan_id, sp.name AS plan_name, sp.base_price_per_member
  INTO v_sub
  FROM organization_subscriptions os
  LEFT JOIN subscription_plans sp ON sp.id = os.subscription_plan_id
  WHERE os.organization_id = org_id
  ORDER BY os.updated_at DESC
  LIMIT 1;

  IF v_sub.id IS NULL THEN
    RETURN jsonb_build_object('error', 'No active subscription found for organization');
  END IF;

  SELECT p.subscription_end_date, p.subscription_start_date, p.created_at, p.billing_cycle,
         p.amount, p.member_count
  INTO v_payment
  FROM payments p
  WHERE p.organization_id = org_id
    AND p.status IN ('success', 'settlement', 'paid')
    AND p.created_at IS NOT NULL
    AND p.created_at <= v_now
  ORDER BY p.created_at DESC
  LIMIT 1;

  IF FOUND AND v_payment.amount IS NOT NULL THEN
    v_last_paid_amount := (v_payment.amount)::numeric;
    v_last_paid_member_count := COALESCE((v_payment.member_count)::integer, v_sub.member_count);
  ELSE
    v_last_paid_amount := NULL;
    v_last_paid_member_count := NULL;
  END IF;

  IF FOUND AND v_payment.subscription_end_date IS NOT NULL THEN
    v_end_ts := (v_payment.subscription_end_date)::timestamptz;
    IF v_payment.created_at IS NOT NULL THEN
      IF (COALESCE(v_payment.billing_cycle, v_sub.billing_cycle) = 'yearly' AND v_end_ts > (v_payment.created_at)::timestamptz + interval '1 year' + interval '1 day')
         OR (COALESCE(v_payment.billing_cycle, v_sub.billing_cycle) != 'yearly' AND v_end_ts > (v_payment.created_at)::timestamptz + interval '1 month' + interval '1 day') THEN
        v_end_ts := (v_payment.created_at)::timestamptz + CASE WHEN COALESCE(v_payment.billing_cycle, v_sub.billing_cycle) = 'yearly' THEN interval '1 year' ELSE interval '1 month' END;
      END IF;
    END IF;
    IF v_payment.subscription_start_date IS NOT NULL THEN
      v_start_ts := (v_payment.subscription_start_date)::timestamptz;
    ELSE
      v_start_ts := (COALESCE(v_sub.subscription_start_date::timestamptz, v_sub.created_at::timestamptz));
    END IF;
  ELSIF FOUND AND v_payment.created_at IS NOT NULL THEN
    v_end_ts := (v_payment.created_at)::timestamptz + CASE
      WHEN COALESCE(v_payment.billing_cycle, v_sub.billing_cycle) = 'yearly' THEN interval '1 year'
      ELSE interval '1 month'
    END;
    v_start_ts := (v_payment.created_at)::timestamptz;
  ELSE
    v_end_ts := (v_sub.subscription_end_date)::timestamptz;
    v_start_ts := (COALESCE(v_sub.subscription_start_date::timestamptz, v_sub.created_at::timestamptz));
  END IF;

  IF v_sub.subscription_end_date IS NOT NULL THEN
    v_os_end := (v_sub.subscription_end_date)::timestamptz;
    IF v_os_end > v_now THEN
      IF FOUND AND v_payment.created_at IS NOT NULL THEN
        v_payment_period_end := (v_payment.created_at)::timestamptz + CASE
          WHEN COALESCE(v_payment.billing_cycle, v_sub.billing_cycle) = 'yearly' THEN interval '1 year' + interval '31 days'
          ELSE interval '1 month' + interval '5 days'
        END;
        IF v_os_end <= v_payment_period_end THEN
          v_end_ts := v_os_end;
        END IF;
      ELSIF v_os_end <= v_now + interval '2 years' THEN
        v_end_ts := v_os_end;
      END IF;
    END IF;
  END IF;

  IF v_end_ts IS NULL THEN
    v_end_ts := COALESCE(
      v_sub.trial_end_date::timestamptz,
      v_sub.subscription_end_date::timestamptz,
      v_now + CASE WHEN COALESCE(v_sub.billing_cycle, 'monthly') = 'yearly' THEN interval '1 year' ELSE interval '1 month' END
    );
  END IF;

  v_remaining_days := COALESCE(
    CASE
      WHEN v_end_ts IS NULL THEN 0
      ELSE GREATEST(0, FLOOR(EXTRACT(epoch FROM (v_end_ts - v_now)) / 86400.0)::integer)
    END,
    0
  );
  v_member_diff := new_member_count - v_sub.member_count;

  IF v_sub.billing_cycle = 'yearly' THEN
    v_total_days := 365;
  ELSE
    v_total_days := 30;
  END IF;

  v_prorate_pct := CASE WHEN v_total_days > 0 THEN (v_remaining_days::numeric / v_total_days) * 100 ELSE 0 END;

  v_current_plan := jsonb_build_object(
    'id', v_sub.plan_id,
    'name', COALESCE(v_sub.plan_name, 'Unknown'),
    'member_count', v_sub.member_count,
    'base_price_per_member', COALESCE(v_sub.base_price_per_member, 0),
    'billing_cycle', COALESCE(v_sub.billing_cycle, 'monthly'),
    'end_date', v_end_ts
  );

  IF target_plan_id IS NOT NULL AND target_plan_id IS DISTINCT FROM v_sub.subscription_plan_id THEN
    SELECT jsonb_build_object(
      'id', id::text,
      'name', name,
      'base_price_per_member', base_price_per_member,
      'annual_discount_percentage', COALESCE(annual_discount_percentage, 0)
    )
    INTO v_target_plan
    FROM subscription_plans
    WHERE id = target_plan_id AND is_active = true
    LIMIT 1;
    IF NOT FOUND OR v_target_plan IS NULL THEN
      RETURN jsonb_build_object('error', 'Target plan not found or inactive');
    END IF;
    v_is_plan_change := true;
  ELSE
    v_target_plan := jsonb_build_object(
      'id', v_sub.plan_id::text,
      'name', COALESCE(v_sub.plan_name, 'Unknown'),
      'base_price_per_member', COALESCE(v_sub.base_price_per_member, 0),
      'annual_discount_percentage', 0
    );
    v_is_plan_change := false;
  END IF;

  v_curr_nm := lower(trim(COALESCE(v_sub.plan_name, '')));
  v_tgt_nm := lower(trim(COALESCE(v_target_plan->>'name', '')));
  v_skip_prorate_startup_to_scale := COALESCE(v_is_plan_change, false)
    AND v_curr_nm ~* '(^|[[:space:]])(starter|start[[:space:]]*up|startup)([[:space:]]|$)'
    AND v_tgt_nm ~* 'scale[[:space:]]*up';

  IF v_skip_prorate_startup_to_scale THEN
    v_tgt_annual := COALESCE(NULLIF((v_target_plan->>'annual_discount_percentage'), '')::numeric, 0);
    IF v_sub.billing_cycle = 'yearly' THEN
      v_tgt_list_price := (v_target_plan->>'base_price_per_member')::numeric * new_member_count * 12.0 * (1 - v_tgt_annual / 100.0);
      v_current_daily_rate := (COALESCE(v_sub.base_price_per_member, 0) * v_sub.member_count * 12.0 / 365.0);
      v_target_daily_rate := ((v_target_plan->>'base_price_per_member')::numeric * new_member_count * 12.0 / 365.0);
    ELSE
      v_tgt_list_price := (v_target_plan->>'base_price_per_member')::numeric * new_member_count;
      v_current_daily_rate := (COALESCE(v_sub.base_price_per_member, 0) * v_sub.member_count / 30.0);
      v_target_daily_rate := ((v_target_plan->>'base_price_per_member')::numeric * new_member_count / 30.0);
    END IF;
    v_plan_change_charge := 0;
    v_member_change_charge := 0;
    v_prorate_amount := ROUND(v_tgt_list_price, 0);
    v_prorate_pct := 100;
  ELSE
    IF v_sub.billing_cycle = 'yearly' THEN
      v_current_daily_rate := (COALESCE(v_sub.base_price_per_member, 0) * v_sub.member_count * 12.0 / 365.0);
    ELSE
      v_current_daily_rate := (COALESCE(v_sub.base_price_per_member, 0) * v_sub.member_count / 30.0);
    END IF;

    IF v_is_plan_change THEN
      v_target_daily_rate := (v_target_plan->>'base_price_per_member')::numeric * new_member_count;
      IF v_sub.billing_cycle = 'yearly' THEN
        v_target_daily_rate := v_target_daily_rate * 12.0 / 365.0;
      ELSE
        v_target_daily_rate := v_target_daily_rate / 30.0;
      END IF;
      v_plan_change_charge := GREATEST(0, (v_target_daily_rate - v_current_daily_rate) * v_remaining_days);
    ELSE
      v_target_daily_rate := v_current_daily_rate;
    END IF;

    IF v_member_diff > 0 THEN
      IF v_sub.billing_cycle = 'yearly' THEN
        v_member_change_charge := (COALESCE(v_sub.base_price_per_member, 0) * 12.0) * v_member_diff * (v_remaining_days::numeric / 365.0);
      ELSE
        v_member_change_charge := (COALESCE(v_sub.base_price_per_member, 0) * v_member_diff * v_remaining_days::numeric / 30.0);
      END IF;
    END IF;

    v_prorate_amount := ROUND((COALESCE(v_plan_change_charge, 0) + COALESCE(v_member_change_charge, 0))::numeric, 0);
  END IF;

  v_is_upgrade := (v_member_diff > 0 OR v_is_plan_change);
  v_charge_now := (COALESCE(v_prorate_amount, 0) > 0 AND v_remaining_days >= 0);
  v_scheduled_date := COALESCE(
    CASE WHEN v_charge_now THEN v_now ELSE v_end_ts END,
    v_now
  );
  v_change_type := CASE
    WHEN v_member_diff > 0 AND NOT v_is_plan_change THEN 'member_increase'
    WHEN v_is_plan_change AND v_member_diff >= 0 THEN 'upgrade'
    WHEN v_is_plan_change AND v_member_diff < 0 THEN 'downgrade'
    ELSE 'downgrade'
  END;

  v_result := jsonb_build_object(
    'success', true,
    'current_plan', v_current_plan,
    'target_plan', jsonb_build_object(
      'id', v_target_plan->>'id',
      'name', v_target_plan->>'name',
      'base_price_per_member', (v_target_plan->>'base_price_per_member')::numeric
    ),
    'last_paid_amount', v_last_paid_amount,
    'last_paid_member_count', v_last_paid_member_count,
    'calculation', jsonb_build_object(
      'new_member_count', new_member_count,
      'member_difference', v_member_diff,
      'remaining_days', v_remaining_days,
      'total_days', v_total_days,
      'prorate_percentage', ROUND(v_prorate_pct, 2),
      'prorate_amount', v_prorate_amount,
      'plan_change_charge', ROUND(v_plan_change_charge, 0),
      'member_change_charge', ROUND(v_member_change_charge, 0),
      'is_upgrade', v_is_upgrade,
      'is_plan_change', v_is_plan_change,
      'charge_now', v_charge_now,
      'change_type', v_change_type,
      'scheduled_date', to_char(v_scheduled_date AT TIME ZONE 'UTC', 'YYYY-MM-DD''T''HH24:MI:SS.MS''Z'''),
      'current_daily_rate', ROUND(v_current_daily_rate, 2),
      'target_daily_rate', ROUND(COALESCE(v_target_daily_rate, v_current_daily_rate), 2),
      'current_plan_credit', 0,
      'skip_prorate', v_skip_prorate_startup_to_scale
    )
  );

  RETURN v_result;
END;
$_$;


ALTER FUNCTION "public"."calculate_prorate_upgrade"("org_id" "uuid", "new_member_count" integer, "target_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."calculate_prorate_upgrade"("org_id" "uuid", "new_member_count" integer, "target_plan_id" "uuid") IS 'Prorate upgrade; skip time-prorate for Start Up → Scale Up (full list price for target plan × members).';



CREATE OR REPLACE FUNCTION "public"."can_access_web_id"("p_web_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.analytics_web_access a
    JOIN public.profiles p
      ON p.active_organization_id = a.organization_id
     AND p.user_id = (SELECT auth.uid())
    WHERE a.web_id = p_web_id
      AND a.is_approved = true
  );
$$;


ALTER FUNCTION "public"."can_access_web_id"("p_web_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_add_employee"("p_org_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer;
  v_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = auth.uid() AND uo.organization_id = p_org_id
  ) THEN
    RETURN false;
  END IF;

  SELECT os.member_count INTO v_limit
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_org_id
  LIMIT 1;

  IF v_limit IS NULL THEN
    RETURN false;
  END IF;

  v_count := public.count_active_employees_for_org(p_org_id);
  RETURN v_count < v_limit;
END;
$$;


ALTER FUNCTION "public"."can_add_employee"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_approve_content_production"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_employee uuid;
  v_config public.approval_access_configurations%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RETURN false;
  END IF;
  SELECT ur.role INTO v_role
  FROM public.user_roles ur
  WHERE ur.user_id = p_user_id AND ur.organization_id = p_organization_id
  LIMIT 1;
  IF v_role IS NULL THEN
    RETURN false;
  END IF;
  SELECT e.id INTO v_employee
  FROM public.employees e
  WHERE e.user_id = p_user_id AND e.organization_id = p_organization_id
  ORDER BY e.id
  LIMIT 1;
  SELECT c.* INTO v_config
  FROM public.approval_access_configurations c
  WHERE c.organization_id = p_organization_id
    AND c.column_type = 'prod_approved'
    AND c.is_active = true
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN v_role IN ('owner', 'admin');
  END IF;
  RETURN (v_role = ANY (COALESCE(v_config.allowed_roles, ARRAY[]::text[])))
    OR (v_employee IS NOT NULL AND v_employee::text = ANY (COALESCE(v_config.exceptions, ARRAY[]::text[])));
END;
$$;


ALTER FUNCTION "public"."can_approve_content_production"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_edit_content_brief_field"("p_plan_id" "uuid", "p_field" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_org uuid;
  v_pic uuid;
  v_role text;
  v_roles text[];
  v_exceptions text[];
  v_is_pic boolean;
BEGIN
  IF p_plan_id IS NULL
     OR p_field NOT IN ('brief_storyboard', 'brief_concept', 'brief_caption', 'brief_link') THEN
    RETURN false;
  END IF;

  v_actor := COALESCE(p_user_id, auth.uid());
  IF auth.uid() IS NOT NULL AND v_actor IS DISTINCT FROM auth.uid() THEN
    RETURN false;
  END IF;
  IF auth.uid() IS NULL THEN
    IF NOT public.is_service_session() OR v_actor IS NULL THEN
      RETURN false;
    END IF;
  END IF;
  IF v_actor IS NULL THEN
    RETURN false;
  END IF;

  SELECT plan.organization_id, plan.pic_id
    INTO v_org, v_pic
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations AS member
    WHERE member.user_id = v_actor
      AND member.organization_id = v_org
      AND COALESCE(member.is_active, true) = true
  ) THEN
    RETURN false;
  END IF;

  SELECT lower(btrim(role.role))
    INTO v_role
  FROM public.user_roles AS role
  WHERE role.user_id = v_actor
    AND role.organization_id = v_org
  ORDER BY CASE lower(btrim(role.role))
    WHEN 'owner' THEN 0
    WHEN 'admin' THEN 1
    ELSE 2
  END
  LIMIT 1;

  v_is_pic := EXISTS (
    SELECT 1
    FROM public.employees AS employee
    WHERE employee.organization_id = v_org
      AND employee.user_id = v_actor
      AND employee.id = v_pic
  );

  SELECT config.allowed_roles, config.exceptions
    INTO v_roles, v_exceptions
  FROM public.approval_access_configurations AS config
  WHERE config.organization_id = v_org
    AND config.column_type = p_field
    AND config.is_active IS TRUE
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN v_is_pic OR v_role IN ('owner', 'admin');
  END IF;

  RETURN v_role = 'owner'
    OR v_role = ANY (
      SELECT lower(btrim(allowed))
      FROM unnest(COALESCE(v_roles, ARRAY[]::text[])) AS allowed
    )
    OR EXISTS (
      SELECT 1
      FROM public.employees AS employee
      WHERE employee.organization_id = v_org
        AND employee.user_id = v_actor
        AND employee.id::text = ANY (COALESCE(v_exceptions, ARRAY[]::text[]))
    );
END;
$$;


ALTER FUNCTION "public"."can_edit_content_brief_field"("p_plan_id" "uuid", "p_field" "text", "p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_edit_content_brief_field"("p_plan_id" "uuid", "p_field" "text", "p_user_id" "uuid") IS 'True when the account may edit one brief field. An active Approval Access row wins. Otherwise the PIC, an owner, or an admin may edit.';



CREATE OR REPLACE FUNCTION "public"."cancel_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_actor text;
  v_pr public.purchase_requests%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;

  SELECT * INTO v_po
  FROM public.catalog_purchase_orders
  WHERE id = p_purchase_order_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found';
  END IF;
  IF v_po.status <> 'waiting' THEN
    RAISE EXCEPTION 'catalog_po_not_waiting';
  END IF;

  SELECT * INTO v_pr
  FROM public.purchase_requests
  WHERE catalog_purchase_order_id = v_po.id
  FOR UPDATE;

  IF FOUND AND public.catalog_po_is_paid(v_pr.status, v_pr.payment_status, v_pr.paid_at) THEN
    RAISE EXCEPTION 'catalog_po_already_paid';
  END IF;

  v_actor := public.catalog_po_actor_name(p_organization_id);

  UPDATE public.catalog_purchase_orders
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = auth.uid(),
    updated_at = now()
  WHERE id = v_po.id;

  IF v_pr.id IS NOT NULL AND v_pr.status <> 'cancelled' THEN
    UPDATE public.purchase_requests
    SET
      status = 'cancelled',
      updated_at = now()
    WHERE id = v_pr.id;
  END IF;

  INSERT INTO public.catalog_purchase_order_events (
    purchase_order_id,
    organization_id,
    event_type,
    actor_user_id,
    actor_name_snapshot,
    comment
  ) VALUES (
    v_po.id,
    p_organization_id,
    'cancelled',
    auth.uid(),
    v_actor,
    NULLIF(btrim(p_comment), '')
  );

  RETURN to_jsonb((SELECT po FROM public.catalog_purchase_orders po WHERE po.id = v_po.id));
END;
$$;


ALTER FUNCTION "public"."cancel_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.catalog_stock_transfers%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_transfer_forbidden';
  END IF;
  IF public.catalog_inventory_transfer_mode(p_organization_id) = 'advanced'
    AND NOT (
      public.user_has_inventory_feature_access(p_organization_id, 'transfer_request')
      OR public.user_has_inventory_feature_access(p_organization_id, 'transfer_approval')
    )
  THEN
    RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
  END IF;
  SELECT * INTO v_transfer FROM public.catalog_stock_transfers
  WHERE id = p_transfer_id AND organization_id = p_organization_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'catalog_transfer_not_found'; END IF;
  IF v_transfer.status NOT IN ('pending_approval', 'approved') THEN RAISE EXCEPTION 'catalog_transfer_invalid_status'; END IF;
  UPDATE public.catalog_stock_transfers SET status = 'cancelled', cancelled_at = now(), cancelled_by = auth.uid(), updated_at = now() WHERE id = v_transfer.id;
  PERFORM public.catalog_transfer_insert_event(v_transfer.id, p_organization_id, 'cancelled', p_comment);
  RETURN to_jsonb((SELECT t FROM public.catalog_stock_transfers t WHERE t.id = v_transfer.id));
END;
$$;


ALTER FUNCTION "public"."cancel_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_income_for_payment_rejection"("p_sales_activity_payment_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF p_sales_activity_payment_id IS NULL THEN
    RETURN;
  END IF;

  SELECT it.organization_id
  INTO v_org
  FROM public.income_transactions it
  WHERE it.sales_activity_payment_id = p_sales_activity_payment_id
  LIMIT 1;

  IF v_org IS NOT NULL AND NOT public.user_is_org_owner_or_admin(v_org) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.income_transactions
  SET status = 'cancelled', updated_at = now()
  WHERE sales_activity_payment_id = p_sales_activity_payment_id
    AND deposit_confirmed_at IS NULL
    AND status IN ('pending', 'deposited');
END;
$$;


ALTER FUNCTION "public"."cancel_income_for_payment_rejection"("p_sales_activity_payment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_social_media_scheduled_posts_for_plan"("p_plan_id" "uuid", "p_reason" "text" DEFAULT 'plan_gate_failed'::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE public.social_media_scheduled_posts
  SET
    status = 'cancelled',
    error_message = COALESCE(p_reason, 'cancelled'),
    updated_at = now()
  WHERE social_media_plan_id = p_plan_id
    AND status IN ('pending', 'publishing');

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


