CREATE OR REPLACE FUNCTION "public"."candidate_request_token"() RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v text;
BEGIN
  BEGIN
    v := nullif(current_setting('request.headers', true), '')::json ->> 'x-candidate-token';
  EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
  END;
  IF v IS NULL OR v !~ '^cand_[0-9a-f]{48}$' THEN
    RETURN NULL;
  END IF;
  RETURN v;
END;
$_$;


ALTER FUNCTION "public"."candidate_request_token"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."candidate_submit_profile"("p_token" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  n int;
BEGIN
  IF p_token IS NULL OR p_token !~ '^cand_[0-9a-f]{48}$' THEN
    RAISE EXCEPTION 'invalid_token' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.candidate_profiles
     SET profile_completed = true, submitted_at = now()
   WHERE recruitment_token = p_token;
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 0 THEN
    RAISE EXCEPTION 'invalid_token' USING ERRCODE = 'P0001';
  END IF;
  UPDATE public.job_applications SET status = 'confirmed'
   WHERE recruitment_token = p_token
     AND coalesce(status, 'pending') NOT IN ('confirmed', 'accepted', 'rejected');
  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."candidate_submit_profile"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_enqueue"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NEW.approved IS NOT TRUE OR OLD.approved IS TRUE THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = NEW.pic_id
      AND e.organization_id = NEW.organization_id
      AND e.is_ai IS TRUE
  ) THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.content_types ct
    WHERE ct.id = NEW.content_type_id
      AND lower(btrim(ct.name)) = 'carousel'
  ) THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_canva_connections c
    INNER JOIN public.organization_canva_connection_tokens t
      ON t.organization_id = c.organization_id
    WHERE c.organization_id = NEW.organization_id
      AND c.is_active
      AND c.oauth_connected_at IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.canva_carousel_runs (
    social_media_plan_id, organization_id, status, attempts, updated_at
  )
  VALUES (NEW.id, NEW.organization_id, 'queued', 0, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET status = 'queued',
      error = NULL,
      canva_job_id = NULL,
      continuation_token = NULL,
      finished_at = NULL,
      attempts = CASE WHEN public.canva_carousel_runs.status = 'failed' THEN 0 ELSE public.canva_carousel_runs.attempts END,
      logo_placed = false,
      updated_at = now()
  WHERE public.canva_carousel_runs.status IS DISTINCT FROM 'succeeded'
    AND NOT (
      public.canva_carousel_runs.status = 'running'
      AND public.canva_carousel_runs.updated_at > now() - interval '3 minutes'
    )
  RETURNING social_media_plan_id INTO v_id;

  IF v_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM public.canva_carousel_post(NEW.id, 'start');
  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."canva_carousel_enqueue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_post"("p_plan_id" "uuid", "p_mode" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url text;
  v_secret text;
BEGIN
  SELECT ds.decrypted_secret INTO v_url
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'ai_employee_project_url'
  LIMIT 1;
  SELECT ds.decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'ai_employee_internal_secret'
  LIMIT 1;

  IF v_url IS NULL OR btrim(v_url) = '' OR v_secret IS NULL OR btrim(v_secret) = '' THEN
    UPDATE public.canva_carousel_runs
    SET status = 'failed',
        error = 'canva_dispatch_missing',
        finished_at = now(),
        updated_at = now()
    WHERE social_media_plan_id = p_plan_id
      AND status IS DISTINCT FROM 'succeeded';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/canva-carousel-run',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-synckerja-internal-secret', v_secret
    ),
    body := jsonb_build_object('plan_id', p_plan_id, 'mode', CASE WHEN p_mode = 'resume' THEN 'resume' ELSE 'start' END),
    timeout_milliseconds := 150000
  );
END;
$$;


ALTER FUNCTION "public"."canva_carousel_post"("p_plan_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_refresh"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_plan_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.social_media_plans p
    WHERE p.id = p_plan_id
      AND p.organization_id IN (SELECT public.user_organization_ids())
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.canva_carousel_runs
  SET refresh_requested = true,
      images_ready = false,
      export_attempts = 0,
      error = NULL,
      updated_at = now()
  WHERE social_media_plan_id = p_plan_id
    AND status = 'succeeded'
    AND design_id IS NOT NULL
    AND btrim(design_id) <> '';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'canva_design_missing' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.canva_carousel_post(p_plan_id, 'refresh');
END;
$$;


ALTER FUNCTION "public"."canva_carousel_refresh"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_replace_images"("p_plan_id" "uuid", "p_paths" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  old_paths text[];
BEGIN
  IF coalesce(auth.role(), '') IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF p_plan_id IS NULL
    OR p_paths IS NULL
    OR cardinality(p_paths) < 1
    OR cardinality(p_paths) > 10
    OR EXISTS (
      SELECT 1
      FROM unnest(p_paths) AS path
      WHERE path IS NULL
        OR btrim(path) = ''
        OR path LIKE '%..%'
        OR split_part(path, '/', 2) IS DISTINCT FROM p_plan_id::text
    )
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(array_agg(storage_path), ARRAY[]::text[])
  INTO old_paths
  FROM public.social_media_plan_carousel_images
  WHERE social_media_plan_id = p_plan_id;

  DELETE FROM public.social_media_plan_carousel_images
  WHERE social_media_plan_id = p_plan_id;

  INSERT INTO public.social_media_plan_carousel_images (
    social_media_plan_id,
    sort_order,
    storage_path
  )
  SELECT p_plan_id, (ordinality - 1)::integer, path
  FROM unnest(p_paths) WITH ORDINALITY AS slide(path, ordinality);

  RETURN old_paths;
END;
$$;


ALTER FUNCTION "public"."canva_carousel_replace_images"("p_plan_id" "uuid", "p_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_resume"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan uuid;
  v_count integer := 0;
BEGIN
  FOR v_plan IN
    SELECT r.social_media_plan_id
    FROM public.canva_carousel_runs r
    INNER JOIN public.social_media_plans p ON p.id = r.social_media_plan_id
    WHERE p.approved IS TRUE
      AND (
        (
          r.status IN ('queued', 'running')
          AND r.updated_at < now() - interval '40 seconds'
        ) OR (
          r.status = 'succeeded'
          AND r.revision_requested = true
          AND r.design_id IS NOT NULL
          AND r.revision_attempts < 3
          AND r.updated_at < now() - interval '50 seconds'
        ) OR (
          r.status = 'succeeded'
          AND r.revision_requested = false
          AND r.images_ready = false
          AND r.design_id IS NOT NULL
          AND r.export_attempts < 3
          AND r.updated_at < now() - interval '50 seconds'
        ) OR (
          r.status = 'succeeded'
          AND r.logo_placed IS FALSE
          AND r.design_id IS NOT NULL
          AND r.error IS NULL
          AND r.updated_at < now() - interval '40 seconds'
        )
      )
    ORDER BY r.updated_at
    LIMIT 3
  LOOP
    PERFORM public.canva_carousel_post(v_plan, 'resume');
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."canva_carousel_resume"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_carousel_revise"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_plan_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.social_media_plans p
    WHERE p.id = p_plan_id
      AND p.organization_id IN (SELECT public.user_organization_ids())
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.link_comments c
    WHERE c.social_media_plan_id = p_plan_id
      AND c.carousel_slide_number BETWEEN 1 AND 10
      AND c.canva_revision_applied_at IS NULL
      AND btrim(coalesce(c.comment_text, '')) <> ''
  ) THEN
    RAISE EXCEPTION 'slide_comments_missing' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.canva_carousel_runs
  SET revision_requested = true,
      revision_attempts = 0,
      error = NULL,
      updated_at = now()
  WHERE social_media_plan_id = p_plan_id
    AND status = 'succeeded'
    AND design_id IS NOT NULL
    AND btrim(design_id) <> '';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'canva_design_missing' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.canva_carousel_post(p_plan_id, 'resume');
END;
$$;


