CREATE OR REPLACE FUNCTION "public"."canva_carousel_stop_unapproved"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.approved IS TRUE OR OLD.approved IS DISTINCT FROM TRUE THEN
    RETURN NEW;
  END IF;
  UPDATE public.canva_carousel_runs
  SET status = 'failed',
      error = 'not_approved',
      finished_at = COALESCE(finished_at, now()),
      updated_at = now()
  WHERE social_media_plan_id = NEW.id
    AND status IN ('queued', 'running')
    AND canva_job_id IS NULL;
  RETURN NEW;
END;
$$;


