CREATE OR REPLACE FUNCTION "public"."canva_story_enqueue"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF NEW.approved IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND OLD.approved IS TRUE THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = NEW.pic_id AND e.organization_id = NEW.organization_id AND e.is_ai IS TRUE
  ) THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.content_types ct
    WHERE ct.id = NEW.content_type_id AND lower(btrim(ct.name)) = 'story'
  ) THEN RETURN NEW; END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_canva_connections c
    INNER JOIN public.organization_canva_connection_tokens t ON t.organization_id = c.organization_id
    WHERE c.organization_id = NEW.organization_id AND c.is_active AND c.oauth_connected_at IS NOT NULL
  ) THEN RETURN NEW; END IF;

  INSERT INTO public.canva_story_runs (
    social_media_plan_id, organization_id, status, attempts, updated_at
  )
  VALUES (NEW.id, NEW.organization_id, 'queued', 0, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET status = 'queued',
      error = NULL,
      canva_job_id = NULL,
      continuation_token = NULL,
      finished_at = NULL,
      images_ready = false,
      refresh_requested = false,
      export_attempts = 0,
      attempts = CASE WHEN public.canva_story_runs.status = 'failed' THEN 0 ELSE public.canva_story_runs.attempts END,
      updated_at = now()
  WHERE public.canva_story_runs.status IS DISTINCT FROM 'succeeded'
    AND NOT (
      public.canva_story_runs.status = 'running'
      AND public.canva_story_runs.updated_at > now() - interval '3 minutes'
    )
  RETURNING social_media_plan_id INTO v_id;

  IF v_id IS NULL THEN RETURN NEW; END IF;
  PERFORM public.canva_story_post(NEW.id, 'start');
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."canva_story_enqueue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_story_post"("p_plan_id" "uuid", "p_mode" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url text;
  v_secret text;
BEGIN
  SELECT ds.decrypted_secret INTO v_url
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'ai_employee_project_url'
  LIMIT 1;
  SELECT ds.decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets ds
  WHERE ds.name = 'ai_employee_internal_secret'
  LIMIT 1;

  IF v_url IS NULL OR btrim(v_url) = '' OR v_secret IS NULL OR btrim(v_secret) = '' THEN
    UPDATE public.canva_story_runs
    SET status = 'failed',
        error = 'canva_dispatch_missing',
        finished_at = now(),
        updated_at = now()
    WHERE social_media_plan_id = p_plan_id
      AND status IS DISTINCT FROM 'succeeded';
    RETURN;
  END IF;

  PERFORM net.http_post(
    url := rtrim(v_url, '/') || '/functions/v1/canva-story-run',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-synckerja-internal-secret', v_secret
    ),
    body := jsonb_build_object(
      'plan_id', p_plan_id,
      'mode', CASE
        WHEN p_mode = 'resume' THEN 'resume'
        WHEN p_mode = 'refresh' THEN 'refresh'
        ELSE 'start'
      END
    ),
    timeout_milliseconds := 150000
  );
END;
$$;


ALTER FUNCTION "public"."canva_story_post"("p_plan_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_story_refresh"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_plan_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.social_media_plans p
    WHERE p.id = p_plan_id AND p.organization_id IN (SELECT public.user_organization_ids())
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  UPDATE public.canva_story_runs
  SET refresh_requested = true, images_ready = false, export_attempts = 0, error = NULL, updated_at = now()
  WHERE social_media_plan_id = p_plan_id
    AND status = 'succeeded'
    AND design_id IS NOT NULL AND btrim(design_id) <> '';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'canva_design_missing' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.canva_story_post(p_plan_id, 'refresh');
END;
$$;


ALTER FUNCTION "public"."canva_story_refresh"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_story_resume"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan uuid;
  v_count integer := 0;
BEGIN
  FOR v_plan IN
    SELECT r.social_media_plan_id
    FROM public.canva_story_runs r
    WHERE (
      r.status IN ('queued', 'running')
      AND r.updated_at < now() - interval '40 seconds'
    ) OR (
      r.status = 'succeeded'
      AND r.revision_requested = true
      AND r.design_id IS NOT NULL
      AND r.revision_attempts < 3
      AND r.updated_at < now() - interval '50 seconds'
    ) OR (
      r.status = 'succeeded'
      AND r.revision_requested = false
      AND r.images_ready = false
      AND r.refresh_requested = true
      AND r.updated_at < now() - interval '40 seconds'
    )
    ORDER BY r.updated_at
    LIMIT 3
  LOOP
    PERFORM public.canva_story_post(v_plan, 'resume');
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."canva_story_resume"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_story_revise"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_plan_id IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.social_media_plans p
    WHERE p.id = p_plan_id
      AND p.organization_id IN (SELECT public.user_organization_ids())
  ) THEN
    RAISE EXCEPTION 'not_allowed' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.link_comments c
    WHERE c.social_media_plan_id = p_plan_id
      AND c.canva_revision_applied_at IS NULL
      AND btrim(coalesce(c.comment_text, '')) <> ''
  ) THEN
    RAISE EXCEPTION 'story_comments_missing' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.canva_story_runs
  SET revision_requested = true,
      revision_attempts = 0,
      error = NULL,
      updated_at = now()
  WHERE social_media_plan_id = p_plan_id
    AND status = 'succeeded'
    AND design_id IS NOT NULL
    AND btrim(design_id) <> '';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'canva_design_missing' USING ERRCODE = 'P0002';
  END IF;

  PERFORM public.canva_story_post(p_plan_id, 'resume');
END;
$$;


ALTER FUNCTION "public"."canva_story_revise"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canva_story_start"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_id uuid;
BEGIN
  IF p_plan_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT p.organization_id
  INTO v_org
  FROM public.social_media_plans p
  JOIN public.content_types ct ON ct.id = p.content_type_id
  JOIN public.employees e
    ON e.id = p.pic_id
   AND e.organization_id = p.organization_id
   AND e.is_ai IS TRUE
  WHERE p.id = p_plan_id
    AND p.approved IS TRUE
    AND lower(btrim(ct.name)) = 'story'
    AND p.organization_id IN (SELECT public.user_organization_ids());

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = auth.uid()
      AND role.organization_id = v_org
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.organization_canva_connections c
    INNER JOIN public.organization_canva_connection_tokens t
      ON t.organization_id = c.organization_id
    WHERE c.organization_id = v_org
      AND c.is_active
      AND c.oauth_connected_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'canva_not_connected' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.canva_story_runs (
    social_media_plan_id, organization_id, status, attempts, updated_at
  )
  VALUES (p_plan_id, v_org, 'queued', 0, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET status = 'queued',
      error = NULL,
      canva_job_id = NULL,
      continuation_token = NULL,
      finished_at = NULL,
      images_ready = false,
      refresh_requested = false,
      revision_requested = false,
      revision_attempts = 0,
      review_after_export = false,
      export_attempts = 0,
      attempts = 0,
      updated_at = now()
  WHERE public.canva_story_runs.status IS DISTINCT FROM 'running'
     OR public.canva_story_runs.updated_at <= now() - interval '3 minutes'
  RETURNING social_media_plan_id INTO v_id;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'too_soon' USING ERRCODE = '22023';
  END IF;

  PERFORM public.canva_story_post(p_plan_id, 'start');
END;
$$;


