CREATE OR REPLACE FUNCTION "public"."catalog_po_update_avg_cost"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_old_qty numeric(14, 3);
  v_old_avg numeric(14, 2);
  v_track_cogs boolean;
  v_new_avg numeric(14, 2);
BEGIN
  IF p_qty IS NULL OR p_qty <= 0 THEN
    RETURN;
  END IF;

  IF p_item_kind = 'product' AND p_variant_id IS NOT NULL THEN
    SELECT vo.in_stock, vo.avg_cost, vo.track_cogs
      INTO v_old_qty, v_old_avg, v_track_cogs
    FROM public.catalog_product_variant_outlets vo
    WHERE vo.variant_id = p_variant_id AND vo.outlet_id = p_outlet_id;
    IF v_track_cogs IS NOT TRUE THEN RETURN; END IF;
    v_old_qty := COALESCE(v_old_qty, 0);
    v_old_avg := COALESCE(v_old_avg, 0);
    IF (v_old_qty + p_qty) <= 0 THEN
      v_new_avg := p_unit_cost;
    ELSE
      v_new_avg := ((v_old_qty * v_old_avg) + (p_qty * p_unit_cost)) / (v_old_qty + p_qty);
    END IF;
    UPDATE public.catalog_product_variant_outlets
    SET avg_cost = ROUND(v_new_avg, 2)
    WHERE variant_id = p_variant_id AND outlet_id = p_outlet_id;
    RETURN;
  END IF;

  IF p_item_kind = 'product' THEN
    SELECT po.in_stock, po.avg_cost, po.track_cogs
      INTO v_old_qty, v_old_avg, v_track_cogs
    FROM public.catalog_product_outlets po
    WHERE po.product_id = p_product_id AND po.outlet_id = p_outlet_id;
    IF v_track_cogs IS NOT TRUE THEN RETURN; END IF;
    v_old_qty := COALESCE(v_old_qty, 0);
    v_old_avg := COALESCE(v_old_avg, 0);
    IF (v_old_qty + p_qty) <= 0 THEN
      v_new_avg := p_unit_cost;
    ELSE
      v_new_avg := ((v_old_qty * v_old_avg) + (p_qty * p_unit_cost)) / (v_old_qty + p_qty);
    END IF;
    UPDATE public.catalog_product_outlets
    SET avg_cost = ROUND(v_new_avg, 2)
    WHERE product_id = p_product_id AND outlet_id = p_outlet_id;
    RETURN;
  END IF;

  IF p_item_kind = 'ingredient' THEN
    SELECT io.in_stock, io.avg_cost, io.track_cogs
      INTO v_old_qty, v_old_avg, v_track_cogs
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id;
    IF v_track_cogs IS NOT TRUE THEN RETURN; END IF;
    v_old_qty := COALESCE(v_old_qty, 0);
    v_old_avg := COALESCE(v_old_avg, 0);
    IF (v_old_qty + p_qty) <= 0 THEN
      v_new_avg := p_unit_cost;
    ELSE
      v_new_avg := ((v_old_qty * v_old_avg) + (p_qty * p_unit_cost)) / (v_old_qty + p_qty);
    END IF;
    UPDATE public.catalog_ingredient_outlets
    SET avg_cost = ROUND(v_new_avg, 2)
    WHERE ingredient_id = p_ingredient_id AND outlet_id = p_outlet_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."catalog_po_update_avg_cost"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_qty" numeric, "p_unit_cost" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_product_recipe_validate_header"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  product_kind text;
  option_group_id uuid;
BEGIN
  SELECT kind INTO product_kind
  FROM public.default_prices
  WHERE id = NEW.product_id
    AND organization_id = NEW.organization_id;
  IF product_kind IS DISTINCT FROM 'product' THEN
    RAISE EXCEPTION 'product_recipe_product_must_be_product_kind';
  END IF;

  IF NEW.modifier_option_id IS NOT NULL THEN
    SELECT group_id INTO option_group_id
    FROM public.catalog_modifier_options
    WHERE id = NEW.modifier_option_id
      AND organization_id = NEW.organization_id
      AND is_active = true;
    IF option_group_id IS NULL THEN
      RAISE EXCEPTION 'product_recipe_modifier_option_invalid';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.catalog_product_modifiers cpm
      WHERE cpm.product_id = NEW.product_id
        AND cpm.group_id = option_group_id
    ) THEN
      RAISE EXCEPTION 'product_recipe_modifier_not_linked';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."catalog_product_recipe_validate_header"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_product_recipe_validate_line"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  line_kind text;
BEGIN
  SELECT kind INTO line_kind
  FROM public.catalog_ingredients
  WHERE id = NEW.ingredient_id
    AND organization_id = NEW.organization_id
    AND is_deleted = false;
  IF line_kind NOT IN ('raw', 'semi_finished') THEN
    RAISE EXCEPTION 'product_recipe_line_must_be_ingredient';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."catalog_product_recipe_validate_line"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_recipe_fingerprint"("p_product" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    md5(string_agg(l.ingredient_id::text || ':' || trim_scale(l.quantity)::text, '|' ORDER BY l.ingredient_id)),
    ''
  )
  FROM public.catalog_product_recipes r
  JOIN public.catalog_product_recipe_lines l ON l.recipe_id = r.id
  WHERE r.product_id = p_product AND r.modifier_option_id IS NULL;
$$;


ALTER FUNCTION "public"."catalog_recipe_fingerprint"("p_product" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_stock_movement_outlet_unit_cost"("p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT NULLIF(
    CASE
      WHEN p_item_kind = 'ingredient' THEN (
        SELECT io.avg_cost FROM public.catalog_ingredient_outlets io
        WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id
      )
      WHEN p_item_kind = 'product' AND p_variant_id IS NOT NULL THEN (
        SELECT vo.avg_cost FROM public.catalog_product_variant_outlets vo
        WHERE vo.variant_id = p_variant_id AND vo.outlet_id = p_outlet_id
      )
      WHEN p_item_kind = 'product' THEN (
        SELECT po.avg_cost FROM public.catalog_product_outlets po
        WHERE po.product_id = p_product_id AND po.outlet_id = p_outlet_id
      )
    END,
    0
  );
$$;


ALTER FUNCTION "public"."catalog_stock_movement_outlet_unit_cost"("p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_stock_movements_stamp_unit_cost"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.movement_type = 'adjustment' AND NEW.unit_cost IS NULL THEN
    NEW.unit_cost := public.catalog_stock_movement_outlet_unit_cost(
      NEW.outlet_id, NEW.item_kind, NEW.product_id, NEW.variant_id, NEW.ingredient_id
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."catalog_stock_movements_stamp_unit_cost"() OWNER TO "postgres";


