    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.catalog_po_actor_name(p_organization_id);
$$;


ALTER FUNCTION "public"."catalog_transfer_actor_name"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_transfer_ensure_dest_row"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_track_cogs" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_item_kind = 'product' AND p_variant_id IS NOT NULL THEN
    INSERT INTO public.catalog_product_variant_outlets (
      variant_id, outlet_id, organization_id, in_stock, track_cogs
    ) VALUES (
      p_variant_id, p_outlet_id, p_organization_id, 0, COALESCE(p_track_cogs, false)
    )
    ON CONFLICT (variant_id, outlet_id) DO NOTHING;
  ELSIF p_item_kind = 'product' THEN
    INSERT INTO public.catalog_product_outlets (
      product_id, outlet_id, organization_id, in_stock, track_cogs
    ) VALUES (
      p_product_id, p_outlet_id, p_organization_id, 0, COALESCE(p_track_cogs, false)
    )
    ON CONFLICT (product_id, outlet_id) DO NOTHING;
  ELSE
    INSERT INTO public.catalog_ingredient_outlets (
      ingredient_id, outlet_id, organization_id, in_stock, track_cogs
    ) VALUES (
      p_ingredient_id, p_outlet_id, p_organization_id, 0, COALESCE(p_track_cogs, false)
    )
    ON CONFLICT (ingredient_id, outlet_id) DO NOTHING;
  END IF;
END;
$$;


ALTER FUNCTION "public"."catalog_transfer_ensure_dest_row"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_track_cogs" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_transfer_fulfill_line"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_to_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_line" "record") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_src_avg numeric;
  v_src_cogs boolean;
  v_resolved_variant uuid;
  v_product_id uuid;
  v_variant_id uuid;
  v_ingredient_id uuid;
  v_qty numeric;
BEGIN
  v_qty := p_line.qty;
  v_product_id := p_line.product_id;
  v_variant_id := p_line.variant_id;
  v_ingredient_id := p_line.ingredient_id;

  SELECT
    o_avg_cost, o_track_cogs, o_variant_id
    INTO v_src_avg, v_src_cogs, v_resolved_variant
  FROM public.catalog_transfer_read_source_stock(
    p_organization_id,
    p_to_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id
  );

  IF p_item_kind = 'product' THEN
    v_variant_id := v_resolved_variant;
  END IF;

  PERFORM public.catalog_transfer_ensure_dest_row(
    p_organization_id,
    p_to_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id,
    v_src_cogs
  );

  PERFORM public.catalog_po_update_avg_cost(
    p_organization_id,
    p_to_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id,
    v_qty,
    v_src_avg
  );

  PERFORM public.apply_catalog_stock_movement(
    p_organization_id,
    p_to_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id,
    'transfer',
    v_qty,
    'inventory_transfer',
    p_transfer_id::text || ':' || p_line.id::text || ':to',
    NULLIF(btrim(p_note), '')
  );
END;
$$;


ALTER FUNCTION "public"."catalog_transfer_fulfill_line"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_to_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_line" "record") OWNER TO "postgres";


