ALTER FUNCTION "public"."catalog_transfer_insert_event"("p_transfer_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_transfer_read_source_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", OUT "o_qty" numeric, OUT "o_avg_cost" numeric, OUT "o_track_cogs" boolean, OUT "o_variant_id" "uuid") RETURNS "record"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
BEGIN
  o_qty := 0;
  o_avg_cost := 0;
  o_track_cogs := false;
  o_variant_id := p_variant_id;

  IF p_item_kind = 'product' THEN
    IF o_variant_id IS NULL THEN
      SELECT v.id
        INTO o_variant_id
      FROM public.catalog_product_variants v
      WHERE v.product_id = p_product_id
      ORDER BY v.sort_order, v.created_at
      LIMIT 1;
    END IF;

    IF o_variant_id IS NOT NULL THEN
      SELECT vo.in_stock, vo.avg_cost, vo.track_cogs
        INTO o_qty, o_avg_cost, o_track_cogs
      FROM public.catalog_product_variant_outlets vo
      WHERE vo.variant_id = o_variant_id AND vo.outlet_id = p_outlet_id;
    ELSE
      SELECT po.in_stock, po.avg_cost, po.track_cogs
        INTO o_qty, o_avg_cost, o_track_cogs
      FROM public.catalog_product_outlets po
      WHERE po.product_id = p_product_id AND po.outlet_id = p_outlet_id;
    END IF;
  ELSE
    SELECT io.in_stock, io.avg_cost, io.track_cogs
      INTO o_qty, o_avg_cost, o_track_cogs
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id;
  END IF;

  o_qty := COALESCE(o_qty, 0);
  o_avg_cost := COALESCE(o_avg_cost, 0);
  o_track_cogs := COALESCE(o_track_cogs, false);
END;
$$;


ALTER FUNCTION "public"."catalog_transfer_read_source_stock"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", OUT "o_qty" numeric, OUT "o_avg_cost" numeric, OUT "o_track_cogs" boolean, OUT "o_variant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_transfer_ship_line"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_from_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_line" "record") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_src_qty numeric;
  v_src_avg numeric;
  v_src_cogs boolean;
  v_resolved_variant uuid;
  v_product_id uuid;
  v_variant_id uuid;
  v_ingredient_id uuid;
  v_qty numeric;
BEGIN
  v_qty := p_line.qty;
  v_product_id := p_line.product_id;
  v_variant_id := p_line.variant_id;
  v_ingredient_id := p_line.ingredient_id;

  SELECT
    o_qty, o_avg_cost, o_track_cogs, o_variant_id
    INTO v_src_qty, v_src_avg, v_src_cogs, v_resolved_variant
  FROM public.catalog_transfer_read_source_stock(
    p_organization_id,
    p_from_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id
  );

  IF p_item_kind = 'product' THEN
    v_variant_id := v_resolved_variant;
  END IF;

  IF v_qty > v_src_qty THEN
    RAISE EXCEPTION 'catalog_stock_insufficient';
  END IF;

  PERFORM public.apply_catalog_stock_movement(
    p_organization_id,
    p_from_outlet_id,
    p_item_kind,
    v_product_id,
    v_variant_id,
    v_ingredient_id,
    'transfer',
    -v_qty,
    'inventory_transfer',
    p_transfer_id::text || ':' || p_line.id::text || ':from',
    NULLIF(btrim(p_note), '')
  );
END;
$$;


ALTER FUNCTION "public"."catalog_transfer_ship_line"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_from_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_line" "record") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_campaign_budget_headroom"("p_campaign_id" "uuid", "p_additional_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_remaining numeric(15, 2);
  v_additional numeric(15, 2);
BEGIN
  IF p_campaign_id IS NULL THEN
    RETURN true;
  END IF;

  v_additional := COALESCE(p_additional_amount, 0);
  IF v_additional <= 0 THEN
    RETURN true;
  END IF;

  SELECT COALESCE(remaining_budget, 0)
  INTO v_remaining
  FROM public.kol_campaigns
  WHERE id = p_campaign_id;

  IF v_remaining < v_additional THEN
    RAISE EXCEPTION 'Campaign budget exceeded: remaining %, requested %', v_remaining, v_additional
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."check_campaign_budget_headroom"("p_campaign_id" "uuid", "p_additional_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_carousel_images_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  img_count INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  SELECT COUNT(*)::INTEGER INTO img_count
  FROM public.social_media_plan_carousel_images
  WHERE social_media_plan_id = NEW.social_media_plan_id;

  IF img_count >= 10 THEN
    RAISE EXCEPTION 'Maximum 10 carousel images per plan.';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_carousel_images_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_subscription_over_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.current_member IS NOT NULL
     AND NEW.member_count IS NOT NULL
     AND NEW.current_member > NEW.member_count THEN
    NEW.is_over_limit := true;
  ELSIF NEW.current_member IS NOT NULL AND NEW.member_count IS NOT NULL THEN
    NEW.is_over_limit := false;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_subscription_over_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_threshold_achievement"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.current_value is not null
     and new.target_value is not null
     and new.target_value > 0
     and new.current_value >= new.target_value
  then
    if coalesce(new.is_achieved, false) is distinct from true then
      new.is_achieved := true;
      new.achieved_at := coalesce(new.achieved_at, timezone('utc'::text, now()));
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."check_threshold_achievement"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."daily_task_assignment_push_queue" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "recipient_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    "event_type" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "daily_task_id" "uuid",
    "task_step_id" "uuid",
    "task_steps_to_steps_id" "uuid",
    "title" "text" DEFAULT ''::"text" NOT NULL,
    "due_date" timestamp with time zone,
    "assigned_by_user_id" "uuid",
    "url" "text" DEFAULT ''::"text" NOT NULL,
    CONSTRAINT "daily_task_assignment_push_queue_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['task'::"text", 'step'::"text", 'substep'::"text"]))),
    CONSTRAINT "daily_task_assignment_push_queue_event_type_check" CHECK (("event_type" = ANY (ARRAY['assign'::"text", 'unassign'::"text", 'reassign'::"text"])))
);


ALTER TABLE "public"."daily_task_assignment_push_queue" OWNER TO "postgres";


COMMENT ON TABLE "public"."daily_task_assignment_push_queue" IS 'Queue for batching Daily Task assignment pushes (one row per recipient).';



CREATE OR REPLACE FUNCTION "public"."claim_daily_task_assignment_push_queue"("p_recipient_user_id" "uuid", "p_window_seconds" integer DEFAULT 20, "p_max" integer DEFAULT 25) RETURNS SETOF "public"."daily_task_assignment_push_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT q.id
    FROM public.daily_task_assignment_push_queue q
    WHERE q.recipient_user_id = p_recipient_user_id
      AND q.sent_at IS NULL
      AND q.created_at >= now() - make_interval(secs => GREATEST(1, p_window_seconds))
    ORDER BY q.created_at DESC
    LIMIT GREATEST(1, p_max)
    FOR UPDATE SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.daily_task_assignment_push_queue q
    SET sent_at = now()
    FROM candidates c
    WHERE q.id = c.id
      AND q.sent_at IS NULL
    RETURNING q.*
  )
  SELECT * FROM claimed;
END;
$$;


ALTER FUNCTION "public"."claim_daily_task_assignment_push_queue"("p_recipient_user_id" "uuid", "p_window_seconds" integer, "p_max" integer) OWNER TO "postgres";


