    "media_resolved_url" "text",
    "caption" "text",
    "title" "text",
    "privacy_level" "text" DEFAULT 'PUBLIC_TO_EVERYONE'::"text",
    "provider_config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "external_post_id" "text",
    "published_url" "text",
    "published_at" timestamp with time zone,
    "error_message" "text",
    "retry_count" integer DEFAULT 0 NOT NULL,
    "scheduled_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "next_retry_at" timestamp with time zone,
    "locked_at" timestamp with time zone,
    "last_error_at" timestamp with time zone,
    "platform_account_id" "text",
    CONSTRAINT "social_media_scheduled_posts_delivery_mode_check" CHECK (("delivery_mode" = ANY (ARRAY['api_auto'::"text", 'manual_only'::"text"]))),
    CONSTRAINT "social_media_scheduled_posts_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'publishing'::"text", 'published'::"text", 'failed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."social_media_scheduled_posts" OWNER TO "postgres";


COMMENT ON TABLE "public"."social_media_scheduled_posts" IS 'Scheduled auto-publish jobs per social_media_plan and platform. Phase 1: TikTok api_auto.';



COMMENT ON COLUMN "public"."social_media_scheduled_posts"."next_retry_at" IS 'Do not claim before this time (retry backoff).';



COMMENT ON COLUMN "public"."social_media_scheduled_posts"."locked_at" IS 'When the row entered publishing (worker claim).';



COMMENT ON COLUMN "public"."social_media_scheduled_posts"."last_error_at" IS 'Timestamp of the most recent publish error.';



COMMENT ON COLUMN "public"."social_media_scheduled_posts"."platform_account_id" IS 'OAuth account id denormalized from provider_config for multi-account per platform.';



CREATE OR REPLACE FUNCTION "public"."claim_due_scheduled_posts"("p_limit" integer DEFAULT 25, "p_per_org_limit" integer DEFAULT 3) RETURNS SETOF "public"."social_media_scheduled_posts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH due AS (
    SELECT
      s.id,
      s.organization_id,
      s.scheduled_at,
      ROW_NUMBER() OVER (
        PARTITION BY s.organization_id ORDER BY s.scheduled_at ASC
      ) AS org_rn
    FROM public.social_media_scheduled_posts s
    WHERE s.status = 'pending'
      AND s.scheduled_at <= now()
      AND (s.next_retry_at IS NULL OR s.next_retry_at <= now())
      AND NOT EXISTS (
        SELECT 1
        FROM public.social_media_scheduled_posts earlier
        WHERE earlier.social_media_plan_id = s.social_media_plan_id
          AND earlier.id <> s.id
          AND earlier.status NOT IN ('published', 'cancelled')
          AND (
            public.scheduled_post_platform_rank(earlier.platform)
              < public.scheduled_post_platform_rank(s.platform)
            OR (
              public.scheduled_post_platform_rank(earlier.platform)
                = public.scheduled_post_platform_rank(s.platform)
              AND COALESCE(earlier.platform_account_id, '')
                < COALESCE(s.platform_account_id, '')
            )
          )
      )
  ),
  ranked_candidates AS (
    SELECT d.id, d.scheduled_at
    FROM due d
    WHERE d.org_rn <= GREATEST(1, LEAST(COALESCE(p_per_org_limit, 3), 20))
    ORDER BY d.scheduled_at ASC
    LIMIT GREATEST(1, LEAST(p_limit, 100))
  ),
  candidates AS (
    SELECT s.id
    FROM public.social_media_scheduled_posts s
    INNER JOIN ranked_candidates rc ON rc.id = s.id
    FOR UPDATE OF s SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.social_media_scheduled_posts s
    SET
      status = 'publishing',
      locked_at = now(),
      updated_at = now()
    FROM candidates c
    WHERE s.id = c.id
      AND s.status = 'pending'
    RETURNING s.*
  )
  SELECT * FROM claimed;
END;
$$;


ALTER FUNCTION "public"."claim_due_scheduled_posts"("p_limit" integer, "p_per_org_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_due_scheduled_posts"("p_limit" integer, "p_per_org_limit" integer) IS 'Claim due pending rows. A later platform waits until every earlier platform on the same plan is published.';



CREATE TABLE IF NOT EXISTS "public"."google_contacts_sync_jobs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "reason" "text" DEFAULT 'create'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "run_after" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "google_contacts_sync_jobs_reason_check" CHECK (("reason" = ANY (ARRAY['create'::"text", 'update'::"text", 'backfill'::"text"]))),
    CONSTRAINT "google_contacts_sync_jobs_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'done'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."google_contacts_sync_jobs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_google_contacts_sync_jobs"("p_limit" integer DEFAULT 25) RETURNS SETOF "public"."google_contacts_sync_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH picked AS (
    SELECT j.id
    FROM public.google_contacts_sync_jobs j
    WHERE j.status IN ('pending', 'failed')
      AND j.run_after <= now()
      AND j.attempts < 8
    ORDER BY j.run_after ASC, j.created_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 25), 100))
    FOR UPDATE SKIP LOCKED
  )
  UPDATE public.google_contacts_sync_jobs j
  SET status = 'processing',
      attempts = j.attempts + 1,
      updated_at = now()
  FROM picked
  WHERE j.id = picked.id
  RETURNING j.*;
END;
$$;


ALTER FUNCTION "public"."claim_google_contacts_sync_jobs"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_resume_publishing_posts"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."social_media_scheduled_posts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT s.id
    FROM public.social_media_scheduled_posts s
    WHERE s.status = 'publishing'
      AND COALESCE(s.locked_at, s.updated_at) < now() - interval '10 minutes'
      AND (
        (
          s.platform = 'TikTok'
          AND s.provider_config->>'tiktok_publish_id' IS NOT NULL
        )
        OR (
          s.platform = 'YouTube'
          AND (
            (
              s.provider_config->>'youtube_upload_url' IS NOT NULL
              AND COALESCE(s.provider_config->>'youtube_upload_completed', 'false') = 'true'
            )
            OR s.provider_config->>'youtube_video_id' IS NOT NULL
          )
        )
        OR (
          s.platform = 'Instagram'
          AND s.provider_config->>'ig_container_id' IS NOT NULL
          AND COALESCE(s.provider_config->>'ig_upload_phase', '') IN ('uploaded', 'published')
        )
        OR (
          s.platform = 'Facebook'
          AND s.provider_config->>'fb_video_id' IS NOT NULL
        )
        OR (
          s.platform = 'LinkedIn'
          AND (
            s.provider_config->>'linkedin_upload_urn' IS NOT NULL
            OR s.provider_config->>'linkedin_post_urn' IS NOT NULL
          )
        )
      )
    ORDER BY COALESCE(s.locked_at, s.updated_at) ASC
    LIMIT GREATEST(1, LEAST(p_limit, 50))
    FOR UPDATE SKIP LOCKED
  ),
  touched AS (
    UPDATE public.social_media_scheduled_posts s
    SET
      locked_at = now(),
      updated_at = now()
    FROM candidates c
    WHERE s.id = c.id
      AND s.status = 'publishing'
    RETURNING s.*
  )
  SELECT * FROM touched;
END;
$$;


ALTER FUNCTION "public"."claim_resume_publishing_posts"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."claim_resume_publishing_posts"("p_limit" integer) IS 'Re-claim publishing rows with no heartbeat for 10 minutes when TikTok/Facebook/YouTube/Instagram/LinkedIn already has resume state.';



