CREATE OR REPLACE FUNCTION "public"."claim_social_media_production_push_queue"("p_recipient_user_id" "uuid", "p_window_seconds" integer DEFAULT 20, "p_max" integer DEFAULT 25) RETURNS SETOF "public"."social_media_production_push_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH candidates AS (
    SELECT q.id
    FROM public.social_media_production_push_queue q
    WHERE q.recipient_user_id = p_recipient_user_id
      AND q.sent_at IS NULL
      AND q.created_at >= now() - make_interval(secs => GREATEST(1, p_window_seconds))
    ORDER BY q.created_at DESC
    LIMIT GREATEST(1, p_max)
    FOR UPDATE SKIP LOCKED
  ),
  claimed AS (
    UPDATE public.social_media_production_push_queue q
    SET sent_at = now()
    FROM candidates c
    WHERE q.id = c.id
      AND q.sent_at IS NULL
    RETURNING q.*
  )
  SELECT * FROM claimed;
END;
$$;


