CREATE OR REPLACE FUNCTION "public"."cms_sales_contract_path_allowed"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid;
BEGIN
  IF NOT public.is_cms_admin() THEN
    RETURN false;
  END IF;
  IF p_name IS NULL
     OR p_name !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$'
  THEN
    RETURN false;
  END IF;
  v_org := split_part(p_name, '/', 1)::uuid;
  RETURN EXISTS (
    SELECT 1 FROM public.organizations o WHERE o.id = v_org
  );
END;
$_$;


