CREATE OR REPLACE FUNCTION "public"."cognitive_start_test"("p_recruitment_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_test_id uuid;
  v_duration_minutes integer;
  v_candidate_test_id uuid;
  v_started_at timestamptz;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;

  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT t.id, t.duration_minutes
  INTO v_test_id, v_duration_minutes
  FROM public.tests t
  WHERE t.type = 'cognitive'
    AND t.is_active = true
  ORDER BY t.updated_at DESC
  LIMIT 1;

  IF v_test_id IS NULL THEN
    v_test_id := 'a1000000-0000-4000-8000-000000000002'::uuid;
    v_duration_minutes := 15;
  END IF;

  v_started_at := now();

  INSERT INTO public.candidate_tests (
    candidate_profile_id,
    test_id,
    status,
    started_at,
    created_at,
    updated_at
  )
  VALUES (
    v_profile_id,
    v_test_id,
    'in_progress',
    v_started_at,
    v_started_at,
    v_started_at
  )
  ON CONFLICT (candidate_profile_id, test_id)
  DO UPDATE SET
    status = 'in_progress',
    started_at = EXCLUDED.started_at,
    submitted_at = NULL,
    score_total = NULL,
    score_verbal = NULL,
    score_numerical = NULL,
    score_logical = NULL,
    answers = NULL,
    updated_at = EXCLUDED.updated_at
  RETURNING id INTO v_candidate_test_id;

  RETURN jsonb_build_object(
    'candidate_test_id', v_candidate_test_id,
    'started_at', v_started_at,
    'duration_minutes', COALESCE(v_duration_minutes, 15)
  );
END;
$$;


ALTER FUNCTION "public"."cognitive_start_test"("p_recruitment_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cognitive_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_cognitive_question_id" "uuid", "p_selected_option_index" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_candidate_profile_id uuid;
  v_test_id uuid;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL OR p_cognitive_question_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;
  IF p_selected_option_index NOT BETWEEN 1 AND 4 THEN
    RAISE EXCEPTION 'Pilihan jawaban tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;
  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id
  INTO v_candidate_profile_id, v_test_id
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;
  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.cognitive_questions cq
    WHERE cq.id = p_cognitive_question_id
      AND cq.test_id = v_test_id
  ) THEN
    RAISE EXCEPTION 'Soal tidak valid';
  END IF;

  UPDATE public.candidate_tests ct
  SET
    status = 'in_progress',
    answers = jsonb_set(
      COALESCE(ct.answers, '{}'::jsonb),
      ARRAY[p_cognitive_question_id::text],
      to_jsonb(p_selected_option_index),
      true
    ),
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;
END;
$$;


ALTER FUNCTION "public"."cognitive_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_cognitive_question_id" "uuid", "p_selected_option_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cognitive_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_candidate_profile_id uuid;
  v_test_id uuid;
  v_answers jsonb;
  v_total integer := 0;
  v_verbal integer := 0;
  v_numerical integer := 0;
  v_logical integer := 0;
  r record;
  v_selected integer;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;
  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id, ct.answers
  INTO v_candidate_profile_id, v_test_id, v_answers
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;
  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  v_answers := COALESCE(v_answers, '{}'::jsonb);

  FOR r IN
    SELECT cq.id, cq.correct_option_index, cq.category
    FROM public.cognitive_questions cq
    WHERE cq.test_id = v_test_id
    ORDER BY cq.question_order ASC
  LOOP
    v_selected := NULLIF((v_answers ->> r.id::text)::int, 0);
    IF v_selected IS NULL THEN
      CONTINUE;
    END IF;
    IF v_selected = r.correct_option_index THEN
      v_total := v_total + 1;
      IF r.category = 'verbal' THEN
        v_verbal := v_verbal + 1;
      ELSIF r.category = 'numerical' THEN
        v_numerical := v_numerical + 1;
      ELSIF r.category = 'logical' THEN
        v_logical := v_logical + 1;
      END IF;
    END IF;
  END LOOP;

  UPDATE public.candidate_tests ct
  SET
    status = 'submitted',
    submitted_at = now(),
    score_total = v_total,
    score_verbal = v_verbal,
    score_numerical = v_numerical,
    score_logical = v_logical,
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;

  RETURN jsonb_build_object(
    'score_total', v_total,
    'score_verbal', v_verbal,
    'score_numerical', v_numerical,
    'score_logical', v_logical
  );
END;
$$;


ALTER FUNCTION "public"."cognitive_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_synckerja_order_qris"("p_code" "text", "p_pending_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_st_id uuid;
  v_st_name text := 'Dine In';
  v_cart jsonb;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet_paid(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
    AND organization_id = v_out.organization_id
    AND pos_outlet_id = v_out.outlet_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF v_pending.status <> 'paid' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_paid');
  END IF;
  SELECT st.id, st.name INTO v_st_id, v_st_name
  FROM public.catalog_sales_types st
  WHERE st.organization_id = v_out.organization_id AND st.is_active AND lower(st.name) LIKE '%dine%'
  ORDER BY st.sort_order LIMIT 1;
  v_cart := COALESCE(v_pending.payload -> 'cart', '[]'::jsonb);
  IF jsonb_typeof(v_cart) <> 'array' OR jsonb_array_length(v_cart) < 1 THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'lineKey', 'plain:' || COALESCE(elem ->> 'catalog_product_id', ''),
      'catalogId', elem ->> 'catalog_product_id',
      'kind', COALESCE(NULLIF(elem ->> 'item_kind', ''), 'product'),
      'serviceName', elem ->> 'service_name',
      'subServiceName', elem -> 'sub_service_name',
      'quantity', elem ->> 'quantity',
      'unitPrice', elem ->> 'unit_price',
      'variantId', elem -> 'catalog_variant_id'
    )), '[]'::jsonb)
    INTO v_cart
    FROM jsonb_array_elements(COALESCE(v_pending.payload -> 'items', '[]'::jsonb)) AS elem;
  END IF;

  IF v_pending.session_id IS NOT NULL AND v_pending.sales_activity_id IS NOT NULL THEN
    UPDATE public.pos_table_sessions
    SET sales_activity_id = COALESCE(sales_activity_id, v_pending.sales_activity_id)
    WHERE id = v_pending.session_id
      AND organization_id = v_out.organization_id
      AND outlet_id = v_out.outlet_id
      AND status = 'open';
    PERFORM public._synckerja_order_fire_kitchen(
      v_out.organization_id,
      v_out.outlet_id,
      v_pending.session_id,
      NULLIF(v_pending.payload #>> '{activity,pos_table_id}', '')::uuid,
      COALESCE(v_pending.payload #>> '{activity,table_number}', 'Walk-in'),
      v_pending.payload #>> '{activity,client_name}',
      v_cart,
      'on_pay',
      COALESCE(v_st_name, 'Dine In'),
      v_st_id
    );
  END IF;
  RETURN jsonb_build_object('ok', true, 'sales_activity_id', v_pending.sales_activity_id);
END;
$$;


