$$;


ALTER FUNCTION "public"."compute_omnichannel_seat_topup_amount"("p_org_id" "uuid", "p_additional_seats" integer, "p_billing_cycle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_omnichannel_seat_topup_amount_service"("p_org_id" "uuid", "p_additional_seats" integer, "p_billing_cycle" "text", "p_verified_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_seats integer;
  v_cycle text;
  v_plan_id uuid;
  v_member_count integer;
  v_paid integer;
  v_headroom integer;
  v_unit numeric;
  v_follows_plan_discount boolean;
  v_annual_pct numeric;
  v_monthly_total numeric;
  v_yearly numeric;
BEGIN
  IF p_verified_user_id IS NULL THEN
    RAISE EXCEPTION 'verified user required';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_verified_user_id AND uo.organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.organizations o
    WHERE o.id = p_org_id
      AND coalesce(o.subscription_self_service_enabled, true) = false
  ) THEN
    RAISE EXCEPTION 'sales tenants cannot purchase omnichannel seats';
  END IF;

  v_seats := p_additional_seats;
  IF v_seats IS NULL OR v_seats < 1 THEN
    RAISE EXCEPTION 'additional seats must be >= 1';
  END IF;

  v_cycle := lower(trim(coalesce(p_billing_cycle, 'monthly')));
  IF v_cycle NOT IN ('monthly', 'yearly') THEN
    RAISE EXCEPTION 'billing_cycle must be monthly or yearly';
  END IF;

  SELECT
    os.subscription_plan_id,
    COALESCE(os.member_count, 0)::integer,
    COALESCE(os.omnichannel_paid_seat_count, 0)::integer
  INTO v_plan_id, v_member_count, v_paid
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_org_id
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'no organization subscription';
  END IF;

  v_headroom := GREATEST(0, v_member_count - v_paid);
  IF v_headroom < 1 THEN
    RAISE EXCEPTION 'no headroom for additional omnichannel seats under current HR member limit';
  END IF;
  IF v_seats > v_headroom THEN
    RAISE EXCEPTION 'additional seats cannot exceed HR member headroom (member_count minus paid omnichannel seats)';
  END IF;

  SELECT
    coalesce(ppao.unit_price_override_per_month, sa.default_unit_price_per_month),
    sa.follows_plan_annual_discount,
    sp.annual_discount_percentage
  INTO v_unit, v_follows_plan_discount, v_annual_pct
  FROM public.subscription_plan_add_ons ppao
  INNER JOIN public.subscription_add_ons sa ON sa.id = ppao.add_on_id
  INNER JOIN public.subscription_plans sp ON sp.id = ppao.subscription_plan_id
  WHERE ppao.subscription_plan_id = v_plan_id
    AND sa.code = 'omnichannel_roster'
    AND sa.is_active = true
    AND sp.is_active = true
  LIMIT 1;

  IF v_unit IS NULL THEN
    RAISE EXCEPTION 'omnichannel add-on not available for current plan';
  END IF;

  v_monthly_total := greatest(0::numeric, v_unit) * v_seats;

  IF v_cycle = 'monthly' THEN
    RETURN round(v_monthly_total);
  END IF;

  v_annual_pct := case
    when coalesce(v_follows_plan_discount, true) then coalesce(v_annual_pct, 20::numeric)
    else 20::numeric
  end;

  v_yearly := v_monthly_total * 12 * (1 - coalesce(v_annual_pct, 20) / 100::numeric);
  RETURN round(v_yearly);
END;
$$;


ALTER FUNCTION "public"."compute_omnichannel_seat_topup_amount_service"("p_org_id" "uuid", "p_additional_seats" integer, "p_billing_cycle" "text", "p_verified_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_bank_expense_mutation_match"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match public.bank_mutation_matches%ROWTYPE;
  v_actor uuid;
BEGIN
  v_actor := auth.uid();

  SELECT * INTO v_match
  FROM public.bank_mutation_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_mutation_match_not_found';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_match.organization_id) THEN
    RAISE EXCEPTION 'bank_mutation_match_forbidden';
  END IF;

  IF v_match.status <> 'suggested' THEN
    RAISE EXCEPTION 'bank_mutation_match_not_suggested';
  END IF;

  IF v_match.expense_id IS NULL THEN
    RAISE EXCEPTION 'bank_mutation_match_no_expense';
  END IF;

  UPDATE public.bank_statement_lines
  SET expense_id = v_match.expense_id
  WHERE id = v_match.statement_line_id
    AND expense_id IS NULL;

  UPDATE public.bank_mutation_matches
  SET
    status = 'confirmed',
    confirmed_by = v_actor,
    confirmed_at = now(),
    updated_at = now()
  WHERE id = v_match.id;

  RETURN jsonb_build_object(
    'ok', true,
    'match_id', v_match.id,
    'expense_id', v_match.expense_id
  );
END;
$$;


ALTER FUNCTION "public"."confirm_bank_expense_mutation_match"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_bank_mutation_match"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match public.bank_mutation_matches%ROWTYPE;
  v_actor uuid;
  v_confirm jsonb;
BEGIN
  v_actor := auth.uid();

  SELECT * INTO v_match
  FROM public.bank_mutation_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_mutation_match_not_found';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_match.organization_id) THEN
    RAISE EXCEPTION 'bank_mutation_match_forbidden';
  END IF;

  IF v_match.status <> 'suggested' THEN
    RAISE EXCEPTION 'bank_mutation_match_not_suggested';
  END IF;

  IF v_match.income_transaction_id IS NULL THEN
    RAISE EXCEPTION 'bank_mutation_match_no_income';
  END IF;

  v_confirm := public.confirm_income_bank_deposit(
    v_match.income_transaction_id,
    'brick_mutasi',
    v_actor
  );

  IF v_match.sales_activity_payment_id IS NOT NULL THEN
    UPDATE public.sales_activity_payments
    SET
      transfer_verification_status = 'approved',
      transfer_verified_at = now(),
      transfer_verified_by = v_actor
    WHERE id = v_match.sales_activity_payment_id;
  END IF;

  UPDATE public.bank_mutation_matches
  SET
    status = 'confirmed',
    confirmed_by = v_actor,
    confirmed_at = now(),
    updated_at = now()
  WHERE id = v_match.id;

  RETURN jsonb_build_object(
    'ok', true,
    'match_id', v_match.id,
    'deposit', v_confirm
  );
END;
$$;


ALTER FUNCTION "public"."confirm_bank_mutation_match"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_email_verification"("p_token" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v email_verification_tokens%ROWTYPE;
BEGIN
  SELECT * INTO v FROM public.email_verification_tokens WHERE token = p_token FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_token');
  END IF;
  IF v.email_verified THEN
    RETURN json_build_object('ok', true, 'already', true);
  END IF;
  IF v.expires_at < now() THEN
    RETURN json_build_object('ok', false, 'error', 'expired');
  END IF;
  UPDATE public.email_verification_tokens
  SET email_verified = true, used_at = now()
  WHERE token = p_token;
  RETURN json_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."confirm_email_verification"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_email_verification_otp"("p_email" "text", "p_code" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
DECLARE
  c_max_per_token constant int := 5;
  c_max_per_user_24h constant int := 20;
  v_email_norm text := lower(trim(coalesce(p_email, '')));
  v_code text;
  v_uid uuid;
  v_recent_failures int;
  v_row public.email_verification_tokens%ROWTYPE;
BEGIN
  IF length(v_email_norm) = 0 THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_input');
  END IF;

  v_code := regexp_replace(coalesce(p_code, ''), '\D', '', 'g');
  IF length(v_code) <> 6 THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_code');
  END IF;

  SELECT u.id INTO v_uid FROM auth.users u WHERE lower(trim(u.email)) = v_email_norm LIMIT 1;
  IF v_uid IS NULL THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_code');
  END IF;

  SELECT coalesce(sum(t.failed_attempts), 0) INTO v_recent_failures
  FROM public.email_verification_tokens t
  WHERE t.user_id = v_uid AND t.created_at > now() - interval '24 hours';
  IF v_recent_failures >= c_max_per_user_24h THEN
    RETURN json_build_object('ok', false, 'error', 'too_many_attempts');
  END IF;

  SELECT * INTO v_row
  FROM public.email_verification_tokens
  WHERE user_id = v_uid AND email_verified = false AND expires_at >= now()
    AND failed_attempts < c_max_per_token
  ORDER BY created_at DESC
  LIMIT 1
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_or_expired');
  END IF;

  IF v_row.token <> v_code THEN
    UPDATE public.email_verification_tokens
    SET failed_attempts = failed_attempts + 1,
        expires_at = CASE WHEN failed_attempts + 1 >= c_max_per_token THEN now() - interval '1 second' ELSE expires_at END
    WHERE id = v_row.id;
    IF v_row.failed_attempts + 1 >= c_max_per_token THEN
      RETURN json_build_object('ok', false, 'error', 'too_many_attempts');
    END IF;
    RETURN json_build_object('ok', false, 'error', 'invalid_code');
  END IF;

  UPDATE public.email_verification_tokens
  SET email_verified = true, used_at = now()
  WHERE id = v_row.id;
  RETURN json_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."confirm_email_verification_otp"("p_email" "text", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."confirm_income_bank_deposit"("p_income_id" "uuid", "p_deposit_source" "text" DEFAULT 'manual_verification'::"text", "p_confirmed_by" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_income public.income_transactions%ROWTYPE;
  v_actor uuid;
  v_source text;
  v_new_status text;
BEGIN
  -- User yang login selalu tercatat sebagai pengonfirmasi; p_confirmed_by hanya untuk service_role.
  v_actor := COALESCE(auth.uid(), p_confirmed_by);
  v_source := COALESCE(NULLIF(btrim(p_deposit_source), ''), 'manual_verification');

  SELECT * INTO v_income
  FROM public.income_transactions
  WHERE id = p_income_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'income_transaction_not_found';
  END IF;

  IF v_income.status = 'cancelled' THEN
    RAISE EXCEPTION 'income_transaction_cancelled';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_income.organization_id) THEN
    RAISE EXCEPTION 'income_deposit_confirm_forbidden';
  END IF;

  IF v_income.deposit_confirmed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_confirmed', true,
      'income_id', v_income.id,
      'status', v_income.status
    );
  END IF;

  IF v_income.bank_account_id IS NULL THEN
    RAISE EXCEPTION 'income_bank_account_required';
  END IF;

  v_new_status := public.income_status_after_deposit(
    v_income.income_type_id,
    v_income.category_id,
    v_income.bank_account_id
  );

  UPDATE public.income_transactions
  SET
    deposit_confirmed_at = now(),
    deposit_confirmed_by = v_actor,
    deposit_source = v_source,
    status = v_new_status,
    updated_at = now()
  WHERE id = v_income.id;

  PERFORM public.credit_income_bank_deposit(
    v_income.id,
    v_income.bank_account_id,
    v_income.organization_id,
    v_income.amount,
    COALESCE(v_actor, v_income.created_by),
    'Income deposit confirmed'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'income_id', v_income.id,
    'status', v_new_status
  );
END;
$$;


ALTER FUNCTION "public"."confirm_income_bank_deposit"("p_income_id" "uuid", "p_deposit_source" "text", "p_confirmed_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_mfa_recovery_code"("p_code_hash" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT id INTO v_id
  FROM public.user_mfa_recovery_codes
  WHERE user_id = auth.uid()
    AND code_hash = p_code_hash
    AND used_at IS NULL
  LIMIT 1
  FOR UPDATE;

  IF v_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.user_mfa_recovery_codes
  SET used_at = now()
  WHERE id = v_id;

  INSERT INTO public.auth_security_events (user_id, event, metadata)
  VALUES (auth.uid(), 'mfa_recovery_used', '{}'::jsonb);

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."consume_mfa_recovery_code"("p_code_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."content_brief_demote_approval"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.social_media_plans AS plan
  SET status = 'Need Review',
      approved = false,
      completion_date = NULL
  WHERE plan.id = p_plan_id
    AND plan.status IS DISTINCT FROM 'Request Revision'
    AND (COALESCE(plan.approved, false) OR plan.status = 'Approved');
END;
$$;


ALTER FUNCTION "public"."content_brief_demote_approval"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."content_brief_edit_access"("p_plan_id" "uuid") RETURNS TABLE("storyboard" boolean, "concept" boolean, "caption" boolean, "link" boolean)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard', auth.uid()),
    public.can_edit_content_brief_field(p_plan_id, 'brief_concept', auth.uid()),
    public.can_edit_content_brief_field(p_plan_id, 'brief_caption', auth.uid()),
    public.can_edit_content_brief_field(p_plan_id, 'brief_link', auth.uid());
$$;


ALTER FUNCTION "public"."content_brief_edit_access"("p_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."content_brief_edit_access"("p_plan_id" "uuid") IS 'The signed-in account''s edit rights for storyboard, concept, caption, and link.';



CREATE OR REPLACE FUNCTION "public"."content_brief_revision_locked"("p_plan_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_status text;
  v_production_approved boolean;
  v_production_status text;
  v_post_link text;
BEGIN
  IF p_plan_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT plan.organization_id,
         plan.status,
         plan.production_approved,
         plan.production_status,
         plan.post_link::text
    INTO v_org, v_status, v_production_approved, v_production_status, v_post_link
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF auth.uid() IS NOT NULL THEN
    IF v_org NOT IN (SELECT public.user_organization_ids()) THEN
      RAISE EXCEPTION 'Not allowed'
        USING ERRCODE = '42501';
    END IF;
  ELSIF NOT public.is_service_session() THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  IF v_status = 'Request Revision' THEN
    RETURN false;
  END IF;

  IF COALESCE(v_production_approved, false) OR v_production_status = 'Approved' THEN
    RETURN true;
  END IF;

  IF COALESCE(v_post_link, 'null') NOT IN ('null', '[]', '{}', '""')
     AND NULLIF(btrim(v_post_link), '') IS NOT NULL THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.social_media_scheduled_posts AS scheduled
    WHERE scheduled.social_media_plan_id = p_plan_id
      AND scheduled.status IN ('pending', 'publishing', 'published')
  );
END;
$$;


ALTER FUNCTION "public"."content_brief_revision_locked"("p_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."content_brief_revision_locked"("p_plan_id" "uuid") IS 'True when brief content cannot change until the brief status is Request Revision.';



CREATE OR REPLACE FUNCTION "public"."content_brief_snapshot"("p_plan_id" "uuid", "p_actor" "uuid", "p_source" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_brief text;
  v_concept text;
  v_caption text;
  v_link text;
  v_hash text;
  v_last_hash text;
  v_next integer;
  v_id uuid;
BEGIN
  IF p_plan_id IS NULL OR p_source NOT IN ('office', 'mcp') THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  SELECT plan.organization_id, plan.brief
    INTO v_org, v_brief
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT audience.description
    INTO v_concept
  FROM public.brief_target_audiences AS audience
  WHERE audience.social_media_plan_id = p_plan_id;

  SELECT caption.content
    INTO v_caption
  FROM public.brief_captions AS caption
  WHERE caption.social_media_plan_id = p_plan_id;

  SELECT link_ref.content
    INTO v_link
  FROM public.brief_link_references AS link_ref
  WHERE link_ref.social_media_plan_id = p_plan_id;

  v_hash := md5(
    CASE WHEN v_brief IS NULL THEN 'N' ELSE 'T' || v_brief END
    || E'\x1f' ||
    CASE WHEN v_concept IS NULL THEN 'N' ELSE 'T' || v_concept END
    || E'\x1f' ||
    CASE WHEN v_caption IS NULL THEN 'N' ELSE 'T' || v_caption END
    || E'\x1f' ||
    CASE WHEN v_link IS NULL THEN 'N' ELSE 'T' || v_link END
  );

  SELECT versions.content_hash
    INTO v_last_hash
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id
  ORDER BY versions.version_no DESC
  LIMIT 1;

  IF v_last_hash IS NOT NULL AND v_last_hash = v_hash THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(MAX(versions.version_no), 0) + 1
    INTO v_next
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  INSERT INTO public.content_brief_versions (
    organization_id,
    social_media_plan_id,
    version_no,
    brief,
    concept,
    caption,
    link_reference,
    content_hash,
    created_by,
    source
  ) VALUES (
    v_org,
    p_plan_id,
    v_next,
    v_brief,
    v_concept,
    v_caption,
    v_link,
    v_hash,
    p_actor,
    p_source
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."content_brief_snapshot"("p_plan_id" "uuid", "p_actor" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."conversations_snapshot_last_handler_on_resolve"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.lead_status_id IS NOT DISTINCT FROM OLD.lead_status_id THEN
    RETURN NEW;
  END IF;

  IF public.lead_status_is_resolved_or_expired_visibility(NEW.lead_status_id)
     AND NOT public.lead_status_is_resolved_or_expired_visibility(OLD.lead_status_id) THEN
    NEW.last_handling_assignee_id := COALESCE(OLD.assignee_id, NEW.last_handling_assignee_id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."conversations_snapshot_last_handler_on_resolve"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_active_ai_employees_for_org"("p_org_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.employees e
  LEFT JOIN public.employee_statuses es ON es.id = e.employee_status_id
  WHERE e.organization_id = p_org_id
    AND COALESCE(e.pending_removal, false) = false
    AND COALESCE(e.is_ai, false) = true
    AND lower(trim(COALESCE(es.name, 'active'))) IN ('active', 'probation');
$$;


ALTER FUNCTION "public"."count_active_ai_employees_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_active_employees_for_org"("p_org_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.employees e
  LEFT JOIN public.employee_statuses es ON es.id = e.employee_status_id
  WHERE e.organization_id = p_org_id
    AND COALESCE(e.pending_removal, false) = false
    AND COALESCE(e.is_ai, false) = false
    AND lower(trim(COALESCE(es.name, 'active'))) IN ('active', 'probation');
$$;


