CREATE OR REPLACE FUNCTION "public"."count_roster_eligible_employees"("p_org_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE((
    SELECT count(*)::integer
    FROM public.employees e
    LEFT JOIN public.employee_statuses es ON es.id = e.employee_status_id
    WHERE e.organization_id = p_org_id
      AND e.user_id IS NOT NULL
      AND COALESCE(e.pending_removal, false) = false
      AND NOT (
        lower(trim(COALESCE(e.status, ''))) IN (
          'inactive', 'terminated', 'resigned', 'resign', 'resignation',
          'pending removal', 'pendingremoval'
        )
        OR lower(trim(COALESCE(es.name, ''))) IN (
          'inactive', 'terminated', 'resigned', 'resign', 'resignation',
          'pending removal', 'pendingremoval'
        )
        OR lower(trim(COALESCE(e.status, ''))) LIKE '%resign%'
        OR lower(trim(COALESCE(e.status, ''))) LIKE '%terminat%'
        OR lower(trim(COALESCE(es.name, ''))) LIKE '%resign%'
        OR lower(trim(COALESCE(es.name, ''))) LIKE '%terminat%'
      )
  ), 0);
$$;


ALTER FUNCTION "public"."count_roster_eligible_employees"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_template_followups_since_reset"("p_conv_id" "uuid", "p_lead_id" "uuid", "p_reset_at" timestamp with time zone) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COUNT(*)::integer
  FROM public.whatsapp_template_followups wtf
  WHERE wtf.send_status = 'sent'
    AND (
      (p_conv_id IS NOT NULL AND wtf.whatsapp_conversation_id = p_conv_id)
      OR (p_lead_id IS NOT NULL AND wtf.lead_id = p_lead_id)
    )
    AND (p_reset_at IS NULL OR wtf.created_at > p_reset_at);
$$;


ALTER FUNCTION "public"."count_template_followups_since_reset"("p_conv_id" "uuid", "p_lead_id" "uuid", "p_reset_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bank_transfer"("p_from_bank_account_id" "uuid", "p_to_bank_account_id" "uuid", "p_amount" numeric, "p_fee" numeric DEFAULT 0, "p_note" "text" DEFAULT NULL::"text", "p_transaction_date" "date" DEFAULT ((CURRENT_DATE AT TIME ZONE 'UTC'::"text"))::"date") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org_id uuid;
  v_from RECORD;
  v_to RECORD;
  v_type_id uuid;
  v_cat_id uuid;
  v_from_balance NUMERIC(15, 2);
  v_to_balance NUMERIC(15, 2);
  v_from_ledger NUMERIC(15, 2);
  v_to_ledger NUMERIC(15, 2);
  v_from_before NUMERIC(15, 2);
  v_to_before NUMERIC(15, 2);
  v_total_out NUMERIC(15, 2);
  v_expense_id uuid;
  v_journal_id uuid;
  v_to_label text;
  v_expense_name text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_from_bank_account_id = p_to_bank_account_id THEN
    RAISE EXCEPTION 'SAME_ACCOUNT';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'INVALID_AMOUNT';
  END IF;

  IF p_fee IS NULL OR p_fee < 0 THEN
    RAISE EXCEPTION 'INVALID_FEE';
  END IF;

  v_total_out := p_amount + p_fee;

  SELECT p.active_organization_id INTO v_org_id
  FROM public.profiles p
  WHERE p.user_id = v_uid
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No active organization';
  END IF;

  SELECT ba.* INTO v_from
  FROM public.bank_accounts ba
  WHERE ba.id = p_from_bank_account_id
    AND ba.organization_id = v_org_id;

  IF NOT FOUND OR v_from.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'INVALID_SOURCE_ACCOUNT';
  END IF;

  SELECT ba.* INTO v_to
  FROM public.bank_accounts ba
  WHERE ba.id = p_to_bank_account_id
    AND ba.organization_id = v_org_id;

  IF NOT FOUND OR v_to.is_active IS NOT TRUE THEN
    RAISE EXCEPTION 'INVALID_DESTINATION_ACCOUNT';
  END IF;

  IF p_fee > 0 THEN
    SELECT et.id INTO v_type_id
    FROM public.expense_types et
    WHERE et.organization_id IS NULL
      AND lower(trim(et.name)) = lower(trim('Internal bank transfer'))
    LIMIT 1;

    IF v_type_id IS NULL THEN
      RAISE EXCEPTION 'Internal transfer expense type not configured';
    END IF;

    SELECT ec.id INTO v_cat_id
    FROM public.expense_categories ec
    WHERE ec.organization_id IS NULL
      AND ec.expense_type_id = v_type_id
      AND lower(trim(ec.name)) = lower(trim('Internal bank transfer'))
    LIMIT 1;

    IF v_cat_id IS NULL THEN
      RAISE EXCEPTION 'Internal transfer expense category not configured';
    END IF;
  END IF;

  SELECT b.balance INTO v_from_balance
  FROM public.bank_account_balances b
  WHERE b.bank_account_id = p_from_bank_account_id
    AND b.organization_id = v_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_from_balance := public._computed_bank_balance(p_from_bank_account_id, v_org_id);
    INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
    VALUES (p_from_bank_account_id, v_org_id, v_from_balance);
    SELECT b.balance INTO v_from_balance
    FROM public.bank_account_balances b
    WHERE b.bank_account_id = p_from_bank_account_id
      AND b.organization_id = v_org_id
    FOR UPDATE;
  ELSE
    v_from_ledger := public._computed_bank_balance(p_from_bank_account_id, v_org_id);
    IF v_from_balance IS DISTINCT FROM v_from_ledger THEN
      UPDATE public.bank_account_balances
      SET balance = v_from_ledger,
          updated_at = NOW()
      WHERE bank_account_id = p_from_bank_account_id
        AND organization_id = v_org_id;
      v_from_balance := v_from_ledger;
    END IF;
  END IF;

  v_from_before := v_from_balance;
  IF v_from_before < v_total_out THEN
    RAISE EXCEPTION 'INSUFFICIENT_FUNDS';
  END IF;

  SELECT b.balance INTO v_to_balance
  FROM public.bank_account_balances b
  WHERE b.bank_account_id = p_to_bank_account_id
    AND b.organization_id = v_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_to_balance := public._computed_bank_balance(p_to_bank_account_id, v_org_id);
    INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
    VALUES (p_to_bank_account_id, v_org_id, v_to_balance);
    SELECT b.balance INTO v_to_balance
    FROM public.bank_account_balances b
    WHERE b.bank_account_id = p_to_bank_account_id
      AND b.organization_id = v_org_id
    FOR UPDATE;
  ELSE
    v_to_ledger := public._computed_bank_balance(p_to_bank_account_id, v_org_id);
    IF v_to_balance IS DISTINCT FROM v_to_ledger THEN
      UPDATE public.bank_account_balances
      SET balance = v_to_ledger,
          updated_at = NOW()
      WHERE bank_account_id = p_to_bank_account_id
        AND organization_id = v_org_id;
      v_to_balance := v_to_ledger;
    END IF;
  END IF;

  v_to_before := v_to_balance;

  v_to_label := coalesce(v_to.name, '') || coalesce(' / ' || v_to.bank_name, '');
  v_expense_id := NULL;

  IF p_fee > 0 THEN
    v_expense_name := 'Bank transfer admin fee (to: ' || v_to_label || ')';

    INSERT INTO public.expenses (
      organization_id,
      expense_name,
      amount,
      expense_type,
      expense_type_id,
      category,
      expense_category_id,
      withdrawal_from_balance,
      bank_account_id,
      create_date,
      is_recurring,
      description,
      created_by,
      status
    ) VALUES (
      v_org_id,
      v_expense_name,
      p_fee,
      'Internal bank transfer',
      v_type_id,
      'Internal bank transfer',
      v_cat_id,
      NULL,
      p_from_bank_account_id,
      p_transaction_date,
      false,
      CASE
        WHEN p_note IS NOT NULL AND length(trim(p_note)) > 0
        THEN 'Internal transfer fee. Principal moved: ' || trim(p_amount::TEXT) || ' (not booked as expense). ' || trim(p_note)
        ELSE 'Internal transfer fee. Principal moved: ' || trim(p_amount::TEXT) || ' (not booked as expense).'
      END,
      v_uid,
      'active'
    )
    RETURNING id INTO v_expense_id;
  END IF;

  INSERT INTO public.bank_transfer_journals (
    organization_id,
    from_bank_account_id,
    to_bank_account_id,
    amount,
    fee,
    expense_id,
    income_transaction_id,
    note,
    created_by
  ) VALUES (
    v_org_id,
    p_from_bank_account_id,
    p_to_bank_account_id,
    p_amount,
    coalesce(p_fee, 0),
    v_expense_id,
    NULL,
    p_note,
    v_uid
  )
  RETURNING id INTO v_journal_id;

  UPDATE public.bank_account_balances
  SET balance = v_from_before - v_total_out,
      updated_at = NOW()
  WHERE bank_account_id = p_from_bank_account_id
    AND organization_id = v_org_id;

  IF p_fee > 0 AND v_expense_id IS NOT NULL THEN
    INSERT INTO public.bank_account_balance_history (
      bank_account_id,
      organization_id,
      transaction_type,
      transaction_id,
      amount,
      balance_before,
      balance_after,
      description,
      created_by
    ) VALUES (
      p_from_bank_account_id,
      v_org_id,
      'expense',
      v_expense_id,
      -p_fee,
      v_from_before,
      v_from_before - p_fee,
      'Bank transfer admin fee',
      v_uid
    );

    INSERT INTO public.bank_account_balance_history (
      bank_account_id,
      organization_id,
      transaction_type,
      transaction_id,
      amount,
      balance_before,
      balance_after,
      description,
      created_by
    ) VALUES (
      p_from_bank_account_id,
      v_org_id,
      'manual_adjustment',
      NULL,
      -p_amount,
      v_from_before - p_fee,
      v_from_before - v_total_out,
      'Bank transfer principal out',
      v_uid
    );
  ELSE
    INSERT INTO public.bank_account_balance_history (
      bank_account_id,
      organization_id,
      transaction_type,
      transaction_id,
      amount,
      balance_before,
      balance_after,
      description,
      created_by
    ) VALUES (
      p_from_bank_account_id,
      v_org_id,
      'manual_adjustment',
      NULL,
      -p_amount,
      v_from_before,
      v_from_before - v_total_out,
      'Bank transfer out (no fee)',
      v_uid
    );
  END IF;

  UPDATE public.bank_account_balances
  SET balance = v_to_before + p_amount,
      updated_at = NOW()
  WHERE bank_account_id = p_to_bank_account_id
    AND organization_id = v_org_id;

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    p_to_bank_account_id,
    v_org_id,
    'manual_adjustment',
    NULL,
    p_amount,
    v_to_before,
    v_to_before + p_amount,
    'Bank transfer in',
    v_uid
  );

  RETURN json_build_object(
    'journal_id', v_journal_id,
    'expense_id', v_expense_id,
    'income_transaction_id', NULL
  );
END;
$$;


ALTER FUNCTION "public"."create_bank_transfer"("p_from_bank_account_id" "uuid", "p_to_bank_account_id" "uuid", "p_amount" numeric, "p_fee" numeric, "p_note" "text", "p_transaction_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_catalog_purchase_order"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_supplier_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_lines" "jsonb", "p_create_and_fulfill" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po_id uuid;
  v_order_number text;
  v_total numeric(14, 2) := 0;
  v_line jsonb;
  v_qty numeric;
  v_unit_cost numeric;
  v_subtotal numeric;
  v_name text;
  v_actor text;
  v_product_id uuid;
  v_variant_id uuid;
  v_ingredient_id uuid;
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_po_mode text;
BEGIN
  v_po_mode := public.catalog_inventory_po_mode(p_organization_id);

  IF v_po_mode = 'advanced' THEN
    IF p_create_and_fulfill IS TRUE THEN
      RAISE EXCEPTION 'catalog_po_create_and_fulfill_disabled';
    END IF;
    IF NOT public.user_has_inventory_feature_access(p_organization_id, 'po_request') THEN
      RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
    END IF;
  ELSIF p_create_and_fulfill IS NOT TRUE THEN
    RAISE EXCEPTION 'catalog_po_create_and_fulfill_required';
  END IF;

  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;
  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'catalog_po_outlet_required';
  END IF;
  IF p_item_kind NOT IN ('product', 'ingredient') THEN
    RAISE EXCEPTION 'catalog_po_kind_invalid';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'catalog_po_lines_required';
  END IF;

  v_order_number := '#' || floor(extract(epoch from clock_timestamp()) * 1000)::bigint::text;
  v_actor := public.catalog_po_actor_name(p_organization_id);

  INSERT INTO public.catalog_purchase_orders (
    organization_id,
    outlet_id,
    supplier_id,
    item_kind,
    note,
    status,
    order_number,
    occurred_at,
    total_value,
    created_by
  ) VALUES (
    p_organization_id,
    p_outlet_id,
    p_supplier_id,
    p_item_kind,
    NULLIF(btrim(p_note), ''),
    'waiting',
    v_order_number,
    now(),
    0,
    auth.uid()
  )
  RETURNING id INTO v_po_id;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    v_unit_cost := COALESCE((v_line ->> 'unit_cost')::numeric, 0);
    v_name := COALESCE(NULLIF(btrim(v_line ->> 'name_snapshot'), ''), '—');
    v_product_id := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_variant_id := NULLIF(v_line ->> 'variant_id', '')::uuid;
    v_ingredient_id := NULLIF(v_line ->> 'ingredient_id', '')::uuid;

    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;

    v_subtotal := ROUND(v_qty * v_unit_cost, 2);
    v_total := v_total + v_subtotal;

    INSERT INTO public.catalog_purchase_order_lines (
      purchase_order_id,
      organization_id,
      product_id,
      variant_id,
      ingredient_id,
      qty,
      unit_cost,
      subtotal,
      name_snapshot
    ) VALUES (
      v_po_id,
      p_organization_id,
      CASE WHEN p_item_kind = 'product' THEN v_product_id ELSE NULL END,
      CASE WHEN p_item_kind = 'product' THEN v_variant_id ELSE NULL END,
      CASE WHEN p_item_kind = 'ingredient' THEN v_ingredient_id ELSE NULL END,
      v_qty,
      v_unit_cost,
      v_subtotal,
      v_name
    );
  END LOOP;

  IF v_total <= 0 THEN
    DELETE FROM public.catalog_purchase_orders WHERE id = v_po_id;
    RAISE EXCEPTION 'catalog_po_lines_required';
  END IF;

  UPDATE public.catalog_purchase_orders
  SET total_value = v_total
  WHERE id = v_po_id;

  INSERT INTO public.catalog_purchase_order_events (
    purchase_order_id,
    organization_id,
    event_type,
    actor_user_id,
    actor_name_snapshot,
    comment
  ) VALUES (
    v_po_id,
    p_organization_id,
    'created',
    auth.uid(),
    v_actor,
    NULLIF(btrim(p_note), '')
  );

  IF v_po_mode = 'advanced' THEN
    PERFORM public.sync_catalog_po_purchase_request(v_po_id);
  ELSE
    PERFORM public.fulfill_catalog_purchase_order(p_organization_id, v_po_id, NULL);
  END IF;

  SELECT * INTO v_po FROM public.catalog_purchase_orders WHERE id = v_po_id;
  RETURN to_jsonb(v_po);
END;
$$;


ALTER FUNCTION "public"."create_catalog_purchase_order"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_supplier_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_lines" "jsonb", "p_create_and_fulfill" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_catalog_stock_transfer"("p_organization_id" "uuid", "p_from_outlet_id" "uuid", "p_to_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer_id uuid; v_order_number text; v_line jsonb; v_qty numeric; v_name text; v_unit text;
  v_product_id uuid; v_variant_id uuid; v_ingredient_id uuid; v_line_id uuid;
  v_src_qty numeric; v_src_avg numeric; v_src_cogs boolean; v_resolved_variant uuid;
  v_from_ok boolean; v_to_ok boolean; v_has_line boolean := false;
  v_transfer public.catalog_stock_transfers%ROWTYPE; v_transfer_mode text; v_initial_status text;
BEGIN
  v_transfer_mode := public.catalog_inventory_transfer_mode(p_organization_id);
  IF v_transfer_mode = 'advanced' THEN
    IF NOT public.user_has_inventory_feature_access(p_organization_id, 'transfer_request') THEN RAISE EXCEPTION 'catalog_inventory_feature_forbidden'; END IF;
    v_initial_status := 'pending_approval';
  ELSE v_initial_status := 'completed'; END IF;
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN RAISE EXCEPTION 'catalog_transfer_forbidden'; END IF;
  IF p_from_outlet_id IS NULL OR p_to_outlet_id IS NULL THEN RAISE EXCEPTION 'catalog_transfer_outlet_required'; END IF;
  IF p_from_outlet_id = p_to_outlet_id THEN RAISE EXCEPTION 'catalog_transfer_same_outlet'; END IF;
  IF p_item_kind NOT IN ('product', 'ingredient') THEN RAISE EXCEPTION 'catalog_transfer_kind_invalid'; END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN RAISE EXCEPTION 'catalog_transfer_lines_required'; END IF;
  SELECT EXISTS (SELECT 1 FROM public.pos_outlets WHERE id = p_from_outlet_id AND organization_id = p_organization_id) INTO v_from_ok;
  SELECT EXISTS (SELECT 1 FROM public.pos_outlets WHERE id = p_to_outlet_id AND organization_id = p_organization_id) INTO v_to_ok;
  IF NOT v_from_ok OR NOT v_to_ok THEN RAISE EXCEPTION 'catalog_transfer_outlet_required'; END IF;
  v_order_number := '#' || floor(extract(epoch from clock_timestamp()) * 1000)::bigint::text;
  INSERT INTO public.catalog_stock_transfers (organization_id, from_outlet_id, to_outlet_id, item_kind, note, status, order_number, occurred_at, created_by, completed_at, completed_by)
  VALUES (p_organization_id, p_from_outlet_id, p_to_outlet_id, p_item_kind, NULLIF(btrim(p_note), ''), v_initial_status, v_order_number, now(), auth.uid(), CASE WHEN v_initial_status = 'completed' THEN now() ELSE NULL END, CASE WHEN v_initial_status = 'completed' THEN auth.uid() ELSE NULL END)
  RETURNING id INTO v_transfer_id;
  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0); v_name := COALESCE(NULLIF(btrim(v_line ->> 'name_snapshot'), ''), '—'); v_unit := NULLIF(btrim(v_line ->> 'unit_snapshot'), '');
    v_product_id := NULLIF(v_line ->> 'product_id', '')::uuid; v_variant_id := NULLIF(v_line ->> 'variant_id', '')::uuid; v_ingredient_id := NULLIF(v_line ->> 'ingredient_id', '')::uuid;
    IF v_qty <= 0 THEN CONTINUE; END IF;
    IF p_item_kind = 'product' THEN v_ingredient_id := NULL; IF v_product_id IS NULL THEN RAISE EXCEPTION 'catalog_transfer_lines_required'; END IF;
    ELSE v_product_id := NULL; v_variant_id := NULL; IF v_ingredient_id IS NULL THEN RAISE EXCEPTION 'catalog_transfer_lines_required'; END IF;
      IF v_unit IS NULL THEN SELECT NULLIF(btrim(i.unit_code), '') INTO v_unit FROM public.catalog_ingredients i WHERE i.id = v_ingredient_id; END IF; END IF;
    SELECT o_qty, o_avg_cost, o_track_cogs, o_variant_id INTO v_src_qty, v_src_avg, v_src_cogs, v_resolved_variant FROM public.catalog_transfer_read_source_stock(p_organization_id, p_from_outlet_id, p_item_kind, v_product_id, v_variant_id, v_ingredient_id);
    IF p_item_kind = 'product' THEN v_variant_id := v_resolved_variant; END IF;
    IF v_transfer_mode = 'simple' AND v_qty > v_src_qty THEN RAISE EXCEPTION 'catalog_stock_insufficient'; END IF;
    INSERT INTO public.catalog_stock_transfer_lines (transfer_id, organization_id, product_id, variant_id, ingredient_id, qty, unit_snapshot, name_snapshot, in_stock_from_snapshot)
    VALUES (v_transfer_id, p_organization_id, CASE WHEN p_item_kind = 'product' THEN v_product_id ELSE NULL END, CASE WHEN p_item_kind = 'product' THEN v_variant_id ELSE NULL END, CASE WHEN p_item_kind = 'ingredient' THEN v_ingredient_id ELSE NULL END, v_qty, v_unit, v_name, v_src_qty)
    RETURNING id INTO v_line_id;
    IF v_transfer_mode = 'simple' THEN
      PERFORM public.apply_catalog_stock_movement(p_organization_id, p_from_outlet_id, p_item_kind, v_product_id, v_variant_id, v_ingredient_id, 'transfer', -v_qty, 'inventory_transfer', v_transfer_id::text || ':' || v_line_id::text || ':from', NULLIF(btrim(p_note), ''));
      PERFORM public.catalog_transfer_ensure_dest_row(p_organization_id, p_to_outlet_id, p_item_kind, v_product_id, v_variant_id, v_ingredient_id, v_src_cogs);
      PERFORM public.catalog_po_update_avg_cost(p_organization_id, p_to_outlet_id, p_item_kind, v_product_id, v_variant_id, v_ingredient_id, v_qty, v_src_avg);
      PERFORM public.apply_catalog_stock_movement(p_organization_id, p_to_outlet_id, p_item_kind, v_product_id, v_variant_id, v_ingredient_id, 'transfer', v_qty, 'inventory_transfer', v_transfer_id::text || ':' || v_line_id::text || ':to', NULLIF(btrim(p_note), ''));
    END IF;
    v_has_line := true;
  END LOOP;
  IF NOT v_has_line THEN DELETE FROM public.catalog_stock_transfers WHERE id = v_transfer_id; RAISE EXCEPTION 'catalog_transfer_lines_required'; END IF;
  PERFORM public.catalog_transfer_insert_event(v_transfer_id, p_organization_id, 'created', p_note);
  SELECT * INTO v_transfer FROM public.catalog_stock_transfers WHERE id = v_transfer_id;
  RETURN to_jsonb(v_transfer);
END; $$;


ALTER FUNCTION "public"."create_catalog_stock_transfer"("p_organization_id" "uuid", "p_from_outlet_id" "uuid", "p_to_outlet_id" "uuid", "p_item_kind" "text", "p_note" "text", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_email_verification_token_on_signup"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text;
  v_expires timestamptz := now() + interval '24 hours';
BEGIN
  v_token := public.generate_unique_verification_otp();
  INSERT INTO public.email_verification_tokens (user_id, token, expires_at, email_verified)
  VALUES (NEW.id, v_token, v_expires, false);
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_email_verification_token_on_signup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_expense_from_brick_debt_line"("p_line_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line public.debt_statement_lines%ROWTYPE;
  v_debt public.debts%ROWTYPE;
  v_settings public.organization_brick_import_settings%ROWTYPE;
  v_category_name text;
  v_type_name text;
  v_expense_id uuid;
  v_created_by uuid;
BEGIN
  SELECT * INTO v_line FROM public.debt_statement_lines WHERE id = p_line_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'brick_debt_line_not_found';
  END IF;

  IF auth.role() <> 'service_role'
    AND NOT public.user_is_org_owner_or_admin(v_line.organization_id) THEN
    RAISE EXCEPTION 'brick_debt_line_forbidden';
  END IF;

  IF v_line.direction <> 'debit' THEN
    UPDATE public.debt_statement_lines
    SET import_status = 'skipped', import_error = 'not_a_debit', synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'not_a_debit');
  END IF;

  IF v_line.import_status = 'imported' THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'already_imported');
  END IF;

  SELECT * INTO v_debt FROM public.debts WHERE id = v_line.debt_id;
  IF NOT FOUND OR v_debt.debt_type <> 'Kartu Kredit' THEN
    RAISE EXCEPTION 'brick_debt_line_invalid_debt';
  END IF;

  IF COALESCE(v_debt.brick_auto_import, true) = false THEN
    UPDATE public.debt_statement_lines
    SET import_status = 'skipped', import_error = 'auto_import_disabled', synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'auto_import_disabled');
  END IF;

  IF v_debt.status <> 'active' THEN
    UPDATE public.debt_statement_lines
    SET import_status = 'skipped', import_error = 'debt_not_active', synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'debt_not_active');
  END IF;

  IF COALESCE(v_debt.available_limit, 0) < v_line.amount THEN
    UPDATE public.debt_statement_lines
    SET
      import_status = 'failed_insufficient_limit',
      import_error = 'available_limit_exceeded',
      synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', false, 'error', 'failed_insufficient_limit');
  END IF;

  SELECT * INTO v_settings
  FROM public.organization_brick_import_settings
  WHERE organization_id = v_line.organization_id;

  IF v_settings.default_expense_category_id IS NULL OR v_settings.default_expense_type_id IS NULL THEN
    UPDATE public.debt_statement_lines
    SET
      import_status = 'failed_missing_settings',
      import_error = 'missing_default_category_or_type',
      synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', false, 'error', 'failed_missing_settings');
  END IF;

  SELECT name INTO v_category_name
  FROM public.expense_categories
  WHERE id = v_settings.default_expense_category_id;

  SELECT name INTO v_type_name
  FROM public.expense_types
  WHERE id = v_settings.default_expense_type_id;

  IF v_category_name IS NULL OR v_type_name IS NULL THEN
    UPDATE public.debt_statement_lines
    SET
      import_status = 'failed_missing_settings',
      import_error = 'invalid_default_category_or_type',
      synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', false, 'error', 'failed_missing_settings');
  END IF;

  v_created_by := COALESCE(v_settings.import_created_by, v_debt.created_by);

  INSERT INTO public.expenses (
    organization_id,
    expense_name,
    amount,
    expense_type,
    category,
    create_date,
    description,
    status,
    created_by,
    expense_type_id,
    expense_category_id,
    withdrawal_from_balance,
    brick_debt_statement_line_id,
    exclude_from_reminder_bills,
    transaction_reference
  )
  VALUES (
    v_line.organization_id,
    COALESCE(NULLIF(trim(v_line.merchant_name), ''), NULLIF(trim(v_line.description), ''), 'Brick CC'),
    v_line.amount,
    v_type_name,
    v_category_name,
    (v_line.transaction_date AT TIME ZONE 'Asia/Jakarta')::date,
    COALESCE(v_line.description, v_line.merchant_name),
    'active',
    v_created_by,
    v_settings.default_expense_type_id,
    v_settings.default_expense_category_id,
    v_debt.id,
    p_line_id,
    true,
    v_line.external_id
  )
  RETURNING id INTO v_expense_id;

  UPDATE public.debt_statement_lines
  SET import_status = 'imported', import_error = NULL, synced_at = now()
  WHERE id = p_line_id;

  RETURN jsonb_build_object('ok', true, 'expense_id', v_expense_id);
EXCEPTION
  WHEN unique_violation THEN
    UPDATE public.debt_statement_lines
    SET import_status = 'imported', import_error = NULL, synced_at = now()
    WHERE id = p_line_id;
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'duplicate_expense');
END;
$$;


ALTER FUNCTION "public"."create_expense_from_brick_debt_line"("p_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."credit_income_bank_deposit"("p_income_id" "uuid", "p_bank_account_id" "uuid", "p_organization_id" "uuid", "p_amount" numeric, "p_created_by" "uuid", "p_description" "text" DEFAULT 'Income deposit confirmed'::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_balance_before numeric;
  v_balance_after numeric;
BEGIN
  IF p_bank_account_id IS NULL OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
  VALUES (p_bank_account_id, p_organization_id, 0)
  ON CONFLICT (bank_account_id) DO NOTHING;

  SELECT balance INTO v_balance_before
  FROM public.bank_account_balances
  WHERE bank_account_id = p_bank_account_id
  FOR UPDATE;

  v_balance_after := COALESCE(v_balance_before, 0) + p_amount;

  UPDATE public.bank_account_balances
  SET balance = v_balance_after, updated_at = now()
  WHERE bank_account_id = p_bank_account_id;

  INSERT INTO public.bank_account_balance_history (
    bank_account_id, organization_id, transaction_type, transaction_id,
    amount, balance_before, balance_after, description, created_by
  ) VALUES (
    p_bank_account_id,
    p_organization_id,
    'income',
    p_income_id,
    p_amount,
    COALESCE(v_balance_before, 0),
    v_balance_after,
    p_description,
    p_created_by
  );
END;
$$;


ALTER FUNCTION "public"."credit_income_bank_deposit"("p_income_id" "uuid", "p_bank_account_id" "uuid", "p_organization_id" "uuid", "p_amount" numeric, "p_created_by" "uuid", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."crm_assignee_segment_for_org"("p_organization_id" "uuid", "p_assignee_employee_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN p_assignee_employee_id IS NULL THEN 'unassigned'::text
    WHEN (
      SELECT e.user_id
      FROM public.employees e
      WHERE e.id = p_assignee_employee_id
      LIMIT 1
    ) IS NULL THEN 'unassigned'::text
    WHEN NOT EXISTS (
      SELECT 1
      FROM public.user_roles ur
      JOIN public.employees e ON e.id = p_assignee_employee_id AND e.user_id = ur.user_id
      WHERE ur.organization_id = p_organization_id
    ) THEN 'agent'::text
    ELSE (
      SELECT CASE
        WHEN lower(trim(cr.role)) IN ('owner', 'admin') THEN 'admin'::text
        WHEN lower(trim(cr.role)) IN ('hr', 'manager') THEN 'supervisor'::text
        WHEN lower(trim(cr.role)) IN ('employee', 'member') THEN 'agent'::text
        ELSE 'agent'::text
      END
      FROM (
        SELECT ur.role
        FROM public.user_roles ur
        JOIN public.employees e ON e.id = p_assignee_employee_id AND e.user_id = ur.user_id
        WHERE ur.organization_id = p_organization_id
        ORDER BY CASE lower(trim(ur.role))
          WHEN 'owner' THEN 1
          WHEN 'admin' THEN 2
          WHEN 'hr' THEN 3
          WHEN 'manager' THEN 4
          WHEN 'employee' THEN 5
          WHEN 'member' THEN 6
          ELSE 99
        END
        LIMIT 1
      ) cr
    )
  END;
$$;


ALTER FUNCTION "public"."crm_assignee_segment_for_org"("p_organization_id" "uuid", "p_assignee_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."crm_assignee_segment_for_org"("p_organization_id" "uuid", "p_assignee_employee_id" "uuid") IS 'CRM metric bucket for conversation assignee: admin (owner/admin), supervisor (hr/manager), agent (employee/member/none); unassigned if no assignee or employee has no user_id.';



CREATE OR REPLACE FUNCTION "public"."crm_customer_survey_summary"("p_organization_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ DECLARE v_min_rating smallint := 4; v_org_target numeric := 80; v_total bigint; v_promoters bigint; v_pct numeric; v_counts jsonb; v_by_assignee jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'forbidden'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.user_id = auth.uid() AND p.active_organization_id = p_organization_id) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT COALESCE(s.promoter_min_rating, 4), COALESCE(s.promoter_pct_target, 80) INTO v_min_rating, v_org_target FROM public.organization_customer_survey_settings s WHERE s.organization_id = p_organization_id; IF NOT FOUND THEN v_min_rating := 4; v_org_target := 80; END IF; SELECT count(*)::bigint INTO v_total FROM public.customer_survey_responses r WHERE r.organization_id = p_organization_id AND r.submitted_at >= p_from AND r.submitted_at < p_to; SELECT count(*)::bigint INTO v_promoters FROM public.customer_survey_responses r WHERE r.organization_id = p_organization_id AND r.submitted_at >= p_from AND r.submitted_at < p_to AND r.rating >= v_min_rating; v_pct := CASE WHEN v_total > 0 THEN round((100.0 * v_promoters / v_total)::numeric, 2) ELSE 0::numeric END; SELECT coalesce(jsonb_object_agg(rating::text, c), '{}'::jsonb) INTO v_counts FROM (SELECT r.rating, count(*)::bigint AS c FROM public.customer_survey_responses r WHERE r.organization_id = p_organization_id AND r.submitted_at >= p_from AND r.submitted_at < p_to GROUP BY r.rating) q; SELECT coalesce(jsonb_agg(row_to_json(t)), '[]'::jsonb) INTO v_by_assignee FROM (SELECT r.assignee_id, coalesce(nullif(trim(e.full_name), ''), e.email, r.assignee_id::text) AS assignee_name, count(*)::bigint AS response_count, count(*) FILTER (WHERE r.rating >= v_min_rating)::bigint AS promoter_count, CASE WHEN count(*) > 0 THEN round((100.0 * count(*) FILTER (WHERE r.rating >= v_min_rating) / count(*))::numeric, 2) ELSE 0::numeric END AS promoter_pct, coalesce(MAX(at.promoter_pct_target), v_org_target) AS target_promoter_pct, (count(at.assignee_id) > 0) AS has_assignee_override, jsonb_build_object('1', count(*) FILTER (WHERE r.rating = 1), '2', count(*) FILTER (WHERE r.rating = 2), '3', count(*) FILTER (WHERE r.rating = 3), '4', count(*) FILTER (WHERE r.rating = 4), '5', count(*) FILTER (WHERE r.rating = 5)) AS counts_by_rating FROM public.customer_survey_responses r LEFT JOIN public.employees e ON e.id = r.assignee_id LEFT JOIN public.organization_customer_survey_assignee_targets at ON at.organization_id = r.organization_id AND at.assignee_id = r.assignee_id WHERE r.organization_id = p_organization_id AND r.submitted_at >= p_from AND r.submitted_at < p_to GROUP BY r.assignee_id, e.full_name, e.email ORDER BY response_count DESC) t; RETURN jsonb_build_object('total_responses', v_total, 'promoter_count', v_promoters, 'promoter_pct', v_pct, 'promoter_min_rating', v_min_rating, 'org_promoter_pct_target', v_org_target, 'min_responses_for_status', 3, 'counts_by_rating', coalesce(v_counts, '{}'::jsonb), 'by_assignee', coalesce(v_by_assignee, '[]'::jsonb)); END; $$;


ALTER FUNCTION "public"."crm_customer_survey_summary"("p_organization_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."customer_survey_history"("p_conversation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_allowed boolean;
BEGIN
  IF p_conversation_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT c.organization_id
  INTO v_org_id
  FROM public.whatsapp_conversations c
  WHERE c.id = p_conversation_id;

  IF v_org_id IS NULL THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = auth.uid()
      AND p.active_organization_id = v_org_id
  )
  INTO v_allowed;

  IF NOT coalesce(v_allowed, false) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  RETURN coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', r.id,
          'rating', r.rating,
          'comment', r.comment,
          'submitted_at', r.submitted_at,
          'assignee_id', r.assignee_id,
          'assignee_name', coalesce(nullif(btrim(e.full_name), ''), nullif(btrim(e.email), ''))
        )
        ORDER BY r.submitted_at DESC
      )
      FROM public.customer_survey_responses r
      LEFT JOIN public.employees e ON e.id = r.assignee_id
      WHERE r.whatsapp_conversation_id = p_conversation_id
        AND r.organization_id = v_org_id
    ),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."customer_survey_history"("p_conversation_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."customer_survey_history"("p_conversation_id" "uuid") IS 'All survey responses for a WhatsApp conversation, newest first.';



CREATE OR REPLACE FUNCTION "public"."customer_survey_latest_by_conversations"("p_organization_id" "uuid", "p_conversation_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_allowed boolean;
BEGIN
  IF p_organization_id IS NULL OR p_conversation_ids IS NULL OR cardinality(p_conversation_ids) = 0 THEN
    RETURN '[]'::jsonb;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = auth.uid()
      AND p.active_organization_id = p_organization_id
  )
  INTO v_allowed;

  IF NOT coalesce(v_allowed, false) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  RETURN coalesce(
    (
      SELECT jsonb_agg(
        jsonb_build_object(
          'conversation_id', x.whatsapp_conversation_id,
          'rating', x.rating,
          'comment', x.comment,
          'submitted_at', x.submitted_at,
          'assignee_id', x.assignee_id,
          'assignee_name', coalesce(nullif(btrim(e.full_name), ''), nullif(btrim(e.email), ''))
        )
        ORDER BY x.submitted_at DESC
      )
      FROM (
        SELECT DISTINCT ON (r.whatsapp_conversation_id)
          r.whatsapp_conversation_id,
          r.rating,
          r.comment,
          r.submitted_at,
          r.assignee_id
        FROM public.customer_survey_responses r
        WHERE r.organization_id = p_organization_id
          AND r.whatsapp_conversation_id = ANY (p_conversation_ids)
        ORDER BY r.whatsapp_conversation_id, r.submitted_at DESC
      ) x
      LEFT JOIN public.employees e ON e.id = x.assignee_id
    ),
    '[]'::jsonb
  );
END;
$$;


ALTER FUNCTION "public"."customer_survey_latest_by_conversations"("p_organization_id" "uuid", "p_conversation_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."customer_survey_latest_by_conversations"("p_organization_id" "uuid", "p_conversation_ids" "uuid"[]) IS 'Latest customer_survey_responses per whatsapp_conversation_id for active org members.';



CREATE OR REPLACE FUNCTION "public"."daily_tasks_skip_touch_on_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Cascade deletes of steps/assignments must not UPDATE the task row being removed.
  PERFORM set_config('synckerja.skip_daily_task_touch', '1', true);
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."daily_tasks_skip_touch_on_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_bank_transfer_by_income_transaction"("p_income_transaction_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org_id uuid;
  j RECORD;
  v_from_before NUMERIC(15, 2);
  v_to_before NUMERIC(15, 2);
  v_total_out NUMERIC(15, 2);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT p.active_organization_id INTO v_org_id
  FROM public.profiles p
  WHERE p.user_id = v_uid
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No active organization';
  END IF;

  -- active_organization_id bisa diubah sendiri oleh user; pastikan benar anggota org itu.
  IF v_org_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'Not a member of active organization';
  END IF;

  SELECT * INTO j
  FROM public.bank_transfer_journals btj
  WHERE btj.income_transaction_id = p_income_transaction_id
    AND btj.organization_id = v_org_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NOT_BANK_TRANSFER_INCOME';
  END IF;

  v_total_out := j.amount + j.fee;

  SELECT b.balance INTO v_from_before
  FROM public.bank_account_balances b
  WHERE b.bank_account_id = j.from_bank_account_id
    AND b.organization_id = v_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'SOURCE_BALANCE_ROW_MISSING';
  END IF;

  SELECT b.balance INTO v_to_before
  FROM public.bank_account_balances b
  WHERE b.bank_account_id = j.to_bank_account_id
    AND b.organization_id = v_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'DEST_BALANCE_ROW_MISSING';
  END IF;

  IF v_to_before < j.amount THEN
    RAISE EXCEPTION 'INSUFFICIENT_DEST_TO_DELETE_TRANSFER';
  END IF;

  UPDATE public.bank_account_balances
  SET balance = v_from_before + v_total_out,
      updated_at = NOW()
  WHERE bank_account_id = j.from_bank_account_id
    AND organization_id = v_org_id;

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    j.from_bank_account_id,
    v_org_id,
    'manual_adjustment',
    NULL,
    v_total_out,
    v_from_before,
    v_from_before + v_total_out,
    'Revert bank transfer (delete paired income/expense)',
    v_uid
  );

  UPDATE public.bank_account_balances
  SET balance = v_to_before - j.amount,
      updated_at = NOW()
  WHERE bank_account_id = j.to_bank_account_id
    AND organization_id = v_org_id;

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    j.to_bank_account_id,
    v_org_id,
    'manual_adjustment',
    NULL,
    -j.amount,
    v_to_before,
    v_to_before - j.amount,
    'Revert bank transfer (remove credit to destination)',
    v_uid
  );

  DELETE FROM public.bank_transfer_journals
  WHERE id = j.id;

  DELETE FROM public.expenses
  WHERE id = j.expense_id;

  DELETE FROM public.income_transactions
  WHERE id = p_income_transaction_id;

  RETURN json_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."delete_bank_transfer_by_income_transaction"("p_income_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_bank_transfer_by_journal_id"("p_journal_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_org_id uuid;
  j RECORD;
  v_total_out NUMERIC(15, 2);
  v_from_ledger NUMERIC(15, 2);
  v_to_ledger NUMERIC(15, 2);
  v_from_after NUMERIC(15, 2);
  v_to_after NUMERIC(15, 2);
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT p.active_organization_id INTO v_org_id
  FROM public.profiles p
  WHERE p.user_id = v_uid
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No active organization';
  END IF;

  SELECT * INTO j
  FROM public.bank_transfer_journals btj
  WHERE btj.id = p_journal_id
    AND btj.organization_id = v_org_id
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANK_TRANSFER_JOURNAL_NOT_FOUND';
  END IF;

  IF j.income_transaction_id IS NOT NULL THEN
    RAISE EXCEPTION 'LEGACY_TRANSFER_USE_INCOME_DELETE';
  END IF;

  v_total_out := j.amount + j.fee;

  v_to_ledger := public._computed_bank_balance(j.to_bank_account_id, v_org_id);
  v_from_ledger := public._computed_bank_balance(j.from_bank_account_id, v_org_id);

  IF v_to_ledger < j.amount THEN
    RAISE EXCEPTION 'INSUFFICIENT_DEST_TO_DELETE_TRANSFER';
  END IF;

  v_to_after := v_to_ledger - j.amount;
  v_from_after := v_from_ledger + v_total_out;

  INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
  VALUES (j.from_bank_account_id, v_org_id, v_from_after)
  ON CONFLICT (bank_account_id) DO UPDATE
  SET balance = EXCLUDED.balance,
      updated_at = NOW();

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    j.from_bank_account_id,
    v_org_id,
    'manual_adjustment',
    NULL,
    v_total_out,
    v_from_ledger,
    v_from_after,
    'Revert bank transfer (by journal)',
    v_uid
  );

  INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
  VALUES (j.to_bank_account_id, v_org_id, v_to_after)
  ON CONFLICT (bank_account_id) DO UPDATE
  SET balance = EXCLUDED.balance,
      updated_at = NOW();

  INSERT INTO public.bank_account_balance_history (
    bank_account_id,
    organization_id,
    transaction_type,
    transaction_id,
    amount,
    balance_before,
    balance_after,
    description,
    created_by
  ) VALUES (
    j.to_bank_account_id,
    v_org_id,
    'manual_adjustment',
    NULL,
    -j.amount,
    v_to_ledger,
    v_to_after,
    'Revert bank transfer credit (by journal)',
    v_uid
  );

  DELETE FROM public.bank_transfer_journals
  WHERE id = j.id;

  IF j.expense_id IS NOT NULL THEN
    DELETE FROM public.expenses
    WHERE id = j.expense_id;
  END IF;

  RETURN json_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."delete_bank_transfer_by_journal_id"("p_journal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_operational_email_recipient"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.operational_email_recipients;
BEGIN
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'id_required';
  END IF;

  SELECT * INTO v_row
  FROM public.operational_email_recipients r
  WHERE r.id = p_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_row.organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF v_row.status <> 'pending' THEN
    RAISE EXCEPTION 'cannot_delete_verified';
  END IF;

  DELETE FROM public.operational_email_recipients WHERE id = p_id;
END;
$$;


ALTER FUNCTION "public"."delete_operational_email_recipient"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_public_review_comment"("comment_id" "uuid", "token_param" "text", "commenter_display_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_name text;
BEGIN
  v_name := trim(commenter_display_name);
  IF v_name IS NULL OR v_name = '' THEN
    RAISE EXCEPTION 'commenter_display_name is required';
  END IF;

  SELECT social_media_plan_id INTO v_plan_id
  FROM public.public_review_tokens
  WHERE token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired review link';
  END IF;

  DELETE FROM public.link_comments AS lc
  WHERE lc.id = comment_id
    AND lc.social_media_plan_id = v_plan_id
    AND lc.created_by IS NULL
    AND lower(trim(COALESCE(lc.commenter_display_name, ''))) = lower(v_name);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Comment not found or you are not the author';
  END IF;

  RETURN TRUE;
END;
$$;


ALTER FUNCTION "public"."delete_public_review_comment"("comment_id" "uuid", "token_param" "text", "commenter_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."did_cross_inventory_alert_threshold"("p_prev" numeric, "p_next" numeric, "p_alert_enabled" boolean, "p_alert_at" numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_was text;
  v_now text;
BEGIN
  v_was := public.inventory_alert_status_from_stock(p_prev, p_alert_enabled, p_alert_at);
  v_now := public.inventory_alert_status_from_stock(p_next, p_alert_enabled, p_alert_at);
  IF v_now IS NULL THEN
    RETURN NULL;
  END IF;
  -- Fire only on transition into the status (out preferred over low)
  IF v_now = 'out' AND COALESCE(v_was, '') IS DISTINCT FROM 'out' THEN
    RETURN 'out';
  END IF;
  IF v_now = 'low' AND COALESCE(v_was, '') IS DISTINCT FROM 'low' THEN
    RETURN 'low';
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."did_cross_inventory_alert_threshold"("p_prev" numeric, "p_next" numeric, "p_alert_enabled" boolean, "p_alert_at" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disc_start_test"("p_recruitment_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_disc_test_id uuid;
  v_duration_minutes integer;
  v_candidate_test_id uuid;
  v_started_at timestamptz;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;

  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT t.id, t.duration_minutes
  INTO v_disc_test_id, v_duration_minutes
  FROM public.tests t
  WHERE t.type = 'disc'
    AND t.is_active = true
  ORDER BY t.updated_at DESC
  LIMIT 1;

  IF v_disc_test_id IS NULL THEN
    -- fallback to default id used by UI
    v_disc_test_id := 'a1000000-0000-4000-8000-000000000001'::uuid;
    v_duration_minutes := 10;
  END IF;

  v_started_at := now();

  INSERT INTO public.candidate_tests (
    candidate_profile_id,
    test_id,
    status,
    started_at,
    created_at,
    updated_at
  )
  VALUES (
    v_profile_id,
    v_disc_test_id,
    'in_progress',
    v_started_at,
    v_started_at,
    v_started_at
  )
  ON CONFLICT (candidate_profile_id, test_id)
  DO UPDATE SET
    status = 'in_progress',
    started_at = EXCLUDED.started_at,
    submitted_at = NULL,
    score_d = NULL,
    score_i = NULL,
    score_s = NULL,
    score_c = NULL,
    score_total = NULL,
    answers = NULL,
    updated_at = EXCLUDED.updated_at
  RETURNING id INTO v_candidate_test_id;

  RETURN jsonb_build_object(
    'candidate_test_id', v_candidate_test_id,
    'started_at', v_started_at,
    'duration_minutes', COALESCE(v_duration_minutes, 10)
  );
END;
$$;


ALTER FUNCTION "public"."disc_start_test"("p_recruitment_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disc_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_test_question_id" "uuid", "p_most_like_option_index" integer, "p_least_like_option_index" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_test_id uuid;
  v_candidate_profile_id uuid;
  v_answer jsonb;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL OR p_test_question_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;
  IF p_most_like_option_index NOT BETWEEN 1 AND 4 OR p_least_like_option_index NOT BETWEEN 1 AND 4 THEN
    RAISE EXCEPTION 'Pilihan jawaban tidak valid';
  END IF;
  IF p_most_like_option_index = p_least_like_option_index THEN
    RAISE EXCEPTION 'Pilihan P dan K tidak boleh sama';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;

  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id
  INTO v_candidate_profile_id, v_test_id
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;

  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  -- Ensure question belongs to the same test
  IF NOT EXISTS (
    SELECT 1
    FROM public.test_questions tq
    WHERE tq.id = p_test_question_id
      AND tq.test_id = v_test_id
  ) THEN
    RAISE EXCEPTION 'Soal tidak valid';
  END IF;

  v_answer := jsonb_build_object(
    'most', p_most_like_option_index,
    'least', p_least_like_option_index
  );

  UPDATE public.candidate_tests ct
  SET
    status = 'in_progress',
    answers = jsonb_set(
      COALESCE(ct.answers, '{}'::jsonb),
      ARRAY[p_test_question_id::text],
      v_answer,
      true
    ),
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;
END;
$$;


ALTER FUNCTION "public"."disc_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_test_question_id" "uuid", "p_most_like_option_index" integer, "p_least_like_option_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disc_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_candidate_profile_id uuid;
  v_test_id uuid;
  v_answers jsonb;
  v_score_d integer := 0;
  v_score_i integer := 0;
  v_score_s integer := 0;
  v_score_c integer := 0;
  r record;
  v_most_idx integer;
  v_least_idx integer;
  v_most_dim text;
  v_least_dim text;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;

  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id, ct.answers
  INTO v_candidate_profile_id, v_test_id, v_answers
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;
  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  v_answers := COALESCE(v_answers, '{}'::jsonb);

  FOR r IN
    SELECT tq.id,
           tq.option_1_dimension, tq.option_2_dimension, tq.option_3_dimension, tq.option_4_dimension
    FROM public.test_questions tq
    WHERE tq.test_id = v_test_id
    ORDER BY tq.question_order ASC
  LOOP
    v_most_idx := NULLIF((v_answers -> r.id::text ->> 'most')::int, 0);
    v_least_idx := NULLIF((v_answers -> r.id::text ->> 'least')::int, 0);

    IF v_most_idx IS NULL OR v_least_idx IS NULL THEN
      CONTINUE;
    END IF;

    v_most_dim := CASE v_most_idx
      WHEN 1 THEN r.option_1_dimension
      WHEN 2 THEN r.option_2_dimension
      WHEN 3 THEN r.option_3_dimension
      WHEN 4 THEN r.option_4_dimension
      ELSE NULL
    END;

    v_least_dim := CASE v_least_idx
      WHEN 1 THEN r.option_1_dimension
      WHEN 2 THEN r.option_2_dimension
      WHEN 3 THEN r.option_3_dimension
      WHEN 4 THEN r.option_4_dimension
      ELSE NULL
    END;

    IF v_most_dim = 'D' THEN v_score_d := v_score_d + 1;
    ELSIF v_most_dim = 'I' THEN v_score_i := v_score_i + 1;
    ELSIF v_most_dim = 'S' THEN v_score_s := v_score_s + 1;
    ELSIF v_most_dim = 'C' THEN v_score_c := v_score_c + 1;
    END IF;

    IF v_least_dim = 'D' THEN v_score_d := v_score_d - 1;
    ELSIF v_least_dim = 'I' THEN v_score_i := v_score_i - 1;
    ELSIF v_least_dim = 'S' THEN v_score_s := v_score_s - 1;
    ELSIF v_least_dim = 'C' THEN v_score_c := v_score_c - 1;
    END IF;
  END LOOP;

  UPDATE public.candidate_tests ct
  SET
    status = 'submitted',
    submitted_at = now(),
    score_d = v_score_d,
    score_i = v_score_i,
    score_s = v_score_s,
    score_c = v_score_c,
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;

  RETURN jsonb_build_object(
    'score_d', v_score_d,
    'score_i', v_score_i,
    'score_s', v_score_s,
    'score_c', v_score_c
  );
END;
$$;


ALTER FUNCTION "public"."disc_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_payroll_paid_announcement"("p_announcement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated integer;
BEGIN
  UPDATE public.employee_payroll_paid_announcements
  SET dismissed_at = now()
  WHERE id = p_announcement_id
    AND user_id = auth.uid()
    AND dismissed_at IS NULL;

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Announcement not found');
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


