CREATE OR REPLACE FUNCTION "public"."employees_generate_employee_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  seq int;
BEGIN
  IF TG_OP = 'INSERT' AND (NEW.employee_id IS NULL OR btrim(NEW.employee_id) = '') THEN
    IF NEW.organization_id IS NOT NULL THEN
      SELECT COALESCE(MAX((regexp_match(e.employee_id, '^EMP-([0-9]+)$'))[1]::int), 0) + 1
      INTO seq
      FROM public.employees e
      WHERE e.organization_id = NEW.organization_id;
      NEW.employee_id := 'EMP-' || lpad(seq::text, 5, '0');
    ELSE
      NEW.employee_id := 'EMP-' || upper(substring(replace(NEW.id::text, '-', ''), 1, 10));
    END IF;
  END IF;
  RETURN NEW;
END;
$_$;


ALTER FUNCTION "public"."employees_generate_employee_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."employees_sync_ai_reviewer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  IF COALESCE(NEW.is_ai, false) THEN
    PERFORM public.ai_employee_sync_reviewer_from_manager(NEW.id);
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.user_id IS DISTINCT FROM OLD.user_id
    OR NEW.is_ai IS DISTINCT FROM OLD.is_ai
    OR NEW.organization_id IS DISTINCT FROM OLD.organization_id
  ) THEN
    FOR r IN
      SELECT e.id FROM public.employees e
      WHERE e.manager_id = NEW.id AND e.is_ai IS TRUE AND e.id <> NEW.id
    LOOP
      PERFORM public.ai_employee_sync_reviewer_from_manager(r.id);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


