CREATE OR REPLACE FUNCTION "public"."enable_pos_addon_zero_charge"("p_org_id" "uuid", "p_paid_outlet_count" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing integer;
  v_outlet_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '28000';
  END IF;

  IF NOT public.user_has_org_role(p_org_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(os.pos_paid_outlet_count, 0)
  INTO v_existing
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_org_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization subscription not found';
  END IF;

  SELECT COUNT(*)::integer
  INTO v_outlet_count
  FROM public.pos_outlets po
  WHERE po.organization_id = p_org_id
    AND COALESCE(po.is_deleted, false) = false;

  IF v_outlet_count > (1 + v_existing) THEN
    RAISE EXCEPTION 'active outlets (%) exceed POS quota (%)', v_outlet_count, (1 + v_existing);
  END IF;

  -- p_paid_outlet_count sengaja diabaikan: jumlah outlet berbayar
  -- hanya boleh dinaikkan dari server setelah pembayaran terverifikasi
  UPDATE public.organization_subscriptions
  SET pos_addon_active = true,
      updated_at = now()
  WHERE organization_id = p_org_id;
END;
$$;


ALTER FUNCTION "public"."enable_pos_addon_zero_charge"("p_org_id" "uuid", "p_paid_outlet_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_ai_employee_built_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_job text;
BEGIN
  IF COALESCE(NEW.is_ai, false) IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.is_ai, false) IS TRUE THEN
    RETURN NEW;
  END IF;
  v_job := nullif(btrim(coalesce(current_setting('synckerja.ai_job_code', true), '')), '');
  IF v_job IS NULL THEN
    v_job := 'content_plan';
  END IF;
  IF v_job <> 'content_plan' THEN
    RAISE EXCEPTION 'Job desc karyawan AI belum tersedia. Pilih Content Plan.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_ai_employee_built_job"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_ai_employee_seat_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now boolean;
  v_was boolean;
  v_status text;
  v_old_status text;
  v_allow integer;
  v_used integer;
  v_has_subscription boolean;
BEGIN
  SELECT lower(trim(COALESCE(es.name, 'active')))
  INTO v_status
  FROM public.employee_statuses es
  WHERE es.id = NEW.employee_status_id;

  v_status := COALESCE(v_status, 'active');
  v_now := COALESCE(NEW.is_ai, false) = true
    AND COALESCE(NEW.pending_removal, false) = false
    AND v_status IN ('active', 'probation');

  v_was := false;
  IF TG_OP = 'UPDATE' THEN
    SELECT lower(trim(COALESCE(es.name, 'active')))
    INTO v_old_status
    FROM public.employee_statuses es
    WHERE es.id = OLD.employee_status_id;
    v_old_status := COALESCE(v_old_status, 'active');
    v_was := COALESCE(OLD.is_ai, false) = true
      AND COALESCE(OLD.pending_removal, false) = false
      AND v_old_status IN ('active', 'probation')
      AND OLD.organization_id IS NOT DISTINCT FROM NEW.organization_id;
  END IF;

  IF NOT v_now OR v_was THEN
    RETURN NEW;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.organization_subscriptions os
    WHERE os.organization_id = NEW.organization_id
  ) INTO v_has_subscription;

  IF NOT v_has_subscription THEN
    RETURN NEW;
  END IF;

  v_allow := public.ai_employee_seat_allowance(NEW.organization_id);
  v_used := public.count_active_ai_employees_for_org(NEW.organization_id);

  IF v_used + 1 > v_allow THEN
    RAISE EXCEPTION 'Kursi karyawan AI tidak cukup. Sisa kursi: %', GREATEST(v_allow - v_used, 0)
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_ai_employee_seat_limit"() OWNER TO "postgres";


