CREATE OR REPLACE FUNCTION "public"."enforce_employee_shift_no_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF COALESCE(NEW.is_active, true) IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.employee_shifts es
    WHERE es.employee_id = NEW.employee_id
      AND es.organization_id = NEW.organization_id
      AND COALESCE(es.is_active, true) IS TRUE
      AND es.id IS DISTINCT FROM NEW.id
      AND daterange(
            es.effective_from_date,
            COALESCE(es.effective_to_date, 'infinity'::date),
            '[]'
          ) && daterange(
            NEW.effective_from_date,
            COALESCE(NEW.effective_to_date, 'infinity'::date),
            '[]'
          )
  ) THEN
    RAISE EXCEPTION 'Employee shift assignment overlaps with an existing active assignment'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_employee_shift_no_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_gateway_payout_validation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_fp text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF (
      NEW.use_for_gateway_payout IS TRUE
      OR OLD.use_for_gateway_payout IS TRUE
    ) AND (
      coalesce(NEW.account_number, '') IS DISTINCT FROM coalesce(OLD.account_number, '')
      OR coalesce(NEW.account_holder, '') IS DISTINCT FROM coalesce(OLD.account_holder, '')
      OR coalesce(NEW.gateway_payout_bank_code, '') IS DISTINCT FROM coalesce(OLD.gateway_payout_bank_code, '')
    ) THEN
      NEW.gateway_payout_validation_status := 'stale';
      NEW.use_for_gateway_payout := false;
      NEW.gateway_payout_validated_at := NULL;
      NEW.gateway_payout_validation_fingerprint := NULL;
      NEW.gateway_payout_validated_holder := NULL;
      NEW.gateway_payout_validation_id := NULL;
      NEW.gateway_payout_is_normal_account := NULL;
    END IF;
  END IF;

  IF NEW.use_for_gateway_payout IS TRUE THEN
    IF NEW.gateway_payout_validation_status IS DISTINCT FROM 'match' THEN
      RAISE EXCEPTION 'gateway_payout_not_validated';
    END IF;

    v_fp := public.gateway_payout_bank_fingerprint(
      NEW.gateway_payout_bank_code,
      NEW.account_number,
      NEW.account_holder
    );

    IF NEW.gateway_payout_validation_fingerprint IS NULL
      OR NEW.gateway_payout_validation_fingerprint IS DISTINCT FROM v_fp THEN
      RAISE EXCEPTION 'gateway_payout_fingerprint_mismatch';
    END IF;

    IF NEW.gateway_payout_is_normal_account IS NOT TRUE THEN
      RAISE EXCEPTION 'gateway_payout_not_normal_account';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_gateway_payout_validation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_pos_outlet_quota"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cap integer;
  v_locked boolean := false;
  v_existing integer := 0;
  v_active integer := 0;
BEGIN
  SELECT
    coalesce(o.subscription_self_service_enabled, true) IS FALSE
    AND os.sales_outlet_quota IS NOT NULL
  INTO v_locked
  FROM public.organizations o
  JOIN public.organization_subscriptions os ON os.organization_id = o.id
  WHERE o.id = NEW.organization_id;

  v_locked := coalesce(v_locked, false);

  IF TG_OP = 'UPDATE'
     AND v_locked
     AND NOT public.sales_contract_apply_active()
     AND NEW.is_active IS DISTINCT FROM OLD.is_active THEN
    RAISE EXCEPTION 'outlet status waits for a signed contract' USING ERRCODE = '42501';
  END IF;

  v_cap := public.outlet_operating_cap(NEW.organization_id);

  IF coalesce(NEW.is_deleted, false) = false
     AND (TG_OP = 'INSERT' OR coalesce(OLD.is_deleted, false) = true) THEN
    SELECT count(*)::integer
    INTO v_existing
    FROM public.pos_outlets p
    WHERE p.organization_id = NEW.organization_id
      AND coalesce(p.is_deleted, false) = false
      AND p.id IS DISTINCT FROM NEW.id;

    IF v_existing >= v_cap THEN
      RAISE EXCEPTION 'outlet quota reached' USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.is_active AND coalesce(NEW.is_deleted, false) = false THEN
    IF NOT (TG_OP = 'UPDATE' AND OLD.is_active AND coalesce(OLD.is_deleted, false) = false) THEN
      SELECT count(*)::integer
      INTO v_active
      FROM public.pos_outlets p
      WHERE p.organization_id = NEW.organization_id
        AND coalesce(p.is_deleted, false) = false
        AND p.is_active
        AND p.id IS DISTINCT FROM NEW.id;

      IF v_active >= v_cap THEN
        RAISE EXCEPTION 'outlet quota reached' USING ERRCODE = '23514';
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enforce_pos_outlet_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_customer_survey_on_wa_resolve"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enabled boolean;
  v_assignee_id uuid;
BEGIN
  IF TG_OP <> 'UPDATE' THEN
    RETURN NEW;
  END IF;

  IF NEW.lead_status_id IS NOT DISTINCT FROM OLD.lead_status_id THEN
    RETURN NEW;
  END IF;

  IF coalesce(lower(trim(NEW.channel::text)), 'whatsapp') <> 'whatsapp' THEN
    RETURN NEW;
  END IF;

  v_assignee_id := COALESCE(NEW.assignee_id, OLD.assignee_id);

  IF v_assignee_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NOT public.lead_status_is_resolved_survey(NEW.lead_status_id) THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(s.is_enabled, false)
  INTO v_enabled
  FROM public.organization_customer_survey_settings s
  WHERE s.organization_id = NEW.organization_id;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.customer_survey_invitations (
    organization_id,
    whatsapp_conversation_id,
    phone_number_id,
    assignee_id,
    status,
    resolve_marked_at
  )
  VALUES (
    NEW.organization_id,
    NEW.id,
    NEW.phone_number_id,
    v_assignee_id,
    'pending_send',
    now()
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."enqueue_customer_survey_on_wa_resolve"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_customer_survey_on_wa_resolve"() IS 'Enqueue CES survey on WA resolve; assignee_id snapshot uses NEW or OLD assignee so live assignee can be cleared on same UPDATE.';



CREATE OR REPLACE FUNCTION "public"."enqueue_google_ads_conversion_pending"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_sales_activity_id" "uuid" DEFAULT NULL::"uuid", "p_payment_at" timestamp with time zone DEFAULT "now"(), "p_force_retry" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead public.leads%ROWTYPE;
  v_existing_status text;
  v_gclid text;
BEGIN
  IF p_organization_id IS NULL OR p_lead_id IS NULL THEN
    RETURN false;
  END IF;

  IF auth.uid() IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids()))
     AND current_setting('role', true) IS DISTINCT FROM 'service_role'
     AND current_user NOT IN ('postgres', 'supabase_admin') THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  SELECT * INTO v_lead
  FROM public.leads
  WHERE id = p_lead_id
    AND organization_id = p_organization_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  v_gclid := nullif(btrim(coalesce(v_lead.gclid, '')), '');
  IF v_gclid IS NULL THEN
    RETURN false;
  END IF;

  SELECT status INTO v_existing_status
  FROM public.google_ads_conversion_uploads
  WHERE lead_id = p_lead_id;

  IF v_existing_status = 'success' AND NOT p_force_retry THEN
    RETURN false;
  END IF;

  UPDATE public.leads
  SET payment_at = coalesce(payment_at, p_payment_at),
      updated_at = now()
  WHERE id = p_lead_id;

  INSERT INTO public.google_ads_conversion_uploads (
    organization_id,
    lead_id,
    sales_activity_id,
    gclid,
    status,
    skip_reason,
    error_message,
    google_ads_partial_failure,
    upload_attempt_count,
    updated_at
  )
  VALUES (
    p_organization_id,
    p_lead_id,
    p_sales_activity_id,
    v_gclid,
    'pending',
    NULL,
    NULL,
    NULL,
    CASE WHEN p_force_retry THEN 0 ELSE coalesce(
      (SELECT upload_attempt_count FROM public.google_ads_conversion_uploads WHERE lead_id = p_lead_id),
      0
    ) END,
    now()
  )
  ON CONFLICT (lead_id) DO UPDATE SET
    sales_activity_id = coalesce(excluded.sales_activity_id, google_ads_conversion_uploads.sales_activity_id),
    gclid = excluded.gclid,
    status = CASE
      WHEN google_ads_conversion_uploads.status = 'success' AND NOT p_force_retry
        THEN google_ads_conversion_uploads.status
      ELSE 'pending'
    END,
    skip_reason = CASE
      WHEN google_ads_conversion_uploads.status = 'success' AND NOT p_force_retry
        THEN google_ads_conversion_uploads.skip_reason
      ELSE NULL
    END,
    error_message = CASE
      WHEN google_ads_conversion_uploads.status = 'success' AND NOT p_force_retry
        THEN google_ads_conversion_uploads.error_message
      WHEN p_force_retry THEN NULL
      ELSE google_ads_conversion_uploads.error_message
    END,
    google_ads_partial_failure = CASE
      WHEN google_ads_conversion_uploads.status = 'success' AND NOT p_force_retry
        THEN google_ads_conversion_uploads.google_ads_partial_failure
      WHEN p_force_retry THEN NULL
      ELSE google_ads_conversion_uploads.google_ads_partial_failure
    END,
    upload_attempt_count = CASE
      WHEN google_ads_conversion_uploads.status = 'success' AND NOT p_force_retry
        THEN google_ads_conversion_uploads.upload_attempt_count
      WHEN p_force_retry THEN 0
      ELSE google_ads_conversion_uploads.upload_attempt_count
    END,
    updated_at = now()
  WHERE google_ads_conversion_uploads.status IS DISTINCT FROM 'success'
     OR p_force_retry;

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."enqueue_google_ads_conversion_pending"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_sales_activity_id" "uuid", "p_payment_at" timestamp with time zone, "p_force_retry" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."enqueue_google_ads_conversion_pending"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_sales_activity_id" "uuid", "p_payment_at" timestamp with time zone, "p_force_retry" boolean) IS 'Queue lead for deferred Google Ads upload after payment. Requires gclid. p_force_retry resets failed/pending for settings backfill.';



CREATE OR REPLACE FUNCTION "public"."enqueue_google_contacts_sync"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_reason" "text" DEFAULT 'update'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone text;
  v_reason text;
BEGIN
  IF p_organization_id IS NULL OR p_lead_id IS NULL THEN
    RETURN false;
  END IF;

  v_reason := CASE
    WHEN p_reason IN ('create', 'update', 'backfill') THEN p_reason
    ELSE 'update'
  END;

  IF NOT public.is_google_contacts_connected(p_organization_id) THEN
    RETURN false;
  END IF;

  SELECT nullif(btrim(coalesce(l.phone_number, '')), '') INTO v_phone
  FROM public.leads l
  WHERE l.id = p_lead_id
    AND l.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  IF v_phone IS NULL THEN
    SELECT nullif(btrim(coalesce(s.phone_number, '')), '') INTO v_phone
    FROM public.lead_submissions s
    WHERE s.lead_id = p_lead_id
    ORDER BY s.created_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_phone IS NULL THEN
    INSERT INTO public.lead_google_contact_links (
      organization_id, lead_id, sync_status, last_error, updated_at
    )
    VALUES (
      p_organization_id, p_lead_id, 'skipped', 'missing_phone', now()
    )
    ON CONFLICT (organization_id, lead_id) DO UPDATE SET
      sync_status = CASE
        WHEN lead_google_contact_links.google_resource_name IS NOT NULL
          THEN lead_google_contact_links.sync_status
        ELSE 'skipped'
      END,
      last_error = CASE
        WHEN lead_google_contact_links.google_resource_name IS NOT NULL
          THEN lead_google_contact_links.last_error
        ELSE 'missing_phone'
      END,
      updated_at = now();
    RETURN false;
  END IF;

  INSERT INTO public.lead_google_contact_links (
    organization_id, lead_id, sync_status, updated_at
  )
  VALUES (p_organization_id, p_lead_id, 'pending', now())
  ON CONFLICT (organization_id, lead_id) DO UPDATE SET
    sync_status = 'pending',
    last_error = NULL,
    updated_at = now();

  IF EXISTS (
    SELECT 1
    FROM public.google_contacts_sync_jobs j
    WHERE j.organization_id = p_organization_id
      AND j.lead_id = p_lead_id
      AND j.status IN ('pending', 'processing')
  ) THEN
    RETURN true;
  END IF;

  INSERT INTO public.google_contacts_sync_jobs (
    organization_id, lead_id, reason, status, run_after
  )
  VALUES (
    p_organization_id, p_lead_id, v_reason, 'pending', now()
  );

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."enqueue_google_contacts_sync"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_pos_receipt_feedback_invitation"("p_organization_id" "uuid", "p_sales_activity_id" "uuid", "p_pos_outlet_id" "uuid", "p_served_by_employee_id" "uuid", "p_customer_email" "text", "p_customer_phone" "text", "p_customer_name" "text", "p_share_via_email" boolean, "p_share_via_sms" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_email text := nullif(lower(trim(coalesce(p_customer_email, ''))), '');
  v_phone text := nullif(trim(coalesce(p_customer_phone, '')), '');
  v_email_status text := 'skipped';
  v_sms_status text := 'skipped';
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF p_organization_id IS NULL OR p_sales_activity_id IS NULL THEN
    RAISE EXCEPTION 'invalid_args';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sales_activities sa
    WHERE sa.id = p_sales_activity_id
      AND sa.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'sales_activity_not_found';
  END IF;

  IF p_share_via_email AND v_email IS NOT NULL THEN
    v_email_status := 'pending_send';
  END IF;

  IF p_share_via_sms AND v_phone IS NOT NULL THEN
    v_sms_status := 'pending_send';
  END IF;

  INSERT INTO public.pos_receipt_feedback_invitations (
    organization_id,
    sales_activity_id,
    pos_outlet_id,
    served_by_employee_id,
    customer_email,
    customer_phone,
    customer_name,
    share_via_email,
    share_via_sms,
    email_status,
    sms_status
  )
  VALUES (
    p_organization_id,
    p_sales_activity_id,
    p_pos_outlet_id,
    p_served_by_employee_id,
    v_email,
    v_phone,
    nullif(trim(coalesce(p_customer_name, '')), ''),
    COALESCE(p_share_via_email, false),
    COALESCE(p_share_via_sms, false),
    v_email_status,
    v_sms_status
  )
  ON CONFLICT (sales_activity_id) DO UPDATE SET
    customer_email = COALESCE(EXCLUDED.customer_email, public.pos_receipt_feedback_invitations.customer_email),
    customer_phone = COALESCE(EXCLUDED.customer_phone, public.pos_receipt_feedback_invitations.customer_phone),
    customer_name = COALESCE(EXCLUDED.customer_name, public.pos_receipt_feedback_invitations.customer_name),
    share_via_email = public.pos_receipt_feedback_invitations.share_via_email OR EXCLUDED.share_via_email,
    share_via_sms = public.pos_receipt_feedback_invitations.share_via_sms OR EXCLUDED.share_via_sms,
    email_status = CASE
      WHEN EXCLUDED.share_via_email AND EXCLUDED.customer_email IS NOT NULL THEN 'pending_send'
      ELSE public.pos_receipt_feedback_invitations.email_status
    END,
    sms_status = CASE
      WHEN EXCLUDED.share_via_sms AND EXCLUDED.customer_phone IS NOT NULL THEN 'pending_send'
      ELSE public.pos_receipt_feedback_invitations.sms_status
    END,
    updated_at = now()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."enqueue_pos_receipt_feedback_invitation"("p_organization_id" "uuid", "p_sales_activity_id" "uuid", "p_pos_outlet_id" "uuid", "p_served_by_employee_id" "uuid", "p_customer_email" "text", "p_customer_phone" "text", "p_customer_name" "text", "p_share_via_email" boolean, "p_share_via_sms" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pos_shift_email_dispatches" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "outlet_id" "uuid" NOT NULL,
    "language" "text" DEFAULT 'id'::"text" NOT NULL,
    "status" "text" DEFAULT 'pending_send'::"text" NOT NULL,
    "recipient_count" integer,
    "resend_message_id" "text",
    "error_message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    CONSTRAINT "pos_shift_email_dispatches_status_check" CHECK (("status" = ANY (ARRAY['pending_send'::"text", 'sent'::"text", 'send_failed'::"text", 'skipped_disabled'::"text"])))
);


ALTER TABLE "public"."pos_shift_email_dispatches" OWNER TO "postgres";


COMMENT ON TABLE "public"."pos_shift_email_dispatches" IS 'Queue + audit log for automatic shift recap emails after pos_end_shift.';



CREATE OR REPLACE FUNCTION "public"."enqueue_pos_shift_recap_email"("p_shift_id" "uuid", "p_language" "text" DEFAULT 'id'::"text") RETURNS "public"."pos_shift_email_dispatches"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shift public.pos_cashier_shifts;
  v_enabled boolean := true;
  v_lang text := COALESCE(NULLIF(btrim(p_language), ''), 'id');
  v_row public.pos_shift_email_dispatches;
BEGIN
  SELECT * INTO v_shift FROM public.pos_cashier_shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
  END IF;

  SELECT COALESCE(s.shift_recap_email_enabled, true) INTO v_enabled
  FROM public.operational_email_notification_settings s
  WHERE s.organization_id = v_shift.organization_id;

  IF NOT COALESCE(v_enabled, true) THEN
    INSERT INTO public.pos_shift_email_dispatches (
      shift_id,
      organization_id,
      outlet_id,
      language,
      status
    )
    VALUES (
      v_shift.id,
      v_shift.organization_id,
      v_shift.outlet_id,
      v_lang,
      'skipped_disabled'
    )
    ON CONFLICT (shift_id) DO UPDATE SET
      language = EXCLUDED.language
    RETURNING * INTO v_row;

    RETURN v_row;
  END IF;

  INSERT INTO public.pos_shift_email_dispatches (
    shift_id,
    organization_id,
    outlet_id,
    language,
    status
  )
  VALUES (
    v_shift.id,
    v_shift.organization_id,
    v_shift.outlet_id,
    v_lang,
    'pending_send'
  )
  ON CONFLICT (shift_id) DO UPDATE SET
    language = EXCLUDED.language
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."enqueue_pos_shift_recap_email"("p_shift_id" "uuid", "p_language" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_task_step_comment_push"("p_comment_id" "uuid", "p_event_type" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_comment public.task_step_comments%ROWTYPE;
  v_task_id uuid;
  v_step_title text;
  v_actor_name text;
  v_url text;
  v_body_preview text;
  v_author_user_id uuid;
  r_recipient uuid;
BEGIN
  SELECT * INTO v_comment
  FROM public.task_step_comments c
  WHERE c.id = p_comment_id
  LIMIT 1;

  IF NOT FOUND OR v_comment.is_deleted THEN
    RETURN;
  END IF;

  SELECT ts.task_id, COALESCE(NULLIF(trim(ts.title), ''), 'Task Step')
  INTO v_task_id, v_step_title
  FROM public.task_steps ts
  WHERE ts.id = v_comment.task_step_id
  LIMIT 1;

  v_actor_name := public.profile_display_name(v_comment.profile_id, v_comment.organization_id);
  v_url := public.build_task_step_comment_deeplink(v_task_id, v_comment.task_step_id);
  v_body_preview := left(regexp_replace(COALESCE(v_comment.body, ''), '\s+', ' ', 'g'), 120);
  v_author_user_id := public.profile_user_id(v_comment.profile_id);

  FOR r_recipient IN
    SELECT DISTINCT uid FROM (
      -- Step assignees
      SELECT public.employee_user_id(tsa.employee_id) AS uid
      FROM public.task_steps_assigned tsa
      WHERE tsa.task_step_id = v_comment.task_step_id
        AND public.employee_user_id(tsa.employee_id) IS NOT NULL
      UNION
      -- Step assigners
      SELECT public.employee_user_id(tsa.assigned_by) AS uid
      FROM public.task_steps_assigned tsa
      WHERE tsa.task_step_id = v_comment.task_step_id
        AND public.employee_user_id(tsa.assigned_by) IS NOT NULL
      UNION
      -- Task assignees
      SELECT public.employee_user_id(dta.employee_id) AS uid
      FROM public.daily_tasks_assigned dta
      WHERE dta.daily_task_id = v_task_id
        AND public.employee_user_id(dta.employee_id) IS NOT NULL
      UNION
      -- Task assigners
      SELECT public.employee_user_id(dta.assigned_by) AS uid
      FROM public.daily_tasks_assigned dta
      WHERE dta.daily_task_id = v_task_id
        AND public.employee_user_id(dta.assigned_by) IS NOT NULL
      UNION
      -- Task creator
      SELECT dt.created_by AS uid
      FROM public.daily_tasks dt
      WHERE dt.id = v_task_id
        AND dt.created_by IS NOT NULL
      UNION
      -- Mentioned profiles
      SELECT public.profile_user_id(mp) AS uid
      FROM unnest(COALESCE(v_comment.mentioned_profile_ids, '{}'::uuid[])) AS mp
      WHERE public.profile_user_id(mp) IS NOT NULL
      UNION
      -- Thread participants
      SELECT public.profile_user_id(c.profile_id) AS uid
      FROM public.task_step_comments c
      WHERE c.task_step_id = v_comment.task_step_id
        AND c.is_deleted = false
        AND public.profile_user_id(c.profile_id) IS NOT NULL
    ) recipients
    WHERE uid IS NOT NULL
      AND uid IS DISTINCT FROM v_author_user_id
  LOOP
    INSERT INTO public.task_step_comment_push_queue (
      organization_id,
      recipient_user_id,
      event_type,
      comment_id,
      daily_task_id,
      task_step_id,
      actor_profile_id,
      title,
      body_preview,
      url
    ) VALUES (
      v_comment.organization_id,
      r_recipient,
      p_event_type,
      v_comment.id,
      v_task_id,
      v_comment.task_step_id,
      v_comment.profile_id,
      v_step_title,
      v_body_preview,
      v_url
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."enqueue_task_step_comment_push"("p_comment_id" "uuid", "p_event_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_task_step_comment_reaction_push"("p_comment_id" "uuid", "p_actor_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_comment public.task_step_comments%ROWTYPE;
  v_task_id uuid;
  v_step_title text;
  v_actor_name text;
  v_url text;
  v_author_user_id uuid;
  r_recipient uuid;
BEGIN
  SELECT * INTO v_comment
  FROM public.task_step_comments c
  WHERE c.id = p_comment_id
  LIMIT 1;

  IF NOT FOUND OR v_comment.is_deleted THEN
    RETURN;
  END IF;

  SELECT ts.task_id, COALESCE(NULLIF(trim(ts.title), ''), 'Task Step')
  INTO v_task_id, v_step_title
  FROM public.task_steps ts
  WHERE ts.id = v_comment.task_step_id
  LIMIT 1;

  v_actor_name := public.profile_display_name(p_actor_profile_id, v_comment.organization_id);
  v_url := public.build_task_step_comment_deeplink(v_task_id, v_comment.task_step_id);
  v_author_user_id := public.profile_user_id(p_actor_profile_id);

  FOR r_recipient IN
    SELECT DISTINCT uid FROM (
      SELECT public.profile_user_id(v_comment.profile_id) AS uid
      UNION
      SELECT public.employee_user_id(tsa.employee_id) AS uid
      FROM public.task_steps_assigned tsa
      WHERE tsa.task_step_id = v_comment.task_step_id
      UNION
      SELECT public.profile_user_id(c.profile_id) AS uid
      FROM public.task_step_comments c
      WHERE c.task_step_id = v_comment.task_step_id
        AND c.is_deleted = false
    ) recipients
    WHERE uid IS NOT NULL
      AND uid IS DISTINCT FROM v_author_user_id
  LOOP
    INSERT INTO public.task_step_comment_push_queue (
      organization_id,
      recipient_user_id,
      event_type,
      comment_id,
      daily_task_id,
      task_step_id,
      actor_profile_id,
      title,
      body_preview,
      url
    ) VALUES (
      v_comment.organization_id,
      r_recipient,
      'reaction',
      v_comment.id,
      v_task_id,
      v_comment.task_step_id,
      p_actor_profile_id,
      v_step_title,
      v_actor_name || ' reacted',
      v_url
    );
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."enqueue_task_step_comment_reaction_push"("p_comment_id" "uuid", "p_actor_profile_id" "uuid") OWNER TO "postgres";


