CREATE OR REPLACE FUNCTION "public"."ensure_brief_storyboard_shots"("p_plan_id" "uuid", "p_row_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_index integer;
BEGIN
  IF p_plan_id IS NULL OR p_row_count IS NULL OR p_row_count < 0 OR p_row_count > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard') THEN
    RAISE EXCEPTION 'brief_field_forbidden' USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
  END IF;

  PERFORM 1
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
    INTO v_count
  FROM public.brief_storyboard_shots AS shot
  WHERE shot.social_media_plan_id = p_plan_id;

  IF v_count = 0 AND p_row_count > 0 THEN
    FOR v_index IN 0..(p_row_count - 1) LOOP
      INSERT INTO public.brief_storyboard_shots (social_media_plan_id, row_index)
      VALUES (p_plan_id, v_index);
    END LOOP;
  ELSIF v_count IS DISTINCT FROM p_row_count THEN
    RAISE EXCEPTION 'brief_shot_mismatch' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.brief_voice_clips AS clip
  SET shot_id = shot.id
  FROM public.brief_storyboard_shots AS shot
  WHERE clip.social_media_plan_id = p_plan_id
    AND shot.social_media_plan_id = p_plan_id
    AND clip.kind = 'vo'
    AND clip.shot_id IS NULL
    AND clip.row_index = shot.row_index;

  UPDATE public.brief_storyboard_images AS image
  SET shot_id = shot.id
  FROM public.brief_storyboard_shots AS shot
  WHERE image.social_media_plan_id = p_plan_id
    AND shot.social_media_plan_id = p_plan_id
    AND image.column_index = 1
    AND image.shot_id IS NULL
    AND image.row_index = shot.row_index;
END;
$$;


ALTER FUNCTION "public"."ensure_brief_storyboard_shots"("p_plan_id" "uuid", "p_row_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ensure_brief_storyboard_shots"("p_plan_id" "uuid", "p_row_count" integer) IS 'Create permanent storyboard row ids once, then attach clips and images that still use only row_index.';



CREATE OR REPLACE FUNCTION "public"."ensure_livechat_lead_statuses_for_org"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 PERFORM public.ensure_livechat_lead_statuses_for_org__impl(p_organization_id); END; $$;


ALTER FUNCTION "public"."ensure_livechat_lead_statuses_for_org"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_livechat_lead_statuses_for_org__impl"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_has_unread boolean;
  v_max_sort integer;
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.lead_statuses ls
    WHERE ls.organization_id = p_organization_id
      AND LOWER(TRIM(ls.name)) IN ('open', 'unread')
  ) INTO v_has_unread;

  IF NOT v_has_unread THEN
    INSERT INTO public.lead_statuses (
      id, name, description, color, is_active, sort_order, organization_id, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      'Open',
      'New inbound conversation',
      '#6B7280',
      TRUE,
      1,
      p_organization_id,
      NOW(),
      NOW()
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.lead_statuses ls
    WHERE ls.organization_id = p_organization_id
      AND LOWER(TRIM(ls.name)) IN ('in progress', 'on going', 'ongoing', 'in-progress')
  ) THEN
    INSERT INTO public.lead_statuses (
      id, name, description, color, is_active, sort_order, organization_id, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      'In Progress',
      'Agent has replied; conversation is active',
      '#F59E0B',
      TRUE,
      2,
      p_organization_id,
      NOW(),
      NOW()
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.lead_statuses ls
    WHERE ls.organization_id = p_organization_id
      AND LOWER(TRIM(ls.name)) = 'converted'
  ) THEN
    INSERT INTO public.lead_statuses (
      id, name, description, color, is_active, sort_order, organization_id, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      'Converted',
      'Lead converted to sale',
      '#10B981',
      TRUE,
      3,
      p_organization_id,
      NOW(),
      NOW()
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.lead_statuses ls
    WHERE ls.organization_id = p_organization_id
      AND LOWER(TRIM(ls.name)) = 'qualified'
  ) THEN
    INSERT INTO public.lead_statuses (
      id, name, description, color, is_active, sort_order, organization_id, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      'Qualified',
      'Qualified prospect',
      '#3B82F6',
      TRUE,
      4,
      p_organization_id,
      NOW(),
      NOW()
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.lead_statuses ls
    WHERE ls.organization_id = p_organization_id
      AND LOWER(TRIM(ls.name)) IN ('closed', 'resolve')
  ) THEN
    INSERT INTO public.lead_statuses (
      id, name, description, color, is_active, sort_order, organization_id, created_at, updated_at
    ) VALUES (
      gen_random_uuid(),
      'Closed',
      'Conversation resolved (Resolve in UI)',
      '#6B7280',
      TRUE,
      5,
      p_organization_id,
      NOW(),
      NOW()
    );
  END IF;
END;
$$;


