CREATE OR REPLACE FUNCTION "public"."ensure_open_threads_dm_conversation_cycle"("p_organization_id" "uuid", "p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE v_conv record; v_open_cycle_id uuid; v_first_out timestamptz;
BEGIN
  SELECT c.id, c.created_at INTO v_conv FROM public.threads_dm_conversations c WHERE c.id = p_conversation_id AND c.organization_id = p_organization_id;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT cy.id INTO v_open_cycle_id FROM public.threads_dm_conversation_cycles cy WHERE cy.conversation_id = p_conversation_id AND cy.resolved_at IS NULL ORDER BY cy.cycle_started_at DESC LIMIT 1;
  IF v_open_cycle_id IS NOT NULL THEN
    SELECT MIN(m.created_at) INTO v_first_out FROM public.threads_dm_messages m WHERE m.conversation_id = p_conversation_id AND m.direction = 'outbound' AND m.created_at >= (SELECT cycle_started_at FROM public.threads_dm_conversation_cycles WHERE id = v_open_cycle_id);
    IF v_first_out IS NOT NULL THEN UPDATE public.threads_dm_conversation_cycles SET first_response_at = COALESCE(first_response_at, v_first_out), updated_at = now() WHERE id = v_open_cycle_id AND first_response_at IS NULL; END IF;
    RETURN;
  END IF;
  INSERT INTO public.threads_dm_conversation_cycles (conversation_id, cycle_started_at) VALUES (p_conversation_id, COALESCE(v_conv.created_at, now()));
END; $$;


