CREATE OR REPLACE FUNCTION "public"."ensure_registration_profile"("p_user_id" "uuid", "p_email" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
DECLARE
  v_id uuid;
  v_email text;
BEGIN
  IF p_user_id IS NULL OR p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_input');
  END IF;

  SELECT u.id, u.email INTO v_id, v_email
  FROM auth.users u
  WHERE u.id = p_user_id AND lower(trim(u.email)) = lower(trim(p_email))
  LIMIT 1;

  IF v_id IS NULL THEN
    RETURN json_build_object('ok', false, 'error', 'no_matching_user');
  END IF;

  IF auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM v_id THEN
    RETURN json_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  INSERT INTO public.profiles (user_id, email)
  VALUES (v_id, COALESCE(v_email, ''))
  ON CONFLICT (user_id) DO UPDATE SET
    email = EXCLUDED.email,
    updated_at = now();

  RETURN json_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."ensure_registration_profile"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."estimate_travel_minutes"("p_organization_id" "uuid", "p_client_location_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rules record;
  v_hq record;
  v_client record;
  v_km numeric;
  v_speed numeric;
BEGIN
  IF p_organization_id IS NULL OR p_client_location_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT *
  INTO v_rules
  FROM public.load_attendance_rules(p_organization_id) r
  LIMIT 1;

  SELECT ol.*
  INTO v_client
  FROM public.office_locations ol
  WHERE ol.id = p_client_location_id
    AND ol.organization_id = p_organization_id;

  IF v_client.id IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_client.estimated_travel_minutes IS NOT NULL THEN
    RETURN v_client.estimated_travel_minutes;
  END IF;

  SELECT ol.*
  INTO v_hq
  FROM public.office_locations ol
  WHERE ol.organization_id = p_organization_id
    AND COALESCE(ol.is_active, true)
    AND COALESCE(ol.is_client_location, false) IS NOT TRUE
    AND ol.latitude IS NOT NULL
    AND ol.longitude IS NOT NULL
  ORDER BY ol.created_at ASC
  LIMIT 1;

  IF v_hq.id IS NULL OR v_client.latitude IS NULL OR v_client.longitude IS NULL THEN
    RETURN NULL;
  END IF;

  v_km := public._haversine_km(
    v_hq.latitude::double precision,
    v_hq.longitude::double precision,
    v_client.latitude::double precision,
    v_client.longitude::double precision
  );

  v_speed := GREATEST(COALESCE(v_rules.urban_travel_speed_kmh, 35), 1);
  RETURN GREATEST(0, round((v_km / v_speed) * 60.0)::integer);
END;
$$;


ALTER FUNCTION "public"."estimate_travel_minutes"("p_organization_id" "uuid", "p_client_location_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."facebook_conversation_cycles_bi_seed_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_assignee uuid;
BEGIN
  SELECT c.assignee_id INTO v_assignee
  FROM public.facebook_conversations c
  WHERE c.id = NEW.conversation_id;
  IF v_assignee IS NOT NULL AND NEW.first_assignee_in_cycle_at IS NULL THEN
    NEW.first_assignee_in_cycle_at := NEW.cycle_started_at;
  END IF;
  RETURN NEW;
END;
$$;


