CREATE OR REPLACE FUNCTION "public"."facebook_conversations_normalize_ticket_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.ticket_id := 'FB-' || UPPER(SUBSTRING(REPLACE(NEW.id::text, '-', ''), 1, 8));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."facebook_conversations_normalize_ticket_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."facebook_conversations_set_cycle_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.assignee_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.assignee_id IS NOT DISTINCT FROM NEW.assignee_id THEN
    RETURN NEW;
  END IF;
  UPDATE public.facebook_conversation_cycles cy
  SET first_assignee_in_cycle_at = now(), updated_at = now()
  WHERE cy.conversation_id = NEW.id
    AND cy.resolved_at IS NULL
    AND cy.first_assignee_in_cycle_at IS NULL;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."facebook_conversations_set_cycle_first_assignee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fetch_google_ads_pending_conversion_batch"("p_limit" integer DEFAULT 50) RETURNS TABLE("lead_id" "uuid", "organization_id" "uuid", "sales_activity_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    u.lead_id,
    u.organization_id,
    u.sales_activity_id
  FROM public.google_ads_conversion_uploads u
  INNER JOIN public.leads l ON l.id = u.lead_id
  WHERE u.status IN ('pending', 'failed')
    AND u.upload_attempt_count < 5
    AND nullif(btrim(coalesce(l.gclid, '')), '') IS NOT NULL
    AND l.payment_at IS NOT NULL
    AND l.payment_at <= now() - interval '5 hours'
  ORDER BY l.payment_at ASC
  LIMIT greatest(1, least(coalesce(p_limit, 50), 100));
$$;


ALTER FUNCTION "public"."fetch_google_ads_pending_conversion_batch"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fetch_google_ads_pending_conversion_batch"("p_limit" integer) IS 'Returns leads ready for Google Ads deferred UploadClickConversions (5h after payment).';



CREATE OR REPLACE FUNCTION "public"."finalize_payroll_run_thp_expense"("p_run_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_settings record;
  v_expense_id uuid;
  v_amount numeric := 0;
  v_employee_count integer := 0;
  v_unpaid integer := 0;
  v_has_xendit boolean := false;
  v_type_id uuid;
  v_type_name text;
  v_category_id uuid;
  v_category_name text;
  v_created_by uuid;
  v_reference text;
BEGIN
  SELECT pr.id, pr.organization_id, pr.status, pr.run_name, pr.paid_by
  INTO v_run
  FROM public.payroll_runs pr
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'run_not_found');
  END IF;

  IF v_run.status IS DISTINCT FROM 'paid' THEN
    RETURN jsonb_build_object('ok', false, 'skipped', true, 'reason', 'run_not_paid');
  END IF;

  SELECT id INTO v_expense_id
  FROM public.expenses
  WHERE payroll_run_id = p_run_id
  LIMIT 1;

  IF v_expense_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'expense_id', v_expense_id,
      'skipped', true,
      'reason', 'already_posted'
    );
  END IF;

  SELECT * INTO v_settings
  FROM public.organization_payroll_expense_settings
  WHERE organization_id = v_run.organization_id;

  IF NOT COALESCE(v_settings.is_enabled, false) THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'expense_post_disabled');
  END IF;

  SELECT COUNT(*)::integer
  INTO v_unpaid
  FROM public.employee_payroll_calculations c
  WHERE c.payroll_run_id = p_run_id
    AND c.payment_status IS DISTINCT FROM 'paid';

  IF v_unpaid > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'calculations_not_all_paid');
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.xendit_disbursements xd
    JOIN public.employee_payroll_calculations c ON c.id = xd.source_id
    WHERE xd.source_type = 'payroll_calculation'
      AND c.payroll_run_id = p_run_id
      AND xd.status = 'completed'
  ) INTO v_has_xendit;

  IF NOT v_has_xendit THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'xendit_disbursement_not_completed');
  END IF;

  SELECT COALESCE(SUM(c.take_home_pay), 0), COUNT(*)::integer
  INTO v_amount, v_employee_count
  FROM public.employee_payroll_calculations c
  WHERE c.payroll_run_id = p_run_id
    AND c.payment_status = 'paid';

  IF v_amount IS NULL OR v_amount <= 0 THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'reason', 'amount_zero', 'amount', 0);
  END IF;

  SELECT et.id, et.name
  INTO v_type_id, v_type_name
  FROM public.expense_types et
  WHERE lower(trim(et.name)) = lower(trim(COALESCE(v_settings.expense_type_name, 'Fixed Expenses')))
    AND COALESCE(et.is_active, true)
    AND (et.organization_id = v_run.organization_id OR et.organization_id IS NULL)
  ORDER BY CASE WHEN et.organization_id = v_run.organization_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_type_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'missing_expense_type',
      'expense_type_name', COALESCE(v_settings.expense_type_name, 'Fixed Expenses')
    );
  END IF;

  SELECT ec.id, ec.name
  INTO v_category_id, v_category_name
  FROM public.expense_categories ec
  WHERE lower(trim(ec.name)) = lower(trim(COALESCE(v_settings.expense_category_name, 'Gaji Karyawan Tetap')))
    AND COALESCE(ec.is_active, true)
    AND (ec.organization_id = v_run.organization_id OR ec.organization_id IS NULL)
    AND (ec.expense_type_id IS NULL OR ec.expense_type_id = v_type_id)
  ORDER BY CASE WHEN ec.organization_id = v_run.organization_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_category_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'missing_expense_category',
      'expense_category_name', COALESCE(v_settings.expense_category_name, 'Gaji Karyawan Tetap')
    );
  END IF;

  v_created_by := COALESCE(p_actor_user_id, v_run.paid_by);
  IF v_created_by IS NULL THEN
    SELECT ur.user_id INTO v_created_by
    FROM public.user_roles ur
    WHERE ur.organization_id = v_run.organization_id
      AND ur.role IN ('owner', 'admin')
    ORDER BY CASE ur.role WHEN 'owner' THEN 0 ELSE 1 END
    LIMIT 1;
  END IF;

  IF v_created_by IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'missing_created_by');
  END IF;

  v_reference := format('synckerja:%s:payroll_expense:%s', v_run.organization_id, p_run_id);

  INSERT INTO public.expenses (
    organization_id,
    expense_name,
    amount,
    expense_type,
    category,
    expense_type_id,
    expense_category_id,
    department,
    create_date,
    is_recurring,
    description,
    created_by,
    payroll_run_id,
    gateway_wallet_provider,
    bank_account_id,
    withdrawal_from_balance,
    transaction_reference,
    status
  )
  SELECT
    v_run.organization_id,
    format('Payroll %s — THP', v_run.run_name),
    v_amount,
    v_type_name,
    v_category_name,
    v_type_id,
    v_category_id,
    COALESCE(v_settings.department, 'Finance'),
    COALESCE(pp.pay_date::date, CURRENT_DATE),
    false,
    format('Auto-post dari payroll run · %s karyawan', v_employee_count),
    v_created_by,
    p_run_id,
    'xendit',
    NULL,
    NULL,
    v_reference,
    'active'
  FROM public.payroll_runs pr
  JOIN public.payroll_periods pp ON pp.id = pr.payroll_period_id
  WHERE pr.id = p_run_id
  RETURNING id INTO v_expense_id;

  RETURN jsonb_build_object(
    'ok', true,
    'expense_id', v_expense_id,
    'amount', v_amount,
    'employee_count', v_employee_count,
    'organization_id', v_run.organization_id
  );
END;
$$;


ALTER FUNCTION "public"."finalize_payroll_run_thp_expense"("p_run_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_payroll_run_thp_expense"("p_run_id" "uuid", "p_actor_user_id" "uuid") IS 'After payroll run finalized paid via Xendit: insert one THP expense row (idempotent per run).';



CREATE OR REPLACE FUNCTION "public"."finalize_purchase_request_gateway_payment"("p_purchase_request_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pr public.purchase_requests%ROWTYPE;
  v_type_name text;
  v_category_name text;
  v_expense_id uuid;
  v_has_xendit boolean := false;
  v_has_brick boolean := false;
BEGIN
  SELECT * INTO v_pr FROM public.purchase_requests WHERE id = p_purchase_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'purchase_request_not_found';
  END IF;

  IF v_pr.gateway_wallet_provider IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'skipped', true, 'reason', 'not_gateway_payment');
  END IF;

  IF v_pr.gateway_wallet_provider = 'xendit' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.xendit_disbursements xd
      WHERE xd.source_type = 'purchase_request'
        AND xd.source_id = v_pr.id
        AND xd.status = 'completed'
    ) INTO v_has_xendit;
    IF NOT v_has_xendit THEN
      RAISE EXCEPTION 'xendit_disbursement_not_completed';
    END IF;
  ELSIF v_pr.gateway_wallet_provider = 'brick' THEN
    SELECT EXISTS (
      SELECT 1 FROM public.brick_disbursements bd
      WHERE bd.source_type = 'purchase_request'
        AND bd.source_id = v_pr.id
        AND bd.status = 'completed'
    ) INTO v_has_brick;
    IF NOT v_has_brick THEN
      RAISE EXCEPTION 'brick_disbursement_not_completed';
    END IF;
  ELSE
    RAISE EXCEPTION 'unsupported_gateway_provider';
  END IF;

  SELECT id INTO v_expense_id
  FROM public.expenses
  WHERE purchase_request_id = v_pr.id
  LIMIT 1;

  IF v_expense_id IS NOT NULL THEN
  ELSE
    SELECT name INTO v_type_name FROM public.expense_types WHERE id = v_pr.expense_type_id;
    SELECT name INTO v_category_name FROM public.expense_categories WHERE id = v_pr.expense_category_id;

    IF v_type_name IS NULL OR v_category_name IS NULL THEN
      RAISE EXCEPTION 'purchase_request_missing_expense_classification';
    END IF;

    INSERT INTO public.expenses (
      organization_id,
      expense_name,
      amount,
      expense_type,
      category,
      expense_type_id,
      expense_category_id,
      department,
      create_date,
      is_recurring,
      description,
      created_by,
      purchase_request_id,
      gateway_wallet_provider,
      bank_account_id,
      withdrawal_from_balance
    ) VALUES (
      v_pr.organization_id,
      v_pr.request_title,
      v_pr.amount_idr,
      v_type_name,
      v_category_name,
      v_pr.expense_type_id,
      v_pr.expense_category_id,
      v_pr.department_name,
      COALESCE(v_pr.paid_at::date, CURRENT_DATE),
      COALESCE(v_pr.is_recurring, false),
      v_pr.description,
      COALESCE(v_pr.paid_by_user_id, v_pr.created_by),
      v_pr.id,
      v_pr.gateway_wallet_provider,
      NULL,
      NULL
    )
    RETURNING id INTO v_expense_id;
  END IF;

  UPDATE public.purchase_requests
  SET
    payment_status = 'paid',
    paid_at = COALESCE(paid_at, now()),
    updated_at = now()
  WHERE id = v_pr.id;

  RETURN jsonb_build_object(
    'ok', true,
    'expense_id', v_expense_id,
    'organization_id', v_pr.organization_id,
    'gateway_wallet_provider', v_pr.gateway_wallet_provider
  );
END;
$$;


ALTER FUNCTION "public"."finalize_purchase_request_gateway_payment"("p_purchase_request_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."finalize_purchase_request_gateway_payment"("p_purchase_request_id" "uuid") IS 'After Xendit/Brick disbursement completes: create expense (if missing), mark PR paid. Wallet balance synced via edge function.';



CREATE OR REPLACE FUNCTION "public"."finance_receipt_in_active_org"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid := public.storage_active_organization_id();
  v_top text;
BEGIN
  IF v_org IS NULL OR p_name IS NULL OR position('../' in p_name) > 0 THEN
    RETURN false;
  END IF;
  v_top := (storage.foldername(p_name))[1];
  IF v_top !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN false;
  END IF;
  RETURN v_top = v_org::text
    OR public.storage_user_in_active_org(v_top);
END;
$_$;


ALTER FUNCTION "public"."finance_receipt_in_active_org"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flush_operational_inventory_alert_tx"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_txid bigint := NEW.txid;
  v_org uuid;
  v_items jsonb := '[]'::jsonb;
  v_job_id uuid;
  r record;
  v_today date := public.inventory_alert_wib_today();
BEGIN
  SELECT organization_id INTO v_org
  FROM public.operational_inventory_alert_staging
  WHERE txid = v_txid
  LIMIT 1;

  IF v_org IS NULL THEN
    DELETE FROM public.operational_inventory_alert_tx_flush WHERE txid = v_txid;
    RETURN NULL;
  END IF;

  FOR r IN
    SELECT DISTINCT ON (s.outlet_id, s.ingredient_id, s.status)
      s.outlet_id,
      s.ingredient_id,
      s.ingredient_name,
      s.unit,
      s.outlet_name,
      s.status,
      s.in_stock,
      s.alert_at
    FROM public.operational_inventory_alert_staging s
    WHERE s.txid = v_txid
    ORDER BY s.outlet_id, s.ingredient_id, s.status, s.id DESC
  LOOP
    -- Skip if already alerted today for this key
    IF EXISTS (
      SELECT 1
      FROM public.operational_inventory_alert_cooldown c
      WHERE c.organization_id = v_org
        AND c.outlet_id = r.outlet_id
        AND c.ingredient_id = r.ingredient_id
        AND c.status = r.status
        AND c.sent_on_date = v_today
    ) THEN
      CONTINUE;
    END IF;

    v_items := v_items || jsonb_build_array(
      jsonb_build_object(
        'outletId', r.outlet_id,
        'outletName', r.outlet_name,
        'ingredientId', r.ingredient_id,
        'name', r.ingredient_name,
        'unit', r.unit,
        'status', r.status,
        'inStock', r.in_stock,
        'alertAt', r.alert_at
      )
    );

    INSERT INTO public.operational_inventory_alert_cooldown (
      organization_id, outlet_id, ingredient_id, status, sent_on_date
    )
    VALUES (v_org, r.outlet_id, r.ingredient_id, r.status, v_today)
    ON CONFLICT (organization_id, outlet_id, ingredient_id, status) DO UPDATE
      SET sent_on_date = EXCLUDED.sent_on_date,
          created_at = now();
  END LOOP;

  DELETE FROM public.operational_inventory_alert_staging WHERE txid = v_txid;
  DELETE FROM public.operational_inventory_alert_tx_flush WHERE txid = v_txid;

  IF jsonb_array_length(v_items) = 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.operational_inventory_alert_jobs (
    organization_id,
    payload,
    status
  )
  VALUES (
    v_org,
    jsonb_build_object('items', v_items),
    'pending'
  )
  RETURNING id INTO v_job_id;

  PERFORM public.invoke_dispatch_operational_inventory_alert(v_job_id);

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."flush_operational_inventory_alert_tx"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fulfill_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_line record;
  v_item_kind text;
  v_actor text;
  v_pr public.purchase_requests%ROWTYPE;
  v_po_mode text;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;

  v_po_mode := public.catalog_inventory_po_mode(p_organization_id);

  SELECT * INTO v_po
  FROM public.catalog_purchase_orders
  WHERE id = p_purchase_order_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found';
  END IF;
  IF v_po.status <> 'waiting' THEN
    RAISE EXCEPTION 'catalog_po_not_waiting';
  END IF;

  SELECT * INTO v_pr
  FROM public.purchase_requests
  WHERE catalog_purchase_order_id = v_po.id
  LIMIT 1;

  IF FOUND THEN
    IF v_po_mode = 'advanced'
      AND NOT public.user_has_inventory_feature_access(p_organization_id, 'po_fulfillment')
    THEN
      RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
    END IF;

    IF v_pr.status <> 'approved'
      OR NOT public.catalog_po_is_paid(v_pr.status, v_pr.payment_status, v_pr.paid_at)
    THEN
      RAISE EXCEPTION 'catalog_po_payment_required';
    END IF;
  END IF;

  v_item_kind := v_po.item_kind;
  v_actor := public.catalog_po_actor_name(p_organization_id);

  FOR v_line IN
    SELECT *
    FROM public.catalog_purchase_order_lines
    WHERE purchase_order_id = v_po.id
    ORDER BY created_at
  LOOP
    PERFORM public.catalog_po_update_avg_cost(
      p_organization_id,
      v_po.outlet_id,
      v_item_kind,
      v_line.product_id,
      v_line.variant_id,
      v_line.ingredient_id,
      v_line.qty,
      v_line.unit_cost
    );

    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      v_po.outlet_id,
      v_item_kind,
      v_line.product_id,
      v_line.variant_id,
      v_line.ingredient_id,
      'purchase_order',
      v_line.qty,
      'inventory_purchase_order',
      v_po.id::text || ':' || v_line.id::text,
      COALESCE(NULLIF(btrim(p_comment), ''), NULLIF(btrim(v_po.note), ''), 'Purchase order')
    );
  END LOOP;

  UPDATE public.catalog_purchase_orders
  SET
    status = 'completed',
    fulfilled_at = now(),
    fulfilled_by = auth.uid(),
    updated_at = now()
  WHERE id = v_po.id;

  INSERT INTO public.catalog_purchase_order_events (
    purchase_order_id,
    organization_id,
    event_type,
    actor_user_id,
    actor_name_snapshot,
    comment
  ) VALUES (
    v_po.id,
    p_organization_id,
    'fulfilled',
    auth.uid(),
    v_actor,
    NULLIF(btrim(p_comment), '')
  );

  RETURN to_jsonb((SELECT po FROM public.catalog_purchase_orders po WHERE po.id = v_po.id));
END;
$$;


ALTER FUNCTION "public"."fulfill_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fulfill_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.catalog_stock_transfers%ROWTYPE;
  v_line record;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_transfer_forbidden';
  END IF;
  IF NOT public.user_has_inventory_feature_access(p_organization_id, 'transfer_fulfillment') THEN
    RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
  END IF;

  SELECT * INTO v_transfer
  FROM public.catalog_stock_transfers
  WHERE id = p_transfer_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_transfer_not_found';
  END IF;
  IF v_transfer.status <> 'shipped' THEN
    RAISE EXCEPTION 'catalog_transfer_invalid_status';
  END IF;

  FOR v_line IN
    SELECT *
    FROM public.catalog_stock_transfer_lines
    WHERE transfer_id = v_transfer.id
    ORDER BY created_at
  LOOP
    PERFORM public.catalog_transfer_fulfill_line(
      p_organization_id,
      v_transfer.id,
      v_transfer.to_outlet_id,
      v_transfer.item_kind,
      COALESCE(p_comment, v_transfer.note),
      v_line
    );
  END LOOP;

  UPDATE public.catalog_stock_transfers
  SET
    status = 'completed',
    completed_at = now(),
    completed_by = auth.uid(),
    updated_at = now()
  WHERE id = v_transfer.id;

  PERFORM public.catalog_transfer_insert_event(v_transfer.id, p_organization_id, 'fulfilled', p_comment);

  RETURN to_jsonb((SELECT t FROM public.catalog_stock_transfers t WHERE t.id = v_transfer.id));
END;
$$;


ALTER FUNCTION "public"."fulfill_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gateway_payout_bank_fingerprint"("p_bank_code" "text", "p_account_number" "text", "p_account_holder" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT encode(
    sha256(
      convert_to(
        lower(trim(coalesce(p_bank_code, ''))) || '|' ||
        regexp_replace(coalesce(p_account_number, ''), '[^0-9]', '', 'g') || '|' ||
        upper(trim(coalesce(p_account_holder, ''))),
        'UTF8'
      )
    ),
    'hex'
  );
$$;


ALTER FUNCTION "public"."gateway_payout_bank_fingerprint"("p_bank_code" "text", "p_account_number" "text", "p_account_holder" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_contract_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Placeholder aman: kalau kolom contract_number ada dan masih NULL,
  -- isi dengan UUID sederhana; jika sudah terisi, biarkan apa adanya.
  IF NEW.contract_number IS NULL THEN
    NEW.contract_number := gen_random_uuid()::text;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_contract_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_pos_outlet_public_code"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE v_code text; v_i int := 0;
BEGIN
  LOOP
    v_i := v_i + 1; v_code := '';
    FOR i IN 1..6 LOOP
      v_code := v_code || substr('abcdefghijklmnopqrstuvwxyz0123456789', 1 + floor(random() * 36)::int, 1);
    END LOOP;
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.pos_outlets o WHERE o.public_code = v_code AND o.is_deleted = false);
    IF v_i > 40 THEN RAISE EXCEPTION 'public_code_generate_failed'; END IF;
  END LOOP;
  RETURN v_code;
END;
$$;


ALTER FUNCTION "public"."generate_pos_outlet_public_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_verification_otp"() RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token text;
  v_tries int := 0;
BEGIN
  LOOP
    v_token := lpad(
      ((('x' || encode(extensions.gen_random_bytes(4), 'hex'))::bit(32)::bigint) % 1000000)::text,
      6, '0');
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.email_verification_tokens t WHERE t.token = v_token);
    v_tries := v_tries + 1;
    IF v_tries > 80 THEN
      RAISE EXCEPTION 'could not generate unique verification otp';
    END IF;
  END LOOP;
  RETURN v_token;
END;
$$;


ALTER FUNCTION "public"."generate_unique_verification_otp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_active_payroll_paid_announcements"() RETURNS TABLE("id" "uuid", "period_label" "text", "bank_name" "text", "account_last4" "text", "finance_tip_key" "text", "expires_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    a.id,
    a.period_label,
    a.bank_name,
    a.account_last4,
    a.finance_tip_key,
    a.expires_at,
    a.created_at
  FROM public.employee_payroll_paid_announcements a
  WHERE a.user_id = auth.uid()
    AND a.dismissed_at IS NULL
    AND a.expires_at > now()
  ORDER BY a.created_at DESC
  LIMIT 3;
$$;


ALTER FUNCTION "public"."get_active_payroll_paid_announcements"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_resolved_blockers"("p_organization_id" "uuid", "p_limit" integer DEFAULT 100, "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("blocker_resolved_id" "uuid", "task_step_history_id" "uuid", "task_title" "text", "step_title" "text", "sub_step_title" "text", "resolved_at" timestamp with time zone, "blocker_description" "text", "resolution_description" "text", "blocker_created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.get_all_resolved_blockers__impl(p_organization_id, p_limit, p_start_date, p_end_date);
END;
$$;


ALTER FUNCTION "public"."get_all_resolved_blockers"("p_organization_id" "uuid", "p_limit" integer, "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_all_resolved_blockers__impl"("p_organization_id" "uuid", "p_limit" integer DEFAULT 100, "p_start_date" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_end_date" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("blocker_resolved_id" "uuid", "task_step_history_id" "uuid", "task_title" "text", "step_title" "text", "sub_step_title" "text", "resolved_at" timestamp with time zone, "blocker_description" "text", "resolution_description" "text", "blocker_created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select
    r.id as blocker_resolved_id,
    h.id as task_step_history_id,
    coalesce(dt.title, '-') as task_title,
    coalesce(ts.title, pts.title, '-') as step_title,
    tss.title as sub_step_title,
    r.created_at as resolved_at,
    coalesce(h.description, '-') as blocker_description,
    coalesce(r.description, 'No resolution details provided') as resolution_description,
    h.created_at as blocker_created_at
  from public.task_step_history_blocker_resolved r
  join public.task_step_history h
    on h.id = r.task_step_history_id
  left join public.task_steps ts
    on ts.id = h.task_step_id
  left join public.task_steps_to_steps tss
    on tss.id = h.task_steps_to_steps_id
  left join public.task_steps pts
    on pts.id = tss.parent_step_id
  left join public.daily_tasks dt
    on dt.id = coalesce(h.task_id, ts.task_id, pts.task_id)
  where h.organization_id = p_organization_id
    and (p_start_date is null or r.created_at >= p_start_date)
    and (p_end_date is null or r.created_at <= p_end_date)
  order by r.created_at desc
  limit greatest(coalesce(p_limit, 100), 1);
$$;


ALTER FUNCTION "public"."get_all_resolved_blockers__impl"("p_organization_id" "uuid", "p_limit" integer, "p_start_date" timestamp with time zone, "p_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_blocker_resolutions"("p_task_step_history_ids" "uuid"[]) RETURNS TABLE("id" "uuid", "task_step_history_id" "uuid", "description" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT r.id, r.task_step_history_id, r.description, r.created_at
  FROM public.task_step_history_blocker_resolved r
  WHERE r.task_step_history_id = ANY(p_task_step_history_ids)
    AND public._task_step_history_org_id(r.task_step_history_id) IN (SELECT public.user_organization_ids());
$$;


ALTER FUNCTION "public"."get_blocker_resolutions"("p_task_step_history_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_catalog_inventory_workflow_modes"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po_mode text := 'simple';
  v_transfer_mode text := 'simple';
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden';
