  SELECT s.po_mode, s.transfer_mode
    INTO v_po_mode, v_transfer_mode
  FROM public.catalog_inventory_settings s
  WHERE s.organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'po_mode', COALESCE(v_po_mode, 'simple'),
    'transfer_mode', COALESCE(v_transfer_mode, 'simple')
  );
END;
$$;


ALTER FUNCTION "public"."get_catalog_inventory_workflow_modes"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_click_targets_for_path"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_path" "text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from date;
  v_to date;
  v_has_bounds boolean;
BEGIN
  IF p_web_id IS NULL OR trim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF p_path IS NULL OR trim(p_path) = '' THEN
    RAISE EXCEPTION 'path is required';
  END IF;

  IF NOT public.can_access_web_id(p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT b.resolved_from, b.resolved_to, b.has_bounds
  INTO v_from, v_to, v_has_bounds
  FROM public.traffic_resolve_query_date_bounds(p_web_id, p_from, p_to) b;

  IF NOT v_has_bounds THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'clicks', clicks,
      'unique_sessions', unique_sessions,
      'track_key', NULLIF(track_key, ''),
      'element_type', element_type,
      'element_label', element_label,
      'target_url', NULLIF(target_url, ''),
      'is_internal', is_internal
    ) ORDER BY clicks DESC), '[]'::jsonb)
    FROM (
      SELECT
        COUNT(*)::bigint AS clicks,
        COUNT(DISTINCT ce.session_id)::bigint AS unique_sessions,
        COALESCE(ce.track_key, '') AS track_key,
        ce.element_type,
        ce.element_label,
        COALESCE(ce.target_url, '') AS target_url,
        COALESCE(ce.is_internal, false) AS is_internal
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND (timezone('Asia/Jakarta', ce.created_at))::date BETWEEN v_from AND v_to
        AND public.traffic_path_key(ce.path) = public.traffic_path_key(p_path)
      GROUP BY COALESCE(ce.track_key, ''), ce.element_type, ce.element_label, COALESCE(ce.target_url, ''), COALESCE(ce.is_internal, false)
      ORDER BY COUNT(*) DESC
      LIMIT GREATEST(1, LEAST(p_limit, 200))
    ) t
  );
END;
$$;


ALTER FUNCTION "public"."get_click_targets_for_path"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_path" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_click_targets_for_path"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_path" "text", "p_limit" integer) IS 'Click target breakdown for a page path from raw events; paths matched via traffic_path_key.';



CREATE OR REPLACE FUNCTION "public"."get_click_targets_for_source_key"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_source_key" "text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from date;
  v_to date;
  v_has_bounds boolean;
  v_key text;
BEGIN
  IF p_web_id IS NULL OR trim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF NOT public.can_access_web_id(p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT b.resolved_from, b.resolved_to, b.has_bounds
  INTO v_from, v_to, v_has_bounds
  FROM public.traffic_resolve_query_date_bounds(p_web_id, p_from, p_to) b;

  IF NOT v_has_bounds THEN
    RETURN '[]'::jsonb;
  END IF;

  v_key := COALESCE(NULLIF(trim(p_source_key), ''), '');
  IF v_key NOT IN ('utm', 'paid_click_ids', 'referral', 'direct') THEN
    RAISE EXCEPTION 'invalid source_key';
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'clicks', clicks,
      'unique_sessions', unique_sessions,
      'track_key', NULLIF(track_key, ''),
      'element_type', element_type,
      'element_label', element_label,
      'target_url', NULLIF(target_url, ''),
      'is_internal', is_internal
    ) ORDER BY clicks DESC), '[]'::jsonb)
    FROM (
      SELECT
        COUNT(*)::bigint AS clicks,
        COUNT(DISTINCT ce.session_id)::bigint AS unique_sessions,
        COALESCE(ce.track_key, '') AS track_key,
        ce.element_type,
        ce.element_label,
        COALESCE(ce.target_url, '') AS target_url,
        COALESCE(ce.is_internal, false) AS is_internal
      FROM public.analytics_click_events ce
      LEFT JOIN public.analytics_sessions s
        ON s.id = ce.session_id AND s.web_id = ce.web_id
      CROSS JOIN LATERAL (
        SELECT public.traffic_classify_session_source_key(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          s.first_utm_content, s.utm_content, s.last_utm_content,
          s.first_utm_term, s.utm_term, s.last_utm_term,
          s.first_landing_url, s.landing_url, s.last_landing_url,
          s.has_gclid, s.first_has_gclid, s.last_has_gclid,
          s.has_fbclid, s.first_has_fbclid, s.last_has_fbclid,
          s.has_msclkid, s.has_gbraid, s.has_wbraid,
          s.first_referrer, s.referrer, s.last_referrer
        ) AS source_key
      ) sk
      WHERE ce.web_id = p_web_id
        AND (timezone('Asia/Jakarta', ce.created_at))::date BETWEEN v_from AND v_to
        AND sk.source_key = v_key
      GROUP BY COALESCE(ce.track_key, ''), ce.element_type, ce.element_label, COALESCE(ce.target_url, ''), COALESCE(ce.is_internal, false)
      ORDER BY COUNT(*) DESC
      LIMIT GREATEST(1, LEAST(p_limit, 200))
    ) t
  );
END;
$$;


ALTER FUNCTION "public"."get_click_targets_for_source_key"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_source_key" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_click_targets_for_source_key"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_source_key" "text", "p_limit" integer) IS 'Click targets per source_key; raw events with traffic_resolve_query_date_bounds.';



CREATE OR REPLACE FUNCTION "public"."get_click_targets_for_utm_row"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_route" "text", "p_utm_campaign" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_content" "text", "p_utm_term" "text", "p_session_id" "text" DEFAULT NULL::"text", "p_session_day" "date" DEFAULT NULL::"date", "p_limit" integer DEFAULT 50, "p_visitor_id" "text" DEFAULT NULL::"text", "p_row_kind" "text" DEFAULT 'session'::"text", "p_page_view_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from date;
  v_to date;
  v_has_bounds boolean;
  v_route text;
  v_campaign text;
  v_source text;
  v_medium text;
  v_content text;
  v_term text;
  v_session_id text;
  v_visitor_id text;
  v_row_kind text;
  v_page_view_id uuid;
BEGIN
  IF p_web_id IS NULL OR trim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF NOT public.can_access_web_id(p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT b.resolved_from, b.resolved_to, b.has_bounds
  INTO v_from, v_to, v_has_bounds
  FROM public.traffic_resolve_query_date_bounds(p_web_id, p_from, p_to) b;

  IF NOT v_has_bounds THEN
    RETURN '[]'::jsonb;
  END IF;

  v_route := COALESCE(p_route, '');
  v_campaign := COALESCE(p_utm_campaign, '');
  v_source := COALESCE(p_utm_source, '');
  v_medium := COALESCE(p_utm_medium, '');
  v_content := COALESCE(p_utm_content, '');
  v_term := COALESCE(p_utm_term, '');
  v_session_id := COALESCE(NULLIF(btrim(p_session_id), ''), '');
  v_visitor_id := COALESCE(NULLIF(btrim(p_visitor_id), ''), '');
  v_row_kind := COALESCE(NULLIF(btrim(p_row_kind), ''), 'session');
  IF v_row_kind NOT IN ('session', 'journey') THEN
    v_row_kind := 'session';
  END IF;

  v_page_view_id := NULL;
  IF NULLIF(btrim(p_page_view_id), '') IS NOT NULL THEN
    BEGIN
      v_page_view_id := NULLIF(btrim(p_page_view_id), '')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      v_page_view_id := NULL;
    END;
  END IF;

  RETURN (
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'clicks', clicks,
      'unique_sessions', unique_sessions,
      'track_key', NULLIF(track_key, ''),
      'element_type', element_type,
      'element_label', element_label,
      'target_url', NULLIF(target_url, ''),
      'is_internal', is_internal
    ) ORDER BY clicks DESC), '[]'::jsonb)
    FROM (
      SELECT
        COUNT(*)::bigint AS clicks,
        COUNT(DISTINCT ce.session_id)::bigint AS unique_sessions,
        COALESCE(ce.track_key, '') AS track_key,
        ce.element_type,
        ce.element_label,
        COALESCE(ce.target_url, '') AS target_url,
        COALESCE(ce.is_internal, false) AS is_internal
      FROM public.analytics_click_events ce
      INNER JOIN public.analytics_sessions s
        ON s.id = ce.session_id AND s.web_id = ce.web_id
      CROSS JOIN LATERAL (
        SELECT
          public.traffic_effective_utm_source(
            s.first_utm_source, s.utm_source, s.last_utm_source,
            public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
          ) AS utm_source_eff,
          public.traffic_effective_utm_medium(
            s.first_utm_medium, s.utm_medium, s.last_utm_medium,
            public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
          ) AS utm_medium_eff,
          public.traffic_effective_utm_campaign(
            s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
            public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
          ) AS utm_campaign_eff,
          public.traffic_effective_utm_content(
            s.first_utm_content, s.utm_content, s.last_utm_content,
            public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
          ) AS utm_content_eff,
          public.traffic_effective_utm_term(
            s.first_utm_term, s.utm_term, s.last_utm_term,
            public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
          ) AS utm_term_eff,
          COALESCE(NULLIF(btrim(ce.visitor_id), ''), NULLIF(btrim(s.visitor_id), '')) AS visitor_id
      ) eff
      WHERE ce.web_id = p_web_id
        AND (timezone('Asia/Jakarta', ce.created_at))::date BETWEEN v_from AND v_to
        AND (p_session_day IS NULL OR (timezone('Asia/Jakarta', ce.created_at))::date = p_session_day)
        AND COALESCE(nullif(btrim(eff.utm_campaign_eff), ''), '') = v_campaign
        AND COALESCE(nullif(btrim(eff.utm_source_eff), ''), '') = v_source
        AND COALESCE(nullif(btrim(eff.utm_medium_eff), ''), '') = v_medium
        AND COALESCE(nullif(btrim(eff.utm_content_eff), ''), '') = v_content
        AND COALESCE(nullif(btrim(eff.utm_term_eff), ''), '') = v_term
        AND (
          (v_session_id <> '' AND ce.session_id::text = v_session_id)
          OR (v_session_id = '' AND v_visitor_id <> '' AND eff.visitor_id = v_visitor_id)
          OR (v_session_id = '' AND v_visitor_id = '')
        )
        AND (
          v_row_kind = 'session'
          OR (
            v_row_kind = 'journey'
            AND public.traffic_path_key(ce.path) = public.traffic_path_key(v_route)
          )
        )
        AND (
          v_page_view_id IS NULL
          OR v_row_kind <> 'journey'
          OR EXISTS (
            SELECT 1
            FROM public.analytics_page_views pv
            WHERE pv.id = v_page_view_id
              AND pv.session_id = ce.session_id
              AND public.traffic_path_key(pv.path) = public.traffic_path_key(ce.path)
          )
        )
      GROUP BY COALESCE(ce.track_key, ''), ce.element_type, ce.element_label, COALESCE(ce.target_url, ''), COALESCE(ce.is_internal, false)
      ORDER BY COUNT(*) DESC
      LIMIT GREATEST(1, LEAST(p_limit, 200))
    ) t
  );
END;
$$;


ALTER FUNCTION "public"."get_click_targets_for_utm_row"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_route" "text", "p_utm_campaign" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_content" "text", "p_utm_term" "text", "p_session_id" "text", "p_session_day" "date", "p_limit" integer, "p_visitor_id" "text", "p_row_kind" "text", "p_page_view_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_click_targets_for_utm_row"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_route" "text", "p_utm_campaign" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_content" "text", "p_utm_term" "text", "p_session_id" "text", "p_session_day" "date", "p_limit" integer, "p_visitor_id" "text", "p_row_kind" "text", "p_page_view_id" "text") IS 'Click targets for UTM row; raw events with traffic_resolve_query_date_bounds.';



CREATE OR REPLACE FUNCTION "public"."get_crm_first_response_time_per_room"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "customer_display" "text", "assignee_name" "text", "assignee_id" "uuid", "crm_assignee_segment" "text", "channel" "text", "sla_first_reply_status" "text", "sla_first_reply_late_minutes" integer, "sla_resolution_status" "text", "sla_resolution_late_minutes" integer, "sla_inter_reply_status" "text", "sla_inter_reply_late_minutes" integer, "cycle_started_at" timestamp with time zone, "assignment_due_at" timestamp with time zone, "resolution_due_at" timestamp with time zone, "first_response_at" timestamp with time zone, "resolved_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
