CREATE OR REPLACE FUNCTION "public"."get_department_objectives_with_key_results"("p_organization_id" "uuid", "p_cycle_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_include_individual" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 RETURN public.get_department_objectives_with_key_results__impl(p_organization_id, p_cycle_ids, p_include_individual); END; $$;


ALTER FUNCTION "public"."get_department_objectives_with_key_results"("p_organization_id" "uuid", "p_cycle_ids" "uuid"[], "p_include_individual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_department_objectives_with_key_results__impl"("p_organization_id" "uuid", "p_cycle_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_include_individual" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  result jsonb;
BEGIN
  WITH depts AS (
    SELECT
      dbo.id,
      dbo.organization_id,
      dbo.cycle_id,
      dbo.company_objective_id,
      dbo.department_id,
      dbo.title,
      dbo.description,
      dbo.status,
      dbo.progress_percentage,
      dbo.weight,
      dbo.start_date,
      dbo.end_date,
      dbo.owner_id,
      dbo.created_by,
      dbo.created_at,
      dbo.updated_at,
      d.name AS dept_name,
      co.title AS co_title,
      oc.name AS oc_name,
      oc.year AS oc_year,
      oc.quarter AS oc_quarter
    FROM department_objectives dbo
    INNER JOIN departments d ON d.id = dbo.department_id
    INNER JOIN company_objectives co ON co.id = dbo.company_objective_id
    INNER JOIN okr_cycles oc ON oc.id = dbo.cycle_id
    WHERE dbo.organization_id = p_organization_id
      AND (
        p_cycle_ids IS NULL
        OR cardinality(p_cycle_ids) = 0
        OR dbo.cycle_id = ANY(p_cycle_ids)
      )
    ORDER BY dbo.created_at DESC
  ),
  krs AS (
    SELECT
      kr.department_objective_id,
      jsonb_agg(
        jsonb_build_object(
          'id', kr.id,
          'title', kr.title,
          'target_value', kr.target_value,
          'current_value', kr.current_value,
          'unit', kr.unit,
          'metric_type', kr.metric_type,
          'progress_percentage', kr.progress_percentage,
          'weight', kr.weight,
          'department_objective_id', kr.department_objective_id,
          'company_objective_id', kr.company_objective_id
        )
      ) FILTER (WHERE kr.id IS NOT NULL) AS key_results_json
    FROM key_results kr
    INNER JOIN depts dbo ON dbo.id = kr.department_objective_id
    WHERE kr.company_objective_id IS NULL
      AND trim(lower(COALESCE(kr.title, ''))) IS DISTINCT FROM trim(lower(COALESCE(dbo.title, '')))
    GROUP BY kr.department_objective_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', d.id,
      'organization_id', d.organization_id,
      'cycle_id', d.cycle_id,
      'company_objective_id', d.company_objective_id,
      'department_id', d.department_id,
      'title', d.title,
      'description', d.description,
      'status', d.status,
      'progress_percentage', d.progress_percentage,
      'weight', d.weight,
      'start_date', d.start_date,
      'end_date', d.end_date,
      'owner_id', d.owner_id,
      'created_by', d.created_by,
      'created_at', d.created_at,
      'updated_at', d.updated_at,
      'departments', jsonb_build_object('name', d.dept_name),
      'company_objectives', jsonb_build_object('title', d.co_title),
      'okr_cycles', jsonb_build_object('name', d.oc_name, 'year', d.oc_year, 'quarter', d.oc_quarter),
      'key_results', (
        SELECT COALESCE(k.key_results_json, '[]'::jsonb)
        FROM krs k
        WHERE k.department_objective_id = d.id
      )
    )
  )
  INTO result
  FROM depts d;

  RETURN COALESCE(result, '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_department_objectives_with_key_results__impl"("p_organization_id" "uuid", "p_cycle_ids" "uuid"[], "p_include_individual" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "email_connection_id" "uuid", "from_email" "text", "from_display_name" "text", "thread_subject" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "email_connection_display" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "lead_status_id" "uuid", "followup" integer, "fu_priority" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id,
    c.organization_id,
    c.email_connection_id,
    c.from_email,
    c.from_display_name,
    c.thread_subject,
    m.created_at AS last_message_at,
    LEFT(m.body, 200) AS last_message_body,
    m.direction AS last_message_direction,
    COALESCE(NULLIF(TRIM(conn.email_address), ''), conn.inbound_address)::TEXT AS email_connection_display,
    c.created_at,
    c.updated_at,
    c.lead_status_id,
    COALESCE(c.followup, 0),
    c.fu_priority
  FROM public.email_conversations c
  JOIN public.organization_email_connections conn
    ON conn.id = c.email_connection_id
   AND conn.organization_id = c.organization_id
  LEFT JOIN LATERAL (
    SELECT created_at, body, direction
    FROM public.email_messages
    WHERE conversation_id = c.id
    ORDER BY created_at DESC
    LIMIT 1
  ) m ON true
  WHERE c.organization_id = p_organization_id
    AND (
      (
        SELECT ur.role
        FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.organization_id = p_organization_id
        LIMIT 1
      ) IN ('owner', 'admin')
      OR public.omnichannel_employee_sees_conversation(
        c.assignee_id,
        c.last_handling_assignee_id,
        c.lead_status_id,
        (
          SELECT e.id
          FROM public.employees e
          WHERE e.user_id = auth.uid()
            AND e.organization_id = p_organization_id
          LIMIT 1
        )
      )
    )
  ORDER BY m.created_at DESC NULLS LAST;
$$;


