CREATE OR REPLACE FUNCTION "public"."get_email_unread_counts"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 RETURN QUERY SELECT * FROM public.get_email_unread_counts__impl(p_organization_id); END; $$;


ALTER FUNCTION "public"."get_email_unread_counts"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_email_unread_counts__impl"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id AS conversation_id, COUNT(m.id)::BIGINT AS unread_count
  FROM email_conversations c
  LEFT JOIN email_messages m ON m.conversation_id = c.id AND m.direction = 'inbound' AND m.read_at IS NULL
  WHERE c.organization_id = p_organization_id
  GROUP BY c.id
  HAVING COUNT(m.id) > 0;
$$;


