CREATE OR REPLACE FUNCTION "public"."get_employee_task_ids"("p_employee_id" "uuid") RETURNS TABLE("task_id" "uuid", "assignment_level" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND NOT EXISTS (
       SELECT 1 FROM public.employees e
       WHERE e.id = p_employee_id
         AND e.organization_id IN (SELECT public.user_organization_ids())
     ) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.get_employee_task_ids__impl(p_employee_id);
END;
$$;


ALTER FUNCTION "public"."get_employee_task_ids"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_employee_task_ids__impl"("p_employee_id" "uuid") RETURNS TABLE("task_id" "uuid", "assignment_level" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
BEGIN
  RETURN QUERY

  -- Task-level assignments (directly assigned to daily tasks)
  SELECT DISTINCT
    dta.daily_task_id as task_id,
    'task'::text as assignment_level
  FROM public.daily_tasks_assigned dta
  WHERE dta.employee_id = p_employee_id
    AND dta.daily_task_id IS NOT NULL

  UNION

  -- Step-level assignments (assigned to task steps)
  SELECT DISTINCT
    ts.task_id as task_id,
    'step'::text as assignment_level
  FROM public.task_steps_assigned tsa
  INNER JOIN public.task_steps ts ON tsa.task_step_id = ts.id
  WHERE tsa.employee_id = p_employee_id
    AND ts.task_id IS NOT NULL

  UNION

  -- Sub-step-level assignments (assigned to sub-steps)
  SELECT DISTINCT
    ts.task_id as task_id,
    'substep'::text as assignment_level
  FROM public.task_steps_to_steps_assigned tstsa
  INNER JOIN public.task_steps_to_steps tsts ON tstsa.task_steps_to_steps_id = tsts.id
  INNER JOIN public.task_steps ts ON tsts.parent_step_id = ts.id
  WHERE tstsa.employee_id = p_employee_id
    AND ts.task_id IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."get_employee_task_ids__impl"("p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_employee_task_ids__impl"("p_employee_id" "uuid") IS 'Optimized function to get all daily task IDs assigned to an employee across task, step, and sub-step levels. Returns distinct task IDs with assignment level indicator.';



CREATE OR REPLACE FUNCTION "public"."get_facebook_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "customer_psid" "text", "customer_name" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "last_message_status" "text", "lead_status_id" "uuid", "lead_status_name" "text", "facebook_page_id" "text", "facebook_page_display_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id,
    c.organization_id,
    c.customer_psid,
    c.customer_name,
    m.created_at AS last_message_at,
    LEFT(m.body, 200) AS last_message_body,
    m.direction AS last_message_direction,
    m.status AS last_message_status,
    c.lead_status_id,
    ls.name AS lead_status_name,
    c.facebook_page_id,
    COALESCE(NULLIF(TRIM(COALESCE(p.page_name, '')), ''), p.facebook_page_id)::TEXT AS facebook_page_display_name,
    c.created_at,
    c.updated_at
  FROM public.facebook_conversations c
  LEFT JOIN public.lead_statuses ls ON ls.id = c.lead_status_id
  LEFT JOIN public.organization_facebook_pages p
    ON p.organization_id = c.organization_id
   AND p.facebook_page_id = c.facebook_page_id
   AND p.is_active = true
  LEFT JOIN LATERAL (
    SELECT created_at, body, direction, status
    FROM public.facebook_messages
    WHERE conversation_id = c.id
    ORDER BY created_at DESC
    LIMIT 1
  ) m ON true
  WHERE c.organization_id = p_organization_id
    AND (
      (
        SELECT ur.role
        FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.organization_id = p_organization_id
        LIMIT 1
      ) IN ('owner', 'admin')
      OR (
        (
          SELECT e.id
          FROM public.employees e
          WHERE e.user_id = auth.uid()
            AND e.organization_id = p_organization_id
          LIMIT 1
        ) IS NOT NULL
        AND (
          c.assignee_id = (
            SELECT e.id
            FROM public.employees e
            WHERE e.user_id = auth.uid()
              AND e.organization_id = p_organization_id
            LIMIT 1
          )
          OR (
            c.assignee_id IS NULL
            AND NOT public.lead_status_is_resolved_or_expired_visibility(c.lead_status_id)
          )
          OR public.omnichannel_employee_sees_conversation(
            c.assignee_id,
            c.last_handling_assignee_id,
            c.lead_status_id,
            (
              SELECT e.id
              FROM public.employees e
              WHERE e.user_id = auth.uid()
                AND e.organization_id = p_organization_id
              LIMIT 1
            )
          )
        )
      )
    )
  ORDER BY m.created_at DESC NULLS LAST;
$$;


