 RETURN QUERY SELECT * FROM public.get_facebook_unread_counts__impl(p_organization_id); END; $$;


ALTER FUNCTION "public"."get_facebook_unread_counts"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_facebook_unread_counts__impl"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
