$$;


ALTER FUNCTION "public"."get_facebook_unread_counts__impl"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_instagram_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "customer_ig_id" "text", "customer_external_id" "text", "customer_name" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "last_message_status" "text", "lead_status_id" "uuid", "lead_status_name" "text", "instagram_business_account_id" "text", "instagram_account_display_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH viewer AS (
    SELECT
      auth.uid() AS user_id,
      (
        SELECT ur.role
        FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.organization_id = p_organization_id
        LIMIT 1
      ) AS role,
      (
        SELECT e.id
        FROM public.employees e
        WHERE e.user_id = auth.uid()
          AND e.organization_id = p_organization_id
        LIMIT 1
      ) AS employee_id
  ),
  visible AS (
    SELECT
      c.id,
      c.organization_id,
      c.customer_ig_id,
      c.customer_external_id,
      c.customer_name,
      c.lead_status_id,
      c.instagram_business_account_id,
      c.created_at,
      c.updated_at,
      m.created_at AS last_message_at,
      LEFT(m.body, 200) AS last_message_body,
      m.direction AS last_message_direction,
      m.status AS last_message_status,
      ls.name AS lead_status_name,
      COALESCE(
        CASE
          WHEN a.instagram_username IS NOT NULL AND TRIM(a.instagram_username) <> '' THEN '@' || TRIM(a.instagram_username)
        END,
        NULLIF(TRIM(COALESCE(a.instagram_name, '')), ''),
        a.instagram_business_account_id
      )::TEXT AS instagram_account_display_name,
      ROW_NUMBER() OVER (
        PARTITION BY
          c.organization_id,
          c.instagram_business_account_id,
          public.instagram_conversation_customer_dedupe_key(
            c.customer_ig_id,
            c.customer_external_id,
            c.customer_name
          )
        ORDER BY
          (CASE WHEN COALESCE(TRIM(c.customer_name), '') <> '' THEN 0 ELSE 1 END),
          m.created_at DESC NULLS LAST,
          c.updated_at DESC,
          c.created_at DESC
      ) AS dedupe_rn
    FROM public.instagram_conversations c
    CROSS JOIN viewer v
    LEFT JOIN public.lead_statuses ls ON ls.id = c.lead_status_id
    LEFT JOIN public.organization_instagram_accounts a
      ON a.organization_id = c.organization_id
     AND a.instagram_business_account_id = c.instagram_business_account_id
     AND a.is_active = true
    LEFT JOIN LATERAL (
      SELECT created_at, body, direction, status
      FROM public.instagram_messages
      WHERE conversation_id = c.id
      ORDER BY created_at DESC
      LIMIT 1
    ) m ON true
    WHERE c.organization_id = p_organization_id
      AND v.user_id IS NOT NULL
      AND (
        EXISTS (
          SELECT 1
          FROM public.organizations o
          WHERE o.id = p_organization_id
            AND o.user_id = v.user_id
        )
        OR v.role IN ('owner', 'admin', 'hr')
        OR public.is_omnichannel_survey_settings_admin(p_organization_id)
        OR (
          EXISTS (
            SELECT 1
            FROM public.organization_omnichannel_staff s
            WHERE s.organization_id = p_organization_id
              AND s.employee_id = v.employee_id
          )
          AND (
            c.assignee_id IS NULL
            OR c.assignee_id = v.employee_id
            OR public.omnichannel_employee_sees_conversation(
              c.assignee_id,
              c.last_handling_assignee_id,
              c.lead_status_id,
              v.employee_id
            )
          )
        )
        OR (
          v.employee_id IS NOT NULL
          AND (
            c.assignee_id = v.employee_id
            OR (
              c.assignee_id IS NULL
              AND NOT public.lead_status_is_resolved_or_expired_visibility(c.lead_status_id)
            )
            OR public.omnichannel_employee_sees_conversation(
              c.assignee_id,
              c.last_handling_assignee_id,
              c.lead_status_id,
              v.employee_id
            )
          )
        )
        OR (
          v.employee_id IS NULL
          AND EXISTS (
            SELECT 1
            FROM public.profiles p
            WHERE p.user_id = v.user_id
              AND p.active_organization_id = p_organization_id
          )
          AND c.assignee_id IS NULL
          AND NOT public.lead_status_is_resolved_or_expired_visibility(c.lead_status_id)
        )
      )
  )
  SELECT
    id,
    organization_id,
    customer_ig_id,
    customer_external_id,
    customer_name,
    last_message_at,
    last_message_body,
    last_message_direction,
    last_message_status,
    lead_status_id,
    lead_status_name,
    instagram_business_account_id,
    instagram_account_display_name,
    created_at,
    updated_at
  FROM visible
  WHERE dedupe_rn = 1
  ORDER BY last_message_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."get_instagram_conversations_with_preview"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_instagram_conversations_with_preview"("p_organization_id" "uuid") IS 'Instagram DM preview for Livechat. Dedupes by @username / external sender id / ig id drift.';



CREATE OR REPLACE FUNCTION "public"."get_instagram_unread_counts"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 RETURN QUERY SELECT * FROM public.get_instagram_unread_counts__impl(p_organization_id); END; $$;


ALTER FUNCTION "public"."get_instagram_unread_counts"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_instagram_unread_counts__impl"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "unread_count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id AS conversation_id, COUNT(m.id)::BIGINT AS unread_count
  FROM public.instagram_conversations c
  LEFT JOIN public.instagram_messages m
    ON m.conversation_id = c.id
    AND m.direction = 'inbound'
    AND m.read_at IS NULL
  WHERE c.organization_id = p_organization_id
  GROUP BY c.id;
$$;


ALTER FUNCTION "public"."get_instagram_unread_counts__impl"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_job_by_recruitment_token"("token_param" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT to_jsonb(rl) - 'created_by'
         || jsonb_build_object(
              'job_openings',
              to_jsonb(jo) - 'created_by'
              || jsonb_build_object(
                   'organizations', (SELECT jsonb_build_object('company_name', o.company_name, 'industry', o.industry,
                                                               'address', o.address, 'website', o.website,
                                                               'description', o.description)
                                     FROM public.organizations o WHERE o.id = jo.organization_id),
                   'departments', (SELECT jsonb_build_object('name', d.name) FROM public.departments d WHERE d.id = jo.department_id),
                   'job_positions', (SELECT jsonb_build_object('name', p.name) FROM public.job_positions p WHERE p.id = jo.job_position_id),
                   'job_levels', (SELECT jsonb_build_object('name', l.name) FROM public.job_levels l WHERE l.id = jo.job_level_id),
                   'employee_statuses', (SELECT jsonb_build_object('name', s.name) FROM public.employee_statuses s WHERE s.id = jo.employment_status_id)
                 ),
              'required_skills',
              coalesce((SELECT jsonb_agg(jsonb_build_object('title', rs.title, 'skill_level', rs.skill_level,
                                                            'is_required', rs.is_required, 'description', rs.description)
                                         ORDER BY rs.is_required DESC NULLS LAST, rs.title)
                        FROM public.recruitment_skills rs WHERE rs.job_opening_id = jo.id), '[]'::jsonb)
            )
  FROM public.recruitment_links rl
  JOIN public.job_openings jo ON jo.id = rl.job_opening_id
  WHERE token_param IS NOT NULL
    AND length(token_param) BETWEEN 8 AND 200
    AND rl.token = token_param
    AND rl.status = 'active'
    AND (rl.expires_at IS NULL OR rl.expires_at > now())
  LIMIT 1;
$$;


ALTER FUNCTION "public"."get_job_by_recruitment_token"("token_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_latest_signup_verification_token"("p_user_id" "uuid", "p_email" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
DECLARE
  v_uid uuid;
  v_token text;
BEGIN
  IF coalesce(auth.role(), '') IS DISTINCT FROM 'service_role' THEN
    RETURN json_build_object('ok', false, 'error', 'not_authorized');
  END IF;
  IF p_user_id IS NULL OR p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN json_build_object('ok', false, 'error', 'invalid_input');
  END IF;
  SELECT u.id INTO v_uid FROM auth.users u WHERE u.id = p_user_id AND lower(trim(u.email)) = lower(trim(p_email)) LIMIT 1;
  IF v_uid IS NULL THEN RETURN json_build_object('ok', false, 'error', 'no_matching_user'); END IF;
  SELECT t.token INTO v_token FROM public.email_verification_tokens t WHERE t.user_id = v_uid ORDER BY t.created_at DESC LIMIT 1;
  IF v_token IS NULL THEN RETURN json_build_object('ok', false, 'error', 'no_token'); END IF;
  RETURN json_build_object('ok', true, 'token', v_token);
END;
$$;


ALTER FUNCTION "public"."get_latest_signup_verification_token"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_catalog_inventory_settings"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_settings public.catalog_inventory_settings;
  v_access jsonb;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_settings
  FROM public.catalog_inventory_settings s
  WHERE s.organization_id = p_organization_id;

  IF NOT FOUND THEN
    INSERT INTO public.catalog_inventory_settings (organization_id)
    VALUES (p_organization_id)
    RETURNING * INTO v_settings;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'feature_key', fa.feature_key,
        'allowed_roles', fa.allowed_roles
      )
      ORDER BY fa.feature_key
    ),
    '[]'::jsonb
  )
    INTO v_access
  FROM public.catalog_inventory_feature_access fa
  WHERE fa.organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'organization_id', v_settings.organization_id,
    'po_mode', v_settings.po_mode,
    'transfer_mode', v_settings.transfer_mode,
    'feature_access', v_access
  );
END;
$$;


