CREATE OR REPLACE FUNCTION "public"."get_or_create_operational_email_notification_settings"("p_organization_id" "uuid") RETURNS "public"."operational_email_notification_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.operational_email_notification_settings;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT * INTO v_row
  FROM public.operational_email_notification_settings s
  WHERE s.organization_id = p_organization_id;

  IF FOUND THEN
    RETURN v_row;
  END IF;

  INSERT INTO public.operational_email_notification_settings (organization_id)
  VALUES (p_organization_id)
  ON CONFLICT (organization_id) DO NOTHING
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    SELECT * INTO v_row
    FROM public.operational_email_notification_settings s
    WHERE s.organization_id = p_organization_id;
  END IF;

  RETURN v_row;
END;
$$;


