CREATE OR REPLACE FUNCTION "public"."get_or_create_org_api_system_actor"("p_organization_id" "uuid") RETURNS TABLE("user_id" "uuid", "display_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_name text := 'Synckerja API';
BEGIN
  SELECT a.user_id, COALESCE(NULLIF(btrim(a.display_name), ''), 'Synckerja API')
    INTO v_user_id, v_name
  FROM public.organization_api_system_actors a
  WHERE a.organization_id = p_organization_id;

  IF v_user_id IS NOT NULL THEN
    RETURN QUERY SELECT v_user_id, v_name;
    RETURN;
  END IF;

  v_name := 'Synckerja API';

  SELECT ur.user_id INTO v_user_id
  FROM public.user_roles ur
  WHERE ur.organization_id = p_organization_id
    AND ur.role IN ('owner', 'admin')
  ORDER BY CASE ur.role WHEN 'owner' THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'No owner/admin found for organization %', p_organization_id;
  END IF;

  INSERT INTO public.organization_api_system_actors (organization_id, user_id, display_name)
  VALUES (p_organization_id, v_user_id, v_name)
  ON CONFLICT (organization_id) DO UPDATE
    SET updated_at = now(),
        display_name = COALESCE(NULLIF(organization_api_system_actors.display_name, ''), EXCLUDED.display_name)
  RETURNING organization_api_system_actors.user_id, organization_api_system_actors.display_name
  INTO v_user_id, v_name;

  RETURN QUERY SELECT v_user_id, v_name;
END;
$$;


ALTER FUNCTION "public"."get_or_create_org_api_system_actor"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_organization_members"("_organization_id" "uuid") RETURNS TABLE("user_id" "uuid", "full_name" "text", "email" "text", "role" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ranked AS (
    SELECT
      uo.user_id AS uid,
      COALESCE(p.full_name, e.full_name, p.email, '')::text AS fn,
      p.email::text AS em,
      ur.role::text AS r,
      CASE lower(ur.role::text)
        WHEN 'owner' THEN 1
        WHEN 'admin' THEN 2
        WHEN 'manager' THEN 3
        WHEN 'member' THEN 4
        ELSE 5
      END AS rk
    FROM public.user_organizations uo
    JOIN public.profiles p ON p.user_id = uo.user_id
    LEFT JOIN public.employees e
      ON e.user_id = uo.user_id
      AND e.organization_id = uo.organization_id
    JOIN public.user_roles ur
      ON ur.user_id = uo.user_id
      AND ur.organization_id = uo.organization_id
    WHERE uo.organization_id = _organization_id
      AND COALESCE(uo.is_active, true) = true
      AND EXISTS (
        SELECT 1
        FROM public.user_organizations me
        WHERE me.user_id = (SELECT auth.uid())
          AND me.organization_id = _organization_id
          AND COALESCE(me.is_active, true) = true
      )
  ),
  best AS (
    SELECT DISTINCT ON (ranked.uid)
      ranked.uid,
      ranked.fn,
      ranked.em,
      ranked.r
    FROM ranked
    ORDER BY ranked.uid, ranked.rk ASC
  )
  SELECT best.uid, best.fn, best.em, best.r FROM best;
$$;


ALTER FUNCTION "public"."get_organization_members"("_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payroll_disburse_preview"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_employees jsonb := '[]'::jsonb;
  v_row record;
  v_issues jsonb;
  v_snapshot jsonb;
  v_live_bank text;
  v_live_acct text;
  v_live_holder text;
  v_count_pending integer := 0;
  v_count_invalid integer := 0;
  v_count_processing integer := 0;
  v_count_failed integer := 0;
  v_count_paid integer := 0;
  v_total_thp_pending numeric := 0;
  v_total_thp_all numeric := 0;
  v_current_period record;
  v_prev_period record;
  v_prev_run record;
  v_prev_total_thp numeric := 0;
  v_prev_employee_count integer := 0;
  v_matched_count integer := 0;
  v_matched_prev_thp numeric := 0;
  v_matched_curr_thp numeric := 0;
  v_delta_amount numeric := 0;
  v_delta_percent numeric := NULL;
  v_matched_delta_amount numeric := 0;
  v_matched_delta_percent numeric := NULL;
  v_severity text := 'unavailable';
  v_requires_ack boolean := false;
  v_period_comparison jsonb;
BEGIN
  SELECT pr.id, pr.organization_id, pr.status, pr.run_name
  INTO v_run
  FROM public.payroll_runs pr
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Payroll run not found');
  END IF;

  IF NOT (v_run.organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.user_has_org_role(v_run.organization_id, ARRAY['owner','admin','hr']) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  FOR v_row IN
    SELECT
      c.id AS calculation_id,
      c.take_home_pay,
      c.payment_status,
      c.payout_snapshot,
      e.full_name AS employee_name,
      e.employee_id AS employee_code,
      epi.bank_name AS live_bank_name,
      epi.bank_account_number AS live_account_number,
      epi.bank_account_holder AS live_account_holder
    FROM public.employee_payroll_calculations c
    JOIN public.employees e ON e.id = c.employee_id
    JOIN public.employee_payroll_info epi ON epi.id = c.employee_payroll_info_id
    WHERE c.payroll_run_id = p_run_id
    ORDER BY e.full_name NULLS LAST, e.employee_id
  LOOP
    v_snapshot := COALESCE(v_row.payout_snapshot, '{}'::jsonb);
    v_issues := '[]'::jsonb;

    IF COALESCE(trim(v_snapshot->>'account_number'), '') = ''
      OR COALESCE(trim(v_snapshot->>'account_holder'), '') = ''
      OR COALESCE(trim(v_snapshot->>'bank_name'), '') = '' THEN
      v_issues := v_issues || to_jsonb('missing_bank'::text);
    END IF;

    IF COALESCE(v_row.take_home_pay, 0) <= 0 THEN
      v_issues := v_issues || to_jsonb('invalid_amount'::text);
    END IF;

    IF v_row.payment_status = 'processing' THEN
      v_issues := v_issues || to_jsonb('already_processing'::text);
      v_count_processing := v_count_processing + 1;
    ELSIF v_row.payment_status = 'failed' THEN
      v_issues := v_issues || to_jsonb('failed_previous'::text);
      v_count_failed := v_count_failed + 1;
    ELSIF v_row.payment_status = 'paid' THEN
      v_issues := v_issues || to_jsonb('already_paid'::text);
      v_count_paid := v_count_paid + 1;
    END IF;

    v_live_bank := COALESCE(trim(v_row.live_bank_name), '');
    v_live_acct := COALESCE(trim(v_row.live_account_number), '');
    v_live_holder := COALESCE(trim(v_row.live_account_holder), '');
    IF v_live_bank <> COALESCE(trim(v_snapshot->>'bank_name'), '')
      OR v_live_acct <> COALESCE(trim(v_snapshot->>'account_number'), '')
      OR v_live_holder <> COALESCE(trim(v_snapshot->>'account_holder'), '') THEN
      v_issues := v_issues || to_jsonb('snapshot_drift'::text);
    END IF;

    IF v_row.payment_status = 'pending'
      AND jsonb_array_length(v_issues) = 0 THEN
      v_count_pending := v_count_pending + 1;
      v_total_thp_pending := v_total_thp_pending + COALESCE(v_row.take_home_pay, 0);
    ELSIF v_row.payment_status = 'pending' THEN
      v_count_invalid := v_count_invalid + 1;
    END IF;

    v_total_thp_all := v_total_thp_all + COALESCE(v_row.take_home_pay, 0);

    v_employees := v_employees || jsonb_build_array(jsonb_build_object(
      'calculation_id', v_row.calculation_id,
      'employee_name', v_row.employee_name,
      'employee_code', v_row.employee_code,
      'bank_name', v_snapshot->>'bank_name',
      'account_number', v_snapshot->>'account_number',
      'account_holder', v_snapshot->>'account_holder',
      'take_home_pay', COALESCE(v_row.take_home_pay, 0),
      'payment_status', v_row.payment_status,
      'issues', v_issues,
      'eligible', (v_row.payment_status = 'pending' AND jsonb_array_length(v_issues) = 0)
    ));
  END LOOP;

  SELECT pp.id, pp.period_name, pp.start_date
  INTO v_current_period
  FROM public.payroll_runs pr
  JOIN public.payroll_periods pp ON pp.id = pr.payroll_period_id
  WHERE pr.id = p_run_id;

  SELECT pp.id, pp.period_name, pp.start_date
  INTO v_prev_period
  FROM public.payroll_periods pp
  WHERE pp.organization_id = v_run.organization_id
    AND pp.start_date < v_current_period.start_date
  ORDER BY pp.start_date DESC
  LIMIT 1;

  IF v_prev_period IS NULL THEN
    v_period_comparison := jsonb_build_object(
      'available', false,
      'severity', 'unavailable',
      'requires_review_ack', false
    );
  ELSE
    SELECT pr.id, pr.status
    INTO v_prev_run
    FROM public.payroll_runs pr
    WHERE pr.payroll_period_id = v_prev_period.id
      AND pr.status IN ('paid', 'calculated')
    ORDER BY
      CASE pr.status WHEN 'paid' THEN 0 WHEN 'calculated' THEN 1 ELSE 2 END,
      COALESCE(pr.paid_at, pr.calculated_at, pr.created_at) DESC
    LIMIT 1;

    IF v_prev_run IS NULL THEN
      v_period_comparison := jsonb_build_object(
        'available', false,
        'previous_period_id', v_prev_period.id,
        'previous_period_name', v_prev_period.period_name,
        'severity', 'unavailable',
        'requires_review_ack', false
      );
    ELSE
      SELECT
        COALESCE(round(SUM(c.take_home_pay)), 0),
        COUNT(*)::integer
      INTO v_prev_total_thp, v_prev_employee_count
      FROM public.employee_payroll_calculations c
      WHERE c.payroll_run_id = v_prev_run.id;

      SELECT
        COUNT(*)::integer,
        COALESCE(round(SUM(curr.take_home_pay)), 0),
        COALESCE(round(SUM(prev.take_home_pay)), 0)
      INTO v_matched_count, v_matched_curr_thp, v_matched_prev_thp
      FROM public.employee_payroll_calculations curr
      JOIN public.employee_payroll_calculations prev
        ON prev.employee_id = curr.employee_id
       AND prev.payroll_run_id = v_prev_run.id
      WHERE curr.payroll_run_id = p_run_id
        AND curr.payment_status = 'pending'
        AND COALESCE(curr.take_home_pay, 0) > 0
        AND COALESCE(trim(curr.payout_snapshot->>'account_number'), '') <> ''
        AND COALESCE(trim(curr.payout_snapshot->>'account_holder'), '') <> ''
        AND COALESCE(trim(curr.payout_snapshot->>'bank_name'), '') <> ''
        AND NOT EXISTS (
          SELECT 1
          FROM public.employee_payroll_info epi
          WHERE epi.id = curr.employee_payroll_info_id
            AND (
              COALESCE(trim(epi.bank_name), '') <> COALESCE(trim(curr.payout_snapshot->>'bank_name'), '')
              OR COALESCE(trim(epi.bank_account_number), '') <> COALESCE(trim(curr.payout_snapshot->>'account_number'), '')
              OR COALESCE(trim(epi.bank_account_holder), '') <> COALESCE(trim(curr.payout_snapshot->>'account_holder'), '')
            )
        );

      v_delta_amount := round(v_total_thp_pending) - v_prev_total_thp;
      IF v_prev_total_thp > 0 THEN
        v_delta_percent := round((v_delta_amount / v_prev_total_thp) * 100, 2);
      END IF;

      v_matched_delta_amount := v_matched_curr_thp - v_matched_prev_thp;
      IF v_matched_prev_thp > 0 THEN
        v_matched_delta_percent := round((v_matched_delta_amount / v_matched_prev_thp) * 100, 2);
      END IF;

      IF v_delta_percent IS NULL THEN
        v_severity := 'unavailable';
        v_requires_ack := false;
      ELSIF v_delta_percent >= 15 THEN
        v_severity := 'significant_increase';
        v_requires_ack := true;
      ELSIF v_delta_percent <= -15 THEN
        v_severity := 'significant_decrease';
        v_requires_ack := true;
      ELSIF abs(v_delta_percent) >= 5 THEN
        v_severity := 'moderate';
        v_requires_ack := false;
      ELSE
        v_severity := 'stable';
        v_requires_ack := false;
      END IF;

      v_period_comparison := jsonb_build_object(
        'available', true,
        'previous_period_id', v_prev_period.id,
        'previous_period_name', v_prev_period.period_name,
        'previous_run_id', v_prev_run.id,
        'previous_run_status', v_prev_run.status,
        'previous_total_thp', v_prev_total_thp,
        'previous_employee_count', v_prev_employee_count,
        'current_total_thp', round(v_total_thp_pending),
        'current_employee_count', v_count_pending,
        'matched_employee_count', v_matched_count,
        'matched_previous_thp', v_matched_prev_thp,
        'matched_current_thp', v_matched_curr_thp,
        'delta_amount', v_delta_amount,
        'delta_percent', v_delta_percent,
        'matched_delta_amount', v_matched_delta_amount,
        'matched_delta_percent', v_matched_delta_percent,
        'severity', v_severity,
        'requires_review_ack', v_requires_ack
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'run_id', v_run.id,
    'run_name', v_run.run_name,
    'run_status', v_run.status,
    'employees', v_employees,
    'summary', jsonb_build_object(
      'count_pending', v_count_pending,
      'count_invalid', v_count_invalid,
      'count_processing', v_count_processing,
      'count_failed', v_count_failed,
      'count_paid', v_count_paid,
      'total_thp_pending', round(v_total_thp_pending),
      'total_thp_all', round(v_total_thp_all),
      'has_active_disbursement', (v_count_processing > 0)
    ),
    'period_comparison', v_period_comparison
  );
END;
$$;


ALTER FUNCTION "public"."get_payroll_disburse_preview"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_payroll_statutory_escrow_amounts"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_pph21 numeric := 0;
  v_bpjs_kes numeric := 0;
  v_bpjs_pen numeric := 0;
BEGIN
  SELECT pr.id, pr.organization_id, pr.status
  INTO v_run
  FROM public.payroll_runs pr
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Payroll run not found');
  END IF;

  IF NOT (v_run.organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.user_has_org_role(v_run.organization_id, ARRAY['owner','admin','hr']) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(SUM(pi.calculated_amount), 0)
  INTO v_pph21
  FROM public.payroll_items pi
  JOIN public.employee_payroll_calculations c ON c.id = pi.payroll_calculation_id
  WHERE c.payroll_run_id = p_run_id
    AND (
      pi.item_type = 'tax'
      OR lower(COALESCE(pi.item_category, '')) = 'pph21'
    );

  SELECT COALESCE(SUM(pi.calculated_amount), 0)
  INTO v_bpjs_kes
  FROM public.payroll_items pi
  JOIN public.employee_payroll_calculations c ON c.id = pi.payroll_calculation_id
  WHERE c.payroll_run_id = p_run_id
    AND lower(COALESCE(pi.item_category, '')) = 'bpjs_kesehatan';

  SELECT COALESCE(SUM(pi.calculated_amount), 0)
  INTO v_bpjs_pen
  FROM public.payroll_items pi
  JOIN public.employee_payroll_calculations c ON c.id = pi.payroll_calculation_id
  WHERE c.payroll_run_id = p_run_id
    AND lower(COALESCE(pi.item_category, '')) = 'bpjs_pensiun';

  RETURN jsonb_build_object(
    'success', true,
    'payroll_run_id', p_run_id,
    'organization_id', v_run.organization_id,
    'run_status', v_run.status,
    'amount_pph21', v_pph21,
    'amount_bpjs_kesehatan', v_bpjs_kes,
    'amount_bpjs_pensiun', v_bpjs_pen,
    'amount_total', v_pph21 + v_bpjs_kes + v_bpjs_pen
  );
END;
$$;


ALTER FUNCTION "public"."get_payroll_statutory_escrow_amounts"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_pos_receipt_send_status"("p_sales_activity_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_email_status text;
  v_sms_status text;
  v_email_sent_at timestamptz;
  v_sms_sent_at timestamptz;
BEGIN
  IF p_sales_activity_id IS NULL THEN
    RETURN jsonb_build_object('email_sent', false, 'sms_sent', false);
  END IF;

  SELECT sa.organization_id
  INTO v_org
  FROM public.sales_activities sa
  WHERE sa.id = p_sales_activity_id;

  IF v_org IS NULL OR v_org NOT IN (SELECT public.user_organization_ids()) THEN
    RETURN jsonb_build_object('email_sent', false, 'sms_sent', false);
  END IF;

  SELECT i.email_status, i.sms_status, i.email_sent_at, i.sms_sent_at
  INTO v_email_status, v_sms_status, v_email_sent_at, v_sms_sent_at
  FROM public.pos_receipt_feedback_invitations i
  WHERE i.sales_activity_id = p_sales_activity_id;

  RETURN jsonb_build_object(
    'email_sent',
      COALESCE(v_email_status = 'sent', false) OR v_email_sent_at IS NOT NULL,
    'sms_sent',
      COALESCE(v_sms_status = 'sent', false) OR v_sms_sent_at IS NOT NULL
  );
END;
$$;


ALTER FUNCTION "public"."get_pos_receipt_send_status"("p_sales_activity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_pos_receipt_send_status"("p_sales_activity_id" "uuid") IS 'Returns { email_sent, sms_sent } for a sales activity digital receipt invitation.';



CREATE OR REPLACE FUNCTION "public"."get_public_customer_survey_form"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv public.customer_survey_invitations%ROWTYPE;
  v_s public.organization_customer_survey_settings%ROWTYPE;
BEGIN
  SELECT i.* INTO v_inv
  FROM public.customer_survey_invitations i
  WHERE i.public_token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_inv.status <> 'sent' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_available');
  END IF;

  SELECT s.* INTO v_s
  FROM public.organization_customer_survey_settings s
  WHERE s.organization_id = v_inv.organization_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'token', p_token,
    'survey_page_title', coalesce(nullif(trim(v_s.survey_page_title), ''), 'Feedback'),
    'question_text', v_s.question_text,
    'scale_min_label', v_s.scale_min_label,
    'scale_max_label', v_s.scale_max_label,
    'follow_up_mode', v_s.follow_up_mode,
    'follow_up_single', v_s.follow_up_single,
    'follow_up_low', v_s.follow_up_low,
    'follow_up_mid', v_s.follow_up_mid,
    'follow_up_high', v_s.follow_up_high,
    'thank_you_message', v_s.thank_you_message
  );
END;
$$;


ALTER FUNCTION "public"."get_public_customer_survey_form"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_order_product_rating_summaries"("p_code" "text", "p_catalog_item_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_rows jsonb;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found', 'summaries', '[]'::jsonb);
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'catalog_item_id', s.catalog_item_id,
        'avg_rating', s.avg_rating,
        'rating_count', s.rating_count
      )
      ORDER BY s.catalog_item_id
    ),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT
      a.catalog_item_id,
      ROUND(AVG(a.rating)::numeric, 1) AS avg_rating,
      COUNT(*)::integer AS rating_count
    FROM public.pos_receipt_feedback_item_attributions a
    WHERE a.pos_outlet_id = v_out.outlet_id
      AND a.organization_id = v_out.organization_id
      AND a.rating >= 4
      AND (
        p_catalog_item_ids IS NULL
        OR cardinality(p_catalog_item_ids) = 0
        OR a.catalog_item_id = ANY (p_catalog_item_ids)
      )
    GROUP BY a.catalog_item_id
  ) s;

  RETURN jsonb_build_object('ok', true, 'summaries', COALESCE(v_rows, '[]'::jsonb));
END;
$$;


ALTER FUNCTION "public"."get_public_order_product_rating_summaries"("p_code" "text", "p_catalog_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_order_product_reviews"("p_code" "text", "p_catalog_item_id" "uuid", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_avg numeric;
  v_count integer;
  v_reviews jsonb;
  v_limit integer;
  v_offset integer;
BEGIN
  IF p_catalog_item_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_item');
  END IF;

  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  v_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 50));
  v_offset := GREATEST(0, COALESCE(p_offset, 0));

  SELECT
    ROUND(AVG(a.rating)::numeric, 1),
    COUNT(*)::integer
  INTO v_avg, v_count
  FROM public.pos_receipt_feedback_item_attributions a
  WHERE a.pos_outlet_id = v_out.outlet_id
    AND a.organization_id = v_out.organization_id
    AND a.catalog_item_id = p_catalog_item_id
    AND a.rating >= 4;

  SELECT COALESCE(
    jsonb_agg(row_json ORDER BY submitted_at DESC),
    '[]'::jsonb
  )
  INTO v_reviews
  FROM (
    SELECT
      jsonb_build_object(
        'id', a.id,
        'rating', a.rating,
        'comment', a.comment,
        'submitted_at', a.submitted_at,
        'reply_text', r.reply_text,
        'replied_at', r.replied_at
      ) AS row_json,
      a.submitted_at
    FROM public.pos_receipt_feedback_item_attributions a
    JOIN public.pos_receipt_feedback_responses r ON r.id = a.response_id
    WHERE a.pos_outlet_id = v_out.outlet_id
      AND a.organization_id = v_out.organization_id
      AND a.catalog_item_id = p_catalog_item_id
      AND a.rating >= 4
      AND a.comment IS NOT NULL
      AND length(trim(a.comment)) > 0
    ORDER BY a.submitted_at DESC
    LIMIT v_limit
    OFFSET v_offset
  ) q;

  RETURN jsonb_build_object(
    'ok', true,
    'catalog_item_id', p_catalog_item_id,
    'avg_rating', v_avg,
    'rating_count', COALESCE(v_count, 0),
    'reviews', COALESCE(v_reviews, '[]'::jsonb),
    'limit', v_limit,
    'offset', v_offset
  );
END;
$$;


ALTER FUNCTION "public"."get_public_order_product_reviews"("p_code" "text", "p_catalog_item_id" "uuid", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_pos_receipt_feedback"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv public.pos_receipt_feedback_invitations%ROWTYPE;
  v_sa public.sales_activities%ROWTYPE;
  v_outlet public.pos_outlets%ROWTYPE;
  v_org public.organizations%ROWTYPE;
  v_resp public.pos_receipt_feedback_responses%ROWTYPE;
  v_items jsonb;
  v_receipt_settings public.pos_outlet_receipt_settings%ROWTYPE;
  v_already_submitted boolean := false;
BEGIN
  SELECT i.* INTO v_inv
  FROM public.pos_receipt_feedback_invitations i
  WHERE i.public_token = p_token
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT sa.* INTO v_sa
  FROM public.sales_activities sa
  WHERE sa.id = v_inv.sales_activity_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_inv.pos_outlet_id IS NOT NULL THEN
    SELECT o.* INTO v_outlet
    FROM public.pos_outlets o
    WHERE o.id = v_inv.pos_outlet_id;
  END IF;

  SELECT o.* INTO v_org
  FROM public.organizations o
  WHERE o.id = v_inv.organization_id
  LIMIT 1;

  IF v_inv.pos_outlet_id IS NOT NULL THEN
    SELECT rs.* INTO v_receipt_settings
    FROM public.pos_outlet_receipt_settings rs
    WHERE rs.outlet_id = v_inv.pos_outlet_id
    LIMIT 1;
  END IF;

  SELECT r.* INTO v_resp
  FROM public.pos_receipt_feedback_responses r
  WHERE r.invitation_id = v_inv.id
  LIMIT 1;

  v_already_submitted := FOUND;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', i.id,
        'service_name', i.service_name,
        'sub_service_name', i.sub_service_name,
        'quantity', i.quantity,
        'unit_price', i.unit_price,
        'total_price', i.total_price
      )
      ORDER BY i.created_at
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM public.sales_activity_items i
  WHERE i.sales_activity_id = v_sa.id;

  RETURN jsonb_build_object(
    'ok', true,
    'token', p_token,
    'already_submitted', v_already_submitted,
    'rating', v_resp.rating,
    'comment', v_resp.comment,
    'reply_text', v_resp.reply_text,
    'business_name', COALESCE(nullif(trim(v_outlet.name), ''), nullif(trim(v_org.company_name), ''), 'Store'),
    'outlet_name', COALESCE(nullif(trim(v_outlet.name), ''), ''),
    'customer_name', COALESCE(nullif(trim(v_inv.customer_name), ''), nullif(trim(v_sa.client_name), ''), ''),
    'footer_notes', COALESCE(v_receipt_settings.footer_notes, ''),
    'transaction', jsonb_build_object(
      'receipt_number', left(replace(v_sa.id::text, '-', ''), 7),
      'date', v_sa.date,
      'created_at', v_sa.created_at,
      'total_amount', v_sa.total_amount,
      'checkout_subtotal', v_sa.checkout_subtotal,
      'checkout_tax_amount', v_sa.checkout_tax_amount,
      'checkout_gratuity_amount', v_sa.checkout_gratuity_amount,
      'payment_method', v_sa.payment_method,
      'payment_reference', v_sa.payment_reference,
      'cash_tendered', v_sa.cash_tendered,
      'table_number', v_sa.table_number,
      'items', v_items
    ),
    'thank_you_message', 'Thank you for your feedback!'
  );
END;
$$;


ALTER FUNCTION "public"."get_public_pos_receipt_feedback"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_review_brief_extended_by_token"("token_param" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_ta text;
  v_cap text;
BEGIN
  SELECT prt.social_media_plan_id INTO v_plan_id
  FROM public.public_review_tokens prt
  WHERE prt.token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT bta.description INTO v_ta FROM public.brief_target_audiences bta WHERE bta.social_media_plan_id = v_plan_id LIMIT 1;
  SELECT bc.content INTO v_cap FROM public.brief_captions bc WHERE bc.social_media_plan_id = v_plan_id LIMIT 1;

  RETURN json_build_object(
    'target_audience', COALESCE(v_ta, ''),
    'caption', COALESCE(v_cap, '')
  );
END;
$$;


ALTER FUNCTION "public"."get_public_review_brief_extended_by_token"("token_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_review_comments"("token_param" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_link_url text;
  v_comments json;
BEGIN
  SELECT social_media_plan_id, link_url INTO v_plan_id, v_link_url
  FROM public.public_review_tokens
  WHERE token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RETURN '[]'::json;
  END IF;

  SELECT COALESCE(json_agg(
    json_build_object(
      'id', lc.id,
      'social_media_plan_id', lc.social_media_plan_id,
      'link_url', lc.link_url,
      'comment_text', lc.comment_text,
      'created_by', lc.created_by,
      'created_at', lc.created_at,
      'updated_at', lc.updated_at,
      'video_timestamp_seconds', lc.video_timestamp_seconds,
      'annotation_data', lc.annotation_data,
      'creator_display_name', CASE
        WHEN lc.commenter_display_name IS NOT NULL AND trim(lc.commenter_display_name) <> '' THEN trim(lc.commenter_display_name)
        WHEN lc.created_by IS NOT NULL THEN COALESCE((SELECT p.full_name FROM public.profiles p WHERE p.user_id = lc.created_by LIMIT 1), 'Unknown')
        ELSE 'Anonim'
      END
    ) ORDER BY lc.created_at ASC
  ), '[]'::json) INTO v_comments
  FROM public.link_comments lc
  WHERE lc.social_media_plan_id = v_plan_id
    AND lc.link_url = v_link_url;

  RETURN v_comments;
END;
$$;


ALTER FUNCTION "public"."get_public_review_comments"("token_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_review_content_by_token"("token_param" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_link_url text;
  v_result json;
BEGIN
  SELECT social_media_plan_id, link_url INTO v_plan_id, v_link_url
  FROM public.public_review_tokens
  WHERE token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT json_build_object(
    'social_media_plan_id', smp.id,
    'link_url', v_link_url,
    'title', smp.title,
    'post_date', smp.post_date,
    'google_drive_link', smp.google_drive_link,
    'content_type_name', ct.name,
    'service_name', s.name,
    'sub_service_name', ss.name,
    'pic_production_name', pic.full_name,
    'carousel_image_paths', COALESCE(
      (
        SELECT json_agg(image.storage_path ORDER BY image.sort_order)
        FROM public.social_media_plan_carousel_images AS image
        WHERE image.social_media_plan_id = smp.id
      ),
      '[]'::json
    )
  ) INTO v_result
  FROM public.social_media_plans smp
  LEFT JOIN public.content_types ct ON ct.id = smp.content_type_id
  LEFT JOIN public.services s ON s.id = smp.service_id
  LEFT JOIN public.sub_services ss ON ss.id = smp.sub_service_id
  LEFT JOIN public.employees pic ON pic.id = smp.pic_production_id
  WHERE smp.id = v_plan_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."get_public_review_content_by_token"("token_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_branches"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN '[]'::jsonb;
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(
      jsonb_build_object(
        'name', o.name,
        'address', NULLIF(btrim(o.address), ''),
        'public_code', o.public_code
      )
      ORDER BY o.sort_order, o.name
    )
    FROM public.pos_outlets o
    JOIN public.synckerja_order_outlet_settings s
      ON s.outlet_id = o.id
     AND s.organization_id = o.organization_id
     AND s.enabled = true
    WHERE o.organization_id = v_out.organization_id
      AND o.id <> v_out.outlet_id
      AND COALESCE(o.is_deleted, false) = false
      AND o.is_active = true
      AND o.public_code IS NOT NULL
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_branches"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_cashier_ticket"("p_code" "text", "p_claim_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_session public.pos_table_sessions%ROWTYPE;
  v_token text;
  v_fulfillment text;
BEGIN
  v_token := upper(btrim(COALESCE(p_claim_token, '')));
  IF length(v_token) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE organization_id = v_out.organization_id
    AND pos_outlet_id = v_out.outlet_id
    AND claim_token = v_token
    AND checkout_channel = 'synckerja_cashier'
  ORDER BY created_at DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF v_pending.expires_at < now() AND v_pending.status = 'pending' THEN
    UPDATE public.pos_pending_checkouts SET status = 'expired' WHERE id = v_pending.id;
    v_pending.status := 'expired';
  END IF;
  IF v_pending.session_id IS NOT NULL THEN
    SELECT * INTO v_session FROM public.pos_table_sessions WHERE id = v_pending.session_id;
  END IF;
  v_fulfillment := COALESCE(
    NULLIF(v_pending.payload ->> 'fulfillmentMode', ''),
    'dine_in'
  );
  RETURN jsonb_build_object(
    'ok', true,
    'status', v_pending.status,
    'claim_token', v_token,
    'table_number', COALESCE(v_session.table_name, v_pending.payload #>> '{activity,table_number}'),
    'grand_total', COALESCE(
      (v_pending.payload #>> '{checkoutTotals,grandTotal}')::numeric,
      (v_pending.payload #>> '{activity,total_amount}')::numeric,
      0
    ),
    'expires_at', v_pending.expires_at,
    'cart_updated_at', v_pending.updated_at,
    'claimed', v_pending.claimed_at IS NOT NULL OR COALESCE(v_session.claimed_at IS NOT NULL, false),
    'paid', v_pending.status = 'paid' OR COALESCE(v_session.status = 'paid', false),
    'fulfillment', v_fulfillment,
    'sales_type_label', COALESCE(
      v_pending.payload ->> 'salesTypeLabel',
      CASE WHEN v_fulfillment = 'takeaway' THEN 'Takeaway' ELSE 'Dine In' END
    )
  );
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_cashier_ticket"("p_code" "text", "p_claim_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_catalog"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_items jsonb;
  v_cats jsonb;
  v_st_id uuid;
  v_st_name text := 'Dine In';
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found', 'categories', '[]'::jsonb, 'items', '[]'::jsonb);
  END IF;
  SELECT st.id, st.name INTO v_st_id, v_st_name
  FROM public.catalog_sales_types st
  WHERE st.organization_id = v_out.organization_id
    AND st.is_active = true
    AND lower(st.name) LIKE '%dine%'
  ORDER BY st.sort_order
  LIMIT 1;

  SELECT COALESCE(jsonb_agg(item ORDER BY sort_order, name), '[]'::jsonb)
  INTO v_items
  FROM (
    SELECT
      ci.sort_order,
      dp.name,
      jsonb_build_object(
        'id', dp.id,
        'name', COALESCE(dp.name, 'Item'),
        'description', dp.description,
        'unit_price', COALESCE(dp.unit_price, 0),
        'photo_path', dp.photo_path,
        'product_category_id', dp.product_category_id,
        'product_category_name', c.name,
        'pos_status', COALESCE(cpo.pos_status, dp.pos_status, 'available'),
        'kind', COALESCE(dp.kind, 'product'),
        'service_id', dp.service_id,
        'sub_service_id', dp.sub_service_id,
        'track_stock', COALESCE(dp.track_stock, false),
        'inventory_sku_id', dp.inventory_sku_id,
        'available_qty', NULL,
        'has_modifiers', EXISTS (
          SELECT 1
          FROM public.catalog_product_modifiers cpm
          JOIN public.catalog_modifier_groups g ON g.id = cpm.group_id AND g.is_active
          WHERE cpm.product_id = dp.id
            AND (
              NOT EXISTS (SELECT 1 FROM public.catalog_modifier_outlets mo WHERE mo.group_id = g.id)
              OR EXISTS (
                SELECT 1 FROM public.catalog_modifier_outlets mo
                WHERE mo.group_id = g.id AND mo.outlet_id = ci.outlet_id
              )
            )
        ),
        'variant_count', (
          SELECT count(*)::int FROM public.catalog_product_variants v WHERE v.product_id = dp.id
        ),
        'variants', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('id', v.id, 'name', v.name, 'price', v.price) ORDER BY v.sort_order)
          FROM public.catalog_product_variants v
          WHERE v.product_id = dp.id
        ), '[]'::jsonb)
      ) AS item
    FROM public.synckerja_order_catalog_items ci
    JOIN public.default_prices dp ON dp.id = ci.catalog_item_id AND dp.organization_id = v_out.organization_id
    JOIN public.catalog_product_outlets cpo
      ON cpo.product_id = dp.id
     AND cpo.outlet_id = ci.outlet_id
     AND cpo.organization_id = v_out.organization_id
    LEFT JOIN public.catalog_product_categories c ON c.id = dp.product_category_id
    WHERE ci.outlet_id = v_out.outlet_id
      AND ci.catalog_item_id IS NOT NULL
      AND COALESCE(cpo.pos_status, dp.pos_status, 'available') <> 'hidden'
    UNION ALL
    SELECT
      ci.sort_order,
      cb.name,
      jsonb_build_object(
        'id', cb.id,
        'name', COALESCE(cb.name, 'Bundle'),
        'description', NULL,
        'unit_price', COALESCE(cb.bundle_price, 0),
        'photo_path', cb.photo_path,
        'product_category_id', NULL,
        'product_category_name', NULL,
        'pos_status', 'available',
        'kind', 'bundle',
        'service_id', NULL,
        'sub_service_id', NULL,
        'track_stock', false,
        'inventory_sku_id', NULL,
        'available_qty', NULL,
        'has_modifiers', false,
        'variant_count', 0,
        'variants', '[]'::jsonb
      ) AS item
    FROM public.synckerja_order_catalog_items ci
    JOIN public.catalog_bundles cb
      ON cb.id = ci.bundle_id
     AND cb.organization_id = v_out.organization_id
     AND cb.is_active
     AND COALESCE(cb.is_deleted, false) = false
    JOIN public.catalog_bundle_outlets cbo
      ON cbo.bundle_id = cb.id
     AND cbo.outlet_id = ci.outlet_id
    WHERE ci.outlet_id = v_out.outlet_id
      AND ci.bundle_id IS NOT NULL
  ) listed;

  SELECT COALESCE(jsonb_agg(cat ORDER BY (cat->>'sort_order')::int, cat->>'name'), '[]'::jsonb)
  INTO v_cats
  FROM (
    SELECT jsonb_build_object(
      'id', c.id,
      'name', c.name,
      'sort_order', c.sort_order,
      'layout', COALESCE(MAX(lay.layout), 'list'),
      'related_category_id', MAX(xs.to_category_id::text)
    ) AS cat
    FROM public.synckerja_order_catalog_items ci
    JOIN public.default_prices dp ON dp.id = ci.catalog_item_id
    JOIN public.catalog_product_outlets cpo
      ON cpo.product_id = dp.id
     AND cpo.outlet_id = ci.outlet_id
    JOIN public.catalog_product_categories c ON c.id = dp.product_category_id
    LEFT JOIN public.synckerja_order_category_layouts lay
      ON lay.outlet_id = ci.outlet_id
     AND lay.category_id = c.id
    LEFT JOIN public.synckerja_order_cross_sell xs
      ON xs.organization_id = v_out.organization_id
     AND xs.from_category_id = c.id
    WHERE ci.outlet_id = v_out.outlet_id
      AND ci.catalog_item_id IS NOT NULL
      AND COALESCE(cpo.pos_status, dp.pos_status, 'available') <> 'hidden'
    GROUP BY c.id, c.name, c.sort_order
  ) grouped_cats;

  RETURN jsonb_build_object(
    'ok', true,
    'categories', COALESCE(v_cats, '[]'::jsonb),
    'items', COALESCE(v_items, '[]'::jsonb),
    'dine_in_sales_type_id', v_st_id,
    'dine_in_sales_type_label', COALESCE(v_st_name, 'Dine In')
  );
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_catalog"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_checkout_preview"("p_code" "text", "p_subtotal" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_totals jsonb;
  v_st_id uuid;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT st.id INTO v_st_id
  FROM public.catalog_sales_types st
  JOIN public.catalog_sales_type_outlets sto
    ON sto.sales_type_id = st.id AND sto.outlet_id = v_out.outlet_id
  WHERE st.organization_id = v_out.organization_id
    AND st.is_active
    AND lower(st.name) LIKE '%dine%'
  ORDER BY st.sort_order
  LIMIT 1;

  v_totals := public._synckerja_order_checkout_totals(
    v_out.organization_id,
    GREATEST(0, COALESCE(p_subtotal, 0)),
    v_out.outlet_id,
    v_st_id
  );
  RETURN jsonb_build_object('ok', true) || COALESCE(v_totals, '{}'::jsonb);
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_checkout_preview"("p_code" "text", "p_subtotal" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_item_options"("p_code" "text", "p_item_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_product public.default_prices%ROWTYPE;
  v_bundle public.catalog_bundles%ROWTYPE;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  SELECT dp.* INTO v_product
  FROM public.default_prices dp
  JOIN public.synckerja_order_catalog_items ci
    ON ci.catalog_item_id = dp.id
   AND ci.outlet_id = v_out.outlet_id
   AND ci.organization_id = v_out.organization_id
  JOIN public.catalog_product_outlets cpo
    ON cpo.product_id = dp.id
   AND cpo.outlet_id = v_out.outlet_id
  WHERE dp.id = p_item_id
    AND dp.organization_id = v_out.organization_id
    AND COALESCE(cpo.pos_status, dp.pos_status, 'available') <> 'hidden'
  LIMIT 1;

  IF FOUND THEN
    RETURN jsonb_build_object(
      'ok', true,
      'kind', 'product',
      'id', v_product.id,
      'name', COALESCE(v_product.name, 'Item'),
      'description', v_product.description,
      'unit_price', COALESCE(v_product.unit_price, 0),
      'photo_path', v_product.photo_path,
      'variants', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'id', v.id,
          'name', v.name,
          'price', v.price,
          'out_of_stock', COALESCE((
            SELECT vo.in_stock <= 0
            FROM public.catalog_product_variant_outlets vo
            WHERE vo.variant_id = v.id AND vo.outlet_id = v_out.outlet_id
          ), false)
        ) ORDER BY v.sort_order)
        FROM public.catalog_product_variants v
        WHERE v.product_id = v_product.id
      ), '[]'::jsonb),
      'modifier_groups', COALESCE((
        SELECT jsonb_agg(grp.obj ORDER BY grp.sort_order)
        FROM (
          SELECT
            g.sort_order,
            jsonb_build_object(
              'id', g.id,
              'name', g.name,
              'is_required', (g.limit_enabled AND g.is_required),
              'min_selected', CASE
                WHEN g.limit_enabled AND g.is_required THEN LEAST(
                  GREATEST(1, g.max_selected),
                  GREATEST(1, COALESCE(g.min_selected, 1))
                )
                ELSE 0
              END,
              'max_selected', CASE
                WHEN g.limit_enabled THEN GREATEST(1, g.max_selected)
                ELSE GREATEST(1, (
                  SELECT count(*)::int
                  FROM public.catalog_modifier_options o
                  WHERE o.group_id = g.id AND o.is_active
                ))
              END,
              'single_select', (NOT COALESCE(g.option_qty_enabled, false))
                AND g.limit_enabled AND GREATEST(1, g.max_selected) = 1,
              'option_qty_enabled', COALESCE(g.option_qty_enabled, false),
              'options', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                  'id', o.id,
                  'name', o.name,
                  'extra_price', COALESCE(o.extra_price, 0),
                  'out_of_stock', public._synckerja_order_modifier_option_oos(v_out.outlet_id, g.id, o.id)
                ) ORDER BY o.sort_order, o.name)
                FROM public.catalog_modifier_options o
                WHERE o.group_id = g.id AND o.is_active
              ), '[]'::jsonb)
            ) AS obj
          FROM public.catalog_product_modifiers cpm
          JOIN public.catalog_modifier_groups g ON g.id = cpm.group_id
          WHERE cpm.product_id = v_product.id
            AND g.is_active
            AND (
              NOT EXISTS (SELECT 1 FROM public.catalog_modifier_outlets mo WHERE mo.group_id = g.id)
              OR EXISTS (
                SELECT 1 FROM public.catalog_modifier_outlets mo
                WHERE mo.group_id = g.id AND mo.outlet_id = v_out.outlet_id
              )
            )
        ) grp
        WHERE jsonb_array_length(COALESCE(grp.obj -> 'options', '[]'::jsonb)) > 0
      ), '[]'::jsonb),
      'included_items', '[]'::jsonb
    );
  END IF;

  SELECT cb.* INTO v_bundle
  FROM public.catalog_bundles cb
  JOIN public.synckerja_order_catalog_items ci
    ON ci.bundle_id = cb.id
   AND ci.outlet_id = v_out.outlet_id
   AND ci.organization_id = v_out.organization_id
  JOIN public.catalog_bundle_outlets cbo
    ON cbo.bundle_id = cb.id
   AND cbo.outlet_id = v_out.outlet_id
  WHERE cb.id = p_item_id
    AND cb.organization_id = v_out.organization_id
    AND cb.is_active
    AND COALESCE(cb.is_deleted, false) = false
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'kind', 'bundle',
    'id', v_bundle.id,
    'name', COALESCE(v_bundle.name, 'Bundle'),
    'description', NULL,
    'unit_price', COALESCE(v_bundle.bundle_price, 0),
    'photo_path', v_bundle.photo_path,
    'variants', '[]'::jsonb,
    'modifier_groups', '[]'::jsonb,
    'included_items', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'name', COALESCE(dp.name, 'Item'),
        'quantity', bi.quantity
      ) ORDER BY bi.sort_order)
      FROM public.catalog_bundle_items bi
      JOIN public.default_prices dp ON dp.id = bi.product_id
      WHERE bi.bundle_id = v_bundle.id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_item_options"("p_code" "text", "p_item_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_link"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_enabled boolean;
  v_maps text;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'not_found',
      'link_ordering_enabled', false,
      'maps_url', null
    );
  END IF;

  SELECT s.link_ordering_enabled, s.maps_url
    INTO v_enabled, v_maps
  FROM public.synckerja_order_outlet_settings s
  WHERE s.outlet_id = v_out.outlet_id
    AND s.organization_id = v_out.organization_id;

  RETURN jsonb_build_object(
    'ok', true,
    'link_ordering_enabled', COALESCE(v_enabled, false),
    'maps_url', CASE
      WHEN v_maps ~ '^https://' THEN v_maps
      ELSE NULL
    END
  );
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_link"("p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_qris_status"("p_code" "text", "p_pending_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_req public.xendit_payment_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet_paid(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
    AND organization_id = v_out.organization_id
    AND pos_outlet_id = v_out.outlet_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  SELECT * INTO v_req
  FROM public.xendit_payment_requests
  WHERE pos_pending_checkout_id = v_pending.id
  ORDER BY created_at DESC
  LIMIT 1;
  RETURN jsonb_build_object(
    'ok', true,
    'status', COALESCE(v_req.status, v_pending.status),
    'sales_activity_id', COALESCE(v_pending.sales_activity_id, v_req.sales_activity_id),
    'qr_string', v_req.qr_string,
    'expires_at', v_req.expires_at
  );
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_qris_status"("p_code" "text", "p_pending_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_store"("p_code" "text", "p_table_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_org public.synckerja_order_org_settings%ROWTYPE;
  v_tbl record;
  v_table jsonb := NULL;
  v_hours jsonb;
  v_address text;
  v_phone text;
  v_cover text;
  v_covers text[];
  v_outlet_logo text;
  v_blocked boolean := false;
  v_payload jsonb;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet_paid(p_code);
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_found');
    END IF;
    v_blocked := true;
  END IF;
  SELECT * INTO v_org FROM public.synckerja_order_org_settings WHERE organization_id = v_out.organization_id;
  SELECT NULLIF(btrim(o.address), ''), NULLIF(btrim(o.phone), '')
  INTO v_address, v_phone
  FROM public.pos_outlets o
  WHERE o.id = v_out.outlet_id;
  v_phone := COALESCE(v_phone, NULLIF(btrim(v_org.contact_phone), ''));
  SELECT s.cover_paths, NULLIF(btrim(s.cover_path), '')
  INTO v_covers, v_cover
  FROM public.synckerja_order_outlet_settings s
  WHERE s.outlet_id = v_out.outlet_id;
  IF v_covers IS NULL OR cardinality(v_covers) = 0 THEN
    v_covers := CASE WHEN v_cover IS NOT NULL THEN ARRAY[v_cover] ELSE ARRAY[]::text[] END;
  END IF;
  IF cardinality(v_covers) = 0 AND NULLIF(btrim(v_org.cover_path), '') IS NOT NULL THEN
    v_covers := ARRAY[btrim(v_org.cover_path)];
  END IF;
  v_cover := NULLIF(btrim(v_covers[1]), '');
  SELECT NULLIF(btrim(r.logo_storage_path), '') INTO v_outlet_logo
  FROM public.pos_outlet_receipt_settings r
  WHERE r.outlet_id = v_out.outlet_id;
  v_hours := public._synckerja_order_hours_state(v_out.outlet_id);
  IF p_table_name IS NOT NULL AND btrim(p_table_name) <> '' THEN
    SELECT * INTO v_tbl FROM public._synckerja_order_table_state(v_out.organization_id, v_out.outlet_id, p_table_name);
    IF NOT FOUND THEN
      v_payload := jsonb_build_object(
        'ok', true,
        'public_code', v_out.public_code,
        'outlet_id', v_out.outlet_id,
        'outlet_name', v_out.outlet_name,
        'outlet_address', v_address,
        'outlet_phone', v_phone,
        'business_name', COALESCE(NULLIF(v_org.business_name, ''), v_out.outlet_name),
        'logo_path', v_org.logo_path,
        'outlet_logo_path', v_outlet_logo,
        'cover_path', v_cover,
        'cover_paths', to_jsonb(v_covers),
        'pickup_enabled', v_org.pickup_enabled,
        'is_open', COALESCE((v_hours ->> 'is_open')::boolean, false),
        'hours', v_hours,
        'table', NULL,
        'table_error', 'not_found'
      );
      IF v_blocked THEN
        v_payload := v_payload || jsonb_build_object(
          'ok', false,
          'error', 'ordering_unavailable',
          'outlet_address', NULL,
          'outlet_phone', NULL
        );
      END IF;
      RETURN v_payload;
    END IF;
    IF v_tbl.table_id IS NOT NULL THEN
      v_table := jsonb_build_object(
        'id', v_tbl.table_id,
        'name', v_tbl.table_name,
        'pax', v_tbl.table_pax,
        'remaining_pax', v_tbl.remaining_pax,
        'join', v_tbl.join_state,
        'session_id', v_tbl.open_session_id
      );
    END IF;
  END IF;
  v_payload := jsonb_build_object(
    'ok', true,
    'public_code', v_out.public_code,
    'outlet_id', v_out.outlet_id,
    'outlet_name', v_out.outlet_name,
    'outlet_address', v_address,
    'outlet_phone', v_phone,
    'business_name', COALESCE(NULLIF(v_org.business_name, ''), v_out.outlet_name),
    'logo_path', v_org.logo_path,
    'outlet_logo_path', v_outlet_logo,
    'cover_path', v_cover,
    'cover_paths', to_jsonb(v_covers),
    'pickup_enabled', v_org.pickup_enabled,
    'is_open', COALESCE((v_hours ->> 'is_open')::boolean, false),
    'hours', v_hours,
    'table', v_table
  );
  IF v_blocked THEN
    v_payload := v_payload || jsonb_build_object(
      'ok', false,
      'error', 'ordering_unavailable',
      'outlet_address', NULL,
      'outlet_phone', NULL
    );
  END IF;
  RETURN v_payload;
END;
$$;


ALTER FUNCTION "public"."get_public_synckerja_order_store"("p_code" "text", "p_table_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_synckerja_order_whatsapp"("p_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_settings public.synckerja_order_outlet_settings%ROWTYPE;
  v_digits text;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF NOT public.synckerja_order_sales_module_enabled(v_out.organization_id, 'omnichannel')
     OR NOT public.synckerja_order_sales_module_enabled(v_out.organization_id, 'whatsappBusiness') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'disabled');
  END IF;

  SELECT * INTO v_settings
  FROM public.synckerja_order_outlet_settings
  WHERE outlet_id = v_out.outlet_id AND organization_id = v_out.organization_id;

  IF NOT FOUND OR NOT v_settings.whatsapp_button_enabled THEN
    RETURN jsonb_build_object('ok', false, 'error', 'disabled');
  END IF;

  IF v_settings.whatsapp_account_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_selected');
  END IF;

  SELECT nullif(regexp_replace(coalesce(a.display_phone_number, ''), '\D', '', 'g'), '')
    INTO v_digits
  FROM public.organization_whatsapp_accounts a
  WHERE a.id = v_settings.whatsapp_account_id
    AND a.organization_id = v_out.organization_id
    AND a.is_active = true;

  IF v_digits IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'inactive');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'phone_digits', v_digits,
    'prefill_message', nullif(btrim(coalesce(v_settings.whatsapp_prefill_message, '')), '')
  );
END;
$$;


