CREATE OR REPLACE FUNCTION "public"."get_social_media_schedule_monitoring_summary"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'pending_late_count', (SELECT count(*)::int FROM public.v_social_media_schedules_pending_late),
    'stuck_publishing_count', (SELECT count(*)::int FROM public.v_social_media_schedules_stuck_publishing),
    'failed_24h_count', (SELECT count(*)::int FROM public.v_social_media_schedules_failed_24h),
    'rate_deferred_count', (SELECT count(*)::int FROM public.v_social_media_schedules_rate_deferred),
    'pending_due_now_count', (
      SELECT count(*)::int
      FROM public.social_media_scheduled_posts s
      WHERE s.status = 'pending'
        AND s.scheduled_at <= now()
        AND (s.next_retry_at IS NULL OR s.next_retry_at <= now())
    ),
    'last_tick', (
      SELECT to_jsonb(t)
      FROM (
        SELECT
          id,
          started_at,
          finished_at,
          duration_ms,
          dry_run,
          claimed,
          resumed,
          processed,
          published_ok,
          deferred_rate_limited,
          failed,
          recovered_stale,
          pending_due_now,
          pending_late,
          rate_deferred
        FROM public.social_media_scheduler_tick_logs
        ORDER BY started_at DESC
        LIMIT 1
      ) t
    ),
    'pending_late_sample', (
      SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
      FROM (SELECT * FROM public.v_social_media_schedules_pending_late ORDER BY scheduled_at LIMIT 10) t
    ),
    'stuck_publishing_sample', (
      SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
      FROM (SELECT * FROM public.v_social_media_schedules_stuck_publishing ORDER BY updated_at LIMIT 10) t
    ),
    'failed_24h_sample', (
      SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
      FROM (SELECT * FROM public.v_social_media_schedules_failed_24h ORDER BY updated_at DESC LIMIT 10) t
    ),
    'rate_deferred_sample', (
      SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb)
      FROM (SELECT * FROM public.v_social_media_schedules_rate_deferred ORDER BY next_retry_at LIMIT 10) t
    )
  );
$$;


ALTER FUNCTION "public"."get_social_media_schedule_monitoring_summary"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_social_media_schedule_monitoring_summary"() IS 'Ops summary: counts + samples including rate-limit deferred and pending due queue.';



CREATE TABLE IF NOT EXISTS "public"."social_media_scheduler_config" (
    "id" smallint DEFAULT 1 NOT NULL,
    "batch_size" integer DEFAULT 20 NOT NULL,
    "per_org_per_tick" integer DEFAULT 3 NOT NULL,
    "resume_batch_size" integer DEFAULT 10 NOT NULL,
    "tick_concurrency" integer DEFAULT 4 NOT NULL,
    "tick_time_budget_ms" integer DEFAULT 25000 NOT NULL,
    "tiktok_global_in_flight" integer DEFAULT 12 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "youtube_global_in_flight" integer DEFAULT 6 NOT NULL,
    "instagram_global_in_flight" integer DEFAULT 4 NOT NULL,
    "linkedin_global_in_flight" integer DEFAULT 4 NOT NULL,
    "facebook_global_in_flight" integer DEFAULT 4 NOT NULL,
    CONSTRAINT "social_media_scheduler_config_batch_size" CHECK ((("batch_size" >= 1) AND ("batch_size" <= 100))),
    CONSTRAINT "social_media_scheduler_config_budget" CHECK ((("tick_time_budget_ms" >= 5000) AND ("tick_time_budget_ms" <= 120000))),
    CONSTRAINT "social_media_scheduler_config_concurrency" CHECK ((("tick_concurrency" >= 1) AND ("tick_concurrency" <= 20))),
    CONSTRAINT "social_media_scheduler_config_facebook_in_flight" CHECK ((("facebook_global_in_flight" >= 1) AND ("facebook_global_in_flight" <= 50))),
    CONSTRAINT "social_media_scheduler_config_instagram_in_flight" CHECK ((("instagram_global_in_flight" >= 1) AND ("instagram_global_in_flight" <= 50))),
    CONSTRAINT "social_media_scheduler_config_linkedin_in_flight" CHECK ((("linkedin_global_in_flight" >= 1) AND ("linkedin_global_in_flight" <= 50))),
    CONSTRAINT "social_media_scheduler_config_per_org" CHECK ((("per_org_per_tick" >= 1) AND ("per_org_per_tick" <= 20))),
    CONSTRAINT "social_media_scheduler_config_resume" CHECK ((("resume_batch_size" >= 1) AND ("resume_batch_size" <= 50))),
    CONSTRAINT "social_media_scheduler_config_singleton" CHECK (("id" = 1)),
    CONSTRAINT "social_media_scheduler_config_tiktok_in_flight" CHECK ((("tiktok_global_in_flight" >= 1) AND ("tiktok_global_in_flight" <= 50))),
    CONSTRAINT "social_media_scheduler_config_youtube_in_flight" CHECK ((("youtube_global_in_flight" >= 1) AND ("youtube_global_in_flight" <= 50)))
);


