CREATE OR REPLACE FUNCTION "public"."get_subscription_status"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_os record;
  v_employee_count integer;
  v_member_limit integer;
  v_plan_name text;
  v_base_price numeric;
  v_now timestamptz := now();
  v_end timestamptz;
  v_days int;
  v_is_trial boolean;
  v_is_expired boolean;
  v_is_active boolean;
  v_status text;
  v_over boolean;
  v_next_payment timestamptz;
  v_paid_omni integer;
  v_roster_cap integer;
  v_lm_active boolean;
  v_lm_grace timestamptz;
  v_lm_entitled boolean;
  v_paid_pos integer;
  v_pos_addon boolean;
  v_self_service boolean;
  v_pos_sales_tenant boolean;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = auth.uid() AND uo.organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT os.*, sp.name AS sp_name, sp.base_price_per_member AS sp_bpp
  INTO v_os
  FROM public.organization_subscriptions os
  LEFT JOIN public.subscription_plans sp ON sp.id = os.subscription_plan_id
  WHERE os.organization_id = p_org_id
  LIMIT 1;

  IF v_os.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(o.subscription_self_service_enabled, true)
  INTO v_self_service
  FROM public.organizations o
  WHERE o.id = p_org_id;
  v_self_service := COALESCE(v_self_service, true);

  v_member_limit := COALESCE(v_os.member_count, 1);
  v_plan_name := COALESCE(v_os.sp_name, 'Plan');
  v_base_price := COALESCE(v_os.sp_bpp, 0);
  v_is_trial := COALESCE(v_os.is_trial, false);
  v_paid_omni := COALESCE(v_os.omnichannel_paid_seat_count, 0);
  v_roster_cap := LEAST(COALESCE(v_os.member_count, 0), v_paid_omni);
  v_lm_active := COALESCE(v_os.lead_magnet_active, false);
  v_lm_grace := v_os.lead_magnet_grace_until;
  v_lm_entitled := v_lm_active OR (v_lm_grace IS NOT NULL AND v_lm_grace > v_now);
  v_paid_pos := COALESCE(v_os.pos_paid_outlet_count, 0);
  -- Sales tenants (self-service subscription page off) are billed by sales:
  -- POS access must not depend on enabling the add-on in Plans.
  v_pos_sales_tenant := NOT v_self_service;
  v_pos_addon := COALESCE(v_os.pos_addon_active, false) OR v_pos_sales_tenant;

  v_employee_count := public.count_active_employees_for_org(p_org_id);
  v_over := v_employee_count > v_member_limit;

  IF v_is_trial THEN
    v_end := v_os.trial_end_date;
  ELSE
    v_end := v_os.subscription_end_date;
  END IF;

  IF v_end IS NOT NULL AND v_end < v_now THEN
    v_is_expired := true;
    v_days := 0;
  ELSIF v_end IS NOT NULL THEN
    v_is_expired := false;
    v_days := GREATEST(0, FLOOR(EXTRACT(epoch FROM (v_end - v_now)) / 86400.0)::integer);
  ELSE
    v_is_expired := false;
    v_days := 9999;
  END IF;

  v_status := COALESCE(v_os.status, 'trial');
  IF v_is_expired THEN
    v_status := 'expired';
  END IF;

  v_is_active := NOT v_is_expired AND (
    (v_is_trial AND (v_os.trial_end_date IS NULL OR v_os.trial_end_date > v_now))
    OR (
      NOT v_is_trial
      AND v_os.status = 'active'
      AND (v_os.subscription_end_date IS NULL OR v_os.subscription_end_date > v_now)
    )
  );

  SELECT p.subscription_end_date INTO v_next_payment
  FROM public.payments p
  WHERE p.organization_id = p_org_id
    AND p.status IN ('success', 'settlement', 'paid')
  ORDER BY p.created_at DESC
  LIMIT 1;

  IF v_next_payment IS NULL THEN
    v_next_payment := v_os.subscription_end_date;
  END IF;

  RETURN jsonb_build_object(
    'status', v_status,
    'plan_name', v_plan_name,
    'is_trial', v_is_trial,
    'is_active', v_is_active,
    'is_expired', v_is_expired,
    'employee_count', v_employee_count,
    'member_limit', v_member_limit,
    'is_over_limit', v_over,
    'days_remaining', v_days,
    'end_date', v_end,
    'subscription_start_date', v_os.subscription_start_date,
    'subscription_end_date', v_os.subscription_end_date,
    'trial_end_date', v_os.trial_end_date,
    'billing_cycle', COALESCE(v_os.billing_cycle, 'monthly'),
    'billing_term_months', public._coerce_billing_term_months(v_os.billing_term_months),
    'base_price_per_member', v_base_price,
    'next_payment_date', v_next_payment,
    'omnichannel_paid_seat_count', v_paid_omni,
    'omnichannel_roster_seat_cap', v_roster_cap,
    'lead_magnet_active', v_lm_active,
    'lead_magnet_grace_until', v_lm_grace,
    'lead_magnet_entitled', v_lm_entitled,
    'pos_paid_outlet_count', v_paid_pos,
    'pos_addon_active', v_pos_addon,
    'pos_addon_sales_tenant_bypass', v_pos_sales_tenant,
    'subscription_self_service_enabled', v_self_service
  );
END;
$$;


ALTER FUNCTION "public"."get_subscription_status"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_threads_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "customer_threads_id" "text", "customer_name" "text", "root_media_id" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "last_message_status" "text", "lead_status_id" "uuid", "lead_status_name" "text", "threads_user_id" "text", "threads_account_display_name" "text", "ticket_id" "text", "assignee_id" "uuid", "meta_session_expires_at" timestamp with time zone, "last_inbound_at" timestamp with time zone, "conversation_origin" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    dm.id,
    dm.organization_id,
    dm.customer_threads_id,
    dm.customer_name,
    NULL::text AS root_media_id,
    dm.last_message_at,
    dm.last_message_body,
    dm.last_message_direction,
    dm.last_message_status,
    dm.lead_status_id,
    dm.lead_status_name,
    dm.threads_user_id,
    dm.threads_account_display_name,
    dm.ticket_id,
    dm.assignee_id,
    dm.meta_session_expires_at,
    dm.last_inbound_at,
    dm.conversation_origin,
    dm.created_at,
    dm.updated_at
  FROM public.get_threads_dm_conversations_with_preview(p_organization_id) dm;
$$;


ALTER FUNCTION "public"."get_threads_conversations_with_preview"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_threads_conversations_with_preview"("p_organization_id" "uuid") IS 'Legacy alias — proxies to get_threads_dm_conversations_with_preview for Threads DM livechat.';



CREATE OR REPLACE FUNCTION "public"."get_threads_dm_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "customer_participant_id" "text", "customer_threads_id" "text", "customer_name" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "last_message_status" "text", "lead_status_id" "uuid", "lead_status_name" "text", "threads_user_id" "text", "threads_account_display_name" "text", "ticket_id" "text", "assignee_id" "uuid", "meta_session_expires_at" timestamp with time zone, "last_inbound_at" timestamp with time zone, "conversation_origin" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id, c.organization_id, c.customer_participant_id, c.customer_participant_id AS customer_threads_id, c.customer_name,
    m.created_at AS last_message_at, LEFT(m.body, 200) AS last_message_body, m.direction AS last_message_direction, m.status AS last_message_status,
    c.lead_status_id, ls.name AS lead_status_name, c.threads_user_id,
    COALESCE(NULLIF(TRIM(COALESCE(acct.threads_username, '')), ''), NULLIF(TRIM(COALESCE(acct.instagram_username, '')), ''), NULLIF(TRIM(COALESCE(acct.instagram_name, '')), ''), c.threads_user_id)::TEXT AS threads_account_display_name,
    c.ticket_id, c.assignee_id, c.meta_session_expires_at, c.last_inbound_at, c.conversation_origin, c.created_at, c.updated_at
  FROM public.threads_dm_conversations c
  LEFT JOIN public.lead_statuses ls ON ls.id = c.lead_status_id
  LEFT JOIN LATERAL (SELECT a.threads_username, a.instagram_username, a.instagram_name FROM public.organization_instagram_accounts a WHERE a.organization_id = c.organization_id AND a.threads_user_id = c.threads_user_id AND a.is_active = true AND a.has_threads = true ORDER BY a.updated_at DESC NULLS LAST LIMIT 1) acct ON true
  LEFT JOIN LATERAL (SELECT created_at, body, direction, status FROM public.threads_dm_messages WHERE conversation_id = c.id ORDER BY created_at DESC LIMIT 1) m ON true
  WHERE c.organization_id = p_organization_id
    AND ((SELECT ur.role FROM public.user_roles ur WHERE ur.user_id = auth.uid() AND ur.organization_id = p_organization_id LIMIT 1) IN ('owner', 'admin')
      OR ((SELECT e.id FROM public.employees e WHERE e.user_id = auth.uid() AND e.organization_id = p_organization_id LIMIT 1) IS NOT NULL
        AND (c.assignee_id = (SELECT e.id FROM public.employees e WHERE e.user_id = auth.uid() AND e.organization_id = p_organization_id LIMIT 1)
          OR (c.assignee_id IS NULL AND NOT public.lead_status_is_resolved_or_expired_visibility(c.lead_status_id))
          OR public.omnichannel_employee_sees_conversation(c.assignee_id, c.last_handling_assignee_id, c.lead_status_id, (SELECT e.id FROM public.employees e WHERE e.user_id = auth.uid() AND e.organization_id = p_organization_id LIMIT 1)))))
  ORDER BY m.created_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."get_threads_dm_conversations_with_preview"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_traffic_dashboard"("p_from" "text", "p_to" "text", "p_web_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  d_from date;
  d_to date;
  w text;
begin
  if not exists (select 1 from public.cms_admins c where c.user_id = auth.uid()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;

  if p_from is null or btrim(p_from) = '' or p_to is null or btrim(p_to) = '' then
    raise exception 'p_from and p_to required' using errcode = '22023';
  end if;

  d_from := left(btrim(p_from), 10)::date;
  d_to := left(btrim(p_to), 10)::date;

  if d_to < d_from then
    raise exception 'invalid range' using errcode = '22023';
  end if;

  w := public.hub_require_active_web_id(p_web_id, true);

  return jsonb_build_object(
    'source_breakdown',
    coalesce(
      (
        select jsonb_agg(to_jsonb(t) order by t.day, t.web_id, t.source_key)
        from (
          select
            sdb.web_id,
            sdb.day,
            sdb.source_key,
            sdb.sessions_count
          from public.analytics_daily_source_breakdown sdb
          where sdb.day between d_from and d_to
            and (w is null or sdb.web_id = w)
        ) t
      ),
      '[]'::jsonb
    ),
    'utm_rows',
    coalesce(
      (
        select jsonb_agg(to_jsonb(u) order by u.day desc, u.sessions_count desc)
        from (
          select
            uu.web_id,
            uu.day,
            uu.utm_source,
            uu.utm_medium,
            uu.utm_campaign,
            uu.utm_content,
            uu.utm_term,
            uu.route,
            uu.sessions_count
          from public.analytics_daily_utm uu
          where uu.day between d_from and d_to
            and (w is null or uu.web_id = w)
        ) u
      ),
      '[]'::jsonb
    ),
    'p_from', d_from,
    'p_to', d_to,
    'p_web_id', w
  );
end;
$$;


ALTER FUNCTION "public"."get_traffic_dashboard"("p_from" "text", "p_to" "text", "p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_traffic_dashboard"("p_from" "text", "p_to" "text", "p_web_id" "text") IS 'CMS Traffic page: JSON with source_breakdown + utm_rows (incl. route) from analytics_daily_*. Requires cms_admins.';



CREATE OR REPLACE FUNCTION "public"."get_traffic_dashboard"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer DEFAULT 15, "p_top_clicks_limit" integer DEFAULT 15, "p_utm_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  base_payload jsonb;
  utm_table jsonb;
  v_from date;
  v_to date;
BEGIN
  base_payload := public.get_traffic_dashboard_base_before_hybrid_utm(
    p_web_id,
    p_from,
    p_to,
    p_top_pages_limit,
    p_top_clicks_limit,
    p_utm_limit
  );

  v_from := NULLIF(base_payload->>'from', '')::date;
  v_to := NULLIF(base_payload->>'to', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN base_payload;
  END IF;

  WITH
    active_sessions AS (
      SELECT DISTINCT pv.session_id
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      UNION
      SELECT DISTINCT ce.session_id
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    session_attribution AS (
      SELECT
        s.id AS session_id,
        COALESCE(NULLIF(btrim(s.visitor_id), ''), s.id::text) AS visit_key,
        NULLIF(btrim(s.visitor_id), '') AS visitor_id,
        public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS first_landing_url,
        public.traffic_effective_utm_source(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_source_eff,
        public.traffic_effective_utm_medium(
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_medium_eff,
        public.traffic_effective_utm_campaign(
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_campaign_eff,
        public.traffic_effective_utm_content(
          s.first_utm_content, s.utm_content, s.last_utm_content,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_content_eff,
        public.traffic_effective_utm_term(
          s.first_utm_term, s.utm_term, s.last_utm_term,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_term_eff,
        public.traffic_classify_session_source_key(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          s.first_utm_content, s.utm_content, s.last_utm_content,
          s.first_utm_term, s.utm_term, s.last_utm_term,
          s.first_landing_url, s.landing_url, s.last_landing_url,
          s.has_gclid, s.first_has_gclid, s.last_has_gclid,
          s.has_fbclid, s.first_has_fbclid, s.last_has_fbclid,
          s.has_msclkid, s.has_gbraid, s.has_wbraid,
          s.first_referrer, s.referrer, s.last_referrer
        ) AS source_key
      FROM public.analytics_sessions s
      INNER JOIN active_sessions act ON act.session_id = s.id
      WHERE s.web_id = p_web_id
    ),
    page_events AS (
      SELECT pv.session_id, pv.started_at AS occurred_at, pv.started_at AS page_view_at, NULL::timestamptz AS click_at
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    click_events AS (
      SELECT ce.session_id, ce.created_at AS occurred_at, NULL::timestamptz AS page_view_at, ce.created_at AS click_at
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    all_events AS (
      SELECT * FROM page_events
      UNION ALL
      SELECT * FROM click_events
    ),
    session_metrics AS (
      SELECT
        e.session_id,
        MIN(e.occurred_at) AS occurred_at,
        COUNT(*) FILTER (WHERE e.page_view_at IS NOT NULL)::bigint AS page_views,
        COUNT(*) FILTER (WHERE e.click_at IS NOT NULL)::bigint AS clicks
      FROM all_events e
      GROUP BY e.session_id
    ),
    scroll_metrics AS (
      SELECT pv.session_id, MAX(pv.scroll_max_pct)::double precision AS max_deep_scroll_pct
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND pv.scroll_max_pct IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY pv.session_id
    ),
    ranked_sessions AS (
      SELECT
        sa.visit_key,
        sa.visitor_id,
        sa.session_id,
        sm.occurred_at,
        coalesce(
          left(
            CASE
              WHEN lp.route_path = '' AND lp.had_landing_ref THEN '/'
              WHEN lp.route_path = '' THEN ''
              WHEN left(lp.route_path, 1) = '/' THEN lp.route_path
              ELSE '/' || lp.route_path
            END,
            512
          ),
          ''
        ) AS route,
        sa.utm_campaign_eff AS utm_campaign,
        sa.utm_source_eff AS utm_source,
        sa.utm_medium_eff AS utm_medium,
        sa.utm_content_eff AS utm_content,
        sa.utm_term_eff AS utm_term,
        COALESCE(sm.page_views, 0)::bigint AS page_views,
        COALESCE(sm.clicks, 0)::bigint AS clicks,
        sc.max_deep_scroll_pct
      FROM session_attribution sa
      INNER JOIN session_metrics sm ON sm.session_id = sa.session_id
      LEFT JOIN scroll_metrics sc ON sc.session_id = sa.session_id
      CROSS JOIN LATERAL (
        SELECT
          coalesce(
            trim(both '/' FROM regexp_replace(
              regexp_replace(coalesce(sa.first_landing_url, ''), '^https?://[^/]+', '', 'i'),
              '[?#].*$',
              ''
            )),
            ''
          ) AS route_path,
          nullif(btrim(sa.first_landing_url), '') IS NOT NULL AS had_landing_ref
      ) lp
      WHERE sa.source_key IN ('utm', 'paid_click_ids')
      ORDER BY sm.occurred_at DESC, sa.session_id
      LIMIT GREATEST(1, LEAST(p_utm_limit, 2000))
    )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'row_kind', 'session',
    'visit_key', visit_key,
    'visitor_id', visitor_id,
    'session_id', session_id,
    'parent_session_id', session_id,
    'page_view_id', NULL,
    'occurred_at', occurred_at,
    'time_label', to_char(occurred_at AT TIME ZONE 'Asia/Jakarta', 'DD Mon YYYY HH24:MI'),
    'day', (occurred_at AT TIME ZONE 'Asia/Jakarta')::date,
    'route', NULLIF(route, ''),
    'utm_campaign', utm_campaign,
    'utm_source', utm_source,
    'utm_medium', utm_medium,
    'utm_content', utm_content,
    'utm_term', utm_term,
    'sessions', 1,
    'page_views', page_views,
    'clicks', clicks,
    'max_deep_scroll_pct', max_deep_scroll_pct,
    'avg_max_deep_scroll_pct', max_deep_scroll_pct,
    'scroll_sessions', CASE WHEN max_deep_scroll_pct IS NULL THEN 0 ELSE 1 END
  ) ORDER BY occurred_at DESC, session_id), '[]'::jsonb)
  INTO utm_table
  FROM ranked_sessions;

  RETURN jsonb_set(base_payload, '{utm_table}', utm_table, true);
END;
$_$;


ALTER FUNCTION "public"."get_traffic_dashboard"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_traffic_dashboard"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) IS 'Dashboard RPC; UTM table session-only (one row per UTM/paid session, first-touch attribution).';



CREATE OR REPLACE FUNCTION "public"."get_traffic_dashboard_base_before_first_touch_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer DEFAULT 15, "p_top_clicks_limit" integer DEFAULT 15, "p_utm_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  base_payload jsonb;
  top_pages jsonb;
  v_from date;
  v_to date;
BEGIN
  base_payload := public.get_traffic_dashboard_base_before_top_pages_visitor_id_basis(
    p_web_id,
    p_from,
    p_to,
    p_top_pages_limit,
    p_top_clicks_limit,
    p_utm_limit
  );

  v_from := NULLIF(base_payload->>'from', '')::date;
  v_to := NULLIF(base_payload->>'to', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN base_payload;
  END IF;

  WITH
    page_events AS (
      SELECT
        public.traffic_path_key(pv.path) AS path,
        COALESCE(NULLIF(btrim(pv.visitor_id), ''), NULLIF(btrim(s.visitor_id), ''), pv.session_id::text) AS visit_key,
        COALESCE(pv.active_ms, 0)::bigint AS active_ms,
        pv.scroll_max_pct
      FROM public.analytics_page_views pv
      LEFT JOIN public.analytics_sessions s
        ON s.id = pv.session_id AND s.web_id = pv.web_id
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    base AS (
      SELECT
        path,
        COUNT(*)::bigint AS impr,
        COUNT(DISTINCT visit_key)::bigint AS unique_sessions,
        COALESCE(percentile_cont(0.5) WITHIN GROUP (ORDER BY active_ms), 0)::bigint AS median_active_ms,
        CASE
          WHEN COUNT(*) = 0 THEN 0
          ELSE (SUM(active_ms) / NULLIF(COUNT(*), 0))::bigint
        END AS avg_active_ms
      FROM page_events
      WHERE path IS NOT NULL
      GROUP BY path
      ORDER BY COUNT(*) DESC
      LIMIT GREATEST(1, LEAST(p_top_pages_limit, 100))
    ),
    clicks_by_path AS (
      SELECT
        public.traffic_path_key(ce.path) AS path,
        COUNT(*)::bigint AS clicks
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY public.traffic_path_key(ce.path)
    ),
    click_targets_agg AS (
      SELECT
        t.path,
        t.track_key,
        t.element_type,
        t.element_label,
        t.target_url,
        t.is_internal
      FROM (
        SELECT
          public.traffic_path_key(ce.path) AS path,
          ce.track_key,
          ce.element_type,
          ce.element_label,
          ce.target_url,
          ce.is_internal,
          COUNT(*)::bigint AS clicks,
          ROW_NUMBER() OVER (
            PARTITION BY public.traffic_path_key(ce.path)
            ORDER BY COUNT(*) DESC, COALESCE(ce.is_internal, false) DESC, ce.target_url ASC
          ) AS rn
        FROM public.analytics_click_events ce
        WHERE ce.web_id = p_web_id
          AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
        GROUP BY
          public.traffic_path_key(ce.path),
          ce.track_key,
          ce.element_type,
          ce.element_label,
          ce.target_url,
          ce.is_internal
      ) t
      WHERE t.rn = 1
    ),
    per_visit_path_scroll AS (
      SELECT
        path,
        visit_key,
        MAX(scroll_max_pct)::double precision AS max_scroll_pct
      FROM page_events
      WHERE scroll_max_pct IS NOT NULL
        AND path IS NOT NULL
      GROUP BY path, visit_key
    ),
    scroll_by_path AS (
      SELECT
        path,
        MAX(max_scroll_pct)::double precision AS max_deep_scroll_pct,
        AVG(max_scroll_pct)::double precision AS avg_max_deep_scroll_pct
      FROM per_visit_path_scroll
      GROUP BY path
    )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'path', b.path,
    'impr', b.impr,
    'unique_sessions', b.unique_sessions,
    'clicks', COALESCE(c.clicks, 0),
    'median_active_ms', b.median_active_ms,
    'avg_active_ms', b.avg_active_ms,
    'n', b.unique_sessions,
    'max_deep_scroll_pct', sc.max_deep_scroll_pct,
    'avg_max_deep_scroll_pct', sc.avg_max_deep_scroll_pct,
    'click_event_name', 'click',
    'click_track_key', NULLIF(ct.track_key, ''),
    'click_element_type', ct.element_type,
    'click_element_label', ct.element_label,
    'click_target_url', NULLIF(ct.target_url, ''),
    'click_is_internal', ct.is_internal
  ) ORDER BY b.impr DESC), '[]'::jsonb)
  INTO top_pages
  FROM base b
  LEFT JOIN clicks_by_path c ON c.path = b.path
  LEFT JOIN click_targets_agg ct ON ct.path = b.path
  LEFT JOIN scroll_by_path sc ON sc.path = b.path;

  RETURN jsonb_set(base_payload, '{top_pages}', top_pages, true);
END;
$$;


ALTER FUNCTION "public"."get_traffic_dashboard_base_before_first_touch_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_traffic_dashboard_base_before_first_touch_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) IS 'Dashboard RPC wrapper; Top pages unique sessions use visitor_id with session_id fallback.';



CREATE OR REPLACE FUNCTION "public"."get_traffic_dashboard_base_before_hybrid_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer DEFAULT 15, "p_top_clicks_limit" integer DEFAULT 15, "p_utm_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  base_payload jsonb;
  source_breakdown jsonb;
  utm_table jsonb;
  unified_sessions bigint;
  unified_page_views bigint;
  unified_clicks bigint;
  v_from date;
  v_to date;
BEGIN
  base_payload := public.get_traffic_dashboard_base_before_first_touch_utm(
    p_web_id,
    p_from,
    p_to,
    p_top_pages_limit,
    p_top_clicks_limit,
    p_utm_limit
  );

  v_from := NULLIF(base_payload->>'from', '')::date;
  v_to := NULLIF(base_payload->>'to', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN base_payload;
  END IF;

  WITH
    active_sessions AS (
      SELECT DISTINCT pv.session_id
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      UNION
      SELECT DISTINCT ce.session_id
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    session_attribution AS (
      SELECT
        s.id AS session_id,
        s.web_id,
        COALESCE(NULLIF(btrim(s.visitor_id), ''), s.id::text) AS visit_key,
        NULLIF(btrim(s.visitor_id), '') AS visitor_id,
        public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS first_landing_url,
        public.traffic_effective_utm_source(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_source_eff,
        public.traffic_effective_utm_medium(
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_medium_eff,
        public.traffic_effective_utm_campaign(
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_campaign_eff,
        public.traffic_effective_utm_content(
          s.first_utm_content, s.utm_content, s.last_utm_content,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_content_eff,
        public.traffic_effective_utm_term(
          s.first_utm_term, s.utm_term, s.last_utm_term,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_term_eff,
        public.traffic_classify_session_source_key(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          s.first_utm_content, s.utm_content, s.last_utm_content,
          s.first_utm_term, s.utm_term, s.last_utm_term,
          s.first_landing_url, s.landing_url, s.last_landing_url,
          s.has_gclid, s.first_has_gclid, s.last_has_gclid,
          s.has_fbclid, s.first_has_fbclid, s.last_has_fbclid,
          s.has_msclkid, s.has_gbraid, s.has_wbraid,
          s.first_referrer, s.referrer, s.last_referrer
        ) AS source_key
      FROM public.analytics_sessions s
      INNER JOIN active_sessions act ON act.session_id = s.id
      WHERE s.web_id = p_web_id
    ),
    page_events AS (
      SELECT
        pv.session_id,
        pv.started_at AS occurred_at,
        pv.started_at AS page_view_at,
        NULL::timestamptz AS click_at,
        pv.active_ms,
        pv.scroll_max_pct,
        pv.ended_at,
        pv.started_at
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    click_events AS (
      SELECT
        ce.session_id,
        ce.created_at AS occurred_at,
        NULL::timestamptz AS page_view_at,
        ce.created_at AS click_at,
        NULL::bigint AS active_ms,
        NULL::double precision AS scroll_max_pct,
        NULL::timestamptz AS ended_at,
        ce.created_at AS started_at
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    all_events AS (
      SELECT * FROM page_events
      UNION ALL
      SELECT * FROM click_events
    ),
    session_metrics AS (
      SELECT
        e.session_id,
        MIN(e.occurred_at) AS occurred_at,
        COUNT(*) FILTER (WHERE e.page_view_at IS NOT NULL)::bigint AS page_views,
        COUNT(*) FILTER (WHERE e.click_at IS NOT NULL)::bigint AS clicks
      FROM all_events e
      GROUP BY e.session_id
    ),
    scroll_metrics AS (
      SELECT
        pv.session_id,
        MAX(pv.scroll_max_pct)::double precision AS max_deep_scroll_pct
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND pv.scroll_max_pct IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY pv.session_id
    ),
    enriched AS (
      SELECT
        sa.session_id,
        sa.visit_key,
        sa.visitor_id,
        sa.source_key,
        sm.occurred_at,
        sm.page_views,
        sm.clicks,
        sc.max_deep_scroll_pct,
        sa.first_landing_url,
        sa.utm_source_eff,
        sa.utm_medium_eff,
        sa.utm_campaign_eff,
        sa.utm_content_eff,
        sa.utm_term_eff
      FROM session_attribution sa
      INNER JOIN session_metrics sm ON sm.session_id = sa.session_id
      LEFT JOIN scroll_metrics sc ON sc.session_id = sa.session_id
    )
  SELECT
    COUNT(*)::bigint,
    COALESCE(SUM(page_views), 0)::bigint,
    COALESCE(SUM(clicks), 0)::bigint
  INTO unified_sessions, unified_page_views, unified_clicks
  FROM enriched;

  WITH
    active_sessions AS (
      SELECT DISTINCT pv.session_id
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      UNION
      SELECT DISTINCT ce.session_id
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    session_attribution AS (
      SELECT
        s.id AS session_id,
        s.web_id,
        COALESCE(NULLIF(btrim(s.visitor_id), ''), s.id::text) AS visit_key,
        NULLIF(btrim(s.visitor_id), '') AS visitor_id,
        public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS first_landing_url,
        public.traffic_effective_utm_source(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_source_eff,
        public.traffic_effective_utm_medium(
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_medium_eff,
        public.traffic_effective_utm_campaign(
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_campaign_eff,
        public.traffic_effective_utm_content(
          s.first_utm_content, s.utm_content, s.last_utm_content,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_content_eff,
        public.traffic_effective_utm_term(
          s.first_utm_term, s.utm_term, s.last_utm_term,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_term_eff,
        public.traffic_classify_session_source_key(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          s.first_utm_content, s.utm_content, s.last_utm_content,
          s.first_utm_term, s.utm_term, s.last_utm_term,
          s.first_landing_url, s.landing_url, s.last_landing_url,
          s.has_gclid, s.first_has_gclid, s.last_has_gclid,
          s.has_fbclid, s.first_has_fbclid, s.last_has_fbclid,
          s.has_msclkid, s.has_gbraid, s.has_wbraid,
          s.first_referrer, s.referrer, s.last_referrer
        ) AS source_key
      FROM public.analytics_sessions s
      INNER JOIN active_sessions act ON act.session_id = s.id
      WHERE s.web_id = p_web_id
    ),
    page_events AS (
      SELECT
        pv.session_id,
        pv.started_at AS occurred_at,
        pv.started_at AS page_view_at,
        NULL::timestamptz AS click_at
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    click_events AS (
      SELECT
        ce.session_id,
        ce.created_at AS occurred_at,
        NULL::timestamptz AS page_view_at,
        ce.created_at AS click_at
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    all_events AS (
      SELECT * FROM page_events
      UNION ALL
      SELECT * FROM click_events
    ),
    session_metrics AS (
      SELECT
        e.session_id,
        MIN(e.occurred_at) AS occurred_at,
        COUNT(*) FILTER (WHERE e.page_view_at IS NOT NULL)::bigint AS page_views,
        COUNT(*) FILTER (WHERE e.click_at IS NOT NULL)::bigint AS clicks
      FROM all_events e
      GROUP BY e.session_id
    ),
    scroll_metrics AS (
      SELECT
        pv.session_id,
        MAX(pv.scroll_max_pct)::double precision AS max_deep_scroll_pct
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND pv.scroll_max_pct IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY pv.session_id
    ),
    enriched AS (
      SELECT
        sa.session_id,
        sa.visit_key,
        sa.visitor_id,
        sa.source_key,
        sm.occurred_at,
        sm.page_views,
        sm.clicks,
        sc.max_deep_scroll_pct,
        sa.first_landing_url,
        sa.utm_source_eff,
        sa.utm_medium_eff,
        sa.utm_campaign_eff,
        sa.utm_content_eff,
        sa.utm_term_eff
      FROM session_attribution sa
      INNER JOIN session_metrics sm ON sm.session_id = sa.session_id
      LEFT JOIN scroll_metrics sc ON sc.session_id = sa.session_id
    ),
    source_rows AS (
      SELECT
        source_key,
        COUNT(*)::bigint AS sessions,
        COALESCE(SUM(page_views), 0)::bigint AS page_views,
        COALESCE(SUM(clicks), 0)::bigint AS clicks,
        MAX(max_deep_scroll_pct)::double precision AS max_deep_scroll_pct,
        CASE
          WHEN COUNT(*) FILTER (WHERE max_deep_scroll_pct IS NOT NULL) = 0 THEN NULL
          ELSE (
            SUM(max_deep_scroll_pct) FILTER (WHERE max_deep_scroll_pct IS NOT NULL)
            / NULLIF(COUNT(*) FILTER (WHERE max_deep_scroll_pct IS NOT NULL), 0)
          )::double precision
        END AS avg_max_deep_scroll_pct,
        COUNT(*) FILTER (WHERE max_deep_scroll_pct IS NOT NULL)::bigint AS scroll_sessions
      FROM enriched
      GROUP BY source_key
    ),
    ordered AS (
      SELECT
        source_key,
        CASE source_key
          WHEN 'utm' THEN 'UTM / kampanye (minimal satu parameter utm_* terisi)'
          WHEN 'paid_click_ids' THEN 'Iklan berbayar (gclid / fbclid / msclkid / gbraid / wbraid) tanpa UTM lengkap'
          WHEN 'referral' THEN 'Rujukan (referrer terisi)'
          WHEN 'direct' THEN 'Langsung (tanpa referrer & tanpa UTM / click id)'
          ELSE source_key
        END AS label,
        sessions,
        page_views,
        clicks,
        max_deep_scroll_pct,
        avg_max_deep_scroll_pct,
        scroll_sessions,
        CASE source_key
          WHEN 'utm' THEN 1
          WHEN 'paid_click_ids' THEN 2
          WHEN 'referral' THEN 3
          WHEN 'direct' THEN 4
          ELSE 9
        END AS ord
      FROM source_rows
    )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'key', source_key,
    'label', label,
    'sessions', sessions,
    'page_views', page_views,
    'clicks', clicks,
    'max_deep_scroll_pct', max_deep_scroll_pct,
    'avg_max_deep_scroll_pct', avg_max_deep_scroll_pct,
    'scroll_sessions', scroll_sessions
  ) ORDER BY ord), '[]'::jsonb)
  INTO source_breakdown
  FROM ordered;

  WITH
    active_sessions AS (
      SELECT DISTINCT pv.session_id
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      UNION
      SELECT DISTINCT ce.session_id
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    session_attribution AS (
      SELECT
        s.id AS session_id,
        COALESCE(NULLIF(btrim(s.visitor_id), ''), s.id::text) AS visit_key,
        NULLIF(btrim(s.visitor_id), '') AS visitor_id,
        public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS first_landing_url,
        public.traffic_effective_utm_source(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_source_eff,
        public.traffic_effective_utm_medium(
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_medium_eff,
        public.traffic_effective_utm_campaign(
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_campaign_eff,
        public.traffic_effective_utm_content(
          s.first_utm_content, s.utm_content, s.last_utm_content,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_content_eff,
        public.traffic_effective_utm_term(
          s.first_utm_term, s.utm_term, s.last_utm_term,
          public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url)
        ) AS utm_term_eff,
        public.traffic_classify_session_source_key(
          s.first_utm_source, s.utm_source, s.last_utm_source,
          s.first_utm_medium, s.utm_medium, s.last_utm_medium,
          s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign,
          s.first_utm_content, s.utm_content, s.last_utm_content,
          s.first_utm_term, s.utm_term, s.last_utm_term,
          s.first_landing_url, s.landing_url, s.last_landing_url,
          s.has_gclid, s.first_has_gclid, s.last_has_gclid,
          s.has_fbclid, s.first_has_fbclid, s.last_has_fbclid,
          s.has_msclkid, s.has_gbraid, s.has_wbraid,
          s.first_referrer, s.referrer, s.last_referrer
        ) AS source_key
      FROM public.analytics_sessions s
      INNER JOIN active_sessions act ON act.session_id = s.id
      WHERE s.web_id = p_web_id
    ),
    page_events AS (
      SELECT pv.session_id, pv.started_at AS occurred_at, pv.started_at AS page_view_at, NULL::timestamptz AS click_at
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    click_events AS (
      SELECT ce.session_id, ce.created_at AS occurred_at, NULL::timestamptz AS page_view_at, ce.created_at AS click_at
      FROM public.analytics_click_events ce
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    all_events AS (
      SELECT * FROM page_events
      UNION ALL
      SELECT * FROM click_events
    ),
    session_metrics AS (
      SELECT
        e.session_id,
        MIN(e.occurred_at) AS occurred_at,
        COUNT(*) FILTER (WHERE e.page_view_at IS NOT NULL)::bigint AS page_views,
        COUNT(*) FILTER (WHERE e.click_at IS NOT NULL)::bigint AS clicks
      FROM all_events e
      GROUP BY e.session_id
    ),
    scroll_metrics AS (
      SELECT pv.session_id, MAX(pv.scroll_max_pct)::double precision AS max_deep_scroll_pct
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND pv.scroll_max_pct IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY pv.session_id
    ),
    session_rows AS (
      SELECT
        sa.visit_key,
        sa.visitor_id,
        sa.session_id,
        sm.occurred_at,
        coalesce(
          left(
            CASE
              WHEN lp.route_path = '' AND lp.had_landing_ref THEN '/'
              WHEN lp.route_path = '' THEN ''
              WHEN left(lp.route_path, 1) = '/' THEN lp.route_path
              ELSE '/' || lp.route_path
            END,
            512
          ),
          ''
        ) AS route,
        sa.utm_campaign_eff AS utm_campaign,
        sa.utm_source_eff AS utm_source,
        sa.utm_medium_eff AS utm_medium,
        sa.utm_content_eff AS utm_content,
        sa.utm_term_eff AS utm_term,
        COALESCE(sm.page_views, 0)::bigint AS page_views,
        COALESCE(sm.clicks, 0)::bigint AS clicks,
        sc.max_deep_scroll_pct
      FROM session_attribution sa
      INNER JOIN session_metrics sm ON sm.session_id = sa.session_id
      LEFT JOIN scroll_metrics sc ON sc.session_id = sa.session_id
      CROSS JOIN LATERAL (
        SELECT
          coalesce(
            trim(both '/' FROM regexp_replace(
              regexp_replace(coalesce(sa.first_landing_url, ''), '^https?://[^/]+', '', 'i'),
              '[?#].*$',
              ''
            )),
            ''
          ) AS route_path,
          nullif(btrim(sa.first_landing_url), '') IS NOT NULL AS had_landing_ref
      ) lp
      WHERE sa.source_key IN ('utm', 'paid_click_ids')
      ORDER BY sm.occurred_at DESC, sa.session_id
      LIMIT GREATEST(1, LEAST(p_utm_limit, 2000))
    )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'visit_key', visit_key,
    'visitor_id', visitor_id,
    'session_id', session_id,
    'occurred_at', occurred_at,
    'time_label', to_char(occurred_at AT TIME ZONE 'Asia/Jakarta', 'DD Mon YYYY HH24:MI'),
    'day', (occurred_at AT TIME ZONE 'Asia/Jakarta')::date,
    'route', NULLIF(route, ''),
    'utm_campaign', utm_campaign,
    'utm_source', utm_source,
    'utm_medium', utm_medium,
    'utm_content', utm_content,
    'utm_term', utm_term,
    'sessions', 1,
    'page_views', page_views,
    'clicks', clicks,
    'max_deep_scroll_pct', max_deep_scroll_pct,
    'avg_max_deep_scroll_pct', max_deep_scroll_pct,
    'scroll_sessions', CASE WHEN max_deep_scroll_pct IS NULL THEN 0 ELSE 1 END
  ) ORDER BY occurred_at DESC, session_id), '[]'::jsonb)
  INTO utm_table
  FROM session_rows;

  RETURN jsonb_set(
    jsonb_set(
      jsonb_set(
        jsonb_set(
          jsonb_set(base_payload, '{source_breakdown}', source_breakdown, true),
          '{kpis,clicks}',
          to_jsonb(COALESCE(unified_clicks, 0)),
          true
        ),
        '{kpis,sessions}',
        to_jsonb(COALESCE(unified_sessions, 0)),
        true
      ),
      '{kpis,page_views}',
      to_jsonb(COALESCE(unified_page_views, 0)),
      true
    ),
    '{utm_table}',
    utm_table,
    true
  );
END;
$_$;


ALTER FUNCTION "public"."get_traffic_dashboard_base_before_hybrid_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_traffic_dashboard_base_before_hybrid_utm"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer, "p_top_clicks_limit" integer, "p_utm_limit" integer) IS 'Dashboard RPC; UTM Tracking and source breakdown use first-touch session attribution (SPA-safe).';



CREATE OR REPLACE FUNCTION "public"."get_traffic_dashboard_base_before_top_pages_visitor_id_basis"("p_web_id" "text", "p_from" "date", "p_to" "date", "p_top_pages_limit" integer DEFAULT 15, "p_top_clicks_limit" integer DEFAULT 15, "p_utm_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  base_payload jsonb;
  source_breakdown jsonb;
  utm_table jsonb;
  unified_sessions bigint;
  unified_page_views bigint;
  unified_clicks bigint;
  v_from date;
  v_to date;
BEGIN
  base_payload := public.get_traffic_dashboard_base_before_visitor_id_basis(
    p_web_id,
    p_from,
    p_to,
    p_top_pages_limit,
    p_top_clicks_limit,
    p_utm_limit
  );

  v_from := NULLIF(base_payload->>'from', '')::date;
  v_to := NULLIF(base_payload->>'to', '')::date;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN base_payload;
  END IF;

  WITH
    candidate_events AS (
      SELECT
        pv.web_id,
        COALESCE(NULLIF(btrim(pv.visitor_id), ''), NULLIF(btrim(s.visitor_id), ''), pv.session_id::text) AS visit_key,
        COALESCE(NULLIF(btrim(pv.visitor_id), ''), NULLIF(btrim(s.visitor_id), '')) AS visitor_id,
        pv.session_id,
        pv.started_at AS occurred_at,
        pv.started_at AS page_view_at,
        NULL::timestamptz AS click_at,
        coalesce(nullif(btrim(s.last_landing_url), ''), nullif(btrim(s.landing_url), '')) AS landing_url,
        coalesce(nullif(btrim(s.last_landing_url), ''), nullif(btrim(s.landing_url), ''), nullif(btrim(s.first_landing_url), '')) AS route_landing_url,
        coalesce(nullif(btrim(s.last_utm_source), ''), nullif(btrim(s.utm_source), '')) AS utm_source,
        coalesce(nullif(btrim(s.last_utm_medium), ''), nullif(btrim(s.utm_medium), '')) AS utm_medium,
        coalesce(nullif(btrim(s.last_utm_campaign), ''), nullif(btrim(s.utm_campaign), '')) AS utm_campaign,
        coalesce(nullif(btrim(s.last_utm_content), ''), nullif(btrim(s.utm_content), '')) AS utm_content,
        coalesce(nullif(btrim(s.last_utm_term), ''), nullif(btrim(s.utm_term), '')) AS utm_term,
        (coalesce(s.has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
        (coalesce(s.has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
        (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
        (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
        (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
        coalesce(nullif(btrim(s.last_referrer), ''), nullif(btrim(s.referrer), '')) AS referrer,
        coalesce(pv.active_ms, 0) > 0
          OR coalesce(pv.scroll_max_pct, 0) >= 5
          OR (pv.ended_at IS NOT NULL AND extract(epoch FROM (pv.ended_at - pv.started_at)) >= 5) AS is_human_page_view
      FROM public.analytics_page_views pv
      LEFT JOIN public.analytics_sessions s
        ON s.id = pv.session_id AND s.web_id = pv.web_id
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to

      UNION ALL

      SELECT
        ce.web_id,
        COALESCE(NULLIF(btrim(ce.visitor_id), ''), NULLIF(btrim(s.visitor_id), ''), ce.session_id::text) AS visit_key,
        COALESCE(NULLIF(btrim(ce.visitor_id), ''), NULLIF(btrim(s.visitor_id), '')) AS visitor_id,
        ce.session_id,
        ce.created_at AS occurred_at,
        NULL::timestamptz AS page_view_at,
        ce.created_at AS click_at,
        coalesce(nullif(btrim(s.last_landing_url), ''), nullif(btrim(s.landing_url), '')) AS landing_url,
        coalesce(nullif(btrim(s.last_landing_url), ''), nullif(btrim(s.landing_url), ''), nullif(btrim(s.first_landing_url), '')) AS route_landing_url,
        coalesce(nullif(btrim(s.last_utm_source), ''), nullif(btrim(s.utm_source), '')) AS utm_source,
        coalesce(nullif(btrim(s.last_utm_medium), ''), nullif(btrim(s.utm_medium), '')) AS utm_medium,
        coalesce(nullif(btrim(s.last_utm_campaign), ''), nullif(btrim(s.utm_campaign), '')) AS utm_campaign,
        coalesce(nullif(btrim(s.last_utm_content), ''), nullif(btrim(s.utm_content), '')) AS utm_content,
        coalesce(nullif(btrim(s.last_utm_term), ''), nullif(btrim(s.utm_term), '')) AS utm_term,
        (coalesce(s.has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
        (coalesce(s.has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
        (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
        (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
        (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
        coalesce(nullif(btrim(s.last_referrer), ''), nullif(btrim(s.referrer), '')) AS referrer,
        false AS is_human_page_view
      FROM public.analytics_click_events ce
      LEFT JOIN public.analytics_sessions s
        ON s.id = ce.session_id AND s.web_id = ce.web_id
      WHERE ce.web_id = p_web_id
        AND ce.session_id IS NOT NULL
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
    ),
    visit_base AS (
      SELECT DISTINCT ON (visit_key)
        web_id,
        visit_key,
        visitor_id,
        session_id,
        occurred_at,
        landing_url,
        route_landing_url,
        utm_source,
        utm_medium,
        utm_campaign,
        utm_content,
        utm_term,
        has_gclid,
        has_fbclid,
        has_msclkid,
        has_gbraid,
        has_wbraid,
        referrer
      FROM candidate_events
      ORDER BY visit_key, is_human_page_view DESC, occurred_at ASC
    ),
    effective AS (
      SELECT
        web_id,
        visit_key,
        visitor_id,
        session_id,
        occurred_at,
        route_landing_url,
        coalesce(nullif(btrim(utm_source), ''), nullif(trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_source=([^&]*)'))[1]), '')) AS utm_source_eff,
        coalesce(nullif(btrim(utm_medium), ''), nullif(trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_medium=([^&]*)'))[1]), '')) AS utm_medium_eff,
        coalesce(nullif(btrim(utm_campaign), ''), nullif(trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_campaign=([^&]*)'))[1]), '')) AS utm_campaign_eff,
        coalesce(nullif(btrim(utm_content), ''), nullif(trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_content=([^&]*)'))[1]), '')) AS utm_content_eff,
        coalesce(nullif(btrim(utm_term), ''), nullif(trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_term=([^&]*)'))[1]), '')) AS utm_term_eff,
        has_gclid,
        has_fbclid,
        has_msclkid,
        has_gbraid,
        has_wbraid,
        referrer
      FROM visit_base
    ),
    classified AS (
      SELECT
        e.*,
        CASE
          WHEN e.has_gclid OR e.has_fbclid OR e.has_msclkid OR e.has_gbraid OR e.has_wbraid THEN 'paid_click_ids'
          WHEN
            nullif(btrim(e.utm_source_eff), '') IS NOT NULL
            OR nullif(btrim(e.utm_medium_eff), '') IS NOT NULL
            OR nullif(btrim(e.utm_campaign_eff), '') IS NOT NULL
            OR nullif(btrim(e.utm_content_eff), '') IS NOT NULL
            OR nullif(btrim(e.utm_term_eff), '') IS NOT NULL
            THEN 'utm'
          WHEN nullif(btrim(e.referrer), '') IS NOT NULL THEN 'referral'
          ELSE 'direct'
        END AS source_key
      FROM effective e
    ),
    event_metrics AS (
      SELECT
        visit_key,
        COUNT(*) FILTER (WHERE page_view_at IS NOT NULL)::bigint AS page_views,
        COUNT(*) FILTER (WHERE click_at IS NOT NULL)::bigint AS clicks
      FROM candidate_events
      GROUP BY visit_key
    ),
    scroll_metrics AS (
      SELECT
        COALESCE(NULLIF(btrim(pv.visitor_id), ''), NULLIF(btrim(s.visitor_id), ''), pv.session_id::text) AS visit_key,
        MAX(pv.scroll_max_pct)::double precision AS max_deep_scroll_pct
      FROM public.analytics_page_views pv
      LEFT JOIN public.analytics_sessions s
        ON s.id = pv.session_id AND s.web_id = pv.web_id
      WHERE pv.web_id = p_web_id
        AND pv.session_id IS NOT NULL
        AND pv.scroll_max_pct IS NOT NULL
        AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_from AND v_to
      GROUP BY COALESCE(NULLIF(btrim(pv.visitor_id), ''), NULLIF(btrim(s.visitor_id), ''), pv.session_id::text)
    ),
    enriched AS (
      SELECT
        c.*,
        COALESCE(em.page_views, 0)::bigint AS page_views,
        COALESCE(em.clicks, 0)::bigint AS clicks,
        sm.max_deep_scroll_pct
      FROM classified c
      LEFT JOIN event_metrics em ON em.visit_key = c.visit_key
      LEFT JOIN scroll_metrics sm ON sm.visit_key = c.visit_key
    )
  SELECT
    COUNT(*)::bigint,
    COALESCE(SUM(page_views), 0)::bigint,
    COALESCE(SUM(clicks), 0)::bigint
  INTO unified_sessions, unified_page_views, unified_clicks
  FROM enriched;

  WITH
    candidate_events AS (
