CREATE OR REPLACE FUNCTION "public"."get_whatsapp_conversation_ids_by_message_search"("p_organization_id" "uuid", "p_search" "text") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.get_whatsapp_conversation_ids_by_message_search__impl(p_organization_id, p_search);
END;
$$;


ALTER FUNCTION "public"."get_whatsapp_conversation_ids_by_message_search"("p_organization_id" "uuid", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_whatsapp_conversation_ids_by_message_search__impl"("p_organization_id" "uuid", "p_search" "text") RETURNS SETOF "uuid"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT DISTINCT c.id
  FROM whatsapp_conversations c
  INNER JOIN whatsapp_messages m ON m.conversation_id = c.id
  WHERE c.organization_id = p_organization_id
    AND p_search IS NOT NULL
    AND length(trim(p_search)) > 0
    AND m.body IS NOT NULL
    AND m.body ILIKE '%' || trim(p_search) || '%';
$$;


