CREATE OR REPLACE FUNCTION "public"."get_whatsapp_conversations_with_preview"("p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "customer_wa_id" "text", "customer_name" "text", "last_message_at" timestamp with time zone, "last_message_body" "text", "last_message_direction" "text", "last_message_status" "text", "lead_status_id" "uuid", "lead_status_name" "text", "channel" "text", "phone_number_id" "text", "whatsapp_account_display_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id,
    c.organization_id,
    c.customer_wa_id,
    c.customer_name,
    m.created_at AS last_message_at,
    LEFT(m.body, 200) AS last_message_body,
    m.direction AS last_message_direction,
    m.status AS last_message_status,
    c.lead_status_id,
    ls.name AS lead_status_name,
    COALESCE(c.channel, 'whatsapp') AS channel,
    c.phone_number_id,
    COALESCE(
      NULLIF(TRIM(a.whatsapp_business_name), ''),
      NULLIF(TRIM(a.display_phone_number), ''),
      a.phone_number_id
    )::TEXT AS whatsapp_account_display_name,
    c.created_at,
    c.updated_at
  FROM public.whatsapp_conversations c
  LEFT JOIN public.lead_statuses ls ON ls.id = c.lead_status_id
  LEFT JOIN public.organization_whatsapp_accounts a
    ON a.organization_id = c.organization_id
   AND a.phone_number_id = c.phone_number_id
   AND a.is_active = true
  LEFT JOIN LATERAL (
    SELECT created_at, body, direction, status
    FROM public.whatsapp_messages
    WHERE conversation_id = c.id
    ORDER BY created_at DESC
    LIMIT 1
  ) m ON true
  WHERE c.organization_id = p_organization_id
    AND COALESCE(c.channel, 'whatsapp') = 'whatsapp'
    AND (
      (
        SELECT ur.role
        FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.organization_id = p_organization_id
        LIMIT 1
      ) IN ('owner', 'admin')
      OR public.omnichannel_employee_sees_conversation(
        c.assignee_id,
        c.last_handling_assignee_id,
        c.lead_status_id,
        (
          SELECT e.id
          FROM public.employees e
          WHERE e.user_id = auth.uid()
            AND e.organization_id = p_organization_id
          LIMIT 1
        )
      )
    )
  ORDER BY m.created_at DESC NULLS LAST;
$$;


ALTER FUNCTION "public"."get_whatsapp_conversations_with_preview"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."get_whatsapp_conversations_with_preview"("p_organization_id" "uuid") IS 'WhatsApp conversations with preview. Owner/Admin see all; Employee sees active assignee OR resolved/expired they closed (last_handling_assignee_id).';



