CREATE OR REPLACE FUNCTION "public"."get_whatsapp_cycle_metrics__impl"("p_organization_id" "uuid") RETURNS TABLE("conversation_id" "uuid", "assignee_id" "uuid", "cycle_started_at" timestamp with time zone, "first_response_at" timestamp with time zone, "resolved_at" timestamp with time zone, "channel" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    cy.conversation_id,
    c.assignee_id,
    cy.cycle_started_at,
    cy.first_response_at,
    cy.resolved_at,
    COALESCE(NULLIF(lower(trim(c.channel)), ''), 'whatsapp') AS channel
  FROM public.whatsapp_conversation_cycles cy
  JOIN public.whatsapp_conversations c ON c.id = cy.conversation_id
  WHERE c.organization_id = p_organization_id
  UNION ALL
  SELECT
    cy.conversation_id,
    c.assignee_id,
    cy.cycle_started_at,
    cy.first_response_at,
    cy.resolved_at,
    'facebook'::text AS channel
  FROM public.facebook_conversation_cycles cy
  JOIN public.facebook_conversations c ON c.id = cy.conversation_id
  WHERE c.organization_id = p_organization_id
  ORDER BY cycle_started_at DESC;
$$;


