CREATE OR REPLACE FUNCTION "public"."handle_expense_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_debt_record record;
BEGIN
  IF OLD.withdrawal_from_balance IS NULL THEN
    RETURN OLD;
  END IF;

  SELECT debt_type INTO v_debt_record FROM public.debts WHERE id = OLD.withdrawal_from_balance;

  UPDATE public.debts
  SET
    available_limit = coalesce(available_limit, limit_amount) + OLD.amount,
    debt_amount = CASE
      WHEN v_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
      ELSE greatest(0, coalesce(debt_amount, 0) - OLD.amount)
    END,
    updated_at = now()
  WHERE id = OLD.withdrawal_from_balance;

  IF v_debt_record.debt_type = 'Pinjaman Online' THEN
    PERFORM public.recalculate_pinjaman_online_debt_amount (OLD.withdrawal_from_balance);
  END IF;

  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."handle_expense_delete"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_expense_delete"() IS 'AFTER DELETE: reverse debt + recalculate Pinjaman Online (reference).';



CREATE OR REPLACE FUNCTION "public"."handle_expense_gateway_wallet_debit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_usable numeric;
BEGIN
  IF NEW.gateway_wallet_provider IS NULL OR NEW.amount IS NULL OR NEW.amount <= 0 THEN
    RETURN NEW;
  END IF;

  IF NEW.purchase_request_id IS NOT NULL THEN
    IF NEW.gateway_wallet_provider = 'xendit' AND EXISTS (
      SELECT 1 FROM public.xendit_disbursements xd
      WHERE xd.source_type = 'purchase_request'
        AND xd.source_id = NEW.purchase_request_id
        AND xd.status = 'completed'
    ) THEN
      RETURN NEW;
    END IF;

    IF NEW.gateway_wallet_provider = 'brick' AND EXISTS (
      SELECT 1 FROM public.brick_disbursements bd
      WHERE bd.source_type = 'purchase_request'
        AND bd.source_id = NEW.purchase_request_id
        AND bd.status = 'completed'
    ) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF NEW.payroll_run_id IS NOT NULL AND NEW.gateway_wallet_provider = 'xendit' AND EXISTS (
    SELECT 1 FROM public.xendit_disbursements xd
    JOIN public.employee_payroll_calculations c ON c.id = xd.source_id
    WHERE xd.source_type = 'payroll_calculation'
      AND c.payroll_run_id = NEW.payroll_run_id
      AND xd.status = 'completed'
  ) THEN
    RETURN NEW;
  END IF;

  SELECT usable_balance INTO v_usable
  FROM public.organization_gateway_wallets
  WHERE organization_id = NEW.organization_id
    AND provider = NEW.gateway_wallet_provider
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Gateway wallet not configured for provider %', NEW.gateway_wallet_provider;
  END IF;

  IF v_usable < NEW.amount THEN
    RAISE EXCEPTION 'Insufficient gateway wallet balance (provider %, available %, required %)',
      NEW.gateway_wallet_provider, v_usable, NEW.amount;
  END IF;

  UPDATE public.organization_gateway_wallets
  SET
    usable_balance = usable_balance - NEW.amount,
    total_balance = GREATEST(0, total_balance - NEW.amount),
    updated_at = now()
  WHERE organization_id = NEW.organization_id
    AND provider = NEW.gateway_wallet_provider;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_expense_gateway_wallet_debit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_expense_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_debt_record record;
BEGIN
  IF NEW.withdrawal_from_balance IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
  INTO v_debt_record
  FROM public.debts
  WHERE id = NEW.withdrawal_from_balance
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Debt with id % not found', NEW.withdrawal_from_balance;
  END IF;

  UPDATE public.debts
  SET
    available_limit = coalesce(available_limit, limit_amount) - NEW.amount,
    debt_amount = CASE
      WHEN v_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
      ELSE coalesce(debt_amount, 0) + NEW.amount
    END,
    updated_at = now()
  WHERE id = NEW.withdrawal_from_balance;

  IF v_debt_record.debt_type = 'Pinjaman Online' THEN
    PERFORM public.recalculate_pinjaman_online_debt_amount (NEW.withdrawal_from_balance);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_expense_insert"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_expense_insert"() IS 'AFTER INSERT: update debt + recalculate Pinjaman Online (reference).';



CREATE OR REPLACE FUNCTION "public"."handle_expense_soft_delete_debt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_debt_record record;
BEGIN
  IF OLD.status IS DISTINCT FROM 'active' OR NEW.status IS DISTINCT FROM 'deleted' THEN
    RETURN NEW;
  END IF;

  IF OLD.withdrawal_from_balance IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT debt_type INTO v_debt_record FROM public.debts WHERE id = OLD.withdrawal_from_balance;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  UPDATE public.debts
  SET
    available_limit = coalesce(available_limit, limit_amount) + OLD.amount,
    debt_amount = CASE
      WHEN v_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
      ELSE greatest(0, coalesce(debt_amount, 0) - OLD.amount)
    END,
    updated_at = now()
  WHERE id = OLD.withdrawal_from_balance;

  IF v_debt_record.debt_type = 'Pinjaman Online' THEN
    PERFORM public.recalculate_pinjaman_online_debt_amount (OLD.withdrawal_from_balance);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_expense_soft_delete_debt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_expense_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_old_debt_record record;
  v_new_debt_record record;
  v_amount_diff numeric(15, 2);
BEGIN
  v_amount_diff := NEW.amount - OLD.amount;

  IF (OLD.withdrawal_from_balance IS DISTINCT FROM NEW.withdrawal_from_balance) THEN
    IF OLD.withdrawal_from_balance IS NOT NULL THEN
      SELECT debt_type INTO v_old_debt_record FROM public.debts WHERE id = OLD.withdrawal_from_balance;
      UPDATE public.debts
      SET
        available_limit = coalesce(available_limit, limit_amount) + OLD.amount,
        debt_amount = CASE
          WHEN v_old_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
          ELSE greatest(0, coalesce(debt_amount, 0) - OLD.amount)
        END,
        updated_at = now()
      WHERE id = OLD.withdrawal_from_balance;

      IF v_old_debt_record.debt_type = 'Pinjaman Online' THEN
        PERFORM public.recalculate_pinjaman_online_debt_amount (OLD.withdrawal_from_balance);
      END IF;
    END IF;

    IF NEW.withdrawal_from_balance IS NOT NULL THEN
      SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
      INTO v_new_debt_record
      FROM public.debts
      WHERE id = NEW.withdrawal_from_balance
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Debt with id % not found', NEW.withdrawal_from_balance;
      END IF;

      UPDATE public.debts
      SET
        available_limit = coalesce(available_limit, limit_amount) - NEW.amount,
        debt_amount = CASE
          WHEN v_new_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
          ELSE coalesce(debt_amount, 0) + NEW.amount
        END,
        updated_at = now()
      WHERE id = NEW.withdrawal_from_balance;

      IF v_new_debt_record.debt_type = 'Pinjaman Online' THEN
        PERFORM public.recalculate_pinjaman_online_debt_amount (NEW.withdrawal_from_balance);
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  IF OLD.withdrawal_from_balance IS NOT NULL AND v_amount_diff != 0 THEN
    SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
    INTO v_old_debt_record
    FROM public.debts
    WHERE id = OLD.withdrawal_from_balance
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Debt with id % not found', OLD.withdrawal_from_balance;
    END IF;

    UPDATE public.debts
    SET
      available_limit = coalesce(available_limit, limit_amount) - v_amount_diff,
      debt_amount = CASE
        WHEN v_old_debt_record.debt_type = 'Pinjaman Online' THEN debt_amount
        ELSE coalesce(debt_amount, 0) + v_amount_diff
      END,
      updated_at = now()
    WHERE id = OLD.withdrawal_from_balance;

    IF v_old_debt_record.debt_type = 'Pinjaman Online' THEN
      PERFORM public.recalculate_pinjaman_online_debt_amount (OLD.withdrawal_from_balance);
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_expense_update"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."handle_expense_update"() IS 'AFTER UPDATE: update debt + recalculate Pinjaman Online (reference).';



CREATE OR REPLACE FUNCTION "public"."handle_new_user_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (user_id, email)
  VALUES (
    NEW.id,
    COALESCE(NEW.email, '')
  )
  ON CONFLICT (user_id) DO UPDATE SET
    email = EXCLUDED.email,
    updated_at = now();
  RETURN NEW;
END;
$$;


