CREATE OR REPLACE FUNCTION "public"."has_penalty_exemption"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_applied_date" "date", "p_penalty_rule_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.penalty_exemptions pe
    WHERE pe.employee_id = p_employee_id
      AND pe.organization_id = p_organization_id
      AND COALESCE(pe.is_active, true)
      AND pe.start_date <= p_applied_date
      AND (pe.end_date IS NULL OR pe.end_date >= p_applied_date)
      AND (pe.penalty_rule_id IS NULL OR pe.penalty_rule_id = p_penalty_rule_id)
  );
$$;


ALTER FUNCTION "public"."has_penalty_exemption"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_applied_date" "date", "p_penalty_rule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hire_ai_employee"("p_organization_id" "uuid", "p_full_name" "text", "p_job_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_name text := nullif(btrim(coalesce(p_full_name, '')), '');
  v_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles role
    WHERE role.user_id = auth.uid() AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin', 'hr')
  ) THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE = '42501';
  END IF;
  IF v_name IS NULL OR char_length(v_name) > 80 THEN
    RAISE EXCEPTION 'Isi nama karyawan AI.' USING ERRCODE = '22023';
  END IF;
  IF coalesce(p_job_code, '') <> 'content_plan' THEN
    RAISE EXCEPTION 'Job desc karyawan AI belum tersedia. Pilih Content Plan.' USING ERRCODE = '22023';
  END IF;
  PERFORM set_config('synckerja.ai_job_code', 'content_plan', true);
  INSERT INTO public.employees (organization_id, full_name, user_id, is_ai)
  VALUES (p_organization_id, v_name, NULL, true)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."hire_ai_employee"("p_organization_id" "uuid", "p_full_name" "text", "p_job_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."hub_require_active_web_id"("p_web_id" "text", "p_allow_null" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  w text;
begin
  if p_allow_null and (p_web_id is null or btrim(p_web_id) = '') then
    return null;
  end if;
  w := public.resolve_canonical_web_id(p_web_id);
  if w is null then
    raise exception 'invalid web_id' using errcode = '22023';
  end if;
  if not exists (select 1 from public.properties p where p.slug = w and p.is_active) then
    raise exception 'invalid web_id' using errcode = '22023';
  end if;
  return w;
end;
$$;


