CREATE OR REPLACE FUNCTION "public"."insert_daily_task_assignment_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid", "p_title" "text", "p_due_date" timestamp with time zone, "p_assigned_by_user_id" "uuid", "p_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  notif_title text;
  notif_body text;
  actor_name text;
  due_txt text;
  queue_daily_task_id uuid;
  queue_task_step_id uuid;
  queue_substep_id uuid;
BEGIN
  actor_name := COALESCE(
    (SELECT COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(e.email), ''), 'User')::text
     FROM public.employees e
     WHERE e.user_id = p_assigned_by_user_id
     LIMIT 1),
    'User'
  );

  due_txt := CASE WHEN p_due_date IS NULL THEN '' ELSE to_char(p_due_date, 'YYYY-MM-DD') END;

  notif_title := CASE
    WHEN p_event_type = 'assign' THEN 'Daily Task assigned'
    WHEN p_event_type = 'unassign' THEN 'Daily Task unassigned'
    ELSE 'Daily Task reassigned'
  END;

  notif_body := '[' || p_entity_type || '] ' || COALESCE(NULLIF(p_title, ''), 'Item')
    || CASE WHEN due_txt <> '' THEN ' • Due ' || due_txt ELSE '' END
    || ' • by ' || actor_name;

  -- Avoid FK to entities mid-cascade-delete on unassign.
  IF p_event_type = 'unassign' THEN
    queue_daily_task_id := NULL;
    queue_task_step_id := NULL;
    queue_substep_id := NULL;
  ELSE
    queue_daily_task_id := p_daily_task_id;
    queue_task_step_id := p_task_step_id;
    queue_substep_id := p_task_steps_to_steps_id;
  END IF;

  INSERT INTO public.daily_task_notifications (
    user_id, organization_id, title, body,
    daily_task_id, task_step_id, task_steps_to_steps_id,
    read_at, created_at
  ) VALUES (
    p_recipient_user_id, p_organization_id, notif_title, notif_body,
    queue_daily_task_id, queue_task_step_id, queue_substep_id,
    NULL, now()
  );

  INSERT INTO public.daily_task_assignment_push_queue (
    organization_id, recipient_user_id, created_at, sent_at,
    event_type, entity_type,
    daily_task_id, task_step_id, task_steps_to_steps_id,
    title, due_date, assigned_by_user_id, url
  ) VALUES (
    p_organization_id, p_recipient_user_id, now(), NULL,
    p_event_type, p_entity_type,
    queue_daily_task_id, queue_task_step_id, queue_substep_id,
    COALESCE(p_title, ''), p_due_date, p_assigned_by_user_id, COALESCE(p_url, '')
  );
END;
$$;


ALTER FUNCTION "public"."insert_daily_task_assignment_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid", "p_title" "text", "p_due_date" timestamp with time zone, "p_assigned_by_user_id" "uuid", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_daily_task_completion_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid", "p_assignee_user_id" "uuid", "p_assigner_user_id" "uuid", "p_title" "text", "p_requires_approval" boolean, "p_completion_approval_id" "uuid", "p_reject_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  notif_title text;
  notif_body text;
  assignee_name text;
  url text := '/tools/daily-task?view=jobdesc';
BEGIN
  assignee_name := COALESCE(
    (SELECT COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(e.email), ''), 'User')::text
     FROM public.employees e
     WHERE e.user_id = p_assignee_user_id
     LIMIT 1),
    'User'
  );

  IF p_event_type = 'completed' THEN
    notif_title := 'Daily Task selesai';
    notif_body := '[' || p_entity_type || '] ' || COALESCE(NULLIF(p_title,''),'Item') || ' • oleh ' || assignee_name;
    IF p_requires_approval THEN
      notif_body := notif_body || ' • butuh approval kamu';
    END IF;
  ELSE
    notif_title := 'Daily Task ditolak';
    notif_body := '[' || p_entity_type || '] ' || COALESCE(NULLIF(p_title,''),'Item') || ' • ditolak';
    IF p_reject_reason IS NOT NULL AND btrim(p_reject_reason) <> '' THEN
      notif_body := notif_body || ' • ' || btrim(p_reject_reason);
    END IF;
  END IF;

  INSERT INTO public.daily_task_notifications (
    user_id, organization_id, title, body,
    daily_task_id, task_step_id, task_steps_to_steps_id,
    read_at, created_at
  ) VALUES (
    p_recipient_user_id, p_organization_id, notif_title, notif_body,
    p_daily_task_id, p_task_step_id, p_task_steps_to_steps_id,
    NULL, now()
  );

  INSERT INTO public.daily_task_completion_push_queue (
    organization_id, recipient_user_id, created_at, sent_at,
    event_type, entity_type,
    daily_task_id, task_step_id, task_steps_to_steps_id,
    assignee_user_id, assigner_user_id,
    title, requires_approval, completion_approval_id, reject_reason, url
  ) VALUES (
    p_organization_id, p_recipient_user_id, now(), NULL,
    p_event_type, p_entity_type,
    p_daily_task_id, p_task_step_id, p_task_steps_to_steps_id,
    p_assignee_user_id, p_assigner_user_id,
    COALESCE(p_title,''), COALESCE(p_requires_approval,false), p_completion_approval_id, p_reject_reason, url
  );
END;
$$;


ALTER FUNCTION "public"."insert_daily_task_completion_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid", "p_assignee_user_id" "uuid", "p_assigner_user_id" "uuid", "p_title" "text", "p_requires_approval" boolean, "p_completion_approval_id" "uuid", "p_reject_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_public_review_comment"("token_param" "text", "comment_text" "text", "commenter_display_name" "text", "video_timestamp_seconds" numeric DEFAULT NULL::numeric, "annotation_data" "jsonb" DEFAULT NULL::"jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_link_url text;
  v_inserted_id uuid;
  v_inserted_row public.link_comments%ROWTYPE;
  v_name text;
BEGIN
  IF comment_text IS NULL OR trim(comment_text) = '' THEN
    RAISE EXCEPTION 'comment_text is required';
  END IF;

  v_name := trim(commenter_display_name);
  IF v_name = '' THEN
    RAISE EXCEPTION 'commenter_display_name is required';
  END IF;

  SELECT social_media_plan_id, link_url INTO v_plan_id, v_link_url
  FROM public.public_review_tokens
  WHERE token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired review link';
  END IF;

  INSERT INTO public.link_comments (
    social_media_plan_id,
    link_url,
    comment_text,
    created_by,
    commenter_display_name,
    video_timestamp_seconds,
    annotation_data
  ) VALUES (
    v_plan_id,
    v_link_url,
    trim(comment_text),
    NULL,
    v_name,
    video_timestamp_seconds,
    annotation_data
  )
  RETURNING id INTO v_inserted_id;

  SELECT * INTO v_inserted_row FROM public.link_comments WHERE id = v_inserted_id;

  RETURN json_build_object(
    'id', v_inserted_row.id,
    'social_media_plan_id', v_inserted_row.social_media_plan_id,
    'link_url', v_inserted_row.link_url,
    'comment_text', v_inserted_row.comment_text,
    'created_by', v_inserted_row.created_by,
    'created_at', v_inserted_row.created_at,
    'updated_at', v_inserted_row.updated_at,
    'video_timestamp_seconds', v_inserted_row.video_timestamp_seconds,
    'annotation_data', v_inserted_row.annotation_data,
    'creator_display_name', v_inserted_row.commenter_display_name
  );
END;
$$;


ALTER FUNCTION "public"."insert_public_review_comment"("token_param" "text", "comment_text" "text", "commenter_display_name" "text", "video_timestamp_seconds" numeric, "annotation_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insert_social_media_production_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_social_media_plan_id" "uuid", "p_review_token" "text", "p_actor_user_id" "uuid", "p_assignee_user_id" "uuid", "p_assigner_user_id" "uuid", "p_plan_title" "text", "p_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_title text;
  v_body text;
  v_plan_label text;
  v_actor_name text;
  v_pic_name text;
BEGIN
  IF p_recipient_user_id IS NULL THEN
    RETURN;
  END IF;

  IF p_actor_user_id IS NOT NULL AND p_recipient_user_id = p_actor_user_id THEN
    RETURN;
  END IF;

  v_plan_label := COALESCE(NULLIF(btrim(p_plan_title), ''), 'Konten');
  v_actor_name := COALESCE(public.user_display_name(p_actor_user_id), 'Reviewer');

  IF p_event_type = 'approved' THEN
    v_title := 'Konten disetujui';
    v_body := v_plan_label || ' telah di-approve oleh ' || v_actor_name || '.';
  ELSIF p_event_type = 'revision_requested' THEN
    v_title := 'Permintaan revisi';
    v_body := v_plan_label || ' perlu revisi. Cek detail di Daily Task / link review.';
  ELSIF p_event_type = 'need_review' THEN
    SELECT COALESCE(NULLIF(btrim(employee.full_name), ''), 'PIC produksi')
    INTO v_pic_name
    FROM public.social_media_plans plan
    JOIN public.employees employee ON employee.id = plan.pic_production_id
    WHERE plan.id = p_social_media_plan_id;
    v_title := 'Produksi perlu direview';
    v_body := v_plan_label || ' dari ' || COALESCE(v_pic_name, 'PIC produksi') || ' menunggu review.';
  ELSE
    v_title := 'Revisi siap direview';
    v_body := v_plan_label || ' sudah dikirim ulang untuk review.';
  END IF;

  INSERT INTO public.social_media_production_notifications (
    user_id, organization_id, social_media_plan_id, review_token,
    event_type, title, body, url, read_at, created_at
  ) VALUES (
    p_recipient_user_id, p_organization_id, p_social_media_plan_id, p_review_token,
    p_event_type, v_title, v_body, p_url, NULL, now()
  );

  INSERT INTO public.social_media_production_push_queue (
    organization_id, recipient_user_id, created_at, sent_at,
    event_type, social_media_plan_id, review_token,
    actor_user_id, assignee_user_id, assigner_user_id,
    plan_title, url
  ) VALUES (
    p_organization_id, p_recipient_user_id, now(), NULL,
    p_event_type, p_social_media_plan_id, p_review_token,
    p_actor_user_id, p_assignee_user_id, p_assigner_user_id,
    COALESCE(p_plan_title, ''), p_url
  );
END;
$$;


ALTER FUNCTION "public"."insert_social_media_production_notification"("p_recipient_user_id" "uuid", "p_organization_id" "uuid", "p_event_type" "text", "p_social_media_plan_id" "uuid", "p_review_token" "text", "p_actor_user_id" "uuid", "p_assignee_user_id" "uuid", "p_assigner_user_id" "uuid", "p_plan_title" "text", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instagram_conversation_customer_dedupe_key"("p_customer_ig_id" "text", "p_customer_external_id" "text", "p_customer_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  SELECT LOWER(TRIM(COALESCE(
    CASE
      WHEN LOWER(REGEXP_REPLACE(TRIM(COALESCE(p_customer_name, '')), '^@+', '')) ~ '^[a-z0-9._]{1,30}$'
       AND LOWER(REGEXP_REPLACE(TRIM(COALESCE(p_customer_name, '')), '^@+', '')) ~ '[a-z]'
      THEN NULLIF(LOWER(REGEXP_REPLACE(TRIM(p_customer_name), '^@+', '')), '')
      ELSE NULL
    END,
    NULLIF(TRIM(p_customer_external_id), ''),
    NULLIF(TRIM(p_customer_ig_id), '')
  )));
$_$;


ALTER FUNCTION "public"."instagram_conversation_customer_dedupe_key"("p_customer_ig_id" "text", "p_customer_external_id" "text", "p_customer_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."instagram_conversation_customer_dedupe_key"("p_customer_ig_id" "text", "p_customer_external_id" "text", "p_customer_name" "text") IS 'Stable customer identity: IG handle (@ or bare) > external (webhook sender) > ig id.';



CREATE OR REPLACE FUNCTION "public"."instagram_conversation_cycles_bi_seed_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.first_assignee_in_cycle_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.instagram_conversations c
    WHERE c.id = NEW.conversation_id
      AND c.assignee_id IS NOT NULL
  ) THEN
    NEW.first_assignee_in_cycle_at := NEW.cycle_started_at;
  END IF;
  RETURN NEW;
END;
$$;


