CREATE OR REPLACE FUNCTION "public"."instagram_conversations_normalize_ticket_id"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  NEW.ticket_id := 'IG-' || UPPER(SUBSTRING(REPLACE(NEW.id::text, '-', ''), 1, 8));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."instagram_conversations_normalize_ticket_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."instagram_conversations_set_cycle_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.assignee_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.assignee_id IS NOT DISTINCT FROM NEW.assignee_id THEN
    RETURN NEW;
  END IF;
  UPDATE public.instagram_conversation_cycles cy
  SET first_assignee_in_cycle_at = now(), updated_at = now()
  WHERE cy.conversation_id = NEW.id
    AND cy.resolved_at IS NULL
    AND cy.first_assignee_in_cycle_at IS NULL;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."instagram_conversations_set_cycle_first_assignee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."install_ai_employee_built_job"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.is_ai, false) IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND COALESCE(OLD.is_ai, false) IS TRUE THEN
    RETURN NEW;
  END IF;
  PERFORM public.ai_employee_install_content_plan(NEW.id, NEW.organization_id);
  PERFORM public.ai_employee_assign_content_plan_position(NEW.id, NEW.organization_id);
  PERFORM public.ai_employee_sync_reviewer_from_manager(NEW.id);
  RETURN NEW;
END;
$$;


