CREATE OR REPLACE FUNCTION "public"."inventory_alert_status_from_stock"("p_in_stock" numeric, "p_alert_enabled" boolean, "p_alert_at" numeric) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN COALESCE(p_in_stock, 0) <= 0 THEN 'out'
    WHEN COALESCE(p_alert_enabled, false)
      AND p_alert_at IS NOT NULL
      AND COALESCE(p_in_stock, 0) <= p_alert_at THEN 'low'
    ELSE NULL
  END;
$$;


