CREATE OR REPLACE FUNCTION "public"."is_blibli_seller_chat_connected"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN public.is_blibli_seller_chat_connected__impl(p_organization_id);
END;
$$;


ALTER FUNCTION "public"."is_blibli_seller_chat_connected"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_blibli_seller_chat_connected__impl"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_blibli_seller_connections c
    INNER JOIN public.organization_blibli_seller_connection_tokens t
      ON t.connection_id = c.id
    WHERE c.organization_id = p_organization_id
      AND c.status = 'active'
  );
$$;


