CREATE OR REPLACE FUNCTION "public"."list_catalog_inventory_org_roles"("p_organization_id" "uuid") RETURNS TABLE("role" "text", "employee_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT
    ur.role::text,
    COUNT(DISTINCT e.id)::bigint
  FROM public.user_roles ur
  LEFT JOIN public.employees e
    ON e.user_id = ur.user_id
   AND e.organization_id = ur.organization_id
  WHERE ur.organization_id = p_organization_id
    AND ur.role IN ('owner', 'admin', 'hr', 'employee')
  GROUP BY ur.role
  ORDER BY CASE ur.role
    WHEN 'owner' THEN 1
    WHEN 'admin' THEN 2
    WHEN 'hr' THEN 3
    ELSE 4
  END;
END;
$$;


ALTER FUNCTION "public"."list_catalog_inventory_org_roles"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_pos_receipt_feedback"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_employee_id" "uuid" DEFAULT NULL::"uuid", "p_sentiment" "text" DEFAULT NULL::"text", "p_from" "date" DEFAULT NULL::"date", "p_to" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rows jsonb;
  v_good bigint;
  v_bad bigint;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = auth.uid()
      AND p.active_organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT count(*) FILTER (WHERE public.pos_receipt_feedback_sentiment(r.rating) = 'good'),
         count(*) FILTER (WHERE public.pos_receipt_feedback_sentiment(r.rating) = 'bad')
  INTO v_good, v_bad
  FROM public.pos_receipt_feedback_responses r
  WHERE r.organization_id = p_organization_id
    AND (p_outlet_id IS NULL OR r.pos_outlet_id = p_outlet_id)
    AND (p_employee_id IS NULL OR r.served_by_employee_id = p_employee_id)
    AND (p_sentiment IS NULL OR public.pos_receipt_feedback_sentiment(r.rating) = p_sentiment)
    AND (p_from IS NULL OR r.submitted_at::date >= p_from)
    AND (p_to IS NULL OR r.submitted_at::date <= p_to);

  SELECT COALESCE(
    jsonb_agg(row_to_json(t)::jsonb ORDER BY t.submitted_at DESC),
    '[]'::jsonb
  )
  INTO v_rows
  FROM (
    SELECT
      r.id,
      r.invitation_id,
      r.sales_activity_id,
      r.pos_outlet_id,
      r.served_by_employee_id,
      r.rating,
      public.pos_receipt_feedback_sentiment(r.rating) AS sentiment,
      r.comment,
      r.reply_text,
      r.replied_by,
      r.replied_at,
      r.submitted_at,
      COALESCE(nullif(trim(v_inv.customer_name), ''), nullif(trim(sa.client_name), ''), '—') AS customer_name,
      COALESCE(nullif(trim(po.name), ''), '—') AS outlet_name,
      COALESCE(nullif(trim(e.full_name), ''), '—') AS employee_name
    FROM public.pos_receipt_feedback_responses r
    JOIN public.pos_receipt_feedback_invitations v_inv ON v_inv.id = r.invitation_id
    LEFT JOIN public.sales_activities sa ON sa.id = r.sales_activity_id
    LEFT JOIN public.pos_outlets po ON po.id = r.pos_outlet_id
    LEFT JOIN public.employees e ON e.id = r.served_by_employee_id
    WHERE r.organization_id = p_organization_id
      AND (p_outlet_id IS NULL OR r.pos_outlet_id = p_outlet_id)
      AND (p_employee_id IS NULL OR r.served_by_employee_id = p_employee_id)
      AND (p_sentiment IS NULL OR public.pos_receipt_feedback_sentiment(r.rating) = p_sentiment)
      AND (p_from IS NULL OR r.submitted_at::date >= p_from)
      AND (p_to IS NULL OR r.submitted_at::date <= p_to)
    ORDER BY r.submitted_at DESC
    LIMIT 500
  ) t;

  RETURN jsonb_build_object(
    'ok', true,
    'good_count', COALESCE(v_good, 0),
    'bad_count', COALESCE(v_bad, 0),
    'rows', v_rows
  );
END;
$$;


ALTER FUNCTION "public"."list_pos_receipt_feedback"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_employee_id" "uuid", "p_sentiment" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


