COMMENT ON TABLE "public"."bank_account_activity_logs" IS 'Audit trail for Ops Settings Bank Account create/update/deactivate/assign.';



CREATE OR REPLACE FUNCTION "public"."log_bank_account_activity"("p_organization_id" "uuid", "p_bank_account_id" "uuid", "p_action" "text", "p_summary" "text", "p_meta" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "public"."bank_account_activity_logs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.bank_account_activity_logs;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  INSERT INTO public.bank_account_activity_logs (
    organization_id,
    bank_account_id,
    action,
    summary,
    meta,
    actor_user_id
  )
  VALUES (
    p_organization_id,
    p_bank_account_id,
    p_action,
    COALESCE(NULLIF(btrim(p_summary), ''), p_action),
    COALESCE(p_meta, '{}'::jsonb),
    auth.uid()
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


