  UPDATE public.brick_payment_requests
  SET
    status = 'paid',
    brick_payment_id = COALESCE(p_brick_payment_id, brick_payment_id),
    paid_at = now(),
    updated_at = now()
  WHERE id = v_req.id;

  RETURN jsonb_build_object('ok', true, 'status', 'paid');
END;
$$;


