CREATE OR REPLACE FUNCTION "public"."maybe_finalize_payroll_run"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_pending integer;
  v_processing integer;
  v_failed integer;
  v_paid integer;
  v_total integer;
BEGIN
  SELECT pr.id, pr.organization_id, pr.status, pp.pay_date
  INTO v_run
  FROM public.payroll_runs pr
  JOIN public.payroll_periods pp ON pp.id = pr.payroll_period_id
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Payroll run not found');
  END IF;

  IF v_run.status = 'paid' THEN
    RETURN jsonb_build_object('success', true, 'finalized', false, 'already_paid', true);
  END IF;

  SELECT
    count(*) FILTER (WHERE payment_status = 'pending'),
    count(*) FILTER (WHERE payment_status = 'processing'),
    count(*) FILTER (WHERE payment_status = 'failed'),
    count(*) FILTER (WHERE payment_status = 'paid'),
    count(*)
  INTO v_pending, v_processing, v_failed, v_paid, v_total
  FROM public.employee_payroll_calculations
  WHERE payroll_run_id = p_run_id;

  IF v_total = 0 THEN
    RETURN jsonb_build_object('success', true, 'finalized', false, 'message', 'No calculations');
  END IF;

  IF v_pending > 0 OR v_processing > 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'finalized', false,
      'pending', v_pending,
      'processing', v_processing,
      'failed', v_failed,
      'paid', v_paid
    );
  END IF;

  IF v_failed > 0 THEN
    RETURN jsonb_build_object(
      'success', true,
      'finalized', false,
      'has_failures', true,
      'failed', v_failed,
      'paid', v_paid
    );
  END IF;

  IF v_paid = v_total THEN
    UPDATE public.payroll_runs
    SET status = 'paid',
        paid_at = COALESCE(v_run.pay_date::timestamptz, now()),
        paid_by = auth.uid(),
        updated_at = now()
    WHERE id = p_run_id;

    PERFORM public.payroll_log_audit(
      v_run.organization_id,
      p_run_id,
      NULL,
      'marked_paid',
      jsonb_build_object('source', 'auto_finalize', 'calculations_paid', v_paid)
    );

    RETURN jsonb_build_object(
      'success', true,
      'finalized', true,
      'paid', v_paid
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'finalized', false);
END;
$$;


ALTER FUNCTION "public"."maybe_finalize_payroll_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maybe_refresh_analytics_rollups"("p_web_id" "text", "p_debounce_seconds" integer DEFAULT 45) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_web_id text;
  v_debounce int;
  v_last_started timestamptz;
  v_from date;
  v_to date;
  v_clear_err text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_web_id := lower(btrim(coalesce(p_web_id, '')));
  IF v_web_id = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  v_debounce := GREATEST(15, LEAST(coalesce(p_debounce_seconds, 45), 300));

  PERFORM pg_advisory_xact_lock(hashtext('analytics_rollup_refresh:' || v_web_id));

  SELECT s.last_started_at
  INTO v_last_started
  FROM public.analytics_rollup_refresh_state s
  WHERE s.web_id = v_web_id
  FOR UPDATE;

  IF v_last_started IS NOT NULL
     AND v_last_started > (now() - make_interval(secs => v_debounce)) THEN
    RETURN jsonb_build_object(
      'status', 'skipped',
      'web_id', v_web_id,
      'reason', 'debounced',
      'debounce_seconds', v_debounce,
      'last_started_at', v_last_started
    );
  END IF;

  INSERT INTO public.analytics_rollup_refresh_state (web_id, last_started_at, updated_at)
  VALUES (v_web_id, now(), now())
  ON CONFLICT (web_id) DO UPDATE SET
    last_started_at = EXCLUDED.last_started_at,
    last_error = NULL,
    updated_at = now();

  SELECT y.day_yesterday, y.day_today
  INTO v_from, v_to
  FROM public.traffic_wib_today_yesterday() y;

  BEGIN
    PERFORM public.refresh_analytics_rollups(v_web_id, v_from, v_to);

    BEGIN
      PERFORM public.clear_analytics_rollups_slice_for_traffic_sync(v_web_id, v_from, v_to);
    EXCEPTION
      WHEN undefined_function THEN
        DELETE FROM public.analytics_daily_utm u
        WHERE u.web_id = v_web_id AND u.day BETWEEN v_from AND v_to;
        DELETE FROM public.analytics_daily_source_breakdown d
        WHERE d.web_id = v_web_id AND d.day BETWEEN v_from AND v_to;
      WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS v_clear_err = MESSAGE_TEXT;
        RAISE WARNING 'clear_analytics_rollups_slice_for_traffic_sync failed for %: %', v_web_id, v_clear_err;
    END;

    PERFORM public.refresh_analytics_daily_rollups(v_from, v_to, v_web_id);

    UPDATE public.analytics_rollup_refresh_state
    SET last_completed_at = now(),
        last_error = NULL,
        updated_at = now()
    WHERE web_id = v_web_id;

    RETURN jsonb_build_object(
      'status', 'refreshed',
      'web_id', v_web_id,
      'from', to_char(v_from, 'YYYY-MM-DD'),
      'to', to_char(v_to, 'YYYY-MM-DD'),
      'debounce_seconds', v_debounce
    );
  EXCEPTION
    WHEN OTHERS THEN
      UPDATE public.analytics_rollup_refresh_state
      SET last_error = SQLERRM,
          updated_at = now()
      WHERE web_id = v_web_id;
      RAISE WARNING 'maybe_refresh_analytics_rollups failed for %: %', v_web_id, SQLERRM;
      RETURN jsonb_build_object(
        'status', 'error',
        'web_id', v_web_id,
        'message', SQLERRM
      );
  END;
END;
$$;


ALTER FUNCTION "public"."maybe_refresh_analytics_rollups"("p_web_id" "text", "p_debounce_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."maybe_refresh_analytics_rollups"("p_web_id" "text", "p_debounce_seconds" integer) IS 'Debounced rollup refresh for today+yesterday WIB after analytics ingest (service_role only).';



CREATE OR REPLACE FUNCTION "public"."mcp_access_cutoff"("p_user_id" "uuid", "p_organization_id" "uuid", "p_client_id" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_revoked_at timestamptz;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR NULLIF(btrim(COALESCE(p_client_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT revocation.revoked_at
  INTO v_revoked_at
  FROM public.mcp_oauth_revocations revocation
  WHERE revocation.user_id = p_user_id
    AND revocation.organization_id = p_organization_id
    AND revocation.client_id = p_client_id;

  RETURN v_revoked_at;
END;
$$;


