CREATE OR REPLACE FUNCTION "public"."mcp_adjustment_resolve_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text := btrim(COALESCE(p_search, ''));
  v_count integer := 0;
  v_labels text[] := ARRAY[]::text[];
  v_found jsonb;
  r record;
BEGIN
  IF v_search = '' OR char_length(v_search) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  FOR r IN
    SELECT * FROM (
      SELECT 'ingredient'::text AS kind, NULL::uuid AS product_id, NULL::uuid AS variant_id, i.id AS ingredient_id,
             i.name AS label, io.in_stock AS qty_before
      FROM public.catalog_ingredients i
      JOIN public.catalog_ingredient_outlets io ON io.ingredient_id = i.id AND io.outlet_id = p_outlet_id
      WHERE i.organization_id = p_organization_id AND NOT COALESCE(i.is_deleted, false)
        AND i.track_inventory = true AND lower(btrim(i.name)) = lower(v_search)
      UNION ALL
      SELECT 'product', dp.id, NULL, NULL, dp.name, link.in_stock
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link ON link.product_id = dp.id AND link.outlet_id = p_outlet_id
      WHERE dp.organization_id = p_organization_id AND dp.kind = 'product' AND dp.track_stock = true
        AND lower(btrim(dp.name)) = lower(v_search)
        AND NOT EXISTS (SELECT 1 FROM public.catalog_product_variants v WHERE v.product_id = dp.id)
      UNION ALL
      SELECT 'product', dp.id, v.id, NULL, dp.name || ' / ' || v.name, COALESCE(vo.in_stock, 0)
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link ON link.product_id = dp.id AND link.outlet_id = p_outlet_id
      JOIN public.catalog_product_variants v ON v.product_id = dp.id
      LEFT JOIN public.catalog_product_variant_outlets vo ON vo.variant_id = v.id AND vo.outlet_id = p_outlet_id
      WHERE dp.organization_id = p_organization_id AND dp.kind = 'product' AND dp.track_stock = true
        AND (lower(btrim(v.name)) = lower(v_search) OR lower(dp.name || ' / ' || v.name) = lower(v_search))
    ) found
    ORDER BY label
  LOOP
    v_count := v_count + 1;
    v_labels := v_labels || r.label;
    v_found := jsonb_build_object(
      'kind', r.kind, 'product_id', r.product_id, 'variant_id', r.variant_id,
      'ingredient_id', r.ingredient_id, 'name', r.label, 'qty_before', COALESCE(r.qty_before, 0)
    );
  END LOOP;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION '%', 'ambiguous: ' || array_to_string(v_labels, ' | ') USING ERRCODE = '22023';
  END IF;
  RETURN v_found;
END;
$$;


ALTER FUNCTION "public"."mcp_adjustment_resolve_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_ai_employee_job_counts"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_done integer;
  v_rejected integer;
  v_failed integer;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_employee_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = p_user_id
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT
    count(*) FILTER (WHERE job.status = 'done')::integer,
    count(*) FILTER (WHERE job.status = 'rejected')::integer,
    count(*) FILTER (WHERE job.status = 'failed')::integer
  INTO v_done, v_rejected, v_failed
  FROM public.ai_employee_jobs job
  WHERE job.employee_id = p_employee_id
    AND job.organization_id = p_organization_id
    AND job.finished_at >= p_start
    AND job.finished_at < p_end;

  RETURN jsonb_build_object(
    'done', COALESCE(v_done, 0),
    'rejected', COALESCE(v_rejected, 0),
    'failed', COALESCE(v_failed, 0)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_ai_employee_job_counts"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_start" timestamp with time zone, "p_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_assign_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_employee_id" "uuid", "p_due_date" "text") RETURNS TABLE("id" "uuid", "assignee_name" "text", "due_date" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_can_assign boolean;
  v_due timestamptz;
  v_assignment uuid;
  v_name text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL OR p_employee_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = p_user_id
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin', 'hr')
  ) INTO v_can_assign;

  IF p_employee_id IS DISTINCT FROM v_self AND NOT v_can_assign THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.daily_tasks task
    WHERE task.id = p_id AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.employees emp
    WHERE emp.id = p_employee_id AND emp.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_due_date IS NOT NULL AND btrim(p_due_date) <> '' THEN
    IF btrim(p_due_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_due := (btrim(p_due_date) || ' 17:00:00')::timestamp AT TIME ZONE 'Asia/Jakarta';
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_due AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_due_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_due IS NOT NULL THEN
    UPDATE public.daily_tasks task
    SET due_date = v_due, updated_at = now()
    WHERE task.id = p_id AND task.organization_id = p_organization_id;
  END IF;

  DELETE FROM public.daily_tasks_assigned assigned
  WHERE assigned.daily_task_id = p_id
    AND assigned.organization_id = p_organization_id;

  INSERT INTO public.daily_tasks_assigned (
    organization_id, daily_task_id, employee_id, assigned_by
  )
  VALUES (p_organization_id, p_id, p_employee_id, v_self)
  RETURNING daily_tasks_assigned.id INTO v_assignment;

  IF v_due IS NOT NULL THEN
    INSERT INTO public.task_steps_assigned_duedate (
      organization_id, daily_tasks_assigned_id, due_date
    )
    VALUES (p_organization_id, v_assignment, v_due);
  END IF;

  SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), ''))
  INTO v_name
  FROM public.employees emp
  LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
  WHERE emp.id = p_employee_id;

  id := p_id;
  assignee_name := v_name;
  due_date := v_due;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_assign_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_employee_id" "uuid", "p_due_date" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_attach_task_step_image"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid", "p_filename" "text", "p_file_url" "text", "p_file_size" bigint) RETURNS TABLE("id" "uuid", "step_id" "uuid", "filename" "text", "file_url" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_filename text;
  v_file_url text;
  v_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_step_id IS NULL OR p_file_size IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_filename := btrim(COALESCE(p_filename, ''));
  v_file_url := btrim(COALESCE(p_file_url, ''));
  IF char_length(v_filename) < 1
    OR char_length(v_filename) > 80
    OR position('/' in v_filename) > 0
    OR position(chr(92) in v_filename) > 0
    OR char_length(v_file_url) < 8
    OR char_length(v_file_url) > 2000
    OR left(v_file_url, 8) <> 'https://'
    OR p_file_size < 1
    OR p_file_size > 5242880
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.task_steps step
    JOIN public.daily_tasks task ON task.id = step.task_id
    WHERE step.id = p_step_id
      AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.task_files (task_steps_id, filename, file_url, file_size)
  VALUES (p_step_id, v_filename, v_file_url, p_file_size)
  RETURNING task_files.id INTO v_id;

  id := v_id;
  step_id := p_step_id;
  filename := v_filename;
  file_url := v_file_url;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_attach_task_step_image"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid", "p_filename" "text", "p_file_url" "text", "p_file_size" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_check_habit"("p_user_id" "uuid", "p_organization_id" "uuid", "p_habit_id" "uuid", "p_checked" boolean, "p_date" "text", "p_index" integer) RETURNS TABLE("id" "uuid", "entry_date" "date", "item_index" integer, "checked" boolean, "checked_count" integer, "target_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_profile uuid;
  v_day date;
  v_today date;
  v_habit record;
  v_target integer;
  v_flags boolean[];
  v_today_flags boolean[];
  v_today_count integer;
  v_legacy boolean;
  v_slot integer;
  v_checked_count integer;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_habit_id IS NULL OR p_checked IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_date IS NULL OR btrim(p_date) = '' THEN
    v_day := (now() AT TIME ZONE 'Asia/Jakarta')::date;
  ELSE
    IF btrim(p_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_date)::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT
    habit.id,
    habit.frequency,
    habit.target_count,
    habit.weekly_days,
    habit.monthly_dates,
    habit.is_active
  INTO v_habit
  FROM public.habits habit
  WHERE habit.id = p_habit_id
    AND habit.organization_id = p_organization_id
    AND habit.employee_id = v_self;

  IF v_habit.id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  v_target := GREATEST(COALESCE(v_habit.target_count, 1), 1);
  IF NOT public.mcp_habit_on_day(
    v_habit.frequency,
    CASE WHEN v_habit.weekly_days IS NULL THEN NULL ELSE to_jsonb(v_habit.weekly_days) END,
    CASE WHEN v_habit.monthly_dates IS NULL THEN NULL ELSE to_jsonb(v_habit.monthly_dates) END,
    v_habit.is_active,
    v_day
  ) THEN
    RAISE EXCEPTION 'not_scheduled' USING ERRCODE = '22023';
  END IF;

  v_today := (now() AT TIME ZONE 'Asia/Jakarta')::date;
  IF v_day > v_today AND public.mcp_habit_on_day(
    v_habit.frequency,
    CASE WHEN v_habit.weekly_days IS NULL THEN NULL ELSE to_jsonb(v_habit.weekly_days) END,
    CASE WHEN v_habit.monthly_dates IS NULL THEN NULL ELSE to_jsonb(v_habit.monthly_dates) END,
    v_habit.is_active,
    v_today
  ) THEN
    SELECT count(*) INTO v_today_count
    FROM public.habit_entries entry
    WHERE entry.habit_id = v_habit.id
      AND entry.employee_id = v_self
      AND entry.organization_id = p_organization_id
      AND entry.entry_date = v_today;
    v_today_flags := public.mcp_habit_flags(v_habit.id, v_self, p_organization_id, v_today, v_target);
    IF lower(COALESCE(v_habit.frequency, '')) IN ('weekly', 'monthly') THEN
      IF v_today_count = 0 THEN
        RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
      END IF;
    ELSIF v_target > 1 THEN
      IF v_today_count < v_target THEN
        RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
      END IF;
    ELSIF NOT COALESCE(v_today_flags[1], false) THEN
      RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_target = 1 THEN
    IF p_index IS NOT NULL AND p_index <> 0 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_slot := 0;
  ELSE
    IF p_index IS NULL OR p_index < 0 OR p_index >= v_target THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_slot := p_index;
  END IF;

  v_flags := public.mcp_habit_flags(v_habit.id, v_self, p_organization_id, v_day, v_target);
  IF COALESCE(v_flags[v_slot + 1], false) IS DISTINCT FROM p_checked THEN
    SELECT profile.id INTO v_profile
    FROM public.profiles profile
    WHERE profile.user_id = p_user_id
    LIMIT 1;

    IF v_target = 1 THEN
      IF p_checked THEN
        INSERT INTO public.habit_entries (
          habit_id, entry_date, count, notes, organization_id, employee_id, created_by
        )
        VALUES (v_habit.id, v_day, 1, NULL, p_organization_id, v_self, v_profile);
      ELSE
        DELETE FROM public.habit_entries entry
        WHERE entry.habit_id = v_habit.id
          AND entry.employee_id = v_self
          AND entry.organization_id = p_organization_id
          AND entry.entry_date = v_day;
      END IF;
    ELSE
      SELECT EXISTS (
        SELECT 1
        FROM public.habit_entries entry
        WHERE entry.habit_id = v_habit.id
          AND entry.employee_id = v_self
          AND entry.organization_id = p_organization_id
          AND entry.entry_date = v_day
          AND (entry.notes IS NULL OR entry.notes !~ '^checklist_index:[0-9]+$')
      ) INTO v_legacy;

      IF v_legacy THEN
        v_flags[v_slot + 1] := p_checked;
        DELETE FROM public.habit_entries entry
        WHERE entry.habit_id = v_habit.id
          AND entry.employee_id = v_self
          AND entry.organization_id = p_organization_id
          AND entry.entry_date = v_day;
        FOR v_slot IN 0..v_target - 1 LOOP
          IF COALESCE(v_flags[v_slot + 1], false) THEN
            INSERT INTO public.habit_entries (
              habit_id, entry_date, count, notes, organization_id, employee_id, created_by
            )
            VALUES (
              v_habit.id,
              v_day,
              1,
              'checklist_index:' || v_slot::text,
              p_organization_id,
              v_self,
              v_profile
            );
          END IF;
        END LOOP;
        v_slot := COALESCE(p_index, 0);
      ELSIF p_checked THEN
        INSERT INTO public.habit_entries (
          habit_id, entry_date, count, notes, organization_id, employee_id, created_by
        )
        VALUES (
          v_habit.id,
          v_day,
          1,
          'checklist_index:' || v_slot::text,
          p_organization_id,
          v_self,
          v_profile
        );
      ELSE
        DELETE FROM public.habit_entries entry
        WHERE entry.habit_id = v_habit.id
          AND entry.employee_id = v_self
          AND entry.organization_id = p_organization_id
          AND entry.entry_date = v_day
          AND entry.notes = 'checklist_index:' || v_slot::text;
      END IF;
    END IF;
  END IF;

  v_flags := public.mcp_habit_flags(v_habit.id, v_self, p_organization_id, v_day, v_target);
  v_checked_count := 0;
  FOR v_slot IN 1..v_target LOOP
    IF COALESCE(v_flags[v_slot], false) THEN
      v_checked_count := v_checked_count + 1;
    END IF;
  END LOOP;

  id := v_habit.id;
  entry_date := v_day;
  item_index := COALESCE(p_index, 0);
  checked := p_checked;
  checked_count := v_checked_count;
  target_count := v_target;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_check_habit"("p_user_id" "uuid", "p_organization_id" "uuid", "p_habit_id" "uuid", "p_checked" boolean, "p_date" "text", "p_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_confirm_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_base_version" integer, "p_confirm_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") RETURNS TABLE("id" "uuid", "version_no" integer, "status" "text", "approved" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_approved boolean;
  v_current_brief text;
  v_old_concept text;
  v_old_caption text;
  v_old_link text;
  v_new_brief text;
  v_new_concept text;
  v_new_caption text;
  v_new_link text;
  v_latest integer;
  v_storyboard_changed boolean := false;
  v_concept_changed boolean := false;
  v_caption_changed boolean := false;
  v_link_changed boolean := false;
  v_changed boolean := false;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_plan_id IS NULL
     OR p_base_version IS NULL OR p_confirm_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations AS member
    WHERE member.user_id = p_user_id
      AND member.organization_id = p_organization_id
      AND COALESCE(member.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT plan.status, plan.approved, plan.brief
    INTO v_status, v_approved, v_current_brief
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
    AND plan.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(MAX(versions.version_no), 0)
    INTO v_latest
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  IF v_latest IS DISTINCT FROM p_base_version THEN
    RAISE EXCEPTION 'brief_version_conflict'
      USING ERRCODE = 'P0001', DETAIL = v_latest::text;
  END IF;

  SELECT audience.description INTO v_old_concept
  FROM public.brief_target_audiences AS audience
  WHERE audience.social_media_plan_id = p_plan_id;

  SELECT caption_row.content INTO v_old_caption
  FROM public.brief_captions AS caption_row
  WHERE caption_row.social_media_plan_id = p_plan_id;

  SELECT link_row.content INTO v_old_link
  FROM public.brief_link_references AS link_row
  WHERE link_row.social_media_plan_id = p_plan_id;

  v_new_brief := COALESCE(p_brief, '');
  v_new_concept := NULLIF(btrim(COALESCE(p_concept, '')), '');
  v_new_caption := NULLIF(btrim(COALESCE(p_caption, '')), '');
  v_new_link := NULLIF(btrim(COALESCE(p_link, '')), '');

  v_storyboard_changed := NULLIF(btrim(v_new_brief), '')
    IS DISTINCT FROM NULLIF(btrim(COALESCE(v_current_brief, '')), '');
  v_concept_changed := v_new_concept IS DISTINCT FROM NULLIF(btrim(COALESCE(v_old_concept, '')), '');
  v_caption_changed := v_new_caption IS DISTINCT FROM NULLIF(btrim(COALESCE(v_old_caption, '')), '');
  v_link_changed := v_new_link IS DISTINCT FROM NULLIF(btrim(COALESCE(v_old_link, '')), '');
  v_changed := v_storyboard_changed OR v_concept_changed OR v_caption_changed OR v_link_changed;

  IF v_storyboard_changed AND NOT public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard', p_user_id) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
  END IF;

  IF v_concept_changed AND NOT public.can_edit_content_brief_field(p_plan_id, 'brief_concept', p_user_id) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_concept';
  END IF;

  IF v_caption_changed AND NOT public.can_edit_content_brief_field(p_plan_id, 'brief_caption', p_user_id) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_caption';
  END IF;

  IF v_link_changed AND NOT public.can_edit_content_brief_field(p_plan_id, 'brief_link', p_user_id) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_link';
  END IF;

  IF v_changed AND public.content_brief_revision_locked(p_plan_id) THEN
    RAISE EXCEPTION 'brief_edit_locked' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
    VALUES (p_confirm_id, p_organization_id, p_user_id, 'content.briefs.update');
  EXCEPTION
    WHEN unique_violation THEN
      RAISE EXCEPTION 'confirmation_used' USING ERRCODE = 'P0001';
  END;

  IF v_changed THEN
    PERFORM public.content_brief_snapshot(p_plan_id, p_user_id, 'mcp');
  END IF;

  IF v_storyboard_changed THEN
    -- guard_social_media_plan_brief_pic has no auth.uid() for MCP writes:
    -- tell it which member is saving (transaction-local).
    PERFORM set_config('mcp.plan_brief_user', p_user_id::text, true);
    UPDATE public.social_media_plans AS plan
    SET brief = v_new_brief,
        updated_at = now()
    WHERE plan.id = p_plan_id;
  END IF;

  IF v_concept_changed THEN
    INSERT INTO public.brief_target_audiences (social_media_plan_id, description, updated_at)
    VALUES (p_plan_id, v_new_concept, now())
    ON CONFLICT (social_media_plan_id) DO UPDATE
    SET description = EXCLUDED.description,
        updated_at = now();
  END IF;

  IF v_caption_changed THEN
    INSERT INTO public.brief_captions (social_media_plan_id, content, updated_at)
    VALUES (p_plan_id, v_new_caption, now())
    ON CONFLICT (social_media_plan_id) DO UPDATE
    SET content = EXCLUDED.content,
        updated_at = now();
  END IF;

  IF v_link_changed THEN
    INSERT INTO public.brief_link_references (social_media_plan_id, content, updated_at)
    VALUES (p_plan_id, v_new_link, now())
    ON CONFLICT (social_media_plan_id) DO UPDATE
    SET content = EXCLUDED.content,
        updated_at = now();
  END IF;

  IF v_changed THEN
    PERFORM public.content_brief_demote_approval(p_plan_id);
  END IF;

  SELECT plan.status, plan.approved
    INTO v_status, v_approved
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id;

  SELECT COALESCE(MAX(versions.version_no), 0)
    INTO v_latest
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  id := p_plan_id;
  version_no := v_latest;
  status := v_status;
  approved := COALESCE(v_approved, false);
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_confirm_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_base_version" integer, "p_confirm_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_confirm_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_base_version" integer, "p_confirm_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") IS 'Save a confirmed MCP brief edit. Checks version, field access, and the production lock before recording the confirmation. The snapshot source is mcp.';



CREATE OR REPLACE FUNCTION "public"."mcp_confirm_ingredient_production"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_id" "uuid", "p_qty" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_name text;
  v_unit text;
  v_stock numeric;
  v_avg numeric;
  v_lines jsonb;
BEGIN
  IF p_confirm_id IS NULL OR p_item_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_qty IS NULL OR p_qty <= 0 OR p_qty > 1000000 OR round(p_qty, 3) <> p_qty THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM public.mcp_inventory_manager_guard(p_user_id, p_organization_id);

  INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
  VALUES (p_confirm_id, p_organization_id, p_user_id, 'inventory.production.create');

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
    true
  );

  v_result := public.apply_catalog_ingredient_produce(
    p_organization_id,
    p_outlet_id,
    p_item_id,
    p_qty,
    'mcp:' || p_confirm_id::text
  );

  IF COALESCE((v_result ->> 'skipped')::boolean, false) THEN
    RAISE EXCEPTION 'confirmation_used' USING ERRCODE = '23505';
  END IF;

  SELECT i.name, i.unit_code, io.in_stock, io.avg_cost
    INTO v_name, v_unit, v_stock, v_avg
  FROM public.catalog_ingredients i
  LEFT JOIN public.catalog_ingredient_outlets io ON io.ingredient_id = i.id AND io.outlet_id = p_outlet_id
  WHERE i.id = p_item_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'ingredient', i.name,
           'unit_code', i.unit_code,
           'used', -m.qty_delta,
           'stock_after', m.qty_after
         ) ORDER BY i.name), '[]'::jsonb)
    INTO v_lines
  FROM public.catalog_stock_movements m
  JOIN public.catalog_ingredients i ON i.id = m.ingredient_id
  WHERE m.organization_id = p_organization_id
    AND m.reference_type = 'ingredient_produce'
    AND m.reference_id LIKE 'mcp:' || p_confirm_id::text || ':raw:%';

  RETURN jsonb_build_object(
    'saved', true,
    'outlet_id', p_outlet_id,
    'item_id', p_item_id,
    'item', v_name,
    'unit_code', v_unit,
    'qty', p_qty,
    'stock_after', v_stock,
    'avg_cost_after', v_avg,
    'unit_cost', round((v_result ->> 'unit_cost')::numeric, 2),
    'batch_cost', round((v_result ->> 'batch_cost')::numeric, 2),
    'used', v_lines
  );
END;
$$;


ALTER FUNCTION "public"."mcp_confirm_ingredient_production"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_id" "uuid", "p_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_confirm_inventory_purchase_order"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_confirm_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM public.mcp_inventory_manager_guard(p_user_id, p_organization_id);

  INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
  VALUES (p_confirm_id, p_organization_id, p_user_id, 'inventory.purchase_order.create');

  RETURN public.mcp_create_inventory_purchase_order(
    p_user_id,
    p_organization_id,
    p_outlet_id,
    p_search,
    p_qty,
    p_unit_cost,
    p_supplier_id,
    p_note
  );
END;
$$;


ALTER FUNCTION "public"."mcp_confirm_inventory_purchase_order"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_confirm_receive_purchase_order"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_total" numeric, "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_comment text;
  v_total numeric;
BEGIN
  IF p_confirm_id IS NULL OR p_purchase_order_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  PERFORM public.mcp_po_receive_member_guard(p_user_id, p_organization_id);

  v_comment := NULLIF(btrim(COALESCE(p_comment, '')), '');
  IF v_comment IS NOT NULL AND char_length(v_comment) > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT po.total_value INTO v_total
  FROM public.catalog_purchase_orders po
  WHERE po.id = p_purchase_order_id
    AND po.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_expected_total IS NULL OR v_total IS DISTINCT FROM p_expected_total THEN
    RAISE EXCEPTION 'catalog_po_changed' USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
  VALUES (p_confirm_id, p_organization_id, p_user_id, 'inventory.purchase_order.receive');

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user_id, 'role', 'authenticated')::text, true);

  PERFORM public.fulfill_catalog_purchase_order(
    p_organization_id,
    p_purchase_order_id,
    COALESCE(v_comment, 'Diterima lewat chat')
  );

  RETURN public.mcp_po_receive_snapshot(p_organization_id, p_purchase_order_id)
    || jsonb_build_object('saved', true, 'stock_received', true);
END;
$$;


ALTER FUNCTION "public"."mcp_confirm_receive_purchase_order"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_expected_total" numeric, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_confirm_stock_adjustment"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_qty_before" numeric, "p_qty_change" numeric, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now numeric;
  v_result jsonb;
BEGIN
  IF p_confirm_id IS NULL OR p_qty_change IS NULL OR p_qty_change = 0
     OR NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id AND uo.organization_id = p_organization_id AND COALESCE(uo.is_active, true)
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
  IF NOT public.catalog_can_adjust_stock(p_user_id, p_organization_id) THEN
    RAISE EXCEPTION 'catalog_adjustment_forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_item_kind = 'ingredient' THEN
    SELECT io.in_stock INTO v_now FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = p_ingredient_id AND io.outlet_id = p_outlet_id;
  ELSIF p_variant_id IS NOT NULL THEN
    SELECT COALESCE((SELECT vo.in_stock FROM public.catalog_product_variant_outlets vo
      WHERE vo.variant_id = p_variant_id AND vo.outlet_id = p_outlet_id), 0) INTO v_now;
  ELSE
    SELECT link.in_stock INTO v_now FROM public.catalog_product_outlets link
    WHERE link.product_id = p_product_id AND link.outlet_id = p_outlet_id;
  END IF;

  IF COALESCE(v_now, 0) IS DISTINCT FROM p_qty_before THEN
    RAISE EXCEPTION 'catalog_adjustment_stock_changed' USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
  VALUES (p_confirm_id, p_organization_id, p_user_id, 'inventory.adjustment.create');

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user_id, 'role', 'authenticated')::text, true);

  v_result := public.app_apply_catalog_stock_movement(
    p_organization_id, p_outlet_id, p_item_kind, p_product_id, p_variant_id, p_ingredient_id,
    'adjustment', p_qty_change, 'inventory_adjustment', p_confirm_id::text,
    btrim(p_reason) || ' (lewat chat)'
  );

  RETURN jsonb_build_object(
    'saved', true,
    'qty_before', p_qty_before,
    'qty_change', p_qty_change,
    'qty_after', p_qty_before + p_qty_change,
    'movement', v_result
  );
END;
$$;


ALTER FUNCTION "public"."mcp_confirm_stock_adjustment"("p_confirm_id" "uuid", "p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_item_kind" "text", "p_product_id" "uuid", "p_variant_id" "uuid", "p_ingredient_id" "uuid", "p_qty_before" numeric, "p_qty_change" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_company_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_cycle_id" "uuid", "p_title" "text", "p_why_important" "text", "p_status" "text") RETURNS TABLE("id" "uuid", "level" "text", "title" "text", "status" "text", "progress_percentage" double precision, "cycle_id" "uuid", "owner_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_title text;
  v_why text;
  v_status text;
  v_objective public.company_objectives%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_cycle_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.okr_cycles cycle
    WHERE cycle.id = p_cycle_id
      AND cycle.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'invalid_cycle' USING ERRCODE = '22023';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF v_title IS NULL OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_why := NULLIF(btrim(COALESCE(p_why_important, '')), '');
  IF v_why IS NOT NULL AND char_length(v_why) > 2000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_status := COALESCE(NULLIF(btrim(COALESCE(p_status, '')), ''), 'draft');
  IF v_status NOT IN ('draft', 'active') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.company_objectives (
    organization_id,
    cycle_id,
    title,
    why_important,
    status,
    progress_percentage,
    weight,
    owner_id,
    created_by
  )
  VALUES (
    p_organization_id,
    p_cycle_id,
    v_title,
    v_why,
    v_status,
    0,
    100,
    p_user_id,
    p_user_id
  )
  RETURNING * INTO v_objective;

  INSERT INTO public.key_results (
    title,
    target_value,
    current_value,
    unit,
    metric_type,
    progress_percentage,
    weight,
    company_objective_id
  )
  VALUES (
    v_objective.title,
    100,
    0,
    '%',
    'percentage',
    0,
    100,
    v_objective.id
  );

  id := v_objective.id;
  level := 'company';
  title := v_objective.title;
  status := v_objective.status;
  progress_percentage := v_objective.progress_percentage;
  cycle_id := v_objective.cycle_id;
  owner_name := NULL;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_create_company_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_cycle_id" "uuid", "p_title" "text", "p_why_important" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_content_type_id" "uuid", "p_service_id" "uuid", "p_sub_service_id" "uuid", "p_feature_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_post_aspect" "text") RETURNS TABLE("id" "uuid", "title" "text", "content_type_name" "text", "service_name" "text", "sub_service_name" "text", "feature_name" "text", "shot_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_title text;
  v_brief text;
  v_concept text;
  v_caption text;
  v_aspect text;
  v_day date;
  v_post_date timestamptz;
  v_pic uuid;
  v_type_name text;
  v_service_id uuid;
  v_service_name text;
  v_sub_id uuid;
  v_sub_name text;
  v_feature_id uuid;
  v_feature_name text;
  v_feature_service uuid;
  v_locked_sub uuid;
  v_shot_count integer;
  v_doc jsonb;
  v_plan public.social_media_plans%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_content_type_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id
  INTO v_pic
  FROM public.employees emp
  LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
  WHERE emp.organization_id = p_organization_id
    AND emp.user_id = p_user_id
    AND COALESCE(emp.pending_removal, false) = false
    AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
    AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
      NOT IN ('inactive', 'terminated', 'pendingremoval')
  ORDER BY emp.id ASC
  LIMIT 1;

  IF v_pic IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF v_title IS NULL OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT ct.name
  INTO v_type_name
  FROM public.content_types ct
  WHERE ct.id = p_content_type_id
    AND COALESCE(ct.is_active, true) = true
    AND (ct.organization_id = p_organization_id OR ct.organization_id IS NULL);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF (p_sub_service_id IS NOT NULL OR p_feature_id IS NOT NULL) AND p_service_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_service_id IS NOT NULL THEN
    SELECT svc.id, svc.name
    INTO v_service_id, v_service_name
    FROM public.services svc
    WHERE svc.id = p_service_id
      AND svc.organization_id = p_organization_id
      AND COALESCE(svc.is_active, true) = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_sub_service_id IS NOT NULL THEN
    SELECT sub.id, sub.name
    INTO v_sub_id, v_sub_name
    FROM public.sub_services sub
    WHERE sub.id = p_sub_service_id
      AND sub.organization_id = p_organization_id
      AND sub.service_id = v_service_id
      AND COALESCE(sub.is_active, true) = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_feature_id IS NOT NULL THEN
    SELECT feat.feature_name, feat.service_id, feat.sub_service_id
    INTO v_feature_name, v_feature_service, v_locked_sub
    FROM public.product_knowledge_features feat
    WHERE feat.id = p_feature_id
      AND feat.organization_id = p_organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;

    IF v_feature_service IS NOT NULL AND v_feature_service IS DISTINCT FROM v_service_id THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;

    IF v_locked_sub IS NOT NULL THEN
      IF v_sub_id IS NOT NULL AND v_sub_id IS DISTINCT FROM v_locked_sub THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;

      SELECT sub.id, sub.name
      INTO v_sub_id, v_sub_name
      FROM public.sub_services sub
      WHERE sub.id = v_locked_sub
        AND sub.organization_id = p_organization_id
        AND sub.service_id = v_service_id
        AND COALESCE(sub.is_active, true) = true;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_feature_id := p_feature_id;
  END IF;

  IF NULLIF(btrim(COALESCE(p_post_date, '')), '') IS NULL THEN
    v_post_date := NULL;
  ELSE
    IF btrim(p_post_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_post_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_post_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    v_post_date := v_day::timestamp AT TIME ZONE 'Asia/Jakarta';
  END IF;

  v_brief := NULLIF(btrim(COALESCE(p_brief, '')), '');
  IF v_brief IS NULL
    OR char_length(v_brief) > 20000
    OR position('| Timing | Visual | VO (Voice Over) |' IN v_brief) = 0
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer
  INTO v_shot_count
  FROM regexp_split_to_table(split_part(v_brief, '<!--', 1), E'\n') AS raw_line(line)
  WHERE btrim(line) LIKE '|%'
    AND btrim(line) NOT LIKE '| Timing | Visual | VO (Voice Over) |%'
    AND btrim(line) NOT LIKE '| ---%';

  IF v_shot_count < 1 OR v_shot_count > 30 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_aspect := NULLIF(btrim(COALESCE(p_post_aspect, '')), '');
  IF v_aspect IS NOT NULL AND v_aspect NOT IN ('4:5', '1:1') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_concept := NULLIF(btrim(COALESCE(p_concept, '')), '');
  IF v_concept IS NOT NULL AND (
    char_length(v_concept) > 20000
    OR left(v_concept, 6) <> '{"v":1'
    OR position('portraitPath' IN v_concept) > 0
    OR position('bodyPath' IN v_concept) > 0
    OR position('locationPath' IN v_concept) > 0
    OR position('propertyPath' IN v_concept) > 0
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_concept IS NOT NULL THEN
    BEGIN
      v_doc := v_concept::jsonb;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END;
    IF COALESCE(v_doc->>'v', '') <> '1' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_doc := v_doc - 'postAspect';
    IF lower(btrim(v_type_name)) IN ('post', 'carousel') AND v_aspect IS NOT NULL THEN
      v_doc := v_doc || jsonb_build_object('postAspect', v_aspect);
    END IF;
    v_concept := v_doc::text;
  ELSIF lower(btrim(v_type_name)) IN ('post', 'carousel') AND v_aspect IS NOT NULL THEN
    v_concept := jsonb_build_object(
      'v', 1,
      'postAspect', v_aspect,
      'locations', '[]'::jsonb,
      'characters', '[]'::jsonb,
      'properties', '[]'::jsonb
    )::text;
  END IF;

  v_caption := NULLIF(btrim(COALESCE(p_caption, '')), '');
  IF v_caption IS NOT NULL AND char_length(v_caption) > 2200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.social_media_plans (
    organization_id,
    title,
    brief,
    post_date,
    content_type_id,
    service_id,
    sub_service_id,
    feature_id,
    pic_id
  )
  VALUES (
    p_organization_id,
    v_title,
    v_brief,
    v_post_date,
    p_content_type_id,
    v_service_id,
    v_sub_id,
    v_feature_id,
    v_pic
  )
  RETURNING * INTO v_plan;

  IF v_caption IS NOT NULL THEN
    INSERT INTO public.brief_captions (social_media_plan_id, content)
    VALUES (v_plan.id, v_caption);
  END IF;

  IF v_concept IS NOT NULL THEN
    INSERT INTO public.brief_target_audiences (social_media_plan_id, description)
    VALUES (v_plan.id, v_concept);
  END IF;

  id := v_plan.id;
  title := v_plan.title;
  content_type_name := v_type_name;
  service_name := v_service_name;
  sub_service_name := v_sub_name;
  feature_name := v_feature_name;
  shot_count := v_shot_count;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_content_type_id" "uuid", "p_service_id" "uuid", "p_sub_service_id" "uuid", "p_feature_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_post_aspect" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_content_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_brief" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "post_date" timestamp with time zone, "approved" boolean, "production_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_title text;
  v_brief text;
  v_day date;
  v_post_date timestamptz;
  v_pic uuid;
  v_plan public.social_media_plans%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id
  INTO v_pic
  FROM public.employees emp
  LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
  WHERE emp.organization_id = p_organization_id
    AND emp.user_id = p_user_id
    AND COALESCE(emp.pending_removal, false) = false
    AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
    AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
      NOT IN ('inactive', 'terminated', 'pendingremoval')
  ORDER BY emp.id ASC
  LIMIT 1;

  IF v_pic IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF v_title IS NULL OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_brief := NULLIF(btrim(COALESCE(p_brief, '')), '');
  IF v_brief IS NOT NULL AND char_length(v_brief) > 4000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NULLIF(btrim(COALESCE(p_post_date, '')), '') IS NULL THEN
    v_post_date := NULL;
  ELSE
    IF btrim(p_post_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_post_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_post_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    v_post_date := v_day::timestamp AT TIME ZONE 'Asia/Jakarta';
  END IF;

  INSERT INTO public.social_media_plans (
    organization_id,
    title,
    brief,
    post_date,
    pic_id
  )
  VALUES (
    p_organization_id,
    v_title,
    v_brief,
    v_post_date,
    v_pic
  )
  RETURNING * INTO v_plan;

  id := v_plan.id;
  title := v_plan.title;
  status := v_plan.status;
  post_date := v_plan.post_date;
  approved := v_plan.approved;
  production_status := v_plan.production_status;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_content_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_brief" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_department_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_company_objective_id" "uuid", "p_department_id" "uuid", "p_title" "text", "p_description" "text", "p_status" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "progress_percentage" double precision, "cycle_id" "uuid", "company_objective_id" "uuid", "department_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_title text;
  v_description text;
  v_status text;
  v_cycle uuid;
  v_department uuid;
  v_row public.department_objectives%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_company_objective_id IS NULL OR p_department_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_description IS NULL OR btrim(p_description) = '' THEN
    v_description := NULL;
  ELSIF char_length(btrim(p_description)) > 2000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  ELSE
    v_description := btrim(p_description);
  END IF;

  v_status := COALESCE(NULLIF(btrim(COALESCE(p_status, '')), ''), 'active');
  IF v_status NOT IN ('draft', 'active') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT objective.cycle_id
  INTO v_cycle
  FROM public.company_objectives objective
  WHERE objective.id = p_company_objective_id
    AND objective.organization_id = p_organization_id;
  IF v_cycle IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT dep.id
  INTO v_department
  FROM public.departments dep
  WHERE dep.id = p_department_id
    AND dep.organization_id = p_organization_id
    AND COALESCE(dep.is_active, true) = true;
  IF v_department IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.department_objectives (
    organization_id,
    cycle_id,
    company_objective_id,
    department_id,
    title,
    description,
    status,
    progress_percentage,
    weight,
    owner_id,
    created_by
  )
  VALUES (
    p_organization_id,
    v_cycle,
    p_company_objective_id,
    v_department,
    v_title,
    v_description,
    v_status,
    0,
    100,
    p_user_id,
    p_user_id
  )
  RETURNING * INTO v_row;

  INSERT INTO public.key_results (
    title,
    target_value,
    current_value,
    unit,
    metric_type,
    progress_percentage,
    weight,
    department_objective_id
  )
  VALUES (
    v_row.title,
    100,
    0,
    '%',
    'percentage',
    0,
    100,
    v_row.id
  );

  id := v_row.id;
  title := v_row.title;
  status := v_row.status;
  progress_percentage := v_row.progress_percentage;
  cycle_id := v_row.cycle_id;
  company_objective_id := v_row.company_objective_id;
  department_id := v_row.department_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_create_department_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_company_objective_id" "uuid", "p_department_id" "uuid", "p_title" "text", "p_description" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_expense"("p_user_id" "uuid", "p_organization_id" "uuid", "p_expense_name" "text", "p_amount" numeric, "p_create_date" "text", "p_expense_type" "text", "p_category" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "expense_name" "text", "amount" double precision, "expense_type" "text", "category" "text", "create_date" "date", "status" "text", "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_name text;
  v_day date;
  v_type_input text;
  v_category_input text;
  v_type_id uuid;
  v_type_name text;
  v_category_id uuid;
  v_category_name text;
  v_description text;
  v_row public.expenses%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_name := NULLIF(btrim(COALESCE(p_expense_name, '')), '');
  IF v_name IS NULL OR char_length(v_name) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 9999999999999.99 OR scale(p_amount) > 2 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NULLIF(btrim(COALESCE(p_create_date, '')), '') IS NULL
    OR btrim(p_create_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_day := btrim(p_create_date)::date;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END;
  IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_create_date) THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;

  v_type_input := NULLIF(btrim(COALESCE(p_expense_type, '')), '');
  v_category_input := NULLIF(btrim(COALESCE(p_category, '')), '');
  IF v_type_input IS NULL OR char_length(v_type_input) > 200
    OR v_category_input IS NULL OR char_length(v_category_input) > 200
    OR lower(v_type_input) = 'internal bank transfer' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT et.id, et.name
  INTO v_type_id, v_type_name
  FROM public.expense_types et
  WHERE et.is_active = true
    AND lower(btrim(et.name)) = lower(v_type_input)
    AND (et.organization_id = p_organization_id OR et.organization_id IS NULL)
  ORDER BY (et.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, et.created_at ASC
  LIMIT 1;
  IF v_type_id IS NULL THEN
    RAISE EXCEPTION 'invalid_master' USING ERRCODE = '22023';
  END IF;

  SELECT ec.id, ec.name
  INTO v_category_id, v_category_name
  FROM public.expense_categories ec
  WHERE ec.is_active = true
    AND ec.expense_type_id = v_type_id
    AND lower(btrim(ec.name)) = lower(v_category_input)
    AND (ec.organization_id = p_organization_id OR ec.organization_id IS NULL)
  ORDER BY (ec.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ec.created_at ASC
  LIMIT 1;
  IF v_category_id IS NULL THEN
    RAISE EXCEPTION 'invalid_master' USING ERRCODE = '22023';
  END IF;

  v_description := NULLIF(btrim(COALESCE(p_description, '')), '');
  IF p_description IS NOT NULL AND (v_description IS NULL OR char_length(v_description) > 2000) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.expenses (
    organization_id,
    created_by,
    expense_name,
    amount,
    expense_type,
    expense_type_id,
    category,
    expense_category_id,
    create_date,
    description,
    status,
    is_recurring
  )
  VALUES (
    p_organization_id,
    p_user_id,
    v_name,
    p_amount,
    v_type_name,
    v_type_id,
    v_category_name,
    v_category_id,
    v_day,
    v_description,
    'active',
    false
  )
  RETURNING * INTO v_row;

  id := v_row.id;
  expense_name := v_row.expense_name;
  amount := v_row.amount::double precision;
  expense_type := v_row.expense_type;
  category := v_row.category;
  create_date := v_row.create_date;
  status := v_row.status;
  description := v_row.description;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_expense"("p_user_id" "uuid", "p_organization_id" "uuid", "p_expense_name" "text", "p_amount" numeric, "p_create_date" "text", "p_expense_type" "text", "p_category" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_income_transaction"("p_user_id" "uuid", "p_organization_id" "uuid", "p_transaction_date" "text", "p_amount" numeric, "p_customer_name" "text", "p_payment_method" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "transaction_date" "date", "amount" double precision, "customer_name" "text", "payment_method" "text", "status" "text", "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_day date;
  v_customer text;
  v_method text;
  v_description text;
  v_row public.income_transactions%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(btrim(COALESCE(p_transaction_date, '')), '') IS NULL
    OR btrim(p_transaction_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_day := btrim(p_transaction_date)::date;
  EXCEPTION WHEN others THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END;
  IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_transaction_date) THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 9999999999999.99 OR scale(p_amount) > 2 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_customer := NULLIF(btrim(COALESCE(p_customer_name, '')), '');
  IF p_customer_name IS NOT NULL AND (v_customer IS NULL OR char_length(v_customer) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_method := NULLIF(lower(btrim(COALESCE(p_payment_method, ''))), '');
  IF p_payment_method IS NOT NULL AND (
    v_method IS NULL
    OR v_method NOT IN ('cash', 'credit_card', 'debit_card', 'check', 'digital_wallet', 'other')
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_description := NULLIF(btrim(COALESCE(p_description, '')), '');
  IF p_description IS NOT NULL AND (v_description IS NULL OR char_length(v_description) > 2000) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.income_transactions (
    organization_id,
    user_id,
    created_by,
    transaction_date,
    amount,
    customer_name,
    payment_method,
    description,
    status,
    is_recurring
  )
  VALUES (
    p_organization_id,
    p_user_id,
    p_user_id,
    v_day,
    p_amount,
    v_customer,
    v_method,
    v_description,
    'pending',
    false
  )
  RETURNING * INTO v_row;

  id := v_row.id;
  transaction_date := v_row.transaction_date;
  amount := v_row.amount::double precision;
  customer_name := v_row.customer_name;
  payment_method := v_row.payment_method;
  status := v_row.status;
  description := v_row.description;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_income_transaction"("p_user_id" "uuid", "p_organization_id" "uuid", "p_transaction_date" "text", "p_amount" numeric, "p_customer_name" "text", "p_payment_method" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_individual_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_department_objective_id" "uuid", "p_title" "text", "p_description" "text", "p_status" "text", "p_employee_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "progress_percentage" double precision, "cycle_id" "uuid", "department_objective_id" "uuid", "employee_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_can_assign boolean;
  v_title text;
  v_description text;
  v_status text;
  v_cycle uuid;
  v_department uuid;
  v_employee uuid;
  v_target uuid;
  v_row public.individual_objectives%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_department_objective_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id
  INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = p_user_id
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin', 'hr')
  ) INTO v_can_assign;

  v_employee := COALESCE(p_employee_id, v_self);
  IF v_employee IS DISTINCT FROM v_self AND NOT v_can_assign THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_description IS NULL OR btrim(p_description) = '' THEN
    v_description := NULL;
  ELSIF char_length(btrim(p_description)) > 2000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  ELSE
    v_description := btrim(p_description);
  END IF;

  v_status := COALESCE(NULLIF(btrim(COALESCE(p_status, '')), ''), 'active');
  IF v_status NOT IN ('draft', 'active') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT objective.cycle_id, objective.department_id
  INTO v_cycle, v_department
  FROM public.department_objectives objective
  WHERE objective.id = p_department_objective_id
    AND objective.organization_id = p_organization_id;
  IF v_cycle IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT emp.id
  INTO v_target
  FROM public.employees emp
  LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
  WHERE emp.id = v_employee
    AND emp.organization_id = p_organization_id
    AND emp.department_id = v_department
    AND COALESCE(emp.pending_removal, false) = false
    AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
    AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
      NOT IN ('inactive', 'terminated', 'pendingremoval');
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.individual_objectives (
    organization_id,
    cycle_id,
    department_objective_id,
    employee_id,
    title,
    description,
    status,
    progress_percentage,
    weight,
    created_by
  )
  VALUES (
    p_organization_id,
    v_cycle,
    p_department_objective_id,
    v_target,
    v_title,
    v_description,
    v_status,
    0,
    100,
    p_user_id
  )
  RETURNING * INTO v_row;

  INSERT INTO public.key_results (
    title,
    target_value,
    current_value,
    unit,
    metric_type,
    progress_percentage,
    weight,
    individual_objective_id
  )
  VALUES (
    v_row.title,
    100,
    0,
    '%',
    'percentage',
    0,
    100,
    v_row.id
  );

  id := v_row.id;
  title := v_row.title;
  status := v_row.status;
  progress_percentage := v_row.progress_percentage;
  cycle_id := v_row.cycle_id;
  department_objective_id := v_row.department_objective_id;
  employee_id := v_row.employee_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_create_individual_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_department_objective_id" "uuid", "p_title" "text", "p_description" "text", "p_status" "text", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_inventory_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text;
  v_note text;
  v_outlet_name text;
  v_po_mode text;
  v_fulfill boolean;
  v_count integer := 0;
  v_labels text[] := ARRAY[]::text[];
  v_match record;
  v_kind text;
  v_name text;
  v_variant_name text;
  v_product_id uuid;
  v_variant_id uuid;
  v_ingredient_id uuid;
  v_qty_before numeric;
  v_qty_after numeric;
  v_created jsonb;
  v_status text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    EXISTS (
      SELECT 1
      FROM public.user_roles ur
      WHERE ur.user_id = p_user_id
        AND ur.organization_id = p_organization_id
        AND ur.role = 'owner'::text
    )
    OR EXISTS (
      SELECT 1
      FROM public.organization_omnichannel_staff staff
      INNER JOIN public.employees employee
        ON employee.id = staff.employee_id
       AND employee.user_id = p_user_id
      WHERE staff.organization_id = p_organization_id
        AND staff.role = 'admin'::text
    )
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_search := btrim(COALESCE(p_search, ''));
  IF v_search = '' OR char_length(v_search) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_qty IS NULL
    OR p_qty <= 0
    OR p_qty > 99999999999.999
    OR scale(p_qty) > 3
    OR p_unit_cost IS NULL
    OR p_unit_cost <= 0
    OR p_unit_cost > 999999999999.99
    OR round(p_qty * p_unit_cost, 2) <= 0
    OR round(p_qty * p_unit_cost, 2) > 999999999999.99
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(btrim(COALESCE(p_note, '')), '');
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT outlet.name
    INTO v_outlet_name
  FROM public.pos_outlets outlet
  WHERE outlet.id = p_outlet_id
    AND outlet.organization_id = p_organization_id
    AND outlet.is_deleted = false;

  IF v_outlet_name IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_supplier_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.catalog_suppliers supplier
    WHERE supplier.id = p_supplier_id
      AND supplier.organization_id = p_organization_id
      AND supplier.is_deleted = false
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  FOR v_match IN
    SELECT found.kind, found.name, found.variant_name, found.product_id, found.variant_id,
           found.ingredient_id, found.qty_before, found.label
    FROM (
      SELECT
        'ingredient'::text AS kind,
        i.name,
        NULL::text AS variant_name,
        NULL::uuid AS product_id,
        NULL::uuid AS variant_id,
        i.id AS ingredient_id,
        io.in_stock AS qty_before,
        i.name AS label
      FROM public.catalog_ingredients i
      JOIN public.catalog_ingredient_outlets io
        ON io.ingredient_id = i.id
       AND io.outlet_id = p_outlet_id
       AND io.organization_id = p_organization_id
      WHERE i.organization_id = p_organization_id
        AND i.is_deleted = false
        AND i.track_inventory = true
        AND lower(btrim(i.name)) = lower(v_search)

      UNION ALL

      SELECT
        'product'::text,
        dp.name,
        NULL::text,
        dp.id,
        NULL::uuid,
        NULL::uuid,
        link.in_stock,
        dp.name
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link
        ON link.product_id = dp.id
       AND link.outlet_id = p_outlet_id
       AND link.organization_id = p_organization_id
      WHERE dp.organization_id = p_organization_id
        AND dp.kind = 'product'
        AND dp.track_stock = true
        AND lower(btrim(dp.name)) = lower(v_search)
        AND NOT EXISTS (
          SELECT 1
          FROM public.catalog_product_variants variant
          WHERE variant.product_id = dp.id
        )

      UNION ALL

      SELECT
        'product'::text,
        dp.name,
        variant.name,
        dp.id,
        variant.id,
        NULL::uuid,
        COALESCE(stock.in_stock, 0),
        dp.name || ' / ' || variant.name
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link
        ON link.product_id = dp.id
       AND link.outlet_id = p_outlet_id
       AND link.organization_id = p_organization_id
      JOIN public.catalog_product_variants variant
        ON variant.product_id = dp.id
       AND variant.organization_id = dp.organization_id
      LEFT JOIN public.catalog_product_variant_outlets stock
        ON stock.variant_id = variant.id
       AND stock.outlet_id = p_outlet_id
       AND stock.organization_id = p_organization_id
      WHERE dp.organization_id = p_organization_id
        AND dp.kind = 'product'
        AND dp.track_stock = true
        AND lower(btrim(variant.name)) = lower(v_search)
    ) found
    ORDER BY found.label
  LOOP
    v_count := v_count + 1;
    v_labels := v_labels || v_match.label;
    v_kind := v_match.kind;
    v_name := v_match.name;
    v_variant_name := v_match.variant_name;
    v_product_id := v_match.product_id;
    v_variant_id := v_match.variant_id;
    v_ingredient_id := v_match.ingredient_id;
    v_qty_before := v_match.qty_before;
  END LOOP;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION '%', 'ambiguous: ' || array_to_string(v_labels, ' | ')
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
    (SELECT settings.po_mode
     FROM public.catalog_inventory_settings settings
     WHERE settings.organization_id = p_organization_id),
    'simple'
  )
  INTO v_po_mode;

  v_fulfill := v_po_mode IS DISTINCT FROM 'advanced';

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config(
    'request.jwt.claims',
    json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
    true
  );

  v_created := public.create_catalog_purchase_order(
    p_organization_id,
    p_outlet_id,
    p_supplier_id,
    v_kind,
    v_note,
    jsonb_build_array(jsonb_build_object(
      'product_id', v_product_id,
      'variant_id', v_variant_id,
      'ingredient_id', v_ingredient_id,
      'qty', p_qty,
      'unit_cost', p_unit_cost,
      'name_snapshot', v_labels[1]
    )),
    v_fulfill
  );

  v_status := v_created ->> 'status';

  IF v_kind = 'ingredient' THEN
    SELECT io.in_stock
      INTO v_qty_after
    FROM public.catalog_ingredient_outlets io
    WHERE io.ingredient_id = v_ingredient_id
      AND io.outlet_id = p_outlet_id
      AND io.organization_id = p_organization_id;
  ELSIF v_variant_id IS NOT NULL THEN
    SELECT COALESCE(stock.in_stock, 0)
      INTO v_qty_after
    FROM public.catalog_product_variants variant
    LEFT JOIN public.catalog_product_variant_outlets stock
      ON stock.variant_id = variant.id
     AND stock.outlet_id = p_outlet_id
     AND stock.organization_id = p_organization_id
    WHERE variant.id = v_variant_id;
  ELSE
    SELECT link.in_stock
      INTO v_qty_after
    FROM public.catalog_product_outlets link
    WHERE link.product_id = v_product_id
      AND link.outlet_id = p_outlet_id
      AND link.organization_id = p_organization_id;
  END IF;

  IF v_status IS DISTINCT FROM 'completed' THEN
    v_qty_after := v_qty_before;
  END IF;

  RETURN jsonb_build_object(
    'purchase_order_id', v_created ->> 'id',
    'order_number', v_created ->> 'order_number',
    'status', v_status,
    'po_mode', v_po_mode,
    'stock_received', v_status = 'completed',
    'outlet_id', p_outlet_id,
    'outlet_name', v_outlet_name,
    'kind', v_kind,
    'name', v_name,
    'variant_name', v_variant_name,
    'qty_added', p_qty,
    'unit_cost', p_unit_cost,
    'qty_before', COALESCE(v_qty_before, 0),
    'qty_after', COALESCE(v_qty_after, v_qty_before, 0)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_create_inventory_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_lead"("p_user_id" "uuid", "p_organization_id" "uuid", "p_client" "text", "p_title" "text", "p_category" "text", "p_source" "text", "p_fu_priority" "text", "p_status" "text") RETURNS TABLE("id" "uuid", "ticket_id" "text", "client" "text", "title" "text", "source" "text", "status" "text", "fu_priority" "text", "assignee" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client text;
  v_title text;
  v_category text;
  v_source text;
  v_priority text;
  v_status_name text;
  v_status_id uuid;
  v_employee_id uuid;
  v_employee_name text;
  v_profile_name text;
  v_assignee text;
  v_created_by_name text;
  v_lead_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_client := NULLIF(btrim(COALESCE(p_client, '')), '');
  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  v_category := NULLIF(btrim(COALESCE(p_category, '')), '');
  IF v_client IS NULL OR char_length(v_client) > 200
    OR v_title IS NULL OR char_length(v_title) > 200
    OR v_category IS NULL OR char_length(v_category) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_source := NULLIF(btrim(COALESCE(p_source, '')), '');
  IF v_source IS NOT NULL AND char_length(v_source) > 80 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_priority := NULLIF(btrim(COALESCE(p_fu_priority, '')), '');
  IF v_priority IS NOT NULL AND v_priority NOT IN ('High', 'Medium', 'Low', 'Please Follow Up') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_status_name := NULLIF(btrim(COALESCE(p_status, '')), '');
  IF v_status_name IS NOT NULL THEN
    IF lower(v_status_name) IN ('converted', 'closed', 'resolve') OR char_length(v_status_name) > 80 THEN
      RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
    END IF;
    SELECT ls.id
    INTO v_status_id
    FROM public.lead_statuses ls
    WHERE ls.is_active = true
      AND lower(btrim(ls.name)) = lower(v_status_name)
      AND (ls.organization_id = p_organization_id OR ls.organization_id IS NULL)
    ORDER BY (ls.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ls.sort_order ASC NULLS LAST
    LIMIT 1;
    IF v_status_id IS NULL THEN
      RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
    END IF;
  END IF;

  SELECT employee.id, NULLIF(btrim(employee.full_name), '')
  INTO v_employee_id, v_employee_name
  FROM public.employees employee
  WHERE employee.user_id = p_user_id
    AND employee.organization_id = p_organization_id
  ORDER BY employee.id ASC
  LIMIT 1;

  SELECT NULLIF(btrim(profile.full_name), '')
  INTO v_profile_name
  FROM public.profiles profile
  WHERE profile.user_id = p_user_id
  LIMIT 1;

  v_assignee := COALESCE(v_employee_name, v_profile_name, 'Unknown');
  v_created_by_name := COALESCE(v_profile_name, v_employee_name, 'Unknown');

  INSERT INTO public.leads AS lead (
    client,
    title,
    category,
    assignee,
    assignee_id,
    fu_priority,
    source,
    status_id,
    organization_id,
    created_by,
    created_by_name,
    followup
  )
  VALUES (
    v_client,
    v_title,
    v_category,
    v_assignee,
    v_employee_id,
    COALESCE(v_priority, 'Please Follow Up'),
    COALESCE(v_source, 'Website'),
    v_status_id,
    p_organization_id,
    p_user_id,
    v_created_by_name,
    0
  )
  RETURNING lead.id INTO v_lead_id;

  RETURN QUERY
  SELECT
    lead.id,
    lead.ticket_id,
    lead.client,
    lead.title,
    lead.source,
    ls.name,
    lead.fu_priority,
    lead.assignee,
    lead.created_at
  FROM public.leads lead
  LEFT JOIN public.lead_statuses ls ON ls.id = lead.status_id
  WHERE lead.id = v_lead_id;
END;
$$;


ALTER FUNCTION "public"."mcp_create_lead"("p_user_id" "uuid", "p_organization_id" "uuid", "p_client" "text", "p_title" "text", "p_category" "text", "p_source" "text", "p_fu_priority" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_recipe_draft"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_product_name" "text", "p_lines" "jsonb", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_product uuid;
  v_count integer;
  v_labels text;
  v_elem jsonb;
  v_name text;
  v_unit text;
  v_qty numeric;
  v_ing record;
  v_factor_in numeric;
  v_factor_ing numeric;
  v_base numeric;
  v_missing text[] := ARRAY[]::text[];
  v_mismatch text[] := ARRAY[]::text[];
  v_small text[] := ARRAY[]::text[];
  v_lines jsonb := '[]'::jsonb;
  v_id uuid;
  v_mass constant jsonb := '{"mg":0.000001,"g":0.001,"ons":0.1,"kg":1}';
  v_volume constant jsonb := '{"ml":0.001,"l":1}';
BEGIN
  IF NOT public._recipe_is_member(p_user_id, p_organization_id) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
  IF NOT public._recipe_is_manager(p_user_id, p_organization_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array'
    OR jsonb_array_length(p_lines) < 1 OR jsonb_array_length(p_lines) > 50 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_outlet_id IS NULL THEN
    SELECT o.id INTO v_outlet FROM public.pos_outlets o
    WHERE o.organization_id = p_organization_id AND o.is_deleted = false AND o.is_active = true
    ORDER BY o.is_default DESC, o.sort_order, o.created_at LIMIT 1;
  ELSE
    SELECT o.id INTO v_outlet FROM public.pos_outlets o
    WHERE o.id = p_outlet_id AND o.organization_id = p_organization_id AND o.is_deleted = false;
  END IF;
  IF v_outlet IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*), max(dp.id::text), string_agg(dp.name, ' | ')
    INTO v_count, v_labels, v_name
  FROM public.default_prices dp
  WHERE dp.organization_id = p_organization_id AND dp.kind = 'product'
    AND lower(btrim(dp.name)) = lower(btrim(COALESCE(p_product_name, '')));
  IF v_count = 0 THEN
    RAISE EXCEPTION 'menu_not_found' USING ERRCODE = 'P0002';
  ELSIF v_count > 1 THEN
    RAISE EXCEPTION '%', 'ambiguous: ' || v_name USING ERRCODE = '22023';
  END IF;
  v_product := v_labels::uuid;

  FOR v_elem IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_name := btrim(COALESCE(v_elem ->> 'ingredient', ''));
    v_unit := lower(btrim(COALESCE(v_elem ->> 'unit', '')));
    BEGIN
      v_qty := (v_elem ->> 'quantity')::numeric;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END;
    IF v_name = '' OR v_unit = '' OR v_qty IS NULL OR v_qty <= 0 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;

    SELECT i.id, i.name, i.unit_code INTO v_ing
    FROM public.catalog_ingredients i
    WHERE i.organization_id = p_organization_id AND i.is_deleted = false
      AND lower(btrim(i.name)) = lower(v_name)
    LIMIT 1;
    IF NOT FOUND THEN
      v_missing := v_missing || v_name;
      CONTINUE;
    END IF;

    IF v_unit = lower(v_ing.unit_code) THEN
      v_base := v_qty;
    ELSIF v_mass ? v_unit AND v_mass ? lower(v_ing.unit_code) THEN
      v_factor_in := (v_mass ->> v_unit)::numeric;
      v_factor_ing := (v_mass ->> lower(v_ing.unit_code))::numeric;
      v_base := v_qty * v_factor_in / v_factor_ing;
    ELSIF v_volume ? v_unit AND v_volume ? lower(v_ing.unit_code) THEN
      v_factor_in := (v_volume ->> v_unit)::numeric;
      v_factor_ing := (v_volume ->> lower(v_ing.unit_code))::numeric;
      v_base := v_qty * v_factor_in / v_factor_ing;
    ELSE
      v_mismatch := v_mismatch || (v_ing.name || ' (' || v_ing.unit_code || ')');
      CONTINUE;
    END IF;

    IF round(v_base, 3) <= 0 THEN
      v_small := v_small || (v_ing.name || ' (' || v_ing.unit_code || ')');
      CONTINUE;
    END IF;

    v_lines := v_lines || jsonb_build_object('ingredient_id', v_ing.id, 'quantity', round(v_base, 3));
  END LOOP;

  IF cardinality(v_missing) > 0 THEN
    RAISE EXCEPTION '%', 'ingredient_not_found: ' || array_to_string(v_missing, ' | ') USING ERRCODE = 'P0002';
  END IF;
  IF cardinality(v_mismatch) > 0 THEN
    RAISE EXCEPTION '%', 'unit_mismatch: ' || array_to_string(v_mismatch, ' | ') USING ERRCODE = '22023';
  END IF;
  IF cardinality(v_small) > 0 THEN
    RAISE EXCEPTION '%', 'recipe_draft_quantity_too_small: ' || array_to_string(v_small, ' | ') USING ERRCODE = '22023';
  END IF;

  v_id := public._recipe_draft_insert(p_user_id, p_organization_id, v_outlet, v_product, v_lines, p_note, 'claude');
  RETURN public._recipe_draft_review(v_id, p_user_id);
END;
$$;


ALTER FUNCTION "public"."mcp_create_recipe_draft"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_product_name" "text", "p_lines" "jsonb", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_description" "text", "p_priority" "text", "p_due_date" "text", "p_employee_id" "uuid", "p_plan_month" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "priority" "text", "due_date" timestamp with time zone, "plan_month" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_can_assign boolean;
  v_title text;
  v_description text;
  v_priority text;
  v_due timestamptz;
  v_plan_month text;
  v_plan timestamptz;
  v_row public.daily_tasks%ROWTYPE;
  v_assignment uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = p_user_id
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin', 'hr')
  ) INTO v_can_assign;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_description IS NULL OR btrim(p_description) = '' THEN
    v_description := '';
  ELSIF char_length(btrim(p_description)) > 2000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  ELSE
    v_description := btrim(p_description);
  END IF;

  v_priority := COALESCE(NULLIF(btrim(COALESCE(p_priority, '')), ''), 'medium');
  IF v_priority NOT IN ('low', 'medium', 'high', 'urgent', 'needs_to_be_presented') THEN
    RAISE EXCEPTION 'invalid_priority' USING ERRCODE = '22023';
  END IF;

  v_plan_month := NULLIF(btrim(COALESCE(p_plan_month, '')), '');
  IF v_plan_month IS NULL OR v_plan_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_plan := (v_plan_month || '-01 00:00:00')::timestamp AT TIME ZONE 'UTC';

  IF p_due_date IS NOT NULL AND btrim(p_due_date) <> '' THEN
    IF btrim(p_due_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_due := (btrim(p_due_date) || ' 17:00:00')::timestamp AT TIME ZONE 'Asia/Jakarta';
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_due AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_due_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_employee_id IS NOT NULL THEN
    IF p_employee_id IS DISTINCT FROM v_self AND NOT v_can_assign THEN
      RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM public.employees emp
      WHERE emp.id = p_employee_id AND emp.organization_id = p_organization_id
    ) THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  INSERT INTO public.daily_tasks (
    organization_id, title, description, status, priority, due_date, plan_date, created_by
  )
  VALUES (
    p_organization_id, v_title, v_description, 'pending', v_priority, v_due, v_plan, p_user_id
  )
  RETURNING * INTO v_row;

  IF p_employee_id IS NOT NULL THEN
    INSERT INTO public.daily_tasks_assigned (
      organization_id, daily_task_id, employee_id, assigned_by
    )
    VALUES (p_organization_id, v_row.id, p_employee_id, v_self)
    RETURNING daily_tasks_assigned.id INTO v_assignment;

    IF v_due IS NOT NULL THEN
      INSERT INTO public.task_steps_assigned_duedate (
        organization_id, daily_tasks_assigned_id, due_date
      )
      VALUES (p_organization_id, v_assignment, v_due);
    END IF;
  END IF;

  id := v_row.id;
  title := v_row.title;
  status := v_row.status;
  priority := v_row.priority;
  due_date := v_row.due_date;
  plan_month := to_char(v_row.plan_date AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM');
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_description" "text", "p_priority" "text", "p_due_date" "text", "p_employee_id" "uuid", "p_plan_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid", "p_title" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "title" "text", "step_order" integer, "is_completed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_title text;
  v_description text;
  v_order integer;
  v_id uuid;
  v_done boolean;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_task_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_description IS NULL OR btrim(p_description) = '' THEN
    v_description := NULL;
  ELSIF char_length(btrim(p_description)) > 2000 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  ELSE
    v_description := btrim(p_description);
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.daily_tasks task
    WHERE task.id = p_task_id
      AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(MAX(step."order"), 0) + 1 INTO v_order
  FROM public.task_steps step
  WHERE step.task_id = p_task_id;

  INSERT INTO public.task_steps (task_id, title, description, is_completed, "order", created_by)
  VALUES (p_task_id, v_title, v_description, false, v_order, p_user_id)
  RETURNING task_steps.id, task_steps.title, task_steps."order", task_steps.is_completed
  INTO v_id, v_title, v_order, v_done;

  UPDATE public.daily_tasks task
  SET
    has_steps = true,
    status = CASE WHEN lower(task.status) = 'completed' THEN 'pending' ELSE task.status END,
    updated_at = now()
  WHERE task.id = p_task_id
    AND task.organization_id = p_organization_id;

  id := v_id;
  title := v_title;
  step_order := v_order;
  is_completed := v_done;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_create_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid", "p_title" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_task_substep"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid", "p_title" "text") RETURNS TABLE("id" "uuid", "step_id" "uuid", "title" "text", "substep_order" integer, "is_completed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_title text;
  v_order integer;
  v_id uuid;
  v_done boolean;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_step_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.task_steps step
    JOIN public.daily_tasks task ON task.id = step.task_id
    WHERE step.id = p_step_id
      AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(MAX(sub."order"), 0) + 1 INTO v_order
  FROM public.task_steps_to_steps sub
  WHERE sub.parent_step_id = p_step_id;

  INSERT INTO public.task_steps_to_steps (
    parent_step_id,
    organization_id,
    title,
    is_completed,
    "order",
    created_by
  )
  VALUES (p_step_id, p_organization_id, v_title, false, v_order, p_user_id)
  RETURNING
    task_steps_to_steps.id,
    task_steps_to_steps.title,
    task_steps_to_steps."order",
    task_steps_to_steps.is_completed
  INTO v_id, v_title, v_order, v_done;

  UPDATE public.task_steps step
  SET
    is_completed = false,
    completed_at = NULL,
    updated_at = now()
  WHERE step.id = p_step_id
    AND step.is_completed = true;

  id := v_id;
  step_id := p_step_id;
  title := v_title;
  substep_order := v_order;
  is_completed := v_done;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_create_task_substep"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_thinking_master"("p_user_id" "uuid", "p_organization_id" "uuid", "p_statement" "text", "p_prior_belief" "text", "p_audience" "text", "p_facts" "jsonb", "p_fingerprint" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_id uuid;
  v_statement text := btrim(COALESCE(p_statement, ''));
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  IF v_statement = '' OR btrim(COALESCE(p_prior_belief, '')) = '' OR p_facts IS NULL OR btrim(COALESCE(p_fingerprint, '')) = '' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.thinking_master_thoughts (
    organization_id, statement, original_input, prior_belief, audience, root_belief,
    confirmation_source, confirmed_at, mt_status, status, workspace,
    canonical_semantic, semantic_fingerprint, created_by
  ) VALUES (
    p_organization_id, v_statement, v_statement, btrim(p_prior_belief), btrim(COALESCE(p_audience, '')), v_statement,
    'original', now(), 'confirmed', 'draft', 'thinking_lab',
    p_facts, p_fingerprint, p_user_id
  )
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


ALTER FUNCTION "public"."mcp_create_thinking_master"("p_user_id" "uuid", "p_organization_id" "uuid", "p_statement" "text", "p_prior_belief" "text", "p_audience" "text", "p_facts" "jsonb", "p_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_create_thinking_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_content_type_id" "uuid", "p_service_id" "uuid", "p_sub_service_id" "uuid", "p_feature_id" "uuid", "p_content_pillar_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text") RETURNS TABLE("id" "uuid", "title" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_pic uuid;
  v_title text;
  v_type_name text;
  v_service_id uuid;
  v_service_name text;
  v_sub_id uuid;
  v_sub_name text;
  v_feature_id uuid;
  v_feature_name text;
  v_feature_service uuid;
  v_locked_sub uuid;
  v_pillar_name text;
  v_post_date timestamp;
  v_day date;
  v_brief text;
  v_concept text;
  v_caption text;
  v_doc jsonb;
  v_shot_count integer;
  v_plan public.social_media_plans%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_content_type_id IS NULL OR p_content_pillar_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id
  INTO v_pic
  FROM public.employees emp
  LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
  WHERE emp.organization_id = p_organization_id
    AND emp.user_id = p_user_id
    AND COALESCE(emp.pending_removal, false) = false
    AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
    AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
      NOT IN ('inactive', 'terminated', 'pendingremoval')
  ORDER BY emp.id ASC
  LIMIT 1;

  IF v_pic IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT pillar.name
  INTO v_pillar_name
  FROM public.content_pillars pillar
  WHERE pillar.id = p_content_pillar_id
    AND pillar.is_active = true
    AND (pillar.organization_id = p_organization_id OR pillar.is_default = true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF v_title IS NULL OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT ct.name
  INTO v_type_name
  FROM public.content_types ct
  WHERE ct.id = p_content_type_id
    AND COALESCE(ct.is_active, true) = true
    AND (ct.organization_id = p_organization_id OR ct.organization_id IS NULL);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF (p_sub_service_id IS NOT NULL OR p_feature_id IS NOT NULL) AND p_service_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_service_id IS NOT NULL THEN
    SELECT svc.id, svc.name
    INTO v_service_id, v_service_name
    FROM public.services svc
    WHERE svc.id = p_service_id
      AND svc.organization_id = p_organization_id
      AND COALESCE(svc.is_active, true) = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_sub_service_id IS NOT NULL THEN
    SELECT sub.id, sub.name
    INTO v_sub_id, v_sub_name
    FROM public.sub_services sub
    WHERE sub.id = p_sub_service_id
      AND sub.organization_id = p_organization_id
      AND sub.service_id = v_service_id
      AND COALESCE(sub.is_active, true) = true;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF p_feature_id IS NOT NULL THEN
    SELECT feat.feature_name, feat.service_id, feat.sub_service_id
    INTO v_feature_name, v_feature_service, v_locked_sub
    FROM public.product_knowledge_features feat
    WHERE feat.id = p_feature_id
      AND feat.organization_id = p_organization_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;

    IF v_feature_service IS NOT NULL AND v_feature_service IS DISTINCT FROM v_service_id THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;

    IF v_locked_sub IS NOT NULL THEN
      IF v_sub_id IS NOT NULL AND v_sub_id IS DISTINCT FROM v_locked_sub THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;

      SELECT sub.id, sub.name
      INTO v_sub_id, v_sub_name
      FROM public.sub_services sub
      WHERE sub.id = v_locked_sub
        AND sub.organization_id = p_organization_id
        AND sub.service_id = v_service_id
        AND COALESCE(sub.is_active, true) = true;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
      END IF;
    END IF;

    v_feature_id := p_feature_id;
  END IF;

  IF NULLIF(btrim(COALESCE(p_post_date, '')), '') IS NULL THEN
    v_post_date := NULL;
  ELSE
    IF btrim(p_post_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_post_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_post_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    v_post_date := v_day::timestamp AT TIME ZONE 'Asia/Jakarta';
  END IF;

  v_brief := NULLIF(btrim(COALESCE(p_brief, '')), '');
  IF v_brief IS NULL
    OR char_length(v_brief) > 200000
    OR position('| Timing | Visual | VO (Voice Over) |' IN v_brief) = 0
    OR position('| Shot |' IN v_brief) = 0
    OR position('Veo 3 prompt' IN v_brief) = 0
    OR position('Master prompt' IN v_brief) = 0
    OR position('portraitPath' IN v_brief) > 0
    OR position('bodyPath' IN v_brief) > 0
    OR position('sheetPath' IN v_brief) > 0
    OR position('locationPath' IN v_brief) > 0
    OR position('propertyPath' IN v_brief) > 0
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT count(*)::integer
  INTO v_shot_count
  FROM regexp_split_to_table(split_part(v_brief, '<!--', 1), E'\n') AS raw_line(line)
  WHERE btrim(line) LIKE '|%'
    AND btrim(line) NOT LIKE '| Timing | Visual | VO (Voice Over) |%'
    AND btrim(line) NOT LIKE '| ---%';

  IF v_shot_count < 1 OR v_shot_count > 576 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_concept := NULLIF(btrim(COALESCE(p_concept, '')), '');
  IF v_concept IS NOT NULL AND (
    char_length(v_concept) > 20000
    OR left(v_concept, 6) <> '{"v":1'
    OR position('portraitPath' IN v_concept) > 0
    OR position('bodyPath' IN v_concept) > 0
    OR position('sheetPath' IN v_concept) > 0
    OR position('locationPath' IN v_concept) > 0
    OR position('propertyPath' IN v_concept) > 0
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_concept IS NOT NULL THEN
    BEGIN
      v_doc := v_concept::jsonb;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END;
    IF COALESCE(v_doc->>'v', '') <> '1' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_caption := NULLIF(btrim(COALESCE(p_caption, '')), '');
  IF v_caption IS NOT NULL AND char_length(v_caption) > 2200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.social_media_plans (
    organization_id,
    title,
    brief,
    post_date,
    content_type_id,
    service_id,
    sub_service_id,
    feature_id,
    pic_id,
    content_pillar_id
  )
  VALUES (
    p_organization_id,
    v_title,
    v_brief,
    v_post_date,
    p_content_type_id,
    v_service_id,
    v_sub_id,
    v_feature_id,
    v_pic,
    p_content_pillar_id
  )
  RETURNING * INTO v_plan;

  IF v_caption IS NOT NULL THEN
    INSERT INTO public.brief_captions (social_media_plan_id, content)
    VALUES (v_plan.id, v_caption);
  END IF;

  IF v_concept IS NOT NULL THEN
    INSERT INTO public.brief_target_audiences (social_media_plan_id, description)
    VALUES (v_plan.id, v_concept);
  END IF;

  id := v_plan.id;
  title := v_plan.title;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_create_thinking_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_title" "text", "p_post_date" "text", "p_content_type_id" "uuid", "p_service_id" "uuid", "p_sub_service_id" "uuid", "p_feature_id" "uuid", "p_content_pillar_id" "uuid", "p_brief" "text", "p_concept" "text", "p_caption" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.daily_tasks task
    WHERE task.id = p_id AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_tasks_assigned assigned
    WHERE assigned.daily_task_id = p_id AND assigned.organization_id = p_organization_id
  ) OR EXISTS (
    SELECT 1
    FROM public.task_steps step
    JOIN public.task_steps_assigned assigned ON assigned.task_step_id = step.id
    WHERE step.task_id = p_id
  ) OR EXISTS (
    SELECT 1
    FROM public.task_steps step
    JOIN public.task_steps_to_steps sub ON sub.parent_step_id = step.id
    JOIN public.task_steps_to_steps_assigned assigned ON assigned.task_steps_to_steps_id = sub.id
    WHERE step.task_id = p_id
  ) THEN
    RAISE EXCEPTION 'not_deletable' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.daily_tasks task
  WHERE task.id = p_id
    AND task.organization_id = p_organization_id
  RETURNING task.id INTO v_id;

  id := v_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_delete_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_delete_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_task_id uuid;
  v_plan_id uuid;
  v_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT step.task_id, step.social_media_plan_id
  INTO v_task_id, v_plan_id
  FROM public.task_steps step
  JOIN public.daily_tasks task ON task.id = step.task_id
  WHERE step.id = p_id
    AND task.organization_id = p_organization_id;

  IF v_task_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_plan_id IS NOT NULL
    OR EXISTS (
      SELECT 1 FROM public.task_steps_assigned assigned
      WHERE assigned.task_step_id = p_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.task_steps_to_steps sub
      JOIN public.task_steps_to_steps_assigned assigned
        ON assigned.task_steps_to_steps_id = sub.id
      WHERE sub.parent_step_id = p_id
    )
  THEN
    RAISE EXCEPTION 'not_deletable' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.task_steps step
  WHERE step.id = p_id
  RETURNING step.id INTO v_id;

  IF NOT EXISTS (
    SELECT 1 FROM public.task_steps step WHERE step.task_id = v_task_id
  ) THEN
    UPDATE public.daily_tasks task
    SET has_steps = false, updated_at = now()
    WHERE task.id = v_task_id
      AND task.organization_id = p_organization_id;
  END IF;

  id := v_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_delete_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_drive_link_key"("p_url" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_url IS NULL OR btrim(p_url) = '' THEN ''
    WHEN lower(btrim(p_url)) LIKE '%drive.google.com/drive/folders/%'
      AND btrim(p_url) ~* '/folders/([a-zA-Z0-9_-]+)'
      THEN 'folder:' || (regexp_match(btrim(p_url), '/folders/([a-zA-Z0-9_-]+)', 'i'))[1]
    WHEN btrim(p_url) ILIKE '%drive.google.com%' AND btrim(p_url) ~* '/file/d/([a-zA-Z0-9_-]+)'
      THEN 'file:' || (regexp_match(btrim(p_url), '/file/d/([a-zA-Z0-9_-]+)', 'i'))[1]
    WHEN btrim(p_url) ILIKE '%drive.google.com%' AND btrim(p_url) ~* '/d/([a-zA-Z0-9_-]+)'
      THEN 'file:' || (regexp_match(btrim(p_url), '/d/([a-zA-Z0-9_-]+)', 'i'))[1]
    WHEN btrim(p_url) ILIKE '%drive.google.com%' AND btrim(p_url) ~* '[?&]id=([a-zA-Z0-9_-]+)'
      THEN 'file:' || (regexp_match(btrim(p_url), '[?&]id=([a-zA-Z0-9_-]+)', 'i'))[1]
    ELSE lower(split_part(split_part(btrim(p_url), '?', 1), '#', 1))
  END;
$$;


ALTER FUNCTION "public"."mcp_drive_link_key"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_ensure_brief_storyboard_shots"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_row_count" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_index integer;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_plan_id IS NULL
     OR p_row_count IS NULL OR p_row_count < 0 OR p_row_count > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations AS member
    WHERE member.user_id = p_user_id
      AND member.organization_id = p_organization_id
      AND COALESCE(member.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  PERFORM 1
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
    AND plan.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
    INTO v_count
  FROM public.brief_storyboard_shots AS shot
  WHERE shot.social_media_plan_id = p_plan_id;

  -- Only fill a plan that has no ids yet. A plan whose ids exist is left alone,
  -- even when the count differs; the Office editor owns row moves.
  IF v_count > 0 OR p_row_count = 0 THEN
    RETURN v_count;
  END IF;

  FOR v_index IN 0..(p_row_count - 1) LOOP
    INSERT INTO public.brief_storyboard_shots (social_media_plan_id, row_index)
    VALUES (p_plan_id, v_index);
  END LOOP;

  UPDATE public.brief_voice_clips AS clip
  SET shot_id = shot.id
  FROM public.brief_storyboard_shots AS shot
  WHERE clip.social_media_plan_id = p_plan_id
    AND shot.social_media_plan_id = p_plan_id
    AND clip.kind = 'vo'
    AND clip.shot_id IS NULL
    AND clip.row_index = shot.row_index;

  UPDATE public.brief_storyboard_images AS image
  SET shot_id = shot.id
  FROM public.brief_storyboard_shots AS shot
  WHERE image.social_media_plan_id = p_plan_id
    AND shot.social_media_plan_id = p_plan_id
    AND image.column_index = 1
    AND image.shot_id IS NULL
    AND image.row_index = shot.row_index;

  RETURN p_row_count;
END;
$$;


ALTER FUNCTION "public"."mcp_ensure_brief_storyboard_shots"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_row_count" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_ensure_brief_storyboard_shots"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_row_count" integer) IS 'MCP content.briefs.get: create permanent storyboard row ids once for a plan that has none, then attach clips and images that still use only row_index. Never edits brief text.';



CREATE OR REPLACE FUNCTION "public"."mcp_get_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "approved" boolean, "production_status" "text", "post_date" timestamp with time zone, "updated_at" timestamp with time zone, "content_type_name" "text", "service_name" "text", "sub_service_name" "text", "feature_name" "text", "pillar_name" "text", "pic_name" "text", "brief" "text", "concept" "jsonb", "concept_text" "text", "caption" "text", "has_drive_file" boolean, "published" boolean, "version_no" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_raw text;
  v_doc jsonb;
  v_concept jsonb;
  v_concept_text text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.social_media_plans plan
    WHERE plan.id = p_id
      AND plan.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT ta.description
  INTO v_raw
  FROM public.brief_target_audiences ta
  WHERE ta.social_media_plan_id = p_id
  ORDER BY ta.updated_at DESC NULLS LAST, ta.created_at DESC
  LIMIT 1;

  v_raw := NULLIF(btrim(COALESCE(v_raw, '')), '');
  IF v_raw IS NOT NULL AND left(v_raw, 1) = '{' THEN
    BEGIN
      v_doc := v_raw::jsonb;
    EXCEPTION WHEN others THEN
      v_doc := NULL;
    END;
  END IF;

  IF v_doc IS NOT NULL AND jsonb_typeof(v_doc) = 'object' THEN
    v_concept := jsonb_build_object(
      'voice_over', NULLIF(left(btrim(COALESCE(v_doc->>'voiceOver', '')), 4000), ''),
      'post_aspect', NULLIF(btrim(COALESCE(v_doc->>'postAspect', '')), ''),
      'characters', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'handle', left(btrim(COALESCE(item->>'handle', item->>'name', '')), 80),
          'description', left(btrim(COALESCE(item->>'description', '')), 500)
        ))
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_doc->'characters') = 'array' THEN v_doc->'characters' ELSE '[]'::jsonb END) AS item
        WHERE jsonb_typeof(item) = 'object'
      ), '[]'::jsonb),
      'locations', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'handle', left(btrim(COALESCE(item->>'handle', item->>'name', '')), 80),
          'description', left(btrim(COALESCE(item->>'description', '')), 500)
        ))
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_doc->'locations') = 'array' THEN v_doc->'locations' ELSE '[]'::jsonb END) AS item
        WHERE jsonb_typeof(item) = 'object'
      ), '[]'::jsonb),
      'properties', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'handle', left(btrim(COALESCE(item->>'handle', item->>'name', '')), 80),
          'description', left(btrim(COALESCE(item->>'description', '')), 500)
        ))
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_doc->'properties') = 'array' THEN v_doc->'properties' ELSE '[]'::jsonb END) AS item
        WHERE jsonb_typeof(item) = 'object'
      ), '[]'::jsonb)
    );
  ELSIF v_raw IS NOT NULL THEN
    v_concept_text := left(v_raw, 4000);
  END IF;

  RETURN QUERY
  SELECT
    plan.id,
    plan.title::text,
    plan.status::text,
    plan.approved,
    plan.production_status::text,
    plan.post_date,
    plan.updated_at,
    ct.name::text,
    svc.name::text,
    sub.name::text,
    feat.feature_name::text,
    pillar.name::text,
    emp.full_name::text,
    left(COALESCE(plan.brief, ''), 25000)::text,
    v_concept,
    v_concept_text,
    (
      SELECT left(cap.content, 2200)::text
      FROM public.brief_captions cap
      WHERE cap.social_media_plan_id = plan.id
      ORDER BY cap.updated_at DESC NULLS LAST, cap.created_at DESC
      LIMIT 1
    ),
    NULLIF(btrim(COALESCE(plan.google_drive_link, '')), '') IS NOT NULL,
    COALESCE(plan.post_link::text, 'null') NOT IN ('null', '[]', '{}', '""'),
    COALESCE((
      SELECT MAX(versions.version_no)
      FROM public.content_brief_versions AS versions
      WHERE versions.social_media_plan_id = plan.id
    ), 0)::integer
  FROM public.social_media_plans plan
  LEFT JOIN public.content_types ct ON ct.id = plan.content_type_id
  LEFT JOIN public.services svc ON svc.id = plan.service_id AND svc.organization_id = plan.organization_id
  LEFT JOIN public.sub_services sub ON sub.id = plan.sub_service_id AND sub.organization_id = plan.organization_id
  LEFT JOIN public.product_knowledge_features feat ON feat.id = plan.feature_id AND feat.organization_id = plan.organization_id
  LEFT JOIN public.content_pillars pillar ON pillar.id = plan.content_pillar_id
  LEFT JOIN public.employees emp ON emp.id = plan.pic_id AND emp.organization_id = plan.organization_id
  WHERE plan.id = p_id
    AND plan.organization_id = p_organization_id;
END;
$$;


ALTER FUNCTION "public"."mcp_get_content_brief"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_thinking_chain"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid") RETURNS TABLE("idea_id" "uuid", "idea_statement" "text", "master_statement" "text", "master_subject" "text", "big_thought_statement" "text", "territory_statement" "text", "angle_statement" "text", "development_paths" "jsonb", "pillars" "jsonb", "executions" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_idea_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.thinking_lab_ideas idea
    JOIN public.thinking_lab_angles angle
      ON angle.id = idea.angle_id
     AND angle.organization_id = idea.organization_id
    JOIN public.thinking_lab_territories territory
      ON territory.id = angle.territory_id
     AND territory.organization_id = idea.organization_id
    JOIN public.thinking_big_thoughts thought
      ON thought.id = territory.big_thought_id
     AND thought.organization_id = idea.organization_id
    JOIN public.thinking_master_thoughts master
      ON master.id = thought.master_thought_id
     AND master.organization_id = idea.organization_id
     AND master.workspace = 'thinking_lab'
    WHERE idea.id = p_idea_id
      AND idea.organization_id = p_organization_id
      AND idea.status = 'locked'
      AND idea.validation->>'decision' = 'LOLOS'
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    idea.id,
    left(btrim(idea.statement), 8000),
    left(btrim(master.statement), 8000),
    NULLIF(left(btrim(COALESCE(master.canonical_semantic->>'subject', '')), 500), ''),
    left(btrim(thought.statement), 8000),
    left(btrim(territory.statement), 8000),
    left(btrim(angle.statement), 8000),
    COALESCE(idea.development_paths, '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', pillar.id,
        'name', left(btrim(pillar.name), 200),
        'category', left(btrim(COALESCE(pillar.category, '')), 200),
        'description', left(btrim(COALESCE(pillar.description, '')), 2000)
      ) ORDER BY pillar.is_default DESC, pillar.name)
      FROM public.content_pillars pillar
      WHERE pillar.is_active = true
        AND (pillar.organization_id = p_organization_id OR pillar.is_default = true)
    ), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', ex.id,
        'pillar_name', left(btrim(COALESCE(ex.pillar_name, '')), 200),
        'title', left(btrim(COALESCE(ex.script->>'title', '')), 200),
        'admission', ex.admission,
        'canonical_semantic', ex.canonical_semantic,
        'line_issue_count', CASE
          WHEN jsonb_typeof(ex.script -> 'lineIssues') = 'array' THEN jsonb_array_length(ex.script -> 'lineIssues')
          ELSE 0
        END
      ) ORDER BY ex.updated_at DESC)
      FROM (
        SELECT ex_inner.*
        FROM public.thinking_lab_executions ex_inner
        WHERE ex_inner.organization_id = p_organization_id
          AND ex_inner.idea_id = idea.id
        ORDER BY ex_inner.updated_at DESC
        LIMIT 20
      ) ex
    ), '[]'::jsonb)
  FROM public.thinking_lab_ideas idea
  JOIN public.thinking_lab_angles angle
    ON angle.id = idea.angle_id
   AND angle.organization_id = idea.organization_id
  JOIN public.thinking_lab_territories territory
    ON territory.id = angle.territory_id
   AND territory.organization_id = idea.organization_id
  JOIN public.thinking_big_thoughts thought
    ON thought.id = territory.big_thought_id
   AND thought.organization_id = idea.organization_id
  JOIN public.thinking_master_thoughts master
    ON master.id = thought.master_thought_id
   AND master.organization_id = idea.organization_id
   AND master.workspace = 'thinking_lab'
  WHERE idea.id = p_idea_id
    AND idea.organization_id = p_organization_id
    AND idea.status = 'locked'
    AND idea.validation->>'decision' = 'LOLOS';
END;
$$;


ALTER FUNCTION "public"."mcp_get_thinking_chain"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_thinking_execution"("p_user_id" "uuid", "p_organization_id" "uuid", "p_execution_id" "uuid") RETURNS TABLE("id" "uuid", "idea_id" "uuid", "content_pillar_id" "uuid", "pillar_name" "text", "script" "jsonb", "canonical_semantic" "jsonb", "admission" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_execution_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.thinking_lab_executions ex
    JOIN public.thinking_lab_ideas idea
      ON idea.id = ex.idea_id
     AND idea.organization_id = ex.organization_id
    WHERE ex.id = p_execution_id
      AND ex.organization_id = p_organization_id
      AND ex.creative_idea_id IS NULL
      AND idea.status = 'locked'
      AND idea.validation->>'decision' = 'LOLOS'
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    ex.id,
    ex.idea_id,
    ex.content_pillar_id,
    ex.pillar_name,
    ex.script,
    ex.canonical_semantic,
    ex.admission
  FROM public.thinking_lab_executions ex
  JOIN public.thinking_lab_ideas idea
    ON idea.id = ex.idea_id
   AND idea.organization_id = ex.organization_id
  WHERE ex.id = p_execution_id
    AND ex.organization_id = p_organization_id
    AND ex.creative_idea_id IS NULL
    AND idea.status = 'locked'
    AND idea.validation->>'decision' = 'LOLOS';
END;
$$;


ALTER FUNCTION "public"."mcp_get_thinking_execution"("p_user_id" "uuid", "p_organization_id" "uuid", "p_execution_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_get_thinking_tree"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = p_master_thought_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN jsonb_build_object(
    'master', jsonb_build_object(
      'id', v_master.id,
      'statement', left(btrim(COALESCE(NULLIF(v_master.statement, ''), v_master.original_input, '')), 500),
      'prior_belief', left(btrim(COALESCE(v_master.prior_belief, '')), 500),
      'audience', left(btrim(COALESCE(v_master.audience, '')), 300),
      'subject', left(COALESCE(v_master.canonical_semantic->>'subject', ''), 300),
      'status', COALESCE(v_master.mt_status, v_master.status, ''),
      'catalog', (SELECT s.name FROM public.services s WHERE s.id = v_master.service_id)
    ),
    'big_thoughts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', b.id,
        'code', b.code,
        'label', b.title,
        'statement', left(btrim(b.statement), 500),
        'status', b.status,
        'audit', public.mcp_thinking_audit_item(v_master.last_audit, b.code),
        'failure', NULLIF(left(COALESCE(b.canonical_semantic->'gateFailure'->>'reason', ''), 400), ''),
        'territories', COALESCE((
          SELECT jsonb_agg(jsonb_build_object(
            'id', t.id,
            'code', t.code,
            'statement', left(btrim(t.statement), 300),
            'status', t.status,
            'admission', t.admission,
            'audit', public.mcp_thinking_audit_item(b.territory_set, t.code),
            'angles', COALESCE((
              SELECT jsonb_agg(jsonb_build_object(
                'id', a.id,
                'code', a.code,
                'statement', left(btrim(a.statement), 500),
                'status', a.status,
                'admission', a.admission,
                'audit', public.mcp_thinking_audit_item(t.angle_set, a.code),
                'ideas', COALESCE((
                  SELECT jsonb_agg(jsonb_build_object(
                    'id', i.id,
                    'code', i.code,
                    'statement', left(btrim(i.statement), 600),
                    'status', i.status,
                    'admission', i.admission,
                    'decision', i.validation->>'decision',
                    'failed', (
                      SELECT jsonb_build_object('id', c->>'id', 'reason', left(COALESCE(c->>'explanation', c->>'reason', ''), 400))
                      FROM jsonb_array_elements(COALESCE(i.validation->'criteria', '[]'::jsonb)) c
                      WHERE c->>'status' <> 'PASS'
                      LIMIT 1
                    )
                  ) ORDER BY i.sort_order, i.code)
                  FROM public.thinking_lab_ideas i
                  WHERE i.angle_id = a.id AND i.organization_id = p_organization_id
                ), '[]'::jsonb)
              ) ORDER BY a.sort_order, a.code)
              FROM public.thinking_lab_angles a
              WHERE a.territory_id = t.id AND a.organization_id = p_organization_id
            ), '[]'::jsonb)
          ) ORDER BY t.sort_order, t.code)
          FROM public.thinking_lab_territories t
          WHERE t.big_thought_id = b.id AND t.organization_id = p_organization_id
        ), '[]'::jsonb)
      ) ORDER BY b.sort_order, b.code)
      FROM public.thinking_big_thoughts b
      WHERE b.master_thought_id = v_master.id AND b.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_get_thinking_tree"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_habit_flags"("p_habit_id" "uuid", "p_employee_id" "uuid", "p_organization_id" "uuid", "p_day" "date", "p_target" integer) RETURNS boolean[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_target integer;
  v_flags boolean[];
  v_has_indexed boolean := false;
  v_legacy integer := 0;
  v_notes text;
  v_idx integer;
  v_slot integer;
BEGIN
  v_target := GREATEST(COALESCE(p_target, 1), 1);
  v_flags := array_fill(false, ARRAY[v_target]);

  IF v_target = 1 THEN
    IF EXISTS (
      SELECT 1
      FROM public.habit_entries entry
      WHERE entry.habit_id = p_habit_id
        AND entry.employee_id = p_employee_id
        AND entry.organization_id = p_organization_id
        AND entry.entry_date = p_day
    ) THEN
      v_flags[1] := true;
    END IF;
    RETURN v_flags;
  END IF;

  FOR v_notes IN
    SELECT entry.notes
    FROM public.habit_entries entry
    WHERE entry.habit_id = p_habit_id
      AND entry.employee_id = p_employee_id
      AND entry.organization_id = p_organization_id
      AND entry.entry_date = p_day
  LOOP
    IF v_notes ~ '^checklist_index:[0-9]+$' THEN
      v_has_indexed := true;
      v_idx := substring(v_notes FROM '^checklist_index:([0-9]+)$')::integer;
      IF v_idx >= 0 AND v_idx < v_target THEN
        v_flags[v_idx + 1] := true;
      END IF;
    ELSE
      v_legacy := v_legacy + 1;
    END IF;
  END LOOP;

  IF NOT v_has_indexed THEN
    FOR v_slot IN 0..LEAST(v_legacy, v_target) - 1 LOOP
      v_flags[v_slot + 1] := true;
    END LOOP;
  END IF;

  RETURN v_flags;
END;
$_$;


ALTER FUNCTION "public"."mcp_habit_flags"("p_habit_id" "uuid", "p_employee_id" "uuid", "p_organization_id" "uuid", "p_day" "date", "p_target" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_habit_on_day"("p_frequency" "text", "p_weekly" "jsonb", "p_monthly" "jsonb", "p_active" boolean, "p_day" "date") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_weekly jsonb;
  v_monthly jsonb;
BEGIN
  IF COALESCE(p_active, false) = false OR p_day IS NULL THEN
    RETURN false;
  END IF;

  v_weekly := CASE WHEN p_weekly IS NULL OR jsonb_typeof(p_weekly) IS DISTINCT FROM 'array' THEN '[]'::jsonb ELSE p_weekly END;
  v_monthly := CASE WHEN p_monthly IS NULL OR jsonb_typeof(p_monthly) IS DISTINCT FROM 'array' THEN '[]'::jsonb ELSE p_monthly END;

  IF lower(COALESCE(p_frequency, 'daily')) = 'weekly' THEN
    IF jsonb_array_length(v_weekly) = 0 THEN
      RETURN true;
    END IF;
    RETURN EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_weekly) elem
      WHERE (elem #>> '{}') ~ '^[0-9]+$'
        AND (elem #>> '{}')::int = EXTRACT(DOW FROM p_day)::int
    );
  END IF;

  IF lower(COALESCE(p_frequency, 'daily')) = 'monthly' THEN
    IF jsonb_array_length(v_monthly) = 0 THEN
      RETURN false;
    END IF;
    RETURN EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_monthly) elem
      WHERE (elem #>> '{}') ~ '^[0-9]+$'
        AND (elem #>> '{}')::int = EXTRACT(DAY FROM p_day)::int
    );
  END IF;

  RETURN true;
END;
$_$;


ALTER FUNCTION "public"."mcp_habit_on_day"("p_frequency" "text", "p_weekly" "jsonb", "p_monthly" "jsonb", "p_active" boolean, "p_day" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_assert_member"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_assert_member"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_bounds"("p_start" "date", "p_end" "date") RETURNS TABLE("v_from" timestamp with time zone, "v_to" timestamp with time zone)
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF p_start IS NULL OR p_end IS NULL OR p_start > p_end OR p_end - p_start > 92 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  v_from := p_start::timestamp AT TIME ZONE 'Asia/Jakarta';
  v_to := (p_end + 1)::timestamp AT TIME ZONE 'Asia/Jakarta';
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_bounds"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_check_channel"("p_channel" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v text := NULLIF(lower(btrim(COALESCE(p_channel, ''))), '');
BEGIN
  IF v IS NOT NULL AND v NOT IN ('instagram', 'facebook', 'whatsapp') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  RETURN v;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_check_channel"("p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_conversation_base"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text") RETURNS TABLE("conversation_id" "uuid", "channel" "text", "customer_name" "text", "ticket_id" "text", "lead_status_id" "uuid", "assignee_id" "uuid", "from_ad" boolean, "first_inbound_at" timestamp with time zone, "last_direction" "text", "last_body" "text", "last_type" "text", "last_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT c.id, 'instagram'::text, c.customer_name, c.ticket_id, c.lead_status_id, c.assignee_id,
         false, c.first_inbound_at, lm.direction, lm.body, lm.message_type, lm.created_at
  FROM public.instagram_conversations c
  LEFT JOIN LATERAL (
    SELECT m.direction, m.body, m.message_type, m.created_at
    FROM public.instagram_messages m
    WHERE m.conversation_id = c.id
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT 1
  ) lm ON true
  WHERE c.organization_id = p_organization_id
    AND (p_channel IS NULL OR p_channel = 'instagram')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id)

  UNION ALL

  SELECT c.id, 'facebook'::text, c.customer_name, c.ticket_id, c.lead_status_id, c.assignee_id,
         false, c.first_inbound_at, lm.direction, lm.body, lm.message_type, lm.created_at
  FROM public.facebook_conversations c
  LEFT JOIN LATERAL (
    SELECT m.direction, m.body, m.message_type, m.created_at
    FROM public.facebook_messages m
    WHERE m.conversation_id = c.id
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT 1
  ) lm ON true
  WHERE c.organization_id = p_organization_id
    AND (p_channel IS NULL OR p_channel = 'facebook')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id)

  UNION ALL

  SELECT c.id, 'whatsapp'::text, c.customer_name, c.ticket_id, c.lead_status_id, c.assignee_id,
         (c.ctwa_clid IS NOT NULL OR c.ctwa_referral IS NOT NULL), c.first_inbound_at,
         lm.direction, lm.body, lm.message_type, lm.created_at
  FROM public.whatsapp_conversations c
  LEFT JOIN LATERAL (
    SELECT m.direction, m.body, m.message_type, m.created_at
    FROM public.whatsapp_messages m
    WHERE m.conversation_id = c.id
    ORDER BY m.created_at DESC, m.id DESC
    LIMIT 1
  ) lm ON true
  WHERE c.organization_id = p_organization_id
    AND COALESCE(c.channel, 'whatsapp') = 'whatsapp'
    AND (p_channel IS NULL OR p_channel = 'whatsapp')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id);
$$;


ALTER FUNCTION "public"."mcp_inbox_conversation_base"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_conversations"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_start" "date", "p_end" "date", "p_awaiting_only" boolean, "p_limit" integer) RETURNS TABLE("conversation_id" "uuid", "channel" "text", "customer_name" "text", "ticket_id" "text", "lead_status" "text", "assignee" "text", "from_ad" boolean, "first_inbound_at" timestamp with time zone, "last_message_at" timestamp with time zone, "last_message_direction" "text", "last_message_preview" "text", "awaiting_reply" boolean, "waiting_minutes" integer, "inbound_in_period" integer, "outbound_in_period" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_channel text;
  v_from timestamptz;
  v_to timestamptz;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 50);
BEGIN
  PERFORM public.mcp_inbox_assert_member(p_user_id, p_organization_id);
  v_channel := public.mcp_inbox_check_channel(p_channel);
  SELECT b.v_from, b.v_to INTO v_from, v_to FROM public.mcp_inbox_bounds(p_start, p_end) b;

  RETURN QUERY
  WITH stats AS (
    SELECT pm.channel, pm.conversation_id,
           COUNT(*) FILTER (WHERE pm.direction = 'inbound')::integer AS inbound_n,
           COUNT(*) FILTER (WHERE pm.direction = 'outbound')::integer AS outbound_n
    FROM public.mcp_inbox_period_messages(p_organization_id, p_employee_id, v_channel, v_from, v_to) pm
    GROUP BY pm.channel, pm.conversation_id
  )
  SELECT b.conversation_id,
         b.channel,
         b.customer_name,
         b.ticket_id,
         ls.name,
         e.full_name,
         b.from_ad,
         b.first_inbound_at,
         b.last_at,
         b.last_direction,
         left(COALESCE(NULLIF(btrim(b.last_body), ''), '[' || COALESCE(b.last_type, 'message') || ']'), 200),
         b.last_direction = 'inbound',
         CASE WHEN b.last_direction = 'inbound'
              THEN GREATEST(0, floor(extract(epoch FROM (now() - b.last_at)) / 60))::integer
         END,
         s.inbound_n,
         s.outbound_n
  FROM public.mcp_inbox_conversation_base(p_organization_id, p_employee_id, v_channel) b
  JOIN stats s ON s.channel = b.channel AND s.conversation_id = b.conversation_id
  LEFT JOIN public.lead_statuses ls ON ls.id = b.lead_status_id
  LEFT JOIN public.employees e ON e.id = b.assignee_id
  WHERE NOT COALESCE(p_awaiting_only, false) OR b.last_direction = 'inbound'
  ORDER BY (b.last_direction = 'inbound') DESC, b.last_at DESC NULLS LAST, b.conversation_id
  LIMIT v_limit;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_conversations"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_start" "date", "p_end" "date", "p_awaiting_only" boolean, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_messages"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_conversation_id" "uuid", "p_limit" integer) RETURNS TABLE("message_id" "uuid", "direction" "text", "sent_by" "text", "message_type" "text", "body" "text", "has_media" boolean, "reply_to_body" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_channel text;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
BEGIN
  PERFORM public.mcp_inbox_assert_member(p_user_id, p_organization_id);
  v_channel := public.mcp_inbox_check_channel(p_channel);
  IF v_channel IS NULL OR p_conversation_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.mcp_inbox_conversation_base(p_organization_id, p_employee_id, v_channel) b
    WHERE b.conversation_id = p_conversation_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_channel = 'instagram' THEN
    RETURN QUERY
    SELECT x.* FROM (
      SELECT m.id, m.direction,
             CASE WHEN m.direction = 'inbound' THEN 'customer' ELSE 'agent' END,
             m.message_type, left(m.body, 2000), m.media_url IS NOT NULL,
             left(m.reply_to_body, 300), m.created_at
      FROM public.instagram_messages m
      WHERE m.conversation_id = p_conversation_id
      ORDER BY m.created_at DESC, m.id DESC
      LIMIT v_limit
    ) x ORDER BY x.created_at ASC, x.id ASC;
  ELSIF v_channel = 'facebook' THEN
    RETURN QUERY
    SELECT x.* FROM (
      SELECT m.id, m.direction,
             CASE WHEN m.direction = 'inbound' THEN 'customer' ELSE 'agent' END,
             m.message_type, left(m.body, 2000), m.media_url IS NOT NULL,
             left(m.reply_to_body, 300), m.created_at
      FROM public.facebook_messages m
      WHERE m.conversation_id = p_conversation_id
      ORDER BY m.created_at DESC, m.id DESC
      LIMIT v_limit
    ) x ORDER BY x.created_at ASC, x.id ASC;
  ELSE
    RETURN QUERY
    SELECT x.* FROM (
      SELECT m.id, m.direction,
             CASE WHEN m.direction = 'inbound' THEN 'customer'
                  WHEN COALESCE(m.source, 'agent') IN ('agent', 'business_app') THEN 'agent'
                  ELSE 'automation' END,
             m.message_type, left(m.body, 2000), m.media_url IS NOT NULL,
             left(m.reply_to_body, 300), m.created_at
      FROM public.whatsapp_messages m
      WHERE m.conversation_id = p_conversation_id
      ORDER BY m.created_at DESC, m.id DESC
      LIMIT v_limit
    ) x ORDER BY x.created_at ASC, x.id ASC;
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_messages"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_conversation_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_period_messages"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("conversation_id" "uuid", "channel" "text", "message_id" "uuid", "direction" "text", "is_human_reply" boolean, "created_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT m.conversation_id, 'instagram'::text, m.id, m.direction, m.direction = 'outbound', m.created_at
  FROM public.instagram_messages m
  JOIN public.instagram_conversations c ON c.id = m.conversation_id
  WHERE c.organization_id = p_organization_id
    AND (p_channel IS NULL OR p_channel = 'instagram')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id)
    AND m.created_at >= p_from AND m.created_at < p_to

  UNION ALL

  SELECT m.conversation_id, 'facebook'::text, m.id, m.direction, m.direction = 'outbound', m.created_at
  FROM public.facebook_messages m
  JOIN public.facebook_conversations c ON c.id = m.conversation_id
  WHERE c.organization_id = p_organization_id
    AND (p_channel IS NULL OR p_channel = 'facebook')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id)
    AND m.created_at >= p_from AND m.created_at < p_to

  UNION ALL

  SELECT m.conversation_id, 'whatsapp'::text, m.id, m.direction,
         m.direction = 'outbound' AND COALESCE(m.source, 'agent') IN ('agent', 'business_app'), m.created_at
  FROM public.whatsapp_messages m
  JOIN public.whatsapp_conversations c ON c.id = m.conversation_id
  WHERE c.organization_id = p_organization_id
    AND COALESCE(c.channel, 'whatsapp') = 'whatsapp'
    AND (p_channel IS NULL OR p_channel = 'whatsapp')
    AND (p_employee_id IS NULL OR c.assignee_id = p_employee_id)
    AND m.created_at >= p_from AND m.created_at < p_to;
$$;


ALTER FUNCTION "public"."mcp_inbox_period_messages"("p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inbox_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_start" "date", "p_end" "date") RETURNS TABLE("channel" "text", "conversations" integer, "new_conversations" integer, "from_ad_conversations" integer, "inbound_messages" integer, "outbound_messages" integer, "awaiting_reply" integer, "customer_turns" integer, "replied_turns" integer, "replied_within_5m" integer, "median_first_reply_minutes" numeric, "avg_first_reply_minutes" numeric, "inbound_by_hour" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_channel text;
  v_from timestamptz;
  v_to timestamptz;
BEGIN
  PERFORM public.mcp_inbox_assert_member(p_user_id, p_organization_id);
  v_channel := public.mcp_inbox_check_channel(p_channel);
  SELECT b.v_from, b.v_to INTO v_from, v_to FROM public.mcp_inbox_bounds(p_start, p_end) b;

  RETURN QUERY
  WITH pm AS (
    SELECT * FROM public.mcp_inbox_period_messages(p_organization_id, p_employee_id, v_channel, v_from, v_to)
  ),
  ordered AS (
    SELECT pm.*,
           lag(pm.direction) OVER w AS prev_direction
    FROM pm
    WINDOW w AS (PARTITION BY pm.channel, pm.conversation_id ORDER BY pm.created_at, pm.message_id)
  ),
  turns AS (
    SELECT o.channel, o.conversation_id, o.created_at AS asked_at,
           (SELECT min(r.created_at) FROM pm r
             WHERE r.channel = o.channel AND r.conversation_id = o.conversation_id
               AND r.is_human_reply AND r.created_at > o.created_at) AS replied_at
    FROM ordered o
    WHERE o.direction = 'inbound' AND COALESCE(o.prev_direction, 'outbound') <> 'inbound'
  ),
  turn_stats AS (
    SELECT t.channel,
           COUNT(*)::integer AS turns_n,
           COUNT(t.replied_at)::integer AS replied_n,
           COUNT(*) FILTER (WHERE t.replied_at - t.asked_at <= interval '5 minutes')::integer AS fast_n,
           round((percentile_cont(0.5) WITHIN GROUP (
             ORDER BY extract(epoch FROM (t.replied_at - t.asked_at)) / 60
           ) FILTER (WHERE t.replied_at IS NOT NULL))::numeric, 1) AS median_m,
           round((avg(extract(epoch FROM (t.replied_at - t.asked_at)) / 60)
             FILTER (WHERE t.replied_at IS NOT NULL))::numeric, 1) AS avg_m
    FROM turns t
    GROUP BY t.channel
  ),
  msg_stats AS (
    SELECT pm.channel,
           COUNT(DISTINCT pm.conversation_id)::integer AS conv_n,
           COUNT(*) FILTER (WHERE pm.direction = 'inbound')::integer AS in_n,
           COUNT(*) FILTER (WHERE pm.direction = 'outbound')::integer AS out_n
    FROM pm
    GROUP BY pm.channel
  ),
  hours AS (
    SELECT h.channel, jsonb_object_agg(lpad(h.hr::text, 2, '0'), h.n ORDER BY h.hr) AS by_hour
    FROM (
      SELECT pm.channel,
             extract(hour FROM pm.created_at AT TIME ZONE 'Asia/Jakarta')::integer AS hr,
             COUNT(*)::integer AS n
      FROM pm
      WHERE pm.direction = 'inbound'
      GROUP BY 1, 2
    ) h
    GROUP BY h.channel
  ),
  conv_stats AS (
    SELECT b.channel,
           COUNT(*) FILTER (WHERE b.first_inbound_at >= v_from AND b.first_inbound_at < v_to)::integer AS new_n,
           COUNT(*) FILTER (WHERE b.from_ad)::integer AS ad_n,
           COUNT(*) FILTER (WHERE b.last_direction = 'inbound')::integer AS waiting_n
    FROM public.mcp_inbox_conversation_base(p_organization_id, p_employee_id, v_channel) b
    WHERE EXISTS (
      SELECT 1 FROM pm WHERE pm.channel = b.channel AND pm.conversation_id = b.conversation_id
    )
    GROUP BY b.channel
  )
  SELECT ms.channel,
         ms.conv_n,
         COALESCE(cs.new_n, 0),
         COALESCE(cs.ad_n, 0),
         ms.in_n,
         ms.out_n,
         COALESCE(cs.waiting_n, 0),
         COALESCE(ts.turns_n, 0),
         COALESCE(ts.replied_n, 0),
         COALESCE(ts.fast_n, 0),
         ts.median_m,
         ts.avg_m,
         COALESCE(h.by_hour, '{}'::jsonb)
  FROM msg_stats ms
  LEFT JOIN turn_stats ts ON ts.channel = ms.channel
  LEFT JOIN conv_stats cs ON cs.channel = ms.channel
  LEFT JOIN hours h ON h.channel = ms.channel
  ORDER BY ms.channel;
END;
$$;


ALTER FUNCTION "public"."mcp_inbox_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid", "p_channel" "text", "p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_inventory_manager_guard"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT (
    EXISTS (
      SELECT 1
      FROM public.user_roles ur
      WHERE ur.user_id = p_user_id
        AND ur.organization_id = p_organization_id
        AND ur.role = 'owner'::text
    )
    OR EXISTS (
      SELECT 1
      FROM public.organization_omnichannel_staff staff
      INNER JOIN public.employees employee
        ON employee.id = staff.employee_id
       AND employee.user_id = p_user_id
      WHERE staff.organization_id = p_organization_id
        AND staff.role = 'admin'::text
    )
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_inventory_manager_guard"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_link_task_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid", "p_individual_objective_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "objective_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_id uuid;
  v_title text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_task_id IS NULL OR p_individual_objective_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.individual_objectives objective
    WHERE objective.id = p_individual_objective_id
      AND objective.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.daily_tasks AS task
  SET
    objective_id = p_individual_objective_id,
    updated_at = now()
  WHERE task.id = p_task_id
    AND task.organization_id = p_organization_id
  RETURNING task.id, task.title INTO v_id, v_title;

  IF v_id IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  id := v_id;
  title := v_title;
  objective_id := p_individual_objective_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_link_task_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid", "p_individual_objective_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_ads_accounts"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("platform" "text", "label" "text", "account_id" "text", "is_active" boolean, "last_test_ok" boolean, "connected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT q.platform, q.label, q.account_id, q.is_active, q.last_test_ok, q.connected_at
  FROM (
    SELECT
      'google'::text AS platform,
      a.label,
      a.customer_id AS account_id,
      a.is_active,
      c.last_test_ok,
      c.oauth_connected_at AS connected_at
    FROM public.organization_google_ads_accounts a
    LEFT JOIN public.organization_google_ads_connections c
      ON c.organization_id = a.organization_id
    WHERE a.organization_id = p_organization_id
    UNION ALL
    SELECT
      'google'::text,
      NULL::text,
      NULL::text,
      c.is_active,
      c.last_test_ok,
      c.oauth_connected_at
    FROM public.organization_google_ads_connections c
    WHERE c.organization_id = p_organization_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.organization_google_ads_accounts a
        WHERE a.organization_id = c.organization_id
      )
    UNION ALL
    SELECT
      'meta'::text,
      a.label,
      a.ad_account_id,
      a.is_active,
      c.last_test_ok,
      c.oauth_connected_at
    FROM public.organization_meta_ads_accounts a
    LEFT JOIN public.organization_meta_ads_connections c
      ON c.organization_id = a.organization_id
    WHERE a.organization_id = p_organization_id
    UNION ALL
    SELECT
      'meta'::text,
      NULL::text,
      NULL::text,
      c.is_active,
      c.last_test_ok,
      c.oauth_connected_at
    FROM public.organization_meta_ads_connections c
    WHERE c.organization_id = p_organization_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.organization_meta_ads_accounts a
        WHERE a.organization_id = c.organization_id
      )
    UNION ALL
    SELECT
      'tiktok'::text,
      a.label,
      a.advertiser_id,
      a.is_active,
      c.last_test_ok,
      c.oauth_connected_at
    FROM public.organization_tiktok_ads_accounts a
    LEFT JOIN public.organization_tiktok_ads_connections c
      ON c.organization_id = a.organization_id
    WHERE a.organization_id = p_organization_id
    UNION ALL
    SELECT
      'tiktok'::text,
      NULL::text,
      NULL::text,
      c.is_active,
      c.last_test_ok,
      c.oauth_connected_at
    FROM public.organization_tiktok_ads_connections c
    WHERE c.organization_id = p_organization_id
      AND NOT EXISTS (
        SELECT 1
        FROM public.organization_tiktok_ads_accounts a
        WHERE a.organization_id = c.organization_id
      )
  ) q
  ORDER BY q.platform ASC, q.label ASC NULLS LAST, q.account_id ASC NULLS LAST
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_ads_accounts"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_ai_employee_jobs"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rows jsonb;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_employee_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = p_user_id
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT job.id, job.source, job.priority, job.status, job.attempts,
           job.reason, job.daily_task_id, job.plan_id, job.run_id,
           job.next_attempt_at, job.created_at, job.claimed_at, job.finished_at
    FROM public.ai_employee_jobs job
    WHERE job.employee_id = p_employee_id
      AND job.organization_id = p_organization_id
    ORDER BY job.created_at DESC
    LIMIT 20
  ) x;
  RETURN v_rows;
END;
$$;


ALTER FUNCTION "public"."mcp_list_ai_employee_jobs"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_ai_employee_routines"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_employee_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles role
    WHERE role.user_id = p_user_id
      AND role.organization_id = p_organization_id
      AND lower(btrim(role.role)) IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees employee
    WHERE employee.id = p_employee_id
      AND employee.organization_id = p_organization_id
      AND COALESCE(employee.is_ai, false)
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'action_code', routine.action_code,
      'cadence', routine.cadence,
      'weekday', routine.weekday,
      'weekdays', routine.weekdays,
      'time_local', to_char(routine.time_local, 'HH24:MI'),
      'is_active', routine.is_active,
      'next_run_at', routine.next_run_at,
      'last_sent_at', routine.last_sent_at,
      'last_status', routine.last_status,
      'reviewer_name', reviewer.full_name,
      'deliveries', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'status', delivery.status,
          'period_start', delivery.period_start,
          'period_end', delivery.period_end,
          'created_at', delivery.created_at,
          'summary', delivery.summary,
          'error', left(delivery.error, 240)
        ) ORDER BY delivery.created_at DESC)
        FROM (
          SELECT status, period_start, period_end, created_at, summary, error
          FROM public.ai_employee_routine_deliveries delivery
          WHERE delivery.routine_id = routine.id
          ORDER BY delivery.created_at DESC, delivery.id DESC
          LIMIT 5
        ) delivery
      ), '[]'::jsonb)
    ) ORDER BY routine.action_code)
    FROM public.ai_employee_routines routine
    JOIN public.ai_employee_profiles profile
      ON profile.employee_id = routine.employee_id
     AND profile.organization_id = routine.organization_id
    LEFT JOIN public.employees reviewer
      ON reviewer.id = profile.reviewer_employee_id
     AND reviewer.organization_id = routine.organization_id
    WHERE routine.employee_id = p_employee_id
      AND routine.organization_id = p_organization_id
  ), '[]'::jsonb);
END;
$$;


ALTER FUNCTION "public"."mcp_list_ai_employee_routines"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_list_ai_employee_routines"("p_user_id" "uuid", "p_organization_id" "uuid", "p_employee_id" "uuid") IS 'Daftar rutinitas untuk owner atau admin. Tidak mengembalikan alamat email.';



CREATE OR REPLACE FUNCTION "public"."mcp_list_brief_voice_clips"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") RETURNS TABLE("id" "uuid", "kind" "text", "row_index" integer, "shot_id" "uuid", "file_name" "text", "spoken_text" "text", "storage_path" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_plan_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.social_media_plans plan
    WHERE plan.id = p_plan_id
      AND plan.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    clip.id,
    clip.kind,
    clip.row_index,
    clip.shot_id,
    clip.file_name,
    clip.spoken_text,
    clip.storage_path,
    clip.created_at
  FROM public.brief_voice_clips clip
  WHERE clip.organization_id = p_organization_id
    AND clip.social_media_plan_id = p_plan_id
    AND clip.kind = 'vo'
  ORDER BY clip.row_index ASC, clip.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."mcp_list_brief_voice_clips"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_list_brief_voice_clips"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") IS 'MCP content.briefs.voice.list: VO clips for one plan, including the permanent shot_id.';



CREATE OR REPLACE FUNCTION "public"."mcp_list_catalog_suppliers"("p_user_id" "uuid", "p_organization_id" "uuid", "p_search" "text") RETURNS TABLE("id" "uuid", "name" "text", "phone" "text", "city" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text := NULLIF(btrim(COALESCE(p_search, '')), '');
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF v_search IS NOT NULL AND char_length(v_search) > 80 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT s.id, s.name, NULLIF(btrim(s.phone), ''), NULLIF(btrim(s.city), '')
  FROM public.catalog_suppliers s
  WHERE s.organization_id = p_organization_id
    AND s.is_deleted = false
    AND (
      v_search IS NULL
      OR s.name ILIKE '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%'
    )
  ORDER BY
    CASE WHEN v_search IS NOT NULL AND lower(btrim(s.name)) = lower(v_search) THEN 0 ELSE 1 END,
    s.name
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_catalog_suppliers"("p_user_id" "uuid", "p_organization_id" "uuid", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_completed_steps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") RETURNS TABLE("id" "uuid", "task_title" "text", "step_title" "text", "completed_at" timestamp with time zone, "assignee_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_month text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_month := NULLIF(btrim(COALESCE(p_month, '')), '');
  IF v_month IS NOT NULL AND v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_month' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    step.id,
    task.title,
    step.title,
    COALESCE(step.completed_at, step.updated_at),
    assignee.full_name
  FROM public.task_steps step
  JOIN public.daily_tasks task ON task.id = step.task_id
  LEFT JOIN LATERAL (
    SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name
    FROM public.task_steps_assigned assigned
    JOIN public.employees emp ON emp.id = assigned.employee_id
    LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
    WHERE assigned.task_step_id = step.id
      AND assigned.organization_id = task.organization_id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1
  ) assignee ON true
  WHERE task.organization_id = p_organization_id
    AND step.is_completed = true
    AND (
      v_month IS NULL
      OR to_char(COALESCE(step.completed_at, step.updated_at) AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM') = v_month
    )
  ORDER BY COALESCE(step.completed_at, step.updated_at) DESC NULLS LAST, step.id DESC
  LIMIT 20;
END;
$_$;


ALTER FUNCTION "public"."mcp_list_completed_steps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_connections"("p_organization_id" "uuid") RETURNS TABLE("user_id" "uuid", "client_id" "text", "full_name" "text", "client_name" "text", "connected_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_org_wide boolean;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = v_user
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_org_wide := EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_user
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin')
  );

  RETURN QUERY
  SELECT
    picked.user_id,
    picked.client_id,
    picked.full_name,
    picked.client_name,
    picked.connected_at
  FROM (
    SELECT DISTINCT ON (token.user_id)
      token.user_id,
      token.client_id,
      COALESCE(
        NULLIF(btrim(profile.full_name), ''),
        (
          SELECT emp.full_name
          FROM public.employees emp
          WHERE emp.user_id = token.user_id
            AND emp.organization_id = token.organization_id
            AND NULLIF(btrim(emp.full_name), '') IS NOT NULL
          LIMIT 1
        )
      ) AS full_name,
      client.client_name,
      token.created_at AS connected_at
    FROM public.mcp_oauth_refresh_tokens token
    LEFT JOIN public.profiles profile
      ON profile.user_id = token.user_id
    LEFT JOIN public.mcp_oauth_clients client
      ON client.client_id = token.client_id
    WHERE token.organization_id = p_organization_id
      AND token.revoked_at IS NULL
      AND token.expires_at > now()
      AND (v_org_wide OR token.user_id = v_user)
    ORDER BY token.user_id, token.created_at DESC, token.id DESC
  ) picked
  ORDER BY picked.connected_at DESC;
END;
$$;


ALTER FUNCTION "public"."mcp_list_connections"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_content_calendar"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "post_date" timestamp with time zone, "approved" boolean, "production_status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_month text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_month := NULLIF(btrim(COALESCE(p_month, '')), '');
  IF v_month IS NULL THEN
    v_month := to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM');
  END IF;
  IF v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_month' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.title,
    p.status,
    p.post_date,
    p.approved,
    p.production_status
  FROM public.social_media_plans p
  WHERE p.organization_id = p_organization_id
    AND p.post_date IS NOT NULL
    AND to_char(p.post_date AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM') = v_month
  ORDER BY p.post_date ASC, p.id ASC
  LIMIT 50;
END;
$_$;


ALTER FUNCTION "public"."mcp_list_content_calendar"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_content_catalog"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("kind" "text", "id" "uuid", "name" "text", "service_id" "uuid", "sub_service_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    'type'::text,
    picked.id,
    picked.name::text,
    NULL::uuid,
    NULL::uuid
  FROM (
    SELECT ct.id, ct.name
    FROM public.content_types ct
    WHERE COALESCE(ct.is_active, true) = true
      AND (ct.organization_id = p_organization_id OR ct.organization_id IS NULL)
    ORDER BY ct.name ASC, ct.id ASC
    LIMIT 100
  ) picked;

  RETURN QUERY
  SELECT
    'service'::text,
    picked.id,
    picked.name::text,
    NULL::uuid,
    NULL::uuid
  FROM (
    SELECT svc.id, svc.name
    FROM public.services svc
    WHERE svc.organization_id = p_organization_id
      AND COALESCE(svc.is_active, true) = true
    ORDER BY svc.name ASC, svc.id ASC
    LIMIT 100
  ) picked;

  RETURN QUERY
  SELECT
    'sub_service'::text,
    picked.id,
    picked.name::text,
    picked.service_id,
    NULL::uuid
  FROM (
    SELECT sub.id, sub.name, sub.service_id
    FROM public.sub_services sub
    WHERE sub.organization_id = p_organization_id
      AND COALESCE(sub.is_active, true) = true
    ORDER BY sub.name ASC, sub.id ASC
    LIMIT 200
  ) picked;

  RETURN QUERY
  SELECT
    'feature'::text,
    picked.id,
    picked.feature_name::text,
    picked.service_id,
    picked.sub_service_id
  FROM (
    SELECT feat.id, feat.feature_name, feat.service_id, feat.sub_service_id
    FROM public.product_knowledge_features feat
    WHERE feat.organization_id = p_organization_id
    ORDER BY feat.feature_name ASC, feat.id ASC
    LIMIT 200
  ) picked;
END;
$$;


