CREATE OR REPLACE FUNCTION "public"."mcp_list_crm_leads"("p_user_id" "uuid", "p_organization_id" "uuid", "p_status" "text") RETURNS TABLE("id" "uuid", "ticket_id" "text", "client" "text", "title" "text", "source" "text", "status" "text", "fu_priority" "text", "assignee" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_status := NULLIF(lower(btrim(COALESCE(p_status, ''))), '');

  RETURN QUERY
  SELECT
    l.id,
    l.ticket_id,
    l.client,
    l.title,
    l.source,
    ls.name,
    l.fu_priority,
    l.assignee,
    l.created_at
  FROM public.leads l
  LEFT JOIN public.lead_statuses ls ON ls.id = l.status_id
  WHERE l.organization_id = p_organization_id
    AND (v_status IS NULL OR lower(btrim(ls.name)) = v_status)
  ORDER BY l.created_at DESC, l.id ASC
  LIMIT 50;
END;
$$;


