CREATE OR REPLACE FUNCTION "public"."mcp_list_employees"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "full_name" "text", "status" "text", "department_name" "text", "job_level_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    e.id,
    e.full_name,
    es.name,
    dep.name,
    jl.name
  FROM public.employees e
  LEFT JOIN public.employee_statuses es ON es.id = e.employee_status_id
  LEFT JOIN public.departments dep ON dep.id = e.department_id
  LEFT JOIN public.job_levels jl ON jl.id = e.job_level_id
  WHERE e.organization_id = p_organization_id
  ORDER BY
    CASE WHEN lower(COALESCE(es.name, '')) IN ('terminated', 'inactive') THEN 1 ELSE 0 END,
    e.full_name ASC,
    e.id ASC
  LIMIT 50;
END;
$$;


