CREATE OR REPLACE FUNCTION "public"."mcp_list_habits"("p_user_id" "uuid", "p_organization_id" "uuid", "p_date" "text") RETURNS TABLE("id" "uuid", "name" "text", "frequency" "text", "target_count" integer, "items" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_day date;
  v_habit record;
  v_names jsonb;
  v_target integer;
  v_flags boolean[];
  v_items jsonb;
  v_label text;
  v_slot integer;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_date IS NULL OR btrim(p_date) = '' THEN
    v_day := (now() AT TIME ZONE 'Asia/Jakarta')::date;
  ELSE
    IF btrim(p_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_date)::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  FOR v_habit IN
    SELECT
      habit.id,
      habit.name,
      habit.frequency,
      habit.target_count,
      habit.checklist_names,
      habit.weekly_days,
      habit.monthly_dates,
      habit.is_active,
      habit.created_at
    FROM public.habits habit
    WHERE habit.organization_id = p_organization_id
      AND habit.employee_id = v_self
      AND public.mcp_habit_on_day(
        habit.frequency,
        CASE WHEN habit.weekly_days IS NULL THEN NULL ELSE to_jsonb(habit.weekly_days) END,
        CASE WHEN habit.monthly_dates IS NULL THEN NULL ELSE to_jsonb(habit.monthly_dates) END,
        habit.is_active,
        v_day
      )
    ORDER BY habit.created_at DESC, habit.id ASC
    LIMIT 50
  LOOP
    v_target := GREATEST(COALESCE(v_habit.target_count, 1), 1);
    v_names := CASE
      WHEN v_habit.checklist_names IS NULL THEN '[]'::jsonb
      ELSE to_jsonb(v_habit.checklist_names)
    END;
    IF jsonb_typeof(v_names) IS DISTINCT FROM 'array' THEN
      v_names := '[]'::jsonb;
    END IF;
    v_flags := public.mcp_habit_flags(v_habit.id, v_self, p_organization_id, v_day, v_target);
    v_items := '[]'::jsonb;
    FOR v_slot IN 0..v_target - 1 LOOP
      v_label := NULLIF(btrim(v_names ->> v_slot), '');
      IF v_label IS NULL THEN
        IF v_target = 1 THEN
          v_label := v_habit.name;
        ELSE
          v_label := (v_slot + 1)::text || ' of ' || v_target::text;
        END IF;
      END IF;
      v_items := v_items || jsonb_build_array(
        jsonb_build_object(
          'index', v_slot,
          'name', v_label,
          'checked', COALESCE(v_flags[v_slot + 1], false)
        )
      );
    END LOOP;

    id := v_habit.id;
    name := v_habit.name;
    frequency := v_habit.frequency;
    target_count := v_target;
    items := v_items;
    RETURN NEXT;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."mcp_list_habits"("p_user_id" "uuid", "p_organization_id" "uuid", "p_date" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_income_transactions"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") RETURNS TABLE("id" "uuid", "transaction_date" "date", "amount" double precision, "customer_name" "text", "payment_method" "text", "status" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_month text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_month := NULLIF(btrim(COALESCE(p_month, '')), '');
  IF v_month IS NULL THEN
    v_month := to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM');
  END IF;
  IF v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_month' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    t.id,
    t.transaction_date,
    t.amount::double precision,
    t.customer_name,
    t.payment_method,
    t.status
  FROM public.income_transactions t
  WHERE t.organization_id = p_organization_id
    AND to_char(t.transaction_date, 'YYYY-MM') = v_month
  ORDER BY t.transaction_date DESC, t.id ASC
  LIMIT 50;
END;
$_$;


ALTER FUNCTION "public"."mcp_list_income_transactions"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_inventory_stock"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "product_name" "text", "sku_name" "text", "internal_sku" "text", "available_qty" integer, "reserved_qty" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    lvl.id,
    prod.name,
    sku.name,
    sku.internal_sku,
    lvl.available_qty,
    lvl.reserved_qty
  FROM public.inventory_stock_levels lvl
  JOIN public.inventory_skus sku
    ON sku.id = lvl.sku_id
   AND sku.organization_id = lvl.organization_id
  JOIN public.inventory_products prod
    ON prod.id = sku.product_id
   AND prod.organization_id = lvl.organization_id
  WHERE lvl.organization_id = p_organization_id
  ORDER BY lvl.available_qty ASC, sku.internal_sku ASC, lvl.id ASC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_inventory_stock"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_inventory_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_kind" "text", "p_date_start" "text", "p_date_end" "text", "p_search" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_kind text;
  v_search text;
  v_like text;
  v_start timestamptz;
  v_end timestamptz;
  v_day date;
  v_outlet uuid;
  v_outlet_name text;
  v_total bigint;
  v_rows jsonb;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_kind := lower(btrim(COALESCE(p_kind, 'both')));
  IF v_kind NOT IN ('both', 'ingredients', 'item_library') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF (p_date_start IS NULL) <> (p_date_end IS NULL) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_date_start IS NULL THEN
    v_day := (timezone('Asia/Jakarta', clock_timestamp()))::date;
  ELSE
    IF btrim(p_date_start) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$'
      OR btrim(p_date_end) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_date_start)::date;
      IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_date_start)
        OR to_char(btrim(p_date_end)::date, 'YYYY-MM-DD') <> btrim(p_date_end) THEN
        RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
      END IF;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END;
    IF btrim(p_date_end)::date < v_day OR (btrim(p_date_end)::date - v_day) > 365 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_day := btrim(p_date_start)::date;
  END IF;

  IF p_date_start IS NULL THEN
    v_start := v_day::timestamp AT TIME ZONE 'Asia/Jakarta';
    v_end := ((v_day + 1)::timestamp AT TIME ZONE 'Asia/Jakarta') - interval '1 millisecond';
  ELSE
    v_start := btrim(p_date_start)::date::timestamp AT TIME ZONE 'Asia/Jakarta';
    v_end := ((btrim(p_date_end)::date + 1)::timestamp AT TIME ZONE 'Asia/Jakarta') - interval '1 millisecond';
  END IF;

  v_search := left(btrim(COALESCE(p_search, '')), 80);
  v_like := '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  IF p_outlet_id IS NULL THEN
    SELECT outlet.id, outlet.name
    INTO v_outlet, v_outlet_name
    FROM public.pos_outlets outlet
    WHERE outlet.organization_id = p_organization_id
      AND outlet.is_deleted = false
      AND outlet.is_active = true
    ORDER BY outlet.is_default DESC, outlet.sort_order, outlet.created_at
    LIMIT 1;
  ELSE
    SELECT outlet.id, outlet.name
    INTO v_outlet, v_outlet_name
    FROM public.pos_outlets outlet
    WHERE outlet.id = p_outlet_id
      AND outlet.organization_id = p_organization_id
      AND outlet.is_deleted = false;
  END IF;

  IF v_outlet IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  WITH items AS (
    SELECT
      'ingredient'::text AS kind,
      i.name,
      NULL::text AS variant_name,
      COALESCE(cat.name, '') AS category,
      io.in_stock AS current_qty,
      NULL::uuid AS product_id,
      NULL::uuid AS variant_id,
      i.id AS ingredient_id
    FROM public.catalog_ingredients i
    JOIN public.catalog_ingredient_outlets io
      ON io.ingredient_id = i.id
     AND io.outlet_id = v_outlet
     AND io.organization_id = p_organization_id
    LEFT JOIN public.catalog_ingredient_categories cat
      ON cat.id = i.category_id
     AND cat.organization_id = i.organization_id
    WHERE i.organization_id = p_organization_id
      AND i.is_deleted = false
      AND i.track_inventory = true
      AND v_kind IN ('both', 'ingredients')

    UNION ALL

    SELECT
      'product'::text,
      dp.name,
      NULL::text,
      COALESCE(cat.name, ''),
      link.in_stock,
      dp.id,
      NULL::uuid,
      NULL::uuid
    FROM public.default_prices dp
    JOIN public.catalog_product_outlets link
      ON link.product_id = dp.id
     AND link.outlet_id = v_outlet
     AND link.organization_id = p_organization_id
    LEFT JOIN public.catalog_product_categories cat
      ON cat.id = dp.product_category_id
    WHERE dp.organization_id = p_organization_id
      AND dp.kind = 'product'
      AND dp.track_stock = true
      AND v_kind IN ('both', 'item_library')
      AND NOT EXISTS (
        SELECT 1
        FROM public.catalog_product_variants variant
        WHERE variant.product_id = dp.id
      )

    UNION ALL

    SELECT
      'product'::text,
      dp.name,
      variant.name,
      COALESCE(cat.name, ''),
      COALESCE(stock.in_stock, 0),
      dp.id,
      variant.id,
      NULL::uuid
    FROM public.default_prices dp
    JOIN public.catalog_product_outlets link
      ON link.product_id = dp.id
     AND link.outlet_id = v_outlet
     AND link.organization_id = p_organization_id
    JOIN public.catalog_product_variants variant
      ON variant.product_id = dp.id
     AND variant.organization_id = dp.organization_id
    LEFT JOIN public.catalog_product_variant_outlets stock
      ON stock.variant_id = variant.id
     AND stock.outlet_id = v_outlet
     AND stock.organization_id = p_organization_id
    LEFT JOIN public.catalog_product_categories cat
      ON cat.id = dp.product_category_id
    WHERE dp.organization_id = p_organization_id
      AND dp.kind = 'product'
      AND dp.track_stock = true
      AND v_kind IN ('both', 'item_library')
  ),
  scored AS (
    SELECT
      item.kind,
      item.name,
      item.variant_name,
      item.category,
      item.current_qty,
      item.current_qty - COALESCE(sums.after_start, 0) AS beginning,
      COALESCE(sums.purchase_order, 0) AS purchase_order,
      COALESCE(sums.sales, 0) AS sales,
      COALESCE(sums.transfer, 0) AS transfer,
      COALESCE(sums.adjustment, 0) AS adjustment,
      item.current_qty - COALESCE(sums.after_end, 0) AS ending
    FROM items item
    LEFT JOIN LATERAL (
      SELECT
        SUM(movement.qty_delta) FILTER (WHERE movement.occurred_at > v_start) AS after_start,
        SUM(movement.qty_delta) FILTER (WHERE movement.occurred_at > v_end) AS after_end,
        SUM(movement.qty_delta) FILTER (
          WHERE movement.occurred_at >= v_start
            AND movement.occurred_at <= v_end
            AND movement.movement_type IN ('purchase_order', 'production')
        ) AS purchase_order,
        SUM(movement.qty_delta) FILTER (
          WHERE movement.occurred_at >= v_start
            AND movement.occurred_at <= v_end
            AND movement.movement_type IN ('sale', 'recipe_consume')
        ) AS sales,
        SUM(movement.qty_delta) FILTER (
          WHERE movement.occurred_at >= v_start
            AND movement.occurred_at <= v_end
            AND movement.movement_type = 'transfer'
        ) AS transfer,
        SUM(movement.qty_delta) FILTER (
          WHERE movement.occurred_at >= v_start
            AND movement.occurred_at <= v_end
            AND movement.movement_type IN ('adjustment', 'opening')
        ) AS adjustment
      FROM public.catalog_stock_movements movement
      WHERE movement.organization_id = p_organization_id
        AND movement.outlet_id = v_outlet
        AND movement.item_kind = item.kind
        AND movement.product_id IS NOT DISTINCT FROM item.product_id
        AND movement.variant_id IS NOT DISTINCT FROM item.variant_id
        AND movement.ingredient_id IS NOT DISTINCT FROM item.ingredient_id
    ) sums ON true
    WHERE v_search = ''
      OR item.name ILIKE v_like ESCAPE '\'
      OR COALESCE(item.variant_name, '') ILIKE v_like ESCAPE '\'
      OR item.category ILIKE v_like ESCAPE '\'
  ),
  ranked AS (
    SELECT
      scored.*,
      COUNT(*) OVER () AS total,
      ROW_NUMBER() OVER (
        ORDER BY lower(scored.name), lower(COALESCE(scored.variant_name, '')), scored.kind
      ) AS rn
    FROM scored
  )
  SELECT
    COALESCE(MAX(ranked.total), 0),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'kind', ranked.kind,
          'name', ranked.name,
          'variant_name', ranked.variant_name,
          'category', ranked.category,
          'current_qty', ranked.current_qty,
          'beginning', ranked.beginning,
          'purchase_order', ranked.purchase_order,
          'sales', ranked.sales,
          'transfer', ranked.transfer,
          'adjustment', ranked.adjustment,
          'ending', ranked.ending
        )
        ORDER BY ranked.rn
      ) FILTER (WHERE ranked.rn <= 200),
      '[]'::jsonb
    )
  INTO v_total, v_rows
  FROM ranked;

  RETURN jsonb_build_object(
    'outlet_id', v_outlet,
    'outlet_name', v_outlet_name,
    'period_start', v_start,
    'period_end', v_end,
    'truncated', v_total > 200,
    'rows', v_rows
  );
END;
$_$;


ALTER FUNCTION "public"."mcp_list_inventory_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_kind" "text", "p_date_start" "text", "p_date_end" "text", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_kol_campaigns"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "status" "text", "start_date" "date", "end_date" "date", "budget" double precision, "total_budget" double precision, "allocated_budget" double precision, "remaining_budget" double precision)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.name,
    c.status,
    c.start_date,
    c.end_date,
    c.budget::double precision,
    c.total_budget::double precision,
    c.allocated_budget::double precision,
    c.remaining_budget::double precision
  FROM public.kol_campaigns c
  WHERE c.organization_id = p_organization_id
  ORDER BY c.updated_at DESC, c.id ASC
  LIMIT 50;
END;
$$;


