CREATE OR REPLACE FUNCTION "public"."mcp_list_lead_magnet_drafts"("p_user_id" "uuid", "p_organization_id" "uuid", "p_campaign_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "target_market" "text", "keyword" "text", "comment_reply_text" "text", "follow_gate_text" "text", "framework_offer_text" "text", "delivery_text" "text", "delivery_button_label" "text", "has_file" boolean, "file_name" "text", "social_media_plan_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    campaign.id,
    left(campaign.name, 4000),
    left(coalesce(campaign.target_market, ''), 4000),
    left(campaign.keyword, 4000),
    left(campaign.comment_reply_text, 4000),
    left(campaign.follow_gate_text, 4000),
    left(campaign.framework_offer_text, 4000),
    left(campaign.delivery_text, 4000),
    left(coalesce(campaign.delivery_button_label, ''), 4000),
    (campaign.delivery_mode = 'upload' AND nullif(btrim(coalesce(campaign.delivery_storage_path, '')), '') IS NOT NULL),
    nullif(left(coalesce(campaign.delivery_file_name, ''), 200), ''),
    campaign.social_media_plan_id
  FROM public.lead_magnet_campaigns campaign
  WHERE campaign.organization_id = p_organization_id
    AND campaign.status = 'draft'
    AND (p_campaign_id IS NULL OR campaign.id = p_campaign_id)
  ORDER BY campaign.updated_at DESC, campaign.id DESC
  LIMIT CASE WHEN p_campaign_id IS NULL THEN 30 ELSE 1 END;

  IF p_campaign_id IS NOT NULL AND NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_list_lead_magnet_drafts"("p_user_id" "uuid", "p_organization_id" "uuid", "p_campaign_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_okr_cycles"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "name" "text", "year" integer, "quarter" "text", "period_type" "text", "start_date" "date", "end_date" "date", "is_active" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    c.id,
    c.name,
    c.year,
    c.quarter::text,
    c.period_type::text,
    c.start_date,
    c.end_date,
    c.is_active
  FROM public.okr_cycles c
  WHERE c.organization_id = p_organization_id
  ORDER BY c.is_active DESC, c.start_date DESC NULLS LAST, c.id ASC
  LIMIT 20;
END;
$$;


ALTER FUNCTION "public"."mcp_list_okr_cycles"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


