CREATE OR REPLACE FUNCTION "public"."mcp_list_task_initiative"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "level" "text", "title" "text", "task_title" "text", "priority" "text", "due_date" timestamp with time zone, "assignee_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT item.id, item.level, item.title, item.task_title, item.priority, item.due_date, item.assignee_name
  FROM (
    SELECT
      task.id,
      'task'::text AS level,
      task.title,
      task.title AS task_title,
      task.priority,
      COALESCE(assignee.due_date, task.due_date) AS due_date,
      assignee.full_name AS assignee_name,
      task.created_at
    FROM public.daily_tasks task
    LEFT JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name,
        due.due_date
      FROM public.daily_tasks_assigned assigned
      JOIN public.employees emp ON emp.id = assigned.employee_id
      LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
      LEFT JOIN LATERAL (
        SELECT dated.due_date
        FROM public.task_steps_assigned_duedate dated
        WHERE dated.daily_tasks_assigned_id = assigned.id
        ORDER BY dated.created_at DESC
        LIMIT 1
      ) due ON true
      WHERE assigned.daily_task_id = task.id
        AND assigned.organization_id = task.organization_id
      ORDER BY assigned.assigned_at DESC
      LIMIT 1
    ) assignee ON true
    WHERE task.organization_id = p_organization_id
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')

    UNION ALL

    SELECT
      step.id,
      'step'::text,
      step.title,
      task.title,
      COALESCE(step.priority, task.priority),
      COALESCE(assignee.due_date, task.due_date),
      assignee.full_name,
      step.created_at
    FROM public.task_steps step
    JOIN public.daily_tasks task ON task.id = step.task_id
    LEFT JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name,
        due.due_date
      FROM public.task_steps_assigned assigned
      JOIN public.employees emp ON emp.id = assigned.employee_id
      LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
      LEFT JOIN LATERAL (
        SELECT dated.due_date
        FROM public.task_steps_assigned_duedate dated
        WHERE dated.task_steps_assigned_id = assigned.id
        ORDER BY dated.created_at DESC
        LIMIT 1
      ) due ON true
      WHERE assigned.task_step_id = step.id
        AND assigned.organization_id = task.organization_id
      ORDER BY assigned.assigned_at DESC
      LIMIT 1
    ) assignee ON true
    WHERE task.organization_id = p_organization_id
      AND step.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')

    UNION ALL

    SELECT
      sub.id,
      'substep'::text,
      sub.title,
      task.title,
      task.priority,
      COALESCE(assignee.due_date, task.due_date),
      assignee.full_name,
      sub.created_at
    FROM public.task_steps_to_steps sub
    JOIN public.task_steps step ON step.id = sub.parent_step_id
    JOIN public.daily_tasks task ON task.id = step.task_id
    LEFT JOIN LATERAL (
      SELECT
        COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name,
        due.due_date
      FROM public.task_steps_to_steps_assigned assigned
      JOIN public.employees emp ON emp.id = assigned.employee_id
      LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
      LEFT JOIN LATERAL (
        SELECT dated.due_date
        FROM public.task_steps_assigned_duedate dated
        WHERE dated.task_steps_to_steps_assigned_id = assigned.id
        ORDER BY dated.created_at DESC
        LIMIT 1
      ) due ON true
      WHERE assigned.task_steps_to_steps_id = sub.id
        AND assigned.organization_id = task.organization_id
      ORDER BY assigned.assigned_at DESC
      LIMIT 1
    ) assignee ON true
    WHERE task.organization_id = p_organization_id
      AND sub.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
  ) item
  ORDER BY (item.assignee_name IS NULL) DESC, item.created_at DESC, item.id DESC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_task_initiative"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_task_steps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid") RETURNS TABLE("id" "uuid", "title" "text", "step_order" integer, "is_completed" boolean, "assignee_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_task_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.daily_tasks task
    WHERE task.id = p_task_id
      AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    step.id,
    step.title,
    step."order",
    step.is_completed,
    assignee.full_name
  FROM public.task_steps step
  LEFT JOIN LATERAL (
    SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name
    FROM public.task_steps_assigned assigned
    JOIN public.employees emp ON emp.id = assigned.employee_id
    LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
    WHERE assigned.task_step_id = step.id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1
  ) assignee ON true
  WHERE step.task_id = p_task_id
  ORDER BY step."order" ASC, step.created_at ASC, step.id ASC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_task_steps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_task_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_task_substeps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid") RETURNS TABLE("id" "uuid", "step_id" "uuid", "title" "text", "substep_order" integer, "is_completed" boolean, "assignee_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_step_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.task_steps step
    JOIN public.daily_tasks task ON task.id = step.task_id
    WHERE step.id = p_step_id
      AND task.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    sub.id,
    sub.parent_step_id,
    sub.title,
    sub."order",
    sub.is_completed,
    assignee.full_name
  FROM public.task_steps_to_steps sub
  LEFT JOIN LATERAL (
    SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name
    FROM public.task_steps_to_steps_assigned assigned
    JOIN public.employees emp ON emp.id = assigned.employee_id
    LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
    WHERE assigned.task_steps_to_steps_id = sub.id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1
  ) assignee ON true
  WHERE sub.parent_step_id = p_step_id
    AND sub.organization_id = p_organization_id
  ORDER BY sub."order" ASC, sub.created_at ASC, sub.id ASC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_task_substeps"("p_user_id" "uuid", "p_organization_id" "uuid", "p_step_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_tasks"("p_user_id" "uuid", "p_organization_id" "uuid", "p_status" "text", "p_month" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "priority" "text", "due_date" timestamp with time zone, "assignee_name" "text", "creator_name" "text", "plan_month" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_status text;
  v_month text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_status := NULLIF(lower(btrim(COALESCE(p_status, ''))), '');
  IF v_status IS NOT NULL AND v_status NOT IN ('pending', 'in_progress', 'completed', 'cancelled') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  v_month := NULLIF(btrim(COALESCE(p_month, '')), '');
  IF v_month IS NOT NULL AND v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_month' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    task.id,
    task.title,
    task.status,
    task.priority,
    task.due_date,
    assignee.full_name,
    COALESCE(creator_employee.full_name, creator_profile.full_name),
    to_char(task.plan_date AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM')
  FROM public.daily_tasks task
  LEFT JOIN LATERAL (
    SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), '')) AS full_name
    FROM public.daily_tasks_assigned assigned
    JOIN public.employees emp ON emp.id = assigned.employee_id
    LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
    WHERE assigned.daily_task_id = task.id
      AND assigned.organization_id = task.organization_id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1
  ) assignee ON true
  LEFT JOIN LATERAL (
    SELECT NULLIF(btrim(emp.full_name), '') AS full_name
    FROM public.employees emp
    WHERE emp.user_id = task.created_by
      AND emp.organization_id = task.organization_id
    ORDER BY emp.id ASC
    LIMIT 1
  ) creator_employee ON true
  LEFT JOIN LATERAL (
    SELECT NULLIF(btrim(prof.full_name), '') AS full_name
    FROM public.profiles prof
    WHERE prof.user_id = task.created_by
    LIMIT 1
  ) creator_profile ON true
  WHERE task.organization_id = p_organization_id
    AND (v_status IS NULL OR lower(task.status) = v_status)
    AND (
      v_month IS NULL
      OR to_char(task.plan_date AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM') = v_month
    )
  ORDER BY task.created_at DESC, task.id DESC
  LIMIT 30;
END;
$_$;


ALTER FUNCTION "public"."mcp_list_tasks"("p_user_id" "uuid", "p_organization_id" "uuid", "p_status" "text", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_thinking_ideas"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "statement" "text", "master_statement" "text", "angle_statement" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    idea.id,
    left(btrim(idea.statement), 500),
    left(btrim(master.statement), 500),
    left(btrim(angle.statement), 500)
  FROM public.thinking_lab_ideas idea
  JOIN public.thinking_lab_angles angle
    ON angle.id = idea.angle_id
   AND angle.organization_id = idea.organization_id
  JOIN public.thinking_lab_territories territory
    ON territory.id = angle.territory_id
   AND territory.organization_id = idea.organization_id
  JOIN public.thinking_big_thoughts thought
    ON thought.id = territory.big_thought_id
   AND thought.organization_id = idea.organization_id
  JOIN public.thinking_master_thoughts master
    ON master.id = thought.master_thought_id
   AND master.organization_id = idea.organization_id
   AND master.workspace = 'thinking_lab'
  WHERE idea.organization_id = p_organization_id
    AND idea.status = 'locked'
    AND idea.validation->>'decision' = 'LOLOS'
  ORDER BY idea.updated_at DESC, idea.id DESC
  LIMIT 30;
END;
$$;


ALTER FUNCTION "public"."mcp_list_thinking_ideas"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_thinking_masters"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("id" "uuid", "statement" "text", "prior_belief" "text", "audience" "text", "status" "text", "big_thoughts" integer, "ideas" integer, "updated_at" timestamp with time zone, "catalog" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  RETURN QUERY
  SELECT
    m.id,
    left(btrim(COALESCE(NULLIF(m.statement, ''), m.original_input, '')), 500),
    left(btrim(COALESCE(m.prior_belief, '')), 500),
    left(btrim(COALESCE(m.audience, '')), 300),
    COALESCE(m.mt_status, m.status, ''),
    (SELECT count(*)::int FROM public.thinking_big_thoughts b WHERE b.master_thought_id = m.id),
    (SELECT count(*)::int
       FROM public.thinking_lab_ideas i
       JOIN public.thinking_lab_angles a ON a.id = i.angle_id
       JOIN public.thinking_lab_territories t ON t.id = a.territory_id
       JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
      WHERE b.master_thought_id = m.id),
    m.updated_at,
    (SELECT s.name FROM public.services s WHERE s.id = m.service_id)
  FROM public.thinking_master_thoughts m
  WHERE m.organization_id = p_organization_id
  ORDER BY m.updated_at DESC
  LIMIT 30;
END;
$$;


ALTER FUNCTION "public"."mcp_list_thinking_masters"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_list_tool_audit"("p_organization_id" "uuid") RETURNS TABLE("user_id" "uuid", "full_name" "text", "tool_name" "text", "outcome" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_org_wide boolean;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = v_user
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_org_wide := EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_user
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin')
  );

  RETURN QUERY
  SELECT
    call.user_id,
    profile.full_name,
    call.tool_name,
    call.outcome,
    call.created_at
  FROM public.mcp_tool_calls call
  LEFT JOIN public.profiles profile
    ON profile.user_id = call.user_id
  WHERE call.organization_id = p_organization_id
    AND (v_org_wide OR call.user_id = v_user)
  ORDER BY call.created_at DESC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_list_tool_audit"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_lock_thinking_angles"("p_user_id" "uuid", "p_organization_id" "uuid", "p_territory_id" "uuid", "p_rows" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row jsonb;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  PERFORM 1 FROM public.thinking_lab_territories
   WHERE id = p_territory_id AND organization_id = p_organization_id AND status = 'locked'
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  FOR v_row IN SELECT * FROM jsonb_array_elements(COALESCE(p_rows, '[]'::jsonb)) LOOP
    UPDATE public.thinking_lab_angles
       SET status = 'locked', semantic_fingerprint = v_row->>'fingerprint'
     WHERE id = (v_row->>'id')::uuid AND organization_id = p_organization_id AND territory_id = p_territory_id;
  END LOOP;
END;
$$;


