CREATE OR REPLACE FUNCTION "public"."mcp_po_receive_snapshot"("p_organization_id" "uuid", "p_purchase_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_outlet_name text;
  v_supplier_name text;
  v_lines jsonb;
BEGIN
  SELECT * INTO v_po
  FROM public.catalog_purchase_orders po
  WHERE po.id = p_purchase_order_id
    AND po.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT o.name INTO v_outlet_name FROM public.pos_outlets o WHERE o.id = v_po.outlet_id;
  SELECT s.name INTO v_supplier_name FROM public.catalog_suppliers s WHERE s.id = v_po.supplier_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'name', l.name_snapshot,
      'qty', l.qty,
      'unit_cost', l.unit_cost,
      'subtotal', l.subtotal,
      'stock_now', COALESCE(stock.in_stock, 0)
    ) ORDER BY l.created_at), '[]'::jsonb)
  INTO v_lines
  FROM public.catalog_purchase_order_lines l
  LEFT JOIN LATERAL (
    SELECT CASE
      WHEN l.ingredient_id IS NOT NULL THEN (
        SELECT io.in_stock FROM public.catalog_ingredient_outlets io
        WHERE io.ingredient_id = l.ingredient_id AND io.outlet_id = v_po.outlet_id)
      WHEN l.variant_id IS NOT NULL THEN (
        SELECT vo.in_stock FROM public.catalog_product_variant_outlets vo
        WHERE vo.variant_id = l.variant_id AND vo.outlet_id = v_po.outlet_id)
      ELSE (
        SELECT po2.in_stock FROM public.catalog_product_outlets po2
        WHERE po2.product_id = l.product_id AND po2.outlet_id = v_po.outlet_id)
    END AS in_stock
  ) stock ON true
  WHERE l.purchase_order_id = v_po.id;

  RETURN jsonb_build_object(
    'purchase_order_id', v_po.id,
    'order_number', v_po.order_number,
    'status', v_po.status,
    'kind', v_po.item_kind,
    'outlet_id', v_po.outlet_id,
    'outlet_name', COALESCE(v_outlet_name, '—'),
    'supplier_name', COALESCE(v_supplier_name, 'No Supplier'),
    'note', v_po.note,
    'occurred_at', v_po.occurred_at,
    'total_value', v_po.total_value,
    'finance_status', public.mcp_po_finance_status(v_po.id),
    'lines', v_lines
  );
END;
$$;


ALTER FUNCTION "public"."mcp_po_receive_snapshot"("p_organization_id" "uuid", "p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_preview_ingredient_production"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet_name text;
  v_item_id uuid;
  v_item record;
  v_recipe_id uuid;
  v_yield numeric;
  v_scale numeric;
  v_line record;
  v_lines jsonb := '[]'::jsonb;
  v_need numeric;
  v_stock numeric;
  v_line_cost numeric;
  v_batch_cost numeric := 0;
  v_unit_cost numeric;
  v_short text[] := ARRAY[]::text[];
  v_no_cost text[] := ARRAY[]::text[];
  v_out record;
  v_out_before numeric;
  v_avg_after numeric;
BEGIN
  PERFORM public.mcp_inventory_manager_guard(p_user_id, p_organization_id);

  IF p_qty IS NULL OR p_qty <= 0 OR p_qty > 1000000 OR round(p_qty, 3) <> p_qty THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT o.name INTO v_outlet_name
  FROM public.pos_outlets o
  WHERE o.id = p_outlet_id
    AND o.organization_id = p_organization_id
    AND NOT COALESCE(o.is_deleted, false);
  IF v_outlet_name IS NULL THEN
    RAISE EXCEPTION 'outlet_not_found' USING ERRCODE = 'P0002';
  END IF;

  v_item_id := public._mcp_resolve_semi_finished(p_organization_id, p_search);

  SELECT i.id, i.name, i.unit_code, i.track_inventory
    INTO v_item
  FROM public.catalog_ingredients i
  WHERE i.id = v_item_id;
  IF v_item.track_inventory IS NOT TRUE THEN
    RAISE EXCEPTION 'production_item_not_tracked' USING ERRCODE = '22023';
  END IF;

  SELECT r.id, r.yield_qty INTO v_recipe_id, v_yield
  FROM public.catalog_ingredient_recipes r
  WHERE r.output_ingredient_id = v_item_id
    AND r.organization_id = p_organization_id;
  IF v_recipe_id IS NULL OR v_yield IS NULL OR v_yield <= 0 OR NOT EXISTS (
    SELECT 1 FROM public.catalog_ingredient_recipe_lines l WHERE l.recipe_id = v_recipe_id AND l.quantity > 0
  ) THEN
    RAISE EXCEPTION 'production_recipe_required' USING ERRCODE = '22023';
  END IF;

  v_scale := p_qty / v_yield;

  FOR v_line IN
    SELECT l.ingredient_id, l.quantity, i.name, i.unit_code, i.track_inventory,
           io.in_stock, io.avg_cost, io.track_cogs
    FROM public.catalog_ingredient_recipe_lines l
    JOIN public.catalog_ingredients i ON i.id = l.ingredient_id AND NOT COALESCE(i.is_deleted, false)
    LEFT JOIN public.catalog_ingredient_outlets io
      ON io.ingredient_id = l.ingredient_id AND io.outlet_id = p_outlet_id
    WHERE l.recipe_id = v_recipe_id AND l.quantity > 0
    ORDER BY l.sort_order, i.name
  LOOP
    v_need := round(v_line.quantity * v_scale, 3);
    v_stock := COALESCE(v_line.in_stock, 0);
    v_line_cost := CASE WHEN v_line.track_cogs IS TRUE THEN COALESCE(v_line.avg_cost, 0) * (v_line.quantity * v_scale) ELSE 0 END;
    v_batch_cost := v_batch_cost + v_line_cost;
    IF v_line.track_inventory IS TRUE AND v_stock < (v_line.quantity * v_scale) THEN
      v_short := array_append(v_short, v_line.name);
    END IF;
    IF v_line.track_cogs IS NOT TRUE OR COALESCE(v_line.avg_cost, 0) <= 0 THEN
      v_no_cost := array_append(v_no_cost, v_line.name);
    END IF;
    v_lines := v_lines || jsonb_build_object(
      'ingredient', v_line.name,
      'unit_code', v_line.unit_code,
      'per_batch', v_line.quantity,
      'need', v_need,
      'stock_tracked', v_line.track_inventory IS TRUE,
      'stock_before', CASE WHEN v_line.track_inventory IS TRUE THEN v_stock END,
      'stock_after', CASE WHEN v_line.track_inventory IS TRUE THEN round(v_stock - v_line.quantity * v_scale, 3) END,
      'enough', v_line.track_inventory IS NOT TRUE OR v_stock >= (v_line.quantity * v_scale),
      'unit_cost', CASE WHEN v_line.track_cogs IS TRUE THEN COALESCE(v_line.avg_cost, 0) ELSE 0 END,
      'cost', round(v_line_cost, 2)
    );
  END LOOP;

  v_unit_cost := CASE WHEN v_batch_cost > 0 THEN v_batch_cost / p_qty ELSE 0 END;

  SELECT io.in_stock, io.avg_cost, io.track_cogs INTO v_out
  FROM public.catalog_ingredient_outlets io
  WHERE io.ingredient_id = v_item_id AND io.outlet_id = p_outlet_id;
  v_out_before := COALESCE(v_out.in_stock, 0);
  IF v_out.track_cogs IS TRUE THEN
    v_avg_after := CASE
      WHEN (v_out_before + p_qty) <= 0 THEN v_unit_cost
      ELSE ((v_out_before * COALESCE(v_out.avg_cost, 0)) + (p_qty * v_unit_cost)) / (v_out_before + p_qty)
    END;
  END IF;

  RETURN jsonb_build_object(
    'outlet_id', p_outlet_id,
    'outlet_name', v_outlet_name,
    'item_id', v_item_id,
    'item', v_item.name,
    'unit_code', v_item.unit_code,
    'qty', p_qty,
    'recipe_yield', v_yield,
    'batches', round(v_scale, 4),
    'lines', v_lines,
    'can_produce', cardinality(v_short) = 0,
    'short_of', to_jsonb(v_short),
    'without_cost', to_jsonb(v_no_cost),
    'batch_cost', round(v_batch_cost, 2),
    'unit_cost', round(v_unit_cost, 2),
    'stock_before', v_out_before,
    'stock_after', round(v_out_before + p_qty, 3),
    'cost_tracked', v_out.track_cogs IS TRUE,
    'avg_cost_before', CASE WHEN v_out.track_cogs IS TRUE THEN COALESCE(v_out.avg_cost, 0) END,
    'avg_cost_after', CASE WHEN v_out.track_cogs IS TRUE THEN round(v_avg_after, 2) END
  );
END;
$$;


ALTER FUNCTION "public"."mcp_preview_ingredient_production"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_preview_inventory_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_search text;
  v_note text;
  v_outlet_name text;
  v_supplier_name text;
  v_po_mode text;
  v_count integer := 0;
  v_labels text[] := ARRAY[]::text[];
  v_match record;
  v_kind text;
  v_name text;
  v_variant_name text;
  v_unit_code text;
  v_qty_before numeric;
  v_receive_now boolean;
BEGIN
  PERFORM public.mcp_inventory_manager_guard(p_user_id, p_organization_id);

  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_search := btrim(COALESCE(p_search, ''));
  IF v_search = '' OR char_length(v_search) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_qty IS NULL
    OR p_qty <= 0
    OR p_qty > 99999999999.999
    OR scale(p_qty) > 3
    OR p_unit_cost IS NULL
    OR p_unit_cost <= 0
    OR p_unit_cost > 999999999999.99
    OR round(p_qty * p_unit_cost, 2) <= 0
    OR round(p_qty * p_unit_cost, 2) > 999999999999.99
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_note := NULLIF(btrim(COALESCE(p_note, '')), '');
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT outlet.name
    INTO v_outlet_name
  FROM public.pos_outlets outlet
  WHERE outlet.id = p_outlet_id
    AND outlet.organization_id = p_organization_id
    AND outlet.is_deleted = false;

  IF v_outlet_name IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF p_supplier_id IS NOT NULL THEN
    SELECT supplier.name
      INTO v_supplier_name
    FROM public.catalog_suppliers supplier
    WHERE supplier.id = p_supplier_id
      AND supplier.organization_id = p_organization_id
      AND supplier.is_deleted = false;
    IF v_supplier_name IS NULL THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  -- Same matching rule as mcp_create_inventory_purchase_order.
  FOR v_match IN
    SELECT found.kind, found.name, found.variant_name, found.unit_code, found.qty_before, found.label
    FROM (
      SELECT
        'ingredient'::text AS kind,
        i.name,
        NULL::text AS variant_name,
        i.unit_code AS unit_code,
        io.in_stock AS qty_before,
        i.name AS label
      FROM public.catalog_ingredients i
      JOIN public.catalog_ingredient_outlets io
        ON io.ingredient_id = i.id
       AND io.outlet_id = p_outlet_id
       AND io.organization_id = p_organization_id
      WHERE i.organization_id = p_organization_id
        AND i.is_deleted = false
        AND i.track_inventory = true
        AND lower(btrim(i.name)) = lower(v_search)

      UNION ALL

      SELECT
        'product'::text,
        dp.name,
        NULL::text,
        NULL::text,
        link.in_stock,
        dp.name
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link
        ON link.product_id = dp.id
       AND link.outlet_id = p_outlet_id
       AND link.organization_id = p_organization_id
      WHERE dp.organization_id = p_organization_id
        AND dp.kind = 'product'
        AND dp.track_stock = true
        AND lower(btrim(dp.name)) = lower(v_search)
        AND NOT EXISTS (
          SELECT 1
          FROM public.catalog_product_variants variant
          WHERE variant.product_id = dp.id
        )

      UNION ALL

      SELECT
        'product'::text,
        dp.name,
        variant.name,
        NULL::text,
        COALESCE(stock.in_stock, 0),
        dp.name || ' / ' || variant.name
      FROM public.default_prices dp
      JOIN public.catalog_product_outlets link
        ON link.product_id = dp.id
       AND link.outlet_id = p_outlet_id
       AND link.organization_id = p_organization_id
      JOIN public.catalog_product_variants variant
        ON variant.product_id = dp.id
       AND variant.organization_id = dp.organization_id
      LEFT JOIN public.catalog_product_variant_outlets stock
        ON stock.variant_id = variant.id
       AND stock.outlet_id = p_outlet_id
       AND stock.organization_id = p_organization_id
      WHERE dp.organization_id = p_organization_id
        AND dp.kind = 'product'
        AND dp.track_stock = true
        AND lower(btrim(variant.name)) = lower(v_search)
    ) found
    ORDER BY found.label
  LOOP
    v_count := v_count + 1;
    v_labels := v_labels || v_match.label;
    v_kind := v_match.kind;
    v_name := v_match.name;
    v_variant_name := v_match.variant_name;
    v_unit_code := v_match.unit_code;
    v_qty_before := v_match.qty_before;
  END LOOP;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_count > 1 THEN
    RAISE EXCEPTION '%', 'ambiguous: ' || array_to_string(v_labels, ' | ')
      USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(
    (SELECT settings.po_mode
     FROM public.catalog_inventory_settings settings
     WHERE settings.organization_id = p_organization_id),
    'simple'
  )
  INTO v_po_mode;

  v_receive_now := v_po_mode IS DISTINCT FROM 'advanced';

  RETURN jsonb_build_object(
    'saved', false,
    'outlet_id', p_outlet_id,
    'outlet_name', v_outlet_name,
    'kind', v_kind,
    'name', v_name,
    'variant_name', v_variant_name,
    'unit_code', v_unit_code,
    'qty', p_qty,
    'unit_cost', p_unit_cost,
    'subtotal', round(p_qty * p_unit_cost, 2),
    'supplier_id', p_supplier_id,
    'supplier_name', v_supplier_name,
    'note', v_note,
    'po_mode', v_po_mode,
    'stock_received_on_confirm', v_receive_now,
    'qty_before', COALESCE(v_qty_before, 0),
    'qty_after_expected', CASE WHEN v_receive_now THEN COALESCE(v_qty_before, 0) + p_qty ELSE COALESCE(v_qty_before, 0) END
  );
END;
$$;


ALTER FUNCTION "public"."mcp_preview_inventory_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_qty" numeric, "p_unit_cost" numeric, "p_supplier_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_preview_receive_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_purchase_order_id" "uuid" DEFAULT NULL::"uuid", "p_order_number" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po_id uuid;
  v_number text;
  v_snapshot jsonb;
  v_po_mode text;
  v_finance text;
  v_blocked text := NULL;
BEGIN
  PERFORM public.mcp_po_receive_member_guard(p_user_id, p_organization_id);

  IF p_purchase_order_id IS NOT NULL THEN
    v_po_id := p_purchase_order_id;
  ELSE
    v_number := btrim(COALESCE(p_order_number, ''));
    IF v_number = '' OR char_length(v_number) > 40 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    IF left(v_number, 1) <> '#' THEN
      v_number := '#' || v_number;
    END IF;
    SELECT po.id INTO v_po_id
    FROM public.catalog_purchase_orders po
    WHERE po.organization_id = p_organization_id
      AND po.order_number = v_number
    LIMIT 1;
    IF v_po_id IS NULL THEN
      RAISE EXCEPTION 'catalog_po_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  v_snapshot := public.mcp_po_receive_snapshot(p_organization_id, v_po_id);
  v_po_mode := public.catalog_inventory_po_mode(p_organization_id);
  v_finance := v_snapshot ->> 'finance_status';

  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', p_user_id, 'role', 'authenticated')::text, true);

  IF v_snapshot ->> 'status' <> 'waiting' THEN
    v_blocked := 'catalog_po_not_waiting';
  ELSIF v_finance <> 'none' THEN
    IF v_po_mode = 'advanced'
      AND NOT public.user_has_inventory_feature_access(p_organization_id, 'po_fulfillment') THEN
      v_blocked := 'catalog_inventory_feature_forbidden';
    ELSIF v_finance <> 'paid' THEN
      v_blocked := 'catalog_po_payment_required';
    END IF;
  END IF;

  RETURN v_snapshot || jsonb_build_object(
    'saved', false,
    'po_mode', v_po_mode,
    'can_receive', v_blocked IS NULL,
    'blocked_reason', v_blocked,
    'lines', (
      SELECT COALESCE(jsonb_agg(line || jsonb_build_object(
        'stock_after_expected', (line ->> 'stock_now')::numeric + (line ->> 'qty')::numeric
      )), '[]'::jsonb)
      FROM jsonb_array_elements(v_snapshot -> 'lines') line
    )
  );
END;
$$;


ALTER FUNCTION "public"."mcp_preview_receive_purchase_order"("p_user_id" "uuid", "p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_order_number" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_preview_stock_adjustment"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_set_to" numeric, "p_change" numeric, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_before numeric;
  v_delta numeric;
  v_outlet_name text;
  v_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id AND uo.organization_id = p_organization_id AND COALESCE(uo.is_active, true)
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
  IF NOT public.catalog_can_adjust_stock(p_user_id, p_organization_id) THEN
    RAISE EXCEPTION 'catalog_adjustment_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_reason IS NULL THEN
    RAISE EXCEPTION 'catalog_adjustment_reason_required' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_reason) > 500 OR (p_set_to IS NULL) = (p_change IS NULL)
     OR (p_set_to IS NOT NULL AND p_set_to < 0) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT o.name INTO v_outlet_name
  FROM public.pos_outlets o
  WHERE o.id = p_outlet_id AND o.organization_id = p_organization_id AND NOT COALESCE(o.is_deleted, false);
  IF v_outlet_name IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  v_item := public.mcp_adjustment_resolve_item(p_organization_id, p_outlet_id, p_search);
  v_before := (v_item ->> 'qty_before')::numeric;
  v_delta := COALESCE(p_set_to - v_before, p_change);

  IF v_delta = 0 OR abs(v_delta) > 1000000000 THEN
    RAISE EXCEPTION 'catalog_adjustment_no_change' USING ERRCODE = '22023';
  END IF;

  RETURN v_item || jsonb_build_object(
    'saved', false,
    'outlet_id', p_outlet_id,
    'outlet_name', v_outlet_name,
    'qty_change', v_delta,
    'qty_after', v_before + v_delta,
    'reason', v_reason
  );
END;
$$;


ALTER FUNCTION "public"."mcp_preview_stock_adjustment"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_search" "text", "p_set_to" numeric, "p_change" numeric, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_read_content_brief_for_update"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") RETURNS TABLE("version_no" integer, "status" "text", "approved" boolean, "revision_locked" boolean, "can_storyboard" boolean, "can_concept" boolean, "can_caption" boolean, "can_link" boolean, "brief" "text", "concept" "text", "caption" "text", "link_reference" "text", "shots" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status text;
  v_approved boolean;
  v_brief text;
  v_concept text;
  v_caption text;
  v_link text;
  v_shots jsonb;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_plan_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations AS member
    WHERE member.user_id = p_user_id
      AND member.organization_id = p_organization_id
      AND COALESCE(member.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT plan.status, plan.approved, plan.brief
    INTO v_status, v_approved, v_brief
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
    AND plan.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT audience.description INTO v_concept
  FROM public.brief_target_audiences AS audience
  WHERE audience.social_media_plan_id = p_plan_id;

  SELECT caption_row.content INTO v_caption
  FROM public.brief_captions AS caption_row
  WHERE caption_row.social_media_plan_id = p_plan_id;

  SELECT link_row.content INTO v_link
  FROM public.brief_link_references AS link_row
  WHERE link_row.social_media_plan_id = p_plan_id;

  SELECT COALESCE(MAX(versions.version_no), 0)
    INTO version_no
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object('id', shot.id, 'row_index', shot.row_index)
      ORDER BY shot.row_index
    ),
    '[]'::jsonb
  )
    INTO v_shots
  FROM public.brief_storyboard_shots AS shot
  WHERE shot.social_media_plan_id = p_plan_id;

  status := v_status;
  approved := COALESCE(v_approved, false);
  revision_locked := public.content_brief_revision_locked(p_plan_id);
  can_storyboard := public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard', p_user_id);
  can_concept := public.can_edit_content_brief_field(p_plan_id, 'brief_concept', p_user_id);
  can_caption := public.can_edit_content_brief_field(p_plan_id, 'brief_caption', p_user_id);
  can_link := public.can_edit_content_brief_field(p_plan_id, 'brief_link', p_user_id);
  brief := v_brief;
  concept := v_concept;
  caption := v_caption;
  link_reference := v_link;
  shots := v_shots;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_read_content_brief_for_update"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_read_content_brief_for_update"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid") IS 'Read one brief, its version, edit rights, and production lock for an MCP preview. Writes nothing.';



CREATE OR REPLACE FUNCTION "public"."mcp_record_tool_call"("p_user_id" "uuid", "p_organization_id" "uuid", "p_client_id" "text", "p_tool_name" "text", "p_outcome" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL
    OR p_organization_id IS NULL
    OR NULLIF(btrim(COALESCE(p_client_id, '')), '') IS NULL
    OR NULLIF(btrim(COALESCE(p_tool_name, '')), '') IS NULL
    OR char_length(p_tool_name) > 120
    OR p_outcome NOT IN ('ok', 'error', 'forbidden', 'rate_limited') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.mcp_tool_calls old_call
  WHERE old_call.organization_id = p_organization_id
    AND old_call.created_at < now() - interval '30 days';

  INSERT INTO public.mcp_tool_calls (organization_id, user_id, client_id, tool_name, outcome)
  VALUES (p_organization_id, p_user_id, p_client_id, p_tool_name, p_outcome);
END;
$$;


ALTER FUNCTION "public"."mcp_record_tool_call"("p_user_id" "uuid", "p_organization_id" "uuid", "p_client_id" "text", "p_tool_name" "text", "p_outcome" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_revoke_connection"("p_organization_id" "uuid", "p_user_id" "uuid", "p_client_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_org_wide boolean;
  v_now timestamptz;
  v_count integer;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL OR p_organization_id IS NULL OR p_user_id IS NULL OR NULLIF(btrim(COALESCE(p_client_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = v_user
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_org_wide := EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = v_user
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin')
  );

  IF v_user <> p_user_id AND NOT v_org_wide THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_now := clock_timestamp();

  UPDATE public.mcp_oauth_refresh_tokens token
  SET revoked_at = v_now
  WHERE token.organization_id = p_organization_id
    AND token.user_id = p_user_id
    AND token.client_id = p_client_id
    AND token.revoked_at IS NULL
    AND token.expires_at > v_now;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count = 0 THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.mcp_oauth_revocations (user_id, organization_id, client_id, revoked_at)
  VALUES (p_user_id, p_organization_id, p_client_id, v_now)
  ON CONFLICT (user_id, organization_id, client_id)
  DO UPDATE SET revoked_at = EXCLUDED.revoked_at;
END;
$$;


ALTER FUNCTION "public"."mcp_revoke_connection"("p_organization_id" "uuid", "p_user_id" "uuid", "p_client_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_save_thinking_execution"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid", "p_content_pillar_id" "uuid", "p_statement" "text", "p_script" "jsonb", "p_facts" "jsonb", "p_admission" "text") RETURNS TABLE("id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_pillar_name text;
  v_existing uuid;
  v_id uuid;
  v_statement text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_idea_id IS NULL OR p_content_pillar_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.thinking_lab_ideas idea
    WHERE idea.id = p_idea_id
      AND idea.organization_id = p_organization_id
      AND idea.status = 'locked'
      AND idea.validation->>'decision' = 'LOLOS'
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT pillar.name
  INTO v_pillar_name
  FROM public.content_pillars pillar
  WHERE pillar.id = p_content_pillar_id
    AND pillar.is_active = true
    AND (pillar.organization_id = p_organization_id OR pillar.is_default = true);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_statement := NULLIF(left(btrim(COALESCE(p_statement, '')), 20000), '');
  IF v_statement IS NULL
    OR p_admission IS DISTINCT FROM 'GENERATE_VALID'
    OR jsonb_typeof(p_script) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_facts) IS DISTINCT FROM 'object'
    OR COALESCE(p_facts->>'relationToParent', '') IS DISTINCT FROM 'VALID_EXECUTION'
    OR COALESCE(p_facts->>'resolution', '') IS DISTINCT FROM 'RESOLVED'
    OR position('portraitPath' IN p_script::text) > 0
    OR position('bodyPath' IN p_script::text) > 0
    OR position('sheetPath' IN p_script::text) > 0
    OR position('locationPath' IN p_script::text) > 0
    OR position('propertyPath' IN p_script::text) > 0
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT ex.id
  INTO v_existing
  FROM public.thinking_lab_executions ex
  WHERE ex.organization_id = p_organization_id
    AND ex.idea_id = p_idea_id
    AND ex.content_pillar_id = p_content_pillar_id
    AND ex.creative_idea_id IS NULL
    AND ex.author_employee_id IS NULL
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    UPDATE public.thinking_lab_executions ex
    SET pillar = p_content_pillar_id::text,
        pillar_name = v_pillar_name,
        statement = v_statement,
        script = p_script,
        canonical_semantic = p_facts || jsonb_build_object('pillar', v_pillar_name),
        admission = 'GENERATE_VALID'
    WHERE ex.id = v_existing
      AND ex.organization_id = p_organization_id
      AND ex.author_employee_id IS NULL
    RETURNING ex.id INTO v_id;
  ELSE
    INSERT INTO public.thinking_lab_executions (
      organization_id,
      idea_id,
      pillar,
      content_pillar_id,
      pillar_name,
      statement,
      script,
      canonical_semantic,
      admission
    )
    VALUES (
      p_organization_id,
      p_idea_id,
      p_content_pillar_id::text,
      p_content_pillar_id,
      v_pillar_name,
      v_statement,
      p_script,
      p_facts || jsonb_build_object('pillar', v_pillar_name),
      'GENERATE_VALID'
    )
    RETURNING thinking_lab_executions.id INTO v_id;
  END IF;

  id := v_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_save_thinking_execution"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid", "p_content_pillar_id" "uuid", "p_statement" "text", "p_script" "jsonb", "p_facts" "jsonb", "p_admission" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_content_plan_drive_link"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_url" "text") RETURNS TABLE("id" "uuid", "title" "text", "google_drive_link" "text", "production_status" "text", "changed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_url text;
  v_plan public.social_media_plans%ROWTYPE;
  v_status text;
  v_baseline text;
  v_same boolean;
  v_folder boolean;
  v_promote boolean := false;
  v_only_link boolean := false;
  v_employee uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_plan_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_url := btrim(COALESCE(p_url, ''));
  IF char_length(v_url) < 20 OR char_length(v_url) > 2000
     OR v_url !~* '^https://'
     OR v_url !~* 'drive\.google\.com' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_folder := v_url ~* 'drive\.google\.com/drive/folders/[a-zA-Z0-9_-]+';
  IF NOT v_folder
     AND v_url !~* '/file/d/[a-zA-Z0-9_-]+'
     AND v_url !~* '/d/[a-zA-Z0-9_-]+'
     AND v_url !~* '[?&]id=[a-zA-Z0-9_-]+' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT plan.*
  INTO v_plan
  FROM public.social_media_plans plan
  WHERE plan.id = p_plan_id
    AND plan.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  -- Office locks the Google Drive Link cell until the brief is approved
  -- (ContentPlanRow: isGoogleDriveLinkDisabled = !plan.approved). Same rule here.
  IF NOT COALESCE(v_plan.approved, false) THEN
    RAISE EXCEPTION 'not_approved' USING ERRCODE = '42501';
  END IF;

  v_status := lower(btrim(COALESCE(v_plan.production_status, '')));
  v_baseline := COALESCE(
    NULLIF(btrim(COALESCE(v_plan.production_revision_baseline_link, '')), ''),
    NULLIF(btrim(COALESCE(v_plan.google_drive_link, '')), ''),
    ''
  );
  v_same := public.mcp_drive_link_key(v_url) = public.mcp_drive_link_key(v_baseline);

  IF v_status = 'request revision' THEN
    IF v_folder AND v_same THEN
      IF btrim(COALESCE(v_plan.google_drive_link, '')) = v_url THEN
        v_promote := false;
      ELSE
        v_only_link := true;
      END IF;
    ELSIF NOT v_same THEN
      v_promote := true;
    ELSIF btrim(COALESCE(v_plan.google_drive_link, '')) = v_url THEN
      v_promote := false;
    ELSE
      v_only_link := true;
    END IF;
  ELSE
    v_promote := true;
  END IF;

  IF v_only_link THEN
    UPDATE public.social_media_plans plan
    SET google_drive_link = v_url,
        updated_at = now()
    WHERE plan.id = p_plan_id
      AND plan.organization_id = p_organization_id
    RETURNING * INTO v_plan;
  ELSIF v_promote THEN
    IF COALESCE(v_plan.pic_production_source, '') IS DISTINCT FROM 'task_steps_assigned' THEN
      SELECT emp.id
      INTO v_employee
      FROM public.employees emp
      LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
      WHERE emp.organization_id = p_organization_id
        AND emp.user_id = p_user_id
        AND COALESCE(emp.pending_removal, false) = false
        AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
        AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
          NOT IN ('inactive', 'terminated', 'pendingremoval')
      ORDER BY emp.id ASC
      LIMIT 1;
    END IF;

    UPDATE public.social_media_plans plan
    SET google_drive_link = v_url,
        production_status = 'Need Review',
        production_completion_date = now(),
        production_revision_baseline_link = NULL,
        pic_production_id = CASE
          WHEN COALESCE(plan.pic_production_source, '') = 'task_steps_assigned' OR v_employee IS NULL
            THEN plan.pic_production_id
          ELSE v_employee
        END,
        pic_production_source = CASE
          WHEN COALESCE(plan.pic_production_source, '') = 'task_steps_assigned' OR v_employee IS NULL
            THEN plan.pic_production_source
          ELSE 'google_drive_link'
        END,
        updated_at = now()
    WHERE plan.id = p_plan_id
      AND plan.organization_id = p_organization_id
    RETURNING * INTO v_plan;
  END IF;

  id := v_plan.id;
  title := v_plan.title;
  google_drive_link := v_plan.google_drive_link;
  production_status := v_plan.production_status;
  changed := v_only_link OR v_promote;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_set_content_plan_drive_link"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."mcp_set_content_plan_drive_link"("p_user_id" "uuid", "p_organization_id" "uuid", "p_plan_id" "uuid", "p_url" "text") IS 'MCP content.plans.media.set_link: save a Google Drive file or folder URL on one approved content plan.';



CREATE OR REPLACE FUNCTION "public"."mcp_set_lead_magnet_delivery"("p_user_id" "uuid", "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime" "text", "p_size_bytes" integer, "p_public_url" "text") RETURNS TABLE("id" "uuid", "file_name" "text", "has_file" boolean, "previous_storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_status text;
  v_previous text;
  v_name text;
  v_path text;
  v_url text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_campaign_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_path := btrim(coalesce(p_storage_path, ''));
  v_name := btrim(coalesce(p_file_name, ''));
  v_url := btrim(coalesce(p_public_url, ''));
  IF v_path <> lower(v_path)
    OR v_path !~ (
      '^' || lower(p_organization_id::text) || '/' || lower(p_campaign_id::text) ||
      '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}_[a-z0-9._-]+\.pdf$'
    )
    OR v_name = ''
    OR char_length(v_name) > 200
    OR position('/' IN v_name) > 0
    OR lower(p_mime) <> 'application/pdf'
    OR p_size_bytes IS NULL
    OR p_size_bytes <= 0
    OR p_size_bytes > 26214400
    OR left(v_url, 8) <> 'https://'
    OR char_length(v_url) > 2000
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT campaign.status, campaign.delivery_storage_path
  INTO v_status, v_previous
  FROM public.lead_magnet_campaigns campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'not_draft' USING ERRCODE = '42501';
  END IF;

  UPDATE public.lead_magnet_campaigns campaign
  SET
    delivery_mode = 'upload',
    delivery_storage_path = v_path,
    delivery_file_name = v_name,
    delivery_file_mime = 'application/pdf',
    delivery_file_size_bytes = p_size_bytes,
    delivery_url = v_url
  WHERE campaign.id = p_campaign_id
    AND campaign.organization_id = p_organization_id;

  id := p_campaign_id;
  file_name := v_name;
  has_file := true;
  previous_storage_path := nullif(btrim(coalesce(v_previous, '')), '');
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_set_lead_magnet_delivery"("p_user_id" "uuid", "p_organization_id" "uuid", "p_campaign_id" "uuid", "p_storage_path" "text", "p_file_name" "text", "p_mime" "text", "p_size_bytes" integer, "p_public_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_lead_status"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_status" "text") RETURNS TABLE("id" "uuid", "ticket_id" "text", "client" "text", "title" "text", "source" "text", "status" "text", "fu_priority" "text", "assignee" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_status_name text;
  v_status_id uuid;
  v_current_status uuid;
  v_ticket text;
  v_prefix text;
  v_conv_id uuid;
  v_conv_table text;
  v_count integer;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_status_name := NULLIF(btrim(COALESCE(p_status, '')), '');
  IF v_status_name IS NULL OR char_length(v_status_name) > 80
    OR lower(v_status_name) IN ('converted', 'closed', 'resolve') THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  SELECT ls.id
  INTO v_status_id
  FROM public.lead_statuses ls
  WHERE ls.is_active = true
    AND lower(btrim(ls.name)) = lower(v_status_name)
    AND (ls.organization_id = p_organization_id OR ls.organization_id IS NULL)
  ORDER BY (ls.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ls.sort_order ASC NULLS LAST
  LIMIT 1;
  IF v_status_id IS NULL THEN
    RAISE EXCEPTION 'invalid_status' USING ERRCODE = '22023';
  END IF;

  SELECT lead.status_id, NULLIF(btrim(lead.ticket_id), '')
  INTO v_current_status, v_ticket
  FROM public.leads lead
  WHERE lead.id = p_id
    AND lead.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_current_status IS DISTINCT FROM v_status_id THEN
    PERFORM set_config('mcp.actor_user_id', p_user_id::text, true);

    UPDATE public.leads AS lead
    SET status_id = v_status_id, updated_at = now()
    WHERE lead.id = p_id
      AND lead.organization_id = p_organization_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;

    SELECT enrollment.conversation_id, enrollment.conversation_table
    INTO v_conv_id, v_conv_table
    FROM public.lead_magnet_enrollments enrollment
    WHERE enrollment.organization_id = p_organization_id
      AND enrollment.lead_id = p_id
      AND enrollment.conversation_id IS NOT NULL
      AND enrollment.conversation_table IN (
        'whatsapp_conversations',
        'instagram_conversations',
        'facebook_conversations',
        'email_conversations'
      )
    ORDER BY enrollment.updated_at DESC
    LIMIT 1;

    v_count := 0;
    IF v_conv_id IS NOT NULL AND v_conv_table = 'instagram_conversations' THEN
      UPDATE public.instagram_conversations AS conversation
      SET lead_status_id = v_status_id, updated_at = now()
      WHERE conversation.id = v_conv_id
        AND conversation.organization_id = p_organization_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSIF v_conv_id IS NOT NULL AND v_conv_table = 'facebook_conversations' THEN
      UPDATE public.facebook_conversations AS conversation
      SET lead_status_id = v_status_id, updated_at = now()
      WHERE conversation.id = v_conv_id
        AND conversation.organization_id = p_organization_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSIF v_conv_id IS NOT NULL AND v_conv_table = 'email_conversations' THEN
      UPDATE public.email_conversations AS conversation
      SET lead_status_id = v_status_id, updated_at = now()
      WHERE conversation.id = v_conv_id
        AND conversation.organization_id = p_organization_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    ELSIF v_conv_id IS NOT NULL AND v_conv_table = 'whatsapp_conversations' THEN
      UPDATE public.whatsapp_conversations AS conversation
      SET lead_status_id = v_status_id, updated_at = now()
      WHERE conversation.id = v_conv_id
        AND conversation.organization_id = p_organization_id;
      GET DIAGNOSTICS v_count = ROW_COUNT;
    END IF;

    IF v_count = 0 AND v_ticket IS NOT NULL THEN
      v_prefix := upper(v_ticket);
      IF left(v_prefix, 3) = 'IG-' THEN
        UPDATE public.instagram_conversations AS conversation
        SET lead_status_id = v_status_id, updated_at = now()
        WHERE conversation.id = (
          SELECT candidate.id
          FROM public.instagram_conversations candidate
          WHERE candidate.organization_id = p_organization_id
            AND lower(btrim(candidate.ticket_id)) = lower(v_ticket)
          LIMIT 1
        );
        GET DIAGNOSTICS v_count = ROW_COUNT;
        IF v_count = 0 THEN
          UPDATE public.whatsapp_conversations AS conversation
          SET lead_status_id = v_status_id, updated_at = now()
          WHERE conversation.id = (
            SELECT candidate.id
            FROM public.whatsapp_conversations candidate
            WHERE candidate.organization_id = p_organization_id
              AND lower(btrim(candidate.ticket_id)) = lower(v_ticket)
            LIMIT 1
          );
        END IF;
      ELSIF left(v_prefix, 3) = 'FB-' THEN
        UPDATE public.facebook_conversations AS conversation
        SET lead_status_id = v_status_id, updated_at = now()
        WHERE conversation.id = (
          SELECT candidate.id
          FROM public.facebook_conversations candidate
          WHERE candidate.organization_id = p_organization_id
            AND lower(btrim(candidate.ticket_id)) = lower(v_ticket)
          LIMIT 1
        );
      ELSIF left(v_prefix, 6) = 'EMAIL-' THEN
        UPDATE public.email_conversations AS conversation
        SET lead_status_id = v_status_id, updated_at = now()
        WHERE conversation.id = (
          SELECT candidate.id
          FROM public.email_conversations candidate
          WHERE candidate.organization_id = p_organization_id
            AND lower(btrim(candidate.ticket_id)) = lower(v_ticket)
          LIMIT 1
        );
      ELSIF left(v_prefix, 3) = 'WA-' THEN
        UPDATE public.whatsapp_conversations AS conversation
        SET lead_status_id = v_status_id, updated_at = now()
        WHERE conversation.id = (
          SELECT candidate.id
          FROM public.whatsapp_conversations candidate
          WHERE candidate.organization_id = p_organization_id
            AND lower(btrim(candidate.ticket_id)) = lower(v_ticket)
          LIMIT 1
        );
      END IF;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    lead.id,
    lead.ticket_id,
    lead.client,
    lead.title,
    lead.source,
    ls.name,
    lead.fu_priority,
    lead.assignee,
    lead.created_at
  FROM public.leads lead
  LEFT JOIN public.lead_statuses ls ON ls.id = lead.status_id
  WHERE lead.id = p_id
    AND lead.organization_id = p_organization_id;
END;
$$;


ALTER FUNCTION "public"."mcp_set_lead_status"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_task_step_completed"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_completed" boolean DEFAULT true) RETURNS TABLE("id" "uuid", "title" "text", "step_order" integer, "is_completed" boolean, "completed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_id uuid;
  v_title text;
  v_order integer;
  v_done boolean;
  v_completed_at timestamptz;
  v_plan_id uuid;
  v_is_concept boolean;
  v_has_substeps boolean;
  v_plan_ok boolean;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL OR p_completed IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- Step harus milik org ini
  SELECT step.social_media_plan_id, COALESCE(step.is_concept_step, false)
  INTO v_plan_id, v_is_concept
  FROM public.task_steps step
  JOIN public.daily_tasks task ON task.id = step.task_id
  WHERE step.id = p_id
    AND task.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  v_has_substeps := EXISTS (
    SELECT 1 FROM public.task_steps_to_steps sub WHERE sub.parent_step_id = p_id
  );

  IF v_has_substeps THEN
    -- Jangan centang step kalau masih ada sub-step yang belum selesai
    IF p_completed AND EXISTS (
      SELECT 1
      FROM public.task_steps_to_steps sub
      WHERE sub.parent_step_id = p_id
        AND COALESCE(sub.is_completed, false) = false
    ) THEN
      RAISE EXCEPTION 'substeps_incomplete' USING ERRCODE = '22023';
    END IF;
    -- Step dengan sub-step dibuka lagi lewat sub-step-nya, bukan manual
    IF NOT p_completed THEN
      RAISE EXCEPTION 'substeps_managed' USING ERRCODE = '22023';
    END IF;
  ELSIF p_completed AND v_plan_id IS NOT NULL THEN
    SELECT CASE
      WHEN v_is_concept THEN COALESCE(plan.approved, false)
      ELSE NULLIF(btrim(COALESCE(plan.google_drive_link, '')), '') IS NOT NULL
        OR COALESCE(plan.production_approved, false)
    END
    INTO v_plan_ok
    FROM public.social_media_plans plan
    WHERE plan.id = v_plan_id;
    IF NOT COALESCE(v_plan_ok, false) THEN
      RAISE EXCEPTION 'content_plan_locked' USING ERRCODE = '42501';
    END IF;
  END IF;

  UPDATE public.task_steps step
  SET
    is_completed = p_completed,
    completed_at = CASE
      WHEN p_completed THEN COALESCE(step.completed_at, now())
      ELSE NULL
    END,
    updated_at = now()
  WHERE step.id = p_id
  RETURNING step.id, step.title, step."order", step.is_completed, step.completed_at
  INTO v_id, v_title, v_order, v_done, v_completed_at;

  id := v_id;
  title := v_title;
  step_order := v_order;
  is_completed := v_done;
  completed_at := v_completed_at;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_set_task_step_completed"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_completed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_thinking_idea_paths"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid", "p_paths" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  IF p_idea_id IS NULL OR p_paths IS NULL OR jsonb_typeof(p_paths) <> 'array' OR jsonb_array_length(p_paths) > 60 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  UPDATE public.thinking_lab_ideas idea
     SET development_paths = p_paths,
         updated_at = now()
   WHERE idea.id = p_idea_id
     AND idea.organization_id = p_organization_id
     AND idea.status = 'locked'
     AND idea.validation->>'decision' = 'LOLOS';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_set_thinking_idea_paths"("p_user_id" "uuid", "p_organization_id" "uuid", "p_idea_id" "uuid", "p_paths" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_set_thinking_master_catalog"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid", "p_service_id" "uuid", "p_sub_service_ids" "uuid"[], "p_feature_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_subs uuid[] := COALESCE(p_sub_service_ids, '{}');
  v_features uuid[] := COALESCE(p_feature_ids, '{}');
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  IF p_service_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.services s
     WHERE s.id = p_service_id AND s.organization_id = p_organization_id AND COALESCE(s.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_subs) sid
     WHERE NOT EXISTS (SELECT 1 FROM public.sub_services ss WHERE ss.id = sid AND ss.service_id = p_service_id)
  ) OR EXISTS (
    SELECT 1 FROM unnest(v_features) fid
     WHERE NOT EXISTS (
       SELECT 1 FROM public.product_knowledge_features f
        WHERE f.id = fid AND f.organization_id = p_organization_id AND f.service_id = p_service_id
     )
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  UPDATE public.thinking_master_thoughts
     SET service_id = p_service_id,
         sub_service_ids = v_subs,
         feature_ids = v_features
   WHERE id = p_master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_set_thinking_master_catalog"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid", "p_service_id" "uuid", "p_sub_service_ids" "uuid"[], "p_feature_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_supersede_connections"("p_user_id" "uuid", "p_organization_id" "uuid", "p_keep_client_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_now timestamptz;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR NULLIF(btrim(COALESCE(p_keep_client_id, '')), '') IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_now := clock_timestamp();

  WITH newest AS (
    SELECT token.id
    FROM public.mcp_oauth_refresh_tokens token
    WHERE token.user_id = p_user_id
      AND token.organization_id = p_organization_id
      AND token.client_id = p_keep_client_id
      AND token.revoked_at IS NULL
      AND token.expires_at > v_now
    ORDER BY token.created_at DESC, token.id DESC
    LIMIT 1
  ),
  doomed AS (
    SELECT token.id, token.client_id
    FROM public.mcp_oauth_refresh_tokens token
    WHERE token.user_id = p_user_id
      AND token.organization_id = p_organization_id
      AND token.revoked_at IS NULL
      AND token.expires_at > v_now
      AND NOT EXISTS (SELECT 1 FROM newest WHERE newest.id = token.id)
  ),
  closed AS (
    UPDATE public.mcp_oauth_refresh_tokens token
    SET revoked_at = v_now
    FROM doomed
    WHERE token.id = doomed.id
    RETURNING doomed.client_id
  )
  INSERT INTO public.mcp_oauth_revocations (user_id, organization_id, client_id, revoked_at)
  SELECT p_user_id, p_organization_id, closed.client_id, v_now
  FROM closed
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.mcp_oauth_refresh_tokens live
    WHERE live.user_id = p_user_id
      AND live.organization_id = p_organization_id
      AND live.client_id = closed.client_id
      AND live.revoked_at IS NULL
      AND live.expires_at > v_now
  )
  ON CONFLICT (user_id, organization_id, client_id)
  DO UPDATE SET revoked_at = EXCLUDED.revoked_at;
END;
$$;


ALTER FUNCTION "public"."mcp_supersede_connections"("p_user_id" "uuid", "p_organization_id" "uuid", "p_keep_client_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_switch_organization"("p_user_id" "uuid", "p_client_id" "text", "p_organization_id" "uuid") RETURNS TABLE("connection_id" "uuid", "organization_id" "uuid", "employee_id" "uuid", "organization_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from uuid;
  v_connection uuid;
  v_employee uuid;
  v_name text;
  v_now timestamptz;
BEGIN
  IF p_user_id IS NULL
    OR p_organization_id IS NULL
    OR NULLIF(btrim(COALESCE(p_client_id, '')), '') IS NULL
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT session.connection_id, session.active_organization_id
  INTO v_connection, v_from
  FROM public.mcp_connector_sessions session
  WHERE session.user_id = p_user_id
    AND session.client_id = p_client_id
  FOR UPDATE;

  IF v_connection IS NULL THEN
    RAISE EXCEPTION 'session_missing' USING ERRCODE = 'P0002';
  END IF;

  SELECT employee.id
  INTO v_employee
  FROM public.employees employee
  WHERE employee.user_id = p_user_id
    AND employee.organization_id = p_organization_id
  LIMIT 1;

  SELECT org.company_name
  INTO v_name
  FROM public.organizations org
  WHERE org.id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'organization_lookup_failed' USING ERRCODE = 'P0002';
  END IF;

  v_now := clock_timestamp();

  UPDATE public.mcp_connector_sessions session
  SET active_organization_id = p_organization_id,
      updated_at = v_now
  WHERE session.user_id = p_user_id
    AND session.client_id = p_client_id;

  UPDATE public.mcp_oauth_refresh_tokens token
  SET organization_id = p_organization_id,
      employee_id = v_employee
  WHERE token.user_id = p_user_id
    AND token.client_id = p_client_id
    AND token.revoked_at IS NULL
    AND token.expires_at > v_now;

  IF v_from IS DISTINCT FROM p_organization_id THEN
    INSERT INTO public.mcp_org_switches (
      connection_id,
      user_id,
      client_id,
      from_organization_id,
      to_organization_id,
      created_at
    )
    VALUES (v_connection, p_user_id, p_client_id, v_from, p_organization_id, v_now);
  END IF;

  connection_id := v_connection;
  organization_id := p_organization_id;
  employee_id := v_employee;
  organization_name := COALESCE(v_name, '');
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_switch_organization"("p_user_id" "uuid", "p_client_id" "text", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_take_task_initiative"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_level" "text", "p_due_date" "text", "p_employee_id" "uuid") RETURNS TABLE("id" "uuid", "level" "text", "assignee_name" "text", "due_date" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_can_assign boolean;
  v_level text;
  v_target uuid;
  v_due timestamptz;
  v_assignment uuid;
  v_name text;
  v_open boolean;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_level := lower(btrim(COALESCE(p_level, '')));
  IF v_level NOT IN ('task', 'step', 'substep') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_due_date IS NULL OR btrim(p_due_date) = '' THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;
  IF btrim(p_due_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;
  BEGIN
    v_due := (btrim(p_due_date) || ' 17:00:00')::timestamp AT TIME ZONE 'Asia/Jakarta';
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END;
  IF to_char(v_due AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_due_date) THEN
    RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = p_user_id
      AND ur.organization_id = p_organization_id
      AND lower(ur.role) IN ('owner', 'admin', 'hr')
  ) INTO v_can_assign;

  v_target := COALESCE(p_employee_id, v_self);
  IF v_target IS DISTINCT FROM v_self AND NOT v_can_assign THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.employees emp
    WHERE emp.id = v_target AND emp.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_level = 'task' THEN
    SELECT lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
    INTO v_open
    FROM public.daily_tasks task
    WHERE task.id = p_id AND task.organization_id = p_organization_id;
    IF v_open IS NULL THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
    IF NOT v_open THEN
      RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
    END IF;

    UPDATE public.daily_tasks task
    SET due_date = v_due, updated_at = now()
    WHERE task.id = p_id AND task.organization_id = p_organization_id;

    DELETE FROM public.daily_tasks_assigned assigned
    WHERE assigned.daily_task_id = p_id
      AND assigned.organization_id = p_organization_id;

    INSERT INTO public.daily_tasks_assigned (
      organization_id, daily_task_id, employee_id, assigned_by
    )
    VALUES (p_organization_id, p_id, v_target, v_self)
    RETURNING daily_tasks_assigned.id INTO v_assignment;

    INSERT INTO public.task_steps_assigned_duedate (
      organization_id, daily_tasks_assigned_id, due_date
    )
    VALUES (p_organization_id, v_assignment, v_due);
  ELSIF v_level = 'step' THEN
    SELECT step.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
    INTO v_open
    FROM public.task_steps step
    JOIN public.daily_tasks task ON task.id = step.task_id
    WHERE step.id = p_id AND task.organization_id = p_organization_id;
    IF v_open IS NULL THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
    IF NOT v_open THEN
      RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
    END IF;

    DELETE FROM public.task_steps_assigned assigned
    WHERE assigned.task_step_id = p_id
      AND assigned.organization_id = p_organization_id;

    INSERT INTO public.task_steps_assigned (
      organization_id, task_step_id, employee_id, assigned_by
    )
    VALUES (p_organization_id, p_id, v_target, v_self)
    RETURNING task_steps_assigned.id INTO v_assignment;

    INSERT INTO public.task_steps_assigned_duedate (
      organization_id, task_steps_assigned_id, due_date
    )
    VALUES (p_organization_id, v_assignment, v_due);
  ELSE
    SELECT sub.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
    INTO v_open
    FROM public.task_steps_to_steps sub
    JOIN public.task_steps step ON step.id = sub.parent_step_id
    JOIN public.daily_tasks task ON task.id = step.task_id
    WHERE sub.id = p_id AND task.organization_id = p_organization_id;
    IF v_open IS NULL THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;
    IF NOT v_open THEN
      RAISE EXCEPTION 'not_open' USING ERRCODE = '22023';
    END IF;

    DELETE FROM public.task_steps_to_steps_assigned assigned
    WHERE assigned.task_steps_to_steps_id = p_id
      AND assigned.organization_id = p_organization_id;

    INSERT INTO public.task_steps_to_steps_assigned (
      organization_id, task_steps_to_steps_id, employee_id, assigned_by
    )
    VALUES (p_organization_id, p_id, v_target, v_self)
    RETURNING task_steps_to_steps_assigned.id INTO v_assignment;

    INSERT INTO public.task_steps_assigned_duedate (
      organization_id, task_steps_to_steps_assigned_id, due_date
    )
    VALUES (p_organization_id, v_assignment, v_due);
  END IF;

  SELECT COALESCE(NULLIF(btrim(emp.full_name), ''), NULLIF(btrim(prof.full_name), ''))
  INTO v_name
  FROM public.employees emp
  LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
  WHERE emp.id = v_target;

  id := p_id;
  level := v_level;
  assignee_name := v_name;
  due_date := v_due;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_take_task_initiative"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_level" "text", "p_due_date" "text", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_take_tool_slot"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS TABLE("allowed" boolean, "record_denial" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_window timestamptz;
  v_count integer;
  v_logged boolean;
  v_now timestamptz;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.mcp_tool_rate (user_id, organization_id, window_start, call_count, denial_logged)
  VALUES (p_user_id, p_organization_id, clock_timestamp(), 0, false)
  ON CONFLICT (user_id, organization_id) DO NOTHING;

  SELECT rate.window_start, rate.call_count, rate.denial_logged
  INTO v_window, v_count, v_logged
  FROM public.mcp_tool_rate rate
  WHERE rate.user_id = p_user_id
    AND rate.organization_id = p_organization_id
  FOR UPDATE;

  v_now := clock_timestamp();

  IF v_window <= v_now - interval '5 minutes' THEN
    UPDATE public.mcp_tool_rate rate
    SET window_start = v_now, call_count = 1, denial_logged = false
    WHERE rate.user_id = p_user_id
      AND rate.organization_id = p_organization_id;
    RETURN QUERY SELECT true, false;
    RETURN;
  END IF;

  IF v_count < 60 THEN
    UPDATE public.mcp_tool_rate rate
    SET call_count = v_count + 1
    WHERE rate.user_id = p_user_id
      AND rate.organization_id = p_organization_id;
    RETURN QUERY SELECT true, false;
    RETURN;
  END IF;

  IF NOT v_logged THEN
    UPDATE public.mcp_tool_rate rate
    SET denial_logged = true
    WHERE rate.user_id = p_user_id
      AND rate.organization_id = p_organization_id;
    RETURN QUERY SELECT false, true;
    RETURN;
  END IF;

  RETURN QUERY SELECT false, false;
END;
$$;


ALTER FUNCTION "public"."mcp_take_tool_slot"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_task_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") RETURNS TABLE("pending" bigint, "in_progress" bigint, "completed" bigint, "cancelled" bigint, "overdue" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_month text;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_month := NULLIF(btrim(COALESCE(p_month, '')), '');
  IF v_month IS NULL THEN
    v_month := to_char(now() AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM');
  ELSIF v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION 'invalid_month' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT
    count(*) FILTER (WHERE lower(task.status) = 'pending'),
    count(*) FILTER (WHERE lower(task.status) = 'in_progress'),
    count(*) FILTER (WHERE lower(task.status) = 'completed'),
    count(*) FILTER (WHERE lower(task.status) = 'cancelled'),
    count(*) FILTER (
      WHERE lower(task.status) NOT IN ('completed', 'cancelled')
        AND task.due_date IS NOT NULL
        AND (task.due_date AT TIME ZONE 'Asia/Jakarta')::date
          < (now() AT TIME ZONE 'Asia/Jakarta')::date
    )
  FROM public.daily_tasks task
  WHERE task.organization_id = p_organization_id
    AND to_char(
      COALESCE(task.plan_date, task.created_at) AT TIME ZONE 'Asia/Jakarta',
      'YYYY-MM'
    ) = v_month;
END;
$_$;


ALTER FUNCTION "public"."mcp_task_summary"("p_user_id" "uuid", "p_organization_id" "uuid", "p_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_task_workload"("p_user_id" "uuid", "p_organization_id" "uuid", "p_timeframe" "text") RETURNS TABLE("employee_id" "uuid", "full_name" "text", "active_count" bigint, "idle" boolean, "pending_days" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_timeframe text;
  v_today date;
  v_start date;
  v_end date;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_timeframe := lower(COALESCE(NULLIF(btrim(COALESCE(p_timeframe, '')), ''), 'week'));
  v_today := (now() AT TIME ZONE 'Asia/Jakarta')::date;
  IF v_timeframe = 'day' THEN
    v_start := v_today;
    v_end := v_today;
  ELSIF v_timeframe = 'week' THEN
    v_start := v_today - ((EXTRACT(DOW FROM v_today)::int + 6) % 7);
    v_end := v_start + 6;
  ELSIF v_timeframe = 'month' THEN
    v_start := date_trunc('month', v_today::timestamp)::date;
    v_end := (date_trunc('month', v_today::timestamp) + interval '1 month' - interval '1 day')::date;
  ELSE
    RAISE EXCEPTION 'invalid_timeframe' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH people AS (
    SELECT
      emp.id,
      COALESCE(
        NULLIF(btrim(emp.full_name), ''),
        NULLIF(btrim(prof.full_name), ''),
        'Unknown'
      ) AS full_name
    FROM public.employees emp
    LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
    LEFT JOIN public.profiles prof ON prof.user_id = emp.user_id
    WHERE emp.organization_id = p_organization_id
      AND COALESCE(emp.pending_removal, false) = false
      AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
      AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
        NOT IN ('inactive', 'terminated', 'pendingremoval')
  ),
  hits AS (
    SELECT assigned.employee_id, assigned.assigned_at
    FROM public.daily_tasks_assigned assigned
    JOIN public.daily_tasks task
      ON task.id = assigned.daily_task_id
     AND task.organization_id = p_organization_id
    WHERE assigned.organization_id = p_organization_id
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
      AND task.due_date IS NOT NULL
      AND (
        (task.due_date AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_start AND v_end
        OR (task.due_date AT TIME ZONE 'Asia/Jakarta')::date < v_today
      )

    UNION ALL

    SELECT assigned.employee_id, assigned.assigned_at
    FROM public.task_steps_assigned assigned
    JOIN public.task_steps step ON step.id = assigned.task_step_id
    JOIN public.daily_tasks task
      ON task.id = step.task_id
     AND task.organization_id = p_organization_id
    LEFT JOIN LATERAL (
      SELECT dated.due_date
      FROM public.task_steps_assigned_duedate dated
      WHERE dated.task_steps_assigned_id = assigned.id
      ORDER BY dated.created_at DESC
      LIMIT 1
    ) due ON true
    WHERE assigned.organization_id = p_organization_id
      AND step.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
      AND COALESCE(due.due_date, task.due_date) IS NOT NULL
      AND (
        (COALESCE(due.due_date, task.due_date) AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_start AND v_end
        OR (COALESCE(due.due_date, task.due_date) AT TIME ZONE 'Asia/Jakarta')::date < v_today
      )

    UNION ALL

    SELECT assigned.employee_id, assigned.assigned_at
    FROM public.task_steps_to_steps_assigned assigned
    JOIN public.task_steps_to_steps sub ON sub.id = assigned.task_steps_to_steps_id
    JOIN public.task_steps step ON step.id = sub.parent_step_id
    JOIN public.daily_tasks task
      ON task.id = step.task_id
     AND task.organization_id = p_organization_id
    LEFT JOIN LATERAL (
      SELECT dated.due_date
      FROM public.task_steps_assigned_duedate dated
      WHERE dated.task_steps_to_steps_assigned_id = assigned.id
      ORDER BY dated.created_at DESC
      LIMIT 1
    ) due ON true
    WHERE assigned.organization_id = p_organization_id
      AND sub.is_completed = false
      AND lower(COALESCE(task.status, '')) NOT IN ('completed', 'cancelled')
      AND COALESCE(due.due_date, task.due_date) IS NOT NULL
      AND (
        (COALESCE(due.due_date, task.due_date) AT TIME ZONE 'Asia/Jakarta')::date BETWEEN v_start AND v_end
        OR (COALESCE(due.due_date, task.due_date) AT TIME ZONE 'Asia/Jakarta')::date < v_today
      )
  )
  SELECT
    people.id,
    people.full_name,
    count(hits.employee_id),
    count(hits.employee_id) = 0,
    COALESCE(
      MAX(GREATEST(0, floor(EXTRACT(EPOCH FROM (now() - hits.assigned_at)) / 86400)))::integer,
      0
    )
  FROM people
  LEFT JOIN hits ON hits.employee_id = people.id
  GROUP BY people.id, people.full_name
  ORDER BY (count(hits.employee_id) = 0) DESC, people.full_name ASC, people.id ASC
  LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_task_workload"("p_user_id" "uuid", "p_organization_id" "uuid", "p_timeframe" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_angle_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_territory_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_t public.thinking_lab_territories%ROWTYPE;
  v_bt public.thinking_big_thoughts%ROWTYPE;
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_t FROM public.thinking_lab_territories WHERE id = p_territory_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_bt FROM public.thinking_big_thoughts WHERE id = v_t.big_thought_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = v_bt.master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object(
    'master', jsonb_build_object(
      'statement', COALESCE(v_master.statement, ''),
      'root_belief', COALESCE(v_master.root_belief, '')
    ),
    'big_thought', jsonb_build_object(
      'id', v_bt.id, 'statement', v_bt.statement, 'status', v_bt.status, 'semantic_fingerprint', v_bt.semantic_fingerprint
    ),
    'territory', jsonb_build_object(
      'id', v_t.id, 'code', v_t.code, 'statement', v_t.statement, 'status', v_t.status,
      'semantic_fingerprint', v_t.semantic_fingerprint, 'big_thought_id', v_t.big_thought_id, 'angle_set', v_t.angle_set
    ),
    'angles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'code', a.code, 'statement', a.statement, 'status', a.status, 'admission', a.admission,
        'sort_order', a.sort_order, 'subject', COALESCE(a.canonical_semantic->>'subject', '')
      ) ORDER BY a.sort_order, a.code)
      FROM public.thinking_lab_angles a
      WHERE a.territory_id = v_t.id AND a.organization_id = p_organization_id
    ), '[]'::jsonb),
    'master_codes', COALESCE((
      SELECT jsonb_agg(a.code)
      FROM public.thinking_lab_angles a
      JOIN public.thinking_lab_territories t ON t.id = a.territory_id
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
      WHERE b.master_thought_id = v_master.id AND a.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_angle_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_territory_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_apply"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid", "p_changes" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v jsonb;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  IF p_changes IS NULL OR jsonb_typeof(p_changes) <> 'object' THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  PERFORM 1 FROM public.thinking_master_thoughts
   WHERE id = p_master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab'
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;

  v := p_changes->'master';
  IF v IS NOT NULL AND jsonb_typeof(v) = 'object' THEN
    UPDATE public.thinking_master_thoughts SET
      statement = CASE WHEN v ? 'statement' THEN btrim(v->>'statement') ELSE statement END,
      root_belief = CASE WHEN v ? 'root_belief' THEN v->>'root_belief' ELSE root_belief END,
      prior_belief = CASE WHEN v ? 'prior_belief' THEN v->>'prior_belief' ELSE prior_belief END,
      audience = CASE WHEN v ? 'audience' THEN v->>'audience' ELSE audience END,
      canonical_semantic = CASE WHEN v ? 'canonical_semantic' THEN v->'canonical_semantic' ELSE canonical_semantic END,
      semantic_fingerprint = CASE WHEN v ? 'semantic_fingerprint' THEN v->>'semantic_fingerprint' ELSE semantic_fingerprint END,
      last_audit = CASE WHEN v ? 'last_audit' THEN v->'last_audit' ELSE last_audit END,
      updated_at = now()
    WHERE id = p_master_thought_id AND organization_id = p_organization_id;
  END IF;

  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(p_changes->'big_thoughts', '[]'::jsonb)) LOOP
    UPDATE public.thinking_big_thoughts b SET
      statement = CASE WHEN v ? 'statement' THEN btrim(v->>'statement') ELSE b.statement END,
      title = CASE WHEN v ? 'title' THEN v->>'title' ELSE b.title END,
      canonical_semantic = CASE WHEN v ? 'canonical_semantic' THEN v->'canonical_semantic' ELSE b.canonical_semantic END,
      semantic_fingerprint = CASE WHEN v ? 'semantic_fingerprint' THEN v->>'semantic_fingerprint' ELSE b.semantic_fingerprint END,
      territory_set = CASE WHEN v ? 'territory_set' THEN v->'territory_set' ELSE b.territory_set END,
      updated_at = now()
    WHERE b.id = (v->>'id')::uuid AND b.organization_id = p_organization_id AND b.master_thought_id = p_master_thought_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  END LOOP;

  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(p_changes->'territories', '[]'::jsonb)) LOOP
    UPDATE public.thinking_lab_territories t SET
      statement = CASE WHEN v ? 'statement' THEN btrim(v->>'statement') ELSE t.statement END,
      canonical_semantic = CASE WHEN v ? 'canonical_semantic' THEN v->'canonical_semantic' ELSE t.canonical_semantic END,
      semantic_fingerprint = CASE WHEN v ? 'semantic_fingerprint' THEN v->>'semantic_fingerprint' ELSE t.semantic_fingerprint END,
      angle_set = CASE WHEN v ? 'angle_set' THEN v->'angle_set' ELSE t.angle_set END,
      updated_at = now()
    FROM public.thinking_big_thoughts b
    WHERE t.id = (v->>'id')::uuid AND t.organization_id = p_organization_id
      AND b.id = t.big_thought_id AND b.master_thought_id = p_master_thought_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  END LOOP;

  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(p_changes->'angles', '[]'::jsonb)) LOOP
    UPDATE public.thinking_lab_angles a SET
      statement = CASE WHEN v ? 'statement' THEN btrim(v->>'statement') ELSE a.statement END,
      canonical_semantic = CASE WHEN v ? 'canonical_semantic' THEN v->'canonical_semantic' ELSE a.canonical_semantic END,
      semantic_fingerprint = CASE WHEN v ? 'semantic_fingerprint' THEN v->>'semantic_fingerprint' ELSE a.semantic_fingerprint END,
      parent_territory_fingerprint = CASE WHEN v ? 'parent_territory_fingerprint' THEN v->>'parent_territory_fingerprint' ELSE a.parent_territory_fingerprint END,
      idea_set = CASE WHEN v ? 'idea_set' THEN v->'idea_set' ELSE a.idea_set END,
      updated_at = now()
    FROM public.thinking_lab_territories t
    JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
    WHERE a.id = (v->>'id')::uuid AND a.organization_id = p_organization_id
      AND t.id = a.territory_id AND b.master_thought_id = p_master_thought_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  END LOOP;

  FOR v IN SELECT * FROM jsonb_array_elements(COALESCE(p_changes->'ideas', '[]'::jsonb)) LOOP
    UPDATE public.thinking_lab_ideas i SET
      statement = CASE WHEN v ? 'statement' THEN btrim(v->>'statement') ELSE i.statement END,
      canonical_semantic = CASE WHEN v ? 'canonical_semantic' THEN v->'canonical_semantic' ELSE i.canonical_semantic END,
      semantic_fingerprint = CASE WHEN v ? 'semantic_fingerprint' THEN v->>'semantic_fingerprint' ELSE i.semantic_fingerprint END,
      parent_angle_fingerprint = CASE WHEN v ? 'parent_angle_fingerprint' THEN v->>'parent_angle_fingerprint' ELSE i.parent_angle_fingerprint END,
      validation = CASE WHEN v ? 'validation' THEN v->'validation' ELSE i.validation END,
      updated_at = now()
    FROM public.thinking_lab_angles a
    JOIN public.thinking_lab_territories t ON t.id = a.territory_id
    JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
    WHERE i.id = (v->>'id')::uuid AND i.organization_id = p_organization_id
      AND a.id = i.angle_id AND b.master_thought_id = p_master_thought_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_apply"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid", "p_changes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_audit_item"("p_set" "jsonb", "p_code" "text") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT jsonb_build_object(
    'verdict', item->>'verdict',
    'reason', left(COALESCE(item->'gateFailure'->>'reason', ''), 400)
  )
  FROM jsonb_array_elements(COALESCE(p_set->'audit'->'items', '[]'::jsonb)) item
  WHERE upper(item->>'code') = upper(p_code)
  LIMIT 1;
$$;


ALTER FUNCTION "public"."mcp_thinking_audit_item"("p_set" "jsonb", "p_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_big_thought_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = p_master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object(
    'statement', COALESCE(v_master.statement, ''),
    'root_belief', COALESCE(v_master.root_belief, ''),
    'subject', COALESCE(v_master.canonical_semantic->>'subject', ''),
    'confirmed', v_master.confirmation_source IS NOT NULL,
    'locked', COALESCE(v_master.mt_status, '') = 'locked',
    'last_audit', v_master.last_audit,
    'big_thoughts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', b.id, 'code', b.code, 'label', b.title, 'statement', b.statement,
        'status', b.status, 'sort_order', b.sort_order,
        'canonical_semantic', b.canonical_semantic, 'semantic_fingerprint', b.semantic_fingerprint
      ) ORDER BY b.sort_order, b.code)
      FROM public.thinking_big_thoughts b
      WHERE b.master_thought_id = v_master.id AND b.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_big_thought_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_catalog_options"("p_user_id" "uuid", "p_organization_id" "uuid", "p_service_id" "uuid") RETURNS TABLE("kind" "text", "id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  RETURN QUERY
  SELECT 'sub_category'::text, ss.id, btrim(ss.name)
    FROM public.sub_services ss
    JOIN public.services s ON s.id = ss.service_id
   WHERE ss.service_id = p_service_id
     AND s.organization_id = p_organization_id
     AND COALESCE(s.is_active, true) = true
  UNION ALL
  SELECT 'feature'::text, f.id, btrim(f.feature_name)
    FROM public.product_knowledge_features f
   WHERE f.organization_id = p_organization_id
     AND f.service_id = p_service_id
  ORDER BY 1, 3;
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_catalog_options"("p_user_id" "uuid", "p_organization_id" "uuid", "p_service_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_catalogs"("p_user_id" "uuid", "p_organization_id" "uuid", "p_query" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_query text := btrim(COALESCE(p_query, ''));
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  RETURN QUERY
  SELECT s.id, s.name
    FROM public.services s
   WHERE s.organization_id = p_organization_id
     AND COALESCE(s.is_active, true) = true
     AND (
       v_query = ''
       OR s.id::text = lower(v_query)
       OR lower(btrim(s.name)) = lower(v_query)
       OR (
         NOT EXISTS (
           SELECT 1 FROM public.services x
            WHERE x.organization_id = p_organization_id AND COALESCE(x.is_active, true) = true
              AND (x.id::text = lower(v_query) OR lower(btrim(x.name)) = lower(v_query))
         )
         AND s.name ILIKE '%' || replace(replace(v_query, '%', ''), '_', '') || '%'
       )
     )
   ORDER BY s.name
   LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_catalogs"("p_user_id" "uuid", "p_organization_id" "uuid", "p_query" "text") OWNER TO "postgres";


