CREATE OR REPLACE FUNCTION "public"."mcp_thinking_idea_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_angle_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_a public.thinking_lab_angles%ROWTYPE;
  v_t public.thinking_lab_territories%ROWTYPE;
  v_bt public.thinking_big_thoughts%ROWTYPE;
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_a FROM public.thinking_lab_angles WHERE id = p_angle_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_t FROM public.thinking_lab_territories WHERE id = v_a.territory_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_bt FROM public.thinking_big_thoughts WHERE id = v_t.big_thought_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = v_bt.master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object(
    'master', jsonb_build_object(
      'statement', COALESCE(v_master.statement, ''),
      'root_belief', COALESCE(v_master.root_belief, ''),
      'audience', COALESCE(v_master.audience, ''),
      'prior_belief', COALESCE(v_master.prior_belief, ''),
      'subject', COALESCE(v_master.canonical_semantic->>'subject', '')
    ),
    'big_thought', jsonb_build_object(
      'id', v_bt.id, 'statement', v_bt.statement, 'status', v_bt.status, 'semantic_fingerprint', v_bt.semantic_fingerprint
    ),
    'territory', jsonb_build_object(
      'id', v_t.id, 'statement', v_t.statement, 'status', v_t.status,
      'semantic_fingerprint', v_t.semantic_fingerprint, 'big_thought_id', v_t.big_thought_id
    ),
    'angle', jsonb_build_object(
      'id', v_a.id, 'code', v_a.code, 'statement', v_a.statement, 'status', v_a.status,
      'semantic_fingerprint', v_a.semantic_fingerprint, 'territory_id', v_a.territory_id, 'idea_set', v_a.idea_set
    ),
    'ideas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'code', i.code, 'statement', i.statement, 'angle_id', i.angle_id,
        'admission', i.admission, 'status', i.status, 'sort_order', i.sort_order, 'validation', i.validation
      ) ORDER BY i.created_at DESC)
      FROM public.thinking_lab_ideas i
      JOIN public.thinking_lab_angles a ON a.id = i.angle_id
      JOIN public.thinking_lab_territories t ON t.id = a.territory_id
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
      WHERE b.master_thought_id = v_master.id AND i.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_idea_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_angle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_master_catalog"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = p_master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object(
    'category', (SELECT btrim(s.name) FROM public.services s WHERE s.id = v_master.service_id),
    'sub_categories', COALESCE((
      SELECT jsonb_agg(btrim(ss.name) ORDER BY ss.name)
        FROM public.sub_services ss WHERE ss.id = ANY (v_master.sub_service_ids)
    ), '[]'::jsonb),
    'features', COALESCE((
      SELECT jsonb_agg(btrim(f.feature_name) ORDER BY f.feature_name)
        FROM public.product_knowledge_features f WHERE f.id = ANY (v_master.feature_ids)
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_master_catalog"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_member_guard"("p_user_id" "uuid", "p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_member_guard"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_thinking_subtree"("p_user_id" "uuid", "p_organization_id" "uuid", "p_master_thought_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_master jsonb;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT jsonb_build_object(
    'id', m.id, 'statement', m.statement, 'root_belief', m.root_belief, 'prior_belief', m.prior_belief,
    'audience', m.audience, 'status', m.status, 'mt_status', m.mt_status,
    'semantic_fingerprint', m.semantic_fingerprint, 'last_audit', m.last_audit, 'canonical_semantic', m.canonical_semantic
  ) INTO v_master
  FROM public.thinking_master_thoughts m
  WHERE m.id = p_master_thought_id AND m.organization_id = p_organization_id AND m.workspace = 'thinking_lab';
  IF v_master IS NULL THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  RETURN jsonb_build_object(
    'master', v_master,
    'big_thoughts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', b.id, 'code', b.code, 'title', b.title, 'statement', b.statement, 'status', b.status,
        'semantic_fingerprint', b.semantic_fingerprint, 'territory_set', b.territory_set, 'canonical_semantic', b.canonical_semantic
      ) ORDER BY b.sort_order)
      FROM public.thinking_big_thoughts b
      WHERE b.master_thought_id = p_master_thought_id AND b.organization_id = p_organization_id), '[]'::jsonb),
    'territories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', t.id, 'code', t.code, 'big_thought_id', t.big_thought_id, 'statement', t.statement, 'status', t.status,
        'admission', t.admission, 'semantic_fingerprint', t.semantic_fingerprint, 'angle_set', t.angle_set,
        'canonical_semantic', t.canonical_semantic
      ) ORDER BY t.sort_order)
      FROM public.thinking_lab_territories t
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id AND b.organization_id = t.organization_id
      WHERE b.master_thought_id = p_master_thought_id AND t.organization_id = p_organization_id), '[]'::jsonb),
    'angles', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', a.id, 'code', a.code, 'territory_id', a.territory_id, 'statement', a.statement, 'status', a.status,
        'admission', a.admission, 'semantic_fingerprint', a.semantic_fingerprint,
        'parent_territory_fingerprint', a.parent_territory_fingerprint, 'idea_set', a.idea_set,
        'canonical_semantic', a.canonical_semantic
      ) ORDER BY a.sort_order)
      FROM public.thinking_lab_angles a
      JOIN public.thinking_lab_territories t ON t.id = a.territory_id AND t.organization_id = a.organization_id
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id AND b.organization_id = a.organization_id
      WHERE b.master_thought_id = p_master_thought_id AND a.organization_id = p_organization_id), '[]'::jsonb),
    'ideas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'code', i.code, 'angle_id', i.angle_id, 'statement', i.statement, 'status', i.status,
        'admission', i.admission, 'semantic_fingerprint', i.semantic_fingerprint,
        'parent_angle_fingerprint', i.parent_angle_fingerprint, 'validation', i.validation,
        'canonical_semantic', i.canonical_semantic
      ) ORDER BY i.sort_order)
      FROM public.thinking_lab_ideas i
      JOIN public.thinking_lab_angles a ON a.id = i.angle_id AND a.organization_id = i.organization_id
      JOIN public.thinking_lab_territories t ON t.id = a.territory_id AND t.organization_id = i.organization_id
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id AND b.organization_id = i.organization_id
      WHERE b.master_thought_id = p_master_thought_id AND i.organization_id = p_organization_id), '[]'::jsonb)
  );
END;
$$;


