CREATE OR REPLACE FUNCTION "public"."mcp_thinking_territory_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_big_thought_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bt public.thinking_big_thoughts%ROWTYPE;
  v_master public.thinking_master_thoughts%ROWTYPE;
BEGIN
  PERFORM public.mcp_thinking_member_guard(p_user_id, p_organization_id);
  SELECT * INTO v_bt FROM public.thinking_big_thoughts
   WHERE id = p_big_thought_id AND organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  SELECT * INTO v_master FROM public.thinking_master_thoughts
   WHERE id = v_bt.master_thought_id AND organization_id = p_organization_id AND workspace = 'thinking_lab';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  RETURN jsonb_build_object(
    'master', jsonb_build_object(
      'statement', COALESCE(v_master.statement, ''),
      'root_belief', COALESCE(v_master.root_belief, ''),
      'audience', COALESCE(v_master.audience, ''),
      'confirmed', v_master.confirmation_source IS NOT NULL
    ),
    'big_thought', jsonb_build_object(
      'id', v_bt.id, 'code', v_bt.code, 'statement', v_bt.statement, 'status', v_bt.status,
      'semantic_fingerprint', v_bt.semantic_fingerprint, 'canonical_semantic', v_bt.canonical_semantic,
      'territory_set', v_bt.territory_set
    ),
    'territories', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', t.id, 'code', t.code, 'statement', t.statement, 'status', t.status,
        'admission', t.admission, 'sort_order', t.sort_order
      ) ORDER BY t.sort_order, t.code)
      FROM public.thinking_lab_territories t
      WHERE t.big_thought_id = v_bt.id AND t.organization_id = p_organization_id
    ), '[]'::jsonb),
    'master_codes', COALESCE((
      SELECT jsonb_agg(t.code)
      FROM public.thinking_lab_territories t
      JOIN public.thinking_big_thoughts b ON b.id = t.big_thought_id
      WHERE b.master_thought_id = v_master.id AND t.organization_id = p_organization_id
    ), '[]'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_thinking_territory_context"("p_user_id" "uuid", "p_organization_id" "uuid", "p_big_thought_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_content_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_post_date" "text", "p_brief" "text", "p_base_version" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "post_date" timestamp with time zone, "approved" boolean, "production_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_title text;
  v_brief text;
  v_day date;
  v_post_date timestamptz;
  v_pic uuid;
  v_existing_pic uuid;
  v_current_brief text;
  v_latest integer;
  v_brief_changed boolean := false;
  v_plan public.social_media_plans%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF p_title IS NOT NULL AND (v_title IS NULL OR char_length(v_title) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_brief := NULLIF(btrim(COALESCE(p_brief, '')), '');
  IF p_brief IS NOT NULL AND (v_brief IS NULL OR char_length(v_brief) > 4000) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_post_date IS NULL OR NULLIF(btrim(p_post_date), '') IS NULL THEN
    v_post_date := NULL;
  ELSE
    IF btrim(p_post_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_post_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_post_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    v_post_date := v_day::timestamp AT TIME ZONE 'Asia/Jakarta';
  END IF;

  IF v_title IS NULL AND v_brief IS NULL AND v_post_date IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_brief IS NOT NULL THEN
    SELECT plan.pic_id, plan.brief
      INTO v_existing_pic, v_current_brief
    FROM public.social_media_plans plan
    WHERE plan.id = p_id
      AND plan.organization_id = p_organization_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
    END IF;

    IF v_brief IS DISTINCT FROM NULLIF(btrim(COALESCE(v_current_brief, '')), '') THEN
      SELECT COALESCE(MAX(versions.version_no), 0)
        INTO v_latest
      FROM public.content_brief_versions AS versions
      WHERE versions.social_media_plan_id = p_id;

      IF p_base_version IS NULL THEN
        RAISE EXCEPTION 'brief_version_required'
          USING ERRCODE = 'P0001', DETAIL = v_latest::text;
      END IF;

      IF p_base_version IS DISTINCT FROM v_latest THEN
        RAISE EXCEPTION 'brief_version_conflict'
          USING ERRCODE = 'P0001', DETAIL = v_latest::text;
      END IF;

      IF NOT public.can_edit_content_brief_field(p_id, 'brief_storyboard', p_user_id) THEN
        RAISE EXCEPTION 'brief_field_forbidden'
          USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
      END IF;

      IF public.content_brief_revision_locked(p_id) THEN
        RAISE EXCEPTION 'brief_edit_locked'
          USING ERRCODE = 'P0001';
      END IF;

      PERFORM public.content_brief_snapshot(p_id, p_user_id, 'mcp');
      v_brief_changed := true;
    END IF;

    IF v_existing_pic IS NULL THEN
      SELECT emp.id
        INTO v_pic
      FROM public.employees emp
      LEFT JOIN public.employee_statuses es ON es.id = emp.employee_status_id
      WHERE emp.organization_id = p_organization_id
        AND emp.user_id = p_user_id
        AND COALESCE(emp.pending_removal, false) = false
        AND lower(COALESCE(emp.status, 'active')) NOT IN ('inactive', 'terminated', 'resigned')
        AND lower(regexp_replace(COALESCE(es.name, ''), '[\s_]+', '', 'g'))
          NOT IN ('inactive', 'terminated', 'pendingremoval')
      ORDER BY emp.id ASC
      LIMIT 1;

      IF v_pic IS NULL THEN
        RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
      END IF;

      UPDATE public.social_media_plans plan
      SET pic_id = v_pic
      WHERE plan.id = p_id
        AND plan.organization_id = p_organization_id
        AND plan.pic_id IS NULL;
    END IF;
  END IF;

  PERFORM set_config('mcp.plan_brief_user', p_user_id::text, true);

  UPDATE public.social_media_plans AS plan
  SET
    title = COALESCE(v_title, plan.title),
    brief = COALESCE(v_brief, plan.brief),
    post_date = COALESCE(v_post_date, plan.post_date),
    updated_at = now()
  WHERE plan.id = p_id
    AND plan.organization_id = p_organization_id
  RETURNING * INTO v_plan;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_brief_changed THEN
    PERFORM public.content_brief_demote_approval(p_id);
    SELECT * INTO v_plan
    FROM public.social_media_plans AS plan
    WHERE plan.id = p_id;
  END IF;

  id := v_plan.id;
  title := v_plan.title;
  status := v_plan.status;
  post_date := v_plan.post_date;
  approved := v_plan.approved;
  production_status := v_plan.production_status;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_update_content_plan"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_post_date" "text", "p_brief" "text", "p_base_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_expense"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_expense_name" "text", "p_amount" numeric, "p_create_date" "text", "p_expense_type" "text", "p_category" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "expense_name" "text", "amount" double precision, "expense_type" "text", "category" "text", "create_date" "date", "status" "text", "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_name text;
  v_day date;
  v_type_input text;
  v_category_input text;
  v_type_id uuid;
  v_type_name text;
  v_category_id uuid;
  v_category_name text;
  v_description text;
  v_current public.expenses%ROWTYPE;
  v_row public.expenses%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_name := NULL;
  IF p_expense_name IS NOT NULL THEN
    v_name := NULLIF(btrim(p_expense_name), '');
    IF v_name IS NULL OR char_length(v_name) > 200 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_amount IS NOT NULL AND (p_amount <= 0 OR p_amount > 9999999999999.99 OR scale(p_amount) > 2) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_day := NULL;
  IF p_create_date IS NOT NULL THEN
    IF btrim(p_create_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_create_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_create_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_description := NULL;
  IF p_description IS NOT NULL THEN
    v_description := NULLIF(btrim(p_description), '');
    IF v_description IS NULL OR char_length(v_description) > 2000 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_expense_type IS NOT NULL AND (
    NULLIF(btrim(p_expense_type), '') IS NULL
    OR char_length(btrim(p_expense_type)) > 200
    OR lower(btrim(p_expense_type)) = 'internal bank transfer'
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_category IS NOT NULL AND (
    NULLIF(btrim(p_category), '') IS NULL
    OR char_length(btrim(p_category)) > 200
  ) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_name IS NULL AND p_amount IS NULL AND v_day IS NULL
    AND p_expense_type IS NULL AND p_category IS NULL AND v_description IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT expense.*
  INTO v_current
  FROM public.expenses expense
  WHERE expense.id = p_id
    AND expense.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_current.status IS DISTINCT FROM 'active'
    OR v_current.bank_account_id IS NOT NULL
    OR v_current.gateway_wallet_provider IS NOT NULL
    OR v_current.withdrawal_from_balance IS NOT NULL
    OR v_current.payroll_run_id IS NOT NULL
    OR v_current.is_recurring
    OR v_current.recurring_settlement_for_expense_id IS NOT NULL
    OR v_current.purchase_request_id IS NOT NULL
    OR lower(btrim(v_current.expense_type)) = 'internal bank transfer' THEN
    RAISE EXCEPTION 'not_editable' USING ERRCODE = '22023';
  END IF;

  v_type_id := NULL;
  v_type_name := NULL;
  v_category_id := NULL;
  v_category_name := NULL;
  IF p_expense_type IS NOT NULL OR p_category IS NOT NULL THEN
    v_type_input := COALESCE(NULLIF(btrim(COALESCE(p_expense_type, '')), ''), v_current.expense_type);
    v_category_input := COALESCE(NULLIF(btrim(COALESCE(p_category, '')), ''), v_current.category);
    IF lower(btrim(v_type_input)) = 'internal bank transfer' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;

    SELECT et.id, et.name
    INTO v_type_id, v_type_name
    FROM public.expense_types et
    WHERE et.is_active = true
      AND lower(btrim(et.name)) = lower(v_type_input)
      AND (et.organization_id = p_organization_id OR et.organization_id IS NULL)
    ORDER BY (et.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, et.created_at ASC
    LIMIT 1;
    IF v_type_id IS NULL THEN
      RAISE EXCEPTION 'invalid_master' USING ERRCODE = '22023';
    END IF;

    SELECT ec.id, ec.name
    INTO v_category_id, v_category_name
    FROM public.expense_categories ec
    WHERE ec.is_active = true
      AND ec.expense_type_id = v_type_id
      AND lower(btrim(ec.name)) = lower(v_category_input)
      AND (ec.organization_id = p_organization_id OR ec.organization_id IS NULL)
    ORDER BY (ec.organization_id IS NOT DISTINCT FROM p_organization_id) DESC, ec.created_at ASC
    LIMIT 1;
    IF v_category_id IS NULL THEN
      RAISE EXCEPTION 'invalid_master' USING ERRCODE = '22023';
    END IF;
  END IF;

  UPDATE public.expenses AS expense
  SET
    expense_name = COALESCE(v_name, expense.expense_name),
    amount = COALESCE(p_amount, expense.amount),
    create_date = COALESCE(v_day, expense.create_date),
    expense_type = COALESCE(v_type_name, expense.expense_type),
    expense_type_id = CASE WHEN v_type_id IS NULL THEN expense.expense_type_id ELSE v_type_id END,
    category = COALESCE(v_category_name, expense.category),
    expense_category_id = CASE WHEN v_category_id IS NULL THEN expense.expense_category_id ELSE v_category_id END,
    description = COALESCE(v_description, expense.description),
    updated_at = now()
  WHERE expense.id = p_id
    AND expense.organization_id = p_organization_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  id := v_row.id;
  expense_name := v_row.expense_name;
  amount := v_row.amount::double precision;
  expense_type := v_row.expense_type;
  category := v_row.category;
  create_date := v_row.create_date;
  status := v_row.status;
  description := v_row.description;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_update_expense"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_expense_name" "text", "p_amount" numeric, "p_create_date" "text", "p_expense_type" "text", "p_category" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_income_transaction"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_transaction_date" "text", "p_amount" numeric, "p_customer_name" "text", "p_payment_method" "text", "p_description" "text") RETURNS TABLE("id" "uuid", "transaction_date" "date", "amount" double precision, "customer_name" "text", "payment_method" "text", "status" "text", "description" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_day date;
  v_customer text;
  v_method text;
  v_description text;
  v_current public.income_transactions%ROWTYPE;
  v_row public.income_transactions%ROWTYPE;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_day := NULL;
  IF p_transaction_date IS NOT NULL THEN
    IF btrim(p_transaction_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_day := btrim(p_transaction_date)::date;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END;
    IF to_char(v_day, 'YYYY-MM-DD') <> btrim(p_transaction_date) THEN
      RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_amount IS NOT NULL AND (p_amount <= 0 OR p_amount > 9999999999999.99 OR scale(p_amount) > 2) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_customer := NULL;
  IF p_customer_name IS NOT NULL THEN
    v_customer := NULLIF(btrim(p_customer_name), '');
    IF v_customer IS NULL OR char_length(v_customer) > 200 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_method := NULL;
  IF p_payment_method IS NOT NULL THEN
    v_method := NULLIF(lower(btrim(p_payment_method)), '');
    IF v_method IS NULL
      OR v_method NOT IN ('cash', 'credit_card', 'debit_card', 'check', 'digital_wallet', 'other') THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  v_description := NULL;
  IF p_description IS NOT NULL THEN
    v_description := NULLIF(btrim(p_description), '');
    IF v_description IS NULL OR char_length(v_description) > 2000 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF v_day IS NULL AND p_amount IS NULL AND v_customer IS NULL AND v_method IS NULL AND v_description IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  SELECT tx.*
  INTO v_current
  FROM public.income_transactions tx
  WHERE tx.id = p_id
    AND tx.organization_id = p_organization_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_current.status IS DISTINCT FROM 'pending'
    OR v_current.bank_account_id IS NOT NULL
    OR v_current.deposit_confirmed_at IS NOT NULL
    OR EXISTS (
      SELECT 1
      FROM public.income_allocations ia
      WHERE ia.income_transaction_id = v_current.id
    ) THEN
    RAISE EXCEPTION 'not_editable' USING ERRCODE = '22023';
  END IF;

  UPDATE public.income_transactions AS tx
  SET
    transaction_date = COALESCE(v_day, tx.transaction_date),
    amount = COALESCE(p_amount, tx.amount),
    customer_name = COALESCE(v_customer, tx.customer_name),
    payment_method = COALESCE(v_method, tx.payment_method),
    description = COALESCE(v_description, tx.description),
    updated_at = now()
  WHERE tx.id = p_id
    AND tx.organization_id = p_organization_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  id := v_row.id;
  transaction_date := v_row.transaction_date;
  amount := v_row.amount::double precision;
  customer_name := v_row.customer_name;
  payment_method := v_row.payment_method;
  status := v_row.status;
  description := v_row.description;
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_update_income_transaction"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_transaction_date" "text", "p_amount" numeric, "p_customer_name" "text", "p_payment_method" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_lead"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_client" "text", "p_title" "text", "p_category" "text", "p_source" "text", "p_fu_priority" "text") RETURNS TABLE("id" "uuid", "ticket_id" "text", "client" "text", "title" "text", "source" "text", "status" "text", "fu_priority" "text", "assignee" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_client text;
  v_title text;
  v_category text;
  v_source text;
  v_priority text;
  v_saved_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_client := NULLIF(btrim(COALESCE(p_client, '')), '');
  IF p_client IS NOT NULL AND (v_client IS NULL OR char_length(v_client) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF p_title IS NOT NULL AND (v_title IS NULL OR char_length(v_title) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_category := NULLIF(btrim(COALESCE(p_category, '')), '');
  IF p_category IS NOT NULL AND (v_category IS NULL OR char_length(v_category) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_source := NULLIF(btrim(COALESCE(p_source, '')), '');
  IF p_source IS NOT NULL AND (v_source IS NULL OR char_length(v_source) > 80) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_priority := NULLIF(btrim(COALESCE(p_fu_priority, '')), '');
  IF v_priority IS NOT NULL AND v_priority NOT IN ('High', 'Medium', 'Low', 'Please Follow Up') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_client IS NULL AND v_title IS NULL AND v_category IS NULL AND v_source IS NULL AND v_priority IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  UPDATE public.leads AS lead
  SET
    client = COALESCE(v_client, lead.client),
    title = COALESCE(v_title, lead.title),
    category = COALESCE(v_category, lead.category),
    source = COALESCE(v_source, lead.source),
    fu_priority = COALESCE(v_priority, lead.fu_priority),
    updated_at = now()
  WHERE lead.id = p_id
    AND lead.organization_id = p_organization_id
  RETURNING lead.id INTO v_saved_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  RETURN QUERY
  SELECT
    lead.id,
    lead.ticket_id,
    lead.client,
    lead.title,
    lead.source,
    ls.name,
    lead.fu_priority,
    lead.assignee,
    lead.created_at
  FROM public.leads lead
  LEFT JOIN public.lead_statuses ls ON ls.id = lead.status_id
  WHERE lead.id = v_saved_id;
END;
$$;


ALTER FUNCTION "public"."mcp_update_lead"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_client" "text", "p_title" "text", "p_category" "text", "p_source" "text", "p_fu_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_level" "text", "p_id" "uuid", "p_title" "text", "p_status" "text") RETURNS TABLE("id" "uuid", "level" "text", "title" "text", "status" "text", "progress_percentage" double precision, "cycle_id" "uuid", "owner_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_level text;
  v_title text;
  v_status text;
  v_saved_id uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  v_level := lower(btrim(COALESCE(p_level, '')));
  IF v_level NOT IN ('company', 'department', 'individual') THEN
    RAISE EXCEPTION 'invalid_level' USING ERRCODE = '22023';
  END IF;

  v_title := NULLIF(btrim(COALESCE(p_title, '')), '');
  IF p_title IS NOT NULL AND (v_title IS NULL OR char_length(v_title) > 200) THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_status := NULLIF(btrim(COALESCE(p_status, '')), '');
  IF v_status IS NOT NULL AND v_status NOT IN ('draft', 'active', 'completed', 'cancelled') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_title IS NULL AND v_status IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF v_level = 'company' THEN
    UPDATE public.company_objectives AS objective
    SET
      title = COALESCE(v_title, objective.title),
      status = COALESCE(v_status, objective.status),
      updated_at = now()
    WHERE objective.id = p_id
      AND objective.organization_id = p_organization_id
    RETURNING objective.id INTO v_saved_id;
  ELSIF v_level = 'department' THEN
    UPDATE public.department_objectives AS objective
    SET
      title = COALESCE(v_title, objective.title),
      status = COALESCE(v_status, objective.status),
      updated_at = now()
    WHERE objective.id = p_id
      AND objective.organization_id = p_organization_id
    RETURNING objective.id INTO v_saved_id;
  ELSE
    UPDATE public.individual_objectives AS objective
    SET
      title = COALESCE(v_title, objective.title),
      status = COALESCE(v_status, objective.status),
      updated_at = now()
    WHERE objective.id = p_id
      AND objective.organization_id = p_organization_id
    RETURNING objective.id INTO v_saved_id;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_level = 'company' THEN
    RETURN QUERY
    SELECT
      objective.id,
      'company'::text,
      objective.title,
      objective.status,
      objective.progress_percentage::double precision,
      objective.cycle_id,
      NULL::text
    FROM public.company_objectives objective
    WHERE objective.id = v_saved_id;
  ELSIF v_level = 'department' THEN
    RETURN QUERY
    SELECT
      objective.id,
      'department'::text,
      objective.title,
      objective.status,
      objective.progress_percentage::double precision,
      objective.cycle_id,
      dep.name
    FROM public.department_objectives objective
    LEFT JOIN public.departments dep ON dep.id = objective.department_id
    WHERE objective.id = v_saved_id;
  ELSE
    RETURN QUERY
    SELECT
      objective.id,
      'individual'::text,
      objective.title,
      objective.status,
      objective.progress_percentage::double precision,
      objective.cycle_id,
      emp.full_name
    FROM public.individual_objectives objective
    LEFT JOIN public.employees emp ON emp.id = objective.employee_id
    WHERE objective.id = v_saved_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."mcp_update_objective"("p_user_id" "uuid", "p_organization_id" "uuid", "p_level" "text", "p_id" "uuid", "p_title" "text", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_priority" "text", "p_due_date" "text", "p_plan_month" "text") RETURNS TABLE("id" "uuid", "title" "text", "status" "text", "priority" "text", "due_date" timestamp with time zone, "plan_month" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_title text;
  v_priority text;
  v_due timestamptz;
  v_has_due boolean := false;
  v_has_plan boolean := false;
  v_plan_month text;
  v_plan timestamptz;
  v_row public.daily_tasks%ROWTYPE;
  v_assignment uuid;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;
  IF p_title IS NULL AND p_priority IS NULL AND p_due_date IS NULL AND p_plan_month IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  IF p_title IS NOT NULL THEN
    v_title := btrim(p_title);
    IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_priority IS NOT NULL THEN
    v_priority := btrim(p_priority);
    IF v_priority NOT IN ('low', 'medium', 'high', 'urgent', 'needs_to_be_presented') THEN
      RAISE EXCEPTION 'invalid_priority' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF p_due_date IS NOT NULL THEN
    v_has_due := true;
    IF btrim(p_due_date) = '' THEN
      v_due := NULL;
    ELSE
      IF btrim(p_due_date) !~ '^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$' THEN
        RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
      END IF;
      BEGIN
        v_due := (btrim(p_due_date) || ' 17:00:00')::timestamp AT TIME ZONE 'Asia/Jakarta';
      EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
      END;
      IF to_char(v_due AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM-DD') IS DISTINCT FROM btrim(p_due_date) THEN
        RAISE EXCEPTION 'invalid_date' USING ERRCODE = '22023';
      END IF;
    END IF;
  END IF;

  IF p_plan_month IS NOT NULL THEN
    v_has_plan := true;
    v_plan_month := btrim(p_plan_month);
    IF v_plan_month = '' OR v_plan_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_plan := (v_plan_month || '-01 00:00:00')::timestamp AT TIME ZONE 'UTC';
  END IF;

  UPDATE public.daily_tasks task
  SET
    title = COALESCE(v_title, task.title),
    priority = COALESCE(v_priority, task.priority),
    due_date = CASE WHEN v_has_due THEN v_due ELSE task.due_date END,
    plan_date = CASE WHEN v_has_plan THEN v_plan ELSE task.plan_date END,
    updated_at = now()
  WHERE task.id = p_id
    AND task.organization_id = p_organization_id
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF v_has_due AND v_due IS NOT NULL THEN
    SELECT assigned.id INTO v_assignment
    FROM public.daily_tasks_assigned assigned
    WHERE assigned.daily_task_id = p_id
      AND assigned.organization_id = p_organization_id
    ORDER BY assigned.assigned_at DESC
    LIMIT 1;
    IF v_assignment IS NOT NULL THEN
      INSERT INTO public.task_steps_assigned_duedate (
        organization_id, daily_tasks_assigned_id, due_date
      )
      VALUES (p_organization_id, v_assignment, v_due);
    END IF;
  END IF;

  id := v_row.id;
  title := v_row.title;
  status := v_row.status;
  priority := v_row.priority;
  due_date := v_row.due_date;
  plan_month := to_char(v_row.plan_date AT TIME ZONE 'Asia/Jakarta', 'YYYY-MM');
  RETURN NEXT;
END;
$_$;


ALTER FUNCTION "public"."mcp_update_task"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_priority" "text", "p_due_date" "text", "p_plan_month" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_update_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_description" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "title" "text", "description" "text", "step_order" integer, "is_completed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
DECLARE
  v_self uuid;
  v_title text;
  v_description text;
  v_change_description boolean := false;
  v_id uuid;
  v_order integer;
  v_done boolean;
BEGIN
  IF p_user_id IS NULL OR p_organization_id IS NULL OR p_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_title := btrim(COALESCE(p_title, ''));
  IF char_length(v_title) < 1 OR char_length(v_title) > 200 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_description IS NOT NULL THEN
    IF char_length(btrim(p_description)) > 2000 THEN
      RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
    END IF;
    v_description := NULLIF(btrim(p_description), '');
    v_change_description := true;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = p_user_id
      AND uo.organization_id = p_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'not_a_member' USING ERRCODE = '42501';
  END IF;

  SELECT emp.id INTO v_self
  FROM public.employees emp
  WHERE emp.user_id = p_user_id
    AND emp.organization_id = p_organization_id
  ORDER BY emp.id ASC
  LIMIT 1;
  IF v_self IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  UPDATE public.task_steps step
  SET
    title = v_title,
    description = CASE WHEN v_change_description THEN v_description ELSE step.description END,
    updated_at = now()
  FROM public.daily_tasks task
  WHERE step.id = p_id
    AND step.task_id = task.id
    AND task.organization_id = p_organization_id
  RETURNING step.id, step.title, step.description, step."order", step.is_completed
  INTO v_id, v_title, v_description, v_order, v_done;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  id := v_id;
  title := v_title;
  description := v_description;
  step_order := v_order;
  is_completed := v_done;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."mcp_update_task_step"("p_user_id" "uuid", "p_organization_id" "uuid", "p_id" "uuid", "p_title" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mcp_write_catalog_ingredient"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_name" "text", "p_unit_code" "text", "p_category_name" "text", "p_opening_stock" numeric, "p_unit_cost" numeric, "p_alert_at" numeric, "p_confirm_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_units constant text[] := ARRAY[
    'pcs','box','bks','btr','cm','c','ekr','fl oz','gal','g','grs','ikt','in','jar','klg',
    'kds','ktn','krg','kg','crt','kw','lbr','l','lsn','m','mg','ml','ons','oz','pck','pt',
    'prs','ptg','lb','q','sct','tbsp','tsp','tn','whole'
  ];
  v_name text;
  v_unit text;
  v_category_name text;
  v_outlet_name text;
  v_category_id uuid;
  v_category_label text;
  v_category_is_new boolean := false;
  v_track_cogs boolean;
  v_ingredient_id uuid;
  v_stock_after numeric := 0;
BEGIN
  PERFORM public.mcp_inventory_manager_guard(p_user_id, p_organization_id);

  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_name := btrim(COALESCE(p_name, ''));
  IF v_name = '' OR char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  v_unit := btrim(COALESCE(p_unit_code, ''));
  IF NOT (v_unit = ANY (v_units)) THEN
    RAISE EXCEPTION 'ingredient_unit_invalid' USING ERRCODE = '22023';
  END IF;

  v_category_name := NULLIF(btrim(COALESCE(p_category_name, '')), '');
  IF v_category_name IS NOT NULL AND char_length(v_category_name) > 80 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF p_opening_stock IS NULL
    OR p_opening_stock < 0
    OR p_opening_stock > 99999999999.999
    OR scale(p_opening_stock) > 3
    OR p_unit_cost IS NULL
    OR p_unit_cost < 0
    OR p_unit_cost > 999999999999.99
    OR (p_alert_at IS NOT NULL AND (p_alert_at < 0 OR p_alert_at > 99999999999.999))
  THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  -- Stock without a price would put zero-cost stock into HPP.
  IF p_opening_stock > 0 AND p_unit_cost = 0 THEN
    RAISE EXCEPTION 'ingredient_cost_required' USING ERRCODE = '22023';
  END IF;

  SELECT outlet.name
    INTO v_outlet_name
  FROM public.pos_outlets outlet
  WHERE outlet.id = p_outlet_id
    AND outlet.organization_id = p_organization_id
    AND outlet.is_deleted = false;

  IF v_outlet_name IS NULL THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_ingredients i
    WHERE i.organization_id = p_organization_id
      AND i.is_deleted = false
      AND lower(btrim(i.name)) = lower(v_name)
  ) THEN
    RAISE EXCEPTION 'ingredient_duplicate' USING ERRCODE = '23505';
  END IF;

  IF v_category_name IS NOT NULL THEN
    SELECT c.id, c.name
      INTO v_category_id, v_category_label
    FROM public.catalog_ingredient_categories c
    WHERE c.organization_id = p_organization_id
      AND lower(btrim(c.name)) = lower(v_category_name);
    IF v_category_id IS NULL THEN
      v_category_is_new := true;
      v_category_label := v_category_name;
    END IF;
  END IF;

  v_track_cogs := p_unit_cost > 0;

  -- Preview: everything above is validated, nothing is written.
  IF p_confirm_id IS NULL THEN
    RETURN jsonb_build_object(
      'saved', false,
      'outlet_id', p_outlet_id,
      'outlet_name', v_outlet_name,
      'name', v_name,
      'kind', 'raw',
      'unit_code', v_unit,
      'category_name', v_category_label,
      'category_is_new', v_category_is_new,
      'opening_stock', p_opening_stock,
      'unit_cost', p_unit_cost,
      'opening_value', round(p_opening_stock * p_unit_cost, 2),
      'track_cogs', v_track_cogs,
      'alert_at', p_alert_at
    );
  END IF;

  INSERT INTO public.mcp_tool_confirmations (id, organization_id, user_id, tool)
  VALUES (p_confirm_id, p_organization_id, p_user_id, 'inventory.ingredient.create');

  IF v_category_name IS NOT NULL AND v_category_id IS NULL THEN
    INSERT INTO public.catalog_ingredient_categories (organization_id, name, sort_order)
    VALUES (
      p_organization_id,
      v_category_name,
      (SELECT count(*) + 1 FROM public.catalog_ingredient_categories c WHERE c.organization_id = p_organization_id)
    )
    RETURNING id INTO v_category_id;
  END IF;

  IF v_category_id IS NOT NULL THEN
    -- The Ingredient page lists only categories linked to the selected outlet.
    INSERT INTO public.catalog_ingredient_category_outlets (category_id, outlet_id, organization_id)
    VALUES (v_category_id, p_outlet_id, p_organization_id)
    ON CONFLICT (category_id, outlet_id) DO NOTHING;
  END IF;

  INSERT INTO public.catalog_ingredients (
    organization_id, name, kind, category_id, unit_code, track_inventory, sort_order, is_deleted
  )
  VALUES (
    p_organization_id,
    v_name,
    'raw',
    v_category_id,
    v_unit,
    true,
    (SELECT count(*) + 1 FROM public.catalog_ingredients i
      WHERE i.organization_id = p_organization_id AND i.is_deleted = false),
    false
  )
  RETURNING id INTO v_ingredient_id;

  INSERT INTO public.catalog_ingredient_outlets (
    ingredient_id, outlet_id, organization_id, in_stock, alert_enabled, alert_at, track_cogs, avg_cost
  )
  VALUES (
    v_ingredient_id,
    p_outlet_id,
    p_organization_id,
    0,
    p_alert_at IS NOT NULL,
    p_alert_at,
    v_track_cogs,
    CASE WHEN v_track_cogs THEN p_unit_cost ELSE 0 END
  );

  IF p_opening_stock > 0 THEN
    -- Same ledger path as the page: an 'opening' movement, attributed to the session user.
    PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);
    PERFORM set_config('request.jwt.claim.role', 'authenticated', true);
    PERFORM set_config(
      'request.jwt.claims',
      json_build_object('sub', p_user_id, 'role', 'authenticated')::text,
      true
    );
    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      p_outlet_id,
      'ingredient',
      NULL,
      NULL,
      v_ingredient_id,
      'opening',
      p_opening_stock,
      'mcp_confirmation',
      p_confirm_id::text,
      'Opening stock (Claude)'
    );
  END IF;

  SELECT io.in_stock
    INTO v_stock_after
  FROM public.catalog_ingredient_outlets io
  WHERE io.ingredient_id = v_ingredient_id
    AND io.outlet_id = p_outlet_id;

  RETURN jsonb_build_object(
    'saved', true,
    'ingredient_id', v_ingredient_id,
    'outlet_id', p_outlet_id,
    'outlet_name', v_outlet_name,
    'name', v_name,
    'kind', 'raw',
    'unit_code', v_unit,
    'category_name', v_category_label,
    'category_is_new', v_category_is_new,
    'opening_stock', p_opening_stock,
    'unit_cost', p_unit_cost,
    'opening_value', round(p_opening_stock * p_unit_cost, 2),
    'track_cogs', v_track_cogs,
    'alert_at', p_alert_at,
    'in_stock', COALESCE(v_stock_after, 0)
  );
END;
$$;


ALTER FUNCTION "public"."mcp_write_catalog_ingredient"("p_user_id" "uuid", "p_organization_id" "uuid", "p_outlet_id" "uuid", "p_name" "text", "p_unit_code" "text", "p_category_name" "text", "p_opening_stock" numeric, "p_unit_cost" numeric, "p_alert_at" numeric, "p_confirm_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."merge_checkout_identity_bridge_dry_run"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_phone_lead public.leads%ROWTYPE;
  v_email_lead public.leads%ROWTYPE;
  v_phone_key text;
  v_email_key text;
  v_attr_count int;
  v_phone_attr boolean;
  v_email_attr boolean;
  v_winner uuid;
  v_losers uuid[];
  v_cluster_key text;
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  IF p_phone_lead_id IS NULL OR p_email_lead_id IS NULL THEN
    RAISE EXCEPTION 'lead_ids_required'
      USING ERRCODE = 'P0001';
  END IF;

  IF p_phone_lead_id = p_email_lead_id THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'skipped', true,
      'skip_reason', 'same_lead',
      'winner_lead_id', p_phone_lead_id,
      'loser_lead_ids', '[]'::jsonb,
      'cluster_key', NULL,
      'merged', false
    );
  END IF;

  SELECT * INTO v_phone_lead
  FROM public.leads
  WHERE id = p_phone_lead_id
    AND organization_id = p_organization_id
    AND merged_into_lead_id IS NULL;

  SELECT * INTO v_email_lead
  FROM public.leads
  WHERE id = p_email_lead_id
    AND organization_id = p_organization_id
    AND merged_into_lead_id IS NULL;

  IF v_phone_lead.id IS NULL OR v_email_lead.id IS NULL THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'skipped', true,
      'skip_reason', 'lead_not_found_or_archived',
      'winner_lead_id', NULL,
      'loser_lead_ids', '[]'::jsonb,
      'cluster_key', NULL,
      'merged', false
    );
  END IF;

  v_phone_key := public.normalize_wa_phone_key(v_phone_lead.phone_number);
  v_email_key := lower(btrim(COALESCE(v_email_lead.email, '')));
  IF v_email_key = '' THEN
    v_email_key := NULL;
  END IF;

  IF v_phone_key IS NULL OR v_email_key IS NULL THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'skipped', true,
      'skip_reason', 'missing_phone_or_email_key',
      'winner_lead_id', NULL,
      'loser_lead_ids', '[]'::jsonb,
      'cluster_key', NULL,
      'merged', false
    );
  END IF;

  IF NOT public._lead_merge_is_valid_identity_email(v_email_key) THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'skipped', true,
      'skip_reason', 'invalid_email',
      'winner_lead_id', NULL,
      'loser_lead_ids', '[]'::jsonb,
      'cluster_key', NULL,
      'merged', false
    );
  END IF;

  SELECT count(*)::int
  INTO v_attr_count
  FROM public.leads l
  WHERE l.id IN (p_phone_lead_id, p_email_lead_id)
    AND public._lead_merge_is_attributed(p_organization_id, l.id, l.source, l.ticket_id);

  v_cluster_key := 'phone:' || v_phone_key || '|email:' || v_email_key;

  IF v_attr_count > 1 THEN
    RETURN jsonb_build_object(
      'organization_id', p_organization_id,
      'skipped', true,
      'skip_reason', 'ambiguous_attributed',
      'winner_lead_id', NULL,
      'loser_lead_ids', '[]'::jsonb,
      'cluster_key', v_cluster_key,
      'merged', false
    );
  END IF;

  v_phone_attr := public._lead_merge_is_attributed(
    p_organization_id, v_phone_lead.id, v_phone_lead.source, v_phone_lead.ticket_id
  );
  v_email_attr := public._lead_merge_is_attributed(
    p_organization_id, v_email_lead.id, v_email_lead.source, v_email_lead.ticket_id
  );

  IF v_email_attr AND NOT v_phone_attr THEN
    v_winner := p_email_lead_id;
  ELSE
    v_winner := p_phone_lead_id;
  END IF;

  v_losers := ARRAY(
    SELECT x FROM unnest(ARRAY[p_phone_lead_id, p_email_lead_id]) AS x
    WHERE x IS DISTINCT FROM v_winner
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'skipped', false,
    'skip_reason', NULL,
    'winner_lead_id', v_winner,
    'loser_lead_ids', to_jsonb(v_losers),
    'cluster_key', v_cluster_key,
    'phone_lead_id', p_phone_lead_id,
    'email_lead_id', p_email_lead_id,
    'merged', false
  );
END;
$$;


ALTER FUNCTION "public"."merge_checkout_identity_bridge_dry_run"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_checkout_identity_bridge_dry_run"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid") IS 'Fase 5: dry-run soft-merge of phone-anchored lead vs email-anchored lead (checkout bridge).';



CREATE OR REPLACE FUNCTION "public"."merge_checkout_identity_bridge_execute"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid", "p_confirm" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_plan jsonb;
  v_winner uuid;
  v_losers uuid[];
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  IF coalesce(p_confirm, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'confirm_required'
      USING ERRCODE = 'P0001',
            HINT = 'Call merge_checkout_identity_bridge_execute(org, phone_lead, email_lead, true) after dry_run.';
  END IF;

  v_plan := public.merge_checkout_identity_bridge_dry_run(
    p_organization_id,
    p_phone_lead_id,
    p_email_lead_id
  );

  IF coalesce((v_plan->>'skipped')::boolean, false) THEN
    RETURN v_plan || jsonb_build_object('merged', false);
  END IF;

  v_winner := (v_plan->>'winner_lead_id')::uuid;
  v_losers := ARRAY(SELECT jsonb_array_elements_text(v_plan->'loser_lead_ids')::uuid);

  PERFORM public._lead_merge_execute_cluster(
    p_organization_id,
    'checkout_bridge',
    v_plan->>'cluster_key',
    v_winner,
    v_losers,
    v_actor
  );

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'skipped', false,
    'skip_reason', NULL,
    'winner_lead_id', v_winner,
    'loser_lead_ids', to_jsonb(v_losers),
    'cluster_key', v_plan->>'cluster_key',
    'phone_lead_id', p_phone_lead_id,
    'email_lead_id', p_email_lead_id,
    'merged', true
  );
END;
$$;


ALTER FUNCTION "public"."merge_checkout_identity_bridge_execute"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid", "p_confirm" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_checkout_identity_bridge_execute"("p_organization_id" "uuid", "p_phone_lead_id" "uuid", "p_email_lead_id" "uuid", "p_confirm" boolean) IS 'Fase 5: execute checkout identity bridge soft-merge (confirm=true required).';



CREATE OR REPLACE FUNCTION "public"."merge_customer_lead_duplicates_dry_run"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_clusters jsonb := '[]'::jsonb;
  r record;
  v_ids uuid[];
  v_attr_count int;
  v_winner uuid;
  v_losers uuid[];
  v_row jsonb;
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  FOR r IN
    SELECT
      'phone'::text AS kind,
      public.normalize_wa_phone_key(l.phone_number) AS cluster_key,
      array_agg(l.id ORDER BY l.created_at) AS lead_ids
    FROM public.leads l
    WHERE l.organization_id = p_organization_id
      AND l.merged_into_lead_id IS NULL
      AND l.phone_number IS NOT NULL
      AND public.normalize_wa_phone_key(l.phone_number) IS NOT NULL
    GROUP BY 1, 2
    HAVING count(*) >= 2
  LOOP
    v_ids := r.lead_ids;
    SELECT count(*)::int
    INTO v_attr_count
    FROM public.leads l
    WHERE l.id = ANY (v_ids)
      AND public._lead_merge_is_attributed(p_organization_id, l.id, l.source, l.ticket_id);

    IF v_attr_count > 1 THEN
      v_row := jsonb_build_object(
        'kind', r.kind,
        'cluster_key', r.cluster_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', true,
        'skip_reason', 'ambiguous_attributed',
        'winner_lead_id', NULL,
        'loser_lead_ids', '[]'::jsonb
      );
    ELSE
      v_winner := public._lead_merge_pick_winner(p_organization_id, v_ids);
      v_losers := array(
        SELECT x FROM unnest(v_ids) AS x WHERE x IS DISTINCT FROM v_winner
      );
      v_row := jsonb_build_object(
        'kind', r.kind,
        'cluster_key', r.cluster_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', false,
        'skip_reason', NULL,
        'winner_lead_id', v_winner,
        'loser_lead_ids', to_jsonb(v_losers)
      );
    END IF;
    v_clusters := v_clusters || jsonb_build_array(v_row);
  END LOOP;

  FOR r IN
    SELECT
      'email'::text AS kind,
      lower(btrim(l.email)) AS cluster_key,
      array_agg(l.id ORDER BY l.created_at) AS lead_ids
    FROM public.leads l
    WHERE l.organization_id = p_organization_id
      AND l.merged_into_lead_id IS NULL
      AND l.email IS NOT NULL
      AND length(btrim(l.email)) > 0
    GROUP BY 1, 2
    HAVING count(*) >= 2
  LOOP
    v_ids := r.lead_ids;
    SELECT count(*)::int
    INTO v_attr_count
    FROM public.leads l
    WHERE l.id = ANY (v_ids)
      AND public._lead_merge_is_attributed(p_organization_id, l.id, l.source, l.ticket_id);

    IF v_attr_count > 1 THEN
      v_row := jsonb_build_object(
        'kind', r.kind,
        'cluster_key', r.cluster_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', true,
        'skip_reason', 'ambiguous_attributed',
        'winner_lead_id', NULL,
        'loser_lead_ids', '[]'::jsonb
      );
    ELSE
      v_winner := public._lead_merge_pick_winner(p_organization_id, v_ids);
      v_losers := array(
        SELECT x FROM unnest(v_ids) AS x WHERE x IS DISTINCT FROM v_winner
      );
      v_row := jsonb_build_object(
        'kind', r.kind,
        'cluster_key', r.cluster_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', false,
        'skip_reason', NULL,
        'winner_lead_id', v_winner,
        'loser_lead_ids', to_jsonb(v_losers)
      );
    END IF;
    v_clusters := v_clusters || jsonb_build_array(v_row);
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'clusters', v_clusters,
    'mergeable_count', (
      SELECT count(*)::int
      FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS NOT TRUE
    ),
    'skipped_count', (
      SELECT count(*)::int
      FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS TRUE
    )
  );
END;
$$;


ALTER FUNCTION "public"."merge_customer_lead_duplicates_dry_run"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_customer_lead_duplicates_dry_run"("p_organization_id" "uuid") IS 'Fase 3: report phone/email duplicate lead clusters for one organization (no writes).';



CREATE OR REPLACE FUNCTION "public"."merge_customer_lead_duplicates_execute"("p_organization_id" "uuid", "p_confirm" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_dry jsonb;
  v_cluster jsonb;
  v_merged int := 0;
  v_skipped int := 0;
  v_kind text;
  v_key text;
  v_winner uuid;
  v_losers uuid[];
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  IF coalesce(p_confirm, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'confirm_required'
      USING ERRCODE = 'P0001',
            HINT = 'Call merge_customer_lead_duplicates_execute(org_id, true) after reviewing dry_run.';
  END IF;

  v_dry := public.merge_customer_lead_duplicates_dry_run(p_organization_id);

  FOR v_cluster IN
    SELECT value FROM jsonb_array_elements(v_dry->'clusters')
  LOOP
    IF (v_cluster->>'kind') <> 'phone' THEN
      CONTINUE;
    END IF;

    IF coalesce((v_cluster->>'skipped')::boolean, false) THEN
      v_skipped := v_skipped + 1;
      INSERT INTO public.lead_merge_events (
        organization_id, cluster_kind, cluster_key, winner_lead_id, loser_lead_ids,
        skipped, skip_reason, created_by
      ) VALUES (
        p_organization_id,
        v_cluster->>'kind',
        v_cluster->>'cluster_key',
        NULL,
        COALESCE(
          ARRAY(SELECT jsonb_array_elements_text(v_cluster->'lead_ids')::uuid),
          '{}'::uuid[]
        ),
        true,
        v_cluster->>'skip_reason',
        v_actor
      );
      CONTINUE;
    END IF;

    v_kind := v_cluster->>'kind';
    v_key := v_cluster->>'cluster_key';
    v_winner := (v_cluster->>'winner_lead_id')::uuid;
    v_losers := ARRAY(
      SELECT jsonb_array_elements_text(v_cluster->'loser_lead_ids')::uuid
    );

    PERFORM public._lead_merge_execute_cluster(
      p_organization_id,
      v_kind,
      v_key,
      v_winner,
      v_losers,
      v_actor
    );
    v_merged := v_merged + 1;
  END LOOP;

  -- Email pass (fresh dry_run after phone clears identity on losers)
  v_dry := public.merge_customer_lead_duplicates_dry_run(p_organization_id);
  FOR v_cluster IN
    SELECT value FROM jsonb_array_elements(v_dry->'clusters')
  LOOP
    IF (v_cluster->>'kind') <> 'email' THEN
      CONTINUE;
    END IF;

    IF coalesce((v_cluster->>'skipped')::boolean, false) THEN
      v_skipped := v_skipped + 1;
      INSERT INTO public.lead_merge_events (
        organization_id, cluster_kind, cluster_key, winner_lead_id, loser_lead_ids,
        skipped, skip_reason, created_by
      ) VALUES (
        p_organization_id,
        v_cluster->>'kind',
        v_cluster->>'cluster_key',
        NULL,
        COALESCE(
          ARRAY(SELECT jsonb_array_elements_text(v_cluster->'lead_ids')::uuid),
          '{}'::uuid[]
        ),
        true,
        v_cluster->>'skip_reason',
        v_actor
      );
      CONTINUE;
    END IF;

    v_winner := (v_cluster->>'winner_lead_id')::uuid;
    v_losers := ARRAY(
      SELECT jsonb_array_elements_text(v_cluster->'loser_lead_ids')::uuid
    );
    PERFORM public._lead_merge_execute_cluster(
      p_organization_id,
      'email',
      v_cluster->>'cluster_key',
      v_winner,
      v_losers,
      v_actor
    );
    v_merged := v_merged + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'merged_clusters', v_merged,
    'skipped_clusters', v_skipped,
    'remaining', public.merge_customer_lead_duplicates_dry_run(p_organization_id)
  );
END;
$$;


ALTER FUNCTION "public"."merge_customer_lead_duplicates_execute"("p_organization_id" "uuid", "p_confirm" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_customer_lead_duplicates_execute"("p_organization_id" "uuid", "p_confirm" boolean) IS 'Fase 3: soft-archive duplicate leads per org. Requires p_confirm=true after dry_run review.';



CREATE OR REPLACE FUNCTION "public"."merge_identity_graph_leads_dry_run"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_clusters jsonb := '[]'::jsonb;
  v_row jsonb;
  r record;
  v_ids uuid[];
  v_attr_count int;
  v_winner uuid;
  v_losers uuid[];
  v_comp_key text;
  v_updated int;
  i int;
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  -- Build parent map via iterative min-id union on shared keys
  CREATE TEMP TABLE IF NOT EXISTS _ig_leads (
    id uuid PRIMARY KEY,
    phone_key text,
    email_key text,
    root uuid
  ) ON COMMIT DROP;
  TRUNCATE _ig_leads;

  INSERT INTO _ig_leads (id, phone_key, email_key, root)
  SELECT
    l.id,
    public.normalize_wa_phone_key(l.phone_number),
    CASE
      WHEN public._lead_merge_is_valid_identity_email(l.email) THEN lower(btrim(l.email))
      ELSE NULL
    END,
    l.id
  FROM public.leads l
  WHERE l.organization_id = p_organization_id
    AND l.merged_into_lead_id IS NULL
    AND (
      public.normalize_wa_phone_key(l.phone_number) IS NOT NULL
      OR public._lead_merge_is_valid_identity_email(l.email)
    );

  -- Iterate unions until stable (shared phone or email → min root)
  FOR i IN 1..20 LOOP
    UPDATE _ig_leads a
    SET root = s.new_root
    FROM (
      SELECT x.id, m.min_root AS new_root
      FROM _ig_leads x
      JOIN LATERAL (
        SELECT min(y.root::text)::uuid AS min_root
        FROM _ig_leads y
        WHERE
          (x.phone_key IS NOT NULL AND y.phone_key = x.phone_key)
          OR (x.email_key IS NOT NULL AND y.email_key = x.email_key)
          OR y.id = x.id
      ) m ON true
      WHERE x.root IS DISTINCT FROM m.min_root
    ) s
    WHERE a.id = s.id;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    EXIT WHEN v_updated = 0;
  END LOOP;

  -- Path compression pass: set root to min root in component
  UPDATE _ig_leads a
  SET root = s.min_root
  FROM (
    SELECT root AS old_root, min(id::text)::uuid AS min_root
    FROM _ig_leads
    GROUP BY root
  ) s
  WHERE a.root = s.old_root;

  FOR r IN
    SELECT root, array_agg(id ORDER BY id) AS lead_ids
    FROM _ig_leads
    GROUP BY root
    HAVING count(*) >= 2
  LOOP
    v_ids := r.lead_ids;
    v_comp_key := r.root::text;

    SELECT count(*)::int
    INTO v_attr_count
    FROM public.leads l
    WHERE l.id = ANY (v_ids)
      AND public._lead_merge_is_attributed(p_organization_id, l.id, l.source, l.ticket_id);

    IF v_attr_count > 1 THEN
      v_row := jsonb_build_object(
        'kind', 'identity_graph',
        'cluster_key', v_comp_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', true,
        'skip_reason', 'ambiguous_attributed',
        'winner_lead_id', NULL,
        'loser_lead_ids', '[]'::jsonb
      );
    ELSE
      v_winner := public._lead_merge_pick_winner(p_organization_id, v_ids);
      v_losers := array(SELECT x FROM unnest(v_ids) AS x WHERE x IS DISTINCT FROM v_winner);
      v_row := jsonb_build_object(
        'kind', 'identity_graph',
        'cluster_key', v_comp_key,
        'lead_ids', to_jsonb(v_ids),
        'skipped', false,
        'skip_reason', NULL,
        'winner_lead_id', v_winner,
        'loser_lead_ids', to_jsonb(v_losers)
      );
    END IF;
    v_clusters := v_clusters || jsonb_build_array(v_row);
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'clusters', v_clusters,
    'mergeable_count', (
      SELECT count(*)::int FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS NOT TRUE
    ),
    'skipped_count', (
      SELECT count(*)::int FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS TRUE
    )
  );
END;
$$;


