CREATE OR REPLACE FUNCTION "public"."merge_typo_email_leads_dry_run"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_clusters jsonb := '[]'::jsonb;
  r record;
  v_valid_ids uuid[];
  v_row jsonb;
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);

  FOR r IN
    SELECT
      l.id AS typo_id,
      lower(btrim(l.email)) AS typo_email,
      split_part(lower(btrim(l.email)), '@', 1) AS local_part,
      split_part(lower(btrim(l.email)), '@', 2) AS typo_domain
    FROM public.leads l
    WHERE l.organization_id = p_organization_id
      AND l.merged_into_lead_id IS NULL
      AND l.email IS NOT NULL
      AND length(btrim(l.email)) > 0
      AND NOT public._lead_merge_is_valid_identity_email(l.email)
  LOOP
    SELECT array_agg(v.id ORDER BY v.created_at)
    INTO v_valid_ids
    FROM public.leads v
    WHERE v.organization_id = p_organization_id
      AND v.merged_into_lead_id IS NULL
      AND public._lead_merge_is_valid_identity_email(v.email)
      AND split_part(lower(btrim(v.email)), '@', 1) = r.local_part
      AND public._lead_merge_is_typo_domain(
        split_part(lower(btrim(v.email)), '@', 2),
        r.typo_domain
      );

    v_valid_ids := COALESCE(v_valid_ids, '{}'::uuid[]);

    IF cardinality(v_valid_ids) = 0 THEN
      v_row := jsonb_build_object(
        'kind', 'typo_email',
        'cluster_key', r.typo_email,
        'lead_ids', jsonb_build_array(r.typo_id),
        'skipped', true,
        'skip_reason', 'no_typo_target',
        'winner_lead_id', NULL,
        'loser_lead_ids', '[]'::jsonb
      );
    ELSIF cardinality(v_valid_ids) > 1 THEN
      v_row := jsonb_build_object(
        'kind', 'typo_email',
        'cluster_key', r.typo_email,
        'lead_ids', to_jsonb(v_valid_ids || r.typo_id),
        'skipped', true,
        'skip_reason', 'ambiguous_typo_target',
        'winner_lead_id', NULL,
        'loser_lead_ids', '[]'::jsonb
      );
    ELSE
      v_row := jsonb_build_object(
        'kind', 'typo_email',
        'cluster_key', r.typo_email,
        'lead_ids', jsonb_build_array(v_valid_ids[1], r.typo_id),
        'skipped', false,
        'skip_reason', NULL,
        'winner_lead_id', v_valid_ids[1],
        'loser_lead_ids', jsonb_build_array(r.typo_id)
      );
    END IF;
    v_clusters := v_clusters || jsonb_build_array(v_row);
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'clusters', v_clusters,
    'mergeable_count', (
      SELECT count(*)::int FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS NOT TRUE
    ),
    'skipped_count', (
      SELECT count(*)::int FROM jsonb_array_elements(v_clusters) c
      WHERE (c->>'skipped')::boolean IS TRUE
    )
  );
END;
$$;


ALTER FUNCTION "public"."merge_typo_email_leads_dry_run"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."merge_typo_email_leads_dry_run"("p_organization_id" "uuid") IS 'Fase 4a: report typo email → valid email merge clusters.';



CREATE OR REPLACE FUNCTION "public"."merge_typo_email_leads_execute"("p_organization_id" "uuid", "p_confirm" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_dry jsonb;
  v_cluster jsonb;
  v_merged int := 0;
  v_skipped int := 0;
  v_winner uuid;
  v_losers uuid[];
BEGIN
  PERFORM public._lead_merge_assert_org_access(p_organization_id);
  IF coalesce(p_confirm, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'confirm_required' USING ERRCODE = 'P0001';
  END IF;

  v_dry := public.merge_typo_email_leads_dry_run(p_organization_id);

  FOR v_cluster IN SELECT value FROM jsonb_array_elements(v_dry->'clusters')
  LOOP
    IF coalesce((v_cluster->>'skipped')::boolean, false) THEN
      v_skipped := v_skipped + 1;
      INSERT INTO public.lead_merge_events (
        organization_id, cluster_kind, cluster_key, winner_lead_id, loser_lead_ids,
        skipped, skip_reason, created_by
      ) VALUES (
        p_organization_id,
        'typo_email',
        v_cluster->>'cluster_key',
        NULL,
        COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_cluster->'lead_ids')::uuid), '{}'::uuid[]),
        true,
        v_cluster->>'skip_reason',
        v_actor
      );
      CONTINUE;
    END IF;

    v_winner := (v_cluster->>'winner_lead_id')::uuid;
    v_losers := ARRAY(SELECT jsonb_array_elements_text(v_cluster->'loser_lead_ids')::uuid);
    PERFORM public._lead_merge_execute_cluster(
      p_organization_id,
      'typo_email',
      v_cluster->>'cluster_key',
      v_winner,
      v_losers,
      v_actor
    );
    v_merged := v_merged + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'organization_id', p_organization_id,
    'merged_clusters', v_merged,
    'skipped_clusters', v_skipped,
    'remaining', public.merge_typo_email_leads_dry_run(p_organization_id)
  );
END;
$$;


ALTER FUNCTION "public"."merge_typo_email_leads_execute"("p_organization_id" "uuid", "p_confirm" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."migrate_legacy_sku_to_catalog_stock"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_migrated integer := 0;
  v_skipped integer := 0;
  v_rec record;
  v_sku_qty numeric(14, 3);
  v_current numeric(14, 3);
  v_delta numeric(14, 3);
  v_already boolean;
  v_has_variants boolean;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;

  SELECT id
    INTO v_outlet
  FROM public.pos_outlets
  WHERE organization_id = p_organization_id
    AND is_deleted = false
    AND is_active = true
  ORDER BY is_default DESC, sort_order, created_at
  LIMIT 1;

  IF v_outlet IS NULL THEN
    RETURN jsonb_build_object('error', 'catalog_stock_outlet_required', 'migrated', 0, 'skipped', 0);
  END IF;

  FOR v_rec IN
    SELECT dp.id AS product_id, dp.inventory_sku_id
    FROM public.default_prices dp
    WHERE dp.organization_id = p_organization_id
      AND dp.kind = 'product'
      AND dp.track_stock = true
      AND dp.inventory_sku_id IS NOT NULL
  LOOP
    SELECT EXISTS (
      SELECT 1
      FROM public.catalog_product_variants v
      WHERE v.product_id = v_rec.product_id
    )
    INTO v_has_variants;

    IF v_has_variants THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT EXISTS (
      SELECT 1
      FROM public.catalog_stock_movements m
      WHERE m.organization_id = p_organization_id
        AND m.outlet_id = v_outlet
        AND m.item_kind = 'product'
        AND m.product_id = v_rec.product_id
        AND m.reference_type = 'sku_migration'
        AND m.reference_id = v_rec.product_id::text
    )
    INTO v_already;

    IF v_already THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    SELECT COALESCE(l.available_qty, 0)::numeric(14, 3)
      INTO v_sku_qty
    FROM public.inventory_stock_levels l
    WHERE l.sku_id = v_rec.inventory_sku_id
      AND l.organization_id = p_organization_id;

    v_sku_qty := COALESCE(v_sku_qty, 0);

    INSERT INTO public.catalog_product_outlets (
      product_id,
      outlet_id,
      organization_id,
      in_stock
    )
    VALUES (v_rec.product_id, v_outlet, p_organization_id, 0)
    ON CONFLICT (product_id, outlet_id) DO NOTHING;

    SELECT po.in_stock
      INTO v_current
    FROM public.catalog_product_outlets po
    WHERE po.product_id = v_rec.product_id
      AND po.outlet_id = v_outlet
    FOR UPDATE;

    v_current := COALESCE(v_current, 0);
    v_delta := v_sku_qty - v_current;

    IF v_delta = 0 THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      v_outlet,
      'product',
      v_rec.product_id,
      NULL,
      NULL,
      CASE WHEN v_current = 0 THEN 'opening' ELSE 'adjustment' END,
      v_delta,
      'sku_migration',
      v_rec.product_id::text,
      'Legacy SKU pool migration'
    );

    v_migrated := v_migrated + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'migrated', v_migrated,
    'skipped', v_skipped,
    'outlet_id', v_outlet
  );
END;
$$;


ALTER FUNCTION "public"."migrate_legacy_sku_to_catalog_stock"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_brief_storyboard_row"("p_plan_id" "uuid", "p_action" "text", "p_row_index" integer) RETURNS TABLE("storage_path" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
  v_index integer;
  v_shot uuid;
BEGIN
  IF p_plan_id IS NULL
     OR p_row_index IS NULL
     OR p_row_index < 0
     OR p_action NOT IN ('insert', 'delete') THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard') THEN
    RAISE EXCEPTION 'brief_field_forbidden' USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
  END IF;

  PERFORM 1
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT count(*)::integer
    INTO v_count
  FROM public.brief_storyboard_shots AS shot
  WHERE shot.social_media_plan_id = p_plan_id;

  IF p_action = 'insert' AND v_count = 0 AND p_row_index = 0 THEN
    INSERT INTO public.brief_storyboard_shots (social_media_plan_id, row_index)
    VALUES (p_plan_id, 0);
    RETURN;
  END IF;

  IF v_count = 0 OR (p_action = 'insert' AND p_row_index > v_count) OR (p_action = 'delete' AND p_row_index >= v_count) THEN
    RAISE EXCEPTION 'brief_shot_mismatch' USING ERRCODE = 'P0001';
  END IF;

  IF p_action = 'insert' THEN
    FOR v_index IN
      SELECT shot.row_index
      FROM public.brief_storyboard_shots AS shot
      WHERE shot.social_media_plan_id = p_plan_id
        AND shot.row_index >= p_row_index
      ORDER BY shot.row_index DESC
    LOOP
      UPDATE public.brief_storyboard_shots AS shot
      SET row_index = shot.row_index + 1
      WHERE shot.social_media_plan_id = p_plan_id
        AND shot.row_index = v_index;
    END LOOP;

    FOR v_index IN
      SELECT DISTINCT image.row_index
      FROM public.brief_storyboard_images AS image
      WHERE image.social_media_plan_id = p_plan_id
        AND image.column_index = 1
        AND image.row_index >= p_row_index
      ORDER BY image.row_index DESC
    LOOP
      UPDATE public.brief_storyboard_images AS image
      SET row_index = image.row_index + 1
      WHERE image.social_media_plan_id = p_plan_id
        AND image.column_index = 1
        AND image.row_index = v_index;
    END LOOP;

    FOR v_index IN
      SELECT DISTINCT clip.row_index
      FROM public.brief_voice_clips AS clip
      WHERE clip.social_media_plan_id = p_plan_id
        AND clip.kind = 'vo'
        AND clip.row_index >= p_row_index
      ORDER BY clip.row_index DESC
    LOOP
      UPDATE public.brief_voice_clips AS clip
      SET row_index = clip.row_index + 1
      WHERE clip.social_media_plan_id = p_plan_id
        AND clip.kind = 'vo'
        AND clip.row_index = v_index;
    END LOOP;

    INSERT INTO public.brief_storyboard_shots (social_media_plan_id, row_index)
    VALUES (p_plan_id, p_row_index);
    RETURN;
  END IF;

  SELECT shot.id
    INTO v_shot
  FROM public.brief_storyboard_shots AS shot
  WHERE shot.social_media_plan_id = p_plan_id
    AND shot.row_index = p_row_index;

  RETURN QUERY
  SELECT clip.storage_path
  FROM public.brief_voice_clips AS clip
  WHERE clip.social_media_plan_id = p_plan_id
    AND clip.kind = 'vo'
    AND (clip.shot_id = v_shot OR (clip.shot_id IS NULL AND clip.row_index = p_row_index));

  DELETE FROM public.brief_voice_clips AS clip
  WHERE clip.social_media_plan_id = p_plan_id
    AND clip.kind = 'vo'
    AND (clip.shot_id = v_shot OR (clip.shot_id IS NULL AND clip.row_index = p_row_index));

  DELETE FROM public.brief_storyboard_images AS image
  WHERE image.social_media_plan_id = p_plan_id
    AND image.column_index = 1
    AND (image.shot_id = v_shot OR (image.shot_id IS NULL AND image.row_index = p_row_index));

  DELETE FROM public.brief_storyboard_shots AS shot
  WHERE shot.id = v_shot;

  FOR v_index IN
    SELECT shot.row_index
    FROM public.brief_storyboard_shots AS shot
    WHERE shot.social_media_plan_id = p_plan_id
      AND shot.row_index > p_row_index
    ORDER BY shot.row_index ASC
  LOOP
    UPDATE public.brief_storyboard_shots AS shot
    SET row_index = shot.row_index - 1
    WHERE shot.social_media_plan_id = p_plan_id
      AND shot.row_index = v_index;
  END LOOP;

  FOR v_index IN
    SELECT DISTINCT image.row_index
    FROM public.brief_storyboard_images AS image
    WHERE image.social_media_plan_id = p_plan_id
      AND image.column_index = 1
      AND image.row_index > p_row_index
    ORDER BY image.row_index ASC
  LOOP
    UPDATE public.brief_storyboard_images AS image
    SET row_index = image.row_index - 1
    WHERE image.social_media_plan_id = p_plan_id
      AND image.column_index = 1
      AND image.row_index = v_index;
  END LOOP;

  FOR v_index IN
    SELECT DISTINCT clip.row_index
    FROM public.brief_voice_clips AS clip
    WHERE clip.social_media_plan_id = p_plan_id
      AND clip.kind = 'vo'
      AND clip.row_index > p_row_index
    ORDER BY clip.row_index ASC
  LOOP
    UPDATE public.brief_voice_clips AS clip
    SET row_index = clip.row_index - 1
    WHERE clip.social_media_plan_id = p_plan_id
      AND clip.kind = 'vo'
      AND clip.row_index = v_index;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."move_brief_storyboard_row"("p_plan_id" "uuid", "p_action" "text", "p_row_index" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."move_brief_storyboard_row"("p_plan_id" "uuid", "p_action" "text", "p_row_index" integer) IS 'Insert or delete one storyboard row. Surviving VO clips and images keep shot_id. Returns storage paths of removed VO clips.';



