CREATE OR REPLACE FUNCTION "public"."normalize_kol_campaign_targets"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.target_engagement IS NOT NULL AND NEW.target_engagement > 100
     AND NEW.target_reach IS NOT NULL AND NEW.target_reach > 0 THEN
    NEW.target_engagement := LEAST(
      100,
      GREATEST(1, ROUND((NEW.target_engagement::numeric / NEW.target_reach) * 100, 1)::integer)
    );
  END IF;

  IF NEW.target_engagement IS NOT NULL THEN
    NEW.target_engagement := LEAST(100, GREATEST(0, NEW.target_engagement));
  END IF;

  IF NEW.target_engagement IS NULL OR NEW.target_engagement <= 0 THEN
    NEW.target_engagement := 5;
  END IF;

  IF NEW.target_conversion IS NULL OR NEW.target_conversion <= 0 THEN
    NEW.target_conversion := GREATEST(
      1,
      COALESCE(ROUND(COALESCE(NEW.target_reach, 100000)::numeric / 5000.0)::integer, 1)
    );
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."normalize_kol_campaign_targets"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_sla_channel"("ch" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE lower(coalesce(nullif(trim(ch), ''), 'whatsapp'))
    WHEN 'wa_cloud' THEN 'whatsapp'
    WHEN 'messenger' THEN 'facebook'
    WHEN 'th' THEN 'threads'
    ELSE lower(coalesce(nullif(trim(ch), ''), 'whatsapp'))
  END;
$$;


ALTER FUNCTION "public"."normalize_sla_channel"("ch" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."normalize_wa_phone_key"("p_text" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  d text;
BEGIN
  IF p_text IS NULL OR btrim(p_text) = '' THEN
    RETURN NULL;
  END IF;
  d := regexp_replace(btrim(p_text), '\D', '', 'g');
  IF d = '' OR d IS NULL THEN
    RETURN NULL;
  END IF;
  IF left(d, 1) = '0' AND length(d) >= 10 THEN
    d := '62' || substr(d, 2);
  END IF;
  IF left(d, 2) <> '62' AND left(d, 1) = '8' AND length(d) >= 9 AND length(d) <= 12 THEN
    d := '62' || d;
  END IF;
  IF length(d) < 8 OR length(d) > 18 THEN
    RETURN NULL;
  END IF;
  RETURN d;
END;
$$;


ALTER FUNCTION "public"."normalize_wa_phone_key"("p_text" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."normalize_wa_phone_key"("p_text" "text") IS 'Digit-only WA key (62…); aligns with app normalizeWaPhoneKey.';



CREATE OR REPLACE FUNCTION "public"."notify_pic_production_manager_need_review"("p_plan_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_title text;
  v_manager uuid;
  v_token text;
  v_assignee uuid;
  v_assigner uuid;
BEGIN
  SELECT plan.organization_id, COALESCE(NULLIF(btrim(plan.title), ''), 'Konten')
  INTO v_org, v_title
  FROM public.social_media_plans plan
  WHERE plan.id = p_plan_id
    AND COALESCE(plan.production_approved, false) = false;

  IF v_org IS NULL THEN
    RETURN;
  END IF;

  v_manager := public.pic_production_manager_user_id(p_plan_id);
  IF v_manager IS NULL THEN
    RETURN;
  END IF;

  v_token := public.latest_review_token_for_plan(p_plan_id);
  v_assignee := public.resolve_production_assignee_user_id(p_plan_id);
  v_assigner := public.resolve_production_assigner_user_id(p_plan_id);

  PERFORM public.insert_social_media_production_notification(
    v_manager, v_org, 'need_review', p_plan_id, v_token,
    auth.uid(), v_assignee, v_assigner, v_title,
    '/tools/daily-task?view=jobdesc&productionPlan=' || p_plan_id::text
  );
END;
$$;


