CREATE OR REPLACE FUNCTION "public"."organization_omnichannel_staff_block_delete_if_assigned"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  oid uuid := OLD.organization_id;
  eid uuid := OLD.employee_id;
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.leads l
    WHERE l.organization_id = oid AND l.assignee_id = eid
  ) THEN
    RAISE EXCEPTION 'Cannot remove omnichannel staff while assigned to a lead';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.whatsapp_conversations c
    WHERE c.organization_id = oid AND c.assignee_id = eid
  ) THEN
    RAISE EXCEPTION 'Cannot remove omnichannel staff while assigned to a WhatsApp conversation';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.instagram_conversations c
    WHERE c.organization_id = oid AND c.assignee_id = eid
  ) THEN
    RAISE EXCEPTION 'Cannot remove omnichannel staff while assigned to an Instagram conversation';
  END IF;
  RETURN OLD;
END;
$$;


ALTER FUNCTION "public"."organization_omnichannel_staff_block_delete_if_assigned"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."organization_omnichannel_staff_validate_employee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cap integer;
  v_current integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = NEW.employee_id
      AND e.organization_id = NEW.organization_id
      AND e.user_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Omnichannel roster: employee must belong to organization and have user_id';
  END IF;

  SELECT LEAST(
    COALESCE(os.member_count, 0),
    COALESCE(os.omnichannel_paid_seat_count, 0)
  )
  INTO v_cap
  FROM public.organization_subscriptions os
  WHERE os.organization_id = NEW.organization_id;

  IF v_cap IS NULL THEN
    v_cap := 0;
  END IF;

  SELECT count(*)::integer
  INTO v_current
  FROM public.organization_omnichannel_staff s
  WHERE s.organization_id = NEW.organization_id;

  IF v_current >= v_cap THEN
    RAISE EXCEPTION 'Omnichannel roster seat limit reached';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."organization_omnichannel_staff_validate_employee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."outlet_operating_cap"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_self_service boolean;
  v_trial boolean := false;
  v_paid integer := 0;
  v_sales_quota integer;
  v_pos boolean := false;
BEGIN
  SELECT coalesce(o.subscription_self_service_enabled, true)
  INTO v_self_service
  FROM public.organizations o
  WHERE o.id = p_organization_id;

  IF NOT FOUND THEN
    RETURN 1;
  END IF;

  SELECT
    coalesce(os.is_trial, false),
    coalesce(os.pos_paid_outlet_count, 0),
    os.sales_outlet_quota
  INTO v_trial, v_paid, v_sales_quota
  FROM public.organization_subscriptions os
  WHERE os.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RETURN 1;
  END IF;

  IF v_self_service IS DISTINCT FROM false OR v_sales_quota IS NULL THEN
    IF v_trial THEN
      RETURN 1;
    END IF;
    RETURN 1 + GREATEST(v_paid, 0);
  END IF;

  SELECT coalesce(m.is_enabled, false)
  INTO v_pos
  FROM public.organization_sales_module_access m
  WHERE m.organization_id = p_organization_id
    AND m.module_key = 'pos';

  IF NOT coalesce(v_pos, false) THEN
    RETURN 0;
  END IF;

  RETURN GREATEST(v_sales_quota, 0);
END;
$$;


ALTER FUNCTION "public"."outlet_operating_cap"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pause_flow_enrollments_on_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
    AND (OLD.assignee_id IS NULL OR TRIM(COALESCE(OLD.assignee_id::text, '')) = '')
    AND NEW.assignee_id IS NOT NULL
    AND TRIM(NEW.assignee_id::text) <> ''
  THEN
    UPDATE public.omnichannel_flow_enrollments e
    SET
      status = 'paused',
      paused_reason = 'assignee_taken_over',
      updated_at = now()
    WHERE e.conversation_id = NEW.id
      AND e.status IN ('active', 'waiting_for_reply');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."pause_flow_enrollments_on_assignee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pause_lead_magnet_enrollments_on_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
    AND (OLD.assignee_id IS NULL OR TRIM(COALESCE(OLD.assignee_id::text, '')) = '')
    AND NEW.assignee_id IS NOT NULL
    AND TRIM(NEW.assignee_id::text) <> ''
  THEN
    UPDATE public.lead_magnet_enrollments e
    SET
      status = 'paused',
      paused_reason = 'assignee_taken_over',
      updated_at = now()
    WHERE e.conversation_id = NEW.id
      AND e.conversation_table = TG_ARGV[0]
      AND e.status NOT IN ('delivered', 'failed', 'paused');
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."pause_lead_magnet_enrollments_on_assignee"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_employee"("p_run_id" "uuid", "p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_info record;
  v_tax_config record;
  v_ratio numeric;
  v_basic_prorated numeric;
  v_allowances numeric := 0;
  v_deductions numeric := 0;
  v_penalties numeric := 0;
  v_overtime_pay numeric := 0;
  v_thr_amount numeric := 0;
  v_has_thr_component boolean := false;
  v_gross numeric;
  v_non_taxable_annual numeric := 0;
  v_tax jsonb;
  v_calc_mode text := 'annualized';
  v_effective_year integer;
  v_monthly_tax numeric;
  v_employer_tax numeric;
  v_bpjs_k numeric;
  v_bpjs_p numeric;
  v_take_home numeric;
  v_target numeric;
  v_comp record;
  v_fixed_allowance numeric := 0;
  v_resolved numeric;
  v_calc_id uuid;
  v_line_items jsonb := '[]'::jsonb;
  v_penalty_ids uuid[] := ARRAY[]::uuid[];
  v_payout_snapshot jsonb;
BEGIN
  SELECT pr.*, pp.start_date, pp.end_date, pp.id AS period_id, pp.pay_date,
         COALESCE(pp.is_bonus_period, false) AS is_bonus_period
  INTO v_run
  FROM public.payroll_runs pr
  JOIN public.payroll_periods pp ON pp.id = pr.payroll_period_id
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RAISE EXCEPTION 'Payroll run not found' USING ERRCODE = 'P0001';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = p_employee_id
      AND e.organization_id = v_run.organization_id
      AND COALESCE(e.is_ai, false)
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'ai employee');
  END IF;

  SELECT epi.*, e.full_name, e.join_date, e.hire_date
  INTO v_info
  FROM public.employee_payroll_info epi
  JOIN public.employees e ON e.id = epi.employee_id
  WHERE epi.employee_id = p_employee_id
    AND epi.organization_id = v_run.organization_id;

  IF v_info IS NULL OR COALESCE(v_info.basic_salary, 0) <= 0 THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'missing payroll info');
  END IF;

  IF v_info.tax_configuration_id IS NOT NULL THEN
    SELECT tc.calculation_mode INTO v_calc_mode
    FROM public.tax_configurations tc
    WHERE tc.id = v_info.tax_configuration_id;
  END IF;
  v_calc_mode := COALESCE(v_calc_mode, 'annualized');
  v_effective_year := EXTRACT(YEAR FROM v_run.end_date)::integer;

  v_ratio := public.payroll_employee_prorate_ratio(
    v_run.organization_id, v_run.start_date, v_run.end_date, p_employee_id,
    COALESCE(v_info.count_national_holiday_as_working_day, false)
  );

  IF v_ratio <= 0 THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'zero effective working days');
  END IF;

  v_basic_prorated := round(COALESCE(v_info.basic_salary, 0) * v_ratio);

  SELECT EXISTS (
    SELECT 1 FROM public.employee_payroll_components c
    WHERE c.employee_payroll_info_id = v_info.id
      AND c.is_active IS NOT DISTINCT FROM true
      AND c.component_type = 'allowance'
      AND lower(COALESCE(c.component_category, c.component_name, '')) LIKE '%thr%'
      AND (c.payroll_period_id IS NULL OR c.payroll_period_id = v_run.payroll_period_id)
  ) INTO v_has_thr_component;

  IF v_run.is_bonus_period AND NOT v_has_thr_component THEN
    v_thr_amount := public.payroll_calculate_thr_amount(
      v_run.organization_id, p_employee_id, COALESCE(v_info.basic_salary, 0), v_run.end_date
    );
    IF v_thr_amount > 0 THEN
      v_allowances := v_allowances + v_thr_amount;
      v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
        'item_name', 'THR',
        'item_type', 'allowance',
        'item_category', 'thr',
        'calculated_amount', v_thr_amount
      ));
    END IF;
  END IF;

  FOR v_comp IN
    SELECT c.* FROM public.employee_payroll_components c
    WHERE c.employee_payroll_info_id = v_info.id
      AND c.is_active IS NOT DISTINCT FROM true
      AND c.component_type = 'allowance'
      AND COALESCE(c.is_percentage, false) = false
      AND ((COALESCE(c.is_recurring, true) = true AND c.payroll_period_id IS NULL)
           OR c.payroll_period_id = v_run.payroll_period_id)
  LOOP
    v_resolved := round(COALESCE(v_comp.amount, 0));
    v_allowances := v_allowances + v_resolved;
    v_fixed_allowance := v_fixed_allowance + v_resolved;
    IF COALESCE(v_comp.is_taxable, true) = false THEN
      v_non_taxable_annual := v_non_taxable_annual + v_resolved * 12;
    END IF;
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'component_id', v_comp.id, 'item_name', v_comp.component_name,
      'item_type', 'allowance', 'item_category', v_comp.component_category,
      'calculated_amount', v_resolved
    ));
  END LOOP;

  FOR v_comp IN
    SELECT c.* FROM public.employee_payroll_components c
    WHERE c.employee_payroll_info_id = v_info.id
      AND c.is_active IS NOT DISTINCT FROM true
      AND c.component_type = 'allowance'
      AND COALESCE(c.is_percentage, false) = true
      AND ((COALESCE(c.is_recurring, true) = true AND c.payroll_period_id IS NULL)
           OR c.payroll_period_id = v_run.payroll_period_id)
  LOOP
    IF COALESCE(v_comp.percentage_base, 'basic_salary') = 'gross_salary' THEN
      v_resolved := round((COALESCE(v_comp.amount, 0) / 100.0) * (v_basic_prorated + v_fixed_allowance));
    ELSE
      v_resolved := round((COALESCE(v_comp.amount, 0) / 100.0) * v_basic_prorated);
    END IF;
    v_allowances := v_allowances + v_resolved;
    IF COALESCE(v_comp.is_taxable, true) = false THEN
      v_non_taxable_annual := v_non_taxable_annual + v_resolved * 12;
    END IF;
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'component_id', v_comp.id, 'item_name', v_comp.component_name,
      'item_type', 'allowance', 'item_category', v_comp.component_category,
      'calculated_amount', v_resolved
    ));
  END LOOP;

  IF COALESCE(v_info.overtime_eligible, false) THEN
    v_overtime_pay := (public.payroll_calculate_overtime_pay(
      v_run.organization_id, p_employee_id, v_run.start_date, v_run.end_date, v_basic_prorated
    )->>'overtimePay')::numeric;
    v_allowances := v_allowances + v_overtime_pay;
    IF v_overtime_pay > 0 THEN
      v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
        'item_name', 'Lembur', 'item_type', 'allowance',
        'item_category', 'overtime', 'calculated_amount', v_overtime_pay
      ));
    END IF;
  END IF;

  FOR v_comp IN
    SELECT c.* FROM public.employee_payroll_components c
    WHERE c.employee_payroll_info_id = v_info.id
      AND c.is_active IS NOT DISTINCT FROM true
      AND c.component_type = 'deduction'
      AND ((COALESCE(c.is_recurring, true) = true AND c.payroll_period_id IS NULL)
           OR c.payroll_period_id = v_run.payroll_period_id)
  LOOP
    IF COALESCE(v_comp.is_percentage, false) THEN
      IF COALESCE(v_comp.percentage_base, 'basic_salary') = 'gross_salary' THEN
        v_resolved := round((COALESCE(v_comp.amount, 0) / 100.0) * (v_basic_prorated + v_allowances));
      ELSE
        v_resolved := round((COALESCE(v_comp.amount, 0) / 100.0) * v_basic_prorated);
      END IF;
    ELSE
      v_resolved := round(COALESCE(v_comp.amount, 0));
    END IF;
    v_deductions := v_deductions + v_resolved;
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'component_id', v_comp.id, 'item_name', v_comp.component_name,
      'item_type', 'deduction', 'item_category', v_comp.component_category,
      'calculated_amount', v_resolved
    ));
  END LOOP;

  FOR v_comp IN
    SELECT ap.id, ap.penalty_amount, ap.penalty_reason
    FROM public.attendance_penalties ap
    WHERE ap.employee_id = p_employee_id
      AND ap.organization_id = v_run.organization_id
      AND ap.status = 'active'
      AND (ap.payroll_periods_id = v_run.payroll_period_id
           OR (ap.payroll_periods_id IS NULL
               AND ap.applied_date BETWEEN v_run.start_date AND v_run.end_date))
  LOOP
    v_penalties := v_penalties + COALESCE(v_comp.penalty_amount, 0);
    v_penalty_ids := array_append(v_penalty_ids, v_comp.id);
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'item_name', COALESCE(v_comp.penalty_reason, 'Penalty'),
      'item_type', 'deduction', 'item_category', 'penalty',
      'calculated_amount', round(COALESCE(v_comp.penalty_amount, 0))
    ));
  END LOOP;

  v_gross := v_basic_prorated + v_allowances;
  v_target := GREATEST(0, v_gross - v_deductions - v_penalties);

  IF v_calc_mode = 'ter' THEN
    v_tax := public.payroll_calculate_pph21_ter_v2(
      v_gross,
      COALESCE(v_info.employee_tax_status, 'pegawai_tetap'),
      COALESCE(v_info.ptkp_status, 'TK/0'),
      v_effective_year
    );
  ELSE
    v_tax := public.payroll_calculate_tax_by_method(
      v_gross,
      COALESCE(v_info.ptkp_status, 'TK/0'),
      COALESCE(v_info.tax_method, 'gross'),
      NULL,
      v_non_taxable_annual,
      CASE WHEN COALESCE(v_info.tax_method, 'gross') IN ('netto', 'gross_up') THEN v_target ELSE NULL END
    );
    v_tax := v_tax || jsonb_build_object('calculationMode', 'annualized');
  END IF;

  v_monthly_tax := COALESCE((v_tax->>'monthlyTax')::numeric, 0);
  v_employer_tax := COALESCE((v_tax->>'employerTaxCost')::numeric, 0);
  v_bpjs_k := COALESCE((v_tax->>'monthlyBpjsKesehatan')::numeric, 0);
  v_bpjs_p := COALESCE((v_tax->>'monthlyBpjsPensiun')::numeric, 0);

  IF v_bpjs_k > 0 THEN
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'item_name', 'BPJS Kesehatan', 'item_type', 'deduction',
      'item_category', 'bpjs_kesehatan', 'calculated_amount', round(v_bpjs_k)
    ));
  END IF;
  IF v_bpjs_p > 0 THEN
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'item_name', 'BPJS Pensiun', 'item_type', 'deduction',
      'item_category', 'bpjs_pensiun', 'calculated_amount', round(v_bpjs_p)
    ));
  END IF;
  IF v_monthly_tax + v_employer_tax > 0 THEN
    v_line_items := v_line_items || jsonb_build_array(jsonb_build_object(
      'item_name', CASE WHEN COALESCE(v_info.tax_method, 'gross') = 'gross_up'
        THEN 'PPh 21 (Ditanggung Perusahaan)' ELSE 'PPh 21' END,
      'item_type', 'tax', 'item_category', 'pph21',
      'calculated_amount', round(v_monthly_tax + v_employer_tax)
    ));
  END IF;

  IF COALESCE(v_info.tax_method, 'gross') = 'gross_up' AND v_calc_mode <> 'ter' THEN
    v_take_home := v_target;
  ELSE
    v_take_home := round(
      COALESCE((v_tax->>'takeHomePay')::numeric, v_gross - v_monthly_tax - v_bpjs_k - v_bpjs_p)
      - v_deductions - v_penalties
    );
  END IF;

  v_payout_snapshot := jsonb_build_object(
    'bank_name', v_info.bank_name,
    'account_number', v_info.bank_account_number,
    'account_holder', v_info.bank_account_holder
  );

  INSERT INTO public.employee_payroll_calculations (
    organization_id, employee_id, employee_payroll_info_id,
    payroll_period_id, payroll_run_id, tax_configuration_id,
    basic_salary, total_allowances, total_deductions, total_penalties,
    total_tax_deductions, gross_pay, net_pay, take_home_pay,
    total_taxes, total_tax_amount, tax_breakdown, calculation_details,
    payout_snapshot, calculation_status, payment_status
  ) VALUES (
    v_run.organization_id, p_employee_id, v_info.id,
    v_run.payroll_period_id, p_run_id, v_info.tax_configuration_id,
    v_basic_prorated, round(v_allowances), round(v_deductions + v_bpjs_k + v_bpjs_p + v_monthly_tax),
    round(v_penalties), round(v_monthly_tax + v_employer_tax),
    round(CASE WHEN COALESCE(v_info.tax_method, 'gross') = 'gross' OR v_calc_mode = 'ter'
      THEN v_gross ELSE COALESCE((v_tax->>'imputedMonthlyGross')::numeric, v_gross) END),
    v_take_home, v_take_home,
    (round(v_monthly_tax + v_employer_tax))::text,
    round(v_monthly_tax + v_employer_tax),
    v_tax->'taxBreakdown',
    jsonb_build_object(
      'taxMethod', COALESCE(v_info.tax_method, 'gross'),
      'calculationMode', v_calc_mode,
      'terCategory', v_tax->>'terCategory',
      'terRate', v_tax->>'terRate',
      'prorateRatio', v_ratio,
      'overtimePay', v_overtime_pay,
      'thrAmount', v_thr_amount,
      'penaltyIds', to_jsonb(v_penalty_ids)
    ),
    v_payout_snapshot, 'calculated', 'pending'
  )
  ON CONFLICT (employee_payroll_info_id, payroll_run_id)
  DO UPDATE SET
    basic_salary = EXCLUDED.basic_salary,
    total_allowances = EXCLUDED.total_allowances,
    total_deductions = EXCLUDED.total_deductions,
    total_penalties = EXCLUDED.total_penalties,
    total_tax_deductions = EXCLUDED.total_tax_deductions,
    gross_pay = EXCLUDED.gross_pay,
    net_pay = EXCLUDED.net_pay,
    take_home_pay = EXCLUDED.take_home_pay,
    total_taxes = EXCLUDED.total_taxes,
    total_tax_amount = EXCLUDED.total_tax_amount,
    tax_breakdown = EXCLUDED.tax_breakdown,
    calculation_details = EXCLUDED.calculation_details,
    payout_snapshot = EXCLUDED.payout_snapshot,
    calculation_status = 'calculated',
    updated_at = now()
  RETURNING id INTO v_calc_id;

  DELETE FROM public.payroll_items WHERE payroll_calculation_id = v_calc_id;

  INSERT INTO public.payroll_items (
    organization_id, payroll_calculation_id, component_id,
    item_name, item_type, item_category, calculated_amount
  )
  SELECT v_run.organization_id, v_calc_id,
    NULLIF(elem->>'component_id', '')::uuid,
    elem->>'item_name', elem->>'item_type', elem->>'item_category',
    (elem->>'calculated_amount')::numeric
  FROM jsonb_array_elements(v_line_items) AS elem;

  IF array_length(v_penalty_ids, 1) IS NOT NULL THEN
    UPDATE public.attendance_penalties ap
    SET status = 'paid', payment_date = COALESCE(v_run.pay_date, CURRENT_DATE), updated_at = now()
    WHERE ap.id = ANY (v_penalty_ids) AND ap.status = 'active';
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'calculationId', v_calc_id,
    'takeHomePay', v_take_home, 'grossPay', v_gross
  );
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_employee"("p_run_id" "uuid", "p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_overtime_pay"("p_org_id" "uuid", "p_employee_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_basic_salary" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_hourly numeric;
  v_total_minutes integer := 0;
  v_total_pay numeric := 0;
  v_scheduled_end time;
  v_threshold integer := 0;
  v_rec record;
  v_sched record;
  v_attendance_date date;
  v_raw_minutes integer;
  v_hours numeric;
  v_first_hour numeric;
  v_next_hours numeric;
BEGIN
  v_hourly := COALESCE(p_basic_salary, 0) / 173;

  FOR v_rec IN
    SELECT ar.attendance_date,
           ar.check_out_time,
           ar.check_out_at
    FROM public.attendance_records ar
    WHERE ar.employee_id = p_employee_id
      AND ar.organization_id = p_org_id
      AND COALESCE(ar.attendance_date, ar.check_in_at::date) BETWEEN p_period_start AND p_period_end
      AND (ar.check_out_time IS NOT NULL OR ar.check_out_at IS NOT NULL)
  LOOP
    v_attendance_date := COALESCE(v_rec.attendance_date, v_rec.check_out_at::date);

    SELECT *
    INTO v_sched
    FROM public.resolve_effective_schedule(
      p_employee_id,
      p_org_id,
      v_attendance_date
    ) r
    LIMIT 1;

    v_scheduled_end := COALESCE(v_sched.end_time::time, '17:00:00'::time);

    IF v_sched.source = 'shift' AND COALESCE(v_sched.break_duration_minutes, 0) > 0 THEN
      v_scheduled_end := v_scheduled_end + (v_sched.break_duration_minutes || ' minutes')::interval;
    END IF;

    v_threshold := COALESCE(v_sched.overtime_threshold_minutes, 0);

    v_raw_minutes := GREATEST(
      0,
      (
        EXTRACT(EPOCH FROM (
          COALESCE(v_rec.check_out_time, v_rec.check_out_at::time)
          - v_scheduled_end
        )) / 60
      )::integer - v_threshold
    );

    IF v_raw_minutes > 0 THEN
      v_total_minutes := v_total_minutes + v_raw_minutes;
    END IF;
  END LOOP;

  IF v_total_minutes <= 0 THEN
    RETURN jsonb_build_object('overtimePay', 0, 'totalMinutes', 0);
  END IF;

  v_hours := v_total_minutes / 60.0;
  v_first_hour := LEAST(1, v_hours);
  v_next_hours := GREATEST(0, v_hours - 1);
  v_total_pay := round(v_first_hour * v_hourly * 1.5 + v_next_hours * v_hourly * 2);

  RETURN jsonb_build_object(
    'overtimePay', v_total_pay,
    'totalMinutes', v_total_minutes
  );
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_overtime_pay"("p_org_id" "uuid", "p_employee_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_basic_salary" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_pph21_annualized"("p_monthly_gross" numeric, "p_ptkp_status" "text" DEFAULT 'TK/0'::"text", "p_custom_ptkp" numeric DEFAULT NULL::numeric, "p_non_taxable_annual" numeric DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_gross numeric := GREATEST(COALESCE(p_monthly_gross, 0), 0);
  v_annual_gross numeric;
  v_professional numeric;
  v_bpjs_k_annual numeric := 0;
  v_bpjs_p_annual numeric := 0;
  v_bpjs_k_monthly numeric := 0;
  v_bpjs_p_monthly numeric := 0;
  v_net_income numeric;
  v_ptkp numeric;
  v_pkp numeric;
  v_remaining numeric;
  v_tax numeric := 0;
  v_bracket_tax numeric;
  v_bracket_size numeric;
  v_taxable numeric;
  v_breakdown jsonb := '[]'::jsonb;
  v_i integer;
  v_min numeric;
  v_max numeric;
  v_rate numeric;
BEGIN
  v_annual_gross := v_gross * 12;
  v_professional := LEAST(v_annual_gross * 0.05, 6000000);

  v_bpjs_k_monthly := LEAST(v_gross, 12000000) * 0.02;
  v_bpjs_p_monthly := LEAST(v_gross, 8930600) * 0.01;
  v_bpjs_k_annual := v_bpjs_k_monthly * 12;
  v_bpjs_p_annual := v_bpjs_p_monthly * 12;

  v_net_income := v_annual_gross - v_professional - v_bpjs_k_annual - v_bpjs_p_annual;
  v_ptkp := public.payroll_ptkp_amount(p_ptkp_status, p_custom_ptkp);
  v_pkp := GREATEST(0, v_net_income - v_ptkp - GREATEST(COALESCE(p_non_taxable_annual, 0), 0));
  v_remaining := v_pkp;

  FOR v_i IN 1..4 LOOP
    EXIT WHEN v_remaining <= 0;
    CASE v_i
      WHEN 1 THEN v_min := 0; v_max := 60000000; v_rate := 0.05;
      WHEN 2 THEN v_min := 60000000; v_max := 250000000; v_rate := 0.15;
      WHEN 3 THEN v_min := 250000000; v_max := 500000000; v_rate := 0.25;
      ELSE v_min := 500000000; v_max := 999999999999; v_rate := 0.30;
    END CASE;
    v_bracket_size := v_max - v_min;
    IF v_i = 4 THEN
      v_taxable := v_remaining;
    ELSE
      v_taxable := LEAST(v_remaining, v_bracket_size);
    END IF;
    IF v_taxable > 0 THEN
      v_bracket_tax := v_taxable * v_rate;
      v_tax := v_tax + v_bracket_tax;
      v_breakdown := v_breakdown || jsonb_build_array(
        jsonb_build_object(
          'bracket', v_min::text || ' - ' || CASE WHEN v_i = 4 THEN '∞' ELSE v_max::text END,
          'amount', round(v_taxable),
          'tax', round(v_bracket_tax),
          'rate', v_rate * 100
        )
      );
      v_remaining := v_remaining - v_taxable;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'annualGross', round(v_annual_gross),
    'professionalAllowance', round(v_professional),
    'bpjsKesehatanEmployee', round(v_bpjs_k_annual),
    'bpjsPensiunEmployee', round(v_bpjs_p_annual),
    'monthlyBpjsKesehatan', round(v_bpjs_k_monthly),
    'monthlyBpjsPensiun', round(v_bpjs_p_monthly),
    'netIncome', round(v_net_income),
    'ptkpAmount', round(v_ptkp),
    'pkpAmount', round(v_pkp),
    'annualTax', round(v_tax),
    'monthlyTax', round(v_tax / 12),
    'takeHomePay', round(v_gross - (v_tax / 12) - v_bpjs_k_monthly - v_bpjs_p_monthly),
    'taxBreakdown', v_breakdown
  );
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_pph21_annualized"("p_monthly_gross" numeric, "p_ptkp_status" "text", "p_custom_ptkp" numeric, "p_non_taxable_annual" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_pph21_ter_v2"("p_monthly_gross" numeric, "p_employee_tax_status" "text" DEFAULT 'pegawai_tetap'::"text", "p_ptkp_status" "text" DEFAULT 'TK/0'::"text", "p_effective_year" integer DEFAULT 2024) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_gross numeric := GREATEST(COALESCE(p_monthly_gross, 0), 0);
  v_category text;
  v_rate numeric := 0;
  v_bracket record;
  v_tax numeric;
  v_bpjs_k numeric;
  v_bpjs_p numeric;
BEGIN
  v_category := public.payroll_ter_category_for_employee(p_employee_tax_status, p_ptkp_status);

  SELECT b.ter_rate, b.min_monthly_income, b.max_monthly_income
  INTO v_bracket
  FROM public.payroll_ter_brackets b
  WHERE b.category_code = v_category
    AND b.effective_year = p_effective_year
    AND v_gross >= b.min_monthly_income
    AND (b.max_monthly_income IS NULL OR v_gross <= b.max_monthly_income)
  ORDER BY b.min_monthly_income DESC
  LIMIT 1;

  v_rate := COALESCE(v_bracket.ter_rate, 0);
  v_tax := round(v_gross * v_rate);
  v_bpjs_k := round(LEAST(v_gross, 12000000) * 0.02);
  v_bpjs_p := round(LEAST(v_gross, 8930600) * 0.01);

  RETURN jsonb_build_object(
    'taxMethod', 'ter',
    'calculationMode', 'ter',
    'terCategory', v_category,
    'terRate', v_rate,
    'bracketMin', v_bracket.min_monthly_income,
    'bracketMax', v_bracket.max_monthly_income,
    'monthlyTax', v_tax,
    'monthlyBpjsKesehatan', v_bpjs_k,
    'monthlyBpjsPensiun', v_bpjs_p,
    'takeHomePay', round(v_gross - v_tax - v_bpjs_k - v_bpjs_p),
    'imputedMonthlyGross', round(v_gross),
    'employerTaxCost', 0,
    'taxBreakdown', jsonb_build_array(
      jsonb_build_object(
        'bracket', COALESCE(v_bracket.min_monthly_income::text, '0') || ' - ' || COALESCE(v_bracket.max_monthly_income::text, '∞'),
        'amount', round(v_gross),
        'tax', v_tax,
        'rate', v_rate * 100
      )
    )
  );
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_pph21_ter_v2"("p_monthly_gross" numeric, "p_employee_tax_status" "text", "p_ptkp_status" "text", "p_effective_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_tax_by_method"("p_gross" numeric, "p_ptkp_status" "text", "p_tax_method" "text", "p_custom_ptkp" numeric DEFAULT NULL::numeric, "p_non_taxable_annual" numeric DEFAULT 0, "p_target_take_home" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_method text := COALESCE(p_tax_method, 'gross');
  v_result jsonb;
  v_target numeric;
  v_low numeric;
  v_high numeric;
  v_mid numeric;
  v_thp numeric;
  v_i integer;
  v_imputed numeric;
  v_monthly_tax numeric;
BEGIN
  IF v_method = 'gross' THEN
    v_result := public.payroll_calculate_pph21_annualized(
      p_gross, p_ptkp_status, p_custom_ptkp, p_non_taxable_annual
    );
    RETURN v_result || jsonb_build_object(
      'taxMethod', 'gross',
      'imputedMonthlyGross', round(p_gross),
      'employerTaxCost', 0
    );
  END IF;

  v_target := COALESCE(p_target_take_home, p_gross);
  v_low := GREATEST(v_target, 0);
  v_high := GREATEST(v_target * 2, v_target + 1000000);

  FOR v_i IN 1..20 LOOP
    v_mid := (v_low + v_high) / 2;
    v_result := public.payroll_calculate_pph21_annualized(
      v_mid, p_ptkp_status, p_custom_ptkp, p_non_taxable_annual
    );
    IF v_method = 'gross_up' THEN
      v_thp := v_mid
        - (v_result->>'monthlyBpjsKesehatan')::numeric
        - (v_result->>'monthlyBpjsPensiun')::numeric;
    ELSE
      v_thp := (v_result->>'takeHomePay')::numeric;
    END IF;

    IF abs(v_thp - v_target) <= 100 THEN
      EXIT;
    ELSIF v_thp < v_target THEN
      v_low := v_mid;
    ELSE
      v_high := v_mid;
    END IF;
  END LOOP;

  v_imputed := v_mid;
  v_result := public.payroll_calculate_pph21_annualized(
    v_imputed, p_ptkp_status, p_custom_ptkp, p_non_taxable_annual
  );
  v_monthly_tax := (v_result->>'monthlyTax')::numeric;

  IF v_method = 'gross_up' THEN
    RETURN v_result || jsonb_build_object(
      'taxMethod', 'gross_up',
      'imputedMonthlyGross', round(v_imputed),
      'employerTaxCost', round(v_monthly_tax),
      'monthlyTax', 0,
      'takeHomePay', round(
        v_imputed
        - (v_result->>'monthlyBpjsKesehatan')::numeric
        - (v_result->>'monthlyBpjsPensiun')::numeric
      )
    );
  END IF;

  RETURN v_result || jsonb_build_object(
    'taxMethod', 'netto',
    'imputedMonthlyGross', round(v_imputed),
    'employerTaxCost', 0
  );
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_tax_by_method"("p_gross" numeric, "p_ptkp_status" "text", "p_tax_method" "text", "p_custom_ptkp" numeric, "p_non_taxable_annual" numeric, "p_target_take_home" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_calculate_thr_amount"("p_org_id" "uuid", "p_employee_id" "uuid", "p_basic_salary" numeric, "p_period_end" "date") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_mode text;
  v_join date;
  v_year integer;
  v_months integer;
  v_year_start date;
BEGIN
  SELECT COALESCE(o.payroll_thr_calculation_mode, 'proportional')
  INTO v_mode
  FROM public.organizations o
  WHERE o.id = p_org_id;

  IF v_mode = 'manual_only' THEN
    RETURN 0;
  END IF;

  IF v_mode = 'full_month_salary' THEN
    RETURN round(GREATEST(COALESCE(p_basic_salary, 0), 0));
  END IF;

  SELECT COALESCE(e.join_date, e.hire_date)
  INTO v_join
  FROM public.employees e
  WHERE e.id = p_employee_id;

  v_year := EXTRACT(YEAR FROM p_period_end)::integer;
  v_year_start := make_date(v_year, 1, 1);

  IF v_join IS NULL OR v_join <= v_year_start THEN
    v_months := 12;
  ELSIF EXTRACT(YEAR FROM v_join)::integer > v_year THEN
    RETURN 0;
  ELSE
    v_months := GREATEST(
      1,
      (EXTRACT(YEAR FROM p_period_end)::integer * 12 + EXTRACT(MONTH FROM p_period_end)::integer)
      - (EXTRACT(YEAR FROM v_join)::integer * 12 + EXTRACT(MONTH FROM v_join)::integer)
      + 1
    );
    v_months := LEAST(12, v_months);
  END IF;

  RETURN round(GREATEST(COALESCE(p_basic_salary, 0), 0) * v_months / 12.0);
END;
$$;


ALTER FUNCTION "public"."payroll_calculate_thr_amount"("p_org_id" "uuid", "p_employee_id" "uuid", "p_basic_salary" numeric, "p_period_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_count_shift_assigned_working_days"("p_org_id" "uuid", "p_employee_id" "uuid", "p_start" "date", "p_end" "date", "p_count_holiday_as_working" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_count integer := 0;
  v_d date;
  v_sched record;
  v_is_holiday boolean;
BEGIN
  IF p_start IS NULL OR p_end IS NULL OR p_start > p_end THEN
    RETURN 0;
  END IF;

  v_d := p_start;
  WHILE v_d <= p_end LOOP
    SELECT *
    INTO v_sched
    FROM public.resolve_effective_schedule(
      p_employee_id,
      p_org_id,
      v_d
    ) r
    LIMIT 1;

    IF COALESCE(v_sched.is_working_day, false)
       AND v_sched.source = 'shift' THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.national_holidays nh
        WHERE nh.date = v_d
          AND nh.is_active IS NOT DISTINCT FROM true
          AND nh.applies_to_attendance IS NOT DISTINCT FROM true
          AND (nh.organization_id IS NULL OR nh.organization_id = p_org_id)
      ) INTO v_is_holiday;

      IF p_count_holiday_as_working OR NOT v_is_holiday THEN
        v_count := v_count + 1;
      END IF;
    END IF;

    v_d := v_d + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."payroll_count_shift_assigned_working_days"("p_org_id" "uuid", "p_employee_id" "uuid", "p_start" "date", "p_end" "date", "p_count_holiday_as_working" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_count_working_days"("p_org_id" "uuid", "p_start" "date", "p_end" "date", "p_working_days" integer[], "p_count_holiday_as_working" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_count integer := 0;
  v_d date;
  v_app_dow integer;
  v_is_holiday boolean;
BEGIN
  IF p_start IS NULL OR p_end IS NULL OR p_start > p_end THEN
    RETURN 0;
  END IF;

  v_d := p_start;
  WHILE v_d <= p_end LOOP
    v_app_dow := public.pg_dow_to_app_dow(EXTRACT(DOW FROM v_d)::integer);
    IF v_app_dow = ANY (COALESCE(p_working_days, ARRAY[1, 2, 3, 4, 5])) THEN
      SELECT EXISTS (
        SELECT 1
        FROM public.national_holidays nh
        WHERE nh.date = v_d
          AND nh.is_active IS NOT DISTINCT FROM true
          AND nh.applies_to_attendance IS NOT DISTINCT FROM true
          AND (nh.organization_id IS NULL OR nh.organization_id = p_org_id)
      ) INTO v_is_holiday;

      IF p_count_holiday_as_working OR NOT v_is_holiday THEN
        v_count := v_count + 1;
      END IF;
    END IF;
    v_d := v_d + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."payroll_count_working_days"("p_org_id" "uuid", "p_start" "date", "p_end" "date", "p_working_days" integer[], "p_count_holiday_as_working" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_employee_prorate_ratio"("p_org_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_employee_id" "uuid", "p_count_holiday_as_working" boolean DEFAULT false) RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_working_days integer[];
  v_emp_wss_id uuid;
  v_join date;
  v_total integer;
  v_effective integer;
  v_eff_start date;
  v_eff_end date;
  v_has_shift_assignment boolean := false;
BEGIN
  SELECT e.work_schedule_id, COALESCE(e.join_date, e.hire_date)
  INTO v_emp_wss_id, v_join
  FROM public.employees e
  WHERE e.id = p_employee_id;

  IF v_emp_wss_id IS NOT NULL THEN
    SELECT COALESCE(ws.working_days, ARRAY[1, 2, 3, 4, 5])
    INTO v_working_days
    FROM public.work_schedule_settings ws
    WHERE ws.id = v_emp_wss_id
      AND ws.organization_id = p_org_id
      AND ws.is_active IS NOT DISTINCT FROM true;
  END IF;

  IF v_working_days IS NULL THEN
    SELECT COALESCE(ws.working_days, ARRAY[1, 2, 3, 4, 5])
    INTO v_working_days
    FROM public.work_schedule_settings ws
    WHERE ws.organization_id = p_org_id
      AND ws.is_active IS NOT DISTINCT FROM true
    ORDER BY ws.is_default DESC NULLS LAST, ws.created_at
    LIMIT 1;
  END IF;

  IF v_working_days IS NULL THEN
    v_working_days := ARRAY[1, 2, 3, 4, 5];
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.employee_shifts es
    WHERE es.employee_id = p_employee_id
      AND es.organization_id = p_org_id
      AND COALESCE(es.is_active, true)
      AND es.effective_from_date <= p_period_end
      AND (es.effective_to_date IS NULL OR es.effective_to_date >= p_period_start)
  )
  INTO v_has_shift_assignment;

  v_eff_start := p_period_start;
  v_eff_end := p_period_end;

  IF v_join IS NOT NULL AND v_join > v_eff_start THEN
    v_eff_start := v_join;
  END IF;

  IF v_eff_start > v_eff_end THEN
    RETURN 0;
  END IF;

  IF v_has_shift_assignment THEN
    v_total := public.payroll_count_shift_assigned_working_days(
      p_org_id, p_employee_id, p_period_start, p_period_end, p_count_holiday_as_working
    );
    v_effective := public.payroll_count_shift_assigned_working_days(
      p_org_id, p_employee_id, v_eff_start, v_eff_end, p_count_holiday_as_working
    );
  ELSE
    v_total := public.payroll_count_working_days(
      p_org_id, p_period_start, p_period_end, v_working_days, p_count_holiday_as_working
    );
    v_effective := public.payroll_count_working_days(
      p_org_id, v_eff_start, v_eff_end, v_working_days, p_count_holiday_as_working
    );
  END IF;

  IF v_total <= 0 THEN
    RETURN 1;
  END IF;

  RETURN LEAST(1, v_effective::numeric / v_total::numeric);
END;
$$;


ALTER FUNCTION "public"."payroll_employee_prorate_ratio"("p_org_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_employee_id" "uuid", "p_count_holiday_as_working" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_log_audit"("p_org_id" "uuid", "p_run_id" "uuid", "p_calc_id" "uuid", "p_action" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.payroll_audit_log (
    organization_id, payroll_run_id, employee_calculation_id,
    action, actor_user_id, metadata
  ) VALUES (
    p_org_id, p_run_id, p_calc_id,
    p_action, auth.uid(), COALESCE(p_metadata, '{}'::jsonb)
  );
END;
$$;


ALTER FUNCTION "public"."payroll_log_audit"("p_org_id" "uuid", "p_run_id" "uuid", "p_calc_id" "uuid", "p_action" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_ptkp_amount"("p_ptkp_status" "text", "p_custom" numeric DEFAULT NULL::numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    NULLIF(p_custom, 0),
    CASE COALESCE(p_ptkp_status, 'TK/0')
      WHEN 'TK/0' THEN 54000000
      WHEN 'TK/1' THEN 58500000
      WHEN 'TK/2' THEN 63000000
      WHEN 'TK/3' THEN 67500000
      WHEN 'K/0' THEN 58500000
      WHEN 'K/1' THEN 63000000
      WHEN 'K/2' THEN 67500000
      WHEN 'K/3' THEN 72000000
      ELSE 54000000
    END
  );
$$;


ALTER FUNCTION "public"."payroll_ptkp_amount"("p_ptkp_status" "text", "p_custom" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_run_transfer_in_flight"("p_run_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  -- Jumlah kalkulasi (belum 'paid') di run ini yang uangnya sedang atau sudah dikirim.
  SELECT count(*)::integer
  FROM public.employee_payroll_calculations c
  WHERE c.payroll_run_id = p_run_id
    AND c.payment_status IS DISTINCT FROM 'paid'
    AND (
      c.payment_status = 'processing'
      OR EXISTS (
        SELECT 1 FROM public.xendit_disbursements x
        WHERE x.source_type = 'payroll_calculation'
          AND x.source_id = c.id
          AND x.status IN ('pending', 'processing', 'completed')
      )
      OR EXISTS (
        SELECT 1 FROM public.brick_disbursements b
        WHERE b.source_type = 'payroll_calculation'
          AND b.source_id = c.id
          AND b.status IN ('pending', 'processing', 'completed')
      )
    );
$$;


ALTER FUNCTION "public"."payroll_run_transfer_in_flight"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payroll_ter_category_for_employee"("p_employee_tax_status" "text", "p_ptkp_status" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN COALESCE(p_employee_tax_status, '') IN ('pegawai_tidak_tetap', 'freelancer') THEN 'C'
    WHEN COALESCE(p_ptkp_status, 'TK/0') IN ('TK/0', 'TK/1') THEN 'A'
    WHEN COALESCE(p_ptkp_status, 'TK/0') IN ('TK/2', 'TK/3', 'K/0') THEN 'B'
    ELSE 'C'
  END;
$$;


ALTER FUNCTION "public"."payroll_ter_category_for_employee"("p_employee_tax_status" "text", "p_ptkp_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pg_dow_to_app_dow"("p_pg_dow" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE WHEN p_pg_dow = 0 THEN 7 ELSE p_pg_dow END;
$$;


ALTER FUNCTION "public"."pg_dow_to_app_dow"("p_pg_dow" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pic_production_manager_user_id"("p_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT public.employee_user_id(employee.manager_id)
  FROM public.social_media_plans plan
  JOIN public.employees employee ON employee.id = plan.pic_production_id
  WHERE plan.id = p_plan_id
    AND employee.manager_id IS NOT NULL
  LIMIT 1
$$;


ALTER FUNCTION "public"."pic_production_manager_user_id"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."poll_email_verified_by_token"("p_token" "text", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v boolean;
BEGIN
  IF p_token IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT t.email_verified
  INTO v
  FROM public.email_verification_tokens t
  WHERE t.token = p_token AND t.user_id = p_user_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  RETURN COALESCE(v, false);
END;
$$;


ALTER FUNCTION "public"."poll_email_verified_by_token"("p_token" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pos_cash_movements" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "shift_id" "uuid" NOT NULL,
    "direction" "text" NOT NULL,
    "amount" numeric(14,2) NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pos_cash_movements_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "pos_cash_movements_direction_check" CHECK (("direction" = ANY (ARRAY['in'::"text", 'out'::"text"])))
);


ALTER TABLE "public"."pos_cash_movements" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_add_cash_movement"("p_shift_id" "uuid", "p_direction" "text", "p_amount" numeric, "p_description" "text") RETURNS "public"."pos_cash_movements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_shift public.pos_cashier_shifts;
  v_row public.pos_cash_movements;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_direction NOT IN ('in', 'out') THEN
    RAISE EXCEPTION 'invalid_direction';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount';
  END IF;

  SELECT * INTO v_shift FROM public.pos_cashier_shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
  END IF;
  IF v_shift.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF v_shift.status <> 'open' THEN
    RAISE EXCEPTION 'shift_not_open';
  END IF;

  INSERT INTO public.pos_cash_movements (
    organization_id,
    shift_id,
    direction,
    amount,
    description,
    created_by
  ) VALUES (
    v_shift.organization_id,
    p_shift_id,
    p_direction,
    p_amount,
    COALESCE(NULLIF(trim(p_description), ''), '—'),
    v_user
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."pos_add_cash_movement"("p_shift_id" "uuid", "p_direction" "text", "p_amount" numeric, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_backfill_sales_item_unit_cogs"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("updated_count" bigint, "skipped_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_updated bigint := 0;
  v_skipped bigint := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  WITH candidates AS (
    SELECT
      sai.id,
      sa.pos_outlet_id AS outlet_id,
      sai.catalog_product_id,
      sai.catalog_variant_id
    FROM public.sales_activity_items sai
    JOIN public.sales_activities sa ON sa.id = sai.sales_activity_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sai.item_kind = 'product'
      AND sai.unit_cogs IS NULL
      AND sai.catalog_product_id IS NOT NULL
      AND sa.pos_outlet_id IS NOT NULL
  ),
  priced AS (
    SELECT
      c.id,
      public.pos_estimate_line_unit_cogs(
        p_organization_id,
        c.outlet_id,
        c.catalog_product_id,
        c.catalog_variant_id
      ) AS estimated_cogs
    FROM candidates c
  ),
  updated AS (
    UPDATE public.sales_activity_items sai
    SET
      unit_cogs = p.estimated_cogs,
      cogs_source = 'estimated'
    FROM priced p
    WHERE sai.id = p.id
      AND p.estimated_cogs IS NOT NULL
    RETURNING sai.id
  )
  SELECT COUNT(*) INTO v_updated FROM updated;

  SELECT COUNT(*)::bigint INTO v_skipped
  FROM public.sales_activity_items sai
  JOIN public.sales_activities sa ON sa.id = sai.sales_activity_id
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND sai.item_kind = 'product'
    AND sai.unit_cogs IS NULL;

  RETURN QUERY SELECT v_updated, v_skipped;
END;
$$;


ALTER FUNCTION "public"."pos_backfill_sales_item_unit_cogs"("p_organization_id" "uuid", "p_outlet_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_backfill_sales_item_unit_cogs"("p_organization_id" "uuid", "p_outlet_id" "uuid") IS 'Fill null unit_cogs on product lines from pos_estimate_line_unit_cogs; sets cogs_source=estimated. Does not overwrite snapshots.';



CREATE OR REPLACE FUNCTION "public"."pos_brand_sales_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("brand_id" "uuid", "brand_name" "text", "brand_sort_order" integer, "catalog_product_id" "uuid", "catalog_variant_id" "uuid", "catalog_bundle_id" "uuid", "item_name" "text", "variant_name" "text", "sku" "text", "qty_sold" numeric, "qty_refunded" numeric, "gross_sales" numeric, "net_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  ELSIF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  RETURN QUERY
  WITH activity_gross AS (SELECT sai.sales_activity_id, COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross FROM public.sales_activity_items sai GROUP BY sai.sales_activity_id),
  sold_lines AS (
    SELECT CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE dp.product_brand_id END AS brand_id, CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_product_id END AS product_id, CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_variant_id END AS variant_id, sai.catalog_bundle_id AS bundle_id, sai.service_name, sai.quantity, sai.inventory_sku_id,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) ELSE COALESCE(sai.total_price, 0) END AS net_line_sales,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0) ELSE 0::numeric END AS discount_line,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN public.pos_estimate_line_unit_cogs(p_organization_id, sa.pos_outlet_id, sai.catalog_product_id, sai.catalog_variant_id) ELSE NULL END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path
    FROM public.sales_activities sa JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id JOIN activity_gross ag ON ag.sales_activity_id = sa.id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none' AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.created_at >= p_from) AND (p_to IS NULL OR sa.created_at < p_to) AND (sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL) AND sai.item_kind <> 'service'
  ),
  sold_grouped AS (
    SELECT l.brand_id, l.product_id, l.variant_id, l.bundle_id, COALESCE(NULLIF(MAX(cb.name), ''), NULLIF(MAX(dp.name), ''), NULLIF(MAX(l.service_name), ''), 'Unlinked')::text AS product_name, CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE NULLIF(MAX(cv.name), '') END::text AS variant_name, CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE COALESCE(NULLIF(MAX(cv.sku), ''), NULLIF(MAX(dp.sku), ''), NULLIF(MAX(isk.internal_sku), '')) END::text AS resolved_sku,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold, COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales, COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount, COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales, COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs, COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND l.bundle_id IS NULL), false) AS cogs_incomplete, COALESCE(BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL), false) AS cogs_estimated
    FROM sold_lines l LEFT JOIN public.default_prices dp ON dp.id = l.product_id LEFT JOIN public.catalog_product_variants cv ON cv.id = l.variant_id LEFT JOIN public.catalog_bundles cb ON cb.id = l.bundle_id LEFT JOIN public.inventory_skus isk ON isk.id = l.inventory_sku_id
    GROUP BY l.brand_id, l.product_id, l.variant_id, l.bundle_id, CASE WHEN l.product_id IS NULL AND l.bundle_id IS NULL THEN lower(btrim(COALESCE(l.service_name, ''))) ELSE NULL END
  ),
  refund_qty_grouped AS (
    SELECT dp.product_brand_id AS brand_id, rcl.catalog_product_id AS product_id, rcl.catalog_variant_id AS variant_id, COALESCE(SUM(COALESCE(rcl.quantity, 0)), 0)::numeric AS qty_refunded
    FROM public.pos_sales_refund_cogs_lines rcl JOIN public.pos_sales_refunds pr ON pr.id = rcl.refund_id JOIN public.sales_activities sa ON sa.id = pr.sales_activity_id LEFT JOIN public.default_prices dp ON dp.id = rcl.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
    GROUP BY dp.product_brand_id, rcl.catalog_product_id, rcl.catalog_variant_id
  ),
  refund_activity_net AS (
    SELECT sa.id AS activity_id, public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) AS bill_net, COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_amount_lines AS (
    SELECT dp.product_brand_id AS brand_id, CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_product_id END AS product_id, CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_variant_id END AS variant_id, sai.catalog_bundle_id AS bundle_id,
      CASE WHEN ran.bill_net > 0 AND ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * ran.refund_total ELSE 0::numeric END AS refund_line_amount
    FROM refund_activity_net ran JOIN public.sales_activity_items sai ON sai.sales_activity_id = ran.activity_id JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id WHERE sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL
  ),
  refund_amount_grouped AS (SELECT ral.brand_id, ral.product_id, ral.variant_id, ral.bundle_id, COALESCE(SUM(COALESCE(ral.refund_line_amount, 0)), 0)::numeric AS refund_amount FROM refund_amount_lines ral GROUP BY ral.brand_id, ral.product_id, ral.variant_id, ral.bundle_id),
  merged AS (
    SELECT sg.brand_id, sg.product_id, sg.variant_id, sg.bundle_id, sg.product_name, sg.variant_name, sg.resolved_sku, sg.qty_sold, COALESCE(rq.qty_refunded, 0)::numeric AS qty_refunded, sg.gross_sales, sg.net_sales, sg.discount_amount, COALESCE(ra.refund_amount, 0)::numeric AS refund_amount, sg.cogs, sg.cogs_incomplete, sg.cogs_estimated
    FROM sold_grouped sg LEFT JOIN refund_qty_grouped rq ON sg.brand_id IS NOT DISTINCT FROM rq.brand_id AND sg.product_id IS NOT DISTINCT FROM rq.product_id AND sg.variant_id IS NOT DISTINCT FROM rq.variant_id AND sg.bundle_id IS NULL
    LEFT JOIN refund_amount_grouped ra ON sg.brand_id IS NOT DISTINCT FROM ra.brand_id AND sg.product_id IS NOT DISTINCT FROM ra.product_id AND sg.variant_id IS NOT DISTINCT FROM ra.variant_id AND sg.bundle_id IS NOT DISTINCT FROM ra.bundle_id
    UNION ALL
    SELECT rq.brand_id, rq.product_id, rq.variant_id, NULL::uuid, COALESCE(NULLIF(dp.name, ''), 'Unlinked')::text, NULLIF(cv.name, '')::text, COALESCE(NULLIF(cv.sku, ''), NULLIF(dp.sku, ''))::text, 0::numeric, rq.qty_refunded, 0::numeric, 0::numeric, 0::numeric, COALESCE(ra.refund_amount, 0)::numeric, 0::numeric, false, false
    FROM refund_qty_grouped rq LEFT JOIN public.default_prices dp ON dp.id = rq.product_id LEFT JOIN public.catalog_product_variants cv ON cv.id = rq.variant_id LEFT JOIN refund_amount_grouped ra ON rq.brand_id IS NOT DISTINCT FROM ra.brand_id AND rq.product_id IS NOT DISTINCT FROM ra.product_id AND rq.variant_id IS NOT DISTINCT FROM ra.variant_id AND ra.bundle_id IS NULL
    WHERE NOT EXISTS (SELECT 1 FROM sold_grouped sg WHERE sg.brand_id IS NOT DISTINCT FROM rq.brand_id AND sg.product_id IS NOT DISTINCT FROM rq.product_id AND sg.variant_id IS NOT DISTINCT FROM rq.variant_id AND sg.bundle_id IS NULL)
  )
  SELECT m.brand_id, COALESCE(NULLIF(b.name, ''), 'Unbranded')::text, COALESCE(b.sort_order, 9999)::integer, m.product_id, m.variant_id, m.bundle_id, COALESCE(m.product_name, 'Unlinked')::text, m.variant_name, m.resolved_sku, m.qty_sold, m.qty_refunded, m.gross_sales, m.net_sales, m.discount_amount, m.refund_amount, m.cogs, (m.net_sales - m.cogs)::numeric, CASE WHEN m.net_sales > 0 THEN ROUND(((m.net_sales - m.cogs) / m.net_sales) * 100, 2) ELSE 0::numeric END, m.cogs_incomplete, m.cogs_estimated
  FROM merged m LEFT JOIN public.catalog_brands b ON b.id = m.brand_id
  WHERE m.qty_sold > 0 OR m.qty_refunded > 0 OR m.gross_sales > 0 OR m.refund_amount > 0
  ORDER BY COALESCE(b.sort_order, 9999), COALESCE(b.name, 'Unbranded'), m.net_sales DESC;
END; $$;


ALTER FUNCTION "public"."pos_brand_sales_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_brand_sales_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Brand Sales item breakdown under each brand (product/variant/bundle grain).';



CREATE OR REPLACE FUNCTION "public"."pos_brand_sales_by_outlet"("p_organization_id" "uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("brand_id" "uuid", "brand_name" "text", "outlet_id" "uuid", "outlet_name" "text", "qty_sold" numeric, "qty_refunded" numeric, "gross_sales" numeric, "net_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  ELSIF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  RETURN QUERY
  WITH activity_gross AS (SELECT sai.sales_activity_id, COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross FROM public.sales_activity_items sai GROUP BY sai.sales_activity_id),
  sold_lines AS (
    SELECT sa.pos_outlet_id AS outlet_id, CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE dp.product_brand_id END AS brand_id, sai.quantity,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) ELSE COALESCE(sai.total_price, 0) END AS net_line_sales,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0) ELSE 0::numeric END AS discount_line,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN public.pos_estimate_line_unit_cogs(p_organization_id, sa.pos_outlet_id, sai.catalog_product_id, sai.catalog_variant_id) ELSE NULL END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path, sai.catalog_bundle_id IS NOT NULL AS is_bundle_line
    FROM public.sales_activities sa JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id JOIN activity_gross ag ON ag.sales_activity_id = sa.id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none' AND sa.pos_outlet_id IS NOT NULL AND (p_from IS NULL OR sa.created_at >= p_from) AND (p_to IS NULL OR sa.created_at < p_to) AND (sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL) AND sai.item_kind <> 'service'
  ),
  sold_grouped AS (
    SELECT l.brand_id, l.outlet_id, COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold, COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales, COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount, COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales, COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs, COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND NOT l.is_bundle_line), false) AS cogs_incomplete, COALESCE(BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL), false) AS cogs_estimated
    FROM sold_lines l GROUP BY l.brand_id, l.outlet_id
  ),
  refund_qty_grouped AS (
    SELECT dp.product_brand_id AS brand_id, sa.pos_outlet_id AS outlet_id, COALESCE(SUM(COALESCE(rcl.quantity, 0)), 0)::numeric AS qty_refunded
    FROM public.pos_sales_refund_cogs_lines rcl JOIN public.pos_sales_refunds pr ON pr.id = rcl.refund_id JOIN public.sales_activities sa ON sa.id = pr.sales_activity_id LEFT JOIN public.default_prices dp ON dp.id = rcl.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL AND sa.pos_outlet_id IS NOT NULL AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
    GROUP BY dp.product_brand_id, sa.pos_outlet_id
  ),
  refund_activity_net AS (
    SELECT sa.id AS activity_id, sa.pos_outlet_id AS outlet_id, public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) AS bill_net, COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL AND sa.pos_outlet_id IS NOT NULL AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_amount_lines AS (
    SELECT ran.outlet_id, dp.product_brand_id AS brand_id, CASE WHEN ran.bill_net > 0 AND ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * ran.refund_total ELSE 0::numeric END AS refund_line_amount
    FROM refund_activity_net ran JOIN public.sales_activity_items sai ON sai.sales_activity_id = ran.activity_id JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id WHERE sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL
  ),
  refund_amount_grouped AS (SELECT ral.brand_id, ral.outlet_id, COALESCE(SUM(COALESCE(ral.refund_line_amount, 0)), 0)::numeric AS refund_amount FROM refund_amount_lines ral GROUP BY ral.brand_id, ral.outlet_id),
  merged AS (
    SELECT sg.brand_id, sg.outlet_id, COALESCE(sg.qty_sold, 0)::numeric AS qty_sold, COALESCE(rq.qty_refunded, 0)::numeric AS qty_refunded, COALESCE(sg.gross_sales, 0)::numeric AS gross_sales, COALESCE(sg.net_sales, 0)::numeric AS net_sales, COALESCE(sg.discount_amount, 0)::numeric AS discount_amount, COALESCE(ra.refund_amount, 0)::numeric AS refund_amount, COALESCE(sg.cogs, 0)::numeric AS cogs, COALESCE(sg.cogs_incomplete, false) AS cogs_incomplete, COALESCE(sg.cogs_estimated, false) AS cogs_estimated
    FROM sold_grouped sg LEFT JOIN refund_qty_grouped rq ON rq.brand_id IS NOT DISTINCT FROM sg.brand_id AND rq.outlet_id = sg.outlet_id LEFT JOIN refund_amount_grouped ra ON ra.brand_id IS NOT DISTINCT FROM sg.brand_id AND ra.outlet_id = sg.outlet_id
    UNION ALL SELECT rq.brand_id, rq.outlet_id, 0::numeric, rq.qty_refunded, 0::numeric, 0::numeric, 0::numeric, COALESCE(ra.refund_amount, 0)::numeric, 0::numeric, false, false FROM refund_qty_grouped rq LEFT JOIN refund_amount_grouped ra ON ra.brand_id IS NOT DISTINCT FROM rq.brand_id AND ra.outlet_id = rq.outlet_id WHERE NOT EXISTS (SELECT 1 FROM sold_grouped sg WHERE sg.brand_id IS NOT DISTINCT FROM rq.brand_id AND sg.outlet_id = rq.outlet_id)
    UNION ALL SELECT ra.brand_id, ra.outlet_id, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, ra.refund_amount, 0::numeric, false, false FROM refund_amount_grouped ra WHERE NOT EXISTS (SELECT 1 FROM sold_grouped sg WHERE sg.brand_id IS NOT DISTINCT FROM ra.brand_id AND sg.outlet_id = ra.outlet_id) AND NOT EXISTS (SELECT 1 FROM refund_qty_grouped rq WHERE rq.brand_id IS NOT DISTINCT FROM ra.brand_id AND rq.outlet_id = ra.outlet_id)
  ), rolled AS (
    SELECT m.brand_id, m.outlet_id, COALESCE(SUM(m.qty_sold), 0)::numeric AS qty_sold, COALESCE(SUM(m.qty_refunded), 0)::numeric AS qty_refunded, COALESCE(SUM(m.gross_sales), 0)::numeric AS gross_sales, COALESCE(SUM(m.net_sales), 0)::numeric AS net_sales, COALESCE(SUM(m.discount_amount), 0)::numeric AS discount_amount, COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount, COALESCE(SUM(m.cogs), 0)::numeric AS cogs, COALESCE(BOOL_OR(m.cogs_incomplete), false) AS cogs_incomplete, COALESCE(BOOL_OR(m.cogs_estimated), false) AS cogs_estimated FROM merged m GROUP BY m.brand_id, m.outlet_id
  )
  SELECT r.brand_id, COALESCE(NULLIF(b.name, ''), 'Unbranded')::text, r.outlet_id, COALESCE(NULLIF(o.name, ''), 'Outlet')::text, r.qty_sold, r.qty_refunded, r.gross_sales, r.net_sales, r.discount_amount, r.refund_amount, r.cogs, (r.net_sales - r.cogs)::numeric, CASE WHEN r.net_sales > 0 THEN ROUND(((r.net_sales - r.cogs) / r.net_sales) * 100, 2) ELSE 0::numeric END, r.cogs_incomplete, r.cogs_estimated
  FROM rolled r LEFT JOIN public.catalog_brands b ON b.id = r.brand_id LEFT JOIN public.pos_outlets o ON o.id = r.outlet_id
  WHERE r.qty_sold > 0 OR r.qty_refunded > 0 OR r.gross_sales > 0 OR r.refund_amount > 0
  ORDER BY COALESCE(b.name, 'Unbranded'), COALESCE(o.name, 'Outlet');
END; $$;


ALTER FUNCTION "public"."pos_brand_sales_by_outlet"("p_organization_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_brand_sales_by_outlet"("p_organization_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Brand Sales by outlet for export (all outlets in org).';



CREATE OR REPLACE FUNCTION "public"."pos_brand_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("brand_id" "uuid", "brand_name" "text", "sort_order" integer, "qty_sold" numeric, "qty_refunded" numeric, "gross_sales" numeric, "net_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean, "summary_product_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_summary_product_net numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  WITH activity_gross AS (
    SELECT sai.sales_activity_id, COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai GROUP BY sai.sales_activity_id
  ),
  sold_lines AS (
    SELECT CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE dp.product_brand_id END AS brand_id, sai.quantity,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) ELSE COALESCE(sai.total_price, 0) END AS net_line_sales,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0) ELSE 0::numeric END AS discount_line,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN public.pos_estimate_line_unit_cogs(p_organization_id, sa.pos_outlet_id, sai.catalog_product_id, sai.catalog_variant_id) ELSE NULL END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path, sai.catalog_bundle_id IS NOT NULL AS is_bundle_line
    FROM public.sales_activities sa JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id JOIN activity_gross ag ON ag.sales_activity_id = sa.id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.created_at >= p_from) AND (p_to IS NULL OR sa.created_at < p_to)
      AND (sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL) AND sai.item_kind <> 'service'
  ),
  sold_grouped AS (
    SELECT l.brand_id, COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold, COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount, COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND NOT l.is_bundle_line), false) AS cogs_incomplete,
      COALESCE(BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL), false) AS cogs_estimated
    FROM sold_lines l GROUP BY l.brand_id
  ), summary AS (SELECT COALESCE(SUM(sg.net_sales), 0)::numeric AS product_net FROM sold_grouped sg)
  SELECT s.product_net INTO v_summary_product_net FROM summary s;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT sai.sales_activity_id, COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross FROM public.sales_activity_items sai GROUP BY sai.sales_activity_id
  ), sold_lines AS (
    SELECT CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE dp.product_brand_id END AS brand_id, sai.quantity,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) ELSE COALESCE(sai.total_price, 0) END AS net_line_sales,
      CASE WHEN ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0) ELSE 0::numeric END AS discount_line,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN public.pos_estimate_line_unit_cogs(p_organization_id, sa.pos_outlet_id, sai.catalog_product_id, sai.catalog_variant_id) ELSE NULL END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path, sai.catalog_bundle_id IS NOT NULL AS is_bundle_line
    FROM public.sales_activities sa JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id JOIN activity_gross ag ON ag.sales_activity_id = sa.id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.created_at >= p_from) AND (p_to IS NULL OR sa.created_at < p_to)
      AND (sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL) AND sai.item_kind <> 'service'
  ), sold_grouped AS (
    SELECT l.brand_id, COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold, COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount, COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND NOT l.is_bundle_line), false) AS cogs_incomplete,
      COALESCE(BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL), false) AS cogs_estimated
    FROM sold_lines l GROUP BY l.brand_id
  ), refund_qty_grouped AS (
    SELECT dp.product_brand_id AS brand_id, COALESCE(SUM(COALESCE(rcl.quantity, 0)), 0)::numeric AS qty_refunded
    FROM public.pos_sales_refund_cogs_lines rcl JOIN public.pos_sales_refunds pr ON pr.id = rcl.refund_id JOIN public.sales_activities sa ON sa.id = pr.sales_activity_id LEFT JOIN public.default_prices dp ON dp.id = rcl.catalog_product_id
    WHERE sa.organization_id = p_organization_id AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
    GROUP BY dp.product_brand_id
  ), refund_activity_net AS (
    SELECT sa.id AS activity_id, public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method) AS bill_net, COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted' AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id) AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
  ), refund_amount_lines AS (
    SELECT dp.product_brand_id AS brand_id, CASE WHEN ran.bill_net > 0 AND ag.lines_gross > 0 THEN COALESCE(sai.total_price, 0) / ag.lines_gross * ran.refund_total ELSE 0::numeric END AS refund_line_amount
    FROM refund_activity_net ran JOIN public.sales_activity_items sai ON sai.sales_activity_id = ran.activity_id JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sai.item_kind = 'product' OR sai.catalog_bundle_id IS NOT NULL
  ), refund_amount_grouped AS (SELECT ral.brand_id, COALESCE(SUM(COALESCE(ral.refund_line_amount, 0)), 0)::numeric AS refund_amount FROM refund_amount_lines ral GROUP BY ral.brand_id),
  merged AS (
    SELECT sg.brand_id, COALESCE(sg.qty_sold, 0)::numeric AS qty_sold, COALESCE(rq.qty_refunded, 0)::numeric AS qty_refunded, COALESCE(sg.gross_sales, 0)::numeric AS gross_sales, COALESCE(sg.net_sales, 0)::numeric AS net_sales, COALESCE(sg.discount_amount, 0)::numeric AS discount_amount, COALESCE(ra.refund_amount, 0)::numeric AS refund_amount, COALESCE(sg.cogs, 0)::numeric AS cogs, COALESCE(sg.cogs_incomplete, false) AS cogs_incomplete, COALESCE(sg.cogs_estimated, false) AS cogs_estimated
    FROM sold_grouped sg LEFT JOIN refund_qty_grouped rq ON rq.brand_id IS NOT DISTINCT FROM sg.brand_id LEFT JOIN refund_amount_grouped ra ON ra.brand_id IS NOT DISTINCT FROM sg.brand_id
    UNION ALL SELECT rq.brand_id, 0::numeric, rq.qty_refunded, 0::numeric, 0::numeric, 0::numeric, COALESCE(ra.refund_amount, 0)::numeric, 0::numeric, false, false FROM refund_qty_grouped rq LEFT JOIN refund_amount_grouped ra ON ra.brand_id IS NOT DISTINCT FROM rq.brand_id WHERE NOT EXISTS (SELECT 1 FROM sold_grouped sg WHERE sg.brand_id IS NOT DISTINCT FROM rq.brand_id)
    UNION ALL SELECT ra.brand_id, 0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric, ra.refund_amount, 0::numeric, false, false FROM refund_amount_grouped ra WHERE NOT EXISTS (SELECT 1 FROM sold_grouped sg WHERE sg.brand_id IS NOT DISTINCT FROM ra.brand_id) AND NOT EXISTS (SELECT 1 FROM refund_qty_grouped rq WHERE rq.brand_id IS NOT DISTINCT FROM ra.brand_id)
  ), rolled AS (
    SELECT m.brand_id, COALESCE(SUM(m.qty_sold), 0)::numeric AS qty_sold, COALESCE(SUM(m.qty_refunded), 0)::numeric AS qty_refunded, COALESCE(SUM(m.gross_sales), 0)::numeric AS gross_sales, COALESCE(SUM(m.net_sales), 0)::numeric AS net_sales, COALESCE(SUM(m.discount_amount), 0)::numeric AS discount_amount, COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount, COALESCE(SUM(m.cogs), 0)::numeric AS cogs, COALESCE(BOOL_OR(m.cogs_incomplete), false) AS cogs_incomplete, COALESCE(BOOL_OR(m.cogs_estimated), false) AS cogs_estimated FROM merged m GROUP BY m.brand_id
  )
  SELECT r.brand_id, COALESCE(NULLIF(b.name, ''), 'Unbranded')::text, COALESCE(b.sort_order, 9999)::integer, r.qty_sold, r.qty_refunded, r.gross_sales, r.net_sales, r.discount_amount, r.refund_amount, r.cogs, (r.net_sales - r.cogs)::numeric, CASE WHEN r.net_sales > 0 THEN ROUND(((r.net_sales - r.cogs) / r.net_sales) * 100, 2) ELSE 0::numeric END, r.cogs_incomplete, r.cogs_estimated, v_summary_product_net
  FROM rolled r LEFT JOIN public.catalog_brands b ON b.id = r.brand_id
  WHERE r.qty_sold > 0 OR r.qty_refunded > 0 OR r.gross_sales > 0 OR r.refund_amount > 0
  ORDER BY r.gross_sales DESC, COALESCE(b.name, 'Unbranded') ASC;
END;
$$;


ALTER FUNCTION "public"."pos_brand_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_brand_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Brand Sales rollup: qty sold/refunded, gross/net/discount/refund, COGS per catalog brand.';



CREATE OR REPLACE FUNCTION "public"."pos_cancel_pending_checkout"("p_pending_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_is_service boolean := false;
BEGIN
  v_is_service := coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') = 'service_role';

  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pos_pending_checkout_not_found';
  END IF;

  IF NOT v_is_service THEN
    IF auth.uid() IS NULL
       OR v_pending.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
      RAISE EXCEPTION 'forbidden_org';
    END IF;
  END IF;

  IF v_pending.status IN ('paid', 'finalizing') THEN
    RETURN jsonb_build_object('ok', true, 'already_final', true);
  END IF;

  IF v_pending.status IN ('cancelled', 'expired', 'failed') THEN
    RETURN jsonb_build_object('ok', true, 'already_cancelled', true);
  END IF;

  UPDATE public.pos_pending_checkouts
  SET
    status = CASE
      WHEN p_reason = 'expired' THEN 'expired'
      WHEN p_reason = 'failed' THEN 'failed'
      ELSE 'cancelled'
    END,
    cancelled_at = now(),
    error_message = NULLIF(btrim(COALESCE(p_reason, '')), ''),
    updated_at = now()
  WHERE id = p_pending_id;

  IF v_pending.xendit_payment_request_id IS NOT NULL THEN
    UPDATE public.xendit_payment_requests
    SET
      status = CASE
        WHEN p_reason = 'failed' THEN 'failed'
        ELSE 'expired'
      END,
      updated_at = now()
    WHERE id = v_pending.xendit_payment_request_id
      AND status = 'pending';
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."pos_cancel_pending_checkout"("p_pending_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_category_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("category_id" "uuid", "category_name" "text", "sort_order" integer, "qty_sold" numeric, "qty_refunded" numeric, "gross_sales" numeric, "net_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean, "summary_product_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_summary_product_net numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold_lines AS (
    SELECT
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        ELSE dp.product_category_id
      END AS cat_id,
      sai.quantity,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(
            sa.checkout_subtotal,
            sa.checkout_tax_amount,
            sa.checkout_gratuity_amount,
            COALESCE(sa.total_paid_amount, sa.total_amount, 0),
            sa.checkout_application_method
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0)
        ELSE 0::numeric
      END AS discount_line,
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            sa.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path,
      sai.catalog_bundle_id IS NOT NULL AS is_bundle_line
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        sai.item_kind = 'product'
        OR sai.catalog_bundle_id IS NOT NULL
      )
      AND sai.item_kind <> 'service'
  ),
  sold_grouped AS (
    SELECT
      l.cat_id,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND NOT l.is_bundle_line), false) AS cogs_incomplete,
      COALESCE(
        BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL),
        false
      ) AS cogs_estimated
    FROM sold_lines l
    GROUP BY l.cat_id
  ),
  summary AS (
    SELECT COALESCE(SUM(sg.net_sales), 0)::numeric AS product_net
    FROM sold_grouped sg
  )
  SELECT s.product_net INTO v_summary_product_net FROM summary s;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold_lines AS (
    SELECT
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        ELSE dp.product_category_id
      END AS cat_id,
      sai.quantity,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(
            sa.checkout_subtotal,
            sa.checkout_tax_amount,
            sa.checkout_gratuity_amount,
            COALESCE(sa.total_paid_amount, sa.total_amount, 0),
            sa.checkout_application_method
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0)
        ELSE 0::numeric
      END AS discount_line,
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            sa.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path,
      sai.catalog_bundle_id IS NOT NULL AS is_bundle_line
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        sai.item_kind = 'product'
        OR sai.catalog_bundle_id IS NOT NULL
      )
      AND sai.item_kind <> 'service'
  ),
  sold_grouped AS (
    SELECT
      l.cat_id,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.discount_line, 0)), 0)::numeric AS discount_amount,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND NOT l.is_bundle_line), false) AS cogs_incomplete,
      COALESCE(
        BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL),
        false
      ) AS cogs_estimated
    FROM sold_lines l
    GROUP BY l.cat_id
  ),
  refund_qty_grouped AS (
    SELECT
      dp.product_category_id AS cat_id,
      COALESCE(SUM(COALESCE(rcl.quantity, 0)), 0)::numeric AS qty_refunded
    FROM public.pos_sales_refund_cogs_lines rcl
    JOIN public.pos_sales_refunds pr ON pr.id = rcl.refund_id
    JOIN public.sales_activities sa ON sa.id = pr.sales_activity_id
    LEFT JOIN public.default_prices dp ON dp.id = rcl.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
    GROUP BY dp.product_category_id
  ),
  refund_activity_net AS (
    SELECT
      sa.id AS activity_id,
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      ) AS bill_net,
      COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_amount_lines AS (
    SELECT
      dp.product_category_id AS cat_id,
      CASE
        WHEN ran.bill_net > 0 AND ag.lines_gross > 0 THEN
          (COALESCE(sai.total_price, 0) / ag.lines_gross * ran.bill_net) / ran.bill_net * ran.refund_total
        ELSE 0::numeric
      END AS refund_line_amount
    FROM refund_activity_net ran
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = ran.activity_id
    JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sai.item_kind = 'product'
       OR sai.catalog_bundle_id IS NOT NULL
  ),
  refund_amount_grouped AS (
    SELECT
      ral.cat_id,
      COALESCE(SUM(COALESCE(ral.refund_line_amount, 0)), 0)::numeric AS refund_amount
    FROM refund_amount_lines ral
    GROUP BY ral.cat_id
  ),
  merged AS (
    SELECT
      sg.cat_id,
      COALESCE(sg.qty_sold, 0)::numeric AS qty_sold,
      COALESCE(rq.qty_refunded, 0)::numeric AS qty_refunded,
      COALESCE(sg.gross_sales, 0)::numeric AS gross_sales,
      COALESCE(sg.net_sales, 0)::numeric AS net_sales,
      COALESCE(sg.discount_amount, 0)::numeric AS discount_amount,
      COALESCE(ra.refund_amount, 0)::numeric AS refund_amount,
      COALESCE(sg.cogs, 0)::numeric AS cogs,
      COALESCE(sg.cogs_incomplete, false) AS cogs_incomplete,
      COALESCE(sg.cogs_estimated, false) AS cogs_estimated
    FROM sold_grouped sg
    LEFT JOIN refund_qty_grouped rq ON rq.cat_id IS NOT DISTINCT FROM sg.cat_id
    LEFT JOIN refund_amount_grouped ra ON ra.cat_id IS NOT DISTINCT FROM sg.cat_id
    UNION ALL
    SELECT
      rq.cat_id,
      0::numeric AS qty_sold,
      rq.qty_refunded,
      0::numeric AS gross_sales,
      0::numeric AS net_sales,
      0::numeric AS discount_amount,
      COALESCE(ra.refund_amount, 0)::numeric AS refund_amount,
      0::numeric AS cogs,
      false AS cogs_incomplete,
      false AS cogs_estimated
    FROM refund_qty_grouped rq
    LEFT JOIN refund_amount_grouped ra ON ra.cat_id IS NOT DISTINCT FROM rq.cat_id
    WHERE NOT EXISTS (
      SELECT 1 FROM sold_grouped sg WHERE sg.cat_id IS NOT DISTINCT FROM rq.cat_id
    )
    UNION ALL
    SELECT
      ra.cat_id,
      0::numeric AS qty_sold,
      0::numeric AS qty_refunded,
      0::numeric AS gross_sales,
      0::numeric AS net_sales,
      0::numeric AS discount_amount,
      ra.refund_amount,
      0::numeric AS cogs,
      false AS cogs_incomplete,
      false AS cogs_estimated
    FROM refund_amount_grouped ra
    WHERE NOT EXISTS (
      SELECT 1 FROM sold_grouped sg WHERE sg.cat_id IS NOT DISTINCT FROM ra.cat_id
    )
      AND NOT EXISTS (
      SELECT 1 FROM refund_qty_grouped rq WHERE rq.cat_id IS NOT DISTINCT FROM ra.cat_id
    )
  ),
  rolled AS (
    SELECT
      m.cat_id,
      COALESCE(SUM(m.qty_sold), 0)::numeric AS qty_sold,
      COALESCE(SUM(m.qty_refunded), 0)::numeric AS qty_refunded,
      COALESCE(SUM(m.gross_sales), 0)::numeric AS gross_sales,
      COALESCE(SUM(m.net_sales), 0)::numeric AS net_sales,
      COALESCE(SUM(m.discount_amount), 0)::numeric AS discount_amount,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount,
      COALESCE(SUM(m.cogs), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(m.cogs_incomplete), false) AS cogs_incomplete,
      COALESCE(BOOL_OR(m.cogs_estimated), false) AS cogs_estimated
    FROM merged m
    GROUP BY m.cat_id
  )
  SELECT
    r.cat_id AS category_id,
    COALESCE(NULLIF(cat.name, ''), 'Uncategorized')::text AS category_name,
    COALESCE(cat.sort_order, 9999)::integer AS sort_order,
    r.qty_sold,
    r.qty_refunded,
    r.gross_sales,
    r.net_sales,
    r.discount_amount,
    r.refund_amount,
    r.cogs,
    (r.net_sales - r.cogs)::numeric AS gross_profit,
    CASE
      WHEN r.net_sales > 0 THEN ROUND(((r.net_sales - r.cogs) / r.net_sales) * 100, 2)
      ELSE 0::numeric
    END AS margin_pct,
    r.cogs_incomplete,
    r.cogs_estimated,
    v_summary_product_net AS summary_product_net_sales
  FROM rolled r
  LEFT JOIN public.catalog_product_categories cat ON cat.id = r.cat_id
  WHERE r.qty_sold > 0
     OR r.qty_refunded > 0
     OR r.gross_sales > 0
     OR r.refund_amount > 0
  ORDER BY r.gross_sales DESC, COALESCE(cat.name, 'Uncategorized') ASC;
END;
$$;


ALTER FUNCTION "public"."pos_category_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_category_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Category Sales: qty sold/refunded, gross/net/discount/refund amount, COGS per product category.';



CREATE OR REPLACE FUNCTION "public"."pos_claim_synckerja_cashier_checkout"("p_claim_token" "text", "p_outlet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid;
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_session public.pos_table_sessions%ROWTYPE;
  v_token text;
  v_st_id uuid;
  v_st_label text;
BEGIN
  v_user := auth.uid();
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthorized');
  END IF;
  v_token := upper(btrim(COALESCE(p_claim_token, '')));
  IF length(v_token) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_token');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE claim_token = v_token
    AND checkout_channel = 'synckerja_cashier'
    AND pos_outlet_id = p_outlet_id
    AND organization_id IN (SELECT public.user_organization_ids())
  ORDER BY created_at DESC
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  IF v_pending.status = 'paid' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_paid');
  END IF;
  IF v_pending.status NOT IN ('pending') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_available', 'status', v_pending.status);
  END IF;
  IF v_pending.expires_at < now() THEN
    UPDATE public.pos_pending_checkouts SET status = 'expired' WHERE id = v_pending.id;
    RETURN jsonb_build_object('ok', false, 'error', 'expired');
  END IF;
  IF v_pending.session_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_session');
  END IF;
  SELECT * INTO v_session
  FROM public.pos_table_sessions
  WHERE id = v_pending.session_id
    AND outlet_id = p_outlet_id
    AND status = 'open';
  IF NOT FOUND THEN
    IF EXISTS (
      SELECT 1 FROM public.pos_table_sessions
      WHERE id = v_pending.session_id AND status = 'paid'
    ) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'already_paid');
    END IF;
    RETURN jsonb_build_object('ok', false, 'error', 'session_closed');
  END IF;

  UPDATE public.pos_table_sessions
  SET
    awaiting_cashier_claim = false,
    claimed_at = COALESCE(claimed_at, now()),
    claimed_by = COALESCE(claimed_by, v_user)
  WHERE id = v_session.id;

  UPDATE public.pos_pending_checkouts
  SET claimed_at = COALESCE(claimed_at, now())
  WHERE id = v_pending.id;

  BEGIN
    v_st_id := NULLIF(v_pending.payload #>> '{activity,catalog_sales_type_id}', '')::uuid;
  EXCEPTION WHEN others THEN
    v_st_id := NULL;
  END;
  v_st_label := COALESCE(
    NULLIF(v_pending.payload ->> 'salesTypeLabel', ''),
    CASE
      WHEN COALESCE(v_pending.payload ->> 'fulfillmentMode', 'dine_in') = 'takeaway' THEN 'Takeaway'
      ELSE 'Dine In'
    END
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pending_checkout_id', v_pending.id,
    'session_id', v_session.id,
    'checkout_channel', 'synckerja_cashier',
    'cart_snapshot', COALESCE(v_session.cart_snapshot, v_pending.payload -> 'cart', '[]'::jsonb),
    'customer_name', v_session.customer_name,
    'customer_phone', v_session.customer_phone,
    'table_name', v_session.table_name,
    'pos_table_id', v_session.pos_table_id,
    'group_id', v_session.group_id,
    'pax', v_session.pax,
    'seated_at', v_session.seated_at,
    'checkout_totals', v_pending.payload -> 'checkoutTotals',
    'payload', v_pending.payload,
    'catalog_sales_type_id', v_st_id,
    'sales_type_label', v_st_label,
    'fulfillment', COALESCE(v_pending.payload ->> 'fulfillmentMode', 'dine_in')
  );
END;
$$;


ALTER FUNCTION "public"."pos_claim_synckerja_cashier_checkout"("p_claim_token" "text", "p_outlet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_collected_by_sales_by_payment"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("collector_user_id" "uuid", "payment_kind" "text", "transaction_count" bigint, "total_collected" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      sa.id,
      sa.created_by,
      sa.payment_method,
      sa.payment_reference,
      sa.payment_channel_id,
      COALESCE(sa.total_paid_amount, sa.total_amount, 0)::numeric AS collected
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  ),
  resolved AS (
    SELECT
      s.created_by AS collector_user_id,
      CASE
        WHEN COALESCE(
          ch.category,
          CASE lower(COALESCE(s.payment_method, ''))
            WHEN 'cash' THEN 'cash'
            ELSE 'other'
          END
        ) = 'cash' THEN 'cash'
        ELSE 'non_cash'
      END AS payment_kind,
      s.collected
    FROM sales s
    LEFT JOIN public.pos_payment_method_channels ch ON ch.id = s.payment_channel_id
  )
  SELECT
    r.collector_user_id,
    r.payment_kind,
    COUNT(*)::bigint AS transaction_count,
    COALESCE(SUM(r.collected), 0)::numeric AS total_collected
  FROM resolved r
  GROUP BY r.collector_user_id, r.payment_kind
  ORDER BY r.collector_user_id NULLS FIRST, r.payment_kind ASC;
END;
$$;


ALTER FUNCTION "public"."pos_collected_by_sales_by_payment"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_collected_by_sales_by_payment"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Collected By report breakdown: cash vs non-cash per checkout processor.';



CREATE OR REPLACE FUNCTION "public"."pos_collected_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("collector_user_id" "uuid", "collector_name" "text", "employee_id" "uuid", "transaction_count" bigint, "total_collected" numeric, "summary_total_collected" numeric, "summary_transaction_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      sa.id,
      sa.created_by,
      COALESCE(sa.total_paid_amount, sa.total_amount, 0)::numeric AS collected
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  ),
  summary AS (
    SELECT
      COALESCE(SUM(s.collected), 0)::numeric AS summary_total_collected,
      COUNT(*)::bigint AS summary_transaction_count
    FROM sales s
  ),
  enriched AS (
    SELECT
      s.created_by AS collector_user_id,
      COALESCE(
        NULLIF(btrim(e.full_name), ''),
        NULLIF(btrim(p.full_name), ''),
        NULLIF(split_part(au.email, '@', 1), ''),
        'Unknown Staff'
      ) AS collector_name,
      e.id AS employee_id,
      s.collected
    FROM sales s
    LEFT JOIN public.employees e
      ON e.user_id = s.created_by
     AND e.organization_id = p_organization_id
    LEFT JOIN public.profiles p ON p.user_id = s.created_by
    LEFT JOIN auth.users au ON au.id = s.created_by
  ),
  grouped AS (
    SELECT
      en.collector_user_id,
      en.collector_name,
      MAX(en.employee_id::text)::uuid AS employee_id,
      COUNT(*)::bigint AS transaction_count,
      COALESCE(SUM(en.collected), 0)::numeric AS total_collected
    FROM enriched en
    GROUP BY en.collector_user_id, en.collector_name
  )
  SELECT
    g.collector_user_id,
    g.collector_name,
    g.employee_id,
    g.transaction_count,
    g.total_collected,
    sm.summary_total_collected,
    sm.summary_transaction_count
  FROM grouped g
  CROSS JOIN summary sm
  ORDER BY g.total_collected DESC, g.collector_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_collected_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_collected_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Collected By report: txn count and total collected per checkout processor (created_by).';



CREATE OR REPLACE FUNCTION "public"."pos_complete_synckerja_cashier_checkout"("p_pending_id" "uuid", "p_session_id" "uuid", "p_sales_activity_id" "uuid", "p_outlet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending public.pos_pending_checkouts%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthorized');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
    AND pos_outlet_id = p_outlet_id
    AND checkout_channel = 'synckerja_cashier'
    AND organization_id IN (SELECT public.user_organization_ids());
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  UPDATE public.pos_pending_checkouts
  SET
    status = 'paid',
    paid_at = COALESCE(paid_at, now()),
    sales_activity_id = COALESCE(p_sales_activity_id, sales_activity_id),
    updated_at = now()
  WHERE id = p_pending_id;
  RETURN jsonb_build_object('ok', true, 'pending_checkout_id', p_pending_id);
END;
$$;


ALTER FUNCTION "public"."pos_complete_synckerja_cashier_checkout"("p_pending_id" "uuid", "p_session_id" "uuid", "p_sales_activity_id" "uuid", "p_outlet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_create_pending_checkout"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_amount numeric;
  v_session_id uuid;
  v_shift_id uuid;
  v_lead_id uuid;
  v_actor uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'pos_outlet_required';
  END IF;

  v_amount := COALESCE((p_payload -> 'checkoutTotals' ->> 'grandTotal')::numeric, 0);
  IF v_amount < 1500 THEN
    RAISE EXCEPTION 'pos_qris_amount_too_low';
  END IF;
  IF v_amount > 10000000 THEN
    RAISE EXCEPTION 'pos_qris_amount_too_high';
  END IF;

  v_session_id := NULLIF(p_payload ->> 'sessionId', '')::uuid;
  IF v_session_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.pos_pending_checkouts
    WHERE organization_id = p_organization_id
      AND session_id = v_session_id
      AND status = 'pending'
      AND expires_at > now()
  ) THEN
    RAISE EXCEPTION 'pos_qris_pending_exists';
  END IF;

  v_shift_id := NULLIF(p_payload ->> 'posShiftId', '')::uuid;
  v_lead_id := NULLIF(p_payload ->> 'leadId', '')::uuid;
  v_actor := auth.uid();

  INSERT INTO public.pos_pending_checkouts (
    organization_id,
    pos_outlet_id,
    pos_shift_id,
    status,
    payload,
    lead_id,
    session_id,
    keep_session_open,
    expires_at,
    created_by
  )
  VALUES (
    p_organization_id,
    p_outlet_id,
    v_shift_id,
    'pending',
    p_payload,
    v_lead_id,
    v_session_id,
    COALESCE((p_payload ->> 'keepSessionOpen')::boolean, false),
    now() + interval '90 seconds',
    v_actor
  )
  RETURNING * INTO v_pending;

  RETURN jsonb_build_object(
    'ok', true,
    'pending_checkout_id', v_pending.id,
    'expires_at', v_pending.expires_at
  );
END;
$$;


ALTER FUNCTION "public"."pos_create_pending_checkout"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_dashboard_gross_by_dow"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("dow" smallint, "gross_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH spine AS (
    SELECT generate_series(0, 6)::smallint AS dow
  ),
  sales AS (
    SELECT
      EXTRACT(DOW FROM (sa.created_at AT TIME ZONE 'Asia/Jakarta'))::smallint AS dow,
      COALESCE(SUM(
        public.pos_sales_activity_exclusive_net(
          sa.checkout_subtotal,
          sa.checkout_tax_amount,
          sa.checkout_gratuity_amount,
          COALESCE(sa.total_paid_amount, sa.total_amount, 0),
          sa.checkout_application_method
        ) + COALESCE(sa.checkout_discount_amount, 0)
      ), 0)::numeric AS gross_sales
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY 1
  )
  SELECT
    s.dow,
    COALESCE(x.gross_sales, 0)::numeric AS gross_sales
  FROM spine s
  LEFT JOIN sales x ON x.dow = s.dow
  ORDER BY s.dow;
END;
$$;


