CREATE TABLE IF NOT EXISTS "public"."pos_cashier_shifts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "outlet_id" "uuid" NOT NULL,
    "opened_by" "uuid",
    "closed_by" "uuid",
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "opening_cash" numeric(14,2) DEFAULT 0 NOT NULL,
    "expected_cash" numeric(14,2),
    "closing_cash" numeric(14,2),
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "pos_cashier_shifts_closed_consistency" CHECK (((("status" = 'open'::"text") AND ("closed_at" IS NULL)) OR (("status" = 'closed'::"text") AND ("closed_at" IS NOT NULL)))),
    CONSTRAINT "pos_cashier_shifts_opening_cash_check" CHECK (("opening_cash" >= (0)::numeric)),
    CONSTRAINT "pos_cashier_shifts_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text"])))
);


ALTER TABLE "public"."pos_cashier_shifts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_end_shift"("p_shift_id" "uuid", "p_closing_cash" numeric) RETURNS "public"."pos_cashier_shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_cashier_shifts;
  v_expected numeric;
  v_closing numeric;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  IF p_closing_cash IS NULL OR p_closing_cash < 0 THEN
    RAISE EXCEPTION 'invalid_closing_cash';
  END IF;

  v_closing := ROUND(p_closing_cash::numeric, 2);

  SELECT * INTO v_row FROM public.pos_cashier_shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
  END IF;
  IF v_row.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF v_row.status <> 'open' THEN
    RAISE EXCEPTION 'shift_not_open';
  END IF;

  IF v_row.opened_by IS DISTINCT FROM v_user
     AND NOT public.user_is_org_owner_or_admin(v_row.organization_id) THEN
    RAISE EXCEPTION 'not_shift_opener';
  END IF;

  v_expected := public.pos_shift_expected_cash(p_shift_id);

  UPDATE public.pos_cashier_shifts
  SET
    status = 'closed',
    closed_at = now(),
    closed_by = v_user,
    expected_cash = v_expected,
    closing_cash = v_closing,
    updated_at = now()
  WHERE id = p_shift_id
  RETURNING * INTO v_row;

  PERFORM public.enqueue_pos_shift_recap_email(p_shift_id, 'id');

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."pos_end_shift"("p_shift_id" "uuid", "p_closing_cash" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_ensure_default_roles"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_admin_id uuid;
  v_cashier_id uuid;
  v_kitchen_id uuid;
  v_key text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  INSERT INTO public.pos_employee_roles (organization_id, name, slug, is_system)
  VALUES (p_organization_id, 'Administrator', 'administrator', true)
  ON CONFLICT (organization_id, slug) DO UPDATE
    SET name = EXCLUDED.name, is_system = true, updated_at = now();

  SELECT id INTO v_admin_id
  FROM public.pos_employee_roles
  WHERE organization_id = p_organization_id AND slug = 'administrator';

  INSERT INTO public.pos_employee_roles (organization_id, name, slug, is_system)
  VALUES (p_organization_id, 'Cashier', 'cashier', true)
  ON CONFLICT (organization_id, slug) DO UPDATE
    SET name = EXCLUDED.name, is_system = true, updated_at = now();

  SELECT id INTO v_cashier_id
  FROM public.pos_employee_roles
  WHERE organization_id = p_organization_id AND slug = 'cashier';

  INSERT INTO public.pos_employee_roles (organization_id, name, slug, is_system)
  VALUES (p_organization_id, 'Kitchen', 'kitchen', true)
  ON CONFLICT (organization_id, slug) DO UPDATE
    SET name = EXCLUDED.name, is_system = true, updated_at = now();

  SELECT id INTO v_kitchen_id
  FROM public.pos_employee_roles
  WHERE organization_id = p_organization_id AND slug = 'kitchen';

  IF NOT EXISTS (
    SELECT 1 FROM public.pos_employee_role_permissions WHERE role_id = v_admin_id
  ) THEN
    FOREACH v_key IN ARRAY public.pos_default_admin_permission_keys() LOOP
      INSERT INTO public.pos_employee_role_permissions (role_id, permission_key)
      VALUES (v_admin_id, v_key)
      ON CONFLICT DO NOTHING;
    END LOOP;
  ELSE
    INSERT INTO public.pos_employee_role_permissions (role_id, permission_key)
    VALUES (v_admin_id, 'app.kitchen_display')
    ON CONFLICT DO NOTHING;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.pos_employee_role_permissions WHERE role_id = v_cashier_id
  ) THEN
    FOREACH v_key IN ARRAY public.pos_default_cashier_permission_keys() LOOP
      INSERT INTO public.pos_employee_role_permissions (role_id, permission_key)
      VALUES (v_cashier_id, v_key)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.pos_employee_role_permissions WHERE role_id = v_kitchen_id
  ) THEN
    FOREACH v_key IN ARRAY public.pos_default_kitchen_permission_keys() LOOP
      INSERT INTO public.pos_employee_role_permissions (role_id, permission_key)
      VALUES (v_kitchen_id, v_key)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;

  UPDATE public.pos_employee_staff s
  SET role_id = r.id
  FROM public.pos_employee_roles r
  WHERE s.organization_id = p_organization_id
    AND s.role_id IS NULL
    AND r.organization_id = p_organization_id
    AND r.slug = s.pos_role;
END;
$$;


ALTER FUNCTION "public"."pos_ensure_default_roles"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_ensure_open_shift"("p_organization_id" "uuid", "p_outlet_id" "uuid") RETURNS "public"."pos_cashier_shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_cashier_shifts;
  v_settings public.pos_outlet_shift_settings;
  v_opening numeric := 100000;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.pos_outlets o
    WHERE o.id = p_outlet_id
      AND o.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'outlet_not_found';
  END IF;

  SELECT * INTO v_row
  FROM public.pos_cashier_shifts
  WHERE outlet_id = p_outlet_id
    AND organization_id = p_organization_id
    AND status = 'open'
  LIMIT 1;

  IF FOUND THEN
    RETURN v_row;
  END IF;

  SELECT * INTO v_settings
  FROM public.pos_outlet_shift_settings
  WHERE outlet_id = p_outlet_id;

  IF NOT FOUND OR v_settings.auto_start_enabled IS NOT TRUE THEN
    RAISE EXCEPTION 'shift_required';
  END IF;

  v_opening := GREATEST(COALESCE(v_settings.default_opening_cash, 100000), 0);
  RETURN public.pos_start_shift(p_organization_id, p_outlet_id, v_opening);
END;
$$;


ALTER FUNCTION "public"."pos_ensure_open_shift"("p_organization_id" "uuid", "p_outlet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_estimate_line_unit_cogs"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid" DEFAULT NULL::"uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_cost numeric := NULL;
  v_track boolean := false;
  v_bom numeric := 0;
  v_has_bom boolean := false;
BEGIN
  IF p_organization_id IS NULL OR p_outlet_id IS NULL OR p_product_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Prefer variant finished-goods avg_cost when tracked
  IF p_variant_id IS NOT NULL THEN
    SELECT COALESCE(vo.track_cogs, false), COALESCE(vo.avg_cost, 0)
    INTO v_track, v_cost
    FROM public.catalog_product_variant_outlets vo
    WHERE vo.organization_id = p_organization_id
      AND vo.outlet_id = p_outlet_id
      AND vo.variant_id = p_variant_id
    LIMIT 1;

    IF v_track AND v_cost IS NOT NULL THEN
      RETURN ROUND(v_cost::numeric, 2);
    END IF;
  END IF;

  -- Product finished-goods avg_cost when tracked
  SELECT COALESCE(po.track_cogs, false), COALESCE(po.avg_cost, 0)
  INTO v_track, v_cost
  FROM public.catalog_product_outlets po
  WHERE po.organization_id = p_organization_id
    AND po.outlet_id = p_outlet_id
    AND po.product_id = p_product_id
  LIMIT 1;

  IF v_track AND v_cost IS NOT NULL THEN
    RETURN ROUND(v_cost::numeric, 2);
  END IF;

  -- Fallback: base product recipe BOM (modifier_option_id IS NULL)
  SELECT
    COALESCE(SUM(
      CASE
        WHEN COALESCE(io.track_cogs, false) THEN COALESCE(rl.quantity, 0) * COALESCE(io.avg_cost, 0)
        ELSE 0
      END
    ), 0),
    EXISTS (
      SELECT 1
      FROM public.catalog_product_recipes r2
      JOIN public.catalog_product_recipe_lines rl2 ON rl2.recipe_id = r2.id
      WHERE r2.organization_id = p_organization_id
        AND r2.product_id = p_product_id
        AND r2.modifier_option_id IS NULL
    )
  INTO v_bom, v_has_bom
  FROM public.catalog_product_recipes r
  JOIN public.catalog_product_recipe_lines rl ON rl.recipe_id = r.id
  LEFT JOIN public.catalog_ingredient_outlets io
    ON io.ingredient_id = rl.ingredient_id
   AND io.outlet_id = p_outlet_id
   AND io.organization_id = p_organization_id
  WHERE r.organization_id = p_organization_id
    AND r.product_id = p_product_id
    AND r.modifier_option_id IS NULL;

  IF v_has_bom AND v_bom > 0 THEN
    RETURN ROUND(v_bom::numeric, 2);
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."pos_estimate_line_unit_cogs"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_product_id" "uuid", "p_variant_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_expire_stale_pending_checkouts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row record;
  v_count integer := 0;
BEGIN
  FOR v_row IN
    SELECT id FROM public.pos_pending_checkouts
    WHERE status = 'pending' AND expires_at <= now()
  LOOP
    PERFORM public.pos_cancel_pending_checkout(v_row.id, 'expired');
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'expired', v_count);
END;
$$;


ALTER FUNCTION "public"."pos_expire_stale_pending_checkouts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_finalize_qris_checkout"("p_pending_id" "uuid", "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_activity jsonb;
  v_items jsonb;
  v_modifiers jsonb;
  v_discounts jsonb;
  v_stock_lines jsonb;
  v_activity_id uuid;
  v_payment_id uuid;
  v_actor uuid;
  v_outlet uuid;
  v_line jsonb;
  v_line_idx integer := 0;
  v_line_key text;
  v_scope text;
  v_item_id uuid;
  v_item_ids uuid[] := ARRAY[]::uuid[];
  v_mod jsonb;
  v_disc jsonb;
  v_idx integer;
BEGIN
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pos_pending_checkout_not_found';
  END IF;

  IF v_pending.status = 'paid' AND v_pending.sales_activity_id IS NOT NULL THEN
    SELECT id INTO v_payment_id
    FROM public.sales_activity_payments
    WHERE sales_activity_id = v_pending.sales_activity_id
    ORDER BY created_at ASC
    LIMIT 1;
    RETURN jsonb_build_object(
      'ok', true,
      'already_finalized', true,
      'sales_activity_id', v_pending.sales_activity_id,
      'payment_id', v_payment_id
    );
  END IF;

  IF v_pending.status NOT IN ('pending', 'finalizing') THEN
    RAISE EXCEPTION 'pos_pending_checkout_invalid_status';
  END IF;

  UPDATE public.pos_pending_checkouts
  SET status = 'finalizing', updated_at = now()
  WHERE id = p_pending_id;

  v_activity := v_pending.payload -> 'activity';
  v_items := COALESCE(v_pending.payload -> 'items', '[]'::jsonb);
  v_modifiers := COALESCE(v_pending.payload -> 'modifiers', '[]'::jsonb);
  v_discounts := COALESCE(v_pending.payload -> 'discounts', '[]'::jsonb);
  v_stock_lines := COALESCE(v_pending.payload -> 'catalogStockLines', '[]'::jsonb);
  v_actor := COALESCE(p_actor, v_pending.created_by, NULLIF(v_activity ->> 'created_by', '')::uuid);
  v_outlet := v_pending.pos_outlet_id;

  IF v_activity IS NULL THEN
    RAISE EXCEPTION 'pos_pending_checkout_missing_activity';
  END IF;

  INSERT INTO public.sales_activities (
    organization_id,
    lead_id,
    client_name,
    client_phone,
    client_email,
    activity_type,
    status,
    date,
    created_by,
    service_id,
    sub_service_id,
    total_amount,
    total_paid_amount,
    remaining_amount,
    is_down_payment,
    payment_method,
    payment_reference,
    payment_channel_id,
    cash_tendered,
    customer_visit_id,
    table_number,
    pos_table_id,
    table_duration_minutes,
    pos_outlet_id,
    catalog_sales_type_id,
    pos_shift_id,
    served_by_user_id,
    checkout_subtotal,
    checkout_tax_amount,
    checkout_gratuity_amount,
    checkout_application_method,
    checkout_discount_amount,
    description
  )
  VALUES (
    v_pending.organization_id,
    COALESCE(v_pending.lead_id, NULLIF(v_activity ->> 'lead_id', '')::uuid),
    COALESCE(NULLIF(v_activity ->> 'client_name', ''), 'Walk-in'),
    NULLIF(v_activity ->> 'client_phone', ''),
    NULLIF(v_activity ->> 'client_email', ''),
    'Store Checkout',
    'Converted',
    COALESCE(NULLIF(v_activity ->> 'date', '')::date, CURRENT_DATE),
    v_actor,
    NULLIF(v_activity ->> 'service_id', '')::uuid,
    NULLIF(v_activity ->> 'sub_service_id', '')::uuid,
    COALESCE((v_activity ->> 'total_amount')::numeric, 0),
    COALESCE((v_activity ->> 'total_amount')::numeric, 0),
    0,
    false,
    'qris',
    NULLIF(v_activity ->> 'payment_reference', ''),
    NULLIF(v_activity ->> 'payment_channel_id', '')::uuid,
    NULL,
    NULLIF(v_activity ->> 'customer_visit_id', '')::uuid,
    NULLIF(v_activity ->> 'table_number', ''),
    NULLIF(v_activity ->> 'pos_table_id', '')::uuid,
    NULLIF(v_activity ->> 'table_duration_minutes', '')::integer,
    v_outlet,
    NULLIF(v_activity ->> 'catalog_sales_type_id', '')::uuid,
    v_pending.pos_shift_id,
    NULLIF(v_activity ->> 'served_by_user_id', '')::uuid,
    COALESCE((v_activity ->> 'checkout_subtotal')::numeric, 0),
    COALESCE((v_activity ->> 'checkout_tax_amount')::numeric, 0),
    COALESCE((v_activity ->> 'checkout_gratuity_amount')::numeric, 0),
    NULLIF(v_activity ->> 'checkout_application_method', ''),
    COALESCE((v_activity ->> 'checkout_discount_amount')::numeric, 0),
    COALESCE(NULLIF(v_activity ->> 'description', ''), 'Store checkout')
  )
  RETURNING id INTO v_activity_id;

  v_idx := 0;
  FOR v_line IN SELECT value FROM jsonb_array_elements(v_items)
  LOOP
    v_idx := v_idx + 1;
    INSERT INTO public.sales_activity_items (
      sales_activity_id,
      organization_id,
      service_id,
      sub_service_id,
      service_name,
      sub_service_name,
      quantity,
      unit_price,
      total_price,
      notes,
      item_kind,
      inventory_sku_id,
      track_stock,
      catalog_product_id,
      catalog_variant_id,
      catalog_bundle_id,
      catalog_sales_type_id,
      unit_cogs,
      cogs_source
    )
    VALUES (
      v_activity_id,
      v_pending.organization_id,
      NULLIF(v_line ->> 'service_id', '')::uuid,
      NULLIF(v_line ->> 'sub_service_id', '')::uuid,
      NULLIF(v_line ->> 'service_name', ''),
      NULLIF(v_line ->> 'sub_service_name', ''),
      COALESCE((v_line ->> 'quantity')::numeric, 1),
      COALESCE((v_line ->> 'unit_price')::numeric, 0),
      COALESCE((v_line ->> 'total_price')::numeric, 0),
      NULLIF(v_line ->> 'notes', ''),
      COALESCE(NULLIF(v_line ->> 'item_kind', ''), 'product'),
      NULLIF(v_line ->> 'inventory_sku_id', '')::uuid,
      COALESCE((v_line ->> 'track_stock')::boolean, false),
      NULLIF(v_line ->> 'catalog_product_id', '')::uuid,
      NULLIF(v_line ->> 'catalog_variant_id', '')::uuid,
      NULLIF(v_line ->> 'catalog_bundle_id', '')::uuid,
      NULLIF(v_line ->> 'catalog_sales_type_id', '')::uuid,
      NULLIF(v_line ->> 'unit_cogs', '')::numeric,
      COALESCE(NULLIF(v_line ->> 'cogs_source', ''), 'none')
    )
    RETURNING id INTO v_item_id;
    v_item_ids := array_append(v_item_ids, v_item_id);
  END LOOP;

  v_idx := 0;
  FOR v_mod IN SELECT value FROM jsonb_array_elements(v_modifiers)
  LOOP
    v_idx := v_idx + 1;
    INSERT INTO public.sales_activity_item_modifiers (
      organization_id,
      sales_activity_id,
      sales_activity_item_id,
      modifier_group_id,
      modifier_option_id,
      group_name,
      option_name,
      extra_price,
      quantity,
      line_quantity,
      gross_sales,
      discount_amount
    )
    VALUES (
      v_pending.organization_id,
      v_activity_id,
      CASE
        WHEN (v_mod ->> 'item_index') IS NOT NULL
          THEN v_item_ids[GREATEST(1, ((v_mod ->> 'item_index')::integer + 1))]
        ELSE NULL
      END,
      NULLIF(v_mod ->> 'modifier_group_id', '')::uuid,
      NULLIF(v_mod ->> 'modifier_option_id', '')::uuid,
      COALESCE(NULLIF(v_mod ->> 'group_name', ''), 'Unknown'),
      COALESCE(NULLIF(v_mod ->> 'option_name', ''), 'Unknown'),
      COALESCE((v_mod ->> 'extra_price')::numeric, 0),
      COALESCE((v_mod ->> 'quantity')::numeric, 1),
      COALESCE((v_mod ->> 'line_quantity')::numeric, 1),
      COALESCE((v_mod ->> 'gross_sales')::numeric, 0),
      COALESCE((v_mod ->> 'discount_amount')::numeric, 0)
    );
  END LOOP;

  FOR v_disc IN SELECT value FROM jsonb_array_elements(v_discounts)
  LOOP
    INSERT INTO public.sales_activity_line_discounts (
      organization_id,
      sales_activity_id,
      sales_activity_item_id,
      catalog_discount_id,
      discount_name,
      amount_rp,
      line_quantity,
      input_configuration,
      amount_unit,
      amount_value,
      value_label
    )
    VALUES (
      v_pending.organization_id,
      v_activity_id,
      CASE
        WHEN (v_disc ->> 'item_index') IS NOT NULL
          THEN v_item_ids[GREATEST(1, ((v_disc ->> 'item_index')::integer + 1))]
        ELSE NULL
      END,
      NULLIF(v_disc ->> 'catalog_discount_id', '')::uuid,
      COALESCE(NULLIF(v_disc ->> 'discount_name', ''), 'Unknown'),
      COALESCE((v_disc ->> 'amount_rp')::numeric, 0),
      COALESCE((v_disc ->> 'line_quantity')::numeric, 0),
      NULLIF(v_disc ->> 'input_configuration', ''),
      NULLIF(v_disc ->> 'amount_unit', ''),
      NULLIF(v_disc ->> 'amount_value', '')::numeric,
      COALESCE(NULLIF(v_disc ->> 'value_label', ''), '—')
    );
  END LOOP;

  v_line_idx := 0;
  FOR v_line IN SELECT value FROM jsonb_array_elements(v_stock_lines)
  LOOP
    v_line_idx := v_line_idx + 1;
    v_line_key := COALESCE(NULLIF(btrim(v_line ->> 'line_key'), ''), 'L' || v_line_idx::text);
    v_scope := COALESCE(NULLIF(btrim(v_line ->> 'stock_scope'), ''), 'full');
    IF v_scope NOT IN ('full', 'recipe_only', 'finished_goods_only') THEN
      v_scope := 'full';
    END IF;

    IF NOT EXISTS (
      SELECT 1 FROM public.catalog_stock_movements
      WHERE organization_id = v_pending.organization_id
        AND reference_type = 'store_checkout'
        AND reference_id LIKE v_activity_id::text || ':' || v_line_key || ':%'
    ) THEN
      PERFORM public._apply_catalog_stock_lines(
        v_pending.organization_id,
        v_outlet,
        'store_checkout',
        v_activity_id::text,
        jsonb_build_array(v_line || jsonb_build_object('line_key', v_line_key)),
        v_scope
      );
    END IF;
  END LOOP;

  PERFORM public.apply_store_checkout_income(v_activity_id, 'qris', v_actor);

  SELECT id INTO v_payment_id
  FROM public.sales_activity_payments
  WHERE sales_activity_id = v_activity_id
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_pending.session_id IS NOT NULL THEN
    IF v_pending.keep_session_open THEN
      UPDATE public.pos_table_sessions
      SET cart_snapshot = COALESCE(v_pending.payload -> 'remainderCartLines', '[]'::jsonb)
      WHERE id = v_pending.session_id AND status = 'open';
    ELSE
      UPDATE public.pos_table_sessions
      SET
        status = 'paid',
        closed_at = now(),
        sales_activity_id = v_activity_id,
        closed_by = v_actor
      WHERE id = v_pending.session_id AND status = 'open';
    END IF;
  END IF;

  UPDATE public.pos_pending_checkouts
  SET
    status = 'paid',
    sales_activity_id = v_activity_id,
    paid_at = now(),
    updated_at = now()
  WHERE id = p_pending_id;

  UPDATE public.xendit_payment_requests
  SET sales_activity_id = v_activity_id
  WHERE pos_pending_checkout_id = p_pending_id;

  RETURN jsonb_build_object(
    'ok', true,
    'sales_activity_id', v_activity_id,
    'payment_id', v_payment_id
  );
END;
$$;


ALTER FUNCTION "public"."pos_finalize_qris_checkout"("p_pending_id" "uuid", "p_actor" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_gratuity_sales_by_rate"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("catalog_gratuity_id" "uuid", "gratuity_name" "text", "gratuity_sort_order" integer, "rate_label" "text", "rate_sort_order" integer, "times_applied" numeric, "gratuity_collected" numeric, "gross_gratuity" numeric, "refund_amount" numeric, "net_gratuity" numeric, "summary_total_net_gratuity" numeric, "has_backfill_estimate" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gratuity_total AS (
    SELECT sacg.sales_activity_id, COALESCE(SUM(COALESCE(sacg.amount_rp, 0)), 0)::numeric AS gratuity_total
    FROM public.sales_activity_checkout_gratuities sacg GROUP BY sacg.sales_activity_id
  ),
  sold AS (
    SELECT sacg.catalog_gratuity_id AS disc_id, sacg.gratuity_name AS disc_name, sacg.rate_label AS val_label,
      COALESCE(sacg.amount_percent, 0)::numeric AS val_sort, COUNT(*)::numeric AS times_applied,
      COALESCE(SUM(COALESCE(sacg.amount_rp, 0)), 0)::numeric AS gratuity_collected,
      BOOL_OR(sacg.is_backfill_estimate) AS has_backfill_estimate
    FROM public.sales_activity_checkout_gratuities sacg
    JOIN public.sales_activities sa ON sa.id = sacg.sales_activity_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from) AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY sacg.catalog_gratuity_id, sacg.gratuity_name, sacg.rate_label, sacg.amount_percent
  ),
  refund_activity_net AS (
    SELECT sa.id AS activity_id, COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted' AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from) AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT sacg.catalog_gratuity_id AS disc_id, sacg.gratuity_name AS disc_name, sacg.rate_label AS val_label,
      COALESCE(sacg.amount_percent, 0)::numeric AS val_sort,
      CASE WHEN agt.gratuity_total > 0 THEN COALESCE(sacg.amount_rp, 0) / agt.gratuity_total * ran.refund_total ELSE 0::numeric END AS refund_collected
    FROM refund_activity_net ran
    JOIN public.sales_activity_checkout_gratuities sacg ON sacg.sales_activity_id = ran.activity_id
    JOIN activity_gratuity_total agt ON agt.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT rl.disc_id, rl.disc_name, rl.val_label, rl.val_sort,
      COALESCE(SUM(COALESCE(rl.refund_collected, 0)), 0)::numeric AS refund_amount
    FROM refund_lines rl GROUP BY rl.disc_id, rl.disc_name, rl.val_label, rl.val_sort
  ),
  merged AS (
    SELECT s.disc_id, s.disc_name, s.val_label, s.val_sort, COALESCE(s.times_applied, 0)::numeric AS times_applied,
      COALESCE(s.gratuity_collected, 0)::numeric AS gratuity_collected, COALESCE(rg.refund_amount, 0)::numeric AS refund_amount,
      COALESCE(s.has_backfill_estimate, false) AS has_backfill_estimate
    FROM sold s
    LEFT JOIN refund_grouped rg ON rg.disc_id IS NOT DISTINCT FROM s.disc_id AND rg.disc_name = s.disc_name AND rg.val_label = s.val_label AND rg.val_sort = s.val_sort
    UNION ALL
    SELECT rg.disc_id, rg.disc_name, rg.val_label, rg.val_sort, 0::numeric, 0::numeric, rg.refund_amount, false
    FROM refund_grouped rg
    WHERE NOT EXISTS (SELECT 1 FROM sold s WHERE s.disc_id IS NOT DISTINCT FROM rg.disc_id AND s.disc_name = rg.disc_name AND s.val_label = rg.val_label AND s.val_sort = rg.val_sort)
  ),
  rolled AS (
    SELECT m.disc_id, m.disc_name, m.val_label, m.val_sort,
      COALESCE(SUM(m.times_applied), 0)::numeric AS times_applied,
      COALESCE(SUM(m.gratuity_collected), 0)::numeric AS gratuity_collected,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount,
      BOOL_OR(m.has_backfill_estimate) AS has_backfill_estimate
    FROM merged m GROUP BY m.disc_id, m.disc_name, m.val_label, m.val_sort
  ),
  summary AS (
    SELECT COALESCE(SUM(r.gratuity_collected - r.refund_amount), 0)::numeric AS net_total FROM rolled r
  )
  SELECT r.disc_id, r.disc_name, COALESCE(cg.sort_order, 9999)::integer, r.val_label, COALESCE(r.val_sort, 0)::integer,
    r.times_applied, r.gratuity_collected, r.gratuity_collected, r.refund_amount,
    (r.gratuity_collected - r.refund_amount)::numeric, s.net_total, r.has_backfill_estimate
  FROM rolled r CROSS JOIN summary s LEFT JOIN public.catalog_gratuities cg ON cg.id = r.disc_id
  WHERE r.times_applied > 0 OR r.gratuity_collected > 0 OR r.refund_amount > 0
  ORDER BY COALESCE(cg.sort_order, 9999), r.gratuity_collected DESC, r.val_label ASC;
END;
$$;


ALTER FUNCTION "public"."pos_gratuity_sales_by_rate"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_gratuity_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("catalog_gratuity_id" "uuid", "gratuity_name" "text", "sort_order" integer, "times_applied" numeric, "gratuity_collected" numeric, "gross_gratuity" numeric, "refund_amount" numeric, "net_gratuity" numeric, "summary_total_net_gratuity" numeric, "has_backfill_estimate" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gratuity_total AS (
    SELECT sacg.sales_activity_id,
      COALESCE(SUM(COALESCE(sacg.amount_rp, 0)), 0)::numeric AS gratuity_total
    FROM public.sales_activity_checkout_gratuities sacg
    GROUP BY sacg.sales_activity_id
  ),
  sold AS (
    SELECT sacg.catalog_gratuity_id AS disc_id, sacg.gratuity_name AS disc_name,
      COUNT(*)::numeric AS times_applied,
      COALESCE(SUM(COALESCE(sacg.amount_rp, 0)), 0)::numeric AS gratuity_collected,
      BOOL_OR(sacg.is_backfill_estimate) AS has_backfill_estimate
    FROM public.sales_activity_checkout_gratuities sacg
    JOIN public.sales_activities sa ON sa.id = sacg.sales_activity_id
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted' AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY sacg.catalog_gratuity_id, sacg.gratuity_name
  ),
  refund_activity_net AS (
    SELECT sa.id AS activity_id, COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted' AND sa.refund_status = 'full' AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT sacg.catalog_gratuity_id AS disc_id, sacg.gratuity_name AS disc_name,
      CASE WHEN agt.gratuity_total > 0 THEN COALESCE(sacg.amount_rp, 0) / agt.gratuity_total * ran.refund_total ELSE 0::numeric END AS refund_collected
    FROM refund_activity_net ran
    JOIN public.sales_activity_checkout_gratuities sacg ON sacg.sales_activity_id = ran.activity_id
    JOIN activity_gratuity_total agt ON agt.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT rl.disc_id, rl.disc_name, COALESCE(SUM(COALESCE(rl.refund_collected, 0)), 0)::numeric AS refund_amount
    FROM refund_lines rl GROUP BY rl.disc_id, rl.disc_name
  ),
  merged AS (
    SELECT s.disc_id, s.disc_name, COALESCE(s.times_applied, 0)::numeric AS times_applied,
      COALESCE(s.gratuity_collected, 0)::numeric AS gratuity_collected,
      COALESCE(rg.refund_amount, 0)::numeric AS refund_amount,
      COALESCE(s.has_backfill_estimate, false) AS has_backfill_estimate
    FROM sold s
    LEFT JOIN refund_grouped rg ON rg.disc_id IS NOT DISTINCT FROM s.disc_id AND rg.disc_name = s.disc_name
    UNION ALL
    SELECT rg.disc_id, rg.disc_name, 0::numeric, 0::numeric, rg.refund_amount, false
    FROM refund_grouped rg
    WHERE NOT EXISTS (SELECT 1 FROM sold s WHERE s.disc_id IS NOT DISTINCT FROM rg.disc_id AND s.disc_name = rg.disc_name)
  ),
  rolled AS (
    SELECT m.disc_id, m.disc_name,
      COALESCE(SUM(m.times_applied), 0)::numeric AS times_applied,
      COALESCE(SUM(m.gratuity_collected), 0)::numeric AS gratuity_collected,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount,
      BOOL_OR(m.has_backfill_estimate) AS has_backfill_estimate
    FROM merged m GROUP BY m.disc_id, m.disc_name
  ),
  summary AS (
    SELECT COALESCE(SUM(r.gratuity_collected - r.refund_amount), 0)::numeric AS net_total FROM rolled r
  )
  SELECT r.disc_id, r.disc_name, COALESCE(cg.sort_order, 9999)::integer, r.times_applied, r.gratuity_collected,
    r.gratuity_collected, r.refund_amount, (r.gratuity_collected - r.refund_amount)::numeric, s.net_total, r.has_backfill_estimate
  FROM rolled r CROSS JOIN summary s LEFT JOIN public.catalog_gratuities cg ON cg.id = r.disc_id
  WHERE r.times_applied > 0 OR r.gratuity_collected > 0 OR r.refund_amount > 0
  ORDER BY r.gratuity_collected DESC, r.disc_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_gratuity_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_gross_profit_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("catalog_product_id" "uuid", "catalog_variant_id" "uuid", "product_name" "text", "variant_name" "text", "category_id" "uuid", "category_name" "text", "qty" numeric, "net_sales" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  lines AS (
    SELECT
      sai.catalog_product_id AS product_id,
      sai.catalog_variant_id AS variant_id,
      dp.product_category_id AS cat_id,
      sai.service_name,
      sai.quantity,
      sai.total_price,
      sai.unit_cogs AS snapshot_cogs,
      sa.pos_outlet_id AS outlet_id,
      CASE
        WHEN ag.lines_gross > 0 AND sa.checkout_subtotal IS NOT NULL THEN
          COALESCE(sai.total_price, 0) * (
            public.pos_sales_activity_exclusive_net(
              sa.checkout_subtotal,
              sa.checkout_tax_amount,
              sa.checkout_gratuity_amount,
              COALESCE(sa.total_paid_amount, sa.total_amount, 0),
              sa.checkout_application_method
            ) / ag.lines_gross
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales,
      CASE
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            sa.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL) AS used_estimate_path
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND sai.item_kind = 'product'
      AND (p_category_id IS NULL OR dp.product_category_id = p_category_id)
  ),
  grouped AS (
    SELECT
      l.product_id,
      l.variant_id,
      l.cat_id,
      COALESCE(
        NULLIF(MAX(dp.name), ''),
        NULLIF(MAX(l.service_name), ''),
        'Unlinked'
      )::text AS product_name,
      NULLIF(MAX(cv.name), '')::text AS variant_name,
      NULLIF(MAX(cat.name), '')::text AS category_name,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL), false) AS cogs_incomplete,
      COALESCE(
        BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL),
        false
      ) AS cogs_estimated
    FROM lines l
    LEFT JOIN public.default_prices dp ON dp.id = l.product_id
    LEFT JOIN public.catalog_product_variants cv ON cv.id = l.variant_id
    LEFT JOIN public.catalog_product_categories cat ON cat.id = l.cat_id
    GROUP BY l.product_id, l.variant_id, l.cat_id
  )
  SELECT
    g.product_id AS catalog_product_id,
    g.variant_id AS catalog_variant_id,
    g.product_name,
    g.variant_name,
    g.cat_id AS category_id,
    g.category_name,
    g.qty,
    g.net_sales,
    g.cogs,
    (g.net_sales - g.cogs)::numeric AS gross_profit,
    CASE
      WHEN g.net_sales > 0 THEN ROUND(((g.net_sales - g.cogs) / g.net_sales) * 100, 2)
      ELSE 0::numeric
    END AS margin_pct,
    g.cogs_incomplete,
    g.cogs_estimated
  FROM grouped g
  ORDER BY (g.net_sales - g.cogs) DESC, g.net_sales DESC;
END;
$$;


ALTER FUNCTION "public"."pos_gross_profit_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_category_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_gross_profit_by_item"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_category_id" "uuid") IS 'Per-product/variant gross profit; optional p_category_id filters via default_prices.product_category_id.';



CREATE OR REPLACE FUNCTION "public"."pos_gross_profit_daily"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("day" "date", "net_sales" numeric, "cogs" numeric, "gross_profit" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  ELSIF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'forbidden_org'; END IF;
  RETURN QUERY
  WITH bounds AS (SELECT COALESCE(p_from, timestamptz '1970-01-01') AS from_ts, COALESCE(p_to, timestamptz '2100-01-01') AS to_ts),
  day_spine AS (SELECT d::date AS day FROM bounds b, LATERAL generate_series((b.from_ts AT TIME ZONE 'Asia/Jakarta')::date, ((b.to_ts - interval '1 second') AT TIME ZONE 'Asia/Jakarta')::date, interval '1 day') AS d),
  sales AS (
    SELECT (sa.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      COALESCE(SUM(public.pos_sales_activity_exclusive_net(sa.checkout_subtotal, sa.checkout_tax_amount, sa.checkout_gratuity_amount, COALESCE(sa.total_paid_amount, sa.total_amount, 0), sa.checkout_application_method)), 0)::numeric AS net_sales
    FROM public.sales_activities sa CROSS JOIN bounds b
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none' AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.created_at >= b.from_ts AND sa.created_at < b.to_ts GROUP BY 1),
  cogs_by_day AS (
    SELECT (sa.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      COALESCE(SUM(COALESCE(CASE WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN public.pos_estimate_line_unit_cogs(p_organization_id, sa.pos_outlet_id, sai.catalog_product_id, sai.catalog_variant_id) ELSE NULL END, 0) * COALESCE(sai.quantity, 0)), 0)::numeric AS cogs
    FROM public.sales_activities sa JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id CROSS JOIN bounds b
    WHERE sa.organization_id = p_organization_id AND sa.activity_type = 'Store Checkout' AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none' AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.created_at >= b.from_ts AND sa.created_at < b.to_ts AND sai.item_kind = 'product' GROUP BY 1)
  SELECT ds.day, COALESCE(s.net_sales, 0)::numeric, COALESCE(c.cogs, 0)::numeric, (COALESCE(s.net_sales, 0) - COALESCE(c.cogs, 0))::numeric
  FROM day_spine ds LEFT JOIN sales s ON s.day = ds.day LEFT JOIN cogs_by_day c ON c.day = ds.day ORDER BY ds.day;
END;
$$;


ALTER FUNCTION "public"."pos_gross_profit_daily"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_gross_profit_daily"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Daily net_sales / cogs / gross_profit (non-refunded Store Checkout by created_at WIB).';



CREATE OR REPLACE FUNCTION "public"."pos_gross_profit_non_product_breakdown"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("service_id" "uuid", "line_name" "text", "sub_name" "text", "line_kind" "text", "qty" numeric, "net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  lines AS (
    SELECT
      sai.service_id,
      COALESCE(NULLIF(TRIM(sai.service_name), ''), 'Custom amount')::text AS line_name,
      NULLIF(TRIM(sai.sub_service_name), '')::text AS sub_name,
      CASE
        WHEN sai.service_id IS NOT NULL THEN 'service'
        ELSE 'custom'
      END::text AS line_kind,
      sai.quantity,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) * (
            public.pos_sales_activity_exclusive_net(
              sa.checkout_subtotal,
              sa.checkout_tax_amount,
              sa.checkout_gratuity_amount,
              COALESCE(sa.total_paid_amount, sa.total_amount, 0),
              sa.checkout_application_method
            ) / ag.lines_gross
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND sai.item_kind <> 'product'
  ),
  grouped AS (
    SELECT
      l.service_id,
      l.line_name,
      l.sub_name,
      l.line_kind,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales
    FROM lines l
    GROUP BY l.service_id, l.line_name, l.sub_name, l.line_kind
  )
  SELECT
    g.service_id,
    g.line_name,
    g.sub_name,
    g.line_kind,
    g.qty,
    g.net_sales
  FROM grouped g
  WHERE g.net_sales > 0.01
  ORDER BY g.net_sales DESC, g.line_name ASC, g.sub_name ASC NULLS FIRST;
END;
$$;


ALTER FUNCTION "public"."pos_gross_profit_non_product_breakdown"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_gross_profit_non_product_breakdown"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Non-product/service net sales breakdown grouped by service name for gross profit items footer.';



CREATE OR REPLACE FUNCTION "public"."pos_gross_profit_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("gross_sales" numeric, "discounts" numeric, "refunds" numeric, "net_sales" numeric, "product_net_sales" numeric, "non_product_net" numeric, "gratuity" numeric, "tax" numeric, "cogs" numeric, "cogs_adjustment" numeric, "cogs_reversed" numeric, "gross_profit" numeric, "gross_profit_margin" numeric, "cogs_incomplete" boolean, "transaction_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_net numeric := 0;
  v_product_net numeric := 0;
  v_discounts numeric := 0;
  v_gratuity numeric := 0;
  v_tax numeric := 0;
  v_count bigint := 0;
  v_refunds numeric := 0;
  v_cogs numeric := 0;
  v_cogs_adjustment numeric := 0;
  v_cogs_reversed numeric := 0;
  v_incomplete boolean := false;
  v_from_ts timestamptz := COALESCE(p_from, timestamptz '1970-01-01');
  v_to_ts timestamptz := COALESCE(p_to, timestamptz '2100-01-01');
  v_from_date date := (v_from_ts AT TIME ZONE 'Asia/Jakarta')::date;
  v_to_date date := ((v_to_ts - interval '1 second') AT TIME ZONE 'Asia/Jakarta')::date;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  SELECT
    COALESCE(SUM(
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      )
    ), 0),
    COALESCE(SUM(COALESCE(sa.checkout_discount_amount, 0)), 0),
    COALESCE(SUM(COALESCE(sa.checkout_gratuity_amount, 0)), 0),
    COALESCE(SUM(COALESCE(sa.checkout_tax_amount, 0)), 0),
    COUNT(*)::bigint
  INTO v_net, v_discounts, v_gratuity, v_tax, v_count
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND sa.created_at >= v_from_ts
    AND sa.created_at < v_to_ts;

  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross,
      COALESCE(SUM(COALESCE(sai.total_price, 0)) FILTER (WHERE sai.item_kind = 'product'), 0)::numeric AS product_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  product_contrib AS (
    SELECT
      CASE
        WHEN ag.lines_gross > 0 THEN
          ag.product_gross * (
            public.pos_sales_activity_exclusive_net(
              sa.checkout_subtotal,
              sa.checkout_tax_amount,
              sa.checkout_gratuity_amount,
              COALESCE(sa.total_paid_amount, sa.total_amount, 0),
              sa.checkout_application_method
            ) / ag.lines_gross
          )
        ELSE 0::numeric
      END AS product_net_contrib
    FROM public.sales_activities sa
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.created_at >= v_from_ts
      AND sa.created_at < v_to_ts
  )
  SELECT COALESCE(SUM(product_net_contrib), 0)
  INTO v_product_net
  FROM product_contrib;

  SELECT COALESCE(SUM(COALESCE(sa.refund_amount, 0)), 0)
  INTO v_refunds
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'full'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND sa.refunded_at IS NOT NULL
    AND sa.refunded_at >= v_from_ts
    AND sa.refunded_at < v_to_ts;

  SELECT COALESCE(SUM(COALESCE(r.cogs_reversed, 0)), 0)
  INTO v_cogs_reversed
  FROM public.pos_sales_refunds r
  JOIN public.sales_activities sa ON sa.id = r.sales_activity_id
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND COALESCE(sa.refund_status, 'none') = 'full'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND sa.refunded_at IS NOT NULL
    AND sa.refunded_at >= v_from_ts
    AND sa.refunded_at < v_to_ts;

  SELECT COALESCE(SUM(a.amount), 0)
  INTO v_cogs_adjustment
  FROM public.pos_gross_profit_cogs_adjustments a
  WHERE a.organization_id = p_organization_id
    AND a.adjustment_date >= v_from_date
    AND a.adjustment_date <= v_to_date
    AND (
      p_outlet_id IS NULL
      OR a.pos_outlet_id IS NULL
      OR a.pos_outlet_id = p_outlet_id
    );

  WITH sold AS (
    SELECT
      sa.pos_outlet_id AS outlet_id,
      sai.quantity,
      sai.catalog_product_id,
      sai.catalog_variant_id,
      sai.unit_cogs
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.created_at >= v_from_ts
      AND sa.created_at < v_to_ts
      AND sai.item_kind = 'product'
  ),
  priced AS (
    SELECT
      s.quantity,
      CASE
        WHEN s.unit_cogs IS NOT NULL THEN s.unit_cogs
        WHEN s.catalog_product_id IS NOT NULL AND s.outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            s.outlet_id,
            s.catalog_product_id,
            s.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs
    FROM sold s
  )
  SELECT
    COALESCE(SUM(COALESCE(p.resolved_unit_cogs, 0) * COALESCE(p.quantity, 0)), 0),
    COALESCE(BOOL_OR(p.resolved_unit_cogs IS NULL), false)
  INTO v_cogs, v_incomplete
  FROM priced p;

  RETURN QUERY
  SELECT
    (v_net + v_discounts)::numeric AS gross_sales,
    v_discounts::numeric AS discounts,
    v_refunds::numeric AS refunds,
    v_net::numeric AS net_sales,
    v_product_net::numeric AS product_net_sales,
    GREATEST(0, v_net - v_product_net)::numeric AS non_product_net,
    v_gratuity::numeric AS gratuity,
    v_tax::numeric AS tax,
    v_cogs::numeric AS cogs,
    v_cogs_adjustment::numeric AS cogs_adjustment,
    v_cogs_reversed::numeric AS cogs_reversed,
    (v_net - v_cogs - v_cogs_adjustment)::numeric AS gross_profit,
    CASE
      WHEN v_net > 0 THEN ROUND(((v_net - v_cogs - v_cogs_adjustment) / v_net) * 100, 2)
      ELSE 0::numeric
    END AS gross_profit_margin,
    COALESCE(v_incomplete, false) AS cogs_incomplete,
    v_count;
END;
$$;


ALTER FUNCTION "public"."pos_gross_profit_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_gross_profit_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Gross profit with product/non-product net, manual COGS adjustments, and informational cogs_reversed on refunds.';



CREATE OR REPLACE FUNCTION "public"."pos_invoice_cancel"("p_activity_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_total numeric;
  v_paid numeric;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT sa.organization_id, COALESCE(sa.total_amount, 0), COALESCE(sa.total_paid_amount, 0)
  INTO v_org, v_total, v_paid
  FROM public.sales_activities sa
  WHERE sa.id = p_activity_id;

  IF v_org IS NULL THEN
    RAISE EXCEPTION 'not_found';
  END IF;

  IF v_org NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF v_paid >= v_total AND v_total > 0 THEN
    RAISE EXCEPTION 'invoice_already_paid';
  END IF;

  UPDATE public.sales_activities
  SET
    invoice_cancelled_at = COALESCE(invoice_cancelled_at, now()),
    invoice_cancel_reason = COALESCE(NULLIF(btrim(p_reason), ''), invoice_cancel_reason, '—'),
    updated_at = now()
  WHERE id = p_activity_id;
END;
$$;


ALTER FUNCTION "public"."pos_invoice_cancel"("p_activity_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_invoice_display_status"("p_invoice_cancelled_at" timestamp with time zone, "p_invoice_due_date" "date", "p_payment_status" "text", "p_total_amount" numeric, "p_total_paid_amount" numeric) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public', 'extensions'
    AS $$
DECLARE
  v_total numeric := GREATEST(COALESCE(p_total_amount, 0), 0);
  v_paid numeric := GREATEST(COALESCE(p_total_paid_amount, 0), 0);
  v_remaining numeric;
BEGIN
  IF p_invoice_cancelled_at IS NOT NULL THEN
    RETURN 'cancelled';
  END IF;

  IF v_total <= 0 THEN
    RETURN 'unpaid';
  END IF;

  IF v_paid >= v_total THEN
    RETURN 'paid';
  END IF;

  IF v_paid > 0 THEN
    IF p_invoice_due_date IS NOT NULL AND p_invoice_due_date < CURRENT_DATE THEN
      RETURN 'overdue';
    END IF;
    RETURN 'partial';
  END IF;

  IF p_invoice_due_date IS NOT NULL AND p_invoice_due_date < CURRENT_DATE THEN
    RETURN 'overdue';
  END IF;

  RETURN COALESCE(NULLIF(btrim(p_payment_status), ''), 'unpaid');
END;
$$;


ALTER FUNCTION "public"."pos_invoice_display_status"("p_invoice_cancelled_at" timestamp with time zone, "p_invoice_due_date" "date", "p_payment_status" "text", "p_total_amount" numeric, "p_total_paid_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_invoices_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_status_filter" "text" DEFAULT NULL::"text", "p_search_query" "text" DEFAULT NULL::"text", "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("activity_id" "uuid", "invoice_number" "text", "created_at" timestamp with time zone, "invoice_due_date" "date", "outlet_id" "uuid", "outlet_name" "text", "client_name" "text", "display_status" "text", "overdue_days" integer, "total_amount" numeric, "total_paid_amount" numeric, "amount_due" numeric, "item_summary" "text", "summary_count" bigint, "summary_unpaid" bigint, "summary_partial" bigint, "summary_paid" bigint, "summary_overdue" bigint, "summary_cancelled" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
  v_search text := btrim(COALESCE(p_search_query, ''));
  v_invoice_prefix text;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  v_invoice_prefix := upper(replace(replace(v_search, 'INV-', ''), '-', ''));

  RETURN QUERY
  WITH eligible AS (
    SELECT
      sa.id,
      sa.created_at,
      sa.invoice_number,
      sa.invoice_due_date,
      sa.invoice_cancelled_at,
      sa.payment_status,
      sa.client_name,
      sa.pos_outlet_id,
      COALESCE(sa.total_amount, 0)::numeric AS total_amount,
      COALESCE(sa.total_paid_amount, 0)::numeric AS total_paid_amount
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND lower(btrim(sa.activity_type)) <> 'store checkout'
      AND COALESCE(sa.total_amount, 0) > 0
      AND sa.invoice_number IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.sales_activity_items sai WHERE sai.sales_activity_id = sa.id
      )
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        v_search = ''
        OR sa.client_name ILIKE '%' || v_search || '%'
        OR upper(replace(COALESCE(sa.invoice_number, ''), '-', '')) LIKE '%' || upper(replace(v_search, '-', '')) || '%'
        OR (
          v_invoice_prefix <> ''
          AND upper(replace(sa.id::text, '-', '')) LIKE v_invoice_prefix || '%'
        )
      )
  ),
  enriched AS (
    SELECT
      e.*,
      public.pos_invoice_display_status(
        e.invoice_cancelled_at,
        e.invoice_due_date,
        e.payment_status,
        e.total_amount,
        e.total_paid_amount
      ) AS display_status,
      CASE
        WHEN e.invoice_cancelled_at IS NOT NULL THEN NULL
        WHEN e.invoice_due_date IS NULL THEN NULL
        WHEN e.invoice_due_date >= CURRENT_DATE THEN NULL
        ELSE (CURRENT_DATE - e.invoice_due_date)::integer
      END AS overdue_days,
      GREATEST(e.total_amount - e.total_paid_amount, 0)::numeric AS amount_due
    FROM eligible e
  ),
  filtered AS (
    SELECT e.*
    FROM enriched e
    WHERE p_status_filter IS NULL
       OR btrim(p_status_filter) = ''
       OR btrim(p_status_filter) = 'all'
       OR e.display_status = lower(btrim(p_status_filter))
  ),
  summary AS (
    SELECT
      COUNT(*)::bigint AS summary_count,
      COUNT(*) FILTER (WHERE f.display_status = 'unpaid')::bigint AS summary_unpaid,
      COUNT(*) FILTER (WHERE f.display_status = 'partial')::bigint AS summary_partial,
      COUNT(*) FILTER (WHERE f.display_status = 'paid')::bigint AS summary_paid,
      COUNT(*) FILTER (WHERE f.display_status = 'overdue')::bigint AS summary_overdue,
      COUNT(*) FILTER (WHERE f.display_status = 'cancelled')::bigint AS summary_cancelled
    FROM filtered f
  ),
  page AS (
    SELECT f.*
    FROM filtered f
    WHERE p_cursor IS NULL OR f.created_at < p_cursor
    ORDER BY f.created_at DESC
    LIMIT v_limit
  )
  SELECT
    p.id AS activity_id,
    COALESCE(p.invoice_number, 'INV-' || upper(substr(replace(p.id::text, '-', ''), 1, 8))) AS invoice_number,
    p.created_at,
    p.invoice_due_date,
    p.pos_outlet_id AS outlet_id,
    COALESCE(NULLIF(btrim(po.name), ''), '—') AS outlet_name,
    COALESCE(NULLIF(btrim(p.client_name), ''), '—') AS client_name,
    p.display_status,
    p.overdue_days,
    p.total_amount,
    p.total_paid_amount,
    p.amount_due,
    COALESCE(items.item_summary, '') AS item_summary,
    sm.summary_count,
    sm.summary_unpaid,
    sm.summary_partial,
    sm.summary_paid,
    sm.summary_overdue,
    sm.summary_cancelled
  FROM page p
  CROSS JOIN summary sm
  LEFT JOIN public.pos_outlets po ON po.id = p.pos_outlet_id
  LEFT JOIN LATERAL (
    SELECT string_agg(sub.n, ', ' ORDER BY sub.ord) AS item_summary
    FROM (
      SELECT
        COALESCE(NULLIF(btrim(sai.service_name), ''), 'Item') AS n,
        row_number() OVER (ORDER BY sai.created_at) AS ord
      FROM public.sales_activity_items sai
      WHERE sai.sales_activity_id = p.id
      ORDER BY sai.created_at
      LIMIT 3
    ) sub
  ) items ON true
  ORDER BY p.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."pos_invoices_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_status_filter" "text", "p_search_query" "text", "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_item_sales_hourly"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("product_key" "text", "item_name" "text", "variant_name" "text", "sku" "text", "hour" integer, "qty" numeric, "net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  hourly_lines AS (
    SELECT
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN 'b:' || sai.catalog_bundle_id::text
        WHEN sai.catalog_product_id IS NOT NULL THEN
          'p:' || sai.catalog_product_id::text || ':v:' || COALESCE(sai.catalog_variant_id::text, '')
        ELSE 'n:' || lower(btrim(COALESCE(sai.service_name, 'unlinked')))
      END AS product_key,
      COALESCE(
        NULLIF(cb.name, ''),
        NULLIF(dp.name, ''),
        NULLIF(sai.service_name, ''),
        'Unlinked'
      )::text AS resolved_name,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE NULLIF(cv.name, '') END::text AS resolved_variant,
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        ELSE COALESCE(
          NULLIF(cv.sku, ''),
          NULLIF(dp.sku, ''),
          NULLIF(isk.internal_sku, '')
        )
      END::text AS resolved_sku,
      EXTRACT(HOUR FROM sa.created_at AT TIME ZONE 'Asia/Jakarta')::integer AS sale_hour,
      COALESCE(sai.quantity, 0)::numeric AS line_qty,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(
            sa.checkout_subtotal,
            sa.checkout_tax_amount,
            sa.checkout_gratuity_amount,
            COALESCE(sa.total_paid_amount, sa.total_amount, 0),
            sa.checkout_application_method
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    LEFT JOIN public.catalog_product_variants cv ON cv.id = sai.catalog_variant_id
    LEFT JOIN public.catalog_bundles cb ON cb.id = sai.catalog_bundle_id
    LEFT JOIN public.inventory_skus isk ON isk.id = sai.inventory_sku_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        sai.item_kind = 'product'
        OR sai.catalog_bundle_id IS NOT NULL
      )
      AND sai.item_kind <> 'service'
  )
  SELECT
    hl.product_key,
    MAX(hl.resolved_name)::text AS item_name,
    MAX(hl.resolved_variant)::text AS variant_name,
    MAX(hl.resolved_sku)::text AS sku,
    hl.sale_hour AS hour,
    COALESCE(SUM(hl.line_qty), 0)::numeric AS qty,
    COALESCE(SUM(hl.net_line_sales), 0)::numeric AS net_sales
  FROM hourly_lines hl
  GROUP BY hl.product_key, hl.sale_hour
  ORDER BY MAX(hl.resolved_name), hl.sale_hour;
END;
$$;


ALTER FUNCTION "public"."pos_item_sales_hourly"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_item_sales_hourly"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Item Sales hourly matrix: qty and net sales per item × hour (0–23 WIB).';



CREATE OR REPLACE FUNCTION "public"."pos_item_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_category_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("catalog_product_id" "uuid", "catalog_variant_id" "uuid", "catalog_bundle_id" "uuid", "item_name" "text", "variant_name" "text", "sku" "text", "category_id" "uuid", "category_name" "text", "qty_sold" numeric, "qty_refunded" numeric, "gross_sales" numeric, "net_sales" numeric, "cogs" numeric, "gross_profit" numeric, "margin_pct" numeric, "cogs_incomplete" boolean, "cogs_estimated" boolean, "summary_product_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_summary_product_net numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold_lines AS (
    SELECT
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_product_id END AS product_id,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_variant_id END AS variant_id,
      sai.catalog_bundle_id AS bundle_id,
      dp.product_category_id AS cat_id,
      sai.service_name,
      sai.quantity,
      sai.inventory_sku_id,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(
            sa.checkout_subtotal,
            sa.checkout_tax_amount,
            sa.checkout_gratuity_amount,
            COALESCE(sa.total_paid_amount, sa.total_amount, 0),
            sa.checkout_application_method
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0)
        ELSE 0::numeric
      END AS discount_line,
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            sa.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        sai.item_kind = 'product'
        OR sai.catalog_bundle_id IS NOT NULL
      )
      AND sai.item_kind <> 'service'
      AND (
        p_category_id IS NULL
        OR sai.catalog_bundle_id IS NOT NULL
        OR dp.product_category_id = p_category_id
      )
  ),
  sold_grouped AS (
    SELECT
      l.product_id,
      l.variant_id,
      l.bundle_id,
      l.cat_id,
      COALESCE(
        NULLIF(MAX(cb.name), ''),
        NULLIF(MAX(dp.name), ''),
        NULLIF(MAX(l.service_name), ''),
        'Unlinked'
      )::text AS product_name,
      CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE NULLIF(MAX(cv.name), '') END::text AS variant_name,
      CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE NULLIF(MAX(cat.name), '') END::text AS category_name,
      CASE
        WHEN l.bundle_id IS NOT NULL THEN NULL
        ELSE COALESCE(
          NULLIF(MAX(cv.sku), ''),
          NULLIF(MAX(dp.sku), ''),
          NULLIF(MAX(isk.internal_sku), '')
        )
      END::text AS resolved_sku,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND l.bundle_id IS NULL), false) AS cogs_incomplete,
      COALESCE(
        BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL),
        false
      ) AS cogs_estimated
    FROM sold_lines l
    LEFT JOIN public.default_prices dp ON dp.id = l.product_id
    LEFT JOIN public.catalog_product_variants cv ON cv.id = l.variant_id
    LEFT JOIN public.catalog_product_categories cat ON cat.id = l.cat_id
    LEFT JOIN public.catalog_bundles cb ON cb.id = l.bundle_id
    LEFT JOIN public.inventory_skus isk ON isk.id = l.inventory_sku_id
    GROUP BY
      l.product_id,
      l.variant_id,
      l.bundle_id,
      l.cat_id,
      CASE
        WHEN l.product_id IS NULL AND l.bundle_id IS NULL
        THEN lower(btrim(COALESCE(l.service_name, '')))
        ELSE NULL
      END
  ),
  summary AS (
    SELECT COALESCE(SUM(sg.net_sales), 0)::numeric AS product_net
    FROM sold_grouped sg
  )
  SELECT s.product_net INTO v_summary_product_net FROM summary s;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold_lines AS (
    SELECT
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_product_id END AS product_id,
      CASE WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL ELSE sai.catalog_variant_id END AS variant_id,
      sai.catalog_bundle_id AS bundle_id,
      dp.product_category_id AS cat_id,
      sai.service_name,
      sai.quantity,
      sai.inventory_sku_id,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * public.pos_sales_activity_exclusive_net(
            sa.checkout_subtotal,
            sa.checkout_tax_amount,
            sa.checkout_gratuity_amount,
            COALESCE(sa.total_paid_amount, sa.total_amount, 0),
            sa.checkout_application_method
          )
        ELSE COALESCE(sai.total_price, 0)
      END AS net_line_sales,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(sa.checkout_discount_amount, 0)
        ELSE 0::numeric
      END AS discount_line,
      CASE
        WHEN sai.catalog_bundle_id IS NOT NULL THEN NULL
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND sa.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            p_organization_id,
            sa.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs,
      (sai.unit_cogs IS NULL AND sai.catalog_bundle_id IS NULL) AS used_estimate_path
    FROM public.sales_activities sa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    JOIN activity_gross ag ON ag.sales_activity_id = sa.id
    LEFT JOIN public.default_prices dp ON dp.id = sai.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        sai.item_kind = 'product'
        OR sai.catalog_bundle_id IS NOT NULL
      )
      AND sai.item_kind <> 'service'
      AND (
        p_category_id IS NULL
        OR sai.catalog_bundle_id IS NOT NULL
        OR dp.product_category_id = p_category_id
      )
  ),
  sold_grouped AS (
    SELECT
      l.product_id,
      l.variant_id,
      l.bundle_id,
      l.cat_id,
      COALESCE(
        NULLIF(MAX(cb.name), ''),
        NULLIF(MAX(dp.name), ''),
        NULLIF(MAX(l.service_name), ''),
        'Unlinked'
      )::text AS product_name,
      CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE NULLIF(MAX(cv.name), '') END::text AS variant_name,
      CASE WHEN l.bundle_id IS NOT NULL THEN NULL ELSE NULLIF(MAX(cat.name), '') END::text AS category_name,
      CASE
        WHEN l.bundle_id IS NOT NULL THEN NULL
        ELSE COALESCE(
          NULLIF(MAX(cv.sku), ''),
          NULLIF(MAX(dp.sku), ''),
          NULLIF(MAX(isk.internal_sku), '')
        )
      END::text AS resolved_sku,
      COALESCE(SUM(COALESCE(l.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0)), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(l.net_line_sales, 0) + COALESCE(l.discount_line, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(l.resolved_unit_cogs, 0) * COALESCE(l.quantity, 0)), 0)::numeric AS cogs,
      COALESCE(BOOL_OR(l.resolved_unit_cogs IS NULL AND l.bundle_id IS NULL), false) AS cogs_incomplete,
      COALESCE(
        BOOL_OR(l.used_estimate_path AND l.resolved_unit_cogs IS NOT NULL),
        false
      ) AS cogs_estimated
    FROM sold_lines l
    LEFT JOIN public.default_prices dp ON dp.id = l.product_id
    LEFT JOIN public.catalog_product_variants cv ON cv.id = l.variant_id
    LEFT JOIN public.catalog_product_categories cat ON cat.id = l.cat_id
    LEFT JOIN public.catalog_bundles cb ON cb.id = l.bundle_id
    LEFT JOIN public.inventory_skus isk ON isk.id = l.inventory_sku_id
    GROUP BY
      l.product_id,
      l.variant_id,
      l.bundle_id,
      l.cat_id,
      CASE
        WHEN l.product_id IS NULL AND l.bundle_id IS NULL
        THEN lower(btrim(COALESCE(l.service_name, '')))
        ELSE NULL
      END
  ),
  refund_grouped AS (
    SELECT
      rcl.catalog_product_id AS product_id,
      rcl.catalog_variant_id AS variant_id,
      COALESCE(SUM(COALESCE(rcl.quantity, 0)), 0)::numeric AS qty_refunded
    FROM public.pos_sales_refund_cogs_lines rcl
    JOIN public.pos_sales_refunds pr ON pr.id = rcl.refund_id
    JOIN public.sales_activities sa ON sa.id = pr.sales_activity_id
    LEFT JOIN public.default_prices dp ON dp.id = rcl.catalog_product_id
    WHERE sa.organization_id = p_organization_id
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
      AND (p_category_id IS NULL OR dp.product_category_id = p_category_id)
    GROUP BY rcl.catalog_product_id, rcl.catalog_variant_id
  ),
  merged AS (
    SELECT
      sg.product_id,
      sg.variant_id,
      sg.bundle_id,
      sg.cat_id,
      sg.product_name,
      sg.variant_name,
      sg.category_name,
      sg.resolved_sku,
      sg.qty_sold,
      COALESCE(rg.qty_refunded, 0)::numeric AS qty_refunded,
      sg.gross_sales,
      sg.net_sales,
      sg.cogs,
      sg.cogs_incomplete,
      sg.cogs_estimated
    FROM sold_grouped sg
    LEFT JOIN refund_grouped rg
      ON sg.product_id IS NOT DISTINCT FROM rg.product_id
     AND sg.variant_id IS NOT DISTINCT FROM rg.variant_id
     AND sg.bundle_id IS NULL
    UNION ALL
    SELECT
      rg.product_id,
      rg.variant_id,
      NULL::uuid AS bundle_id,
      dp.product_category_id AS cat_id,
      COALESCE(NULLIF(dp.name, ''), 'Unlinked')::text AS product_name,
      NULLIF(cv.name, '')::text AS variant_name,
      NULLIF(cat.name, '')::text AS category_name,
      COALESCE(NULLIF(cv.sku, ''), NULLIF(dp.sku, ''))::text AS resolved_sku,
      0::numeric AS qty_sold,
      rg.qty_refunded,
      0::numeric AS gross_sales,
      0::numeric AS net_sales,
      0::numeric AS cogs,
      false AS cogs_incomplete,
      false AS cogs_estimated
    FROM refund_grouped rg
    LEFT JOIN public.default_prices dp ON dp.id = rg.product_id
    LEFT JOIN public.catalog_product_variants cv ON cv.id = rg.variant_id
    LEFT JOIN public.catalog_product_categories cat ON cat.id = dp.product_category_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM sold_grouped sg
      WHERE sg.product_id IS NOT DISTINCT FROM rg.product_id
        AND sg.variant_id IS NOT DISTINCT FROM rg.variant_id
        AND sg.bundle_id IS NULL
    )
  )
  SELECT
    m.product_id AS catalog_product_id,
    m.variant_id AS catalog_variant_id,
    m.bundle_id AS catalog_bundle_id,
    COALESCE(m.product_name, 'Unlinked')::text AS item_name,
    m.variant_name,
    m.resolved_sku AS sku,
    m.cat_id AS category_id,
    m.category_name,
    m.qty_sold,
    m.qty_refunded,
    m.gross_sales,
    m.net_sales,
    m.cogs,
    (m.net_sales - m.cogs)::numeric AS gross_profit,
    CASE
      WHEN m.net_sales > 0 THEN ROUND(((m.net_sales - m.cogs) / m.net_sales) * 100, 2)
      ELSE 0::numeric
    END AS margin_pct,
    m.cogs_incomplete,
    m.cogs_estimated,
    v_summary_product_net AS summary_product_net_sales
  FROM merged m
  ORDER BY m.net_sales DESC, m.qty_sold DESC;
END;
$$;


ALTER FUNCTION "public"."pos_item_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_category_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_item_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_category_id" "uuid") IS 'Item Sales summary: qty sold/refunded, gross/net, COGS per product+variant; optional category filter.';



CREATE OR REPLACE FUNCTION "public"."pos_mark_synckerja_cashier_kitchen_fired"("p_pending_id" "uuid", "p_outlet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pending public.pos_pending_checkouts%ROWTYPE;
  v_payload jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unauthorized');
  END IF;
  SELECT * INTO v_pending
  FROM public.pos_pending_checkouts
  WHERE id = p_pending_id
    AND pos_outlet_id = p_outlet_id
    AND checkout_channel = 'synckerja_cashier'
    AND organization_id IN (SELECT public.user_organization_ids());
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  v_payload := COALESCE(v_pending.payload, '{}'::jsonb) || jsonb_build_object('kitchenFired', true);
  UPDATE public.pos_pending_checkouts SET payload = v_payload WHERE id = v_pending.id;
  RETURN jsonb_build_object('ok', true, 'kitchen_fired', true);
END;
$$;


ALTER FUNCTION "public"."pos_mark_synckerja_cashier_kitchen_fired"("p_pending_id" "uuid", "p_outlet_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_modifier_sales_by_option"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("group_id" "uuid", "group_name" "text", "group_sort_order" integer, "option_id" "uuid", "option_name" "text", "option_sort_order" integer, "qty_sold" numeric, "gross_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "net_sales" numeric, "summary_modifier_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold AS (
    SELECT
      saim.modifier_group_id AS grp_id,
      saim.modifier_option_id AS opt_id,
      COALESCE(SUM(COALESCE(saim.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(saim.gross_sales, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(saim.discount_amount, 0)), 0)::numeric AS discount_amount
    FROM public.sales_activity_item_modifiers saim
    JOIN public.sales_activities sa ON sa.id = saim.sales_activity_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY saim.modifier_group_id, saim.modifier_option_id
  ),
  refund_activity_net AS (
    SELECT
      sa.id AS activity_id,
      COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT
      saim.modifier_group_id AS grp_id,
      saim.modifier_option_id AS opt_id,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(saim.gross_sales, 0) / ag.lines_gross * ran.refund_total
        ELSE 0::numeric
      END AS refund_line_amount
    FROM refund_activity_net ran
    JOIN public.sales_activity_item_modifiers saim ON saim.sales_activity_id = ran.activity_id
    JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT
      rl.grp_id,
      rl.opt_id,
      COALESCE(SUM(COALESCE(rl.refund_line_amount, 0)), 0)::numeric AS refund_amount
    FROM refund_lines rl
    GROUP BY rl.grp_id, rl.opt_id
  ),
  merged AS (
    SELECT
      s.grp_id,
      s.opt_id,
      COALESCE(s.qty_sold, 0)::numeric AS qty_sold,
      COALESCE(s.gross_sales, 0)::numeric AS gross_sales,
      COALESCE(s.discount_amount, 0)::numeric AS discount_amount,
      COALESCE(rg.refund_amount, 0)::numeric AS refund_amount
    FROM sold s
    LEFT JOIN refund_grouped rg
      ON rg.grp_id IS NOT DISTINCT FROM s.grp_id
     AND rg.opt_id = s.opt_id
    UNION ALL
    SELECT
      rg.grp_id,
      rg.opt_id,
      0::numeric AS qty_sold,
      0::numeric AS gross_sales,
      0::numeric AS discount_amount,
      rg.refund_amount
    FROM refund_grouped rg
    WHERE NOT EXISTS (
      SELECT 1
      FROM sold s
      WHERE s.grp_id IS NOT DISTINCT FROM rg.grp_id
        AND s.opt_id = rg.opt_id
    )
  ),
  rolled AS (
    SELECT
      m.grp_id,
      m.opt_id,
      COALESCE(SUM(m.qty_sold), 0)::numeric AS qty_sold,
      COALESCE(SUM(m.gross_sales), 0)::numeric AS gross_sales,
      COALESCE(SUM(m.discount_amount), 0)::numeric AS discount_amount,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount
    FROM merged m
    GROUP BY m.grp_id, m.opt_id
  ),
  summary AS (
    SELECT
      COALESCE(SUM(r.gross_sales - r.discount_amount - r.refund_amount), 0)::numeric AS net_total
    FROM rolled r
  )
  SELECT
    r.grp_id AS group_id,
    COALESCE(
      NULLIF(btrim(g.name), ''),
      NULLIF(
        btrim(
          (
            SELECT sn.group_name
            FROM public.sales_activity_item_modifiers sn
            WHERE sn.modifier_group_id IS NOT DISTINCT FROM r.grp_id
            ORDER BY sn.created_at DESC
            LIMIT 1
          )
        ),
        ''
      ),
      'Unknown'
    )::text AS group_name,
    COALESCE(g.sort_order, 9999)::integer AS group_sort_order,
    r.opt_id AS option_id,
    COALESCE(
      NULLIF(btrim(o.name), ''),
      NULLIF(
        btrim(
          (
            SELECT sn.option_name
            FROM public.sales_activity_item_modifiers sn
            WHERE sn.modifier_option_id = r.opt_id
            ORDER BY sn.created_at DESC
            LIMIT 1
          )
        ),
        ''
      ),
      'Unknown'
    )::text AS option_name,
    COALESCE(o.sort_order, 9999)::integer AS option_sort_order,
    r.qty_sold,
    r.gross_sales,
    r.discount_amount,
    r.refund_amount,
    (r.gross_sales - r.discount_amount - r.refund_amount)::numeric AS net_sales,
    s.net_total AS summary_modifier_net_sales
  FROM rolled r
  CROSS JOIN summary s
  LEFT JOIN public.catalog_modifier_groups g ON g.id = r.grp_id
  LEFT JOIN public.catalog_modifier_options o ON o.id = r.opt_id
  WHERE r.qty_sold > 0
     OR r.gross_sales > 0
     OR r.refund_amount > 0
  ORDER BY COALESCE(g.sort_order, 9999), r.gross_sales DESC, COALESCE(o.name, 'Unknown') ASC;
END;
$$;


ALTER FUNCTION "public"."pos_modifier_sales_by_option"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_modifier_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("group_id" "uuid", "group_name" "text", "sort_order" integer, "qty_sold" numeric, "gross_sales" numeric, "discount_amount" numeric, "refund_amount" numeric, "net_sales" numeric, "summary_modifier_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    GROUP BY sai.sales_activity_id
  ),
  sold AS (
    SELECT
      saim.modifier_group_id AS grp_id,
      COALESCE(SUM(COALESCE(saim.quantity, 0)), 0)::numeric AS qty_sold,
      COALESCE(SUM(COALESCE(saim.gross_sales, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(COALESCE(saim.discount_amount, 0)), 0)::numeric AS discount_amount
    FROM public.sales_activity_item_modifiers saim
    JOIN public.sales_activities sa ON sa.id = saim.sales_activity_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY saim.modifier_group_id
  ),
  refund_activity_net AS (
    SELECT
      sa.id AS activity_id,
      COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT
      saim.modifier_group_id AS grp_id,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(saim.gross_sales, 0) / ag.lines_gross * ran.refund_total
        ELSE 0::numeric
      END AS refund_line_amount
    FROM refund_activity_net ran
    JOIN public.sales_activity_item_modifiers saim ON saim.sales_activity_id = ran.activity_id
    JOIN activity_gross ag ON ag.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT
      rl.grp_id,
      COALESCE(SUM(COALESCE(rl.refund_line_amount, 0)), 0)::numeric AS refund_amount
    FROM refund_lines rl
    GROUP BY rl.grp_id
  ),
  merged AS (
    SELECT
      s.grp_id,
      COALESCE(s.qty_sold, 0)::numeric AS qty_sold,
      COALESCE(s.gross_sales, 0)::numeric AS gross_sales,
      COALESCE(s.discount_amount, 0)::numeric AS discount_amount,
      COALESCE(rg.refund_amount, 0)::numeric AS refund_amount
    FROM sold s
    LEFT JOIN refund_grouped rg ON rg.grp_id IS NOT DISTINCT FROM s.grp_id
    UNION ALL
    SELECT
      rg.grp_id,
      0::numeric AS qty_sold,
      0::numeric AS gross_sales,
      0::numeric AS discount_amount,
      rg.refund_amount
    FROM refund_grouped rg
    WHERE NOT EXISTS (
      SELECT 1 FROM sold s WHERE s.grp_id IS NOT DISTINCT FROM rg.grp_id
    )
  ),
  rolled AS (
    SELECT
      m.grp_id,
      COALESCE(SUM(m.qty_sold), 0)::numeric AS qty_sold,
      COALESCE(SUM(m.gross_sales), 0)::numeric AS gross_sales,
      COALESCE(SUM(m.discount_amount), 0)::numeric AS discount_amount,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount
    FROM merged m
    GROUP BY m.grp_id
  ),
  summary AS (
    SELECT
      COALESCE(SUM(r.gross_sales - r.discount_amount - r.refund_amount), 0)::numeric AS net_total
    FROM rolled r
  )
  SELECT
    r.grp_id AS group_id,
    COALESCE(
      NULLIF(btrim(g.name), ''),
      NULLIF(
        btrim(
          (
            SELECT sn.group_name
            FROM public.sales_activity_item_modifiers sn
            WHERE sn.modifier_group_id IS NOT DISTINCT FROM r.grp_id
            ORDER BY sn.created_at DESC
            LIMIT 1
          )
        ),
        ''
      ),
      'Unknown'
    )::text AS group_name,
    COALESCE(g.sort_order, 9999)::integer AS sort_order,
    r.qty_sold,
    r.gross_sales,
    r.discount_amount,
    r.refund_amount,
    (r.gross_sales - r.discount_amount - r.refund_amount)::numeric AS net_sales,
    s.net_total AS summary_modifier_net_sales
  FROM rolled r
  CROSS JOIN summary s
  LEFT JOIN public.catalog_modifier_groups g ON g.id = r.grp_id
  WHERE r.qty_sold > 0
     OR r.gross_sales > 0
     OR r.refund_amount > 0
  ORDER BY r.gross_sales DESC, COALESCE(g.name, 'Unknown') ASC;
END;
$$;


ALTER FUNCTION "public"."pos_modifier_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_outlets_assign_public_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'extensions'
    AS $$
BEGIN
  IF NEW.public_code IS NULL OR btrim(NEW.public_code) = '' THEN
    NEW.public_code := public.generate_pos_outlet_public_code();
  ELSE
    NEW.public_code := lower(btrim(NEW.public_code));
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."pos_outlets_assign_public_code"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_payment_methods_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("category" "text", "channel_id" "uuid", "channel_name" "text", "channel_slug" "text", "transaction_count" bigint, "total_collected" numeric, "summary_total_collected" numeric, "summary_transaction_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_summary_total numeric := 0;
  v_summary_count bigint := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  PERFORM public.pos_seed_default_payment_channels(p_organization_id);

  SELECT
    COALESCE(SUM(COALESCE(sa.total_paid_amount, sa.total_amount, 0)), 0),
    COUNT(*)::bigint
  INTO v_summary_total, v_summary_count
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND (p_from IS NULL OR sa.created_at >= p_from)
    AND (p_to IS NULL OR sa.created_at < p_to);

  RETURN QUERY
  WITH sales AS (
    SELECT
      sa.id,
      sa.payment_method,
      sa.payment_reference,
      sa.payment_channel_id,
      COALESCE(sa.total_paid_amount, sa.total_amount, 0)::numeric AS collected
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  ),
  resolved AS (
    SELECT
      s.id,
      s.collected,
      COALESCE(
        ch.category,
        CASE lower(COALESCE(s.payment_method, ''))
          WHEN 'cash' THEN 'cash'
          WHEN 'e_wallet' THEN 'e_wallet'
          WHEN 'bank_transfer' THEN 'edc'
          WHEN 'transfer' THEN 'edc'
          WHEN 'credit_card' THEN 'edc'
          ELSE 'other'
        END
      ) AS category,
      ch.id AS channel_id,
      COALESCE(
        ch.name,
        NULLIF(TRIM(s.payment_reference), ''),
        CASE lower(COALESCE(s.payment_method, ''))
          WHEN 'cash' THEN 'Cash'
          WHEN 'e_wallet' THEN 'E-Wallet'
          WHEN 'bank_transfer' THEN 'Bank Transfer'
          WHEN 'transfer' THEN 'Bank Transfer'
          ELSE COALESCE(s.payment_method, 'Other')
        END
      ) AS channel_name,
      COALESCE(ch.slug, NULLIF(TRIM(s.payment_reference), ''), lower(COALESCE(s.payment_method, 'other'))) AS channel_slug
    FROM sales s
    LEFT JOIN public.pos_payment_method_channels ch ON ch.id = s.payment_channel_id
  ),
  grouped AS (
    SELECT
      r.category,
      r.channel_id,
      r.channel_name,
      r.channel_slug,
      COUNT(*)::bigint AS transaction_count,
      COALESCE(SUM(r.collected), 0)::numeric AS total_collected
    FROM resolved r
    GROUP BY r.category, r.channel_id, r.channel_name, r.channel_slug
  )
  SELECT
    g.category,
    g.channel_id,
    g.channel_name,
    g.channel_slug,
    g.transaction_count,
    g.total_collected,
    v_summary_total AS summary_total_collected,
    v_summary_count AS summary_transaction_count
  FROM grouped g
  ORDER BY
    CASE g.category
      WHEN 'cash' THEN 1
      WHEN 'e_wallet' THEN 2
      WHEN 'edc' THEN 3
      WHEN 'e_commerce' THEN 4
      WHEN 'integration' THEN 5
      ELSE 6
    END,
    g.channel_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_payment_methods_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_payment_methods_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Payment Methods report: txn count and total collected by category/channel for Store Checkout sales.';



CREATE OR REPLACE FUNCTION "public"."pos_receipt_feedback_sentiment"("p_rating" smallint) RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_rating >= 4 THEN 'good'
    WHEN p_rating <= 3 THEN 'bad'
    ELSE NULL
  END;
$$;


ALTER FUNCTION "public"."pos_receipt_feedback_sentiment"("p_rating" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_refund_store_checkout"("p_activity_id" "uuid", "p_reason" "text" DEFAULT NULL::"text", "p_actor" "uuid" DEFAULT NULL::"uuid", "p_shift_id" "uuid" DEFAULT NULL::"uuid", "p_reverse_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_activity public.sales_activities%ROWTYPE;
  v_actor uuid;
  v_amount numeric;
  v_reverse_id text;
  v_payment_id uuid;
  v_income public.income_transactions%ROWTYPE;
  v_balance_before numeric;
  v_balance_after numeric;
  v_refund_id uuid;
  v_cogs_reversed numeric := 0;
  v_cogs_incomplete boolean := false;
BEGIN
  v_actor := COALESCE(p_actor, auth.uid());
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_activity_id IS NULL THEN
    RAISE EXCEPTION 'pos_refund_activity_required';
  END IF;

  SELECT * INTO v_activity
  FROM public.sales_activities
  WHERE id = p_activity_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'store_checkout_not_found';
  END IF;

  IF v_activity.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF v_activity.activity_type IS DISTINCT FROM 'Store Checkout'
     OR v_activity.status IS DISTINCT FROM 'Converted' THEN
    RAISE EXCEPTION 'store_checkout_wrong_type';
  END IF;

  IF COALESCE(v_activity.refund_status, 'none') = 'full' THEN
    RAISE EXCEPTION 'already_refunded';
  END IF;

  v_amount := COALESCE(v_activity.total_paid_amount, v_activity.total_amount, 0);
  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'store_checkout_invalid_amount';
  END IF;

  v_reverse_id := COALESCE(NULLIF(btrim(p_reverse_id), ''), 'refund-' || p_activity_id::text);

  SELECT sap.id INTO v_payment_id
  FROM public.sales_activity_payments sap
  WHERE sap.sales_activity_id = p_activity_id
  ORDER BY sap.created_at DESC NULLS LAST
  LIMIT 1;

  IF v_payment_id IS NOT NULL THEN
    SELECT * INTO v_income
    FROM public.income_transactions it
    WHERE it.sales_activity_payment_id = v_payment_id
    ORDER BY it.created_at DESC NULLS LAST
    LIMIT 1
    FOR UPDATE;

    IF FOUND AND COALESCE(v_income.status, '') IS DISTINCT FROM 'cancelled' THEN
      IF v_income.deposit_confirmed_at IS NOT NULL
         AND v_income.bank_account_id IS NOT NULL
         AND COALESCE(v_income.amount, 0) > 0 THEN
        INSERT INTO public.bank_account_balances (bank_account_id, organization_id, balance)
        VALUES (v_income.bank_account_id, v_income.organization_id, 0)
        ON CONFLICT (bank_account_id) DO NOTHING;

        SELECT balance INTO v_balance_before
        FROM public.bank_account_balances
        WHERE bank_account_id = v_income.bank_account_id
        FOR UPDATE;

        v_balance_after := COALESCE(v_balance_before, 0) - COALESCE(v_income.amount, 0);

        UPDATE public.bank_account_balances
        SET balance = v_balance_after, updated_at = now()
        WHERE bank_account_id = v_income.bank_account_id;

        INSERT INTO public.bank_account_balance_history (
          bank_account_id, organization_id, transaction_type, transaction_id,
          amount, balance_before, balance_after, description, created_by
        ) VALUES (
          v_income.bank_account_id,
          v_income.organization_id,
          'income',
          v_income.id,
          -COALESCE(v_income.amount, 0),
          COALESCE(v_balance_before, 0),
          v_balance_after,
          'Store checkout refund reversal',
          v_actor
        );
      END IF;

      UPDATE public.income_transactions
      SET
        status = 'cancelled',
        updated_at = now()
      WHERE id = v_income.id;
    END IF;
  END IF;

  UPDATE public.sales_activities
  SET
    refund_status = 'full',
    refund_amount = v_amount,
    refunded_at = now(),
    refunded_by = v_actor,
    refund_reason = NULLIF(btrim(COALESCE(p_reason, '')), ''),
    refund_pos_shift_id = p_shift_id,
    refund_reverse_id = v_reverse_id,
    updated_at = now()
  WHERE id = p_activity_id;

  -- Resolve COGS for product lines (snapshot else estimate) before insert refund row
  SELECT
    COALESCE(SUM(COALESCE(x.resolved_unit_cogs, 0) * COALESCE(x.quantity, 0)), 0),
    COALESCE(BOOL_OR(x.resolved_unit_cogs IS NULL), false)
  INTO v_cogs_reversed, v_cogs_incomplete
  FROM (
    SELECT
      sai.quantity,
      CASE
        WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
        WHEN sai.catalog_product_id IS NOT NULL AND v_activity.pos_outlet_id IS NOT NULL THEN
          public.pos_estimate_line_unit_cogs(
            v_activity.organization_id,
            v_activity.pos_outlet_id,
            sai.catalog_product_id,
            sai.catalog_variant_id
          )
        ELSE NULL
      END AS resolved_unit_cogs
    FROM public.sales_activity_items sai
    WHERE sai.sales_activity_id = p_activity_id
      AND sai.item_kind = 'product'
  ) x;

  INSERT INTO public.pos_sales_refunds (
    organization_id,
    sales_activity_id,
    amount,
    reason,
    pos_shift_id,
    refunded_by,
    reverse_id,
    cogs_reversed,
    cogs_incomplete
  )
  VALUES (
    v_activity.organization_id,
    p_activity_id,
    v_amount,
    NULLIF(btrim(COALESCE(p_reason, '')), ''),
    p_shift_id,
    v_actor,
    v_reverse_id,
    v_cogs_reversed,
    v_cogs_incomplete
  )
  RETURNING id INTO v_refund_id;

  INSERT INTO public.pos_sales_refund_cogs_lines (
    organization_id,
    refund_id,
    sales_activity_item_id,
    catalog_product_id,
    catalog_variant_id,
    quantity,
    unit_cogs,
    cogs_source,
    line_cogs
  )
  SELECT
    v_activity.organization_id,
    v_refund_id,
    sai.id,
    sai.catalog_product_id,
    sai.catalog_variant_id,
    COALESCE(sai.quantity, 0),
    CASE
      WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
      WHEN sai.catalog_product_id IS NOT NULL AND v_activity.pos_outlet_id IS NOT NULL THEN
        public.pos_estimate_line_unit_cogs(
          v_activity.organization_id,
          v_activity.pos_outlet_id,
          sai.catalog_product_id,
          sai.catalog_variant_id
        )
      ELSE NULL
    END,
    CASE
      WHEN sai.unit_cogs IS NOT NULL THEN COALESCE(sai.cogs_source, 'snapshot')
      WHEN sai.catalog_product_id IS NOT NULL AND v_activity.pos_outlet_id IS NOT NULL
           AND public.pos_estimate_line_unit_cogs(
             v_activity.organization_id,
             v_activity.pos_outlet_id,
             sai.catalog_product_id,
             sai.catalog_variant_id
           ) IS NOT NULL
        THEN 'estimated'
      ELSE 'none'
    END,
    COALESCE(
      (
        CASE
          WHEN sai.unit_cogs IS NOT NULL THEN sai.unit_cogs
          WHEN sai.catalog_product_id IS NOT NULL AND v_activity.pos_outlet_id IS NOT NULL THEN
            public.pos_estimate_line_unit_cogs(
              v_activity.organization_id,
              v_activity.pos_outlet_id,
              sai.catalog_product_id,
              sai.catalog_variant_id
            )
          ELSE NULL
        END
      ) * COALESCE(sai.quantity, 0),
      0
    )
  FROM public.sales_activity_items sai
  WHERE sai.sales_activity_id = p_activity_id
    AND sai.item_kind = 'product';

  RETURN jsonb_build_object(
    'ok', true,
    'refund_id', v_refund_id,
    'activity_id', p_activity_id,
    'amount', v_amount,
    'reverse_id', v_reverse_id,
    'cogs_reversed', v_cogs_reversed,
    'cogs_incomplete', v_cogs_incomplete
  );
END;
$$;


ALTER FUNCTION "public"."pos_refund_store_checkout"("p_activity_id" "uuid", "p_reason" "text", "p_actor" "uuid", "p_shift_id" "uuid", "p_reverse_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_sales_activity_exclusive_net"("p_subtotal" numeric, "p_tax" numeric, "p_gratuity" numeric, "p_paid" numeric, "p_method" "text" DEFAULT NULL::"text") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN public.pos_sales_activity_tax_inclusive(
      p_subtotal,
      p_tax,
      p_gratuity,
      p_paid,
      p_method
    ) THEN GREATEST(
      0,
      COALESCE(p_subtotal, 0)
        - COALESCE(p_tax, 0)
        - COALESCE(p_gratuity, 0)
    )
    ELSE COALESCE(
      p_subtotal,
      p_paid,
      0
    )
  END;
$$;


ALTER FUNCTION "public"."pos_sales_activity_exclusive_net"("p_subtotal" numeric, "p_tax" numeric, "p_gratuity" numeric, "p_paid" numeric, "p_method" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_sales_activity_exclusive_net"("p_subtotal" numeric, "p_tax" numeric, "p_gratuity" numeric, "p_paid" numeric, "p_method" "text") IS 'Report net sales (Moka-style): exclusive of tax/gratuity when checkout is tax-inclusive.';



CREATE OR REPLACE FUNCTION "public"."pos_sales_activity_tax_inclusive"("p_subtotal" numeric, "p_tax" numeric, "p_gratuity" numeric, "p_paid" numeric, "p_method" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_method = 'include' THEN true
    WHEN p_method = 'add' THEN false
    WHEN p_subtotal IS NOT NULL
         AND ABS(COALESCE(p_paid, 0) - COALESCE(p_subtotal, 0)) < 1
         AND (COALESCE(p_tax, 0) + COALESCE(p_gratuity, 0)) > 0 THEN true
    ELSE false
  END;
$$;


ALTER FUNCTION "public"."pos_sales_activity_tax_inclusive"("p_subtotal" numeric, "p_tax" numeric, "p_gratuity" numeric, "p_paid" numeric, "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_sales_summary_daily"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("day" "date", "net_sales" numeric, "gross_sales" numeric, "total_collected" numeric, "refunds" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH bounds AS (
    SELECT
      COALESCE(p_from, timestamptz '1970-01-01') AS from_ts,
      COALESCE(p_to, timestamptz '2100-01-01') AS to_ts
  ),
  day_spine AS (
    SELECT d::date AS day
    FROM bounds b,
    LATERAL generate_series(
      (b.from_ts AT TIME ZONE 'Asia/Jakarta')::date,
      ((b.to_ts - interval '1 second') AT TIME ZONE 'Asia/Jakarta')::date,
      interval '1 day'
    ) AS d
  ),
  sales AS (
    SELECT
      (sa.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      COALESCE(SUM(
        public.pos_sales_activity_exclusive_net(
          sa.checkout_subtotal,
          sa.checkout_tax_amount,
          sa.checkout_gratuity_amount,
          COALESCE(sa.total_paid_amount, sa.total_amount, 0),
          sa.checkout_application_method
        )
      ), 0)::numeric AS net_sales,
      COALESCE(SUM(COALESCE(sa.checkout_discount_amount, 0)), 0)::numeric AS discounts,
      COALESCE(SUM(COALESCE(sa.total_paid_amount, sa.total_amount, 0)), 0)::numeric AS total_collected
    FROM public.sales_activities sa
    CROSS JOIN bounds b
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.created_at >= b.from_ts
      AND sa.created_at < b.to_ts
    GROUP BY 1
  ),
  refund_rows AS (
    SELECT
      (sa.refunded_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      COALESCE(SUM(COALESCE(sa.refund_amount, 0)), 0)::numeric AS refunds
    FROM public.sales_activities sa
    CROSS JOIN bounds b
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND sa.refunded_at >= b.from_ts
      AND sa.refunded_at < b.to_ts
    GROUP BY 1
  )
  SELECT
    ds.day,
    COALESCE(s.net_sales, 0)::numeric AS net_sales,
    (COALESCE(s.net_sales, 0) + COALESCE(s.discounts, 0))::numeric AS gross_sales,
    COALESCE(s.total_collected, 0)::numeric AS total_collected,
    COALESCE(r.refunds, 0)::numeric AS refunds
  FROM day_spine ds
  LEFT JOIN sales s ON s.day = ds.day
  LEFT JOIN refund_rows r ON r.day = ds.day
  ORDER BY ds.day;
END;
$$;


ALTER FUNCTION "public"."pos_sales_summary_daily"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_sales_summary_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("gross_sales" numeric, "discounts" numeric, "refunds" numeric, "net_sales" numeric, "gratuity" numeric, "tax" numeric, "rounding" numeric, "total_collected" numeric, "transaction_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_net numeric := 0;
  v_discounts numeric := 0;
  v_gratuity numeric := 0;
  v_tax numeric := 0;
  v_total numeric := 0;
  v_count bigint := 0;
  v_refunds numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  SELECT
    COALESCE(SUM(
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      )
    ), 0),
    COALESCE(SUM(COALESCE(sa.checkout_discount_amount, 0)), 0),
    COALESCE(SUM(COALESCE(sa.checkout_gratuity_amount, 0)), 0),
    COALESCE(SUM(COALESCE(sa.checkout_tax_amount, 0)), 0),
    COALESCE(SUM(COALESCE(sa.total_paid_amount, sa.total_amount, 0)), 0),
    COUNT(*)::bigint
  INTO v_net, v_discounts, v_gratuity, v_tax, v_total, v_count
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND (p_from IS NULL OR sa.created_at >= p_from)
    AND (p_to IS NULL OR sa.created_at < p_to);

  SELECT COALESCE(SUM(COALESCE(sa.refund_amount, 0)), 0)
  INTO v_refunds
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'full'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND sa.refunded_at IS NOT NULL
    AND (p_from IS NULL OR sa.refunded_at >= p_from)
    AND (p_to IS NULL OR sa.refunded_at < p_to);

  RETURN QUERY
  SELECT
    (v_net + v_discounts)::numeric AS gross_sales,
    v_discounts::numeric AS discounts,
    v_refunds::numeric AS refunds,
    v_net::numeric AS net_sales,
    v_gratuity::numeric AS gratuity,
    v_tax::numeric AS tax,
    0::numeric AS rounding,
    v_total::numeric AS total_collected,
    v_count;
END;
$$;


ALTER FUNCTION "public"."pos_sales_summary_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_sales_type_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("sales_type_id" "uuid", "sales_type_name" "text", "sort_order" integer, "transaction_count" bigint, "gross_sales" numeric, "net_sales" numeric, "total_collected" numeric, "summary_gross_sales" numeric, "summary_net_sales" numeric, "summary_transaction_count" bigint, "summary_total_collected" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_summary_gross numeric := 0;
  v_summary_net numeric := 0;
  v_summary_count bigint := 0;
  v_summary_collected numeric := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  SELECT
    COALESCE(SUM(
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      )
      + COALESCE(sa.checkout_discount_amount, 0)
    ), 0),
    COALESCE(SUM(
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      )
    ), 0),
    COUNT(*)::bigint,
    COALESCE(SUM(COALESCE(sa.total_paid_amount, sa.total_amount, 0)), 0)
  INTO v_summary_gross, v_summary_net, v_summary_count, v_summary_collected
  FROM public.sales_activities sa
  WHERE sa.organization_id = p_organization_id
    AND sa.activity_type = 'Store Checkout'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none'
    AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
    AND (p_from IS NULL OR sa.created_at >= p_from)
    AND (p_to IS NULL OR sa.created_at < p_to);

  RETURN QUERY
  WITH filtered_activities AS (
    SELECT
      sa.id,
      sa.catalog_sales_type_id,
      sa.checkout_subtotal,
      sa.checkout_discount_amount,
      COALESCE(sa.total_paid_amount, sa.total_amount, 0)::numeric AS collected,
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      ) AS bill_net
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  ),
  activity_gross AS (
    SELECT
      sai.sales_activity_id,
      COALESCE(SUM(COALESCE(sai.total_price, 0)), 0)::numeric AS lines_gross
    FROM public.sales_activity_items sai
    JOIN filtered_activities fa ON fa.id = sai.sales_activity_id
    GROUP BY sai.sales_activity_id
  ),
  line_allocations AS (
    SELECT
      fa.id AS activity_id,
      COALESCE(sai.catalog_sales_type_id, fa.catalog_sales_type_id) AS resolved_type_id,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * fa.bill_net
        ELSE 0::numeric
      END AS net_line,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * COALESCE(fa.checkout_discount_amount, 0)
        ELSE 0::numeric
      END AS discount_line,
      CASE
        WHEN ag.lines_gross > 0 THEN
          COALESCE(sai.total_price, 0) / ag.lines_gross * fa.collected
        ELSE 0::numeric
      END AS collected_line
    FROM filtered_activities fa
    JOIN public.sales_activity_items sai ON sai.sales_activity_id = fa.id
    JOIN activity_gross ag ON ag.sales_activity_id = fa.id
  ),
  line_grouped AS (
    SELECT
      la.resolved_type_id AS sales_type_id,
      COUNT(DISTINCT la.activity_id)::bigint AS transaction_count,
      COALESCE(SUM(la.net_line + la.discount_line), 0)::numeric AS gross_sales,
      COALESCE(SUM(la.net_line), 0)::numeric AS net_sales,
      COALESCE(SUM(la.collected_line), 0)::numeric AS total_collected
    FROM line_allocations la
    GROUP BY la.resolved_type_id
  ),
  bill_only AS (
    SELECT
      fa.catalog_sales_type_id AS sales_type_id,
      COUNT(*)::bigint AS transaction_count,
      COALESCE(SUM(fa.bill_net + COALESCE(fa.checkout_discount_amount, 0)), 0)::numeric AS gross_sales,
      COALESCE(SUM(fa.bill_net), 0)::numeric AS net_sales,
      COALESCE(SUM(fa.collected), 0)::numeric AS total_collected
    FROM filtered_activities fa
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.sales_activity_items sai
      WHERE sai.sales_activity_id = fa.id
    )
    GROUP BY fa.catalog_sales_type_id
  ),
  combined AS (
    SELECT * FROM line_grouped
    UNION ALL
    SELECT * FROM bill_only
  ),
  grouped AS (
    SELECT
      c.sales_type_id,
      SUM(c.transaction_count)::bigint AS transaction_count,
      COALESCE(SUM(c.gross_sales), 0)::numeric AS gross_sales,
      COALESCE(SUM(c.net_sales), 0)::numeric AS net_sales,
      COALESCE(SUM(c.total_collected), 0)::numeric AS total_collected
    FROM combined c
    GROUP BY c.sales_type_id
  )
  SELECT
    g.sales_type_id,
    COALESCE(st.name, 'Unassigned')::text AS sales_type_name,
    COALESCE(st.sort_order, 9999)::integer AS sort_order,
    g.transaction_count,
    g.gross_sales,
    g.net_sales,
    g.total_collected,
    v_summary_gross AS summary_gross_sales,
    v_summary_net AS summary_net_sales,
    v_summary_count AS summary_transaction_count,
    v_summary_collected AS summary_total_collected
  FROM grouped g
  LEFT JOIN public.catalog_sales_types st ON st.id = g.sales_type_id
  ORDER BY COALESCE(st.sort_order, 9999), COALESCE(st.name, 'Unassigned');
END;
$$;


ALTER FUNCTION "public"."pos_sales_type_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_sales_type_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Sales Type report: line-level aggregation by catalog_sales_type_id with bill-header fallback for legacy rows.';



CREATE OR REPLACE FUNCTION "public"."pos_seed_default_payment_channels"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 PERFORM public.pos_seed_default_payment_channels__impl(p_organization_id); END; $$;


ALTER FUNCTION "public"."pos_seed_default_payment_channels"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_seed_default_payment_channels__impl"("p_organization_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO public.pos_payment_method_channels (
    organization_id, pos_outlet_id, category, name, slug, legacy_payment_method, sort_order
  )
  SELECT p_organization_id, NULL, v.category, v.name, v.slug, v.legacy_payment_method, v.sort_order
  FROM (
    VALUES
      ('cash', 'Cash', 'cash', 'cash', 10),
      ('qris', 'QRIS', 'qris', 'qris', 15),
      ('e_wallet', 'GOPAY', 'gopay', 'e_wallet', 20),
      ('e_wallet', 'OVO', 'ovo', 'e_wallet', 21),
      ('e_wallet', 'DANA', 'dana', 'e_wallet', 22),
      ('e_wallet', 'ShopeePay', 'shopeepay', 'e_wallet', 23),
      ('edc', 'BCA', 'bca', 'bank_transfer', 30),
      ('edc', 'Mandiri', 'mandiri', 'bank_transfer', 31),
      ('edc', 'Bank Transfer', 'bank-transfer', 'bank_transfer', 32),
      ('e_commerce', 'Tokopedia', 'tokopedia', NULL, 40),
      ('integration', 'Online Order', 'online-order', NULL, 50),
      ('integration', 'GoStore - GoPay', 'gostore-gopay', NULL, 51),
      ('other', 'Other', 'other', NULL, 90)
  ) AS v(category, name, slug, legacy_payment_method, sort_order)
  ON CONFLICT (organization_id, slug) DO NOTHING;
END;
$$;


ALTER FUNCTION "public"."pos_seed_default_payment_channels__impl"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_served_by_sales_by_sales_type"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("server_user_id" "uuid", "catalog_sales_type_id" "uuid", "sales_type_name" "text", "transaction_count" bigint, "gross_sales" numeric, "net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      sa.served_by_user_id,
      sa.catalog_sales_type_id,
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      ) AS bill_net,
      COALESCE(sa.checkout_discount_amount, 0)::numeric AS discount_amount
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  )
  SELECT
    s.served_by_user_id AS server_user_id,
    s.catalog_sales_type_id,
    COALESCE(NULLIF(btrim(cst.name), ''), 'Unknown') AS sales_type_name,
    COUNT(*)::bigint AS transaction_count,
    COALESCE(SUM(s.bill_net + s.discount_amount), 0)::numeric AS gross_sales,
    COALESCE(SUM(s.bill_net), 0)::numeric AS net_sales
  FROM sales s
  LEFT JOIN public.catalog_sales_types cst ON cst.id = s.catalog_sales_type_id
  GROUP BY s.served_by_user_id, s.catalog_sales_type_id, COALESCE(NULLIF(btrim(cst.name), ''), 'Unknown')
  ORDER BY s.served_by_user_id NULLS FIRST, sales_type_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_served_by_sales_by_sales_type"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_served_by_sales_by_sales_type"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Served By report breakdown: sales type per server.';



CREATE OR REPLACE FUNCTION "public"."pos_served_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("server_user_id" "uuid", "server_name" "text", "employee_id" "uuid", "transaction_count" bigint, "gross_sales" numeric, "net_sales" numeric, "summary_gross_sales" numeric, "summary_net_sales" numeric, "summary_transaction_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH sales AS (
    SELECT
      sa.served_by_user_id,
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      ) AS bill_net,
      COALESCE(sa.checkout_discount_amount, 0)::numeric AS discount_amount
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
  ),
  summary AS (
    SELECT
      COALESCE(SUM(s.bill_net + s.discount_amount), 0)::numeric AS summary_gross_sales,
      COALESCE(SUM(s.bill_net), 0)::numeric AS summary_net_sales,
      COUNT(*)::bigint AS summary_transaction_count
    FROM sales s
  ),
  enriched AS (
    SELECT
      s.served_by_user_id AS server_user_id,
      COALESCE(
        NULLIF(btrim(e.full_name), ''),
        NULLIF(btrim(p.full_name), ''),
        NULLIF(split_part(au.email, '@', 1), ''),
        'Unknown Server'
      ) AS server_name,
      e.id AS employee_id,
      s.bill_net,
      s.discount_amount
    FROM sales s
    LEFT JOIN public.employees e
      ON e.user_id = s.served_by_user_id
     AND e.organization_id = p_organization_id
    LEFT JOIN public.profiles p ON p.user_id = s.served_by_user_id
    LEFT JOIN auth.users au ON au.id = s.served_by_user_id
  ),
  grouped AS (
    SELECT
      en.server_user_id,
      CASE
        WHEN en.server_user_id IS NULL THEN 'Unknown Server'
        ELSE en.server_name
      END AS server_name,
      MAX(en.employee_id::text)::uuid AS employee_id,
      COUNT(*)::bigint AS transaction_count,
      COALESCE(SUM(en.bill_net + en.discount_amount), 0)::numeric AS gross_sales,
      COALESCE(SUM(en.bill_net), 0)::numeric AS net_sales
    FROM enriched en
    GROUP BY en.server_user_id, CASE
      WHEN en.server_user_id IS NULL THEN 'Unknown Server'
      ELSE en.server_name
    END
  )
  SELECT
    g.server_user_id,
    g.server_name,
    g.employee_id,
    g.transaction_count,
    g.gross_sales,
    g.net_sales,
    sm.summary_gross_sales,
    sm.summary_net_sales,
    sm.summary_transaction_count
  FROM grouped g
  CROSS JOIN summary sm
  ORDER BY g.net_sales DESC, g.server_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_served_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_served_by_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) IS 'Served By report: txn count, gross and net sales per waiter (served_by_user_id).';



CREATE OR REPLACE FUNCTION "public"."pos_shift_cashier_display_name"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(btrim(e.full_name), ''),
    NULLIF(btrim(p.full_name), ''),
    NULLIF(split_part(au.email, '@', 1), ''),
    '—'
  )
  FROM auth.users au
  LEFT JOIN public.profiles p ON p.id = au.id
  LEFT JOIN public.employees e ON e.user_id = au.id
    AND e.organization_id IN (SELECT public.user_organization_ids())
  WHERE au.id = p_user_id
  LIMIT 1;
$$;


