CREATE OR REPLACE FUNCTION "public"."pos_shift_cashier_display_name"("p_user_id" "uuid", "p_organization_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(btrim(e.full_name), ''),
    NULLIF(btrim(p.full_name), ''),
    NULLIF(split_part(au.email, '@', 1), ''),
