ALTER FUNCTION "public"."pos_shift_cashier_display_name"("p_user_id" "uuid", "p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_shift_detail"("p_shift_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shift public.pos_cashier_shifts;
  v_outlet_name text;
  v_opened_by_name text;
  v_closed_by_name text;
  v_expected numeric;
  v_cash_sales numeric := 0;
  v_cash_refunds numeric := 0;
  v_cash_in numeric := 0;
  v_cash_out numeric := 0;
  v_products_sold_qty numeric := 0;
  v_refunded_products_qty numeric := 0;
  v_sold_lines jsonb := '[]'::jsonb;
  v_cash_movements jsonb := '[]'::jsonb;
  v_payment_methods jsonb := '[]'::jsonb;
  v_difference numeric;
BEGIN
  SELECT * INTO v_shift FROM public.pos_cashier_shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
  END IF;

  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF v_shift.organization_id NOT IN (SELECT public.user_organization_ids())
     OR NOT public.user_is_org_owner_or_admin(v_shift.organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  SELECT COALESCE(o.name, '—') INTO v_outlet_name
  FROM public.pos_outlets o
  WHERE o.id = v_shift.outlet_id;

  v_opened_by_name := public.pos_shift_cashier_display_name(v_shift.opened_by, v_shift.organization_id);
  v_closed_by_name := public.pos_shift_cashier_display_name(v_shift.closed_by, v_shift.organization_id);
  v_expected := public.pos_shift_expected_cash(p_shift_id);

  SELECT COALESCE(SUM(sa.total_paid_amount), 0) INTO v_cash_sales
  FROM public.sales_activities sa
  WHERE sa.pos_shift_id = p_shift_id
    AND sa.payment_method = 'cash'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none';

  SELECT COALESCE(SUM(sa.refund_amount), 0) INTO v_cash_refunds
  FROM public.sales_activities sa
  WHERE sa.refund_pos_shift_id = p_shift_id
    AND sa.payment_method = 'cash'
    AND COALESCE(sa.refund_status, 'none') = 'full';

  SELECT
    COALESCE(SUM(CASE WHEN m.direction = 'in' THEN m.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN m.direction = 'out' THEN m.amount ELSE 0 END), 0)
  INTO v_cash_in, v_cash_out
  FROM public.pos_cash_movements m
  WHERE m.shift_id = p_shift_id;

  SELECT COALESCE(SUM(sai.quantity), 0) INTO v_products_sold_qty
  FROM public.sales_activities sa
  INNER JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
  WHERE sa.pos_shift_id = p_shift_id
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none';

  SELECT COALESCE(SUM(sai.quantity), 0) INTO v_refunded_products_qty
  FROM public.sales_activities sa
  INNER JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
  WHERE sa.refund_pos_shift_id = p_shift_id
    AND COALESCE(sa.refund_status, 'none') = 'full';

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'service_name', agg.service_name,
        'sub_service_name', agg.sub_service_name,
        'quantity', agg.qty
      )
      ORDER BY agg.service_name, agg.sub_service_name
    ),
    '[]'::jsonb
  ) INTO v_sold_lines
  FROM (
    SELECT
      sai.service_name,
      sai.sub_service_name,
      SUM(sai.quantity)::numeric AS qty
    FROM public.sales_activities sa
    INNER JOIN public.sales_activity_items sai ON sai.sales_activity_id = sa.id
    WHERE sa.pos_shift_id = p_shift_id
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
    GROUP BY sai.service_name, sai.sub_service_name
  ) agg;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', m.id,
        'direction', m.direction,
        'amount', m.amount,
        'description', m.description,
        'created_at', m.created_at
      )
      ORDER BY m.created_at DESC
    ),
    '[]'::jsonb
  ) INTO v_cash_movements
  FROM public.pos_cash_movements m
  WHERE m.shift_id = p_shift_id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'payment_method', pm.payment_method,
        'total_collected', pm.total_collected
      )
      ORDER BY pm.total_collected DESC
    ),
    '[]'::jsonb
  ) INTO v_payment_methods
  FROM (
    SELECT
      COALESCE(NULLIF(btrim(sa.payment_method), ''), 'unknown') AS payment_method,
      COALESCE(SUM(sa.total_paid_amount), 0)::numeric AS total_collected
    FROM public.sales_activities sa
    WHERE sa.pos_shift_id = p_shift_id
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
    GROUP BY COALESCE(NULLIF(btrim(sa.payment_method), ''), 'unknown')
  ) pm;

  v_difference := CASE
    WHEN v_shift.status = 'closed' AND v_shift.closing_cash IS NOT NULL
      THEN v_shift.closing_cash - v_expected
    ELSE NULL
  END;

  RETURN jsonb_build_object(
    'shift_id', v_shift.id,
    'outlet_id', v_shift.outlet_id,
    'outlet_name', v_outlet_name,
    'opened_at', v_shift.opened_at,
    'closed_at', v_shift.closed_at,
    'status', v_shift.status,
    'opened_by_user_id', v_shift.opened_by,
    'opened_by_name', v_opened_by_name,
    'closed_by_user_id', v_shift.closed_by,
    'closed_by_name', v_closed_by_name,
    'opening_cash', v_shift.opening_cash,
    'expected_cash', v_expected,
    'closing_cash', v_shift.closing_cash,
    'cash_difference', v_difference,
    'cash_sales', v_cash_sales,
    'cash_refunds', v_cash_refunds,
    'cash_from_invoices', 0,
    'cash_in', v_cash_in,
    'cash_out', v_cash_out,
    'cash_in_out_net', v_cash_in - v_cash_out,
    'products_sold_qty', v_products_sold_qty,
    'refunded_products_qty', v_refunded_products_qty,
    'sold_lines', v_sold_lines,
    'cash_movements', v_cash_movements,
    'payment_methods', v_payment_methods
  );
END;
$$;


ALTER FUNCTION "public"."pos_shift_detail"("p_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_shift_expected_cash"("p_shift_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shift public.pos_cashier_shifts;
  v_cash_sales numeric := 0;
  v_cash_refunds numeric := 0;
  v_cash_in numeric := 0;
  v_cash_out numeric := 0;
BEGIN
  SELECT * INTO v_shift FROM public.pos_cashier_shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
  END IF;

  IF auth.uid() IS NOT NULL
     AND v_shift.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  SELECT COALESCE(SUM(sa.total_paid_amount), 0) INTO v_cash_sales
  FROM public.sales_activities sa
  WHERE sa.pos_shift_id = p_shift_id
    AND sa.payment_method = 'cash'
    AND sa.status = 'Converted'
    AND COALESCE(sa.refund_status, 'none') = 'none';

  SELECT COALESCE(SUM(sa.refund_amount), 0) INTO v_cash_refunds
  FROM public.sales_activities sa
  WHERE sa.refund_pos_shift_id = p_shift_id
    AND sa.payment_method = 'cash'
    AND COALESCE(sa.refund_status, 'none') = 'full';

  SELECT
    COALESCE(SUM(CASE WHEN m.direction = 'in' THEN m.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN m.direction = 'out' THEN m.amount ELSE 0 END), 0)
  INTO v_cash_in, v_cash_out
  FROM public.pos_cash_movements m
  WHERE m.shift_id = p_shift_id;

  RETURN v_shift.opening_cash + v_cash_sales - v_cash_refunds + v_cash_in - v_cash_out;
END;
$$;


ALTER FUNCTION "public"."pos_shift_expected_cash"("p_shift_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_shift_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_opened_by" "uuid" DEFAULT NULL::"uuid", "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("shift_id" "uuid", "outlet_id" "uuid", "outlet_name" "text", "opened_at" timestamp with time zone, "closed_at" timestamp with time zone, "status" "text", "opened_by_user_id" "uuid", "opened_by_name" "text", "opening_cash" numeric, "expected_cash" numeric, "closing_cash" numeric, "cash_difference" numeric, "summary_shift_count" bigint, "summary_open_count" bigint, "summary_total_shortage" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      s.id,
      s.organization_id,
      s.outlet_id,
      s.opened_at,
      s.closed_at,
      s.status,
      s.opened_by,
      s.opening_cash,
      s.expected_cash,
      s.closing_cash,
      CASE
        WHEN s.status = 'open' THEN public.pos_shift_expected_cash(s.id)
        ELSE COALESCE(s.expected_cash, public.pos_shift_expected_cash(s.id))
      END AS computed_expected,
      CASE
        WHEN s.status = 'closed' AND s.closing_cash IS NOT NULL THEN
          s.closing_cash - COALESCE(s.expected_cash, public.pos_shift_expected_cash(s.id))
        ELSE NULL
      END AS computed_difference
    FROM public.pos_cashier_shifts s
    WHERE s.organization_id = p_organization_id
      AND (p_outlet_id IS NULL OR s.outlet_id = p_outlet_id)
      AND (p_from IS NULL OR s.opened_at >= p_from)
      AND (p_to IS NULL OR s.opened_at < p_to)
      AND (p_opened_by IS NULL OR s.opened_by = p_opened_by)
  ),
  summary AS (
    SELECT
      COUNT(*)::bigint AS summary_shift_count,
      COUNT(*) FILTER (WHERE f.status = 'open')::bigint AS summary_open_count,
      COALESCE(
        SUM(
          CASE
            WHEN f.computed_difference IS NOT NULL AND f.computed_difference < 0
              THEN ABS(f.computed_difference)
            ELSE 0
          END
        ),
        0
      )::numeric AS summary_total_shortage
    FROM filtered f
  ),
  page AS (
    SELECT f.*
    FROM filtered f
    WHERE p_cursor IS NULL OR f.opened_at < p_cursor
    ORDER BY f.opened_at DESC
    LIMIT v_limit
  )
  SELECT
    p.id AS shift_id,
    p.outlet_id,
    COALESCE(o.name, '—') AS outlet_name,
    p.opened_at,
    p.closed_at,
    p.status,
    p.opened_by AS opened_by_user_id,
    public.pos_shift_cashier_display_name(p.opened_by, p_organization_id) AS opened_by_name,
    p.opening_cash,
    p.computed_expected AS expected_cash,
    p.closing_cash,
    p.computed_difference AS cash_difference,
    sm.summary_shift_count,
    sm.summary_open_count,
    sm.summary_total_shortage
  FROM page p
  CROSS JOIN summary sm
  LEFT JOIN public.pos_outlets o ON o.id = p.outlet_id;
END;
$$;


ALTER FUNCTION "public"."pos_shift_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_opened_by" "uuid", "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."pos_employee_staff" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "employee_id" "uuid" NOT NULL,
    "pos_role" "text" DEFAULT 'cashier'::"text" NOT NULL,
    "pin_hash" "text",
    "pin_enabled" boolean DEFAULT false NOT NULL,
    "allow_pin_for_permissions" boolean DEFAULT true NOT NULL,
    "description" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "invited_at" timestamp with time zone,
    "verified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "role_id" "uuid",
    CONSTRAINT "pos_employee_staff_pos_role_check" CHECK (("pos_role" = ANY (ARRAY['administrator'::"text", 'cashier'::"text"])))
);


ALTER TABLE "public"."pos_employee_staff" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_clear_pin"("p_staff_id" "uuid") RETURNS "public"."pos_employee_staff"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_employee_staff;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT * INTO v_row FROM public.pos_employee_staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'staff_not_found';
  END IF;
  IF v_row.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  UPDATE public.pos_employee_staff
  SET
    pin_hash = NULL,
    pin_enabled = false,
    updated_at = now()
  WHERE id = p_staff_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."pos_staff_clear_pin"("p_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_is_user_verified"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN false;
  END IF;
  IF p_user_id IS NULL THEN
    RETURN false;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.magic_links ml
    WHERE ml.user_id = p_user_id
      AND (ml.status = 'completed' OR ml.email_verified = true)
  ) THEN
    RETURN true;
  END IF;
  -- Legacy / owner: has auth user, never used magic-link invite flow
  RETURN NOT EXISTS (
    SELECT 1 FROM public.magic_links ml WHERE ml.user_id = p_user_id
  );
END;
$$;


ALTER FUNCTION "public"."pos_staff_is_user_verified"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_set_outlets"("p_staff_id" "uuid", "p_outlet_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_staff public.pos_employee_staff;
  v_outlet uuid;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT * INTO v_staff FROM public.pos_employee_staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'staff_not_found';
  END IF;
  IF v_staff.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  DELETE FROM public.pos_employee_staff_outlets WHERE staff_id = p_staff_id;

  IF p_outlet_ids IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_outlet IN ARRAY p_outlet_ids LOOP
    IF EXISTS (
      SELECT 1 FROM public.pos_outlets o
      WHERE o.id = v_outlet
        AND o.organization_id = v_staff.organization_id
        AND COALESCE(o.is_deleted, false) = false
    ) THEN
      INSERT INTO public.pos_employee_staff_outlets (organization_id, staff_id, outlet_id)
      VALUES (v_staff.organization_id, p_staff_id, v_outlet)
      ON CONFLICT (staff_id, outlet_id) DO NOTHING;
    END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."pos_staff_set_outlets"("p_staff_id" "uuid", "p_outlet_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_set_pin"("p_staff_id" "uuid", "p_pin" "text") RETURNS "public"."pos_employee_staff"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_employee_staff;
  v_pin text := trim(COALESCE(p_pin, ''));
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF length(v_pin) <> 4 OR v_pin !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'invalid_pin';
  END IF;

  SELECT * INTO v_row FROM public.pos_employee_staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'staff_not_found';
  END IF;
  IF v_row.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  UPDATE public.pos_employee_staff
  SET
    pin_hash = extensions.crypt(v_pin, extensions.gen_salt('bf'::text)),
    pin_enabled = true,
    updated_at = now()
  WHERE id = p_staff_id
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$_$;


ALTER FUNCTION "public"."pos_staff_set_pin"("p_staff_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_sync_verified"("p_organization_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_updated integer := 0;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  WITH verified_users AS (
    SELECT DISTINCT ml.user_id
    FROM public.magic_links ml
    WHERE ml.status = 'completed'
       OR ml.email_verified = true
  ),
  legacy_users AS (
    SELECT e.user_id
    FROM public.employees e
    WHERE e.organization_id = p_organization_id
      AND e.user_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.magic_links ml WHERE ml.user_id = e.user_id
      )
  ),
  to_verify AS (
    SELECT s.id
    FROM public.pos_employee_staff s
    INNER JOIN public.employees e
      ON e.id = s.employee_id
     AND e.organization_id = s.organization_id
    WHERE s.organization_id = p_organization_id
      AND s.verified_at IS NULL
      AND e.user_id IS NOT NULL
      AND (
        e.user_id IN (SELECT user_id FROM verified_users)
        OR e.user_id IN (SELECT user_id FROM legacy_users)
      )
  )
  UPDATE public.pos_employee_staff s
  SET
    verified_at = now(),
    updated_at = now()
  FROM to_verify t
  WHERE s.id = t.id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated;
END;
$$;


ALTER FUNCTION "public"."pos_staff_sync_verified"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_staff_verify_pin"("p_staff_id" "uuid", "p_pin" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_employee_staff;
  v_pin text := trim(COALESCE(p_pin, ''));
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF length(v_pin) <> 4 OR v_pin !~ '^[0-9]+$' THEN
    RETURN false;
  END IF;

  SELECT * INTO v_row
  FROM public.pos_employee_staff
  WHERE id = p_staff_id;

  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF v_row.organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF NOT v_row.is_active OR NOT v_row.pin_enabled OR v_row.pin_hash IS NULL THEN
    RETURN false;
  END IF;
  IF NOT COALESCE(v_row.allow_pin_for_permissions, false) THEN
    RETURN false;
  END IF;

  RETURN extensions.crypt(v_pin, v_row.pin_hash) = v_row.pin_hash;
END;
$_$;


ALTER FUNCTION "public"."pos_staff_verify_pin"("p_staff_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_start_shift"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_opening_cash" numeric) RETURNS "public"."pos_cashier_shifts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_row public.pos_cashier_shifts;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id IS NULL OR p_outlet_id IS NULL THEN
    RAISE EXCEPTION 'invalid_args';
  END IF;
  IF p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.pos_outlets o
    WHERE o.id = p_outlet_id
      AND o.organization_id = p_organization_id
      AND o.is_deleted = false
  ) THEN
    RAISE EXCEPTION 'outlet_not_found';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.pos_cashier_shifts s
    WHERE s.outlet_id = p_outlet_id AND s.status = 'open'
  ) THEN
    RAISE EXCEPTION 'shift_already_open';
  END IF;

  INSERT INTO public.pos_cashier_shifts (
    organization_id,
    outlet_id,
    opened_by,
    opening_cash,
    status
  ) VALUES (
    p_organization_id,
    p_outlet_id,
    v_user,
    GREATEST(COALESCE(p_opening_cash, 0), 0),
    'open'
  )
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."pos_start_shift"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_opening_cash" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_tax_sales_by_rate"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("catalog_tax_id" "uuid", "tax_name" "text", "tax_sort_order" integer, "rate_label" "text", "rate_sort_order" integer, "times_applied" numeric, "taxable_amount" numeric, "tax_collected" numeric, "gross_tax" numeric, "refund_amount" numeric, "refund_taxable_amount" numeric, "net_tax" numeric, "net_taxable_amount" numeric, "summary_total_net_tax" numeric, "has_backfill_estimate" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_tax_total AS (
    SELECT
      sact.sales_activity_id,
      COALESCE(SUM(COALESCE(sact.amount_rp, 0)), 0)::numeric AS tax_total,
      COALESCE(MAX(COALESCE(sact.taxable_base_rp, 0)), 0)::numeric AS activity_taxable_base
    FROM public.sales_activity_checkout_taxes sact
    GROUP BY sact.sales_activity_id
  ),
  sold AS (
    SELECT
      sact.catalog_tax_id AS disc_id,
      sact.tax_name AS disc_name,
      sact.rate_label AS val_label,
      COALESCE(sact.amount_percent, 0)::numeric AS val_sort,
      COUNT(*)::numeric AS times_applied,
      COALESCE(SUM(COALESCE(sact.taxable_base_rp, 0)), 0)::numeric AS taxable_amount,
      COALESCE(SUM(COALESCE(sact.amount_rp, 0)), 0)::numeric AS tax_collected,
      BOOL_OR(sact.is_backfill_estimate) AS has_backfill_estimate
    FROM public.sales_activity_checkout_taxes sact
    JOIN public.sales_activities sa ON sa.id = sact.sales_activity_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY sact.catalog_tax_id, sact.tax_name, sact.rate_label, sact.amount_percent
  ),
  refund_activity_net AS (
    SELECT
      sa.id AS activity_id,
      COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT
      sact.catalog_tax_id AS disc_id,
      sact.tax_name AS disc_name,
      sact.rate_label AS val_label,
      COALESCE(sact.amount_percent, 0)::numeric AS val_sort,
      CASE
        WHEN adt.tax_total > 0 THEN
          COALESCE(sact.amount_rp, 0) / adt.tax_total * ran.refund_total
        ELSE 0::numeric
      END AS refund_collected,
      CASE
        WHEN adt.tax_total > 0 THEN
          adt.activity_taxable_base * COALESCE(sact.amount_rp, 0) / adt.tax_total
        ELSE 0::numeric
      END AS refund_taxable
    FROM refund_activity_net ran
    JOIN public.sales_activity_checkout_taxes sact ON sact.sales_activity_id = ran.activity_id
    JOIN activity_tax_total adt ON adt.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT
      rl.disc_id,
      rl.disc_name,
      rl.val_label,
      rl.val_sort,
      COALESCE(SUM(COALESCE(rl.refund_collected, 0)), 0)::numeric AS refund_amount,
      COALESCE(SUM(COALESCE(rl.refund_taxable, 0)), 0)::numeric AS refund_taxable_amount
    FROM refund_lines rl
    GROUP BY rl.disc_id, rl.disc_name, rl.val_label, rl.val_sort
  ),
  merged AS (
    SELECT
      s.disc_id,
      s.disc_name,
      s.val_label,
      s.val_sort,
      COALESCE(s.times_applied, 0)::numeric AS times_applied,
      COALESCE(s.taxable_amount, 0)::numeric AS taxable_amount,
      COALESCE(s.tax_collected, 0)::numeric AS tax_collected,
      COALESCE(rg.refund_amount, 0)::numeric AS refund_amount,
      COALESCE(rg.refund_taxable_amount, 0)::numeric AS refund_taxable_amount,
      COALESCE(s.has_backfill_estimate, false) AS has_backfill_estimate
    FROM sold s
    LEFT JOIN refund_grouped rg
      ON rg.disc_id IS NOT DISTINCT FROM s.disc_id
     AND rg.disc_name = s.disc_name
     AND rg.val_label = s.val_label
     AND rg.val_sort = s.val_sort
    UNION ALL
    SELECT
      rg.disc_id,
      rg.disc_name,
      rg.val_label,
      rg.val_sort,
      0::numeric AS times_applied,
      0::numeric AS taxable_amount,
      0::numeric AS tax_collected,
      rg.refund_amount,
      rg.refund_taxable_amount,
      false AS has_backfill_estimate
    FROM refund_grouped rg
    WHERE NOT EXISTS (
      SELECT 1
      FROM sold s
      WHERE s.disc_id IS NOT DISTINCT FROM rg.disc_id
        AND s.disc_name = rg.disc_name
        AND s.val_label = rg.val_label
        AND s.val_sort = rg.val_sort
    )
  ),
  rolled AS (
    SELECT
      m.disc_id,
      m.disc_name,
      m.val_label,
      m.val_sort,
      COALESCE(SUM(m.times_applied), 0)::numeric AS times_applied,
      COALESCE(SUM(m.taxable_amount), 0)::numeric AS taxable_amount,
      COALESCE(SUM(m.tax_collected), 0)::numeric AS tax_collected,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount,
      COALESCE(SUM(m.refund_taxable_amount), 0)::numeric AS refund_taxable_amount,
      BOOL_OR(m.has_backfill_estimate) AS has_backfill_estimate
    FROM merged m
    GROUP BY m.disc_id, m.disc_name, m.val_label, m.val_sort
  ),
  summary AS (
    SELECT
      COALESCE(SUM(r.tax_collected - r.refund_amount), 0)::numeric AS net_total
    FROM rolled r
  )
  SELECT
    r.disc_id AS catalog_tax_id,
    r.disc_name AS tax_name,
    COALESCE(ct.sort_order, 9999)::integer AS tax_sort_order,
    r.val_label AS rate_label,
    COALESCE(r.val_sort, 0)::integer AS rate_sort_order,
    r.times_applied,
    r.taxable_amount,
    r.tax_collected,
    r.tax_collected AS gross_tax,
    r.refund_amount,
    r.refund_taxable_amount,
    (r.tax_collected - r.refund_amount)::numeric AS net_tax,
    (r.taxable_amount - r.refund_taxable_amount)::numeric AS net_taxable_amount,
    s.net_total AS summary_total_net_tax,
    r.has_backfill_estimate
  FROM rolled r
  CROSS JOIN summary s
  LEFT JOIN public.catalog_taxes ct ON ct.id = r.disc_id
  WHERE r.times_applied > 0
     OR r.tax_collected > 0
     OR r.refund_amount > 0
  ORDER BY COALESCE(ct.sort_order, 9999), r.tax_collected DESC, r.val_label ASC;
END;
$$;


ALTER FUNCTION "public"."pos_tax_sales_by_rate"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_tax_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS TABLE("catalog_tax_id" "uuid", "tax_name" "text", "sort_order" integer, "times_applied" numeric, "taxable_amount" numeric, "tax_collected" numeric, "gross_tax" numeric, "refund_amount" numeric, "refund_taxable_amount" numeric, "net_tax" numeric, "net_taxable_amount" numeric, "summary_total_net_tax" numeric, "has_backfill_estimate" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH activity_tax_total AS (
    SELECT
      sact.sales_activity_id,
      COALESCE(SUM(COALESCE(sact.amount_rp, 0)), 0)::numeric AS tax_total,
      COALESCE(MAX(COALESCE(sact.taxable_base_rp, 0)), 0)::numeric AS activity_taxable_base
    FROM public.sales_activity_checkout_taxes sact
    GROUP BY sact.sales_activity_id
  ),
  sold AS (
    SELECT
      sact.catalog_tax_id AS disc_id,
      sact.tax_name AS disc_name,
      COUNT(*)::numeric AS times_applied,
      COALESCE(SUM(COALESCE(sact.taxable_base_rp, 0)), 0)::numeric AS taxable_amount,
      COALESCE(SUM(COALESCE(sact.amount_rp, 0)), 0)::numeric AS tax_collected,
      BOOL_OR(sact.is_backfill_estimate) AS has_backfill_estimate
    FROM public.sales_activity_checkout_taxes sact
    JOIN public.sales_activities sa ON sa.id = sact.sales_activity_id
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
    GROUP BY sact.catalog_tax_id, sact.tax_name
  ),
  refund_activity_net AS (
    SELECT
      sa.id AS activity_id,
      COALESCE(sa.refund_amount, 0)::numeric AS refund_total
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND sa.refund_status = 'full'
      AND sa.refunded_at IS NOT NULL
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.refunded_at >= p_from)
      AND (p_to IS NULL OR sa.refunded_at < p_to)
  ),
  refund_lines AS (
    SELECT
      sact.catalog_tax_id AS disc_id,
      sact.tax_name AS disc_name,
      CASE
        WHEN adt.tax_total > 0 THEN
          COALESCE(sact.amount_rp, 0) / adt.tax_total * ran.refund_total
        ELSE 0::numeric
      END AS refund_collected,
      CASE
        WHEN adt.tax_total > 0 THEN
          adt.activity_taxable_base * COALESCE(sact.amount_rp, 0) / adt.tax_total
        ELSE 0::numeric
      END AS refund_taxable
    FROM refund_activity_net ran
    JOIN public.sales_activity_checkout_taxes sact ON sact.sales_activity_id = ran.activity_id
    JOIN activity_tax_total adt ON adt.sales_activity_id = ran.activity_id
  ),
  refund_grouped AS (
    SELECT
      rl.disc_id,
      rl.disc_name,
      COALESCE(SUM(COALESCE(rl.refund_collected, 0)), 0)::numeric AS refund_amount,
      COALESCE(SUM(COALESCE(rl.refund_taxable, 0)), 0)::numeric AS refund_taxable_amount
    FROM refund_lines rl
    GROUP BY rl.disc_id, rl.disc_name
  ),
  merged AS (
    SELECT
      s.disc_id,
      s.disc_name,
      COALESCE(s.times_applied, 0)::numeric AS times_applied,
      COALESCE(s.taxable_amount, 0)::numeric AS taxable_amount,
      COALESCE(s.tax_collected, 0)::numeric AS tax_collected,
      COALESCE(rg.refund_amount, 0)::numeric AS refund_amount,
      COALESCE(rg.refund_taxable_amount, 0)::numeric AS refund_taxable_amount,
      COALESCE(s.has_backfill_estimate, false) AS has_backfill_estimate
    FROM sold s
    LEFT JOIN refund_grouped rg
      ON rg.disc_id IS NOT DISTINCT FROM s.disc_id
     AND rg.disc_name = s.disc_name
    UNION ALL
    SELECT
      rg.disc_id,
      rg.disc_name,
      0::numeric AS times_applied,
      0::numeric AS taxable_amount,
      0::numeric AS tax_collected,
      rg.refund_amount,
      rg.refund_taxable_amount,
      false AS has_backfill_estimate
    FROM refund_grouped rg
    WHERE NOT EXISTS (
      SELECT 1
      FROM sold s
      WHERE s.disc_id IS NOT DISTINCT FROM rg.disc_id
        AND s.disc_name = rg.disc_name
    )
  ),
  rolled AS (
    SELECT
      m.disc_id,
      m.disc_name,
      COALESCE(SUM(m.times_applied), 0)::numeric AS times_applied,
      COALESCE(SUM(m.taxable_amount), 0)::numeric AS taxable_amount,
      COALESCE(SUM(m.tax_collected), 0)::numeric AS tax_collected,
      COALESCE(SUM(m.refund_amount), 0)::numeric AS refund_amount,
      COALESCE(SUM(m.refund_taxable_amount), 0)::numeric AS refund_taxable_amount,
      BOOL_OR(m.has_backfill_estimate) AS has_backfill_estimate
    FROM merged m
    GROUP BY m.disc_id, m.disc_name
  ),
  summary AS (
    SELECT
      COALESCE(SUM(r.tax_collected - r.refund_amount), 0)::numeric AS net_total
    FROM rolled r
  )
  SELECT
    r.disc_id AS catalog_tax_id,
    r.disc_name AS tax_name,
    COALESCE(ct.sort_order, 9999)::integer AS sort_order,
    r.times_applied,
    r.taxable_amount,
    r.tax_collected,
    r.tax_collected AS gross_tax,
    r.refund_amount,
    r.refund_taxable_amount,
    (r.tax_collected - r.refund_amount)::numeric AS net_tax,
    (r.taxable_amount - r.refund_taxable_amount)::numeric AS net_taxable_amount,
    s.net_total AS summary_total_net_tax,
    r.has_backfill_estimate
  FROM rolled r
  CROSS JOIN summary s
  LEFT JOIN public.catalog_taxes ct ON ct.id = r.disc_id
  WHERE r.times_applied > 0
     OR r.tax_collected > 0
     OR r.refund_amount > 0
  ORDER BY r.tax_collected DESC, r.disc_name ASC;
END;
$$;


ALTER FUNCTION "public"."pos_tax_sales_report"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pos_transactions_cancelled_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("session_id" "uuid", "closed_at" timestamp with time zone, "outlet_id" "uuid", "outlet_name" "text", "table_name" "text", "staff_user_id" "uuid", "staff_name" "text", "cancel_reason" "text", "item_summary" "text", "cart_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      pts.id,
      pts.closed_at,
      pts.outlet_id,
      pts.table_name,
      COALESCE(pts.waiter_id, pts.opened_by) AS staff_user_id,
      pts.cancel_reason,
      pts.cart_snapshot
    FROM public.pos_table_sessions pts
    WHERE pts.organization_id = p_organization_id
      AND pts.status = 'cancelled'
      AND pts.closed_at IS NOT NULL
      AND (p_outlet_id IS NULL OR pts.outlet_id = p_outlet_id)
      AND (p_from IS NULL OR pts.closed_at >= p_from)
      AND (p_to IS NULL OR pts.closed_at < p_to)
  ),
  page AS (
    SELECT f.*
    FROM filtered f
    WHERE p_cursor IS NULL OR f.closed_at < p_cursor
    ORDER BY f.closed_at DESC
    LIMIT v_limit
  )
  SELECT
    p.id AS session_id,
    p.closed_at,
    p.outlet_id,
    COALESCE(NULLIF(btrim(po.name), ''), '—') AS outlet_name,
    COALESCE(NULLIF(btrim(p.table_name), ''), '—') AS table_name,
    p.staff_user_id,
    COALESCE(
      NULLIF(btrim(e.full_name), ''),
      NULLIF(btrim(pr.full_name), ''),
      NULLIF(split_part(au.email, '@', 1), ''),
      'Unknown Staff'
    ) AS staff_name,
    COALESCE(NULLIF(btrim(p.cancel_reason), ''), '—') AS cancel_reason,
    COALESCE(items.item_summary, '') AS item_summary,
    COALESCE(p.cart_snapshot, '[]'::jsonb) AS cart_snapshot
  FROM page p
  LEFT JOIN public.pos_outlets po ON po.id = p.outlet_id
  LEFT JOIN public.employees e ON e.user_id = p.staff_user_id AND e.organization_id = p_organization_id
  LEFT JOIN public.profiles pr ON pr.user_id = p.staff_user_id
  LEFT JOIN auth.users au ON au.id = p.staff_user_id
  LEFT JOIN LATERAL (
    SELECT string_agg(sub.n, ', ' ORDER BY sub.ord) AS item_summary
    FROM (
      SELECT
        COALESCE(
          NULLIF(btrim(elem->>'serviceName'), ''),
          NULLIF(btrim(elem->>'service_name'), ''),
          'Item'
        ) AS n,
        ordinality AS ord
      FROM jsonb_array_elements(COALESCE(p.cart_snapshot, '[]'::jsonb)) WITH ORDINALITY AS t(elem, ordinality)
      ORDER BY ordinality
      LIMIT 3
    ) sub
  ) items ON true
  ORDER BY p.closed_at DESC;
END;
$$;


ALTER FUNCTION "public"."pos_transactions_cancelled_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_transactions_cancelled_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor" timestamp with time zone, "p_limit" integer) IS 'Transactions audit: paginated cancelled table sessions.';



CREATE OR REPLACE FUNCTION "public"."pos_transactions_success_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_receipt_query" "text" DEFAULT NULL::"text", "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("activity_id" "uuid", "created_at" timestamp with time zone, "outlet_id" "uuid", "outlet_name" "text", "receipt_code" "text", "collected_by_user_id" "uuid", "collected_by_name" "text", "served_by_user_id" "uuid", "served_by_name" "text", "item_summary" "text", "total_collected" numeric, "net_sales" numeric, "gross_sales" numeric, "summary_txn_count" bigint, "summary_total_collected" numeric, "summary_net_sales" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_receipt_prefix text;
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  v_receipt_prefix := upper(replace(replace(COALESCE(btrim(p_receipt_query), ''), 'SC-', ''), '-', ''));

  RETURN QUERY
  WITH filtered AS (
    SELECT
      sa.id,
      sa.created_at,
      sa.pos_outlet_id,
      sa.created_by,
      sa.served_by_user_id,
      COALESCE(sa.total_paid_amount, sa.total_amount, 0)::numeric AS collected,
      public.pos_sales_activity_exclusive_net(
        sa.checkout_subtotal,
        sa.checkout_tax_amount,
        sa.checkout_gratuity_amount,
        COALESCE(sa.total_paid_amount, sa.total_amount, 0),
        sa.checkout_application_method
      ) AS bill_net,
      COALESCE(sa.checkout_discount_amount, 0)::numeric AS discount_amount
    FROM public.sales_activities sa
    WHERE sa.organization_id = p_organization_id
      AND sa.activity_type = 'Store Checkout'
      AND sa.status = 'Converted'
      AND COALESCE(sa.refund_status, 'none') = 'none'
      AND (p_outlet_id IS NULL OR sa.pos_outlet_id = p_outlet_id)
      AND (p_from IS NULL OR sa.created_at >= p_from)
      AND (p_to IS NULL OR sa.created_at < p_to)
      AND (
        v_receipt_prefix = ''
        OR upper(replace(sa.id::text, '-', '')) LIKE v_receipt_prefix || '%'
      )
  ),
  summary AS (
    SELECT
      COUNT(*)::bigint AS summary_txn_count,
      COALESCE(SUM(f.collected), 0)::numeric AS summary_total_collected,
      COALESCE(SUM(f.bill_net), 0)::numeric AS summary_net_sales
    FROM filtered f
  ),
  page AS (
    SELECT f.*
    FROM filtered f
    WHERE p_cursor IS NULL OR f.created_at < p_cursor
    ORDER BY f.created_at DESC
    LIMIT v_limit
  )
  SELECT
    p.id AS activity_id,
    p.created_at,
    p.pos_outlet_id AS outlet_id,
    COALESCE(NULLIF(btrim(po.name), ''), '—') AS outlet_name,
    ('SC-' || upper(substr(replace(p.id::text, '-', ''), 1, 8))) AS receipt_code,
    p.created_by AS collected_by_user_id,
    COALESCE(
      NULLIF(btrim(ec.full_name), ''),
      NULLIF(btrim(pc.full_name), ''),
      NULLIF(split_part(auc.email, '@', 1), ''),
      'Unknown Staff'
    ) AS collected_by_name,
    p.served_by_user_id,
    CASE
      WHEN p.served_by_user_id IS NULL THEN NULL
      ELSE COALESCE(
        NULLIF(btrim(es.full_name), ''),
        NULLIF(btrim(ps.full_name), ''),
        NULLIF(split_part(aus.email, '@', 1), ''),
        'Unknown Server'
      )
    END AS served_by_name,
    COALESCE(items.item_summary, '') AS item_summary,
    p.collected AS total_collected,
    p.bill_net AS net_sales,
    (p.bill_net + p.discount_amount) AS gross_sales,
    sm.summary_txn_count,
    sm.summary_total_collected,
    sm.summary_net_sales
  FROM page p
  CROSS JOIN summary sm
  LEFT JOIN public.pos_outlets po ON po.id = p.pos_outlet_id
  LEFT JOIN public.employees ec ON ec.user_id = p.created_by AND ec.organization_id = p_organization_id
  LEFT JOIN public.profiles pc ON pc.user_id = p.created_by
  LEFT JOIN auth.users auc ON auc.id = p.created_by
  LEFT JOIN public.employees es ON es.user_id = p.served_by_user_id AND es.organization_id = p_organization_id
  LEFT JOIN public.profiles ps ON ps.user_id = p.served_by_user_id
  LEFT JOIN auth.users aus ON aus.id = p.served_by_user_id
  LEFT JOIN LATERAL (
    SELECT string_agg(sub.n, ', ' ORDER BY sub.ord) AS item_summary
    FROM (
      SELECT
        COALESCE(NULLIF(btrim(sai.service_name), ''), 'Item') AS n,
        row_number() OVER (ORDER BY sai.created_at) AS ord
      FROM public.sales_activity_items sai
      WHERE sai.sales_activity_id = p.id
      ORDER BY sai.created_at
      LIMIT 3
    ) sub
  ) items ON true
  ORDER BY p.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."pos_transactions_success_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_receipt_query" "text", "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_transactions_success_orders"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_receipt_query" "text", "p_cursor" timestamp with time zone, "p_limit" integer) IS 'Transactions audit: paginated successful store checkouts with summary totals.';



CREATE OR REPLACE FUNCTION "public"."pos_transactions_void_items"("p_organization_id" "uuid", "p_outlet_id" "uuid" DEFAULT NULL::"uuid", "p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_limit" integer DEFAULT 50) RETURNS TABLE("void_id" "uuid", "created_at" timestamp with time zone, "outlet_id" "uuid", "outlet_name" "text", "session_id" "uuid", "table_name" "text", "product_name" "text", "quantity" numeric, "unit_price" numeric, "line_total" numeric, "reason" "text", "voided_by_user_id" "uuid", "voided_by_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 50), 200));
BEGIN
  IF auth.uid() IS NULL THEN
    IF coalesce(auth.role(), current_setting('request.jwt.claim.role', true), '') <> 'service_role' THEN
      RAISE EXCEPTION 'not_authenticated';
    END IF;
  ELSIF p_organization_id IS NULL
     OR p_organization_id NOT IN (SELECT public.user_organization_ids()) OR NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;

  RETURN QUERY
  WITH filtered AS (
    SELECT
      v.id,
      v.created_at,
      v.outlet_id,
      v.session_id,
      v.product_name,
      v.quantity,
      v.unit_price,
      v.reason,
      v.voided_by
    FROM public.pos_line_voids v
    WHERE v.organization_id = p_organization_id
      AND (p_outlet_id IS NULL OR v.outlet_id = p_outlet_id)
      AND (p_from IS NULL OR v.created_at >= p_from)
      AND (p_to IS NULL OR v.created_at < p_to)
  ),
  page AS (
    SELECT f.*
    FROM filtered f
    WHERE p_cursor IS NULL OR f.created_at < p_cursor
    ORDER BY f.created_at DESC
    LIMIT v_limit
  )
  SELECT
    p.id AS void_id,
    p.created_at,
    p.outlet_id,
    COALESCE(NULLIF(btrim(po.name), ''), '—') AS outlet_name,
    p.session_id,
    COALESCE(NULLIF(btrim(pts.table_name), ''), '—') AS table_name,
    COALESCE(NULLIF(btrim(p.product_name), ''), '—') AS product_name,
    p.quantity::numeric,
    p.unit_price::numeric,
    (p.quantity * p.unit_price)::numeric AS line_total,
    COALESCE(NULLIF(btrim(p.reason), ''), '—') AS reason,
    p.voided_by AS voided_by_user_id,
    COALESCE(
      NULLIF(btrim(pr.full_name), ''),
      NULLIF(split_part(au.email, '@', 1), ''),
      'Unknown Staff'
    ) AS voided_by_name
  FROM page p
  LEFT JOIN public.pos_outlets po ON po.id = p.outlet_id
  LEFT JOIN public.pos_table_sessions pts ON pts.id = p.session_id
  LEFT JOIN public.profiles pr ON pr.user_id = p.voided_by
  LEFT JOIN auth.users au ON au.id = p.voided_by
  ORDER BY p.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."pos_transactions_void_items"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor" timestamp with time zone, "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pos_transactions_void_items"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_cursor" timestamp with time zone, "p_limit" integer) IS 'Transactions audit: paginated line voids.';



CREATE OR REPLACE FUNCTION "public"."pos_verify_admin_pin_for_outlet"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_pin" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'extensions'
    AS $_$
DECLARE
  v_user uuid := auth.uid();
  v_pin text := trim(COALESCE(p_pin, ''));
  v_staff public.pos_employee_staff;
  v_has_outlet boolean;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'forbidden_org';
  END IF;
  IF length(v_pin) <> 4 OR v_pin !~ '^[0-9]+$' THEN
    RETURN NULL;
  END IF;

  FOR v_staff IN
    SELECT s.*
    FROM public.pos_employee_staff s
    WHERE s.organization_id = p_organization_id
      AND s.is_active = true
      AND s.pin_enabled = true
      AND s.pin_hash IS NOT NULL
      AND COALESCE(s.allow_pin_for_permissions, false) = true
      AND (
        s.pos_role = 'administrator'
        OR EXISTS (
          SELECT 1
          FROM public.pos_employee_roles r
          WHERE r.id = s.role_id
            AND r.slug = 'administrator'
        )
      )
  LOOP
    SELECT EXISTS (
      SELECT 1
      FROM public.pos_employee_staff_outlets o
      WHERE o.staff_id = v_staff.id
        AND o.outlet_id = p_outlet_id
    ) INTO v_has_outlet;

    IF NOT v_has_outlet THEN
      IF EXISTS (
        SELECT 1 FROM public.pos_employee_staff_outlets o WHERE o.staff_id = v_staff.id
      ) THEN
        CONTINUE;
      END IF;
    END IF;

    IF extensions.crypt(v_pin, v_staff.pin_hash) = v_staff.pin_hash THEN
      RETURN v_staff.id;
    END IF;
  END LOOP;

  RETURN NULL;
END;
$_$;


ALTER FUNCTION "public"."pos_verify_admin_pin_for_outlet"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_is_public_readable"("p_status" "text", "p_published_at" timestamp with time zone, "p_scheduled_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select (
    p_status = 'published'
    and p_published_at is not null
    and p_published_at <= now()
  ) or (
    p_status = 'scheduled'
    and p_scheduled_at is not null
    and p_scheduled_at <= now()
  );
$$;


ALTER FUNCTION "public"."post_is_public_readable"("p_status" "text", "p_published_at" timestamp with time zone, "p_scheduled_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prefix_package_media_path"("p_web_id" "text", "p_path" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_path is null or btrim(p_path) = '' then null
    when p_path like p_web_id || '/%' then p_path
    else p_web_id || '/' || ltrim(p_path, '/')
  end;
$$;


ALTER FUNCTION "public"."prefix_package_media_path"("p_web_id" "text", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_payroll_expense_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.payroll_run_id IS NOT NULL THEN
      RAISE EXCEPTION 'payroll_expense_readonly'
        USING ERRCODE = 'P0001',
              DETAIL = 'Payroll THP expenses cannot be deleted.';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.payroll_run_id IS NOT NULL THEN
    IF NEW.payroll_run_id IS DISTINCT FROM OLD.payroll_run_id
      OR NEW.amount IS DISTINCT FROM OLD.amount
      OR NEW.expense_name IS DISTINCT FROM OLD.expense_name
      OR NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN
      RAISE EXCEPTION 'payroll_expense_readonly'
        USING ERRCODE = 'P0001',
              DETAIL = 'Payroll THP expenses are read-only.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_payroll_expense_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_due_flow_delay_jobs"("p_limit" integer DEFAULT 50) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_job record;
BEGIN
  FOR v_job IN
    SELECT id
    FROM public.omnichannel_flow_delay_jobs
    WHERE status = 'pending' AND resume_at <= now()
    ORDER BY resume_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 50), 200))
    FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.omnichannel_flow_delay_jobs
    SET status = 'processing', updated_at = now()
    WHERE id = v_job.id AND status = 'pending';

    IF FOUND THEN
      v_count := v_count + 1;
    END IF;
  END LOOP;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."process_due_flow_delay_jobs"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."process_due_flow_delay_jobs"("p_limit" integer) IS 'Marks due delay jobs as processing. Edge function flow-delay-worker completes execution.';



CREATE OR REPLACE FUNCTION "public"."process_payroll_run"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_run record;
  v_emp record;
  v_created integer := 0;
  v_skipped integer := 0;
  v_result jsonb;
  v_calc_ids uuid[];
  v_was_reprocess boolean := false;
  v_in_flight integer;
BEGIN
  SELECT pr.*, pp.start_date, pp.end_date
  INTO v_run
  FROM public.payroll_runs pr
  JOIN public.payroll_periods pp ON pp.id = pr.payroll_period_id
  WHERE pr.id = p_run_id;

  IF v_run IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Payroll run not found');
  END IF;

  IF NOT (v_run.organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;

  IF NOT public.user_has_org_role(v_run.organization_id, ARRAY['owner','admin','hr']) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  -- Kunci run: proses ulang, mark paid, dan finalisasi tidak boleh berjalan bersamaan.
  PERFORM 1 FROM public.payroll_runs WHERE id = p_run_id FOR UPDATE;
  v_run.status := (SELECT status FROM public.payroll_runs WHERE id = p_run_id);

  IF v_run.status = 'paid' THEN
    RETURN jsonb_build_object('success', false, 'message', 'Cannot process a paid payroll run');
  END IF;

  v_in_flight := public.payroll_run_transfer_in_flight(p_run_id);
  IF v_in_flight > 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', format(
        'Tidak bisa proses ulang: %s transfer gaji sedang berjalan atau sudah terkirim. Tunggu sampai selesai, lalu tangani yang gagal lewat Retry.',
        v_in_flight
      ),
      'transfers_in_flight', v_in_flight
    );
  END IF;

  SELECT array_agg(id) INTO v_calc_ids
  FROM public.employee_payroll_calculations
  WHERE payroll_run_id = p_run_id AND payment_status IS DISTINCT FROM 'paid';

  IF v_calc_ids IS NOT NULL THEN
    v_was_reprocess := true;
    DELETE FROM public.payroll_items WHERE payroll_calculation_id = ANY (v_calc_ids);
    DELETE FROM public.employee_payroll_calculations WHERE id = ANY (v_calc_ids);
  END IF;

  FOR v_emp IN
    SELECT e.id FROM public.employees e
    JOIN public.employee_statuses es ON es.id = e.employee_status_id
    JOIN public.employee_payroll_info epi ON epi.employee_id = e.id
    WHERE e.organization_id = v_run.organization_id
      AND COALESCE(e.pending_removal, false) = false
      AND COALESCE(e.is_ai, false) = false
      AND lower(es.name) IN ('active', 'probation')
      AND COALESCE(epi.basic_salary, 0) > 0
      AND epi.ptkp_status IS NOT NULL
      AND epi.tax_configuration_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.employee_payroll_calculations ec
        WHERE ec.payroll_run_id = p_run_id AND ec.employee_id = e.id AND ec.payment_status = 'paid'
      )
  LOOP
    v_result := public.payroll_calculate_employee(p_run_id, v_emp.id);
    IF COALESCE((v_result->>'skipped')::boolean, false) THEN
      v_skipped := v_skipped + 1;
    ELSE
      v_created := v_created + 1;
    END IF;
  END LOOP;

  UPDATE public.payroll_runs
  SET status = 'calculated', calculated_at = now(), calculated_by = auth.uid(), updated_at = now()
  WHERE id = p_run_id;

  PERFORM public.calculate_payroll_run_totals(p_run_id);

  PERFORM public.payroll_log_audit(
    v_run.organization_id, p_run_id, NULL,
    CASE WHEN v_was_reprocess THEN 'reprocessed' ELSE 'calculated' END,
    jsonb_build_object('calculations_created', v_created, 'calculations_skipped', v_skipped)
  );

  RETURN jsonb_build_object(
    'success', true,
    'message', format('Payroll processed: %s employee(s) calculated, %s skipped', v_created, v_skipped),
    'calculations_created', v_created,
    'calculations_skipped', v_skipped
  );
END;
$$;


ALTER FUNCTION "public"."process_payroll_run"("p_run_id" "uuid") OWNER TO "postgres";


