    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(
    NULLIF(trim(e.full_name), ''),
    NULLIF(trim(e.email), ''),
    NULLIF(trim(p.email), ''),
