CREATE OR REPLACE FUNCTION "public"."profiles_enforce_active_org_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.active_organization_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.active_organization_id IS NOT DISTINCT FROM OLD.active_organization_id THEN
    RETURN NEW;
  END IF;
  IF coalesce(auth.role(), '') <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_organizations uo
    WHERE uo.user_id = NEW.user_id
      AND uo.organization_id = NEW.active_organization_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'active_organization_not_member'
      USING ERRCODE = '42501',
            DETAIL = 'active_organization_id must be an organization the user belongs to.';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."profiles_enforce_active_org_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_sales_outlet_quota"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.sales_outlet_quota IS NOT NULL AND NOT public.sales_contract_apply_active() THEN
      RAISE EXCEPTION 'outlet changes wait for a signed contract' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.sales_outlet_quota IS DISTINCT FROM OLD.sales_outlet_quota
     AND NOT public.sales_contract_apply_active() THEN
    RAISE EXCEPTION 'outlet changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_sales_outlet_quota"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_sales_package_price"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF (
      NEW.sales_monthly_price_idr IS NOT NULL
      OR NEW.sales_billing_mode IS NOT NULL
      OR NEW.sales_ppn_included IS NOT NULL
      OR NEW.sales_price_effective_on IS NOT NULL
    ) AND NOT public.sales_contract_apply_active() THEN
      RAISE EXCEPTION 'price changes wait for a signed contract' USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  IF (
    NEW.sales_monthly_price_idr IS DISTINCT FROM OLD.sales_monthly_price_idr
    OR NEW.sales_billing_mode IS DISTINCT FROM OLD.sales_billing_mode
    OR NEW.sales_ppn_included IS DISTINCT FROM OLD.sales_ppn_included
    OR NEW.sales_price_effective_on IS DISTINCT FROM OLD.sales_price_effective_on
  ) AND NOT public.sales_contract_apply_active() THEN
    RAISE EXCEPTION 'price changes wait for a signed contract' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."protect_sales_package_price"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_recipe_draft"("p_draft_id" "uuid", "p_confirm_warnings" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  d public.catalog_recipe_drafts%ROWTYPE;
  v_user uuid := auth.uid();
  v_review jsonb;
  v_recipe uuid;
  v_old jsonb;
BEGIN
  SELECT * INTO d FROM public.catalog_recipe_drafts WHERE id = p_draft_id FOR UPDATE;
  IF NOT FOUND OR NOT public._recipe_is_member(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public._recipe_is_manager(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT r.id INTO v_recipe
  FROM public.catalog_product_recipes r
  WHERE r.product_id = d.product_id AND r.modifier_option_id IS NULL
  FOR UPDATE;

  v_review := public._recipe_draft_review(d.id, v_user);
  IF jsonb_array_length(v_review -> 'blocking') > 0 THEN
    RAISE EXCEPTION '%', 'recipe_draft_blocked: ' || (
      SELECT string_agg(b ->> 'code', ',') FROM jsonb_array_elements(v_review -> 'blocking') b
    ) USING ERRCODE = '22023';
  END IF;
  IF (v_review ->> 'requires_confirmation')::boolean AND NOT COALESCE(p_confirm_warnings, false) THEN
    RAISE EXCEPTION 'recipe_draft_confirmation_required' USING ERRCODE = '22023';
  END IF;

  IF v_recipe IS NULL THEN
    INSERT INTO public.catalog_product_recipes (organization_id, product_id)
    VALUES (d.organization_id, d.product_id)
    RETURNING id INTO v_recipe;
    v_old := '[]'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(jsonb_build_object('ingredient_id', l.ingredient_id, 'quantity', l.quantity)
             ORDER BY l.sort_order), '[]'::jsonb)
      INTO v_old
    FROM public.catalog_product_recipe_lines l
    WHERE l.recipe_id = v_recipe;
  END IF;

  INSERT INTO public.catalog_product_recipe_history (organization_id, product_id, recipe_id, lines, source, draft_id, replaced_by)
  VALUES (d.organization_id, d.product_id, v_recipe, v_old, 'draft_publish', d.id, v_user);

  DELETE FROM public.catalog_product_recipe_lines WHERE recipe_id = v_recipe;

  INSERT INTO public.catalog_product_recipe_lines (recipe_id, ingredient_id, organization_id, quantity, sort_order)
  SELECT v_recipe, (e ->> 'ingredient_id')::uuid, d.organization_id, (e ->> 'quantity')::numeric, ord::integer
  FROM jsonb_array_elements(d.lines) WITH ORDINALITY AS t(e, ord);

  UPDATE public.catalog_product_recipes SET updated_at = now() WHERE id = v_recipe;

  UPDATE public.catalog_recipe_drafts
  SET status = 'published', decided_by = v_user, decided_at = now(), updated_at = now()
  WHERE id = d.id;

  RETURN public._recipe_draft_review(d.id, v_user);
END;
$$;


ALTER FUNCTION "public"."publish_recipe_draft"("p_draft_id" "uuid", "p_confirm_warnings" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_document_in_active_org"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid := public.storage_active_organization_id();
  v_top text;
  v_second text;
BEGIN
  IF v_org IS NULL OR p_name IS NULL OR position('../' in p_name) > 0 THEN
    RETURN false;
  END IF;
  v_top := (storage.foldername(p_name))[1];
  v_second := (storage.foldername(p_name))[2];
  IF v_top = 'invoices' THEN
    RETURN v_second ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      AND v_second = v_org::text;
  END IF;
  RETURN v_top ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND v_top = v_org::text;
END;
$_$;


ALTER FUNCTION "public"."purchase_document_in_active_org"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_expired_google_ads_metrics_cache"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH deleted AS (
    DELETE FROM public.google_ads_metrics_cache
    WHERE expires_at < now()
    RETURNING id
  )
  SELECT count(*)::integer FROM deleted;
$$;


