COMMENT ON FUNCTION "public"."purge_expired_google_ads_metrics_cache"() IS 'Deletes google_ads_metrics_cache rows past expires_at. Schedule via pg_cron or manual call.';



CREATE OR REPLACE FUNCTION "public"."recalculate_pinjaman_online_debt_amount"("p_debt_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_debt public.debts%ROWTYPE;
  v_total_expense numeric(15, 2);
  v_remaining numeric(15, 2);
  v_paid numeric(15, 2);
BEGIN
  SELECT * INTO v_debt FROM public.debts WHERE id = p_debt_id;
  IF NOT FOUND OR v_debt.debt_type IS DISTINCT FROM 'Pinjaman Online' THEN
    RETURN;
  END IF;

  IF auth.uid() IS NULL OR NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = auth.uid()
      AND uo.organization_id = v_debt.organization_id
  ) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT coalesce(sum(amount), 0) INTO v_total_expense
  FROM public.expenses
  WHERE withdrawal_from_balance = p_debt_id
    AND status IS DISTINCT FROM 'deleted';

  v_paid := coalesce(v_debt.paid_amount, 0);
  v_remaining := greatest(0, v_total_expense - v_paid);

  UPDATE public.debts
  SET
    debt_amount = v_total_expense,
    remaining_debt = v_remaining,
    available_limit = greatest(0, coalesce(limit_amount, 0) - v_remaining),
    updated_at = now()
  WHERE id = p_debt_id;
END;
$$;


ALTER FUNCTION "public"."recalculate_pinjaman_online_debt_amount"("p_debt_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recalculate_pinjaman_online_debt_amount"("p_debt_id" "uuid") IS 'Pinjaman Online: sync debt_amount / remaining_debt / available_limit from expenses + paid_amount (no debt_payments table).';



CREATE OR REPLACE FUNCTION "public"."recipient_picker_filter_options"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ok boolean;
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN '{}'::jsonb;
  END IF;
  SELECT public.user_is_org_owner(p_organization_id) INTO v_ok;
  IF NOT coalesce(v_ok, false) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;

  RETURN jsonb_build_object(
    'created_by_names',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(l.created_by_name) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND btrim(coalesce(l.created_by_name, '')) <> ''
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'utm_sources',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution ->> 'utm_source', '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution ->> 'utm_source'), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'utm_mediums',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution ->> 'utm_medium', '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution ->> 'utm_medium'), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'utm_campaigns',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution ->> 'utm_campaign', '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution ->> 'utm_campaign'), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'utm_contents',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution ->> 'utm_content', '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution ->> 'utm_content'), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'utm_terms',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution ->> 'utm_term', '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution ->> 'utm_term'), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'attribution_labels',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.attribution_label, '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.attribution_label), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'gclids',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.gclid, '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.gclid), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'service_names',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(nullif(l.services, '')) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND nullif(btrim(l.services), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'sources',
    (
      SELECT coalesce(jsonb_agg(u.x ORDER BY u.x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(l.source) AS x
        FROM public.leads l
        WHERE l.organization_id = p_organization_id
          AND btrim(coalesce(l.source, '')) <> ''
        UNION
        SELECT 'WhatsApp'::text AS x
        WHERE EXISTS (
          SELECT 1
          FROM public.whatsapp_conversations c
          WHERE c.organization_id = p_organization_id
            AND lower(coalesce(c.channel, 'whatsapp')) <> 'instagram'
        )
      ) u
    ),
    'lead_magnet_campaign_names',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(s.lead_magnet_campaign_name) AS x
        FROM public.lead_submissions s
        WHERE s.organization_id = p_organization_id
          AND s.is_active = true
          AND nullif(btrim(s.lead_magnet_campaign_name), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    ),
    'lead_magnet_target_markets',
    (
      SELECT coalesce(jsonb_agg(x ORDER BY x), '[]'::jsonb)
      FROM (
        SELECT DISTINCT btrim(s.lead_magnet_target_market) AS x
        FROM public.lead_submissions s
        WHERE s.organization_id = p_organization_id
          AND s.is_active = true
          AND nullif(btrim(s.lead_magnet_target_market), '') IS NOT NULL
        ORDER BY x
        LIMIT 500
      ) s
    )
  );
END;
$$;


ALTER FUNCTION "public"."recipient_picker_filter_options"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recipient_picker_filter_options"("p_organization_id" "uuid") IS 'Distinct filter option values for recipient picker (org owner only), including Lead Magnet campaign/target market.';



CREATE OR REPLACE FUNCTION "public"."reconcile_xendit_disbursement_completed"("p_disbursement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.xendit_disbursements%ROWTYPE;
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  SELECT * INTO v_row FROM public.xendit_disbursements WHERE id = p_disbursement_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'disbursement_not_found';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.organization_id = v_row.organization_id
      AND ur.user_id = v_uid
      AND ur.role IN ('owner', 'admin')
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF v_row.status NOT IN ('pending', 'processing') THEN
    RETURN jsonb_build_object('ok', true, 'skipped', true, 'status', v_row.status);
  END IF;

  UPDATE public.xendit_disbursements
  SET
    status = 'completed',
    completed_at = COALESCE(completed_at, now()),
    updated_at = now()
  WHERE id = p_disbursement_id;

  RETURN jsonb_build_object('ok', true, 'disbursement_id', p_disbursement_id);
END;
$$;


ALTER FUNCTION "public"."reconcile_xendit_disbursement_completed"("p_disbursement_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_attendance_checkout"("employee_id_param" "uuid", "organization_id_param" "uuid", "photo_path_param" "text" DEFAULT NULL::"text", "location_data" "jsonb" DEFAULT '{}'::"jsonb", "attendance_id_param" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rules record;
  v_tz text;
  v_today date;
  v_rec record;
  v_now timestamptz := now();
  v_check_in timestamptz;
  v_minutes integer;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = employee_id_param
      AND e.organization_id = organization_id_param
      AND e.user_id = (SELECT auth.uid())
  ) THEN
    RAISE EXCEPTION 'Not authorized to record attendance for this employee' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_rules FROM public.load_attendance_rules(organization_id_param) r LIMIT 1;

  IF COALESCE(v_rules.require_photo_checkout, false)
     AND (photo_path_param IS NULL OR btrim(photo_path_param) = '') THEN
    RAISE EXCEPTION 'Photo is required for check-out per organization attendance rules';
  END IF;

  SELECT wss.timezone
  INTO v_tz
  FROM public.employees e
  LEFT JOIN public.work_schedule_settings wss
    ON wss.id = e.work_schedule_id
   AND wss.organization_id = organization_id_param
  WHERE e.id = employee_id_param
    AND e.organization_id = organization_id_param;

  v_tz := CASE WHEN v_tz IN ('Asia/Jakarta', 'Asia/Makassar', 'Asia/Jayapura') THEN v_tz ELSE 'Asia/Jakarta' END;
  v_today := (timezone(v_tz, v_now))::date;

  SELECT ar.*
  INTO v_rec
  FROM public.attendance_records ar
  WHERE ar.employee_id = employee_id_param
    AND ar.organization_id = organization_id_param
    AND (attendance_id_param IS NULL OR ar.id = attendance_id_param)
    AND ar.attendance_date BETWEEN v_today - 1 AND v_today
    AND (ar.check_in_time IS NOT NULL OR ar.check_in_at IS NOT NULL)
    AND ar.check_out_time IS NULL
    AND ar.check_out_at IS NULL
  ORDER BY ar.attendance_date DESC, ar.check_in_at DESC NULLS LAST
  LIMIT 1
  FOR UPDATE;

  IF v_rec.id IS NULL THEN
    RAISE EXCEPTION 'No open check-in found to check out';
  END IF;

  v_check_in := COALESCE(
    v_rec.check_in_at,
    (v_rec.attendance_date + v_rec.check_in_time) AT TIME ZONE v_tz
  );
  v_minutes := GREATEST(0, floor(extract(epoch FROM (v_now - v_check_in)) / 60)::integer);

  UPDATE public.attendance_records
  SET check_out_at = v_now,
      check_out_time = (timezone(v_tz, v_now))::time,
      check_out_location = COALESCE(location_data, '{}'::jsonb),
      check_out_photo_path = NULLIF(btrim(photo_path_param), ''),
      working_hours_minutes = v_minutes
  WHERE id = v_rec.id;

  RETURN jsonb_build_object(
    'attendance_id', v_rec.id,
    'attendance_date', v_rec.attendance_date,
    'check_out_at', v_now,
    'check_out_time', (timezone(v_tz, v_now))::time,
    'working_hours_minutes', v_minutes,
    'timezone', v_tz
  );
END;
$$;


ALTER FUNCTION "public"."record_attendance_checkout"("employee_id_param" "uuid", "organization_id_param" "uuid", "photo_path_param" "text", "location_data" "jsonb", "attendance_id_param" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_attendance_from_client_visit"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_visit_date" "date", "p_client_visit_id" "uuid", "p_location_id" "uuid", "p_actual_start_time" timestamp with time zone, "p_start_location" "jsonb", "p_start_photo_path" "text", "p_timezone" "text" DEFAULT 'Asia/Jakarta'::"text", "p_is_spontaneous" boolean DEFAULT false, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_existing uuid;
  v_local_ts timestamp;
  v_ts timestamptz;
  v_sched record;
  v_late_info jsonb;
  v_late boolean;
  v_late_mins integer;
  v_mode_text text;
  v_off record;
  v_dist numeric;
  v_radius numeric;
  new_id uuid := gen_random_uuid();
  v_penalty_result jsonb;
  v_penalties_applied integer := 0;
BEGIN
  SELECT ar.id
  INTO v_existing
  FROM public.attendance_records ar
  WHERE ar.employee_id = p_employee_id
    AND ar.organization_id = p_organization_id
    AND ar.attendance_date = p_visit_date
    AND (ar.check_in_time IS NOT NULL OR ar.check_in_at IS NOT NULL)
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object(
      'skipped', true,
      'reason', 'attendance_already_exists',
      'attendance_id', v_existing
    );
  END IF;

  v_local_ts := (p_actual_start_time AT TIME ZONE COALESCE(p_timezone, 'Asia/Jakarta'))::timestamp;
  v_ts := p_actual_start_time;

  v_late_info := public.resolve_attendance_late_for_day(
    p_employee_id,
    p_organization_id,
    p_visit_date,
    v_local_ts,
    p_client_visit_id,
    p_is_spontaneous
  );

  v_late := COALESCE((v_late_info->>'is_late')::boolean, false);
  v_late_mins := COALESCE((v_late_info->>'late_minutes')::integer, 0);
  v_mode_text := v_late_info->>'visit_day_mode';

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(p_employee_id, p_organization_id, p_visit_date) r
  LIMIT 1;

  SELECT
    ol.id,
    ol.radius_meters,
    (
      6371000.0 * acos(
        LEAST(
          1.0::double precision,
          GREATEST(
            -1.0::double precision,
            cos(radians(ol.latitude::double precision))
            * cos(radians((p_start_location->>'latitude')::double precision))
            * cos(
              radians((p_start_location->>'longitude')::double precision)
              - radians(ol.longitude::double precision)
            )
            + sin(radians(ol.latitude::double precision))
            * sin(radians((p_start_location->>'latitude')::double precision))
          )
        )
      )
    )::numeric AS dist
  INTO v_off
  FROM public.office_locations ol
  WHERE ol.id = p_location_id
    AND ol.organization_id = p_organization_id;

  IF v_off.id IS NULL THEN
    RAISE EXCEPTION 'Client visit location not found';
  END IF;

  v_dist := v_off.dist;
  v_radius := COALESCE(v_off.radius_meters::numeric, 100::numeric);
  IF v_dist > v_radius THEN
    RAISE EXCEPTION 'Location is outside client site radius';
  END IF;

  INSERT INTO public.attendance_records (
    id,
    employee_id,
    organization_id,
    attendance_date,
    check_in_time,
    check_in_at,
    check_in_photo_path,
    check_in_location,
    office_location_id,
    work_schedule_id,
    shift_id,
    employee_shift_id,
    is_late,
    late_minutes,
    status,
    notes,
    client_visit_id,
    check_in_source,
    visit_day_mode,
    created_at
  )
  VALUES (
    new_id,
    p_employee_id,
    p_organization_id,
    p_visit_date,
    v_local_ts::time,
    v_ts,
    NULLIF(btrim(p_start_photo_path), ''),
    p_start_location,
    v_off.id,
    v_sched.work_schedule_id,
    v_sched.shift_id,
    v_sched.employee_shift_id,
    v_late,
    v_late_mins,
    'present',
    NULLIF(btrim(p_notes), ''),
    p_client_visit_id,
    'client_visit',
    v_mode_text,
    now()
  );

  IF v_late THEN
    v_penalty_result := public.apply_late_arrival_penalties(new_id);
    v_penalties_applied := COALESCE((v_penalty_result->>'applied')::integer, 0);
  END IF;

  RETURN jsonb_build_object(
    'skipped', false,
    'attendance_id', new_id,
    'attendance_auto_checkin', true,
    'visit_day_mode', v_mode_text,
    'is_late', v_late,
    'late_minutes', v_late_mins,
    'penalties_applied', v_penalties_applied,
    'penalty_details', v_penalty_result
  );
END;
$$;


ALTER FUNCTION "public"."record_attendance_from_client_visit"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_visit_date" "date", "p_client_visit_id" "uuid", "p_location_id" "uuid", "p_actual_start_time" timestamp with time zone, "p_start_location" "jsonb", "p_start_photo_path" "text", "p_timezone" "text", "p_is_spontaneous" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_attendance_with_timezone"("employee_id_param" "uuid", "organization_id_param" "uuid", "local_checkin_time" "text", "latitude_param" double precision, "longitude_param" double precision, "timezone_param" "text" DEFAULT 'Asia/Jakarta'::"text", "photo_path_param" "text" DEFAULT NULL::"text", "location_data" "jsonb" DEFAULT '{}'::"jsonb", "notes_param" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_auth boolean;
  v_ts timestamptz;
  v_date date;
  v_local_ts timestamp;
  v_sched record;
  v_rules record;
  v_mode jsonb;
  v_mode_text text;
  v_late_info jsonb;
  v_late boolean := false;
  v_late_mins integer := 0;
  v_sched_ok boolean := false;
  v_holiday boolean;
  v_holiday_blocks boolean;
  v_off record;
  v_dist numeric;
  v_radius numeric;
  v_loc_ok boolean;
  new_id uuid := gen_random_uuid();
  v_status text := 'present';
  v_penalty_result jsonb;
  v_penalties_applied integer := 0;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = employee_id_param
      AND e.organization_id = organization_id_param
      AND e.user_id = (SELECT auth.uid())
  )
  INTO v_auth;

  IF NOT v_auth THEN
    RAISE EXCEPTION 'Not authorized to record attendance for this employee';
  END IF;

  SELECT *
  INTO v_rules
  FROM public.load_attendance_rules(organization_id_param) r
  LIMIT 1;

  IF COALESCE(v_rules.require_photo_checkin, false)
     AND (photo_path_param IS NULL OR btrim(photo_path_param) = '') THEN
    RAISE EXCEPTION 'Photo is required for check-in per organization attendance rules';
  END IF;

  timezone_param := CASE
      WHEN timezone_param IN ('Asia/Jakarta', 'Asia/Makassar', 'Asia/Jayapura') THEN timezone_param
      ELSE 'Asia/Jakarta'
    END;
  -- Jam check-in memakai jam server, bukan jam yang dikirim perangkat
  v_local_ts := (now() AT TIME ZONE timezone_param)::timestamp;
  v_date := v_local_ts::date;
  v_ts := v_local_ts AT TIME ZONE timezone_param;

  IF EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.employee_id = employee_id_param
      AND ar.organization_id = organization_id_param
      AND ar.attendance_date = v_date
      AND (ar.check_in_time IS NOT NULL OR ar.check_in_at IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Attendance already recorded for this date';
  END IF;

  v_mode := public.resolve_visit_day_mode(employee_id_param, organization_id_param, v_date);
  v_mode_text := COALESCE(v_mode->>'mode', 'normal');

  IF v_mode_text IN ('field_first', 'travel_field')
     AND COALESCE(v_rules.enable_visit_attendance_integration, true) THEN
    RAISE EXCEPTION 'USE_CLIENT_VISIT_CHECKIN';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.national_holidays nh
    WHERE COALESCE(nh.is_active, true)
      AND COALESCE(nh.applies_to_attendance, true)
      AND nh.date = v_date
      AND (
        nh.organization_id IS NULL
        OR nh.organization_id = organization_id_param
      )
  )
  INTO v_holiday;

  v_holiday_blocks := v_holiday AND COALESCE(v_rules.enforce_national_holidays, true);
  IF v_holiday_blocks THEN
    RAISE EXCEPTION 'Attendance is not allowed on national holidays per organization rules';
  END IF;

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(
    employee_id_param,
    organization_id_param,
    v_date
  ) r
  LIMIT 1;

  IF v_sched.work_schedule_id IS NOT NULL OR v_sched.shift_id IS NOT NULL THEN
    v_sched_ok := COALESCE(v_sched.is_working_day, false);
    IF NOT v_sched_ok
       AND v_sched.source = 'shift'
       AND v_sched.shift_id IS NOT NULL
       AND v_sched.employee_shift_id IS NOT NULL THEN
      v_sched_ok := true;
    END IF;
    IF NOT v_sched_ok THEN
      RAISE EXCEPTION 'Attendance is not allowed on this day per work schedule';
    END IF;
  END IF;

  v_late_info := public.resolve_attendance_late_for_day(
    employee_id_param,
    organization_id_param,
    v_date,
    v_local_ts,
    NULL,
    false
  );
  v_late := COALESCE((v_late_info->>'is_late')::boolean, false);
  v_late_mins := COALESCE((v_late_info->>'late_minutes')::integer, 0);

  SELECT
    ol.id,
    ol.radius_meters,
    (
      6371000.0 * acos(
        LEAST(
          1.0::double precision,
          GREATEST(
            -1.0::double precision,
            cos(radians(ol.latitude::double precision))
            * cos(radians(latitude_param))
            * cos(radians(longitude_param) - radians(ol.longitude::double precision))
            + sin(radians(ol.latitude::double precision))
            * sin(radians(latitude_param))
          )
        )
      )
    )::numeric AS dist
  INTO v_off
  FROM public.office_locations ol
  WHERE ol.organization_id = organization_id_param
    AND COALESCE(ol.is_active, true)
    AND COALESCE(ol.is_client_location, false) IS NOT TRUE
    AND ol.latitude IS NOT NULL
    AND ol.longitude IS NOT NULL
  ORDER BY dist ASC
  LIMIT 1;

  IF v_off.id IS NULL THEN
    RAISE EXCEPTION 'Office location required for attendance';
  END IF;

  v_dist := v_off.dist;
  v_radius := COALESCE(
    v_off.radius_meters::numeric,
    v_rules.default_max_radius_meters::numeric,
    100::numeric
  );
  v_loc_ok := v_dist <= v_radius;

  IF NOT v_loc_ok THEN
    RAISE EXCEPTION 'Location is outside allowed office radius (% m, max % m)', v_dist, v_radius;
  END IF;

  INSERT INTO public.attendance_records (
    id,
    employee_id,
    organization_id,
    attendance_date,
    check_in_time,
    check_in_at,
    check_in_photo_path,
    check_in_location,
    office_location_id,
    work_schedule_id,
    shift_id,
    employee_shift_id,
    is_late,
    late_minutes,
    status,
    notes,
    check_in_source,
    visit_day_mode,
    created_at
  )
  VALUES (
    new_id,
    employee_id_param,
    organization_id_param,
    v_date,
    v_local_ts::time,
    v_ts,
    NULLIF(btrim(photo_path_param), ''),
    location_data,
    v_off.id,
    v_sched.work_schedule_id,
    v_sched.shift_id,
    v_sched.employee_shift_id,
    v_late,
    v_late_mins,
    v_status,
    NULLIF(btrim(notes_param), ''),
    'office',
    v_mode_text,
    now()
  );

  IF v_late THEN
    v_penalty_result := public.apply_late_arrival_penalties(new_id);
    v_penalties_applied := COALESCE((v_penalty_result->>'applied')::integer, 0);
  END IF;

  RETURN jsonb_build_array(
    jsonb_build_object(
      'attendance_id', new_id,
      'is_late', v_late,
      'late_minutes', v_late_mins,
      'status', v_status,
      'shift_id', v_sched.shift_id,
      'employee_shift_id', v_sched.employee_shift_id,
      'work_schedule_id', v_sched.work_schedule_id,
      'schedule_source', v_sched.source,
      'start_time', v_sched.start_time,
      'visit_day_mode', v_mode_text,
      'penalties_applied', v_penalties_applied,
      'penalty_details', v_penalty_result
    )
  );
END;
$$;


ALTER FUNCTION "public"."record_attendance_with_timezone"("employee_id_param" "uuid", "organization_id_param" "uuid", "local_checkin_time" "text", "latitude_param" double precision, "longitude_param" double precision, "timezone_param" "text", "photo_path_param" "text", "location_data" "jsonb", "notes_param" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_content_brief_version"("p_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF p_plan_id IS NULL OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  SELECT plan.organization_id
    INTO v_org
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan not found'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_org NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  RETURN public.content_brief_snapshot(p_plan_id, auth.uid(), 'office');
END;
$$;


ALTER FUNCTION "public"."record_content_brief_version"("p_plan_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_content_brief_version"("p_plan_id" "uuid") IS 'Copy the live brief into history when it differs from the latest snapshot. Returns null when nothing changed.';



CREATE OR REPLACE FUNCTION "public"."record_marketing_short_link_visitor"("p_link_id" "uuid", "p_visitor_key" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_visitor_key is null or btrim(p_visitor_key) = '' then
    return;
  end if;

  with ins as (
    insert into public.marketing_short_link_visitors (link_id, visitor_key)
    values (p_link_id, left(btrim(p_visitor_key), 64))
    on conflict (link_id, visitor_key) do nothing
    returning link_id
  )
  update public.marketing_short_links m
  set visitor_count = visitor_count + 1
  from ins
  where m.id = ins.link_id
    and m.active = true;
end;
$$;


ALTER FUNCTION "public"."record_marketing_short_link_visitor"("p_link_id" "uuid", "p_visitor_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_store_checkout_income"("p_activity_id" "uuid", "p_payment_method" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org_id uuid;
  v_type text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'store_checkout_forbidden';
  END IF;

  SELECT organization_id, activity_type
  INTO v_org_id, v_type
  FROM public.sales_activities
  WHERE id = p_activity_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'store_checkout_not_found';
  END IF;

  IF v_org_id IS NULL OR v_org_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'store_checkout_forbidden';
  END IF;

  IF v_type IS DISTINCT FROM 'Store Checkout' THEN
    RAISE EXCEPTION 'store_checkout_wrong_type';
  END IF;

  RETURN public.apply_store_checkout_income(
    p_activity_id,
    p_payment_method,
    auth.uid()
  );
END;
$$;


ALTER FUNCTION "public"."record_store_checkout_income"("p_activity_id" "uuid", "p_payment_method" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_store_checkout_income"("p_activity_id" "uuid", "p_payment_method" "text") IS 'Store POS: cash completed off-bank; bank_transfer/e_wallet credit omnichannel once. Optional payment_reference is copied onto income description.';



CREATE OR REPLACE FUNCTION "public"."recover_stale_publishing_rows"("p_stale_minutes" integer DEFAULT 10) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_row record;
  v_max_retries integer := 8;
BEGIN
  FOR v_row IN
    SELECT s.*
    FROM public.social_media_scheduled_posts s
    WHERE s.status = 'publishing'
      AND COALESCE(s.locked_at, s.updated_at) < now() - make_interval(mins => GREATEST(1, p_stale_minutes))
      AND NOT (
        (
          s.platform = 'TikTok'
          AND s.provider_config->>'tiktok_publish_id' IS NOT NULL
        )
        OR (
          s.platform = 'YouTube'
          AND s.provider_config->>'youtube_video_id' IS NOT NULL
        )
        OR (
          s.platform = 'Instagram'
          AND s.provider_config->>'ig_container_id' IS NOT NULL
          AND COALESCE(s.provider_config->>'ig_upload_phase', '') IN ('uploaded', 'published')
        )
        OR (
          s.platform = 'Facebook'
          AND s.provider_config->>'fb_video_id' IS NOT NULL
        )
        OR (
          s.platform = 'LinkedIn'
          AND s.provider_config->>'linkedin_post_urn' IS NOT NULL
        )
      )
    FOR UPDATE SKIP LOCKED
  LOOP
    IF v_row.retry_count >= v_max_retries THEN
      UPDATE public.social_media_scheduled_posts
      SET
        status = 'failed',
        error_message = 'publish_stalled_max_retries',
        last_error_at = now(),
        next_retry_at = NULL,
        locked_at = NULL,
        updated_at = now()
      WHERE id = v_row.id;
    ELSE
      UPDATE public.social_media_scheduled_posts
      SET
        status = 'pending',
        retry_count = v_row.retry_count + 1,
        next_retry_at = now(),
        last_error_at = now(),
        error_message = 'publish_stalled: no progress while publishing',
        locked_at = NULL,
        updated_at = now()
      WHERE id = v_row.id;
    END IF;
    v_count := v_count + 1;
  END LOOP;

  IF v_count > 0 THEN
    RAISE LOG 'recover_stale_publishing_rows: recovered % row(s)', v_count;
  END IF;

  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."recover_stale_publishing_rows"("p_stale_minutes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."recover_stale_publishing_rows"("p_stale_minutes" integer) IS 'Move publishing rows with no heartbeat and no platform resume state back to pending for the same tick.';



CREATE OR REPLACE FUNCTION "public"."recruitment_file_in_active_org"("p_name" "text", "p_owner" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_org uuid := public.storage_active_organization_id();
  v_top text;
  v_owner uuid := COALESCE(p_owner, (SELECT auth.uid()));
BEGIN
  IF v_org IS NULL OR p_name IS NULL OR position('../' in p_name) > 0 THEN
    RETURN false;
  END IF;
  v_top := (storage.foldername(p_name))[1];
  IF v_top = 'apply' OR (v_top = 'cvs' AND p_owner IS NULL) THEN
    RETURN EXISTS (SELECT 1 FROM public.job_applications ja
                   WHERE ja.cv_file_path = p_name AND ja.organization_id = v_org)
        OR EXISTS (SELECT 1 FROM public.candidate_profiles c
                   WHERE c.cv_file_path = p_name AND c.organization_id = v_org);
  END IF;
  IF v_top = 'cvs' THEN
    RETURN public.storage_user_in_active_org(v_owner::text);
  END IF;
  IF v_top ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    IF EXISTS (
      SELECT 1 FROM public.candidate_profiles c
      WHERE c.id::text = v_top AND c.organization_id = v_org
    ) OR EXISTS (
      SELECT 1 FROM public.candidate_documents d
      JOIN public.candidate_profiles c ON c.id = d.candidate_profile_id
      WHERE d.file_path = p_name AND c.organization_id = v_org
    ) OR EXISTS (
      SELECT 1 FROM public.candidate_profiles c
      WHERE c.cv_file_path = p_name AND c.organization_id = v_org
    ) THEN
      RETURN true;
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.candidate_profiles c
      WHERE c.id::text = v_top AND c.organization_id IS DISTINCT FROM v_org
    ) THEN
      RETURN false;
    END IF;
  END IF;
  RETURN public.storage_user_in_active_org(v_owner::text);
END;
$_$;


ALTER FUNCTION "public"."recruitment_file_in_active_org"("p_name" "text", "p_owner" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recruitment_public_upload_allowed"("p_name" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  parts text[];
BEGIN
  IF p_name IS NULL OR position('..' in p_name) > 0 OR length(p_name) > 400 THEN
    RETURN false;
  END IF;
  parts := storage.foldername(p_name);
  IF parts[1] = 'apply' THEN
    RETURN array_length(parts, 1) = 2
      AND p_name ~* '\.(pdf|doc|docx)$'
      AND EXISTS (SELECT 1 FROM public.recruitment_links rl
                  WHERE rl.token = parts[2] AND rl.status = 'active'
                    AND (rl.expires_at IS NULL OR rl.expires_at > now()));
  END IF;
  IF parts[1] ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    RETURN array_length(parts, 1) = 1
      AND p_name ~* '\.(pdf|doc|docx|jpg|jpeg|png|webp)$'
      AND EXISTS (SELECT 1 FROM public.candidate_profiles c
                  WHERE c.id::text = parts[1] AND c.recruitment_token ~ '^cand_[0-9a-f]{48}$');
  END IF;
  RETURN false;
END;
$_$;


ALTER FUNCTION "public"."recruitment_public_upload_allowed"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_analytics_daily_click_rollups"("p_from" "date", "p_to" "date" DEFAULT NULL::"date", "p_web_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_to date;
  v_web text;
begin
  v_to := coalesce(p_to, p_from);
  if p_from > v_to then
    raise exception 'invalid date range' using errcode = '22023';
  end if;

  v_web := public.hub_require_active_web_id(p_web_id, true);

  delete from public.analytics_daily_clicks d
  where d.day between p_from and v_to
    and (v_web is null or d.web_id = v_web);

  delete from public.analytics_daily_top_click_targets t
  where t.day between p_from and v_to
    and (v_web is null or t.web_id = v_web);

  delete from public.analytics_daily_top_clicks t
  where t.day between p_from and v_to
    and (v_web is null or t.web_id = v_web);

  delete from public.analytics_daily_sessions s
  where s.day between p_from and v_to
    and (v_web is null or s.web_id = v_web);

  insert into public.analytics_daily_clicks (web_id, day, clicks_count, unique_sessions_count)
  select
    ce.web_id,
    (timezone('Asia/Jakarta', ce.created_at))::date as day,
    count(*)::bigint,
    count(distinct ce.session_id)::bigint
  from public.analytics_click_events ce
  where (v_web is null or ce.web_id = v_web)
    and (timezone('Asia/Jakarta', ce.created_at))::date between p_from and v_to
  group by ce.web_id, (timezone('Asia/Jakarta', ce.created_at))::date;

  insert into public.analytics_daily_top_click_targets (
    web_id,
    day,
    path,
    track_key,
    element_type,
    element_label,
    target_url,
    is_internal,
    clicks_count,
    unique_sessions_count
  )
  select
    ce.web_id,
    (timezone('Asia/Jakarta', ce.created_at))::date as day,
    left(btrim(ce.path), 2048),
    coalesce(ce.track_key, ''),
    ce.element_type,
    ce.element_label,
    coalesce(ce.target_url, ''),
    coalesce(ce.is_internal, false),
    count(*)::bigint,
    count(distinct ce.session_id)::bigint
  from public.analytics_click_events ce
  where (v_web is null or ce.web_id = v_web)
    and (timezone('Asia/Jakarta', ce.created_at))::date between p_from and v_to
  group by
    ce.web_id,
    (timezone('Asia/Jakarta', ce.created_at))::date,
    left(btrim(ce.path), 2048),
    coalesce(ce.track_key, ''),
    ce.element_type,
    ce.element_label,
    coalesce(ce.target_url, ''),
    coalesce(ce.is_internal, false);

  insert into public.analytics_daily_top_clicks (
    web_id,
    day,
    path,
    track_key,
    element_type,
    element_label,
    clicks_count,
    unique_sessions_count
  )
  select
    ce.web_id,
    (timezone('Asia/Jakarta', ce.created_at))::date as day,
    left(btrim(ce.path), 2048),
    coalesce(ce.track_key, ''),
    ce.element_type,
    ce.element_label,
    count(*)::bigint,
    count(distinct ce.session_id)::bigint
  from public.analytics_click_events ce
  where (v_web is null or ce.web_id = v_web)
    and (timezone('Asia/Jakarta', ce.created_at))::date between p_from and v_to
  group by
    ce.web_id,
    (timezone('Asia/Jakarta', ce.created_at))::date,
    left(btrim(ce.path), 2048),
    coalesce(ce.track_key, ''),
    ce.element_type,
    ce.element_label;

  insert into public.analytics_daily_sessions (
    web_id,
    day,
    sessions_count,
    sessions_with_utm_count,
    sessions_with_gclid_count,
    sessions_with_fbclid_count,
    sessions_with_msclkid_count
  )
  select
    s.web_id,
    (timezone('Asia/Jakarta', s.started_at))::date as day,
    count(distinct s.id)::bigint,
    count(distinct s.id) filter (
      where
        nullif(btrim(s.utm_source), '') is not null
        or nullif(btrim(s.utm_medium), '') is not null
        or nullif(btrim(s.utm_campaign), '') is not null
    )::bigint,
    count(distinct s.id) filter (where coalesce(s.has_gclid, false))::bigint,
    count(distinct s.id) filter (where coalesce(s.has_fbclid, false))::bigint,
    count(distinct s.id) filter (where coalesce(s.has_msclkid, false))::bigint
  from public.analytics_sessions s
  where (v_web is null or s.web_id = v_web)
    and (timezone('Asia/Jakarta', s.started_at))::date between p_from and v_to
  group by s.web_id, (timezone('Asia/Jakarta', s.started_at))::date;
end;
$$;


ALTER FUNCTION "public"."refresh_analytics_daily_click_rollups"("p_from" "date", "p_to" "date", "p_web_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_analytics_daily_rollups"("p_from" "date", "p_to" "date" DEFAULT NULL::"date", "p_web_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_to date;
BEGIN
  v_to := coalesce(p_to, p_from);
  IF p_from > v_to THEN
    RAISE EXCEPTION 'invalid date range' USING errcode = '22023';
  END IF;

  IF p_web_id IS NOT NULL
    AND (btrim(p_web_id) = '' OR p_web_id NOT IN ('vialdi', 'vialdi-wedding', 'synckerja')) THEN
    RAISE EXCEPTION 'invalid web_id' USING errcode = '22023';
  END IF;

  DELETE FROM public.analytics_daily_source_breakdown d
  WHERE d.day BETWEEN p_from AND v_to
    AND (p_web_id IS NULL OR d.web_id = p_web_id);

  DELETE FROM public.analytics_daily_utm u
  WHERE u.day BETWEEN p_from AND v_to
    AND (p_web_id IS NULL OR u.web_id = p_web_id);

  INSERT INTO public.analytics_daily_source_breakdown (
    web_id,
    day,
    source_key,
    sessions_count,
    page_views_count,
    clicks_count,
    scroll_sessions_count,
    scroll_max_pct_max,
    scroll_max_pct_sum
  )
  WITH human_sessions AS (
    SELECT DISTINCT
      pv.web_id,
      pv.session_id,
      (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date AS day
    FROM public.analytics_page_views pv
    WHERE
      (p_web_id IS NULL OR pv.web_id = p_web_id)
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
      AND (
        coalesce(pv.active_ms, 0) > 0
        OR coalesce(pv.scroll_max_pct, 0) >= 5
        OR (
          pv.ended_at IS NOT NULL
          AND extract(epoch FROM (pv.ended_at - pv.started_at)) >= 5
        )
      )
  ),
  base AS (
    SELECT
      hs.web_id,
      hs.day,
      hs.session_id,
      public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS landing_url,
      public.traffic_first_utm_dim(s.first_utm_source, s.utm_source, s.last_utm_source) AS utm_source,
      public.traffic_first_utm_dim(s.first_utm_medium, s.utm_medium, s.last_utm_medium) AS utm_medium,
      public.traffic_first_utm_dim(s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign) AS utm_campaign,
      public.traffic_first_utm_dim(s.first_utm_content, s.utm_content, s.last_utm_content) AS utm_content,
      public.traffic_first_utm_dim(s.first_utm_term, s.utm_term, s.last_utm_term) AS utm_term,
      (coalesce(s.has_gclid, false) OR coalesce(s.first_has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
      (coalesce(s.has_fbclid, false) OR coalesce(s.first_has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
      (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
      (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
      (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
      public.traffic_first_referrer(s.first_referrer, s.referrer, s.last_referrer) AS referrer
    FROM human_sessions hs
    INNER JOIN public.analytics_sessions s
      ON s.id = hs.session_id
      AND s.web_id = hs.web_id
  ),
  effective AS (
    SELECT
      web_id,
      day,
      session_id,
      coalesce(
        nullif(btrim(utm_source), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_source=([^&]*)'))[1]),
          ''
        )
      ) AS utm_source_eff,
      coalesce(
        nullif(btrim(utm_medium), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_medium=([^&]*)'))[1]),
          ''
        )
      ) AS utm_medium_eff,
      coalesce(
        nullif(btrim(utm_campaign), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_campaign=([^&]*)'))[1]),
          ''
        )
      ) AS utm_campaign_eff,
      coalesce(
        nullif(btrim(utm_content), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_content=([^&]*)'))[1]),
          ''
        )
      ) AS utm_content_eff,
      coalesce(
        nullif(btrim(utm_term), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_term=([^&]*)'))[1]),
          ''
        )
      ) AS utm_term_eff,
      has_gclid,
      has_fbclid,
      has_msclkid,
      has_gbraid,
      has_wbraid,
      referrer
    FROM base
  ),
  classified AS (
    SELECT
      web_id,
      day,
      session_id,
      CASE
        WHEN has_gclid OR has_fbclid OR has_msclkid OR has_gbraid OR has_wbraid THEN 'paid_click_ids'
        WHEN
          nullif(btrim(utm_source_eff), '') IS NOT NULL
          OR nullif(btrim(utm_medium_eff), '') IS NOT NULL
          OR nullif(btrim(utm_campaign_eff), '') IS NOT NULL
          OR nullif(btrim(utm_content_eff), '') IS NOT NULL
          OR nullif(btrim(utm_term_eff), '') IS NOT NULL
          THEN 'utm'
        WHEN nullif(btrim(referrer), '') IS NOT NULL THEN 'referral'
        ELSE 'direct'
      END AS source_key
    FROM effective
  ),
  click_session_days AS (
    SELECT DISTINCT
      ce.web_id,
      ce.session_id,
      (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day
    FROM public.analytics_click_events ce
    WHERE
      (p_web_id IS NULL OR ce.web_id = p_web_id)
      AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
      AND ce.session_id IS NOT NULL
  ),
  click_base AS (
    SELECT
      csd.web_id,
      csd.day,
      csd.session_id,
      public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS landing_url,
      public.traffic_first_utm_dim(s.first_utm_source, s.utm_source, s.last_utm_source) AS utm_source,
      public.traffic_first_utm_dim(s.first_utm_medium, s.utm_medium, s.last_utm_medium) AS utm_medium,
      public.traffic_first_utm_dim(s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign) AS utm_campaign,
      public.traffic_first_utm_dim(s.first_utm_content, s.utm_content, s.last_utm_content) AS utm_content,
      public.traffic_first_utm_dim(s.first_utm_term, s.utm_term, s.last_utm_term) AS utm_term,
      (coalesce(s.has_gclid, false) OR coalesce(s.first_has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
      (coalesce(s.has_fbclid, false) OR coalesce(s.first_has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
      (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
      (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
      (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
      public.traffic_first_referrer(s.first_referrer, s.referrer, s.last_referrer) AS referrer
    FROM click_session_days csd
    LEFT JOIN public.analytics_sessions s
      ON s.id = csd.session_id
      AND s.web_id = csd.web_id
  ),
  click_effective AS (
    SELECT
      web_id,
      day,
      session_id,
      coalesce(
        nullif(btrim(utm_source), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_source=([^&]*)'))[1]),
          ''
        )
      ) AS utm_source_eff,
      coalesce(
        nullif(btrim(utm_medium), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_medium=([^&]*)'))[1]),
          ''
        )
      ) AS utm_medium_eff,
      coalesce(
        nullif(btrim(utm_campaign), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_campaign=([^&]*)'))[1]),
          ''
        )
      ) AS utm_campaign_eff,
      coalesce(
        nullif(btrim(utm_content), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_content=([^&]*)'))[1]),
          ''
        )
      ) AS utm_content_eff,
      coalesce(
        nullif(btrim(utm_term), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_term=([^&]*)'))[1]),
          ''
        )
      ) AS utm_term_eff,
      has_gclid,
      has_fbclid,
      has_msclkid,
      has_gbraid,
      has_wbraid,
      referrer
    FROM click_base
  ),
  click_classified AS (
    SELECT
      web_id,
      day,
      session_id,
      CASE
        WHEN has_gclid OR has_fbclid OR has_msclkid OR has_gbraid OR has_wbraid THEN 'paid_click_ids'
        WHEN
          nullif(btrim(utm_source_eff), '') IS NOT NULL
          OR nullif(btrim(utm_medium_eff), '') IS NOT NULL
          OR nullif(btrim(utm_campaign_eff), '') IS NOT NULL
          OR nullif(btrim(utm_content_eff), '') IS NOT NULL
          OR nullif(btrim(utm_term_eff), '') IS NOT NULL
          THEN 'utm'
        WHEN nullif(btrim(referrer), '') IS NOT NULL THEN 'referral'
        ELSE 'direct'
      END AS source_key
    FROM click_effective
  ),
  src_keys AS (
    SELECT * FROM (VALUES ('utm'::text), ('paid_click_ids'::text), ('referral'::text), ('direct'::text)) v(source_key)
  ),
  sess_agg AS (
    SELECT
      web_id,
      day,
      source_key,
      count(*)::bigint AS sessions_count
    FROM classified
    GROUP BY web_id, day, source_key
  ),
  pv_agg AS (
    SELECT
      c.web_id,
      c.day,
      c.source_key,
      count(*)::bigint AS page_views_count
    FROM classified c
    INNER JOIN public.analytics_page_views pv
      ON pv.web_id = c.web_id
      AND pv.session_id = c.session_id
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date = c.day
    GROUP BY c.web_id, c.day, c.source_key
  ),
  ce_agg AS (
    SELECT
      web_id,
      day,
      source_key,
      sum(cnt)::bigint AS clicks_count
    FROM (
      SELECT
        cc.web_id,
        cc.day,
        cc.source_key,
        count(*)::bigint AS cnt
      FROM public.analytics_click_events ce
      INNER JOIN click_classified cc
        ON cc.web_id = ce.web_id
        AND cc.session_id = ce.session_id
        AND cc.day = (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date
      WHERE
        (p_web_id IS NULL OR ce.web_id = p_web_id)
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
        AND ce.session_id IS NOT NULL
      GROUP BY cc.web_id, cc.day, cc.source_key
      UNION ALL
      SELECT
        ce.web_id,
        (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
        'direct'::text AS source_key,
        count(*)::bigint AS cnt
      FROM public.analytics_click_events ce
      WHERE
        (p_web_id IS NULL OR ce.web_id = p_web_id)
        AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
        AND ce.session_id IS NULL
      GROUP BY ce.web_id, (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date
    ) u
    GROUP BY web_id, day, source_key
  ),
  scroll_sess AS (
    SELECT
      c.web_id,
      c.day,
      c.source_key,
      c.session_id,
      max(pv.scroll_max_pct)::double precision AS session_max_scroll_pct
    FROM classified c
    INNER JOIN public.analytics_page_views pv
      ON pv.web_id = c.web_id
      AND pv.session_id = c.session_id
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date = c.day
      AND pv.scroll_max_pct IS NOT NULL
    GROUP BY c.web_id, c.day, c.source_key, c.session_id
  ),
  scroll_agg AS (
    SELECT
      web_id,
      day,
      source_key,
      count(*)::bigint AS scroll_sessions_count,
      max(session_max_scroll_pct)::double precision AS scroll_max_pct_max,
      coalesce(sum(session_max_scroll_pct), 0)::double precision AS scroll_max_pct_sum
    FROM scroll_sess
    GROUP BY web_id, day, source_key
  ),
  web_days AS (
    SELECT DISTINCT web_id, day FROM classified
    UNION
    SELECT DISTINCT web_id, day FROM ce_agg
  )
  SELECT
    w.web_id,
    w.day,
    k.source_key,
    coalesce(sa.sessions_count, 0)::bigint,
    coalesce(pva.page_views_count, 0)::bigint,
    coalesce(ca.clicks_count, 0)::bigint,
    coalesce(sca.scroll_sessions_count, 0)::bigint,
    sca.scroll_max_pct_max,
    coalesce(sca.scroll_max_pct_sum, 0)::double precision
  FROM web_days w
  CROSS JOIN src_keys k
  LEFT JOIN sess_agg sa
    ON sa.web_id = w.web_id AND sa.day = w.day AND sa.source_key = k.source_key
  LEFT JOIN pv_agg pva
    ON pva.web_id = w.web_id AND pva.day = w.day AND pva.source_key = k.source_key
  LEFT JOIN ce_agg ca
    ON ca.web_id = w.web_id AND ca.day = w.day AND ca.source_key = k.source_key
  LEFT JOIN scroll_agg sca
    ON sca.web_id = w.web_id AND sca.day = w.day AND sca.source_key = k.source_key
  WHERE
    coalesce(sa.sessions_count, 0) > 0
    OR coalesce(pva.page_views_count, 0) > 0
    OR coalesce(ca.clicks_count, 0) > 0
    OR coalesce(sca.scroll_sessions_count, 0) > 0
  ON CONFLICT (web_id, day, source_key) DO UPDATE SET
    sessions_count = excluded.sessions_count,
    page_views_count = excluded.page_views_count,
    clicks_count = excluded.clicks_count,
    scroll_sessions_count = excluded.scroll_sessions_count,
    scroll_max_pct_max = excluded.scroll_max_pct_max,
    scroll_max_pct_sum = excluded.scroll_max_pct_sum,
    updated_at = now();

  INSERT INTO public.analytics_daily_utm (
    web_id,
    day,
    route,
    utm_source,
    utm_medium,
    utm_campaign,
    utm_content,
    utm_term,
    sessions_count,
    page_views_count,
    clicks_count,
    scroll_sessions_count,
    scroll_max_pct_max,
    scroll_max_pct_sum
  )
  WITH human_sessions AS (
    SELECT DISTINCT
      pv.web_id,
      pv.session_id,
      (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date AS day
    FROM public.analytics_page_views pv
    WHERE
      (p_web_id IS NULL OR pv.web_id = p_web_id)
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
      AND (
        coalesce(pv.active_ms, 0) > 0
        OR coalesce(pv.scroll_max_pct, 0) >= 5
        OR (
          pv.ended_at IS NOT NULL
          AND extract(epoch FROM (pv.ended_at - pv.started_at)) >= 5
        )
      )
  ),
  base AS (
    SELECT
      hs.web_id,
      hs.day,
      hs.session_id,
      public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS landing_url,
      public.traffic_first_utm_dim(s.first_utm_source, s.utm_source, s.last_utm_source) AS utm_source,
      public.traffic_first_utm_dim(s.first_utm_medium, s.utm_medium, s.last_utm_medium) AS utm_medium,
      public.traffic_first_utm_dim(s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign) AS utm_campaign,
      public.traffic_first_utm_dim(s.first_utm_content, s.utm_content, s.last_utm_content) AS utm_content,
      public.traffic_first_utm_dim(s.first_utm_term, s.utm_term, s.last_utm_term) AS utm_term,
      (coalesce(s.has_gclid, false) OR coalesce(s.first_has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
      (coalesce(s.has_fbclid, false) OR coalesce(s.first_has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
      (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
      (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
      (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
      public.traffic_first_referrer(s.first_referrer, s.referrer, s.last_referrer) AS referrer
    FROM human_sessions hs
    INNER JOIN public.analytics_sessions s
      ON s.id = hs.session_id
      AND s.web_id = hs.web_id
  ),
  effective AS (
    SELECT
      web_id,
      day,
      session_id,
      coalesce(
        nullif(btrim(utm_source), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_source=([^&]*)'))[1]),
          ''
        )
      ) AS utm_source_eff,
      coalesce(
        nullif(btrim(utm_medium), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_medium=([^&]*)'))[1]),
          ''
        )
      ) AS utm_medium_eff,
      coalesce(
        nullif(btrim(utm_campaign), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_campaign=([^&]*)'))[1]),
          ''
        )
      ) AS utm_campaign_eff,
      coalesce(
        nullif(btrim(utm_content), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_content=([^&]*)'))[1]),
          ''
        )
      ) AS utm_content_eff,
      coalesce(
        nullif(btrim(utm_term), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_term=([^&]*)'))[1]),
          ''
        )
      ) AS utm_term_eff,
      has_gclid,
      has_fbclid,
      has_msclkid,
      has_gbraid,
      has_wbraid,
      referrer
    FROM base
  ),
  classified AS (
    SELECT
      *,
      CASE
        WHEN has_gclid OR has_fbclid OR has_msclkid OR has_gbraid OR has_wbraid THEN 'paid_click_ids'
        WHEN
          nullif(btrim(utm_source_eff), '') IS NOT NULL
          OR nullif(btrim(utm_medium_eff), '') IS NOT NULL
          OR nullif(btrim(utm_campaign_eff), '') IS NOT NULL
          OR nullif(btrim(utm_content_eff), '') IS NOT NULL
          OR nullif(btrim(utm_term_eff), '') IS NOT NULL
          THEN 'utm'
        WHEN nullif(btrim(referrer), '') IS NOT NULL THEN 'referral'
        ELSE 'direct'
      END AS source_key
    FROM effective
  ),
  pv_day AS (
    SELECT
      pv.web_id,
      pv.session_id,
      (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      count(*)::bigint AS pv_n
    FROM public.analytics_page_views pv
    WHERE
      (p_web_id IS NULL OR pv.web_id = p_web_id)
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
    GROUP BY pv.web_id, pv.session_id, (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date
  ),
  ce_day AS (
    SELECT
      ce.web_id,
      ce.session_id,
      (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      count(*)::bigint AS ce_n
    FROM public.analytics_click_events ce
    WHERE
      (p_web_id IS NULL OR ce.web_id = p_web_id)
      AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
    GROUP BY ce.web_id, ce.session_id, (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date
  ),
  scroll_day AS (
    SELECT
      pv.web_id,
      pv.session_id,
      (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date AS day,
      max(pv.scroll_max_pct)::double precision AS smax
    FROM public.analytics_page_views pv
    WHERE
      (p_web_id IS NULL OR pv.web_id = p_web_id)
      AND (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
      AND pv.scroll_max_pct IS NOT NULL
    GROUP BY pv.web_id, pv.session_id, (pv.started_at AT TIME ZONE 'Asia/Jakarta')::date
  ),
  click_session_days AS (
    SELECT DISTINCT
      ce.web_id,
      ce.session_id,
      (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date AS day
    FROM public.analytics_click_events ce
    WHERE
      (p_web_id IS NULL OR ce.web_id = p_web_id)
      AND (ce.created_at AT TIME ZONE 'Asia/Jakarta')::date BETWEEN p_from AND v_to
      AND ce.session_id IS NOT NULL
  ),
  click_base AS (
    SELECT
      csd.web_id,
      csd.day,
      csd.session_id,
      public.traffic_first_landing_url(s.first_landing_url, s.landing_url, s.last_landing_url) AS landing_url,
      public.traffic_first_utm_dim(s.first_utm_source, s.utm_source, s.last_utm_source) AS utm_source,
      public.traffic_first_utm_dim(s.first_utm_medium, s.utm_medium, s.last_utm_medium) AS utm_medium,
      public.traffic_first_utm_dim(s.first_utm_campaign, s.utm_campaign, s.last_utm_campaign) AS utm_campaign,
      public.traffic_first_utm_dim(s.first_utm_content, s.utm_content, s.last_utm_content) AS utm_content,
      public.traffic_first_utm_dim(s.first_utm_term, s.utm_term, s.last_utm_term) AS utm_term,
      (coalesce(s.has_gclid, false) OR coalesce(s.first_has_gclid, false) OR coalesce(s.last_has_gclid, false)) AS has_gclid,
      (coalesce(s.has_fbclid, false) OR coalesce(s.first_has_fbclid, false) OR coalesce(s.last_has_fbclid, false)) AS has_fbclid,
      (coalesce(s.has_msclkid, false) OR coalesce(s.last_has_msclkid, false)) AS has_msclkid,
      (coalesce(s.has_gbraid, false) OR coalesce(s.last_has_gbraid, false)) AS has_gbraid,
      (coalesce(s.has_wbraid, false) OR coalesce(s.last_has_wbraid, false)) AS has_wbraid,
      public.traffic_first_referrer(s.first_referrer, s.referrer, s.last_referrer) AS referrer
    FROM click_session_days csd
    LEFT JOIN public.analytics_sessions s
      ON s.id = csd.session_id
      AND s.web_id = csd.web_id
  ),
  click_effective AS (
    SELECT
      web_id,
      day,
      session_id,
      coalesce(
        nullif(btrim(utm_source), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_source=([^&]*)'))[1]),
          ''
        )
      ) AS utm_source_eff,
      coalesce(
        nullif(btrim(utm_medium), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_medium=([^&]*)'))[1]),
          ''
        )
      ) AS utm_medium_eff,
      coalesce(
        nullif(btrim(utm_campaign), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_campaign=([^&]*)'))[1]),
          ''
        )
      ) AS utm_campaign_eff,
      coalesce(
        nullif(btrim(utm_content), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_content=([^&]*)'))[1]),
          ''
        )
      ) AS utm_content_eff,
      coalesce(
        nullif(btrim(utm_term), ''),
        nullif(
          trim((regexp_match(coalesce(landing_url, ''), '(?i)[?&]utm_term=([^&]*)'))[1]),
          ''
        )
      ) AS utm_term_eff,
      has_gclid,
      has_fbclid,
      has_msclkid,
      has_gbraid,
      has_wbraid,
      referrer
    FROM click_base
  ),
  click_classified_utm AS (
    SELECT
      e.*,
      CASE
        WHEN e.has_gclid OR e.has_fbclid OR e.has_msclkid OR e.has_gbraid OR e.has_wbraid THEN 'paid_click_ids'
        WHEN
          nullif(btrim(e.utm_source_eff), '') IS NOT NULL
          OR nullif(btrim(e.utm_medium_eff), '') IS NOT NULL
          OR nullif(btrim(e.utm_campaign_eff), '') IS NOT NULL
          OR nullif(btrim(e.utm_content_eff), '') IS NOT NULL
          OR nullif(btrim(e.utm_term_eff), '') IS NOT NULL
          THEN 'utm'
        WHEN nullif(btrim(e.referrer), '') IS NOT NULL THEN 'referral'
        ELSE 'direct'
      END AS source_key
    FROM click_effective e
  ),
  utm_enriched_human AS (
    SELECT
      c.web_id,
      c.day,
      coalesce(
        left(
          CASE
            WHEN lp.route_path = '' AND lp.had_landing_ref THEN '/'
            WHEN lp.route_path = '' THEN ''
            WHEN left(lp.route_path, 1) = '/' THEN lp.route_path
            ELSE '/' || lp.route_path
          END,
          512
        ),
        ''
      ) AS route,
      coalesce(c.utm_source_eff, '') AS utm_source,
      coalesce(c.utm_medium_eff, '') AS utm_medium,
      coalesce(c.utm_campaign_eff, '') AS utm_campaign,
      coalesce(c.utm_content_eff, '') AS utm_content,
      coalesce(c.utm_term_eff, '') AS utm_term,
      coalesce(p.pv_n, 0)::bigint AS pv_n,
      coalesce(e.ce_n, 0)::bigint AS ce_n,
      sd.smax AS sess_scroll_max
    FROM classified c
    INNER JOIN public.analytics_sessions s
      ON s.id = c.session_id AND s.web_id = c.web_id
    CROSS JOIN LATERAL (
      SELECT
        coalesce(
          trim(both '/' FROM regexp_replace(
            regexp_replace(
              coalesce(
                nullif(btrim(s.first_landing_url), ''),
                nullif(btrim(s.landing_url), ''),
                nullif(btrim(s.last_landing_url), ''),
                ''
              ),
              '^https?://[^/]+',
              '',
              'i'
            ),
            '[?#].*$',
            ''
          )),
          ''
        ) AS route_path,
        (
          nullif(btrim(s.last_landing_url), '') IS NOT NULL
          OR nullif(btrim(s.landing_url), '') IS NOT NULL
          OR nullif(btrim(s.first_landing_url), '') IS NOT NULL
        ) AS had_landing_ref
    ) lp
    LEFT JOIN pv_day p
      ON p.web_id = c.web_id AND p.session_id = c.session_id AND p.day = c.day
    LEFT JOIN ce_day e
      ON e.web_id = c.web_id AND e.session_id = c.session_id AND e.day = c.day
    LEFT JOIN scroll_day sd
      ON sd.web_id = c.web_id AND sd.session_id = c.session_id AND sd.day = c.day
    WHERE
      c.day BETWEEN p_from AND v_to
      AND c.source_key IN ('utm', 'paid_click_ids')
      AND (
        nullif(btrim(c.utm_source_eff), '') IS NOT NULL
        OR nullif(btrim(c.utm_medium_eff), '') IS NOT NULL
        OR nullif(btrim(c.utm_campaign_eff), '') IS NOT NULL
        OR nullif(btrim(c.utm_content_eff), '') IS NOT NULL
        OR nullif(btrim(c.utm_term_eff), '') IS NOT NULL
      )
  ),
  click_utm_addon AS (
    SELECT
      cc.web_id,
      cc.day,
      coalesce(
        left(
          CASE
            WHEN lp.route_path = '' AND lp.had_landing_ref THEN '/'
            WHEN lp.route_path = '' THEN ''
            WHEN left(lp.route_path, 1) = '/' THEN lp.route_path
            ELSE '/' || lp.route_path
          END,
          512
        ),
        ''
      ) AS route,
      coalesce(cc.utm_source_eff, '') AS utm_source,
      coalesce(cc.utm_medium_eff, '') AS utm_medium,
      coalesce(cc.utm_campaign_eff, '') AS utm_campaign,
      coalesce(cc.utm_content_eff, '') AS utm_content,
      coalesce(cc.utm_term_eff, '') AS utm_term,
      coalesce(p.pv_n, 0)::bigint AS pv_n,
      ed.ce_n::bigint AS ce_n,
      sd.smax AS sess_scroll_max
    FROM click_classified_utm cc
    INNER JOIN ce_day ed
      ON ed.web_id = cc.web_id AND ed.session_id = cc.session_id AND ed.day = cc.day
    LEFT JOIN public.analytics_sessions s
      ON s.id = cc.session_id AND s.web_id = cc.web_id
    CROSS JOIN LATERAL (
      SELECT
        coalesce(
          trim(both '/' FROM regexp_replace(
            regexp_replace(
              coalesce(
                nullif(btrim(s.first_landing_url), ''),
                nullif(btrim(s.landing_url), ''),
                nullif(btrim(s.last_landing_url), ''),
                ''
              ),
              '^https?://[^/]+',
              '',
              'i'
            ),
            '[?#].*$',
            ''
          )),
          ''
        ) AS route_path,
        (
          nullif(btrim(s.last_landing_url), '') IS NOT NULL
          OR nullif(btrim(s.landing_url), '') IS NOT NULL
          OR nullif(btrim(s.first_landing_url), '') IS NOT NULL
        ) AS had_landing_ref
    ) lp
    LEFT JOIN pv_day p
      ON p.web_id = cc.web_id AND p.session_id = cc.session_id AND p.day = cc.day
    LEFT JOIN scroll_day sd
      ON sd.web_id = cc.web_id AND sd.session_id = cc.session_id AND sd.day = cc.day
    WHERE
      cc.day BETWEEN p_from AND v_to
      AND cc.source_key IN ('utm', 'paid_click_ids')
      AND (
        nullif(btrim(cc.utm_source_eff), '') IS NOT NULL
        OR nullif(btrim(cc.utm_medium_eff), '') IS NOT NULL
        OR nullif(btrim(cc.utm_campaign_eff), '') IS NOT NULL
        OR nullif(btrim(cc.utm_content_eff), '') IS NOT NULL
        OR nullif(btrim(cc.utm_term_eff), '') IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM human_sessions hs
        WHERE hs.web_id = cc.web_id AND hs.session_id = cc.session_id AND hs.day = cc.day
      )
  ),
  utm_enriched AS (
    SELECT * FROM utm_enriched_human
    UNION ALL
    SELECT * FROM click_utm_addon
  )
  SELECT
    web_id,
    day,
    route,
    utm_source,
    utm_medium,
    utm_campaign,
    utm_content,
    utm_term,
    count(*)::bigint AS sessions_count,
    sum(pv_n)::bigint AS page_views_count,
    sum(ce_n)::bigint AS clicks_count,
    count(*) FILTER (WHERE sess_scroll_max IS NOT NULL)::bigint AS scroll_sessions_count,
    max(sess_scroll_max)::double precision AS scroll_max_pct_max,
    coalesce(sum(sess_scroll_max) FILTER (WHERE sess_scroll_max IS NOT NULL), 0)::double precision AS scroll_max_pct_sum
  FROM utm_enriched
  GROUP BY web_id, day, route, utm_source, utm_medium, utm_campaign, utm_content, utm_term
  ON CONFLICT (web_id, day, route, utm_source, utm_medium, utm_campaign, utm_content, utm_term)
  DO UPDATE SET
    sessions_count = excluded.sessions_count,
    page_views_count = excluded.page_views_count,
    clicks_count = excluded.clicks_count,
    scroll_sessions_count = excluded.scroll_sessions_count,
    scroll_max_pct_max = excluded.scroll_max_pct_max,
    scroll_max_pct_sum = excluded.scroll_max_pct_sum;
END;
$_$;


ALTER FUNCTION "public"."refresh_analytics_daily_rollups"("p_from" "date", "p_to" "date", "p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."refresh_analytics_daily_rollups"("p_from" "date", "p_to" "date", "p_web_id" "text") IS 'Rebuild analytics_daily_source_breakdown + analytics_daily_utm using first-touch session attribution helpers.';



CREATE OR REPLACE FUNCTION "public"."refresh_analytics_rollups"("p_web_id" "text", "p_from" "date", "p_to" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  d date;
  v_from date;
  v_to date;
  v_min date;
  v_max date;
BEGIN
  IF p_web_id IS NULL OR trim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  SELECT
    LEAST(
      (SELECT MIN((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    ),
    GREATEST(
      (SELECT MAX((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    )
  INTO v_min, v_max;

  IF v_min IS NULL OR v_max IS NULL THEN
    RETURN;
  END IF;

  v_from := COALESCE(p_from, v_min);
  v_to := COALESCE(p_to, v_max);

  IF v_to < v_from THEN
    RAISE EXCEPTION 'invalid range';
  END IF;

  d := v_from;
  WHILE d <= v_to LOOP
    INSERT INTO public.analytics_daily_sessions (
      web_id, day, sessions_count,
      sessions_with_utm_count,
      sessions_with_gclid_count, sessions_with_fbclid_count, sessions_with_msclkid_count
    )
    SELECT
      p_web_id,
      d,
      COUNT(*)::bigint,
      COUNT(*) FILTER (
        WHERE COALESCE(NULLIF(trim(s.utm_source), ''), NULLIF(trim(s.utm_medium), ''), NULLIF(trim(s.utm_campaign), ''), NULLIF(trim(s.utm_content), ''), NULLIF(trim(s.utm_term), '')) IS NOT NULL
      )::bigint,
      COUNT(*) FILTER (WHERE s.has_gclid)::bigint,
      COUNT(*) FILTER (WHERE s.has_fbclid)::bigint,
      COUNT(*) FILTER (WHERE s.has_msclkid)::bigint
    FROM public.analytics_sessions s
    WHERE s.web_id = p_web_id
      AND (timezone('Asia/Jakarta', s.started_at))::date = d
    ON CONFLICT (web_id, day) DO UPDATE SET
      sessions_count = EXCLUDED.sessions_count,
      sessions_with_utm_count = EXCLUDED.sessions_with_utm_count,
      sessions_with_gclid_count = EXCLUDED.sessions_with_gclid_count,
      sessions_with_fbclid_count = EXCLUDED.sessions_with_fbclid_count,
      sessions_with_msclkid_count = EXCLUDED.sessions_with_msclkid_count,
      updated_at = now();

    INSERT INTO public.analytics_daily_page_views (
      web_id, day, page_views_count, active_ms_sum, unique_sessions_count
    )
    SELECT
      p_web_id,
      d,
      COUNT(*)::bigint,
      COALESCE(SUM(pv.active_ms), 0)::bigint,
      COUNT(DISTINCT pv.session_id)::bigint
    FROM public.analytics_page_views pv
    WHERE pv.web_id = p_web_id
      AND (timezone('Asia/Jakarta', pv.started_at))::date = d
    ON CONFLICT (web_id, day) DO UPDATE SET
      page_views_count = EXCLUDED.page_views_count,
      active_ms_sum = EXCLUDED.active_ms_sum,
      unique_sessions_count = EXCLUDED.unique_sessions_count,
      updated_at = now();

    INSERT INTO public.analytics_daily_clicks (
      web_id, day, clicks_count, unique_sessions_count
    )
    SELECT
      p_web_id,
      d,
      COUNT(*)::bigint,
      COUNT(DISTINCT ce.session_id)::bigint
    FROM public.analytics_click_events ce
    WHERE ce.web_id = p_web_id
      AND (timezone('Asia/Jakarta', ce.created_at))::date = d
    ON CONFLICT (web_id, day) DO UPDATE SET
      clicks_count = EXCLUDED.clicks_count,
      unique_sessions_count = EXCLUDED.unique_sessions_count,
      updated_at = now();

    DELETE FROM public.analytics_daily_top_pages
    WHERE web_id = p_web_id AND day = d;

    INSERT INTO public.analytics_daily_top_pages (
      web_id, day, path, page_views_count, active_ms_sum, unique_sessions_count
    )
    SELECT
      p_web_id,
      d,
      pv.path,
      COUNT(*)::bigint,
      COALESCE(SUM(pv.active_ms), 0)::bigint,
      COUNT(DISTINCT pv.session_id)::bigint
    FROM public.analytics_page_views pv
    WHERE pv.web_id = p_web_id
      AND (timezone('Asia/Jakarta', pv.started_at))::date = d
    GROUP BY pv.path;

    -- Histogram waktu aktif per path (untuk median di dashboard)
    WITH
      paths AS (
        SELECT tp.path
        FROM public.analytics_daily_top_pages tp
        WHERE tp.web_id = p_web_id AND tp.day = d
      ),
      buckets AS (
        SELECT generate_series(1, 110) AS idx
      ),
      counts AS (
        SELECT
          pv.path,
          public.active_ms_hist_bucket_idx(pv.active_ms) AS idx,
          COUNT(*)::bigint AS cnt
        FROM public.analytics_page_views pv
        WHERE pv.web_id = p_web_id
          AND (timezone('Asia/Jakarta', pv.started_at))::date = d
        GROUP BY pv.path, public.active_ms_hist_bucket_idx(pv.active_ms)
      ),
      hist AS (
        SELECT
          p.path,
          array_agg(COALESCE(c.cnt, 0) ORDER BY b.idx)::bigint[] AS hist
        FROM paths p
        CROSS JOIN buckets b
        LEFT JOIN counts c
          ON c.path = p.path AND c.idx = b.idx
        GROUP BY p.path
      )
    UPDATE public.analytics_daily_top_pages tp
    SET active_ms_hist = h.hist,
        updated_at = now()
    FROM hist h
    WHERE tp.web_id = p_web_id
      AND tp.day = d
      AND tp.path = h.path;

    -- Scroll per path: satu kontribusi per session per path (max scroll_max_pct) — fair vs UTM/source
    WITH per_session_path AS (
      SELECT
        pv.path,
        pv.session_id,
        MAX(pv.scroll_max_pct)::double precision AS sp_max
      FROM public.analytics_page_views pv
      WHERE pv.web_id = p_web_id
        AND (timezone('Asia/Jakarta', pv.started_at))::date = d
      GROUP BY pv.path, pv.session_id
    ),
    agg AS (
      SELECT
        path,
        COUNT(*) FILTER (WHERE sp_max IS NOT NULL)::bigint AS scroll_sessions_count,
        MAX(sp_max) FILTER (WHERE sp_max IS NOT NULL)::double precision AS scroll_max_pct_max,
        COALESCE(SUM(sp_max) FILTER (WHERE sp_max IS NOT NULL), 0)::double precision AS scroll_max_pct_sum
      FROM per_session_path
      GROUP BY path
    )
    UPDATE public.analytics_daily_top_pages tp
    SET
      scroll_sessions_count = a.scroll_sessions_count,
      scroll_max_pct_max = a.scroll_max_pct_max,
      scroll_max_pct_sum = a.scroll_max_pct_sum,
      updated_at = now()
    FROM agg a
    WHERE tp.web_id = p_web_id
      AND tp.day = d
      AND tp.path = a.path;

    DELETE FROM public.analytics_daily_top_clicks
    WHERE web_id = p_web_id AND day = d;

    INSERT INTO public.analytics_daily_top_clicks (
      web_id, day, path, track_key, element_type, element_label, clicks_count, unique_sessions_count
    )
    SELECT
      p_web_id,
      d,
      ce.path,
      COALESCE(ce.track_key, ''),
      ce.element_type,
      ce.element_label,
      COUNT(*)::bigint,
      COUNT(DISTINCT ce.session_id)::bigint
    FROM public.analytics_click_events ce
    WHERE ce.web_id = p_web_id
      AND (timezone('Asia/Jakarta', ce.created_at))::date = d
    GROUP BY ce.path, COALESCE(ce.track_key, ''), ce.element_type, ce.element_label;

    -- Detail klik per path: agregat target (selaras filter hari WIB dengan top_clicks)
    DELETE FROM public.analytics_daily_top_click_targets
    WHERE web_id = p_web_id AND day = d;

    INSERT INTO public.analytics_daily_top_click_targets (
      web_id, day, path, track_key, element_type, element_label, target_url, is_internal,
      clicks_count, unique_sessions_count
    )
    SELECT
      p_web_id,
      d,
      ce.path,
      COALESCE(ce.track_key, ''),
      ce.element_type,
      ce.element_label,
      COALESCE(ce.target_url, ''),
      COALESCE(ce.is_internal, false),
      COUNT(*)::bigint,
      COUNT(DISTINCT ce.session_id)::bigint
    FROM public.analytics_click_events ce
    WHERE ce.web_id = p_web_id
      AND (timezone('Asia/Jakarta', ce.created_at))::date = d
    GROUP BY
      ce.path,
      COALESCE(ce.track_key, ''),
      ce.element_type,
      ce.element_label,
      COALESCE(ce.target_url, ''),
      COALESCE(ce.is_internal, false);

    DELETE FROM public.analytics_daily_utm
    WHERE web_id = p_web_id AND day = d;

    INSERT INTO public.analytics_daily_utm (
      web_id,
      day,
      route,
      utm_source,
      utm_medium,
      utm_campaign,
      utm_content,
      utm_term,
      sessions_count,
      page_views_count,
      clicks_count,
      scroll_sessions_count,
      scroll_max_pct_max,
      scroll_max_pct_sum
    )
    SELECT
      p_web_id,
      d,
      ud.route_norm,
      ud.utm_source,
      ud.utm_medium,
      ud.utm_campaign,
      ud.utm_content,
      ud.utm_term,
      COUNT(*)::bigint,
      SUM(COALESCE(pv.cnt, 0::bigint))::bigint,
      SUM(COALESCE(ce.cnt, 0::bigint))::bigint,
      COUNT(*) FILTER (WHERE ss.session_max_scroll_pct IS NOT NULL)::bigint,
      MAX(ss.session_max_scroll_pct)::double precision,
      COALESCE(SUM(ss.session_max_scroll_pct), 0)::double precision
    FROM (
      SELECT
        u.session_id,
        COALESCE(
          left(
            CASE
              WHEN u.route_path = '' AND u.had_landing_ref THEN '/'
              WHEN u.route_path = '' THEN ''
              WHEN left(u.route_path, 1) = '/' THEN u.route_path
              ELSE '/' || u.route_path
            END,
            512
          ),
          ''
        ) AS route_norm,
        u.utm_source,
        u.utm_medium,
        u.utm_campaign,
        u.utm_content,
        u.utm_term
      FROM (
        SELECT
          s.id AS session_id,
          COALESCE(
            trim(both '/' FROM regexp_replace(
              regexp_replace(
                COALESCE(NULLIF(trim(s.landing_url), ''), NULLIF(trim(s.first_landing_url), ''), ''),
                '^https?://[^/]+',
                '',
                'i'
              ),
              '[?#].*$',
              ''
            )),
            ''
          ) AS route_path,
          (
            NULLIF(trim(s.landing_url), '') IS NOT NULL
            OR NULLIF(trim(s.first_landing_url), '') IS NOT NULL
          ) AS had_landing_ref,
          COALESCE(NULLIF(trim(s.utm_source), ''), '') AS utm_source,
          COALESCE(NULLIF(trim(s.utm_medium), ''), '') AS utm_medium,
          COALESCE(NULLIF(trim(s.utm_campaign), ''), '') AS utm_campaign,
          COALESCE(NULLIF(trim(s.utm_content), ''), '') AS utm_content,
          COALESCE(NULLIF(trim(s.utm_term), ''), '') AS utm_term
        FROM public.analytics_sessions s
        WHERE s.web_id = p_web_id
          AND (timezone('Asia/Jakarta', s.started_at))::date = d
      ) u
    ) ud
    LEFT JOIN (
      SELECT pv2.session_id, COUNT(*)::bigint AS cnt
      FROM public.analytics_page_views pv2
      WHERE pv2.web_id = p_web_id
        AND (timezone('Asia/Jakarta', pv2.started_at))::date = d
      GROUP BY pv2.session_id
    ) pv ON pv.session_id = ud.session_id
    LEFT JOIN (
      SELECT ce2.session_id, COUNT(*)::bigint AS cnt
      FROM public.analytics_click_events ce2
      WHERE ce2.web_id = p_web_id
        AND (timezone('Asia/Jakarta', ce2.created_at))::date = d
      GROUP BY ce2.session_id
    ) ce ON ce.session_id = ud.session_id
    LEFT JOIN (
      SELECT
        pv3.session_id,
        MAX(pv3.scroll_max_pct)::double precision AS session_max_scroll_pct
      FROM public.analytics_page_views pv3
      WHERE pv3.web_id = p_web_id
        AND (timezone('Asia/Jakarta', pv3.started_at))::date = d
        AND pv3.scroll_max_pct IS NOT NULL
      GROUP BY pv3.session_id
    ) ss ON ss.session_id = ud.session_id
    GROUP BY
      ud.route_norm,
      ud.utm_source,
      ud.utm_medium,
      ud.utm_campaign,
      ud.utm_content,
      ud.utm_term;

    -- ----------------------------------------------------------------------
    -- Source breakdown rollup (event-day attribution in WIB)
    -- ----------------------------------------------------------------------
    WITH
      src_keys AS (
        SELECT * FROM (VALUES ('utm'::text), ('paid_click_ids'::text), ('referral'::text), ('direct'::text)) v(source_key)
      ),
      sessions_agg AS (
        SELECT
          CASE
            WHEN COALESCE(
              NULLIF(trim(s.utm_source), ''),
              NULLIF(trim(s.utm_medium), ''),
              NULLIF(trim(s.utm_campaign), ''),
              NULLIF(trim(s.utm_content), ''),
              NULLIF(trim(s.utm_term), '')
            ) IS NOT NULL THEN 'utm'
            WHEN COALESCE(s.has_gclid, false)
              OR COALESCE(s.has_fbclid, false)
              OR COALESCE(s.has_msclkid, false)
              OR COALESCE(s.has_gbraid, false)
              OR COALESCE(s.has_wbraid, false) THEN 'paid_click_ids'
            WHEN NULLIF(trim(COALESCE(s.referrer, s.first_referrer, '')), '') IS NOT NULL THEN 'referral'
            ELSE 'direct'
          END AS source_key,
          COUNT(*)::bigint AS sessions_count
        FROM public.analytics_sessions s
        WHERE s.web_id = p_web_id
          AND (timezone('Asia/Jakarta', s.started_at))::date = d
        GROUP BY 1
      ),
      page_views_agg AS (
        SELECT
          CASE
            WHEN COALESCE(
              NULLIF(trim(s.utm_source), ''),
              NULLIF(trim(s.utm_medium), ''),
              NULLIF(trim(s.utm_campaign), ''),
              NULLIF(trim(s.utm_content), ''),
              NULLIF(trim(s.utm_term), '')
            ) IS NOT NULL THEN 'utm'
            WHEN COALESCE(s.has_gclid, false)
              OR COALESCE(s.has_fbclid, false)
              OR COALESCE(s.has_msclkid, false)
              OR COALESCE(s.has_gbraid, false)
              OR COALESCE(s.has_wbraid, false) THEN 'paid_click_ids'
            WHEN NULLIF(trim(COALESCE(s.referrer, s.first_referrer, '')), '') IS NOT NULL THEN 'referral'
            ELSE 'direct'
          END AS source_key,
          COUNT(*)::bigint AS page_views_count
        FROM public.analytics_page_views pv
        JOIN public.analytics_sessions s
          ON s.id = pv.session_id AND s.web_id = pv.web_id
        WHERE pv.web_id = p_web_id
          AND (timezone('Asia/Jakarta', pv.started_at))::date = d
        GROUP BY 1
      ),
      clicks_agg AS (
        SELECT
          CASE
            WHEN COALESCE(
              NULLIF(trim(s.utm_source), ''),
              NULLIF(trim(s.utm_medium), ''),
              NULLIF(trim(s.utm_campaign), ''),
              NULLIF(trim(s.utm_content), ''),
              NULLIF(trim(s.utm_term), '')
            ) IS NOT NULL THEN 'utm'
            WHEN COALESCE(s.has_gclid, false)
              OR COALESCE(s.has_fbclid, false)
              OR COALESCE(s.has_msclkid, false)
              OR COALESCE(s.has_gbraid, false)
              OR COALESCE(s.has_wbraid, false) THEN 'paid_click_ids'
            WHEN NULLIF(trim(COALESCE(s.referrer, s.first_referrer, '')), '') IS NOT NULL THEN 'referral'
            ELSE 'direct'
          END AS source_key,
          COUNT(*)::bigint AS clicks_count
        FROM public.analytics_click_events ce
        JOIN public.analytics_sessions s
          ON s.id = ce.session_id AND s.web_id = ce.web_id
        WHERE ce.web_id = p_web_id
          AND (timezone('Asia/Jakarta', ce.created_at))::date = d
        GROUP BY 1
      ),
      scroll_sessions AS (
        SELECT
          pv.session_id,
          MAX(pv.scroll_max_pct)::double precision AS session_max_scroll_pct
        FROM public.analytics_page_views pv
        WHERE pv.web_id = p_web_id
          AND (timezone('Asia/Jakarta', pv.started_at))::date = d
          AND pv.scroll_max_pct IS NOT NULL
        GROUP BY pv.session_id
      ),
      scroll_agg AS (
        SELECT
          CASE
            WHEN COALESCE(
              NULLIF(trim(s.utm_source), ''),
              NULLIF(trim(s.utm_medium), ''),
              NULLIF(trim(s.utm_campaign), ''),
              NULLIF(trim(s.utm_content), ''),
              NULLIF(trim(s.utm_term), '')
            ) IS NOT NULL THEN 'utm'
            WHEN COALESCE(s.has_gclid, false)
              OR COALESCE(s.has_fbclid, false)
              OR COALESCE(s.has_msclkid, false)
              OR COALESCE(s.has_gbraid, false)
              OR COALESCE(s.has_wbraid, false) THEN 'paid_click_ids'
            WHEN NULLIF(trim(COALESCE(s.referrer, s.first_referrer, '')), '') IS NOT NULL THEN 'referral'
            ELSE 'direct'
          END AS source_key,
          COUNT(*)::bigint AS scroll_sessions_count,
          MAX(ss.session_max_scroll_pct)::double precision AS scroll_max_pct_max,
          COALESCE(SUM(ss.session_max_scroll_pct), 0)::double precision AS scroll_max_pct_sum
        FROM scroll_sessions ss
        JOIN public.analytics_sessions s
          ON s.id = ss.session_id AND s.web_id = p_web_id
        GROUP BY 1
      )
    INSERT INTO public.analytics_daily_source_breakdown (
      web_id,
      day,
      source_key,
      sessions_count,
      page_views_count,
      clicks_count,
      scroll_sessions_count,
      scroll_max_pct_max,
      scroll_max_pct_sum
    )
    SELECT
      p_web_id,
      d,
      k.source_key,
      COALESCE(sa.sessions_count, 0),
      COALESCE(pva.page_views_count, 0),
      COALESCE(ca.clicks_count, 0),
      COALESCE(sca.scroll_sessions_count, 0),
      sca.scroll_max_pct_max,
      COALESCE(sca.scroll_max_pct_sum, 0)
    FROM src_keys k
    LEFT JOIN sessions_agg sa ON sa.source_key = k.source_key
    LEFT JOIN page_views_agg pva ON pva.source_key = k.source_key
    LEFT JOIN clicks_agg ca ON ca.source_key = k.source_key
    LEFT JOIN scroll_agg sca ON sca.source_key = k.source_key
    ON CONFLICT (web_id, day, source_key) DO UPDATE SET
      sessions_count = EXCLUDED.sessions_count,
      page_views_count = EXCLUDED.page_views_count,
      clicks_count = EXCLUDED.clicks_count,
      scroll_sessions_count = EXCLUDED.scroll_sessions_count,
      scroll_max_pct_max = EXCLUDED.scroll_max_pct_max,
      scroll_max_pct_sum = EXCLUDED.scroll_max_pct_sum,
      updated_at = now();

    d := d + 1;
  END LOOP;
END;
$_$;


ALTER FUNCTION "public"."refresh_analytics_rollups"("p_web_id" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_budget_allocation_payout"("p_campaign_id" "uuid", "p_kol_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_paid_milestones numeric(15, 2);
  v_total_milestones int;
  v_paid_count int;
  v_completion_rate numeric(5, 2);
  v_bonus numeric(15, 2);
BEGIN
  IF p_campaign_id IS NULL OR p_kol_profile_id IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(SUM(pm.amount) FILTER (WHERE pm.status = 'paid'), 0),
    COUNT(pm.id),
    COUNT(pm.id) FILTER (WHERE pm.status = 'paid')
  INTO v_paid_milestones, v_total_milestones, v_paid_count
  FROM public.kol_payment_terms kpt
  JOIN public.payment_milestones pm ON pm.payment_terms_id = kpt.id
  WHERE kpt.campaign_id = p_campaign_id
    AND kpt.kol_profile_id = p_kol_profile_id
    AND kpt.type = 'agreement';

  SELECT COALESCE(SUM(kpt.bonus_amount), 0)
  INTO v_bonus
  FROM public.kol_payment_terms kpt
  WHERE kpt.campaign_id = p_campaign_id
    AND kpt.kol_profile_id = p_kol_profile_id
    AND kpt.type = 'agreement'
    AND kpt.status IN ('paid', 'partial_paid', 'dp_paid');

  v_completion_rate := CASE
    WHEN v_total_milestones > 0 THEN (v_paid_count::numeric / v_total_milestones::numeric) * 100
    ELSE 0
  END;

  UPDATE public.kol_campaign_budget_allocations
  SET
    actual_payout = v_paid_milestones + v_bonus,
    milestone_completion_rate = v_completion_rate,
    updated_at = timezone('utc'::text, now())
  WHERE campaign_id = p_campaign_id
    AND kol_profile_id = p_kol_profile_id;
END;
$$;


ALTER FUNCTION "public"."refresh_budget_allocation_payout"("p_campaign_id" "uuid", "p_kol_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_organization_has_active_subscription"("p_org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ok boolean;
BEGIN
  IF p_org_id IS NULL THEN
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.organization_subscriptions s
    WHERE s.organization_id = p_org_id
      AND (
        (
          s.status = 'trial'
          AND s.is_trial = true
          AND (s.trial_end_date IS NULL OR s.trial_end_date > now())
        )
        OR (
          s.status = 'active'
          AND (s.subscription_end_date IS NULL OR s.subscription_end_date > now())
        )
      )
  )
  INTO v_ok;

  UPDATE public.organizations o
  SET has_active_subscription = COALESCE(v_ok, false)
  WHERE o.id = p_org_id;
END;
$$;


ALTER FUNCTION "public"."refresh_organization_has_active_subscription"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registration_has_verified_email"("p_user_id" "uuid", "p_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
DECLARE
  v_ok boolean;
  v_has_google boolean;
BEGIN
  IF p_user_id IS NULL OR p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM auth.users u
    INNER JOIN public.email_verification_tokens t ON t.user_id = u.id
    WHERE u.id = p_user_id
      AND lower(trim(u.email)) = lower(trim(p_email))
      AND t.email_verified = true
  )
  INTO v_ok;

  IF COALESCE(v_ok, false) THEN
    RETURN true;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM auth.identities i
    INNER JOIN auth.users u ON u.id = i.user_id
    WHERE i.user_id = p_user_id
      AND lower(trim(u.email)) = lower(trim(p_email))
      AND i.provider = 'google'
  )
  INTO v_has_google;

  IF COALESCE(v_has_google, false) THEN
    RETURN true;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION "public"."registration_has_verified_email"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registration_verify_email_page_allowed"("p_user_id" "uuid", "p_email" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'auth', 'public'
    AS $$
BEGIN
  IF p_user_id IS NULL OR p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN false;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM auth.users u
    WHERE u.id = p_user_id
      AND lower(trim(u.email)) = lower(trim(p_email))
  ) THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.email_verification_tokens t
    WHERE t.user_id = p_user_id
      AND t.email_verified = false
      AND t.used_at IS NULL
  );
END;
$$;


ALTER FUNCTION "public"."registration_verify_email_page_allowed"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_bank_mutation_match"("p_match_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_match public.bank_mutation_matches%ROWTYPE;
BEGIN
  SELECT * INTO v_match
  FROM public.bank_mutation_matches
  WHERE id = p_match_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_mutation_match_not_found';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_match.organization_id) THEN
    RAISE EXCEPTION 'bank_mutation_match_forbidden';
  END IF;

  IF v_match.status <> 'suggested' THEN
    RAISE EXCEPTION 'bank_mutation_match_not_suggested';
  END IF;

  UPDATE public.bank_mutation_matches
  SET status = 'rejected', updated_at = now()
  WHERE id = v_match.id;

  RETURN jsonb_build_object('ok', true, 'match_id', v_match.id);
END;
$$;


ALTER FUNCTION "public"."reject_bank_mutation_match"("p_match_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_recipe_draft"("p_draft_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  d public.catalog_recipe_drafts%ROWTYPE;
  v_user uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
BEGIN
  SELECT * INTO d FROM public.catalog_recipe_drafts WHERE id = p_draft_id FOR UPDATE;
  IF NOT FOUND OR NOT public._recipe_is_member(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public._recipe_is_manager(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF d.status <> 'pending' THEN
    RAISE EXCEPTION 'recipe_draft_not_pending' USING ERRCODE = '22023';
  END IF;
  IF v_note IS NOT NULL AND char_length(v_note) > 500 THEN
    RAISE EXCEPTION 'invalid_input' USING ERRCODE = '22023';
  END IF;

  UPDATE public.catalog_recipe_drafts
  SET status = 'rejected', decided_by = v_user, decided_at = now(), decision_note = v_note, updated_at = now()
  WHERE id = d.id;

  RETURN public._recipe_draft_review(d.id, v_user);
END;
$$;


ALTER FUNCTION "public"."reject_recipe_draft"("p_draft_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb" DEFAULT NULL::"jsonb", "p_release_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line jsonb;
  v_product uuid;
  v_variant uuid;
  v_variant_key uuid;
  v_qty numeric;
  v_release text;
  v_ref text;
  v_outlet uuid;
  v_rec record;
  v_null_variant constant uuid := '00000000-0000-0000-0000-000000000000'::uuid;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;

  v_outlet := p_outlet_id;
  IF v_outlet IS NULL AND p_session_id IS NOT NULL THEN
    SELECT outlet_id INTO v_outlet
    FROM public.pos_table_sessions
    WHERE id = p_session_id AND organization_id = p_organization_id;
  END IF;

  v_release := COALESCE(NULLIF(btrim(p_release_id), ''), gen_random_uuid()::text);
  v_ref := COALESCE(p_session_id::text, v_release) || ':release:' || v_release;

  IF p_lines IS NULL OR jsonb_array_length(COALESCE(p_lines, '[]'::jsonb)) = 0 THEN
    IF p_session_id IS NULL THEN
      RETURN jsonb_build_object('ok', true, 'released', 0);
    END IF;

    FOR v_rec IN
      SELECT product_id, variant_id, reserved_qty
      FROM public.pos_session_stock_reserves
      WHERE session_id = p_session_id
        AND organization_id = p_organization_id
        AND reserved_qty > 0
      FOR UPDATE
    LOOP
      IF v_rec.variant_id IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'::uuid THEN
        UPDATE public.catalog_product_variant_outlets
        SET reserved_qty = GREATEST(0, reserved_qty - v_rec.reserved_qty)
        WHERE variant_id = v_rec.variant_id AND outlet_id = v_outlet;
      ELSE
        UPDATE public.catalog_product_outlets
        SET reserved_qty = GREATEST(0, reserved_qty - v_rec.reserved_qty)
        WHERE product_id = v_rec.product_id AND outlet_id = v_outlet;
      END IF;

      PERFORM public.apply_catalog_stock_movement(
        p_organization_id,
        v_outlet,
        'product',
        v_rec.product_id,
        CASE
          WHEN v_rec.variant_id = '00000000-0000-0000-0000-000000000000'::uuid THEN NULL
          ELSE v_rec.variant_id
        END,
        NULL,
        'release',
        0,
        'pos_stock_reserve',
        v_ref || ':' || v_rec.product_id::text || ':full',
        'Stock reserve release full session'
      );
    END LOOP;

    UPDATE public.pos_session_stock_reserves
    SET reserved_qty = 0, updated_at = now()
    WHERE session_id = p_session_id AND organization_id = p_organization_id;

    RETURN jsonb_build_object('ok', true, 'release_id', v_release, 'full_session', true);
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_product := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_variant := NULLIF(v_line ->> 'variant_id', '')::uuid;
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    IF v_product IS NULL OR v_qty <= 0 THEN
      CONTINUE;
    END IF;

    IF v_variant IS NOT NULL THEN
      UPDATE public.catalog_product_variant_outlets
      SET reserved_qty = GREATEST(0, reserved_qty - v_qty)
      WHERE variant_id = v_variant AND outlet_id = v_outlet;
    ELSE
      UPDATE public.catalog_product_outlets
      SET reserved_qty = GREATEST(0, reserved_qty - v_qty)
      WHERE product_id = v_product AND outlet_id = v_outlet;
    END IF;

    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      v_outlet,
      'product',
      v_product,
      v_variant,
      NULL,
      'release',
      0,
      'pos_stock_reserve',
      v_ref || ':' || v_product::text,
      'Stock reserve release'
    );

    v_variant_key := COALESCE(v_variant, v_null_variant);

    UPDATE public.pos_session_stock_reserves
    SET
      reserved_qty = GREATEST(0, reserved_qty - v_qty),
      updated_at = now()
    WHERE session_id = p_session_id
      AND product_id = v_product
      AND variant_id = v_variant_key;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'release_id', v_release);
END;
$$;


ALTER FUNCTION "public"."release_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_release_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_catalog_stock_reserve"("p_organization_id" "uuid", "p_outlet_id" "uuid", "p_session_id" "uuid", "p_lines" "jsonb", "p_release_id" "text") IS 'Release reserved stock. p_lines NULL releases full session ledger.';



CREATE OR REPLACE FUNCTION "public"."reply_pos_receipt_feedback"("p_feedback_id" "uuid", "p_reply_text" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.pos_receipt_feedback_responses%ROWTYPE;
  v_reply text := nullif(trim(coalesce(p_reply_text, '')), '');
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF v_reply IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'reply_required');
  END IF;

  SELECT r.* INTO v_row
  FROM public.pos_receipt_feedback_responses r
  WHERE r.id = p_feedback_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = auth.uid()
      AND p.active_organization_id = v_row.organization_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.pos_receipt_feedback_responses
  SET
    reply_text = v_reply,
    replied_by = auth.uid(),
    replied_at = now()
  WHERE id = p_feedback_id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_row.id,
    'reply_text', v_row.reply_text,
    'replied_at', v_row.replied_at
  );
END;
$$;


ALTER FUNCTION "public"."reply_pos_receipt_feedback"("p_feedback_id" "uuid", "p_reply_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resign_employee"("p_employee_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  uid uuid := auth.uid();
  emp public.employees%ROWTYPE;
  org_owner uuid;
  terminated_status uuid;
  next_org uuid;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT * INTO emp
  FROM public.employees
  WHERE id = p_employee_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Employee not found or not in your organization.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = uid
      AND ur.organization_id = emp.organization_id
      AND lower(ur.role) IN ('owner', 'admin', 'hr')
  ) THEN
    RAISE EXCEPTION 'You do not have permission to resign this employee.';
  END IF;

  IF emp.user_id IS NOT NULL AND emp.user_id = uid THEN
    RAISE EXCEPTION 'You cannot resign yourself. Please contact another admin or the organization owner.';
  END IF;

  SELECT o.user_id INTO org_owner
  FROM public.organizations o
  WHERE o.id = emp.organization_id;

  IF org_owner IS NOT NULL AND emp.user_id = org_owner THEN
    RAISE EXCEPTION 'Organization owners cannot be resigned. Transfer ownership first.';
  END IF;

  UPDATE public.employees owner_row
  SET manager_id = NULL
  WHERE owner_row.organization_id = emp.organization_id
    AND owner_row.manager_id = emp.id
    AND org_owner IS NOT NULL
    AND owner_row.user_id = org_owner;

  IF EXISTS (
    SELECT 1
    FROM public.employees report
    WHERE report.organization_id = emp.organization_id
      AND report.manager_id = emp.id
  ) THEN
    RAISE EXCEPTION 'Reassign direct reports to another manager first.';
  END IF;

  SELECT es.id INTO terminated_status
  FROM public.employee_statuses es
  WHERE lower(es.name) = 'terminated'
  ORDER BY es.organization_id NULLS FIRST
  LIMIT 1;

  UPDATE public.employees e
  SET employee_status_id = COALESCE(terminated_status, e.employee_status_id),
      status = 'inactive',
      pending_removal = false,
      pending_removal_reason = NULL,
      pending_removal_date = NULL,
      updated_at = now()
  WHERE e.id = emp.id;

  IF emp.user_id IS NOT NULL THEN
    DELETE FROM public.user_roles ur
    WHERE ur.user_id = emp.user_id
      AND ur.organization_id = emp.organization_id;

    DELETE FROM public.user_organizations uo
    WHERE uo.user_id = emp.user_id
      AND uo.organization_id = emp.organization_id;

    SELECT uo.organization_id INTO next_org
    FROM public.user_organizations uo
    JOIN public.organizations o ON o.id = uo.organization_id
    WHERE uo.user_id = emp.user_id
      AND COALESCE(uo.is_active, true) = true
    ORDER BY (o.user_id = emp.user_id) DESC, uo.organization_id
    LIMIT 1;

    UPDATE public.profiles p
    SET active_organization_id = next_org
    WHERE p.user_id = emp.user_id
      AND p.active_organization_id = emp.organization_id;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'message', emp.full_name || ' has been resigned from this organization'
  );
END;
$$;


ALTER FUNCTION "public"."resign_employee"("p_employee_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_assignment_due_date"("p_entity_type" "text", "p_assignment_row_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT d.due_date
  FROM public.task_steps_assigned_duedate d
  WHERE (
    (p_entity_type = 'task' AND d.daily_tasks_assigned_id = p_assignment_row_id)
    OR (p_entity_type = 'step' AND d.task_steps_assigned_id = p_assignment_row_id)
    OR (p_entity_type = 'substep' AND d.task_steps_to_steps_assigned_id = p_assignment_row_id)
  )
  ORDER BY d.created_at DESC
  LIMIT 1
$$;


ALTER FUNCTION "public"."resolve_assignment_due_date"("p_entity_type" "text", "p_assignment_row_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_attendance_late_for_day"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_date" "date", "p_local_checkin" timestamp without time zone, "p_client_visit_id" "uuid" DEFAULT NULL::"uuid", "p_is_spontaneous" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mode jsonb;
  v_mode_text text;
  v_sched record;
  v_visit public.client_visits%ROWTYPE;
  v_ref_mins integer;
  v_checkin_mins integer;
  v_tolerance integer;
  v_late boolean := false;
  v_late_mins integer := 0;
  v_ref_time time;
BEGIN
  v_mode := public.resolve_visit_day_mode(
    p_employee_id,
    p_organization_id,
    p_date,
    NULL,
    p_is_spontaneous
  );
  v_mode_text := v_mode->>'mode';

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(p_employee_id, p_organization_id, p_date) r
  LIMIT 1;

  v_tolerance := COALESCE(v_sched.late_tolerance_minutes, 0);
  v_checkin_mins :=
    EXTRACT(HOUR FROM p_local_checkin)::integer * 60
    + EXTRACT(MINUTE FROM p_local_checkin)::integer;

  IF v_mode_text IN ('field_first', 'travel_field') OR p_is_spontaneous THEN
    IF p_client_visit_id IS NOT NULL THEN
      SELECT * INTO v_visit FROM public.client_visits cv WHERE cv.id = p_client_visit_id;
    ELSIF (v_mode->>'primary_visit_id') IS NOT NULL THEN
      SELECT * INTO v_visit FROM public.client_visits cv WHERE cv.id = (v_mode->>'primary_visit_id')::uuid;
    END IF;

    IF p_is_spontaneous OR v_visit.planned_start_time IS NULL THEN
      v_ref_mins := v_checkin_mins;
      v_ref_time := p_local_checkin::time;
      v_late := false;
      v_late_mins := 0;
    ELSE
      v_ref_mins :=
        EXTRACT(HOUR FROM v_visit.planned_start_time)::integer * 60
        + EXTRACT(MINUTE FROM v_visit.planned_start_time)::integer;
      v_ref_time := v_visit.planned_start_time;
      IF v_checkin_mins > v_ref_mins + v_tolerance THEN
        v_late := true;
        v_late_mins := GREATEST(0, v_checkin_mins - v_ref_mins);
      END IF;
    END IF;
  ELSE
    v_ref_mins := public._time_text_to_minutes(v_sched.start_time);
    v_ref_time := v_sched.start_time::time;
    IF v_checkin_mins > v_ref_mins + v_tolerance THEN
      v_late := true;
      v_late_mins := GREATEST(0, v_checkin_mins - v_ref_mins);
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'is_late', v_late,
    'late_minutes', v_late_mins,
    'late_reference_time', v_ref_time,
    'visit_day_mode', v_mode_text,
    'late_tolerance_minutes', v_tolerance
  );
END;
$$;


ALTER FUNCTION "public"."resolve_attendance_late_for_day"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_date" "date", "p_local_checkin" timestamp without time zone, "p_client_visit_id" "uuid", "p_is_spontaneous" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_brick_disbursement_source_bank_account_id"("p_organization_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bank_id uuid;
BEGIN
  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = p_organization_id
    AND ba.is_active = true
    AND ba.brick_link_status = 'linked'
    AND ba.use_for_omnichannel_income = true
  ORDER BY ba.created_at ASC
  LIMIT 1;

  IF v_bank_id IS NOT NULL THEN
    RETURN v_bank_id;
  END IF;

  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = p_organization_id
    AND ba.is_active = true
    AND ba.brick_link_status = 'linked'
  ORDER BY ba.created_at ASC
  LIMIT 1;

  RETURN v_bank_id;
END;
$$;


ALTER FUNCTION "public"."resolve_brick_disbursement_source_bank_account_id"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_brick_va_bank_account_id"("p_organization_id" "uuid", "p_bank_short_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_bank_id uuid;
  v_code text := upper(trim(p_bank_short_code));
BEGIN
  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = p_organization_id
    AND ba.is_active = true
    AND ba.brick_link_status = 'linked'
    AND (
      upper(ba.bank_name) LIKE '%' || replace(v_code, 'MANDIRI', 'MANDIRI') || '%'
      OR (v_code = 'MANDIRI' AND upper(ba.bank_name) LIKE '%MANDIRI%')
      OR (v_code = 'BRI' AND upper(ba.bank_name) LIKE '%BRI%')
      OR (v_code = 'BCA' AND upper(ba.bank_name) LIKE '%BCA%')
    )
  ORDER BY ba.use_for_omnichannel_income DESC, ba.created_at ASC
  LIMIT 1;

  IF v_bank_id IS NOT NULL THEN
    RETURN v_bank_id;
  END IF;

  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = p_organization_id
    AND ba.use_for_omnichannel_income = true
    AND ba.is_active = true
  ORDER BY ba.created_at ASC
  LIMIT 1;

  IF v_bank_id IS NOT NULL THEN
    RETURN v_bank_id;
  END IF;

  SELECT ba.id INTO v_bank_id
  FROM public.bank_accounts ba
  WHERE ba.organization_id = p_organization_id
    AND ba.is_active = true
  ORDER BY ba.created_at ASC
  LIMIT 1;

  RETURN v_bank_id;
END;
$$;


ALTER FUNCTION "public"."resolve_brick_va_bank_account_id"("p_organization_id" "uuid", "p_bank_short_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_canonical_web_id"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select case
    when p_raw is null or btrim(p_raw) = '' then null
    else coalesce(
      (select a.canonical_slug
       from public.property_web_id_aliases a
       where a.alias = lower(btrim(p_raw))),
      (select p.slug
       from public.properties p
       where p.slug = lower(btrim(p_raw)))
    )
  end;
$$;


ALTER FUNCTION "public"."resolve_canonical_web_id"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_daily_task_entity_title"("p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  t text;
BEGIN
  IF p_entity_type = 'task' THEN
    SELECT COALESCE(NULLIF(trim(dt.title), ''), 'Daily Task') INTO t
    FROM public.daily_tasks dt
    WHERE dt.id = p_daily_task_id
    LIMIT 1;
    RETURN COALESCE(t, 'Daily Task');
  ELSIF p_entity_type = 'step' THEN
    SELECT COALESCE(NULLIF(trim(ts.title), ''), 'Task Step') INTO t
    FROM public.task_steps ts
    WHERE ts.id = p_task_step_id
    LIMIT 1;
    RETURN COALESCE(t, 'Task Step');
  ELSE
    SELECT COALESCE(NULLIF(trim(ss.title), ''), 'Sub-step') INTO t
    FROM public.task_steps_to_steps ss
    WHERE ss.id = p_task_steps_to_steps_id
    LIMIT 1;
    RETURN COALESCE(t, 'Sub-step');
  END IF;
END;
$$;


ALTER FUNCTION "public"."resolve_daily_task_entity_title"("p_entity_type" "text", "p_daily_task_id" "uuid", "p_task_step_id" "uuid", "p_task_steps_to_steps_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_effective_schedule"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_effective_date" "date") RETURNS TABLE("source" "text", "shift_id" "uuid", "employee_shift_id" "uuid", "work_schedule_id" "uuid", "schedule_name" "text", "start_time" "text", "end_time" "text", "late_tolerance_minutes" integer, "overtime_threshold_minutes" integer, "break_duration_minutes" integer, "timezone" "text", "working_days" integer[], "is_working_day" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ BEGIN 
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
 RETURN QUERY SELECT * FROM public.resolve_effective_schedule__impl(p_employee_id, p_organization_id, p_effective_date); END; $$;


ALTER FUNCTION "public"."resolve_effective_schedule"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_effective_schedule__impl"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_effective_date" "date") RETURNS TABLE("source" "text", "shift_id" "uuid", "employee_shift_id" "uuid", "work_schedule_id" "uuid", "schedule_name" "text", "start_time" "text", "end_time" "text", "late_tolerance_minutes" integer, "overtime_threshold_minutes" integer, "break_duration_minutes" integer, "timezone" "text", "working_days" integer[], "is_working_day" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_wss public.work_schedule_settings%ROWTYPE;
  v_emp_wss_id uuid;
  v_es_id uuid;
  v_shift_id uuid;
  v_shift_name text;
  v_shift_start text;
  v_shift_end text;
  v_shift_late_tol integer;
  v_shift_break integer;
  v_working_days integer[];
  v_app_dow integer;
  v_is_working boolean;
BEGIN
  SELECT e.work_schedule_id
  INTO v_emp_wss_id
  FROM public.employees e
  WHERE e.id = p_employee_id
    AND e.organization_id = p_organization_id;

  IF v_emp_wss_id IS NOT NULL THEN
    SELECT wss.*
    INTO v_wss
    FROM public.work_schedule_settings wss
    WHERE wss.id = v_emp_wss_id
      AND wss.organization_id = p_organization_id
      AND COALESCE(wss.is_active, true);
  END IF;

  IF v_wss.id IS NULL THEN
    SELECT wss.*
    INTO v_wss
    FROM public.work_schedule_settings wss
    WHERE wss.organization_id = p_organization_id
      AND COALESCE(wss.is_active, true)
    ORDER BY wss.is_default DESC NULLS LAST, wss.created_at ASC
    LIMIT 1;
  END IF;

  v_working_days := COALESCE(v_wss.working_days, ARRAY[1, 2, 3, 4, 5]);
  v_app_dow := public.pg_dow_to_app_dow(EXTRACT(DOW FROM p_effective_date)::integer);
  v_is_working := v_working_days IS NOT NULL AND v_app_dow = ANY (v_working_days);

  SELECT es.id, es.shift_id, s.name, s.start_time, s.end_time, s.late_tolerance_minutes, s.break_duration_minutes
  INTO v_es_id, v_shift_id, v_shift_name, v_shift_start, v_shift_end, v_shift_late_tol, v_shift_break
  FROM public.employee_shifts es
  INNER JOIN public.shifts s ON s.id = es.shift_id
  WHERE es.employee_id = p_employee_id
    AND es.organization_id = p_organization_id
    AND COALESCE(es.is_active, true)
    AND es.effective_from_date <= p_effective_date
    AND (es.effective_to_date IS NULL OR es.effective_to_date >= p_effective_date)
    AND COALESCE(s.is_active, true)
  ORDER BY es.effective_from_date DESC
  LIMIT 1;

  IF v_shift_id IS NOT NULL THEN
    RETURN QUERY
    SELECT
      'shift'::text,
      v_shift_id,
      v_es_id,
      v_wss.id,
      COALESCE(v_shift_name, 'Shift'),
      COALESCE(v_shift_start, '08:00'),
      COALESCE(v_shift_end, '17:00'),
      COALESCE(v_shift_late_tol, v_wss.late_tolerance_minutes, 0),
      COALESCE(v_wss.overtime_threshold_minutes, 0),
      COALESCE(v_shift_break, 0),
      COALESCE(v_wss.timezone, 'Asia/Jakarta'),
      v_working_days,
      v_is_working;
    RETURN;
  END IF;

  IF v_wss.id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    'work_schedule'::text,
    NULL::uuid,
    NULL::uuid,
    v_wss.id,
    COALESCE(v_wss.name, 'Jadwal Kerja'),
    COALESCE(v_wss.start_time, '09:00'),
    COALESCE(v_wss.end_time, '17:00'),
    COALESCE(v_wss.late_tolerance_minutes, 0),
    COALESCE(v_wss.overtime_threshold_minutes, 0),
    0,
    COALESCE(v_wss.timezone, 'Asia/Jakarta'),
    v_working_days,
    v_is_working;
END;
$$;


ALTER FUNCTION "public"."resolve_effective_schedule__impl"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_form_id_for_omnichannel_submission"("p_organization_id" "uuid", "p_web_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND p_organization_id IS NOT NULL
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN public.resolve_form_id_for_omnichannel_submission__impl(p_organization_id, p_web_id);
END;
$$;


ALTER FUNCTION "public"."resolve_form_id_for_omnichannel_submission"("p_organization_id" "uuid", "p_web_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_form_id_for_omnichannel_submission__impl"("p_organization_id" "uuid", "p_web_id" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_form_id uuid;
  v_web text := nullif(btrim(coalesce(p_web_id, '')), '');
BEGIN
  IF p_organization_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_web IS NOT NULL THEN
    SELECT s.form_id
    INTO v_form_id
    FROM public.lead_submissions s
    WHERE s.organization_id = p_organization_id
      AND s.form_id IS NOT NULL
      AND s.web_id = v_web
    ORDER BY s.updated_at DESC NULLS LAST
    LIMIT 1;

    IF v_form_id IS NOT NULL THEN
      RETURN v_form_id;
    END IF;
  END IF;

  SELECT s.form_id
  INTO v_form_id
  FROM public.lead_submissions s
  WHERE s.organization_id = p_organization_id
    AND s.form_id IS NOT NULL
  ORDER BY s.updated_at DESC NULLS LAST
  LIMIT 1;

  IF v_form_id IS NOT NULL THEN
    RETURN v_form_id;
  END IF;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."resolve_form_id_for_omnichannel_submission__impl"("p_organization_id" "uuid", "p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_form_id_for_omnichannel_submission__impl"("p_organization_id" "uuid", "p_web_id" "text") IS 'Returns a reusable form_id when the org has website-form submissions; NULL for WA-only orgs.';



CREATE OR REPLACE FUNCTION "public"."resolve_inventory_po_expense_classification"("p_organization_id" "uuid", "p_item_kind" "text") RETURNS TABLE("expense_type_id" "uuid", "expense_category_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_type_id uuid;
  v_cat_id uuid;
  v_cat_name text;
BEGIN
  v_cat_name := CASE WHEN p_item_kind = 'product' THEN 'Item Library' ELSE 'Ingredients' END;

  SELECT et.id
    INTO v_type_id
  FROM public.expense_types et
  WHERE et.is_active IS TRUE
    AND lower(btrim(et.name)) <> 'internal bank transfer'
    AND (
      lower(et.name) LIKE '%cogs%'
      OR lower(et.name) LIKE '%harga pokok%'
      OR lower(et.name) LIKE '%inventory%'
      OR lower(et.name) LIKE '%bahan baku%'
    )
    AND (et.organization_id = p_organization_id OR et.organization_id IS NULL)
  ORDER BY
    CASE WHEN et.organization_id = p_organization_id THEN 0 ELSE 1 END,
    et.created_at NULLS LAST
  LIMIT 1;

  IF v_type_id IS NULL THEN
    INSERT INTO public.expense_types (
      name, description, organization_id, is_active, is_default
    ) VALUES (
      'COGS / Inventory',
      'Auto-created for inventory purchase orders',
      p_organization_id,
      true,
      false
    )
    RETURNING id INTO v_type_id;
  END IF;

  SELECT ec.id
    INTO v_cat_id
  FROM public.expense_categories ec
  WHERE ec.expense_type_id = v_type_id
    AND ec.is_active IS TRUE
    AND lower(btrim(ec.name)) = lower(v_cat_name)
    AND (ec.organization_id = p_organization_id OR ec.organization_id IS NULL)
  ORDER BY
    CASE WHEN ec.organization_id = p_organization_id THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_cat_id IS NULL THEN
    INSERT INTO public.expense_categories (
      name, description, expense_type_id, organization_id, is_active, is_default
    ) VALUES (
      v_cat_name,
      'Auto-created for inventory purchase orders',
      v_type_id,
      p_organization_id,
      true,
      false
    )
    RETURNING id INTO v_cat_id;
  END IF;

  expense_type_id := v_type_id;
  expense_category_id := v_cat_id;
  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."resolve_inventory_po_expense_classification"("p_organization_id" "uuid", "p_item_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_production_assignee_user_id"("p_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pic_production_id uuid;
  v_step_assignee uuid;
BEGIN
  SELECT pic_production_id INTO v_pic_production_id
  FROM public.social_media_plans
  WHERE id = p_plan_id;

  IF v_pic_production_id IS NOT NULL THEN
    RETURN public.employee_user_id(v_pic_production_id);
  END IF;

  SELECT tsa.employee_id INTO v_step_assignee
  FROM public.task_steps ts
  JOIN public.task_steps_assigned tsa ON tsa.task_step_id = ts.id
  WHERE ts.social_media_plan_id = p_plan_id
  ORDER BY tsa.assigned_at DESC NULLS LAST
  LIMIT 1;

  RETURN public.employee_user_id(v_step_assignee);
END;
$$;


ALTER FUNCTION "public"."resolve_production_assignee_user_id"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_production_assigner_user_id"("p_plan_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_token_creator uuid;
  v_pic_id uuid;
BEGIN
  SELECT prt.created_by INTO v_token_creator
  FROM public.public_review_tokens prt
  WHERE prt.social_media_plan_id = p_plan_id
  ORDER BY prt.created_at DESC NULLS LAST
  LIMIT 1;

  IF v_token_creator IS NOT NULL THEN
    RETURN v_token_creator;
  END IF;

  SELECT pic_id INTO v_pic_id
  FROM public.social_media_plans
  WHERE id = p_plan_id;

  RETURN public.employee_user_id(v_pic_id);
END;
$$;


ALTER FUNCTION "public"."resolve_production_assigner_user_id"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_sales_outlet_package"("p_organization_id" "uuid", "p_pos_enabled" boolean, "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ids uuid[];
  v_count integer := 0;
  v_keep uuid[] := ARRAY[]::uuid[];
  v_keep_count integer := 0;
BEGIN
  IF NOT coalesce(p_pos_enabled, false) THEN
    RETURN jsonb_build_object('outlet_quota', 0, 'keep_outlet_ids', '[]'::jsonb);
  END IF;

  IF p_outlet_quota IS NULL OR p_outlet_quota < 1 OR p_outlet_quota > 100 THEN
    RAISE EXCEPTION 'outlet quota must be between 1 and 100' USING ERRCODE = '22023';
  END IF;

  SELECT coalesce(array_agg(o.id), ARRAY[]::uuid[])
  INTO v_ids
  FROM public.pos_outlets o
  WHERE o.organization_id = p_organization_id
    AND coalesce(o.is_deleted, false) = false;

  v_count := coalesce(cardinality(v_ids), 0);

  IF v_count > p_outlet_quota THEN
    SELECT count(DISTINCT k.id)::integer, coalesce(array_agg(DISTINCT k.id), ARRAY[]::uuid[])
    INTO v_keep_count, v_keep
    FROM unnest(coalesce(p_keep_outlet_ids, ARRAY[]::uuid[])) AS k(id);

    IF v_keep_count IS DISTINCT FROM p_outlet_quota
       OR EXISTS (
         SELECT 1
         FROM unnest(coalesce(p_keep_outlet_ids, ARRAY[]::uuid[])) AS k(id)
         WHERE NOT (k.id = ANY (v_ids))
       ) THEN
      RAISE EXCEPTION 'pilih tepat % outlet yang tetap buka', p_outlet_quota USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'outlet_quota', p_outlet_quota,
    'keep_outlet_ids', to_jsonb(v_keep)
  );
END;
$$;


ALTER FUNCTION "public"."resolve_sales_outlet_package"("p_organization_id" "uuid", "p_pos_enabled" boolean, "p_outlet_quota" integer, "p_keep_outlet_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_sla_policy_row"("p_organization_id" "uuid", "p_channel" "text") RETURNS TABLE("fr_min" integer, "res_min" integer, "ir_min" integer, "prof" "text", "ws_tz" "text", "ws_rules" "jsonb")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  WITH ch AS (
    SELECT public.normalize_sla_channel(p_channel) AS c
  ),
  fallback AS (
    SELECT
      15::integer AS fr_min,
      1440::integer AS res_min,
      NULL::integer AS ir_min,
      '24x7'::text AS prof,
      'UTC'::text AS ws_tz,
      '[]'::jsonb AS ws_rules
  ),
  picked AS (
    SELECT
      p.first_response_sla_minutes,
      p.resolution_sla_minutes,
      p.inter_reply_sla_minutes,
      p.operational_hours_profile,
      coalesce(ws.timezone, 'Asia/Jakarta') AS tz,
      coalesce(ws.weekly_rules, '[]'::jsonb) AS rules
    FROM public.organization_sla_policies p
    LEFT JOIN public.organization_sla_work_schedules ws ON ws.id = p.work_schedule_id
    WHERE p.organization_id = p_organization_id
      AND p.status = 'active'
      AND (
        NOT EXISTS (
          SELECT 1 FROM public.organization_sla_policy_conditions c WHERE c.policy_id = p.id
        )
        OR EXISTS (
          SELECT 1
          FROM public.organization_sla_policy_conditions c
          WHERE c.policy_id = p.id
            AND c.field = 'channel'
            AND c.operator = 'eq'
            AND public.normalize_sla_channel(c.value) = (SELECT ch.c FROM ch)
        )
      )
    ORDER BY p.priority ASC NULLS LAST, p.created_at ASC
    LIMIT 1
  )
  SELECT
    coalesce(picked.first_response_sla_minutes, fb.fr_min),
    coalesce(picked.resolution_sla_minutes, fb.res_min),
    picked.inter_reply_sla_minutes,
    coalesce(picked.operational_hours_profile, fb.prof),
    coalesce(picked.tz, fb.ws_tz),
    CASE
      WHEN picked.first_response_sla_minutes IS NULL THEN fb.ws_rules
      WHEN picked.operational_hours_profile = 'business_hours' THEN picked.rules
      ELSE '[]'::jsonb
    END
  FROM fallback fb
  LEFT JOIN picked ON true;
$$;


ALTER FUNCTION "public"."resolve_sla_policy_row"("p_organization_id" "uuid", "p_channel" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_sla_policy_row"("p_organization_id" "uuid", "p_channel" "text") IS 'SLA minutes + work calendar per org/channel; lowest priority wins. ir_min is inter_reply_sla_minutes (NULL = no inter-reply SLA).';



CREATE OR REPLACE FUNCTION "public"."resolve_visit_day_mode"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_date" "date", "p_client_location_id" "uuid" DEFAULT NULL::"uuid", "p_is_spontaneous" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rules record;
  v_sched record;
  v_primary public.client_visits%ROWTYPE;
  v_location_id uuid;
  v_travel integer;
  v_work_start_mins integer;
  v_visit_start_mins integer;
  v_overlap integer;
  v_threshold integer;
  v_mode text;
  v_reason text;
BEGIN
  SELECT *
  INTO v_rules
  FROM public.load_attendance_rules(p_organization_id) r
  LIMIT 1;

  IF COALESCE(v_rules.enable_visit_attendance_integration, true) IS NOT TRUE THEN
    RETURN jsonb_build_object('mode', 'normal', 'reason', 'integration_disabled');
  END IF;

  IF p_is_spontaneous THEN
    RETURN jsonb_build_object(
      'mode', 'field_first',
      'reason', 'spontaneous_visit',
      'primary_visit_id', NULL,
      'planned_start_time', NULL,
      'travel_minutes', NULL,
      'work_start_time', NULL
    );
  END IF;

  SELECT cv.*
  INTO v_primary
  FROM public.client_visits cv
  WHERE cv.employee_id = p_employee_id
    AND cv.organization_id = p_organization_id
    AND cv.visit_date = p_date
    AND cv.status IN ('scheduled', 'ongoing')
  ORDER BY cv.planned_start_time NULLS LAST, cv.created_at ASC
  LIMIT 1;

  IF v_primary.id IS NULL THEN
    RETURN jsonb_build_object('mode', 'normal', 'reason', 'no_scheduled_visit');
  END IF;

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(p_employee_id, p_organization_id, p_date) r
  LIMIT 1;

  v_location_id := COALESCE(v_primary.validated_location_id, p_client_location_id);
  v_travel := public.estimate_travel_minutes(p_organization_id, v_location_id);
  v_work_start_mins := public._time_text_to_minutes(v_sched.start_time);
  v_visit_start_mins := CASE
    WHEN v_primary.planned_start_time IS NULL THEN v_work_start_mins
    ELSE EXTRACT(HOUR FROM v_primary.planned_start_time)::integer * 60
      + EXTRACT(MINUTE FROM v_primary.planned_start_time)::integer
  END;
  v_overlap := COALESCE(v_rules.field_first_overlap_minutes, 30);
  v_threshold := COALESCE(v_rules.travel_threshold_minutes, 90);

  IF v_visit_start_mins <= v_work_start_mins + v_overlap THEN
    v_mode := 'field_first';
    v_reason := 'visit_start_overlaps_work_start';
  ELSIF COALESCE(v_travel, 0) >= v_threshold THEN
    v_mode := 'travel_field';
    v_reason := 'travel_exceeds_threshold';
  ELSE
    v_mode := 'office_first';
    v_reason := 'near_client_office_first';
  END IF;

  RETURN jsonb_build_object(
    'mode', v_mode,
    'reason', v_reason,
    'primary_visit_id', v_primary.id,
    'planned_start_time', v_primary.planned_start_time,
    'travel_minutes', v_travel,
    'work_start_time', v_sched.start_time
  );
END;
$$;


ALTER FUNCTION "public"."resolve_visit_day_mode"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_date" "date", "p_client_location_id" "uuid", "p_is_spontaneous" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_content_brief_version"("p_version_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan uuid;
  v_org uuid;
  v_brief text;
  v_concept text;
  v_caption text;
  v_link text;
  v_live_brief text;
  v_live_concept text;
  v_live_caption text;
  v_live_link text;
  v_status text;
  v_changed boolean := false;
  v_recorded uuid;
BEGIN
  IF p_version_id IS NULL OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  SELECT versions.social_media_plan_id,
         versions.brief,
         versions.concept,
         versions.caption,
         versions.link_reference
    INTO v_plan, v_brief, v_concept, v_caption, v_link
  FROM public.content_brief_versions AS versions
  WHERE versions.id = p_version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Version not found'
      USING ERRCODE = 'P0002';
  END IF;

  SELECT plan.organization_id, plan.brief, plan.status
    INTO v_org, v_live_brief, v_status
  FROM public.social_media_plans AS plan
  WHERE plan.id = v_plan
  FOR UPDATE;

  IF v_org NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  SELECT audience.description INTO v_live_concept
  FROM public.brief_target_audiences AS audience
  WHERE audience.social_media_plan_id = v_plan;

  SELECT caption.content INTO v_live_caption
  FROM public.brief_captions AS caption
  WHERE caption.social_media_plan_id = v_plan;

  SELECT link_ref.content INTO v_live_link
  FROM public.brief_link_references AS link_ref
  WHERE link_ref.social_media_plan_id = v_plan;

  IF v_brief IS DISTINCT FROM v_live_brief
     AND NOT public.can_edit_content_brief_field(v_plan, 'brief_storyboard', auth.uid()) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
  END IF;

  IF v_concept IS DISTINCT FROM v_live_concept
     AND NOT public.can_edit_content_brief_field(v_plan, 'brief_concept', auth.uid()) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_concept';
  END IF;

  IF v_caption IS DISTINCT FROM v_live_caption
     AND NOT public.can_edit_content_brief_field(v_plan, 'brief_caption', auth.uid()) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_caption';
  END IF;

  IF v_link IS DISTINCT FROM v_live_link
     AND NOT public.can_edit_content_brief_field(v_plan, 'brief_link', auth.uid()) THEN
    RAISE EXCEPTION 'brief_field_forbidden'
      USING ERRCODE = 'P0001', DETAIL = 'brief_link';
  END IF;

  v_changed := v_brief IS DISTINCT FROM v_live_brief
    OR v_concept IS DISTINCT FROM v_live_concept
    OR v_caption IS DISTINCT FROM v_live_caption
    OR v_link IS DISTINCT FROM v_live_link;

  IF v_changed AND public.content_brief_revision_locked(v_plan) THEN
    RAISE EXCEPTION 'brief_edit_locked'
      USING ERRCODE = 'P0001';
  END IF;

  v_recorded := public.record_content_brief_version(v_plan);

  UPDATE public.social_media_plans
  SET brief = v_brief
  WHERE id = v_plan;

  INSERT INTO public.brief_target_audiences (social_media_plan_id, description, updated_at)
  VALUES (v_plan, v_concept, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET description = EXCLUDED.description,
      updated_at = now();

  INSERT INTO public.brief_captions (social_media_plan_id, content, updated_at)
  VALUES (v_plan, v_caption, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET content = EXCLUDED.content,
      updated_at = now();

  INSERT INTO public.brief_link_references (social_media_plan_id, content, updated_at)
  VALUES (v_plan, v_link, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET content = EXCLUDED.content,
      updated_at = now();

  IF v_changed AND v_status IS DISTINCT FROM 'Request Revision' THEN
    PERFORM public.content_brief_demote_approval(v_plan);
  END IF;

  RETURN v_recorded;
END;
$$;


ALTER FUNCTION "public"."restore_content_brief_version"("p_version_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."restore_content_brief_version"("p_version_id" "uuid") IS 'Reject a field the account cannot edit or a production/publish lock, snapshot the live brief, then write the chosen version. An approved brief returns to Need Review.';



CREATE OR REPLACE FUNCTION "public"."restrict_secret_columns"("p_table" "regclass", "p_secret" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_readable text;
  v_writable text;
begin
  select string_agg(quote_ident(a.attname), ', ' order by a.attnum)
    into v_readable
    from pg_attribute a
   where a.attrelid = p_table and a.attnum > 0 and not a.attisdropped
     and a.attname <> all (p_secret);

  select string_agg(quote_ident(a.attname), ', ' order by a.attnum)
    into v_writable
    from pg_attribute a
   where a.attrelid = p_table and a.attnum > 0 and not a.attisdropped
     and a.attgenerated = ''
     and a.attname <> all (p_secret);

  execute format('revoke all on table %s from anon, authenticated', p_table);
  execute format('grant select (%s) on table %s to authenticated', v_readable, p_table);
  execute format('grant insert (%s) on table %s to authenticated', v_writable, p_table);
  execute format('grant update (%s) on table %s to authenticated', v_writable, p_table);
  execute format('grant delete on table %s to authenticated', p_table);
end;
$$;


ALTER FUNCTION "public"."restrict_secret_columns"("p_table" "regclass", "p_secret" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resubmit_catalog_po_purchase_request"("p_organization_id" "uuid", "p_purchase_order_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_pr public.purchase_requests%ROWTYPE;
  v_pr_id uuid;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;

  SELECT * INTO v_po
  FROM public.catalog_purchase_orders
  WHERE id = p_purchase_order_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found';
  END IF;
  IF v_po.status <> 'waiting' THEN
    RAISE EXCEPTION 'catalog_po_not_waiting';
  END IF;

  SELECT * INTO v_pr
  FROM public.purchase_requests
  WHERE catalog_purchase_order_id = v_po.id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_pr_id := public.sync_catalog_po_purchase_request(v_po.id);
    RETURN to_jsonb((SELECT r FROM public.purchase_requests r WHERE r.id = v_pr_id));
  END IF;

  IF v_pr.status <> 'rejected' THEN
    RAISE EXCEPTION 'catalog_po_not_rejected';
  END IF;

  v_pr_id := public.sync_catalog_po_purchase_request(v_po.id);

  UPDATE public.purchase_requests
  SET
    status = 'submitted',
    submitted_at = now(),
    rejected_at = NULL,
    rejected_by = NULL,
    rejected_by_user_id = NULL,
    rejected_by_name = NULL,
    rejection_reason = NULL,
    approval_notes = NULL,
    payment_status = 'pending',
    updated_at = now()
  WHERE id = v_pr_id;

  RETURN to_jsonb((SELECT r FROM public.purchase_requests r WHERE r.id = v_pr_id));
END;
$$;


ALTER FUNCTION "public"."resubmit_catalog_po_purchase_request"("p_organization_id" "uuid", "p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_catalog_kitchen_commit"("p_organization_id" "uuid", "p_session_id" "uuid", "p_reverse_id" "text", "p_lines" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_outlet uuid;
  v_ref_prefix text;
  v_line jsonb;
  v_fp text;
  v_qty numeric;
  v_reverse_qty numeric;
  v_committed numeric;
  v_ratio numeric;
  v_mov record;
  v_reverse_ref text;
  v_line_key text;
  v_product uuid;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_session_id IS NULL OR p_reverse_id IS NULL OR btrim(p_reverse_id) = '' THEN
    RAISE EXCEPTION 'catalog_stock_reverse_ref_required';
  END IF;

  v_ref_prefix := p_session_id::text || ':reverse:' || p_reverse_id;

  IF EXISTS (
    SELECT 1
    FROM public.catalog_stock_movements
    WHERE organization_id = p_organization_id
      AND reference_type = 'pos_kitchen_reverse'
      AND reference_id LIKE v_ref_prefix || ':%'
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'duplicate');
  END IF;

  SELECT outlet_id INTO v_outlet
  FROM public.pos_table_sessions
  WHERE id = p_session_id AND organization_id = p_organization_id;
  IF v_outlet IS NULL THEN
    SELECT outlet_id INTO v_outlet
    FROM public.pos_session_stock_commits
    WHERE session_id = p_session_id AND organization_id = p_organization_id
    LIMIT 1;
  END IF;

  IF p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0 THEN
    FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
    LOOP
      v_fp := NULLIF(btrim(v_line ->> 'line_fingerprint'), '');
      v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
      v_line_key := COALESCE(NULLIF(btrim(v_line ->> 'line_key'), ''), 'L1');
      v_product := NULLIF(v_line ->> 'product_id', '')::uuid;
      IF v_fp IS NULL OR v_qty <= 0 OR v_product IS NULL THEN
        CONTINUE;
      END IF;

      SELECT committed_qty INTO v_committed
      FROM public.pos_session_stock_commits
      WHERE session_id = p_session_id AND line_fingerprint = v_fp
      FOR UPDATE;

      IF NOT FOUND OR v_committed <= 0 THEN
        CONTINUE;
      END IF;

      v_reverse_qty := LEAST(v_qty, v_committed);
      v_ratio := v_reverse_qty / v_committed;

      FOR v_mov IN
        SELECT m.*
        FROM public.catalog_stock_movements m
        WHERE m.organization_id = p_organization_id
          AND m.reference_type = 'pos_kitchen_commit'
          AND m.reference_id LIKE p_session_id::text || ':%'
          AND m.reference_id LIKE '%:' || v_line_key || ':' || v_product::text || '%'
      LOOP
        v_reverse_ref := v_ref_prefix || ':' || v_mov.reference_id;
        PERFORM public.apply_catalog_stock_movement(
          p_organization_id,
          v_outlet,
          v_mov.item_kind,
          v_mov.product_id,
          v_mov.variant_id,
          v_mov.ingredient_id,
          'adjustment',
          ROUND(-v_mov.qty_delta * v_ratio, 3),
          'pos_kitchen_reverse',
          v_reverse_ref,
          'Kitchen commit reverse'
        );
      END LOOP;

      UPDATE public.pos_session_stock_commits
      SET
        committed_qty = GREATEST(0, committed_qty - v_reverse_qty),
        updated_at = now()
      WHERE session_id = p_session_id AND line_fingerprint = v_fp;
    END LOOP;
  ELSE
    FOR v_mov IN
      SELECT m.*
      FROM public.catalog_stock_movements m
      WHERE m.organization_id = p_organization_id
        AND m.reference_type = 'pos_kitchen_commit'
        AND m.reference_id LIKE p_session_id::text || ':%'
    LOOP
      v_reverse_ref := v_ref_prefix || ':' || v_mov.reference_id;
      PERFORM public.apply_catalog_stock_movement(
        p_organization_id,
        v_outlet,
        v_mov.item_kind,
        v_mov.product_id,
        v_mov.variant_id,
        v_mov.ingredient_id,
        'adjustment',
        -v_mov.qty_delta,
        'pos_kitchen_reverse',
        v_reverse_ref,
        'Kitchen commit reverse all'
      );
    END LOOP;

    UPDATE public.pos_session_stock_commits
    SET committed_qty = 0, updated_at = now()
    WHERE session_id = p_session_id AND organization_id = p_organization_id;
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."reverse_catalog_kitchen_commit"("p_organization_id" "uuid", "p_session_id" "uuid", "p_reverse_id" "text", "p_lines" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."reverse_catalog_kitchen_commit"("p_organization_id" "uuid", "p_session_id" "uuid", "p_reverse_id" "text", "p_lines" "jsonb") IS 'Reverse kitchen stock commits. Partial reverse spans ALL batches for session+line_key+product.';



CREATE OR REPLACE FUNCTION "public"."reverse_store_checkout_stock"("p_organization_id" "uuid", "p_activity_id" "text", "p_reverse_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_mov record;
  v_ref_prefix text;
  v_reverse_ref text;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_stock_forbidden';
  END IF;
  IF p_activity_id IS NULL OR btrim(p_activity_id) = '' THEN
    RAISE EXCEPTION 'catalog_stock_activity_required';
  END IF;

  v_ref_prefix := p_activity_id || ':reverse:' || COALESCE(NULLIF(btrim(p_reverse_id), ''), gen_random_uuid()::text);

  IF EXISTS (
    SELECT 1
    FROM public.catalog_stock_movements
    WHERE organization_id = p_organization_id
      AND reference_type = 'store_checkout_reverse'
      AND reference_id LIKE v_ref_prefix || ':%'
  ) THEN
    RETURN jsonb_build_object('skipped', true, 'reason', 'duplicate');
  END IF;

  FOR v_mov IN
    SELECT *
    FROM public.catalog_stock_movements
    WHERE organization_id = p_organization_id
      AND reference_type = 'store_checkout'
      AND reference_id LIKE p_activity_id || ':%'
  LOOP
    v_reverse_ref := v_ref_prefix || ':' || v_mov.reference_id;
    PERFORM public.apply_catalog_stock_movement(
      p_organization_id,
      v_mov.outlet_id,
      v_mov.item_kind,
      v_mov.product_id,
      v_mov.variant_id,
      v_mov.ingredient_id,
      'adjustment',
      -v_mov.qty_delta,
      'store_checkout_reverse',
      v_reverse_ref,
      'Checkout stock rollback'
    );
  END LOOP;

  RETURN jsonb_build_object('ok', true);
END;
$$;


ALTER FUNCTION "public"."reverse_store_checkout_stock"("p_organization_id" "uuid", "p_activity_id" "text", "p_reverse_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rollback_store_checkout_sales_activity"("p_activity_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  r RECORD;
  v_before numeric;
  v_after numeric;
BEGIN
  IF p_activity_id IS NULL THEN
    RETURN;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sales_activities sa
    WHERE sa.id = p_activity_id
      AND sa.organization_id IN (SELECT public.user_organization_ids())
  ) THEN
    RETURN;
  END IF;

  FOR r IN
    SELECT it.id, it.organization_id, it.bank_account_id, it.amount, it.deposit_confirmed_at
    FROM public.income_transactions it
    WHERE it.sales_activity_payment_id IN (
      SELECT sap.id
      FROM public.sales_activity_payments sap
      WHERE sap.sales_activity_id = p_activity_id
    )
  LOOP
    BEGIN
      PERFORM public.delete_bank_transfer_by_income_transaction(r.id);
    EXCEPTION
      WHEN OTHERS THEN
        IF position('NOT_BANK_TRANSFER_INCOME' in SQLERRM) = 0 THEN
          RAISE;
        END IF;

        IF r.deposit_confirmed_at IS NOT NULL
           AND r.bank_account_id IS NOT NULL
           AND COALESCE(r.amount, 0) > 0 THEN
          SELECT balance INTO v_before
          FROM public.bank_account_balances
          WHERE bank_account_id = r.bank_account_id
            AND organization_id = r.organization_id
          FOR UPDATE;

          IF FOUND THEN
            v_after := COALESCE(v_before, 0) - COALESCE(r.amount, 0);
            UPDATE public.bank_account_balances
            SET balance = v_after, updated_at = now()
            WHERE bank_account_id = r.bank_account_id
              AND organization_id = r.organization_id;

            INSERT INTO public.bank_account_balance_history (
              bank_account_id, organization_id, transaction_type, transaction_id,
              amount, balance_before, balance_after, description, created_by
            ) VALUES (
              r.bank_account_id,
              r.organization_id,
              'income',
              r.id,
              -COALESCE(r.amount, 0),
              COALESCE(v_before, 0),
              v_after,
              'Store checkout rollback',
              auth.uid()
            );
          END IF;
        END IF;

        DELETE FROM public.income_transactions WHERE id = r.id;
    END;
  END LOOP;

  DELETE FROM public.income_transactions
  WHERE sales_activity_payment_id IN (
    SELECT sap.id
    FROM public.sales_activity_payments sap
    WHERE sap.sales_activity_id = p_activity_id
  );

  DELETE FROM public.sales_activities WHERE id = p_activity_id;
END;
$$;


ALTER FUNCTION "public"."rollback_store_checkout_sales_activity"("p_activity_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."rollback_store_checkout_sales_activity"("p_activity_id" "uuid") IS 'Undo a failed store/POS checkout: remove linked income then the sales activity (and cascaded payments).';



CREATE OR REPLACE FUNCTION "public"."run_bank_expense_mutation_match_for_org"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_confirmed integer := 0;
  v_suggested integer := 0;
  v_linked integer := 0;
BEGIN
  -- Link Brick debit lines to existing ERP expenses (dedup / reconcile)
  UPDATE public.bank_statement_lines sl
  SET expense_id = e.id
  FROM public.expenses e
  WHERE sl.organization_id = p_organization_id
    AND sl.direction = 'debit'
    AND sl.expense_id IS NULL
    AND sl.origin <> 'erp_expense'
    AND e.organization_id = sl.organization_id
    AND e.purchase_request_id IS NOT NULL
    AND e.amount = sl.amount
    AND (
      e.bank_account_id = sl.bank_account_id
      OR (
        e.gateway_wallet_provider IS NOT NULL
        AND e.bank_account_id IS NULL
      )
    )
    AND sl.transaction_date >= (e.create_date::timestamptz - interval '1 day')
    AND sl.transaction_date <= (e.create_date::timestamptz + interval '2 days');

  GET DIAGNOSTICS v_linked = ROW_COUNT;

  -- Confirmed matches when expense already exists
  INSERT INTO public.bank_mutation_matches (
    organization_id,
    statement_line_id,
    expense_id,
    match_score,
    match_reason,
    status,
    confirmed_at
  )
  SELECT
    p_organization_id,
    sl.id,
    e.id,
    100,
    'exact_amount+account+date+expense',
    'confirmed',
    now()
  FROM public.bank_statement_lines sl
  INNER JOIN public.expenses e
    ON e.id = sl.expense_id
    AND e.organization_id = sl.organization_id
  WHERE sl.organization_id = p_organization_id
    AND sl.direction = 'debit'
    AND sl.expense_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.bank_mutation_matches m
      WHERE m.statement_line_id = sl.id
        AND m.status IN ('suggested', 'confirmed')
    );

  GET DIAGNOSTICS v_confirmed = ROW_COUNT;

  -- Suggested matches: Brick debit without expense_id → paid PR with expense
  INSERT INTO public.bank_mutation_matches (
    organization_id,
    statement_line_id,
    expense_id,
    match_score,
    match_reason,
    status
  )
  SELECT
    p_organization_id,
    sl.id,
    e.id,
    90,
    'exact_amount+account+date+suggested',
    'suggested'
  FROM public.bank_statement_lines sl
  INNER JOIN public.expenses e
    ON e.organization_id = sl.organization_id
    AND e.purchase_request_id IS NOT NULL
    AND e.amount = sl.amount
    AND (
      (e.bank_account_id IS NOT NULL AND e.bank_account_id = sl.bank_account_id)
      OR e.gateway_wallet_provider IS NOT NULL
    )
  INNER JOIN public.purchase_requests pr
    ON pr.id = e.purchase_request_id
    AND pr.payment_status = 'paid'
  WHERE sl.organization_id = p_organization_id
    AND sl.direction = 'debit'
    AND sl.expense_id IS NULL
    AND sl.origin <> 'erp_expense'
    AND sl.transaction_date >= (e.create_date::timestamptz - interval '1 day')
    AND sl.transaction_date <= (e.create_date::timestamptz + interval '2 days')
    AND NOT EXISTS (
      SELECT 1 FROM public.bank_mutation_matches m
      WHERE m.statement_line_id = sl.id
        AND m.status IN ('suggested', 'confirmed')
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.bank_mutation_matches m
      WHERE m.expense_id = e.id
        AND m.status IN ('suggested', 'confirmed')
    );

  GET DIAGNOSTICS v_suggested = ROW_COUNT;

  RETURN jsonb_build_object(
    'ok', true,
    'linked_expense_lines', v_linked,
    'confirmed_inserted', v_confirmed,
    'suggested_inserted', v_suggested
  );
END;
$$;


ALTER FUNCTION "public"."run_bank_expense_mutation_match_for_org"("p_organization_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."run_bank_expense_mutation_match_for_org"("p_organization_id" "uuid") IS 'Match debit bank_statement_lines to expenses from payment process; reconcile Brick debits.';



CREATE OR REPLACE FUNCTION "public"."run_bank_mutation_match_for_org"("p_organization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inserted integer := 0;
  v_role text := COALESCE(auth.jwt() ->> 'role', '');
BEGIN
  IF v_role IS DISTINCT FROM 'service_role'
     AND NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'bank_mutation_match_forbidden';
  END IF;

  INSERT INTO public.bank_mutation_matches (
    organization_id,
    statement_line_id,
    income_transaction_id,
    sales_activity_payment_id,
    match_score,
    match_reason,
    status
  )
  SELECT
    p_organization_id,
    sl.id,
    it.id,
    it.sales_activity_payment_id,
    100,
    'exact_amount+account+date',
    'suggested'
  FROM public.bank_statement_lines sl
  INNER JOIN public.income_transactions it
    ON it.organization_id = sl.organization_id
    AND it.bank_account_id = sl.bank_account_id
    AND it.status = 'pending'
    AND it.deposit_confirmed_at IS NULL
    AND it.amount = sl.amount
  INNER JOIN public.sales_activity_payments sap
    ON sap.id = it.sales_activity_payment_id
    AND sap.transfer_verification_status = 'unchecked'
  WHERE sl.organization_id = p_organization_id
    AND sl.direction = 'credit'
    AND NOT EXISTS (
      SELECT 1 FROM public.bank_mutation_matches m
      WHERE m.statement_line_id = sl.id AND m.status = 'confirmed'
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.bank_mutation_matches m
      WHERE m.income_transaction_id = it.id AND m.status IN ('suggested', 'confirmed')
    )
    AND sl.transaction_date >= (
      COALESCE(sap.payment_date::timestamptz, it.transaction_date::timestamptz) - interval '1 day'
    )
    AND sl.transaction_date <= (
      COALESCE(sap.payment_date::timestamptz, it.transaction_date::timestamptz) + interval '1 day'
    );

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN jsonb_build_object('ok', true, 'suggested_inserted', v_inserted);
END;
$$;


ALTER FUNCTION "public"."run_bank_mutation_match_for_org"("p_organization_id" "uuid") OWNER TO "postgres";


