CREATE OR REPLACE FUNCTION "public"."save_content_brief"("p_plan_id" "uuid", "p_base_version" integer, "p_record" boolean, "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
  v_latest integer;
  v_status text;
  v_current_brief text;
  v_old_concept text;
  v_old_caption text;
  v_old_link text;
  v_new_concept text;
  v_new_caption text;
  v_new_link text;
  v_changed boolean := false;
  v_storyboard_changed boolean := false;
BEGIN
  IF p_plan_id IS NULL OR auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  IF p_base_version IS NULL THEN
    RAISE EXCEPTION 'brief_version_required'
      USING ERRCODE = 'P0001', DETAIL = '0';
  END IF;

  SELECT plan.organization_id, plan.status, plan.brief
    INTO v_org, v_status, v_current_brief
  FROM public.social_media_plans AS plan
  WHERE plan.id = p_plan_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Plan not found'
      USING ERRCODE = 'P0002';
  END IF;

  IF v_org NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'Not allowed'
      USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(MAX(versions.version_no), 0)
    INTO v_latest
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  IF v_latest IS DISTINCT FROM p_base_version THEN
    RAISE EXCEPTION 'brief_version_conflict'
      USING ERRCODE = 'P0001', DETAIL = v_latest::text;
  END IF;

  v_new_concept := NULLIF(btrim(COALESCE(p_concept, '')), '');
  v_new_caption := NULLIF(btrim(COALESCE(p_caption, '')), '');
  v_new_link := NULLIF(btrim(COALESCE(p_link, '')), '');

  SELECT audience.description INTO v_old_concept
  FROM public.brief_target_audiences AS audience
  WHERE audience.social_media_plan_id = p_plan_id;

  SELECT caption.content INTO v_old_caption
  FROM public.brief_captions AS caption
  WHERE caption.social_media_plan_id = p_plan_id;

  SELECT link_ref.content INTO v_old_link
  FROM public.brief_link_references AS link_ref
  WHERE link_ref.social_media_plan_id = p_plan_id;

  IF p_brief IS DISTINCT FROM v_current_brief THEN
    IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_storyboard', auth.uid()) THEN
      RAISE EXCEPTION 'brief_field_forbidden'
        USING ERRCODE = 'P0001', DETAIL = 'brief_storyboard';
    END IF;
    v_storyboard_changed := true;
    v_changed := true;
  END IF;

  IF v_new_concept IS DISTINCT FROM v_old_concept THEN
    IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_concept', auth.uid()) THEN
      RAISE EXCEPTION 'brief_field_forbidden'
        USING ERRCODE = 'P0001', DETAIL = 'brief_concept';
    END IF;
    v_changed := true;
  END IF;

  IF v_new_caption IS DISTINCT FROM v_old_caption THEN
    IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_caption', auth.uid()) THEN
      RAISE EXCEPTION 'brief_field_forbidden'
        USING ERRCODE = 'P0001', DETAIL = 'brief_caption';
    END IF;
    v_changed := true;
  END IF;

  IF v_new_link IS DISTINCT FROM v_old_link THEN
    IF NOT public.can_edit_content_brief_field(p_plan_id, 'brief_link', auth.uid()) THEN
      RAISE EXCEPTION 'brief_field_forbidden'
        USING ERRCODE = 'P0001', DETAIL = 'brief_link';
    END IF;
    v_changed := true;
  END IF;

  IF v_changed AND public.content_brief_revision_locked(p_plan_id) THEN
    RAISE EXCEPTION 'brief_edit_locked'
      USING ERRCODE = 'P0001';
  END IF;

  IF COALESCE(p_record, false) THEN
    PERFORM public.content_brief_snapshot(p_plan_id, auth.uid(), 'office');
  END IF;

  IF v_storyboard_changed THEN
    UPDATE public.social_media_plans
    SET brief = p_brief
    WHERE id = p_plan_id;
  END IF;

  INSERT INTO public.brief_target_audiences (social_media_plan_id, description, updated_at)
  VALUES (p_plan_id, v_new_concept, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET description = EXCLUDED.description,
      updated_at = now();

  INSERT INTO public.brief_captions (social_media_plan_id, content, updated_at)
  VALUES (p_plan_id, v_new_caption, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET content = EXCLUDED.content,
      updated_at = now();

  INSERT INTO public.brief_link_references (social_media_plan_id, content, updated_at)
  VALUES (p_plan_id, v_new_link, now())
  ON CONFLICT (social_media_plan_id) DO UPDATE
  SET content = EXCLUDED.content,
      updated_at = now();

  IF v_changed AND v_status IS DISTINCT FROM 'Request Revision' THEN
    PERFORM public.content_brief_demote_approval(p_plan_id);
  END IF;

  SELECT COALESCE(MAX(versions.version_no), 0)
    INTO v_latest
  FROM public.content_brief_versions AS versions
  WHERE versions.social_media_plan_id = p_plan_id;

  RETURN v_latest;
END;
$$;


ALTER FUNCTION "public"."save_content_brief"("p_plan_id" "uuid", "p_base_version" integer, "p_record" boolean, "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."save_content_brief"("p_plan_id" "uuid", "p_base_version" integer, "p_record" boolean, "p_brief" "text", "p_concept" "text", "p_caption" "text", "p_link" "text") IS 'Lock the plan, reject a stale base_version, a field the account cannot edit, or a production/publish lock, optionally snapshot, then write brief, concept, caption, and link. An approved brief returns to Need Review when the content changes.';



CREATE OR REPLACE FUNCTION "public"."scheduled_post_platform_rank"("p_platform" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT COALESCE(
    array_position(
      ARRAY['Facebook', 'Instagram', 'LinkedIn', 'TikTok', 'YouTube', 'Threads']::text[],
      p_platform
    ),
    100
  );
$$;


ALTER FUNCTION "public"."scheduled_post_platform_rank"("p_platform" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scheduled_post_retry_backoff_interval"("p_retry_count" integer) RETURNS interval
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT make_interval(mins => (
    CASE GREATEST(1, LEAST(p_retry_count, 5))
      WHEN 1 THEN 2
      WHEN 2 THEN 5
      WHEN 3 THEN 15
      WHEN 4 THEN 30
      ELSE 60
    END
  ));
$$;


ALTER FUNCTION "public"."scheduled_post_retry_backoff_interval"("p_retry_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_facebook_messages"("p_organization_id" "uuid", "p_search" "text") RETURNS TABLE("conversation_id" "uuid", "message_id" "uuid", "body" "text", "created_at" timestamp with time zone, "direction" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') IN ('authenticated', 'anon')
     AND NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT * FROM public.search_facebook_messages__impl(p_organization_id, p_search);
END;
$$;


ALTER FUNCTION "public"."search_facebook_messages"("p_organization_id" "uuid", "p_search" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_facebook_messages__impl"("p_organization_id" "uuid", "p_search" "text") RETURNS TABLE("conversation_id" "uuid", "message_id" "uuid", "body" "text", "created_at" timestamp with time zone, "direction" "text")
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT
    c.id AS conversation_id,
    m.id AS message_id,
    LEFT(m.body, 300) AS body,
    m.created_at,
    m.direction::TEXT
  FROM public.facebook_conversations c
  INNER JOIN public.facebook_messages m ON m.conversation_id = c.id
  WHERE c.organization_id = p_organization_id
    AND p_search IS NOT NULL
    AND length(trim(p_search)) > 0
    AND m.body IS NOT NULL
    AND m.body ILIKE '%' || trim(p_search) || '%'
  ORDER BY m.created_at DESC
  LIMIT 500;
$$;


ALTER FUNCTION "public"."search_facebook_messages__impl"("p_organization_id" "uuid", "p_search" "text") OWNER TO "postgres";


