CREATE OR REPLACE FUNCTION "public"."service_get_leads_by_utm_campaign"("p_organization_id" "uuid", "p_from" "date", "p_to" "date") RETURNS TABLE("utm_campaign_key" "text", "leads_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from timestamptz;
  v_to timestamptz;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_from IS NULL OR p_to IS NULL THEN
    RAISE EXCEPTION 'date range is required';
  END IF;

  IF p_to < p_from THEN
    RAISE EXCEPTION 'invalid range';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.organizations o WHERE o.id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_from := (p_from::text || 'T00:00:00.000Z')::timestamptz;
  v_to := (p_to::text || 'T23:59:59.999Z')::timestamptz;

  RETURN QUERY
  SELECT
    btrim(l.attribution ->> 'utm_campaign') AS utm_campaign_key,
    COUNT(*)::bigint AS leads_count
  FROM public.leads l
  WHERE l.organization_id = p_organization_id
    AND l.created_at >= v_from
    AND l.created_at <= v_to
    AND btrim(COALESCE(l.attribution ->> 'utm_campaign', '')) <> ''
  GROUP BY btrim(l.attribution ->> 'utm_campaign');
END;
$$;


ALTER FUNCTION "public"."service_get_leads_by_utm_campaign"("p_organization_id" "uuid", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."service_get_leads_by_utm_campaign"("p_organization_id" "uuid", "p_from" "date", "p_to" "date") IS 'Count leads grouped by exact-case btrim(utm_campaign) for org-scoped Google Ads enrichment (service_role only).';



CREATE OR REPLACE FUNCTION "public"."service_get_traffic_ingestion_status"("p_organization_id" "uuid", "p_web_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  raw_exists boolean;
  daily_exists boolean;
  agg_min date;
  agg_max date;
  raw_min date;
  raw_max date;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_web_id IS NULL OR btrim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF NOT public.org_can_access_web_id(p_organization_id, p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  raw_exists :=
    EXISTS (SELECT 1 FROM public.analytics_sessions s WHERE s.web_id = p_web_id LIMIT 1)
    OR EXISTS (SELECT 1 FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id LIMIT 1)
    OR EXISTS (SELECT 1 FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id LIMIT 1);

  daily_exists := EXISTS (
    SELECT 1 FROM public.analytics_daily_sessions d WHERE d.web_id = p_web_id LIMIT 1
  );

  SELECT MIN(day), MAX(day)
  INTO agg_min, agg_max
  FROM public.analytics_daily_sessions
  WHERE web_id = p_web_id;

  SELECT
    LEAST(
      (SELECT MIN((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    ),
    GREATEST(
      (SELECT MAX((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    )
  INTO raw_min, raw_max;

  RETURN jsonb_build_object(
    'raw_events_exist', raw_exists,
    'daily_rollups_exist', daily_exists,
    'aggregate_day_min', agg_min,
    'aggregate_day_max', agg_max,
    'raw_day_min', raw_min,
    'raw_day_max', raw_max,
    'data_status', CASE
      WHEN NOT raw_exists THEN 'no_ingested_data'
      WHEN NOT daily_exists THEN 'raw_pending_rollup'
      ELSE 'ok'
    END
  );
END;
$$;


ALTER FUNCTION "public"."service_get_traffic_ingestion_status"("p_organization_id" "uuid", "p_web_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."service_get_traffic_ingestion_status"("p_organization_id" "uuid", "p_web_id" "text") IS 'Ingestion status for a web_id scoped to an organization (edge/service_role only).';



CREATE OR REPLACE FUNCTION "public"."service_get_traffic_sessions_by_gad_campaign_id"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") RETURNS TABLE("gad_campaign_id" "text", "sessions_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from date;
  v_to date;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_web_id IS NULL OR btrim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF NOT public.org_can_access_web_id(p_organization_id, p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT
    COALESCE(p_from, MIN((timezone('Asia/Jakarta', s.started_at))::date)),
    COALESCE(p_to, MAX((timezone('Asia/Jakarta', s.started_at))::date))
  INTO v_from, v_to
  FROM public.analytics_sessions s
  WHERE s.web_id = p_web_id;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN;
  END IF;

  IF v_to < v_from THEN
    RAISE EXCEPTION 'invalid range';
  END IF;

  RETURN QUERY
  SELECT
    gad_id AS gad_campaign_id,
    COUNT(*)::bigint AS sessions_count
  FROM (
    SELECT DISTINCT
      s.id,
      substring(
        COALESCE(s.last_landing_url, s.first_landing_url, s.landing_url, '')
        FROM 'gad_campaignid=([0-9]+)'
      ) AS gad_id
    FROM public.analytics_sessions s
    WHERE s.web_id = p_web_id
      AND (timezone('Asia/Jakarta', s.started_at))::date BETWEEN v_from AND v_to
      AND COALESCE(s.last_landing_url, s.first_landing_url, s.landing_url, '') ~ 'gad_campaignid=[0-9]+'
      AND (
        s.has_gclid = true
        OR s.has_gbraid = true
        OR s.gclid IS NOT NULL
        OR lower(btrim(COALESCE(s.last_utm_medium, s.first_utm_medium, s.utm_medium, ''))) = 'cpc'
      )
  ) q
  WHERE gad_id IS NOT NULL AND btrim(gad_id) <> ''
  GROUP BY gad_id;
END;
$$;


ALTER FUNCTION "public"."service_get_traffic_sessions_by_gad_campaign_id"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."service_get_traffic_sessions_by_gad_campaign_id"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") IS 'Count sessions per gad_campaignid parsed from landing URLs (Google Ads auto-tagging fallback for edge enrichment).';



CREATE OR REPLACE FUNCTION "public"."service_get_traffic_sessions_by_utm_campaign"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") RETURNS TABLE("utm_campaign_key" "text", "sessions_count" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from date;
  v_to date;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;

  IF p_web_id IS NULL OR btrim(p_web_id) = '' THEN
    RAISE EXCEPTION 'web_id is required';
  END IF;

  IF NOT public.org_can_access_web_id(p_organization_id, p_web_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT
    COALESCE(p_from, MIN(s.day)),
    COALESCE(p_to, MAX(s.day))
  INTO v_from, v_to
  FROM public.analytics_daily_sessions s
  WHERE s.web_id = p_web_id;

  IF v_from IS NULL OR v_to IS NULL THEN
    RETURN;
  END IF;

  IF v_to < v_from THEN
    RAISE EXCEPTION 'invalid range';
  END IF;

  RETURN QUERY
  SELECT
    lower(btrim(u.utm_campaign)) AS utm_campaign_key,
    COALESCE(SUM(u.sessions_count), 0)::bigint AS sessions_count
  FROM public.analytics_daily_utm u
  WHERE u.web_id = p_web_id
    AND u.day BETWEEN v_from AND v_to
    AND btrim(u.utm_campaign) <> ''
  GROUP BY lower(btrim(u.utm_campaign));
END;
$$;


ALTER FUNCTION "public"."service_get_traffic_sessions_by_utm_campaign"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."service_get_traffic_sessions_by_utm_campaign"("p_organization_id" "uuid", "p_web_id" "text", "p_from" "date", "p_to" "date") IS 'Sum analytics_daily_utm sessions by utm_campaign for org-scoped edge enrichment (service_role only).';



CREATE OR REPLACE FUNCTION "public"."set_attendance_penalty_payroll_period"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
BEGIN
  IF NEW.payroll_periods_id IS NOT NULL THEN
    RETURN NEW;
  END IF;
  SELECT pp.id
  INTO NEW.payroll_periods_id
  FROM public.payroll_periods pp
  WHERE pp.organization_id = NEW.organization_id
    AND NEW.applied_date >= pp.start_date
    AND NEW.applied_date <= pp.end_date
  ORDER BY pp.start_date DESC
  LIMIT 1;
  RETURN NEW;
END;
$$;


