CREATE OR REPLACE FUNCTION "public"."ship_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_transfer public.catalog_stock_transfers%ROWTYPE;
  v_line record;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_transfer_forbidden';
  END IF;
  IF NOT public.user_has_inventory_feature_access(p_organization_id, 'transfer_shipment') THEN
    RAISE EXCEPTION 'catalog_inventory_feature_forbidden';
  END IF;

  SELECT * INTO v_transfer
  FROM public.catalog_stock_transfers
  WHERE id = p_transfer_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_transfer_not_found';
  END IF;
  IF v_transfer.status <> 'approved' THEN
    RAISE EXCEPTION 'catalog_transfer_invalid_status';
  END IF;

  FOR v_line IN
    SELECT *
    FROM public.catalog_stock_transfer_lines
    WHERE transfer_id = v_transfer.id
    ORDER BY created_at
  LOOP
    PERFORM public.catalog_transfer_ship_line(
      p_organization_id,
      v_transfer.id,
      v_transfer.from_outlet_id,
      v_transfer.item_kind,
      COALESCE(p_comment, v_transfer.note),
      v_line
    );
  END LOOP;

  UPDATE public.catalog_stock_transfers
  SET
    status = 'shipped',
    shipped_at = now(),
    shipped_by = auth.uid(),
    updated_at = now()
  WHERE id = v_transfer.id;

  PERFORM public.catalog_transfer_insert_event(v_transfer.id, p_organization_id, 'shipped', p_comment);

  RETURN to_jsonb((SELECT t FROM public.catalog_stock_transfers t WHERE t.id = v_transfer.id));
END;
$$;


ALTER FUNCTION "public"."ship_catalog_stock_transfer"("p_organization_id" "uuid", "p_transfer_id" "uuid", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sjt_start_test"("p_recruitment_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_test_id uuid;
  v_duration_minutes integer;
  v_candidate_test_id uuid;
  v_started_at timestamptz;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;
  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT t.id, t.duration_minutes
  INTO v_test_id, v_duration_minutes
  FROM public.tests t
  WHERE t.type = 'sjt'
    AND t.is_active = true
  ORDER BY t.updated_at DESC
  LIMIT 1;

  IF v_test_id IS NULL THEN
    v_test_id := 'a1000000-0000-4000-8000-000000000003'::uuid;
    v_duration_minutes := 15;
  END IF;

  v_started_at := now();

  INSERT INTO public.candidate_tests (
    candidate_profile_id,
    test_id,
    status,
    started_at,
    created_at,
    updated_at
  )
  VALUES (
    v_profile_id,
    v_test_id,
    'in_progress',
    v_started_at,
    v_started_at,
    v_started_at
  )
  ON CONFLICT (candidate_profile_id, test_id)
  DO UPDATE SET
    status = 'in_progress',
    started_at = EXCLUDED.started_at,
    submitted_at = NULL,
    score_sjt = NULL,
    sjt_dimension_scores = NULL,
    answers = NULL,
    updated_at = EXCLUDED.updated_at
  RETURNING id INTO v_candidate_test_id;

  RETURN jsonb_build_object(
    'candidate_test_id', v_candidate_test_id,
    'started_at', v_started_at,
    'duration_minutes', COALESCE(v_duration_minutes, 15)
  );
END;
$$;


ALTER FUNCTION "public"."sjt_start_test"("p_recruitment_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sjt_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_sjt_question_id" "uuid", "p_selected_option_index" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_candidate_profile_id uuid;
  v_test_id uuid;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL OR p_sjt_question_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;
  IF p_selected_option_index NOT BETWEEN 1 AND 4 THEN
    RAISE EXCEPTION 'Pilihan jawaban tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;
  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id
  INTO v_candidate_profile_id, v_test_id
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;
  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.sjt_questions sq
    WHERE sq.id = p_sjt_question_id
      AND sq.test_id = v_test_id
  ) THEN
    RAISE EXCEPTION 'Soal tidak valid';
  END IF;

  UPDATE public.candidate_tests ct
  SET
    status = 'in_progress',
    answers = jsonb_set(
      COALESCE(ct.answers, '{}'::jsonb),
      ARRAY[p_sjt_question_id::text],
      to_jsonb(p_selected_option_index),
      true
    ),
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;
END;
$$;


ALTER FUNCTION "public"."sjt_submit_answer"("p_recruitment_token" "text", "p_candidate_test_id" "uuid", "p_sjt_question_id" "uuid", "p_selected_option_index" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sjt_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_profile_id uuid;
  v_candidate_profile_id uuid;
  v_test_id uuid;
  v_answers jsonb;
  v_score integer := 0;
  v_total_weighted integer := 0;
  v_count_a integer := 0;
  v_count_b integer := 0;
  v_count_c integer := 0;
  v_count_d integer := 0;
  v_dim_etika jsonb := jsonb_build_object('A', 0, 'B', 0, 'C', 0, 'D', 0, 'weighted', 0);
  v_dim_komunikasi jsonb := jsonb_build_object('A', 0, 'B', 0, 'C', 0, 'D', 0, 'weighted', 0);
  v_dim_prioritas jsonb := jsonb_build_object('A', 0, 'B', 0, 'C', 0, 'D', 0, 'weighted', 0);
  v_dim_konflik jsonb := jsonb_build_object('A', 0, 'B', 0, 'C', 0, 'D', 0, 'weighted', 0);
  v_dim_prosedur jsonb := jsonb_build_object('A', 0, 'B', 0, 'C', 0, 'D', 0, 'weighted', 0);
  v_dim_key text;
  v_grade text;
  v_weight integer;
  r record;
  v_selected integer;
BEGIN
  IF p_recruitment_token IS NULL OR btrim(p_recruitment_token) = '' THEN
    RAISE EXCEPTION 'Token tidak valid';
  END IF;
  IF p_candidate_test_id IS NULL THEN
    RAISE EXCEPTION 'Parameter tidak valid';
  END IF;

  SELECT cp.id INTO v_profile_id
  FROM public.candidate_profiles cp
  WHERE cp.recruitment_token = btrim(p_recruitment_token)
  LIMIT 1;

  IF v_profile_id IS NULL THEN
    RAISE EXCEPTION 'Profile tidak ditemukan';
  END IF;
  IF NOT public.candidate_profile_accessible(v_profile_id) THEN
    RAISE EXCEPTION 'Tidak memiliki akses';
  END IF;

  SELECT ct.candidate_profile_id, ct.test_id, ct.answers
  INTO v_candidate_profile_id, v_test_id, v_answers
  FROM public.candidate_tests ct
  WHERE ct.id = p_candidate_test_id
  LIMIT 1;

  IF v_candidate_profile_id IS NULL THEN
    RAISE EXCEPTION 'Tes kandidat tidak ditemukan';
  END IF;
  IF v_candidate_profile_id <> v_profile_id THEN
    RAISE EXCEPTION 'Tes kandidat tidak sesuai';
  END IF;

  v_answers := COALESCE(v_answers, '{}'::jsonb);

  FOR r IN
    SELECT sq.id, sq.best_option_index, sq.question_order
    FROM public.sjt_questions sq
    WHERE sq.test_id = v_test_id
    ORDER BY sq.question_order ASC
  LOOP
    v_selected := NULLIF((v_answers ->> r.id::text)::int, 0);
    IF v_selected IS NULL THEN
      CONTINUE;
    END IF;

    -- Grade simplification:
    -- A (4) if best option, otherwise C (2). This matches sjtResultUtils "new format"
    -- which expects A/B/C/D counts + weighted totals per dimension.
    IF v_selected = r.best_option_index THEN
      v_grade := 'A';
      v_weight := 4;
      v_score := v_score + 1;
    ELSE
      v_grade := 'C';
      v_weight := 2;
    END IF;

    v_total_weighted := v_total_weighted + v_weight;
    IF v_grade = 'A' THEN
      v_count_a := v_count_a + 1;
    ELSIF v_grade = 'B' THEN
      v_count_b := v_count_b + 1;
    ELSIF v_grade = 'C' THEN
      v_count_c := v_count_c + 1;
    ELSE
      v_count_d := v_count_d + 1;
    END IF;

    -- Dimension mapping by question_order (cycles across 5 dimensions):
    -- 1 etika, 2 komunikasi, 3 prioritas, 4 konflik, 0 prosedur
    v_dim_key := CASE (r.question_order % 5)
      WHEN 1 THEN 'etika'
      WHEN 2 THEN 'komunikasi'
      WHEN 3 THEN 'prioritas'
      WHEN 4 THEN 'konflik'
      ELSE 'prosedur'
    END;

    IF v_dim_key = 'etika' THEN
      v_dim_etika := jsonb_set(v_dim_etika, ARRAY[v_grade], to_jsonb(COALESCE((v_dim_etika ->> v_grade)::int, 0) + 1), true);
      v_dim_etika := jsonb_set(v_dim_etika, ARRAY['weighted'], to_jsonb(COALESCE((v_dim_etika ->> 'weighted')::int, 0) + v_weight), true);
    ELSIF v_dim_key = 'komunikasi' THEN
      v_dim_komunikasi := jsonb_set(v_dim_komunikasi, ARRAY[v_grade], to_jsonb(COALESCE((v_dim_komunikasi ->> v_grade)::int, 0) + 1), true);
      v_dim_komunikasi := jsonb_set(v_dim_komunikasi, ARRAY['weighted'], to_jsonb(COALESCE((v_dim_komunikasi ->> 'weighted')::int, 0) + v_weight), true);
    ELSIF v_dim_key = 'prioritas' THEN
      v_dim_prioritas := jsonb_set(v_dim_prioritas, ARRAY[v_grade], to_jsonb(COALESCE((v_dim_prioritas ->> v_grade)::int, 0) + 1), true);
      v_dim_prioritas := jsonb_set(v_dim_prioritas, ARRAY['weighted'], to_jsonb(COALESCE((v_dim_prioritas ->> 'weighted')::int, 0) + v_weight), true);
    ELSIF v_dim_key = 'konflik' THEN
      v_dim_konflik := jsonb_set(v_dim_konflik, ARRAY[v_grade], to_jsonb(COALESCE((v_dim_konflik ->> v_grade)::int, 0) + 1), true);
      v_dim_konflik := jsonb_set(v_dim_konflik, ARRAY['weighted'], to_jsonb(COALESCE((v_dim_konflik ->> 'weighted')::int, 0) + v_weight), true);
    ELSE
      v_dim_prosedur := jsonb_set(v_dim_prosedur, ARRAY[v_grade], to_jsonb(COALESCE((v_dim_prosedur ->> v_grade)::int, 0) + 1), true);
      v_dim_prosedur := jsonb_set(v_dim_prosedur, ARRAY['weighted'], to_jsonb(COALESCE((v_dim_prosedur ->> 'weighted')::int, 0) + v_weight), true);
    END IF;
  END LOOP;

  UPDATE public.candidate_tests ct
  SET
    status = 'submitted',
    submitted_at = now(),
    score_sjt = v_score,
    sjt_dimension_scores = jsonb_build_object(
      'total_weighted', v_total_weighted,
      'count_A', v_count_a,
      'count_B', v_count_b,
      'count_C', v_count_c,
      'count_D', v_count_d,
      'etika', v_dim_etika,
      'komunikasi', v_dim_komunikasi,
      'prioritas', v_dim_prioritas,
      'konflik', v_dim_konflik,
      'prosedur', v_dim_prosedur
    ),
    updated_at = now()
  WHERE ct.id = p_candidate_test_id;

  RETURN jsonb_build_object(
    'score_sjt', v_score,
    'sjt_dimension_scores', jsonb_build_object(
      'total_weighted', v_total_weighted,
      'count_A', v_count_a,
      'count_B', v_count_b,
      'count_C', v_count_c,
      'count_D', v_count_d,
      'etika', v_dim_etika,
      'komunikasi', v_dim_komunikasi,
      'prioritas', v_dim_prioritas,
      'konflik', v_dim_konflik,
      'prosedur', v_dim_prosedur
    )
  );
END;
$$;


ALTER FUNCTION "public"."sjt_submit_test"("p_recruitment_token" "text", "p_candidate_test_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sla__local_minute_is_working"("p_at" timestamp with time zone, "p_tz" "text", "p_rules" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  loc timestamp;
  dow integer;
  mod integer;
  r jsonb;
  open_m integer;
  close_m integer;
BEGIN
  loc := date_trunc('minute', p_at AT TIME ZONE p_tz);
  dow := EXTRACT(ISODOW FROM loc)::integer;
  mod := EXTRACT(HOUR FROM loc)::integer * 60 + EXTRACT(MINUTE FROM loc)::integer;
  FOR r IN SELECT * FROM jsonb_array_elements(coalesce(p_rules, '[]'::jsonb))
  LOOP
    IF (r->>'dow')::integer = dow THEN
      open_m := public.sla__time_to_min(coalesce(r->>'open', '00:00'));
      close_m := public.sla__time_to_min(coalesce(r->>'close', '00:00'));
      IF mod >= open_m AND mod < close_m THEN
        RETURN true;
      END IF;
    END IF;
  END LOOP;
  RETURN false;
END;
$$;


ALTER FUNCTION "public"."sla__local_minute_is_working"("p_at" timestamp with time zone, "p_tz" "text", "p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sla__time_to_min"("t" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT split_part(t, ':', 1)::integer * 60 + split_part(t, ':', 2)::integer;
$$;


ALTER FUNCTION "public"."sla__time_to_min"("t" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sla_add_working_minutes"("p_start" timestamp with time zone, "p_work_minutes" integer, "p_profile" "text", "p_tz" "text", "p_rules" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cur timestamptz := p_start;
  rem integer := greatest(p_work_minutes, 0);
  iter integer := 0;
BEGIN
  IF p_profile IS NULL OR p_profile = '24x7' OR p_work_minutes <= 0 THEN
    RETURN p_start + make_interval(mins => greatest(p_work_minutes, 0));
  END IF;
  WHILE rem > 0 LOOP
    iter := iter + 1;
    IF iter > 3000000 THEN
      RETURN p_start + make_interval(mins => p_work_minutes);
    END IF;
    IF public.sla__local_minute_is_working(cur, p_tz, p_rules) THEN
      rem := rem - 1;
    END IF;
    cur := cur + interval '1 minute';
  END LOOP;
  RETURN cur;
END;
$$;


ALTER FUNCTION "public"."sla_add_working_minutes"("p_start" timestamp with time zone, "p_work_minutes" integer, "p_profile" "text", "p_tz" "text", "p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sla_inter_reply_worst_in_cycle"("p_ir_min" integer, "p_prof" "text", "p_tz" "text", "p_rules" "jsonb", "p_first_response_at" timestamp with time zone, "p_resolved_at" timestamp with time zone, "p_msgs" "jsonb") RETURNS TABLE("ir_status" "text", "ir_late" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  eval_at timestamptz;
  arr jsonb;
  i int;
  j int;
  n int;
  at_i timestamptz;
  dir_i text;
  at_j timestamptz;
  dir_j text;
  due_at timestamptz;
  next_out timestamptz;
  reply_at timestamptz;
  gap_late int;
  worst int := 0;
  has_qualifying_inbound boolean := false;
  has_pending boolean := false;
  open_cycle boolean;
BEGIN
  ir_status := 'na';
  ir_late := NULL;

  IF p_ir_min IS NULL OR p_ir_min <= 0 OR p_first_response_at IS NULL THEN
    RETURN NEXT;
    RETURN;
  END IF;

  arr := coalesce(p_msgs, '[]'::jsonb);
  IF jsonb_typeof(arr) <> 'array' THEN
    RETURN NEXT;
    RETURN;
  END IF;

  n := coalesce(jsonb_array_length(arr), 0);
  IF n = 0 THEN
    RETURN NEXT;
    RETURN;
  END IF;

  eval_at := coalesce(p_resolved_at, now());
  open_cycle := p_resolved_at IS NULL;

  FOR i IN 0..(n - 1) LOOP
    dir_i := lower(trim(coalesce(arr->i->>'dir', '')));
    IF dir_i <> 'inbound' THEN
      CONTINUE;
    END IF;
    at_i := (arr->i->>'at')::timestamptz;
    IF at_i IS NULL OR at_i <= p_first_response_at THEN
      CONTINUE;
    END IF;

    has_qualifying_inbound := true;
    due_at := public.sla_add_working_minutes(at_i, p_ir_min, p_prof, p_tz, p_rules);

    next_out := NULL;
    FOR j IN (i + 1)..(n - 1) LOOP
      dir_j := lower(trim(coalesce(arr->j->>'dir', '')));
      IF dir_j = 'outbound' THEN
        at_j := (arr->j->>'at')::timestamptz;
        IF at_j IS NOT NULL AND at_j > at_i THEN
          next_out := at_j;
          EXIT;
        END IF;
      END IF;
    END LOOP;

    IF next_out IS NOT NULL THEN
      reply_at := next_out;
    ELSE
      reply_at := eval_at;
    END IF;

    IF reply_at > due_at THEN
      gap_late := greatest(
        0,
        public.sla_working_minutes_between(due_at, reply_at, p_prof, p_tz, p_rules)
      );
    ELSE
      gap_late := 0;
    END IF;

    IF gap_late > worst THEN
      worst := gap_late;
    END IF;

    IF next_out IS NULL AND open_cycle AND eval_at <= due_at THEN
      has_pending := true;
    END IF;
  END LOOP;

  IF NOT has_qualifying_inbound THEN
    ir_status := 'na';
    ir_late := NULL;
    RETURN NEXT;
    RETURN;
  END IF;

  IF worst > 0 THEN
    ir_status := 'late';
    ir_late := worst;
  ELSIF has_pending THEN
    ir_status := 'pending';
    ir_late := NULL;
  ELSE
    ir_status := 'on_time';
    ir_late := NULL;
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."sla_inter_reply_worst_in_cycle"("p_ir_min" integer, "p_prof" "text", "p_tz" "text", "p_rules" "jsonb", "p_first_response_at" timestamp with time zone, "p_resolved_at" timestamp with time zone, "p_msgs" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sla_inter_reply_worst_in_cycle"("p_ir_min" integer, "p_prof" "text", "p_tz" "text", "p_rules" "jsonb", "p_first_response_at" timestamp with time zone, "p_resolved_at" timestamp with time zone, "p_msgs" "jsonb") IS 'Per cycle: each inbound after first_response_at has due = add_working_minutes(inbound, ir_min). Reply = next outbound after that inbound, else eval_at = coalesce(resolved_at, now()). ir_late = max working minutes past due across gaps. pending = open cycle, unanswered inbound, eval <= due.';



CREATE OR REPLACE FUNCTION "public"."sla_working_minutes_between"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_profile" "text", "p_tz" "text", "p_rules" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  cur timestamptz := date_trunc('minute', p_from);
  end_m timestamptz := date_trunc('minute', p_to);
  cnt integer := 0;
  iter integer := 0;
BEGIN
  IF p_to <= p_from THEN
    RETURN 0;
  END IF;
  IF p_profile IS NULL OR p_profile = '24x7' THEN
    RETURN ceil(extract(epoch FROM (p_to - p_from)) / 60.0)::integer;
  END IF;
  WHILE cur < end_m LOOP
    iter := iter + 1;
    IF iter > 3000000 THEN
      RETURN ceil(extract(epoch FROM (p_to - p_from)) / 60.0)::integer;
    END IF;
    IF public.sla__local_minute_is_working(cur, p_tz, p_rules) THEN
      cnt := cnt + 1;
    END IF;
    cur := cur + interval '1 minute';
  END LOOP;
  RETURN cnt;
END;
$$;


ALTER FUNCTION "public"."sla_working_minutes_between"("p_from" timestamp with time zone, "p_to" timestamp with time zone, "p_profile" "text", "p_tz" "text", "p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_client_visit_execution"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_visit_date" "date", "p_location_id" "uuid", "p_lead_client_id" "uuid", "p_actual_start_time" timestamp with time zone, "p_start_location" "jsonb", "p_start_photo_path" "text", "p_created_by" "uuid", "p_location_validation_result" "jsonb" DEFAULT NULL::"jsonb", "p_validation_accuracy_meters" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_location_client_id uuid;
  v_scheduled public.client_visits%ROWTYPE;
  v_result public.client_visits%ROWTYPE;
  v_is_spontaneous boolean := false;
  v_mode jsonb;
  v_mode_text text;
  v_attendance jsonb := NULL;
  v_tz text := 'Asia/Jakarta';
  v_lead_id uuid;
BEGIN
  IF p_employee_id IS NULL OR p_organization_id IS NULL OR p_visit_date IS NULL OR p_location_id IS NULL THEN
    RAISE EXCEPTION 'INVALID_ARGUMENT';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = p_employee_id
      AND e.user_id = auth.uid()
      AND e.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'ACCESS_DENIED';
  END IF;

  IF NOT (p_organization_id IN (SELECT public.user_organization_ids())) THEN
    RAISE EXCEPTION 'ACCESS_DENIED';
  END IF;

  SELECT COALESCE(wss.timezone, 'Asia/Jakarta')
  INTO v_tz
  FROM public.work_schedule_settings wss
  WHERE wss.organization_id = p_organization_id
    AND COALESCE(wss.is_active, true)
  ORDER BY wss.is_default DESC NULLS LAST, wss.created_at ASC
  LIMIT 1;

  SELECT ol.client_id
  INTO v_location_client_id
  FROM public.office_locations ol
  WHERE ol.id = p_location_id
    AND ol.organization_id = p_organization_id;

  IF EXISTS (
    SELECT 1
    FROM public.client_visits cv
    WHERE cv.employee_id = p_employee_id
      AND cv.organization_id = p_organization_id
      AND cv.visit_date = p_visit_date
      AND cv.status = 'completed'
      AND cv.actual_start_time IS NOT NULL
      AND cv.actual_end_time IS NOT NULL
      AND (
        cv.validated_location_id = p_location_id
        OR (
          v_location_client_id IS NOT NULL
          AND cv.lead_client_id = v_location_client_id
        )
      )
  ) THEN
    RAISE EXCEPTION 'COMPLETED_VISIT_EXISTS';
  END IF;

  SELECT cv.*
  INTO v_scheduled
  FROM public.client_visits cv
  WHERE cv.employee_id = p_employee_id
    AND cv.organization_id = p_organization_id
    AND cv.visit_date = p_visit_date
    AND cv.status = 'scheduled'
    AND (
      cv.validated_location_id = p_location_id
      OR (
        v_location_client_id IS NOT NULL
        AND cv.lead_client_id = v_location_client_id
      )
      OR (
        p_lead_client_id IS NOT NULL
        AND cv.lead_client_id = p_lead_client_id
      )
    )
  ORDER BY
    CASE WHEN cv.validated_location_id = p_location_id THEN 0 ELSE 1 END,
    cv.planned_start_time NULLS LAST
  LIMIT 1
  FOR UPDATE;

  IF v_scheduled.id IS NOT NULL THEN
    UPDATE public.client_visits
    SET
      actual_start_time = p_actual_start_time,
      start_location = p_start_location,
      status = 'ongoing',
      start_photo_path = p_start_photo_path,
      created_by = p_created_by,
      validated_location_id = p_location_id,
      location_validation_result = p_location_validation_result,
      validation_accuracy_meters = p_validation_accuracy_meters,
      notes = COALESCE(p_notes, notes),
      updated_at = now()
    WHERE id = v_scheduled.id
      AND status = 'scheduled'
    RETURNING * INTO v_result;

    IF v_result.id IS NULL THEN
      RAISE EXCEPTION 'SCHEDULED_UPDATE_FAILED';
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1
      FROM public.client_visits cv
      WHERE cv.employee_id = p_employee_id
        AND cv.organization_id = p_organization_id
        AND cv.visit_date = p_visit_date
        AND cv.status = 'scheduled'
    ) THEN
      RAISE EXCEPTION 'SCHEDULED_VISIT_EXISTS';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.client_visits cv
      WHERE cv.employee_id = p_employee_id
        AND cv.organization_id = p_organization_id
        AND cv.visit_date = p_visit_date
        AND cv.status = 'ongoing'
    ) THEN
      RAISE EXCEPTION 'ONGOING_VISIT_EXISTS';
    END IF;

    v_is_spontaneous := true;

    SELECT c.lead_id
    INTO v_lead_id
    FROM public.clients c
    WHERE c.id = p_lead_client_id
      AND c.organization_id = p_organization_id;

    INSERT INTO public.client_visits (
      employee_id,
      organization_id,
      lead_client_id,
      lead_id,
      visit_date,
      planned_start_time,
      planned_end_time,
      visit_purpose,
      actual_start_time,
      start_location,
      status,
      start_photo_path,
      created_by,
      validated_location_id,
      location_validation_result,
      validation_accuracy_meters,
      notes
    )
    VALUES (
      p_employee_id,
      p_organization_id,
      p_lead_client_id,
      v_lead_id,
      p_visit_date,
      NULL,
      NULL,
      'Spontaneous client visit',
      p_actual_start_time,
      p_start_location,
      'ongoing',
      p_start_photo_path,
      p_created_by,
      p_location_id,
      p_location_validation_result,
      p_validation_accuracy_meters,
      p_notes
    )
    RETURNING * INTO v_result;
  END IF;

  v_mode := public.resolve_visit_day_mode(
    p_employee_id,
    p_organization_id,
    p_visit_date,
    p_location_id,
    v_is_spontaneous
  );
  v_mode_text := v_mode->>'mode';

  IF v_is_spontaneous OR v_mode_text IN ('field_first', 'travel_field') THEN
    v_attendance := public.record_attendance_from_client_visit(
      p_employee_id,
      p_organization_id,
      p_visit_date,
      v_result.id,
      p_location_id,
      p_actual_start_time,
      p_start_location,
      p_start_photo_path,
      v_tz,
      v_is_spontaneous,
      p_notes
    );
  END IF;

  RETURN jsonb_build_object(
    'visit', to_jsonb(v_result),
    'visit_day_mode', v_mode_text,
    'attendance', v_attendance
  );
END;
$$;


ALTER FUNCTION "public"."start_client_visit_execution"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_visit_date" "date", "p_location_id" "uuid", "p_lead_client_id" "uuid", "p_actual_start_time" timestamp with time zone, "p_start_location" "jsonb", "p_start_photo_path" "text", "p_created_by" "uuid", "p_location_validation_result" "jsonb", "p_validation_accuracy_meters" numeric, "p_notes" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."start_client_visit_execution"("p_employee_id" "uuid", "p_organization_id" "uuid", "p_visit_date" "date", "p_location_id" "uuid", "p_lead_client_id" "uuid", "p_actual_start_time" timestamp with time zone, "p_start_location" "jsonb", "p_start_photo_path" "text", "p_created_by" "uuid", "p_location_validation_result" "jsonb", "p_validation_accuracy_meters" numeric, "p_notes" "text") IS 'Start client visit; walk-in INSERT copies clients.lead_id onto client_visits.lead_id.';



CREATE OR REPLACE FUNCTION "public"."storage_active_organization_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT p.active_organization_id
  FROM public.profiles p
  WHERE p.user_id = (SELECT auth.uid())
$$;


ALTER FUNCTION "public"."storage_active_organization_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_user_in_active_org"("p_user_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  SELECT public.storage_active_organization_id() IS NOT NULL
    AND p_user_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    AND (
      EXISTS (
        SELECT 1
        FROM public.user_organizations uo
        WHERE uo.user_id::text = p_user_id
          AND uo.organization_id = public.storage_active_organization_id()
      )
      OR EXISTS (
        SELECT 1
        FROM public.employees e
        WHERE e.user_id::text = p_user_id
          AND e.organization_id = public.storage_active_organization_id()
      )
    )
$_$;


ALTER FUNCTION "public"."storage_user_in_active_org"("p_user_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_mfa_recovery_codes"("p_hashes" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  DELETE FROM public.user_mfa_recovery_codes
  WHERE user_id = auth.uid();

  INSERT INTO public.user_mfa_recovery_codes (user_id, code_hash)
  SELECT auth.uid(), unnest(p_hashes);
END;
$$;


ALTER FUNCTION "public"."store_mfa_recovery_codes"("p_hashes" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sub_service_library_photos"("p_organization_id" "uuid", "p_ids" "uuid"[]) RETURNS TABLE("sub_service_id" "uuid", "product_name" "text", "photo_path" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT sub.id,
         left(btrim(sub.name), 80),
         product.photo_path
  FROM unnest(COALESCE(p_ids, '{}'::uuid[])) WITH ORDINALITY AS item(id, ord)
  JOIN public.sub_services sub
    ON sub.id = item.id
   AND sub.organization_id = p_organization_id
  JOIN LATERAL (
    SELECT chosen.photo_path
    FROM public.default_prices chosen
    WHERE chosen.organization_id = sub.organization_id
      AND chosen.kind = 'product'
      AND NULLIF(btrim(chosen.photo_path), '') IS NOT NULL
      AND (
        chosen.id = sub.catalog_product_id
        OR (
          sub.catalog_product_id IS NULL
          AND lower(btrim(chosen.name)) = lower(btrim(sub.name))
          AND (
            SELECT count(*)
            FROM public.default_prices other
            WHERE other.organization_id = sub.organization_id
              AND other.kind = 'product'
              AND lower(btrim(other.name)) = lower(btrim(sub.name))
          ) = 1
        )
      )
    ORDER BY (chosen.id IS NOT DISTINCT FROM sub.catalog_product_id) DESC, chosen.updated_at DESC NULLS LAST
    LIMIT 1
  ) AS product ON true
  ORDER BY item.ord;
$$;


ALTER FUNCTION "public"."sub_service_library_photos"("p_organization_id" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_customer_survey"("p_token" "uuid", "p_rating" integer, "p_comment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv public.customer_survey_invitations%ROWTYPE;
  v_follow_q text;
  v_s public.organization_customer_survey_settings%ROWTYPE;
BEGIN
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_rating');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.customer_survey_invitations i
  WHERE i.public_token = p_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF v_inv.status <> 'sent' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_used_or_invalid');
  END IF;

  IF EXISTS (SELECT 1 FROM public.customer_survey_responses r WHERE r.invitation_id = v_inv.id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_submitted');
  END IF;

  SELECT s.* INTO v_s
  FROM public.organization_customer_survey_settings s
  WHERE s.organization_id = v_inv.organization_id;

  v_follow_q := NULL;
  IF FOUND THEN
    IF v_s.follow_up_mode = 'single' AND v_s.follow_up_single IS NOT NULL THEN
      v_follow_q := trim(v_s.follow_up_single);
    ELSIF v_s.follow_up_mode = 'by_score' THEN
      IF p_rating <= 2 THEN
        v_follow_q := trim(coalesce(v_s.follow_up_low, ''));
      ELSIF p_rating = 3 THEN
        v_follow_q := trim(coalesce(v_s.follow_up_mid, ''));
      ELSE
        v_follow_q := trim(coalesce(v_s.follow_up_high, ''));
      END IF;
      IF v_follow_q = '' THEN
        v_follow_q := NULL;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.customer_survey_responses (
    invitation_id,
    organization_id,
    whatsapp_conversation_id,
    assignee_id,
    rating,
    comment,
    follow_up_question_used
  )
  VALUES (
    v_inv.id,
    v_inv.organization_id,
    v_inv.whatsapp_conversation_id,
    v_inv.assignee_id,
    p_rating::smallint,
    nullif(trim(coalesce(p_comment, '')), ''),
    v_follow_q
  );

  UPDATE public.customer_survey_invitations
  SET status = 'submitted', updated_at = now()
  WHERE id = v_inv.id;

  RETURN jsonb_build_object('ok', true, 'thank_you_message', coalesce(v_s.thank_you_message, ''));
END;
$$;


ALTER FUNCTION "public"."submit_customer_survey"("p_token" "uuid", "p_rating" integer, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_job_application"("p_link_token" "text", "p_applicant" "jsonb", "p_skills" "jsonb" DEFAULT '[]'::"jsonb", "p_cv_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_link public.recruitment_links%ROWTYPE;
  v_name text  := left(btrim(coalesce(p_applicant->>'applicant_name', '')), 200);
  v_email text := lower(left(btrim(coalesce(p_applicant->>'applicant_email', '')), 200));
  v_phone text := nullif(left(btrim(coalesce(p_applicant->>'applicant_phone', '')), 40), '');
  v_birth date;
  v_token text;
  v_profile_id uuid;
  v_app_id uuid;
BEGIN
  IF p_link_token IS NULL OR length(p_link_token) NOT BETWEEN 8 AND 200 THEN
    RAISE EXCEPTION 'invalid_link' USING ERRCODE = 'P0001';
  END IF;
  SELECT * INTO v_link FROM public.recruitment_links
  WHERE token = p_link_token AND status = 'active'
    AND (expires_at IS NULL OR expires_at > now());
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_link' USING ERRCODE = 'P0001';
  END IF;
  IF v_name = '' OR v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RAISE EXCEPTION 'invalid_applicant' USING ERRCODE = 'P0001';
  END IF;
  BEGIN
    v_birth := nullif(p_applicant->>'birth_date', '')::date;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid_applicant' USING ERRCODE = 'P0001';
  END;
  IF p_cv_path IS NOT NULL AND (
       p_cv_path NOT LIKE 'apply/' || v_link.token || '/%'
       OR position('..' in p_cv_path) > 0
       OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'recruitment-files' AND o.name = p_cv_path)
     ) THEN
    RAISE EXCEPTION 'invalid_cv' USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.job_applications ja
    WHERE ja.job_opening_id = v_link.job_opening_id AND lower(ja.applicant_email) = v_email
  ) THEN
    RAISE EXCEPTION 'already_applied' USING ERRCODE = 'P0001';
  END IF;
  v_token := 'cand_' || encode(extensions.gen_random_bytes(24), 'hex');
  INSERT INTO public.candidate_profiles (
    organization_id, full_name, email, mobile_phone, birth_date, gender, nik,
    cover_letter, experience_years, expected_salary, employment_status, status,
    profile_completed, recruitment_token, cv_file_path
  ) VALUES (
    v_link.organization_id, v_name, v_email, v_phone, v_birth,
    nullif(left(p_applicant->>'gender', 20), ''),
    nullif(left(regexp_replace(coalesce(p_applicant->>'nik', ''), '\D', '', 'g'), 16), ''),
    left(p_applicant->>'cover_letter', 5000),
    left(p_applicant->>'experience_years', 50),
    left(p_applicant->>'expected_salary', 50),
    'pending', 'submitted', false, v_token, p_cv_path
  ) RETURNING id INTO v_profile_id;
  INSERT INTO public.job_applications (
    job_opening_id, organization_id, recruitment_link_id, candidate_profile_id,
    applicant_name, applicant_email, applicant_phone, birth_date, gender, nik,
    cv_file_path, cover_letter, experience_years, expected_salary, skills, status, recruitment_token
  ) VALUES (
    v_link.job_opening_id, v_link.organization_id, v_link.id, v_profile_id,
    v_name, v_email, v_phone, v_birth,
    nullif(left(p_applicant->>'gender', 20), ''),
    nullif(left(regexp_replace(coalesce(p_applicant->>'nik', ''), '\D', '', 'g'), 16), ''),
    p_cv_path,
    left(p_applicant->>'cover_letter', 5000),
    left(p_applicant->>'experience_years', 50),
    left(p_applicant->>'expected_salary', 50),
    CASE WHEN jsonb_typeof(p_skills) = 'array' THEN p_skills ELSE '[]'::jsonb END,
    'pending', v_token
  ) RETURNING id INTO v_app_id;
  UPDATE public.recruitment_links SET submissions = coalesce(submissions, 0) + 1 WHERE id = v_link.id;
  UPDATE public.job_openings SET submissions = coalesce(submissions, 0) + 1 WHERE id = v_link.job_opening_id;
  RETURN jsonb_build_object('application_id', v_app_id, 'candidate_profile_id', v_profile_id, 'token', v_token);
END;
$_$;


ALTER FUNCTION "public"."submit_job_application"("p_link_token" "text", "p_applicant" "jsonb", "p_skills" "jsonb", "p_cv_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_public_pos_receipt_feedback"("p_token" "uuid", "p_rating" integer, "p_comment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_inv public.pos_receipt_feedback_invitations%ROWTYPE;
  v_response_id uuid;
BEGIN
  IF p_rating IS NULL OR p_rating < 1 OR p_rating > 5 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_rating');
  END IF;

  SELECT i.* INTO v_inv
  FROM public.pos_receipt_feedback_invitations i
  WHERE i.public_token = p_token
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.pos_receipt_feedback_responses r WHERE r.invitation_id = v_inv.id
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'already_submitted');
  END IF;

  INSERT INTO public.pos_receipt_feedback_responses (
    invitation_id,
    organization_id,
    sales_activity_id,
    pos_outlet_id,
    served_by_employee_id,
    rating,
    comment
  )
  VALUES (
    v_inv.id,
    v_inv.organization_id,
    v_inv.sales_activity_id,
    v_inv.pos_outlet_id,
    v_inv.served_by_employee_id,
    p_rating::smallint,
    nullif(trim(coalesce(p_comment, '')), '')
  )
  RETURNING id INTO v_response_id;

  PERFORM public.sync_pos_receipt_feedback_item_attributions(v_response_id);

  RETURN jsonb_build_object('ok', true, 'thank_you_message', 'Thank you for your feedback!');
END;
$$;


ALTER FUNCTION "public"."submit_public_pos_receipt_feedback"("p_token" "uuid", "p_rating" integer, "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_synckerja_order_create_qris"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text" DEFAULT NULL::"text", "p_guest_email" "text" DEFAULT NULL::"text", "p_bill_note" "text" DEFAULT NULL::"text", "p_fulfillment" "text" DEFAULT 'dine_in'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_tbl record;
  v_cart jsonb;
  v_session uuid;
  v_subtotal numeric;
  v_totals jsonb;
  v_payload jsonb;
  v_pending uuid;
  v_actor uuid;
  v_lead uuid;
  v_st record;
  v_client text;
  v_items jsonb := '[]'::jsonb;
  v_mods jsonb := '[]'::jsonb;
  v_line jsonb;
  v_mod jsonb;
  v_status uuid;
  v_hours jsonb;
  v_idx integer := 0;
  v_kind text;
  v_opt_id uuid;
  v_group_id uuid;
  v_group_name text;
  v_opt_name text;
  v_extra numeric;
  v_opt_qty numeric;
  v_line_qty numeric;
  v_note text;
  v_phone text;
  v_email text;
  v_bill text;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  v_hours := public._synckerja_order_hours_state(v_out.outlet_id);
  IF NOT COALESCE((v_hours ->> 'is_open')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_closed');
  END IF;
  SELECT * INTO v_tbl FROM public._synckerja_order_table_state(v_out.organization_id, v_out.outlet_id, p_table_name);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_not_found');
  END IF;
  IF v_tbl.join_state = 'full' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_full');
  END IF;
  v_cart := public._synckerja_order_sanitize_cart(v_out.organization_id, v_out.outlet_id, p_cart);
  IF jsonb_array_length(v_cart) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'empty_cart');
  END IF;
  v_subtotal := public._synckerja_order_cart_subtotal(v_cart);
  v_totals := public._synckerja_order_checkout_totals(v_out.organization_id, v_subtotal);
  IF COALESCE((v_totals ->> 'grandTotal')::numeric, 0) < 1500 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'pos_qris_amount_too_low');
  END IF;
  v_actor := public._synckerja_order_org_actor(v_out.organization_id);
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_not_ready');
  END IF;
  v_client := COALESCE(NULLIF(btrim(p_guest_name), ''), 'Walk-in');
  v_phone := NULLIF(left(btrim(COALESCE(p_guest_phone, '')), 32), '');
  v_email := NULLIF(left(btrim(COALESCE(p_guest_email, '')), 120), '');
  v_bill := NULLIF(left(btrim(COALESCE(p_bill_note, '')), 500), '');
  SELECT * INTO v_st
  FROM public._synckerja_order_resolve_sales_type(v_out.organization_id, p_fulfillment);
  SELECT id INTO v_status FROM public.lead_statuses
  WHERE organization_id = v_out.organization_id OR organization_id IS NULL
  ORDER BY sort_order ASC LIMIT 1;

  v_lead := public._synckerja_order_ensure_lead(
    v_out.organization_id,
    v_actor,
    v_status,
    v_client,
    v_phone,
    v_email
  );

  IF v_tbl.join_state = 'join' AND v_tbl.open_session_id IS NOT NULL THEN
    v_session := v_tbl.open_session_id;
    UPDATE public.pos_table_sessions
    SET pax = pax + 1,
        customer_name = COALESCE(NULLIF(btrim(customer_name), ''), NULLIF(v_client, 'Walk-in')),
        customer_phone = COALESCE(NULLIF(btrim(customer_phone), ''), v_phone),
        guest_note = COALESCE(v_bill, guest_note)
    WHERE id = v_session AND status = 'open';
  ELSE
    INSERT INTO public.pos_table_sessions (
      organization_id, outlet_id, group_id, pos_table_id, table_name, pax,
      status, cart_snapshot, customer_name, customer_phone, guest_note
    ) VALUES (
      v_out.organization_id, v_out.outlet_id, v_tbl.group_id, v_tbl.table_id, v_tbl.table_name, 1,
      'open', '[]'::jsonb, NULLIF(v_client, 'Walk-in'), v_phone, v_bill
    ) RETURNING id INTO v_session;
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(v_cart)
  LOOP
    v_kind := COALESCE(NULLIF(v_line ->> 'kind', ''), 'product');
    v_line_qty := COALESCE((v_line ->> 'quantity')::numeric, 1);
    v_note := public._synckerja_order_sanitize_kitchen_note(
      COALESCE(v_line ->> 'kitchenNote', v_line ->> 'kitchen_note')
    );
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'service_id', v_line -> 'serviceId',
      'sub_service_id', v_line -> 'subServiceId',
      'service_name', v_line ->> 'serviceName',
      'sub_service_name', v_line -> 'subServiceName',
      'quantity', v_line_qty,
      'unit_price', (v_line ->> 'unitPrice')::numeric,
      'total_price', v_line_qty * (v_line ->> 'unitPrice')::numeric,
      'notes', to_jsonb(v_note),
      'item_kind', v_kind,
      'inventory_sku_id', v_line -> 'inventorySkuId',
      'track_stock', COALESCE((v_line ->> 'trackStock')::boolean, false),
      'catalog_product_id', CASE WHEN v_kind = 'bundle' THEN NULL ELSE v_line ->> 'catalogId' END,
      'catalog_variant_id', v_line -> 'variantId',
      'catalog_bundle_id', CASE WHEN v_kind = 'bundle' THEN v_line ->> 'catalogId' ELSE NULL END,
      'catalog_sales_type_id', v_st.sales_type_id,
      'unit_cogs', NULL,
      'cogs_source', 'none'
    ));
    FOR v_mod IN SELECT value FROM jsonb_array_elements(COALESCE(v_line -> 'modifiers', '[]'::jsonb))
    LOOP
      BEGIN
        v_opt_id := COALESCE(NULLIF(v_mod ->> 'optionId', ''), NULLIF(v_mod ->> 'option_id', ''))::uuid;
      EXCEPTION WHEN others THEN
        v_opt_id := NULL;
      END;
      IF v_opt_id IS NULL THEN
        CONTINUE;
      END IF;
      BEGIN
        v_opt_qty := GREATEST(1, floor(COALESCE((v_mod ->> 'quantity')::numeric, 1)));
      EXCEPTION WHEN others THEN
        v_opt_qty := 1;
      END;
      SELECT o.group_id, g.name, o.name, COALESCE(o.extra_price, 0)
      INTO v_group_id, v_group_name, v_opt_name, v_extra
      FROM public.catalog_modifier_options o
      JOIN public.catalog_modifier_groups g ON g.id = o.group_id
      WHERE o.id = v_opt_id
      LIMIT 1;
      v_mods := v_mods || jsonb_build_array(jsonb_build_object(
        'item_index', v_idx,
        'modifier_group_id', v_group_id,
        'modifier_option_id', v_opt_id,
        'group_name', COALESCE(v_group_name, v_mod ->> 'groupName', 'Unknown'),
        'option_name', COALESCE(v_opt_name, v_mod ->> 'name', 'Unknown'),
        'extra_price', COALESCE(v_extra, 0),
        'quantity', v_opt_qty * v_line_qty,
        'line_quantity', v_line_qty,
        'gross_sales', COALESCE(v_extra, 0) * v_opt_qty * v_line_qty,
        'discount_amount', 0
      ));
    END LOOP;
    v_idx := v_idx + 1;
  END LOOP;

  v_payload := jsonb_build_object(
    'fulfillmentMode', v_st.fulfillment,
    'salesTypeLabel', v_st.sales_type_name,
    'activity', jsonb_build_object(
      'lead_id', v_lead,
      'client_name', v_client,
      'client_phone', v_phone,
      'date', CURRENT_DATE,
      'created_by', v_actor,
      'total_amount', (v_totals ->> 'grandTotal')::numeric,
      'table_number', v_tbl.table_name,
      'pos_table_id', v_tbl.table_id,
      'catalog_sales_type_id', v_st.sales_type_id,
      'checkout_subtotal', (v_totals ->> 'subtotal')::numeric,
      'checkout_tax_amount', (v_totals ->> 'taxTotal')::numeric,
      'checkout_gratuity_amount', (v_totals ->> 'gratuityTotal')::numeric,
      'checkout_application_method', v_totals ->> 'applicationMethod',
      'checkout_discount_amount', 0,
      'description', CASE
        WHEN v_bill IS NULL THEN 'Synckerja Order'
        ELSE 'Synckerja Order: ' || v_bill
      END
    ),
    'items', v_items,
    'modifiers', v_mods,
    'discounts', '[]'::jsonb,
    'catalogStockLines', '[]'::jsonb,
    'checkoutTotals', v_totals,
    'cart', v_cart,
    'leadId', v_lead,
    'sessionId', v_session,
    'keepSessionOpen', true,
    'remainderCartLines', '[]'::jsonb
  );

  INSERT INTO public.pos_pending_checkouts (
    organization_id, pos_outlet_id, status, payload, lead_id, session_id,
    keep_session_open, expires_at, created_by
  ) VALUES (
    v_out.organization_id, v_out.outlet_id, 'pending', v_payload, v_lead, v_session,
    true, now() + interval '90 seconds', v_actor
  ) RETURNING id INTO v_pending;

  RETURN jsonb_build_object(
    'ok', true,
    'pending_checkout_id', v_pending,
    'session_id', v_session,
    'fulfillment', v_st.fulfillment,
    'sales_type_label', v_st.sales_type_name
  );
END;
$$;


ALTER FUNCTION "public"."submit_synckerja_order_create_qris"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text", "p_guest_email" "text", "p_bill_note" "text", "p_fulfillment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_synckerja_order_pay_at_cashier"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text" DEFAULT NULL::"text", "p_guest_email" "text" DEFAULT NULL::"text", "p_bill_note" "text" DEFAULT NULL::"text", "p_fulfillment" "text" DEFAULT 'dine_in'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_tbl record;
  v_cart jsonb;
  v_session uuid;
  v_subtotal numeric;
  v_totals jsonb;
  v_payload jsonb;
  v_pending uuid;
  v_pending_row public.pos_pending_checkouts%ROWTYPE;
  v_actor uuid;
  v_st record;
  v_hours jsonb;
  v_phone text;
  v_note text;
  v_client text;
  v_token text;
  v_existing public.pos_table_sessions%ROWTYPE;
  v_items jsonb := '[]'::jsonb;
  v_mods jsonb := '[]'::jsonb;
  v_line jsonb;
  v_mod jsonb;
  v_idx integer := 0;
  v_kind text;
  v_opt_id uuid;
  v_group_id uuid;
  v_group_name text;
  v_opt_name text;
  v_extra numeric;
  v_opt_qty numeric;
  v_line_qty numeric;
  v_line_note text;
  v_reuse_pending boolean := false;
  v_prev_fulfillment text;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  v_hours := public._synckerja_order_hours_state(v_out.outlet_id);
  IF NOT COALESCE((v_hours ->> 'is_open')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_closed');
  END IF;
  SELECT * INTO v_tbl FROM public._synckerja_order_table_state(v_out.organization_id, v_out.outlet_id, p_table_name);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_not_found');
  END IF;
  IF v_tbl.join_state = 'full' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_full');
  END IF;
  v_cart := public._synckerja_order_sanitize_cart(v_out.organization_id, v_out.outlet_id, p_cart);
  IF jsonb_array_length(v_cart) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'empty_cart');
  END IF;
  v_subtotal := public._synckerja_order_cart_subtotal(v_cart);
  v_totals := public._synckerja_order_checkout_totals(v_out.organization_id, v_subtotal);
  v_actor := public._synckerja_order_org_actor(v_out.organization_id);
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_not_ready');
  END IF;
  v_client := COALESCE(NULLIF(btrim(p_guest_name), ''), 'Walk-in');
  v_phone := NULLIF(left(btrim(COALESCE(p_guest_phone, '')), 32), '');
  v_note := NULLIF(left(btrim(COALESCE(p_bill_note, '')), 500), '');
  SELECT * INTO v_st
  FROM public._synckerja_order_resolve_sales_type(v_out.organization_id, p_fulfillment);

  SELECT p.* INTO v_pending_row
  FROM public.pos_pending_checkouts p
  JOIN public.pos_table_sessions s ON s.id = p.session_id
  WHERE s.organization_id = v_out.organization_id
    AND s.outlet_id = v_out.outlet_id
    AND s.pos_table_id = v_tbl.table_id
    AND s.status = 'open'
    AND p.checkout_channel = 'synckerja_cashier'
    AND p.status = 'pending'
  ORDER BY p.created_at DESC
  LIMIT 1;

  IF FOUND THEN
    v_prev_fulfillment := COALESCE(NULLIF(v_pending_row.payload ->> 'fulfillmentMode', ''), 'dine_in');
    IF v_prev_fulfillment IS DISTINCT FROM v_st.fulfillment THEN
      RETURN jsonb_build_object('ok', false, 'error', 'fulfillment_mismatch');
    END IF;
    v_reuse_pending := true;
    v_token := v_pending_row.claim_token;
    v_pending := v_pending_row.id;
    SELECT * INTO v_existing FROM public.pos_table_sessions WHERE id = v_pending_row.session_id;
    UPDATE public.pos_table_sessions
    SET
      cart_snapshot = v_cart,
      customer_name = COALESCE(NULLIF(btrim(customer_name), ''), NULLIF(btrim(COALESCE(p_guest_name, '')), '')),
      customer_phone = COALESCE(NULLIF(btrim(customer_phone), ''), v_phone),
      guest_note = COALESCE(v_note, guest_note)
    WHERE id = v_existing.id;
    v_session := v_existing.id;
  ELSE
    SELECT * INTO v_existing
    FROM public.pos_table_sessions
    WHERE organization_id = v_out.organization_id
      AND outlet_id = v_out.outlet_id
      AND pos_table_id = v_tbl.table_id
      AND status = 'open'
      AND awaiting_cashier_claim = true
    ORDER BY created_at DESC
    LIMIT 1;

    IF FOUND THEN
      UPDATE public.pos_table_sessions
      SET
        cart_snapshot = v_cart,
        customer_name = COALESCE(NULLIF(btrim(customer_name), ''), NULLIF(btrim(COALESCE(p_guest_name, '')), '')),
        customer_phone = COALESCE(NULLIF(btrim(customer_phone), ''), v_phone),
        guest_note = COALESCE(v_note, guest_note)
      WHERE id = v_existing.id
      RETURNING id INTO v_session;
      v_token := public._synckerja_order_new_claim_token();
    ELSIF v_tbl.join_state = 'join' AND v_tbl.open_session_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'table_busy');
    ELSE
      v_token := public._synckerja_order_new_claim_token();
      INSERT INTO public.pos_table_sessions (
        organization_id, outlet_id, group_id, pos_table_id, table_name, pax,
        status, cart_snapshot, customer_name, customer_phone, guest_note,
        awaiting_cashier_claim
      ) VALUES (
        v_out.organization_id, v_out.outlet_id, v_tbl.group_id, v_tbl.table_id, v_tbl.table_name, 1,
        'open', v_cart, NULLIF(btrim(COALESCE(p_guest_name, '')), ''), v_phone, v_note, true
      ) RETURNING id INTO v_session;
    END IF;
  END IF;

  FOR v_line IN SELECT value FROM jsonb_array_elements(v_cart)
  LOOP
    v_kind := COALESCE(NULLIF(v_line ->> 'kind', ''), 'product');
    v_line_qty := COALESCE((v_line ->> 'quantity')::numeric, 1);
    v_line_note := public._synckerja_order_sanitize_kitchen_note(
      COALESCE(v_line ->> 'kitchenNote', v_line ->> 'kitchen_note')
    );
    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'service_id', v_line -> 'serviceId',
      'sub_service_id', v_line -> 'subServiceId',
      'service_name', v_line ->> 'serviceName',
      'sub_service_name', v_line -> 'subServiceName',
      'quantity', v_line_qty,
      'unit_price', (v_line ->> 'unitPrice')::numeric,
      'total_price', v_line_qty * (v_line ->> 'unitPrice')::numeric,
      'notes', to_jsonb(v_line_note),
      'item_kind', v_kind,
      'inventory_sku_id', v_line -> 'inventorySkuId',
      'track_stock', COALESCE((v_line ->> 'trackStock')::boolean, false),
      'catalog_product_id', CASE WHEN v_kind = 'bundle' THEN NULL ELSE v_line ->> 'catalogId' END,
      'catalog_variant_id', v_line -> 'variantId',
      'catalog_bundle_id', CASE WHEN v_kind = 'bundle' THEN v_line ->> 'catalogId' ELSE NULL END,
      'catalog_sales_type_id', v_st.sales_type_id,
      'unit_cogs', NULL,
      'cogs_source', 'none'
    ));
    FOR v_mod IN SELECT value FROM jsonb_array_elements(COALESCE(v_line -> 'modifiers', '[]'::jsonb))
    LOOP
      BEGIN
        v_opt_id := COALESCE(NULLIF(v_mod ->> 'optionId', ''), NULLIF(v_mod ->> 'option_id', ''))::uuid;
      EXCEPTION WHEN others THEN
        v_opt_id := NULL;
      END;
      IF v_opt_id IS NULL THEN CONTINUE; END IF;
      BEGIN
        v_opt_qty := GREATEST(1, floor(COALESCE((v_mod ->> 'quantity')::numeric, 1)));
      EXCEPTION WHEN others THEN
        v_opt_qty := 1;
      END;
      SELECT o.group_id, g.name, o.name, COALESCE(o.extra_price, 0)
      INTO v_group_id, v_group_name, v_opt_name, v_extra
      FROM public.catalog_modifier_options o
      JOIN public.catalog_modifier_groups g ON g.id = o.group_id
      WHERE o.id = v_opt_id LIMIT 1;
      v_mods := v_mods || jsonb_build_array(jsonb_build_object(
        'item_index', v_idx,
        'modifier_group_id', v_group_id,
        'modifier_option_id', v_opt_id,
        'group_name', COALESCE(v_group_name, v_mod ->> 'groupName', 'Unknown'),
        'option_name', COALESCE(v_opt_name, v_mod ->> 'name', 'Unknown'),
        'extra_price', COALESCE(v_extra, 0),
        'quantity', v_opt_qty * v_line_qty,
        'line_quantity', v_line_qty,
        'gross_sales', COALESCE(v_extra, 0) * v_opt_qty * v_line_qty,
        'discount_amount', 0
      ));
    END LOOP;
    v_idx := v_idx + 1;
  END LOOP;

  v_payload := jsonb_build_object(
    'checkoutChannel', 'synckerja_cashier',
    'fulfillmentMode', v_st.fulfillment,
    'salesTypeLabel', v_st.sales_type_name,
    'kitchenFired', COALESCE((v_pending_row.payload ->> 'kitchenFired')::boolean, false),
    'activity', jsonb_build_object(
      'client_name', v_client,
      'client_phone', v_phone,
      'date', CURRENT_DATE,
      'created_by', v_actor,
      'total_amount', (v_totals ->> 'grandTotal')::numeric,
      'table_number', v_tbl.table_name,
      'pos_table_id', v_tbl.table_id,
      'catalog_sales_type_id', v_st.sales_type_id,
      'checkout_subtotal', (v_totals ->> 'subtotal')::numeric,
      'checkout_tax_amount', (v_totals ->> 'taxTotal')::numeric,
      'checkout_gratuity_amount', (v_totals ->> 'gratuityTotal')::numeric,
      'checkout_application_method', v_totals ->> 'applicationMethod',
      'checkout_discount_amount', 0,
      'description', CASE
        WHEN v_note IS NULL THEN 'Synckerja Order'
        ELSE 'Synckerja Order: ' || v_note
      END
    ),
    'items', v_items,
    'modifiers', v_mods,
    'discounts', '[]'::jsonb,
    'catalogStockLines', '[]'::jsonb,
    'checkoutTotals', v_totals,
    'cart', v_cart,
    'sessionId', v_session,
    'keepSessionOpen', true,
    'remainderCartLines', '[]'::jsonb
  );

  IF v_reuse_pending THEN
    UPDATE public.pos_pending_checkouts
    SET
      payload = v_payload,
      expires_at = now() + interval '4 hours',
      updated_at = now()
    WHERE id = v_pending;
  ELSE
    INSERT INTO public.pos_pending_checkouts (
      organization_id, pos_outlet_id, status, payload, session_id,
      keep_session_open, expires_at, created_by, checkout_channel, claim_token
    ) VALUES (
      v_out.organization_id, v_out.outlet_id, 'pending', v_payload, v_session,
      true, now() + interval '4 hours', v_actor, 'synckerja_cashier', v_token
    ) RETURNING id INTO v_pending;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pending_checkout_id', v_pending,
    'session_id', v_session,
    'claim_token', v_token,
    'grand_total', (v_totals ->> 'grandTotal')::numeric,
    'expires_at', (now() + interval '4 hours'),
    'updated_in_place', v_reuse_pending,
    'fulfillment', v_st.fulfillment,
    'sales_type_label', v_st.sales_type_name
  );
END;
$$;


ALTER FUNCTION "public"."submit_synckerja_order_pay_at_cashier"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text", "p_guest_email" "text", "p_bill_note" "text", "p_fulfillment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_synckerja_order_pay_later"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text" DEFAULT NULL::"text", "p_guest_email" "text" DEFAULT NULL::"text", "p_bill_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_out record;
  v_tbl record;
  v_cart jsonb;
  v_session uuid;
  v_st_id uuid;
  v_st_name text := 'Dine In';
  v_hours jsonb;
  v_phone text;
  v_note text;
BEGIN
  SELECT * INTO v_out FROM public._synckerja_order_resolve_outlet(p_code);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  v_hours := public._synckerja_order_hours_state(v_out.outlet_id);
  IF NOT COALESCE((v_hours ->> 'is_open')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'store_closed');
  END IF;
  SELECT * INTO v_tbl FROM public._synckerja_order_table_state(v_out.organization_id, v_out.outlet_id, p_table_name);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_not_found');
  END IF;
  IF v_tbl.join_state = 'full' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'table_full');
  END IF;
  v_cart := public._synckerja_order_sanitize_cart(v_out.organization_id, v_out.outlet_id, p_cart);
  IF jsonb_array_length(v_cart) < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'empty_cart');
  END IF;
  v_phone := NULLIF(left(btrim(COALESCE(p_guest_phone, '')), 32), '');
  v_note := NULLIF(left(btrim(COALESCE(p_bill_note, '')), 500), '');
  SELECT st.id, st.name INTO v_st_id, v_st_name
  FROM public.catalog_sales_types st
  WHERE st.organization_id = v_out.organization_id AND st.is_active AND lower(st.name) LIKE '%dine%'
  ORDER BY st.sort_order LIMIT 1;

  IF v_tbl.join_state = 'join' AND v_tbl.open_session_id IS NOT NULL THEN
    UPDATE public.pos_table_sessions
    SET
      cart_snapshot = COALESCE(cart_snapshot, '[]'::jsonb) || v_cart,
      pax = pax + 1,
      customer_name = COALESCE(NULLIF(btrim(customer_name), ''), NULLIF(btrim(COALESCE(p_guest_name, '')), '')),
      customer_phone = COALESCE(NULLIF(btrim(customer_phone), ''), v_phone),
      guest_note = COALESCE(v_note, guest_note)
    WHERE id = v_tbl.open_session_id
      AND organization_id = v_out.organization_id
      AND outlet_id = v_out.outlet_id
      AND status = 'open'
    RETURNING id INTO v_session;
  ELSE
    INSERT INTO public.pos_table_sessions (
      organization_id, outlet_id, group_id, pos_table_id, table_name, pax,
      status, cart_snapshot, customer_name, customer_phone, guest_note
    ) VALUES (
      v_out.organization_id, v_out.outlet_id, v_tbl.group_id, v_tbl.table_id, v_tbl.table_name, 1,
      'open', v_cart, NULLIF(btrim(COALESCE(p_guest_name, '')), ''), v_phone, v_note
    ) RETURNING id INTO v_session;
  END IF;

  PERFORM public._synckerja_order_fire_kitchen(
    v_out.organization_id, v_out.outlet_id, v_session, v_tbl.table_id, v_tbl.table_name,
    p_guest_name, v_cart, 'save_bill', COALESCE(v_st_name, 'Dine In'), v_st_id
  );
  RETURN jsonb_build_object('ok', true, 'session_id', v_session);
END;
$$;


ALTER FUNCTION "public"."submit_synckerja_order_pay_later"("p_code" "text", "p_table_name" "text", "p_guest_name" "text", "p_cart" "jsonb", "p_guest_phone" "text", "p_guest_email" "text", "p_bill_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_analytics_web_access_for_web_id"("p_organization_id" "uuid", "p_web_id" "text", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_web_id text := lower(trim(p_web_id));
  v_has_active_sdk boolean;
BEGIN
  IF v_web_id IS NULL OR length(v_web_id) = 0 THEN
    RAISE EXCEPTION 'web_id wajib diisi.';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.organization_omnichannel_api_tokens t
    WHERE t.organization_id = p_organization_id
      AND t.web_id = v_web_id
      AND t.token_type = 'sdk'
      AND t.is_active = true
      AND (t.expires_at IS NULL OR t.expires_at > now())
  ) INTO v_has_active_sdk;

  IF v_has_active_sdk THEN
    INSERT INTO public.analytics_web_access (organization_id, web_id, created_by, is_approved)
    VALUES (p_organization_id, v_web_id, p_created_by, true)
    ON CONFLICT (organization_id, web_id) DO UPDATE SET
      is_approved = true;
  ELSE
    UPDATE public.analytics_web_access
    SET is_approved = false
    WHERE organization_id = p_organization_id
      AND web_id = v_web_id;
  END IF;
END;
$$;


ALTER FUNCTION "public"."sync_analytics_web_access_for_web_id"("p_organization_id" "uuid", "p_web_id" "text", "p_created_by" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_analytics_web_access_for_web_id"("p_organization_id" "uuid", "p_web_id" "text", "p_created_by" "uuid") IS 'Sets analytics_web_access.is_approved true when org has an active non-expired SDK token for web_id; otherwise false.';



CREATE OR REPLACE FUNCTION "public"."sync_auth_email_on_token_verified"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
BEGIN
  IF NEW.email_verified IS TRUE AND (OLD.email_verified IS DISTINCT FROM TRUE) THEN
    UPDATE auth.users
    SET email_confirmed_at = COALESCE(email_confirmed_at, now())
    WHERE id = NEW.user_id;
  END IF;
  RETURN NEW;
END;
$$;


