CREATE OR REPLACE FUNCTION "public"."sync_catalog_po_purchase_request"("p_purchase_order_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_outlet_name text;
  v_supplier_name text;
  v_bank_code text;
  v_bank_number text;
  v_bank_holder text;
  v_title text;
  v_description text;
  v_lines text;
  v_purchase_type text;
  v_class record;
  v_actor text;
  v_uid uuid;
  v_qty_sum numeric;
  v_pr_id uuid;
  v_existing public.purchase_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_po
  FROM public.catalog_purchase_orders
  WHERE id = p_purchase_order_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found';
  END IF;

  SELECT NULLIF(btrim(o.name), '') INTO v_outlet_name
  FROM public.pos_outlets o
  WHERE o.id = v_po.outlet_id;

  SELECT
    NULLIF(btrim(s.name), ''),
    NULLIF(btrim(s.bank_code), ''),
    NULLIF(btrim(s.bank_account_number), ''),
    NULLIF(btrim(s.bank_account_holder), '')
  INTO v_supplier_name, v_bank_code, v_bank_number, v_bank_holder
  FROM public.catalog_suppliers s
  WHERE s.id = v_po.supplier_id;

  SELECT string_agg(
    COALESCE(NULLIF(btrim(l.name_snapshot), ''), '—')
      || ' × '
      || COALESCE(public.catalog_po_format_qty(l.qty), l.qty::text)
      || ' @ '
      || public.catalog_po_format_idr(l.unit_cost),
    E'\n'
    ORDER BY l.created_at
  ), COALESCE(SUM(l.qty), 0)
  INTO v_lines, v_qty_sum
  FROM public.catalog_purchase_order_lines l
  WHERE l.purchase_order_id = v_po.id;

  v_title := 'PO ' || v_po.order_number || ' — ' || COALESCE(v_outlet_name, 'Outlet');
  v_description := concat_ws(
    E'\n\n',
    NULLIF(btrim(v_po.note), ''),
    'Outlet: ' || COALESCE(v_outlet_name, '—'),
    COALESCE(v_lines, '—')
  );
  v_purchase_type := CASE WHEN v_po.item_kind = 'product' THEN 'Inventory Item' ELSE 'Inventory' END;

  SELECT * INTO v_class
  FROM public.resolve_inventory_po_expense_classification(v_po.organization_id, v_po.item_kind);

  v_uid := auth.uid();
  v_actor := COALESCE(public.catalog_po_actor_name(v_po.organization_id), 'UNKNOWN');

  SELECT * INTO v_existing
  FROM public.purchase_requests
  WHERE catalog_purchase_order_id = v_po.id
  FOR UPDATE;

  IF FOUND THEN
    IF public.catalog_po_is_paid(v_existing.status, v_existing.payment_status, v_existing.paid_at) THEN
      RAISE EXCEPTION 'catalog_po_already_paid';
    END IF;
    IF v_existing.status = 'approved' THEN
      RAISE EXCEPTION 'catalog_po_already_approved';
    END IF;

    UPDATE public.purchase_requests
    SET
      request_title = v_title,
      amount_idr = v_po.total_value,
      quantity = GREATEST(1, ROUND(v_qty_sum)::integer),
      description = v_description,
      vendor_name = v_supplier_name,
      vendor_bank_code = v_bank_code,
      vendor_bank_account_number = v_bank_number,
      vendor_bank_account_holder = v_bank_holder,
      purchase_type = v_purchase_type,
      expense_type_id = v_class.expense_type_id,
      expense_category_id = v_class.expense_category_id,
      updated_at = now()
    WHERE id = v_existing.id;

    RETURN v_existing.id;
  END IF;

  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;

  INSERT INTO public.purchase_requests (
    organization_id,
    requester_id,
    requester_name,
    department_name,
    request_type,
    purchase_type,
    request_title,
    amount_idr,
    quantity,
    is_recurring,
    description,
    company_benefit,
    vendor_name,
    vendor_bank_code,
    vendor_bank_account_number,
    vendor_bank_account_holder,
    status,
    submitted_at,
    created_by,
    expense_type_id,
    expense_category_id,
    payment_status,
    catalog_purchase_order_id
  ) VALUES (
    v_po.organization_id,
    v_uid,
    v_actor,
    NULL,
    'purchase',
    v_purchase_type,
    v_title,
    v_po.total_value,
    GREATEST(1, ROUND(v_qty_sum)::integer),
    false,
    v_description,
    'Inventory restock for ' || COALESCE(v_outlet_name, 'outlet'),
    v_supplier_name,
    v_bank_code,
    v_bank_number,
    v_bank_holder,
    'submitted',
    now(),
    v_uid,
    v_class.expense_type_id,
    v_class.expense_category_id,
    'pending',
    v_po.id
  )
  RETURNING id INTO v_pr_id;

  RETURN v_pr_id;
END;
$$;


ALTER FUNCTION "public"."sync_catalog_po_purchase_request"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_conversation_last_message"("p_conversation_id" "uuid") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  UPDATE public.whatsapp_conversations c
  SET
    last_message_at = m.created_at,
    last_message_body = LEFT(m.body, 200),
    updated_at = NOW()
  FROM (
    SELECT conversation_id, created_at, body
    FROM public.whatsapp_messages
    WHERE conversation_id = p_conversation_id
    ORDER BY created_at DESC
    LIMIT 1
  ) m
  WHERE c.id = p_conversation_id AND c.id = m.conversation_id;
$$;


ALTER FUNCTION "public"."sync_conversation_last_message"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_conversion_thresholds_from_conversions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_post_id uuid;
  v_count numeric;
  r record;
BEGIN
  v_post_id := COALESCE(NEW.content_post_id, OLD.content_post_id);
  IF v_post_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  SELECT COUNT(*)::numeric INTO v_count
  FROM public.kol_conversions
  WHERE content_post_id = v_post_id;

  UPDATE public.kol_performance_thresholds
  SET current_value = v_count, updated_at = timezone('utc'::text, now())
  WHERE kol_content_post_id = v_post_id
    AND metric_type = 'conversion'
    AND is_active IS NOT FALSE;

  FOR r IN
    SELECT DISTINCT payment_terms_id AS id
    FROM public.kol_performance_thresholds
    WHERE kol_content_post_id = v_post_id AND payment_terms_id IS NOT NULL
  LOOP
    PERFORM public.apply_performance_bonus(r.id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_conversion_thresholds_from_conversions"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_email_conv_status_to_lead"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ticket_id text;
BEGIN
  IF NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;
  v_ticket_id := 'EMAIL-' || UPPER(SUBSTRING(REPLACE(NEW.id::text, '-', ''), 1, 8));

  UPDATE public.leads
  SET
    status_id = NEW.lead_status_id,
    updated_at = now()
  WHERE
    organization_id = NEW.organization_id
    AND ticket_id IS NOT NULL
    AND TRIM(ticket_id) <> ''
    AND (ticket_id = v_ticket_id OR UPPER(TRIM(ticket_id)) = v_ticket_id);

  RETURN NEW;
END;
$$;


