CREATE OR REPLACE FUNCTION "public"."sync_payment_milestones"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  elem jsonb;
  ord integer := 1;
BEGIN
  IF tg_op = 'UPDATE' AND NEW.milestones IS NOT DISTINCT FROM OLD.milestones THEN
    RETURN NEW;
  END IF;

  IF NEW.milestones IS NULL
     OR jsonb_typeof(NEW.milestones) <> 'array'
     OR jsonb_array_length(NEW.milestones) = 0 THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('kol.suppress_milestone_status_sync', 'on', true);

  DELETE FROM public.payment_milestones
  WHERE payment_terms_id = NEW.id;

  FOR elem IN SELECT value FROM jsonb_array_elements(NEW.milestones) AS t(value)
  LOOP
    INSERT INTO public.payment_milestones (
      payment_terms_id,
      milestone_name,
      milestone_order,
      percentage,
      amount,
      due_date,
      milestone_description,
      status,
      trigger_condition
    )
    VALUES (
      NEW.id,
      COALESCE(NULLIF(trim(elem->>'name'), ''), NULLIF(trim(elem->>'milestone_name'), ''), 'Milestone'),
      COALESCE(NULLIF(elem->>'milestone_order', '')::integer, ord),
      COALESCE(NULLIF(elem->>'percentage', '')::numeric, 0),
      COALESCE(NULLIF(elem->>'amount', '')::numeric, 0),
      CASE
        WHEN NULLIF(trim(elem->>'due_date'), '') IS NULL THEN NULL
        ELSE NULLIF(trim(elem->>'due_date'), '')::date
      END,
      NULLIF(trim(elem->>'description'), ''),
      COALESCE(NULLIF(trim(elem->>'status'), ''), 'pending'),
      COALESCE(NULLIF(trim(elem->>'trigger_condition'), ''), 'manual')
    );
    ord := ord + 1;
  END LOOP;

  PERFORM set_config('kol.suppress_milestone_status_sync', 'off', true);
  PERFORM public.sync_payment_status_from_milestones(NEW.id);

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_payment_milestones"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_payment_status_from_milestones"("p_payment_terms_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pt public.kol_payment_terms%ROWTYPE;
  v_total int;
  v_paid int;
  v_pending int;
  v_down_payment numeric(15, 2);
  v_new_status text;
  v_remaining numeric(15, 2);
BEGIN
  SELECT * INTO v_pt FROM public.kol_payment_terms WHERE id = p_payment_terms_id;
  IF NOT FOUND OR v_pt.type <> 'agreement' THEN
    RETURN;
  END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE status = 'paid'), COUNT(*) FILTER (WHERE status <> 'paid')
  INTO v_total, v_paid, v_pending
  FROM public.payment_milestones
  WHERE payment_terms_id = p_payment_terms_id;

  IF v_total = 0 THEN
    RETURN;
  END IF;

  SELECT COALESCE(SUM(amount) FILTER (WHERE status = 'paid' AND (milestone_order = 1 OR milestone_name ILIKE '%dp%' OR milestone_name ILIKE '%down%')), 0)
  INTO v_down_payment
  FROM public.payment_milestones
  WHERE payment_terms_id = p_payment_terms_id;

  IF v_paid = 0 THEN
    v_new_status := 'draft';
    v_down_payment := 0;
  ELSIF v_paid = v_total THEN
    v_new_status := 'paid';
  ELSIF v_paid > 0 AND v_pending > 0 THEN
    v_new_status := CASE WHEN v_down_payment > 0 THEN 'partial_paid' ELSE 'dp_paid' END;
  ELSE
    v_new_status := v_pt.status;
  END IF;

  v_remaining := GREATEST(
    COALESCE(v_pt.base_amount, 0) + COALESCE(v_pt.bonus_amount, 0) - v_down_payment - COALESCE(v_pt.deduction_amount, 0),
    0
  );

  PERFORM set_config('kol.suppress_agreement_milestone_sync', 'on', true);

  UPDATE public.kol_payment_terms
  SET
    status = v_new_status,
    down_payment_amount = CASE WHEN v_down_payment > 0 THEN v_down_payment WHEN v_paid = 0 THEN 0 ELSE down_payment_amount END,
    down_payment_date = CASE
      WHEN v_down_payment > 0 AND down_payment_date IS NULL THEN CURRENT_DATE
      WHEN v_paid = 0 THEN NULL
      ELSE down_payment_date
    END,
    remaining_amount = v_remaining,
    final_payment_date = CASE WHEN v_new_status = 'paid' AND final_payment_date IS NULL THEN CURRENT_DATE ELSE final_payment_date END,
    updated_at = timezone('utc'::text, now())
  WHERE id = p_payment_terms_id
    AND (
      status IS DISTINCT FROM v_new_status
      OR down_payment_amount IS DISTINCT FROM CASE WHEN v_down_payment > 0 THEN v_down_payment WHEN v_paid = 0 THEN 0 ELSE down_payment_amount END
      OR remaining_amount IS DISTINCT FROM v_remaining
    );

  PERFORM set_config('kol.suppress_agreement_milestone_sync', 'off', true);

  IF v_pt.campaign_id IS NOT NULL AND v_pt.kol_profile_id IS NOT NULL THEN
    PERFORM public.refresh_budget_allocation_payout(v_pt.campaign_id, v_pt.kol_profile_id);
  END IF;
END;
$$;


ALTER FUNCTION "public"."sync_payment_status_from_milestones"("p_payment_terms_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_performance_thresholds_from_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_engagement numeric;
  v_conversion_count numeric;
  r record;
BEGIN
  v_engagement := CASE
    WHEN COALESCE(NEW.impressions, 0) > 0 AND COALESCE(NEW.engagement_rate, 0) > 0
      THEN (NEW.impressions::numeric * NEW.engagement_rate::numeric) / 100
    ELSE COALESCE(NEW.likes, 0) + COALESCE(NEW.comments, 0) + COALESCE(NEW.shares, 0)
  END;

  SELECT COUNT(*)::numeric
  INTO v_conversion_count
  FROM public.kol_conversions
  WHERE content_post_id = NEW.content_post_id;

  UPDATE public.kol_performance_thresholds
  SET current_value = COALESCE(NEW.reach, 0), updated_at = timezone('utc'::text, now())
  WHERE kol_content_post_id = NEW.content_post_id AND metric_type = 'reach' AND is_active IS NOT FALSE;

  UPDATE public.kol_performance_thresholds
  SET current_value = v_engagement, updated_at = timezone('utc'::text, now())
  WHERE kol_content_post_id = NEW.content_post_id AND metric_type = 'engagement' AND is_active IS NOT FALSE;

  UPDATE public.kol_performance_thresholds
  SET current_value = v_conversion_count, updated_at = timezone('utc'::text, now())
  WHERE kol_content_post_id = NEW.content_post_id AND metric_type = 'conversion' AND is_active IS NOT FALSE;

  FOR r IN
    SELECT DISTINCT payment_terms_id AS id
    FROM public.kol_performance_thresholds
    WHERE kol_content_post_id = NEW.content_post_id AND payment_terms_id IS NOT NULL
  LOOP
    PERFORM public.apply_performance_bonus(r.id);
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_performance_thresholds_from_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_pos_receipt_feedback_item_attributions"("p_response_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_resp public.pos_receipt_feedback_responses%ROWTYPE;
  v_inserted integer := 0;
BEGIN
  IF p_response_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT * INTO v_resp
  FROM public.pos_receipt_feedback_responses
  WHERE id = p_response_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  WITH line_items AS (
    SELECT DISTINCT ON (catalog_item_id)
      catalog_item_id,
      item_kind
    FROM (
      SELECT
        sai.catalog_product_id AS catalog_item_id,
        'product'::text AS item_kind
      FROM public.sales_activity_items sai
      WHERE sai.sales_activity_id = v_resp.sales_activity_id
        AND sai.catalog_product_id IS NOT NULL
        AND sai.catalog_bundle_id IS NULL
      UNION ALL
      SELECT
        sai.catalog_bundle_id AS catalog_item_id,
        'bundle'::text AS item_kind
      FROM public.sales_activity_items sai
      WHERE sai.sales_activity_id = v_resp.sales_activity_id
        AND sai.catalog_bundle_id IS NOT NULL
    ) x
    WHERE catalog_item_id IS NOT NULL
    ORDER BY catalog_item_id, item_kind
  ),
  upserted AS (
    INSERT INTO public.pos_receipt_feedback_item_attributions (
      organization_id,
      pos_outlet_id,
      response_id,
      sales_activity_id,
      catalog_item_id,
      item_kind,
      rating,
      comment,
      submitted_at
    )
    SELECT
      v_resp.organization_id,
      v_resp.pos_outlet_id,
      v_resp.id,
      v_resp.sales_activity_id,
      li.catalog_item_id,
      li.item_kind,
      v_resp.rating,
      v_resp.comment,
      v_resp.submitted_at
    FROM line_items li
    ON CONFLICT (response_id, catalog_item_id) DO UPDATE
      SET
        rating = EXCLUDED.rating,
        comment = EXCLUDED.comment,
        submitted_at = EXCLUDED.submitted_at,
        pos_outlet_id = EXCLUDED.pos_outlet_id,
        item_kind = EXCLUDED.item_kind
    RETURNING 1
  )
  SELECT COUNT(*)::integer INTO v_inserted FROM upserted;

  RETURN COALESCE(v_inserted, 0);
END;
$$;


ALTER FUNCTION "public"."sync_pos_receipt_feedback_item_attributions"("p_response_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_task_steps_has_substeps"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_parent uuid;
BEGIN
  v_parent := COALESCE(NEW.parent_step_id, OLD.parent_step_id);

  UPDATE public.task_steps ts
  SET has_substeps = EXISTS (
    SELECT 1 FROM public.task_steps_to_steps tsts
    WHERE tsts.parent_step_id = v_parent
  )
  WHERE ts.id = v_parent;

  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."sync_task_steps_has_substeps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_threshold_rows_from_payment_terms"("p_payment_terms_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_pt public.kol_payment_terms%ROWTYPE;
  v_json jsonb;
  v_key text;
  v_val jsonb;
  v_metric text;
  v_target numeric;
  v_bonus numeric;
  v_nested boolean := false;
BEGIN
  SELECT * INTO v_pt FROM public.kol_payment_terms WHERE id = p_payment_terms_id;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_json := COALESCE(v_pt.performance_thresholds, '{}'::jsonb);
  IF v_json = '{}'::jsonb OR v_json = '[]'::jsonb THEN
    RETURN;
  END IF;

  DELETE FROM public.kol_performance_thresholds
  WHERE payment_terms_id = p_payment_terms_id;

  IF jsonb_typeof(v_json) = 'array' THEN
    FOR v_val IN SELECT value FROM jsonb_array_elements(v_json)
    LOOP
      v_metric := lower(COALESCE(v_val->>'metric', ''));
      IF v_metric = 'conversions' THEN v_metric := 'conversion'; END IF;
      v_target := (v_val->>'threshold')::numeric;
      v_bonus := COALESCE((v_val->>'bonus_percentage')::numeric, 0);
      IF v_metric <> '' AND v_target IS NOT NULL AND v_target > 0 THEN
        INSERT INTO public.kol_performance_thresholds (
          organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id,
          metric_type, target_value, bonus_percentage, is_active
        ) VALUES (
          v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id,
          v_metric, v_target, v_bonus, true
        );
      END IF;
    END LOOP;
    RETURN;
  END IF;

  FOR v_key, v_val IN SELECT key, value FROM jsonb_each(v_json)
  LOOP
    IF jsonb_typeof(v_val) = 'object' AND v_val ? 'threshold' THEN
      v_nested := true;
      v_metric := lower(v_key);
      IF v_metric = 'conversions' THEN v_metric := 'conversion'; END IF;
      v_target := (v_val->>'threshold')::numeric;
      v_bonus := COALESCE((v_val->>'bonus_percentage')::numeric, 0);
      IF v_metric <> '' AND v_target IS NOT NULL AND v_target > 0 THEN
        INSERT INTO public.kol_performance_thresholds (
          organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id,
          metric_type, target_value, bonus_percentage, is_active
        ) VALUES (
          v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id,
          v_metric, v_target, v_bonus, true
        );
      END IF;
    END IF;
  END LOOP;

  IF v_nested THEN
    RETURN;
  END IF;

  IF v_json ? 'target_reach' AND (v_json->>'target_reach')::numeric > 0 THEN
    INSERT INTO public.kol_performance_thresholds (organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id, metric_type, target_value, bonus_percentage, is_active)
    VALUES (v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id, 'reach', (v_json->>'target_reach')::numeric, COALESCE((v_json->>'reach_bonus_percentage')::numeric, 0), true);
  END IF;
  IF v_json ? 'target_engagement' AND (v_json->>'target_engagement')::numeric > 0 THEN
    INSERT INTO public.kol_performance_thresholds (organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id, metric_type, target_value, bonus_percentage, is_active)
    VALUES (v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id, 'engagement', (v_json->>'target_engagement')::numeric, COALESCE((v_json->>'engagement_bonus_percentage')::numeric, 0), true);
  END IF;
  IF (v_json ? 'target_conversion' OR v_json ? 'target_conversions') THEN
    v_target := COALESCE((v_json->>'target_conversion')::numeric, (v_json->>'target_conversions')::numeric);
    IF v_target > 0 THEN
      INSERT INTO public.kol_performance_thresholds (organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id, metric_type, target_value, bonus_percentage, is_active)
      VALUES (v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id, 'conversion', v_target, COALESCE((v_json->>'conversion_bonus_percentage')::numeric, 0), true);
    END IF;
  END IF;
  IF v_json ? 'target_views' AND (v_json->>'target_views')::numeric > 0 THEN
    INSERT INTO public.kol_performance_thresholds (organization_id, payment_terms_id, kol_content_post_id, kol_profile_id, campaign_id, metric_type, target_value, bonus_percentage, is_active)
    VALUES (v_pt.organization_id, v_pt.id, v_pt.kol_content_post_id, v_pt.kol_profile_id, v_pt.campaign_id, 'views', (v_json->>'target_views')::numeric, COALESCE((v_json->>'views_bonus_percentage')::numeric, 0), true);
  END IF;
END;
$$;


ALTER FUNCTION "public"."sync_threshold_rows_from_payment_terms"("p_payment_terms_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_wa_conv_status_to_lead"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ticket_id text;
BEGIN
  -- Use conversation ticket_id (generated column for WA is always set)
  v_ticket_id := COALESCE(TRIM(NEW.ticket_id), '');
  IF v_ticket_id = '' OR NEW.organization_id IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.leads
  SET
    status_id = NEW.lead_status_id,
    assignee_id = NEW.assignee_id,
    updated_at = now()
  WHERE
    organization_id = NEW.organization_id
    AND ticket_id IS NOT NULL
    AND TRIM(ticket_id) <> ''
    AND (ticket_id = v_ticket_id OR UPPER(TRIM(ticket_id)) = UPPER(v_ticket_id));

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_wa_conv_status_to_lead"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."sync_wa_conv_status_to_lead"() IS 'Syncs lead_status_id and assignee_id from whatsapp_conversations to leads by ticket_id so leads-management table stays in sync with quick action.';



