    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
  SELECT COALESCE(cardinality(paths), 0) <= 8
    AND NOT EXISTS (
      SELECT 1
      FROM unnest(COALESCE(paths, ARRAY[]::text[])) AS item
      WHERE item IS NULL
        OR char_length(btrim(item)) < 1
        OR char_length(item) > 500
    );
$$;


