CREATE OR REPLACE FUNCTION "public"."synckerja_order_sync_outlet_cover_paths"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.cover_paths IS NULL THEN
    NEW.cover_paths := '{}';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF cardinality(NEW.cover_paths) > 0 THEN
      NEW.cover_path := NULLIF(btrim(NEW.cover_paths[1]), '');
    ELSIF NULLIF(btrim(NEW.cover_path), '') IS NOT NULL THEN
      NEW.cover_paths := ARRAY[btrim(NEW.cover_path)];
      NEW.cover_path := btrim(NEW.cover_path);
    ELSE
      NEW.cover_paths := '{}';
      NEW.cover_path := NULL;
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.cover_paths IS DISTINCT FROM OLD.cover_paths THEN
    NEW.cover_path := NULLIF(btrim(NEW.cover_paths[1]), '');
  ELSIF NEW.cover_path IS DISTINCT FROM OLD.cover_path THEN
    IF NULLIF(btrim(NEW.cover_path), '') IS NULL THEN
      NEW.cover_paths := '{}';
      NEW.cover_path := NULL;
    ELSE
      NEW.cover_paths := ARRAY[btrim(NEW.cover_path)];
      NEW.cover_path := btrim(NEW.cover_path);
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."synckerja_order_sync_outlet_cover_paths"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."task_files_storage_can_write"("p_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE (storage.foldername(p_name))[1]
    WHEN 'task-files' THEN EXISTS (
      SELECT 1
      FROM public.daily_tasks dt
      WHERE dt.id::text = (storage.foldername(p_name))[2]
        AND dt.organization_id IN (SELECT public.user_organization_ids())
    )
    WHEN 'task-step-files' THEN EXISTS (
      SELECT 1
      FROM public.task_steps ts
      JOIN public.daily_tasks dt ON dt.id = ts.task_id
      WHERE ts.id::text = (storage.foldername(p_name))[2]
        AND dt.organization_id IN (SELECT public.user_organization_ids())
    )
    WHEN 'task-step-description-images' THEN (
      CASE
        WHEN (storage.foldername(p_name))[2] LIKE 'org-%'
          AND (storage.foldername(p_name))[3] = 'pending' THEN
          substring((storage.foldername(p_name))[2] FROM 5)::uuid
            IN (SELECT public.user_organization_ids())
        ELSE EXISTS (
          SELECT 1
          FROM public.task_steps ts
          JOIN public.daily_tasks dt ON dt.id = ts.task_id
          WHERE ts.id::text = (storage.foldername(p_name))[2]
            AND dt.organization_id IN (SELECT public.user_organization_ids())
        )
      END
    )
    ELSE EXISTS (
      SELECT 1
      FROM public.task_steps ts
      JOIN public.daily_tasks dt ON dt.id = ts.task_id
      WHERE ts.id::text = (storage.foldername(p_name))[1]
        AND dt.organization_id IN (SELECT public.user_organization_ids())
    )
  END;
$$;


