CREATE OR REPLACE FUNCTION "public"."track_lead_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  old_name text;
  new_name text;
  v_actor uuid;
BEGIN
  IF TG_OP = 'UPDATE' AND (OLD.status_id IS DISTINCT FROM NEW.status_id) THEN
    SELECT name INTO old_name FROM public.lead_statuses WHERE id = OLD.status_id;
    SELECT name INTO new_name FROM public.lead_statuses WHERE id = NEW.status_id;
    v_actor := auth.uid();
    IF v_actor IS NULL AND auth.role() = 'service_role' THEN
      BEGIN
        v_actor := NULLIF(current_setting('mcp.actor_user_id', true), '')::uuid;
      EXCEPTION
        WHEN invalid_text_representation THEN
          v_actor := NULL;
      END;
    END IF;
    INSERT INTO public.lead_status_history (
      lead_id,
      old_status,
      new_status,
      organization_id,
      changed_by
    ) VALUES (
      NEW.id,
      old_name,
      COALESCE(new_name, ''),
      NEW.organization_id,
      v_actor
    );
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."track_lead_status_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."traffic_active_page_view_at"("p_session_id" "uuid", "p_at" timestamp with time zone) RETURNS TABLE("page_view_id" "uuid", "path" "text", "started_at" timestamp with time zone)
    LANGUAGE "sql" STABLE PARALLEL SAFE
    SET "search_path" TO 'public'
    AS $$
  SELECT
    pv.id AS page_view_id,
    pv.path,
    pv.started_at
  FROM public.analytics_page_views pv
  WHERE pv.session_id = p_session_id
    AND pv.started_at <= p_at
  ORDER BY pv.started_at DESC
  LIMIT 1;
$$;


