COMMENT ON FUNCTION "public"."traffic_classify_session_source_key"("p_first_utm_source" "text", "p_utm_source" "text", "p_last_utm_source" "text", "p_first_utm_medium" "text", "p_utm_medium" "text", "p_last_utm_medium" "text", "p_first_utm_campaign" "text", "p_utm_campaign" "text", "p_last_utm_campaign" "text", "p_first_utm_content" "text", "p_utm_content" "text", "p_last_utm_content" "text", "p_first_utm_term" "text", "p_utm_term" "text", "p_last_utm_term" "text", "p_first_landing_url" "text", "p_landing_url" "text", "p_last_landing_url" "text", "p_has_gclid" boolean, "p_first_has_gclid" boolean, "p_last_has_gclid" boolean, "p_has_fbclid" boolean, "p_first_has_fbclid" boolean, "p_last_has_fbclid" boolean, "p_has_msclkid" boolean, "p_has_gbraid" boolean, "p_has_wbraid" boolean, "p_first_referrer" "text", "p_referrer" "text", "p_last_referrer" "text") IS 'Classify analytics session source using first-touch UTM / click IDs (SPA-safe).';



