COMMENT ON FUNCTION "public"."traffic_normalize_route_path"("p_path" "text") IS 'Alias for traffic_path_key; canonical route path for click/page attribution.';



CREATE OR REPLACE FUNCTION "public"."traffic_path_key"("p" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  t text;
BEGIN
  IF p IS NULL THEN
    RETURN NULL;
  END IF;
  t := btrim(LOWER(p));
  IF t = '' OR t = '/' THEN
    RETURN '/';
  END IF;
  t := btrim(t, E'/');
  IF t = '' THEN
    RETURN '/';
  END IF;
  IF left(t, 1) = '/' THEN
    RETURN t;
  END IF;
  RETURN '/' || t;
END;
$$;


ALTER FUNCTION "public"."traffic_path_key"("p" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."traffic_path_key"("p" "text") IS 'Canonical path key for matching analytics daily rollup rows to raw analytics_page_views.';



CREATE OR REPLACE FUNCTION "public"."traffic_resolve_query_date_bounds"("p_web_id" "text", "p_from" "date", "p_to" "date") RETURNS TABLE("resolved_from" "date", "resolved_to" "date", "has_bounds" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  agg_min date;
  agg_max date;
  raw_min date;
  raw_max date;
  v_from date;
  v_to date;
BEGIN
  IF p_web_id IS NULL OR trim(p_web_id) = '' THEN
    resolved_from := NULL;
    resolved_to := NULL;
    has_bounds := false;
    RETURN NEXT;
    RETURN;
  END IF;

  IF p_from IS NOT NULL AND p_to IS NOT NULL THEN
    IF p_to < p_from THEN
      resolved_from := NULL;
      resolved_to := NULL;
      has_bounds := false;
    ELSE
      resolved_from := p_from;
      resolved_to := p_to;
      has_bounds := true;
    END IF;
    RETURN NEXT;
    RETURN;
  END IF;

  SELECT MIN(day), MAX(day)
  INTO agg_min, agg_max
  FROM public.analytics_daily_sessions
  WHERE web_id = p_web_id;

  SELECT
    LEAST(
      (SELECT MIN((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MIN((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    ),
    GREATEST(
      (SELECT MAX((timezone('Asia/Jakarta', s.started_at))::date) FROM public.analytics_sessions s WHERE s.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', pv.started_at))::date) FROM public.analytics_page_views pv WHERE pv.web_id = p_web_id),
      (SELECT MAX((timezone('Asia/Jakarta', ce.created_at))::date) FROM public.analytics_click_events ce WHERE ce.web_id = p_web_id)
    )
  INTO raw_min, raw_max;

  v_from := COALESCE(p_from, agg_min, raw_min);
  v_to := COALESCE(p_to, agg_max, raw_max);

  IF v_from IS NULL OR v_to IS NULL OR v_to < v_from THEN
    resolved_from := NULL;
    resolved_to := NULL;
    has_bounds := false;
  ELSE
    resolved_from := v_from;
    resolved_to := v_to;
    has_bounds := true;
  END IF;

  RETURN NEXT;
END;
$$;


ALTER FUNCTION "public"."traffic_resolve_query_date_bounds"("p_web_id" "text", "p_from" "date", "p_to" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."traffic_resolve_query_date_bounds"("p_web_id" "text", "p_from" "date", "p_to" "date") IS 'Resolve WIB date bounds for traffic RPCs; aggregate rollup first, then raw event fallback (matches dashboard hook).';



CREATE OR REPLACE FUNCTION "public"."traffic_session_has_paid_click_ids"("p_has_gclid" boolean, "p_first_has_gclid" boolean, "p_last_has_gclid" boolean, "p_has_fbclid" boolean, "p_first_has_fbclid" boolean, "p_last_has_fbclid" boolean, "p_has_msclkid" boolean, "p_has_gbraid" boolean, "p_has_wbraid" boolean) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT
    coalesce(p_has_gclid, false)
    OR coalesce(p_first_has_gclid, false)
    OR coalesce(p_last_has_gclid, false)
    OR coalesce(p_has_fbclid, false)
    OR coalesce(p_first_has_fbclid, false)
    OR coalesce(p_last_has_fbclid, false)
    OR coalesce(p_has_msclkid, false)
    OR coalesce(p_has_gbraid, false)
    OR coalesce(p_has_wbraid, false);
$$;


ALTER FUNCTION "public"."traffic_session_has_paid_click_ids"("p_has_gclid" boolean, "p_first_has_gclid" boolean, "p_last_has_gclid" boolean, "p_has_fbclid" boolean, "p_first_has_fbclid" boolean, "p_last_has_fbclid" boolean, "p_has_msclkid" boolean, "p_has_gbraid" boolean, "p_has_wbraid" boolean) OWNER TO "postgres";


