CREATE OR REPLACE FUNCTION "public"."transfer_ownership"("_to_user_id" "uuid", "_message" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  uid uuid := auth.uid();
  org_id uuid;
  new_id uuid;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  SELECT p.active_organization_id INTO org_id
  FROM public.profiles p
  WHERE p.user_id = uid;

  IF org_id IS NULL THEN
    RAISE EXCEPTION 'no active organization';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = uid
      AND ur.organization_id = org_id
      AND lower(ur.role) = 'owner'
  ) THEN
    RAISE EXCEPTION 'only organization owner can start a transfer';
  END IF;

  IF _to_user_id = uid THEN
    RAISE EXCEPTION 'cannot transfer ownership to yourself';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.user_organizations uo
    WHERE uo.user_id = _to_user_id
      AND uo.organization_id = org_id
      AND COALESCE(uo.is_active, true) = true
  ) THEN
    RAISE EXCEPTION 'target user is not an active member of this organization';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.ownership_transfers ot
    WHERE ot.from_user_id = uid
      AND ot.organization_id = org_id
      AND ot.status = 'pending'
  ) THEN
    RAISE EXCEPTION 'a pending transfer request already exists for this organization';
  END IF;

  INSERT INTO public.ownership_transfers (from_user_id, to_user_id, organization_id, message, status)
  VALUES (uid, _to_user_id, org_id, _message, 'pending')
  RETURNING id INTO new_id;

  RETURN new_id::text;
END;
$$;


ALTER FUNCTION "public"."transfer_ownership"("_to_user_id" "uuid", "_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_cancel_scheduled_posts_on_plan_gate_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_new_type text;
  v_photo boolean;
  v_story boolean;
  v_image_count integer;
  v_export_path text;
BEGIN
  SELECT name INTO v_new_type
  FROM public.content_types
  WHERE id = NEW.content_type_id;

  v_photo := lower(trim(coalesce(v_new_type, ''))) IN ('post', 'carousel');
  v_story := lower(trim(coalesce(v_new_type, ''))) = 'story';

  IF v_photo THEN
    SELECT count(*) INTO v_image_count
    FROM public.social_media_plan_carousel_images
    WHERE social_media_plan_id = NEW.id;

    IF NEW.approved IS DISTINCT FROM TRUE
      OR NEW.production_approved IS DISTINCT FROM TRUE
      OR NEW.post_date IS NULL
      OR v_image_count < 1
      OR v_image_count > 10
    THEN
      PERFORM public.cancel_social_media_scheduled_posts_for_plan(NEW.id, 'plan_gate_failed');
    END IF;
  ELSIF v_story THEN
    SELECT NULLIF(btrim(r.export_path), '')
    INTO v_export_path
    FROM public.canva_story_runs r
    WHERE r.social_media_plan_id = NEW.id
      AND r.images_ready IS TRUE
    LIMIT 1;

    IF NEW.approved IS DISTINCT FROM TRUE
      OR NEW.production_approved IS DISTINCT FROM TRUE
      OR NEW.post_date IS NULL
      OR v_export_path IS NULL
    THEN
      PERFORM public.cancel_social_media_scheduled_posts_for_plan(NEW.id, 'plan_gate_failed');
    END IF;
  ELSIF NEW.approved IS DISTINCT FROM TRUE
    OR NEW.production_approved IS DISTINCT FROM TRUE
    OR NEW.google_drive_link IS NULL
    OR trim(COALESCE(NEW.google_drive_link, '')) = ''
    OR NEW.post_date IS NULL
    OR v_new_type IS DISTINCT FROM 'Reel'
  THEN
    PERFORM public.cancel_social_media_scheduled_posts_for_plan(NEW.id, 'plan_gate_failed');
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_cancel_scheduled_posts_on_plan_gate_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_carousel_images_need_review_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan uuid;
BEGIN
  FOR v_plan IN
    SELECT DISTINCT inserted.social_media_plan_id
    FROM inserted
  LOOP
    IF EXISTS (
      SELECT 1
      FROM public.social_media_plans plan
      JOIN public.content_types content_type ON content_type.id = plan.content_type_id
      WHERE plan.id = v_plan
        AND content_type.name IN ('Post', 'Carousel')
        AND COALESCE(plan.production_approved, false) = false
        AND coalesce(btrim(plan.production_status), '') = ''
    ) AND NOT EXISTS (
      SELECT 1
      FROM public.social_media_production_notifications note
      WHERE note.social_media_plan_id = v_plan
        AND note.event_type = 'need_review'
    ) THEN
      PERFORM public.notify_pic_production_manager_need_review(v_plan);
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."trg_carousel_images_need_review_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_catalog_ingredient_outlets_inventory_alert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_enabled boolean := true;
  v_cross text;
  v_track boolean := false;
  v_name text;
  v_unit text;
  v_outlet_name text;
  v_txid bigint := txid_current();
BEGIN
  IF NEW.in_stock IS NOT DISTINCT FROM OLD.in_stock THEN
    RETURN NEW;
  END IF;

  IF public.inventory_alert_status_from_stock(
       NEW.in_stock, NEW.alert_enabled, NEW.alert_at
     ) IS NULL THEN
    DELETE FROM public.operational_inventory_alert_cooldown
    WHERE organization_id = NEW.organization_id
      AND outlet_id = NEW.outlet_id
      AND ingredient_id = NEW.ingredient_id;
    RETURN NEW;
  END IF;

  v_cross := public.did_cross_inventory_alert_threshold(
    OLD.in_stock,
    NEW.in_stock,
    NEW.alert_enabled,
    NEW.alert_at
  );
  IF v_cross IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(s.inventory_alerts_enabled, true) INTO v_enabled
  FROM public.operational_email_notification_settings s
  WHERE s.organization_id = NEW.organization_id;

  IF NOT COALESCE(v_enabled, true) THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(i.track_inventory, false), COALESCE(i.name, 'Ingredient'), COALESCE(i.unit_code, '')
  INTO v_track, v_name, v_unit
  FROM public.catalog_ingredients i
  WHERE i.id = NEW.ingredient_id;

  IF NOT v_track THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(o.name, 'Outlet') INTO v_outlet_name
  FROM public.pos_outlets o
  WHERE o.id = NEW.outlet_id;

  IF EXISTS (
    SELECT 1
    FROM public.operational_inventory_alert_cooldown c
    WHERE c.organization_id = NEW.organization_id
      AND c.outlet_id = NEW.outlet_id
      AND c.ingredient_id = NEW.ingredient_id
      AND c.status = v_cross
      AND c.sent_on_date = public.inventory_alert_wib_today()
  ) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.operational_inventory_alert_staging (
    txid,
    organization_id,
    outlet_id,
    ingredient_id,
    ingredient_name,
    unit,
    outlet_name,
    status,
    in_stock,
    alert_at
  )
  VALUES (
    v_txid,
    NEW.organization_id,
    NEW.outlet_id,
    NEW.ingredient_id,
    v_name,
    v_unit,
    COALESCE(v_outlet_name, 'Outlet'),
    v_cross,
    NEW.in_stock,
    NEW.alert_at
  );

  INSERT INTO public.operational_inventory_alert_tx_flush (txid)
  VALUES (v_txid)
  ON CONFLICT (txid) DO NOTHING;

  RETURN NEW;
END;
$$;


