CREATE OR REPLACE FUNCTION "public"."trg_daily_task_assignment_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  entity_type text := TG_ARGV[0];
  event_type text;
  org_id uuid;
  daily_task_id uuid;
  step_id uuid;
  sub_id uuid;
  assignment_row_id uuid;
  new_emp_id uuid;
  old_emp_id uuid;
  actor_emp_id uuid;
  actor_user_id uuid;
  recipient_user_id uuid;
  title text;
  due_date timestamptz;
  url text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    org_id := NEW.organization_id;
    assignment_row_id := NEW.id;
    new_emp_id := NEW.employee_id;
    actor_emp_id := NEW.assigned_by;
    event_type := 'assign';
  ELSIF TG_OP = 'DELETE' THEN
    org_id := OLD.organization_id;
    assignment_row_id := OLD.id;
    old_emp_id := OLD.employee_id;
    actor_emp_id := COALESCE(OLD.assigned_by, OLD.employee_id);
    event_type := 'unassign';
  ELSE
    RETURN COALESCE(NEW, OLD);
  END IF;

  actor_user_id := public.employee_user_id(actor_emp_id);

  IF entity_type = 'task' THEN
    daily_task_id := COALESCE(NEW.daily_task_id, OLD.daily_task_id);
    step_id := NULL;
    sub_id := NULL;
  ELSIF entity_type = 'step' THEN
    daily_task_id := NULL;
    step_id := COALESCE(NEW.task_step_id, OLD.task_step_id);
    sub_id := NULL;
  ELSE
    daily_task_id := NULL;
    step_id := NULL;
    sub_id := COALESCE(NEW.task_steps_to_steps_id, OLD.task_steps_to_steps_id);
  END IF;

  title := public.resolve_daily_task_entity_title(entity_type, daily_task_id, step_id, sub_id);
  due_date := public.resolve_assignment_due_date(entity_type, assignment_row_id);
  url := public.build_daily_task_deeplink(entity_type, daily_task_id, step_id, sub_id);

  -- Notify new assignee on INSERT
  IF TG_OP = 'INSERT' THEN
    recipient_user_id := public.employee_user_id(new_emp_id);
    IF recipient_user_id IS NOT NULL THEN
      -- Skip self-assign
      IF actor_user_id IS NULL OR actor_user_id <> recipient_user_id THEN
        PERFORM public.insert_daily_task_assignment_notification(
          recipient_user_id, org_id, event_type, entity_type,
          daily_task_id, step_id, sub_id,
          title, due_date, actor_user_id, url
        );
      END IF;
    END IF;
  END IF;

  -- Notify old assignee on DELETE (reassign/unassign signal)
  IF TG_OP = 'DELETE' THEN
    recipient_user_id := public.employee_user_id(old_emp_id);
    IF recipient_user_id IS NOT NULL THEN
      PERFORM public.insert_daily_task_assignment_notification(
        recipient_user_id, org_id, event_type, entity_type,
        daily_task_id, step_id, sub_id,
        title, due_date, actor_user_id, url
      );
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."trg_daily_task_assignment_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_daily_task_completed_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  assignee_emp uuid;
  assigner_emp uuid;
  assignee_user uuid;
  assigner_user uuid;
  title text;
  approval_id uuid;
  requires_approval boolean := false;
BEGIN
  IF TG_OP <> 'UPDATE' THEN RETURN NEW; END IF;
  IF COALESCE(OLD.status,'') = 'completed' OR COALESCE(NEW.status,'') <> 'completed' THEN
    RETURN NEW;
  END IF;

  SELECT a.assignee_employee_id, a.assigner_employee_id INTO assignee_emp, assigner_emp
  FROM public.latest_task_assignment(NEW.id) a;
  assignee_user := public.employee_user_id(assignee_emp);
  assigner_user := public.employee_user_id(assigner_emp);
  IF assigner_user IS NULL THEN RETURN NEW; END IF;

  title := COALESCE(NULLIF(trim(NEW.title),''),'Daily Task');
  approval_id := public.completion_pending_approval('task', NEW.id, NULL, NULL);
  requires_approval := approval_id IS NOT NULL;

  PERFORM public.insert_daily_task_completion_notification(
    assigner_user, NEW.organization_id, 'completed', 'task',
    NEW.id, NULL, NULL,
    assignee_user, assigner_user,
    title, requires_approval, approval_id, NULL
  );

  RETURN NEW;
END;
$$;


