CREATE OR REPLACE FUNCTION "public"."trg_enqueue_google_contacts_from_submissions"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    IF TG_OP = 'UPDATE'
       AND NEW.phone_number IS NOT DISTINCT FROM OLD.phone_number
       AND NEW.email IS NOT DISTINCT FROM OLD.email
       AND NEW.name IS NOT DISTINCT FROM OLD.name THEN
      RETURN NEW;
    END IF;

    SELECT l.organization_id INTO v_org
    FROM public.leads l
    WHERE l.id = NEW.lead_id;

    IF v_org IS NOT NULL THEN
      PERFORM public.enqueue_google_contacts_sync(
        v_org,
        NEW.lead_id,
        CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


