CREATE OR REPLACE FUNCTION "public"."trigger_sync_follow_up_priority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM sync_follow_up_priority_for_conversation(OLD.conversation_id);
    PERFORM sync_follow_up_priority_for_lead(OLD.lead_id);
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    PERFORM sync_follow_up_priority_for_conversation(NEW.conversation_id);
    PERFORM sync_follow_up_priority_for_lead(NEW.lead_id);
    RETURN NEW;
  ELSE
    PERFORM sync_follow_up_priority_for_conversation(NEW.conversation_id);
    PERFORM sync_follow_up_priority_for_conversation(OLD.conversation_id);
    PERFORM sync_follow_up_priority_for_lead(NEW.lead_id);
    PERFORM sync_follow_up_priority_for_lead(OLD.lead_id);
    RETURN NEW;
  END IF;
END;
$$;


ALTER FUNCTION "public"."trigger_sync_follow_up_priority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_sync_milestones_from_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF current_setting('kol.suppress_agreement_milestone_sync', true) = 'on' THEN
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status
    OR NEW.down_payment_amount IS DISTINCT FROM OLD.down_payment_amount THEN
    PERFORM public.sync_milestones_from_payment_status(NEW.id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_sync_milestones_from_payment_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trigger_sync_payment_status_from_milestones"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF current_setting('kol.suppress_milestone_status_sync', true) = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    PERFORM public.sync_payment_status_from_milestones(OLD.payment_terms_id);
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT'
    OR NEW.status IS DISTINCT FROM OLD.status
    OR NEW.amount IS DISTINCT FROM OLD.amount THEN
    PERFORM public.sync_payment_status_from_milestones(NEW.payment_terms_id);
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trigger_sync_payment_status_from_milestones"() OWNER TO "postgres";


