CREATE OR REPLACE FUNCTION "public"."try_acquire_social_media_publish_slot"("p_organization_id" "uuid", "p_platform" "text", "p_max_per_window" integer DEFAULT 3) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_new_count integer;
  v_max integer;
BEGIN
  v_max := GREATEST(1, LEAST(COALESCE(p_max_per_window, 3), 20));
  v_window_start := date_trunc('minute', now())
    - ((extract(minute from now())::integer % 5) * interval '1 minute');

  INSERT INTO public.social_media_publish_rate_windows AS w (
    organization_id,
    platform,
    window_start,
    publish_count
  )
  VALUES (p_organization_id, p_platform, v_window_start, 1)
  ON CONFLICT (organization_id, platform, window_start)
  DO UPDATE SET publish_count = w.publish_count + 1
  WHERE w.publish_count < v_max
  RETURNING w.publish_count INTO v_new_count;

  DELETE FROM public.social_media_publish_rate_windows
  WHERE window_start < now() - interval '2 hours';

  RETURN v_new_count IS NOT NULL;
END;
$$;


ALTER FUNCTION "public"."try_acquire_social_media_publish_slot"("p_organization_id" "uuid", "p_platform" "text", "p_max_per_window" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."try_acquire_social_media_publish_slot"("p_organization_id" "uuid", "p_platform" "text", "p_max_per_window" integer) IS 'Atomically increment org+platform publish counter for current 5-min window; false when at cap.';



CREATE OR REPLACE FUNCTION "public"."unlink_bank_account_brick"("p_bank_account_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid;
BEGIN
  SELECT organization_id INTO v_org
  FROM public.bank_accounts
  WHERE id = p_bank_account_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'bank_account_not_found';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(v_org) THEN
    RAISE EXCEPTION 'bank_brick_unlink_forbidden';
  END IF;

  UPDATE public.bank_accounts
  SET
    brick_account_id = NULL,
    brick_link_status = 'unlinked',
    brick_last_sync_error = NULL,
    bank_statement_balance = NULL,
    updated_at = now()
  WHERE id = p_bank_account_id;

  RETURN jsonb_build_object('ok', true, 'bank_account_id', p_bank_account_id);
END;
$$;


ALTER FUNCTION "public"."unlink_bank_account_brick"("p_bank_account_id" "uuid") OWNER TO "postgres";


