CREATE OR REPLACE FUNCTION "public"."update_campaign_budget_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_campaign_id uuid;
  v_total_allocated numeric(15, 2);
  v_campaign_budget numeric(15, 2);
BEGIN
  IF TG_OP = 'DELETE' THEN v_campaign_id := OLD.campaign_id; ELSE v_campaign_id := NEW.campaign_id; END IF;
  SELECT COALESCE(SUM(allocated_budget), 0) INTO v_total_allocated FROM public.kol_campaign_budget_allocations WHERE campaign_id = v_campaign_id;
  SELECT COALESCE(total_budget, budget, 0) INTO v_campaign_budget FROM public.kol_campaigns WHERE id = v_campaign_id;
  UPDATE public.kol_campaigns SET allocated_budget = v_total_allocated, remaining_budget = GREATEST(v_campaign_budget - v_total_allocated, 0), updated_at = timezone('utc'::text, now()) WHERE id = v_campaign_id;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_campaign_budget_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_note" "text", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_po public.catalog_purchase_orders%ROWTYPE;
  v_line jsonb;
  v_qty numeric;
  v_unit_cost numeric;
  v_subtotal numeric;
  v_name text;
  v_total numeric(14, 2) := 0;
  v_actor text;
  v_product_id uuid;
  v_variant_id uuid;
  v_ingredient_id uuid;
  v_pr public.purchase_requests%ROWTYPE;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id NOT IN (SELECT public.user_organization_ids()) THEN
    RAISE EXCEPTION 'catalog_po_forbidden';
  END IF;

  SELECT * INTO v_po
  FROM public.catalog_purchase_orders
  WHERE id = p_purchase_order_id AND organization_id = p_organization_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'catalog_po_not_found';
  END IF;
  IF v_po.status <> 'waiting' THEN
    RAISE EXCEPTION 'catalog_po_not_waiting';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
    RAISE EXCEPTION 'catalog_po_lines_required';
  END IF;

  SELECT * INTO v_pr
  FROM public.purchase_requests
  WHERE catalog_purchase_order_id = v_po.id
  FOR UPDATE;

  IF FOUND THEN
    IF public.catalog_po_is_paid(v_pr.status, v_pr.payment_status, v_pr.paid_at) THEN
      RAISE EXCEPTION 'catalog_po_already_paid';
    END IF;
    IF v_pr.status = 'approved' THEN
      RAISE EXCEPTION 'catalog_po_already_approved';
    END IF;
  END IF;

  v_actor := public.catalog_po_actor_name(p_organization_id);

  DELETE FROM public.catalog_purchase_order_lines WHERE purchase_order_id = v_po.id;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines)
  LOOP
    v_qty := COALESCE((v_line ->> 'qty')::numeric, 0);
    v_unit_cost := COALESCE((v_line ->> 'unit_cost')::numeric, 0);
    v_name := COALESCE(NULLIF(btrim(v_line ->> 'name_snapshot'), ''), '—');
    v_product_id := NULLIF(v_line ->> 'product_id', '')::uuid;
    v_variant_id := NULLIF(v_line ->> 'variant_id', '')::uuid;
    v_ingredient_id := NULLIF(v_line ->> 'ingredient_id', '')::uuid;

    IF v_qty <= 0 THEN
      CONTINUE;
    END IF;

    v_subtotal := ROUND(v_qty * v_unit_cost, 2);
    v_total := v_total + v_subtotal;

    INSERT INTO public.catalog_purchase_order_lines (
      purchase_order_id,
      organization_id,
      product_id,
      variant_id,
      ingredient_id,
      qty,
      unit_cost,
      subtotal,
      name_snapshot
    ) VALUES (
      v_po.id,
      p_organization_id,
      CASE WHEN v_po.item_kind = 'product' THEN v_product_id ELSE NULL END,
      CASE WHEN v_po.item_kind = 'product' THEN v_variant_id ELSE NULL END,
      CASE WHEN v_po.item_kind = 'ingredient' THEN v_ingredient_id ELSE NULL END,
      v_qty,
      v_unit_cost,
      v_subtotal,
      v_name
    );
  END LOOP;

  IF v_total <= 0 THEN
    RAISE EXCEPTION 'catalog_po_lines_required';
  END IF;

  UPDATE public.catalog_purchase_orders
  SET
    note = NULLIF(btrim(p_note), ''),
    total_value = v_total,
    updated_at = now()
  WHERE id = v_po.id;

  INSERT INTO public.catalog_purchase_order_events (
    purchase_order_id,
    organization_id,
    event_type,
    actor_user_id,
    actor_name_snapshot,
    comment
  ) VALUES (
    v_po.id,
    p_organization_id,
    'edited',
    auth.uid(),
    v_actor,
    NULLIF(btrim(p_note), '')
  );

  IF v_pr.id IS NOT NULL THEN
    PERFORM public.sync_catalog_po_purchase_request(v_po.id);
  END IF;

  RETURN to_jsonb((SELECT po FROM public.catalog_purchase_orders po WHERE po.id = v_po.id));
END;
$$;


ALTER FUNCTION "public"."update_catalog_purchase_order"("p_organization_id" "uuid", "p_purchase_order_id" "uuid", "p_note" "text", "p_lines" "jsonb") OWNER TO "postgres";


