CREATE OR REPLACE FUNCTION "public"."update_pos_shift_email_dispatch_language"("p_shift_id" "uuid", "p_language" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_shift public.pos_cashier_shifts;
BEGIN
  SELECT * INTO v_shift FROM public.pos_cashier_shifts WHERE id = p_shift_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'shift_not_found';
