CREATE OR REPLACE FUNCTION "public"."update_public_review_comment"("comment_id" "uuid", "token_param" "text", "commenter_display_name" "text", "new_comment_text" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_id uuid;
  v_name text;
  v_updated public.link_comments%ROWTYPE;
BEGIN
  IF new_comment_text IS NULL OR trim(new_comment_text) = '' THEN
    RAISE EXCEPTION 'new_comment_text is required';
  END IF;

  v_name := trim(commenter_display_name);
  IF v_name IS NULL OR v_name = '' THEN
    RAISE EXCEPTION 'commenter_display_name is required';
  END IF;

  SELECT social_media_plan_id INTO v_plan_id
  FROM public.public_review_tokens
  WHERE token = token_param
  LIMIT 1;

  IF v_plan_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired review link';
  END IF;

  UPDATE public.link_comments AS lc
  SET comment_text = trim(new_comment_text),
      updated_at = now()
  WHERE lc.id = comment_id
    AND lc.social_media_plan_id = v_plan_id
    AND lc.created_by IS NULL
    AND lower(trim(COALESCE(lc.commenter_display_name, ''))) = lower(v_name);

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Comment not found or you are not the author';
  END IF;

  SELECT * INTO v_updated FROM public.link_comments WHERE id = comment_id;

  RETURN json_build_object(
    'id', v_updated.id,
    'social_media_plan_id', v_updated.social_media_plan_id,
    'comment_text', v_updated.comment_text,
    'created_by', v_updated.created_by,
    'created_at', v_updated.created_at,
    'updated_at', v_updated.updated_at,
    'video_timestamp_seconds', v_updated.video_timestamp_seconds,
    'annotation_data', v_updated.annotation_data,
    'creator_display_name', v_updated.commenter_display_name
  );
END;
$$;


ALTER FUNCTION "public"."update_public_review_comment"("comment_id" "uuid", "token_param" "text", "commenter_display_name" "text", "new_comment_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_recipe_draft"("p_draft_id" "uuid", "p_lines" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  d public.catalog_recipe_drafts%ROWTYPE;
  v_user uuid := auth.uid();
  v_lines jsonb;
BEGIN
  SELECT * INTO d FROM public.catalog_recipe_drafts WHERE id = p_draft_id FOR UPDATE;
  IF NOT FOUND OR NOT public._recipe_is_member(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT public._recipe_is_manager(v_user, d.organization_id) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF d.status <> 'pending' OR d.expires_at <= now() THEN
    RAISE EXCEPTION 'recipe_draft_not_pending' USING ERRCODE = '22023';
  END IF;

  v_lines := public._recipe_draft_check_lines(d.organization_id, p_lines);

  UPDATE public.catalog_recipe_drafts
  SET lines = v_lines, edited_by = v_user, edited_at = now(), updated_at = now()
  WHERE id = d.id;

  RETURN public._recipe_draft_review(d.id, v_user);
END;
$$;


