CREATE OR REPLACE FUNCTION "public"."update_sales_activities_is_paid"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.total_amount, 0) > 0
     AND COALESCE(NEW.total_paid_amount, 0) >= NEW.total_amount THEN
    NEW.is_paid := TRUE;
  ELSE
    NEW.is_paid := FALSE;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_sales_activities_is_paid"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_sales_activities_payment_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF COALESCE(NEW.total_amount, 0) <= 0 THEN
    NEW.payment_status := COALESCE(NEW.payment_status, 'unpaid');
  ELSIF COALESCE(NEW.total_paid_amount, 0) >= NEW.total_amount THEN
    NEW.payment_status := 'paid';
  ELSIF COALESCE(NEW.total_paid_amount, 0) > 0 THEN
    NEW.payment_status := 'partial';
  ELSE
    NEW.payment_status := 'unpaid';
  END IF;
  RETURN NEW;
END;
$$;


