CREATE OR REPLACE FUNCTION "public"."update_sales_activity_payment_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_id uuid;
  sum_paid numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_id := OLD.sales_activity_id;
  ELSE
    target_id := NEW.sales_activity_id;
  END IF;

  SELECT COALESCE(SUM(payment_amount), 0) INTO sum_paid
  FROM public.sales_activity_payments
  WHERE sales_activity_id = target_id;

  UPDATE public.sales_activities sa
  SET
    total_paid_amount = sum_paid,
    updated_at = NOW()
  WHERE sa.id = target_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_sales_activity_payment_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_sales_activity_total_amount"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  target_id uuid;
  v_checkout_subtotal numeric;
  v_tax numeric;
  v_gratuity numeric;
  v_paid numeric;
  v_method text;
  v_tax_inclusive boolean;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_id := OLD.sales_activity_id;
  ELSE
    target_id := NEW.sales_activity_id;
  END IF;

  SELECT
    sa.checkout_subtotal,
    sa.checkout_tax_amount,
    sa.checkout_gratuity_amount,
    COALESCE(sa.total_paid_amount, sa.total_amount, 0),
    sa.checkout_application_method
  INTO
    v_checkout_subtotal,
    v_tax,
    v_gratuity,
    v_paid,
    v_method
  FROM public.sales_activities sa
  WHERE sa.id = target_id;

  IF v_checkout_subtotal IS NOT NULL THEN
    v_tax_inclusive := public.pos_sales_activity_tax_inclusive(
      v_checkout_subtotal,
      v_tax,
      v_gratuity,
      v_paid,
      v_method
    );

    UPDATE public.sales_activities sa
    SET
      total_amount = ROUND(
        CASE
          WHEN v_tax_inclusive THEN COALESCE(v_checkout_subtotal, 0)
          ELSE COALESCE(v_checkout_subtotal, 0)
            + COALESCE(v_tax, 0)
            + COALESCE(v_gratuity, 0)
        END,
        2
      ),
      updated_at = NOW()
    WHERE sa.id = target_id;
    RETURN COALESCE(NEW, OLD);
  END IF;

  UPDATE public.sales_activities sa
  SET
    total_amount = COALESCE((
      SELECT SUM(i.total_price)
      FROM public.sales_activity_items i
      WHERE i.sales_activity_id = sa.id
    ), 0),
    updated_at = NOW()
  WHERE sa.id = target_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."update_sales_activity_total_amount"() OWNER TO "postgres";


