CREATE OR REPLACE FUNCTION "public"."update_subscription_status_on_expiry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.trial_end_date IS NOT NULL
     AND NEW.trial_end_date <= now()
     AND NEW.is_trial = true THEN
    NEW.is_trial := false;
    IF NEW.status = 'trial' THEN
      NEW.status := 'expired';
    END IF;
  END IF;

  IF NEW.subscription_end_date IS NOT NULL
     AND NEW.subscription_end_date <= now()
     AND NEW.status = 'active' THEN
    NEW.status := 'expired';
    NEW.auto_renew := false;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_subscription_status_on_expiry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_target_progress"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_progress numeric(5,2);
begin
  -- keep timestamps fresh
  new.updated_at := now();

  -- guard: avoid division by zero / invalid target
  if new.target_value is null or new.target_value <= 0 then
    new.progress_percentage := 0.00;
    return new;
  end if;

  v_progress := round(((new.current_value::numeric / new.target_value::numeric) * 100.0), 2);

  -- clamp 0..100
  if v_progress < 0 then
    v_progress := 0.00;
  elsif v_progress > 100 then
    v_progress := 100.00;
  end if;

  new.progress_percentage := v_progress;

  return new;
end;
$$;


ALTER FUNCTION "public"."update_target_progress"() OWNER TO "postgres";


