CREATE OR REPLACE FUNCTION "public"."upsert_bank_statement_from_brick_callback"("p_organization_id" "uuid", "p_bank_account_id" "uuid", "p_external_id" "text", "p_transaction_date" timestamp with time zone, "p_amount" numeric, "p_description" "text", "p_reference" "text", "p_raw_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line_id uuid;
BEGIN
  IF p_external_id IS NULL OR btrim(p_external_id) = '' THEN
    RAISE EXCEPTION 'brick_statement_external_id_required';
  END IF;

  SELECT id INTO v_line_id
  FROM public.bank_statement_lines
  WHERE organization_id = p_organization_id
    AND external_id = p_external_id
  LIMIT 1;

  IF v_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
    SET
      amount = p_amount,
      description = COALESCE(p_description, description),
      reference = COALESCE(p_reference, reference),
      raw_payload = p_raw_payload,
      origin = 'brick_va',
      synced_at = now()
    WHERE id = v_line_id;
    RETURN v_line_id;
  END IF;

  INSERT INTO public.bank_statement_lines (
    organization_id,
    bank_account_id,
    external_id,
    transaction_date,
    amount,
    direction,
    description,
    reference,
    raw_payload,
    origin,
    synced_at
  ) VALUES (
    p_organization_id,
    p_bank_account_id,
    p_external_id,
    p_transaction_date,
    p_amount,
    'credit',
    p_description,
    p_reference,
    p_raw_payload,
    'brick_va',
    now()
  )
  RETURNING id INTO v_line_id;

  RETURN v_line_id;
END;
$$;


ALTER FUNCTION "public"."upsert_bank_statement_from_brick_callback"("p_organization_id" "uuid", "p_bank_account_id" "uuid", "p_external_id" "text", "p_transaction_date" timestamp with time zone, "p_amount" numeric, "p_description" "text", "p_reference" "text", "p_raw_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_bank_statement_from_brick_disbursement_callback"("p_organization_id" "uuid", "p_bank_account_id" "uuid", "p_external_id" "text", "p_transaction_date" timestamp with time zone, "p_amount" numeric, "p_description" "text", "p_reference" "text", "p_raw_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_line_id uuid;
  v_expense_id uuid;
BEGIN
  IF p_external_id IS NULL OR btrim(p_external_id) = '' THEN
    RAISE EXCEPTION 'brick_disbursement_statement_external_id_required';
  END IF;

  SELECT e.id INTO v_expense_id
  FROM public.brick_disbursements bd
  INNER JOIN public.expenses e ON e.purchase_request_id = bd.source_id
  WHERE bd.organization_id = p_organization_id
    AND bd.source_type = 'purchase_request'
    AND (bd.brick_disbursement_id = p_external_id OR bd.reference_id = p_reference)
  ORDER BY e.created_at DESC
  LIMIT 1;

  SELECT id INTO v_line_id
  FROM public.bank_statement_lines
  WHERE organization_id = p_organization_id
    AND external_id = p_external_id
  LIMIT 1;

  IF v_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
    SET
      amount = p_amount,
      description = COALESCE(p_description, description),
      reference = COALESCE(p_reference, reference),
      raw_payload = p_raw_payload,
      origin = 'brick_disbursement',
      expense_id = COALESCE(expense_id, v_expense_id),
      synced_at = now()
    WHERE id = v_line_id;
    RETURN v_line_id;
  END IF;

  INSERT INTO public.bank_statement_lines (
    organization_id,
    bank_account_id,
    external_id,
    transaction_date,
    amount,
    direction,
    description,
    reference,
    raw_payload,
    origin,
    expense_id,
    synced_at
  ) VALUES (
    p_organization_id,
    p_bank_account_id,
    p_external_id,
    p_transaction_date,
    p_amount,
    'debit',
    p_description,
    p_reference,
    p_raw_payload,
    'brick_disbursement',
    v_expense_id,
    now()
  )
  RETURNING id INTO v_line_id;

  RETURN v_line_id;
END;
$$;


ALTER FUNCTION "public"."upsert_bank_statement_from_brick_disbursement_callback"("p_organization_id" "uuid", "p_bank_account_id" "uuid", "p_external_id" "text", "p_transaction_date" timestamp with time zone, "p_amount" numeric, "p_description" "text", "p_reference" "text", "p_raw_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_bank_statement_from_erp_expense"("p_expense_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_expense public.expenses%ROWTYPE;
  v_bank_id uuid;
  v_external_id text;
  v_description text;
  v_line_id uuid;
  v_provider_label text;
  v_payload jsonb;
  v_txn_at timestamptz;
  v_pr_id uuid;
  v_sub_account_id text;
BEGIN
  SELECT * INTO v_expense FROM public.expenses WHERE id = p_expense_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_expense.purchase_request_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_expense.withdrawal_from_balance IS NOT NULL THEN
    RETURN NULL;
  END IF;

  IF v_expense.brick_bank_statement_line_id IS NOT NULL THEN
    RETURN v_expense.brick_bank_statement_line_id;
  END IF;

  v_bank_id := v_expense.bank_account_id;

  IF v_bank_id IS NULL AND v_expense.gateway_wallet_provider IS NOT NULL THEN
    v_bank_id := public.resolve_brick_disbursement_source_bank_account_id(v_expense.organization_id);
    IF v_bank_id IS NULL THEN
      SELECT ba.id INTO v_bank_id
      FROM public.bank_accounts ba
      WHERE ba.organization_id = v_expense.organization_id
        AND ba.is_active = true
      ORDER BY ba.created_at ASC
      LIMIT 1;
    END IF;
  END IF;

  IF v_bank_id IS NULL THEN
    RETURN NULL;
  END IF;

  v_pr_id := v_expense.purchase_request_id;

  SELECT COALESCE(
    pr.paid_at,
    (
      SELECT xd.completed_at
      FROM public.xendit_disbursements xd
      WHERE xd.source_type = 'purchase_request'
        AND xd.source_id = v_pr_id
        AND xd.status = 'completed'
      ORDER BY xd.completed_at DESC NULLS LAST
      LIMIT 1
    ),
    v_expense.created_at,
    now()
  )
  INTO v_txn_at
  FROM public.purchase_requests pr
  WHERE pr.id = v_pr_id;

  IF v_txn_at IS NULL THEN
    v_txn_at := COALESCE(v_expense.created_at, now());
  END IF;

  v_external_id := 'erp-expense-' || v_expense.id::text;

  IF v_expense.gateway_wallet_provider = 'brick' THEN
    v_provider_label := 'Brick drawer';
  ELSIF v_expense.gateway_wallet_provider = 'xendit' THEN
    v_provider_label := 'Xendit drawer';
    SELECT xsa.xendit_sub_account_id INTO v_sub_account_id
    FROM public.xendit_sub_accounts xsa
    WHERE xsa.organization_id = v_expense.organization_id
      AND xsa.is_primary = true
      AND xsa.xendit_sub_account_id IS NOT NULL
    LIMIT 1;
  ELSE
    v_provider_label := NULL;
  END IF;

  IF v_provider_label IS NOT NULL THEN
    v_description := 'Payment Process — ' || v_provider_label || ' — ' || v_expense.expense_name;
  ELSE
    v_description := 'Payment Process — ' || v_expense.expense_name;
  END IF;

  v_payload := jsonb_build_object(
    'source', 'erp_payment_process',
    'purchase_request_id', v_expense.purchase_request_id,
    'gateway_wallet_provider', v_expense.gateway_wallet_provider
  );
  IF v_sub_account_id IS NOT NULL THEN
    v_payload := v_payload || jsonb_build_object('sub_account_id', v_sub_account_id);
  END IF;

  SELECT id INTO v_line_id
  FROM public.bank_statement_lines
  WHERE organization_id = v_expense.organization_id
    AND external_id = v_external_id
  LIMIT 1;

  IF v_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
    SET
      amount = v_expense.amount,
      description = v_description,
      expense_id = v_expense.id,
      raw_payload = v_payload,
      transaction_date = v_txn_at,
      synced_at = now()
    WHERE id = v_line_id;
  ELSE
    INSERT INTO public.bank_statement_lines (
      organization_id,
      bank_account_id,
      external_id,
      transaction_date,
      amount,
      direction,
      description,
      reference,
      raw_payload,
      origin,
      expense_id,
      synced_at
    ) VALUES (
      v_expense.organization_id,
      v_bank_id,
      v_external_id,
      v_txn_at,
      v_expense.amount,
      'debit',
      v_description,
      v_expense.purchase_request_id::text,
      v_payload,
      'erp_expense',
      v_expense.id,
      now()
    )
    RETURNING id INTO v_line_id;
  END IF;

  UPDATE public.expenses
  SET brick_bank_statement_line_id = v_line_id
  WHERE id = v_expense.id
    AND brick_bank_statement_line_id IS NULL;

  RETURN v_line_id;
END;
$$;


ALTER FUNCTION "public"."upsert_bank_statement_from_erp_expense"("p_expense_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_bank_statement_from_erp_expense"("p_expense_id" "uuid") IS 'Mirror Payment Process expense as bank_statement_lines debit. Includes sub_account_id for Xendit gateway expenses.';



CREATE OR REPLACE FUNCTION "public"."upsert_bank_statement_from_gateway_withdrawal"("p_withdrawal_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_withdrawal public.xendit_gateway_withdrawals%ROWTYPE;
  v_disb public.xendit_disbursements%ROWTYPE;
  v_external_id text;
  v_description text;
  v_line_id uuid;
  v_payload jsonb;
  v_txn_at timestamptz;
  v_credit numeric;
BEGIN
  SELECT * INTO v_withdrawal
  FROM public.xendit_gateway_withdrawals
  WHERE id = p_withdrawal_id;

  IF NOT FOUND OR v_withdrawal.status <> 'completed' THEN
    RETURN NULL;
  END IF;

  IF v_withdrawal.bank_statement_line_id IS NOT NULL THEN
    RETURN v_withdrawal.bank_statement_line_id;
  END IF;

  SELECT * INTO v_disb
  FROM public.xendit_disbursements
  WHERE id = v_withdrawal.xendit_disbursement_id
  LIMIT 1;

  v_credit := COALESCE(v_withdrawal.net_amount, v_withdrawal.amount);
  v_external_id := 'erp-gateway-withdrawal-' || v_withdrawal.id::text;
  v_description := 'Xendit — tarik ke rekening payout';
  v_txn_at := COALESCE(v_withdrawal.settled_at, v_disb.completed_at, v_withdrawal.updated_at, now());

  v_payload := jsonb_build_object(
    'source', 'xendit_gateway_withdrawal',
    'gateway_wallet_provider', 'xendit',
    'withdrawal_id', v_withdrawal.id,
    'xendit_disbursement_id', v_withdrawal.xendit_disbursement_id,
    'sub_account_id', v_withdrawal.sub_account_id,
    'gross_amount', v_withdrawal.amount,
    'platform_fee_amount', v_withdrawal.platform_fee_amount,
    'net_amount', v_credit
  );

  SELECT id INTO v_line_id
  FROM public.bank_statement_lines
  WHERE organization_id = v_withdrawal.organization_id
    AND external_id = v_external_id
  LIMIT 1;

  IF v_line_id IS NOT NULL THEN
    UPDATE public.bank_statement_lines
    SET
      amount = v_credit,
      description = v_description,
      transaction_date = v_txn_at,
      raw_payload = v_payload,
      synced_at = now()
    WHERE id = v_line_id;
  ELSE
    INSERT INTO public.bank_statement_lines (
      organization_id,
      bank_account_id,
      external_id,
      transaction_date,
      amount,
      direction,
      description,
      reference,
      raw_payload,
      origin,
      synced_at
    ) VALUES (
      v_withdrawal.organization_id,
      v_withdrawal.bank_account_id,
      v_external_id,
      v_txn_at,
      v_credit,
      'credit',
      v_description,
      v_withdrawal.id::text,
      v_payload,
      'erp_gateway_withdrawal',
      now()
    )
    RETURNING id INTO v_line_id;
  END IF;

  UPDATE public.xendit_gateway_withdrawals
  SET bank_statement_line_id = v_line_id
  WHERE id = v_withdrawal.id
    AND bank_statement_line_id IS NULL;

  RETURN v_line_id;
END;
$$;


ALTER FUNCTION "public"."upsert_bank_statement_from_gateway_withdrawal"("p_withdrawal_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."upsert_bank_statement_from_gateway_withdrawal"("p_withdrawal_id" "uuid") IS 'ERP credit mirror in bank_statement_lines when Xendit gateway withdrawal settles to payout bank.';



CREATE OR REPLACE FUNCTION "public"."upsert_catalog_inventory_settings"("p_organization_id" "uuid", "p_po_mode" "text", "p_transfer_mode" "text", "p_feature_access" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_key text;
  v_roles text[];
  v_po_keys text[] := ARRAY['po_request', 'po_approval', 'po_fulfillment'];
  v_transfer_keys text[] := ARRAY[
    'transfer_request', 'transfer_approval', 'transfer_shipment', 'transfer_fulfillment'
  ];
  v_required text[];
  v_present text[] := '{}'::text[];
  v_active_keys text[] := '{}'::text[];
BEGIN
  IF p_organization_id IS NULL THEN RAISE EXCEPTION 'organization_id_required'; END IF;
  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN RAISE EXCEPTION 'forbidden'; END IF;
  IF p_po_mode NOT IN ('simple', 'advanced') OR p_transfer_mode NOT IN ('simple', 'advanced') THEN
    RAISE EXCEPTION 'catalog_inventory_mode_invalid';
  END IF;
  v_required := ARRAY[]::text[];
  IF p_po_mode = 'advanced' THEN v_required := v_required || v_po_keys; END IF;
  IF p_transfer_mode = 'advanced' THEN v_required := v_required || v_transfer_keys; END IF;
  v_active_keys := v_required;
  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_feature_access, '[]'::jsonb)) LOOP
    v_key := NULLIF(btrim(v_item ->> 'feature_key'), '');
    IF v_key IS NULL THEN CONTINUE; END IF;
    SELECT COALESCE(array_agg(DISTINCT r ORDER BY r), '{}'::text[]) INTO v_roles
    FROM unnest(COALESCE(ARRAY(SELECT jsonb_array_elements_text(v_item -> 'allowed_roles')), '{}'::text[])) AS r
    WHERE r IN ('owner', 'admin', 'hr', 'employee');
    IF v_key = ANY (v_required) AND COALESCE(array_length(v_roles, 1), 0) = 0 THEN
      RAISE EXCEPTION 'catalog_inventory_access_roles_required';
    END IF;
    v_present := array_append(v_present, v_key);
    INSERT INTO public.catalog_inventory_feature_access (organization_id, feature_key, allowed_roles)
    VALUES (p_organization_id, v_key, v_roles)
    ON CONFLICT (organization_id, feature_key) DO UPDATE SET allowed_roles = EXCLUDED.allowed_roles, updated_at = now();
  END LOOP;
  IF EXISTS (SELECT 1 FROM unnest(v_required) AS req(key) WHERE NOT (req.key = ANY (v_present))) THEN
    RAISE EXCEPTION 'catalog_inventory_access_roles_required';
  END IF;
  INSERT INTO public.catalog_inventory_settings (organization_id, po_mode, transfer_mode)
  VALUES (p_organization_id, p_po_mode, p_transfer_mode)
  ON CONFLICT (organization_id) DO UPDATE SET po_mode = EXCLUDED.po_mode, transfer_mode = EXCLUDED.transfer_mode, updated_at = now();
  DELETE FROM public.catalog_inventory_feature_access fa
  WHERE fa.organization_id = p_organization_id
    AND (COALESCE(array_length(v_active_keys, 1), 0) = 0 OR NOT (fa.feature_key = ANY (v_active_keys)));
  RETURN public.get_or_create_catalog_inventory_settings(p_organization_id);
END;
$$;


ALTER FUNCTION "public"."upsert_catalog_inventory_settings"("p_organization_id" "uuid", "p_po_mode" "text", "p_transfer_mode" "text", "p_feature_access" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_customer_survey_assignee_target"("p_organization_id" "uuid", "p_assignee_id" "uuid", "p_target_pct" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF NOT public.is_omnichannel_survey_settings_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF p_target_pct < 0 OR p_target_pct > 100 THEN
    RAISE EXCEPTION 'invalid_target';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.employees e
    WHERE e.id = p_assignee_id
      AND e.organization_id = p_organization_id
  ) THEN
    RAISE EXCEPTION 'invalid_assignee';
  END IF;

  INSERT INTO public.organization_customer_survey_assignee_targets (
    organization_id,
    assignee_id,
    promoter_pct_target,
    updated_at,
    updated_by
  )
  VALUES (
    p_organization_id,
    p_assignee_id,
    round(p_target_pct::numeric, 2),
    now(),
    auth.uid()
  )
  ON CONFLICT (organization_id, assignee_id) DO UPDATE
  SET
    promoter_pct_target = EXCLUDED.promoter_pct_target,
    updated_at = now(),
    updated_by = auth.uid();
END;
$$;


ALTER FUNCTION "public"."upsert_customer_survey_assignee_target"("p_organization_id" "uuid", "p_assignee_id" "uuid", "p_target_pct" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_kol_budget_allocation"("p_campaign_id" "uuid", "p_kol_profile_id" "uuid", "p_organization_id" "uuid", "p_amount_delta" numeric, "p_payment_model" "text" DEFAULT 'fixed'::"text", "p_payment_terms_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_budget_type text;
  v_delta numeric(15, 2);
BEGIN
  IF p_campaign_id IS NULL OR p_kol_profile_id IS NULL OR p_organization_id IS NULL THEN
    RETURN;
  END IF;

  v_delta := COALESCE(p_amount_delta, 0);
  IF v_delta <= 0 THEN
    RETURN;
  END IF;

  v_budget_type := CASE COALESCE(p_payment_model, 'fixed')
    WHEN 'performance_based' THEN 'performance'
    WHEN 'barter_plus_fee' THEN 'hybrid'
    ELSE 'fixed'
  END;

  INSERT INTO public.kol_campaign_budget_allocations (
    campaign_id,
    kol_profile_id,
    organization_id,
    allocated_budget,
    base_budget,
    payment_model,
    budget_type,
    payment_terms_id
  )
  VALUES (
    p_campaign_id,
    p_kol_profile_id,
    p_organization_id,
    v_delta,
    v_delta,
    COALESCE(p_payment_model, 'fixed'),
    v_budget_type,
    p_payment_terms_id
  )
  ON CONFLICT (campaign_id, kol_profile_id) DO UPDATE SET
    allocated_budget = public.kol_campaign_budget_allocations.allocated_budget + EXCLUDED.allocated_budget,
    base_budget = public.kol_campaign_budget_allocations.base_budget + EXCLUDED.base_budget,
    payment_terms_id = COALESCE(EXCLUDED.payment_terms_id, public.kol_campaign_budget_allocations.payment_terms_id),
    payment_model = EXCLUDED.payment_model,
    budget_type = EXCLUDED.budget_type,
    updated_at = timezone('utc'::text, now());
END;
$$;


ALTER FUNCTION "public"."upsert_kol_budget_allocation"("p_campaign_id" "uuid", "p_kol_profile_id" "uuid", "p_organization_id" "uuid", "p_amount_delta" numeric, "p_payment_model" "text", "p_payment_terms_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_operational_email_notification_settings"("p_organization_id" "uuid", "p_daily_sales_summary_enabled" boolean, "p_inventory_alerts_enabled" boolean, "p_promo_update_enabled" boolean, "p_daily_gross_profit_enabled" boolean DEFAULT true, "p_shift_recap_email_enabled" boolean DEFAULT true) RETURNS "public"."operational_email_notification_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.operational_email_notification_settings;
BEGIN
  IF p_organization_id IS NULL THEN
    RAISE EXCEPTION 'organization_id_required';
  END IF;

  IF NOT public.user_is_org_owner_or_admin(p_organization_id) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  INSERT INTO public.operational_email_notification_settings (
    organization_id,
    daily_sales_summary_enabled,
    inventory_alerts_enabled,
    promo_update_enabled,
    daily_gross_profit_enabled,
    shift_recap_email_enabled
  )
  VALUES (
    p_organization_id,
    COALESCE(p_daily_sales_summary_enabled, true),
    COALESCE(p_inventory_alerts_enabled, true),
    COALESCE(p_promo_update_enabled, true),
    COALESCE(p_daily_gross_profit_enabled, true),
    COALESCE(p_shift_recap_email_enabled, true)
  )
  ON CONFLICT (organization_id) DO UPDATE SET
    daily_sales_summary_enabled = EXCLUDED.daily_sales_summary_enabled,
    inventory_alerts_enabled = EXCLUDED.inventory_alerts_enabled,
    promo_update_enabled = EXCLUDED.promo_update_enabled,
    daily_gross_profit_enabled = EXCLUDED.daily_gross_profit_enabled,
    shift_recap_email_enabled = EXCLUDED.shift_recap_email_enabled,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$$;


ALTER FUNCTION "public"."upsert_operational_email_notification_settings"("p_organization_id" "uuid", "p_daily_sales_summary_enabled" boolean, "p_inventory_alerts_enabled" boolean, "p_promo_update_enabled" boolean, "p_daily_gross_profit_enabled" boolean, "p_shift_recap_email_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."use_shared_whatsapp_token"("p_account_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_catalog'
    AS $$
declare
  v_org uuid;
  v_token text;
begin
  select organization_id into v_org from public.organization_whatsapp_accounts where id = p_account_id;
  if v_org is null then
    raise exception 'connection_not_found' using errcode = 'P0002';
  end if;
  if not public.user_is_org_owner_or_admin(v_org) then
    raise exception 'Hanya owner atau admin yang bisa mengubah kunci koneksi.' using errcode = '42501';
  end if;
  select nullif(btrim(meta_access_token), '') into v_token
    from public.organization_meta_config where organization_id = v_org;
  if v_token is null then
    return false;
  end if;
  update public.organization_whatsapp_accounts
     set meta_access_token = v_token, updated_at = now()
   where id = p_account_id;
  return true;
end;
$$;


ALTER FUNCTION "public"."use_shared_whatsapp_token"("p_account_id" "uuid") OWNER TO "postgres";


