CREATE OR REPLACE FUNCTION "public"."user_has_inventory_feature_access"("p_organization_id" "uuid", "p_feature_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_role text;
  v_allowed text[];
BEGIN
  IF p_organization_id IS NULL OR p_feature_key IS NULL THEN
    RETURN false;
  END IF;

  v_role := public.get_user_role_in_org(p_organization_id);
  IF v_role = 'owner' THEN
    RETURN true;
  END IF;

  SELECT fa.allowed_roles
    INTO v_allowed
  FROM public.catalog_inventory_feature_access fa
  WHERE fa.organization_id = p_organization_id
    AND fa.feature_key = p_feature_key;

  IF v_allowed IS NULL OR COALESCE(array_length(v_allowed, 1), 0) = 0 THEN
    RETURN false;
  END IF;

  RETURN v_role = ANY (v_allowed);
END;
$$;


ALTER FUNCTION "public"."user_has_inventory_feature_access"("p_organization_id" "uuid", "p_feature_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_has_org_role"("p_org" "uuid", "p_roles" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid()
      AND organization_id = p_org
      AND lower(role) = ANY (p_roles)
  );
$$;


