CREATE OR REPLACE FUNCTION "public"."user_roles_actor_can_manage_org"("p_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.user_roles ur
    WHERE ur.user_id = (SELECT auth.uid())
      AND ur.organization_id = p_organization_id
      AND ur.role IN ('owner', 'admin', 'hr')
  )
  OR EXISTS (
    SELECT 1
    FROM public.organizations o
    WHERE o.id = p_organization_id
      AND (
        o.user_id IS NOT DISTINCT FROM (SELECT auth.uid())
        OR o.created_by IS NOT DISTINCT FROM (SELECT auth.uid())
      )
  );
$$;


ALTER FUNCTION "public"."user_roles_actor_can_manage_org"("p_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_attendance_comprehensive"("employee_id_param" "uuid", "organization_id_param" "uuid", "latitude_param" double precision, "longitude_param" double precision, "face_image_data" "text" DEFAULT NULL::"text", "gps_accuracy_meters" numeric DEFAULT NULL::numeric, "is_manual_location" boolean DEFAULT false) RETURNS TABLE("allowed_radius" numeric, "can_attend" boolean, "distance_meters" numeric, "face_registered" boolean, "face_valid" boolean, "is_holiday" boolean, "is_late" boolean, "late_minutes" integer, "location_valid" boolean, "no_duplicate" boolean, "office_location_id" "uuid", "office_location_name" "text", "schedule_valid" boolean, "shift_id" "uuid", "employee_shift_id" "uuid", "work_schedule_id" "uuid", "schedule_source" "text", "start_time" "text", "working_days" integer[], "gps_accuracy_valid" boolean, "photo_required" boolean, "attendance_rules_snapshot" "jsonb", "visit_day_mode" "text", "late_reference_time" time without time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_sched record;
  v_rules record;
  v_mode jsonb;
  v_mode_text text;
  v_tz text;
  v_now_local timestamp;
  v_today date;
  v_off record;
  v_dist numeric;
  v_radius numeric;
  v_loc_ok boolean;
  v_sched_ok boolean;
  v_holiday boolean;
  v_holiday_blocks boolean;
  v_dup_ok boolean;
  v_face_reg boolean;
  v_face_ok boolean;
  v_late boolean := false;
  v_late_mins integer := 0;
  v_late_ref time;
  v_late_info jsonb;
  v_gps_ok boolean := true;
  v_manual_ok boolean := true;
  v_photo_ok boolean := true;
  v_photo_required boolean := false;
  v_can_attend boolean;
  v_auth boolean;
  v_rules_snapshot jsonb;
  v_use_client_checkin boolean := false;
  v_off_id uuid;
  v_off_name text;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = employee_id_param
      AND e.organization_id = organization_id_param
      AND (
        e.user_id = auth.uid()
        OR organization_id_param IN (SELECT public.user_organization_ids())
      )
  )
  INTO v_auth;

  IF NOT v_auth THEN
    RETURN QUERY
    SELECT
      0::numeric, false, NULL::numeric, false, false, false, false, 0,
      false, false, NULL::uuid, NULL::text, false,
      NULL::uuid, NULL::uuid, NULL::uuid, NULL::text, NULL::text, NULL::integer[],
      false, false, NULL::jsonb, NULL::text, NULL::time;
    RETURN;
  END IF;

  SELECT *
  INTO v_rules
  FROM public.load_attendance_rules(organization_id_param) r
  LIMIT 1;

  SELECT COALESCE(wss.timezone, 'Asia/Jakarta')
  INTO v_tz
  FROM public.employees e
  LEFT JOIN public.work_schedule_settings wss
    ON wss.id = e.work_schedule_id
   AND wss.organization_id = organization_id_param
   AND COALESCE(wss.is_active, true)
  WHERE e.id = employee_id_param
    AND e.organization_id = organization_id_param;

  IF v_tz IS NULL THEN
    SELECT COALESCE(wss.timezone, 'Asia/Jakarta')
    INTO v_tz
    FROM public.work_schedule_settings wss
    WHERE wss.organization_id = organization_id_param
      AND COALESCE(wss.is_active, true)
    ORDER BY wss.is_default DESC NULLS LAST, wss.created_at ASC
    LIMIT 1;
  END IF;

  v_tz := COALESCE(v_tz, 'Asia/Jakarta');
  v_now_local := timezone(v_tz, now());
  v_today := (v_now_local)::date;

  v_mode := public.resolve_visit_day_mode(employee_id_param, organization_id_param, v_today);
  v_mode_text := COALESCE(v_mode->>'mode', 'normal');

  v_rules_snapshot := jsonb_build_object(
    'enforce_national_holidays', v_rules.enforce_national_holidays,
    'require_photo_checkin', v_rules.require_photo_checkin,
    'require_gps_accuracy', v_rules.require_gps_accuracy,
    'gps_accuracy_threshold_meters', v_rules.gps_accuracy_threshold_meters,
    'default_max_radius_meters', v_rules.default_max_radius_meters,
    'allow_manual_location', v_rules.allow_manual_location,
    'enable_visit_attendance_integration', v_rules.enable_visit_attendance_integration,
    'visit_day_mode', v_mode_text
  );

  SELECT *
  INTO v_sched
  FROM public.resolve_effective_schedule(
    employee_id_param,
    organization_id_param,
    v_today
  ) r
  LIMIT 1;

  SELECT EXISTS (
    SELECT 1
    FROM public.national_holidays nh
    WHERE COALESCE(nh.is_active, true)
      AND COALESCE(nh.applies_to_attendance, true)
      AND nh.date = v_today
      AND (
        nh.organization_id IS NULL
        OR nh.organization_id = organization_id_param
      )
  )
  INTO v_holiday;

  v_holiday_blocks := v_holiday AND COALESCE(v_rules.enforce_national_holidays, true);

  v_dup_ok := NOT EXISTS (
    SELECT 1
    FROM public.attendance_records ar
    WHERE ar.employee_id = employee_id_param
      AND ar.organization_id = organization_id_param
      AND ar.attendance_date = v_today
      AND ar.check_in_time IS NOT NULL
  );

  SELECT EXISTS (
    SELECT 1
    FROM public.employee_face_registrations efr
    WHERE efr.employee_id = employee_id_param
      AND efr.organization_id = organization_id_param
      AND COALESCE(efr.is_active, true)
  )
  INTO v_face_reg;

  IF face_image_data IS NULL OR btrim(face_image_data) = '' THEN
    v_face_ok := true;
  ELSE
    v_face_ok := v_face_reg;
  END IF;

  IF v_sched.work_schedule_id IS NULL AND v_sched.shift_id IS NULL THEN
    v_sched_ok := false;
  ELSE
    v_sched_ok := COALESCE(v_sched.is_working_day, false);
    IF NOT v_sched_ok
       AND v_sched.source = 'shift'
       AND v_sched.shift_id IS NOT NULL
       AND v_sched.employee_shift_id IS NOT NULL THEN
      v_sched_ok := true;
    END IF;
  END IF;

  v_late_info := public.resolve_attendance_late_for_day(
    employee_id_param,
    organization_id_param,
    v_today,
    v_now_local,
    NULL,
    false
  );
  v_late := COALESCE((v_late_info->>'is_late')::boolean, false);
  v_late_mins := COALESCE((v_late_info->>'late_minutes')::integer, 0);
  v_late_ref := (v_late_info->>'late_reference_time')::time;

  v_use_client_checkin := v_mode_text IN ('field_first', 'travel_field') AND v_dup_ok;

  IF v_use_client_checkin THEN
    v_loc_ok := false;
    v_dist := NULL;
    v_radius := 0;
    v_off_id := NULL;
    v_off_name := NULL;
  ELSE
    SELECT
      ol.id,
      ol.name,
      ol.radius_meters,
      (
        6371000.0 * acos(
          LEAST(
            1.0::double precision,
            GREATEST(
              -1.0::double precision,
              cos(radians(ol.latitude::double precision))
              * cos(radians(latitude_param))
              * cos(radians(longitude_param) - radians(ol.longitude::double precision))
              + sin(radians(ol.latitude::double precision))
              * sin(radians(latitude_param))
            )
          )
        )
      )::numeric AS dist
    INTO v_off
    FROM public.office_locations ol
    WHERE ol.organization_id = organization_id_param
      AND COALESCE(ol.is_active, true)
      AND COALESCE(ol.is_client_location, false) IS NOT TRUE
      AND ol.latitude IS NOT NULL
      AND ol.longitude IS NOT NULL
    ORDER BY dist ASC
    LIMIT 1;

    v_off_id := v_off.id;
    v_off_name := v_off.name;

    IF v_off_id IS NULL THEN
      v_loc_ok := false;
      v_dist := NULL;
      v_radius := 0;
    ELSE
      v_dist := v_off.dist;
      v_radius := COALESCE(
        v_off.radius_meters::numeric,
        v_rules.default_max_radius_meters::numeric,
        100::numeric
      );
      v_loc_ok := v_dist <= v_radius;
    END IF;
  END IF;

  IF COALESCE(v_rules.require_gps_accuracy, false) THEN
    IF gps_accuracy_meters IS NULL THEN
      v_gps_ok := false;
    ELSE
      v_gps_ok := gps_accuracy_meters <= v_rules.gps_accuracy_threshold_meters;
    END IF;
  END IF;

  IF COALESCE(is_manual_location, false) AND NOT COALESCE(v_rules.allow_manual_location, false) THEN
    v_manual_ok := false;
  END IF;

  v_photo_required := COALESCE(v_rules.require_photo_checkin, false);
  IF v_photo_required AND (face_image_data IS NULL OR btrim(face_image_data) = '') THEN
    v_photo_ok := false;
  END IF;

  v_can_attend :=
    NOT v_use_client_checkin
    AND v_loc_ok
    AND v_sched_ok
    AND NOT v_holiday_blocks
    AND v_dup_ok
    AND v_face_ok
    AND v_gps_ok
    AND v_manual_ok
    AND v_photo_ok;

  RETURN QUERY
  SELECT
    COALESCE(v_radius, 0::numeric),
    v_can_attend,
    v_dist,
    v_face_reg,
    v_face_ok,
    v_holiday,
    v_late,
    v_late_mins,
    v_loc_ok,
    v_dup_ok,
    v_off_id,
    v_off_name,
    v_sched_ok,
    v_sched.shift_id,
    v_sched.employee_shift_id,
    v_sched.work_schedule_id,
    v_sched.source,
    v_sched.start_time,
    v_sched.working_days,
    v_gps_ok,
    v_photo_required,
    v_rules_snapshot,
    v_mode_text,
    v_late_ref;
END;
$$;


ALTER FUNCTION "public"."validate_attendance_comprehensive"("employee_id_param" "uuid", "organization_id_param" "uuid", "latitude_param" double precision, "longitude_param" double precision, "face_image_data" "text", "gps_accuracy_meters" numeric, "is_manual_location" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_checkout_comprehensive"("employee_id_param" "uuid", "organization_id_param" "uuid", "photo_path_param" "text" DEFAULT NULL::"text", "face_image_data" "text" DEFAULT NULL::"text") RETURNS TABLE("can_checkout" boolean, "photo_required" boolean, "photo_valid" boolean, "has_checkin" boolean, "already_checked_out" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_rules record;
  v_tz text;
  v_today date;
  v_has_checkin boolean := false;
  v_already_out boolean := false;
  v_photo_required boolean := false;
  v_photo_ok boolean := true;
  v_auth boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.employees e
    WHERE e.id = employee_id_param
      AND e.organization_id = organization_id_param
      AND (
        e.user_id = auth.uid()
        OR organization_id_param IN (SELECT public.user_organization_ids())
      )
  )
  INTO v_auth;

  IF NOT v_auth THEN
    RETURN QUERY SELECT false, false, false, false, false;
    RETURN;
  END IF;

  SELECT *
  INTO v_rules
  FROM public.load_attendance_rules(organization_id_param) r
  LIMIT 1;

  SELECT COALESCE(wss.timezone, 'Asia/Jakarta')
  INTO v_tz
  FROM public.employees e
  LEFT JOIN public.work_schedule_settings wss
    ON wss.id = e.work_schedule_id
   AND wss.organization_id = organization_id_param
  WHERE e.id = employee_id_param
    AND e.organization_id = organization_id_param;

  v_tz := COALESCE(v_tz, 'Asia/Jakarta');
  v_today := (timezone(v_tz, now()))::date;

  SELECT
    (ar.check_in_time IS NOT NULL OR ar.check_in_at IS NOT NULL),
    (ar.check_out_time IS NOT NULL OR ar.check_out_at IS NOT NULL)
  INTO v_has_checkin, v_already_out
  FROM public.attendance_records ar
  WHERE ar.employee_id = employee_id_param
    AND ar.organization_id = organization_id_param
    AND ar.attendance_date = v_today
  LIMIT 1;

  v_has_checkin := COALESCE(v_has_checkin, false);
  v_already_out := COALESCE(v_already_out, false);

  v_photo_required := COALESCE(v_rules.require_photo_checkout, false);
  IF v_photo_required THEN
    IF (photo_path_param IS NULL OR btrim(photo_path_param) = '')
       AND (face_image_data IS NULL OR btrim(face_image_data) = '') THEN
      v_photo_ok := false;
    END IF;
  END IF;

  RETURN QUERY
  SELECT
    v_has_checkin AND NOT v_already_out AND v_photo_ok,
    v_photo_required,
    v_photo_ok,
    v_has_checkin,
    v_already_out;
END;
$$;


ALTER FUNCTION "public"."validate_checkout_comprehensive"("employee_id_param" "uuid", "organization_id_param" "uuid", "photo_path_param" "text", "face_image_data" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_client_visit_location"("user_latitude" double precision, "user_longitude" double precision, "client_id_param" "uuid" DEFAULT NULL::"uuid", "organization_id_param" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org uuid := organization_id_param;
  v_best record;
  v_distance numeric;
BEGIN
  IF v_org IS NULL THEN
    RETURN jsonb_build_object(
      'is_valid', false,
      'error', 'Organization ID is required'
    );
  END IF;

  IF NOT (v_org IN (SELECT public.user_organization_ids())) THEN
    RETURN jsonb_build_object(
      'is_valid', false,
      'error', 'Access denied for organization'
    );
  END IF;

  IF user_latitude IS NULL OR user_longitude IS NULL THEN
    RETURN jsonb_build_object(
      'is_valid', false,
      'error', 'Coordinates are required'
    );
  END IF;

  SELECT
    ol.id,
    ol.name,
    ol.radius_meters,
    (
      6371000.0 * acos(
        LEAST(
          1.0,
          GREATEST(
            -1.0,
            cos(radians(ol.latitude::double precision))
            * cos(radians(user_latitude))
            * cos(radians(user_longitude) - radians(ol.longitude::double precision))
            + sin(radians(ol.latitude::double precision))
            * sin(radians(user_latitude))
          )
        )
      )
    ) AS distance_m
  INTO v_best
  FROM public.office_locations ol
  WHERE ol.organization_id = v_org
    AND ol.is_active IS NOT FALSE
    AND ol.is_client_location IS TRUE
    AND ol.latitude IS NOT NULL
    AND ol.longitude IS NOT NULL
    AND (client_id_param IS NULL OR ol.client_id = client_id_param OR ol.client_id IS NULL)
  ORDER BY (
    6371000.0 * acos(
      LEAST(
        1.0,
        GREATEST(
          -1.0,
          cos(radians(ol.latitude::double precision))
          * cos(radians(user_latitude))
          * cos(radians(user_longitude) - radians(ol.longitude::double precision))
          + sin(radians(ol.latitude::double precision))
          * sin(radians(user_latitude))
        )
      )
    )
  )
  LIMIT 1;

  IF v_best.id IS NULL THEN
    RETURN jsonb_build_object(
      'is_valid', false,
      'error', 'No client visit location configured for this organization'
    );
  END IF;

  v_distance := round(v_best.distance_m::numeric, 1);

  IF v_distance > COALESCE(v_best.radius_meters, 100) THEN
    RETURN jsonb_build_object(
      'is_valid', false,
      'location_id', v_best.id,
      'location_name', v_best.name,
      'distance_meters', v_distance,
      'allowed_radius_meters', COALESCE(v_best.radius_meters, 100),
      'error', format('Outside allowed radius (%sm)', COALESCE(v_best.radius_meters, 100))
    );
  END IF;

  RETURN jsonb_build_object(
    'is_valid', true,
    'location_id', v_best.id,
    'location_name', v_best.name,
    'location_type', 'client-site',
    'distance_meters', v_distance,
    'allowed_radius_meters', COALESCE(v_best.radius_meters, 100),
    'accuracy_meters', NULL
  );
END;
$$;


ALTER FUNCTION "public"."validate_client_visit_location"("user_latitude" double precision, "user_longitude" double precision, "client_id_param" "uuid", "organization_id_param" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_expense_insert_debt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_debt_record record;
  v_available_limit numeric(15, 2);
BEGIN
  IF NEW.withdrawal_from_balance IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
  INTO v_debt_record
  FROM public.debts
  WHERE id = NEW.withdrawal_from_balance
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Debt with id % not found', NEW.withdrawal_from_balance;
  END IF;

  IF v_debt_record.status != 'active' THEN
    RAISE EXCEPTION 'Cannot use debt with status %. Only active debts can be used.', v_debt_record.status;
  END IF;

  v_available_limit := coalesce(v_debt_record.available_limit, v_debt_record.limit_amount);
  IF v_available_limit < NEW.amount THEN
    RAISE EXCEPTION 'Insufficient available limit. Available: %, Required: %',
      v_available_limit, NEW.amount;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_expense_insert_debt"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_expense_insert_debt"() IS 'BEFORE INSERT: validate debt / available_limit (reference).';



CREATE OR REPLACE FUNCTION "public"."validate_expense_update_debt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
DECLARE
  v_debt_record record;
  v_available_limit numeric(15, 2);
  v_amount_diff numeric(15, 2);
BEGIN
  v_amount_diff := NEW.amount - OLD.amount;

  IF (OLD.withdrawal_from_balance IS DISTINCT FROM NEW.withdrawal_from_balance) THEN
    IF NEW.withdrawal_from_balance IS NOT NULL THEN
      SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
      INTO v_debt_record
      FROM public.debts
      WHERE id = NEW.withdrawal_from_balance
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Debt with id % not found', NEW.withdrawal_from_balance;
      END IF;

      IF v_debt_record.status != 'active' THEN
        RAISE EXCEPTION 'Cannot use debt with status %. Only active debts can be used.', v_debt_record.status;
      END IF;

      v_available_limit := coalesce(v_debt_record.available_limit, v_debt_record.limit_amount);
      IF v_available_limit < NEW.amount THEN
        RAISE EXCEPTION 'Insufficient available limit. Available: %, Required: %',
          v_available_limit, NEW.amount;
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.withdrawal_from_balance IS NOT NULL AND v_amount_diff > 0 THEN
    SELECT id, limit_amount, available_limit, debt_amount, status, debt_type
    INTO v_debt_record
    FROM public.debts
    WHERE id = OLD.withdrawal_from_balance
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Debt with id % not found', OLD.withdrawal_from_balance;
    END IF;

    v_available_limit := coalesce(v_debt_record.available_limit, v_debt_record.limit_amount);
    IF v_available_limit < v_amount_diff THEN
      RAISE EXCEPTION 'Insufficient available limit. Available: %, Required additional: %',
        v_available_limit, v_amount_diff;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."validate_expense_update_debt"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validate_expense_update_debt"() IS 'BEFORE UPDATE: validate when amount or withdrawal changes (reference).';



CREATE OR REPLACE FUNCTION "public"."verify_operational_email_recipient"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_row public.operational_email_recipients;
BEGIN
  IF p_token IS NULL THEN
    RAISE EXCEPTION 'token_required';
  END IF;

  SELECT * INTO v_row
  FROM public.operational_email_recipients r
  WHERE r.verification_token = p_token
    AND r.status = 'pending'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'token_invalid';
  END IF;

  IF v_row.verification_expires_at IS NOT NULL AND v_row.verification_expires_at < now() THEN
    RAISE EXCEPTION 'token_expired';
  END IF;

  UPDATE public.operational_email_recipients
  SET
    status = 'verified',
    verified_at = now(),
    verification_token = NULL,
    verification_expires_at = NULL
  WHERE id = v_row.id
  RETURNING * INTO v_row;

  RETURN jsonb_build_object(
    'id', v_row.id,
    'email', v_row.email,
    'status', v_row.status,
    'verified_at', v_row.verified_at
  );
END;
$$;


ALTER FUNCTION "public"."verify_operational_email_recipient"("p_token" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."whatsapp_conversation_cycles_bi_seed_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.first_assignee_in_cycle_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.whatsapp_conversations c
    WHERE c.id = NEW.conversation_id
      AND c.assignee_id IS NOT NULL
  ) THEN
    NEW.first_assignee_in_cycle_at := NEW.cycle_started_at;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."whatsapp_conversation_cycles_bi_seed_first_assignee"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."whatsapp_conversation_cycles_bi_seed_first_assignee"() IS 'BEFORE INSERT on whatsapp_conversation_cycles: sets first_assignee_in_cycle_at from cycle_started_at when parent conversation already has assignee_id.';



CREATE OR REPLACE FUNCTION "public"."whatsapp_conversations_set_cycle_first_assignee"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.assignee_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.assignee_id IS NOT DISTINCT FROM NEW.assignee_id THEN
    RETURN NEW;
  END IF;
  UPDATE public.whatsapp_conversation_cycles cy
  SET
    first_assignee_in_cycle_at = now(),
    updated_at = now()
  WHERE cy.conversation_id = NEW.id
    AND cy.resolved_at IS NULL
    AND cy.first_assignee_in_cycle_at IS NULL;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."whatsapp_conversations_set_cycle_first_assignee"() OWNER TO "postgres";


