    CONSTRAINT "ai_employee_schedules_window_check" CHECK (((("window_start_weekday" IS NULL) OR (("window_start_weekday" >= 1) AND ("window_start_weekday" <= 7))) AND (("window_end_weekday" IS NULL) OR (("window_end_weekday" >= 1) AND ("window_end_weekday" <= 7)))))
);


