    "promo_type" "text" NOT NULL,
    "sales_type_scope" "text" DEFAULT 'all'::"text" NOT NULL,
    "applies_in_multiple" boolean DEFAULT false NOT NULL,
    "time_period_enabled" boolean DEFAULT false NOT NULL,
    "starts_on" "date",
    "ends_on" "date",
    "starts_at_time" time without time zone,
    "ends_at_time" time without time zone,
    "reward_amount_unit" "text",
    "reward_amount_value" numeric(14,2),
    "reward_product_id" "uuid",
    "reward_quantity" integer DEFAULT 1 NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "catalog_promos_name_check" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "catalog_promos_period_dates_check" CHECK (((("time_period_enabled" = false) AND ("starts_on" IS NULL) AND ("ends_on" IS NULL) AND ("starts_at_time" IS NULL) AND ("ends_at_time" IS NULL)) OR (("time_period_enabled" = true) AND ("starts_on" IS NOT NULL) AND ("ends_on" IS NOT NULL) AND ("ends_on" >= "starts_on")))),
    CONSTRAINT "catalog_promos_promo_type_check" CHECK (("promo_type" = ANY (ARRAY['discount_per_item'::"text", 'free_item'::"text"]))),
    CONSTRAINT "catalog_promos_reward_amount_unit_check" CHECK ((("reward_amount_unit" IS NULL) OR ("reward_amount_unit" = ANY (ARRAY['rp'::"text", 'percent'::"text"])))),
    CONSTRAINT "catalog_promos_reward_amount_value_check" CHECK ((("reward_amount_value" IS NULL) OR ("reward_amount_value" >= (0)::numeric))),
    CONSTRAINT "catalog_promos_reward_quantity_check" CHECK (("reward_quantity" >= 1)),
    CONSTRAINT "catalog_promos_reward_shape_check" CHECK (((("promo_type" = 'discount_per_item'::"text") AND ("reward_amount_unit" IS NOT NULL) AND ("reward_amount_value" IS NOT NULL) AND ("reward_product_id" IS NULL) AND ((("reward_amount_unit" = 'percent'::"text") AND ("reward_amount_value" <= (100)::numeric)) OR ("reward_amount_unit" = 'rp'::"text"))) OR (("promo_type" = 'free_item'::"text") AND ("reward_product_id" IS NOT NULL) AND ("reward_amount_unit" IS NULL) AND ("reward_amount_value" IS NULL)))),
    CONSTRAINT "catalog_promos_sales_type_scope_check" CHECK (("sales_type_scope" = ANY (ARRAY['all'::"text", 'specific'::"text"])))
);


