CREATE TABLE IF NOT EXISTS "public"."cms_sales_contract_pending" (
    "organization_id" "uuid" NOT NULL,
    "saved_by" "uuid" NOT NULL,
    "reason" "text" NOT NULL,
    "is_trial" boolean NOT NULL,
    "trial_end_date" timestamp with time zone,
    "subscription_end_date" timestamp with time zone,
    "modules" "jsonb" NOT NULL,
    "hr_seat_count" integer NOT NULL,
    "omnichannel_paid_seat_count" integer NOT NULL,
    "keep_employee_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "saved_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "outlet_quota" integer,
    "keep_outlet_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "monthly_price_idr" bigint,
    "billing_mode" "text",
    "ppn_included" boolean,
    "price_effective_on" "date",
    "period_value_idr" bigint,
    "adjustment_idr" bigint,
    "ai_employee_seat_count" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "cms_sales_contract_pending_adjustment_nonneg" CHECK ((("adjustment_idr" IS NULL) OR ("adjustment_idr" >= 0))),
    CONSTRAINT "cms_sales_contract_pending_ai_employee_nonneg" CHECK (("ai_employee_seat_count" >= 0)),
    CONSTRAINT "cms_sales_contract_pending_billing_mode_check" CHECK ((("billing_mode" IS NULL) OR ("billing_mode" = ANY (ARRAY['monthly'::"text", 'prepaid'::"text"])))),
    CONSTRAINT "cms_sales_contract_pending_hr_nonneg" CHECK (("hr_seat_count" >= 0)),
    CONSTRAINT "cms_sales_contract_pending_modules_object" CHECK (("jsonb_typeof"("modules") = 'object'::"text")),
    CONSTRAINT "cms_sales_contract_pending_monthly_price_nonneg" CHECK ((("monthly_price_idr" IS NULL) OR ("monthly_price_idr" >= 0))),
    CONSTRAINT "cms_sales_contract_pending_omni_nonneg" CHECK (("omnichannel_paid_seat_count" >= 0)),
    CONSTRAINT "cms_sales_contract_pending_outlet_quota_range" CHECK ((("outlet_quota" IS NULL) OR (("outlet_quota" >= 0) AND ("outlet_quota" <= 100)))),
    CONSTRAINT "cms_sales_contract_pending_period_value_nonneg" CHECK ((("period_value_idr" IS NULL) OR ("period_value_idr" >= 0))),
    CONSTRAINT "cms_sales_contract_pending_price_complete" CHECK (((("monthly_price_idr" IS NULL) AND ("billing_mode" IS NULL) AND ("ppn_included" IS NULL) AND ("price_effective_on" IS NULL) AND ("period_value_idr" IS NULL) AND ("adjustment_idr" IS NULL)) OR (("monthly_price_idr" IS NOT NULL) AND ("billing_mode" IS NOT NULL) AND ("ppn_included" IS NOT NULL) AND ("price_effective_on" IS NOT NULL) AND ("period_value_idr" IS NOT NULL) AND ("adjustment_idr" IS NOT NULL)))),
    CONSTRAINT "cms_sales_contract_pending_reason_len" CHECK (("char_length"("btrim"("reason")) >= 3))
);


