CREATE TABLE IF NOT EXISTS "public"."default_prices" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "service_id" "uuid",
    "sub_service_id" "uuid",
    "unit_price" numeric(18,2) DEFAULT 0 NOT NULL,
    "description" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "kind" "text" DEFAULT 'service'::"text" NOT NULL,
    "name" "text",
    "photo_path" "text",
    "unit" "text" DEFAULT 'pcs'::"text" NOT NULL,
    "track_stock" boolean DEFAULT false NOT NULL,
    "inventory_sku_id" "uuid",
    "product_category_id" "uuid",
    "pos_status" "text" DEFAULT 'available'::"text" NOT NULL,
    "product_brand_id" "uuid",
    "use_sales_type_prices" boolean DEFAULT false NOT NULL,
    "sku" "text",
    CONSTRAINT "default_prices_kind_check" CHECK (("kind" = ANY (ARRAY['service'::"text", 'product'::"text"]))),
    CONSTRAINT "default_prices_kind_shape_check" CHECK (((("kind" = 'service'::"text") AND ("service_id" IS NOT NULL)) OR (("kind" = 'product'::"text") AND ("name" IS NOT NULL) AND ("btrim"("name") <> ''::"text")))),
    CONSTRAINT "default_prices_pos_status_check" CHECK (("pos_status" = ANY (ARRAY['available'::"text", 'sold_out'::"text", 'hidden'::"text"]))),
    CONSTRAINT "default_prices_pos_status_kind_check" CHECK ((("kind" <> 'service'::"text") OR ("pos_status" = 'available'::"text"))),
    CONSTRAINT "default_prices_product_category_kind_check" CHECK ((("kind" = 'product'::"text") OR ("product_category_id" IS NULL))),
    CONSTRAINT "default_prices_track_stock_check" CHECK ((("track_stock" = false) OR ("kind" = 'product'::"text"))),
    CONSTRAINT "default_prices_unit_price_check" CHECK (("unit_price" >= (0)::numeric))
);


ALTER TABLE "public"."default_prices" OWNER TO "postgres";


