CREATE TABLE IF NOT EXISTS "public"."kol_campaign_budget_allocations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "campaign_id" "uuid" NOT NULL,
    "kol_profile_id" "uuid" NOT NULL,
    "allocated_budget" numeric(12,2) DEFAULT 0 NOT NULL,
    "budget_type" "text" DEFAULT 'fixed'::"text",
    "notes" "text",
    "organization_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "payment_model" "text" DEFAULT 'fixed'::"text",
    "base_budget" numeric(15,2) DEFAULT 0,
    "bonus_budget" numeric(15,2) DEFAULT 0,
    "performance_multiplier" numeric(3,2) DEFAULT 1.0,
    "payment_terms_id" "uuid",
    "milestone_completion_rate" numeric(5,2) DEFAULT 0,
    "actual_payout" numeric(15,2) DEFAULT 0,
    "budget_utilization_percentage" numeric GENERATED ALWAYS AS (
CASE
    WHEN (("allocated_budget" > (0)::numeric) AND ("actual_payout" IS NOT NULL)) THEN (("actual_payout" / "allocated_budget") * (100)::numeric)
    ELSE (0)::numeric
END) STORED,
    CONSTRAINT "kol_campaign_budget_allocations_budget_type_check" CHECK (("budget_type" = ANY (ARRAY['fixed'::"text", 'performance'::"text", 'hybrid'::"text"]))),
    CONSTRAINT "kol_campaign_budget_allocations_payment_model_check" CHECK (("payment_model" = ANY (ARRAY['fixed'::"text", 'fixed_plus_bonus'::"text", 'performance_based'::"text", 'tiered'::"text", 'barter_plus_fee'::"text"])))
