CREATE MATERIALIZED VIEW "public"."kol_conversion_aggregates" AS
 SELECT "content_post_id",
    "kol_profile_id",
    "count"(*) AS "total_conversions",
    "sum"("conversion_value") AS "total_conversion_value",
    "count"(DISTINCT "conversion_type") AS "conversion_types_count",
    "avg"("conversion_value") AS "avg_conversion_value",
    "date_trunc"('day'::"text", "conversion_date") AS "conversion_day"
   FROM "public"."kol_conversions"
  GROUP BY "content_post_id", "kol_profile_id", ("date_trunc"('day'::"text", "conversion_date"))
  WITH NO DATA;


ALTER MATERIALIZED VIEW "public"."kol_conversion_aggregates" OWNER TO "postgres";


