    "is_follower_at_start" boolean,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "private_reply_sent_at" timestamp with time zone,
    "private_reply_message_id" "text",
    "comment_reply_id" "text",
    "first_dm_method" "text",
    "became_follower_at" timestamp with time zone,
    "follow_confirm_attempts" integer DEFAULT 0 NOT NULL,
    "comment_reply_sent_text" "text",
    "dm_flow_version" smallint DEFAULT 1 NOT NULL,
    "awaiting_contact_kind" "text",
    CONSTRAINT "lead_magnet_enrollments_awaiting_contact_kind_chk" CHECK ((("awaiting_contact_kind" IS NULL) OR ("awaiting_contact_kind" = ANY (ARRAY['email'::"text", 'phone'::"text"])))),
    CONSTRAINT "lead_magnet_enrollments_conv_table_chk" CHECK ((("conversation_table" IS NULL) OR ("conversation_table" = ANY (ARRAY['instagram_conversations'::"text", 'facebook_conversations'::"text"])))),
    CONSTRAINT "lead_magnet_enrollments_first_dm_method_chk" CHECK ((("first_dm_method" IS NULL) OR ("first_dm_method" = ANY (ARRAY['private_reply_button'::"text", 'private_reply_text'::"text", 'standard'::"text"])))),
    CONSTRAINT "lead_magnet_enrollments_paused_chk" CHECK ((("paused_reason" IS NULL) OR ("paused_reason" = ANY (ARRAY['assignee_taken_over'::"text", 'manual'::"text"])))),
    CONSTRAINT "lead_magnet_enrollments_platform_chk" CHECK (("platform" = ANY (ARRAY['instagram'::"text", 'facebook'::"text"]))),
    CONSTRAINT "lead_magnet_enrollments_status_chk" CHECK (("status" = ANY (ARRAY['comment_matched'::"text", 'comment_replied'::"text", 'follow_checked'::"text", 'follow_gate_sent'::"text", 'follow_validated'::"text", 'framework_offered'::"text", 'material_offer_skipped'::"text", 'awaiting_contact'::"text", 'contact_collected'::"text", 'delivered'::"text", 'delivered_whatsapp'::"text", 'delivered_email'::"text", 'delivered_instagram'::"text", 'failed'::"text", 'paused'::"text"])))
);


