CREATE TABLE IF NOT EXISTS "public"."lead_submissions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "web_id" "text",
    "form_id" "text",
    "form_version" integer DEFAULT 1 NOT NULL,
    "step" integer DEFAULT 1 NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "form_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "name" "text",
    "phone_number" "text",
    "email" "text",
    "package_label" "text",
    "analytics_session_id" "uuid",
    "attribution" "jsonb",
    "attribution_label" "text",
    "organization_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "identity_hash" "text",
    "step1_dedupe_key" "text" GENERATED ALWAYS AS (
CASE
    WHEN (("analytics_session_id" IS NOT NULL) AND ("step" = 1) AND ("status" = 'draft'::"text")) THEN ("analytics_session_id")::"text"
    ELSE NULL::"text"
END) STORED,
    "final_dedupe_key" "text" GENERATED ALWAYS AS (
CASE
    WHEN (("analytics_session_id" IS NOT NULL) AND ("status" = 'submitted'::"text") AND ("identity_hash" IS NOT NULL) AND ("btrim"("identity_hash") <> ''::"text")) THEN ((("analytics_session_id")::"text" || ':'::"text") || "identity_hash")
    ELSE NULL::"text"
END) STORED,
    "submitted_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "legacy_table" "text",
    "legacy_id" "uuid",
    "gclid" "text",
    "gender" "text",
    "age" integer,
    "occupation" "text",
    "location" "text",
    "code" "text",
    "industry" "text",
    "notes" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "property_package_id" "uuid",
    "whatsapp_status" "text",
    "whatsapp_message_id" "text",
    "whatsapp_skip_reason" "text",
    "whatsapp_sent_at" timestamp with time zone,
    "whatsapp_conversation_id" "uuid",
    "lead_magnet_enrollment_id" "uuid",
    "lead_magnet_campaign_id" "uuid",
    "lead_magnet_target_market" "text",
    "lead_magnet_campaign_name" "text",
    CONSTRAINT "lead_submissions_age_check" CHECK ((("age" IS NULL) OR (("age" >= 1) AND ("age" <= 149)))),
    CONSTRAINT "lead_submissions_gender_check" CHECK ((("gender" IS NULL) OR ("gender" = ANY (ARRAY['Male'::"text", 'Female'::"text", 'Other'::"text"])))),
    CONSTRAINT "lead_submissions_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'submitted'::"text"]))),
    CONSTRAINT "lead_submissions_whatsapp_status_check" CHECK ((("whatsapp_status" IS NULL) OR ("whatsapp_status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'delivered'::"text", 'failed'::"text", 'skipped'::"text"]))))
);


ALTER TABLE "public"."lead_submissions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."lead_submissions"."form_id" IS 'Optional FK to website capture form. NULL for omnichannel-only leads (e.g. WhatsApp) with no website submission.';



COMMENT ON COLUMN "public"."lead_submissions"."form_data" IS 'Dynamic website form fields from Omnichannel Public API (non-core keys).';



COMMENT ON COLUMN "public"."lead_submissions"."analytics_session_id" IS 'Anonymous analytics session; FK to analytics_sessions.id (null if session removed).';



COMMENT ON COLUMN "public"."lead_submissions"."gclid" IS 'Google Click ID from analytics session (offline conversion export).';



COMMENT ON COLUMN "public"."lead_submissions"."occupation" IS 'Client occupation (pekerjaan). Wedding event date/time stay in form_data and notes.';



COMMENT ON COLUMN "public"."lead_submissions"."notes" IS 'Client profile notes (e.g. wedding package, date, address block).';



COMMENT ON COLUMN "public"."lead_submissions"."property_package_id" IS 'FK ke property_packages; leads.services di-resolve dari package_label baris ini.';



COMMENT ON COLUMN "public"."lead_submissions"."whatsapp_status" IS 'WhatsApp lead confirmation: pending/sent/delivered/failed/skipped. sent=Meta accepted; delivered/failed updated async via webhook.';



COMMENT ON COLUMN "public"."lead_submissions"."whatsapp_skip_reason" IS 'Why WA was not sent: no_consent, no_phone, no_template, wa_not_configured, etc.';



COMMENT ON COLUMN "public"."lead_submissions"."whatsapp_conversation_id" IS 'WhatsApp conversation created/updated when POST /api/v1/leads sends confirmation template (livechat thread).';



COMMENT ON COLUMN "public"."lead_submissions"."lead_magnet_target_market" IS 'Snapshot of campaign target_market when contact (phone/email) was captured via Lead Magnet.';



COMMENT ON COLUMN "public"."lead_submissions"."lead_magnet_campaign_name" IS 'Snapshot of campaign name when contact was captured via Lead Magnet.';



CREATE TABLE IF NOT EXISTS "public"."leads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ticket_id" "text" DEFAULT ((('LEAD-'::"text" || "to_char"("now"(), 'YYYYMMDD'::"text")) || '-'::"text") || "lpad"(("floor"(("random"() * (9999)::double precision)))::"text", 4, '0'::"text")) NOT NULL,
    "client" "text" NOT NULL,
    "title" "text" NOT NULL,
    "category" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_by_name" "text" NOT NULL,
    "assignee" "text" NOT NULL,
    "followup" integer DEFAULT 0,
    "fu_priority" "text" DEFAULT 'Please Follow Up'::"text",
    "source" "text" DEFAULT 'Website'::"text",
    "organization_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "services" "text",
    "converted_at" timestamp with time zone,
    "status_id" "uuid",
    "assignee_id" "uuid",
    "phone_number" "text",
    "email" "text",
    "attribution" "jsonb",
    "attribution_label" "text",
    "analytics_session_id" "uuid",
    "web_id" "text",
    "funnel_key" "text",
    "dedupe_key" "text" GENERATED ALWAYS AS (
CASE
    WHEN (("analytics_session_id" IS NOT NULL) AND ("funnel_key" IS NOT NULL) AND ("btrim"("funnel_key") <> ''::"text")) THEN ((("analytics_session_id")::"text" || ':'::"text") || "funnel_key")
    ELSE NULL::"text"
END) STORED,
    "template_followup_awaiting_reply" boolean DEFAULT false NOT NULL,
    "follow_up_cycle_reset_at" timestamp with time zone,
    "gclid" "text",
    "google_ads_account_id" "uuid",
    "fbclid" "text",
    "meta_ads_account_id" "uuid",
    "payment_at" timestamp with time zone,
    "ctwa_clid" "text",
    "fbclid_captured_at" timestamp with time zone,
    "merged_into_lead_id" "uuid",
    "merged_at" timestamp with time zone,
    "merged_by" "uuid",
    CONSTRAINT "leads_fu_priority_check" CHECK ((("fu_priority" IS NULL) OR ("fu_priority" = ANY (ARRAY['High'::"text", 'Medium'::"text", 'Low'::"text", 'Please Follow Up'::"text", 'Set Status'::"text"]))))
);


ALTER TABLE "public"."leads" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads" IS 'CRM leads; Operations / Leads Management.';



COMMENT ON COLUMN "public"."leads"."assignee_id" IS 'Employee responsible for this lead; only this agent sees it in their room.';



COMMENT ON COLUMN "public"."leads"."attribution" IS 'JSON: landing_url, referrer, utm_source, utm_medium, utm_campaign, utm_content, utm_term (sparse; client snapshot).';



COMMENT ON COLUMN "public"."leads"."attribution_label" IS 'Short human-readable summary computed server-side from attribution.';



COMMENT ON COLUMN "public"."leads"."analytics_session_id" IS 'Linked analytics_sessions.id for UTM attribution.';



COMMENT ON COLUMN "public"."leads"."web_id" IS 'Source website web_id from analytics / API ingest. NULL for omnichannel Lead Magnet leads.';



COMMENT ON COLUMN "public"."leads"."template_followup_awaiting_reply" IS 'True after a successful template follow-up send until customer inbound resets the cycle.';



COMMENT ON COLUMN "public"."leads"."follow_up_cycle_reset_at" IS 'Manual follow-up updates before this timestamp are excluded from count/priority.';



COMMENT ON COLUMN "public"."leads"."gclid" IS 'Google Click ID captured at lead creation (Google Ads offline conversion).';



COMMENT ON COLUMN "public"."leads"."google_ads_account_id" IS 'Optional Google Ads brand account; when null, upload uses org default account.';



COMMENT ON COLUMN "public"."leads"."fbclid" IS 'Facebook Click ID for Meta Ads offline conversion (CAPI).';



COMMENT ON COLUMN "public"."leads"."meta_ads_account_id" IS 'Optional Meta Ads brand account; when null, upload uses org default account.';



COMMENT ON COLUMN "public"."leads"."payment_at" IS 'Timestamp first qualifying payment (DP/full) for Google Ads deferred upload.';



COMMENT ON COLUMN "public"."leads"."ctwa_clid" IS 'Click-to-WhatsApp click ID synced from WhatsApp conversation or attribution.';



COMMENT ON COLUMN "public"."leads"."fbclid_captured_at" IS 'First-touch time when fbclid was captured for this lead (used in Meta CAPI fbc).';



COMMENT ON COLUMN "public"."leads"."merged_into_lead_id" IS 'Fase 3 soft-archive: points at winner lead after identity merge. Active leads have NULL.';



