    CONSTRAINT "marketing_short_links_site_origin_shape" CHECK ((("site_origin" IS NULL) OR ((("char_length"("site_origin") >= 8) AND ("char_length"("site_origin") <= 200)) AND ("site_origin" ~* '^https?://'::"text")))),
    CONSTRAINT "marketing_short_links_slug_format" CHECK (("slug" ~ '^[a-z0-9-]{3,64}$'::"text")),
    CONSTRAINT "marketing_short_links_utm_campaign_len" CHECK ((("utm_campaign" IS NULL) OR ("char_length"("utm_campaign") <= 200))),
    CONSTRAINT "marketing_short_links_utm_content_len" CHECK ((("utm_content" IS NULL) OR ("char_length"("utm_content") <= 200))),
    CONSTRAINT "marketing_short_links_utm_medium_len" CHECK ((("utm_medium" IS NULL) OR ("char_length"("utm_medium") <= 200))),
    CONSTRAINT "marketing_short_links_utm_source_len" CHECK ((("utm_source" IS NULL) OR ("char_length"("utm_source") <= 200))),
    CONSTRAINT "marketing_short_links_utm_term_len" CHECK ((("utm_term" IS NULL) OR ("char_length"("utm_term") <= 200)))
);


