CREATE TABLE IF NOT EXISTS "public"."organization_sla_policies" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text" DEFAULT ''::"text" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "priority" integer DEFAULT 100 NOT NULL,
    "first_response_sla_minutes" integer NOT NULL,
    "resolution_sla_minutes" integer NOT NULL,
    "inter_reply_sla_minutes" integer,
    "operational_hours_profile" "text" DEFAULT '24x7'::"text" NOT NULL,
    "work_schedule_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "updated_by" "uuid",
    CONSTRAINT "organization_sla_policies_desc_len" CHECK (("char_length"("description") <= 500)),
    CONSTRAINT "organization_sla_policies_first_response_sla_minutes_check" CHECK (("first_response_sla_minutes" > 0)),
    CONSTRAINT "organization_sla_policies_inter_reply_sla_minutes_check" CHECK ((("inter_reply_sla_minutes" IS NULL) OR ("inter_reply_sla_minutes" > 0))),
    CONSTRAINT "organization_sla_policies_name_len" CHECK (("char_length"("name") <= 120)),
    CONSTRAINT "organization_sla_policies_operational_hours_profile_check" CHECK (("operational_hours_profile" = ANY (ARRAY['24x7'::"text", 'business_hours'::"text"]))),
    CONSTRAINT "organization_sla_policies_resolution_sla_minutes_check" CHECK (("resolution_sla_minutes" > 0)),
    CONSTRAINT "organization_sla_policies_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'inactive'::"text"])))
);


ALTER TABLE "public"."organization_sla_policies" OWNER TO "postgres";


COMMENT ON TABLE "public"."organization_sla_policies" IS 'SLA policy rows; first matching active policy by ascending priority wins. inter_reply_sla_minutes reserved for future KPI.';



COMMENT ON COLUMN "public"."organization_sla_policies"."inter_reply_sla_minutes" IS 'After first agent reply in a cycle, each subsequent customer inbound must receive the next agent outbound within this many working minutes (CRM inter-reply SLA). NULL disables the metric for matched policy.';



