CREATE TABLE IF NOT EXISTS "public"."organization_subscriptions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'trial'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "subscription_plan_id" "uuid",
    "member_count" integer DEFAULT 1 NOT NULL,
    "is_over_limit" boolean DEFAULT false NOT NULL,
    "trial_end_date" timestamp with time zone,
    "subscription_end_date" timestamp with time zone,
    "billing_cycle" "text" DEFAULT 'monthly'::"text" NOT NULL,
    "auto_renew" boolean DEFAULT true NOT NULL,
    "is_trial" boolean DEFAULT true NOT NULL,
    "trial_start_date" timestamp with time zone,
    "subscription_start_date" timestamp with time zone,
    "last_payment_id" "uuid",
    "current_member" integer DEFAULT 0,
    "subscription_type" "text",
    "start_date" "date",
    "omnichannel_paid_seat_count" integer DEFAULT 0 NOT NULL,
    "lead_magnet_active" boolean DEFAULT false NOT NULL,
    "lead_magnet_grace_until" timestamp with time zone,
    "billing_term_months" integer DEFAULT 1 NOT NULL,
    "pos_paid_outlet_count" integer DEFAULT 0 NOT NULL,
    "pos_addon_active" boolean DEFAULT false NOT NULL,
    "sales_outlet_quota" integer,
    "sales_monthly_price_idr" bigint,
    "sales_billing_mode" "text",
    "sales_ppn_included" boolean,
    "sales_price_effective_on" "date",
    "ai_employee_paid_seat_count" integer DEFAULT 0 NOT NULL,
    "ai_employee_seat_count" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "organization_subscriptions_ai_employee_paid_nonneg" CHECK (("ai_employee_paid_seat_count" >= 0)),
    CONSTRAINT "organization_subscriptions_ai_employee_seat_nonneg" CHECK (("ai_employee_seat_count" >= 0)),
    CONSTRAINT "organization_subscriptions_omnichannel_paid_seat_count_non_nega" CHECK (("omnichannel_paid_seat_count" >= 0)),
    CONSTRAINT "organization_subscriptions_pos_paid_outlet_count_non_negative" CHECK (("pos_paid_outlet_count" >= 0)),
    CONSTRAINT "organization_subscriptions_sales_billing_mode_check" CHECK ((("sales_billing_mode" IS NULL) OR ("sales_billing_mode" = ANY (ARRAY['monthly'::"text", 'prepaid'::"text"])))),
    CONSTRAINT "organization_subscriptions_sales_monthly_price_nonneg" CHECK ((("sales_monthly_price_idr" IS NULL) OR ("sales_monthly_price_idr" >= 0))),
    CONSTRAINT "organization_subscriptions_sales_outlet_quota_range" CHECK ((("sales_outlet_quota" IS NULL) OR (("sales_outlet_quota" >= 0) AND ("sales_outlet_quota" <= 100)))),
    CONSTRAINT "organization_subscriptions_sales_price_complete" CHECK (((("sales_monthly_price_idr" IS NULL) AND ("sales_billing_mode" IS NULL) AND ("sales_ppn_included" IS NULL) AND ("sales_price_effective_on" IS NULL)) OR (("sales_monthly_price_idr" IS NOT NULL) AND ("sales_billing_mode" IS NOT NULL) AND ("sales_ppn_included" IS NOT NULL) AND ("sales_price_effective_on" IS NOT NULL))))
);


ALTER TABLE "public"."organization_subscriptions" OWNER TO "postgres";


COMMENT ON COLUMN "public"."organization_subscriptions"."omnichannel_paid_seat_count" IS 'Purchased omnichannel roster seat entitlement; roster cap = LEAST(member_count, this value).';



COMMENT ON COLUMN "public"."organization_subscriptions"."lead_magnet_active" IS 'Purchased Lead Magnet add-on entitlement (flat per organization).';



COMMENT ON COLUMN "public"."organization_subscriptions"."lead_magnet_grace_until" IS 'Temporary free access until this timestamp (launch grace for existing campaigns).';



COMMENT ON COLUMN "public"."organization_subscriptions"."pos_paid_outlet_count" IS 'Purchased extra POS outlets beyond the included HQ outlet (maxOutlets = 1 + this).';



COMMENT ON COLUMN "public"."organization_subscriptions"."pos_addon_active" IS 'True when POS add-on product is included (Plans Sertakan). Independent of pos_paid_outlet_count (extras may be 0).';



COMMENT ON COLUMN "public"."organization_subscriptions"."sales_outlet_quota" IS 'Total operating outlets for a sales tenant after a signed contract. NULL until that contract is applied.';



COMMENT ON COLUMN "public"."organization_subscriptions"."sales_monthly_price_idr" IS 'Negotiated monthly package price in whole rupiah. NULL until a signed sales contract sets it.';



