    "whatsapp_business_name" "text",
    "name_status" "text",
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "verify_token" "text" DEFAULT ''::"text",
    "connection_mode" "text" DEFAULT 'manual'::"text" NOT NULL,
    "coexistence_onboarded_at" timestamp with time zone,
    "contacts_sync_request_id" "text",
    "history_sync_request_id" "text",
    "history_sync_status" "text",
    "history_sync_progress" integer,
    "history_sync_error" "text",
    "disconnected_reason" "text",
    "capi_dataset_id" "text",
    "has_meta_access_token" boolean GENERATED ALWAYS AS ((COALESCE("btrim"("meta_access_token"), ''::"text") <> ''::"text")) STORED,
    CONSTRAINT "organization_whatsapp_accounts_connection_mode_chk" CHECK (("connection_mode" = ANY (ARRAY['manual'::"text", 'embedded_cloud_api'::"text", 'coexistence'::"text"]))),
    CONSTRAINT "organization_whatsapp_accounts_history_sync_status_chk" CHECK ((("history_sync_status" IS NULL) OR ("history_sync_status" = ANY (ARRAY['requested'::"text", 'running'::"text", 'done'::"text", 'declined'::"text", 'error'::"text"]))))
);


ALTER TABLE "public"."organization_whatsapp_accounts" OWNER TO "postgres";


