CREATE OR REPLACE VIEW "public"."organization_xendit_accounts" WITH ("security_invoker"='true') AS
 SELECT "s"."organization_id",
    "x"."xendit_sub_account_id",
    COALESCE("x"."business_name", 'Organization'::"text") AS "business_name",
    COALESCE("x"."email", ''::"text") AS "email",
    COALESCE("x"."account_type", 'MANAGED'::"text") AS "account_type",
    "s"."is_enabled",
    COALESCE("x"."status", 'pending'::"text") AS "status",
    "x"."kyc_status",
    "x"."metadata",
    "s"."enabled_at",
    "s"."created_at",
    "x"."updated_at",
    "x"."linked_bank_account_id"
   FROM ("public"."organization_xendit_settings" "s"
     LEFT JOIN "public"."xendit_sub_accounts" "x" ON ((("x"."organization_id" = "s"."organization_id") AND ("x"."is_primary" = true))));


