CREATE TABLE IF NOT EXISTS "public"."sales_activities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "client_name" "text" NOT NULL,
    "client_phone" "text",
    "activity_type" "text" NOT NULL,
    "status" "text" DEFAULT 'Active'::"text" NOT NULL,
    "service_id" "uuid",
    "sub_service_id" "uuid",
    "income_type_id" "uuid",
    "income_category_id" "uuid",
    "amount" numeric DEFAULT 0,
    "total_amount" numeric,
    "down_payment_amount" numeric,
    "remaining_amount" numeric,
    "is_down_payment" boolean DEFAULT false,
    "date" "date" NOT NULL,
    "description" "text",
    "is_paid" boolean DEFAULT false,
    "payment_method" "text",
    "receipt_url" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "follow_up_date" timestamp with time zone,
    "notes" "text",
    "client_email" "text",
    "total_paid_amount" numeric DEFAULT 0,
    "payment_status" "text" DEFAULT 'unpaid'::"text",
    "lead_id" "uuid",
    "payment_reference" "text",
    "cash_tendered" numeric,
    "customer_visit_id" "uuid",
    "table_number" "text",
    "pos_outlet_id" "uuid",
    "catalog_sales_type_id" "uuid",
    "checkout_subtotal" numeric,
    "checkout_tax_amount" numeric DEFAULT 0,
    "checkout_gratuity_amount" numeric DEFAULT 0,
    "pos_shift_id" "uuid",
    "pos_table_id" "uuid",
    "table_duration_minutes" integer,
    "checkout_discount_amount" numeric DEFAULT 0 NOT NULL,
    "refund_status" "text" DEFAULT 'none'::"text" NOT NULL,
    "refund_amount" numeric DEFAULT 0 NOT NULL,
    "refunded_at" timestamp with time zone,
    "refunded_by" "uuid",
    "refund_reason" "text",
    "refund_pos_shift_id" "uuid",
    "refund_reverse_id" "text",
    "checkout_application_method" "text",
    "payment_channel_id" "uuid",
    "served_by_user_id" "uuid",
    "invoice_number" "text",
    "invoice_due_date" "date",
    "invoice_cancelled_at" timestamp with time zone,
    "invoice_cancel_reason" "text",
    "invoice_issued_at" timestamp with time zone,
    CONSTRAINT "sales_activities_activity_type_check" CHECK (("activity_type" = ANY (ARRAY['Demo'::"text", 'Meeting'::"text", 'Call'::"text", 'Proposal'::"text", 'Closing'::"text", 'visit'::"text", 'Lead Conversion'::"text", 'Store Checkout'::"text"]))),
    CONSTRAINT "sales_activities_cash_tendered_check" CHECK ((("cash_tendered" IS NULL) OR ("cash_tendered" >= (0)::numeric))),
    CONSTRAINT "sales_activities_checkout_application_method_check" CHECK ((("checkout_application_method" IS NULL) OR ("checkout_application_method" = ANY (ARRAY['add'::"text", 'include'::"text"])))),
    CONSTRAINT "sales_activities_payment_method_check" CHECK ((("payment_method" IS NULL) OR ("lower"("payment_method") = ANY (ARRAY['cash'::"text", 'transfer'::"text", 'credit'::"text", 'pending'::"text", 'bank_transfer'::"text", 'credit_card'::"text", 'e_wallet'::"text", 'qris'::"text", 'other'::"text"])))),
    CONSTRAINT "sales_activities_payment_status_check" CHECK (("payment_status" = ANY (ARRAY['unpaid'::"text", 'partial'::"text", 'paid'::"text"]))),
    CONSTRAINT "sales_activities_refund_status_check" CHECK (("refund_status" = ANY (ARRAY['none'::"text", 'full'::"text"]))),
    CONSTRAINT "sales_activities_status_check" CHECK (("status" = ANY (ARRAY['Active'::"text", 'Negotiating'::"text", 'Won'::"text", 'Lost'::"text", 'Follow Up'::"text", 'Converted'::"text"]))),
    CONSTRAINT "sales_activities_table_duration_minutes_check" CHECK ((("table_duration_minutes" IS NULL) OR ("table_duration_minutes" >= 0))),
    CONSTRAINT "sales_activities_table_number_check" CHECK ((("table_number" IS NULL) OR (("char_length"("btrim"("table_number")) >= 1) AND ("char_length"("btrim"("table_number")) <= 16))))
);


ALTER TABLE "public"."sales_activities" OWNER TO "postgres";


COMMENT ON COLUMN "public"."sales_activities"."payment_reference" IS 'Optional bank transfer / e-wallet reference for store checkout.';



COMMENT ON COLUMN "public"."sales_activities"."cash_tendered" IS 'Optional cash received at store checkout. Change is total subtracted in the UI; not used by income RPC.';



COMMENT ON COLUMN "public"."sales_activities"."customer_visit_id" IS 'Store checkout ticket belonging to a customer visit. Many tickets per visit are allowed.';



COMMENT ON COLUMN "public"."sales_activities"."table_number" IS 'Table printed on this ticket. Independent of later tickets on the same visit.';



COMMENT ON COLUMN "public"."sales_activities"."pos_outlet_id" IS 'POS outlet that processed this store checkout transaction.';



COMMENT ON COLUMN "public"."sales_activities"."catalog_sales_type_id" IS 'Sales type (e.g. Dine In) selected at store checkout; drives gratuity rules.';



COMMENT ON COLUMN "public"."sales_activities"."checkout_subtotal" IS 'Pre-tax/gratuity cart subtotal at checkout (store checkout only).';



COMMENT ON COLUMN "public"."sales_activities"."checkout_tax_amount" IS 'Total tax amount applied at store checkout.';



COMMENT ON COLUMN "public"."sales_activities"."checkout_gratuity_amount" IS 'Total gratuity amount applied at store checkout.';



COMMENT ON COLUMN "public"."sales_activities"."pos_shift_id" IS 'POS cashier shift that recorded this store checkout (cash drawer session).';



COMMENT ON COLUMN "public"."sales_activities"."pos_table_id" IS 'Optional FK to pos_tables when checkout was tied to a floor-plan table.';



COMMENT ON COLUMN "public"."sales_activities"."table_duration_minutes" IS 'Minutes seated from session open to pay/close.';



COMMENT ON COLUMN "public"."sales_activities"."checkout_discount_amount" IS 'Total line discounts (Rp) applied at Store Checkout; Gross Sales = checkout_subtotal + this.';



COMMENT ON COLUMN "public"."sales_activities"."checkout_application_method" IS 'Snapshot of catalog checkout application_method at pay time: add=exclusive, include=inclusive.';



COMMENT ON COLUMN "public"."sales_activities"."served_by_user_id" IS 'Waiter / order taker who served the bill (pos_table_sessions.waiter_id, else opened_by at pay). Distinct from created_by (Collected By).';



COMMENT ON COLUMN "public"."sales_activities"."invoice_number" IS 'Persisted invoice code, typically INV-{8 hex UUID prefix}.';



COMMENT ON COLUMN "public"."sales_activities"."invoice_due_date" IS 'Payment due date for invoice tracking.';



COMMENT ON COLUMN "public"."sales_activities"."invoice_cancelled_at" IS 'When set, invoice display status is cancelled.';



COMMENT ON COLUMN "public"."sales_activities"."invoice_issued_at" IS 'When the invoice was issued; defaults to created_at on backfill.';



