    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "smita_period_shape" CHECK (((("period_type" = 'monthly'::"text") AND ("month" IS NOT NULL) AND ("quarter" IS NULL)) OR (("period_type" = 'quarterly'::"text") AND ("quarter" IS NOT NULL) AND ("month" IS NULL)))),
    CONSTRAINT "social_media_insight_target_assignments_month_check" CHECK ((("month" IS NULL) OR (("month" >= 1) AND ("month" <= 12)))),
    CONSTRAINT "social_media_insight_target_assignments_period_type_check" CHECK (("period_type" = ANY (ARRAY['monthly'::"text", 'quarterly'::"text"]))),
    CONSTRAINT "social_media_insight_target_assignments_platform_check" CHECK (("platform" = ANY (ARRAY['tiktok'::"text", 'youtube'::"text", 'linkedin'::"text"]))),
    CONSTRAINT "social_media_insight_target_assignments_quarter_check" CHECK ((("quarter" IS NULL) OR (("quarter" >= 1) AND ("quarter" <= 4)))),
    CONSTRAINT "social_media_insight_target_assignments_year_check" CHECK ((("year" >= 2000) AND ("year" <= 2100)))
);


