CREATE TABLE IF NOT EXISTS "public"."thinking_lab_executions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "idea_id" "uuid" NOT NULL,
    "pillar" "text" NOT NULL,
    "statement" "text" NOT NULL,
    "canonical_semantic" "jsonb" NOT NULL,
    "admission" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "content_pillar_id" "uuid",
    "pillar_name" "text",
    "script" "jsonb",
    "creative_idea_id" "uuid",
    "format" "text",
    "author_employee_id" "uuid",
    CONSTRAINT "thinking_lab_executions_admission_check" CHECK (("admission" = ANY (ARRAY['GENERATE_VALID'::"text", 'GENERATE_REJECT'::"text", 'UNRESOLVED'::"text"]))),
    CONSTRAINT "thinking_lab_executions_creative_pair_check" CHECK (((("creative_idea_id" IS NULL) AND ("format" IS NULL)) OR (("creative_idea_id" IS NOT NULL) AND ("format" IS NOT NULL)))),
    CONSTRAINT "thinking_lab_executions_format_check" CHECK ((("format" IS NULL) OR ("format" = ANY (ARRAY['video'::"text", 'carousel'::"text", 'post'::"text"])))),
    CONSTRAINT "thinking_lab_executions_statement_check" CHECK (("char_length"(TRIM(BOTH FROM "statement")) > 0))
);


ALTER TABLE "public"."thinking_lab_executions" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_lab_executions" IS 'Thinking Lab content: one locked Idea plus one format pillar. The pillar is not a meaning level.';



COMMENT ON COLUMN "public"."thinking_lab_executions"."script" IS 'Structured voice-over script: assets, scenes, shots, and narration lines that failed the Idea message.';



COMMENT ON COLUMN "public"."thinking_lab_executions"."creative_idea_id" IS 'Optional creative idea. Null on executions created before this link existed.';



COMMENT ON COLUMN "public"."thinking_lab_executions"."author_employee_id" IS 'Karyawan AI yang menulis execution ini. NULL berarti execution manusia dan tidak boleh ditimpa Naya.';



CREATE TABLE IF NOT EXISTS "public"."thinking_lab_ideas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "angle_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "statement" "text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "parent_angle_fingerprint" "text" NOT NULL,
    "canonical_semantic" "jsonb" NOT NULL,
    "admission" "text" NOT NULL,
    "status" "text" DEFAULT 'candidate'::"text" NOT NULL,
    "semantic_fingerprint" "text",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "parent_idea_id" "uuid",
    "validation" "jsonb",
    "development_paths" "jsonb",
    CONSTRAINT "thinking_lab_ideas_admission_check" CHECK (("admission" = ANY (ARRAY['GENERATE_VALID'::"text", 'GENERATE_REJECT'::"text", 'UNRESOLVED'::"text"]))),
    CONSTRAINT "thinking_lab_ideas_code_check" CHECK (("char_length"(TRIM(BOTH FROM "code")) > 0)),
    CONSTRAINT "thinking_lab_ideas_development_paths_array_check" CHECK ((("development_paths" IS NULL) OR ("jsonb_typeof"("development_paths") = 'array'::"text"))),
    CONSTRAINT "thinking_lab_ideas_fingerprint_check" CHECK (("char_length"(TRIM(BOTH FROM "parent_angle_fingerprint")) > 0)),
    CONSTRAINT "thinking_lab_ideas_statement_check" CHECK (("char_length"(TRIM(BOTH FROM "statement")) > 0)),
    CONSTRAINT "thinking_lab_ideas_status_check" CHECK (("status" = ANY (ARRAY['candidate'::"text", 'locked'::"text"]))),
    CONSTRAINT "thinking_lab_ideas_validation_object_check" CHECK ((("validation" IS NULL) OR ("jsonb_typeof"("validation") = 'object'::"text")))
);


ALTER TABLE "public"."thinking_lab_ideas" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_lab_ideas" IS 'Thinking Lab Idea candidates under one direct locked Angle. Includes rejected and unresolved rows.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."parent_angle_fingerprint" IS 'Fingerprint of the direct Angle at generation time.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."canonical_semantic" IS 'Sealed Idea facts. relationToParent is derived. creativeMechanism is descriptive.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."status" IS 'candidate until a later Idea lock. This slice does not lock Ideas.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."parent_idea_id" IS 'Idea this row revises. The original statement stays on the parent row.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."validation" IS 'K1–K7 result. LOLOS, DITOLAK, and BELUM TERVERIFIKASI all stay on this table.';



COMMENT ON COLUMN "public"."thinking_lab_ideas"."development_paths" IS 'Saved pillar and format paths. Each path is identified by contentPillarId and format.';



