);


ALTER TABLE "public"."thinking_lab_pillar_defaults" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_lab_pillar_defaults" IS 'Per-organization Image or Video default for a content pillar. Shared default pillars are not edited.';



CREATE TABLE IF NOT EXISTS "public"."thinking_lab_territories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
