    "status" "text" DEFAULT 'candidate'::"text" NOT NULL,
    "semantic_fingerprint" "text",
    "angle_set" "jsonb",
    CONSTRAINT "thinking_lab_territories_admission_check" CHECK (("admission" = ANY (ARRAY['GENERATE_VALID'::"text", 'GENERATE_REJECT'::"text", 'UNRESOLVED'::"text"]))),
    CONSTRAINT "thinking_lab_territories_code_check" CHECK (("char_length"(TRIM(BOTH FROM "code")) > 0)),
    CONSTRAINT "thinking_lab_territories_statement_check" CHECK (("char_length"(TRIM(BOTH FROM "statement")) > 0)),
    CONSTRAINT "thinking_lab_territories_status_check" CHECK (("status" = ANY (ARRAY['candidate'::"text", 'locked'::"text"])))
);


ALTER TABLE "public"."thinking_lab_territories" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_lab_territories" IS 'Thinking Lab Territory candidates under one direct locked Big Thought.';



COMMENT ON COLUMN "public"."thinking_lab_territories"."status" IS 'candidate until the admitted set passes audit, challenger, and lock.';



COMMENT ON COLUMN "public"."thinking_lab_territories"."angle_set" IS 'Thinking Lab angle sibling audit, audit verdicts, and challenger for this Territory.';



CREATE TABLE IF NOT EXISTS "public"."thinking_master_thoughts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "statement" "text" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "last_audit" "jsonb",
    "last_audit_at" timestamp with time zone,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "original_input" "text" NOT NULL,
    "mt_status" "text" DEFAULT 'raw'::"text" NOT NULL,
    "mt_audit" "jsonb",
    "root_belief" "text",
    "intent_preservation_notes" "text",
    "confirmed_at" timestamp with time zone,
    "confirmation_source" "text",
    "canonical_semantic" "jsonb",
    "semantic_fingerprint" "text",
    "workspace" "text",
    "prior_belief" "text" DEFAULT ''::"text" NOT NULL,
    "audience" "text" DEFAULT ''::"text" NOT NULL,
    "product_reason_pool" "jsonb",
    "service_id" "uuid",
    "sub_service_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "feature_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    CONSTRAINT "thinking_master_thoughts_confirmation_source_check" CHECK ((("confirmation_source" IS NULL) OR ("confirmation_source" = ANY (ARRAY['original'::"text", 'recommendation'::"text", 'edited'::"text"])))),
    CONSTRAINT "thinking_master_thoughts_mt_status_check" CHECK (("mt_status" = ANY (ARRAY['raw'::"text", 'audited_pass'::"text", 'audited_needs_normalization'::"text", 'selected'::"text", 'confirmed'::"text", 'locked'::"text"]))),
    CONSTRAINT "thinking_master_thoughts_statement_check" CHECK (("char_length"(TRIM(BOTH FROM "statement")) > 0)),
    CONSTRAINT "thinking_master_thoughts_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'audited'::"text", 'locked'::"text"]))),
    CONSTRAINT "thinking_master_thoughts_workspace_check" CHECK ((("workspace" IS NULL) OR ("workspace" = 'thinking_lab'::"text")))
);


ALTER TABLE "public"."thinking_master_thoughts" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_master_thoughts" IS 'Org-scoped Master Thought records for the Thinking System.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."canonical_semantic" IS 'Authoritative canonical semantic facts for the exact Master Thought represented by semantic_fingerprint. Audit copies are projections, not another semantic source of truth.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."semantic_fingerprint" IS 'Fingerprint of the Master Thought semantic input used when canonical_semantic was produced. Facts are reusable only while this fingerprint matches the current Master Thought.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."workspace" IS 'Null is the legacy /thinking workspace. thinking_lab rows belong only to /thinking-lab.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."prior_belief" IS 'Audience belief being displaced. Context only. Empty on rows created before this column.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."audience" IS 'Optional audience the planted belief addresses. Context only. Empty when unset.';



COMMENT ON COLUMN "public"."thinking_master_thoughts"."product_reason_pool" IS 'Frozen product advantages, solutions, and features. Null means Big Thoughts may use a general because-clause.';



CREATE TABLE IF NOT EXISTS "public"."thinking_territories" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "big_thought_id" "uuid" NOT NULL,
    "code" "text" NOT NULL,
    "title" "text" NOT NULL,
    "statement" "text" DEFAULT ''::"text" NOT NULL,
    "boundary" "text" DEFAULT ''::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "status" "text" DEFAULT 'candidate'::"text" NOT NULL,
    "last_audit" "jsonb",
    "generation_batch_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "timezone"('utc'::"text", "now"()) NOT NULL,
    "ownership" "text" DEFAULT ''::"text" NOT NULL,
    "canonical_semantic" "jsonb",
    "semantic_fingerprint" "text",
    CONSTRAINT "thinking_territories_code_check" CHECK (("char_length"(TRIM(BOTH FROM "code")) > 0)),
    CONSTRAINT "thinking_territories_status_check" CHECK (("status" = ANY (ARRAY['candidate'::"text", 'locked'::"text", 'rejected'::"text"]))),
    CONSTRAINT "thinking_territories_title_check" CHECK (("char_length"(TRIM(BOTH FROM "title")) > 0))
);


ALTER TABLE "public"."thinking_territories" OWNER TO "postgres";


COMMENT ON TABLE "public"."thinking_territories" IS 'Strategic Territory candidates/locks under a Big Thought.';



COMMENT ON COLUMN "public"."thinking_territories"."ownership" IS 'Short conceptual ownership label: what conversation space this Territory uniquely owns.';



COMMENT ON COLUMN "public"."thinking_territories"."canonical_semantic" IS 'Authoritative Territory-specific canonical semantic facts for the exact node represented by semantic_fingerprint. Audit copies are projections, not another semantic source of truth.';



COMMENT ON COLUMN "public"."thinking_territories"."semantic_fingerprint" IS 'Fingerprint of this Territory''s semantic input plus required parent Big Thought semantic fingerprint. Facts are reusable only while this fingerprint matches.';



