CREATE OR REPLACE VIEW "public"."v_social_media_scheduler_tick_stats_1h" WITH ("security_invoker"='true') AS
 SELECT "date_trunc"('minute'::"text", "started_at") AS "minute_bucket",
    ("count"(*))::integer AS "tick_count",
    ("round"("avg"("duration_ms")))::integer AS "avg_duration_ms",
    ("percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("duration_ms")::double precision)))::integer AS "p95_duration_ms",
    ("sum"("published_ok"))::integer AS "published_ok_sum",
    ("sum"("claimed"))::integer AS "claimed_sum",
    ("sum"("deferred_rate_limited"))::integer AS "deferred_sum"
   FROM "public"."social_media_scheduler_tick_logs"
  WHERE ("started_at" >= ("now"() - '01:00:00'::interval))
  GROUP BY ("date_trunc"('minute'::"text", "started_at"))
  ORDER BY ("date_trunc"('minute'::"text", "started_at")) DESC;


ALTER VIEW "public"."v_social_media_scheduler_tick_stats_1h" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_social_media_scheduler_tick_stats_1h" IS 'Hourly rollup of scheduler tick throughput and latency.';



CREATE OR REPLACE VIEW "public"."v_social_media_schedules_failed_24h" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "social_media_plan_id",
    "platform",
    "scheduled_at",
    "updated_at",
    "retry_count",
    "error_message"
   FROM "public"."social_media_scheduled_posts"
  WHERE (("status" = 'failed'::"text") AND ("updated_at" >= ("now"() - '24:00:00'::interval)));


ALTER VIEW "public"."v_social_media_schedules_failed_24h" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_social_media_schedules_failed_24h" IS 'Failed schedules in the last 24 hours.';



CREATE OR REPLACE VIEW "public"."v_social_media_schedules_pending_late" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "social_media_plan_id",
    "platform",
    "scheduled_at",
    "updated_at",
    "retry_count",
    "error_message"
   FROM "public"."social_media_scheduled_posts"
  WHERE (("status" = 'pending'::"text") AND ("scheduled_at" < ("now"() - '00:03:00'::interval)));


ALTER VIEW "public"."v_social_media_schedules_pending_late" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_social_media_schedules_pending_late" IS 'Pending schedules past scheduled_at + 3 min grace (cron lag buffer).';



CREATE OR REPLACE VIEW "public"."v_social_media_schedules_rate_deferred" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "social_media_plan_id",
    "platform",
    "scheduled_at",
    "next_retry_at",
    "updated_at",
    "retry_count",
    "error_message"
   FROM "public"."social_media_scheduled_posts"
  WHERE (("status" = 'pending'::"text") AND ("error_message" ~~ 'rate_limited:%'::"text") AND ("next_retry_at" IS NOT NULL) AND ("next_retry_at" > "now"()));


ALTER VIEW "public"."v_social_media_schedules_rate_deferred" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_social_media_schedules_rate_deferred" IS 'Pending rows deferred by internal rate limit (waiting for next_retry_at).';



CREATE OR REPLACE VIEW "public"."v_social_media_schedules_stuck_publishing" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "social_media_plan_id",
    "platform",
    "scheduled_at",
    "updated_at",
    "retry_count",
    "error_message"
   FROM "public"."social_media_scheduled_posts"
  WHERE (("status" = 'publishing'::"text") AND (COALESCE("locked_at", "updated_at") < ("now"() - '00:10:00'::interval)));


ALTER VIEW "public"."v_social_media_schedules_stuck_publishing" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_social_media_schedules_stuck_publishing" IS 'Publishing rows with no heartbeat for 10+ minutes.';



