CREATE TABLE IF NOT EXISTS "public"."whatsapp_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "direction" "text" NOT NULL,
    "wa_message_id" "text",
    "body" "text",
    "message_type" "text" DEFAULT 'text'::"text",
    "raw_metadata" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "status" "text",
    "status_updated_at" timestamp with time zone,
    "channel" "text" DEFAULT 'whatsapp'::"text",
    "platform_message_id" "text",
    "read_at" timestamp with time zone,
    "media_url" "text",
    "reply_to_wa_message_id" "text",
    "reply_to_body" "text",
    "source" "text" DEFAULT 'agent'::"text" NOT NULL,
    "automation_flow_id" "uuid",
    "automation_enrollment_id" "uuid",
    CONSTRAINT "whatsapp_messages_direction_check" CHECK (("direction" = ANY (ARRAY['inbound'::"text", 'outbound'::"text"]))),
    CONSTRAINT "whatsapp_messages_source_chk" CHECK (("source" = ANY (ARRAY['agent'::"text", 'flow_automation'::"text", 'system'::"text", 'business_app'::"text"])))
);


ALTER TABLE "public"."whatsapp_messages" OWNER TO "postgres";


COMMENT ON COLUMN "public"."whatsapp_messages"."channel" IS 'Source channel: whatsapp or instagram. Matches conversation channel for consistency.';



COMMENT ON COLUMN "public"."whatsapp_messages"."platform_message_id" IS 'Meta/WhatsApp/Instagram message ID. Same as wa_message_id for compatibility.';



COMMENT ON COLUMN "public"."whatsapp_messages"."media_url" IS 'Public URL for image/video/document preview (outbound: storage link we sent; inbound: our storage after downloading from Meta)';



COMMENT ON COLUMN "public"."whatsapp_messages"."reply_to_wa_message_id" IS 'WhatsApp message ID yang dibalas (context.reply_to)';



COMMENT ON COLUMN "public"."whatsapp_messages"."reply_to_body" IS 'Teks/body pesan yang dibalas, untuk ditampilkan di bubble agar tidak bingung';



COMMENT ON COLUMN "public"."whatsapp_messages"."source" IS 'agent = sent from Synckerja by a person; flow_automation / system = automatic; business_app = typed in the WhatsApp Business app (Coexistence echo or imported history).';



